/**
 * pruefung.mjs
 * ============================================================================
 * UNABHÄNGIGER PRÜFSTAND für den Rechenkern.
 *
 * Jede Prüfung stellt dem Kern eine Aufgabe gegenüber, deren Ergebnis sich von
 * Hand angeben lässt - geschlossene Formel, Gleichgewicht oder Symmetrie.
 * Es wird bewusst NICHT gegen frühere Ausgaben des Werkzeugs verglichen,
 * sondern gegen Werte, die unabhängig davon feststehen.
 *
 * Aufruf:  node pruefung.mjs
 * ============================================================================
 */

import { readFileSync, readdirSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const HIER = dirname(fileURLToPath(import.meta.url));
const NL = String.fromCharCode(10);

// Als URL, nicht als Pfad: unter Windows ist "C:\...\js\x.js" für import()
// kein gültiges Schema (ERR_UNSUPPORTED_ESM_URL_SCHEME). Unter macOS ging
// der blosse Pfad zufällig durch. Dieselbe Schreibweise wie in
// ausleiten.mjs und vergleich_werkzeug.mjs.
const J = (n) => new URL(`./js/${n}`, import.meta.url).href;
/*
 * DER QUELLTEXT DER VERDRAHTUNG. Seit dem 19. September ist app.js in
 * Module geteilt (Durchsicht, Punkt A1): app.*.js und core.anker.js. Die
 * Kontrollen, die den Quelltext lesen, sehen alle zusammen - app.js zuerst.
 */
const APP_QUELLE = () => ['app.js',
  ...readdirSync(join(HIER, 'js')).filter((f) => /^app\..+\.js$/.test(f)).sort(),
  'core.anker.js'].map((f) => readFileSync(join(HIER, 'js', f), 'utf8')).join('\n');

/*
 * DIE NORMWERTE ZUERST. Seit dem 16. September stehen die Querschnittswerte
 * nicht mehr im Quelltext, sondern in data/normen.json - ohne sie wirft
 * jeder Zugriff auf ein Profil. Sie sind keine Betreiberdaten und liegen
 * deshalb auch in einer oeffentlichen Ablage bei.
 */
// Die Tabellenform der Dateien (seit dem 16. September).
const TBF = await import(J('data.tabellen.js'));
const NO = await import(J('data.normen.js'));
NO.setzeNormen(JSON.parse(readFileSync(join(HIER, 'data', 'normen.json'), 'utf8')));
const MA_SORT = await import(J('data.masten.js'));
try {
  MA_SORT.setzeMastenDB(JSON.parse(
    readFileSync(join(HIER, 'data', 'masten.json'), 'utf8')));
} catch { /* ohne Masten-Sortiment weiter - dann ohne Windlast */ }

const T = await import(J('data.tragjoche.js'));
T.setzeDatenbank(JSON.parse(readFileSync(join(HIER, 'data', 'tragjoche.json'), 'utf8')));

const { getProfil, getStahl, PROFILE } = await import(J('data.profiles.js'));
// PROFILE ist seit dem 16. September eine FUNKTION: die Tabelle steht in
// data/normen.json und ist beim Laden des Moduls noch nicht da.
const PROFILE_LISTE = () => PROFILE();
const { berechne, modell, auswertungAn } = await import(J('core.vierendeel.js'));
const { torsionsSchubfluss } = await import(J('core.querschnitt.js'));
const { schnittgroessen, knotenraster, pruefeAbstaende } = await import(J('core.statics.js'));
const { auflagermomente, biegesteifigkeitJoch, E_STAHL,
        MAST_UNVERSCHIEBLICH } = await import(J('core.auflager.js'));
const { klassifiziereWinkel, klasseAuskragend } = await import(J('core.klassen.js'));
const { standardwerte, typUebernehmen, FELDER } = await import(J('ui.schema.js'));
const { verortung, verortungKurz } = await import(J('core.constants.js'));
const A = await import(J('data.anbauteile.js'));
A.setzeAnbauteilDB(JSON.parse(readFileSync(join(HIER, 'data', 'anbauteile.json'), 'utf8')));
const FL = await import(J('data.fl.js'));
FL.setzeFlDB(JSON.parse(readFileSync(join(HIER, 'data', 'fl_bauteile.json'), 'utf8')));
const AJ = await import(J('data.abfangjoche.js'));
// Die Szene des Abfangjochs - sie traegt die Lage jedes Bauteils.
const R3D = await import(J('render.abfang.js'));
AJ.setzeAbfangDB(JSON.parse(
  readFileSync(join(HIER, 'data', 'abfangjoche.json'), 'utf8')));
/*
 * DAS ANKER-SORTIMENT - Zug-/Druckstuetzen und Seilanker am Masten.
 * Wie das Abfangjoch-Sortiment darf es fehlen; die Kontrollen springen dann.
 */
const AN = await import(J('data.anker.js'));
try {
  AN.setzeAnkerDB(JSON.parse(
    readFileSync(join(HIER, 'data', 'anker.json'), 'utf8')));
} catch { /* ohne Sortiment weiter */ }

/**
 * Anbauteil für Prüfzwecke. raster = 0 lässt beide Befestigungspunkte
 * zusammenfallen, damit die geschlossenen Formeln für EINE Einzellast gelten.
 */
const teil = (o) => ({
  id: o.id ?? 'T', vorlage: 'direkt', name: o.name ?? 'P', x: o.x,
  raster: o.raster ?? 0, seite: 'rechts', eigengewicht: 0,
  befestigung: o.befestigung,
  ev: o.ev ?? 0, ex: o.ex ?? 0,
  Gz: o.Gz ?? 0, Gx: o.Gx ?? 0, Gy: o.Gy ?? 0,
  Qz: o.Qz ?? 0, Qx: o.Qx ?? 0, Qy: o.Qy ?? 0, aktiv: true,
  ...(o.lasten ? { lasten: o.lasten } : {}),
  ...(o.module ? { module: o.module } : {}),
});

/** Freier Lastblock im neuen Modell: Angriffspunkt / Kraft / Moment. */
const block = (o) => ({ einwirkung: o.einwirkung ?? 'G',
  x: o.x ?? 0, y: o.y ?? 0, z: o.z ?? 0,
  Fx: o.Fx ?? 0, Fy: o.Fy ?? 0, Fz: o.Fz ?? 0,
  Mxx: o.Mxx ?? 0, Myy: o.Myy ?? 0, Mzz: o.Mzz ?? 0 });

// --- Prüfrahmen -------------------------------------------------------------

let bestanden = 0, gefallen = 0;
const fehlerliste = [];

function pruef(name, ist, soll, tol = 1e-9, einheit = '') {
  // Bei Sollwert null ist ein relativer Vergleich sinnlos - dort gilt eine
  // absolute Schranke, sonst schlägt Rechenrauschen von 1e-15 als Fehler durch.
  const nullSoll = Math.abs(soll) < 1e-12;
  const abw = nullSoll ? Math.abs(ist)
                       : Math.abs(ist - soll) / Math.max(Math.abs(ist), Math.abs(soll));
  // Bei Sollwert null gilt eine absolute Schranke, sonst schlägt das
  // Rechenrauschen der Gleitkommaarithmetik (1e-15) als Fehler durch.
  const ok = nullSoll ? abw < 1e-8 : abw <= tol;
  ok ? bestanden++ : gefallen++;
  const z = (v) => (Math.abs(v) >= 1e4 || (Math.abs(v) < 1e-3 && v !== 0)
    ? v.toExponential(4) : v.toFixed(6));
  console.log(`  ${ok ? '  ok' : 'FEHL'}  ${name.padEnd(52)} ` +
              `${z(ist).padStart(14)} ${z(soll).padStart(14)} ${einheit}` +
              (ok ? '' : `   Abw ${(abw * 100).toFixed(4)} %`));
  if (!ok) fehlerliste.push(`${name}: ist ${z(ist)}, soll ${z(soll)}`);
}

function wahr(name, bedingung, bemerkung = '') {
  bedingung ? bestanden++ : gefallen++;
  console.log(`  ${bedingung ? '  ok' : 'FEHL'}  ${name}${bemerkung ? '  – ' + bemerkung : ''}`);
  if (!bedingung) fehlerliste.push(name);
}

const titel = (t) => console.log(`\n${t}\n${'-'.repeat(t.length)}`);

// --- Basis-Eingabe ohne Einzellasten (reine Gleichlast) ---------------------

function basis(zusatz = {}) {
  const std = { ...standardwerte(), bearbeiten: false };
  const joch = T.getTragjoch('J90');
  return {
    ...typUebernehmen(std, joch),
    typ: 'J90', L: 20, anbauteile: [],
    schneeAktiv: false, gZusatz: 0,
    endbedingung: 'gelenkig', torsionsverteilung: 'schubfluss',
    torsionModell: 'huellkurve', xNachweis: 0,
    ...zusatz,
  };
}

const rechne = (w) => {
  const joch = w.typ !== 'frei' ? T.getTragjoch(w.typ) : null;
  return berechne(w, getProfil(w.profOG), getProfil(w.profUG), getStahl(w.stahl), joch);
};

console.log('='.repeat(104));
console.log('PRÜFSTAND TRAGJOCH – Kern gegen unabhängig bestimmte Werte');
console.log('='.repeat(104));
console.log(`  ${'Status'}  ${'Prüfung'.padEnd(52)} ${'Kern'.padStart(14)} ${'Soll'.padStart(14)}`);

// ===========================================================================
titel('1  Ersatzbalken – geschlossene Formeln');

{
  const w = basis();
  const e = rechne(w);
  const m = e.modell;
  const q = m.qd, L = m.L;

  pruef('Auflagerkraft R_A = q·L/2', m.RA, (q * L) / 2, 1e-12, 'kN');
  pruef('Gleichgewicht  R_A + R_B = q·L', m.RA + m.RB, q * L, 1e-12, 'kN');
  pruef('Feldmoment  M(L/2) = q·L²/8',
        schnittgroessen(L / 2, m).My, (q * L * L) / 8, 1e-10, 'kNm');
  pruef('Moment am Auflager = 0', Math.abs(schnittgroessen(0, m).My), 0, 1e-9, 'kNm');
  pruef('Querkraft V(0) = q·L/2', Math.abs(schnittgroessen(0, m).Vz), (q * L) / 2, 1e-12, 'kN');
  pruef('Querkraft V(L/2) = 0', Math.abs(schnittgroessen(L / 2, m).Vz), 0, 1e-9, 'kN');

  // Windbiegung
  pruef('Windmoment M_z(L/2) = w·L²/8',
        schnittgroessen(L / 2, m).Mz, (m.wd * L * L) / 8, 1e-10, 'kNm');
}

{
  // Einzellast in Feldmitte, ohne Gleichlast
  const w = basis({
    lastHerkunft: 'manuell', gkManuell: 0, wkManuell: 0, skManuell: 0,
    anbauteile: [teil({ x: 10, Gz: 10 })],
    gammaG: 1.0,
  });
  const e = rechne(w);
  const m = e.modell;
  pruef('Einzellast Feldmitte  M = P·L/4',
        schnittgroessen(10, m).My, (10 * 20) / 4, 1e-10, 'kNm');
  pruef('Einzellast Feldmitte  R_A = P/2', m.RA, 5, 1e-12, 'kN');
}

// ===========================================================================
titel('2  Endeinspannung – Drehwinkelverfahren gegen geschlossene Lösung');

{
  // Symmetrische Gleichlast, Drehfeder c an beiden Enden:
  //     M_A = (q·L²/12) · alpha/(1+alpha)      mit alpha = c·L/(2·EI)
  const w = basis({ endbedingung: 'manuell', cPhi: 8000 });
  const e = rechne(w);
  const m = e.modell;
  const alpha = (m.federn.cA * m.L) / (2 * m.steif.EI);
  const soll = ((m.qd * m.L * m.L) / 12) * (alpha / (1 + alpha));
  pruef('Stützmoment M_A bei Drehfeder', m.MA, soll, 1e-10, 'kNm');
  pruef('Symmetrie M_A = M_B', m.MA, m.MB, 1e-10, 'kNm');
}

{
  const e = rechne(basis({ endbedingung: 'voll' }));
  const m = e.modell;
  pruef('Volle Einspannung  M_A = q·L²/12', m.MA, (m.qd * m.L * m.L) / 12, 1e-6, 'kNm');
  pruef('Volle Einspannung  M(L/2) = q·L²/24',
        schnittgroessen(m.L / 2, m).My, (m.qd * m.L * m.L) / 24, 1e-5, 'kNm');
  pruef('Einspanngrad κ = 1', m.kappaA, 1, 1e-6, '–');
}

{
  const e = rechne(basis({ endbedingung: 'gelenkig' }));
  const m = e.modell;
  pruef('Gelenkig  M_A = 0', Math.abs(m.MA), 0, 1e-9, 'kNm');
  pruef('Gelenkig  M(L/2) = q·L²/8',
        schnittgroessen(m.L / 2, m).My, (m.qd * m.L * m.L) / 8, 1e-10, 'kNm');
}

{
  // Der Lastfall hier ist vertikal, also UNVERSCHIEBLICH: das Joch hält die
  // beiden Mastköpfe zusammen, und es gilt 4.00 · E·I/H statt des Kragmastes
  // (core.auflager.js, MAST_UNVERSCHIEBLICH). Der Kragarmwert bleibt daneben
  // ausgewiesen und gilt beim Wind in Jochachse.
  const w = basis({ endbedingung: 'mast', mastProfil: 'HEB 240',
                    mastH: 8, mastSteg: 'jochachse', mastAnschluss: 'kragarm' });
  const e = rechne(w);
  const p = e.modell.federn.mast;
  pruef('Kragmastwert c = E·I/H', p.cKragarm,
        (E_STAHL * (11260 * 1e-8)) / 8, 1e-9, 'kNm/rad');
  pruef('Vertikallast rechnet unverschieblich', p.cPhi,
        MAST_UNVERSCHIEBLICH * p.cKragarm, 1e-9, 'kNm/rad');
  const q = rechne({ ...w, mastSteg: 'quer' });
  pruef('Stegdrehung nutzt I_z', q.modell.federn.mast.I_cm4, 3923, 1e-12, 'cm4');
}

// ===========================================================================
titel('3  Torsion – Schubfluss nach Bredt');

{
  const b = 0.4, h = 0.6, Tx = 5;
  const sf = torsionsSchubfluss(Tx, b, h, 'schubfluss');
  pruef('Schubfluss q = T/(2·b·h)', sf.qT, Tx / (2 * b * h), 1e-12, 'kN/m');
  pruef('Vertikalebene V = T/(2b)', sf.vertikal, Tx / (2 * b), 1e-12, 'kN');
  pruef('Horizontalebene V = T/(2h)', sf.horizontal, Tx / (2 * h), 1e-12, 'kN');
  // Die beiden Wände einer Richtung bilden ein Kräftepaar: Moment = Kraft mal
  // Hebelarm (nicht zweimal), sonst wird doppelt gezählt.
  pruef('Momentengleichgewicht  V_v·b + V_h·h = T',
        sf.vertikal * b + sf.horizontal * h, Tx, 1e-12, 'kNm');

  const nv = torsionsSchubfluss(Tx, b, h, 'nurVertikal');
  pruef('Nur-Vertikal  V = T/b', nv.vertikal, Tx / b, 1e-12, 'kN');
  pruef('Nur-Vertikal ist doppelt so gross', nv.vertikal / sf.vertikal, 2, 1e-12, '–');
  pruef('Nur-Vertikal  Horizontalebene = 0', nv.horizontal, 0, 1e-12, 'kN');
}

// ===========================================================================
titel('4  Aufteilung auf die Eckwinkel');

{
  const w = basis({
    lastHerkunft: 'manuell', gkManuell: 2, wkManuell: 1, skManuell: 0,
    gammaG: 1, gammaQ: 1, lastfall: 'wind',
    anbauteile: [teil({ name: 'HS', x: 8, Gz: 12, Qy: 3, ev: 1.2 })],
  });
  const e = rechne(w);
  const m = e.modell;
  const s = auswertungAn(7.5, m);

  const summeOben = s.ecken.filter((c) => c.gurt === 'OG')
                           .reduce((a, c) => a + c.N_My, 0);
  pruef('Kräftepaar M_y:  |ΣN_OG| · h = M_y',
        Math.abs(summeOben) * m.h, Math.abs(s.My), 1e-10, 'kNm');
  pruef('N_My oben und unten gegengleich',
        s.ecken.find((c) => c.id === 'OG_L').N_My,
        -s.ecken.find((c) => c.id === 'UG_L').N_My, 1e-12, 'kN');

  const linkeEbene = s.ecken.filter((c) => c.seite === 'L')
                            .reduce((a, c) => a + c.N_Mz, 0);
  pruef('Kräftepaar M_z:  |ΣN_Ebene| · b = M_z',
        Math.abs(linkeEbene) * m.b, Math.abs(s.Mz), 1e-10, 'kNm');

  pruef('Summe aller Normalkräfte = 0 (kein Längszwang)',
        s.ecken.reduce((a, c) => a + c.N, 0), 0, 1e-9, 'kN');

  // Lokales Vierendeel-Moment am Knoten und am Anschnitt des Bindeblechs.
  // Der Knoten ist über die Blechbreite b_Bl biegesteif; nachgewiesen wird
  // der Gurt am Rand dieses Bereichs.
  const bBl = s.ebenen.find((x) => x.art === 'vertikal').breite / 1000;
  const fA = (m.a1eff - bBl) / m.a1eff;
  pruef('M_y,Knoten = V_Ebene · a₁ / 4',
        s.My_Knoten, (s.q.vertikal.max * m.a1eff) / 4, 1e-12, 'kNm');
  pruef('M_y,L,lokal = M_Knoten · (a₁ − b_Bl)/a₁',
        s.My_lokal, (s.q.vertikal.max * m.a1eff) / 4 * fA, 1e-12, 'kNm');
  wahr('Der Anschnitt mindert das Gurtmoment ab', s.My_lokal < s.My_Knoten,
       `Faktor ${fA.toFixed(3)} bei b_Bl = ${(bBl * 1000).toFixed(0)} mm`);
}

// ===========================================================================
titel('5  Spannungen – Einheiten und Querschnittswerte');

{
  const p = getProfil('L 90x90x9');
  // 100 kN auf 15.5 cm2  ->  100000 N / 1550 mm2 = 64.516 N/mm2
  const w = basis({
    lastHerkunft: 'manuell', gkManuell: 0, wkManuell: 0, skManuell: 0, gammaG: 1,
    anbauteile: [],
  });
  const e = rechne(w);
  const m = e.modell;
  pruef('Grenzspannung f_y/γ_M0', m.fyd, 235 / 1.05, 1e-12, 'N/mm²');

  // Umrechnung direkt am Kern nachvollziehen
  const s = auswertungAn(m.L / 2, m);
  const og = s.ecken.find((c) => c.id === 'OG_R');
  pruef('σ_N = N·10/A  (kN, cm² → N/mm²)',
        og.sig_N, (Math.abs(og.N) * 10) / p.A, 1e-12, 'N/mm²');
  pruef('σ_My = M·1000/W  (kNm, cm³ → N/mm²)',
        og.sig_My, (s.My_lokal * 1000) / p.Wy, 1e-12, 'N/mm²');

  // Blechquerschnitt
  const bl = s.ebenen.find((x) => x.id === 'V_R');
  pruef('Blech W = t·b²/6', bl.W, (bl.dicke * bl.breite ** 2) / 6, 1e-12, 'mm³');
  pruef('Blech σ = M/W  (kNm → Nmm)', bl.sig, (bl.M * 1e6) / bl.W, 1e-12, 'N/mm²');
  pruef('Blech τ = 1.5·V/A', bl.tau, (1.5 * bl.V * 1000) / (bl.dicke * bl.breite),
        1e-12, 'N/mm²');
  pruef('von Mises σ_v = √(σ²+3τ²)', bl.sig_v,
        Math.sqrt(bl.sig ** 2 + 3 * bl.tau ** 2), 1e-12, 'N/mm²');
}

// ===========================================================================
titel('6  Bindeblech – Gleichgewicht am Rahmenknoten');

{
  const w = basis({
    lastHerkunft: 'manuell', gkManuell: 3, wkManuell: 0, skManuell: 0, gammaG: 1,
    anbauteile: [],
  });
  const e = rechne(w);
  const m = e.modell;
  const s = auswertungAn(m.a1 * 5, m);              // innerer Knoten
  const bl = s.ebenen.find((x) => x.id === 'V_R');
  const V = s.q.vertikal.max;

  // Das Blech nimmt die Gurtmomente BEIDER angrenzender Felder auf:
  //   M_Knoten = 2 · (V·a₁/4) = V·a₁/2
  pruef('M_Knoten = V_Ebene · a₁/2 (innerer Knoten)',
        bl.M_Knoten, (V * m.a1eff) / 2, 1e-12, 'kNm');
  // Blech mit gleichen Endmomenten, Wendepunkt in Blechmitte:
  //   V_Blech = 2·M_Knoten / h   – vom steifen Knotenbereich unberührt
  pruef('V_Blech = 2·M_Knoten/h  (Gleichgewicht am Blech)',
        bl.V, (2 * bl.M_Knoten) / m.h, 1e-9, 'kN');

  // STEIFER KNOTENBEREICH: nachgewiesen wird am Anschnitt des Gurtes.
  //   M_Rd = M_Knoten · L_c / h
  pruef('M_Rd am Anschnitt = M_Knoten · L_c/h',
        bl.M, bl.M_Knoten * (bl.lichteLaenge / m.h), 1e-12, 'kNm');
  // Gegenprobe über das Gleichgewicht des Blechs selbst:
  //   M_Rd = V_Blech · L_c / 2
  pruef('Gegenprobe  M_Rd = V_Blech · L_c/2', bl.M, (bl.V * bl.lichteLaenge) / 2, 1e-9, 'kNm');
  wahr('Abminderung durch den steifen Bereich liegt unter 1',
       bl.abminderung < 1 && bl.abminderung > 0.5,
       `L_c = ${(bl.lichteLaenge * 1000).toFixed(0)} mm bei h = ${(m.h * 1000).toFixed(0)} mm ` +
       `→ ${(bl.abminderung * 100).toFixed(1)} %`);
  pruef('Steife Länge je Ende = (h − L_c)/2',
        bl.steifeLaenge, (m.h - bl.lichteLaenge) / 2, 1e-12, 'm');

  // Beide Nachbarbleche des Schnitts werden getrennt ausgewiesen
  wahr('Schnitt weist beide Nachbarbleche aus',
       Boolean(s.nachbarn?.links && s.nachbarn?.rechts),
       `links x = ${s.nachbarn.links.stationX.toFixed(2)} m, ` +
       `rechts x = ${s.nachbarn.rechts.stationX.toFixed(2)} m`);
  wahr('Massgebend ist das ungünstigere der beiden',
       s.eta === Math.max(s.nachbarn.links.eta, s.nachbarn.rechts.eta));
}

// ===========================================================================
titel('7  Querschnittsklassen gegen EN 1993-1-1 Tab. 5.2');

{
  pruef('Grenze K1 bei ε=1', 9, 9, 0, '');
  wahr('c/t = 8.9 → Klasse 1', klasseAuskragend(8.9, 1) === 1);
  wahr('c/t = 9.5 → Klasse 2', klasseAuskragend(9.5, 1) === 2);
  wahr('c/t = 12  → Klasse 3', klasseAuskragend(12, 1) === 3);
  wahr('c/t = 15  → Klasse 4', klasseAuskragend(15, 1) === 4);

  const eps235 = Math.sqrt(235 / 235), eps355 = Math.sqrt(235 / 355);
  const k90 = klassifiziereWinkel(getProfil('L 90x90x9'), eps235);
  wahr('L 90x90x9 in S235 → Klasse 3', k90.klasse === 3,
       `a/t = ${(90 / 9).toFixed(2)}, Grenze Winkel 11.5·ε = 11.50`);
  const k100 = klassifiziereWinkel(getProfil('L 100x100x10'), eps355);
  wahr('L 100x100x10 in S355 → Klasse 4', k100.klasse === 4,
       `a/t = 10.00 > 11.5·ε = ${(11.5 * eps355).toFixed(2)}`);
}

// ===========================================================================
titel('8  Symmetrie und Gleichgewicht am Gesamtmodell');

{
  const w = basis({
    lastHerkunft: 'manuell', gkManuell: 2.5, wkManuell: 0.8, skManuell: 0, gammaG: 1,
    anbauteile: [teil({ name: 'A', x: 5, Gz: 8 }), teil({ name: 'B', x: 15, Gz: 8 })],
  });
  const e = rechne(w);
  const m = e.modell;
  pruef('Symmetrische Last → R_A = R_B', m.RA, m.RB, 1e-12, 'kN');
  pruef('Vertikales Gleichgewicht ΣV = q·L + ΣP',
        m.RA + m.RB, m.qd * m.L + 16, 1e-12, 'kN');
  pruef('Symmetrie M(x) = M(L−x)',
        schnittgroessen(6, m).My, schnittgroessen(14, m).My, 1e-10, 'kNm');

  // Ausnutzung symmetrisch über die Stationen
  const n = e.knoten.length;
  let maxAbw = 0;
  for (let i = 0; i < n; i++) {
    const a = e.knoten[i].eta, b = e.knoten[n - 1 - i].eta;
    maxAbw = Math.max(maxAbw, Math.abs(a - b) / Math.max(a, b, 1e-9));
  }
  pruef('Ausnutzung symmetrisch über alle Stationen', maxAbw, 0, 1e-9, '–');
}

// ===========================================================================
titel('9  Blechstaffelung und Geometrie der Typendatenbank');

{
  const fehler = T.pruefeDatenbank(getProfil);
  wahr('Typendatenbank stimmig zur Zeichnungsgeometrie', fehler.length === 0,
       fehler.length ? fehler[0] : '9 Regeln je Typ geprüft');

  for (const typ of ['J70', 'J90', 'J100', 'J120', 'J130']) {
    const j = T.getTragjoch(typ);
    const pOG = getProfil(j.og.profil), pUG = getProfil(j.ug.profil);
    const vert = j.bleche.vertikal[0];
    pruef(`${typ}  Vertikalblech = jd − aV,OG − aV,UG`,
          vert.laenge, j.jd - pOG.aV - pUG.aV, 1e-12, 'mm');
    const horFeld = j.bleche.horizontal.find((b) => b.zone === 'feld');
    pruef(`${typ}  Horizontalblech Feld = jbb − 2·ja`,
          horFeld.laenge, j.og.jbb - 2 * j.og.ja, 1e-12, 'mm');
  }

  // Staffelung symmetrisch und lückenlos
  const w = basis({ typ: 'J130', L: 30, profOG: 'L 130x130x12', profUG: 'L 120x80x12',
                    jd: 700, jbbOG: 660, jbbUG: 640 });
  const e = rechne(w);
  const br = e.modell.stationsListe.map((s) => s.vertikal?.breite);
  const symm = br.every((v, i) => v === br[br.length - 1 - i]);
  wahr('J130 Blechstaffelung spiegelsymmetrisch', symm,
       `${br[0]} … ${br[Math.floor(br.length / 2)]} … ${br[br.length - 1]} mm`);
  wahr('Staffelung fällt zur Feldmitte hin ab',
       br[0] >= br[Math.floor(br.length / 2)],
       `Auflager ${br[0]} mm, Feldmitte ${br[Math.floor(br.length / 2)]} mm`);
  wahr('Keine Station ohne Blech', br.every((v) => Number.isFinite(v)));
}

// ===========================================================================
titel('10  Massvarianten und Lastkombination');

{
  const w = basis();
  const jo = T.getTragjoch('J90');
  const pOG = getProfil('L 90x90x9');
  const mSp = modell(w, pOG, pOG, getStahl('S235'), jo, 'schwerpunkt');
  const mAu = modell(w, pOG, pOG, getStahl('S235'), jo, 'aussen');
  const mLi = modell(w, pOG, pOG, getStahl('S235'), jo, 'licht');

  pruef('h Schwerpunkt = jd − 2·zsH', mSp.h * 1000, 500 - 2 * pOG.zsH * 10, 1e-9, 'mm');
  pruef('h Aussenmass = jd', mAu.h * 1000, 500, 1e-12, 'mm');
  pruef('h Lichtmass = jd − 2·t', mLi.h * 1000, 500 - 2 * pOG.t, 1e-12, 'mm');
  wahr('Hebelarme geordnet  licht < schwerpunkt < aussen',
       mLi.b < mSp.b && mSp.b < mAu.b,
       `${(mLi.b * 1000).toFixed(1)} < ${(mSp.b * 1000).toFixed(1)} < ${(mAu.b * 1000).toFixed(1)} mm`);

  // Lastbeiwerte
  const lastbasis = { gammaG: 1.35, gammaQ: 1.5, psi0: 0.5,
                      lastHerkunft: 'manuell', gkManuell: 1, wkManuell: 1, skManuell: 1,
                      schneeAktiv: true };
  const eg = rechne(basis({ ...lastbasis, lastfall: 'windYp' }));
  pruef('q_d,g = γ_G · g_k', eg.modell.qd_g, 1.35, 1e-12, 'kN/m');
  pruef('w_d = γ_Q · w_k (Wind leitend)', eg.modell.wd, 1.5, 1e-12, 'kN/m');
  pruef('q_d,s = γ_Q · ψ₀ · s_k (Schnee begleitend)',
        eg.modell.qd_s, 1.5 * 0.5, 1e-12, 'kN/m');

  const es = rechne(basis({ ...lastbasis, lastfall: 'schneep' }));
  pruef('Schnee leitend:  q_d,s = γ_Q · s_k', es.modell.qd_s, 1.5, 1e-12, 'kN/m');
  pruef('Schnee leitend:  w_d = γ_Q · ψ₀ · w_k', es.modell.wd, 1.5 * 0.5, 1e-12, 'kN/m');
}

// ===========================================================================
titel('11  Grenzfälle');

{
  const ohne = rechne(basis({ lastHerkunft: 'manuell', gkManuell: 0, wkManuell: 0,
                              skManuell: 0, anbauteile: [] }));
  pruef('Ohne Last → η = 0', ohne.max.etaGesamt, 0, 1e-12, '–');

  const kurz = rechne(basis({ L: 8 }));
  wahr('Kurze Spannweite rechnet', Number.isFinite(kurz.max.etaGesamt),
       `L = 8 m, ${kurz.stationen} Stationen, η = ${kurz.max.etaGesamt.toFixed(3)}`);

  const raster = knotenraster(20, 0.75);
  pruef('Knotenraster endet exakt bei L', raster[raster.length - 1], 20, 1e-12, 'm');
  wahr('Knotenraster beginnt bei 0', raster[0] === 0);

  const e130 = rechne(basis({ typ: 'J130', L: 34.5, profOG: 'L 130x130x12',
                              profUG: 'L 120x80x12', jd: 700, jbbOG: 660, jbbUG: 640 }));
  wahr('Grösste Spannweite J130 = 34.5 m rechnet',
       Number.isFinite(e130.max.etaGesamt),
       `${e130.stationen} Stationen, η = ${e130.max.etaGesamt.toFixed(3)}`);
}

// ===========================================================================
titel('12  Altbauweise – verjüngte Enden');

{
  // Datenbank: die geometrischen Zwangsbedingungen aller Typen
  const beanstandet = T.pruefeDatenbank(getProfil);
  wahr('Typendatenbank ohne Beanstandung', beanstandet.length === 0,
       beanstandet.length ? beanstandet[0] : `${T.tragjoche().length} Typen geprüft`);

  const alt = T.tragjoche().filter((j) => j.bauweise === 'alt');
  wahr('Sieben Typen der Altbauweise vorhanden', alt.length === 7,
       alt.map((j) => j.typ).join(', '));

  // Feldquerschnitt identisch mit dem heutigen Sortiment - unabhängige Probe,
  // dass Stückliste (alt) und Sortimentsblatt (neu) dasselbe Joch beschreiben
  alt.forEach((j) => {
    const neu = T.getTragjoch(j.typ.replace('-alt', ''));
    pruef(`${j.typ}: Bauhöhe im Feld wie ${neu.typ}`, j.jd, neu.jd, 1e-12, 'mm');
    pruef(`${j.typ}: Breite Obergurt wie ${neu.typ}`, j.og.jbb, neu.og.jbb, 1e-12, 'mm');
  });

  // Verlauf der Bauhöhe
  const j100 = T.getTragjoch('J100-alt');
  const v = T.voute(j100);
  pruef('J100-alt: Endbauhöhe = Summe der stehenden Schenkel',
        v.endJd, getProfil(j100.og.profil).aV + getProfil(j100.ug.profil).aV, 1e-12, 'mm');
  pruef('J100-alt: Bauhöhe am Jochende', T.bauhoeheAn(j100, 25, 0), v.endJd, 1e-12, 'mm');
  pruef('J100-alt: Bauhöhe am Ende des geraden Stücks',
        T.bauhoeheAn(j100, 25, v.gerade / 1000), v.endJd, 1e-12, 'mm');
  pruef('J100-alt: Bauhöhe am Knick', T.bauhoeheAn(j100, 25, v.knick / 1000),
        j100.jd, 1e-12, 'mm');
  pruef('J100-alt: Bauhöhe in Feldmitte', T.bauhoeheAn(j100, 25, 12.5), j100.jd, 1e-12, 'mm');
  // Mitte der Schräge: genau die halbe Höhendifferenz
  pruef('J100-alt: Bauhöhe in der Mitte der Schräge',
        T.bauhoeheAn(j100, 25, (v.gerade + v.neigung / 2) / 1000),
        (v.endJd + j100.jd) / 2, 1e-12, 'mm');
  wahr('J100-alt: Verlauf symmetrisch',
       Math.abs(T.bauhoeheAn(j100, 25, 2) - T.bauhoeheAn(j100, 25, 23)) < 1e-9);

  // Ausführung nach Spannweite
  pruef('J100-alt: Ausführung bei L = 20.0 m ist die erste',
        T.ausfuehrungFuer(j100, 20).l[0], 20.0, 1e-12, 'm');
  wahr('J100-alt: Ausführung bei L = 24.0 m ist III',
       T.ausfuehrungFuer(j100, 24).bez === 'III',
       T.ausfuehrungFuer(j100, 24).bez);
  wahr('J100-alt: engere Staffelung bei kurzem Joch',
       T.staffelungFuer(j100, 'vertikal', 20).find((s) => s.pos === 11).anzahl
       < T.staffelungFuer(j100, 'vertikal', 29.5).find((s) => s.pos === 11).anzahl);

  // Am verjüngten Ende liegt kein Vertikalblech
  wahr('Keine Vertikalbleche an den beiden ersten Stationen',
       T.blechAnStation(j100, 'vertikal', 0, 34, 25) === null
       && T.blechAnStation(j100, 'vertikal', 1, 34, 25) === null);
  wahr('Horizontalblech ab der zweiten Station vorhanden',
       T.blechAnStation(j100, 'horizontal', 0, 34, 25) === null
       && T.blechAnStation(j100, 'horizontal', 1, 34, 25)?.zone === 'auflager');

  // Rechenkern: Hebelarm folgt der Verjüngung
  const w = basis({ typ: 'J100-alt', L: 25, jd: j100.jd,
                    jbbOG: j100.og.jbb, jbbUG: j100.ug.jbb,
                    profOG: j100.og.profil, profUG: j100.ug.profil, a1: 0.75 });
  const e = rechne(w);
  const mAlt = e.modell;
  wahr('Modell erkennt die Verjüngung', mAlt.verlauf.aktiv === true);
  pruef('Hebelarm in Feldmitte = Feldwert', mAlt.verlauf.hAn(12.5), mAlt.h, 1e-12, 'm');
  const dhSoll = (j100.jd - v.endJd) / 1000;
  pruef('Hebelarm am Jochende um die Höhendifferenz kleiner',
        mAlt.h - mAlt.verlauf.hAn(0), dhSoll, 1e-9, 'm');
  wahr('Hebelarm nimmt zum Auflager monoton ab',
       [0, 0.5, 1.2, 1.8, 2.4, 3, 6].every((x, k, a) =>
         k === 0 || mAlt.verlauf.hAn(x) >= mAlt.verlauf.hAn(a[k - 1]) - 1e-12));

  // Gurtkraft an einer Station: N = M/(2h) mit dem ÖRTLICHEN Hebelarm
  const st = e.knoten.find((k) => k.x > 1.4 && k.x < 3.1);
  pruef('Gurtkraft mit örtlichem Hebelarm  N = M_y/(2·h(x))',
        Math.abs(st.ecken[0].N_My), Math.abs(st.My) / (2 * mAlt.verlauf.hAn(st.x)),
        1e-9, 'kN');
  wahr('Örtlicher Hebelarm dort kleiner als im Feld',
       st.h < mAlt.h - 1e-6, `h(${st.x.toFixed(2)}) = ${(st.h * 1000).toFixed(0)} mm ` +
       `statt ${(mAlt.h * 1000).toFixed(0)} mm`);

  // Gegenprobe: dasselbe Joch ohne Verjüngung muss günstiger sein, weil der
  // Hebelarm im Endbereich grösser ist
  const eNeu = rechne(basis({ typ: 'J100', L: 25, jd: 600, jbbOG: 600, jbbUG: 560,
                              profOG: 'L 100x100x10', profUG: 'L 80x80x8', a1: 0.75 }));
  // Verglichen wird die Ausnutzung der GURTE: darum geht es hier, der
  // Hebelarm im Endbereich ist kleiner und die Gurtkräfte deshalb grösser.
  // Über η_gesamt liefe der Vergleich an den Blechen, und die hängen am
  // Endfeldzuschlag und an der Blechgrösse des jeweiligen Typs - das ist eine
  // andere Frage.
  const etaGurt = (r) => Math.max(...r.knoten.map((k) => k.etaL));
  wahr('Verjüngtes Joch: die Gurte sind ungünstiger als beim durchgehenden',
       etaGurt(e) >= etaGurt(eNeu) - 1e-9,
       `alt η_L = ${etaGurt(e).toFixed(3)}, neu η_L = ${etaGurt(eNeu).toFixed(3)}`);

  // Alle sieben Typen rechnen über ihren ganzen Längenbereich
  let ok = true, meldung = '';
  alt.forEach((j) => {
    [j.laengeNorm[0], (j.laengeNorm[0] + j.laengeNorm[1]) / 2, j.laengeNorm[1]]
      .forEach((L) => {
        const r = rechne(basis({ typ: j.typ, L, jd: j.jd, jbbOG: j.og.jbb,
                                 jbbUG: j.ug.jbb, profOG: j.og.profil,
                                 profUG: j.ug.profil, a1: j.teilung / 1000 }));
        if (!Number.isFinite(r.max.etaGesamt)) { ok = false; meldung = `${j.typ} L=${L}`; }
      });
  });
  wahr('Alle Typen der Altbauweise rechnen über den ganzen Längenbereich', ok,
       meldung || '21 Spannweiten geprüft');
}

// ===========================================================================
titel('13  Blecheinteilung nach Mass-Tabelle und Gabel am Jochende');

{
  const j80 = T.getTragjoch('J80');
  // Die Mass-Tabelle gilt für ALLE Typen und hängt nur von der Jochlänge ab.
  const zeilen = Object.entries(T.datenbank().masstabelle.zeilen);
  wahr('Mass-Tabelle hinterlegt', zeilen.length >= 50, `${zeilen.length} Längen`);

  // Bedingung der Zeichnung: 2·750 + 2·ΣA = Jochlänge
  const schlecht = zeilen.filter(([k, A]) =>
    !pruefeAbstaende(parseFloat(k), 0.75, A.map((v) => v / 1000)).ok);
  const bekannt = T.masstabelleUnschluessig();
  wahr('Jede Tabellenzeile geht auf – ausser den ausgewiesenen',
       schlecht.every(([k]) => bekannt.includes(k)),
       schlecht.length ? `nicht schlüssig: ${schlecht.map(([k]) => k).join(', ')}`
                       : `${zeilen.length} Zeilen geprüft`);
  wahr('Unschlüssige Zeilen werden nicht verwendet',
       bekannt.every((k) => T.abstaendeFuer(j80, parseFloat(k)) === null),
       bekannt.join(', '));

  // Stationsraster: Enden enthalten, Aufbau aus der Tabelle
  const A16 = T.abstaendeFuer(j80, 16.0);
  const xs = knotenraster(16.0, 0.75, A16);
  pruef('J80 16.00 m: erste Station bei 750 mm', xs[1], 0.75, 1e-12, 'm');
  pruef('J80 16.00 m: Raster beginnt am Jochende', xs[0], 0, 1e-12, 'm');
  pruef('J80 16.00 m: Raster endet am Jochende', xs[xs.length - 1], 16.0, 1e-9, 'm');
  pruef('J80 16.00 m: Stationszahl', xs.length, 23, 1e-12, '–');
  wahr('J80 16.00 m: Raster symmetrisch',
       xs.every((x, i) => Math.abs(x - (16.0 - xs[xs.length - 1 - i])) < 1e-9));

  // Gegenprobe mit den Stückzahlen der Werkstattzeichnung:
  // je Ebene hat die Vertikalebene genau zwei Bleche mehr - die an den Enden.
  const zaehle = (L, ebene) => {
    const A = T.abstaendeFuer(j80, L);
    const n = knotenraster(L, 0.75, A).length;
    let k = 0;
    for (let i = 0; i < n; i++) if (T.blechAnStation(j80, ebene, i, n, L)) k++;
    return k;
  };
  [[8.0, 13, 11], [9.0, 14, 12], [16.0, 23, 21], [23.5, 33, 31]].forEach(([L, v, h]) => {
    pruef(`J80 ${L.toFixed(2)} m: Vertikalbleche je Ebene`, zaehle(L, 'vertikal'), v, 1e-12, 'Stk');
    pruef(`J80 ${L.toFixed(2)} m: Horizontalbleche je Ebene`, zaehle(L, 'horizontal'), h, 1e-12, 'Stk');
  });

  // Halbes Mittelfeld: bei 9.00 m schreibt die Zeichnung A1 = 340 = halbes Feld
  const A9 = T.abstaendeFuer(j80, 9.0);
  const x9 = knotenraster(9.0, 0.75, A9);
  wahr('J80 9.00 m: kein Blech in Jochmitte (halbes Mittelfeld)',
       !x9.some((x) => Math.abs(x - 4.5) < 1e-6),
       `${x9.length} Stationen, nächste bei ${x9.reduce((a, b) =>
         Math.abs(b - 4.5) < Math.abs(a - 4.5) ? b : a).toFixed(3)} m`);

  // Gabel: an den Jochenden liegt ein Vertikal-, aber kein Horizontalblech
  const n16 = xs.length;
  wahr('Gabel: Vertikalblech am Jochende vorhanden',
       Boolean(T.blechAnStation(j80, 'vertikal', 0, n16, 16))
       && Boolean(T.blechAnStation(j80, 'vertikal', n16 - 1, n16, 16)));
  wahr('Gabel: kein Horizontalblech am Jochende',
       T.blechAnStation(j80, 'horizontal', 0, n16, 16) === null
       && T.blechAnStation(j80, 'horizontal', n16 - 1, n16, 16) === null);
  wahr('Auflagerblech steht an der ersten Station nach der Gabel',
       T.blechAnStation(j80, 'horizontal', 1, n16, 16)?.zone === 'auflager');

  // Kein Nachweis auf ein Blech, das es nicht gibt
  const w80 = basis({ typ: 'J80', L: 16, jd: j80.jd, jbbOG: j80.og.jbb,
                      jbbUG: j80.ug.jbb, profOG: j80.og.profil,
                      profUG: j80.ug.profil, a1: 0.75 });
  const e80 = rechne(w80);
  const rand = e80.knoten[0];
  wahr('Am Jochende wird nur die Vertikalebene nachgewiesen',
       rand.ebenen.filter((eb) => eb.art === 'horizontal').every((eb) => eb.blechFehlt)
       && rand.ebenen.filter((eb) => eb.art === 'vertikal').every((eb) => !eb.blechFehlt));
  pruef('J80 16.00 m: Modell nutzt die Mass-Tabelle',
        e80.modell.abstaende.length, A16.length, 1e-12, 'Felder');
  wahr('Teilungsquelle ist die Mass-Tabelle',
       e80.modell.teilungQuelle === 'masstabelle', e80.modell.teilungQuelle);
}

// ===========================================================================
titel('14  Grundrissknick – Breite über die Länge');

{
  // Die lichte Weite am Auflager ist die Gabel für den Mast und muss über
  // ALLE Typen einer Bauweise gleich sein.
  const lichte = (j, g) => j[g].jba - 2 * j[g].ja;
  // Vergleichsmodelle (sortiment: false) bilden ein fremdes Bauwerk nach und
  // halten die Regeln des Sortiments nicht ein.
  const neu = T.sortimentstypen().filter((j) => j.bauweise !== 'alt');
  const alt = T.sortimentstypen().filter((j) => j.bauweise === 'alt');
  wahr('Lichte Auflagerweite bei allen heutigen Typen 340 mm',
       neu.every((j) => lichte(j, 'og') === 340 && lichte(j, 'ug') === 340),
       `${neu.length} Typen`);
  wahr('Lichte Auflagerweite bei allen Alttypen 280 mm',
       alt.every((j) => lichte(j, 'og') === 280 && lichte(j, 'ug') === 280),
       `${alt.length} Typen`);

  // Ab J100 ist der Obergurt im Feld breiter als der Untergurt
  const j130 = T.getTragjoch('J130');
  wahr('J130: Obergurt im Feld breiter als Untergurt',
       j130.og.jbb > j130.ug.jbb, `${j130.og.jbb} / ${j130.ug.jbb} mm`);

  pruef('J130: Breite am Jochende = jba', T.breiteAn(j130, 'og', 20, 0),
        j130.og.jba, 1e-12, 'mm');
  pruef('J130: Breite am ersten Knick noch jba',
        T.breiteAn(j130, 'og', 20, j130.jk / 1000), j130.og.jba, 1e-12, 'mm');
  pruef('J130: Breite am zweiten Knick = jbb',
        T.breiteAn(j130, 'og', 20, j130.jkk / 1000), j130.og.jbb, 1e-12, 'mm');
  pruef('J130: Breite in Feldmitte = jbb', T.breiteAn(j130, 'og', 20, 10),
        j130.og.jbb, 1e-12, 'mm');
  pruef('J130: Breite in der Mitte des Übergangs',
        T.breiteAn(j130, 'og', 20, (j130.jk + j130.jkk) / 2000),
        (j130.og.jba + j130.og.jbb) / 2, 1e-9, 'mm');
  wahr('J130: Grundriss symmetrisch',
       Math.abs(T.breiteAn(j130, 'og', 20, 1.1) - T.breiteAn(j130, 'og', 20, 18.9)) < 1e-9);

  // Rechenkern: b folgt dem Knick
  const w = basis({ typ: 'J130', L: 30, jd: j130.jd, jbbOG: j130.og.jbb,
                    jbbUG: j130.ug.jbb, profOG: j130.og.profil,
                    profUG: j130.ug.profil, a1: 0.75 });
  const e = rechne(w);
  const m = e.modell;
  wahr('Modell erkennt den Grundrissknick', m.breite.aktiv === true);
  pruef('Hebelarm b in Feldmitte = Feldwert', m.breite.bAn(15), m.b, 1e-12, 'm');
  const dbSoll = ((j130.og.jba - j130.og.jbb) + (j130.ug.jba - j130.ug.jbb)) / 2 / 1000;
  pruef('Hebelarm b am Auflager um die halbe Breitenänderung kleiner',
        m.breite.bAn(0) - m.b, dbSoll, 1e-9, 'm');

  // Torsionsschubfluss folgt b(x): schmaler Querschnitt -> grössere Ebenenkraft
  const kAuf = e.knoten[0], kFeld = e.knoten[Math.floor(e.knoten.length / 2)];
  wahr('Schnittauswertung nutzt die örtliche Breite',
       kAuf.b < kFeld.b - 1e-6,
       `b(0) = ${(kAuf.b * 1000).toFixed(0)} mm, b(L/2) = ${(kFeld.b * 1000).toFixed(0)} mm`);

  // Typ ohne Knick: b bleibt konstant
  const ohne = rechne(basis({ typ: 'frei', jbbOG: 440, jbbUG: 440 }));
  wahr('Ohne Katalogtyp bleibt die Breite konstant', ohne.modell.breite.aktiv === false);
}

// ===========================================================================
titel('15  Lastfälle');

{
  const L = await import(J('core.lasten.js'));

  const w = basis({ lastHerkunft: 'manuell', gkManuell: 2, wkManuell: 1, skManuell: 3,
                    schneeAktiv: true, gammaG: 1.35, gammaQ: 1.5, psi0: 0.5 });
  const lf = L.lastfaelle(w);
  const holen = (k) => lf.find((x) => x.key === k);

  // 4 Wind (je Richtung ±) + 4 Schnee (Begleitwind ±y und, seit dem
  // 17. September, ±x). Dazu die zwei Havariefaelle, falls Leiter haengen.
  const nw = lf.filter((x) => x.nachweis && x.art === 'tragsicherheit');
  pruef('Acht Nachweislastfälle mit Schnee', nw.length, 8, 1e-12, 'Stk');
  // NUR die seltene Stufe: 4 Wind + 4 Schnee. Die häufige ist entfallen.
  /*
   * >>> ZWOELF, SEIT DER BETRIEBSWIND DAZUKAM (24. September). <<<
   * Acht seltene (Wind +-x/+-y, Schnee mit Wind +-y/+-x) und vier
   * Betriebswind-Faelle (staendig + Wind ψ 0.70, je Richtung).
   */
  pruef('Zwölf Lastfälle der Gebrauchstauglichkeit',
        lf.filter((x) => x.art === 'gebrauchstauglichkeit').length, 12, 1e-12, 'Stk');
  wahr('Der Wind steht in jeder Kombinationsart mit beiden Vorzeichen',
       ['WindX', 'WindY'].every((g) => ['charakteristisch', 'tragsicherheit',
         'gebrauchstauglichkeit'].every((art) => {
         const v = lf.filter((x) => x.art === art).map((x) => Math.sign(x.beiwerte[g]));
         return v.includes(1) && v.includes(-1);
       })));
  /* =======================================================================
   * >>> DIE BETRIEBSSTUFE (Weisung vom 24. September). <<<
   *
   * «Die Gebrauchstauglichkeit kombination ist in diesem fall der Wind bei
   *  0.70 (Betriebswind Wiederkehrperioda 5 Jahre).»
   *
   * Hier stand «nur die seltene Stufe, keine haeufige» - mit der
   * Begruendung, die haeufige bediene keinen Nachweis, den dieses Werkzeug
   * fuehrt. Seit dem Verformungsnachweis (core.verformung.js) tut sie es.
   *
   * VIER Faelle, nicht acht: «nur Wind» braucht keinen eigenen - die
   * charakteristischen Windfaelle tragen den Wind allein mit Beiwert 1,
   * und 0.70 davon ist derselbe Zustand.
   * ===================================================================== */
  {
    const gzg = lf.filter((x) => x.art === 'gebrauchstauglichkeit');
    const betrieb = gzg.filter((x) => x.stufe === 'betrieb');
    pruef('Davon vier in der Betriebsstufe', betrieb.length, 4, 1e-12, 'Stk');
    wahr('… die übrigen sind die seltene Stufe',
         gzg.filter((x) => x.stufe !== 'betrieb').every((x) => x.stufe === 'selten'));
    wahr('… Ständig mit 1.00, Wind mit ψ = 0.70',
         betrieb.every((x) => x.beiwerte.G === 1
           && Math.abs(Math.abs(x.beiwerte.WindX ?? 0) + Math.abs(x.beiwerte.WindY ?? 0)
                       - L.BETRIEBSWIND) < 1e-12),
         betrieb.map((x) => `${x.beiwerte.WindX}/${x.beiwerte.WindY}`).join(' '));
    wahr('… und keiner ist ein Nachweis (die Tragsicherheit färbt allein)',
         gzg.every((x) => x.nachweis === false));
    pruef('Der Betriebswind ist ψ = 0.70', L.BETRIEBSWIND, 0.70, 1e-12, '–');
  }

  // ZUOBERST DIE EINZELNEN LASTARTEN, jede für sich und charakteristisch.
  const chars = lf.filter((x) => x.art === 'charakteristisch');
  wahr('Die charakteristischen Lastfälle stehen zuoberst',
       lf.slice(0, chars.length).every((x) => x.art === 'charakteristisch'));
  wahr('Ständig, Ablenkkräfte, Schnee, Wind ±y, Wind ±x, Ständig + Wind (4)',
       chars.map((x) => x.key).join(',')
         === 'gk,ablk,sk,wyk,wykm,wxk,wxkm,gwk,gwkm,gwkx,gwkxm',
       chars.map((x) => x.bez).join(' · '));
  wahr('Jede Einzellastart trägt genau eine Gruppe',
       ['sk', 'wyk', 'wxk'].every((k) => Object.values(holen(k).beiwerte)
         .filter((v) => v !== 0).length === 1));
  // Weisung vom 16. September: alle Tragwerksteile zusammen, die
  // Ablenkkraft fuer sich.
  wahr('Ständig zeigt das Tragwerk, der zweite Fall die Ablenkkräfte',
       holen('gk').nur === 'tragwerk' && holen('ablk').nur === 'ablenk'
       && holen('gwk').nur === undefined);
  wahr('Gebrauchstauglichkeit ist kein Nachweis',
       lf.filter((x) => x.art === 'gebrauchstauglichkeit')
         .every((x) => x.nachweis === false && x.beiwerte.G === 1));
  // Seit dem 17. September zwei mehr: der Havariefall (intern).
  wahr('Sechs Gruppen: G, Wind x, Wind y, Schnee, Havarie x, Havarie y',
       L.EINWIRKUNGEN.map((e) => e.key).join(',') === 'G,WindX,WindY,Schnee,HavarieX,HavarieY'
       && L.EINWIRKUNGEN.filter((e) => e.intern).length === 2,
       L.EINWIRKUNGEN.map((e) => e.label).join(' · '));

  // Die charakteristischen Lastfälle: alle Beiwerte 1.00 bzw. 0
  const gk = holen('gk'), gwk = holen('gwk');
  pruef('LF ständig: γ_G = 1.00', gk.beiwerte.G, 1, 1e-12, '–');
  pruef('LF ständig: Wind y = 0', gk.beiwerte.WindY, 0, 1e-12, '–');
  pruef('LF ständig + Wind: γ_G = 1.00', gwk.beiwerte.G, 1, 1e-12, '–');
  pruef('LF ständig + Wind: Wind y = 1.00', gwk.beiwerte.WindY, 1, 1e-12, '–');
  // Weisung vom 18. September: Wind nie in x und y zugleich.
  pruef('LF ständig + Wind +y: Wind x = 0', gwk.beiwerte.WindX, 0, 1e-12, '–');
  pruef('LF ständig + Wind +x: Wind x = 1.00, Wind y = 0',
        holen('gwkx').beiwerte.WindX + 10 * holen('gwkx').beiwerte.WindY, 1, 1e-12, '–');
  wahr('Kein vorgegebener Fall traegt Wind x und Wind y zugleich',
       lf.every((x) => !(x.beiwerte.WindX !== 0 && x.beiwerte.WindY !== 0
                         && x.art === 'charakteristisch')));
  wahr('Charakteristische Lastfälle sind kein Nachweis',
       gk.nachweis === false && gwk.nachweis === false);

  // Tragsicherheit: Leiteinwirkung voll, Begleiteinwirkung mit ψ₀
  pruef('Wind y +: Wind y = +γ_Q', holen('windYp').beiwerte.WindY, 1.5, 1e-12, '–');
  pruef('Wind y −: Wind y = −γ_Q', holen('windYm').beiwerte.WindY, -1.5, 1e-12, '–');
  pruef('Wind x +: Wind x = +γ_Q', holen('windXp').beiwerte.WindX, 1.5, 1e-12, '–');
  pruef('Wind x −: Wind x = −γ_Q', holen('windXm').beiwerte.WindX, -1.5, 1e-12, '–');
  pruef('Wind y leitend: Wind x bleibt aus', holen('windYp').beiwerte.WindX, 0, 1e-12, '–');
  pruef('Wind x leitend: Wind y bleibt aus', holen('windXp').beiwerte.WindY, 0, 1e-12, '–');
  pruef('Wind leitend: Schnee = γ_Q · ψ₀', holen('windYp').beiwerte.Schnee, 0.75, 1e-12, '–');
  pruef('Schnee leitend: Schnee = γ_Q', holen('schneep').beiwerte.Schnee, 1.5, 1e-12, '–');
  pruef('Schnee leitend: Wind y = γ_Q · ψ₀', holen('schneep').beiwerte.WindY, 0.75, 1e-12, '–');
  pruef('Schnee leitend −: Wind y = −γ_Q · ψ₀',
        holen('schneem').beiwerte.WindY, -0.75, 1e-12, '–');
  wahr('Ständige Einwirkung wird nie umgekehrt',
       lf.every((x) => (x.beiwerte.G ?? 0) >= 0));

  // Ohne Schnee auf dem Joch, aber mit Q_z am Anbauteil bleibt die Gruppe aktiv
  const ohneSchnee = basis({ schneeAktiv: false, anbauteile: [] });
  const zaehl = (o, art) => L.lastfaelle(o).filter((x) => x.art === art).length;
  // Vier Tragsicherheits-, vier seltene und vier Betriebswind-Faelle.
  wahr('Ohne Schnee und ohne Q_z: vier Nachweislastfälle',
       zaehl(ohneSchnee, 'tragsicherheit') === 4
       && zaehl(ohneSchnee, 'gebrauchstauglichkeit') === 8,
       `${zaehl(ohneSchnee, 'tragsicherheit')} / ${zaehl(ohneSchnee, 'gebrauchstauglichkeit')}`);
  wahr('Ohne Schnee entfällt auch der charakteristische Schneelastfall',
       !L.lastfaelle(ohneSchnee).some((x) => x.key === 'sk'));
  const mitQz = basis({ schneeAktiv: false,
                        anbauteile: [teil({ name: 'P', x: 10, Qz: 5 })] });
  const flachQz = A.expandiereAnbauteile(mitQz.anbauteile, {});
  wahr('Q_z am Anbauteil hält die Gruppe Schnee aktiv',
       zaehl({ ...mitQz, anbauteileFlach: flachQz }, 'tragsicherheit') === 8);

  // --- Doppelte Lastfälle werden gekennzeichnet -----------------------------
  // Mit den charakteristischen Einzellastfaellen sind fuenf Faelle dazu-
  // gekommen, die man sich vorher von Hand anlegen musste. Ein solcher
  // Eigenlastfall rechnet dann dasselbe zweimal.
  {
    const mitEigen = { ...w, lastfaelleEigen: [
      { bez: 'ständige schnee', beiwerte: { G: 1, Schnee: 1 } },
      { bez: 'Wind y', beiwerte: { WindY: 1 } },
    ] };
    const alle = L.lastfaelle(mitEigen);
    const wy = alle.find((x) => x.bez === 'Wind y');
    const gs = alle.find((x) => x.bez === 'ständige schnee');
    wahr('Der doppelte Eigenlastfall ist gekennzeichnet',
         wy.doppeltZu === 'wyk', `doppelt zu «${wy.doppeltBez}»`);
    wahr('Ein Eigenlastfall ohne Entsprechung nicht',
         gs.doppeltZu === undefined);
    wahr('Die vorgegebenen Lastfälle sind nie doppelt',
         alle.filter((x) => !x.eigen).every((x) => x.doppeltZu === undefined));
    // Gekennzeichnet, NICHT entfernt: was jemand eingegeben hat, verschwindet
    // nicht von selbst.
    pruef('Er bleibt in der Liste stehen', alle.length,
          L.lastfaelle(w).length + 2, 1e-12, 'Stk');
    // Ständig (Joch) und Anbauteile haben dieselben Beiwerte und sind trotzdem
    // nicht doppelt - sie unterscheiden sich im Feld `nur`.
    wahr('Ständig und Ablenkkräfte gelten nicht als doppelt',
         alle.find((x) => x.key === 'ablk').doppeltZu === undefined);
  }

  // --- Ständig und Anbauteile ergänzen sich zur vollen ständigen Last -------
  // Die beiden charakteristischen Lastfälle blenden einander aus. Zusammen
  // müssen sie genau das ergeben, was ein Lastfall mit G = 1 ohne Filter
  // liefert - sonst geht auf dem Weg Last verloren oder wird doppelt gezählt.
  {
    const bw1 = { G: 1, WindX: 0, WindY: 0, Schnee: 0, Leiterzug: 0 };
    const mitTeil = basis({ lastHerkunft: 'manuell', gkManuell: 2, wkManuell: 0,
                            skManuell: 0, schneeAktiv: false,
                            anbauteile: [teil({ name: 'P', x: 8, Pv: 6, ev: 1.2 })] });
    const alles = rechne({ ...mitTeil, beiwerteFest: bw1 }).modell;
    const joch  = rechne({ ...mitTeil, beiwerteFest: bw1, nurLast: 'joch' }).modell;
    const anb   = rechne({ ...mitTeil, beiwerteFest: bw1, nurLast: 'anbauteile' }).modell;
    pruef('Nur Joch: die Laufmeterlast bleibt', joch.qd, alles.qd, 1e-12, 'kN/m');
    wahr('Nur Joch: keine Einzellasten', (joch.P ?? []).length === 0
         && (joch.T ?? []).length === 0);
    pruef('Nur Anbauteile: keine Laufmeterlast', anb.qd, 0, 1e-12, 'kN/m');
    pruef('Nur Anbauteile: die Einzellasten bleiben',
          (anb.P ?? []).reduce((a, x) => a + x.w, 0),
          (alles.P ?? []).reduce((a, x) => a + x.w, 0), 1e-12, 'kN');
    pruef('Joch + Anbauteile = alles (Auflagerkraft)', joch.RA + anb.RA,
          alles.RA, 1e-9, 'kN');
    const feldMy = (o) => {
      const r = rechne({ ...mitTeil, beiwerteFest: bw1, ...o });
      const mitte = r.knoten[Math.floor(r.knoten.length / 2)];
      return mitte.My;
    };
    pruef('Joch + Anbauteile = alles (Feldmoment)',
          feldMy({ nurLast: 'joch' }) + feldMy({ nurLast: 'anbauteile' }),
          feldMy({}), 1e-6, 'kNm');
    // Der Lastfall bringt den Filter selbst mit - ohne dass ihn jemand setzt.
    wahr('Der Lastfall trägt den Filter selbst',
         rechne({ ...mitTeil, lastfall: 'ablk' }).modell.qd === 0
         && rechne({ ...mitTeil, lastfall: 'gk' }).modell.qd === alles.qd);

    /*
     * TRAGWERK UND ABLENKUNG ERGAENZEN SICH EBENSO (16. September). Die
     * Ablenkkraft ist der Anteil G·F_x; «Tragwerk» traegt alles andere.
     */
    const mitAbl = basis({ lastHerkunft: 'manuell', gkManuell: 2, wkManuell: 0,
                           skManuell: 0, schneeAktiv: false,
                           anbauteile: [teil({ name: 'P', x: 8, Gz: 6, Gx: 3, ev: 1.2 })] });
    const nx = (mm) => (mm.N ?? []).reduce((a, x) => a + x.w, 0);
    const gAll = rechne({ ...mitAbl, beiwerteFest: bw1 }).modell;
    const gTw = rechne({ ...mitAbl, beiwerteFest: bw1, nurLast: 'tragwerk' }).modell;
    const gAb = rechne({ ...mitAbl, beiwerteFest: bw1, nurLast: 'ablenk' }).modell;
    pruef('Tragwerk: die Laufmeterlast bleibt', gTw.qd, gAll.qd, 1e-12, 'kN/m');
    pruef('Tragwerk: keine Kraft in der Jochachse', nx(gTw), 0, 1e-12, 'kN');
    pruef('Ablenkkräfte: keine Laufmeterlast, kein Gewicht',
          gAb.qd + (gAb.P ?? []).reduce((a, x) => a + x.w, 0), 0, 1e-12, 'kN');
    pruef('Ablenkkräfte: die ganze Kraft in der Jochachse', nx(gAb), nx(gAll), 1e-12, 'kN');
    wahr('… und sie ist nicht null', Math.abs(nx(gAll)) > 1, `${nx(gAll)} kN`);
    pruef('Tragwerk + Ablenkkräfte = alles (Auflagerkraft)', gTw.RA + gAb.RA,
          gAll.RA, 1e-9, 'kN');
  }

  // Normensätze
  const rte = { ...w, ...L.NORMENSAETZE.find((n) => n.key === 'rte').beiwerte };
  pruef('RTE: γ_G = 1.30', L.lastfaelle(rte).find((x) => x.key === 'windYp').beiwerte.G,
        1.30, 1e-12, '–');
  pruef('RTE: Begleitwind = 1.30 · 0.50',
        L.lastfaelle(rte).find((x) => x.key === 'schneep').beiwerte.WindY, 0.65, 1e-12, '–');
  wahr('Normensatz wird an den Beiwerten erkannt',
       L.erkenneNormensatz(rte)?.key === 'rte' &&
       L.erkenneNormensatz({ ...rte, gammaQ: 1.42 }) === null);

  // Anpassung eines vorgegebenen Lastfalls und eigene Lastfälle
  const ang = { ...w, lastfallAnpassung: { windYp: { Schnee: 0 } } };
  pruef('Anpassung überschreibt nur den einen Beiwert',
        L.lastfaelle(ang).find((x) => x.key === 'windYp').beiwerte.Schnee, 0, 1e-12, '–');
  pruef('Übrige Beiwerte folgen weiter dem Normensatz',
        L.lastfaelle(ang).find((x) => x.key === 'windYp').beiwerte.G, 1.35, 1e-12, '–');
  const eig = { ...w, lastfaelleEigen: [{ key: 'e1', bez: 'Montage',
                                          beiwerte: { G: 1.1, WindY: -0.8, Schnee: 0 } }] };
  pruef('Eigener Lastfall wird angehängt', L.lastfaelle(eig).length,
        L.lastfaelle(w).length + 1, 1e-12, 'Stk');
  pruef('Negativer Beiwert bleibt erhalten',
        L.beiwerteFuer(eig, 'e1').WindY, -0.8, 1e-12, '–');

  // Die Beiwerte kommen bis in die Bemessungslasten durch
  const cw = rechne({ ...w, lastfall: 'gwk' });
  pruef('LF ständig + Wind: q_d = g_k', cw.modell.qd, 2, 1e-12, 'kN/m');
  pruef('LF ständig + Wind: w_d = w_k', cw.modell.wd, 1, 1e-12, 'kN/m');
  pruef('LF ständig + Wind: kein Schnee', cw.modell.qd_s, 0, 1e-12, 'kN/m');
  // Der Wind auf das Joch hängt an Wind y, nicht an Wind x
  const nurX = rechne({ ...w, lastfall: 'windXp' });
  pruef('Wind x leitend: w_d auf das Joch = 0', nurX.modell.wd, 0, 1e-12, 'kN/m');
  const minusY = rechne({ ...w, lastfall: 'windYm' });
  pruef('Wind y −: w_d kehrt sich um', minusY.modell.wd, -1.5, 1e-12, 'kN/m');
  pruef('Wind y −: q_d bleibt unverändert', minusY.modell.qd_g, 1.35 * 2, 1e-12, 'kN/m');

  // Umhüllende und "massgebend" lassen die charakteristischen Lastfälle aus
  const { vergleichKombinationen } = await import(J('core.vierendeel.js'));
  const v = vergleichKombinationen(w, getProfil(w.profOG), getProfil(w.profUG),
                                   getStahl('S235'), T.getTragjoch('J90'));
  wahr('Massgebend ist ein Tragsicherheitslastfall',
       v.lastfaelle.find((x) => x.istMassgebend)?.nachweis === true,
       `massgebend: ${v.massgebend}`);
  const etaChar = Math.max(...v.lastfaelle.filter((x) => !x.nachweis).map((x) => x.eta));
  const etaNw = Math.max(...v.lastfaelle.filter((x) => x.nachweis).map((x) => x.eta));
  wahr('Charakteristisches η liegt unter dem Bemessungswert',
       etaChar < etaNw, `${etaChar.toFixed(3)} < ${etaNw.toFixed(3)}`);
  pruef('Umhüllende = grösstes η der Nachweislastfälle',
        v.huellkurve.max.etaGesamt, etaNw, 1e-12, '–');
}

// ===========================================================================
titel('16  Anbauteile: Befestigung und Einwirkungsgruppen');

{
  const { anbauteilLasten, befestigungsArt } = await import(J('core.anbauteile.js'));

  wahr('Befestigung folgt ohne Angabe dem Vorzeichen von z',
       befestigungsArt({ z: -1.5 }) === 'unten' && befestigungsArt({ z: 0.8 }) === 'oben');
  wahr('Angegebene Befestigung hat Vorrang',
       befestigungsArt({ z: -1.5, befestigung: 'durchgehend' }) === 'durchgehend');
  // z zählt ab der Anschlussebene, der Hebelarm ab der Jochachse: dazwischen h/2
  const { anschlussGurt, hebelarmZuAchse } = await import(J('core.anbauteile.js'));
  wahr('Durchgehend: das Vorzeichen von z bestimmt den Anschlussgurt',
       anschlussGurt({ befestigung: 'durchgehend', z: 1.0 }) === 'OG' &&
       anschlussGurt({ befestigung: 'durchgehend', z: -1.0 }) === 'UG');
  wahr('Einseitig: der angegebene Gurt gilt, unabhängig von z',
       anschlussGurt({ befestigung: 'unten', z: 1.0 }) === 'UG');
  pruef('Hängestütze z = −1.35 m am UG: e_v = 1.35 + h/2',
        hebelarmZuAchse({ befestigung: 'unten', z: -1.35 }, 0.5), 1.35 + 0.25, 1e-12, 'm');
  pruef('Jochaufsatz z = +1.00 m am OG: e_v = −(1.00 + h/2)',
        hebelarmZuAchse({ befestigung: 'oben', z: 1.0 }, 0.5), -(1.0 + 0.25), 1e-12, 'm');

  const A2 = await import(J('data.anbauteile.js'));
  wahr('Hängestütze und Jochaufsatz sind durchgehend befestigt',
       A2.getVorlage('hs-fahrdraht').befestigung === 'durchgehend' &&
       A2.getVorlage('ja-einfach').befestigung === 'durchgehend');
  wahr('Die Lampe ist einseitig befestigt',
       A2.getVorlage('lampe-led').befestigung === 'unten');

  // Q_z läuft in der Gruppe Schnee, Q_x in Wind x, Q_y in Wind y.
  // Der Rechenkern bekommt nur AUFGELÖSTE Teile - deshalb hier erst
  // expandieren, genau wie im Betrieb.
  const auf = (liste) => A2.expandiereAnbauteile(liste, {});
  const t1 = auf([teil({ name: 'P', x: 10, Gz: 4, Qz: 6, Qy: 2 })]);
  const r = anbauteilLasten(t1, { beiwerte: { G: 2, WindX: 7, WindY: 3, Schnee: 5 } }, 0.45);
  pruef('F_z = β_G · G_z + β_Schnee · Q_z',
        r.teile.reduce((s, t) => s + t.Fz, 0), 2 * 4 + 5 * 6, 1e-12, 'kN');
  pruef('F_y = β_WindY · Q_y',
        r.teile.reduce((s, t) => s + t.Fy, 0), 3 * 2, 1e-12, 'kN');
  const t1x = auf([teil({ name: 'P', x: 10, Qx: 2, Qy: 2 })]);
  const rx = anbauteilLasten(t1x, { beiwerte: { G: 0, WindX: 7, WindY: 3, Schnee: 0 } }, 0.45);
  pruef('Q_x hängt an Wind x, nicht an Wind y',
        rx.teile.reduce((s, t) => s + t.Fx, 0), 7 * 2, 1e-12, 'kN');
  const rMinus = anbauteilLasten(t1x,
    { beiwerte: { G: 0, WindX: -7, WindY: 3, Schnee: 0 } }, 0.45);
  pruef('Negativer Windbeiwert kehrt F_x um',
        rMinus.teile.reduce((s, t) => s + t.Fx, 0), -7 * 2, 1e-12, 'kN');

  // --- Örtliche Einleitung des Moments F_y · e_v --------------------------
  // Der Hebelarm des einseitigen Kräftepaars ist der Abstand der GURTKRÄFTE,
  // nicht das Aussenmass jbb der Zeichnung: früher stand hier jbb, über den
  // Katalog gerechnet 29 bis 42 % zu viel und damit ein zu kleines
  // Kräftepaar - auf der unsicheren Seite.
  const eins = { beiwerte: { G: 1, WindX: 1, WindY: 1, Schnee: 1 },
                 jbbOG: 400, jbbUG: 400 };
  const hArm = 0.5;
  const bArm = { OG: 0.300, UG: 0.300 };
  const lasten = (bef, b = bArm) => anbauteilLasten(
    auf([{ ...teil({ name: 'A', x: 10, Qy: 4, ev: 1.5 }), befestigung: bef }]),
    eins, hArm, b);

  const durch = lasten('durchgehend');
  const einseitig = lasten('unten');
  // e_v = z-Mass 1.5 m ab Anschlussebene + h/2 = 0.25 m bis zur Jochachse
  const T = 4 * (1.5 + hArm / 2);                      // F_y · e_v = 7 kNm

  pruef('4 Punkte: ΔF_y = T / h', durch.teile[0].dFy, T / hArm, 1e-12, 'kN');
  pruef('2 Punkte: ΔF_z = T / b', einseitig.teile[0].dFz, T / 0.300, 1e-12, 'kN');
  pruef('Nicht mehr über das Aussenmass jbb',
        einseitig.teile[0].dFz / (T / 0.400), 400 / 300, 1e-12, '–');
  // Der Hebelarm darf auch als Funktion (x, Gurt) kommen - so weiss er von
  // der Massvariante und vom Grundrissknick.
  pruef('Der Hebelarm darf ortsabhängig sein',
        lasten('unten', (x, g) => (g === 'UG' ? 0.25 : 0.40)).teile[0].dFz,
        T / 0.25, 1e-12, 'kN');
  // Der obere Anschluss zieht den Hebelarm des OBERgurts, der untere den des
  // Untergurts - sonst hinge das Kräftepaar am falschen Gurtpaar.
  pruef('Der obere Anschluss nimmt den Hebelarm des Obergurts',
        lasten('oben', { OG: 0.20, UG: 0.90 }).teile[0].dFz
        / lasten('oben', { OG: 0.40, UG: 0.90 }).teile[0].dFz, 2, 1e-12, '–');
  pruef('Der untere den des Untergurts',
        lasten('unten', { OG: 0.90, UG: 0.20 }).teile[0].dFz
        / lasten('unten', { OG: 0.90, UG: 0.40 }).teile[0].dFz, 2, 1e-12, '–');
  wahr('4 Punkte belasten die Horizontalebenen',
       durch.lokal.every((l) => l.ebene === 'horizontal'));
  wahr('2 Punkte belasten die Vertikalebenen',
       einseitig.lokal.every((l) => l.ebene === 'vertikal'));
  wahr('4 Punkte greifen an beiden Gurten an, 2 Punkte an einem',
       new Set(durch.lokal.map((l) => l.gurt)).size === 2 &&
       new Set(einseitig.lokal.map((l) => l.gurt)).size === 1);
  pruef('Kräftepaar ist in sich im Gleichgewicht',
        durch.lokal.reduce((s, l) => s + l.dF, 0), 0, 1e-12, 'kN');
  pruef('Anzahl Anschlusspunkte 4 bzw. 2',
        durch.teile[0].punkte.length - einseitig.teile[0].punkte.length, 2, 1e-12, 'Stk');

  // Der Hebelarm folgt der MASSVARIANTE, quer durch den ganzen Rechenkern.
  {
    const haenge = { id: 'H', vorlage: 'direkt', name: 'Hängestütze', x: 6, raster: 0.4,
      seite: 'rechts', befestigung: 'unten', aktiv: true, module: [],
      lasten: [{ einwirkung: 'WindY', x: 0, y: 0, z: 1.6,
                 Fx: 0, Fy: 1.5, Fz: 0, Mxx: 0, Myy: 0, Mzz: 0 }] };
    const mv = (v) => rechne(basis({ massVariante: v, anbauteile: [haenge],
      beiwerteFest: { G: 0, WindX: 0, WindY: 1, Schnee: 0, Leiterzug: 0 } }));
    const sp = mv('schwerpunkt'), au = mv('aussen');
    // Aussenmass = grösserer Hebelarm = kleineres Kräftepaar.
    wahr('Der Hebelarm folgt der Massvariante',
         Math.abs(sp.modell.teile[0].dFz) > Math.abs(au.modell.teile[0].dFz),
         `Schwerpunkt ${sp.modell.teile[0].dFz.toFixed(2)} gegen Aussenmass `
         + `${au.modell.teile[0].dFz.toFixed(2)} kN`);
    // Genau T_d geteilt durch den Gurtabstand - je GURT, nicht im Mittel:
    // die Hängestütze hängt am Untergurt. (Ein reiner Verhältnisvergleich
    // ginge hier fehl: mit der Massvariante ändert sich auch h und damit der
    // Hebelarm e_v des Torsionsmoments selbst.)
    const Td = (m) => { const t = m.teile[0];
      return t.Fy * t.ev + t.Fz * t.ex + t.Mxx; };
    pruef('ΔF_z = T_d / b_UG, Schwerpunktsabstand',
          sp.modell.teile[0].dFz, Td(sp.modell) / sp.modell.bGurt.UG, 1e-9, 'kN');
    pruef('ΔF_z = T_d / b_UG, Aussenmass',
          au.modell.teile[0].dFz, Td(au.modell) / au.modell.bGurt.UG, 1e-9, 'kN');
    pruef('Aussenmass heisst genau jbb', au.modell.bGurt.UG,
          au.modell.jbbUG / 1000, 1e-12, 'm');
    wahr('Schwerpunktsabstand ist deutlich kleiner als jbb',
         sp.modell.bGurt.UG < 0.9 * au.modell.bGurt.UG,
         `${(1000 * sp.modell.bGurt.UG).toFixed(0)} gegen `
         + `${(1000 * au.modell.bGurt.UG).toFixed(0)} mm`);
  }

  // Das Kräftepaar kommt im Blechnachweis an
  const { ebenenQuerkraefte } = await import(J('core.querschnitt.js'));
  // Stationen so gelegt, dass beide Einleitungsstellen auf x = 10 fallen -
  // dann trägt dieses eine Blech das ganze Kräftepaar.
  // Faktor 1: geprueft wird hier der Mechanismus des VOLLEN Kraeftepaars;
  // die Abminderung (17. September) folgt darunter.
  const mLok = { b: 0.4, h: 0.5, a1eff: 0.75, torsionsverteilung: 'schubfluss',
                 lokal: durch.lokal, stationsX: [0, 10, 20], oertlichFaktor: 1 };
  const sg0 = { Vz: 0, Vy: 0, Tx: 0 };
  const fern = ebenenQuerkraefte(sg0, mLok, 0);          // weit weg vom Teil
  const nah = ebenenQuerkraefte(sg0, mLok, 10);          // am Teil
  pruef('Fern vom Anbauteil kein örtlicher Anteil', fern.horizontal.anteilLokal,
        0, 1e-12, 'kN');
  pruef('Am Anbauteil trägt die Horizontalebene das ganze Kräftepaar',
        nah.horizontal.anteilLokal, T / hArm, 1e-12, 'kN');
  pruef('Die Vertikalebene bleibt davon unberührt', nah.vertikal.anteilLokal,
        0, 1e-12, 'kN');
  {
    const QSo = await import(J('core.querschnitt.js'));
    const ab = ebenenQuerkraefte(sg0, { ...mLok, oertlichFaktor: undefined }, 10);
    pruef('Abgemindert: durchgehend befestigt mit dem gemessenen Faktor',
          ab.horizontal.anteilLokal, QSo.OERTLICH_FAKTOR.durchgehend * T / hArm, 1e-12, 'kN');
  }

  // Wirkung im vollständigen Nachweis: die Befestigungsart ändert η
  const mitAT = (bef) => rechne(basis({
    lastHerkunft: 'manuell', gkManuell: 0.6, wkManuell: 0.5, skManuell: 0,
    anbauteile: [{ ...teil({ name: 'HS', x: 10, Gz: 3, Qy: 4, ev: 1.5 }),
                   raster: 0.4, befestigung: bef }],
  }));
  const e4 = mitAT('durchgehend'), e2 = mitAT('unten');
  wahr('Befestigungsart wirkt sich auf die Nachweise aus',
       Math.abs(e4.max.etaGesamt - e2.max.etaGesamt) > 1e-6,
       `4 Punkte η = ${e4.max.etaGesamt.toFixed(3)} · ` +
       `2 Punkte η = ${e2.max.etaGesamt.toFixed(3)}`);
}

// ===========================================================================
titel('17  Modelldarstellung: Nachweisschnitt und Plotgrössen');

{
  const R = await import(J('render.3d.js'));

  const w = basis({ xNachweis: 10 });
  const e = rechne(w);

  // Der Nachweisschnitt ist im Grundzustand aus
  wahr('Nachweisschnitt voreingestellt ausgeschaltet',
       standardwerte().schnittAktiv === false);

  const aus = R.erzeugeSzene(e.modell, e);
  wahr('Ausgeschaltet: keine Schnittebene', aus.schnitt === null);
  wahr('Ausgeschaltet: nur die Jochlänge bleibt bemasst',
       aus.masse.every((mz) => mz.zu !== 'schnitt'),
       `${aus.masse.length} Masse`);
  wahr('Ausgeschaltet: keine Schnittkraftpfeile',
       aus.vektoren.every((v) => v.gruppe !== 'kraefte'));

  const eAn = rechne(basis({ xNachweis: 10, schnittAktiv: true }));
  const an = R.erzeugeSzene(eAn.modell, eAn);
  wahr('Eingeschaltet: Schnittebene vorhanden', Boolean(an.schnitt));
  wahr('Eingeschaltet: Vermassung des Schnitts erscheint',
       an.masse.some((mz) => mz.zu === 'schnitt' && mz.feld === 'jd'));
  wahr('Eingeschaltet: Schnittkraftpfeile erscheinen',
       an.vektoren.some((v) => v.gruppe === 'kraefte'));

  // Bemassung der Anbauteile hängt am Teil, nicht am Schnitt
  const mitTeil = rechne(basis({ anbauteile: [teil({ name: 'HS', x: 8, Gz: 5, ev: 1.2 })] }));
  const sz = R.erzeugeSzene(mitTeil.modell, mitTeil);
  wahr('Anbauteil-Bemassung ist einem Teil zugeordnet',
       sz.masse.some((mz) => mz.zu === 'AT0'));

  // --- Baugruppen im Modell -----------------------------------------------
  // Der Regressionsfall: die aufgelösten Module heissen AT-xxx#0, AT-xxx#1 …
  // Wer sie über die Kennung der BAUGRUPPE sucht, findet nie etwas - dann
  // fehlten Kraftpfeile und alle Module lägen auf derselben Höhe.
  const AG = await import(J('data.anbauteile.js'));
  const bgTeil = AG.neuesAnbauteil('hs-fahrdraht', 8);
  const mitBg = rechne(basis({ trasseRadius: 300, flSpannweite: 50,
                               anbauteile: [bgTeil] }));
  const szBg = R.erzeugeSzene(mitBg.modell, mitBg);
  const lastPfeile = szBg.vektoren.filter((v) => v.art === 'last');
  wahr('Baugruppe: Kraftpfeile werden gezeichnet', lastPfeile.length > 0,
       `${lastPfeile.length} Pfeile`);
  wahr('Jedes Modul der Baugruppe bekommt eigene Pfeile',
       new Set(lastPfeile.map((v) => v.titel.split(' · ')[1])).size >= 2,
       [...new Set(lastPfeile.map((v) => v.titel))].join(' | '));
  wahr('Die Module liegen auf verschiedenen Höhen',
       new Set(lastPfeile.map((v) => v.p[2].toFixed(4))).size >= 2);
  wahr('Baugruppe wird für den Einzelheitsblick ausgewiesen',
       (szBg.anbauteile ?? []).length === 1 && szBg.anbauteile[0].teil === 'AT0');
  wahr('Der Umriss der Baugruppe steckt in den Grenzen',
       szBg.grenzen.zMin <= szBg.anbauteile[0].zMin + 1e-9 &&
       szBg.grenzen.zMax >= szBg.anbauteile[0].zMax - 1e-9,
       `z ${szBg.grenzen.zMin.toFixed(2)} … ${szBg.grenzen.zMax.toFixed(2)} m`);
  wahr('Jedes Modul wird einzeln bemasst',
       szBg.masse.filter((mz) => mz.zu === 'AT0' && mz.achse === 'z').length >= 2);

  // Auftragbare Grössen: Wertebereiche und Zuordnung
  /*
   * SIEBEN seit dem 11. September (Weisung: «beim resultat plott noch
   * normalkraft und torsion aufnhemen zur auswahl»). N ist die Gurtkraft
   * aus dem Kraeftepaar, T das Torsionsmoment des Querschnitts.
   */
  /*
   * ACHT, seit die VERFORMUNG dazukam (24. September): «nimm die
   * verformung in die resultat plot und mache entsprechende diagramme.»
   * NEUN seit dem 25.: «setze noch ein resultat plott
   * gebrauchstauglichkeit» - die Ausnutzung dazu.
   */
  pruef('Neun auftragbare Grössen', R.PLOTS.length, 9, 1e-12, 'Stk');
  wahr('… darunter die Verformung, in Millimetern',
       R.PLOTS.some((p) => p.key === 'w' && p.feld === 'w' && p.einheit === 'mm'));
  /*
   * >>> JEDE GROESSE GEHOERT EINER NACHWEISART. <<<
   *
   * Fehlt die Angabe, gilt TRAGSICHERHEIT - η, σ, M, V, N, T stehen alle
   * auf Bemessungswerten. Das ist die harmlosere Zuordnung: eine
   * vergessene Angabe lässt die Groesse bei «nur Tragsicherheit» stehen,
   * statt sie in die Gebrauchstauglichkeit zu schieben, wo sie eine
   * falsche Aussage wäre.
   */
  wahr('Genau zwei Grössen stehen im Gebrauchszustand',
       R.PLOTS.filter((p) => p.nachweisart === 'gzg').map((p) => p.key).join(' ')
       === 'w etaGzg',
       R.PLOTS.filter((p) => p.nachweisart === 'gzg').map((p) => p.key).join(' '));
  wahr('… die übrigen tragen keine Angabe und gelten damit der Tragsicherheit',
       R.PLOTS.filter((p) => p.nachweisart !== 'gzg')
        .every((p) => p.nachweisart === undefined));
  wahr('η der Gebrauchstauglichkeit steht auf derselben Skala wie η',
       R.PLOTS.find((p) => p.key === 'etaGzg')?.fest
       === R.PLOTS.find((p) => p.key === 'eta')?.fest);
  wahr('Darunter Normalkraft und Torsion',
       ['N', 'T'].every((k) => R.PLOTS.some((p) => p.key === k)));
  wahr('Jede auftragbare Groesse nennt ihre Einheit und ihr Feld',
       R.PLOTS.every((p) => p.feld && p.einheit && p.label && p.fussnote));
  const gurt = aus.flaechen.find((f) => f.gruppe === 'profil' && f.werte);
  const blech = aus.flaechen.find((f) => f.gruppe === 'blech' && f.werte);
  wahr('Gurt führt Normalkraft, aber keine Querkraft',
       Number.isFinite(gurt.werte.N) && gurt.werte.V === null,
       `N = ${gurt.werte.N.toFixed(1)} kN`);
  wahr('Blech führt Querkraft, aber keine Normalkraft',
       Number.isFinite(blech.werte.V) && blech.werte.N === null,
       `V = ${blech.werte.V.toFixed(1)} kN`);
  R.PLOTS.forEach((p) => {
    wahr(`Wertebereich für ${p.label} ermittelt`,
         Number.isFinite(aus.bereiche[p.feld]) && aus.bereiche[p.feld] >= 0,
         `max = ${aus.bereiche[p.feld].toFixed(2)} ${p.einheit}`);
  });
  /*
   * DER BEREICH UMFASST DEN MASTEN MIT.
   *
   * Bis zum 1. September war er das groesste η des JOCHS, denn nur Gurte und
   * Bleche trugen Kennwerte. Seither faerbt sich auch der Mast ein, und sein
   * η ist am Fuss regelmaessig das groessere - fuer die Skala zaehlt, was
   * gezeichnet wird.
   */
  const etaJoch = e.max.eta.eta;
  const etaMast = e.mast?.eta ?? 0;
  pruef('η-Bereich = grösstes η des ganzen Bildes',
        aus.bereiche.eta, Math.max(etaJoch, etaMast), 1e-9, '–');
  wahr('… und der Mast bringt hier das groessere ein',
       etaMast > etaJoch, `Mast ${etaMast.toFixed(3)} gegen Joch ${etaJoch.toFixed(3)}`);
}

// ===========================================================================
/* ===========================================================================
 * >>> DER REITER SYSTEM HAT ZWEI EBENEN. <<<
 * ===========================================================================
 *
 * Weisung vom 13. September: «sidebar system aufraeumen und eine bessere
 * uebersicht schaffen.»
 *
 * Er war 3406 Pixel hoch bei 731 Pixel Fenster - viereinhalb Bildschirme.
 * Die Laenge kam nicht von zu vielen Fragen, sondern davon, dass ALLE gleich
 * laut gestellt waren: die Jochlaenge, die man dauernd aendert, stand neben
 * der Gurtbreite aus dem Katalog, die man einmal im Jahr anfasst.
 *
 * DIE REGEL, nach der sortiert wurde:
 *
 *   Erste Ebene   was man an DIESEM Tragwerk einstellt
 *   Zweite Ebene  was aus dem SORTIMENT kommt, und was einen Regelwert hat,
 *                 den man selten verlaesst
 *
 * Nachgemessen im Browser: 2437 Pixel, also 28 Prozent kuerzer.
 * ========================================================================= */
{
  const U = await import(J('ui.schema.js'));
  const w = standardwerte();
  const keys = (g) => U.sichtbareFelder(g, w).map((f) => f.key);
  const feinVon = (g) => U.sichtbareFelder(g, w).filter((f) => f.fein)
    .map((f) => f.key);

  /*
   * 1 - DIE GRUPPE 'typ' IST IN 'geo' AUFGEGANGEN.
   *
   * «Jochtyp und Rechenmasse» fuehrte GENAU EIN Feld - eine Ueberschrift
   * fuer eine Zeile -, und die Masse standen im naechsten Abschnitt, obwohl
   * der Typ sie setzt.
   */
  wahr('Die Gruppe typ gibt es nicht mehr',
       !U.GRUPPEN.some((g) => g.id === 'typ'));
  wahr('Kein Feld zeigt noch auf sie',
       !U.FELDER.some((f) => f.gruppe === 'typ'));
  wahr('Der Typ steht bei der Geometrie', keys('geo').includes('typ'));
  wahr('… und zwar als erstes', keys('geo')[0] === 'typ');
  wahr('… die Jochlaenge gleich dahinter', keys('geo')[1] === 'L');

  /*
   * 2 - WAS AUS DEM SORTIMENT KOMMT, STEHT IN DER ZWEITEN EBENE.
   *
   * Die Regel ist ableitbar und nicht nach Geschmack gesetzt: ein Feld mit
   * `ausDB` ist ohne «Werte bearbeiten» gar nicht aenderbar. Ein Feld, das
   * man nicht anfassen kann, gehoert nicht in die erste Ebene.
   */
  const ausDbSichtbar = U.sichtbareFelder('geo', w).filter((f) => f.ausDB);
  wahr('Es gibt Katalogfelder in der Geometrie', ausDbSichtbar.length >= 3);
  wahr('… und jedes davon steht in der zweiten Ebene',
       ausDbSichtbar.every((f) => f.fein),
       ausDbSichtbar.filter((f) => !f.fein).map((f) => f.key).join(', '));
  wahr('Die Masskette steht dort auch', feinVon('geo').includes('masskette'));
  wahr('Typ und Laenge dagegen nicht',
       !feinVon('geo').includes('typ') && !feinVon('geo').includes('L'));

  /*
   * 3 - WAS DEN REST BESTIMMT, BLEIBT OBEN.
   *
   * Der Schalter «Tragwerk steht auf Masten» entscheidet, ob die Gruppe
   * darunter ueberhaupt eine Frage stellt. Ein Feld, von dem die Sichtbarkeit
   * anderer abhaengt, in einen zugeklappten Block zu legen, waere die
   * schlechteste Stelle der ganzen Maske.
   */
  wahr('Der Mastschalter ist nicht fein',
       !U.FELDER.find((f) => f.key === 'mastVorhanden').fein);
  /*
   * >>> UND ER STEHT ZUOBERST - JETZT AUCH WIRKLICH. <<<
   *
   * Weisung vom 5. September: «das deaktivieren der masten im modell sollte
   * klar auswaehlbar sein.» Der Kommentar im Schema sagte es seither, der
   * Code tat es nicht: `mastX` war spaeter davorgerutscht. Erst OB es Masten
   * gibt, dann WO sie stehen.
   */
  const mk = keys('mast');
  wahr('Der Mastschalter steht zuoberst', mk[0] === 'mastVorhanden', mk[0]);
  wahr('… und die Stelle dahinter', mk[1] === 'mastX');

  /*
   * 4 - ERST WIE GELAGERT WIRD, DANN WAS DARUEBER HINAUSSTEHT.
   */
  const ak = keys('aufl');
  const vor = (a, b) => ak.indexOf(a) >= 0 && ak.indexOf(a) < ak.indexOf(b);
  wahr('Das Endauflager steht vor den Kragarmen', vor('endbedingung', 'kragA'));
  wahr('Der Anschluss ans Joch auch', vor('mastAnschluss', 'kragA'));
  wahr('Die Bedingung am Masten auch', vor('auflagerLinks', 'kragA'));
  wahr('Und die Kragarme stehen beieinander',
       ak.indexOf('kragB') === ak.indexOf('kragA') + 1);

  /* =========================================================================
   * >>> DIE LASTEN IN DER REIHENFOLGE, IN DER SIE ENTSTEHEN. <<<
   * =========================================================================
   *
   * Weisung vom 13. September: «bauteile optimieren und der lasten.»
   *
   * Die Gruppe begann mit dem Wind auf den MASTEN - einem Sonderfall, der
   * nur bei stehendem Masten gilt -, dann kam sein Schalter, dann die
   * Klassenwahl, dann der Zuschlag, und erst danach die drei
   * charakteristischen Grundlasten. Also von hinten nach vorn.
   */
  {
    const ek = keys('ein');
    const vorEin = (a, b) => ek.indexOf(a) >= 0 && ek.indexOf(b) >= 0
      && ek.indexOf(a) < ek.indexOf(b);
    wahr('Erst die Wahl, dann was daraus folgt',
         vorEin('windKlasse', 'gkManuell'), ek.join(', '));
    /*
     * MIT SCHNEE: ohne ihn stehen die beiden Schneefelder gar nicht da -
     * `schneeAktiv` schaltet sie frei. Die Kontrolle muss ihn einschalten,
     * sonst prueft sie eine leere Liste und faellt aus dem falschen Grund.
     */
    const ekS = U.sichtbareFelder('ein', { ...w, schneeAktiv: true })
      .map((f) => f.key);
    wahr('Schnee ja/nein steht vor der Schneelast',
         ekS.indexOf('schneeAktiv') < ekS.indexOf('skManuell')
         && ekS.includes('skManuell'), ekS.join(', '));
    wahr('… und die Klasse gleich dahinter',
         ekS.indexOf('schneeKlasse') === ekS.indexOf('schneeAktiv') + 1);
    wahr('Die Grundlasten stehen beieinander',
         ek.indexOf('wkManuell') === ek.indexOf('gkManuell') + 1);
    /*
     * >>> DER ZUSCHLAG UND DER MASTWIND SIND ZWEITE EBENE. <<<
     */
    const feinEin = U.sichtbareFelder('ein', { ...w, mastVorhanden: true })
      .filter((f) => f.fein).map((f) => f.key);
    for (const k of ['gZusatz', 'wMast', 'mastWindAufJoch']) {
      wahr(`${k} steht in der zweiten Ebene`, feinEin.includes(k),
           feinEin.join(', '));
    }
    /* =====================================================================
     * >>> DIE DREI GRUNDLASTEN NICHT - UND DAS IST EINE AUSNAHME. <<<
     * =====================================================================
     *
     * Sie tragen `ausLast` und sind ohne «Werte bearbeiten» gesperrt. Nach
     * der Regel aus dem Reiter System (was man nicht anfassen kann, gehoert
     * nicht in die erste Ebene) muessten sie in den Klappblock.
     *
     * SIE BLEIBEN TROTZDEM OBEN. Der Unterschied: die Katalogmasse dort
     * sagen, wie das Bauteil AUSSIEHT - diese hier sagen, was auf ihm
     * LIEGT. Man soll stets sehen, womit gerechnet wird, ohne einen Block
     * aufzuklappen. Der Vermerk steht seit jeher im Schema; hier steht er
     * als Kontrolle, damit ihn kein spaeteres Aufraeumen wegwischt.
     */
    for (const k of ['gkManuell', 'wkManuell']) {
      const f = U.FELDER.find((x) => x.key === k);
      wahr(`${k} ist gesperrt …`, f.ausLast === true);
      wahr('… steht aber in der ersten Ebene', !f.fein);
    }
    // Und die Gruppe sagt, wie ihr Block heisst.
    const gEin = U.GRUPPEN.find((g) => g.id === 'ein');
    wahr('Die Gruppe nennt ihre zweite Ebene beim Namen',
         gEin.feinTitel === 'Zuschlag und Wind auf den Masten');
  }

  /* =========================================================================
   * >>> DER REITER ANBAUTEILE FAENGT MIT DEN BAUTEILEN AN. <<<
   * =========================================================================
   *
   * Er begann mit drei Feldern, die man EINMAL einstellt - Spannweite,
   * Radius, Ablenkwinkel -, und erst darunter kam, worum es geht. An jedem
   * Arbeitsgang scrollte man daran vorbei.
   *
   * `zugeklappt` macht aus der Gruppe einen Klappabschnitt statt einer
   * Ueberschrift. Sie bleibt oben - die Ablenkung folgt aus ihr, und das
   * liest sich von oben nach unten -, kostet aber nur noch eine Zeile.
   *
   * NICHT DASSELBE WIE `fein`: fein trennt INNERHALB einer Gruppe das
   * Haeufige vom Seltenen, zugeklappt legt die ganze Gruppe beiseite.
   */
  {
    const gT = U.GRUPPEN.find((g) => g.id === 'trasse');
    wahr('Die Trasse faengt zugeklappt an', gT.zugeklappt === true);
    wahr('… und hat wirklich Felder darin',
         U.sichtbareFelder('trasse', w).length === 3,
         `${U.sichtbareFelder('trasse', w).length} Felder`);
    // Die Gruppe der Bauteile selbst bleibt offen - sie IST der Reiter.
    const gA = U.GRUPPEN.find((g) => g.id === 'anbau');
    wahr('Die Anbauteile bleiben offen', !gA.zugeklappt);
    /*
     * DIE MASKE MUSS DARAUS AUCH EINEN KLAPPABSCHNITT MACHEN. `zeichneMaske`
     * braucht ein DOM und laeuft hier nicht; geprueft wird die Quelle - das
     * ist die Stelle, an der ein Umbau das Merkmal still fallen liesse.
     */
    const uq2 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Die Maske kennt das Merkmal',
         uq2.includes('if (g.zugeklappt)')
         && uq2.includes('klapp(`gruppe-${gid}`'));
  }

  /*
   * 5 - JEDE GRUPPE MIT FEINEN FELDERN SAGT AUCH, WIE IHR BLOCK HEISST.
   *
   * Ohne Titel stuende dort «Feineinstellungen» - dreimal dasselbe Wort auf
   * einem Bildschirm, und keines sagte, was drin ist.
   */
  const mitFein = U.GRUPPEN.filter((g) =>
    U.FELDER.some((f) => f.gruppe === g.id && f.fein));
  wahr('Es gibt Gruppen mit zweiter Ebene', mitFein.length >= 3);
  wahr('… und jede traegt ihren eigenen Titel',
       mitFein.every((g) => typeof g.feinTitel === 'string' && g.feinTitel),
       mitFein.filter((g) => !g.feinTitel).map((g) => g.id).join(', '));
  wahr('Die Titel sind verschieden',
       new Set(mitFein.map((g) => g.feinTitel)).size === mitFein.length);

  /*
   * 6 - DIE MASKE BAUT DEN BLOCK AUCH WIRKLICH.
   *
   * `zeichneMaske` braucht ein DOM und laeuft hier nicht; geprueft wird die
   * Quelle. Das ist die Stelle, an der ein Umbau den Block still fallen
   * liesse - die Felder traegen dann `fein` und stuenden nirgends.
   */
  const uq = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
  wahr('Die Maske teilt in Haupt und Fein',
       uq.includes('felder.filter((f) => !f.fein)')
       && uq.includes('felder.filter((f) => f.fein)'));
  wahr('… und klappt den Block auf, wenn bearbeitet wird',
       uq.includes('werte.bearbeiten && fein.some((f) => f.ausDB)'));
}

titel('18  Oberfläche: Struktur der Eingabe');

{
  const U = await import(J('ui.schema.js'));
  const sichtbar = (g, w) => U.sichtbareFelder(g, w).map((f) => f.key);
  const w = standardwerte();

  // Keine Grösse darf zweimal bedienbar sein
  const alleSichtbaren = ['geo', 'aufl', 'prof', 'blech', 'anbau', 'ein', 'komb']
    .flatMap((g) => sichtbar(g, w));
  wahr('Nachweisschnitt nicht doppelt in der Eingabe',
       !alleSichtbaren.includes('xNachweis'),
       `Systemreiter: ${sichtbar('geo', w).join(', ')}`);
  wahr('Keine doppelten Feldschlüssel in der Maske',
       new Set(alleSichtbaren).size === alleSichtbaren.length);

  // Versteckte Felder tauchen weder in der Maske noch im Optionen-Dialog auf
  const inOptionen = U.optionenFelder(w).flatMap((a) => a.felder.map((f) => f.key));
  const versteckt = U.FELDER.filter((f) => f.versteckt).map((f) => f.key);
  wahr('Versteckte Felder erscheinen nirgends',
       versteckt.every((k) => !alleSichtbaren.includes(k) && !inOptionen.includes(k)),
       versteckt.join(', '));
  wahr('Jedes Optionsfeld ist auch als optionenDialog gekennzeichnet',
       inOptionen.every((k) => U.feld(k).optionenDialog));

  // Aufgeräumte Voreinstellungen
  pruef('Schrift im Modell 25 % kleiner als früher (13 px)',
        w.modellSchrift, 10, 1e-12, 'px');
  wahr('Lasten- und Bemassungsschrift getrennt einstellbar',
       'modellSchriftLast' in w && 'modellSchriftMass' in w);
  wahr('Nachweisschnitt startet ausgeschaltet', w.schnittAktiv === false);
}

// ===========================================================================
titel('19  Lastgenerator');

{
  const A2 = await import(J('data.anbauteile.js'));

  const r = A2.erzeugeGleislasten({ L: 20, gleise: 4, abstand: 4.5,
                                    vorlagen: ['hs-fahrdraht', 'lampe-led'] });
  pruef('4 Gleise · 2 Vorlagen = 8 Teile', r.teile.length, 8, 1e-12, 'Stk');
  pruef('Gleise symmetrisch zur Jochmitte',
        (r.gleisX[0] + r.gleisX[r.gleisX.length - 1]) / 2, 10, 1e-9, 'm');
  pruef('Gleisabstand eingehalten', r.gleisX[1] - r.gleisX[0], 4.5, 1e-9, 'm');
  wahr('Alle Teile liegen im Joch', r.teile.every((t) => t.x >= 0 && t.x <= 20));
  wahr('Teile sind dem Gleis zugeordnet',
       r.teile.filter((t) => t.gleis === 1).length === 2,
       r.teile.slice(0, 2).map((t) => t.name).join(' · '));

  // Gleise ausserhalb des Jochs werden gemeldet, nicht an den Rand geklemmt
  const eng = A2.erzeugeGleislasten({ L: 8, gleise: 4, abstand: 4.5,
                                      vorlagen: ['hs-fahrdraht'] });
  pruef('Zu breite Gleisgruppe: Gleise ausserhalb gemeldet',
        eng.ausserhalb, 2, 1e-12, 'Stk');
  wahr('Kein Teil ausserhalb des Jochs',
       eng.teile.every((t) => t.x >= 0 && t.x <= 8));

  // Versatz verschiebt die ganze Gruppe
  const v = A2.erzeugeGleislasten({ L: 20, gleise: 2, abstand: 4, versatz: 1.5,
                                    vorlagen: ['hs-fahrdraht'] });
  pruef('Versatz verschiebt die Gruppe', (v.gleisX[0] + v.gleisX[1]) / 2,
        11.5, 1e-9, 'm');

  // Eigene Vorlagen hängen sich in den Vorrat ein
  const anzahlVorher = A2.vorlagen().length;
  const eigen = A2.alsVorlage({ name: 'Sonderstütze', raster: 0.5,
    befestigung: 'durchgehend', eigengewicht: 1, ev: 2, ex: 0,
    Gz: 3, Qz: 1, Qx: 0, Qy: 2, vorlage: 'hs-nur', module: [] }, 'Sonderstütze');
  A2.setzeEigeneVorlagen([eigen]);
  pruef('Eigene Vorlage erscheint im Vorrat',
        A2.vorlagen().length - anzahlVorher, 1, 1e-12, 'Stk');
  wahr('Eigene Vorlage ist als solche gekennzeichnet',
       A2.getVorlage(eigen.id).eigen === true);
  const t = A2.neuesAnbauteil(eigen.id, 5);
  // e_v = 2 m unterhalb heisst im Koordinatenmodell z = −2 m
  pruef('Aus eigener Vorlage entsteht ein Teil mit ihren Werten',
        t.lasten.find((l) => l.einwirkung === 'G').z, -2, 1e-12, 'm');
  pruef('Ständiger Anteil G_z + Eigengewicht übernommen',
        t.lasten.find((l) => l.einwirkung === 'G').Fz, 4, 1e-12, 'kN');
  pruef('Q_y wandert in die Gruppe Wind y',
        t.lasten.find((l) => l.einwirkung === 'WindY').Fy, 2, 1e-12, 'kN');
  wahr('Befestigung wird mitgenommen', t.befestigung === 'durchgehend');
  A2.setzeEigeneVorlagen([]);
}

// ===========================================================================
titel('20  Trasse: Ablenkwinkel und Umlenkkraft');

{
  const TR = await import(J('core.trasse.js'));

  // Die Gleichheit 2·sin(α/2) = L/R ist EXAKT, nicht genähert
  [[50, 300], [60, 180], [45, 1200], [50, 300000]].forEach(([L, R]) => {
    const a = TR.ablenkwinkel(L, R);
    pruef(`2·sin(α/2) = L/R  (L=${L}, R=${R})`,
          2 * Math.sin(a / 2), L / R, 1e-12, '–');
  });

  pruef('Ablenkwinkel R = 300 m, L = 50 m',
        (TR.ablenkwinkel(50, 300) * 180) / Math.PI, 9.5604, 1e-4, '°');
  pruef('Umlenkfaktor = L/R', TR.umlenkfaktor({ L: 50, R: 300 }), 50 / 300, 1e-12, '–');

  // Umlenkkraft: Z · L/R
  const u = TR.umlenkkraft({ Z: 14.9, L: 50, R: 300 });
  pruef('U = Z · L/R', u.U, (14.9 * 50) / 300, 1e-12, 'kN');
  pruef('U verdoppelt sich bei halbem Radius',
        TR.umlenkkraft({ Z: 14.9, L: 50, R: 150 }).U / u.U, 2, 1e-12, '–');
  // Die Bogenseite steckt im VORZEICHEN des Radius, nicht in einem Schalter
  pruef('Negativer Radius lenkt in −x',
        TR.umlenkkraft({ Z: 14.9, L: 50, R: -300 }).U, -u.U, 1e-12, 'kN');
  pruef('Negativer Radius gibt einen negativen Winkel',
        TR.ablenkwinkel(50, -300), -TR.ablenkwinkel(50, 300), 1e-12, 'rad');
  pruef('Negativer Winkel überschreibt den Bogen',
        TR.umlenkkraft({ Z: 14.9, L: 50, R: 300, winkel: -9.5604 }).U,
        -u.U, 1e-4, 'kN');
  wahr('Kein Schalter "günstig/ungünstig" mehr',
       TR.WIRKUNGSWEISEN === undefined);
  wahr('Gerades Gleis erzeugt keine nennenswerte Umlenkung',
       Math.abs(TR.umlenkkraft({ Z: 14.9, L: 50, R: 300000 }).U) < 0.003,
       `${TR.umlenkkraft({ Z: 14.9, L: 50, R: 300000 }).U.toFixed(5)} kN`);
  wahr('Ohne Radius keine Umlenkung', TR.umlenkkraft({ Z: 14.9, L: 50, R: 0 }).U === 0);

  // Handeingabe des Winkels überschreibt den Bogen
  const hand = TR.umlenkkraft({ Z: 14.9, L: 50, R: 300, winkel: 9.5604 });
  pruef('Handwinkel gibt dasselbe wie der Bogen', hand.U, u.U, 1e-5, 'kN');
}

// ===========================================================================
titel('21  Lasttabelle der Fahrleitungsbauteile');

{
  // Werte gegen die Quelle: Lasttabelle, Blatt «Bauteile FL»
  const hs = FL.getFlBauteil('anbauteil-haengestuetze-od-haengerohr');
  pruef('Hängestütze Eigengewicht', hs.eigengewicht, 0.5, 1e-12, 'kN');
  pruef('Hängestütze Wind quer EK2', hs.windQuer.EK2, 0.7, 1e-12, 'kN');
  pruef('Hängestütze Wind längs EK3', hs.windLaengs.EK3, 0.8, 1e-12, 'kN');

  const ja = FL.getFlBauteil('anbauteil-jochaufsatz-norm-typ-doppelt');
  pruef('Jochaufsatz doppelt: quer ≠ längs',
        ja.windQuer.EK2 - ja.windLaengs.EK2, 1.7 - 1.3, 1e-12, 'kN');

  const nfl = FL.getFlBauteil('drahtwerk-n-fl-ts-stcu-50-fd-cu-107');
  pruef('N-FL Leiterzug = 8.5 + 6.4', nfl.leiterzug, 14.9, 1e-12, 'kN');
  pruef('R-FL Leiterzug = 10 + 12',
        FL.getFlBauteil('drahtwerk-r-fl-ts-stcu-92-fd-cu-107').leiterzug, 22, 1e-12, 'kN');
  wahr('Drahtwerke sind Streckenlasten', FL.istStreckenlast(nfl));
  wahr('Die Hängestütze ist es nicht', !FL.istStreckenlast(hs));

  // Streckenlast mal Länge, Einzellast nicht
  const wDraht = FL.flLastwerte('drahtwerk-n-fl-ts-stcu-50-fd-cu-107',
                                { ek: 'EK2', laenge: 50 });
  pruef('Drahtwerk über 50 m: G_z', wDraht.Gz, 0.02 * 50, 1e-12, 'kN');
  pruef('Drahtwerk über 50 m: Q_x', wDraht.Qx, 0.024 * 50, 1e-12, 'kN');
  const wHs = FL.flLastwerte('anbauteil-haengestuetze-od-haengerohr',
                             { ek: 'EK2', laenge: 50 });
  pruef('Einzellast wird NICHT mit der Länge multipliziert', wHs.Gz, 0.5, 1e-12, 'kN');

  // Fehlende Tabellenwerte werden ausgewiesen, nicht als Null verkauft
  wahr('Fehlender Windwert wird gemeldet',
       FL.flLastwerte('anbauteil-ausleger-typ-rohr', { ek: 'EK2' }).ohneWindQuer);

  // Windlast aus der Fläche (RTE 27200)
  pruef('w = A · q · c für EK2 und c = 1.4',
        FL.windAusFlaeche(0.25, 'EK2', 1.4), 0.25 * 1.1 * 1.4, 1e-12, 'kN');
  pruef('Referenz-Staudruck EK3', FL.staudruck('EK3'), 1.3, 1e-12, 'kN/m²');
}

// ===========================================================================
titel('22  Modulare Baugruppen');

{
  const A3 = await import(J('data.anbauteile.js'));
  const bg = A3.neuesAnbauteil('hs-fahrdraht', 10);
  wahr('Vorlage bringt ihre Module mit', (bg.module ?? []).length === 2,
       bg.module.map((m) => m.bauteil).join(' + '));

  const o = { ek: 'EK2', R: 300, spannweite: 50 };
  const flach = A3.expandiereAnbauteile([bg], o);
  pruef('Baugruppe wird in Einzellasten aufgelöst', flach.length, 2, 1e-12, 'Stk');
  wahr('Jedes Modul behält seine eigene Höhe',
       flach[0].z !== flach[1].z,
       `z = ${flach[0].z} m und ${flach[1].z} m`);
  wahr('Lage und Befestigung stammen aus der Baugruppe',
       flach.every((t) => t.x === 10 && t.befestigung === 'durchgehend'));

  const draht = flach.find((t) => t.kraefte.G.Fx !== 0);
  pruef('Umlenkkraft steht als STÄNDIGE Last in Gruppe G',
        draht.kraefte.G.Fx, (14.9 * 50) / 300, 1e-9, 'kN');
  pruef('Sie ist nicht in der Gruppe Wind x gelandet',
        draht.kraefte.WindX.Fx, 0.024 * 50, 1e-12, 'kN');
  pruef('Ablenkwinkel wird am Modul ausgewiesen', draht.alpha, 9.5604, 1e-4, '°');

  // Winkel am Modul überschreibt Radius und Spannweite
  const bgW = { ...bg, module: bg.module.map((m) => ({ ...m, winkel: -5 })) };
  const drahtW = A3.expandiereAnbauteile([bgW], o).find((t) => t.rolle === 'drahtwerk');
  pruef('Winkel am Modul überschreibt den Bogen', drahtW.alpha, -5, 1e-12, '°');
  wahr('Negativer Winkel lenkt in −x', drahtW.kraefte.G.Fx < 0);

  // Alter Stand ohne Module: die Einzelfelder werden in Lastblöcke gehoben
  const frei = { id: 'F', name: 'frei', x: 5, ev: 1, Gz: 3, Qy: 2, aktiv: true };
  const f2 = A3.expandiereAnbauteile([frei], o);
  pruef('Alte freie Eingabe wird in Gruppen aufgeteilt', f2.length, 2, 1e-12, 'Stk');
  pruef('G_z landet in der Gruppe G',
        f2.find((t) => t.einwirkung === 'G').kraefte.G.Fz, 3, 1e-12, 'kN');
  pruef('Q_y landet in der Gruppe Wind y',
        f2.find((t) => t.einwirkung === 'WindY').kraefte.WindY.Fy, 2, 1e-12, 'kN');
  pruef('e_v = 1 m wird zu z = −1 m',
        f2[0].z, -1, 1e-12, 'm');

  // Der ständige Anteil bekommt den Beiwert der Gruppe G, nicht den Windbeiwert
  const { anbauteilLasten } = await import(J('core.anbauteile.js'));
  const gemischt = A3.expandiereAnbauteile(
    [{ id: 'T', name: 'T', x: 10, raster: 0, ev: 0, Gx: 10, Qx: 4, aktiv: true }], o);
  const r = anbauteilLasten(gemischt,
                            { beiwerte: { G: 1.35, WindX: 1.5, WindY: 1.5, Schnee: 1.5 },
                              jbbOG: 440, jbbUG: 440 }, 0.45);
  pruef('F_x = γ_G · G_x + γ_Q · Q_x',
        r.teile.reduce((s, t) => s + t.Fx, 0), 1.35 * 10 + 1.5 * 4, 1e-12, 'kN');
}

// ===========================================================================
titel('22b  Lastblöcke: Angriffspunkt, Kraft, Moment');

{
  const A5 = await import(J('data.anbauteile.js'));
  const { anbauteilLasten } = await import(J('core.anbauteile.js'));
  const bw = { beiwerte: { G: 2, WindX: 3, WindY: 5, Schnee: 7 },
               jbbOG: 400, jbbUG: 400 };

  // Ein Lastblock trägt genau EINE Einwirkungsgruppe
  const at = { id: 'B', name: 'B', x: 10, raster: 0.4, befestigung: 'unten',
               aktiv: true, module: [],
               lasten: [block({ einwirkung: 'G', z: -2, y: 0.3, Fz: 4, Fx: 1 }),
                        block({ einwirkung: 'WindY', z: -2, Fy: 6 }),
                        block({ einwirkung: 'Schnee', z: -2, Fz: 2 })] };
  const flach = A5.expandiereAnbauteile([at], {});
  pruef('Je Lastblock ein aufgelöstes Teil', flach.length, 3, 1e-12, 'Stk');

  const r = anbauteilLasten(flach, bw, 0.5);
  const summe = (f) => r.teile.reduce((s, t) => s + t[f], 0);
  pruef('F_z = 2·4 + 7·2', summe('Fz'), 2 * 4 + 7 * 2, 1e-12, 'kN');
  pruef('F_y = 5·6', summe('Fy'), 5 * 6, 1e-12, 'kN');
  pruef('F_x = 2·1', summe('Fx'), 2 * 1, 1e-12, 'kN');

  // z = −2 m heisst Hebelarm e_v = +2 m; y = 0.3 m ist der Versatz e_x
  const gTeil = r.teile.find((t) => t.einwirkung === 'G');
  // z = −2 m ab der Anschlussebene, dazu h/2 = 0.25 m bis zur Jochachse
  pruef('z = −2 m am UG ergibt e_v = 2.25 m', gTeil.ev, 2.25, 1e-12, 'm');
  pruef('Torsion aus F_y · e_v', r.teile.find((t) => t.einwirkung === 'WindY').Td,
        5 * 6 * 2.25, 1e-12, 'kNm');
  pruef('Torsion aus F_z · y', gTeil.Td, 2 * 4 * 0.3, 1e-12, 'kNm');
  // VORZEICHEN: e_v zaehlt nach unten, das Kraeftepaar r × F ist deshalb
  // NEGATIV im Zaehlsinn des Feldmoments (My positiv = Obergurt Druck).
  pruef('F_x am Hebelarm e_v gibt M_y', gTeil.Myd, -2 * 1 * 2.25, 1e-12, 'kNm');
  // Gegenprobe am Gleichgewicht: gelenkiger Traeger, EIN eingepraegtes
  // Moment C_y in Feldmitte. Der Verlauf muss -C_y/L als Steigung und +C_y
  // als Sprung haben und an beiden Enden auf null zurueckkommen.
  {
    const ev = 1.5, Fx = 3, Lp = 20, C = -Fx * ev;
    const t = { id: 'E', name: 'E', x: 10, raster: 0.4, befestigung: 'unten',
      aktiv: true, seite: 'rechts', module: [],
      lasten: [{ einwirkung: 'WindX', x: 0, y: 0, z: -(1.5 - 0.25),
                 Fx, Fy: 0, Fz: 0, Mxx: 0, Myy: 0, Mzz: 0 }] };
    const e = rechne(basis({ L: Lp, endbedingung: 'gelenkig', anbauteile: [t],
      lastHerkunft: 'manuell', gkManuell: 0, wkManuell: 0, skManuell: 0,
      schneeAktiv: false,
      beiwerteFest: { G: 0, WindX: 1, WindY: 0, Schnee: 0, Leiterzug: 0 } }));
    const bei = (x) => e.knoten.reduce((a, b) =>
      (Math.abs(b.x - x) < Math.abs(a.x - x) ? b : a));
    const ev2 = e.modell.teile[0].ev;
    const C2 = -Fx * ev2;
    pruef('Links vom Angriff: Steigung −C_y/L', bei(5).My,
          (-C2 / Lp) * bei(5).x, 1e-9, 'kNm');
    pruef('Rechts davon: Sprung +C_y', bei(15).My,
          (-C2 / Lp) * bei(15).x + C2, 1e-9, 'kNm');
    pruef('An den Enden zurueck auf null', bei(Lp).My, 0, 1e-9, 'kNm');
    // Und die Last unter der Achse macht ein NEGATIVES Kraeftepaar: der
    // Verlauf steigt links an, statt zu fallen.
    wahr('Last unter der Achse: My steigt links an', bei(5).My > 0);
  }

  // Eingeprägte Momente laufen in die richtigen Schnittgrössen
  const mAT = { id: 'M', name: 'M', x: 8, raster: 0.5, befestigung: 'unten',
                aktiv: true, module: [],
                lasten: [block({ einwirkung: 'G', Mxx: 3, Myy: 4, Mzz: 5 })] };
  const rm = anbauteilLasten(A5.expandiereAnbauteile([mAT], {}), bw, 0.5);
  pruef('M_xx geht in die Torsion', rm.T.reduce((s, t) => s + t.w, 0), 2 * 3, 1e-12, 'kNm');
  pruef('M_yy geht in die Biegung M_y', rm.M.reduce((s, t) => s + t.w, 0),
        2 * 4, 1e-12, 'kNm');
  pruef('M_zz geht in die Grundrissbiegung', rm.Mz.reduce((s, t) => s + t.w, 0),
        2 * 5, 1e-12, 'kNm');

  // Eingeprägtes M_zz im Ersatzbalken: Sprung am Angriffsort, Nullstellen aussen
  const { schnittgroessen } = await import(J('core.statics.js'));
  const mm = { L: 20, qd: 0, P: [], H: [], M: [], N: [], T: [], Mz: [{ x: 8, w: 10 }],
               wd: 0, MA: 0, MB: 0, RA0: 0, torsionModell: 'huellkurve' };
  pruef('M_z(0) = 0', schnittgroessen(0, mm).Mz, 0, 1e-12, 'kNm');
  pruef('M_z(L) = 0', schnittgroessen(20, mm).Mz, 0, 1e-12, 'kNm');
  pruef('M_z links vom Angriff = −M·x/L', schnittgroessen(4, mm).Mz,
        -10 * 4 / 20, 1e-12, 'kNm');
  pruef('Sprung am Angriffsort = M', schnittgroessen(8.0001, mm).Mz -
        schnittgroessen(7.9999, mm).Mz, 10, 1e-3, 'kNm');
}

// ===========================================================================
titel('23  Windlast auf den Mast aus der Lasttabelle');

{
  const MA = await import(J('data.masten.js'));
  pruef('HEB 240, EK2', MA.mastWind('HEB 240', 'EK2'), 0.37, 1e-12, 'kN/m');
  pruef('HEB 240, EK3', MA.mastWind('HEB 240', 'EK3'), 0.44, 1e-12, 'kN/m');
  wahr('Bei den HEB-Profilen sind quer und längs gleich',
       MA.mastWind('HEB 260', 'EK2') === MA.mastWind('HEB 260', 'EK2', 'quer'));
  wahr('Beim HEM 240 entscheidet die Stegrichtung',
       MA.mastWind('HEM 240', 'EK2') === 0.38 &&
       MA.mastWind('HEM 240', 'EK2', 'quer') === 0.42,
       'Steg in Jochachse 0.38 · Steg gedreht 0.42 kN/m');
  wahr('Jedes Mastprofil hat Windwerte',
       MA.mastprofile().every((p) => p.wind?.quer?.EK2 > 0));
}

// ===========================================================================
titel('24  Auflagerblatt und freie Windfläche');

{
  const { auflagerBlatt } = await import(J('core.vierendeel.js'));
  const jo = T.getTragjoch('J90');
  const pOG = getProfil('L 90x90x9');

  const w = basis({ lastHerkunft: 'manuell', gkManuell: 2, wkManuell: 1,
                    skManuell: 0, anbauteile: [] });
  const b = auflagerBlatt(w, pOG, pOG, getStahl('S235'), jo);

  pruef('Vier Einwirkungsgruppen', b.zeilen.length, 4, 1e-12, 'Stk');
  const st = b.zeilen.find((z) => z.key === 'staendig');
  const wi = b.zeilen.find((z) => z.key === 'windY');
  const wx = b.zeilen.find((z) => z.key === 'windX');
  pruef('Wind in Jochachse trägt nichts zum Joch bei', wx.wd, 0, 1e-12, 'kN/m');

  // Ohne Beiwerte: F_z ständig = g_k · L / 2
  pruef('F_z ständig = g_k · L / 2', st.A.Fz, (2 * 20) / 2, 1e-9, 'kN');
  pruef('Wind trägt nichts zu F_z bei', wi.A.Fz, 0, 1e-9, 'kN');
  pruef('F_y Wind = w_k · L / 2', wi.A.Fy, (1 * 20) / 2, 1e-9, 'kN');
  pruef('Ständige Last erzeugt kein F_y', st.A.Fy, 0, 1e-9, 'kN');
  wahr('Symmetrische Last: beide Auflager gleich',
       Math.abs(st.A.Fz - st.B.Fz) < 1e-9 && Math.abs(wi.A.Fy - wi.B.Fy) < 1e-9);
  pruef('Summe = Gleichgewicht der Vertikallast',
        b.total.A.Fz + b.total.B.Fz, 2 * 20, 1e-9, 'kN');

  // Ein Anbauteil in Jochmitte
  const w2 = basis({ lastHerkunft: 'manuell', gkManuell: 0, wkManuell: 0,
                     skManuell: 0,
                     anbauteile: [teil({ name: 'P', x: 10, Gz: 8 })] });
  const b2 = auflagerBlatt(w2, pOG, pOG, getStahl('S235'), jo);
  pruef('Einzellast in Jochmitte teilt sich hälftig',
        b2.zeilen.find((z) => z.key === 'staendig').A.Fz, 4, 1e-9, 'kN');

  // Umlenkkraft landet in F_x, nicht in F_z
  const A4 = await import(J('data.anbauteile.js'));
  const w3 = basis({ lastHerkunft: 'manuell', gkManuell: 0, wkManuell: 0,
                     skManuell: 0, trasseRadius: 300, flSpannweite: 50,
                     anbauteile: [A4.neuesAnbauteil('hs-nur', 10)] });
  const w4 = { ...w3, anbauteile: [{ ...A4.neuesAnbauteil('hs-fahrdraht', 10) }] };
  const bx = auflagerBlatt(w4, pOG, pOG, getStahl('S235'), jo);
  pruef('F_x ständig = Umlenkkraft Z · L/R',
        bx.zeilen.find((z) => z.key === 'staendig').Fx, (14.9 * 50) / 300, 1e-9, 'kN');

  // Freie Windfläche
  const frei = { ...A4.neuesAnbauteil('hs-nur', 10) };
  frei.module = [{ bauteil: 'frei-flaeche', anzahl: 1, z: -1.5, y: 0,
                   eigengewicht: 0.9, aQuer: 0.5, aLaengs: 0.8, cw: 1.4 }];
  frei.lasten = [];
  const modVon = (liste) => liste.find((t) => t.art === 'modul');
  const f = modVon(A4.expandiereAnbauteile([frei], { ek: 'EK2', R: 0, spannweite: 50 }));
  pruef('Freie Fläche: Eigengewicht direkt', f.kraefte.G.Fz, 0.9, 1e-12, 'kN');
  pruef('Freie Fläche: Q_x = A_quer · q · c',
        f.kraefte.WindX.Fx, 0.5 * 1.1 * 1.4, 1e-12, 'kN');
  pruef('Freie Fläche: Q_y = A_längs · q · c',
        f.kraefte.WindY.Fy, 0.8 * 1.1 * 1.4, 1e-12, 'kN');
  const f3v = modVon(A4.expandiereAnbauteile([frei], { ek: 'EK3', R: 0, spannweite: 50 }));
  pruef('Freie Fläche folgt der Einwirkungsklasse',
        f3v.kraefte.WindX.Fx / f.kraefte.WindX.Fx, 1.3 / 1.1, 1e-12, '–');
  const rund = modVon(A4.expandiereAnbauteile(
    [{ ...frei, module: [{ ...frei.module[0], cw: 1.0 }] }],
    { ek: 'EK2', R: 0, spannweite: 50 }));
  pruef('Rundprofil mit c = 1.0', rund.kraefte.WindX.Fx, 0.5 * 1.1 * 1.0, 1e-12, 'kN');
}

// ===========================================================================
titel('25  Mass-Tabelle über alle Typen');

{
  const tab = T.datenbank().masstabelle.zeilen;
  const laengen = Object.keys(tab).map(parseFloat).sort((a, b) => a - b);
  pruef('Längen von 8.00 bis 34.50 m in Schritten von 0.50',
        laengen.length, 54, 1e-12, 'Zeilen');
  wahr('Lückenlos in 0.50-m-Schritten',
       laengen.every((v, i) => i === 0 || Math.abs(v - laengen[i - 1] - 0.5) < 1e-9),
       `${laengen[0]} … ${laengen[laengen.length - 1]} m`);

  // Die Tabelle gilt typunabhängig: dieselbe Länge, dieselbe Einteilung
  ['J70', 'J80', 'J90', 'J100', 'J120', 'J130'].forEach((typ) => {
    const j = T.getTragjoch(typ);
    const a = T.abstaendeFuer(j, 16.0);
    wahr(`${typ}: Einteilung bei 16.00 m wie bei allen anderen`,
         JSON.stringify(a) === JSON.stringify(T.abstaendeFuer(T.getTragjoch('J90'), 16.0)),
         `${a.length} Felder`);
  });

  // Die Felder wachsen von der Jochmitte nach aussen bis auf das Regelmass
  const a24 = tab['24.00'];
  wahr('Regelfall: alle Felder 750 mm', a24.every((v) => v === 750), `${a24.length} × 750`);
  const a20 = tab['20.00'];
  wahr('Zwischenlänge: kleinere Felder innen, 750 aussen',
       a20[0] < 750 && a20[a20.length - 1] === 750,
       a20.join(' · '));

  // Unschlüssige Zeilen: als gedruckt gespeichert, aber nicht verwendet
  const un = T.masstabelleUnschluessig();
  pruef('Drei Zeilen der Zeichnung gehen nicht auf', un.length, 3, 1e-12, 'Stk');
  un.forEach((k) => {
    const z = T.masstabelleZeile(parseFloat(k));
    wahr(`${k} m ist als NICHT schlüssig erkannt`, !z.gueltig,
         `Ist ${z.ist} mm statt ${z.soll} mm (Δ ${z.ist - z.soll})`);
    wahr(`${k} m wird nicht für die Teilung verwendet`,
         T.abstaendeFuer(T.getTragjoch('J130'), parseFloat(k)) === null);
  });

  // Bei einer unschlüssigen Länge fällt der Rechenkern auf gleichmässig zurück
  const e = rechne(basis({ typ: 'J130', L: 29.0 }));
  wahr('Unschlüssige Länge: Rechenkern teilt gleichmässig und weist es aus',
       e.modell.teilungQuelle === 'gleichmaessig',
       `L = 29.00 m, ${e.stationen} Stationen`);
  const eOk = rechne(basis({ typ: 'J130', L: 30.0 }));
  wahr('Schlüssige Länge: Rechenkern nimmt die Mass-Tabelle',
       eOk.modell.teilungQuelle === 'masstabelle',
       `L = 30.00 m, ${eOk.stationen} Stationen`);
}


// ===========================================================================
titel('26  Lastarten im Modell und Vorlagen ganzer Tragwerke');

{
  const R = await import(J('render.3d.js'));
  const A6 = await import(J('data.anbauteile.js'));
  const ST = await import(J('store.js'));
  const U = await import(J('ui.js'));

  // --- Lastarten -----------------------------------------------------------
  pruef('Fünf Lastarten', R.LASTARTEN.length, 5, 1e-12, 'Stk');
  wahr('Jede Einwirkungsgruppe hat eine Lastart',
       ['G', 'WindX', 'WindY', 'Schnee'].every(
         (g) => R.LASTARTEN.some((l) => l.key === R.LASTART_VON_GRUPPE[g])));

  const bg = A6.neuesAnbauteil('hs-fahrdraht', 8);
  // Lastfall «Ständig + Wind»: dort stehen beide Windrichtungen mit 1.00, und
  // nur dann können auch beide im Bild sein.
  const e = rechne(basis({ trasseRadius: 300, flSpannweite: 50, schneeAktiv: true,
                           lastfall: 'gwk', anbauteile: [bg] }));
  const sz = R.erzeugeSzene(e.modell, e);
  const pfeile = sz.vektoren.filter((v) => v.art === 'last');
  wahr('Jeder Lastpfeil trägt seine Lastart',
       pfeile.length > 0 && pfeile.every((v) => v.lastart));
  wahr('Die Umlenkkraft steht als eigene Lastart da',
       pfeile.some((v) => v.lastart === 'leiterzug'),
       pfeile.filter((v) => v.lastart === 'leiterzug').map((v) => v.text).join(' · '));
  // Seit dem 18. September traegt kein Fall beide Richtungen zugleich -
  // Wind x steht im Fall «Ständig + Wind +x».
  const pfeileX = R.erzeugeSzene(...(() => {
    const ex = rechne(basis({ trasseRadius: 300, flSpannweite: 50, schneeAktiv: true,
                              lastfall: 'gwkx', anbauteile: [bg] }));
    return [ex.modell, ex];
  })()).vektoren.filter((v) => v.art === 'last');
  wahr('Wind x und Wind y sind getrennt aufgetragen',
       pfeileX.some((v) => v.lastart === 'windX') && !pfeileX.some((v) => v.lastart === 'windY')
       && pfeile.some((v) => v.lastart === 'windY') && !pfeile.some((v) => v.lastart === 'windX'),
       [...new Set([...pfeile, ...pfeileX].map((v) => v.lastart))].join(' · '));
  // Im Lastfall «Wind y leitend» darf gar kein Wind-x-Pfeil stehen: dort ist
  // die Gruppe ausgeschaltet.
  const eY = rechne(basis({ trasseRadius: 300, flSpannweite: 50,
                            lastfall: 'windYp', anbauteile: [bg] }));
  wahr('Wind y leitend: kein Wind-x-Pfeil im Bild',
       !R.erzeugeSzene(eY.modell, eY).vektoren.some((v) => v.lastart === 'windX'));
  wahr('Eigengewicht läuft nicht unter Leiterzug',
       pfeile.some((v) => v.lastart === 'staendig'));
  // Die Gleichlast wird nach Art getrennt aufgetragen. Dafür braucht es einen
  // Lastfall, in dem Eigengewicht UND Schnee anstehen.
  const eS = rechne(basis({ schneeAktiv: true, lastfall: 'schneep',
                            trasseRadius: 300, flSpannweite: 50, anbauteile: [bg] }));
  const flaechen = R.erzeugeSzene(eS.modell, eS).lastflaechen ?? [];
  wahr('Gleichlast getrennt nach ständig und Schnee',
       flaechen.some((f) => f.lastart === 'staendig') &&
       flaechen.some((f) => f.lastart === 'schnee'),
       flaechen.map((f) => f.lastart).join(' · '));
  wahr('Wind auf das Joch hängt an Wind y',
       flaechen.some((f) => f.lastart === 'windY'));

  // Negativer Windbeiwert dreht die Laufmeterlast um
  const eMinus = rechne(basis({ lastfall: 'windYm', lastHerkunft: 'manuell',
                                gkManuell: 1, wkManuell: 1, skManuell: 0 }));
  const szM = R.erzeugeSzene(eMinus.modell, eMinus);
  const wind = szM.vektoren.find((v) => v.lastart === 'windY');
  wahr('Wind y −: der Pfeil zeigt in die andere Richtung', wind.v[1] < 0,
       `w_d = ${eMinus.modell.wd.toFixed(2)} kN/m`);

  // --- Reiter --------------------------------------------------------------
  wahr('Die Stückliste ist kein eigener Auswertungsreiter mehr',
       !U.AUSWERTUNG_TABS.some((t) => t.id === 'stueckliste'),
       U.AUSWERTUNG_TABS.map((t) => t.titel).join(' · '));
  wahr('Sie steht im Reiter Profile',
       U.EINGABE_TABS.find((t) => t.id === 'profil').gruppen.includes('stueck'));
  wahr('Jeder Reiter hat ein Symbol für die Schiene',
       [...U.EINGABE_TABS, ...U.AUSWERTUNG_TABS].every((t) => t.icon));

  // --- Vorlagen ganzer Tragwerke -------------------------------------------
  const w = basis({ typ: 'J130', L: 24, xNachweis: 5, trasseRadius: 300 });
  const v = ST.vorlageAusWerten(w);
  wahr('Vorlage bringt Typ, Profile und Trasse mit',
       v.typ === 'J130' && v.profOG === w.profOG && v.trasseRadius === 300);
  wahr('Die Jochlänge gehört NICHT in die Vorlage', v.L === undefined);
  wahr('Die Nachweisstelle ebenso wenig', v.xNachweis === undefined);
  wahr('Anbauteile und Lastfälle kommen mit',
       Array.isArray(v.anbauteile) && v.lastfallAnpassung !== undefined);
  wahr('Die Vorlage ist eine Kopie, kein Verweis',
       v.anbauteile !== w.anbauteile);
}


// ===========================================================================
titel('27  Lasteinleitung: Verteilung auf die Nachbarbleche');

{
  const { stationsAnteil } = await import(J('core.anbauteile.js'));
  const st = [0, 1, 2, 3];

  pruef('Genau auf der Station: ganzer Anteil', stationsAnteil(1, 1, st), 1, 1e-12, '–');
  pruef('Genau auf der Station: Nachbar bekommt nichts',
        stationsAnteil(1, 2, st), 0, 1e-12, '–');
  pruef('Feldmitte: hälftig links', stationsAnteil(1.5, 1, st), 0.5, 1e-12, '–');
  pruef('Feldmitte: hälftig rechts', stationsAnteil(1.5, 2, st), 0.5, 1e-12, '–');
  pruef('Ein Viertel vom linken Knoten', stationsAnteil(1.25, 1, st), 0.75, 1e-12, '–');
  pruef('Summe der Anteile ist immer 1',
        st.reduce((a, x) => a + stationsAnteil(1.7, x, st), 0), 1, 1e-12, '–');
  pruef('Ausserhalb links fällt alles auf die Randstation',
        stationsAnteil(-5, 0, st), 1, 1e-12, '–');
  pruef('Ausserhalb rechts ebenso', stationsAnteil(9, 3, st), 1, 1e-12, '–');

  // Der eigentliche Zweck: η hängt STETIG vom Anschlussraster ab. Vorher fiel
  // es am Feldrand um über 25 %, weil die Einleitung ins Nachbarfeld kippte.
  const mitRaster = (r) => rechne(basis({
    lastHerkunft: 'manuell', gkManuell: 0.6, wkManuell: 0.5, skManuell: 0,
    anbauteile: [{ ...teil({ name: 'HS', x: 10, z: -1.5, befestigung: 'durchgehend' }),
                   raster: r,
                   lasten: [block({ einwirkung: 'G', z: -1.5, Fz: 5 }),
                            block({ einwirkung: 'WindY', z: -1.5, Fy: 4 })] }],
    // Das volle Kraeftepaar: abgemindert massgebt es hier nicht mehr, und
    // die Stetigkeit liesse sich nicht mehr ablesen.
    oertlichFaktor: 1,
  })).max.etaGesamt;

  const a1 = rechne(basis({})).modell.a1eff;
  const stufen = [0.60, 0.68, 0.70, 0.72, 0.75, 0.80];
  const werte = stufen.map(mitRaster);
  const spruenge = werte.slice(1).map((v, i) => Math.abs(v - werte[i]) / werte[i]);
  wahr('Kein Sprung mehr am Feldrand', Math.max(...spruenge) < 0.06,
       `a₁ = ${a1.toFixed(3)} m · η ${werte.map((v) => v.toFixed(3)).join(' → ')}` +
       ` · grösster Schritt ${(Math.max(...spruenge) * 100).toFixed(1)} %`);
  wahr('Breiterer Anschluss bleibt günstiger', werte[werte.length - 1] < werte[0],
       `${werte[0].toFixed(3)} → ${werte[werte.length - 1].toFixed(3)}`);
}


// ===========================================================================
titel('28  Vorlagen der Leiter und Übersicht');

{
  const A7 = await import(J('data.anbauteile.js'));
  const FL2 = await import(J('data.fl.js'));

  // Die drei Leitertypen stehen als eigene Kachel zur Verfügung
  [['leiter-nfl', 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107', 14.9],
   ['leiter-rfl', 'drahtwerk-r-fl-ts-stcu-92-fd-cu-107', 22],
   ['leiter-rl', 'drahtwerk-cu-95', 3.9]].forEach(([id, bauteil, Z]) => {
    const v = A7.getVorlage(id);
    wahr(`Vorlage ${id} vorhanden und einseitig befestigt`,
         v.befestigung === 'unten' && v.module.length === 1, v.name);
    pruef(`${id}: Leiterzugkraft aus der Tabelle`,
          FL2.leiterzug(v.module[0].bauteil), Z, 1e-12, 'kN');
    wahr(`${id}: verweist auf das richtige Drahtwerk`,
         v.module[0].bauteil === bauteil);
  });

  // Die Umlenkkraft kommt bei allen dreien durch
  const t = A7.neuesAnbauteil('leiter-rl', 10);
  const fl = A7.expandiereAnbauteile([t], { ek: 'EK2', R: 300, spannweite: 50 });
  pruef('RL im Bogen: U = Z · L/R', fl[0].kraefte.G.Fx, (3.9 * 50) / 300, 1e-9, 'kN');
}

// ===========================================================================
titel('29  Handbuch');

{
  const HB = await import(J('doku.handbuch.js'));

  /*
   * Zwoelf seit dem Kapitel zur AxisVM-Ausleitung (Weisung vom 28. August:
   * "da sollte ein kapitel aufgenommen werden der den export zu axisvm
   * beschreibt"), FUENFZEHN seit dem 11. September.
   *
   * Weisung: "diese und alle anderen berechnungen fuer das abfangjoch masten
   * sind im handbuch zu hinterlegen fuer die nachvollziehbarkeit, aehnlich
   * wie beim tragjoch." Die Abschnitte 1 bis 12 gelten dem Tragjoch; das
   * Abfangjoch, sein Mast und der Zuganker haben seither eigene.
   *
   * Die Zahl steht hier, damit ein verlorenes Kapitel auffaellt.
   */
  wahr('Handbuch hat alle sechzehn Abschnitte', HB.HANDBUCH.length === 16,
       `${HB.HANDBUCH.length} Abschnitte`);
  /*
   * UND DIE DREI NEUEN STEHEN NAMENTLICH DA. Ein blosser Zaehler faellt
   * nicht auf, wenn ein Kapitel gegen ein anderes getauscht wird.
   */
  ['abfangjoch', 'mast-abfang', 'anker'].forEach((id) => {
    wahr(`Handbuch fuehrt den Abschnitt «${id}»`,
         HB.HANDBUCH.some((s) => s.id === id));
  });
  /*
   * DIE HERLEITUNGEN, DIE DORT STEHEN MUESSEN. Sie sind der Grund, warum es
   * die Kapitel gibt - ein Abschnitt ohne sie waere eine Ueberschrift.
   */
  const hbText = HB.HANDBUCH.map((s) => s.html).join(' ');
  [['Kraeftepaar N = M/e', /N = M_Rahmen \/ e/],
   ['Woelbkrafttorsion T/e', /± T \/ e/],
   ['Variante 3 des Ankers', /δ₁₀ \+ X · δ₁₁ = 0/],
   ['Knicken: N_cr und chi', /N_cr = π²·E·I \/ L²/],
   ['die Konsole mit 0.15 m', /Starrelement von[\s\S]{0,12}0\.15 m/]]
    .forEach(([was, r]) => wahr(`Das Handbuch fuehrt ${was}`, r.test(hbText)));
  wahr('Jeder Abschnitt hat Kennung, Titel und Rumpf',
       HB.HANDBUCH.every((s) => s.id && s.titel && s.html?.length > 200));
  wahr('Kennungen sind eindeutig',
       new Set(HB.HANDBUCH.map((s) => s.id)).size === HB.HANDBUCH.length);

  const html = HB.handbuchHtml();
  wahr('Jeder Abschnitt steht im ausgegebenen Blatt',
       HB.HANDBUCH.every((s) => html.includes(`id="hb-${s.id}"`)));
  wahr('Jeder Abschnitt hat seinen Eintrag im Verzeichnis',
       HB.HANDBUCH.every((s) => html.includes(`data-zu="${s.id}"`)));

  // Der Abschnitt Modellgrenzen ist der Grund, warum es das Handbuch gibt.
  // Er muss die Ausschlüsse benennen, sonst ist er wertlos.
  const g = HB.HANDBUCH.find((s) => s.id === 'grenzen').html;
  ['Knicken', 'Beulen', 'Verformung', 'Schweissnähte', 'Ermüdung',
   'Wölbkrafttorsion', 'Querschnittsklasse 4'].forEach((wort) => {
    wahr(`Modellgrenzen nennen: ${wort}`, g.includes(wort));
  });

  // Skizzen: sie sollen die Formeln zeigen, nicht bloss dekorieren
  /*
   * SIEBZEHN seit dem 11. September (Weisung: «ergaenze zudem die diagramme
   * im handbuch wo sinnvoll») - fuenf in den Kapiteln 13 bis 15: der
   * Hebelarm mit seinen drei ineinanderliegenden Massen, die
   * Woelbkrafttorsion, der Mast mit Ausladung, das Zweifeldsystem des
   * Ankers und sein Spreizmass.
   */
  wahr('Handbuch enthält siebzehn Skizzen',
       (html.match(/<figure class="skizze hb-skizze">/g) ?? []).length === 17);
  /* =========================================================================
   * DER DREHSINN DES EINSEITIGEN ANSCHLUSSES
   * =========================================================================
   *
   * Weisung vom 11. September: «hier sollten die verikalen richtungen
   * vertauscht werden. sonst stimmt es nicht mit dem drehsinn infolge der
   * karft f.»
   *
   * Die Skizze zeigte F_y nach rechts, unter der Gurtebene angreifend - und
   * dazu ein Kraeftepaar, das in den GEGENdrehsinn zeigte. Das Gleichgewicht
   * um die Jochachse verlangt
   *
   *     M_x = −z·F_y = +a·F   und   M_x = Σ(y·F_z)
   *
   * also RECHTS nach oben und LINKS nach unten. Gepruef wird am gezeichneten
   * SVG: der linke Pfeil laeuft abwaerts (y waechst), der rechte aufwaerts.
   */
  {
    // Der Abschnitt heisst `einleitung` - Lasteinleitung der Anbauteile.
    const s5 = HB.HANDBUCH.find((x) => x.id === 'einleitung')?.html ?? '';
    const paar = [...s5.matchAll(
      /<line class="k" x1="(296|392)" y1="(\d+)" x2="\d+" y2="(\d+)"/g)];
    wahr('Das Kraeftepaar des einseitigen Anschlusses steht da',
         paar.length === 2, `${paar.length} Pfeile`);
    if (paar.length === 2) {
      const links = paar.find((m2) => m2[1] === '296');
      const rechts = paar.find((m2) => m2[1] === '392');
      wahr('… links zeigt nach unten', +links[3] > +links[2],
           `y ${links[2]} → ${links[3]}`);
      wahr('… rechts zeigt nach oben', +rechts[3] < +rechts[2],
           `y ${rechts[2]} → ${rechts[3]}`);
    }
  }
  wahr('Keine Skizze hat unberechnete Koordinaten',
       !/NaN|undefined/.test(html));
  ['achsen', 'einwirkungen', 'system', 'querschnitt', 'vierendeel',
   'einleitung', 'raster', 'axisvm'].forEach((id) => {
    const s = HB.HANDBUCH.find((x) => x.id === id).html;
    wahr(`Abschnitt ${id} hat eine Skizze`, s.includes('hb-skizze'));
  });

  // Die tragenden Formeln stehen im Text und stimmen mit dem Kern überein
  const alles = HB.HANDBUCH.map((s) => s.html).join('');
  [['Umlenkkraft', 'U = 2 · Z · sin(α/2) = Z · L / R'],
   ['Hebelarm zur Jochachse', 'e_v = −( z_A + z )'],
   ['Bredt-Schubfluss', 'q_T = T / (2 · A_m)'],
   ['Gurtmoment am Anschnitt', 'M_Anschnitt = M_Knoten · ( a₁ − b_Bl ) / a₁'],
   ['Blech am Anschnitt', 'M_R = M_K · L_c / h₀'],
   ['Drehfeder aus dem Mast', 'c_φ = E · I_Mast / H']].forEach(([was, formel]) => {
    wahr(`Handbuch führt die Formel: ${was}`, alles.includes(formel));
  });
}

// ===========================================================================
titel('18b  Örtliche Feldweiten statt des Mittels');

{
  const { nachbarfeldweiten } = await import(J('core.querschnitt.js'));

  // Das J70 über 10 m teilt ungleich: aussen 0.75 m, innen 0.66-0.67 m.
  const e = { ...basis({ typ: 'J70', L: 10, lastfall: 'windYp' }), anbauteile: [] };
  const r = rechne(e);
  const xs = r.knoten.map((k) => k.x);
  const weiten = xs.slice(1).map((x, i) => +(x - xs[i]).toFixed(3));
  wahr('Mass-Tabelle teilt ungleich',
       Math.max(...weiten) - Math.min(...weiten) > 0.05,
       `${Math.min(...weiten)} bis ${Math.max(...weiten)} m`);

  const k1 = r.knoten[1];                       // beidseits 0.75
  const kM = r.knoten.find((k) => Math.abs(k.x - 3.00) < 1e-6);  // 0.75 / 0.67
  pruef('Blech: Summe der beiden Nachbarfelder', k1.aBlech, 1.50, 1e-9, 'm');
  pruef('Blech am Übergang: 0.75 + 0.67', kM.aBlech, weiten[3] + weiten[4], 1e-9, 'm');
  pruef('Gurt: das breitere der beiden Felder', kM.aGurt, 0.75, 1e-9, 'm');
  pruef('Randstation hat nur EIN Nachbarfeld', r.knoten[0].aBlech, 0.75, 1e-9, 'm');

  // Gegenprobe: bei gleichen Feldern muss die frühere Form herauskommen
  const gleich = nachbarfeldweiten({ stationsX: [0, 0.7, 1.4, 2.1] }, 0.7);
  pruef('Gleiche Felder: Summe ist 2·a₁', gleich.summe, 1.4, 1e-9, 'm');
  pruef('Gleiche Felder: Gurt sieht a₁', gleich.max, 0.7, 1e-9, 'm');
  wahr('Ohne Stationsliste bleibt es beim Mittel',
       nachbarfeldweiten({ a1eff: 0.7 }, 5) === null);

  // Die Korrektur wirkt: an den breiten Feldern steigt das Blechmoment.
  const beste = r.knoten.reduce((a, b) => (b.etaB > a.etaB ? b : a));
  wahr('Massgebendes Blech liegt an einem breiten Feld',
       Math.abs(beste.aGurt - 0.75) < 1e-9,
       `x = ${beste.x.toFixed(2)} m, η = ${beste.etaB.toFixed(4)}`);

  // Der Zusammenhang selbst, nicht eine gemerkte Zahl: das Knotenmoment folgt
  // der Summe der Nachbarfelder.
  const bl = beste.ebenen.find((e) => e.eta === beste.etaB);
  pruef('M_Knoten = V_Ebene · Σa / 4',
        bl.M_Knoten, (bl.V_Ebene * beste.aBlech) / 4, 1e-12, 'kNm');
  // η ist dem Moment proportional; mit dem Mittel gerechnet wäre es kleiner.
  const mittel = (2 * r.modell.a1eff) / beste.aBlech;
  pruef('Das Mittel läge an dieser Station 6 % zu tief',
        beste.etaB * mittel, beste.etaB / 1.0588, 1e-3, '–');
}

// ===========================================================================
titel('18e  Grenzlast der Gurtverbindung');

{
  const { begrenzeFeder } = await import(J('core.auflager.js'));

  const e = (zus) => basis({ typ: 'J90', L: 15.5, endbedingung: 'mast',
    mastProfil: 'HEB 260', mastH: 7.5, lastHerkunft: 'manuell',
    gkManuell: 0.6, wkManuell: 0, skManuell: 0, schneeAktiv: false,
    beiwerteFest: { G: 1, WindX: 0, WindY: 0, Schnee: 0 }, ...zus });

  const ohne = rechne(e({ schraubenGrenze: false })).modell;
  // Startwert ist AUS (Weisung): die geometrische Feder gilt, die
  // Schraubengrenze ist ein eigener Nachweis. Wer die Begrenzung prueft,
  // schaltet sie ausdruecklich ein.
  const mit = rechne(e({ schraubenGrenze: true, schraubenFgrenz: 24 })).modell;

  /*
   * JE GURT, NICHT JE GURTEBENE (Weisung, 27. August), und die Begrenzung
   * steht im STARTWERT AUS.
   *
   * Zuvor galt F = M/h, also die ganze Ebenenkraft an einem Anschluss - das
   * Doppelte des Richtigen. Und der Startwert stand auf EIN, womit die
   * Anwendung zweierlei zugleich sagte: der Rechenkern setzte die Feder
   * herab, DAMIT die Grenze eingehalten ist, und Pruefung A1 wies zugleich
   * die Kraft aus der ungebremsten Feder als ueberschritten aus.
   */
  {
    const f = FELDER.find((x) => x.key === 'schraubenGrenze');
    wahr('Die Begrenzung ist im Startwert aus', f.standard === false,
         String(f.standard));
    wahr('Und standardwerte() traegt sie so',
         standardwerte().schraubenGrenze === false);
    // Die Grenzlast bleibt sichtbar, auch ohne Begrenzung - sie wird ja
    // weiterhin nachgewiesen (A1).
    const fg = FELDER.find((x) => x.key === 'schraubenFgrenz');
    wahr('Die Grenzlast bleibt eingebbar, auch ohne Begrenzung',
         fg.sichtbar({ endbedingung: 'mast', schraubenGrenze: false }) === true);
    // Beide Wege muessen dieselbe Kraft meinen.
    const mG = rechne(e({ schraubenGrenze: true, schraubenFgrenz: 8 })).modell;
    pruef('Begrenzung und Nachweis rechnen dieselbe Kraft',
          mG.federn.grenze.FA, Math.abs(mG.federn.grenze.MA) / (2 * mG.h),
          1e-9, 'kN');
  }

  wahr('Ohne Begrenzung bleibt die geometrische Feder stehen',
       ohne.federn.grenze === null
       && Math.abs(ohne.federn.cA - ohne.federn.roh.cA) < 1e-9);
  // Unter blossem Eigengewicht bleibt die Gurtkraft weit unter 24 kN - die
  // Grenze greift dort nicht ein, und das soll sie auch nicht.
  wahr('24 kN greifen unter Eigengewicht allein nicht ein',
       !mit.federn.grenze.begrenzt && mit.federn.grenze.FA < 24,
       `F = ${mit.federn.grenze.FA.toFixed(1)} kN`);

  // Eine Grenze unterhalb der vorhandenen Kraft setzt die Feder herab
  const eng = rechne(e({ schraubenGrenze: true, schraubenFgrenz: 8 })).modell;
  wahr('Eine Grenze von 8 kN setzt die Feder herab',
       eng.federn.grenze.begrenzt && eng.federn.cA < eng.federn.roh.cA,
       `${eng.federn.roh.cA.toFixed(0)} -> ${eng.federn.cA.toFixed(0)} kNm/rad`);
  pruef('Die Gurtkraft trifft dann die Grenzlast', eng.federn.grenze.FA, 8, 1e-3, 'kN');
  // JE GURT: die Ebenenkraft ist das Doppelte, also M = F_Grenz · 2h.
  pruef('Stützmoment = F_Grenz · 2h', Math.abs(eng.MA), 8 * 2 * eng.h, 1e-3, 'kNm');
  wahr('Wenige Durchgänge genügen', eng.federn.grenze.durchgaenge <= 30,
       `${eng.federn.grenze.durchgaenge} Durchgänge`);

  // Eine hohe Grenzlast greift nicht ein
  const hoch = rechne(e({ schraubenGrenze: true, schraubenFgrenz: 1000 })).modell;
  pruef('Hohe Grenzlast lässt die Feder unberührt', hoch.federn.cA,
        hoch.federn.roh.cA, 1e-9, 'kNm/rad');
  wahr('… und meldet keine Begrenzung', !hoch.federn.grenze.begrenzt);

  // Kleinere Grenzlast -> weichere Feder -> grösseres Feldmoment
  const klein = rechne(e({ schraubenGrenze: true, schraubenFgrenz: 6 }));
  const gross = rechne(e({ schraubenGrenze: true, schraubenFgrenz: 10 }));
  const feld = (r) => Math.max(...r.knoten.map((k) => k.My));
  wahr('Kleinere Grenzlast gibt weichere Feder und mehr Feldmoment',
       klein.modell.federn.cA < gross.modell.federn.cA
       && feld(klein) > feld(gross),
       `c ${klein.modell.federn.cA.toFixed(0)} < ${gross.modell.federn.cA.toFixed(0)}, `
       + `Feld ${feld(klein).toFixed(2)} > ${feld(gross).toFixed(2)} kNm`);

  // Volle Einspannung bleibt die gewählte Idealisierung
  const voll = rechne(e({ endbedingung: 'voll', schraubenGrenze: true,
                         schraubenFgrenz: 24 })).modell;
  wahr('Volle Einspannung wird nicht begrenzt', voll.federn.grenze === null);

  // Die Funktion selbst, ohne Modelldrumherum
  const b = begrenzeFeder({ L: 16, qd: 1, P: [], M: [], EI: 65000,
                            cA: 1e6, cB: 1e6, h: 0.45, Fgrenz: 20 });
  // Die Skalierung ist eine Naeherung von unten; ein Rest von gut einem
  // Zehntausendstel bleibt und ist die Sache selbst, kein Fehler.
  pruef('Direkt gerufen: F trifft die Grenze', b.FA, 20, 2e-4, 'kN');
  wahr('Ohne Grenzlast passiert nichts',
       begrenzeFeder({ L: 16, qd: 1, P: [], M: [], EI: 65000, cA: 500,
                       cB: 500, h: 0.45, Fgrenz: 0 }).begrenzt === false);
}

// ===========================================================================
titel('18d  Altbauweise: Gelenk am Auflager');

{
  const { hinweise } = await import(J('core.checks.js'));

  // Beim Wechsel auf einen Alttyp wird die Endbedingung mitgeführt
  const nachAlt = typUebernehmen({ ...standardwerte(), endbedingung: 'mast' },
                                 T.getTragjoch('J90-alt'));
  const nachNeu = typUebernehmen({ ...standardwerte(), endbedingung: 'mast' },
                                 T.getTragjoch('J90'));
  wahr('Alttyp setzt die Endbedingung auf gelenkig',
       nachAlt.endbedingung === 'gelenkig');
  wahr('Neuer Typ lässt die Endbedingung stehen',
       nachNeu.endbedingung === 'mast');

  // Wer sie danach von Hand ändert, wird gewarnt
  const warnung = (typ, end) => {
    const e = { ...basis({ typ, L: 16, endbedingung: end,
                           mastProfil: 'HEB 260', mastH: 7.5 }) };
    return hinweise(rechne(e).modell).some((z) => z.includes('GELENK'));
  };
  wahr('Alttyp eingespannt gerechnet gibt einen Hinweis',
       warnung('J90-alt', 'mast'));
  wahr('Alttyp gelenkig gibt keinen Hinweis', !warnung('J90-alt', 'gelenkig'));
  wahr('Neuer Typ eingespannt gibt keinen solchen Hinweis',
       !warnung('J90', 'mast'));
}

// ===========================================================================
titel('18c  Mastanschluss: Kragarm oder durchlaufend');

{
  const { mastSteifigkeit, MASTANSCHLUESSE, drehfedern, E_STAHL } =
    await import(J('core.auflager.js'));
  const { getMastprofil } = await import(J('data.masten.js'));

  const mast = { mastProfil: 'HEB 260', mastH: 7.5, mastSteg: 'jochachse' };
  // Ohne dritten Parameter gilt der UNVERSCHIEBLICHE Fall - das Joch hält die
  // beiden Mastköpfe zusammen, und das ist der Regelfall (Vertikallasten).
  const krag = mastSteifigkeit({ ...mast, mastAnschluss: 'kragarm' });
  const durch = mastSteifigkeit({ ...mast, mastAnschluss: 'durchlaufend' });
  const kragV = mastSteifigkeit({ ...mast, mastAnschluss: 'kragarm' }, 'A', true);
  const durchV = mastSteifigkeit({ ...mast, mastAnschluss: 'durchlaufend' }, 'A', true);

  const p = getMastprofil('HEB 260');
  pruef('Verschieblich, Kragarm: c_φ = E·I/H',
        kragV.cPhi, (E_STAHL * p.Iy * 1e-8) / 7.5, 1e-9, 'kNm/rad');
  pruef('Verschieblich, durchlaufend: Faktor 1.45',
        durchV.cPhi, 1.45 * kragV.cPhi, 1e-12, 'kNm/rad');
  pruef('Der Kragarmwert bleibt in beiden Fällen ausgewiesen',
        durch.cKragarm, kragV.cPhi, 1e-12, 'kNm/rad');
  wahr('Ohne Angabe gilt der durchlaufende Mast',
       mastSteifigkeit(mast).cVerschieblich === durchV.cPhi);
  wahr('Beide Anschlussarten sind wählbar',
       MASTANSCHLUESSE.length === 2
       && MASTANSCHLUESSE.every((a) => a.key && a.label && a.faktor));

  // Der Anschlussfaktor wirkt nur noch im VERSCHIEBLICHEN Fall - dort gilt
  // die alte Kalibrierung von 6074 kNm/rad (J90, 15.5 m, HEB 260) weiter.
  wahr('Verschieblich: durchlaufend trifft die gemessene Steifigkeit',
       Math.abs(durchV.cPhi - 6074) / 6074 < 0.03,
       `${durchV.cPhi.toFixed(0)} gegen gemessene 6074 kNm/rad`);
  // Unverschieblich regiert die Rahmenwirkung, nicht die Bauart des
  // Anschlusses: das Joch hält die beiden Mastköpfe zusammen.
  pruef('Unverschieblich ist 4.00 · E·I/H', durch.cPhi,
        MAST_UNVERSCHIEBLICH * durch.cKragarm, 1e-9, 'kNm/rad');
  wahr('Unverschieblich hängt nicht mehr am Anschluss',
       Math.abs(durch.cPhi - krag.cPhi) < 1e-9);
  wahr('Unverschieblich ist deutlich steifer als der Kragmast',
       durch.cPhi > 3 * krag.cKragarm);

  const f = (an) => drehfedern({ endbedingung: 'mast', ...mast, mastAnschluss: an });
  pruef('Beide Jochenden bekommen dieselbe Feder',
        f('durchlaufend').cA, f('durchlaufend').cB, 1e-12, 'kNm/rad');
  const fv = (an) => drehfedern({ endbedingung: 'mast', ...mast,
                                  mastAnschluss: an }, true);
  wahr('Die Art nennt den Anschluss, wenn er wirkt',
       fv('durchlaufend').art.includes('durchlaufend')
       && fv('kragarm').art.includes('Kragarm'));
  wahr('Sonst nennt sie den Rahmen',
       f('durchlaufend').art.includes('unverschieblich'));

  // Wirkung auf die Momentenaufteilung des Beispieljochs
  const lauf = (an) => {
    const e = { ...basis({ typ: 'J90', L: 15.5, endbedingung: 'mast',
      mastProfil: 'HEB 260', mastH: 7.5, mastAnschluss: an,
      lastHerkunft: 'manuell', gkManuell: 0.4735, wkManuell: 0, skManuell: 0,
      lastfall: null, beiwerteFest: { G: 1, WindX: 0, WindY: 0, Schnee: 0 } }) };
    const r = rechne(e);
    const My = r.knoten.map((k) => k.My);
    return { stuetz: Math.abs(Math.min(...My)), feld: Math.max(...My) };
  };
  const k = lauf('kragarm'), d = lauf('durchlaufend');
  // Unter Vertikallast verschiebt sich der Rahmen nicht - dann regiert die
  // Rahmenwirkung, und die Bauart des Anschlusses fällt heraus.
  wahr('Vertikallast: der Anschluss ändert nichts mehr',
       Math.abs(d.feld - k.feld) < 1e-9 && Math.abs(d.stuetz - k.stuetz) < 1e-9,
       `Feld ${k.feld.toFixed(2)} / ${d.feld.toFixed(2)} kNm`);
  // Massstab ist der Rahmen mit BEIDEN Masten (PyNite, Füsse eingespannt,
  // Joch an beiden Ebenen angeschlossen): Feldmoment 8.22 kNm. Das frühere
  // Modell konnte sich verschieben und nannte 10.27 kNm.
  wahr('Trifft das Feldmoment des Rahmens mit beiden Masten (8.22 kNm)',
       Math.abs(d.feld - 8.22) < 0.35, `${d.feld.toFixed(2)} kNm`);
}

// ===========================================================================
titel('18j  Farblegende gegen die Plots');

{
  const R = await import(J('render.3d.js'));
  const e = basis({ lastfall: 'windYp',
    anbauteile: [{ ...teil({ name: 'HS', x: 8 }), raster: 0.4,
                   befestigung: 'durchgehend',
                   lasten: [block({ einwirkung: 'G', z: -1.35, Fz: 3 }),
                            block({ einwirkung: 'WindY', z: -1.35, Fy: 4 })] }] });
  const erg = rechne(e);
  const szene = R.erzeugeSzene(erg.modell, erg);

  // Jeder Plot hat eine Skala, und ihr Endwert ist der Höchstwert im Modell
  R.PLOTS.forEach((p) => {
    const legende = p.fest ?? szene.bereiche[p.feld];
    let ist = 0;
    szene.flaechen.forEach((f) => {
      const v = f.werte?.[p.feld];
      if (Number.isFinite(v)) ist = Math.max(ist, Math.abs(v));
    });
    if (p.fest) {
      // η hat bewusst eine FESTE Skala: 1.25 ist die Marke, nicht das
      // Maximum. Werte darüber laufen in die oberste Farbe.
      wahr(`${p.kurz}: feste Skala ${p.fest}, unabhängig vom Modell`,
           legende === p.fest, `grösster Wert im Modell ${ist.toFixed(2)}`);
      wahr(`${p.kurz}: die Fussnote sagt, dass die Skala fest ist`,
           /[Ff]este Skala/.test(p.fussnote ?? ''));
    } else {
      pruef(`${p.kurz}: Skalenende ist der Höchstwert`, legende, ist, 1e-9, p.einheit);
    }
  });

  wahr('Jeder Plot hat Beschriftung und Einheit',
       R.PLOTS.every((p) => p.label && p.einheit && p.kurz));
  wahr('Jeder Plot sagt, was er zeigt',
       R.PLOTS.every((p) => p.fussnote), 'Fussnote je Plot');

  // Was die Fussnoten behaupten, muss auch eingefärbt werden
  const gurt = szene.flaechen.find((f) => f.gruppe === 'profil' && f.werte);
  const blech = szene.flaechen.find((f) => f.gruppe === 'blech' && f.werte);
  wahr('Gurt und Blech tragen Werte', Boolean(gurt && blech));
  wahr('V bleibt am Gurt leer – wie die Fussnote sagt', gurt.werte.V === null);
  wahr('V ist am Blech vorhanden', Number.isFinite(blech.werte.V));

  // Das Gurtmoment ist das GRÖSSERE aus M_y und M_z: nur M_y zu zeigen
  // färbte den Gurt zu günstig ein, sobald der Wind regiert.
  const k = erg.knoten.find((x) => Math.abs(x.Mz_lokal) > Math.abs(x.My_lokal));
  wahr('Es gibt Stationen, an denen M_z das grössere ist', Boolean(k),
       k ? `M_y ${Math.abs(k.My_lokal).toFixed(3)} < M_z ${Math.abs(k.Mz_lokal).toFixed(3)}` : '');
  if (k) {
    const f = szene.flaechen.find((x) => x.gruppe === 'profil' && x.station === k.i && x.werte);
    pruef('Der Plot zeigt dort das grössere Moment', f.werte.M,
          Math.max(Math.abs(k.My_lokal), Math.abs(k.Mz_lokal)), 1e-9, 'kNm');
  }

  // Bauteil-Legende: je Profil, Blechposition und Anbauteil ein Eintrag
  // Werte über dem Skalenende dürfen die Einfärbung nicht sprengen. Die
  // Ansicht selbst braucht ein Canvas; geprüft wird deshalb die Farbfunktion
  // mit dem Aufbau, den _grundfarbe verwendet.
  const A2 = Object.create(R.Modellansicht.prototype);
  A2.szene = szene; A2.modus = 'eta';
  const farbe = (v) => A2._grundfarbe({ werte: { eta: v } }, { xdim: '#888' });
  wahr('Werte über der festen Skala geben eine gültige Farbe',
       /^(#|rgb)/.test(farbe(3.4)) && /^(#|rgb)/.test(farbe(1.25)),
       `η 3.4 -> ${farbe(3.4)}`);
  wahr('Fehlender Wert bleibt neutral',
       A2._grundfarbe({ werte: { eta: null } }, { xdim: '#888' }) === '#888');

  wahr('Bauteillegende hat Einträge', szene.legende.length > 0,
       `${szene.legende.length} Einträge`);
  wahr('Jeder Eintrag hat Bezeichnung und Farbe',
       szene.legende.every((b) => b.label && b.farbe));
  wahr('Bezeichnungen sind eindeutig',
       new Set(szene.legende.map((b) => b.label)).size === szene.legende.length);
}

// ===========================================================================
titel('18i  Vorlage: Hängestütze mit Flächenlast');

{
  const at = A.neuesAnbauteil('hs-flaeche', 8);
  wahr('Vorlage vorhanden', Boolean(at) && at.module.length === 2, at.name);
  wahr('Durchgehend befestigt', at.befestigung === 'durchgehend');

  const flach = A.expandiereAnbauteile([at], { ek: 'EK2' });
  pruef('Zwei Module aufgelöst', flach.length, 2, 1e-12, 'Stk');

  const hs = flach.find((f) => f.bauteil.includes('haengestuetze'));
  const fl = flach.find((f) => f.bauteil === 'frei-flaeche');
  wahr('Beide Module erkannt', Boolean(hs && fl));

  pruef('Hängestütze hängt 1.35 m unter der Anschlussebene', hs.z, -1.35, 1e-12, 'm');
  pruef('Fläche hängt tiefer', fl.z, -2.10, 1e-12, 'm');

  // Die Windlast der freien Fläche folgt der Formel w = A · q_ref(EK) · c
  const { staudruck } = await import(J('data.fl.js'));
  const q = staudruck('EK2');
  pruef('Wind quer aus der Fläche', fl.kraefte.WindX.Fx, 0.50 * q * 1.4, 1e-9, 'kN');
  pruef('Wind längs aus der Fläche', fl.kraefte.WindY.Fy, 0.15 * q * 1.4, 1e-9, 'kN');
  pruef('Eigengewicht wie eingegeben', fl.kraefte.G.Fz, 0.30, 1e-12, 'kN');

  // Grössere Einwirkungsklasse gibt mehr Wind - sonst hinge die Fläche nicht dran
  const stark = A.expandiereAnbauteile([A.neuesAnbauteil('hs-flaeche', 8)], { ek: 'EK3' })
    .find((f) => f.bauteil === 'frei-flaeche');
  wahr('Höhere Einwirkungsklasse gibt mehr Wind',
       stark.kraefte.WindX.Fx > fl.kraefte.WindX.Fx,
       `${fl.kraefte.WindX.Fx.toFixed(3)} -> ${stark.kraefte.WindX.Fx.toFixed(3)} kN`);

  // Sie trägt sich durch bis in die Nachweise
  const mitVorlage = rechne(basis({ lastfall: 'windXp',
    anbauteile: [A.neuesAnbauteil('hs-flaeche', 10)] }));
  const ohne = rechne(basis({ lastfall: 'windXp', anbauteile: [] }));
  wahr('Die Vorlage bewegt die Nachweise',
       mitVorlage.max.etaGesamt > ohne.max.etaGesamt,
       `η ${ohne.max.etaGesamt.toFixed(3)} -> ${mitVorlage.max.etaGesamt.toFixed(3)}`);
}

// ===========================================================================
titel('18g  Handbuch als eigenständige Datei');

{
  const HB = await import(J('doku.handbuch.js'));
  const datei = HB.handbuchDatei({ fussnote: 'Prüfstand' });

  wahr('Vollständiges HTML-Dokument',
       datei.startsWith('<!doctype html>') && datei.trimEnd().endsWith('</html>'));
  wahr('Zeichensatz und Titel gesetzt',
       datei.includes('<meta charset="utf-8">') && datei.includes('<title>'));
  wahr('Alle Abschnitte enthalten',
       HB.HANDBUCH.every((a) => datei.includes(`id="hb-${a.id}"`)),
       `${HB.HANDBUCH.length} Abschnitte`);
  wahr('Verzeichnis als echte Sprungmarken',
       HB.HANDBUCH.every((a) => datei.includes(`href="#hb-${a.id}"`)));
  // Zwoelf seit dem Kapitel zur AxisVM-Ausleitung (28. August): der Anschluss
  // in Draufsicht und in Ansicht. Vorher zehn.
  pruef('Alle siebzehn Skizzen mitgenommen',
        (datei.match(/<figure class="skizze hb-skizze">/g) ?? []).length, 17, 1e-12, 'Stk');
  wahr('Keine unberechneten Werte', !/NaN|undefined|Infinity/.test(datei));
  wahr('Fussnote und Stand stehen drin',
       datei.includes('Prüfstand') && /Stand /.test(datei));
  wahr('Ohne Dokument bleibt das Stylesheet leer, der Text nicht',
       datei.includes('<style>') && datei.length > 20000,
       `${Math.round(datei.length / 1024)} kB`);

  // Ohne Farbtokens stünde dunkler Text auf dunklem Grund: eine eigenständige
  // Datei führt kein Skript aus, das sie zur Laufzeit setzt.
  const { FARBEN } = await import(J('design.js'));
  const hell = HB.handbuchDatei({ tokens: FARBEN.hell });
  wahr('Farbtokens stehen als CSS im Dokument', /:root \{ --/.test(hell));
  wahr('Vordergrund und Hintergrund sind gesetzt',
       /--grund:/.test(hell) || /--hintergrund:/.test(hell)
       || Object.keys(FARBEN.hell).some((k) => hell.includes(`--${k.toLowerCase()}`)));
  pruef('Alle Tokens des Themas übernommen',
        Object.keys(FARBEN.hell).filter((k) =>
          hell.includes('--' + k.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase()) + ':')).length,
        Object.keys(FARBEN.hell).length, 1e-12, 'Stk');
}

// ===========================================================================
titel('18h  Ablage: umbenennen und Projekte');

{
  // IndexedDB gibt es im Prüfstand nicht; geprüft wird die Logik der
  // Umbenennung an den Sätzen selbst, wie store.umbenennen sie bildet.
  const satz = { id: 'x1', name: 'Joch 12', projekt: 'Bahnhof', bemerkung: '',
                 werte: {}, erstellt: 'A', geaendert: 'A' };
  const um = (s, neu) => ({
    ...s,
    ...(neu.name !== undefined ? { name: neu.name.trim() || 'Ohne Namen' } : {}),
    ...(neu.projekt !== undefined ? { projekt: neu.projekt.trim() } : {}),
    geaendert: 'B',
  });
  const a = um(satz, { name: '  Joch 12a  ' });
  wahr('Name wird beschnitten', a.name === 'Joch 12a');
  wahr('Projekt bleibt unberührt, wenn nicht angegeben', a.projekt === 'Bahnhof');
  wahr('Die Eingabewerte bleiben stehen', a.werte === satz.werte);
  wahr('Leerer Name wird aufgefangen', um(satz, { name: '   ' }).name === 'Ohne Namen');
  wahr('Leeres Projekt heisst «ohne Projekt»',
       um(satz, { projekt: '  ' }).projekt === '');
  wahr('Der Erstellzeitpunkt bleibt', a.erstellt === 'A' && a.geaendert === 'B');

  // Gruppierung: mehrere Joche unter einem Projekt
  const { nachProjekt } = await import(J('store.js'));
  wahr('nachProjekt ist vorhanden', typeof nachProjekt === 'function');
  const gruppen = (liste) => {
    const m = new Map();
    liste.forEach((s) => {
      const k = s.projekt || 'Ohne Projekt';
      if (!m.has(k)) m.set(k, []);
      m.get(k).push(s);
    });
    return [...m.entries()].map(([projekt, eintraege]) => ({ projekt, eintraege }));
  };
  const g = gruppen([satz, { ...satz, id: 'x2', name: 'Joch 13' },
                     { ...satz, id: 'x3', projekt: '' }]);
  pruef('Zwei Gruppen', g.length, 2, 1e-12, 'Stk');
  pruef('Zwei Joche im Projekt', g[0].eintraege.length, 2, 1e-12, 'Stk');
  wahr('Ohne Projektnamen eigene Gruppe', g[1].projekt === 'Ohne Projekt');
}

// ===========================================================================
titel('18f  Datenpaket');

{
  // localStorage nachbilden, damit das Modul im Prüfstand läuft
  if (typeof globalThis.localStorage === 'undefined') {
    globalThis.localStorage = {
      _d: {}, getItem(k) { return this._d[k] ?? null; },
      setItem(k, v) { this._d[k] = v; }, removeItem(k) { delete this._d[k]; },
    };
  }
  const P = await import(J('data.paket.js'));

  const paket = P.paketAus('Prüfstand');
  wahr('Paket führt Format und Version',
       paket.format === P.PAKET_FORMAT && paket.version === P.PAKET_VERSION);
  /*
   * SECHS TEILE SEIT DEM 16. SEPTEMBER, nicht drei. Abfangjoche und Anker
   * lagen zwar schon als Datei daneben, waren aber nicht im Paket; die
   * Masten standen überhaupt nur im Quelltext. Ein Paket, das nur die
   * Hälfte der Sortimente trägt, kann eine datenfreie Ausgabe nicht
   * vollständig versorgen.
   */
  wahr('Paket enthält die drei Pflichtteile',
       Boolean(paket.tragjoche && paket.anbauteile && paket.fl_bauteile));
  wahr('Paket enthält auch die drei übrigen Sortimente',
       Boolean(paket.abfangjoche && paket.anker && paket.masten));

  const p = P.pruefePaket(paket);
  wahr('Eigenes Paket besteht die Prüfung', p.ok, p.fehler.join(' '));
  pruef('Sechs Teile erkannt', p.teile.length, 6, 1e-12, 'Stk');
  wahr('Die Teile sind gezählt', p.teile.every((t) => t.anzahl > 0),
       p.teile.map((t) => `${t.label} ${t.anzahl}`).join(' · '));

  // Was abgelehnt werden muss
  wahr('Fremdes Format wird abgelehnt',
       !P.pruefePaket({ format: 'anderes', tragjoche: { typen: [1] } }).ok);
  wahr('Neuere Paketversion wird abgelehnt',
       !P.pruefePaket({ version: P.PAKET_VERSION + 1, tragjoche: { typen: [1] } }).ok);
  wahr('Leeres Paket wird abgelehnt', !P.pruefePaket({}).ok);
  wahr('Kein Objekt wird abgelehnt', !P.pruefePaket(null).ok);
  wahr('Leerer Teil wird abgelehnt',
       !P.pruefePaket({ tragjoche: { typen: [] } }).ok);

  /*
   * SEIT DEM 16. SEPTEMBER SCHREIBT DAS PAKET TABELLEN. Ein Paket, das
   * vorher im Browser hinterlegt wurde, traegt seine Teile noch als Baum -
   * und muss sich weiterhin oeffnen lassen.
   */
  wahr('Das Paket schreibt Tabellenform',
       TBF.istTabellenform(paket.tragjoche) && TBF.istTabellenform(paket.masten));
  {
    const alt = { format: P.PAKET_FORMAT, version: 1,
                  tragjoche: TBF.setzeZusammen(paket.tragjoche) };
    const pa = P.pruefePaket(alt);
    wahr('Ein Paket in Baumform wird weiterhin gelesen', pa.ok, pa.fehler.join(' '));
    pruef('… und seine Typen werden gezaehlt', pa.teile[0]?.anzahl,
          paket.tragjoche.tabellen.typen.length, 1e-12, 'Typen');
  }
  wahr('Ein Teil des falschen Sortiments wird abgelehnt',
       !P.pruefePaket({ format: P.PAKET_FORMAT, tragjoche: paket.masten }).ok);

  // Nur ein Teil: der Rest bleibt stehen
  const nurTypen = { format: P.PAKET_FORMAT, version: 1, tragjoche: paket.tragjoche };
  wahr('Ein einzelner Teil genügt', P.pruefePaket(nurTypen).ok);

  // Ablage im Browser
  P.speichern(paket);
  const zurueck = P.ausSpeicher();
  pruef('Hinterlegt und wieder geholt: gleich viele Typen',
        zurueck.tragjoche.tabellen.typen.length,
        paket.tragjoche.tabellen.typen.length, 1e-12, 'Typen');
  P.speicherLeeren();
  wahr('Nach dem Leeren ist nichts mehr hinterlegt', P.ausSpeicher() === null);

  wahr('Daten gelten als vorhanden, solange Typen geladen sind', P.datenVorhanden());
}

// ===========================================================================
titel('19  AxisVM-Export (SAF)');

{
  const AX = await import(J('export.axisvm.js'));
  const { modell } = await import(J('core.vierendeel.js'));

  const eingabe = basis({
    lastHerkunft: 'manuell', gkManuell: 0.6, wkManuell: 0.5, skManuell: 0.3,
    schneeAktiv: true,
    anbauteile: [{ ...teil({ name: 'HS', x: 7.5 }), raster: 0.4,
                   befestigung: 'unten',
                   lasten: [block({ einwirkung: 'G', z: -1.35, Fz: 3 }),
                            block({ einwirkung: 'WindY', z: -1.35, Fy: 4 })] }],
  });
  const deps = { berechne, modell,
                 profOG: getProfil(eingabe.profOG), profUG: getProfil(eingabe.profUG),
                 stahl: getStahl(eingabe.stahl), joch: T.getTragjoch('J90') };
  const m = modell(eingabe, deps.profOG, deps.profUG, deps.stahl, deps.joch);

  /*
   * DAS AUFLAGERMODELL WIRD HIER BENANNT, NICHT GEERBT.
   *
   * Diese Pruefungen gelten dem GURTmodell - vier Punkte je Ende, keine
   * Drehfeder. Sie standen ohne Angabe da und lebten von der Vorgabe; als
   * die am 31. August auf 'mast' wechselte (Mast im Modell wird auch
   * ausgeleitet), fielen sie, ohne dass am Geprueften etwas falsch war.
   * Eine Pruefung, die ein bestimmtes Modell meint, hat es zu nennen.
   */
  const GURTE = { auflagerModell: 'gurte' };
  const bauA = AX.stabmodell(m, { knotenmodell: 'anschnitt', ...GURTE });
  const bauS = AX.stabmodell(m, { knotenmodell: 'schwerachsen', ...GURTE });

  // --- Geometrie -----------------------------------------------------------
  const kn = [...bauA.knoten.values()];
  pruef('Modell reicht von 0 bis L', Math.max(...kn.map((k) => k.x)), m.L, 1e-9, 'm');
  // Die Breite läuft mit x (Grundrissknick): in Feldmitte das Rechenmass,
  // im Auflagerbereich das grössere Mass - genau wie im Nachweis (knoten()).
  const yBei = (x) => {
    const p = [...bauA.knoten.values()]
      .filter((k) => Math.abs(k.x - x) < 1e-6 && k.name.startsWith('OG'));
    return Math.max(...p.map((k) => k.y)) - Math.min(...p.map((k) => k.y));
  };
  pruef('Gurtabstand in Feldmitte ist das Rechenmass', yBei(10), m.b, 1e-9, 'm');
  // Nur die GURTknoten: die Blechachsen liegen seit dem Schenkelversatz
  // weiter aussen, und das ist gewollt - sie bilden kein Rechteck mehr.
  const gurtKn = kn.filter((k) => /^(OG|UG)[LR]_/.test(k.name));
  pruef('Gurtabstand am Auflager folgt dem Grundrissknick',
        Math.max(...gurtKn.map((k) => k.y)) - Math.min(...gurtKn.map((k) => k.y)),
        m.breite.bAn(0), 1e-9, 'm');
  // Bei der Regelbauart LA_SI zeigt der liegende Schenkel nach AUSSEN und
  // zieht den Schwerpunkt mit. Die stehenden Schenkel - und damit die
  // Vertikalbleche - liegen dadurch INNEN von der Gurtachse; die liegenden
  // Schenkel mit den Horizontalblechen liegen aussen.
  wahr('Blechachsen sind in z weiter aussen als die Gurtachsen',
       Math.max(...kn.map((k) => k.z)) > Math.max(...gurtKn.map((k) => k.z)) + 1e-6);
  wahr('Blechachsen sind in y nicht weiter aussen',
       Math.max(...kn.map((k) => k.y)) <= Math.max(...gurtKn.map((k) => k.y)) + 1e-9);
  pruef('Gurtabstand lotrecht ist die Jochhöhe',
        Math.max(...kn.filter((k) => k.name.startsWith('OG')).map((k) => k.z))
        - Math.max(...kn.filter((k) => k.name.startsWith('UG')).map((k) => k.z)),
        m.h, 1e-9, 'm');

  // Der Lastpunkt hängt um z unter der Schwerachse des Anschlussgurtes
  const last = bauA.knoten.get(bauA.arme[0].knoten);
  pruef('Lastpunkt liegt z unter dem Anschlussgurt', last.z, m.h / 2 - m.h - 1.35,
        1e-9, 'm');

  wahr('Anschnittmodell hat mehr Stäbe als das Schwerachsenmodell',
       bauA.staebe.length > bauS.staebe.length,
       `${bauA.staebe.length} gegen ${bauS.staebe.length}`);
  wahr('Nur das Anschnittmodell hat steife Knotenbereiche',
       bauA.staebe.some((s) => s.qs === 'STARR' && /^(OG|UG)[LR]_S/.test(s.name))
       && !bauS.staebe.some((s) => s.qs === 'STARR' && /^(OG|UG)[LR]_S/.test(s.name)));
  wahr('Jeder Stab verweist auf vorhandene Knoten',
       bauA.staebe.every((s) => bauA.knoten.has(s.von) && bauA.knoten.has(s.bis)));
  wahr('Kein Stab hat Länge null',
       bauA.staebe.every((s) => {
         const a = bauA.knoten.get(s.von), b = bauA.knoten.get(s.bis);
         return Math.hypot(b.x - a.x, b.y - a.y, b.z - a.z) > 1e-9;
       }));
  // MEHRERE LASTBLOECKE AN DERSELBEN STELLE ERGEBEN KEINEN ZWEITEN ARM.
  // Sonst stuenden steife Arme nebeneinander und versteiften die oertliche
  // Einleitung kuenstlich. Seit die Baugruppe eine KETTE bildet (Abschnitt
  // 32), fuehrt arme EINEN Eintrag je Teil - aber alle Teile an derselben
  // Stelle zeigen auf DENSELBEN Knoten, und ein Stab entsteht nur dort, wo
  // sich der Punkt vom Vorgaenger unterscheidet.
  wahr('Mehrere Lastblöcke an derselben Stelle teilen sich einen Knoten',
       new Set(bauA.arme.map((x) => x.knoten)).size === 1,
       `${bauA.arme.length} Lastblöcke auf ` +
       `${new Set(bauA.arme.map((x) => x.knoten)).size} Knoten`);
  wahr('Und ergeben genau einen Arm',
       bauA.staebe.filter((s) => /^ARM\d+_\d+$/.test(s.name)).length === 1);

  // --- Lasten --------------------------------------------------------------
  const l = AX.lasten(m, bauA);
  const summe = (k, r) => l.punkt.filter((p) => p.lastfall === k && p.richtung === r)
    .reduce((s, p) => s + p.wert, 0);
  pruef('F_z zeigt in SAF nach oben, also negativ', summe('G', 'Z'), -3, 1e-9, 'kN');
  pruef('F_y bleibt unverändert', summe('WindY', 'Y'), 4, 1e-9, 'kN');
  const je = (k) => l.strecke.filter((q) => q.lastfall === k);
  const gurteVon = (k) => new Set(je(k).map((q) => q.stab.split('_')[0]));
  // Das EIGENGEWICHT schreibt der Export nicht mehr: das Rechenprogramm
  // ermittelt es aus den Stäben. Nur ein Zuschlag geht hinaus.
  wahr('Eigengewicht wird nicht als Streckenlast geschrieben',
       je('G').length === 0, `${je('G').length} Einträge`);
  // Schnee liegt oben, hälftig auf die beiden OBERGURTE.
  pruef('Schnee auf zwei Gurte', gurteVon('Schnee').size, 2, 1e-12, 'Gurte');
  wahr('Schnee nur auf den Obergurten',
       [...gurteVon('Schnee')].every((g) => g.startsWith('OG')),
       [...gurteVon('Schnee')].join(' '));
  pruef('Schnee je Gurt die Hälfte', je('Schnee')[0].wert, -0.30 / 2, 1e-9, 'kN/m');
  // Wind quer hälftig auf EINEN Ober- und EINEN Untergurt derselben Seite:
  // die Resultierende liegt damit auf halber Höhe, es entsteht keine Torsion.
  pruef('Wind auf zwei Gurte', gurteVon('WindY').size, 2, 1e-12, 'Gurte');
  wahr('Wind auf je einen Ober- und Untergurt derselben Seite',
       [...gurteVon('WindY')].sort().join(' ') === 'OGL UGL');
  pruef('Wind je Gurt die Hälfte', je('WindY')[0].wert, 0.50 / 2, 1e-9, 'kN/m');
  wahr('Schnee wird nur bei eingeschaltetem Schnee ausgegeben',
       AX.lasten(modell({ ...eingabe, schneeAktiv: false }, deps.profOG, deps.profUG,
                        deps.stahl, deps.joch),
                 bauA).strecke.every((q) => q.lastfall !== 'Schnee'));

  // --- Blätter -------------------------------------------------------------
  // Auch hier das Gurtmodell benennen - die Lagerpruefungen unten meinen es.
  const { blaetter } = AX.axisvmMappe(eingabe, deps,
                                      { knotenmodell: 'anschnitt', auflagerModell: 'gurte' });
  const namen = blaetter.map((b) => b.name);
  ['StructuralMaterial', 'StructuralCrossSection', 'StructuralPointConnection',
   'StructuralCurveMember', 'StructuralPointSupport', 'StructuralLoadCase',
   'StructuralLoadGroup', 'StructuralCurveAction', 'StructuralPointAction']
    .forEach((n) => wahr(`Blatt ${n} vorhanden`, namen.includes(n)));
  wahr('Anleitung und Vergleich liegen aussen',
       namen[0] === 'Anleitung' && namen[namen.length - 1] === 'Vergleich');

  const lf = blaetter.find((b) => b.name === 'StructuralLoadCase');
  wahr('Lastfall G ist NICHT als Eigengewicht deklariert',
       lf.rows.find((r) => r[0] === 'G')[4] === 'Others');

  // Das Vergleichsblatt führt die Schnittgrössen je Gruppe, charakteristisch:
  // die Auflagerquerkraft aus G ist von Hand nachrechenbar.
  const vgl = blaetter.find((b) => b.name === 'Vergleich');
  const kopfZ = vgl.rows.findIndex((r) => r?.[0]?.v === 'Station');
  const erste = vgl.rows[kopfZ + 1];
  pruef('V_z am Auflager aus G', erste[3].v, 0.6 * 20 / 2 + 3 * 12.5 / 20, 1e-9, 'kN');

  const qs = blaetter.find((b) => b.name === 'StructuralCrossSection');
  wahr('Gurt als Winkel, Blech als Rechteck ausgegeben',
       qs.rows.some((r) => r[0] === 'GURT_OG' && r[3] === 'Angle')
       && qs.rows.some((r) => String(r[0]).startsWith('BLECH_') && r[3] === 'Rectangle'));

  /*
   * DAS SAF-BLATT SPIEGELT DAS GEWAEHLTE AUFLAGERMODELL.
   *
   * Hier stand `stuetzung(m, a.ende)` - also nur der BUCHSTABE des Endes.
   * `lager.ux` war damit undefiniert, und jedes Lager fiel in die
   * Ersatz-Gabellagerung: volle Haltung in allen Richtungen plus Drehfeder.
   * Bei vier Gurtknoten je Ende wurde daraus ein VIERFACH eingespanntes
   * Jochende. Die alte Pruefung mass genau diesen Fehler und nannte ihn
   * richtig - sie las Spalte 7 und 9 und fand ueberall 'Rigid'/'Free'.
   */
  const auf = blaetter.find((b) => b.name === 'StructuralPointSupport');
  const spalten = auf.rows[0].map((z) => z.v ?? z);
  const sp = (name) => spalten.indexOf(name);
  const lagerZeilen = auf.rows.slice(1);
  wahr('Ein Lager je gehaltenem Knoten des Auflagermodells',
       lagerZeilen.length === 8, `${lagerZeilen.length} Zeilen`);   // 4 Gurte * 2 Enden
  wahr('Windbiegung bleibt gelenkig',
       lagerZeilen.every((r) => r[sp('fiz')] === 'Free'));
  wahr('Am Gurtmodell haelt keine Drehfeder - das Ende haengt an vier Punkten',
       lagerZeilen.every((r) => r[sp('fix')] === 'Free' && r[sp('fiy')] === 'Free'));

  // Die TEILWEISE EINSPANNUNG steht dort als lotrechte Feder am Obergurt.
  const og = lagerZeilen.filter((r) => String(r[3]).startsWith('OG'));
  const ug = lagerZeilen.filter((r) => String(r[3]).startsWith('UG'));
  pruef('Vier Obergurt- und vier Untergurtknoten', og.length, ug.length, 1e-12, 'Stk');
  wahr('Der Untergurt haelt lotrecht starr',
       ug.every((r) => r[sp('uz')] === 'Rigid'));
  // Ohne Einspannung (Vorgabe der Pruefvorrichtung) bleibt der Obergurt frei -
  // das ist das Gelenk, und es soll auch als solches dastehen.
  wahr('Ohne Einspannung ist der Obergurt lotrecht frei',
       og.every((r) => r[sp('uz')] === 'Free'),
       og.map((r) => r[sp('uz')]).join(' '));

  // Und die Gabellagerung gibt es weiterhin - im Ersatzbalken.
  const pktBl = AX.axisvmMappe(eingabe, deps,
    { knotenmodell: 'anschnitt', auflagerModell: 'punkt' }).blaetter;
  const aufP = pktBl.find((b) => b.name === 'StructuralPointSupport').rows.slice(1);
  wahr('Der Ersatzbalken traegt die Gabellagerung',
       aufP.length === 2 && aufP.every((r) => r[7] === 'Rigid' && r[9] === 'Free'),
       `${aufP.length} Zeilen`);

  // --- Endschott: tragend, nur die Ausgabe ist schaltbar --------------------
  const PKT = { knotenmodell: 'schwerachsen', auflagerModell: 'punkt' };
  const mitS = AX.stabmodell(m, PKT);
  const ausS = AX.stabmodell(m, { ...PKT, schottAusblenden: true });
  const schottStaebe = (b) => b.staebe.filter((st) => st.name.startsWith('SCHOTT_')).length;
  pruef('Das Schott steht in beiden Fällen im Modell',
        schottStaebe(ausS), schottStaebe(mitS), 1e-12, 'Stk');
  pruef('Acht Schottstäbe, vier je Ende', schottStaebe(mitS), 8, 1e-12, 'Stk');
  pruef('Gleich viele Stäbe insgesamt',
        ausS.staebe.length, mitS.staebe.length, 1e-12, 'Stk');
  wahr('Ein Auflagerknoten je Ende, auf der Jochachse',
       mitS.auflager.length === 2
         && mitS.auflager.every((a) => Math.abs(mitS.knoten.get(a.knoten).y) < 1e-9));

  // --- Die drei Auflagermodelle ---------------------------------------------
  const gurteM = AX.stabmodell(m, { knotenmodell: 'schwerachsen', auflagerModell: 'gurte' });
  pruef('Variante gurte: vier gehaltene Knoten je Ende',
        gurteM.auflager.length, 8, 1e-12, 'Stk');
  wahr('Variante gurte: nur die Untergurte lotrecht gehalten',
       gurteM.auflager.filter((a) => a.uz === 'Rigid').length === 4
       && gurteM.auflager.every((a) => (a.uz === 'Rigid') === a.knoten.startsWith('UG')));
  wahr('Variante gurte: alle in y gehalten, keine Drehfeder',
       gurteM.auflager.every((a) => a.uy === 'Rigid' && a.fiy === 'Free'));
  wahr('Variante gurte: genau ein Knoten haelt in Jochachse',
       gurteM.auflager.filter((a) => a.ux === 'Rigid').length === 1,
       gurteM.auflager.filter((a) => a.ux === 'Rigid').map((a) => a.knoten).join(' '));
  wahr('Variante gurte: kein Schott',
       schottStaebe(gurteM) === 0);

  const mitteM = AX.stabmodell(m, { knotenmodell: 'schwerachsen', auflagerModell: 'mitte' });
  pruef('Variante mitte: zwei gehaltene Knoten je Ende',
        mitteM.auflager.length, 4, 1e-12, 'Stk');
  wahr('Variante mitte: auf halber Höhe in den Gurtebenen',
       mitteM.auflager.every((a) => {
         const k = mitteM.knoten.get(a.knoten);
         // Die Breite läuft mit x - am Auflager gilt das Mass des Knicks.
         const b = m.breite ? m.breite.bAn(a.x) : m.b;
         const h = m.verlauf ? m.verlauf.hAn(a.x) : m.h;
         return Math.abs(Math.abs(k.y) - b / 2) < 1e-9
             && Math.abs(k.z - (m.h / 2 - h / 2)) < 1e-9
             && a.uz === 'Rigid';
       }));
  wahr('Variante mitte: Gelenk um y', mitteM.auflager.every((a) => a.fiy === 'Free'));

  wahr('Vorgabe nach Bauweise', AX.auflagerVorgabe({ bauweise: 'alt' }) === 'mitte'
       && AX.auflagerVorgabe({ bauweise: 'neu' }) === 'gurte');

  /* =========================================================================
   * >>> DER FUSSPUNKT IST EIN EIGENES MASS. <<<
   * =========================================================================
   *
   * Weisung vom 12. September. Bis dahin lag der Fuss IMMER genau die
   * Anschlusshoehe unter der Jochachse, und die Mastlaenge wuchs allein nach
   * oben. Ein Mast auf tieferem Fundament - fallendes Gelaende, tiefere
   * Einbindung - war bei gleicher Anschlusshoehe nicht abzubilden.
   *
   * Jetzt sind es drei Groessen, und sie haengen so zusammen:
   *
   *   H_frei = H_Anschluss - Fussversatz     (positiv nach oben)
   *   z_Fuss = Jochachse - H_frei
   *   z_Kopf = z_Fuss + L_M
   *
   * >>> UND DIE DREHFEDER RECHNET MIT DER FREIEN LAENGE. <<<
   *
   * Ausdrueckliche Weisung: c_phi = Rahmenfaktor * E*I/H, und H ist die
   * Strecke, ueber die sich der Mast unter dem Jochanschluss verbiegt. Ein
   * tieferer Fuss macht die Einspannung weicher - das ist keine
   * Darstellung, das rechnet mit.
   */
  {
    const AU = await import(J('core.auflager.js'));
    const CK = await import(J('core.constants.js'));
    const gr = { ...basis(), mastVorhanden: true, endbedingung: 'mast',
                 mastProfil: 'HEB 260', mastH: 7.5, mastLaenge: 0 };
    const s0 = AU.mastSteifigkeit(gr, 'A', false);
    const s4 = AU.mastSteifigkeit({ ...gr, mastFuss: -0.4 }, 'A', false);
    pruef('Ohne Versatz ist die freie Laenge die Anschlusshoehe',
          s0.H, 7.5, 1e-12, 'm');
    wahr('… und der Versatz steht als null dabei', s0.fuss === 0);
    pruef('Ein tieferer Fuss verlaengert sie', s4.H, 7.9, 1e-12, 'm');
    pruef('… die Anschlusshoehe bleibt, wo sie war',
          s4.HAnschluss, 7.5, 1e-12, 'm');
    /*
     * c_phi ~ 1/H - die Probe ist ein Dreisatz und braucht keine zweite
     * Rechnung: dieselbe Steifigkeit, nur ein laengerer Hebel.
     */
    pruef('Die Drehfeder folgt der freien Laenge',
          s4.cPhi, s0.cPhi * 7.5 / 7.9, 1e-6, 'kNm/rad');
    wahr('… und wird dadurch weicher, nicht steifer', s4.cPhi < s0.cPhi);
    /*
     * DIE LAENGE MISST VOM FUSS. Ohne eigene Angabe ist sie die freie Laenge
     * plus halbe Jochhoehe plus 0.50 m, aufgerundet auf den halben Meter -
     * bei 7.90 m also 9.00 statt 8.50.
     */
    pruef('Die vorgegebene Laenge misst vom Fuss', s4.laenge, 9.0, 1e-12, 'm');
    /*
     * UND IM AUSGELEITETEN MODELL STEHT ER DORT. Der Fuss faellt um den
     * Versatz, der Kopf um Versatz plus Mehrlaenge.
     */
    const mF = modell({ ...gr, mastFuss: -0.4 },
                      getProfil(gr.profOG), getProfil(gr.profUG),
                      getStahl(gr.stahl), T.getTragjoch(gr.typ ?? 'J90'));
    const bF = AX.stabmodell(mF, { knotenmodell: 'anschnitt' });
    const knF = (n) => [...bF.knoten.values()].find((k) => k.name === n);
    pruef('Im Modell faellt der Mastfuss mit', knF('MAST_A_F').z, -7.9, 1e-9, 'm');
    pruef('… und der Kopf steht auf Fuss + Laenge',
          knF('MAST_A_KOPF').z, -7.9 + 9.0, 1e-9, 'm');
    /*
     * OHNE ANGABE AENDERT SICH NICHTS. Jede bisher gespeicherte Datei
     * rechnet unveraendert weiter - das ist die Bedingung, unter der ein
     * neues Mass ueberhaupt dazukommen darf.
     */
    const ohne = AU.mastSteifigkeit(gr, 'A', false);
    const nullExplizit = AU.mastSteifigkeit({ ...gr, mastFuss: 0 }, 'A', false);
    wahr('Ohne Angabe rechnet alles wie zuvor',
         Math.abs(ohne.cPhi - nullExplizit.cPhi) < 1e-9
         && ohne.H === nullExplizit.H && ohne.laenge === nullExplizit.laenge);
    /*
     * ER GEHOERT DEM MASTEN, NICHT DEM JOCHENDE. Zwei Joche am selben
     * Masten duerfen verschieden hoch anschliessen - aber sie stehen auf
     * demselben Fundament. Deshalb steht er in MASTFELDER.
     */
    wahr('Der Fusspunkt steht in der Mastenliste',
         CK.MASTFELDER.some((f) => f.am === 'fuss' && f.flach === 'mastFuss'
                               && f.flachB === 'mastFussB'));
  }

  /* =========================================================================
   * >>> DIE MASKE BIETET AN, WAS DIESES TRAGWERK HAT. <<<
   * =========================================================================
   *
   * Weisung vom 12. September: «kannst du beim output die lagerung gemaess
   * unseren aktuellen definition anbieten und die restlichen weglassen, falls
   * nicht wirklich notwendig.»
   *
   * Vier Modelle standen nebeneinander, drei davon ohne Bezug zum Tragwerk
   * auf dem Tisch. Es bleiben zwei: seine eigene Lagerung und der Punkt je
   * Ende fuer den Abgleich mit dem Ersatzbalken - das einzige Modell, das die
   * teilweise Einspannung als Drehfeder traegt.
   *
   * WEGGELASSEN WIRD DIE WAHL, NICHT DAS MODELL. `gurte` und `mitte` bleiben,
   * was sie sind; der Pruefstand rechnet sie weiter durch (siehe die
   * Kontrollen zum Gurt- und zum Mittenmodell weiter oben).
   */
  {
    const schl = (m2, art2, hm) => AX.auflagerAngebot(m2, art2, hm)
      .map((k) => k.key).join(',');
    wahr('Mit Mast: seine Lagerung und der Abgleich',
         schl({ federn: { mast: {} }, bauweise: 'neu' }, 'joch', true)
         === 'mast,punkt');
    wahr('Ohne Mast, neue Bauweise: die Gurte statt des Masten',
         schl({ bauweise: 'neu' }, 'joch', false) === 'gurte,punkt');
    wahr('Altbauweise: die Mitte der Gurtebenen',
         schl({ bauweise: 'alt' }, 'joch', false) === 'mitte,punkt');
    wahr('Das Abfangjoch kennt Gurt- und Mittenmodell ohnehin nicht',
         schl({ federn: { mast: {} } }, 'abfangjoch', true) === 'mast,punkt');
    wahr('… und ohne Masten bleibt ihm der Punkt',
         schl({}, 'abfangjoch', false) === 'punkt');
    /*
     * DER ABGLEICH IST IMMER DABEI - er haengt an keinem Bauteil, sondern
     * bildet den Ersatzbalken nach. Faellt er einmal aus der Liste, ist die
     * Vergleichsbasis der Kalibrierung nicht mehr zu erreichen.
     */
    wahr('Der Abgleich steht in jedem Fall zur Wahl',
         ['joch', 'tragausleger', 'abfangjoch'].every((a2) =>
           [true, false].every((hm) =>
             AX.auflagerAngebot({ bauweise: 'neu' }, a2, hm)
               .some((k) => k.key === 'punkt'))));
    wahr('Und keines der angebotenen Modelle ist erfunden',
         ['joch', 'abfangjoch'].every((a2) =>
           AX.auflagerAngebot({ federn: { mast: {} } }, a2, true)
             .every((k) => AX.AUFLAGERMODELLE.some((o) => o.key === k.key))));
  }

  // --- Starrelemente bis an die Blechkanten ---------------------------------
  {
    // Schnitt C-C: Vertikalblech 320 = 500 − 2·90, es stösst an
    // die SPITZEN der stehenden Schenkel. Von der Gurtachse aus: aV − zsH.
    // Horizontalblech 260 = lichte Weite, es stösst an deren INNENSEITE: zsV.
    const teil = (b, anfang, endung) =>
      b.staebe.find((x) => x.name === `${anfang}${endung}`);
    const laengeVon = (b, st) => {
      const a = b.knoten.get(st.von), e = b.knoten.get(st.bis);
      return Math.hypot(e.x - a.x, e.y - a.y, e.z - a.z);
    };
    const bv = bauA.staebe.filter((x) => x.name.startsWith('BV_L_0'));
    wahr('Vertikalblech ist in steif / weich / steif geteilt',
         ['_1', '_2', '_3'].every((e) => bv.some((x) => x.name.endsWith(e))));
    // MASSGEBEND IST DIE BLECHLÄNGE AUS DEM SORTIMENT, nicht eine Ableitung:
    // die Blecheinteilung wird übernommen, nicht nachgerechnet.
    const lV = bauA.staebe.length && m.stationsListe[0].vertikal.laenge;
    pruef('Weicher Teil ist die Blechlänge aus dem Sortiment',
          laengeVon(bauA, teil(bauA, 'BV_L_0', '_2')), lV / 1000, 1e-9, 'm');
    pruef('Steifes Stück ist (Hebelarm − Blechlänge)/2',
          laengeVon(bauA, teil(bauA, 'BV_L_0', '_1')),
          (m.stationsListe[0].h - lV / 1000) / 2, 1e-9, 'm');
    wahr('Beide Enden gleich lang',
         Math.abs(laengeVon(bauA, teil(bauA, 'BV_L_0', '_1'))
                - laengeVon(bauA, teil(bauA, 'BV_L_0', '_3'))) < 1e-12);
    // Für J90 fällt die Ableitung aus dem Profil auf denselben Wert:
    // 320 = 500 − 2·90, also aV − zsH. Das ist die Probe aufs Exempel.
    pruef('Ableitung aV − zsH trifft dasselbe',
          laengeVon(bauA, teil(bauA, 'BV_L_0', '_1')),
          (m.profOG.aV - m.profOG.zsH * 10) / 1000, 1e-6, 'm');
    // Die Endstation trägt kein Horizontalblech - die erste ist Nummer 1.
    pruef('Steifes Stück des Horizontalblechs ist zsV',
          laengeVon(bauA, teil(bauA, 'BH_O_1', '_1')),
          m.profOG.zsV * 10 / 1000, 1e-9, 'm');
    wahr('Nur das mittlere Stück trägt den Blechquerschnitt',
         teil(bauA, 'BV_L_0', '_2').qs.startsWith('BLECH_V')
         && teil(bauA, 'BV_L_0', '_1').qs === 'STARR'
         && teil(bauA, 'BV_L_0', '_3').qs === 'STARR');

    // Das Modell 'schwerachsen' bleibt bewusst ohne - es ist der Vergleich
    // gegen das, was AxisVM ohne Zutun rechnet.
    wahr('Ohne Anschnitt keine Starrelemente im Blech',
         !mitS.staebe.some((x) => /^BV_L_0_[13]$/.test(x.name)));
  }

  // --- Zu enge Schnitte zusammenlegen ---------------------------------------
  {
    const f = AX.schnitteZusammenlegen;
    // Die Mitte bleibt stehen, die Reihen rasten auf sie ein.
    const r1 = f([0, 6.25, 6.35, 20], [6.30, 6.29, 6.31]);
    wahr('Die Mitte überlebt, die Reihen rasten ein',
         r1.xs.includes(6.3) && !r1.xs.includes(6.29) && !r1.xs.includes(6.31));
    pruef('Zwei Verschiebungen vermerkt', r1.verschoben.length, 2, 1e-12, 'Stk');
    pruef('Betrag der Verschiebung', Math.abs(r1.verschoben[0].betrag), 0.01, 1e-9, 'm');

    // Feste Schnitte bleiben, auch wenn sie eng liegen.
    const r2 = f([1.000, 1.010], []);
    pruef('Feste Schnitte werden nicht angetastet', r2.xs.length, 2, 1e-12, 'Stk');

    // Weit genug entfernt: der bewegliche bleibt eigenständig.
    const r3 = f([0, 20], [10]);
    wahr('Genug Abstand, kein Einrasten',
         r3.xs.includes(10) && r3.verschoben.length === 0);

    // Ein bewegliches rastet auf ein festes ein, nicht umgekehrt.
    const r4 = f([5.000], [5.010]);
    wahr('Der bewegliche rastet auf den festen',
         r4.xs.length === 1 && r4.xs[0] === 5 && r4.verschoben[0].nach === 5);
  }

  // Am ganzen Modell: keine zu kurzen Gurtstücke mehr.
  {
    const mitTeil = rechne({ ...basis({ typ: 'J90', L: 20 }),
      anbauteile: [{ ...teil({ name: 'HS', x: 6.3, Gz: 12 }),
                     befestigung: 'durchgehend', raster: 0.02 }],
    }).modell;
    const b = AX.stabmodell(mitTeil, { knotenmodell: 'anschnitt' });
    const gx = [...new Set([...b.knoten.values()]
      .filter((k) => k.name.startsWith('OGL_')).map((k) => k.x))].sort((p, q) => p - q);
    const eng = gx.filter((x, i) => i > 0 && x - gx[i - 1] < 0.025 - 1e-9);
    wahr('Keine Gurtschnitte enger als 25 mm', eng.length === 0);
    wahr('Das enge Raster wird zu einer Reihe',
         b.staebe.filter((x) => /^AT\d+_UG_R\d[LR]$/.test(x.name)).length === 2);
    wahr('Und damit biegesteif - kein zweiter Ast',
         !b.staebe.some((x) => /^AT\d+_UG_B2$/.test(x.name)));
    wahr('Die Verschiebung wird vermerkt', b.verschoben.length > 0);
  }

  // --- Anschluss der Hängestützen -------------------------------------------
  {
    const mitAnbau = (bef, raster) => {
      const mm = rechne({ ...basis({ typ: 'J90', L: 20 }),
        anbauteile: [{ ...teil({ name: 'HS', x: 8, Gz: 12, Qy: 3,
                                 z: bef === 'oben' ? 0.8 : -1.5 }),
                       befestigung: bef, raster }],
      }).modell;
      return AX.stabmodell(mm, { knotenmodell: 'schwerachsen' });
    };
    const stummel = (b, gurt) =>
      b.staebe.filter((x) => new RegExp(`^AT\\d+_${gurt}_R\\d[LR]$`).test(x.name));

    // Ohne Raster: eine Reihe, zwei Punkte, alles steif - Variante A.
    const zwei = mitAnbau('unten', 0);
    pruef('Zwei Punkte: eine Reihe zu je zwei Gurten',
          stummel(zwei, 'UG').length, 2, 1e-12, 'Stk');
    wahr('Zwei Punkte: biegesteif, kein Gelenk',
         stummel(zwei, 'UG').every((x) => !x.gelenkEnde && !x.gelenkAnfang));

    // Mit Raster: zwei Reihen längs der Jochachse, vier Punkte je Ebene.
    const vier = mitAnbau('unten', 0.4);
    pruef('Vier Punkte am Untergurt', stummel(vier, 'UG').length, 4, 1e-12, 'Stk');
    wahr('Die Stummel selbst sind alle steif',
         stummel(vier, 'UG').every((x) => !x.gelenkEnde && !x.gelenkAnfang));
    // Die Freigabe sitzt im vertikalen LINKELEMENT des Übergangs Gurt ->
    // Anbauteil: die zweite Reihe gibt die Längskraft frei, sonst zwängt
    // der Anschluss im Gurt. Die Äste selbst sind überall steif.
    const aeste = (b) => b.staebe.filter((x) => /^AT\d+_UG_B\d$/.test(x.name));
    pruef('Zwei Äste zu den Reihen', aeste(vier).length, 2, 1e-12, 'Stk');
    wahr('Die Äste sind alle steif',
         aeste(vier).every((x) => !x.gelenkEnde && !x.gelenkAnfang));

    const links = (b, gurt) =>
      b.staebe.filter((x) => new RegExp(`^AT\\d+_${gurt}_R\\d[LR]_V$`).test(x.name));
    const linkLage = (b, x) => {
      const p = b.knoten.get(x.von), q = b.knoten.get(x.bis);
      return { dx: q.x - p.x, dy: q.y - p.y, dz: q.z - p.z };
    };
    pruef('Vier Übergangs-Links am Untergurt', links(vier, 'UG').length, 4, 1e-12, 'Stk');
    wahr('Die Links stehen senkrecht',
         links(vier, 'UG').every((x) => {
           const l = linkLage(vier, x);
           return Math.abs(l.dx) < 1e-9 && Math.abs(l.dy) < 1e-9;
         }));
    wahr('Die Links sind 10 cm lang und zeigen am Untergurt nach unten',
         links(vier, 'UG').every((x) => Math.abs(linkLage(vier, x).dz + 0.10) < 1e-9));
    wahr('Die erste Reihe hält die Längskraft',
         links(vier, 'UG').filter((x) => /R1[LR]_V$/.test(x.name))
           .every((x) => x.kraft.x === 'Rigid'));
    wahr('Die zweite Reihe gibt die Längskraft frei',
         links(vier, 'UG').filter((x) => /R2[LR]_V$/.test(x.name))
           .every((x) => x.kraft.x === 'Free' && x.kraft.y === 'Rigid'
                      && x.kraft.z === 'Rigid'));
    // Der Zweck des Linkelements: es überträgt KRÄFTE, keine Momente.
    wahr('Bei vier Punkten überträgt kein Link ein Moment',
         links(vier, 'UG').every((x) =>
           ['xx', 'yy', 'zz'].every((f) => x.kraft[f] === 'Free')));
    wahr('Bei zwei Punkten hält das Link die drei Kräfte',
         links(zwei, 'UG').length === 2
         && links(zwei, 'UG').every((x) =>
              ['x', 'y', 'z'].every((f) => x.kraft[f] === 'Rigid')));
    // Zwei Punkte liegen auf einer Geraden in Gleisrichtung - um sie hielte
    // sonst nichts. Deshalb dort M_y, und NUR dort.
    wahr('Bei zwei Punkten hält das Link zusätzlich M_y',
         links(zwei, 'UG').every((x) => x.kraft.yy === 'Rigid'
                                     && x.kraft.xx === 'Free'
                                     && x.kraft.zz === 'Free'));
    wahr('Bei vier Punkten hält es M_y nicht',
         links(vier, 'UG').every((x) => x.kraft.yy === 'Free'));

    // Die Arme heissen jetzt ARM{Baugruppe}_{Glied}: eine Baugruppe bildet
    // eine KETTE und nicht mehr einen einzelnen Arm (Abschnitt 32).
    const arm = (b) => b.staebe.filter((x) => /^ARM\d+_\d+$/.test(x.name));

    // DIESE VORRICHTUNG HAT KEINEN HOEHENVERSATZ: die Hilfsfunktion teil()
    // fuehrt kein z, der Lastpunkt liegt also AUF der Anschlussebene. Dann
    // gibt es nichts zu ueberbruecken - und vor allem keinen Stab der Laenge
    // null, wie ihn der Aufbau hier frueher erzeugte.
    wahr('Ohne Hoehenversatz entsteht kein Arm',
         arm(vier).length === 0, `${arm(vier).length} Glieder`);
    wahr('Und damit auch kein Stab der Laenge null',
         vier.staebe.every((x) => {
           const p = vier.knoten.get(x.von), q = vier.knoten.get(x.bis);
           return Math.hypot(q.x - p.x, q.y - p.y, q.z - p.z) > 1e-9;
         }));

    // Mit Versatz ist der Arm da - und ein Starrkoerper ohne Gelenk.
    {
      const mm = rechne({ ...basis({ typ: 'J90', L: 20 }),
        anbauteile: [A.neuesAnbauteil('hs-nur', 8)],
      }).modell;
      const b = AX.stabmodell(mm, { knotenmodell: 'schwerachsen' });
      wahr('Mit Hoehenversatz ist die Hängestütze als Starrkörper geführt',
           arm(b).length > 0 && arm(b).every((x) => x.starrRolle === 'anbauteil'
             && !x.gelenkAnfang && !x.gelenkEnde),
           `${arm(b).length} Glieder`);
    }

    wahr('Die Äste liegen in der Jochachse',
         aeste(vier).every((x) => {
           const p = vier.knoten.get(x.von), q = vier.knoten.get(x.bis);
           return Math.abs(p.y - q.y) < 1e-9 && Math.abs(p.z - q.z) < 1e-9
               && Math.abs(p.x - q.x) > 1e-6;
         }));
    wahr('Die Reihen liegen um das Raster auseinander',
         (() => {
           const xs = [...new Set(stummel(vier, 'UG')
             .map((x) => vier.knoten.get(x.von).x))].sort((p, q) => p - q);
           return xs.length === 2 && Math.abs(xs[1] - xs[0] - 0.4) < 1e-9;
         })());
    wahr('Die Stummel laufen rechtwinklig zur Gurtachse',
         stummel(vier, 'UG').every((x) => {
           const p = vier.knoten.get(x.von), q = vier.knoten.get(x.bis);
           return Math.abs(p.x - q.x) < 1e-9 && Math.abs(p.z - q.z) < 1e-9;
         }));

    // Durchgehend: dieselbe Regel oben wie unten, acht Punkte.
    const durch = mitAnbau('durchgehend', 0.4);
    pruef('Durchgehend: vier Punkte unten', stummel(durch, 'UG').length, 4, 1e-12, 'Stk');
    pruef('Durchgehend: vier Punkte oben', stummel(durch, 'OG').length, 4, 1e-12, 'Stk');
    wahr('Durchgehend: auch oben gibt die zweite Reihe die Längskraft frei',
         durch.staebe.some((x) => /^AT\d+_OG_R2[LR]_V$/.test(x.name)
                               && x.kraft.x === 'Free'));
    wahr('Durchgehend: am Obergurt zeigt das Link nach oben',
         durch.staebe.filter((x) => /^AT\d+_OG_R\d[LR]_V$/.test(x.name))
           .every((x) => {
             const p = durch.knoten.get(x.von), q = durch.knoten.get(x.bis);
             return Math.abs(q.z - p.z - 0.10) < 1e-9;
           }));
    wahr('Durchgehend: ein Stab verbindet Ober- und Untergurt',
         durch.staebe.some((x) => /^ARM\d+_D$/.test(x.name)));
    wahr('Durchgehend: auch der Stab durch den Kasten ist ein Starrkörper',
         durch.staebe.find((x) => /^ARM\d+_D$/.test(x.name)).starrRolle === 'anbauteil');
    wahr('Nur bei durchgehend läuft der Stab durch',
         !vier.staebe.some((x) => /^ARM\d+_D$/.test(x.name)));
  }

  // --- Blechachsen liegen versetzt ------------------------------------------
  // Die vier Gurtachsen bilden im Schnitt ein Rechteck, die Blechachsen nicht:
  // ein Blech liegt am Schenkel, nicht auf der Verbindungslinie der Schwerpunkte.
  const versatzStaebe = mitS.staebe.filter((st) => /_e[12]$/.test(st.name));
  wahr('Bindebleche sind quer versetzt angeschlossen', versatzStaebe.length > 0);
  {
    // Gemessen wird am STUMMEL: von der Gurtachse zur Blechachse. Gegen
    // m.b/2 zu prüfen ginge fehl - die Breite läuft mit x (Grundrissknick).
    const versatzAn = (bau, anfang) => {
      const st = bau.staebe.find((x) => x.name.startsWith(anfang) && /_e1$/.test(x.name));
      if (!st) return null;
      const g = bau.knoten.get(st.von), bl = bau.knoten.get(st.bis);
      return { dy: bl.y - g.y, dz: bl.z - g.z };
    };
    const v = versatzAn(mitS, 'BV_L_');
    const h = versatzAn(mitS, 'BH_O_');
    pruef('Vertikalblech: Versatz (zsV − t/2) nach innen',
          v ? v.dy : NaN, (m.profOG.zsV * 10 - m.profOG.t / 2) / 1000, 1e-9, 'm');
    wahr('Vertikalblech: keine Höhenänderung', !!v && Math.abs(v.dz) < 1e-12);
    // Das Horizontalblech liegt an der Innenseite des liegenden Schenkels
    // (Schnitt C-C), nicht in dessen Flucht: die Mittelebene
    // rückt um (t_Schenkel + t_Blech)/2 nach innen. Für L90×90×9 mit 10 mm
    // Blech sind das 9.5 mm - die «10 mm» der Werkstattregel.
    // Nicht den Stummel erwischen: BH_O_0_e1 trägt STARR, nicht das Blech.
    const tH = mitS.querschnitte.get(
      mitS.staebe.find((x) => x.name.startsWith('BH_O_')
                           && x.qs.startsWith('BLECH_H')).qs).parameter[1];
    pruef('Horizontalblech: Flucht minus (t_Schenkel + t_Blech)/2',
          h ? h.dz : NaN,
          (m.profOG.zsH * 10 - m.profOG.t / 2 - (m.profOG.t + tH) / 2) / 1000,
          1e-9, 'm');
    pruef('Das Anliegen macht rund 10 mm aus',
          (m.profOG.t + tH) / 2, 9.5, 0.6, 'mm');
    wahr('Horizontalblech: keine Breitenänderung', !!h && Math.abs(h.dy) < 1e-12);

    // Andere Einbaulage, andere Richtung - der Grund, warum ey/ez aus
    // geometry.js kommen und nicht hier noch einmal stehen. Und zwar jede
    // Richtung für sich: das Vertikalblech sitzt am STEHENDEN Schenkel,
    // dessen Dicke aber in Richtung des LIEGENDEN misst - dy folgt deshalb
    // `lg`, dz folgt `st`.
    const mitLage = (k) => AX.stabmodell({ ...m, ausrOG: k, ausrUG: k },
                                         { knotenmodell: 'schwerachsen' });
    const vLI = versatzAn(mitLage('LI_SI'), 'BV_L_');
    wahr('liegend innen kehrt den Versatz in y um', !!vLI && v.dy * vLI.dy < 0);
    const hSA = versatzAn(mitLage('LA_SA'), 'BH_O_');
    wahr('stehend aussen kehrt den Versatz in z um', !!hSA && h.dz * hSA.dz < 0);
    const vSA = versatzAn(mitLage('LA_SA'), 'BV_L_');
    wahr('stehend aussen lässt den Versatz in y unberührt',
         !!vSA && Math.abs(vSA.dy - v.dy) < 1e-12);
  }
  wahr('Nur die Ausgabe ist geschaltet',
       ausS.schottAusblenden === true && mitS.schottAusblenden === false);

  const PYm = await import(J('export.pynite.js'));
  const skript = (o) => PYm.pyniteSkript(m, { knotenmodell: 'schwerachsen', ...o }).text;
  wahr('Skript blendet die Schottstäbe nur auf Wunsch aus',
       skript({ schottAusblenden: true }).includes('SCHOTT_AUSBLENDEN = True')
       && skript({}).includes('SCHOTT_AUSBLENDEN = False'));
  wahr('Die Schottstäbe stehen in beiden Skripten als Stäbe drin',
       (skript({ schottAusblenden: true }).match(/'SCHOTT_/g) ?? []).length ===
       (skript({}).match(/'SCHOTT_/g) ?? []).length);

  // --- DXF: Ausweichweg ohne SAF-Lizenz ------------------------------------
  const dxf = AX.dxfText(m, { knotenmodell: 'anschnitt', auflagerModell: 'gurte' });
  const zeilen = dxf.text.split('\n');
  wahr('DXF beginnt mit SECTION und endet mit EOF',
       zeilen[0] === '0' && zeilen[1] === 'SECTION'
       && zeilen[zeilen.length - 2] === 'EOF');
  pruef('Je Stab eine LINE', (dxf.text.match(/^LINE$/gm) ?? []).length,
        dxf.bau.staebe.length, 1e-12, 'Stk');
  wahr('Keine unberechneten Koordinaten im DXF', !/NaN|undefined|Infinity/.test(dxf.text));
  wahr('Jeder Querschnitt hat eine eigene Ebene',
       [...new Set(dxf.bau.staebe.map((st) => st.qs))]
         .every((q) => dxf.ebenen.includes(q.toUpperCase())));
  wahr('Auflager- und Lastpunkte liegen auf eigenen Ebenen',
       dxf.ebenen.includes('AUFLAGER') && dxf.ebenen.includes('LASTPUNKT'));

  // Das Begleitblatt trägt, was DXF nicht tragen kann
  const zu = AX.zuordnungsblatt(m, dxf, { knotenmodell: 'anschnitt' });
  const flach = JSON.stringify(zu.rows);
  ['Querschnitte je Ebene', 'Auflager', 'Streckenlasten', 'Punktlasten']
    .forEach((t) => wahr(`Zuordnungsblatt nennt ${t}`, flach.includes(t)));
  wahr('Zuordnungsblatt führt jeden Lastfall der Punktlasten',
       dxf.lasten.punkt.every((q) => flach.includes(q.name)));

  /*
   * DAS BLATT MUSS DAS MODELL BESCHREIBEN, DAS DANEBEN LIEGT.
   *
   * Es rief `stuetzung(m, a.ende)` - nur den Buchstaben. Damit fiel jedes
   * Lager in die Vorgabe (Gabellagerung mit Drehfeder), waehrend die
   * DXF-Datei das Gurtmodell trug: acht Zeilen, alle falsch beschrieben.
   */
  wahr('Zuordnungsblatt nennt eine Zeile je Auflagerknoten',
       dxf.bau.auflager.every((a) => flach.includes(a.knoten)),
       dxf.bau.auflager.map((a) => a.knoten).join(' '));
  wahr('Und nennt das Auflagermodell im Titel',
       flach.includes(`Modell ${dxf.bau.auflager[0].modell}`));
  {
    // Genau ein 'Rigid' in der Spalte ux - im Blatt wie im Modell.
    const zeilen = zu.rows.filter((r) => String(r[0]?.v ?? r[0]).startsWith('Auflager '));
    const uxSpalte = zeilen.map((r) => r[4]);
    wahr('Und haelt genau einen Knoten in Jochachse',
         uxSpalte.filter((v) => v === 'Rigid').length === 1, uxSpalte.join(' '));
  }
}

// ===========================================================================
titel('20  PyNite-Ausleitung');

{
  const PY = await import(J('export.pynite.js'));
  const { modell } = await import(J('core.vierendeel.js'));
  const e = basis({
    lastHerkunft: 'manuell', gkManuell: 0.6, wkManuell: 0.5, skManuell: 0.3,
    schneeAktiv: true,
    anbauteile: [{ ...teil({ name: 'HS', x: 7.5 }), raster: 0.4,
                   befestigung: 'unten',
                   lasten: [block({ einwirkung: 'G', z: -1.35, Fz: 3 }),
                            block({ einwirkung: 'WindY', z: -1.35, Fy: 4 })] }],
  });
  const m = modell(e, getProfil(e.profOG), getProfil(e.profUG),
                   getStahl(e.stahl), T.getTragjoch('J90'));
  const r = PY.pyniteSkript(m, { knotenmodell: 'anschnitt', auflagerModell: 'punkt' });

  wahr('Skript importiert PyNite mit Rückfall auf die alte Schreibweise',
       r.text.includes('from Pynite import FEModel3D')
       && r.text.includes('from PyNite import FEModel3D'));
  pruef('Je Stab eine add_member-Zeile',
        (r.text.match(/^M\.add_member\(/gm) ?? []).length, r.bau.staebe.length,
        1e-12, 'Stk');
  pruef('Je Knoten eine add_node-Zeile',
        (r.text.match(/^M\.add_node\(/gm) ?? []).length, r.bau.knoten.size,
        1e-12, 'Stk');
  wahr('Keine unberechneten Zahlen im Skript', !/NaN|undefined|Infinity/.test(r.text));
  wahr('Ein Lastfall je Einwirkungsgruppe mit Beiwert 1',
       r.faelle.every((f) => r.text.includes(`M.add_load_combo('${f}', {'${f}': 1.0})`)));

  /*
   * DAS LAGER, NICHT DER ENDBUCHSTABE.
   *
   * Hier stand in `pyniteSkript` eine ZWEITE, selbstgebaute Lagerungsregel:
   * jedes Auflager bekam y/z/Torsion gehalten und die Drehfeder dazu -
   * gleich, welches Auflagermodell `stabmodell` gebaut hatte. Beim
   * Gurtmodell waren das acht voll gehaltene Knoten samt acht Federn,
   * obwohl dort nur die Untergurte lotrecht halten und keine Feder
   * vorkommt. PyNite rechnete damit ein anderes Tragwerk als AxisVM aus
   * derselben Ausleitung.
   */
  {
    const g = PY.pyniteSkript(m, { knotenmodell: 'anschnitt', auflagerModell: 'gurte' });
    const zeilen = g.text.split(NL).filter((z) => z.startsWith('M.def_support('));
    pruef('Gurtmodell: acht Auflagerzeilen', zeilen.length, 8, 1e-12, 'Stk');
    // Reihenfolge DX, DY, DZ, RX, RY, RZ - PyNites Y ist unser z.
    const feld = (z, i) => z.slice('M.def_support('.length).split(',')[i].trim();
    const dx = zeilen.filter((z) => feld(z, 1) === 'True');
    wahr('Gurtmodell: genau ein Halt in Jochachse (DX)', dx.length === 1,
         zeilen.map((z) => feld(z, 1)).join(' '));
    const dy = zeilen.filter((z) => feld(z, 2) === 'True');
    wahr('Gurtmodell: vier lotrechte Halte (DY = unser uz), an den Untergurten',
         dy.length === 4 && dy.every((z) => z.includes("'UG")),
         String(dy.length));
    wahr('Gurtmodell: alle in Gleisrichtung gehalten (DZ = unser uy)',
         zeilen.every((z) => feld(z, 3) === 'True'));
    wahr('Gurtmodell: keine Drehfeder', !g.text.includes('def_support_spring'));
    // Ohne Einspannung gibt es auch im Ersatzbalken keine Feder ...
    const p2 = PY.pyniteSkript(m, { knotenmodell: 'anschnitt', auflagerModell: 'punkt' });
    wahr('Gelenkiger Ersatzbalken: auch dort keine Feder',
         !p2.text.includes('def_support_spring'));
    // ... mit teilweiser Einspannung dagegen eine je Ende.
    const eT = { ...e, endbedingung: 'manuell', cPhi: 12951, schraubenGrenze: false };
    const mT = modell(eT, getProfil(eT.profOG), getProfil(eT.profUG),
                      getStahl(eT.stahl), T.getTragjoch('J90'));
    const p3 = PY.pyniteSkript(mT, { knotenmodell: 'anschnitt', auflagerModell: 'punkt' });
    pruef('Teilweise eingespannt: zwei Drehfedern',
          (p3.text.match(/def_support_spring/g) || []).length, 2, 1e-12, 'Stk');
    wahr('Und zwar die geometrische, in kNm/rad',
         p3.text.includes('12951'), p3.text.split(NL)
           .filter((z) => z.includes('def_support_spring')).join(' | '));
    // Das Gurtmodell kann sie nicht tragen - und traegt sie auch nicht.
    const g3 = PY.pyniteSkript(mT, { knotenmodell: 'anschnitt', auflagerModell: 'gurte' });
    wahr('Das Gurtmodell bleibt auch dann ohne Feder',
         !g3.text.includes('def_support_spring'));
  }

  // Achsentausch: unser Z wird PyNites Y
  const knoten = r.text.split('\n').filter((z) => z.startsWith('M.add_node('));
  const auf = knoten.find((z) => z.includes("'AUF_A'"));
  const zahlen = auf.match(/-?\d+\.?\d*(e-?\d+)?/g).map(Number);
  pruef('Auflagerknoten: unser z steht an PyNites Y-Stelle', zahlen[1], 0, 1e-9, 'm');
  pruef('Auflagerknoten: unser y steht an PyNites Z-Stelle', zahlen[2], 0, 1e-9, 'm');

  // Drehlage der Blechquerschnitte: starke Achse je nach Ebene
  const qsV = r.querschnitte.find((q) => q.name.startsWith('BLECH_V'));
  const qsH = r.querschnitte.find((q) => q.name.startsWith('BLECH_H'));
  wahr('Vertikalblech: starke Achse ist Iz', qsV.Iz > qsV.Iy * 10);
  wahr('Horizontalblech: starke Achse ist Iy', qsH.Iy > qsH.Iz * 10);
  pruef('Beide Ebenen, dieselbe Fläche', qsV.A, qsH.A, 1e-12, 'm2');

  // Gurt: unser I_y wirkt gegen die Vertikalbiegung, in PyNite ist das Iz
  const gurt = r.querschnitte.find((q) => q.name === 'GURT_OG');
  const p = getProfil(e.profOG);
  pruef('Gurt: Iz aus unserem i_y', gurt.Iz, (p.iy * p.iy * p.A) / 1e8, 1e-9, 'm4');

  // Schnitte liegen in FELDMITTE, nicht auf den Stationen
  const stationen = JSON.parse(r.text.match(/STATIONEN = (\[[^\]]*\])/)[1]);
  const xs = m.stationsListe.map((st) => st.x);
  wahr('Schnitte liegen zwischen den Stationen, nicht auf ihnen',
       stationen.length === xs.length - 1
       && stationen.every((x) => !xs.some((v) => Math.abs(v - x) < 1e-6)));
}

// ===========================================================================
titel('21  Normalkraft in Jochachse');
// Sie wird im Nachweis längst mitgerechnet (N_ax je Winkel), stand aber in
// keiner Auswertung. Geprüft wird deshalb beides: die Grösse selbst und dass
// sie dort ankommt, wo sie hingehört.
{
  const L = 20, x0 = 6, zug = 12;          // kN längs, ständig
  const Nd = zug * 1.35;                   // Bemessungswert, γ_G = 1.35
  // Der Lastblock sitzt RELATIV zum Anbauteil - mit x = 0 greift er genau
  // dort an, wo das Teil steht.
  const t = teil({ id: 'ZUG', x: x0, befestigung: 'durchgehend',
    lasten: [block({ einwirkung: 'G', x: 0, Fx: zug })] });
  // γ hier ausdrücklich, damit die Zahlen nicht an der Vorgabe hängen.
  const e0 = basis({ L, torsionModell: 'verteilt', anbauteile: [t],
                     gammaG: 1.35, gammaQ: 1.5, psi0: 0.5 });
  const r = rechne(e0);

  // Aufteilung auf die Auflager wie bei der Torsion: links vom Angriff der
  // Anteil (L-x₀)/L, rechts davon x₀/L. Der grössere von beiden ist der
  // Höchstwert - hier links, weil der Angriff näher am linken Auflager liegt.
  pruef('N_x links vom Angriff', schnittgroessen(3, r.modell).Nx,
        (Nd * (L - x0)) / L, 1e-9, 'kN');
  pruef('N_x rechts vom Angriff', schnittgroessen(9, r.modell).Nx,
        (Nd * x0) / L, 1e-9, 'kN');
  pruef('Höchstwert ist der grössere der beiden Anteile',
        r.extrem.NxMax, (Nd * (L - x0)) / L, 1e-9, 'kN');
  pruef('Beide Anteile ergeben zusammen die Last',
        schnittgroessen(3, r.modell).Nx + schnittgroessen(9, r.modell).Nx,
        Nd, 1e-9, 'kN');

  // Flächenproportional auf die vier Winkel - bei gleichen Profilen je ein
  // Viertel.
  const s = { ...r.schnitt };
  const sn = auswertungAn(3, r.modell);
  const summe = sn.ecken.reduce((a, c) => a + c.N_ax, 0);
  pruef('Summe N_ax über alle vier Winkel = N_x', summe, sn.Nx, 1e-9, 'kN');
  wahr('Bei gleichen Profilen je ein Viertel',
       sn.ecken.every((c) => Math.abs(c.N_ax - sn.Nx / 4) < 1e-9));
  wahr('N je Winkel enthält den Normalkraftanteil',
       sn.ecken.every((c) => Math.abs(c.N - (c.N_My + c.N_Mz + c.N_ax)) < 1e-9));
  wahr('Der Schnitt führt N_x mit', Number.isFinite(s.Nx));

  // Ohne Längslast bleibt sie null - sonst wäre die Kachel eine Falle.
  pruef('Ohne Längslast keine Normalkraft', rechne(basis({ L })).extrem.NxMax,
        0, 1e-9, 'kN');
}

// ===========================================================================
titel('22  Ausleger: Wind über die Fahrleitung');
// Das äussere Ende des Auslegers hängt an der Fahrleitung; die wirkt durch den
// Leiterzug als Auflager und nimmt die eine Hälfte des Windes auf. Nur die
// andere kommt am Joch an - auf der Achse des Trägers, auf DERSELBEN Höhe.
{
  const trasse = { ek: 'EK2', R: 300000, spannweite: 50 };
  const bau = (extra) => [{ ...A.neuesAnbauteil('hs-nt-ausleger', 10),
                            name: 'Ausleger', ...extra }];
  const summe = (teile, gruppe, feld) => teile.reduce(
    (s, x) => s + (x.kraefte?.[gruppe]?.[feld] ?? 0), 0);
  const nachRolle = (teile, rolle, feld = 'Fy', gruppe = 'WindY') => teile
    .filter((x) => x.rolle === rolle)
    .reduce((s, x) => s + (x.kraefte?.[gruppe]?.[feld] ?? 0), 0);

  // Die Vorlage fuehrt windAufTraeger seit dem Kragarm-Entscheid selbst.
  // Der Vergleichsfall muss ihn deshalb ausdruecklich abschalten.
  const aus = A.expandiereAnbauteile(bau({ windAufTraeger: false }), trasse);
  const halb = A.expandiereAnbauteile(
    bau({ windAufTraeger: true, windAnteil: 50 }), trasse);
  const ganz = A.expandiereAnbauteile(
    bau({ windAufTraeger: true, windAnteil: 100 }), trasse);

  const wAufbau = nachRolle(aus, 'aufbau');
  const wTraeger = nachRolle(aus, 'traeger');
  const wDraht = nachRolle(aus, 'drahtwerk');
  wahr('Der Ausleger trägt selbst Wind in y', wAufbau > 0);

  pruef('50 %: die Hälfte des Auslegerwindes bleibt',
        summe(halb, 'WindY', 'Fy'),
        summe(aus, 'WindY', 'Fy') - wAufbau / 2, 1e-12, 'kN');
  pruef('100 %: nichts geht verloren', summe(ganz, 'WindY', 'Fy'),
        summe(aus, 'WindY', 'Fy'), 1e-12, 'kN');
  pruef('Träger behält seinen eigenen Wind', nachRolle(halb, 'traeger'),
        wTraeger, 1e-12, 'kN');
  pruef('Drahtwerk bleibt unangetastet', nachRolle(halb, 'drahtwerk'),
        wDraht, 1e-12, 'kN');
  pruef('Eigengewicht unangetastet', summe(halb, 'G', 'Fz'),
        summe(aus, 'G', 'Fz'), 1e-12, 'kN');

  // DIE HÖHE ÄNDERT SICH NICHT - nur der Abstand in y.
  const zAufbau = aus.find((x) => x.rolle === 'aufbau').z;
  const zTraeger = aus.find((x) => x.rolle === 'traeger').z;
  wahr('Ausleger und Träger sitzen auf verschiedenen Höhen', zAufbau !== zTraeger);
  const rest = halb.filter((x) => (x.kraefte?.WindY?.Fy ?? 0) > 0
                                   && Math.abs(x.z - zAufbau) < 1e-9);
  pruef('Der verbleibende Anteil wirkt auf der Höhe des Auslegers',
        rest.reduce((s, x) => s + x.kraefte.WindY.Fy, 0), wAufbau / 2, 1e-12, 'kN');
  wahr('Nichts wandert auf die Höhe des Trägers',
       Math.abs(halb.filter((x) => Math.abs(x.z - zTraeger) < 1e-9)
         .reduce((s, x) => s + (x.kraefte?.WindY?.Fy ?? 0), 0) - wTraeger) < 1e-12);
  const tr = aus.find((y) => y.rolle === 'traeger');
  wahr('Der Eintrag rückt in y auf die Achse des Trägers',
       rest.every((x) => Math.abs(x.y - tr.y) < 1e-12));
  // UND IN JOCHACHSE. Der NT ist ein Kragarm: sein Angriffspunkt liegt 1.2 m
  // versetzt. Bliebe der Anteil dort stehen, käme genau die Hälfte, die über
  // die Stütze ins Joch geht, an der falschen Station an.
  wahr('Und in Jochachse auf den Anschlusspunkt Ausleger/Stütze',
       rest.every((x) => Math.abs(x.x - tr.x) < 1e-12),
       `${rest.map((x) => x.x.toFixed(2)).join(' ')} gegen ${tr.x.toFixed(2)}`);
  wahr('Der Ausleger selbst steht wirklich aussen',
       Math.abs(aus.find((x) => x.rolle === 'aufbau').x - tr.x) > 1,
       `${(aus.find((x) => x.rolle === 'aufbau').x - tr.x).toFixed(2)} m`);

  // Wirkung: der Hebelarm bleibt, die Kraft halbiert sich, also halbiert sich
  // auch ihr Torsionsanteil.
  // DIESELBE EINWIRKUNGSKLASSE WIE OBEN. `trasse` traegt EK2, und die
  // Sollwerte werden daraus gerechnet; der Eingabestand muss ihr folgen.
  // Solange der Startwert ebenfalls EK2 war, fiel das nicht auf.
  const e0 = basis({ L: 20, torsionModell: 'verteilt', windKlasse: '1.1',
                     gammaG: 1.35, gammaQ: 1.5, psi0: 0.5 });
  const Tx = (extra) => rechne({ ...e0, anbauteile: bau(extra) }).extrem.TxMax;
  const ohne = { windAufTraeger: false };
  const ev = Math.abs(zAufbau)
    + rechne({ ...e0, anbauteile: bau(ohne) }).modell.h / 2;
  /*
   * WIRKUNG AUF DIE TORSION - und warum sie so einfach bleibt.
   *
   * Man koennte meinen, die beiden Anteile haetten verschiedene Stationen:
   * der Auslegerwind greift 1.2 m ausserhalb an, der zurueckgesetzte Anteil
   * am Anschluss. Fuer das JOCH ist das aber dieselbe Stelle - der Kragarm
   * traegt seine Last an seiner Wurzel ein (siehe Abschnitt 32). Der
   * Verteilungsfaktor ist deshalb fuer beide gleich, und es bleibt bei der
   * halben Kraft am selben Hebelarm.
   *
   * Der Faktor ist der groessere der beiden Auflageranteile: ein Moment T bei
   * x teilt sich in T(L-x)/L und Tx/L.
   */
  const L0 = 20;
  const anteilT = (x) => Math.max(x, L0 - x) / L0;
  pruef('Torsion sinkt um die halbe Kraft am selben Hebelarm',
        Tx(ohne) - Tx({ windAufTraeger: true, windAnteil: 50 }),
        1.5 * ev * (wAufbau / 2) * anteilT(tr.x), 1e-3, 'kNm');
  pruef('Ohne Schalter unverändert', Tx({ ...ohne, windAnteil: 50 }), Tx(ohne),
        1e-12, 'kNm');
}

titel('23  Vorzeichenrichtige Überlagerung je Blechebene');
// Der Schubfluss läuft um: er addiert sich auf einer Ebene und zieht auf der
// gegenüberliegenden ab. Die Vorzeichen sind an einem PyNite-Stabmodell
// festgelegt worden (kalibrieren.mjs) - hier stehen die Eigenschaften,
// die daraus folgen und die kein Umbau verletzen darf.
{
  const L = 10, x0 = 5;
  // Wind in y, UNTERHALB der Jochachse angreifend - eine Hängestütze.
  const teilUnten = teil({ id: 'W', x: x0, befestigung: 'durchgehend',
    lasten: [block({ einwirkung: 'WindY', x: 0, z: -1.35, Fy: 3 })] });
  const e0 = { ...basis(), typ: 'J70', L, torsionModell: 'verteilt',
               anbauteile: [teilUnten] };
  const huelle = rechne({ ...e0, ebenenUeberlagerung: 'huellkurve' });
  const vorz = rechne({ ...e0, ebenenUeberlagerung: 'vorzeichen' });

  const eb = (r, i, id) => r.knoten[i].ebenen.find((e) => e.id === id);
  const mitte = Math.round(huelle.knoten.length / 2);

  // 1 · DIE MASSGEBENDE EBENE ÄNDERT SICH NICHT.
  // Auf der Ebene, wo Querkraft und Schubfluss gleichsinnig laufen, ist
  // |V + T| = |V| + T - genau die Hüllkurve. Vorzeichenrichtig zu rechnen
  // entlastet also nur die andere Ebene und senkt nie den Nachweis.
  pruef('Höchstes η bleibt gleich', vorz.max.eta.eta, huelle.max.eta.eta, 1e-12);
  wahr('Keine Ebene wird ungünstiger als die Hüllkurve',
       vorz.knoten.every((k, i) => k.ebenen.every((e) => e.eta === null
         || e.eta <= (eb(huelle, i, e.id).eta ?? 0) + 1e-9)));
  wahr('An jeder Station erreicht EINE Ebene je Richtung die Hüllkurve',
       vorz.knoten.every((k, i) => ['vertikal', 'horizontal'].every((art) => {
         const paar = k.ebenen.filter((e) => e.art === art && e.eta !== null);
         if (!paar.length) return true;
         const h = eb(huelle, i, paar[0].id).eta;
         return paar.some((e) => Math.abs(e.eta - h) < 1e-9);
       })));

  // 2 · DIE LAST HÄNGT UNTER DEM JOCH, ALSO IST DAS UNTERE BLECH DRAN.
  // Und zwar auf BEIDEN Jochhälften: Querkraft und Torsion wechseln am
  // Angriff gemeinsam das Vorzeichen, ihr Verhältnis bleibt.
  const untenDran = (i) => (eb(vorz, i, 'H_U')?.V_Ebene ?? 0)
                         > (eb(vorz, i, 'H_O')?.V_Ebene ?? 0) + 1e-9;
  wahr('Unteres Blech massgebend, links wie rechts der Last',
       untenDran(2) && untenDran(vorz.knoten.length - 3));
  wahr('Ober- und Unterblech unterscheiden sich deutlich',
       eb(vorz, 2, 'H_U').V_Ebene > 2 * eb(vorz, 2, 'H_O').V_Ebene);
  wahr('In der Hüllkurve sind sie gleich',
       Math.abs(eb(huelle, 2, 'H_U').V_Ebene - eb(huelle, 2, 'H_O').V_Ebene) < 1e-12);

  // 3 · SYMMETRIE. Eine Last in Jochmitte muss ein spiegelbildliches
  // Ergebnis geben - der frühere Fehler (Querkraft als Betrag, Torsion mit
  // Vorzeichen) liess die massgebende Ebene am Anbauteil umspringen.
  const n = vorz.knoten.length;
  wahr('Spiegelbildlich um die Jochmitte',
       [1, 2, 3].every((i) => ['H_O', 'H_U'].every((id) =>
         Math.abs((eb(vorz, i, id)?.V_Ebene ?? 0)
                - (eb(vorz, n - 1 - i, id)?.V_Ebene ?? 0)) < 1e-9)));

  // 4 · OHNE DREHSINN KEIN VORZEICHEN.
  const hk = rechne({ ...e0, torsionModell: 'huellkurve',
                      ebenenUeberlagerung: 'vorzeichen' });
  const hk0 = rechne({ ...e0, torsionModell: 'huellkurve',
                      ebenenUeberlagerung: 'huellkurve' });
  wahr('Torsions-Hüllkurve fällt auf die Ebenen-Hüllkurve zurück',
       hk.knoten.every((k, i) => k.ebenen.every((e) => e.eta === null
         || Math.abs(e.eta - eb(hk0, i, e.id).eta) < 1e-12)));

  // 5 · Ohne Torsion sind alle vier Ebenen wie bisher.
  const ohne = { ...basis(), typ: 'J70', L, torsionModell: 'verteilt' };
  const a = rechne({ ...ohne, ebenenUeberlagerung: 'vorzeichen' });
  const b = rechne({ ...ohne, ebenenUeberlagerung: 'huellkurve' });
  wahr('Ohne Torsion kein Unterschied',
       a.knoten.every((k, i) => k.ebenen.every((e) => e.eta === null
         || Math.abs(e.eta - eb(b, i, e.id).eta) < 1e-12)));
  void mitte;
}

// ===========================================================================
titel('24  Ungleiche Gurte: Hebelarm, Aufteilung, zwei Maste');
{
  const { hebelarme } = await import(J('core.vierendeel.js'));
  const { gurtanteile, GURT_DAEMPFUNG } = await import(J('core.querschnitt.js'));
  const { mastSteifigkeit, drehfedern } = await import(J('core.auflager.js'));

  // --- 1 · Einbaulage des stehenden Schenkels -------------------------------
  // Signaljoch: jbb 512 mm, L 100x100x10 (zs_V = 2.82 cm). Zeigt der Schenkel
  // nach aussen, ist b = jbb - 2·zs; nach innen b = (jbb - 2·ja) + 2·zs.
  const pOG = getProfil('L 100x100x10'), pUG = getProfil('L 80x80x8');
  const phys = { jd: 600, jbbOG: 512, jbbUG: 491 };
  const innen = hebelarme(phys, pOG, pUG, { og: { st: -1 }, ug: { st: -1 } });
  const aussen = hebelarme(phys, pOG, pUG, { og: { st: +1 }, ug: { st: +1 } });
  pruef('b Obergurt, Schenkel innen', innen.bOG, (512 - 200 + 2 * 28.2) / 1000, 1e-9, 'm');
  pruef('b Obergurt, Schenkel aussen', aussen.bOG, (512 - 2 * 28.2) / 1000, 1e-9, 'm');
  wahr('Schenkel aussen gibt den grösseren Hebelarm', aussen.bOG > innen.bOG);
  pruef('h hängt nicht von der Querlage ab',
        aussen.varianten.schwerpunkt.hT, innen.varianten.schwerpunkt.hT, 1e-12, 'm');
  // Gegen das AxisVM-Modell: Schwerachsen ±228 mm -> b = 456 mm
  pruef('b trifft das Stabmodell', aussen.bOG, 0.4556, 1e-3, 'm');
  pruef('h trifft das Stabmodell', aussen.varianten.schwerpunkt.hT, 0.5493, 1e-3, 'm');
  wahr('Ohne Angabe gilt die Regelbauart (Schenkel innen)',
       Math.abs(hebelarme(phys, pOG, pUG).bOG - innen.bOG) < 1e-12);

  // --- 2 · Aufteilung auf die Gurte einer Vertikalebene ---------------------
  const mUngleich = { profOG: pOG, profUG: pUG };
  const gl = gurtanteile(mUngleich, 'gleich');
  const st = gurtanteile(mUngleich, 'steifigkeit');
  const hu = gurtanteile(mUngleich, 'huellend');
  pruef('hälftig: beide 0.5', gl.OG, 0.5, 1e-12);
  pruef('Steifigkeitsanteile ergänzen sich zu eins', st.OG + st.UG, 1, 1e-12);
  wahr('Der steifere Gurt bekommt mehr', st.OG > st.UG);
  // I = i_y^2 * A: L100x10 -> 3.04^2*19.2 = 177.4 cm4, L80x8 -> 2.42^2*12.3 = 72.0
  pruef('Anteil Obergurt nach I', st.OG, (3.04 ** 2 * 19.2)
        / (3.04 ** 2 * 19.2 + 2.42 ** 2 * 12.3), 1e-9);
  wahr('einhüllend nimmt je Gurt den ungünstigeren Anteil',
       hu.OG === st.OG && hu.UG === 0.5);
  // GEMESSEN: gedämpfte Steifigkeitsaufteilung, an PyNite kalibriert.
  const ge = gurtanteile(mUngleich, 'gemessen');
  pruef('gemessen: Anteile ergänzen sich zu eins', ge.OG + ge.UG, 1, 1e-12);
  wahr('gemessen liegt zwischen hälftig und I-Anteil',
       ge.OG > 0.5 && ge.OG < st.OG);
  // Nachgemessen am 29. August ueber das ganze Sortiment (kalibrieren.mjs,
  // 80 Laeufe): k = 0.45 aus der DIFFERENZ gegen denselben Traeger mit
  // gleichen Gurten. Beim Verhaeltnis 2.46 ergibt das 0.5 + 0.45*0.211.
  pruef('gemessen trifft die Kalibrierung', ge.OG, 0.5 + 0.45 * (st.OG - 0.5), 1e-9);
  // k WANDERT NICHT: gemessen 0.436 bei I_OG/I_UG = 2.04 gegen 0.465 bei
  // 4.15. Die angesetzte Zahl muss zwischen den beiden liegen, sonst ist sie
  // nicht mehr das Mittel der Messung.
  wahr('k liegt zwischen den gemessenen Randwerten',
       GURT_DAEMPFUNG >= 0.436 && GURT_DAEMPFUNG <= 0.465);
  wahr('einhüllend ist nie kleiner als hälftig', hu.OG >= 0.5 && hu.UG >= 0.5);
  const gleich = gurtanteile({ profOG: pOG, profUG: pOG }, 'steifigkeit');
  pruef('Gleiche Gurte: wieder hälftig', gleich.OG, 0.5, 1e-12);

  // Wirkung im Nachweis: nur bei ungleichen Gurten, und nur nach oben.
  const j130 = T.getTragjoch('J130');
  const e0 = { ...basis(), ...typUebernehmen({ ...standardwerte() }, j130),
               typ: 'J130', L: 27, schneeAktiv: false, anbauteile: [],
               endbedingung: 'gelenkig', torsionModell: 'huellkurve' };
  const a = rechne({ ...e0, gurtaufteilung: 'gleich' });
  const b = rechne({ ...e0, gurtaufteilung: 'huellend' });
  wahr('J130 hat ungleiche Gurte', a.modell.profOG.name !== a.modell.profUG.name);
  wahr('Einhüllend ist an keiner Station günstiger',
       a.knoten.every((k, i) => k.ecken.every((e, j) =>
         b.knoten[i].ecken[j].sig_v >= e.sig_v - 1e-9)));
  wahr('Der steifere Obergurt wird ungünstiger',
       b.max.etaOG.og.eta > a.max.etaOG.og.eta);
  // Die Blechquerkraft bleibt unberührt - die Anteile ergänzen sich zu eins.
  wahr('Blechquerkraft unverändert',
       a.knoten.every((k, i) => k.ebenen.every((e, j) => e.V == null
         || Math.abs(e.V - b.knoten[i].ebenen[j].V) < 1e-9)));

  // --- 3 · Zwei verschiedene Maste ------------------------------------------
  const mastEin = { endbedingung: 'mast', mastProfil: 'HEB 260', mastH: 7.8,
                    mastSteg: 'jochachse', mastAnschluss: 'kragarm' };
  const f1 = drehfedern(mastEin);
  pruef('Ein Mast: beide Enden gleich', f1.cA, f1.cB, 1e-12, 'kNm/rad');
  const f2 = drehfedern({ ...mastEin, mastZwei: true,
                          mastProfilB: 'HEM 240', mastHB: 12.0 });
  wahr('Zwei Maste: die Enden unterscheiden sich', Math.abs(f2.cA - f2.cB) > 1);
  pruef('Ende A unverändert', f2.cA, f1.cA, 1e-12, 'kNm/rad');
  const mB = mastSteifigkeit({ ...mastEin, mastZwei: true,
                               mastProfilB: 'HEM 240', mastHB: 12.0 }, 'B');
  pruef('Ende B: Rahmenfeder des zweiten Mastes', f2.cB,
        MAST_UNVERSCHIEBLICH * (210e6 * mB.I_cm4 * 1e-8) / 12.0,
        1e-9, 'kNm/rad');
  wahr('Ohne Schalter bleibt der zweite Mast wirkungslos',
       Math.abs(drehfedern({ ...mastEin, mastProfilB: 'HEM 240', mastHB: 12.0 }).cB
                - f1.cB) < 1e-12);
}

// ===========================================================================
titel('25  Winkelspannung an den Querschnittspunkten');
// Die Querschnittswerte werden aus den Tabellenwerten hergeleitet - I_yz steht
// in keiner Profiltabelle dieses Werkzeugs. Gegengeprüft wird an den Werten,
// die AxisVM für dieselben Profile ausweist.
{
  const { winkelwerte, randspannung, wirksamesW } = await import(J('core.winkel.js'));
  const AX = {
    'L 100x100x10': { A: 1915.52, Iy: 1766604, Iyz: -1036581,
                      I1: 2803186, I2: 730023 },
    'L 80x80x8':    { A: 1226.78, Iy: 722397.8, Iyz: -423612.4,
                      I1: 1146010, I2: 298785.4 },
  };
  Object.entries(AX).forEach(([name, a]) => {
    const w = winkelwerte(getProfil(name));
    pruef(`${name}: A`, w.A, a.A, 0.01, 'mm2');
    pruef(`${name}: I_y`, w.Iy, a.Iy, 0.01, 'mm4');
    // I_yz folgt aus I_2 = i_min²·A und der Invarianz der Spur.
    pruef(`${name}: I_yz (hergeleitet)`, w.Iyz, a.Iyz, 0.01, 'mm4');
    pruef(`${name}: I_1`, w.I1, a.I1, 0.01, 'mm4');
    pruef(`${name}: I_2`, w.I2, a.I2, 0.01, 'mm4');
    wahr(`${name}: I_1 + I_2 = I_y + I_z`,
         Math.abs(w.I1 + w.I2 - (w.Iy + w.Iz)) < 1e-6);
    wahr(`${name}: sechs Eckpunkte`, w.punkte.length === 6);
  });

  // Schiefe Biegung: die Randspannung ist grösser als M/W_schenkelparallel.
  const p100 = getProfil('L 100x100x10');
  const w100 = winkelwerte(p100);
  const Weff = wirksamesW(w100);
  wahr('Wirksames W ist kleiner als das schenkelparallele',
       Weff < p100.Wy * 1000);
  pruef('Faktor gegenüber W schenkelparallel', (p100.Wy * 1000) / Weff,
        1.298, 5e-3);

  // Reine Normalkraft: das Modell darf sie nicht verändern.
  pruef('Nur Normalkraft: σ = N/A', randspannung(w100, 100, 0, 0).sig,
        (100 * 1000) / w100.A, 1e-9, 'N/mm2');
  // Vorzeichen der Momente ohne Wirkung - ausgewertet wird die Hüllkurve.
  pruef('Vorzeichen von M_y ohne Wirkung', randspannung(w100, 0, -3, 0).sig,
        randspannung(w100, 0, 3, 0).sig, 1e-12, 'N/mm2');
  wahr('Zwei Momente sind ungünstiger als eines',
       randspannung(w100, 0, 3, 2).sig > randspannung(w100, 0, 3, 0).sig);

  // EINE Achse allein: die punktweise Ermittlung ist immer ungünstiger.
  // Bei ZWEI Momenten gilt das nicht zwingend - die beiden Randpunkte fallen
  // dann nicht zusammen, und die Summe der Einzelmaxima kann grösser sein als
  // das wirkliche Maximum. Genau deshalb ist die Summe über W keine sichere
  // obere Schranke, sondern nur eine andere Näherung.
  [1, 5, 20].forEach((M) => {
    const punkt = randspannung(w100, 0, M, 0).sig;
    const ueberW = (M * 1e6) / (p100.Wy * 1000);
    wahr(`M_y = ${M} kNm: punktweise ungünstiger`, punkt > ueberW * 1.2);
  });

  // Im Rechenkern: Vorgabe bleibt das schenkelparallele W.
  const j130 = T.getTragjoch('J130');
    // EK2 AUSDRUECKLICH. Die Aussage weiter unten, dass sich die beiden
  // Spannungsmodelle mit M_z um mehr als zwei Prozent unterscheiden, haengt
  // an der Groesse des Windmoments: gemessen 3.05 % unter EK2, aber nur
  // 0.45 % unter EK1. Der Abschnitt prueft das Spannungsmodell, nicht die
  // Einwirkungsklasse; also wird sie festgehalten. Solange der Startwert
  // ebenfalls EK2 war, fiel das nicht auf.
  const e0 = { ...basis(), ...typUebernehmen({ ...standardwerte() }, j130),
               typ: 'J130', L: 27, schneeAktiv: false, anbauteile: [],
               windKlasse: '1.1',
               endbedingung: 'gelenkig', torsionModell: 'huellkurve' };
  const a = rechne(e0);
  const b = rechne({ ...e0, spannungsmodell: 'punkte' });
  wahr('Vorgabe ist das schenkelparallele W',
       a.knoten[0].ecken[0].spannungsmodell === 'schenkel');
  // Der Hauptachsenfaktor zeigt sich nur bei REINER schenkelparalleler
  // Biegung. Kommt M_z dazu, ist die Summe der Beträge im Schenkelmodell eine
  // obere Schranke, die kein einzelner Querschnittspunkt erreicht - dann kann
  // die punktweise Auswertung sogar TIEFER liegen. Geprüft wird deshalb ein
  // rein vertikaler Lastfall.
  const nurG = { G: 1, WindX: 0, WindY: 0, Schnee: 0, Leiterzug: 0 };
  const av = rechne({ ...e0, beiwerteFest: nurG });
  const bv = rechne({ ...e0, beiwerteFest: nurG, spannungsmodell: 'punkte' });
  const iBieg = av.knoten.reduce(
    (best, k, i) => (Math.abs(k.og.sig_My) > Math.abs(av.knoten[best].og.sig_My) ? i : best), 0);
  wahr('Ohne M_z bleibt reine schenkelparallele Biegung',
       Math.abs(av.knoten[iBieg].og.sig_Mz) < 1e-9);
  const faktor = bv.knoten[iBieg].og.sig_v / av.knoten[iBieg].og.sig_v;
  wahr('Punktweise ist rund 30 % ungünstiger', faktor > 1.2 && faktor < 1.45,
       `Faktor ${faktor.toFixed(3)}`);
  // Mit M_z darf es auch andersherum ausgehen - das ist keine Unstimmigkeit,
  // sondern die Folge der Betragsaddition im Schenkelmodell.
  wahr('Mit M_z unterscheiden sich die Modelle ebenfalls',
       Math.abs(b.knoten[iBieg].og.sig_v / a.knoten[iBieg].og.sig_v - 1) > 0.02);
  wahr('Beide Modelle rechnen durch',
       Number.isFinite(a.max.etaGesamt) && Number.isFinite(b.max.etaGesamt));
}

// ===========================================================================
titel('26  Wind auf den Mast verdreht das Jochende');
// Der Wind in der Jochachse biegt den Mast. Sein Kopf verdreht sich, und weil
// das Jochende dort angeschlossen ist, wird ihm die Verdrehung AUFGEZWUNGEN.
// Ohne diesen Anteil fehlte dem Lastfall Wind in Jochachse am nachgerechneten
// Signaljoch rund die Hälfte der Einwirkung.
{
  const { mastKoepfe, mastSteifigkeit, auflagermomente, E_STAHL: E } =
    await import(J('core.auflager.js'));
  const { hinweise } = await import(J('core.checks.js'));

  // Der Mastwind ist der VERSCHIEBLICHE Fall: beide Köpfe wollen in dieselbe
  // Richtung. Deshalb hier die Kragmastfeder (core.auflager.js).
  const mast = mastSteifigkeit({ mastProfil: 'HEB 260', mastH: 9, mastSteg: 'jochachse',
                                 mastAnschluss: 'kragarm' }, 'A', true);
  const k = mastKoepfe(mast, mast, { wMast: 0.31 }).A;
  // Kragmast unter Gleichlast: Kopfverdrehung w·H³/(6·E·I)
  pruef('Kopfverdrehung des Kragmastes', k.theta0,
        (0.31 * 9 ** 3) / (6 * E * mast.I), 1e-12);
  // Hält das Joch den Kopf ganz fest, gibt der Mast M = w·H²/6 ab - das ist
  // die Standardlösung für den am Kopf drehfest gehaltenen Kragmast.
  pruef('Eingeleitetes Moment bei festgehaltenem Kopf', k.M0,
        (0.31 * 9 * 9) / 6, 1e-9);
  // Zwei GLEICHE Maste unter demselben Wind verschieben sich gleich - dann
  // geht keine Kraft durch das Joch, und es bleibt beim reinen Windanteil.
  pruef('Gleiche Maste: keine Längskraft', mastKoepfe(mast, mast, { wMast: 0.31 }).A.P,
        0, 1e-9, 'kN');
  wahr('Ohne Wind und ohne Längskraft keine Verdrehung',
       mastKoepfe(mast, mast, {}).A.theta0 === 0);
  wahr('Ohne Mast keine Verdrehung', mastKoepfe(null, null, { wMast: 0.31 }).A.theta0 === 0);

  // --- DIE LÄNGSKRAFT DES JOCHS ---------------------------------------------
  // Eine Anbaulast in Jochachse laeuft im Ersatzbalken als Normalkraft ins
  // Auflager - in Wirklichkeit greift sie am MASTKOPF an, biegt den Mast und
  // verdreht ihn. Am Signaljoch ist dieser Anteil sechsmal so gross wie der
  // Mastwind.
  {
    const mA = mastSteifigkeit({ mastProfil: 'HEB 260', mastH: 7.8,
      mastSteg: 'jochachse', mastAnschluss: 'kragarm' }, 'A', true);
    const mB = mastSteifigkeit({ mastProfil: 'HEM 240', mastH: 12.0,
      mastSteg: 'jochachse', mastAnschluss: 'kragarm' }, 'B', true);
    const r = mastKoepfe(mA, mB, { wMast: 0.33, wMastB: 0.31, Fx: 3 * 2.14 });
    const kA = (3 * E * mA.I) / mA.H ** 3, kB = (3 * E * mB.I) / mB.H ** 3;
    // Die Kraft teilt sich nach den KOPFSTEIFIGKEITEN, verschoben um den
    // Mastwind: der weichere Mast wird vom steiferen gestuetzt.
    pruef('Kraefte im Gleichgewicht', r.A.P + r.B.P, 3 * 2.14, 1e-9, 'kN');
    // OHNE Mastwind teilt sie sich genau nach der Kopfsteifigkeit auf.
    const nurKraft = mastKoepfe(mA, mB, { Fx: 3 * 2.14 });
    pruef('Ohne Mastwind: Aufteilung genau nach der Kopfsteifigkeit',
          nurKraft.A.P / (nurKraft.A.P + nurKraft.B.P), kA / (kA + kB), 1e-9, '–');
    // MIT Mastwind verschiebt sie sich: der weichere Mast wird gestuetzt.
    wahr('Der Mastwind verschiebt die Aufteilung zum steiferen Mast',
         r.A.P / (r.A.P + r.B.P) > nurKraft.A.P / (nurKraft.A.P + nurKraft.B.P));
    // Gegen den PyNite-Rahmen mit beiden ausmodellierten Masten.
    pruef('Kopfkraft A trifft den Rahmen', r.A.P, 5.106, 0.02, 'kN');
    pruef('Kopfkraft B trifft den Rahmen', r.B.P, 1.315, 0.02, 'kN');
    pruef('Kopfweg ist bei beiden derselbe',
          r.A.P / kA + (0.33 * mA.H ** 4) / (8 * E * mA.I), r.delta, 1e-9, 'm');
    pruef('auch vom anderen Ende gerechnet',
          r.B.P / kB + (0.31 * mB.H ** 4) / (8 * E * mB.I), r.delta, 1e-9, 'm');
    // theta_P = P·H²/(2EI)
    pruef('Verdrehung aus der Kopfkraft', r.A.thetaKraft,
          (r.A.P * mA.H ** 2) / (2 * E * mA.I), 1e-12);
    wahr('Sie ist deutlich groesser als die aus dem Mastwind',
         r.A.thetaKraft > 5 * r.A.thetaWind,
         `${(1000 * r.A.thetaKraft).toFixed(2)} gegen `
         + `${(1000 * r.A.thetaWind).toFixed(2)} mrad`);
    // Und daraus das Moment, gegen PyNite 21.5 / -16.3 kNm.
    wahr('Das eingeleitete Moment liegt beim Rahmenwert',
         Math.abs(r.A.M0 - 21.5) < 2.5 && Math.abs(r.B.M0 - 16.3) < 2.5,
         `M0 = ${r.A.M0.toFixed(1)} / ${r.B.M0.toFixed(1)} kNm`);
  }

  // Durchlaufender Mast: steifere Feder, gleiche Kopfverdrehung -> grösseres
  // Moment. Bewusst auf der sicheren Seite (siehe core.auflager.js).
  const durch = mastSteifigkeit({ mastProfil: 'HEB 260', mastH: 9, mastSteg: 'jochachse',
                                  mastAnschluss: 'durchlaufend' }, 'A', true);
  pruef('Durchlaufend: Moment im Verhältnis der Feder',
        mastKoepfe(durch, durch, { wMast: 0.31 }).A.M0 / k.M0, 1.45, 1e-9);

  // --- Wirkung im Drehwinkelverfahren ---------------------------------------
  const g = { L: 20, qd: 1, P: [], M: [], EI: 1e5, cA: 5000, cB: 5000 };
  const ohne = auflagermomente(g);
  const mit = auflagermomente({ ...g, theta0A: 1e-3, theta0B: 1e-3 });
  pruef('Ohne Kopfverdrehung unverändert',
        auflagermomente({ ...g, theta0A: 0, theta0B: 0 }).MA, ohne.MA, 1e-12);
  // Gleichsinnige Verdrehung beider Enden ist eine ANTIMETRISCHE Einwirkung:
  // das Joch wird in Gegenkrümmung gebogen, die Summe der Stützmomente bleibt.
  pruef('Gleichsinnige Verdrehung ist antimetrisch',
        mit.MA + mit.MB, ohne.MA + ohne.MB, 1e-9);
  wahr('Ein Ende wird entlastet, das andere belastet',
       mit.MA < ohne.MA && mit.MB > ohne.MB);
  // Starres Joch: der Kopf wird ganz festgehalten, das volle c·θ₀ kommt an.
  const starr = auflagermomente({ L: 20, qd: 0, P: [], M: [], EI: 1e12,
                                  cA: 5000, cB: 5000, theta0A: 1e-3, theta0B: 1e-3 });
  pruef('Starres Joch nimmt das volle c·θ₀ auf', Math.abs(starr.MA), 5, 1e-6);

  // --- Wirkung im Nachweis --------------------------------------------------
  const j90 = T.getTragjoch('J90');
  const e0 = { ...basis(), ...typUebernehmen({ ...standardwerte() }, j90),
               typ: 'J90', L: 15.5, schneeAktiv: false, anbauteile: [],
               endbedingung: 'mast', mastProfil: 'HEB 260', mastH: 9,
               mastSteg: 'jochachse', mastAnschluss: 'durchlaufend',
               wMastAusTabelle: false, wMast: 0.4, schraubenGrenze: false,
               // Startwert ist AUS (Weisung): sobald der Mast im Stabmodell
               // steht, traegt er den Wind selbst, und die aufgezwungene
               // Verdrehung waere ein zweiter Ansatz derselben Last. Wer sie
               // prueft, schaltet sie ausdruecklich ein.
               mastWindAufJoch: true,
               torsionModell: 'huellkurve',
               beiwerteFest: { G: 0, WindX: 1, WindY: 0, Schnee: 0, Leiterzug: 0 } };
  const aus = rechne({ ...e0, mastWindAufJoch: false });
  const an = rechne(e0);
  wahr('Mastwind hebt den Lastfall Wind in Jochachse',
       an.max.etaGesamt > aus.max.etaGesamt);
  wahr('Der Mastwind steht im Modell', an.modell.mastKopf !== null
       && aus.modell.mastKopf === null);
  // Nur der Lastfall mit Wind in Jochachse trägt ihn.
  const ohneBeiwert = { ...e0,
    beiwerteFest: { G: 1, WindX: 0, WindY: 0, Schnee: 0, Leiterzug: 0 } };
  pruef('Ohne Beiwert WindX keine Verdrehung',
        rechne(ohneBeiwert).modell.theta0A ?? 0, 0, 1e-12);
  /*
   * Ohne Masten im Modell gibt es nichts zu verdrehen. Seit dem 28. August
   * ist das eine EIGENE Angabe: `mastVorhanden`. Die Endbedingung sagt nur
   * noch, woher die Drehfeder kommt - sie nimmt den Masten nicht mehr mit.
   */
  const manuell = rechne({ ...e0, endbedingung: 'manuell', cPhi: 6000,
                           mastVorhanden: false });
  wahr('Ohne Mast kein Mastwind', manuell.modell.mastKopf === null);

  // --- WIND IN GLEISRICHTUNG WIRKT NICHT AUF DAS JOCH -----------------------
  // Er verschiebt die Mastköpfe (im Grundriss ist das Joch statisch bestimmt
  // gelagert - daraus folgt nichts) und verdreht sie um die Jochachse. Der
  // zweite Anteil wäre bei UNGLEICHEN Masten eine Torsion über die ganze
  // Jochlänge. Er ist bewusst NICHT angesetzt: hergeleitet, nicht geeicht, und
  // gegen das eine verfügbare FEM-Modell verschlechterte er die
  // Übereinstimmung erheblich (Gurte unter Wind quer von +52 auf +89 %).
  const zwei = { ...e0, mastZwei: true, mastProfilB: 'HEM 240', mastHB: 12.0,
                 mastStegB: 'jochachse',
                 beiwerteFest: { G: 0, WindX: 0, WindY: 1, Schnee: 0, Leiterzug: 0 } };
  const rz = rechne(zwei);
  const re = rechne({ ...zwei, mastZwei: false });
  wahr('Ungleiche Maste erzeugen unter Wind y keine Torsion',
       rz.knoten.every((k) => Math.abs(k.Tx) < 1e-12));
  wahr('Gleiche Maste ebenso wenig',
       re.knoten.every((k) => Math.abs(k.Tx) < 1e-12));
  const SCH = await import(J('ui.schema.js'));
  wahr('Es gibt keinen Eingabewert für den Mastwind in Gleisrichtung',
       !SCH.FELDER.some((f) => f.key === 'wMastQuer'));
  const hz = hinweise(rz.modell).join(' | ');
  wahr('Der Hinweis sagt, dass nur der Wind in Jochachse erfasst ist',
       hz.includes('Jochachse') && hz.includes('nicht angesetzt'), hz.slice(0, 80));

  // --- BEIDE WINDRICHTUNGEN, wie bei den Einwirkungen auf das Joch ----------
  // Der Wind bläst in + und in −. Beide Anteile hängen am VORZEICHENBEHAFTETEN
  // Beiwert des Lastfalls und kehren mit ihm um; die Hüllkurve über die
  // Lastfälle deckt damit beide Enden und beide Drehsinne ab.
  const { standardLastfaelle } = await import(J('core.lasten.js'));
  const bd = { ...e0, mastZwei: true, mastProfilB: 'HEM 240', mastHB: 12.0,
               mastStegB: 'jochachse', beiwerteFest: null };
  const lf = Object.fromEntries(standardLastfaelle(bd).filter((l) => l.nachweis)
    .map((l) => [l.key, rechne({ ...bd, beiwerteFest: l.beiwerte }).modell]));
  wahr('Wind ±x kehrt die Auflagerdrehung um',
       Math.sign(lf.windXp.theta0A) === -Math.sign(lf.windXm.theta0A)
       && Math.abs(lf.windXp.theta0A) > 0);
  // Antimetrisch: was das eine Ende im einen Lastfall bekommt, bekommt das
  // andere im anderen. Ohne beide Vorzeichen bliebe ein Ende ungeprüft.
  wahr('Jedes Ende wird in einem der beiden Lastfälle ungünstig',
       Math.max(lf.windXp.MA, lf.windXm.MA) > Math.min(lf.windXp.MA, lf.windXm.MA)
       && Math.max(lf.windXp.MB, lf.windXm.MB) > Math.min(lf.windXp.MB, lf.windXm.MB));
}

// ===========================================================================
titel('26b Der Mast ist Auflager UND Bauteil');
/*
 * BIS ZUM 28. AUGUST hiess dieser Abschnitt «Auflager, nicht Bauteil»: der
 * Mast bestimmte die Drehfeder und den Mastwind, seine eigene Ausnutzung
 * gehoerte «in ein Rahmenmodell» und wurde gar nicht erst ausgewiesen.
 *
 * Der Auftraggeber hat auf Nachfrage anders entschieden - Querschnittsnachweis
 * aus den Schnittgroessen des Ersatzbalkens, jetzt. Was BLEIBT: die Feder,
 * der Mastwind auf das Jochende, und die Ausnutzung des JOCHS, die den
 * Masten nicht mitzaehlt. Beide Zahlen stehen nebeneinander, keine
 * verschluckt die andere.
 */
{
  const AUF = await import(J('core.auflager.js'));
  const { hinweise } = await import(J('core.checks.js'));
  const w = basis({ endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.5,
                    mastSteg: 'jochachse', mastAnschluss: 'kragarm',
                    wMastAusTabelle: false, wMast: 0.37 });
  const e = rechne(w);
  wahr('Der Mastnachweis steht im Ergebnis', e.mast != null
       && Number.isFinite(e.mast.eta), JSON.stringify(e.mast?.eta));
  wahr('Er sitzt NEBEN der Jochausnutzung, nicht darin',
       e.max.etaGesamt === Math.max(...e.knoten.map((k) => k.eta)));
  wahr('etaMitMast gibt es weiterhin nicht', e.max.etaMitMast === undefined);
  // Die Steifigkeitsrechnung des Auflagers bleibt, wo sie war.
  wahr('Der Nachweis steht nicht in core.auflager.js',
       AUF.mastNachweis === undefined);
  // Die Feder und der Mastwind bleiben - daran haengt das Joch.
  wahr('Die Drehfeder aus dem Mast steht weiterhin',
       e.modell.federn.mast != null && e.modell.federn.cA > 0);
  void hinweise;
}

// ===========================================================================
titel('27  Kragarme: das Auflager steht nicht immer am Gurtende');
// L ist die Länge der GURTE - daran hängt die Blecheinteilung. Die Auflager
// stehen dort, wo die Maste stehen. Am nachgerechneten Signaljoch waren das
// 0.33 und 0.735 m weiter innen: 5.3 % Stützweite, 11 % auf jedes Moment.
{
  const { feldmodell, schnittgroessen, auflagerkraefte } =
    await import(J('core.statics.js'));
  const { auflagermomente } = await import(J('core.auflager.js'));

  const leer = { qd: 1, wd: 0, P: [], H: [], T: [], M: [], Mz: [], N: [],
                 torsionModell: 'verteilt' };
  wahr('Ohne Kragarme wird kein Untermodell gebaut',
       feldmodell({ ...leer, L: 10 }) === null
       && feldmodell({ ...leer, L: 10, xA: 0, xB: 10 }) === null);

  // Einfeldträger 6 m mit je 2 m Kragarm, Gleichlast 1 kN/m, gelenkig.
  const m0 = { ...leer, L: 10, xA: 2, xB: 8 };
  const fm = feldmodell(m0);
  pruef('Stützweite', fm.Ls, 6, 1e-12);
  pruef('Kragarmmoment q·a²/2', fm.MkA, 2, 1e-12);
  pruef('Kragarmlast läuft ins Auflager', fm.RkragA, 2, 1e-12);

  const auf = auflagermomente({ L: fm.Ls, qd: 1, P: fm.feld.P, M: fm.feld.M,
                                EI: 1e5, cA: 0, cB: 0, MkA: fm.MkA, MkB: fm.MkB });
  pruef('Gelenkig: Stützmoment ist das Kragarmmoment', auf.MA, 2, 1e-9);
  const rk = auflagerkraefte({ L: fm.Ls, qd: 1, P: fm.feld.P, M: fm.feld.M,
                               MA: auf.MA, MB: auf.MB,
                               RkragA: fm.RkragA, RkragB: fm.RkragB });
  pruef('Auflagerkraft trägt die ganze Last', rk.RA + rk.RB, 10, 1e-9);
  Object.assign(fm.feld, { RA0: rk.RA0, MA: auf.MA, MB: auf.MB });
  const mm = { ...m0, feldmodell: fm, RA0: rk.RA0, MA: auf.MA, MB: auf.MB };
  const My = (x) => schnittgroessen(x, mm).My;
  pruef('Freies Ende momentenfrei', My(0), 0, 1e-12);
  pruef('Kragarm: −q·x²/2', My(1), -0.5, 1e-12);
  pruef('Am Auflager das Kragarmmoment', My(2), -2, 1e-9);
  pruef('Feldmitte q·Ls²/8 − M_k', My(5), 6 * 6 / 8 - 2, 1e-9);
  pruef('Symmetrisch am anderen Ende', My(9), My(1), 1e-9);
  wahr('Im Kragarm ist der Bereich vermerkt',
       schnittgroessen(1, mm).kragarm === 'links'
       && schnittgroessen(9, mm).kragarm === 'rechts');

  // --- im Werkzeug ----------------------------------------------------------
  const j90 = T.getTragjoch('J90');
  const e0 = { ...basis(), ...typUebernehmen({ ...standardwerte() }, j90),
               typ: 'J90', L: 15.5, schneeAktiv: false, anbauteile: [],
               endbedingung: 'gelenkig', torsionModell: 'huellkurve' };
  const ohne = rechne(e0);
  const mit = rechne({ ...e0, kragA: 0.5, kragB: 0.5 });
  pruef('Stützweite im Modell', mit.modell.stuetzweite, 14.5, 1e-12);
  wahr('Kragarme senken das Feldmoment',
       mit.extrem.MyMax < ohne.extrem.MyMax);
  // Die Blecheinteilung hängt an der GURTLÄNGE und darf sich nicht rühren.
  wahr('Blechstationen bleiben unverändert',
       mit.knoten.length === ohne.knoten.length
       && mit.knoten.every((k, i) => Math.abs(k.x - ohne.knoten[i].x) < 1e-12));
  let fehler = null;
  try { rechne({ ...e0, kragA: 8, kragB: 8 }); } catch (e) { fehler = e; }
  wahr('Zu lange Kragarme werden abgewiesen', fehler !== null);

  // --- Gegenprobe am Signaljoch ---------------------------------------------
  // Aus den Gurtkräften des AxisVM-Modells zurückgerechnet: Feldmoment
  // 21.18 kNm, Einspannmoment 10.05 kNm, Stützweite 18.935 m. Wird die Feder
  // auf das FELDMOMENT geeicht, muss das STÜTZMOMENT von selbst stimmen -
  // es ist nicht mitgefittet.
  const sig = { ...basis(), typ: 'frei', L: 20.0, a1: 0.75,
                jd: 600, jbbOG: 600, jbbUG: 560,
                profOG: 'L 100x100x10', profUG: 'L 80x80x8',
                blechQuelle: 'manuell', h2: 110, t2: 10, h1: 110, t1: 10,
                endblechWieZwischen: true, schneeAktiv: false, anbauteile: [],
                lastHerkunft: 'manuell', gkManuell: 0.6966, skManuell: 0,
                wkManuell: 0, gammaM0: 1.0, schraubenGrenze: false,
                endbedingung: 'manuell', cPhi: 9215,
                kragA: 0.33, kragB: 0.735,
                beiwerteFest: { G: 1, WindX: 0, WindY: 0, Schnee: 0, Leiterzug: 0 } };
  const rs = rechne(sig);
  pruef('Signaljoch: Stützweite', rs.modell.stuetzweite, 18.935, 1e-9);
  pruef('Signaljoch: Feldmoment wie AxisVM', rs.extrem.MyMax, 21.18, 0.05);
  pruef('Signaljoch: Stützmoment folgt von selbst', Math.abs(rs.modell.MA), 10.05, 0.15);

  // --- Die Zahlen müssen SICHTBAR sein --------------------------------------
  // Beim Nachbau eines geprüften FEM-Modells lagen die grössten Fehler in der
  // Eingabe: eine geschätzte Drehfeder um Faktor 3 daneben, die Stützweite um
  // 5 %. Beides sieht man dem Ergebnis nicht an, wenn es nirgends steht.
  const { hinweise } = await import(J('core.checks.js'));
  const hs = hinweise(rs.modell).join(' | ');
  wahr('Stützweite und Kragarme stehen im Klartext',
       hs.includes('18.935') && hs.includes('Kragarme'));
  wahr('Feder, Einspanngrad und Stützmoment stehen im Klartext',
       /c_φ = 9215/.test(hs) && /Einspanngrad/.test(hs) && /Stützmoment/.test(hs));
  const hOhne = hinweise(rechne({ ...sig, kragA: 0, kragB: 0 }).modell).join(' | ');
  wahr('Ohne Kragarme wird darauf hingewiesen',
       hOhne.includes('keine Kragarme'));
  const hMast = hinweise(rechne({ ...sig, endbedingung: 'mast',
      mastProfil: 'HEB 260', mastH: 7.8, mastSteg: 'jochachse',
      mastAnschluss: 'durchlaufend', wMastAusTabelle: false, wMast: 0.31,
      mastWindAufJoch: true,
      beiwerteFest: { G: 1, WindX: 1, WindY: 0, Schnee: 0, Leiterzug: 0 },
    }).modell).join(' | ');
  wahr('Der Rahmen und die gewählte Feder werden benannt',
       hMast.includes('verschiebt sich') || hMast.includes('VERSCHIEBT sich'));
  wahr('Die Verdrehung der Mastköpfe wird ausgewiesen',
       hMast.includes('Mastköpfe verdrehen sich')
       && hMast.includes('Wind auf den Mast')
       && hMast.includes('Längskraft des Jochs'));
  wahr('Die gewählte Gurtaufteilung steht im Klartext',
       hinweise(rechne({ ...sig, gurtaufteilung: 'gemessen' }).modell)
         .join(' | ').includes('gedämpft nach Steifigkeit'));
}

// ===========================================================================
titel('28  Knotenbereich: steif oder Achse zu Achse');
// Ob der Überlappungsbereich Gurt/Blech als steif gilt, ist eine ABSPRACHE.
// Beide Antworten sind rechenbar; die Vorgabe bleibt der steife Knoten.
{
  const { KNOTENBEREICHE } = await import(J('core.querschnitt.js'));
  const j90 = T.getTragjoch('J90');
  const e0 = { ...basis(), ...typUebernehmen({ ...standardwerte() }, j90),
               typ: 'J90', L: 15.5, schneeAktiv: false, anbauteile: [],
               endbedingung: 'gelenkig', torsionModell: 'huellkurve' };
  const a = rechne(e0);
  const b = rechne({ ...e0, knotenbereich: 'schwerachsen' });

  wahr('Nachweisgrundlage ist der steife Knotenbereich',
       a.modell.knotenbereich === 'anschnitt');
  wahr('Der Vergleichsmodus ist wählbar',
       KNOTENBEREICHE.length === 2
       && KNOTENBEREICHE.some((k) => k.key === 'schwerachsen'));
  // Ein damit gerechneter Bericht darf nicht als Nachweis durchgehen.
  const { hinweise: hw } = await import(J('core.checks.js'));
  wahr('Der Vergleichsmodus wird als kein vollständiger Nachweis ausgewiesen',
       hw(b.modell).join(' | ').includes('kein vollständiger Nachweis'));
  wahr('Der Nachweisfall trägt keinen solchen Hinweis',
       !hw(a.modell).join(' | ').includes('kein vollständiger Nachweis'));
  // Ohne steifen Bereich fällt die Abminderung weg: Faktor 1.
  pruef('Achse zu Achse: keine Abminderung im Gurt',
        b.knoten[3].anschnittMy, 1, 1e-12);
  wahr('Steif: der Gurt wird abgemindert', a.knoten[3].anschnittMy < 1);
  const bl = (r) => r.knoten[3].ebenen.find((x) => x.art === 'vertikal');
  pruef('Achse zu Achse: keine Abminderung im Blech',
        bl(b).abminderung, 1, 1e-12);
  wahr('Steif: das Blech wird abgemindert', bl(a).abminderung < 1);
  // Das KNOTENmoment ist dasselbe - nur die Stelle des Nachweises ändert sich.
  pruef('Das Knotenmoment bleibt unberührt',
        bl(b).M_Knoten, bl(a).M_Knoten, 1e-12, 'kNm');
  wahr('Achse zu Achse gibt durchweg grössere Werte',
       b.max.etaGesamt > a.max.etaGesamt);
  // Am nachgerechneten Signaljoch trug die Frage Faktor 1.3 bis 1.6 auf die
  // Blechmomente; hier reicht die Richtung als Prüfung.
  wahr('Der Unterschied ist erheblich, nicht kosmetisch',
       b.max.etaGesamt / a.max.etaGesamt > 1.05);
}

// ===========================================================================
titel('29  Endfeldzuschlag auf die Bindebleche');
// In den Endfeldern geht die Torsion über die Anschlussebenen in den Mast.
// Diese örtliche Einleitung führt der Ersatzbalken nicht; am Vergleichsmodell
// lag das Blechmoment aussen um Faktor 2.7 höher, nach innen abklingend.
{
  const { ENDFELD_ZUSCHLAG, ENDFELD_STATIONEN } = await import(J('core.querschnitt.js'));
  const j90 = T.getTragjoch('J90');
  const e0 = { ...basis(), ...typUebernehmen({ ...standardwerte() }, j90),
               typ: 'J90', L: 15.5, schneeAktiv: false, anbauteile: [],
               endbedingung: 'gelenkig', torsionModell: 'huellkurve' };
  const mit = rechne(e0);
  const ohne = rechne({ ...e0, endfeldZuschlag: 1 });

  // Nachgemessen am 31. August gegen ein Rahmenmodell mit demselben
  // Knotenmodell: 0.48 im Mittel, Spanne 0.41 bis 0.64. Unter 1 heisst,
  // dass der Ersatzbalken das Endfeld ueberschaetzt statt unterschaetzt -
  // die Huellkurve ueber alle vier Ebenen traegt dort rund Faktor zwei.
  pruef('Vorgabe ist der gerundete Messwert', ENDFELD_ZUSCHLAG, 0.50, 1e-12);
  wahr('… und liegt in der gemessenen Spanne',
       ENDFELD_ZUSCHLAG >= 0.41 && ENDFELD_ZUSCHLAG <= 0.65);
  pruef('Zwei Stationen je Ende', ENDFELD_STATIONEN, 2, 1e-12);

  const bl = (r, i) => r.knoten[i].ebenen.find((x) => x.art === 'vertikal');
  const n = mit.knoten.length;
  [0, 1, n - 2, n - 1].forEach((i) => {
    wahr(`Station ${i} liegt im Endfeld`, mit.knoten[i].imEndfeld === true);
  });
  const innen = Math.floor(n / 2);
  wahr('Feldmitte liegt nicht im Endfeld', mit.knoten[innen].imEndfeld === false);
  pruef('In Feldmitte bleibt alles, wie es war',
        bl(mit, innen).M, bl(ohne, innen).M, 1e-12, 'kNm');

  // OHNE TORSION KEIN ZUSCHLAG. Dieses Joch trägt keine exzentrischen
  // Anbaulasten; sein Torsionsanteil ist null, also ändert sich nichts.
  pruef('Ohne Torsion greift der Zuschlag nicht',
        bl(mit, 1).endfeldFaktor, 1, 1e-9);
  pruef('… und das Moment bleibt', bl(mit, 1).M, bl(ohne, 1).M, 1e-12, 'kNm');

  // MIT exzentrischer Anbaulast: dort wirkt er, und zwar anteilig.
  const mitTorsion = { ...e0, torsionModell: 'verteilt',
    anbauteile: [teil({ id: 'S', x: 7.75, befestigung: 'durchgehend',
      lasten: [block({ einwirkung: 'WindY', x: 0, z: -1.5, Fy: 3 })] })] };
  const t1 = rechne(mitTorsion);
  const t0 = rechne({ ...mitTorsion, endfeldZuschlag: 1 });
  const b1 = bl(t1, 1), b0 = bl(t0, 1);
  // Der Faktor weicht von 1 ab, sobald Torsion im Spiel ist - seit der
  // Kalibrierung nach UNTEN, weil k_E kleiner als 1 ist. Geprueft wird die
  // Abweichung, nicht ihre Richtung: die haengt am eingestellten k_E.
  wahr('Mit Torsion wird der Faktor wirksam',
       Math.abs(b1.endfeldFaktor - 1) > 0.05,
       `Faktor ${b1.endfeldFaktor.toFixed(3)}, Torsionsanteil `
       + `${(100 * b1.torsionsanteil).toFixed(0)} %`);
  // Solange nicht alles Torsion ist, bleibt er zwischen 1 und dem vollen
  // Wert - bei k_E unter 1 ist das die obere, nicht die untere Schranke.
  wahr('Er bleibt zwischen 1 und dem vollen Wert',
       b1.endfeldFaktor >= Math.min(1, ENDFELD_ZUSCHLAG) - 1e-9
       && b1.endfeldFaktor <= Math.max(1, ENDFELD_ZUSCHLAG) + 1e-9);
  // Der Zuschlag greift auf den RAHMENANTEIL; der Koppelterm aus der schiefen
  // Biegung steht daneben und wird nicht angehoben.
  pruef('Das Moment folgt genau dem Faktor',
        b1.M - b1.M_kopp, (b0.M - b0.M_kopp) * b1.endfeldFaktor, 1e-9, 'kNm');
  pruef('Der Koppelterm bleibt vom Endfeld unberührt', b1.M_kopp, b0.M_kopp, 1e-12, 'kNm');
  // Die QUERKRAFT folgt dem Rahmen und wird nicht angehoben.
  pruef('Die Blechquerkraft bleibt unberührt', b1.V, b0.V, 1e-12, 'kN');
  pruef('M_Knoten bleibt der Rahmenwert', b1.M_Knoten, b0.M_Knoten, 1e-12, 'kNm');
  // Auf η_gesamt muss sich das NICHT auswirken: massgebend kann eine Station
  // in Feldmitte bleiben. Nachgewiesen wird die Wirkung dort, wo sie hingehört.
  // Die Richtung haengt an k_E: ueber 1 hebt der Faktor die Ausnutzung des
  // Endfeldblechs, unter 1 senkt er sie. Geprueft wird, dass er ueberhaupt
  // wirkt - und dass er NUR im Endfeld wirkt.
  wahr('Die Ausnutzung des Endfeldblechs aendert sich',
       Math.abs(t1.knoten[1].etaB - t0.knoten[1].etaB) > 1e-9);
  wahr('… und zwar in die Richtung, die k_E vorgibt',
       (ENDFELD_ZUSCHLAG > 1) === (t1.knoten[1].etaB > t0.knoten[1].etaB));
  const innenK = Math.floor(t1.knoten.length / 2);
  pruef('In Feldmitte bleibt die Ausnutzung unberuehrt',
        t1.knoten[innenK].etaB, t0.knoten[innenK].etaB, 1e-12);
  const { hinweise: hw2 } = await import(J('core.checks.js'));
  wahr('Der Faktor steht in den Hinweisen',
       hw2(mit.modell).join(' | ').includes('äussersten Stationen'));
  wahr('… und sagt, dass er abmindert, wenn k_E unter 1 liegt',
       ENDFELD_ZUSCHLAG >= 1
       || hw2(mit.modell).join(' | ').includes('abgemindert'));
  wahr('Abgeschaltet wird das ebenfalls vermerkt',
       hw2(ohne.modell).join(' | ').includes('abgeschaltet'));
}

// ===========================================================================
titel('29b Zu enges Klemmenraster wird gemeldet');
// Ein Anbauteil haengt ueber zwei Klemmreihen im Abstand `raster`. Das
// Sortiment fuehrt 400 mm; in einer Ausleitung standen 20 mm - ein Vertipper,
// der ein Gurtstueck von 10 mm erzeugte. Gesperrt wird nichts (Ausnahmen
// kommen vor), aber still durchlaufen soll es auch nicht.
{
  const { hinweise: hw3 } = await import(J('core.checks.js'));
  const j90b = T.getTragjoch('J90');
  const grund = { ...basis(), ...typUebernehmen({ ...standardwerte() }, j90b),
                  typ: 'J90', L: 15.5, schneeAktiv: false,
                  endbedingung: 'gelenkig' };
  const mitEng = rechne({ ...grund,
    anbauteile: [teil({ id: 'E', x: 7.75, raster: 0.02, befestigung: 'durchgehend',
      lasten: [block({ einwirkung: 'G', x: 0, z: -1.5, Fz: 2 })] })] });
  const mitNorm = rechne({ ...grund,
    anbauteile: [teil({ id: 'N', x: 7.75, raster: 0.40, befestigung: 'durchgehend',
      lasten: [block({ einwirkung: 'G', x: 0, z: -1.5, Fz: 2 })] })] });
  wahr('20 mm Raster wird gemeldet',
       hw3(mitEng.modell).join(' | ').includes('Klemmenraster ungewöhnlich eng'));
  wahr('… mit dem Mass im Klartext',
       hw3(mitEng.modell).join(' | ').includes('20 mm'));
  wahr('400 mm gibt keinen Hinweis',
       !hw3(mitNorm.modell).join(' | ').includes('Klemmenraster ungewöhnlich eng'));
  // GESPERRT wird nichts - die Rechnung laeuft mit dem Wert, wie er dasteht.
  wahr('Gerechnet wird trotzdem', Number.isFinite(mitEng.max.etaGesamt));
}

// ===========================================================================
titel('29c Abgleichwerkzeug: die Werkzeugseite');
// vergleich_werkzeug.mjs schreibt einen Eingabestand je charakteristischem
// Einzellastfall aus. Geprueft wird hier die Form - dass jeder Lastfall,
// jede Station und jede Bauteilfamilie drinsteht und die Geometrie mitkommt,
// aus der die Gegenseite ihre Staebe zuordnet.
{
  const { standardLastfaelle } = await import(J('core.lasten.js'));
  const w = basis({ lastHerkunft: 'manuell', gkManuell: 0.7, skManuell: 0.24,
                    wkManuell: 0.52, schneeAktiv: true, anbauteile: [] });
  const chars = standardLastfaelle(w).filter((l) => l.art === 'charakteristisch');
  wahr('Es gibt charakteristische Einzellastfaelle zum Vergleichen',
       chars.length >= 5, chars.map((l) => l.key).join(', '));

  // Dieselbe Schleife, die das Werkzeug faehrt.
  const faelle = {};
  let m = null;
  for (const l of chars) {
    const e = rechne({ ...w, lastfall: l.key, beiwerteFest: null });
    m = e.modell;
    faelle[l.key] = e.knoten.map((k) => ({
      x: k.x,
      gurt: Object.fromEntries(k.ecken.map((c) => [c.id, c.sig_v])),
      blech: Object.fromEntries(k.ebenen.filter((p) => p.eta != null)
        .map((p) => [p.id, p.M])),
    }));
  }
  wahr('Je Lastfall alle Stationen', Object.values(faelle)
    .every((v) => v.length === faelle[chars[0].key].length));
  wahr('Je Station alle vier Gurtwinkel', Object.values(faelle)
    .every((v) => v.every((k) => Object.keys(k.gurt).length === 4)));
  wahr('Je Station die Blechebenen', faelle[chars[0].key]
    .some((k) => Object.keys(k.blech).length >= 2));
  // Die Geometrie, aus der die Gegenseite ihre Staebe zuordnet.
  wahr('Die Gurtachsen liegen symmetrisch zur Jochachse',
       Math.abs((m.h / 2) + (-m.h / 2)) < 1e-12);
  wahr('Geometrie vollstaendig',
       [m.L, m.h, m.b, m.fyd].every((v) => Number.isFinite(v) && v > 0));
  // Verschiedene Lastfaelle geben verschiedene Ergebnisse - sonst waere die
  // Schleife umsonst.
  const s1 = faelle[chars[0].key][5].gurt.OG_L;
  const s2 = faelle.wyk ? faelle.wyk[5].gurt.OG_L : null;
  wahr('Die Lastfaelle unterscheiden sich', s2 === null || Math.abs(s1 - s2) > 1e-6);
}

// ===========================================================================
titel('29a PyNite-Export: das Eigengewicht muss mit');
// AxisVM leitet das Eigengewicht aus den Staeben ab, PyNite NICHT - dort
// steht im Skript keine Zeile dafuer. Ohne sie fehlte im Vergleichsmodell die
// groesste Einzellast, und das Feldmoment fiel 45 % zu klein aus.
{
  const { pyniteSkript } = await import(J('export.pynite.js'));
  const { lasten } = await import(J('export.axisvm.js'));
  const { modell } = await import(J('core.vierendeel.js'));
  const w = basis({ lastHerkunft: 'manuell', gkManuell: 0.70, skManuell: 0.24,
                    wkManuell: 0.52, schneeAktiv: true, gZusatz: 0.05,
                    anbauteile: [] });
  const m = modell(w, getProfil(w.profOG), getProfil(w.profUG),
                   getStahl(w.stahl), T.getTragjoch(w.typ));
  const t = pyniteSkript(m, { knotenmodell: 'anschnitt' });
  const text = typeof t === 'string' ? t : t.text;
  const zeilen = text.split('\n').filter((z) => z.includes("case='G'"));
  wahr('Der Export schreibt Eigengewichtslasten', zeilen.length > 0,
       `${zeilen.length} Zeilen`);
  // Volle Laufmeterlast, hälftig... nein: viertelweise auf alle vier Gurte.
  const erste = zeilen[0].match(/'FY', (-?[\d.]+),/);
  pruef('Zusammen ergeben sie g_k', 4 * Math.abs(parseFloat(erste[1])),
        m.char.gk, 1e-5, 'kN/m');

  // Der AxisVM-Export laesst es weiterhin weg - dort rechnet das Programm
  // selbst, und beides waere doppelt.
  const bau = t.bau;
  const ohne = lasten(m, bau);
  const mit = lasten(m, bau, { eigengewicht: true });
  // Jeder Gurtstab bekommt ein Viertel; die Summe ueber die vier Gurte ist
  // die Laufmeterlast.
  const gStrecke = (l) => {
    const q = l.strecke.filter((x) => x.lastfall === 'G');
    return q.length ? 4 * Math.abs(q[0].wert) : 0;
  };
  // Ohne Schalter bleibt nur ein allfaelliger Zuschlag - bei Lasten von Hand
  // gibt es keinen, also gar keine Streckenlast. GENAU DAS war der Fehler:
  // der PyNite-Export nahm die Regel des AxisVM-Exports mit, obwohl PyNite
  // das Eigengewicht nicht selbst rechnet.
  wahr('Ohne Schalter keine Eigengewichtslast',
       ohne.strecke.filter((q) => q.lastfall === 'G').length === 0);
  wahr('Mit Schalter die volle Laufmeterlast',
       Math.abs(gStrecke(mit) - m.char.gk) < 1e-6, `${gStrecke(mit).toFixed(4)} kN/m`);
  // Die Resultierende liegt auf der Jochachse: kein Torsionsmoment.
  const je = new Set(mit.strecke.filter((q) => q.lastfall === 'G')
    .map((q) => q.stab.slice(0, 3)));
  wahr('Auf alle vier Gurte gleich verteilt', je.size === 4,
       [...je].join(', '));
}

// ===========================================================================
titel('30a Modellebenen: Schwerachsen eingefaerbt, Auflager als eigene Ebene');
// Die Schwerachsen SIND das Stabmodell - sie tragen feldweise dieselben
// Kennwerte wie die Volumenkoerper. Der frueher eigene Schalter
// "Stabmodell (ohne Koerper)" sagte nichts, was Gurtprofile und Bindebleche
// nicht schon sagen; sein Platz gehoert jetzt der Auflagerdefinition.
{
  const R = await import(J('render.3d.js'));
  const w = basis({ endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.5,
                    mastSteg: 'jochachse', mastAnschluss: 'kragarm',
                    schraubenGrenze: false, kragA: 0.35, kragB: 0.75 });
  const e = rechne(w);
  const sz = R.erzeugeSzene(e.modell, e);

  // --- Schwerachsen ---------------------------------------------------------
  const gurt = sz.linien.filter((l) => l.gurt);
  wahr('Die Gurtachsen sind feldweise aufgeteilt', gurt.length > 4 * 5,
       `${gurt.length} Abschnitte bei 4 Gurten`);
  wahr('Jeder Abschnitt hat genau zwei Punkte',
       gurt.every((l) => l.punkte.length === 2));
  wahr('Jeder Abschnitt traegt Kennwerte',
       gurt.every((l) => l.werte && Number.isFinite(l.werte.eta)));
  wahr('Verschiedene Felder tragen verschiedene Werte',
       new Set(gurt.map((l) => l.werte.eta)).size > 3);
  // Sie decken die ganze Gurtlaenge ab, ohne Luecke.
  const einGurt = gurt.filter((l) => l.label === gurt[0].label)
    .sort((a, b) => a.punkte[0][0] - b.punkte[0][0]);
  pruef('Sie beginnen am Gurtanfang', einGurt[0].punkte[0][0], 0, 1e-9, 'm');
  pruef('und enden am Gurtende',
        einGurt[einGurt.length - 1].punkte[1][0], e.modell.L, 1e-9, 'm');
  wahr('ohne Luecke dazwischen', einGurt.every((l, i) =>
    i === 0 || Math.abs(l.punkte[0][0] - einGurt[i - 1].punkte[1][0]) < 1e-9));

  // Die Blechachsen ebenso - sonst waere das Fachwerk halb eingefaerbt.
  const bl = sz.linien.filter((l) => l.blechachse);
  wahr('Auch die Blechachsen tragen Kennwerte', bl.length > 0
       && bl.every((l) => l.werte !== undefined));
  wahr('Es gibt keine Gruppe "stab" mehr',
       !sz.linien.some((l) => l.gruppe === 'stab'));

  // --- Auflagerebene --------------------------------------------------------
  const auf = sz.linien.filter((l) => l.gruppe === 'auflager');
  const mAuf = sz.marken.filter((k) => k.gruppe === 'auflager');
  wahr('Es gibt eine Auflagerebene', auf.length > 0 && mAuf.length > 0);
  // DIE MARKE SITZT AN DER MASTACHSE, nicht am Gurtende - frueher stand sie
  // bei x = 0 und x = L und lag mit Kragarmen falsch.
  const xs = mAuf.filter((k) => k.art === 'auflager').map((k) => k.p[0]).sort((a, b) => a - b);
  pruef('Auflager A steht bei kragA', xs[0], 0.35, 1e-9, 'm');
  pruef('Auflager B steht bei L − kragB', xs[1], e.modell.L - 0.75, 1e-9, 'm');
  /*
   * DER MAST IST EIN KOERPER, KEIN STUMMEL (Weisung).
   *
   * Er stand als zwei Striche da, auf ein Stueck gekuerzt - "die Aussage ist
   * die Lagerung, nicht die Masthoehe". Das galt, solange der Mast nur eine
   * Randbedingung war. Er ist seither Teil des Tragwerks: er steht als Stab
   * im ausgeleiteten Modell, und man haengt Anbauteile an ihn, die ueber ihre
   * HOEHE sitzen. Wer die Hoehe nicht sieht, kann sie nicht treffen.
   */
  const mastF = sz.flaechen.filter((f) => /^MAST_/.test(f.teil ?? ''));
  wahr('Der Mast wird als Koerper gezeichnet', mastF.length > 0,
       `${mastF.length} Flaechen`);
  wahr('Und zwar an beiden Enden',
       new Set(mastF.map((f) => f.teil)).size === 2,
       [...new Set(mastF.map((f) => f.teil))].join(', '));
  /*
   * ZWOELF ECKEN, JE ABSCHNITT.
   *
   * Zwei Flansche und der Steg ergeben zwoelf Mantelflaechen und zwei Deckel,
   * also 14 je Prisma. Seit dem 1. September ist der Mast nicht mehr EIN
   * Prisma, sondern eine Folge von Abschnitten - jeder mit seiner Ausnutzung.
   * Geprueft wird deshalb die FORM (ein Vielfaches von 14) statt der Zahl.
   */
  {
    const n = mastF.filter((f) => f.teil === 'MAST_A').length;
    wahr('Als I-Querschnitt mit zwoelf Ecken', n % 14 === 0, `${n} Flaechen`);
    wahr('In mehreren Abschnitten uebereinander', n > 14, `${n / 14} Abschnitte`);
  }
  {
    /*
     * VOM FUSS BIS UEBER DEN OBERGURT.
     *
     * Weisung: die Masten immer einen halben Meter ueber den Obergurt
     * fuehren. Auf jedem Querprofil laufen sie ueber das Joch hinaus, und wer
     * eine Zeichnung dahinterlegt, will beide zur Deckung bringen.
     *
     * Die Masthoehe H selbst bleibt unberuehrt - sie ist als FUSS BIS
     * JOCHACHSE definiert und geht so in die Drehfeder ein. Der Ueberstand
     * waechst nach OBEN; der Fuss bleibt, wo das Lager sitzt.
     */
    const zs = mastF.filter((f) => f.teil === 'MAST_A').flatMap((f) => f.punkte.map((p) => p[2]));
    const H = e.modell.federn.mastA?.H ?? e.modell.federn.mast?.H;
    // Die Oberkante des Obergurts unabhaengig ermitteln - aus den Gurtflaechen
    // selbst, nicht aus den Bildgrenzen: die tragen den Masten inzwischen mit.
    const zOG = Math.max(...sz.flaechen.filter((f) => f.gruppe === 'profil')
      .flatMap((f) => f.punkte.map((p) => p[2])));
    /*
     * MINDESTENS einen halben Meter. Seit dem 5. September liegt die
     * vorgegebene Laenge auf dem HALBMETERRASTER des Sortiments und ist
     * damit meist etwas laenger als das Mindestmass - aufgerundet, nie ab.
     */
    wahr('Der Kopf steht mindestens einen halben Meter ueber dem Obergurt',
         Math.max(...zs) >= zOG + 0.5 - 1e-9,
         `${(Math.max(...zs) - zOG).toFixed(3)} m`);
    /*
     * Die Auflagermarke steht UNTER dem Fundamentklotz (Weisung vom
     * 18. September: «den block unterhalb des masten ansetzen, keine
     * überschneidung») - der Klotz selbst schliesst oben am Mastfuss an.
     */
    const fussMarke = mAuf.find((k) => k.art === 'auflager'
                                    && Math.abs(k.p[0] - 0.35) < 1e-9);
    const fkZ = sz.flaechen.filter((f) => f.teil === 'FUNDAMENT_A')
      .flatMap((f) => f.punkte.map((p) => p[2]));
    pruef('Der Klotz schliesst oben am Mastfuss an', Math.max(...fkZ),
          Math.min(...zs), 1e-9, 'm');
    pruef('Die Auflagermarke sitzt unter dem Klotz', fussMarke.p[2],
          Math.min(...fkZ), 1e-9, 'm');
    wahr('Die Masthoehe H selbst bleibt davon unberuehrt',
         Math.abs(e.modell.federn.mastA.H - 7.5) < 1e-12, `${e.modell.federn.mastA.H} m`);
    // Der wirkliche Querschnitt, nicht ein Kasten: die y-Ausdehnung ist bei
    // "Steg in Jochachse" die Flanschbreite b.
    const ys = mastF.filter((f) => f.teil === 'MAST_A').flatMap((f) => f.punkte.map((p) => p[1]));
    const prof = e.modell.federn.mastA?.profil ?? e.modell.federn.mast?.profil;
    pruef('Mit der Flanschbreite quer zur Jochachse',
          Math.max(...ys) - Math.min(...ys), prof.b / 1000, 1e-9, 'm');
    const xs2 = mastF.filter((f) => f.teil === 'MAST_A').flatMap((f) => f.punkte.map((p) => p[0]));
    pruef('Und der Profilhoehe in der Jochachse',
          Math.max(...xs2) - Math.min(...xs2), prof.h / 1000, 1e-9, 'm');
  }
  /*
   * DAS LAGER SITZT AM MASTFUSS (Weisung).
   *
   * Dort steht das Fundament. An der Jochachse sitzt kein Lager, sondern der
   * ANSCHLUSS - die Drehfeder c_phi, die die Nachgiebigkeit des Mastes
   * zusammenfasst. Die Marke an der Jochachse las sich wie ein Auflager.
   */
  {
    const H = e.modell.federn.mastA?.H ?? e.modell.federn.mast?.H;
    const a = mAuf.find((k) => k.art === 'auflager' && Math.abs(k.p[0] - 0.35) < 1e-9);
    wahr('Die Auflagermarke sitzt am Mastfuss, nicht an der Jochachse',
         a.p[2] < -H * 0.9, `z = ${a.p[2].toFixed(2)} m bei H = ${H} m`);
  }
  // Das Bild reicht bis dorthin - sonst stuende der Mast beim Einpassen
  // halb ausserhalb.
  {
    const H = e.modell.federn.mastA?.H ?? e.modell.federn.mast?.H;
    wahr('Und die Bildgrenzen reichen bis zum Fuss', sz.grenzen.zMin <= -H * 0.9,
         `zMin = ${sz.grenzen.zMin.toFixed(2)} m`);
  }
  /* =========================================================================
   * >>> AUS DER FUSSSCHRAFFUR IST EIN FUNDAMENTKOPF GEWORDEN. <<<
   * =========================================================================
   *
   * Weisung vom 11. September: «die fundamentkoepfe vertikal machen und
   * etwas doppel so dick wie den masten darstellen.»
   *
   * Bis dahin standen dort fuenf schraege Striche - das Zeichen fuer eine
   * Einspannung. Es sagt, WIE gelagert wird, zeigt aber nicht, WAS dort
   * steht. Jetzt ist es ein Koerper: doppelte Mastbreite, quadratisch im
   * Grundriss, auf der Fusslinie stehend.
   *
   * Die Lagerung selbst bleibt in der Ebene `auflager` und der Kopf in
   * `mast` - der Mast ist ein Bauteil und laesst sich wegnehmen, ohne dass
   * die Lagerung verschwindet. Das galt fuer die Schraffur und gilt fuer den
   * Kopf.
   * ======================================================================= */
  const mastL = sz.linien.filter((l) => l.gruppe === 'mast');
  const fkF = sz.flaechen.filter((f) => /^FUNDAMENT_/.test(f.teil ?? ''));
  wahr('Der Fundamentkopf steht als Koerper da', fkF.length > 0,
       `${fkF.length} Flaechen`);
  {
    // Doppelte Mastbreite: HEB 240 ist 0.24 m breit, der Kopf also 0.48 m.
    const ys = fkF.flatMap((f) => f.punkte.map((p2) => p2[1]));
    const zs = fkF.flatMap((f) => f.punkte.map((p2) => p2[2]));
    pruef('… und ist doppelt so breit wie der Mast',
          Math.max(...ys) - Math.min(...ys), 0.48, 1e-6, 'm');
    /*
     * DER BEZUG IST DER MASTFUSS, nicht -H. `H` ist die ANSCHLUSSHOEHE des
     * Jochs; der Mast reicht tiefer - um den Ueberstand und um die halbe
     * Bauhoehe des Traegers. Der erste Anlauf pruefte gegen -7.50 und
     * bekam -7.7455: der Kopf stand richtig, die Kontrolle fragte falsch.
     */
    const mastZ = sz.flaechen
      .filter((f) => f.gruppe === 'mast' && !/FUNDAMENT/.test(f.teil ?? ''))
      .flatMap((f) => f.punkte.map((p2) => p2[2]));
    // Seit dem 18. September UNTER dem Mastfuss, ohne Ueberschneidung.
    pruef('… und steht UNTER dem Mastfuss', Math.max(...zs),
          Math.min(...mastZ), 1e-9, 'm');
  }
  /*
   * DIE TRENNUNG DER EBENEN BLEIBT, nur zaehlt sie jetzt KOERPER: die
   * Fussschraffur war die einzige Mastlinie, und seit dem 11. September ist
   * sie ein Fundamentkopf. Die Aussage ist dieselbe - was zum Masten
   * gehoert, liegt in `mast` und laesst sich wegnehmen, ohne die Lagerung
   * zu verlieren; die Auflagerzeichen bleiben in `auflager`.
   */
  const mastKoerperF = sz.flaechen.filter((f) => f.gruppe === 'mast');
  wahr('Und zwar in der Ebene der Masten',
       auf.every((l) => l.gruppe === 'auflager') && mastKoerperF.length > 0,
       `${mastKoerperF.length} Mastflaechen, ${mastL.length} Mastlinien`);
  wahr('Die Kragarme sind ausgewiesen', auf.filter((l) => l.kragarm).length === 2);
  const txt = mAuf.filter((k) => k.art === 'auflagertext')
    .map((k) => k.zeilen.join(' / ')).join(' | ');
  /*
   * Nur noch die Lagerung (Weisung vom 18. September): «es stellt sich die
   * frage ob es diesen text überhaupt braucht, da der mast schon
   * angeschrieben ist.» Profil und Hoehe stehen im Titel des Masten.
   */
  wahr('Feder und Einspanngrad stehen dabei',
       txt.includes('c_φ') && txt.includes('κ'), txt);
  wahr('… das Profil nicht mehr - es steht im Titel des Masten',
       !txt.includes('HEB 240'), txt);
  wahr('Die Angabe steht einzeilig',
       mAuf.filter((k) => k.art === 'auflagertext').every((k) => k.zeilen.length === 1));
  wahr('Keine Zeile ist länger als 30 Zeichen',
       mAuf.filter((k) => k.art === 'auflagertext')
         .every((k) => k.zeilen.every((z) => z.length <= 30)), txt);

  // Ohne Kragarme sitzen die Auflager an den Gurtenden.
  const ohne = rechne({ ...w, kragA: 0, kragB: 0 });
  const xo = R.erzeugeSzene(ohne.modell, ohne).marken
    .filter((k) => k.art === 'auflager').map((k) => k.p[0]).sort((a, b) => a - b);
  pruef('Ohne Kragarm bei 0', xo[0], 0, 1e-9, 'm');
  pruef('und bei L', xo[1], ohne.modell.L, 1e-9, 'm');
  wahr('Ohne Kragarm keine Kragarmlinie',
       !R.erzeugeSzene(ohne.modell, ohne).linien.some((l) => l.kragarm));

  // Gelenkig gelagert: kein Mast, aber die Marke steht trotzdem.
  const gel = rechne({ ...w, endbedingung: 'gelenkig' });
  const sg = R.erzeugeSzene(gel.modell, gel);
  wahr('Auch gelenkig gibt es die Auflagerebene',
       sg.marken.some((k) => k.gruppe === 'auflager' && k.art === 'auflager'));
  wahr('Dann steht «gelenkig» dabei',
       sg.marken.filter((k) => k.art === 'auflagertext')
         .some((k) => k.zeilen.join(' ').includes('gelenkig')));
}

// ===========================================================================
titel('29b Eigenanteil der Gurte am globalen Moment');
// Die Zwei-Gurt-Idealisierung traegt das globale Moment allein ueber die
// Normalkraefte ab. Nach der Ebenbleibenshypothese traegt jeder Winkel es
// aber auch ueber sein EIGENES Traegheitsmoment mit - klein, aber es laeuft
// mit dem GLOBALEN Moment und nicht mit der Querkraft. In Feldmitte, wo das
// Rahmenmoment gegen null geht, ist es das einzige Moment im Gurt.
{
  const { eigenanteil } = await import(J('core.querschnitt.js'));
  const P = getProfil('L 100x100x10'), Q = getProfil('L 80x80x8');
  const m = { profOG: P, profUG: Q, h: 0.5492, b: 0.4508 };
  const ea = eigenanteil(m);
  const iy = (p) => p.iy ** 2 * p.A, iz = (p) => (p.iz ?? p.iy) ** 2 * p.A;

  // I_ges = Steiner + Eigenanteil, in cm4
  const eZ = 54.92 / 2, eY = 45.08 / 2;
  pruef('I_ges um die waagrechte Achse', ea.Iges_y,
        2 * P.A * eZ ** 2 + 2 * Q.A * eZ ** 2 + 2 * iy(P) + 2 * iy(Q), 1e-6, 'cm4');
  pruef('I_ges um die lotrechte Achse', ea.Iges_z,
        2 * (P.A + Q.A) * eY ** 2 + 2 * iz(P) + 2 * iz(Q), 1e-6, 'cm4');
  pruef('Anteil des Obergurts an M_y', ea.OG.my, iy(P) / ea.Iges_y, 1e-12, '–');
  pruef('Anteil des Untergurts an M_z', ea.UG.mz, iz(Q) / ea.Iges_z, 1e-12, '–');
  wahr('Der steifere Gurt traegt mehr mit', ea.OG.my > ea.UG.my);
  wahr('Zusammen sind es wenige Prozent',
       2 * (ea.OG.my + ea.UG.my) < 0.05 && 2 * (ea.OG.mz + ea.UG.mz) < 0.05,
       `${(200 * (ea.OG.my + ea.UG.my)).toFixed(1)} % / `
       + `${(200 * (ea.OG.mz + ea.UG.mz)).toFixed(1)} %`);
  // Gemessen am Rahmen: 177/(32010 + 499) · 42 kNm = 0.229 kNm je Obergurt
  pruef('Trifft den gemessenen Rahmenwert', ea.OG.mz * 42, 0.229, 0.01, 'kNm');

  // --- Im Rechenkern --------------------------------------------------------
  // Reine Querlast: in Feldmitte geht die Querkraft gegen null, der
  // Eigenanteil bleibt stehen.
  const w = basis({ lastHerkunft: 'manuell', gkManuell: 0, skManuell: 0,
                    wkManuell: 0.52, schneeAktiv: false, anbauteile: [],
                    endbedingung: 'gelenkig',
                    beiwerteFest: { G: 0, WindX: 0, WindY: 1, Schnee: 0, Leiterzug: 0 } });
  const e = rechne(w);
  const mitte = e.knoten[Math.floor(e.knoten.length / 2)];
  const og = mitte.ecken.find((c) => c.id === 'OG_L');
  wahr('In Feldmitte ist die Querkraft fast null', Math.abs(mitte.Vy) < 0.05,
       `V_y = ${mitte.Vy.toFixed(4)} kN`);
  wahr('Das Gurtmoment ist es NICHT', og.Mz_lokal > 0.02,
       `M_z = ${og.Mz_lokal.toFixed(4)} kNm`);
  pruef('Es ist genau der Eigenanteil', og.Mz_lokal, mitte.eigenMz.OG, 1e-9, 'kNm');
  pruef('Und der folgt dem globalen Moment', mitte.eigenMz.OG,
        Math.abs(mitte.Mz) * eigenanteil(e.modell).OG.mz, 1e-9, 'kNm');

  // KEINE Anschnittabminderung: er laeuft mit dem globalen Verlauf.
  const anschnitt = e.knoten[3];
  const ogA = anschnitt.ecken.find((c) => c.id === 'OG_L');
  pruef('Ohne Abminderung auf den Anschnitt',
        ogA.Mz_lokal - anschnitt.Mz_Knoten * anschnitt.anschnittMz,
        anschnitt.eigenMz.OG, 1e-9, 'kNm');

  // Bei UNGLEICHEN Gurten bekommen sie verschiedene Anteile - vorher trugen
  // alle vier Winkel dasselbe M_z. Bei gleichen Profilen bleibt es gleich.
  const ug = mitte.ecken.find((c) => c.id === 'UG_L');
  pruef('Gleiche Profile: gleicher Anteil', og.Mz_lokal, ug.Mz_lokal, 1e-12, 'kNm');
  const un = rechne({ ...w, profOG: 'L 100x100x10', profUG: 'L 80x80x8' });
  const m2 = un.knoten[Math.floor(un.knoten.length / 2)];
  const o2 = m2.ecken.find((c) => c.id === 'OG_L');
  const u2 = m2.ecken.find((c) => c.id === 'UG_L');
  wahr('Ungleiche Gurte: der steifere traegt mehr mit',
       o2.Mz_lokal > u2.Mz_lokal + 1e-6,
       `${o2.Mz_lokal.toFixed(4)} gegen ${u2.Mz_lokal.toFixed(4)} kNm`);

  // Ohne globales Moment kein Eigenanteil.
  const leer = rechne({ ...w, wkManuell: 0 });
  pruef('Ohne Last kein Eigenanteil',
        leer.knoten[5].eigenMz.OG, 0, 1e-12, 'kNm');

  const { hinweise: hw } = await import(J('core.checks.js'));
  wahr('Der Term steht in den Hinweisen',
       hw(e.modell).join(' | ').includes('Eigenanteil der Gurte'));
  wahr('Das Modell weist die Anteile aus',
       e.modell.eigenanteil && e.modell.eigenanteil.Iges_y > 0);
}

// ===========================================================================
titel('30  Schiefe Biegung der Gurtwinkel auf die Bindebleche');
// Der Winkel hat seine Hauptachsen unter 45 Grad. Unter dem oertlichen
// Rahmenmoment weicht er quer aus; die Bleche der ANDEREN Ebene halten
// dagegen. Ohne diesen Term sind die Horizontalbleche unter reiner
// Vertikallast spannungsfrei - das gepruefte FEM-Modell zeigt dort 11 N/mm2.
{
  const { koppelfaktor, SCHIEFE_DAEMPFUNG } = await import(J('core.querschnitt.js'));
  const { winkelwerteFuer } = await import(J('core.winkel.js'));
  const { hinweise } = await import(J('core.checks.js'));
  const P = getProfil('L 100x100x10');
  const blech = { breite: 160, dicke: 10, laenge: 420 };

  // --- die Formel selbst ----------------------------------------------------
  const kf = koppelfaktor(P, blech, 0.70, 0.42, 'z');
  const w = winkelwerteFuer(P);
  const D = w.Iy * w.Iz - w.Iyz * w.Iyz;
  pruef('r = |I_yz| / I_treib', kf.r, Math.abs(w.Iyz) / w.Iz, 1e-12, '–');
  pruef('I* = (I_y I_z − I_yz²) / I_treib', kf.Istern, D / w.Iz, 1e-9, 'mm4');
  pruef('I_p ist das Blech in seiner eigenen Ebene', kf.Ip, (10 * 160 ** 3) / 12,
        1e-9, 'mm4');
  pruef('β = I_p · a / (6 · L_c · I*)', kf.beta,
        (kf.Ip * 700) / (6 * 420 * kf.Istern), 1e-12, '–');
  /*
   * DIE HERGELEITETE FORMEL, ABGEMINDERT AUF DIE MESSUNG.
   *
   * Die Herleitung setzt die volle Behinderung an - der Gurt bleibe im
   * Mittel gerade. Ueber 509 Messstellen an vier Typen liegt sie damit im
   * Mittel 30 Prozent zu hoch (kalibrieren.mjs --nur schief).
   */
  pruef('Faktor = k_S · 2 · r · β/(1+β)', kf.faktor,
        SCHIEFE_DAEMPFUNG * 2 * kf.r * (kf.beta / (1 + kf.beta)), 1e-12, '–');
  wahr('Die Abminderung steht zwischen 0 und 1',
       SCHIEFE_DAEMPFUNG > 0 && SCHIEFE_DAEMPFUNG <= 1);
  pruef('… und ist der gemessene Wert', SCHIEFE_DAEMPFUNG, 0.70, 1e-12, '–');
  // Gleichschenkliger Winkel: r = (I1 − I2)/(I1 + I2)
  pruef('Beim gleichschenkligen Winkel ist r = (I1−I2)/(I1+I2)', kf.r,
        (w.I1 - w.I2) / (w.I1 + w.I2), 1e-9, '–');

  // Grenzfaelle: ein steiferes Blech behindert mehr, ein laengeres weniger.
  const steifer = koppelfaktor(P, { ...blech, breite: 220 }, 0.70, 0.42, 'z');
  const laenger = koppelfaktor(P, { ...blech, laenge: 700 }, 0.70, 0.70, 'z');
  wahr('Ein steiferes Blech zieht mehr Moment an sich', steifer.faktor > kf.faktor);
  wahr('Ein weicheres Blech weniger', laenger.faktor < kf.faktor);
  wahr('Volle Behinderung bleibt die obere Schranke',
       kf.faktor < SCHIEFE_DAEMPFUNG * 2 * kf.r + 1e-12);
  wahr('Ohne Blechangaben kein Koppelterm',
       koppelfaktor(P, null, 0.7, 0.42, 'z') === null
       && koppelfaktor(P, blech, 0, 0.42, 'z') === null);

  // --- im Rechenkern --------------------------------------------------------
  // Reine Vertikallast: die Horizontalbleche bekommen NUR aus diesem Term
  // etwas - der Rahmen gibt ihnen null.
  const v = basis({ lastHerkunft: 'manuell', gkManuell: 1.5, wkManuell: 0,
                    skManuell: 0, schneeAktiv: false, anbauteile: [],
                    beiwerteFest: { G: 1, WindX: 0, WindY: 0, Schnee: 0, Leiterzug: 0 } });
  const mit = rechne(v);
  const ohne = rechne({ ...v, schiefeBiegung: false });
  const hor = (e) => e.knoten[1].ebenen.find((x) => x.art === 'horizontal');
  const ver = (e) => e.knoten[1].ebenen.find((x) => x.art === 'vertikal');
  pruef('Ohne den Term ist das Horizontalblech spannungsfrei',
        hor(ohne).sig_v, 0, 1e-12, 'N/mm²');
  wahr('Mit dem Term traegt es', hor(mit).sig_v > 1,
       `σ_v = ${hor(mit).sig_v.toFixed(2)} N/mm²`);
  pruef('Der Rahmenanteil bleibt null', hor(mit).M_Knoten, 0, 1e-12, 'kNm');
  pruef('Das ganze Moment kommt aus der Kopplung', hor(mit).M, hor(mit).M_kopp,
        1e-12, 'kNm');
  // KEINE Querkraft: der Term ist ein konstantes Moment ueber die Blechlaenge.
  pruef('Die Blechquerkraft bleibt unberuehrt', hor(mit).V, hor(ohne).V, 1e-12, 'kN');
  pruef('Und damit auch τ', hor(mit).tau, hor(ohne).tau, 1e-12, 'N/mm²');
  // Konstantes Moment heisst: keine Abminderung auf den Anschnitt. Geprueft
  // an einem Joch mit UNGLEICHEN Gurten - sonst faellt eine Verwechslung von
  // My_KnotenG (nach Steifigkeit geteilt) und My_Knoten (haelftig) nicht auf.
  const ug = rechne({ ...v, profOG: 'L 100x100x10', profUG: 'L 80x80x8' });
  const horU = ug.knoten[1].ebenen.find((x) => x.art === 'horizontal' && x.id === 'H_O');
  wahr('Ungleiche Gurte: die Aufteilung ist nicht haelftig',
       Math.abs(ug.knoten[1].My_KnotenG.OG - ug.knoten[1].My_Knoten) > 1e-6);
  pruef('Der Koppelterm folgt der Formel', horU.M_kopp,
        koppelfaktor(ug.modell.profOG, horU, ug.knoten[1].aGurt,
                     horU.lichteLaenge, 'y').faktor
        * Math.abs(ug.knoten[1].My_KnotenG.OG), 1e-9, 'kNm');
  const horUnten = ug.knoten[1].ebenen.find((x) => x.id === 'H_U');
  pruef('Das untere Blech folgt dem UNTERgurt', horUnten.M_kopp,
        koppelfaktor(ug.modell.profUG, horUnten, ug.knoten[1].aGurt,
                     horUnten.lichteLaenge, 'y').faktor
        * Math.abs(ug.knoten[1].My_KnotenG.UG), 1e-9, 'kNm');
  wahr('und ist damit ein anderer Wert', Math.abs(horUnten.M_kopp - horU.M_kopp) > 1e-9);

  // Das Vertikalblech bekommt seinen Anteil aus dem GRUNDRISSmoment, also
  // unter Wind - unter reiner Vertikallast nicht.
  pruef('Vertikalblech ohne Grundrissmoment: kein Koppelterm',
        ver(mit).M_kopp, 0, 1e-12, 'kNm');
  const wind = rechne({ ...v, wkManuell: 2.0,
                        beiwerteFest: { G: 0, WindX: 0, WindY: 1, Schnee: 0, Leiterzug: 0 } });
  const windOhne = rechne({ ...v, wkManuell: 2.0, schiefeBiegung: false,
                            beiwerteFest: { G: 0, WindX: 0, WindY: 1, Schnee: 0, Leiterzug: 0 } });
  wahr('Unter Wind traegt das Vertikalblech den Koppelterm',
       ver(wind).M_kopp > 0 && ver(wind).M > ver(windOhne).M);

  // Ohne Torsion und ohne Wind bleibt die Ausnutzung des JOCHS unveraendert
  // oder steigt - der Term nimmt nie etwas weg.
  wahr('Der Term nimmt nie Beanspruchung weg',
       mit.max.etaGesamt >= ohne.max.etaGesamt - 1e-12);

  // --- Schalter und Hinweis -------------------------------------------------
  wahr('Vorgabe ist eingeschaltet', standardwerte().schiefeBiegung === true);
  wahr('Der Term steht in den Hinweisen',
       hinweise(mit.modell).join(' | ').includes('Schiefe Biegung'));
  wahr('Abgeschaltet wird das vermerkt',
       hinweise(ohne.modell).join(' | ').includes('abgeschaltet'));
  const SCH = await import(J('ui.schema.js'));
  wahr('Der Schalter steht im Optionen-Dialog',
       SCH.optionenFelder(standardwerte())
         .some((a) => a.felder.some((f) => f.key === 'schiefeBiegung')));
}

// ===========================================================================
titel('27  Navigation im Modell: schieben, drehen, auf den Zeiger zoomen');

{
  const R = await import(J('render.3d.js'));

  /**
   * Eine Ansicht OHNE Zeichenfläche. Geprüft wird die Kamerarechnung, nicht
   * das Malen: alles unten läuft über _projektor(), also über genau die
   * Abbildung, mit der auch gezeichnet wird. Ein falsches Vorzeichen fiele
   * hier auf und nicht erst am Bildschirm.
   */
  const ansicht = (grenzen, dist = 10) => {
    const a = Object.create(R.Modellansicht.prototype);
    a.cv = { width: 800, height: 600, clientHeight: 600,
             getBoundingClientRect: () => ({ width: 800, height: 600,
                                             left: 0, top: 0 }) };
    a.kamera = { az: -0.62, el: 0.42, dist, ziel: [4, 0, 0.6],
                 fov: 0.60, pan: [0, 0, 0] };
    a.projektion = 'perspektive';
    a.szene = { grenzen };
    a.zeichne = () => {};
    return a;
  };
  const JOCH = { xMin: 0, xMax: 20, yMin: -0.5, yMax: 0.5, zMin: 0, zMax: 1.2 };

  // --- Auf den Zeiger zoomen ------------------------------------------------
  // Der Punkt unter dem Zeiger muss unter dem Zeiger BLEIBEN. Genau das ist
  // der Unterschied zum Zoomen auf die Bildmitte, und genau daran merkt man
  // ein falsches Vorzeichen.
  {
    const a = ansicht(JOCH);
    const { rechts, hoch } = a._basis();
    const ziel = a._blickziel();
    const w = a._weltProPixel();
    const px = 640, py = 180;                      // irgendwo abseits der Mitte
    const ex = px - 400, ey = py - 300;
    const P = ziel.map((v, i) => v + rechts[i] * ex * w - hoch[i] * ey * w);

    const vor = a._projektor()(P);
    pruef('Der Prüfpunkt liegt anfangs unter dem Zeiger (x)', vor[0], px, 1e-6, 'px');
    pruef('... und in y', vor[1], py, 1e-6, 'px');

    a._zoome(0.5, px, py);
    pruef('Der Abstand halbiert sich', a.kamera.dist, 5, 1e-9, 'm');
    const nach = a._projektor()(P);
    pruef('Nach dem Zoomen liegt er immer noch dort (x)', nach[0], px, 1e-6, 'px');
    pruef('... und in y', nach[1], py, 1e-6, 'px');

    // Und zurück: zweimal zoomen mit Kehrwert führt an denselben Ort.
    a._zoome(2, px, py);
    pruef('Hin und zurück ergibt denselben Abstand', a.kamera.dist, 10, 1e-9, 'm');
    const zurueck = a._projektor()(P);
    pruef('... und denselben Bildpunkt', zurueck[0], px, 1e-6, 'px');
  }

  // Ohne Zeigerpunkt bleibt die Bildmitte stehen - das ist der Weg der
  // Tastatur (+/-), und dort gibt es keinen Zeiger.
  {
    const a = ansicht(JOCH);
    a._zoome(0.5);
    wahr('Ohne Zeigerpunkt wird nicht verschoben',
         a.kamera.pan.every((v) => v === 0));
    pruef('Der Abstand ändert sich trotzdem', a.kamera.dist, 5, 1e-9, 'm');
  }

  // --- Schranken am Modell, nicht fest --------------------------------------
  {
    const gross = ansicht(JOCH);
    const klein = ansicht({ xMin: 0, xMax: 6, yMin: -0.4, yMax: 0.4,
                            zMin: 0, zMax: 0.9 });
    const [minG, maxG] = gross._abstandsgrenzen();
    const [minK, maxK] = klein._abstandsgrenzen();
    wahr('Das lange Joch darf näher heran und weiter weg',
         minG > minK && maxG > maxK,
         `20 m: ${minG.toFixed(2)}…${maxG.toFixed(0)} m · ` +
         `6 m: ${minK.toFixed(2)}…${maxK.toFixed(0)} m`);
    wahr('Ohne Szene bleibt es bei den festen Schranken',
         (() => { const a = ansicht(JOCH); a.szene = null;
                  const [u, o] = a._abstandsgrenzen();
                  return u === 0.4 && o === 400; })());

    const a = ansicht(JOCH, 100);
    a._zoome(1e-9, 640, 180);
    pruef('Näher als die untere Schranke geht es nicht',
          a.kamera.dist, minG, 1e-12, 'm');

    // An der Schranke darf auch nicht mehr mitgeschoben werden - sonst
    // wandert das Modell aus dem Bild, während der Abstand längst steht.
    const b = ansicht(JOCH, minG);
    b._zoome(0.5, 640, 180);
    wahr('An der Schranke bleibt die Verschiebung stehen',
         b.kamera.pan.every((v) => v === 0));
  }

  // --- Schieben: das Bild folgt der Hand ------------------------------------
  {
    const a = ansicht(JOCH);
    const Q = a._blickziel();
    const s0 = a._projektor()(Q);
    a._schiebe(100, 40);
    const s1 = a._projektor()(Q);
    pruef('100 Pixel nach rechts gezogen wandert das Modell 100 nach rechts',
          s1[0] - s0[0], 100, 1e-6, 'px');
    pruef('40 nach unten gezogen wandert es 40 nach unten',
          s1[1] - s0[1], 40, 1e-6, 'px');
  }

  // Aus der Nähe schiebt derselbe Pixelweg WENIGER Weltmass - sonst schösse
  // ein herangezoomtes Modell beim ersten Zug aus dem Bild.
  {
    const fern = ansicht(JOCH, 20), nah = ansicht(JOCH, 2);
    fern._schiebe(100, 0); nah._schiebe(100, 0);
    const wegF = Math.hypot(...fern.kamera.pan);
    const wegN = Math.hypot(...nah.kamera.pan);
    pruef('Der Weg ist dem Abstand verhältnisgleich', wegF / wegN, 10, 1e-9, '-');
  }

  // --- Drehen ---------------------------------------------------------------
  // DAS MODELL FOLGT DER HAND, auf BEIDEN Achsen. Geprüft wird das nicht am
  // Winkel, sondern am Bild: wohin wandert der Punkt, den man beim Ziehen
  // anfasst - der zugewandte, Ziel + vor·r?
  //
  // Eine Bedingung über az allein taugt dafür nicht: sie sagt nur, dass sich
  // etwas ändert, nicht wohin es sich bewegt. Genau darum blieb jahrelang
  // unbemerkt, dass waagrecht der Hand ENTGEGENlief, während senkrecht ihr
  // folgte - das Drehen war spiegelverkehrt.
  {
    const zugewandt = (a, r = 3) => {
      const { vor } = a._basis();
      return a._blickziel().map((v, i) => v + vor[i] * r);
    };
    const zug = (dx, dy) => {
      const a = ansicht(JOCH);
      const P = zugewandt(a);
      const s0 = a._projektor()(P);
      a._drehe(dx, dy);
      const s1 = a._projektor()(P);
      return [s1[0] - s0[0], s1[1] - s0[1]];
    };
    wahr('Nach rechts gezogen wandert die zugewandte Seite nach rechts',
         zug(60, 0)[0] > 20, `${zug(60, 0)[0].toFixed(0)} px`);
    wahr('Nach links gezogen nach links',
         zug(-60, 0)[0] < -20, `${zug(-60, 0)[0].toFixed(0)} px`);
    wahr('Nach unten gezogen nach unten',
         zug(0, 60)[1] > 20, `${zug(0, 60)[1].toFixed(0)} px`);
    wahr('Nach oben gezogen nach oben',
         zug(0, -60)[1] < -20, `${zug(0, -60)[1].toFixed(0)} px`);
    // Gleich empfindlich - sonst fasst sich das Drehen schief an.
    const wg = Math.abs(zug(60, 0)[0]), sk = Math.abs(zug(0, 60)[1]);
    wahr('Beide Achsen sprechen gleich stark an',
         Math.min(wg, sk) / Math.max(wg, sk) > 0.8,
         `${wg.toFixed(0)} px waagrecht gegen ${sk.toFixed(0)} px senkrecht`);

    const a = ansicht(JOCH);
    a._drehe(80, 0);
    wahr('Die feste Blickrichtung gilt danach nicht mehr', a.ansichtKey === null);

    // Volle Fensterbreite ~ halbe Umdrehung. Die Breite ist hier gleich der
    // Gerätepixelbreite (dpr = 1), also 800.
    const b = ansicht(JOCH);
    const azB = b.kamera.az;
    b._drehe(800, 0);
    pruef('Eine volle Breite dreht um eine halbe Umdrehung',
          b.kamera.az - azB, Math.PI, 1e-9, 'rad');

    const c = ansicht(JOCH);
    c._drehe(37, 11, true);
    const r = Math.PI / 12;
    wahr('Umschalt rastet auf 15 Grad',
         Math.abs(c.kamera.az / r - Math.round(c.kamera.az / r)) < 1e-9 &&
         Math.abs(c.kamera.el / r - Math.round(c.kamera.el / r)) < 1e-9,
         `az = ${(c.kamera.az * 180 / Math.PI).toFixed(1)}°, ` +
         `el = ${(c.kamera.el * 180 / Math.PI).toFixed(1)}°`);

    const d = ansicht(JOCH);
    d._drehe(0, 1e6);
    pruef('Über den Pol hinaus geht es nicht', d.kamera.el, 1.45, 1e-12, 'rad');
    d._drehe(0, -1e6);
    pruef('Und darunter auch nicht', d.kamera.el, -1.45, 1e-12, 'rad');
  }

  // --- Finger ---------------------------------------------------------------
  // Zwei Finger sind der einzige Weg, auf einem Tablett zu zoomen. Geprüft
  // wird die Quelle: ohne die Zeigerliste gäbe es nur einen Finger, und der
  // dreht.
  {
    const q = readFileSync(join(HIER, 'js', 'render.3d.js'), 'utf8');
    wahr('Alle aufliegenden Zeiger werden geführt',
         q.includes('const zeiger = new Map()'));
    wahr('Zwei Finger kneifen und wischen', q.includes("art: 'kneifen'"));
    wahr('Hebt einer ab, wird neu angesetzt statt gesprungen',
         /zeiger\.size === 1 && griff\?\.art === 'kneifen'/.test(q));
    wahr('Der Doppeltipp kommt ohne dblclick aus',
         !q.includes("addEventListener('dblclick'") && q.includes('tippZeit'));
    wahr('Radschritte in Zeilen und Seiten werden umgerechnet',
         q.includes('inPixel') && q.includes('modus === 1'));
    wahr('Die Zeichenfläche nimmt Tastendrücke entgegen',
         q.includes('c.tabIndex = 0') && q.includes("addEventListener('keydown'"));
  }
}

// ===========================================================================
titel('28  Installierbare Fassung: Manifest, Dienstarbeiter, Dateien');

{
  const M = JSON.parse(readFileSync(join(HIER, 'manifest.webmanifest'), 'utf8'));

  wahr('Startort und Geltungsbereich liegen im eigenen Verzeichnis',
       M.start_url === './' && M.scope === './');
  wahr('Ein zweiter Aufruf holt das offene Fenster nach vorn',
       M.launch_handler?.client_mode === 'focus-existing');

  // Dateien annehmen. Der Browser fragt bei der Installation um Erlaubnis;
  // ohne den Eintrag käme die Frage gar nicht erst.
  const fh = (M.file_handlers ?? [])[0];
  wahr('JSON-Dateien werden angenommen',
       (fh?.accept?.['application/json'] ?? []).includes('.json'));
  wahr('Der Bearbeiter zeigt auf den Startort', fh?.action === './');
  wahr('Eine zweite Datei landet im selben Fenster',
       fh?.launch_type === 'single-client');

  const kurz = M.shortcuts ?? [];
  wahr('Die Sprungliste hat Einträge', kurz.length >= 3, `${kurz.length} Stück`);
  const wuensche = kurz.map((s) => new URL(s.url, 'https://x/').searchParams.get('los'));
  wahr('Jeder Eintrag trägt seinen Wunsch in der Adresse',
       wuensche.every(Boolean) && new Set(wuensche).size === wuensche.length,
       wuensche.join(', '));

  // --- Dienstarbeiter -------------------------------------------------------
  const sw = readFileSync(join(HIER, 'sw.js'), 'utf8');
  const module = readdirSync(join(HIER, 'js')).filter((n) => n.endsWith('.js'));
  wahr('Der Dienstarbeiter führt JEDES Modul aus js/',
       module.every((n) => sw.includes(`'js/${n}'`)), `${module.length} Module`);
  wahr('Manifest und Stylesheet liegen mit in der Ablage',
       sw.includes("'manifest.webmanifest'") && sw.includes("'css/style.css'"));
  wahr('Er liefert sich selbst nie aus der Ablage',
       sw.includes("endsWith('/sw.js')"));
  wahr('Er übernimmt erst auf Zuruf', sw.includes("=== 'uebernehmen'"));
  // OHNE das SORTIMENT: die Betreiberdatenbanken sind keine
  // Startvoraussetzung, sie können als Datenpaket im Browser hinterlegt sein.
  // MIT den Normwerten: seit dem 16. September stehen die Querschnittswerte
  // in data/normen.json statt im Quelltext - ohne sie rechnet nichts, und
  // anders als das Sortiment liegen sie immer bei.
  {
    const schale = sw.slice(sw.indexOf('const SCHALE'),
                            sw.indexOf('Ende erzeugter Block'));
    const daten = [...schale.matchAll(/'(data\/[^']+)'/g)].map((m) => m[1]);
    wahr('Kein Sortiment steht in der Ablageliste',
         daten.every((d) => d === 'data/normen.json'), daten.join(', '));
    wahr('Die Normwerte stehen in der Ablageliste',
         daten.includes('data/normen.json'));
  }

  // --- Modul ----------------------------------------------------------------
  const P = await import(J('pwa.js'));
  wahr('pwa.js nimmt Dateien entgegen', typeof P.dateiEmpfang === 'function');
  wahr('... reicht den Wunsch aus der Sprungliste', typeof P.startWunsch === 'function');
  wahr('... und meldet den Netzzustand', typeof P.netzZustand === 'function');
  wahr('Ohne Adresse gibt es keinen Wunsch', P.startWunsch() === null);
  wahr('Ohne Browser bricht der Netzzustand nicht ab', P.netzZustand() === false);

  const pq = readFileSync(join(HIER, 'js', 'pwa.js'), 'utf8');
  wahr('Nur echte Dateien werden hereingelassen',
       pq.includes("includes('Files')"));
  wahr('Der Browser darf die Datei nicht selbst öffnen',
       pq.includes('e.preventDefault()'));

  // --- Anwendung ------------------------------------------------------------
  const aq = APP_QUELLE();
  wahr('Die Anwendung nimmt Dateien entgegen',
       aq.includes('dateiEmpfang(dateiAnnehmen)'));
  // Fehlt die Datenbasis, steigt start() aus. Der Empfang muss VORHER stehen -
  // sonst liesse sich das Datenpaket gerade dann nicht hineinziehen, wenn es
  // gebraucht wird.
  // Der Aufruf heisst seit dem 1. September nur noch dialogDaten() - das
  // Verwalten der Datenbasis steht unter Optionen, hier bleibt der Start
  // ohne Daten.
  wahr('Und zwar bevor sie mangels Datenbasis aussteigt',
       aq.indexOf('dateiEmpfang(dateiAnnehmen)') < aq.indexOf('dialogDaten();'));
  wahr('Alle drei Dateiarten werden unterschieden',
       ['PAKET_FORMAT', 'tragjoch-ablage', 'tragjoch-stabmodell']
         .every((s) => aq.includes(s)));
  // Seit dem 17. September laeuft die Ablage ueber den Einlesedialog.
  wahr('Eingelesen wird nie ungefragt',
       aq.includes("dialog(sicherung ? 'Sicherung einspielen' : 'Einlesen'") &&
       aq.includes("dialog('Datenpaket laden'"));
  wahr('Der Wunsch aus der Sprungliste wird ausgeführt',
       aq.includes('switch (startWunsch())'));
  wahr('Auch der Fussknopf eines Dialogs schliesst ihn',
       aq.includes("querySelectorAll('[data-zu]')"));

  // --- Darstellung ----------------------------------------------------------
  const css = readFileSync(join(HIER, 'css', 'style.css'), 'utf8');
  wahr('Der Streifen der Fensterknöpfe wird freigehalten',
       css.includes('titlebar-area-x') && css.includes('titlebar-area-width'));
  wahr('Die Kopfleiste zieht das Fenster, ihre Knöpfe nicht',
       css.includes('app-region: drag') && css.includes('app-region: no-drag'));
  wahr('Eine hereingezogene Datei wird angezeigt',
       css.includes('body.datei-ueber'));

  const html = readFileSync(join(HIER, 'index.html'), 'utf8');
  wahr('Die Modulfassung verweist auf das Manifest',
       html.includes('rel="manifest"'));
}

// ===========================================================================
titel('29  Schnitt im Modell und angeschriebene Werte');

{
  const R = await import(J('render.3d.js'));

  const mitSchnitt = (orient) => {
    const w = { ...standardwerte(), schnittAktiv: true, schnittOrientierung: orient };
    const e = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch(w.typ));
    return { e, sz: R.erzeugeSzene(e.modell, e) };
  };

  // --- Was der Längsschnitt überhaupt hergibt -------------------------------
  // Er legt die Bleche EINER Ebene über die ganze Spannweite frei; das ist
  // sein Zweck. Der Querschnitt dagegen liegt an einer Stelle.
  {
    const q = mitSchnitt('quer');
    const v = mitSchnitt('vertikal');
    const h = mitSchnitt('horizontal');
    const marken = (o) => (o.sz.marken ?? []).filter((m) => m.art === 'spannung');
    const xVon = (o) => Math.min(...o.sz.schnitt.poly.map((p) => p[0]));
    const xBis = (o) => Math.max(...o.sz.schnitt.poly.map((p) => p[0]));

    wahr('Der Querschnitt liegt an einer einzigen Stelle',
         xVon(q) === xBis(q), `x = ${xVon(q).toFixed(2)} m`);
    wahr('Der Längsschnitt läuft über die ganze Spannweite',
         xVon(v) === 0 && Math.abs(xBis(v) - q.e.modell.L) < 1e-9,
         `${xVon(v).toFixed(2)} … ${xBis(v).toFixed(2)} m`);
    wahr('Beide Längsrichtungen beschriften jedes Blech ihrer Ebene',
         marken(v).length > 25 && marken(h).length > 25,
         `vertikal ${marken(v).length} · horizontal ${marken(h).length}`);
    wahr('Der Querschnitt tut das nicht - dort steht die Auswertung daneben',
         marken(q).length < marken(v).length / 4,
         `quer ${marken(q).length}`);

    // DIE ZAHL, DIE DEN FEHLER BENANNTE: auf drei Felder zugeschnitten sah
    // man sieben von dreiunddreissig Blechen. Der Ausschnitt darf sich beim
    // Längsschnitt deshalb nicht auf den Nachweisschnitt legen.
    const xN = v.sz.xNachweis;
    const halb = Math.max(1.6, (v.e.modell.a1eff ?? 0.75) * 3);
    const imFenster = marken(v)
      .filter((m) => m.p[0] >= xN - halb && m.p[0] <= xN + halb).length;
    wahr('Ein Ausschnitt von drei Feldern verdeckte die meisten davon',
         imFenster < marken(v).length / 3,
         `${imFenster} von ${marken(v).length} lägen im Fenster ±${halb.toFixed(2)} m`);
  }

  // --- Und was zeigeSchnitt daraus macht ------------------------------------
  // Geprüft wird die ENTSCHEIDUNG, nicht die Animation: die Kamerafahrten
  // brauchen requestAnimationFrame und gehören nicht in den Prüfstand.
  {
    const stand = (orient) => {
      const { sz } = mitSchnitt(orient);
      const a = Object.create(R.Modellansicht.prototype);
      a.szene = sz;
      a.ebenen = { kraefte: false, schnitt: false };
      a.kamera = { az: 0, el: 0, dist: 10, ziel: [0, 0, 0], fov: 0.6, pan: [0, 0, 0] };
      a.fokus = { von: 1, bis: 2 };            // Rest eines früheren Zooms
      a.station = 7;
      const ruf = [];
      a.zoomAuf = (x, st, breite) => { ruf.push(['zoomAuf', x, breite]);
                                       a.fokus = { von: x - breite, bis: x + breite }; };
      a.blickrichtung = (k) => { ruf.push(['blick', k]); a.fokus = null;
                                 a.station = null; a.ansichtKey = k; };
      a.zeigeSchnitt(2.13);
      return { a, ruf };
    };

    const q = stand('quer');
    wahr('Schnitt zeigen schaltet Kräfte und Ebene ein',
         q.a.ebenen.kraefte === true && q.a.ebenen.schnitt === true);
    wahr('Quer wird herangefahren und aufgetrennt',
         q.ruf[0][0] === 'zoomAuf' && q.a.fokus !== null,
         `Fenster ${q.a.fokus.von.toFixed(2)} … ${q.a.fokus.bis.toFixed(2)} m`);

    const v = stand('vertikal');
    wahr('Vertikal zeigt das GANZE Joch', v.a.fokus === null);
    wahr('... und zwar von der Seite', v.ruf[0][0] === 'blick' && v.ruf[0][1] === 'laengs');
    wahr('Eine hervorgehobene Station wird dabei aufgehoben', v.a.station === null);

    const h = stand('horizontal');
    wahr('Horizontal zeigt das ganze Joch von oben',
         h.a.fokus === null && h.ruf[0][1] === 'oben');

    // Der Feldschieber ruft bei jedem Schritt herein. Beim Längsschnitt
    // ändert er nur die Stelle der Auswertung - das Bild steht schon richtig,
    // und ein zweiter Schwenk risse es dem Betrachter unter der Hand weg.
    v.a.zeigeSchnitt(2.13);
    wahr('Ein zweiter Aufruf schwenkt nicht noch einmal',
         v.ruf.length === 1, `${v.ruf.length} Kamerafahrt(en)`);
    // Hat er sich hingegen etwas herangeholt, wird wieder eingerichtet.
    v.a.fokus = { von: 9, bis: 12 };
    v.a.zeigeSchnitt(2.13);
    wahr('Nach einem Zoom auf eine Stelle schon', v.ruf.length === 2);
  }

  // --- Werte anschreiben: nichts halb Geschriebenes -------------------------
  // Eine am Bildrand abgeschnittene 118 liest sich als 18. Eine halbe Zahl
  // ist schlimmer als keine.
  {
    const a = Object.create(R.Modellansicht.prototype);
    a.cv = { width: 800, height: 600 };
    a._s = 1;
    a.schriftLast = 10;
    a._breiten = new Map();
    const c = { font: '10px x', measureText: (s) => ({ width: s.length * 6 }) };

    wahr('Mitten im Bild wird angeschrieben', a._imBild(c, '118', 400, 300));
    wahr('Am linken Rand nicht mehr', !a._imBild(c, '118', 1, 300));
    wahr('Am rechten Rand auch nicht', !a._imBild(c, '118', 790, 300));
    wahr('Und oben und unten ebenso wenig',
         !a._imBild(c, '118', 400, 4) && !a._imBild(c, '118', 400, 599));
    // Eine kurze Zahl passt noch, wo eine lange nicht mehr passt.
    wahr('Der Platzbedarf richtet sich nach der Zahl',
         a._imBild(c, '1', 770, 300) && !a._imBild(c, '130.25', 770, 300));
  }

  // --- Die Rangfolge der Beschriftungen -------------------------------------
  // Vier Zeichengaenge schreiben ins Bild. Bemassung und Marken gewinnen,
  // Pfeiltexte und Werte weichen aus - so hat es der Auftraggeber festgelegt.
  // Frueher fuehrte jeder Gang eine eigene Freihalteliste und schrieb den
  // anderen quer darueber.
  {
    const q = readFileSync(join(HIER, 'js', 'render.3d.js'), 'utf8');
    // Die Reihenfolge im Bildaufbau IST die Rangfolge: wer zuerst zeichnet,
    // belegt zuerst. Steht _texte nicht hinter _marken und _masse, kann es
    // ihnen gar nicht ausweichen.
    const i = (s) => q.indexOf(s, q.indexOf('_lastflaechen(c, proj, t)'));
    wahr('Die Pfeile werden vor den Marken gezeichnet',
         i('this._vektoren(c, proj, t)') < i('this._marken(c, proj, t)'));
    wahr('Die freien Texte kommen NACH Marken und Bemassung',
         i('this._texte(c, t)') > i('this._marken(c, proj, t)') &&
         i('this._texte(c, t)') > i('this._masse(c, proj, t)'));
    wahr('Die Pfeilbeschriftung zeichnet nicht mehr selbst',
         q.includes('this._pfeiltexte.push('));

    // Und die Wirkung: ein belegter Platz nimmt Pfeiltext wie Wert auf.
    const bau = () => {
      const a = Object.create(R.Modellansicht.prototype);
      a.cv = { width: 800, height: 600 };
      a._s = 1; a.schriftLast = 10; a._breiten = new Map();
      a._font = () => '10px mono';
      a._belegt = [];
      a.gruppen = { resultate: false };
      a.werteAnschreiben = false;
      a.gezeichnet = [];
      a._beschriftung = (c, t, text) => a.gezeichnet.push(text);
      a._pfeiltexte = [{ text: 'F_z = 1.30 kN', x: 400, y: 300, farbe: '#fff' },
                       { text: 'F_y = 0.91 kN', x: 400, y: 340, farbe: '#fff' }];
      return a;
    };
    const c2 = { font: '10px mono', measureText: (s) => ({ width: s.length * 6 }) };

    const frei = bau();
    frei._texte(c2, {});
    pruef('Auf freiem Grund stehen beide Pfeiltexte',
          frei.gezeichnet.length, 2, 1e-12, 'Stk');

    const eng = bau();
    // Dort, wo der erste Pfeiltext hinwollte, steht schon eine Masszahl.
    eng._belegt.push({ x: 395, y: 290, w: 60, h: 14 });
    eng._texte(c2, {});
    wahr('Wo eine Masszahl steht, weicht der Pfeiltext',
         eng.gezeichnet.length === 1 && eng.gezeichnet[0] === 'F_y = 0.91 kN',
         eng.gezeichnet.join(' | '));
    pruef('Der gesetzte Text belegt seinerseits einen Platz',
          eng._belegt.length, 2, 1e-12, 'Eintraege');
  }
}

// ===========================================================================
titel('30  Hauptschalter der Werkzeuggruppen');

{
  const R = await import(J('render.3d.js'));

  const sicht = (ebenen, gruppen) => {
    const a = Object.create(R.Modellansicht.prototype);
    a.ebenen = { profil: true, blech: true, anbau: true, achse: true,
                 last: true, kraefte: true, masse: true, schnitt: true,
                 raster: true, marken: true, auflager: true, ...ebenen };
    a.gruppen = { modell: true, lasten: true, resultate: true, ...gruppen };
    return a;
  };

  // Aus heisst AUS: der Hauptschalter nimmt die ganze Gruppe aus dem Bild.
  // Vorher fragten nur die Pfeile danach - die Volumenkoerper und die
  // Lastflaechen nicht. «Lasten aus» liess Wind und Schnee stehen.
  {
    const a = sicht({}, { lasten: false });
    wahr('Lasten aus nimmt die Lastebene mit', !a._ebeneAn('last'));
    wahr('... laesst das Joch aber stehen',
         a._ebeneAn('profil') && a._ebeneAn('blech'));
    wahr('... und die Resultate auch', a._ebeneAn('kraefte'));
  }
  {
    const a = sicht({}, { modell: false });
    wahr('Modell aus nimmt Gurte, Bleche, Achsen und Bemassung mit',
         ['profil', 'blech', 'achse', 'auflager', 'masse', 'raster']
           .every((k) => !a._ebeneAn(k)));
    wahr('... laesst die Lasten stehen', a._ebeneAn('last'));
  }
  {
    const a = sicht({}, { resultate: false });
    wahr('Resultate aus nimmt Schnittkraefte und Schnittebene mit',
         !a._ebeneAn('kraefte') && !a._ebeneAn('schnitt'));
    wahr('... laesst Joch und Lasten stehen',
         a._ebeneAn('profil') && a._ebeneAn('last'));
  }
  {
    const a = sicht({}, { modell: false, lasten: false, resultate: false });
    wahr('Alle drei aus laesst nichts uebrig',
         ['profil', 'blech', 'achse', 'auflager', 'masse', 'raster',
          'last', 'kraefte', 'schnitt'].every((k) => !a._ebeneAn(k)));
  }

  // Der Einzelschalter behaelt das letzte Wort in die andere Richtung.
  wahr('Ein ausgeschalteter Einzelschalter bleibt aus, auch wenn die Gruppe an ist',
       !sicht({ blech: false }, {})._ebeneAn('blech'));
  // Und was keinen Hauptschalter ueber sich hat, folgt nur sich selbst.
  wahr('Ebenen ohne Gruppe folgen allein ihrem Einzelschalter',
       sicht({}, { modell: false, lasten: false, resultate: false })
         ._ebeneAn('marken'));

  // Damit die Tabelle ueberhaupt greift, muessen die Lastflaechen der Szene
  // die Gruppe 'last' tragen - sonst zielte der Schalter ins Leere.
  {
    const w = standardwerte();
    const e = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch(w.typ));
    const sz = R.erzeugeSzene(e.modell, e);
    const fl = sz.lastflaechen ?? [];
    wahr('Es gibt Lastflaechen', fl.length > 0, `${fl.length} Stueck`);
    wahr('Und alle tragen die Gruppe der Lasten',
         fl.every((f) => f.gruppe === 'last'),
         [...new Set(fl.map((f) => f.lastart))].join(', '));
  }

  // --- Anbauteile sind Tragwerk, nicht Last --------------------------------
  // Wer die Lasten global abstellt, um das Joch zu sehen, will den WEG
  // behalten, auf dem die Last hereinkommt: Staender, Ausleger, Traverse.
  // Nur was die Last selbst darstellt, geht mit ihr.
  {
    const teile = ['ja-einfach', 'hs-nt-ausleger', 'leiter-traverse']
      .map((id, i) => A.neuesAnbauteil(id, 5 + i * 5));
    const w = { ...standardwerte(), anbauteile: teile };
    const e = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch(w.typ));
    const sz = R.erzeugeSzene(e.modell, e);

    const at = (sz.flaechen ?? []).filter((f) => f.anbauteil);
    const koerper = at.filter((f) => !f.punkt);
    const punkte = at.filter((f) => f.punkt);
    wahr('Die Baugruppen stehen im Modell', koerper.length > 50 && punkte.length > 0,
         `${koerper.length} Koerper- und ${punkte.length} Angriffspunktflaechen`);
    wahr('Der KOERPER liegt in der eigenen Ebene anbau',
         koerper.every((f) => f.gruppe === 'anbau'));
    wahr('Der Wuerfel am Angriffspunkt bleibt bei den Lasten',
         punkte.every((f) => f.gruppe === 'last'));

    const mk = (art) => (sz.marken ?? []).filter((m) => m.art === art);
    wahr('Die Positionsnummer gehoert zum Bauteil',
         mk('anbau').length > 0 && mk('anbau').every((m) => m.gruppe === 'anbau'),
         `${mk('anbau').length} Nummern`);
    wahr('Der Lastknoten gehoert zur Last',
         mk('lastknoten').length > 0 &&
         mk('lastknoten').every((m) => m.gruppe === 'last'),
         `${mk('lastknoten').length} Knoten`);

    // Und die Wirkung am Schalter
    const a1 = sicht({}, { lasten: false });
    wahr('Lasten aus laesst die Anbauteile stehen', a1._ebeneAn('anbau'));
    wahr('... nimmt aber ihre Lastdarstellung mit', !a1._ebeneAn('last'));
    const a2 = sicht({}, { modell: false });
    wahr('Modell aus nimmt sie mit - sie sind Tragwerk', !a2._ebeneAn('anbau'));
    wahr('Sie lassen sich auch einzeln abschalten',
         !sicht({ anbau: false }, {})._ebeneAn('anbau'));

    const aq = APP_QUELLE();
    const wz = aq.slice(aq.indexOf('const WZ_MODELL'), aq.indexOf('const WZ_LASTEN'));
    wahr('Der Schalter steht in der Gruppe Modell', wz.includes("key: 'anbau'"));
  }

  // --- Die drei Listen muessen zusammenpassen ------------------------------
  // Eine Ebene, die in HAUPTSCHALTER steht, aber keinen Anfangswert in
  // this.ebenen hat, ist von Anfang an unsichtbar - _ebeneAn liest undefined
  // und antwortet nein. Genau daran ist die Prüfung oben zuerst gescheitert,
  // wenn auch nur in ihrem eigenen Nachbau. Also beide Listen vergleichen.
  {
    const q = readFileSync(join(HIER, 'js', 'render.3d.js'), 'utf8');
    /*
     * KOMMENTARE ZUERST WEG.
     *
     * Gelesen wird mit einem Muster «Wort: kleinbuchstabe» - und genau so
     * sieht ein deutscher Satz aus. Ein Kommentar mit «Gruppe: sie kommen
     * von aussen» erzeugte prompt eine Ebene namens `Gruppe`, die es nie
     * gab, und der Pruefstand meldete einen Fehler in seiner eigenen
     * Messung. Prosa ist kein Quelltext.
     */
    const ausBlock = (von, bis) => {
      const a = q.indexOf(von);
      const s = q.slice(a, q.indexOf(bis, a)).replace(/\/\/.*/g, '');
      return new Set([...s.matchAll(/(\w+):\s*['a-z]/g)].map((m) => m[1]));
    };
    const haupt = ausBlock('const HAUPTSCHALTER = {', '};');
    const vorgabe = ausBlock('this.ebenen = {', '};');
    const fehlt = [...haupt].filter((k) => !vorgabe.has(k));
    wahr('Jede Ebene mit Hauptschalter hat auch einen Anfangswert',
         fehlt.length === 0, fehlt.length ? `fehlt: ${fehlt.join(', ')}` :
         `${haupt.size} Ebenen unter vier Gruppen`);
  }

  /*
   * DAS ACHSENKREUZ MUSS UEBER DER FUSSLEISTE BLEIBEN.
   *
   * Gemeldet vom Auftraggeber: die Systemachsen werden verdeckt. Ursache war
   * eine Aenderung an ganz anderer Stelle - der Knopf "Ganzes Joch zeigen"
   * wanderte in die Fussleiste, und die wuchs damit von 36 auf 46 px. Der
   * Ursprung des Kreuzes stand bei genau 46 px ueber dem Rand, also auf ihrer
   * Oberkante; jeder nach unten zeigende Arm lag darunter.
   *
   * Zwei Zahlen in zwei Dateien, die zusammengehoeren und nichts voneinander
   * wissen. Also hier nachgerechnet: die Leistenhoehe aus dem Stylesheet
   * (Rand + Knopf + Rand) gegen die Konstante im Zeichner.
   */
  {
    const css = readFileSync(join(HIER, 'css', 'style.css'), 'utf8');
    const r3d = readFileSync(join(HIER, 'js', 'render.3d.js'), 'utf8');
    const zahl = (quelle, muster) => {
      const m = quelle.match(muster);
      return m ? parseFloat(m[1]) : NaN;
    };
    const fussRand = zahl(css, /\.viewer-fuss\s*\{[^}]*padding:\s*(\d+)px/);
    const knopf = zahl(css, /\.btn-icon\s*\{[^}]*height:\s*(\d+)px/);
    const arm = zahl(r3d, /const ACHSENKREUZ_ARM = (\d+);/);
    const hoch = zahl(r3d, /const ACHSENKREUZ_HOCH = (\d+);/);
    wahr('Die Masse lassen sich alle vier lesen',
         [fussRand, knopf, arm, hoch].every(Number.isFinite),
         `Rand ${fussRand}, Knopf ${knopf}, Arm ${arm}, Hoehe ${hoch}`);
    // Die Leiste: Rand oben + Knopf + Rand unten.
    const leiste = 2 * fussRand + knopf;
    pruef('Die Fussleiste ist so hoch wie gemessen', leiste, 46, 1e-9, 'px');
    // Darunter darf nichts vom Kreuz liegen: Ursprung + Arm + eine Zeile.
    const noetig = leiste + arm + 12;
    wahr('Das Achsenkreuz steht hoch genug ueber der Fussleiste',
         hoch >= noetig, `${hoch} px gegen mindestens ${noetig} px`);
    // Und nicht so hoch, dass es im Bild schwebt - eine Armlaenge Luft genuegt.
    wahr('Aber nicht unnoetig weit oben', hoch <= noetig + arm,
         `${hoch} px gegen hoechstens ${noetig + arm} px`);
  }

}

// ===========================================================================
titel('31  Bewegung: nichts springt');

{
  const css = readFileSync(join(HIER, 'css', 'style.css'), 'utf8');
  const aq = APP_QUELLE();

  // --- Wer keine Bewegung will, bekommt keine ------------------------------
  wahr('Das Stylesheet achtet auf «Bewegung reduzieren»',
       css.includes('prefers-reduced-motion: reduce'));
  // Und zwar auf einen Wimpernschlag, NICHT auf null: bei 0s faellt in
  // manchen Browsern das Ereignis transitionend aus, an dem weich() in
  // app.js haengt - der Bereich bliebe dann in der Klasse «animiert» stehen.
  const block = css.slice(css.indexOf('prefers-reduced-motion'));
  wahr('Abgeschaltet wird auf .01ms, nicht auf null',
       block.includes('transition-duration: .01ms') &&
       block.includes('animation-duration: .01ms'));

  // --- Dialoge: erst fahren, dann wegraeumen -------------------------------
  wahr('Der Dialog wird erst nach der Schliessbewegung geleert',
       aq.includes('DIALOG_ZU_MS') && /setTimeout\([\s\S]{0,200}innerHTML = ''/.test(aq));
  wahr('Ein zweiter Dialog wird dabei nicht mitgerissen',
       aq.includes('dialogLauf !== meins'));

  // Die Dauer steht an zwei Orten - im Skript und im Stylesheet. Laufen sie
  // auseinander, raeumt das Skript zu frueh weg (Sprung) oder zu spaet
  // (Hänger). Also vergleichen.
  const ms = (re, txt, f = 1) => {
    const m = txt.match(re);
    return m ? Math.round(parseFloat(m[1]) * f) : null;
  };
  const jsDialog = ms(/DIALOG_ZU_MS = (\d+)/, aq);
  const cssDialog = ms(/animation: dialog-zu \.(\d+)s/, css, 10);
  pruef('Dialog: Skript und Stylesheet nennen dieselbe Dauer',
        jsDialog, cssDialog, 1e-9, 'ms');

  const jsSchub = ms(/SCHUBLADE_ZU_MS = (\d+)/, aq);
  const cssSchub = ms(/animation: schublade-zu \.(\d+)s/, css, 10);
  pruef('Schublade: dieselbe Dauer an beiden Orten',
        jsSchub, cssSchub, 1e-9, 'ms');

  wahr('Die Schublade faehrt auch zu, nicht nur auf',
       css.includes('@keyframes schublade-zu') &&
       aq.includes('function schubladeZufahren'));
  wahr('Ein Wiederaufmachen bricht das Zufahren ab',
       aq.includes("n.classList.remove('zu');      // falls sie noch am Zufahren war"));

  // --- Was NICHT gefahren werden darf --------------------------------------
  // Ein η, das von 0.58 auf 1.33 hochzaehlt, zeigt unterwegs Werte, die nie
  // gerechnet wurden. Bewegt wird die Farbe, nie die Ziffer.
  const pille = css.slice(css.indexOf('.schiene-nw b, .schiene-nw i'));
  wahr('An den Nachweispillen laeuft nur die Farbe',
       /\.schiene-nw b, \.schiene-nw i \{ transition: color/.test(pille));
  wahr('Der Vermerk dazu steht im Stylesheet',
       css.includes('ZAHLEN WERDEN NICHT GEFAHREN'));

  // --- Der Unterstrich der Reiter ------------------------------------------
  wahr('Der Reiter-Unterstrich laeuft mit',
       /\.tab \{ transition:[^}]*border-bottom-color/.test(css));

  // --- Das Schnittblatt: Bedienung bleibt, Zahlen erneuern sich ------------
  // Dieselbe Ursache wie beim Lastfall-Waehler: die Bedienung rechnet, das
  // Rechnen zeichnet das Blatt neu, und der bediente Knoten war weg. Am
  // Schieber riss das den Zug ab, an der Auswahlliste blinkte es.
  {
    const uq = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    const f = uq.slice(uq.indexOf('export function zeichneSchnitt'));
    const ende = f.indexOf('export function', 20);
    const fn = ende > 0 ? f.slice(0, ende) : f;
    wahr('Das Blatt ist in Bedienung und Zahlen geteilt',
         fn.includes('id="schnitt-steuerung"') && fn.includes('id="schnitt-zahlen"'));
    wahr('Neu gebaut wird die Bedienung nur bei geaenderter Struktur',
         fn.includes("st.dataset.sig !== sig"));
    wahr('Die Struktur ist Feldzahl und Orientierungsliste',
         /const sig = JSON\.stringify\(\[sn\.anzahlSchnitte/.test(fn));
    // Verdrahtet wird nur beim Aufbau - sonst haengen nach zehn Rechnungen
    // zehn Zuhoerer am selben Schieber.
    const zweig = fn.slice(fn.indexOf('if (!st ||'), fn.indexOf('} else {'));
    wahr('Verdrahtet wird nur beim Aufbau',
         zweig.includes("addEventListener('change'") &&
         zweig.includes("addEventListener('input'"));
    wahr('Sonst werden nur die Werte nachgezogen',
         fn.includes("setze('#schnitt-orient', 'value', orient)"));
  }

  // --- Die Fahrt der Bereiche ----------------------------------------------
  // Zwei Fehler steckten darin: die Flaeche blitzte leer durch, und das
  // Modell zoomte, statt sich nur zu verschieben.
  {
    const rq = readFileSync(join(HIER, 'js', 'render.3d.js'), 'utf8');
    const fn = rq.slice(rq.indexOf('  passeGroesseAn() {'));
    const ende = fn.indexOf(String.fromCharCode(10) + '  }');
    const gr = fn.slice(0, ende);

    // cv.width zu setzen leert die Flaeche. Wird erst im naechsten Bild
    // gezeichnet, liegt dazwischen ein fertiges Bild mit leerem Grund -
    // gemessen: 12 Groessenwechsel, 12 leere Bilder.
    wahr('Nach der neuen Groesse wird SOFORT gezeichnet',
         gr.includes('cancelAnimationFrame(this._angefordert)') &&
         gr.trimEnd().endsWith('this._male();'));
    // Und nicht mehr eingepasst: der Massstab haengt allein an der Hoehe,
    // eine schmalere Flaeche gibt also weniger frei, statt zu zoomen.
    wahr('Eingepasst wird nur beim ersten Mal',
         gr.includes('this._ersteGroesse !== false') &&
         // Nur der Aufruf zaehlt, nicht das Wort im Kommentar daneben.
         (gr.match(/this\.passeEin\(\);/g) || []).length === 1);
    wahr('Eine Folge von Schritten wird erkannt',
         gr.includes('this.sparsam = jetzt - (this._letzteGroesse'));
    wahr('Und das volle Bild kommt danach nach',
         gr.includes('this.sparsam = false;') && gr.includes('this.zeichne();'));

    // Sparsam heisst: keine Koerper, keine Beschriftungen - die Achsen
    // tragen dieselben Kennwerte und dieselbe Einfaerbung.
    wahr('Sparsam werden die Koerper weggelassen',
         rq.includes('if (!this.sparsam) this.szene.flaechen.forEach('));
    wahr('... und die Beschriftungen auch',
         /if \(!this\.sparsam\) \{[\s\S]{0,220}this\._texte\(c, t\);/.test(rq));
    wahr('Die Achsen vertreten sie fuer die Dauer der Fahrt',
         rq.includes("if (this.sparsam || this._ebeneAn('achse')"));
    // Der HAUPTSCHALTER gilt aber weiter - sonst erschiene ein abgeschaltetes
    // Modell waehrend der Fahrt wieder.
    wahr('Der Hauptschalter gilt auch im sparsamen Bild',
         rq.includes('if (this.sparsam) { if (!this.gruppen.modell) return; }'));
  }

  // --- Die verschiebbare Karte --------------------------------------------
  // Waehrend der Fahrt Versatz statt left/top, und hoechstens ein Schreiben
  // je Bild. Beides zusammen ist der Unterschied zwischen Ziehen und Ruckeln.
  {
    const zieh = aq.slice(aq.indexOf('function verdrahteLegendeZiehen'),
                          aq.indexOf('/** Gemerkte Lage der Legende'));
    wahr('Gezogen wird ueber den Versatz', zieh.includes('translate3d('));
    wahr('Geschrieben wird hoechstens einmal je Bild',
         zieh.includes('requestAnimationFrame(male)') &&
         zieh.includes('if (angefordert)'));
    wahr('Festgeschrieben wird erst am Schluss',
         zieh.indexOf('translate3d(') < zieh.lastIndexOf('n.style.left ='));
    wahr('Ein blosser Klick loest die Karte nicht aus der Ecke',
         zieh.includes('if (!bewegt) return;'));
    wahr('Abgebrochene Zeiger raeumen mit auf',
         zieh.includes("'pointercancel', ende"));
    wahr('Die Ankuendigung an den Compositor gilt nur waehrend der Fahrt',
         css.includes('.legende.zieht') && css.includes('will-change: transform') &&
         zieh.includes("n.classList.remove('zieht')"));
  }
}

// ===========================================================================
titel('32  Anbauteile als Kette: Ausleger auf der Stuetze, Kettenwerk am Ausleger');

{
  const AX = await import(J('export.axisvm.js'));
  const kern = await import(J('core.anbauteile.js'));

  const bau = (vorlage, x = 10) => {
    const w = { ...standardwerte(), anbauteile: [A.neuesAnbauteil(vorlage, x)] };
    const e = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch(w.typ));
    const b = AX.stabmodell(e.modell, { knotenmodell: 'anschnitt', eingabe: w });
    return { b, arme: b.staebe.filter((s) => /^ARM\d+_\d+$/.test(s.name)) };
  };

  // --- Die Rollen sagen, was auf was sitzt ---------------------------------
  {
    const at = A.neuesAnbauteil('hs-nt-ausleger', 10);
    const flach = A.expandiereAnbauteile([at], { ek: 'EK2' });
    const rollen = flach.map((f) => f.rolle);
    wahr('Die Vorlage nennt Traeger, Aufbau und Drahtwerk',
         rollen.includes('traeger') && rollen.includes('aufbau') &&
         rollen.includes('drahtwerk'), rollen.join(' -> '));
    wahr('Alle Teile gehoeren derselben Baugruppe',
         new Set(flach.map((f) => f.baugruppe)).size === 1);
  }

  // --- Und daraus wird eine Kette, kein Stern ------------------------------
  // Vorher gruppierte die Ausleitung nach KOORDINATEN. Module derselben
  // Baugruppe auf verschiedenen Hoehen fielen damit auseinander, und jedes
  // Stueck hing einzeln am Joch - im AxisVM deutlich zu sehen.
  {
    /*
     * DER NT-AUSLEGER IST EIN KRAGARM (Weisung des Auftraggebers):
     * sein Angriffspunkt liegt 1.2 m in Jochachse versetzt, das Kettenwerk
     * haengt am Ende bei 2.4 m. Die halbe Windlast in Gleisrichtung geht auf
     * den Anschlusspunkt Ausleger/Stuetze zurueck, der Rest ins Kettenwerk.
     * Die Kette hat deshalb VIER Glieder, und die letzten beiden liegen
     * waagrecht.
     */
    const { b, arme } = bau('hs-nt-ausleger');
    const kn = (n) => b.knoten.get(n);
    pruef('Vier Glieder: Stuetze, Anschluss, Kragarm, Kettenwerk',
          arme.length, 4, 1e-12, 'Stk');

    wahr('Das erste Glied haengt am Gurtanschluss', /^AT\d+_(OG|UG)$/.test(arme[0].von),
         arme[0].von);
    wahr('Jedes weitere haengt am vorigen - eine Reihe, kein Stern',
         arme.every((s, i) => i === 0 || s.von === arme[i - 1].bis),
         arme.map((s) => `${s.von}->${s.bis}`).join(' '));
    wahr('Kein Glied hat Laenge null',
         arme.every((s) => {
           const p = kn(s.von), q = kn(s.bis);
           return Math.hypot(q.x - p.x, q.y - p.y, q.z - p.z) > 1e-9;
         }));

    // Der Kragarm steht in JOCHACHSE aus - das ist der ganze Punkt.
    const spitze = kn(arme[3].bis), wurzel = kn(arme[1].bis);
    // 2.50 m seit der Weisung vom 28. August (vorher 2.40 m).
    pruef('Das Kettenwerk haengt 2.50 m ausserhalb', spitze.x - wurzel.x,
          2.5, 1e-9, 'm');
    pruef('Der Ausleger selbst greift auf halbem Weg an',
          kn(arme[2].bis).x - wurzel.x, 1.25, 1e-9, 'm');
    wahr('Und die beiden liegen auf gleicher Hoehe',
         Math.abs(spitze.z - wurzel.z) < 1e-9);

    pruef('Vier Lastpunkte: drei Teile plus der Windanteil',
          b.arme.length, 4, 1e-12, 'Stk');
  }

  // --- Der Jochaufsatz sitzt OBEN, die Kette laeuft hinauf -----------------
  {
    const { b, arme } = bau('ja-einfach');
    const kn = (n) => b.knoten.get(n);
    wahr('Beim Aufsatz steigt die Kette',
         arme.every((s) => kn(s.bis).z > kn(s.von).z),
         arme.map((s) => kn(s.bis).z.toFixed(2)).join(' -> '));
  }

  // --- Wo die Daten keine Kette nennen, wird keine erfunden ---------------
  {
    const { arme } = bau('leiter-traverse');
    pruef('Ein einzelnes Teil ergibt ein Glied', arme.length, 1, 1e-12, 'Stk');
  }

  // --- Ein Lastschalter formt keine Geometrie -----------------------------
  /*
   * Die Kette verbindet LASTPUNKTE, und ein Lastpunkt liegt im SCHWERPUNKT
   * seines Bauteils - nicht an dessen Ende. Zwischen Haengestuetze (-1.35 m)
   * und Ausleger (-2.70 m, 1.5 m aussen) lief deshalb eine Diagonale quer
   * durch den Raum, wo in Wirklichkeit die Stuetze senkrecht hinunterlaeuft
   * und der Ausleger dort waagrecht ansetzt.
   *
   * Aufgefallen ist es an einem Schalter, der damit nichts zu tun hat: bei
   * eingeschaltetem «Fahrleitung als Auflager» entsteht ein Hilfspunkt auf
   * der Stuetzenachse, und der lag zufaellig im Knick. Die Kette sah richtig
   * aus - und fiel in sich zusammen, sobald man den Schalter loeste.
   */
  ['hs-nt-ausleger', 'ausleger-rohr'].forEach((id) => {
    const kette = (an) => {
      const at = { ...A.neuesAnbauteil(id, 10), windAufTraeger: an };
      const flach = A.expandiereAnbauteile([at], { ek: 'EK2', R: 3e5, spannweite: 50 });
      const k = kern.anbauKette(flach, { x0: 10, zAn: 0 });
      return k.glieder.map((g) => `${g.von.x},${g.von.y},${g.von.z}`
                                + ` -> ${g.bis.x},${g.bis.y},${g.bis.z}`).join(' | ');
    };
    const ein = kette(true), aus = kette(false);
    wahr(`${id}: der Lastschalter formt die Kette nicht um`, ein === aus,
         ein === aus ? `${ein.split('|').length} Glieder` : `EIN ${ein}   AUS ${aus}`);
    // DIE EIGENSCHAFT, die den Knick ausmacht: jedes Glied laeuft entlang
    // EINER Achse. Eine Diagonale aendert zwei Koordinaten gleichzeitig -
    // genau das war der falsche Weg quer durch den Raum.
    const at = { ...A.neuesAnbauteil(id, 10), windAufTraeger: false };
    const flach = A.expandiereAnbauteile([at], { ek: 'EK2', R: 3e5, spannweite: 50 });
    const k = kern.anbauKette(flach, { x0: 10, zAn: 0 });
    const schraeg = k.glieder.filter((g) =>
      [g.bis.x - g.von.x, g.bis.y - g.von.y, g.bis.z - g.von.z]
        .filter((d) => Math.abs(d) > 1e-9).length > 1);
    wahr(`${id}: jedes Glied laeuft entlang einer Achse`, schraeg.length === 0,
         schraeg.map((g) => `(${g.von.x},${g.von.z})->(${g.bis.x},${g.bis.z})`).join(' '));
  });

  // --- Beide Ausleger sind Kragarme, und beide haengen an der Stuetze ------
  /*
   * WEISUNG DES AUFTRAGGEBERS. Der NT-Ausleger steht 1.2 m aus, sein
   * Kettenwerk haengt am Ende bei 2.4 m; beim Rohrausleger sind es 1.5 m und
   * 3.0 m. Beide sind an einer HAENGESTUETZE befestigt und stuetzen das
   * Kettenwerk - hierarchisch gleich aufgebaut.
   *
   * Geprueft wird die VORLAGE, nicht eine Zahl im Code: die Daten sind
   * massgebend, und eine Vorlage, die den Traeger verliert oder den Versatz,
   * faellt hier auf.
   */
  {
    /*
     * WEISUNG DES AUFTRAGGEBERS, 28. August: "die nt und roehrausleger mit
     * laenge in x von 2.50 m als voreinstellwert".
     *
     * Beide Ausleger reichen jetzt gleich weit; das Kettenwerk haengt am
     * ENDE, das Eigengewicht des Auslegers greift auf HALBER Laenge an. Vor
     * der Weisung waren es 2.4 m (NT) und 3.0 m (Rohr).
     *
     * Die Zahlen stehen in data/anbauteile.json - hier steht nur, was daraus
     * folgen muss. Der Pruefstand hat die Aenderung denn auch gemeldet, und
     * genau dafuer ist er da.
     */

  /*
   * DIE LAENGE EINES STRECKENTEILS STEHT IM FELD, nicht in einem stillen
   * Rueckfall.
   *
   * Weisung des Auftraggebers, 28. August: "die laenge kann den startwert von
   * 1.00 m haben" - fuer die Auslegerkonsolen, die zwischen 0.50 und 2.00 m
   * lang sind.
   *
   * Vorher stand das Laengenfeld LEER da, und gerechnet wurde trotzdem: mit
   * einem Meter aus `m.laenge ?? 1` in expandiereAnbauteile. Die Zahl war
   * also immer da, nur nicht zu sehen - und ein leeres Feld liest sich wie
   * "noch nicht angegeben", nicht wie "einen Meter".
   */
  {
    const FL = await import(J('data.fl.js'));
    const strecke = 'anbauteil-auslegerkonsole';
    const stueck = 'anbauteil-ausleger-typ-nt';
    wahr('Die Konsole rechnet je Meter',
         FL.istStreckenlast(FL.getFlBauteil(strecke)) === true);
    wahr('Der NT-Ausleger nicht',
         FL.istStreckenlast(FL.getFlBauteil(stueck)) === false);

    pruef('Ein neues Streckenteil bringt seine Laenge mit',
          A.neuesModul(strecke).laenge, 1.0, 1e-12, 'm');
    wahr('Ein Stueckteil bekommt keine',
         A.neuesModul(stueck).laenge === null);
    // Ein unbekanntes Bauteil darf nicht werfen - die Maske baut Module auf,
    // bevor die Datenbank vollstaendig ist.
    wahr('Ein unbekanntes Bauteil bleibt ohne Laenge',
         A.neuesModul('gibt-es-nicht').laenge === null);

    /*
     * UND DIE ZAHL WIRKT AUCH. Die Konsole traegt 0.25 kN/m Eigengewicht;
     * bei einem Meter ist das 0.25 kN, bei zweien das Doppelte. Waere die
     * Laenge blosse Anzeige, staende hier zweimal dasselbe.
     */
    const last = (laenge) => {
      const at = { id: 'K', name: 'Konsole', x: 5, raster: 0, aktiv: true,
                   module: [{ bauteil: strecke, anzahl: 1, laenge, z: -1.5, y: 0 }] };
      const f = A.expandiereAnbauteile([at], { ek: 'EK2', R: 3e5, spannweite: 50 });
      return f.reduce((sum, t) => sum + Math.abs(t.kraefte?.G?.Fz ?? 0), 0);
    };
    const eins = last(1.0);
    pruef('Ein Meter Konsole wiegt, was die Tabelle sagt', eins, 0.25, 1e-9, 'kN');
    pruef('Zwei Meter wiegen doppelt', last(2.0), 2 * eins, 1e-9, 'kN');
    // Der Rueckfall fuer alte Baugruppen nennt dieselbe Zahl wie der Startwert.
    pruef('Ohne Angabe gilt derselbe eine Meter', last(null), eins, 1e-12, 'kN');
    pruef('Und der Standard steht als Zahl da', A.LAENGE_STANDARD, 1.0, 1e-12, 'm');
  }

    const kragarme = [
      { id: 'hs-nt-ausleger', aufbau: 1.25, draht: 2.5 },
      { id: 'ausleger-rohr', aufbau: 1.25, draht: 2.5 },
    ];
    kragarme.forEach((k) => {
      const at = A.neuesAnbauteil(k.id, 10);
      const flach = A.expandiereAnbauteile([at], { ek: 'EK2', R: 3e5, spannweite: 50 });
      const rollen = flach.map((x) => x.rolle);
      const je = (r) => flach.filter((x) => x.rolle === r && x.art !== 'windversatz')[0];

      wahr(`${k.id}: haengt an einer Haengestuetze`,
           rollen.includes('traeger'), rollen.join(' -> '));
      pruef(`${k.id}: der Ausleger steht aus`,
            je('aufbau').x - je('traeger').x, k.aufbau, 1e-9, 'm');
      pruef(`${k.id}: das Kettenwerk haengt am Ende`,
            je('drahtwerk').x - je('traeger').x, k.draht, 1e-9, 'm');
      wahr(`${k.id}: die halbe Windlast geht auf den Anschluss zurueck`,
           at.windAufTraeger === true && at.windAnteil === 50);

      // Und daraus wird eine REIHE: jedes Glied haengt am vorigen.
      const w = { ...standardwerte(), anbauteile: [at] };
      const e = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                         getStahl(w.stahl), T.getTragjoch(w.typ));
      const b = AX.stabmodell(e.modell, { knotenmodell: 'anschnitt', eingabe: w });
      const arme = b.staebe.filter((s) => /^ARM\d+_\d+$/.test(s.name));
      wahr(`${k.id}: die Kette ist eine Reihe`,
           arme.every((s, i) => i === 0 || s.von === arme[i - 1].bis),
           arme.map((s) => s.name).join(' '));
      // Der aeusserste Punkt ist das Kettenwerk - nicht der Hilfspunkt des
      // Windversatzes, der auf der Achse der Stuetze sitzt.
      const letzte = b.knoten.get(arme[arme.length - 1].bis);
      pruef(`${k.id}: das aeusserste Glied endet am Kettenwerk`,
            letzte.x - b.knoten.get(arme[0].von).x, k.draht, 1e-9, 'm');
    });
  }

  // --- Ein Mass zeigt auf den SCHWERPUNKT, das naechste Glied ans ENDE -----
  /*
   * WEISUNG: der eingetragene Angriffspunkt eines Traegers oder Aufbaus ist
   * sein Schwerpunkt, also die halbe Laenge - dort greifen seine Lasten an.
   * Das naechste Glied der Kette sitzt am ENDE, beim doppelten Versatz.
   *
   * Das ist keine Erfindung: die Lasttabelle fuehrt fuer die Haengestuetze
   * "L,rep = 2.7 m". Schwerpunkt 1.35, Ende 2.70 - und genau dort haengt in
   * beiden Kragarm-Vorlagen der Ausleger. Geprueft wird gegen DIESE Zahl,
   * damit Vorlage und Lasttabelle nicht auseinanderlaufen.
   */
  {
    const hs = FL.getFlBauteil('anbauteil-haengestuetze-od-haengerohr');
    const m = /L,rep\s*=\s*([\d.]+)\s*m/.exec(hs.bemerkung ?? '');
    wahr('Die Lasttabelle nennt die Laenge der Haengestuetze',
         !!m, hs.bemerkung ?? '(keine Bemerkung)');
    const LRep = m ? parseFloat(m[1]) : null;

    ['hs-nt-ausleger', 'ausleger-rohr'].forEach((id) => {
      const mod = A.getVorlage(id).module;
      const nach = (r) => mod.find((x) => {
        try { return FL.getFlBauteil(x.bauteil).rolle === r; } catch { return false; }
      });
      const tr = nach('traeger'), au = nach('aufbau'), dr = nach('drahtwerk');
      // Die Vorlagendatei spricht seit Fassung 2.4 das Achsensystem der
      // Ausleitung: z nach OBEN. Eine haengende Stuetze hat also z < 0, und
      // die Laenge ist der Betrag.
      const tief = (m) => Math.abs(m.z ?? -(m.ev ?? 0));

      if (LRep !== null) {
        pruef(`${id}: die Stuetze greift auf halber Laenge an`,
              tief(tr), LRep / 2, 1e-9, 'm');
      }
      pruef(`${id}: der Ausleger haengt am ENDE der Stuetze`,
            tief(au), 2 * tief(tr), 1e-9, 'm');
      pruef(`${id}: das Kettenwerk haengt auf derselben Hoehe`,
            tief(dr), tief(au), 1e-9, 'm');
      pruef(`${id}: und am ENDE des Kragarms`,
            dr.x, 2 * au.x, 1e-9, 'm');
      wahr(`${id}: die Stuetze selbst steht nicht aus`,
           (tr.x ?? 0) === 0, `x = ${tr.x ?? 0}`);
    });
  }

  // --- Die Vorlagendatei spricht das Achsensystem der Ausleitung ----------
  /*
   * Bis Fassung 2.3 stand dort ein Abstand ZUR JOCHACHSE, positiv NACH
   * UNTEN, waehrend Eingabekarte, Ausleitung und AxisVM z nach OBEN zaehlen.
   * Ein Jochaufsatz las sich in der Datei als ev -1.0, obwohl er nach oben
   * ragt. Gelesen wird die alte Schreibweise weiter - Datenpakete von
   * frueher muessen sich oeffnen lassen.
   */
  {
    // Seit dem 16. September in Tabellenform - geprueft wird der Baum.
    const roh = TBF.ausTabellen(JSON.parse(
      readFileSync(join(HIER, 'data', 'anbauteile.json'), 'utf8')));
    const altReste = roh.vorlagen.flatMap((v) => [v, ...(v.module ?? [])])
      .filter((o) => 'ev' in o || 'ex' in o);
    wahr('Keine Vorlage schreibt mehr ev/ex', altReste.length === 0,
         altReste.map((o) => o.id ?? o.bauteil).join(', '));
    wahr('Haengendes hat z < 0',
         roh.vorlagen.find((v) => v.id === 'hs-nur').module[0].z < 0);
    wahr('Aufgesetztes hat z > 0',
         roh.vorlagen.find((v) => v.id === 'ja-alt').module[0].z > 0);

    // Und die Altschreibweise kommt weiterhin an derselben Stelle heraus.
    const altModul = A.normalisiereAnbauteil(
      { id: 'X', x: 0, module: [{ bauteil: 'anbauteil-haengestuetze-od-haengerohr',
                                  anzahl: 1, ev: 1.35, ex: 0.2 }] });
    pruef('Altes ev wird weiter gelesen', altModul.module[0].z, -1.35, 1e-12, 'm');
    pruef('Altes ex ebenso', altModul.module[0].y, 0.2, 1e-12, 'm');
  }

  // --- Den Kragarm spiegeln, die Leiter mitziehen -------------------------
  /*
   * Ein Ausleger steht nach der einen oder der anderen Seite aus, und das
   * wechselt von Joch zu Joch. Von Hand waeren es zwei Vorzeichen - und das
   * zweite (die Leiter am ENDE des Arms) vergisst man.
   *
   * Geprueft wird die REGEL: gespiegelt wird der Ausleger und alles, was auf
   * derselben Seite weiter aussen sitzt; was innen oder auf der anderen
   * Seite steht, bleibt. Und die Lasten bleiben dieselben - der Spiegel
   * aendert die Seite, nicht die Groesse.
   */
  {
    const uq = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Der Ausleger hat einen Spiegelknopf', uq.includes('data-mod-spiegeln'));
    wahr('Nur der Ausleger, und nur wenn er wirklich aussteht',
         /b\?\.rolle === 'aufbau' && Math\.abs\(m\.x \?\? 0\) > 1e-9/.test(uq));
    wahr('Gespiegelt wird auf derselben Seite nach aussen',
         /Math\.sign\(mx\) === seite && Math\.abs\(mx\) >= weite/.test(uq));

    // Dieselbe Regel hier nachgebildet und an den Daten gemessen.
    const spiegle = (module, mod) => {
      const m2 = module.map((x) => ({ ...x }));
      const x0 = m2[mod]?.x ?? 0;
      if (!x0) return m2;
      const seite = Math.sign(x0), weite = Math.abs(x0) - 1e-9;
      m2.forEach((m) => {
        const mx = m.x ?? 0;
        if (Math.sign(mx) === seite && Math.abs(mx) >= weite) m.x = -mx;
      });
      return m2;
    };
    const at = A.neuesAnbauteil('hs-nt-ausleger', 10);
    const iAufbau = at.module.findIndex((m) => {
      try { return FL.getFlBauteil(m.bauteil).rolle === 'aufbau'; } catch { return false; }
    });
    const gespiegelt = { ...at, module: spiegle(at.module, iAufbau) };
    pruef('Der Ausleger wechselt die Seite',
          gespiegelt.module[iAufbau].x, -at.module[iAufbau].x, 1e-12, 'm');
    const iDraht = at.module.findIndex((m) => {
      try { return FL.getFlBauteil(m.bauteil).rolle === 'drahtwerk'; } catch { return false; }
    });
    pruef('Und die Leiter am Ende des Arms zieht mit',
          gespiegelt.module[iDraht].x, -at.module[iDraht].x, 1e-12, 'm');
    pruef('Die Stuetze bleibt, wo sie ist', gespiegelt.module[0].x ?? 0, 0, 1e-12, 'm');

    // Die Lasten bleiben - nur die Seite aendert sich.
    const summe = (a) => A.expandiereAnbauteile([a], { ek: 'EK2', R: 3e5, spannweite: 50 })
      .reduce((s, p) => s + Object.values(p.kraefte)
        .reduce((q, k) => q + Math.abs(k.Fz ?? 0) + Math.abs(k.Fy ?? 0)
                            + Math.abs(k.Fx ?? 0), 0), 0);
    pruef('Der Spiegel aendert die Seite, nicht die Groesse',
          summe(gespiegelt), summe(at), 1e-9, 'kN');
  }

  // --- Ein Feld zeigt vor und nach der Rechnung dasselbe -------------------
  /*
   * Zwei Stellen schreiben in die Modulfelder: der Aufbau der Karte und das
   * Auffrischen bei jeder Rechnung. Sie waren sich uneinig - der Aufbau
   * setzte `?? 0`, das Auffrischen machte aus einem fehlenden Wert ein leeres
   * Feld. Ein Modul ohne eigenes x zeigte deshalb erst «0» und war nach der
   * ersten Rechnung leer; in der Vorlage steht x gar nicht, also traf es
   * jede Haengestuetze.
   */
  {
    const uq = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Die Vorgabe je Modulfeld steht an EINER Stelle',
         uq.includes('const MODUL_VORGABE = {'));
    wahr('Der Aufbau der Karte liest sie', /modFeld\(i, k, 'x', 'x', modWert\(m, 'x'\)/.test(uq));
    wahr('Das Auffrischen liest dieselbe', /const v = modWert\(m, inp\.dataset\.mk\)/.test(uq));
    wahr('Und der Rueckweg legt sie ab statt null',
         uq.includes('leer ? (vorgabe === undefined ? null : vorgabe)'));
    // Leer BEDEUTET nur beim Winkel etwas - dort heisst es «aus R und L_FL».
    const tab = /const MODUL_VORGABE = \{([\s\S]*?)\};/.exec(uq)[1];
    wahr('Leer bleibt nur der Winkel', /winkel: undefined/.test(tab)
         && (tab.match(/undefined/g) || []).length === 1, tab.replace(/\s+/g, ' ').trim());
  }

  // --- Der Kragarm laedt das Joch an SEINER WURZEL ------------------------
  /*
   * Ein NT-Ausleger steht in Jochachse aus. Das Joch beruehrt er dort NICHT -
   * getragen wird er von der Haengestuetze, und die haengt ueber ihren Raster
   * an EINER Station. Die Last kommt also an der Station an, und der Versatz
   * erscheint als Kraeftepaar C_y = d * F_z.
   *
   * DIE PROBE IST DAS GLEICHGEWICHT: dieselbe Last, einmal ueber den Kragarm
   * und einmal unmittelbar auf dem Joch an der versetzten Stelle, muss
   * DIESELBEN Auflagerkraefte ergeben - eine Resultante ist eine Resultante.
   * Ohne das Kraeftepaar unterscheiden sie sich um F*d/L; mit falschem
   * Vorzeichen um das Doppelte davon. Die Probe legt es also eindeutig fest.
   */
  {
    const L = 20, X0 = 8, D = 2.4, FZ = 3;
    const probe = (x, dx) => ({
      id: 'P', name: 'Probe', x, raster: 0.4, befestigung: 'unten', aktiv: true,
      module: [],
      lasten: [{ einwirkung: 'G', x: dx, y: 0, z: -1, Fz: FZ, aktiv: true }],
    });
    /*
     * AUSDRUECKLICH GELENKIG. Die Probe ist ein GLEICHGEWICHTSARGUMENT am
     * Einfeldtraeger: eine Resultante ist eine Resultante, und ohne das
     * Kraeftepaar fehlt genau F*d/L. Mit einer Drehfeder an den Enden geht
     * ein Teil des Kraeftepaars in die Einspannung, und die Probe misst
     * nicht mehr das, was sie beweisen soll. Seit dem 28. August ist der
     * Startwert `mast` - die Randbedingung gehoert deshalb hier hin und
     * nicht in die Voreinstellung.
     */
    const rechneAt = (at) => {
      const w = { ...standardwerte(), typ: 'J90', L, anbauteile: [at],
                  endbedingung: 'gelenkig' };
      return berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                      getStahl(w.stahl), T.getTragjoch(w.typ));
    };
    const kragarm = rechneAt(probe(X0, D));
    const direkt = rechneAt(probe(X0 + D, 0));
    const ohne = rechneAt(probe(X0, 0));

    pruef('Kragarm und Direktlast geben dieselbe Auflagerkraft',
          kragarm.modell.RA, direkt.modell.RA, 1e-9, 'kN');
    // Und die Probe wuerde ein fehlendes oder falsches Kraeftepaar finden:
    pruef('Ohne Kraeftepaar waere es F*d/L daneben',
          ohne.modell.RA - kragarm.modell.RA, FZ * 1.3 * D / L, 1e-9, 'kN');
    // OERTLICH ist es NICHT dasselbe - genau deshalb wurde es geaendert.
    wahr('Oertlich unterscheiden sie sich sehr wohl',
         Math.abs(kragarm.extrem.MyMax - direkt.extrem.MyMax) > 1,
         `${kragarm.extrem.MyMax.toFixed(2)} gegen ${direkt.extrem.MyMax.toFixed(2)} kNm`);

    // Die Last tritt am ANSCHLUSS ein, nicht am Ende des Arms.
    const lasten = A.expandiereAnbauteile([probe(X0, D)], { ek: 'EK2' });
    wahr('Das Teil selbst greift aussen an',
         Math.abs(lasten[0].x - (X0 + D)) < 1e-9, `x = ${lasten[0].x}`);
    wahr('Und weiss, wo seine Baugruppe haengt',
         Math.abs(lasten[0].stationX - X0) < 1e-9, `stationX = ${lasten[0].stationX}`);
  }

  // --- Bild, Kern und Ausleitung meinen dieselbe Hoehe --------------------
  /*
   * z zaehlt ab der SCHWERACHSE DES GURTES, an dem das Teil abgegriffen wird
   * (anschlussGurt): was nach oben ragt, ab Obergurt, was haengt, ab
   * Untergurt. Die Ausleitung nahm dafuer bei 'durchgehend' IMMER den
   * Untergurt - ein Jochaufsatz sass darin um die ganze Jochhoehe zu tief.
   * Fuer die vertikale Last folgenlos, fuer die waagrechte nicht: ihr
   * Hebelarm zur Jochachse und damit die Torsion war um F_y * h daneben.
   *
   * Geprueft wird ueber die GANZE Vorlagendatenbank, nicht an einem Beispiel:
   * so faellt auch eine kuenftige Vorlage auf, deren Teile nach beiden Seiten
   * zeigen - fuer die haette die Kette zwei Wurzeln.
   */
  {
    const kern = await import(J('core.anbauteile.js'));
    let geprueft = 0, schief = [];
    A.vorlagen().forEach((v) => {
      const w = { ...standardwerte(), anbauteile: [A.neuesAnbauteil(v.id, 10)] };
      const e = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                         getStahl(w.stahl), T.getTragjoch(w.typ));
      const b = AX.stabmodell(e.modell, { knotenmodell: 'anschnitt', eingabe: w });
      const jochachse = b.zOben - e.modell.h / 2;
      b.arme.forEach(({ teil, knoten }) => {
        const soll = jochachse - kern.hebelarmZuAchse(teil, e.modell.h);
        const ist = b.knoten.get(knoten).z;
        geprueft++;
        if (Math.abs(ist - soll) > 1e-9) {
          schief.push(`${v.id}/${teil.bauteilName ?? teil.name}: ` +
                      `${ist.toFixed(4)} statt ${soll.toFixed(4)}`);
        }
      });
    });
    wahr(`Jeder Lastpunkt sitzt auf der Hoehe, die der Kern rechnet (${geprueft})`,
         schief.length === 0, schief.slice(0, 3).join(' | '));
  }

  // --- Die Datei sagt, was sie kann ---------------------------------------
  /*
   * Die Formatnummer sagt, wie gelesen wird - nicht, was drinsteht. Ein
   * Modell aus einer aelteren Fassung liest sich tadellos und baut sich
   * klaglos auf; dass die Anbauteile darin einzeln am Joch hingen, sah man
   * erst im fertigen Modell - nach Aufbau, Rechnung und Auslesen. Deshalb
   * traegt die Datei ihre Merkmale bei sich, und die Bruecke sagt laut,
   * wenn eines fehlt.
   */
  {
    const PS1 = readFileSync(join(HIER, 'com', 'AxisVM_aufbauen.ps1'), 'utf8');
    const w = { ...standardwerte(), anbauteile: [A.neuesAnbauteil('hs-nt-ausleger', 10)] };
    const e = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch(w.typ));
    const j = AX.stabmodellJson(e.modell, { eingabe: w });
    wahr('Die Modelldatei nennt ihre Merkmale', Array.isArray(j.merkmale),
         JSON.stringify(j.merkmale));
    wahr('Darunter die Anbauteil-Kette', (j.merkmale ?? []).includes('anbau-kette'));
    wahr('Die Bruecke erwartet genau dieses Merkmal',
         PS1.includes("'anbau-kette' = ("));
    wahr('Und meldet laut, wenn es fehlt',
         PS1.includes('AELTEREN FASSUNG DES WERKZEUGS'));
    wahr('Ohne den Aufbau abzubrechen - was gebaut wird, entscheidet der Nutzer',
         !/fehlt\.Count -gt 0[\s\S]{0,900}?Beenden/.test(PS1));
  }

  // --- Die Lasten wandern dabei nicht --------------------------------------
  // Nur der WEG der Last aendert sich, nicht ihr Angriffspunkt und nicht ihr
  // Betrag. Alle Glieder sind Starrkoerper; am Gurt kommt dieselbe Resultante
  // an wie zuvor.
  {
    const w = { ...standardwerte(), anbauteile: [A.neuesAnbauteil('hs-nt-ausleger', 10)] };
    const e = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch(w.typ));
    const b = AX.stabmodell(e.modell, { knotenmodell: 'anschnitt', eingabe: w });
    const l = AX.lasten(e.modell, b);
    const summe = (r) => l.punkt.filter((p) => p.richtung === r)
      .reduce((s, p) => s + p.wert, 0);
    const ausTeilen = (feld, vz) => (e.modell.anbauteileFlach ?? [])
      .reduce((s, t) => s + Object.values(t.kraefte ?? {})
        .reduce((q, k) => q + vz * (k[feld] ?? 0), 0), 0);
    pruef('Summe F_z bleibt die der Bauteile', summe('Z'), ausTeilen('Fz', -1), 1e-9, 'kN');
    pruef('Summe F_y ebenso', summe('Y'), ausTeilen('Fy', +1), 1e-9, 'kN');
    wahr('Jede Last haengt an einem Knoten der Baugruppe',
         l.punkt.filter((p) => /^AL/.test(p.knoten)).length > 0 &&
         l.punkt.every((p) => b.knoten.has(p.knoten)));
  }
}

// ===========================================================================
titel('33  Bedienung: was in der Sitzung als Nutzer aufgefallen ist');
/*
 * Diese Pruefungen halten Eigenschaften der OBERFLAECHE fest, die sich beim
 * Bauen eines Jochs mit fuenf Baugruppen als Maengel gezeigt haben. Sie lesen
 * die Quelle - eine Zeichenflaeche und ein Rasterumbruch lassen sich ohne
 * Browser nicht messen, die REGEL dahinter aber sehr wohl.
 */
{
  const css = readFileSync(join(HIER, 'css', 'style.css'), 'utf8');
  const aq = APP_QUELLE();
  const uq = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
  const rq = readFileSync(join(HIER, 'js', 'render.3d.js'), 'utf8');
  const kq = readFileSync(join(HIER, 'js', 'core.anbauteile.js'), 'utf8');
  const xq = readFileSync(join(HIER, 'js', 'export.axisvm.js'), 'utf8');

  // --- Der Name der Baugruppe verschwand -----------------------------------
  // «Leiter-Traverse am Joch» und «Lampe LED» standen beide als «L..» da.
  {
    const raster = css.match(/\.at-zeile\s*\{[^}]*grid-template-columns:\s*([^;]+);/);
    wahr('Die Anbauteil-Zeile gibt dem Namen eine Untergrenze',
         !!raster && /minmax\(\s*\d+px/.test(raster[1]), raster && raster[1].trim());
    wahr('Und die Kraeftezeile ist das, was gekuerzt wird',
         /\.at-kraft\s*\{[^}]*text-overflow:\s*ellipsis/.test(css));
    wahr('Kraefte heissen F_x, F_y, F_z - x ist in derselben Zeile die Station',
         uq.includes("['F_x', su.Gx + su.Qx]"));
  }

  // --- Die Modellspalte fiel auf 92 px ------------------------------------
  {
    wahr('Es gibt eine Mindestbreite fuer die Modellspalte',
         /const MODELL_MIN = \d+/.test(aq),
         (aq.match(/const MODELL_MIN = \d+/) || [''])[0]);
    wahr('Die Startbreiten richten sich nach dem Fenster',
         aq.includes('platzFuerSchubladen()') && aq.includes('clientWidth'));
    wahr('Der Zug am Splitter ist nicht mehr fest auf 640 begrenzt',
         !/Math\.min\(640, a0 \+ d\)/.test(aq));
    wahr('Wird das Fenster schmaler, geben die Schubladen nach',
         /addEventListener\('resize'/.test(aq));
    wahr('Eingeklappte Seiten bleiben dabei eingeklappt',
         /if \(!(app\.)?zuSeite\.links\) setzeSeite/.test(aq));
  }

  // --- Nach dem Ein- und Ausfahren lief das Joch aus dem Bild --------------
  {
    wahr('Am Ende der Fahrt wird nachgefahren',
         aq.includes('passeEinWennAbgeschnitten()'));
    wahr('Aber nur heraus, nie heran',
         /noetig <= this\.kamera\.dist \+ 1e-6\) return false/.test(rq));
    wahr('Und nie in einen selbst gewaehlten Ausschnitt hinein',
         /if \(this\.fokus \|\| this\.station !== null\) return false/.test(rq));
  }

  // --- Elf Kraftbeschriftungen ueber dem Joch -----------------------------
  {
    wahr('Auch die Pfeiltexte haben ein Budget',
         /_markenBudget\(\)[\s\S]{0,200}_pfeiltexte/.test(rq));
    wahr('Sortiert nach Betrag, Angewaehltes zuerst',
         /sort\(\(a, b\) => \(b\.rang \?\? 0\) - \(a\.rang \?\? 0\)\)/.test(rq));
  }

  // --- Die Gleiszuordnung setzte nur der Generator ------------------------
  wahr('Die Karte hat ein Feld fuer das Gleis', uq.includes("atFeld(i, 'gleis'"));

  // --- Bei eta > 1 fehlte der Weg zum naechsten Typ -----------------------
  {
    wahr('Es gibt eine Sortimentssuche', aq.includes('function dialogSortiment'));
    /*
     * SIE FOLGT DER ZAHL, DIE OBEN STEHT (Weisung, 9. September). Hier stand
     * `e > 1` - die Ausnutzung des TRAGJOCH-Ersatzbalkens. Beim Abfangjoch
     * zeigt die Ueberschrift aber `eAn`, und der Knopf fehlte genau dann,
     * wenn man ihn brauchte.
     */
    /*
     * SEIT DEM 11. SEPTEMBER AUCH BEIM MASTEN UND BEIM ANKER (Weisung: «das
     * feld sortiment durchrechnen sollte auch dann eingeblendet werden wenn
     * die masten oder anker / druckstuetzen ausgenutzt sind»). Am
     * Abfangjoch wird regelmaessig der Mast massgebend - im Bedienlauf
     * stand das Joch bei 0.52 und ein Mast bei 1.47.
     */
    wahr('Sie erscheint, wenn Joch, Mast oder Anker ueberschritten ist',
         /\(eAn > 1 \|\| mastUeber \|\| ankerUeber\)/.test(uq));
    wahr('… und der Anker zaehlt auch die Ueberlaenge',
         /ankerUeber = \[/.test(uq) && /lieferbar === false/.test(uq));
    wahr('Der Typ wechselt nicht von selbst',
         aq.includes('DER TYP WECHSELT NICHT VON SELBST'));
    wahr('Was nicht gerechnet werden kann, steht mit Grund da',
         aq.includes("block('Nicht gerechnet', geht)"));
    /*
     * >>> UND SIE KENNT BEIDE SORTIMENTE. <<<
     *
     * Weisung: «den groesseren typ pruefen der die abfangkraft traegt.» Der
     * Dialog rechnete nur Tragjoche durch; beim Abfangjoch waere die Liste
     * die eines fremden Bauteils gewesen.
     */
    wahr('Das Abfangjoch hat seine eigene Liste',
         aq.includes('function dialogSortimentAbfang'));
    wahr('… und sie rechnet mit seinem Kern',
         /dialogSortimentAbfang[\s\S]{0,2500}abfangAuswertung\(/.test(aq));
    wahr('… nennt Typen ausserhalb des Laengenbereichs mit Grund',
         /ausserhalb \$\{b\.text\}/.test(aq));
    wahr('… und ein Klick uebernimmt den Abfangtyp',
         aq.includes("aendern('abfangTyp', tr.dataset.abfangtyp)"));
  }

  // --- Rolle und Traeger standen nirgends ---------------------------------
  {
    wahr('Die Karte nennt die Rolle jedes Moduls', uq.includes('ROLLE_TEXT'));
    wahr('Und woran es haengt', uq.includes('haengtAn'));
    wahr('Und warnt, wenn zwei Teile auf demselben Punkt sitzen',
         uq.includes('kette-warn'));
  }

  // --- Bild und Ausleitung bauen dieselbe Kette ---------------------------
  {
    wahr('Die Kette steht an EINER Stelle im Rechenkern',
         kq.includes('export function anbauKette'));
    wahr('Die Modellansicht liest sie von dort', rq.includes('anbauKette(meine,'));
    wahr('Die Ausleitung ebenso', xq.includes('anbauKette(a.teile ?? [a]'));
    wahr('Und niemand zeichnet mehr einen geraden Staender daneben',
         !rq.includes('opt(`Ständer '));
  }
}

// ===========================================================================
titel('34  Teilweise Einspannung: vom Ersatzbalken ins Stabmodell');
/*
 * Der Rechenkern lagert das Jochende ueber eine DREHFEDER c_phi. Das
 * ausgeleitete Stabmodell hat dafuer nur im Auflagermodell 'punkt' einen Ort
 * - dort haengt das Ende ueber ein Schott an EINEM Knoten. Im Modell 'gurte',
 * der Vorgabe fuer die neue Bauweise, sind die vier Gurte einzeln gehalten,
 * und der Obergurt war lotrecht FREI. Das ist ein Gelenk: das ausgeleitete
 * Modell war am Ende immer gelenkig, ganz gleich was die Anwendung gerechnet
 * hatte.
 *
 * UEBERSETZUNG. Eine Endverdrehung theta hebt den Obergurt gegenueber dem
 * Untergurt um theta*h. Haelt je Obergurtknoten eine Feder k, ist die Kraft
 * k*theta*h und das Moment beider zusammen 2*k*h^2*theta:
 *
 *      k = c_phi / (2 h^2)
 *
 * Dieselbe Zwei-Gurt-Vorstellung, auf der biegesteifigkeitJoch und das
 * Kraeftepaar der Anbauteile stehen.
 */
{
  const AX = await import(J('export.axisvm.js'));
  const AU = await import(J('core.auflager.js'));

  const bau = (extra) => {
    const w = { ...standardwerte(), typ: 'J90', L: 20, ...extra };
    const e = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch(w.typ));
    return { w, m: e.modell };
  };
  const lager = (m, w, am) => AX.stabmodellJson(m, { eingabe: w, auflagerModell: am })
    .auflager.filter((a) => a.ende === 'A');
  const lager2 = (m, w, am) => AX.stabmodellJson(m, { eingabe: w, auflagerModell: am })
    .auflager;

  // --- Mit Mast: die Feder muss ankommen ----------------------------------
  {
    // Die Begrenzung steht im Startwert auf AUS (Weisung). Hier ausdruecklich
    // EIN, denn genau darum geht es: ausgeleitet wird trotzdem die
    // geometrische Feder, und die beiden Zahlen muessen sich unterscheiden.
    const { w, m } = bau({ endbedingung: 'mast', mastProfil: 'HEB 260', mastH: 7.5,
                           schraubenGrenze: true, schraubenFgrenz: 8 });
    /*
     * AUSGELEITET WIRD DIE GEOMETRISCHE FEDER (Weisung), nicht die je
     * Lastfall auf die Schraubengrenze herabgesetzte. Ein Stabmodell gibt es
     * nur eines; es truege sonst die Feder eines einzelnen Lastfalls.
     */
    const c = m.federn.roh.cA;
    wahr('Die Anwendung rechnet eine teilweise Einspannung', c > 0 && c < 1e11,
         `c_geo = ${c.toFixed(0)} kNm/rad`);

    /*
     * DAS GURTMODELL TRAEGT SIE NICHT - und das ist kein Versaeumnis,
     * sondern ein Messergebnis. In AxisVM 18 r1k nachgerechnet (J90 ueber
     * 20 m, Schnee 1.0 kN/m, c_phi = 12951 kNm/rad):
     *
     *                        Ende A     Feldmitte    Ende B
     *   gurte ohne Feder     -42.58       26.30       +2.85   kNm
     *   gurte mit Gurtfeder  -42.65       26.30       +2.80
     *   punkt, Drehfeder     -16.70       28.28      -16.71
     *   Anwendung            22.12        27.88       22.12
     *
     * Eine Feder, die 0.07 von 42 kNm bewegt, sieht aus wie eine
     * Uebertragung und ist keine. Sie steht deshalb nicht im Modell.
     */
    const g = lager(m, w, 'gurte');
    const og = g.filter((a) => a.knoten.startsWith('OG'));
    const ug = g.filter((a) => a.knoten.startsWith('UG'));
    pruef('Vier Gurte je Ende', g.length, 4, 1e-12, 'Stk');
    wahr('Der Untergurt haelt lotrecht starr', ug.every((a) => a.uz === 'Rigid'));
    wahr('Der Obergurt bleibt lotrecht frei - keine Scheinuebertragung',
         og.every((a) => a.uz === 'Free' && !a.cUz_kNm),
         og.map((a) => `${a.uz} ${a.cUz_kNm ?? '-'}`).join(' | '));

    // Der Ersatzbalken traegt sie weiterhin als DREHfeder - unveraendert.
    const pk = lager(m, w, 'punkt');
    pruef('Im Ersatzbalken bleibt es eine Drehfeder', pk.length, 1, 1e-12, 'Stk');
    pruef('Mit der geometrischen Feder des Bauwerks', pk[0].cFiy_kNm, c, 1e-6, 'kNm/rad');
    wahr('Und dort traegt der Obergurt keine eigene Feder', !pk[0].cUz_kNm);

    // Und ausdruecklich NICHT die begrenzte - sonst haenge das Modell am
    // Lastfall, den man beim Ausleiten zufaellig eingestellt hatte.
    // Die Begrenzung steht im Startwert auf AUS - hier ausdruecklich ein,
    // sonst gibt es keine zweite Zahl zu vergleichen.
    wahr('Die begrenzte Feder ist eine andere Zahl',
         Math.abs(m.federn.cA - c) > 1,
         `begrenzt ${m.federn.cA.toFixed(0)} gegen geometrisch ${c.toFixed(0)}`);
    wahr('Ausgeleitet wird die geometrische',
         Math.abs(pk[0].cFiy_kNm - c) < 1e-6
         && Math.abs(pk[0].cFiy_kNm - m.federn.cA) > 1);
  }

  // --- GENAU EIN LAENGSHALT, IN JEDEM AUFLAGERMODELL ----------------------
  /*
   * Beim Nachrechnen kam heraus, dass das Gurtmodell an den beiden Enden
   * VERSCHIEDEN dastand: am Ende A waren alle vier Gurtknoten in x gehalten,
   * am Ende B keiner. Eine Verdrehung um y verschiebt Ober- und Untergurt
   * aber gegenlaeufig in x - vier Festhaltungen sperrten sie damit
   * weitgehend, und Ende A war unter symmetrischer Last mit -42.6 kNm nahezu
   * eingespannt, Ende B mit +2.9 kNm nahezu gelenkig.
   *
   * Weisung: nur EIN Knoten haelt in x. Mehr verlangt das Gleichgewicht in
   * Jochrichtung nicht, und jeder weitere Halt ist ein Zwang - zwei auf
   * verschiedener Hoehe sperren die Drehung um y, zwei auf verschiedener
   * Seite die um z.
   */
  {
    const { w, m } = bau({ endbedingung: 'gelenkig' });
    ['gurte', 'mitte', 'punkt'].forEach((modell) => {
      const g = lager2(m, w, modell);
      const fest = g.filter((x) => x.ux === 'Rigid');
      wahr(`Modell ${modell}: genau ein Laengshalt`, fest.length === 1,
           `${fest.length} von ${g.length}: ${fest.map((x) => x.knoten).join(' ')}`);
      wahr(`Modell ${modell}: und er sitzt am Ende A`,
           fest[0]?.ende === 'A', String(fest[0]?.ende));
    });
    // Am Gurtmodell ist es der Untergurt: dort sitzt auch der lotrechte Halt,
    // eine Laengskraft tritt also nicht ueber einen sonst freien Gurt ein.
    const g = lager2(m, w, 'gurte');
    const fest = g.find((x) => x.ux === 'Rigid');
    wahr('Und im Gurtmodell am Untergurt', fest.knoten.startsWith('UG'),
         fest.knoten);
    wahr('Der gehaltene Knoten traegt auch die Vertikalkraft',
         fest.uz === 'Rigid', fest.uz);
    // Kein Ende ist damit eingespannt - keine Drehfeder, kein Kraeftepaar.
    wahr('Das Gurtmodell spannt kein Ende ein',
         g.every((x) => x.fiy === 'Free')
         && g.filter((x) => x.uz === 'Rigid').length === 4);
  }

  // --- Die Schraubengrenze als EIGENER Nachweis ---------------------------
  /*
   * Weisung: die geometrische Feder ins Modell, die Schraubengrenze separat
   * nachweisen. Bis dahin lebte die Grenze nur INNERHALB der Feder - sie war
   * per Konstruktion eingehalten, und man sah nie, wieviel die Verbindung mit
   * der wirklichen Steifigkeit des Mastes zu tragen haette. Genau das ist die
   * Frage, die das ausgeleitete Stabmodell stellt.
   */
  {
    /*
     * MIT EINGESCHALTETEM AUFLAGERNACHWEIS. Er ist seit der Weisung ab Werk
     * aus; ohne das Einschalten stuende A1 gar nicht in der Liste, und genau
     * daran ist dieser Abschnitt beim Umbau aufgelaufen.
     */
    const { m } = bau({ endbedingung: 'mast', mastProfil: 'HEB 260', mastH: 7.5,
                        schraubenFgrenz: 24, nachweise: { auflagerJoch: true } });
    const ga = m.gurtanschluss;
    wahr('Der Gurtanschluss wird eigens gerechnet', !!ga);
    pruef('Aus der GEOMETRISCHEN Feder', ga.cA, m.federn.roh.cA, 1e-9, 'kNm/rad');
    // JE GURT (Weisung): jede Gurtebene haengt an ZWEI Gurten.
    pruef('Kraeftepaar M/(2h), je Gurt', ga.FA,
          Math.abs(ga.MA) / (2 * ga.h), 1e-9, 'kN');
    pruef('Massgebend ist das groessere Ende', ga.F,
          Math.max(ga.FA, ga.FB), 1e-12, 'kN');
    pruef('eta = F / F_Grenz', ga.eta, ga.F / 24, 1e-9, '-');
    const CH = await import(J('core.checks.js'));
    const a1 = CH.konstruktionsChecks(m).find((c) => c.id === 'A1');
    wahr('Er steht als Pruefung A1 in der Liste', !!a1, a1 ? a1.text : '(fehlt)');
    pruef('Sie nennt die Kraft', a1.vorhanden, ga.F, 1e-9, 'kN');
    pruef('Und die Grenzlast', a1.erforderlich, 24, 1e-12, 'kN');
    wahr('Und sagt, ob es reicht', a1.ok === (ga.F <= 24 * (1 + 1e-9)),
         `F = ${ga.F.toFixed(2)} kN gegen 24 kN`);

    /* =====================================================================
     * A2 - ENDAUFLAGER UND AUFLAGERBEDINGUNG BESCHREIBEN DASSELBE ENDE
     * =====================================================================
     *
     * Nachgefragt am 12. September: «die auswahl endauflager und die
     * auflagebedingungen und der berechnungskern sollten verdrahtet sein.»
     *
     * Verdrahtet SIND sie, aber nur auf einem Weg: `endbedingung = 'links'`
     * fuehrt die Bedingung ueber `federAusLinks` in den Rechenkern. Die vier
     * anderen Endauflager holen ihre Feder woanders her und lassen die
     * Bedingung unbeachtet - waehrend das AUSGELEITETE Modell immer ihr
     * folgt. Damit koennen beide zwei verschiedene Tragwerke beschreiben.
     *
     * >>> BIS ZUM 13. SEPTEMBER WAR DIE VORGABE EINER DIESER FAELLE. <<<
     *
     * `endbedingung: 'mast'` und die Vorgabe-Bedingung (Obergurt laengs
     * frei) standen beide als Standard da. Die Bedingung LOEST das
     * Kraeftepaar der beiden Gurtebenen - im ausgeleiteten Modell kann das
     * Jochende sich um y drehen, ohne dass der Mast etwas dagegen haelt.
     * Der Rechenkern setzte dort die Mastfeder an: 16'710 kNm/rad gegen
     * null, eta 0.4567 gegen 0.5086.
     *
     * Jetzt ist `links` die Vorgabe - siehe die Kontrollen unten. Die
     * Pruefung greift nur noch, wenn jemand bewusst eine andere
     * Endbedingung waehlt; sie entscheidet nichts, sie sagt es.
     */
    const a2Fall = (zus) => {
      const b2 = bau({ mastVorhanden: true, mastProfil: 'HEB 260', mastH: 8.0,
                       ...zus });
      return CH.konstruktionsChecks(b2.m).find((c) => c.id === 'A2');
    };
    const beideFest = { OG: { x: 'Rigid' }, UG: { x: 'Rigid' } };
    const a2mast = a2Fall({ endbedingung: 'mast' });
    wahr('A2 steht in der Liste', !!a2mast, a2mast ? a2mast.text : '(fehlt)');
    wahr('Vorgabe-Bedingung und Mastfeder laufen auseinander',
         a2mast && a2mast.ok === false, a2mast?.status ?? '');
    wahr('… und sie ist eine Warnung, kein Fehler',
         a2mast?.warnungNichtFehler === true);
    wahr('Gelenkig und Vorgabe-Bedingung sagen dasselbe',
         a2Fall({ endbedingung: 'gelenkig' })?.ok === true);
    wahr('Mast und beide Gurte gehalten ebenso',
         a2Fall({ endbedingung: 'mast', auflagerLinks: beideFest })?.ok === true);
    wahr('Gelenkig gegen beide Gurte gehalten nicht',
         a2Fall({ endbedingung: 'gelenkig', auflagerLinks: beideFest })
           ?.ok === false);
    /*
     * BEI 'links' GIBT ES NICHTS ZU VERGLEICHEN - dort IST die Bedingung die
     * Feder. Eine Pruefung, die sich selbst bestaetigt, waere eine Zeile
     * ohne Aussage.
     */
    wahr('Bei «aus der Auflagerbedingung» entfaellt die Pruefung',
         !a2Fall({ endbedingung: 'links', auflagerLinks: beideFest }));

    /* =====================================================================
     * >>> DIE VORGABE NIMMT DIE FEDER AUS DER BEDINGUNG. <<<
     * =====================================================================
     *
     * Weisung vom 13. September: «offene fragen umsetzen» - darunter die
     * Frage, ob `links` zur Vorgabe werden soll.
     *
     * Sie soll, und zwar aus dem Grund, der A2 ueberhaupt entstehen liess:
     * ein Jochende wird ueber das KRAEFTEPAAR der beiden Gurtebenen
     * eingespannt. Gibt eine Ebene laengs nach - und genau das ist die
     * Vorgabe, Obergurt laengs frei -, gibt es kein Paar, und dann traegt
     * auch der steifste Mast kein Moment ins Joch.
     *
     * >>> DAS IST EINE AENDERUNG AN DER RECHNUNG, UND SIE STEHT HIER. <<<
     *
     * Gemessen am J90 / 20.00 m mit HEB 260: eta 0.4567 -> 0.5086, elf
     * Prozent, auf der sicheren Seite. Wer die alte Rechnung will, waehlt
     * «teilweise. Steifigkeit aus Mast» - die Wahl bleibt.
     */
    {
      const SCH = await import(J('ui.schema.js'));
      const std = SCH.standardwerte();
      wahr('Die Vorgabe des Endauflagers ist «links»',
           std.endbedingung === 'links', String(std.endbedingung));
      // Mit ihr gibt es nichts mehr zu vergleichen - A2 entfaellt.
      wahr('Mit der Vorgabe entfaellt A2', !a2Fall({}));
      /*
       * UND DAS FELD «Anschluss ans Joch» BLEIBT SICHTBAR. Es haengt an der
       * MASTFEDER, und die geht bei `links` in die Reihenschaltung ein -
       * nur wenn die Gurtebene laengs nachgibt, faellt sie heraus. Eine
       * Vorgabenaenderung, die still ein Feld verschwinden laesst, waere
       * die schlechtere Art von Aufraeumen.
       */
      const sicht = SCH.sichtbareFelder('aufl', { ...std, mastVorhanden: true })
        .map((f) => f.key);
      wahr('«Anschluss ans Joch» steht weiterhin da',
           sicht.includes('mastAnschluss'), sicht.join(', '));
      const mitMast = SCH.sichtbareFelder('aufl',
        { ...std, mastVorhanden: true, endbedingung: 'mast' }).map((f) => f.key);
      wahr('… und bei «Steifigkeit aus Mast» auch',
           mitMast.includes('mastAnschluss'));
      const gel = SCH.sichtbareFelder('aufl',
        { ...std, mastVorhanden: true, endbedingung: 'gelenkig' })
        .map((f) => f.key);
      wahr('Bei gelenkig dagegen nicht', !gel.includes('mastAnschluss'));
    }

    // Voll eingespannt ist eine Idealisierung, keine Verbindung - dort nicht.
    const voll = bau({ endbedingung: 'voll', schraubenFgrenz: 24 });
    wahr('Bei voller Einspannung wird nichts nachgewiesen', !voll.m.gurtanschluss);
  }

  /* =========================================================================
   * >>> DIE KETTE DES TRAGJOCHS IST DIE DES ABFANGJOCHS. <<<
   * =========================================================================
   *
   * Weisung vom 15. September: "das auflger fuer das tragjoch angleichen an
   * abfangjoch, wie beschrieben."
   *
   * Am 13. September hatte das Tragjoch die rechten Winkel uebernommen und
   * war in drei Punkten anders geblieben. Alle drei sind jetzt angeglichen:
   *
   *   1  DER VERSATZ IN z      Ich hatte ihn weggelassen mit der Begruendung,
   *                            die Mastknoten saessen ja schon auf den
   *                            Gurthoehen. Das stimmt - und genau deshalb lief
   *                            die Konsole in der Ebene des horizontalen
   *                            Blechs, also mitten hindurch.
   *   2  DAS LINK IN z         Es misst seine 50 mm lotrecht zum Gurt, nicht
   *                            mehr in der Jochachse.
   *   3  DIE KONSOLENLAENGE    Aus dem Mastprofil (halbe Mastbreite), wie es
   *                            die Weisung vom 12. September verlangt hatte.
   *                            `konsolLaenge` stand seit damals bereit, aber
   *                            nur das Abfangjoch rief sie; hier standen
   *                            weiter pauschale 150 mm.
   *
   * DIE KETTE, GEMESSEN am J90 / 20.00 m mit HEB 260 (Ende A, Obergurt
   * links; Jochachse z = 0, Gurte auf +-0.2246, Winkel L90):
   *
   *   KONSOLE_A_OG    (0.000, 0.000, 0.130) -> (0.130, 0.000, 0.130)   x
   *   KONSARM_A_OGL   (0.130, 0.000, 0.130) -> (0.130,-0.195, 0.130)   y
   *   LINKSTIEL_A_OGL (0.130,-0.195, 0.130) -> (0.130,-0.195, 0.175)   z
   *   LINK_A_OGL      (0.130,-0.195, 0.175) -> (0.130,-0.195, 0.225)   z
   *
   * Der Versatz misst 0.095 m: halber Winkelschenkel (90/2 mm) plus 50 mm
   * Luft - dasselbe Mass wie beim Abfangjoch. Er zeigt nach INNEN, zwischen
   * die beiden Gurtebenen: ueber dem Obergurt endet der Mast, wo kein
   * Ueberstand angegeben ist, und dort waere kein Ansatzpunkt.
   * ======================================================================= */
  {
    const { m: m3 } = bau({ mastVorhanden: true, mastProfil: 'HEB 260',
                            mastH: 8.0 });
    const b3 = AX.stabmodell(m3, { knotenmodell: 'anschnitt' });
    const kn3 = (n) => b3.knoten.get(n);
    const st3 = (n) => b3.staebe.find((s) => s.name === n);
    const achse3 = (n) => {
      const s = st3(n);
      if (!s) return '(fehlt)';
      const a = kn3(s.von), b = kn3(s.bis);
      if (!a || !b) return '(ohne Knoten)';
      const d = [Math.abs(b.x - a.x), Math.abs(b.y - a.y), Math.abs(b.z - a.z)];
      const gross = d.filter((v) => v > 1e-9);
      return gross.length === 1 ? 'xyz'[d.findIndex((v) => v > 1e-9)]
           : gross.length === 0 ? 'Punkt' : 'schräg';
    };
    wahr('Die Konsole läuft in x', achse3('KONSOLE_A_OG') === 'x',
         achse3('KONSOLE_A_OG'));
    wahr('Der Arm zur Gurtachse läuft in y',
         achse3('KONSARM_A_OGL') === 'y' && achse3('KONSARM_A_OGR') === 'y',
         `${achse3('KONSARM_A_OGL')} / ${achse3('KONSARM_A_OGR')}`);
    wahr('Der Stiel darunter läuft in z',
         achse3('LINKSTIEL_A_OGL') === 'z' && achse3('LINKSTIEL_A_UGR') === 'z');
    wahr('Und das Linkelement ebenso',
         achse3('LINK_A_OGL') === 'z' && achse3('LINK_B_UGR') === 'z');
    /*
     * >>> UND ZWAR AN BEIDEN ENDEN UND IN BEIDEN GURTEBENEN. <<<
     *
     * Vier Ecken, zwei Seiten - wer nur eine prueft, laesst die anderen
     * sieben laufen. Das ist genau die Art Fehler, die erst im Modell
     * auffaellt.
     *
     * Je Ende und Gurtebene sieben Glieder: eine Konsole, dann je Seite Arm,
     * Stiel und Link. Macht 2 * 2 * 7 = 28.
     */
    const alleGlieder = b3.staebe.filter((s) =>
      /^(KONSOLE|LINK|LINKSTIEL|KONSARM)_[AB]_/.test(s.name));
    wahr('Die Kette hat an beiden Enden alle Glieder',
         alleGlieder.length === 28, `${alleGlieder.length} Stäbe`);
    const schraege = alleGlieder.filter((s) => achse3(s.name) === 'schräg');
    wahr('Kein Glied der Auflagerkette läuft schräg',
         schraege.length === 0, schraege.map((s) => s.name).join(', '));
    /* =====================================================================
     * >>> DER VERSATZ IN z ZEIGT NACH AUSSEN. <<<
     * =====================================================================
     *
     * Weisung vom 15. September: "in der hoehe die link elemente ausserhalb
     * des vierendeel traegers anbringen. sonst koennten wir ueberlagerungen
     * bekommen wenn das linkelement genau auf ein stehendes blech trifft."
     *
     * Sie nimmt die Loesung vom selben Tag zurueck: ich hatte den Versatz
     * nach INNEN gelegt, zwischen die Gurtebenen. Dort stehen aber die
     * Bleche - und der Anschlusspunkt der Kette faellt mit der Konsolspitze
     * auf eine Station, an der eines stehen kann. Zwei Bauteile am selben
     * Ort sind im Modell nicht mehr auseinanderzuhalten.
     *
     * AUSSEN ist nichts: kein Blech, kein Riegel, kein Anbauteil.
     *
     * Das Mass bleibt: halber Schenkel plus 50 mm Luft, beim L 90x9 also
     * 95 mm. Der Obergurt hinauf, der Untergurt hinunter.
     */
    const kKons = kn3(st3('KONSOLE_A_OG').bis);
    const kGurt = kn3(st3('LINK_A_OGL').bis);
    pruef('Die Konsole liegt ueber der Obergurtebene',
          kKons.z - kGurt.z, 0.090 / 2 + 0.05, 1e-9, 'm');
    const kKonsU = kn3(st3('KONSOLE_A_UG').bis);
    const kGurtU = kn3(st3('LINK_A_UGL').bis);
    pruef('Und unter der Untergurtebene, gleich weit',
          kGurtU.z - kKonsU.z, 0.090 / 2 + 0.05, 1e-9, 'm');
    wahr('Beide Ansaetze liegen ausserhalb der Gurtebenen',
         kKons.z > kGurt.z && kKonsU.z < kGurtU.z);
    /*
     * UND DAS LINK KOMMT VON AUSSEN. Sein Anschlusspunkt sitzt 50 mm ueber
     * dem Obergurt bzw. unter dem Untergurt - nicht dazwischen.
     */
    const kAnsO = kn3(st3('LINK_A_OGL').von);
    const kAnsU = kn3(st3('LINK_A_UGL').von);
    pruef('Das Link haengt 50 mm ueber dem Obergurt',
          kAnsO.z - kGurt.z, 0.05, 1e-9, 'm');
    pruef('… und 50 mm unter dem Untergurt', kGurtU.z - kAnsU.z, 0.05,
          1e-9, 'm');
    /*
     * >>> UND DAMIT LIEGT DIE GANZE KETTE FREI. <<<
     *
     * Die Probe, die den Grund der Weisung festhaelt: kein Glied der Kette
     * liegt zwischen den beiden Gurtebenen, wo die Bleche stehen. Die
     * Gurtknoten selbst sind der Rand und zaehlen nicht mit.
     */
    {
      const zO = kGurt.z, zU = kGurtU.z;
      const drin = b3.staebe
        .filter((x) => /^(KONSOLE|KONSARM|LINKSTIEL|LINK)_[AB]_/.test(x.name))
        .filter((x) => [kn3(x.von), kn3(x.bis)].some(
          (p) => p.z < zO - 1e-9 && p.z > zU + 1e-9));
      wahr('Kein Glied der Kette liegt zwischen den Gurtebenen',
           drin.length === 0, drin.map((x) => x.name).join(', '));
    }
    /*
     * >>> UEBER DEM OBERGURT REICHT DER MAST NICHT IMMER HIN. <<<
     *
     * Unter dem Untergurt schon - dort laeuft er zum Fundament. Oben nur mit
     * Ueberstand; ohne einen traegt ein kurzes starres Stueck den Ansatz.
     * Seit dem 5. September haengt die Mastlaenge an der Anschlusshoehe
     * (H + 0.50 m), es gibt ihn also im Regelfall. Der Rueckfall wird
     * trotzdem geprueft - er ist der Fall, den niemand einstellt und der
     * dann doch vorkommt.
     */
    {
      const { m: mOhne } = bau({ mastVorhanden: true, mastProfil: 'HEB 260',
                                 mastH: 8.0, mastLaenge: 8.0 });
      const bOhne = AX.stabmodell(mOhne, { knotenmodell: 'anschnitt' });
      const stueck = bOhne.staebe.filter((x) => /^KONSANSATZ_/.test(x.name));
      wahr('Ohne Ueberstand traegt ein Ansatzstueck den Obergurtarm',
           stueck.length === 2, `${stueck.length}`);
      wahr('… und keines den Untergurtarm - dort ist der Mast',
           stueck.every((x) => /_OG$/.test(x.name)),
           stueck.map((x) => x.name).join(' '));
      const mit = bau({ mastVorhanden: true, mastProfil: 'HEB 260',
                        mastH: 8.0 }).m;
      wahr('Mit Ueberstand sitzt der Ansatz auf dem Masten',
           AX.stabmodell(mit, { knotenmodell: 'anschnitt' }).staebe
             .every((x) => !/^KONSANSATZ_/.test(x.name)));
    }
    /*
     * >>> DIE KONSOLE MISST DIE HALBE MASTBREITE. <<<
     *
     * HEB 260 -> 130 mm. Vorher standen hier pauschale 150 mm - beim HEB 200
     * endete die Konsole damit weit hinter der Flanschkante, beim HEB 300
     * genau darauf. Das Feld `auflagerKonsole` schlaegt die Ableitung.
     */
    const kMast = kn3(st3('KONSOLE_A_OG').von);
    pruef('Die Konsole misst die halbe Mastbreite',
          kKons.x - kMast.x, 0.130, 1e-9, 'm');
    const { m: m3b } = bau({ mastVorhanden: true, mastProfil: 'HEB 260',
                             mastH: 8.0, auflagerKonsole: 90 });
    const b3b = AX.stabmodell(m3b, { knotenmodell: 'anschnitt' });
    pruef('… und das eigene Mass schlägt sie',
          b3b.knoten.get('KONS_A_OG').x - b3b.knoten.get('MAST_A_OG').x,
          0.090, 1e-9, 'm');
    /*
     * >>> DER GURT WIRD AN DER KONSOLSPITZE GEHALTEN. <<<
     *
     * Das ist die Aenderung, die im Modell etwas bewegt: die Kette laeuft
     * nicht mehr auf die Mastachse zurueck (Weisung vom 12. September:
     * "nicht zurueckfuehren auf die mastachse lage"). Die Stuetzweite des
     * ausgeleiteten Modells wird dadurch um 2*a_K kuerzer als die des
     * Ersatzbalkens - hier 19.740 gegen 20.000 m.
     *
     * Der Ersatzbalken liegt damit auf der SICHEREN Seite; der Unterschied
     * gehoert in den Bericht, nicht in die Stille.
     */
    pruef('Das Link hält den Gurt an der Konsolspitze',
          kGurt.x, 0.130, 1e-9, 'm');
    const kGurtB = kn3(st3('LINK_B_OGL').bis);
    pruef('Am anderen Ende spiegelbildlich', kGurtB.x, 20 - 0.130, 1e-9, 'm');
    pruef('Die Stützweite des Modells ist um 2·a_K kürzer',
          kGurtB.x - kGurt.x, m3.stuetzweite - 0.260, 1e-9, 'm');
  }

  /* =========================================================================
   * >>> DIE UMHUELLENDE FUEHRT MIN UND MAX JE GROESSE. <<<
   * =========================================================================
   *
   * Weisung vom 13. September: «offene fragen umsetzen» - darunter die, ob
   * eine echte Umhuellende je Groesse gezeigt werden soll.
   *
   * `huellkurve()` nimmt je Station den Knoten mit dem GROESSTEN eta, mit
   * allem, was an ihm haengt - also auch mit SEINEM M_y. Fuer den Nachweis
   * ist das richtig. Als Kurve gelesen ist es eine Falle: wo die massgebende
   * Kombination wechselt, springt die Linie, und dM/dx ist dort nicht V.
   *
   * Nachgemessen am J90 / 20.00 m, Feldmitte: M_y = 46.54 kNm, waehrend die
   * Spanne ueber alle Kombinationen von 44.46 bis 48.62 reicht. Der
   * eta-Wert liegt also MITTEN im Band - die fuer eta massgebende
   * Kombination liefert dort nicht das groesste Moment. Genau das war die
   * Frage vom 12. September.
   * ======================================================================= */
  {
    const { vergleichKombinationen: vgl } = await import(J('core.vierendeel.js'));
    const kk = vgl(
      { ...standardwerte(), typ: 'J90', L: 20, mastVorhanden: true },
      getProfil(standardwerte().profOG), getProfil(standardwerte().profUG),
      getStahl(standardwerte().stahl), T.getTragjoch('J90'));
    const h = kk.huellkurve;
    wahr('Die Huellkurve steht da', Boolean(h?.knoten?.length));
    wahr('Jeder Knoten traegt seine Spanne',
         h.knoten.every((r) => r.spanne && r.spanne.My && r.spanne.Vz),
         `${h.knoten.filter((r) => !r.spanne).length} ohne`);
    /*
     * >>> DER NACHWEISWERT LIEGT IMMER IM BAND. <<<
     *
     * Er stammt aus einer der Kombinationen, ueber die das Band gebildet
     * wird - laege er ausserhalb, waere eine davon nicht eingerechnet.
     */
    for (const g of ['My', 'Vz', 'Mz', 'Tx']) {
      const raus = h.knoten.filter((r) => r.spanne?.[g]
        && (r[g] < r.spanne[g][0] - 1e-9 || r[g] > r.spanne[g][1] + 1e-9));
      wahr(`${g}: der Nachweiswert liegt im Band`, raus.length === 0,
           `${raus.length} Ausreisser`);
      wahr(`${g}: die Spanne ist nicht verdreht`,
           h.knoten.every((r) => !r.spanne?.[g]
             || r.spanne[g][0] <= r.spanne[g][1] + 1e-12));
    }
    /* =====================================================================
     * >>> UND SIE LIEGT AUSEINANDER, WO ES ETWAS AUSEINANDERZULEGEN GIBT.
     * =====================================================================
     *
     * Eine Kontrolle auf ein Band, das ueberall auf null zusammenfaellt,
     * waere blind. Gemessen am 13. September, beide Faelle:
     *
     *   nackt (nur Joch)    M_y Mitte 38.26, Spanne 38.26 … 38.26   0/29
     *   mit Fahrleitung     M_y Mitte 46.54, Spanne 44.46 … 48.62  27/29
     *
     * DAS IST KEIN FEHLER, SONDERN DIE AUSSAGE. Ohne Anbauteile tragen die
     * vier Nachweiskombinationen dieselbe vertikale Last; sie unterscheiden
     * sich nur im Wind, und der geht nicht in M_y. Dann IST die Umhuellende
     * eine Linie, und das Band faellt zu Recht in sich zusammen.
     */
    const breite = (hk) => hk.knoten.filter((r) => r.spanne?.My
      && r.spanne.My[1] - r.spanne.My[0] > 1e-6).length;
    wahr('Ohne veraenderliche Vertikallast ist das Band eine Linie',
         breite(h) === 0, `${breite(h)} von ${h.knoten.length}`);
    const mitFL = { ...standardwerte(), typ: 'J90', L: 20, mastVorhanden: true,
      anbauteile: [{ ...A.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL' }] };
    const hFL = vgl(mitFL, getProfil(mitFL.profOG), getProfil(mitFL.profUG),
                    getStahl(mitFL.stahl), T.getTragjoch('J90')).huellkurve;
    wahr('Mit Fahrleitung hat es eine Breite',
         breite(hFL) > hFL.knoten.length / 2,
         `${breite(hFL)} von ${hFL.knoten.length}`);
    /*
     * >>> UND GENAU DAS WAR DIE FRAGE VOM 12. SEPTEMBER. <<<
     *
     * In Feldmitte liegt der Nachweiswert MITTEN im Band: die fuer eta
     * massgebende Kombination liefert dort nicht das groesste Moment. Wer
     * die Linie als Momentenlinie liest, sucht den Fehler in der Rechnung.
     */
    const mitte = hFL.knoten[Math.floor(hFL.knoten.length / 2)];
    pruef('Feldmitte: der Nachweiswert', mitte.My, 46.54, 2e-3, 'kNm');
    // Seit dem 17. September geht der Havariefall mit γ_G = 1.0 in die
    // Huellkurve ein - er liefert die untere Schranke (vorher 44.46).
    pruef('… die untere Schranke', mitte.spanne.My[0], 35.80, 2e-3, 'kNm');
    pruef('… die obere', mitte.spanne.My[1], 48.62, 2e-3, 'kNm');
    wahr('… und er liegt zwischen beiden, nicht am Rand',
         mitte.My > mitte.spanne.My[0] + 1e-6
         && mitte.My < mitte.spanne.My[1] - 1e-6);
    /*
     * >>> DIE EINZELLASTFAELLE BLEIBEN UNBERUEHRT. <<<
     *
     * `knotenH` sind Referenzen auf die Knoten der Einzelkombinationen. Wer
     * daran eine Eigenschaft setzt, setzt sie in JEDER Ansicht dieses
     * Lastfalls - der Einzellastfall traegt dann eine Spanne, die es dort
     * nicht gibt. Deshalb wird kopiert, und deshalb steht das hier.
     */
    const einzeln = Object.values(kk.ergebnisse ?? {});
    wahr('Es gibt Einzellastfaelle', einzeln.length > 1);
    wahr('… und keiner von ihnen traegt eine Spanne',
         einzeln.every((e) => (e.knoten ?? []).every((r) => r.spanne === undefined)));
    /*
     * DAS DIAGRAMM ZEICHNET DAS BAND NUR DORT, WO ES EINES GIBT.
     */
    const CHT = await import(J('render.charts.js'));
    const dH = CHT.diagramme(hFL, 900);
    wahr('Das Huellkurven-Diagramm traegt Bandflaechen',
         (dH.schnittgroessen.match(/class="band /g) ?? []).length === 4,
         `${(dH.schnittgroessen.match(/class="band /g) ?? []).length} Bänder`);
    wahr('… und sagt im Titel, was das Band ist',
         dH.schnittgroessen.includes('Spanne über alle Kombinationen'));
    const dE = CHT.diagramme(einzeln[0], 900);
    wahr('Ein einzelner Lastfall zeichnet keines',
         !dE.schnittgroessen.includes('class="band '));
    wahr('… und nennt sich auch nicht umhüllend',
         !dE.schnittgroessen.includes('umhüllend'));
  }

  /* =========================================================================
   * >>> DIE AUSKRAGUNG IST FREI - NICHT NUR IM ENDFELD. <<<
   * =========================================================================
   *
   * Weisung vom 15. September: "die auskragung kann frei gewaehlt werden
   * nicht nur innerhalb des endfeldes."
   *
   * Am 13. September hatte ich festgehalten, das Auflager liege frei IM
   * ENDFELD - und genau darin lag die Grenze: `mastFreiraum` suchte das
   * ERSTE Blech, auf das der Mast trifft, wenn er vom Jochende nach innen
   * wandert. Damit endete die zulaessige Lage vor dem ersten Bindeblech,
   * obwohl zwischen je zwei Blechen dieselbe Luecke steht.
   *
   * JETZT GILT NUR NOCH: der Mast darf in keinem Blech stehen. In welchem
   * Feld er steht, ist seine Sache.
   *
   * Die Stationsliste kann das seit je - `kragA` ruecken die Mastachse nach
   * innen, und der Gurt bekommt dort einen eigenen Knoten, auch mitten im
   * Feld zwischen zwei Blechen.
   * ======================================================================= */
  {
    const frei = bau({ mastVorhanden: true, mastProfil: 'HEB 260', L: 20,
                       kragA: 0.4 });
    const bF = AX.stabmodell(frei.m, { knotenmodell: 'anschnitt' });
    const stF = bF.staebe.find((s) => s.name === 'LINK_A_OGL');
    const kF = bF.knoten.get(stF.bis);
    // Seit dem 15. September haelt das Link an der Konsolspitze, also eine
    // halbe Mastbreite innerhalb der Mastachse.
    pruef('Der Auflagerknoten sitzt an der Konsolspitze', kF.x, 0.53, 1e-9, 'm');
    /*
     * UND ER IST EINE EIGENE STATION, keine gerundete. Die Nachbarn liegen
     * bei 0.05 und 0.70 - waere gerundet worden, laege er auf einem davon.
     */
    const stationen = [...bF.knoten.keys()]
      .filter((n) => /^OGL_/.test(n))
      .map((n) => Number(n.split('_')[1]))
      .sort((a, b) => a - b);
    wahr('… und steht als eigene Station in der Liste',
         stationen.some((v) => Math.abs(v - 0.53) < 1e-9),
         stationen.slice(0, 6).map((v) => v.toFixed(2)).join(', '));
    wahr('Die Mastachse bleibt ebenfalls eine Station',
         stationen.some((v) => Math.abs(v - 0.4) < 1e-9));
    const nachbarn = stationen.filter((v) => Math.abs(v - 0.4) > 1e-9);
    wahr('… zwischen zwei Blechstationen, nicht auf einer',
         nachbarn.some((v) => v < 0.4) && nachbarn.some((v) => v > 0.4));
    // Und dasselbe am anderen Ende.
    const frei2 = bau({ mastVorhanden: true, mastProfil: 'HEB 260', L: 20,
                        kragB: 0.4 });
    const bF2 = AX.stabmodell(frei2.m, { knotenmodell: 'anschnitt' });
    const st2 = bF2.staebe.find((s) => s.name === 'LINK_B_OGL');
    pruef('Am Ende B ebenso', bF2.knoten.get(st2.bis).x, 19.47, 1e-9, 'm');
    /* =====================================================================
     * >>> UND JETZT WEIT INNERHALB, DRITTES FELD. <<<
     * =====================================================================
     *
     * Das ist die Weisung vom 15. September. Beim J90 sitzt das erste Blech
     * bei 0.75, danach laeuft die Regelteilung; ein Mast bei 2.20 m steht
     * mehrere Felder weit innen. Er muss dort genauso zulaessig sein wie im
     * Endfeld - es sei denn, er stuende in einem Blech.
     */
    const tief = bau({ mastVorhanden: true, mastProfil: 'HEB 260', L: 20,
                       kragA: 2.2 });
    const bT = AX.stabmodell(tief.m, { knotenmodell: 'anschnitt' });
    const stT = bT.staebe.find((s) => s.name === 'LINK_A_OGL');
    pruef('Auch im dritten Feld haelt das Link den Gurt',
          bT.knoten.get(stT.bis).x, 2.33, 1e-9, 'm');
    const stationenT = [...bT.knoten.keys()]
      .filter((n) => /^OGL_/.test(n))
      .map((n) => Number(n.split('_')[1]))
      .sort((a, b) => a - b);
    wahr('Die Mastachse steht auch dort als eigene Station',
         stationenT.some((v) => Math.abs(v - 2.2) < 1e-9),
         stationenT.slice(0, 8).map((v) => v.toFixed(2)).join(', '));
    pruef('Und die Stützweite folgt der Auskragung',
          tief.m.stuetzweite, 17.8, 1e-9, 'm');
  }

  /* =========================================================================
   * >>> BEFUND: DAS GESAMTURTEIL KENNT DEN MASTNACHWEIS NICHT. <<<
   * =========================================================================
   *
   * Gefunden am 13. September beim Einbau der eta-Marke in die Leiste - sie
   * stellt Traeger und Mast nebeneinander, und genau dort faellt es auf.
   *
   * GEMESSEN an einem J90 / 20.00 m auf einem HEB 200, 13.00 m hoch:
   *
   *   Mast, Nachweis nach SIA 263        eta = 3.140
   *   etaGesamt (Fussleiste, Urteil)     eta = 0.387
   *   urteilKonstruktion                 alleOk = true
   *
   * Die Fussleiste meldet dabei «Alle Nachweise erfuellt · eta = 0.387»,
   * waehrend ein gefuehrter Nachweis dreifach ueberschritten ist.
   *
   * >>> WARUM DAS SO IST. <<<
   *
   * `etaGesamt` ist das Maximum ueber die Knoten des ERSATZBALKENS - der
   * Traeger, nichts sonst. Der Mastnachweis laeuft daneben (`erg.mast`), hat
   * seine Gruppe in NACHWEISGRUPPEN (`key: 'mast'`, standard: true), aber
   * KEIN `gilt` - es gibt keine Pruefung, die ihm zugeordnet waere. Damit
   * geht er weder in `etaGesamt` noch in `urteilKonstruktion` ein.
   *
   * >>> ENTSCHIEDEN AM 17. SEPTEMBER: «Maximum, mit Bauteil». <<<
   *
   * `bauteilUrteil` (core.checks.js) nimmt Joch, Masten und Anker; die
   * Fussleiste, die Hauptkachel und der Bericht nennen das massgebende.
   * `etaGesamt` bleibt die Zahl des Jochs.
   * ======================================================================= */
  {
    const { m: mSchlank } = bau({ mastVorhanden: true, mastProfil: 'HEB 200',
                                  mastH: 13.0, L: 20 });
    const CH2 = await import(J('core.checks.js'));
    const eSchlank = berechne({ ...standardwerte(), typ: 'J90', L: 20,
      mastVorhanden: true, mastProfil: 'HEB 200', mastH: 13.0 },
      getProfil(standardwerte().profOG), getProfil(standardwerte().profUG),
      getStahl(standardwerte().stahl), T.getTragjoch('J90'));
    const etaMast = eSchlank.mast?.etaNachweis ?? 0;
    wahr('Der Mast ist deutlich ueberschritten', etaMast > 2,
         `η = ${etaMast.toFixed(3)}`);
    wahr('… und etaGesamt weiss nichts davon',
         eSchlank.max.etaGesamt < 1,
         `etaGesamt = ${eSchlank.max.etaGesamt.toFixed(3)}`);
    const ckS = CH2.konstruktionsChecks(eSchlank.modell);
    const urt = CH2.urteilKonstruktion(ckS, standardwerte().nachweise, 'joch');
    const bt = CH2.bauteilUrteil(eSchlank, standardwerte().nachweise, 'joch');
    pruef('Das Urteil nimmt den Mast', bt.eta, etaMast, 1e-12, '–');
    wahr('… nennt ihn als massgebend und gilt als nicht erfuellt',
         bt.massgebend?.key === 'mast' && bt.ueber === true,
         `${bt.massgebend?.name} · ${bt.liste.map((x) => `${x.name} ${x.eta?.toFixed(3)}`).join(', ')}`);
    wahr('… und fuehrt das Joch daneben mit seiner eigenen Zahl',
         bt.liste.some((x) => x.key === 'joch' && x.eta === eSchlank.max.etaGesamt));
    const ohneMast = CH2.bauteilUrteil(eSchlank,
      { ...standardwerte().nachweise, mast: false }, 'joch');
    wahr('Ein abgeschalteter Mastnachweis zaehlt nicht',
         !ohneMast.liste.some((x) => x.key === 'mast') && !ohneMast.ueber);
    wahr('Ein nicht lieferbarer Anker gilt als nicht erfuellt',
         CH2.bauteilUrteil({ ...eSchlank, anker: { A: { nachweis:
           { typ: 'Druckstütze', lieferbar: false, eta: null, N: -5 } } } },
         { ...standardwerte().nachweise, mast: false }, 'joch').ueber === true);
    const aq = APP_QUELLE();
    wahr('Die Fussleiste urteilt ueber alle Bauteile',
         /urteil\.bauteile = bauteilUrteil\(/.test(aq)
         && /const gut = e <= 1 && !bt\?\.ueber/.test(aq));
    wahr('Der Bericht fuehrt das Gesamturteil',
         readFileSync(join(HIER, 'js', 'export.bericht.js'), 'utf8').includes("B('Gesamturteil')"));
    wahr('Der Mastnachweis steht im Ergebnis', Number.isFinite(etaMast));
  }

  /* =========================================================================
   * >>> TRAGSEIL UND FAHRDRAHT, GETRENNT GEWAEHLT. <<<
   * =========================================================================
   *
   * Weisung vom 13. September: «wir wollten die kettenwerke ts + fd
   * separieren bei der voreingabe der bauteile. da sonst die eingabe
   * verschachtelt wird.»
   *
   * Die Tabelle fuehrt jede Paarung als eigenen Eintrag; bei n Tragseilen
   * und m Fahrdraehten sind das n mal m Zeilen in einer Auswahlliste.
   * ======================================================================= */
  {
    const FLK = await import(J('data.fl.js'));
    /*
     * 1 - DIE ZERLEGUNG LIEST DEN NAMEN.
     *
     * «Ts: X / Fd: Y» sagt beides. Der LEITER traegt seine Familie mit -
     * derselbe Draht hat in zwei Familien verschiedene Zugkraefte (Cu 107:
     * 8.5 kN in der N-FL, 10.0 kN in der R-FL), und ohne die Familie waere
     * die Auswahl zweideutig.
     */
    const kw = FLK.getFlBauteil('drahtwerk-n-fl-ts-stcu-50-fd-cu-107');
    const z = FLK.flZerlegung(kw);
    wahr('Das Kettenwerk zerfaellt in Tragseil und Fahrdraht',
         z.ts === 'N-FL StCu 50' && z.fd === 'N-FL Cu 107',
         `${z.ts} / ${z.fd}`);
    wahr('… und traegt seine Familie mit', z.familie === 'N-FL');
    pruef('Einfach heisst Anzahl eins', z.anzahl, 1, 1e-12, '–');
    const z2 = FLK.flZerlegung(
      FLK.getFlBauteil('drahtwerk-n-fl-ts-stcu-50-fd-cu-107-x2'));
    pruef('… und (x2) heisst zwei', z2.anzahl, 2, 1e-12, '–');
    const ze = FLK.flZerlegung(FLK.getFlBauteil('drahtwerk-cu-95'));
    wahr('Ein einzelner Leiter hat weder Ts noch Fd',
         !ze.ts && !ze.fd && ze.leiter === 'Cu 95', JSON.stringify(ze));
    /*
     * 2 - DIE LISTEN KOMMEN AUS DEN KETTENWERKEN, nicht aus einer gepflegten
     * Aufzaehlung. Kommt eine neue Paarung in die Tabelle, steht sie ohne
     * Zutun in beiden Listen.
     */
    const ts = FLK.flTragseile().map((x) => x.name);
    const fd = FLK.flFahrdraehte().map((x) => x.name);
    wahr('Die Tragseile stehen zur Wahl',
         ts.includes('N-FL StCu 50') && ts.includes('R-FL StCu 92'),
         ts.join(', '));
    wahr('Die Fahrdraehte auch',
         fd.includes('N-FL Cu 107') && fd.includes('N-FL Cu 150')
         && fd.includes('R-FL Cu 107'), fd.join(', '));
    wahr('Cu 150 gibt es nur in der Paarung',
         !FLK.flBauteile('drahtwerk').some((b) =>
           FLK.flZerlegung(b).leiter === 'N-FL Cu 150'));
    wahr('Cu 95 steht bei den einzelnen Leitern',
         FLK.flEinzelleiter().some((b) => b.id === 'drahtwerk-cu-95'));
    /*
     * 3 - DIE PAARUNG FINDET DEN TABELLENEINTRAG.
     */
    for (const [a, b, soll] of [
      ['N-FL StCu 50', 'N-FL Cu 107', 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107'],
      ['N-FL StCu 50', 'N-FL Cu 150', 'drahtwerk-n-fl-ts-stcu-50-fd-cu-150'],
      ['R-FL StCu 92', 'R-FL Cu 107', 'drahtwerk-r-fl-ts-stcu-92-fd-cu-107'],
    ]) {
      wahr(`${a} + ${b}`, FLK.flPaarung(a, b)?.id === soll,
           FLK.flPaarung(a, b)?.id ?? '(keine)');
    }
    wahr('Eine Paarung ueber die Familien hinweg gibt es nicht',
         FLK.flPaarung('N-FL StCu 50', 'R-FL Cu 107') === null);
    wahr('Ohne Partner kommt der einzelne Leiter',
         FLK.flPaarung('N-FL StCu 50', null)?.id === 'drahtwerk-n-fl-stcu-50');
    wahr('Und das Vielfache wird mitgefuehrt',
         FLK.flPaarung('N-FL StCu 50', 'N-FL Cu 107', 2)?.id
           === 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107-x2');

    /* =====================================================================
     * >>> 4 - UND HIER IST DER GRUND, WARUM NICHT SUMMIERT WIRD. <<<
     * =====================================================================
     *
     * Gewicht und Leiterzug addieren sich exakt, der WIND nicht. Das
     * Kettenwerk traegt rund fuenfzehn Prozent mehr als seine beiden Leiter
     * zusammen - die Haenger und das Y-Beiseil haben auch eine Flaeche, und
     * die Tabelle fuehrt sie im Kettenwerk mit.
     *
     * «Massgebend sind die Daten, nicht die Herleitung» - die stehende
     * Vorgabe des Auftraggebers, und hier ist der Fall, fuer den sie
     * geschrieben ist. Wer Ts und Fd einzeln ansetzt und addiert, rechnet
     * den Wind zu klein.
     */
    const tsB = FLK.getFlBauteil('drahtwerk-n-fl-stcu-50');
    const fdB = FLK.getFlBauteil('drahtwerk-n-fl-cu-107');
    pruef('Das Eigengewicht addiert sich', kw.eigengewicht,
          tsB.eigengewicht + fdB.eigengewicht, 1e-12, 'kN/m');
    pruef('Der Leiterzug auch', kw.leiterzug,
          tsB.leiterzug + fdB.leiterzug, 1e-12, 'kN');
    const wq = (b, ek) => (b.windQuer ?? {})[ek];
    for (const ek of ['EK1', 'EK2', 'EK3']) {
      const summe = wq(tsB, ek) + wq(fdB, ek);
      wahr(`Der Wind ${ek} ist MEHR als die Summe`, wq(kw, ek) > summe + 1e-9,
           `${wq(kw, ek)} gegen ${Math.round(summe * 1e5) / 1e5}`);
    }
    pruef('Und zwar um rund fuenfzehn Prozent',
          wq(kw, 'EK2') / (wq(tsB, 'EK2') + wq(fdB, 'EK2')), 1.1538, 1e-3, '–');
    /*
     * 5 - DIE VIELFACHEN SIND EXAKTE VIELFACHE. Das ist kein Zufall, und es
     * ist die Voraussetzung dafuer, dass man sie eines Tages durch das Feld
     * `anzahl` ersetzen koennte.
     */
    const e95 = FLK.getFlBauteil('drahtwerk-cu-95');
    for (const [id, n] of [['drahtwerk-cu-95-x2', 2], ['drahtwerk-cu-95-x3', 3],
                           ['drahtwerk-cu-95-x4', 4]]) {
      const b = FLK.getFlBauteil(id);
      pruef(`Cu 95 (x${n}): Gewicht`, b.eigengewicht,
            e95.eigengewicht * n, 1e-12, 'kN/m');
      pruef(`Cu 95 (x${n}): Wind EK2`, wq(b, 'EK2'), wq(e95, 'EK2') * n,
            1e-12, 'kN/m');
    }
    /*
     * 6 - DIE MASKE ZEIGT DIE KETTENWERKE NICHT MEHR IN DER LISTE - sie sind
     * das ERGEBNIS zweier Wahlen. Geprueft wird die Quelle; `modulListeHtml`
     * braucht die Karte einer Baugruppe und laeuft hier nicht.
     */
    const uq3 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Die Auswahl laesst die Kettenwerke weg',
         uq3.includes("gruppe('drahtwerk', 'Leiter', (b) => !istKettenwerk(b))")
         || uq3.includes('!istKettenwerk(b) || (fremd'));
    wahr('… zeigt aber das Tragseil des gespeicherten Kettenwerks',
         uq3.includes('const listenWert = (id)'));
    wahr('Der Partner bildet eine Paarung, kein Feld',
         uq3.includes("if (feld === 'partner')"));
    wahr('… und ueberlebt den Wechsel des Leiters',
         uq3.includes("if (feld === 'bauteil')"));
  }

  /* =========================================================================
   * >>> DER HAKEN NIMMT DEN FAHRDRAHT WEG, NICHT DAS KETTENWERK. <<<
   * =========================================================================
   *
   * Weisung vom 13. September: «Die Auswahl der einwirkungen bei den leitern
   * die auswaehlbar sind, sollten sich ausschliesslich auf den fahrdraht
   * beziehen, da es vorkommt, dass die ablenkung und der wind separat durch
   * einen fahrdrahtabzug der an einer haengestuetze befestigt ist aufgenommen
   * wird.»
   *
   * Sie schaerft die Weisung vom 28. August: dort ging es um den Fahrdraht,
   * der seine Ablenkung in die Drueckstuetze abgibt. Bis dahin nahm ein
   * abgehakter Anteil aber das GANZE Modul weg - bei einem Kettenwerk also
   * Tragseil UND Fahrdraht.
   *
   * GEMESSEN am N-FL Ts: StCu 50 / Fd: Cu 107, EK2, 40 m, R = 600 m:
   *
   *                        G_z       G_x (Ablenkung)   Q_x (Wind)
   *   alles an            0.8000         0.9933          0.9600
   *   ohne Ablenkung      0.8000         0.4267          0.9600
   *   ohne Wind           0.8000         0.9933          0.5440
   *   ohne Gewicht        0.4000         0.9933          0.9600
   *   Tragseil allein     0.4000         0.4267          0.4160
   *   Fahrdraht allein    0.4000         0.5667          0.4160
   *
   * >>> DIE DIFFERENZ, NICHT DER TABELLENWERT DES TRAGSEILS. <<<
   *
   * Beim WIND bleibt 0.5440 stehen, waehrend das Tragseil allein nur 0.4160
   * traegt: die Haenger und das Y-Beiseil bleiben beim Rest, wo sie
   * hingehoeren. Wer stattdessen den Tragseil-Eintrag naehme, liesse sie
   * unter den Tisch fallen.
   * ======================================================================= */
  {
    const AB = await import(J('data.anbauteile.js'));
    const trasse = { ek: 'EK2', spannweite: 40, R: 600 };
    const bau = (bauteil, wirk = {}) => AB.normalisiereAnbauteil({
      id: 'AT1', name: 'Probe', x: 0, ort: 'joch', lasten: [],
      module: [{ bauteil, x: 0, y: 0, z: -2.7, anzahl: 1, ...wirk }] });
    const s = (bauteil, wirk) => AB.baugruppeSumme(bau(bauteil, wirk), trasse);
    const KW = 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107';
    const TS = 'drahtwerk-n-fl-stcu-50';
    const FD = 'drahtwerk-n-fl-cu-107';
    const ganz = s(KW), ts = s(TS), fd = s(FD);

    /*
     * 1 - MIT ALLEN HAKEN AENDERT SICH NICHTS. Die Vorgabe ist unveraendert;
     * wer nichts abwaehlt, rechnet wie vorher.
     */
    pruef('Kettenwerk, alles an: Gewicht', ganz.Gz, 0.8, 1e-9, 'kN');
    pruef('… Ablenkung', ganz.Gx, 0.9933, 1e-3, 'kN');
    pruef('… Wind', ganz.Qx, 0.96, 1e-9, 'kN');

    /*
     * 2 - ABGEHAKT HEISST: OHNE DEN FAHRDRAHT-ANTEIL.
     */
    /* =====================================================================
     * >>> DREI HAKEN, ZWEI BEZUEGE - UND ZWAR AUS DER SACHE HERAUS. <<<
     * =====================================================================
     *
     * Frage vom 15. September: «es gibt auch abzugsmasten, diese lenken nur
     * die leiter um, dies gilt dann fuer tragseil und fahrdraht. das heisst
     * hier wirken nur ablenk und wind lasten.»
     *
     * Zwei Faelle, die in verschiedene Richtungen ziehen:
     *
     *   FAHRDRAHTABZUG   Ablenkung und Wind des FAHRDRAHTS gehen an die
     *                    Haengestuetze, sein Gewicht haengt am Tragseil.
     *   ABZUGSMAST       lenkt nur um: kein Gewicht, weder vom Tragseil
     *                    noch vom Fahrdraht - aber Ablenkung und Wind
     *                    von BEIDEN.
     *
     * Ein zusaetzliches Feld braucht es dafuer nicht. Das GEWICHT gilt
     * beiden Leitern (es haengt am Tragseil - Weisung vom 28. August),
     * ABLENKUNG und WIND dem Fahrdraht. Damit trifft dieselbe Zeile beide
     * Faelle.
     */
    pruef('Ohne Ablenkung bleibt die des Tragseils',
          s(KW, { wirktAblenk: false }).Gx, ts.Gx, 1e-9, 'kN');
    pruef('Ohne Wind bleibt Kettenwerk minus Fahrdraht',
          s(KW, { wirktQ: false }).Qx, ganz.Qx - fd.Qx, 1e-9, 'kN');
    /*
     * >>> DAS GEWICHT ABER FAELLT FUER BEIDE. <<<
     *
     * Das ist der Abzugsmast. Bliebe hier das Tragseilgewicht stehen, haette
     * man einen Masten, der die Leiter nur umlenkt - und trotzdem ihr halbes
     * Gewicht traegt.
     */
    pruef('Ohne Gewicht faellt es fuer beide Leiter',
          s(KW, { wirktG: false }).Gz, 0, 1e-12, 'kN');
    /*
     * >>> DER ABZUGSMAST, IN EINER ZEILE. <<<
     *
     * Gewicht ab, Ablenkung und Wind an: dann wirken beide Leiter mit ihrer
     * ganzen Umlenkkraft und ihrem ganzen Wind, und nichts haengt vertikal.
     */
    const abzug = s(KW, { wirktG: false });
    pruef('Abzugsmast: kein Gewicht', abzug.Gz, 0, 1e-12, 'kN');
    pruef('… aber die ganze Ablenkung beider Leiter', abzug.Gx, ganz.Gx,
          1e-12, 'kN');
    pruef('… und der ganze Wind', abzug.Qx, ganz.Qx, 1e-12, 'kN');
    /*
     * UND DER FAHRDRAHTABZUG, zum Vergleich: das Gewicht bleibt ganz, weil
     * es am Tragseil haengt; nur Ablenkung und Wind des Fahrdrahts fallen.
     */
    const fdAbzug = s(KW, { wirktAblenk: false, wirktQ: false });
    pruef('Fahrdrahtabzug: das Gewicht bleibt ganz', fdAbzug.Gz, ganz.Gz,
          1e-12, 'kN');
    pruef('… die Ablenkung nur die des Tragseils', fdAbzug.Gx, ts.Gx,
          1e-9, 'kN');
    wahr('… und der Wind traegt die Haenger mit',
         fdAbzug.Qx > ts.Qx + 1e-9,
         `${fdAbzug.Qx.toFixed(4)} gegen ${ts.Qx.toFixed(4)}`);
    /*
     * 3 - BEI EINEM EINZELNEN LEITER FAELLT ER GANZ WEG - wie bisher. Es
     * gibt keinen Fahrdraht-Anteil abzuziehen.
     */
    pruef('Einzelleiter, ohne Gewicht', s(FD, { wirktG: false }).Gz,
          0, 1e-12, 'kN');
    pruef('… ohne Ablenkung', s(FD, { wirktAblenk: false }).Gx, 0, 1e-12, 'kN');
    pruef('… ohne Wind', s(FD, { wirktQ: false }).Qx, 0, 1e-12, 'kN');

    /*
     * 4 - UND WENN ES DEN FAHRDRAHT NICHT EINZELN GIBT.
     *
     * «N-FL Cu 150» steht nur in der Paarung. Dann laesst sich kein Anteil
     * abziehen, und der Haken wirkt wie frueher auf das ganze Modul. Still
     * die Haelfte zu rechnen waere die schlechteste der drei Antworten.
     */
    const KW150 = 'drahtwerk-n-fl-ts-stcu-50-fd-cu-150';
    const FLB = await import(J('data.fl.js'));
    wahr('Cu 150 gibt es nicht einzeln',
         FLB.flPaarung(null, 'N-FL Cu 150') === null);
    pruef('Dann nimmt der Haken alles weg',
          s(KW150, { wirktQ: false }).Qx, 0, 1e-12, 'kN');
    /*
     * DIE WIRKUNG SAGT ES AUCH: `fdTrennbar` steht am Teil, damit Maske und
     * Ausleitung es benennen koennen.
     */
    const t1 = s(KW).teile[0];
    const t2 = s(KW150).teile[0];
    wahr('Beim Cu 107 ist der Anteil trennbar', t1.wirkung?.fdTrennbar === true);
    wahr('… beim Cu 150 nicht', t2.wirkung?.fdTrennbar === false);
    wahr('Und der Fahrdraht steht beim Teil',
         t1.wirkung?.fahrdraht === 'N-FL Cu 107', String(t1.wirkung?.fahrdraht));
  }

  /* =========================================================================
   * >>> DAS PARTNERFELD: HIERARCHISCH, BUENDIG, OHNE SPRUNG. <<<
   * =========================================================================
   *
   * Weisung vom 13. September, drei Saetze auf einmal:
   *
   *   «die sekundaere eingabe hirarchisch verstehen. nur wenn ein tragseil
   *    eingegeben wird dann zusatzauswahl moeglich machen.»
   *   «das feld fuer die zusatzauswahl ist zur zeit versetzt und etwas
   *    groesser als die hauptauswahl.»
   *   «zudem springt die anzeige wenn es eingeblendet wird.»
   *
   * Im Browser nachgemessen: der Kopf ist 296 px breit, darin die Auswahl
   * 271 px, 5 px Abstand, der Knopf «x» 20 px. Das Partnerfeld stand mit
   * einer Beschriftung von 62 px davor - 67 px eingerueckt, 42 px schmaler.
   * Nach dem Umbau: 0 und 0.
   */
  {
    const uq4 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Der Partner gilt nur am Tragseil',
         uq4.includes('const istTs = kw || flTragseile()'));
    /* =====================================================================
     * >>> WAS NICHT GILT, VERSCHWINDET - ES STEHT NICHT GESPERRT DA. <<<
     * =====================================================================
     *
     * Weisung vom 15. September: «die fahrdraht auswahl nur auffuehren, wenn
     * stcu 50 oder 92 (Tragseile) ausgewaehlt ist. dynamisch einblenden
     * nicht abgehakt, das gilt fuer alle elemente in dieser app.»
     *
     * Sie nimmt eine Loesung vom 13. September zurueck: dort stand das Feld
     * gesperrt da, damit beim Wechsel des Bauteils nichts springt. Die
     * Abwaegung war falsch - ein leeres Feld, das nichts zeigt und nichts
     * kann, ist kein Platzhalter, sondern eine Attrappe.
     *
     * Die Linie des Hauses steht seit dem 1. September in `zeichneMaske`:
     * «wenn nicht aktiv Eingabe ausblenden, sonst verwirrend».
     *
     * >>> DIE REGEL, DIE DARAUS FOLGT - UND SIE GILT DER GANZEN ANWENDUNG.
     *
     * Gesperrt darf ein Bedienelement nur dastehen, wenn es etwas ZEIGT:
     *
     *   ein KATALOGWERT       jd, jbb, g_k - «Werte bearbeiten» gibt sie
     *                         frei, und man soll sehen, womit gerechnet wird
     *   eine OPTION mit Grund «nur ohne Masten im Modell» - wer sie sucht,
     *                         faende sie sonst nicht mehr
     *   eine AUSSAGE          «In diesem Werkzeug nicht enthalten»
     *   ein fester NAME       die Bezeichnung eines vorgegebenen Lastfalls
     *
     * Ein gesperrtes LEERES Feld gehoert weg. Diese Kontrolle zaehlt die
     * Stellen mit `disabled` und nagelt fest, dass jede davon zu einer der
     * vier Sorten gehoert - wer eine fuenfte einbaut, faellt hier auf.
     */
    const sperren = [...uq4.matchAll(/disabled/g)].length;
    wahr('Es gibt genau vier Stellen mit einer Sperre', sperren === 4,
         `${sperren} Stellen`);
    wahr('1 - der Katalogwert, den «Werte bearbeiten» freigibt',
         uq4.includes("const dis = gesperrt ? ' disabled' : '';"));
    /*
     * >>> ZWEI DAVON SIND AM 15. SEPTEMBER AUSDRUECKLICH BESTAETIGT. <<<
     *
     * Vorgelegt wurde die Frage, ob auch die Option «Kragarm - nur ohne
     * Masten im Modell» und die Nachweisgruppe «Knicken Joch» verschwinden
     * sollen, statt ausgegraut dazustehen. Antwort: «beide so lassen.»
     *
     * DER GRUND, den die Antwort bestaetigt: beide tragen eine Auskunft, die
     * beim Ausblenden verloren ginge.
     *
     *   Die OPTION steht in einer Liste. Waere sie weg, fragte sich der
     *   Anwender, wo die Wahl hin ist - ausgegraut sagt sie, dass es sie
     *   gibt und warum sie hier nicht geht.
     *
     *   Die NACHWEISGRUPPE sagt, dass dieser Nachweis im Werkzeug NICHT
     *   enthalten ist und separat zu fuehren waere. Ausgeblendet wuesste
     *   niemand, dass er fehlt - und das ist die gefaehrlichere Luecke.
     *
     * Wer sie beim naechsten Aufraeumen wegnimmt, faellt hier auf.
     */
    wahr('2 - die Option, die ihren Grund im Text traegt (bestaetigt 15.9.)',
         uq4.includes("o.aus ? ' disabled' : ''"));
    wahr('3 - die Nachweisgruppe, die es nicht gibt (bestaetigt 15.9.)',
         uq4.includes("g.vorhanden ? '' : ' disabled'"));
    /*
     * UND DIE AUSKUNFT, DIE BEIDE TRAGEN, MUSS STEHEN BLEIBEN. Eine
     * ausgegraute Zeile ohne Begruendung waere das Schlechteste von beidem:
     * sie nimmt Platz und sagt nichts.
     */
    const sq = readFileSync(join(HIER, 'js', 'ui.schema.js'), 'utf8');
    wahr('… die Option nennt ihren Grund',
         sq.includes('nur ohne Masten im Modell'));
    wahr('… und die Gruppe sagt, dass sie separat zu fuehren ist',
         uq4.includes('separat zu führen'));
    wahr('4 - der Name eines vorgegebenen Lastfalls',
         uq4.includes("lf.eigen || !lf.key ? '' : 'disabled'"));
    /*
     * UND DAS PARTNERFELD IST KEINE FUENFTE: es erscheint, wo es gilt, und
     * verschwindet sonst.
     */
    wahr('Das Partnerfeld steht nur beim Tragseil',
         uq4.includes('if (!istTs) return \'\';'));
    wahr('… und auch nur, wenn es eine Paarung gibt',
         uq4.includes("if (!moeglich.length) return '';"));
    wahr('… gesperrt steht es nirgends mehr',
         !uq4.includes('— nur mit Tragseil'));
    const cssP = readFileSync(join(HIER, 'css', 'style.css'), 'utf8');
    const rP = /\.modul-partner \{([^}]*)\}/.exec(cssP)?.[1] ?? '';
    wahr('Es traegt dasselbe Raster wie der Kopf',
         /grid-template-columns:\s*1fr 20px/.test(rP), rP.trim().slice(0, 70));
    wahr('Die Beschriftung steht darueber, nicht davor',
         /grid-column:\s*1 \/ -1/.test(
           /\.modul-partner-t \{([^}]*)\}/.exec(cssP)?.[1] ?? ''));
    /*
     * >>> MIT DEM FAHRDRAHT ENTSTEHT EIN KETTENWERK - UND ES HEISST SO. <<<
     *
     * Weisung: «wenn fahrdraht zusaetzlich eingegeben wird automatisch eine
     * kw benennung vornehmen.» Die Klammer stand als freies Textfeld da und
     * blieb deshalb meistens leer - und der Havariefall waehlt spaeter
     * darueber aus, welches Kettenwerk reisst.
     */
    wahr('Der Kettenwerk-Name wird vergeben',
         uq4.includes('naechsteKwNummer'));
    wahr('… und ein eigener bleibt stehen',
         uq4.includes('m[mod].kettenwerk || naechsteKwNummer'));
    wahr('… und faellt mit dem Fahrdraht wieder weg',
         uq4.includes('werWeg ? null'));
  }

  /* =========================================================================
   * >>> «(x2)» IST KEINE BAUART, SONDERN EINE ANZAHL. <<<
   * =========================================================================
   *
   * Weisung vom 13. September: «die x2 x3 varianten durch anzahl ersetzen.»
   *
   * Die Tabelle fuehrt «Cu 95», «Cu 95 (x2)», «(x3)», «(x4)» als vier
   * Eintraege - und daneben gibt es das Feld `anzahl`, das dasselbe leistet.
   *
   * >>> DIE UMRECHNUNG AENDERT KEINE ZAHL, UND DAS IST NACHGEMESSEN. <<<
   *
   * Die Voraussetzung steht weiter oben als eigene Kontrolle: die Vielfachen
   * sind EXAKTE Vielfache in Gewicht, Leiterzug und Wind je Klasse. Hier
   * wird geprueft, dass die Umrechnung sie auch trifft.
   *
   * SIE GESCHIEHT BEIM LADEN. Ein gespeicherter Stand zeigt auf «Cu 95
   * (x2)»; zeigte die Maske dann «Cu 95» und die Anzahl 1, staende dort eine
   * Zeile, die das Doppelte rechnet, ohne es zu sagen.
   * ======================================================================= */
  {
    const AB2 = await import(J('data.anbauteile.js'));
    const trasse2 = { ek: 'EK2', spannweite: 40, R: 600 };
    const roh = (bauteil, anzahl = 1) => ({
      id: 'AT9', name: 'Probe', x: 0, ort: 'joch', lasten: [],
      module: [{ bauteil, x: 0, y: 0, z: -2.7, anzahl }] });
    const norm = (bauteil, anzahl) =>
      AB2.normalisiereAnbauteil(roh(bauteil, anzahl)).module[0];

    const m2 = norm('drahtwerk-cu-95-x2');
    wahr('Cu 95 (x2) wird zu Cu 95', m2.bauteil === 'drahtwerk-cu-95',
         m2.bauteil);
    pruef('… mit Anzahl zwei', m2.anzahl, 2, 1e-12, '–');
    const m3 = norm('drahtwerk-cu-95-x3', 2);
    pruef('Eine vorhandene Anzahl wird vervielfacht', m3.anzahl, 6, 1e-12, '–');
    const kwX = norm('drahtwerk-n-fl-ts-stcu-50-fd-cu-107-x2');
    wahr('Auch das doppelte Kettenwerk',
         kwX.bauteil === 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107', kwX.bauteil);
    pruef('… mit Anzahl zwei', kwX.anzahl, 2, 1e-12, '–');
    const m1 = norm('drahtwerk-cu-95');
    wahr('Der einfache Eintrag bleibt, wie er ist',
         m1.bauteil === 'drahtwerk-cu-95' && (m1.anzahl ?? 1) === 1);
    /*
     * >>> UND DIE KRAEFTE BLEIBEN GLEICH. <<<
     *
     * Das ist der eigentliche Nachweis: dieselbe Baugruppe, einmal ueber den
     * (x2)-Eintrag und einmal ueber Anzahl zwei - Zahl fuer Zahl dasselbe.
     */
    const s2 = (a) => AB2.baugruppeSumme(AB2.normalisiereAnbauteil(a), trasse2);
    const ueber = s2(roh('drahtwerk-cu-95-x2'));
    const direkt = s2(roh('drahtwerk-cu-95', 2));
    for (const f of ['Gz', 'Gx', 'Qx', 'Qy']) {
      pruef(`Cu 95 doppelt: ${f}`, ueber[f], direkt[f], 1e-12, 'kN');
    }
    const kwUeber = s2(roh('drahtwerk-n-fl-ts-stcu-50-fd-cu-107-x2'));
    const kwDirekt = s2(roh('drahtwerk-n-fl-ts-stcu-50-fd-cu-107', 2));
    for (const f of ['Gz', 'Gx', 'Qx']) {
      pruef(`Kettenwerk doppelt: ${f}`, kwUeber[f], kwDirekt[f], 1e-12, 'kN');
    }
    /*
     * IN DER AUSWAHL STEHEN SIE NICHT MEHR. Ein geladener Satz wird
     * umgerechnet, also bleibt nichts uebrig, worauf noch etwas zeigt.
     */
    const uq5 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Die Liste laesst die Vielfachen weg',
         uq5.includes('const einfach = (b) => (flZerlegung(b).anzahl ?? 1) <= 1'));
    wahr('… zeigt aber einen gespeicherten Eintrag weiter an',
         uq5.includes('(einfach(b) || b.id === wert)'));
  }

  // --- Was die Bruecke koennen muss ---------------------------------------
  {
    const PS1 = readFileSync(join(HIER, 'com', 'AxisVM_aufbauen.ps1'), 'utf8');
    // Die Feder steht am Ersatzbalken als DREHfeder; die Bruecke muss sie
    // setzen koennen. Der lotrechte Federweg bleibt vorbereitet - er kostet
    // nichts und waere sonst beim naechsten Anlauf wieder zu bauen.
    wahr('Die Bruecke setzt die Drehfeder', PS1.includes('$zahl $a.fiy $a.cFiy_kNm'));
    wahr('Und kann eine lotrechte Feder setzen', PS1.includes('$zahl $a.uz  $a.cUz_kNm'));
    // GERECHNET WIRD NUR AUF WEISUNG.
    wahr('Rechnen ist ein eigener Schalter', /\[switch\]\$Rechnen/.test(PS1));
    wahr('Ohne ihn bleibt es beim Hinweis',
         PS1.includes("Schreib 'Das Modell steht. NICHT gerechnet"));
    wahr('Gerechnet wird linear statisch, ohne Rueckfrage',
         PS1.includes('Calculation.LinearAnalysis($cui)'));
    // Und im SELBEN Lauf gelesen - eine neue Instanz kennt keine Ergebnisse.
    wahr('Auslesen ist eine Funktion, aus beiden Wegen erreichbar',
         PS1.includes('function Lies-Schnittgroessen'));
    wahr('Nach dem Rechnen wird im selben Lauf gelesen',
         PS1.includes('$nGel = Lies-Schnittgroessen $m $Ziel'));
    // Der Satz muss vorher dastehen - sonst stirbt der Prozess.
    wahr('Der Ergebnissatz wird vorbereitet',
         PS1.includes("NeuerSatz 'RLineForceValues'"));
  }

  // --- Was die Feder wert ist: sie haengt am LASTFALL ---------------------
  /*
   * Die Verbindung Joch-Mast traegt nur bis zur Grenzlast ihrer Schrauben;
   * die Feder wird deshalb je Lastfall herabgesetzt (begrenzeFeder). Sie ist
   * damit KEINE Eigenschaft des Bauwerks allein. Das ausgeleitete Modell
   * traegt die Feder der BEMESSUNGSKOMBINATION - eine Zahl, ein Modell.
   * Diese Pruefung haelt fest, dass die Spanne wirklich gross ist, damit die
   * Wahl nicht als Kleinigkeit durchgeht.
   */
  {
    const basisW = { ...standardwerte(), typ: 'J90', L: 20,
                     endbedingung: 'mast', mastProfil: 'HEB 260', mastH: 7.5,
                     anbauteile: [A.neuesAnbauteil('hs-nt-ausleger', 10)] };
    const cVon = (lf) => {
      const e = berechne({ ...basisW, lastfall: lf }, getProfil(basisW.profOG),
                         getProfil(basisW.profUG), getStahl(basisW.stahl),
                         T.getTragjoch(basisW.typ));
      return e.modell.federn.cA;
    };
    const werte = ['gk', 'wyk', 'windXm'].map(cVon);
    wahr('Die wirksame Feder haengt am Lastfall',
         Math.max(...werte) / Math.min(...werte) > 2,
         werte.map((v) => v.toFixed(0)).join(' / ') + ' kNm/rad');

    // Und die geometrische Feder kennt zwei Werte - je nachdem, ob sich der
    // Rahmen verschieben kann.
    const st = AU.mastSteifigkeit(basisW, 'A', false);
    pruef('Unverschieblich ist die Feder 3.10 mal die des Kragmastes',
          st.cUnverschieblich / st.cKragarm, AU.MAST_UNVERSCHIEBLICH, 1e-12, '-');
    wahr('Und der Anschlussfaktor greift nur im verschieblichen Fall',
         AU.mastSteifigkeit(basisW, 'A', true).cPhi
           === AU.mastSteifigkeit(basisW, 'A', true).cVerschieblich);
  }
}

titel('34b Die Auflagerbedingung je Gurtebene');

/*
 * WEISUNG DES AUFTRAGGEBERS, 5. September, nach zwei Ausschnitten aus AxisVM:
 *
 *   «der obere ausschnitt ist die halterung der zwei obergurte und die
 *    untere abbildung ist die der untergurte. diese einstellung der
 *    freiheitsgrade gilt in diesem beispiel bei den alten Tragjochen, da
 *    diese verjuengt sind in den enden. wir sollten aber den aufbau gleich
 *    gestalten fuer die restlichen jocharten. die Auflagerbedingung sollten
 *    anpassbar sein in der app.»
 *
 * Was in den Ausschnitten stand:
 *
 *              K_X       K_Y       K_Z      K_XX  K_YY  K_ZZ
 *   OBERGURT     0     1E+10     1E+10        0     0     0
 *   UNTERGURT  1E+10   1E+10     1E+10        0     0     0
 *
 * 1E+10 ist das «starr» der Feder, 0 die echte Freigabe.
 */
{
  const AUF = await import(J('core.auflager.js'));
  const AX = await import(J('export.axisvm.js'));
  const { modell } = await import(J('core.vierendeel.js'));

  const og = AUF.linkBedingung({}, 'joch', 'OG');
  const ug = AUF.linkBedingung({}, 'joch', 'UG');
  /*
   * SEIT DEM 16. SEPTEMBER LIEGT DAS JOCH AUF DEM UNTERGURT (Weisung, am
   * auskragenden Joch in AxisVM so gestellt): Obergurt x y, Untergurt y z.
   */
  wahr('Der Obergurt haelt laengs und quer', og.x === 'Rigid' && og.y === 'Rigid');
  wahr('… und laesst lotrecht los', og.z === 'Free');
  wahr('Der Untergurt haelt quer und lotrecht',
       ug.y === 'Rigid' && ug.z === 'Rigid');
  wahr('… und laesst die Jochachse los', ug.x === 'Free');
  wahr('Die Vorgabe bleibt ein Gelenk',
       AUF.linkEinspannung({}, 'joch', 0.3).art === 'gelenk');
  // K_XX gehalten, die Biegegrade frei (Weisung vom 16. September).
  wahr('Beide halten K_XX und geben die Biegegrade frei',
       og.xx === 'Rigid' && ug.xx === 'Rigid'
       && ['yy', 'zz'].every((f) => og[f] === 'Free' && ug[f] === 'Free'));
  wahr('Ohne Eingabe steht die Vorgabe', !AUF.linkAbweichend({}, 'joch'));

  /*
   * DIE EINSTELLUNG SCHLAEGT DIE VORGABE - aber nur, wo eine steht. Eine
   * halb gefuellte Eingabe darf nicht in eine halbe Lagerung fallen.
   */
  const w1 = { auflagerLinks: { OG: { z: 'Rigid' } } };
  wahr('Ein gesetzter Grad gilt',
       AUF.linkBedingung(w1, 'joch', 'OG').z === 'Rigid');
  wahr('… die uebrigen kommen aus der Vorgabe',
       AUF.linkBedingung(w1, 'joch', 'OG').y === 'Rigid'
       && AUF.linkBedingung(w1, 'joch', 'OG').xx === 'Rigid');
  wahr('Und die Abweichung wird gemeldet', AUF.linkAbweichend(w1, 'joch'));
  const w2 = { auflagerLinks: { UG: { z: 25000, y: 'was?' } } };
  pruef('Eine Zahl bleibt eine Feder',
        AUF.linkBedingung(w2, 'joch', 'UG').z, 25000, 1e-9, 'kN/m');
  wahr('Ein unbrauchbarer Wert faellt zurueck',
       AUF.linkBedingung(w2, 'joch', 'UG').y === 'Rigid');

  /*
   * >>> DAS ABFANGJOCH: DASSELBE, UM NEUNZIG GRAD GEDREHT. <<<
   *
   * Weisung vom 5. September: «bei den Abfangjochen wird man zudem noch die
   * vorderen und hinteren auflager unterschiedlich einstellen koennen, da
   * wir eine Drehfeder um die z achse als gelenk ausbilden wollen, um nicht
   * die biegebeanspruchung in den masten als torsion zu uebertragen.»
   *
   * Seine Gurte liegen NEBENEINANDER in y. Eine Drehung des Endes um z
   * verschiebt sie gegenlaeufig in x - halten beide, ist die Drehung
   * gesperrt, und das Biegemoment aus dem Leiterzug laeuft als Torsion in
   * den Masten. K_ZZ = 0 sieht dann nach einem Gelenk aus und ist keines.
   */
  wahr('Das Abfangjoch fuehrt vorn und hinten',
       AUF.linkEbenen('abfangjoch').map((e) => e.key).join(',') === 'V,H');
  wahr('… und die beiden liegen in y auseinander',
       AUF.linkGelenk('abfangjoch').paarAchse === 'y');
  wahr('Ihr Kraeftepaar sperrt die Drehung um z',
       AUF.linkGelenk('abfangjoch').sperrt === 'zz');
  wahr('Freigegeben wird dafuer die Jochachse',
       AUF.linkGelenk('abfangjoch').gibtFrei === 'x');
  wahr('Der vordere Gurt laesst laengs los',
       AUF.linkBedingung({}, 'abfangjoch', 'V').x === 'Free');
  wahr('Der hintere haelt', AUF.linkBedingung({}, 'abfangjoch', 'H').x === 'Rigid');
  wahr('Beide halten quer und lotrecht',
       ['V', 'H'].every((e) => ['y', 'z'].every(
         (f) => AUF.linkBedingung({}, 'abfangjoch', e)[f] === 'Rigid')));
  /*
   * BEIM TRAGJOCH IST ES DIESELBE ACHSE - kein Zufall: die Ebenen liegen
   * quer zur Traegerachse, und eine Drehung um ihre Verbindungslinie
   * verschiebt sie laengs.
   */
  wahr('Beim Tragjoch liegen die Ebenen in z',
       AUF.linkGelenk('joch').paarAchse === 'z');
  wahr('… ihr Paar sperrt die Drehung um y',
       AUF.linkGelenk('joch').sperrt === 'yy');
  wahr('… und freigegeben wird ebenfalls x',
       AUF.linkGelenk('joch').gibtFrei === 'x');
  wahr('Sechs Freiheitsgrade, drei Kraefte und drei Momente',
       AUF.LINK_GRADE.length === 6
       && AUF.LINK_GRADE.filter((g) => g.art === 'kraft').length === 3);

  /*
   * UND SIE STEHT IN DER HINWEISLISTE. Das Bild ist zugeklappt, sobald man
   * weiterarbeitet; ein Modell, das gar nicht steht, darf man nicht nur
   * dort erfahren, wo man ohnehin schon hinschaut.
   */
  {
    const { hinweise } = await import(J('core.checks.js'));
    const wLab = basis({ endbedingung: 'mast', mastProfil: 'HEB 240',
                         mastH: 7.0, mastSteg: 'jochachse', L: 20 });
    const mLab = modell(wLab, getProfil(wLab.profOG), getProfil(wLab.profUG),
                        getStahl(wLab.stahl), T.getTragjoch('J90'));
    wahr('Mit der Vorgabe steht kein Labilitaetshinweis',
         !hinweise(mLab).some((x) => /LABIL/.test(x)));
    wahr('Ohne Halt in y steht er da',
         hinweise({ ...mLab,
                       auflagerLinks: { OG: { y: 'Free' }, UG: { y: 'Free' } } })
           .some((x) => /LABIL/.test(x)));
    wahr('Ohne Mast im Modell schweigt er - dort traegt die Drehfeder',
         !hinweise({ ...mLab, mastVorhanden: false,
                        auflagerLinks: { OG: { y: 'Free' }, UG: { y: 'Free' } } })
           .some((x) => /LABIL/.test(x)));
  }

  /*
   * >>> DIE BEIDEN ARTEN SEHEN NICHT MEHR GLEICH AUS. <<<
   *
   * Weisung vom 9. September: «die ansicht zeigt nicht das Abfangjoch, es
   * gibt da keine ober und untergurt sondern nur einen traeger.»
   *
   * Das Laengsbild zeichnete beide Arten gleich - zwei Linien mit
   * Querstrichen, die Gestalt des TRAGJOCHS. Das Abfangjoch legt seinen
   * Rahmen waagrecht: zwei Walzprofile nebeneinander, Bleche oben und
   * unten. Im Grundriss sind das zwei Profile mit Breite und dazwischen
   * Blechflaechen.
   */
  {
    const AL2 = await import(J('ui.auflagerlinks.js'));
    const bildJ = AL2.auflagerDiagrammHtml(
      { tragwerksart: 'joch', mastVorhanden: true, jd: 500 }, 'joch');
    const bildA = AL2.auflagerDiagrammHtml(
      { tragwerksart: 'abfangjoch', mastVorhanden: true }, 'abfangjoch');
    /*
     * BEIDE ARTEN ZEIGEN EINE ANSICHT (Weisung, 9. September: «nimm die
     * ansicht anstatt grundriss, so ist es gleich wie beim tragjoch und es
     * kommt nicht zu verwechslungen»). Der Grundriss war fachlich richtig
     * und als PAAR falsch: zwei Bilder nebeneinander, die verschiedene
     * Blickrichtungen meinen, liest man als dieselbe.
     */
    wahr('Beide Arten zeigen eine Ansicht',
         /<b>Ansicht<\/b>/.test(bildJ) && /<b>Ansicht<\/b>/.test(bildA));
    wahr('Kein Grundriss mehr', !/Grundriss/.test(bildA));
    wahr('Beim Abfangjoch ist der hintere Gurt verdeckt',
         /hinterer Gurt verdeckt/.test(bildA));
    /*
     * UND SEINE HALTERUNG WIRD GESTRICHELT GEZEICHNET - die Klasse `hs2`
     * gibt es nur dort, wo eine Ebene hinter der anderen liegt.
     */
    wahr('Die verdeckte Halterung ist als solche gezeichnet',
         /class="hs2/.test(bildA) && !/class="hs2/.test(bildJ));
    wahr('Sein Schnitt nennt die zwei Gurte nebeneinander',
         /zwei Gurte nebeneinander/.test(bildA));
  }

  /*
   * >>> WAS DIE MODELLANSICHT DAVON ZEIGT. <<<
   *
   * Weisung vom 9. September: «die auswirkung im modell 3d noch pruefen.»
   *
   * TRAGJOCH: die Marke am Auflager schreibt die Drehfeder an; mit der
   * Endbedingung «aus der Auflagerbedingung» ist das genau die Zahl, die
   * unter der Matrix steht. Gemessen (J90/20 m, HEB 240/7.0 m):
   *
   *     Vorgabe (Gelenk)          gelenkig · κ 0 %
   *     beide Gurte laengs starr  c_φ 13512 · κ 67 %   (= die Mastfeder)
   *     Gurtfedern 20000          c_φ 2110 · κ 24 %
   *
   * ABFANGJOCH: dort stand «Auflager» und sonst nichts - die eingestellte
   * Bedingung war im Bild unsichtbar. Jetzt traegt die Marke dieselbe
   * Angabe wie beim Tragjoch.
   */
  {
    const R3 = await import(J('render.3d.js'));
    const RA = await import(J('render.abfang.js'));
    const zeilenVon = (sz) => (sz.marken ?? [])
      .filter((x) => x.art === 'auflagertext')
      .map((x) => (x.zeilen ?? []).join(' | '));

    const wA = basis({ endbedingung: 'links', mastProfil: 'HEB 240',
                       mastH: 7.0, mastSteg: 'jochachse', L: 20 });
    const bild = (links) => {
      const w = { ...wA, auflagerLinks: links };
      const e = rechne(w);
      return zeilenVon(R3.erzeugeSzene(e.modell, e));
    };
    wahr('Die Vorgabe steht als Gelenk im Bild',
         bild(undefined).every((z) => /gelenkig/.test(z)), bild(undefined)[0]);
    wahr('Starre Gurte zeigen die Mastfeder',
         bild({ OG: { x: 'Rigid' }, UG: { x: 'Rigid' } })
           .every((z) => /c_φ 13512/.test(z)),
         bild({ OG: { x: 'Rigid' }, UG: { x: 'Rigid' } })[0]);
    wahr('Gurtfedern kommen als Zahl an',
         bild({ OG: { x: 20000 }, UG: { x: 20000 } })
           .every((z) => /c_φ 2110/.test(z)));
    /*
     * UND DIE DREHFEDER AENDERT AUCH IM BILD NICHTS - sie ist keine Eingabe
     * mehr, also darf die Marke sich nicht bewegen.
     */
    wahr('Eine Drehfeder bewegt das Bild nicht',
         bild({ OG: { x: 20000, yy: 50000 }, UG: { x: 20000, yy: 50000 } })
           .join() === bild({ OG: { x: 20000 }, UG: { x: 20000 } }).join());

    // --- Das Abfangjoch ---------------------------------------------------
    if (AJ.abfangDbDa()) {
      const satz = (links) => ({ tragwerksart: 'abfangjoch', abfangTyp: 'A330',
                                 mastVorhanden: true, mastProfil: 'HEB 240',
                                 mastH: 7.0, mastSteg: 'jochachse',
                                 auflagerLinks: links });
      const szA = (links) => RA.abfangSzene('A330', 20,
        { anbauteile: [], lager: satz(links),
          mast: { profil: 'HEB 240', hoehe: 7.0, stegrichtung: 'jochachse' } });
      const zA = zeilenVon(szA(undefined));
      wahr('Das Abfangjoch schreibt seine Lagerung an', zA.length === 2, zA[0]);
      // Der Mast steht im Titel, nicht in der Lagerangabe (18. September).
      wahr('… ohne den Masten davor', zA.every((z) => !/HEB 240/.test(z)));
      wahr('… und der Vorgabe als Gelenk um z',
           zA.every((z) => /Gelenk um z/.test(z)));
      const zS = zeilenVon(szA({ V: { x: 'Rigid' }, H: { x: 'Rigid' } }));
      wahr('Halten beide Gurte laengs, ist es eingespannt',
           zS.every((z) => /eingespannt um z/.test(z)), zS[0]);
    }
  }

  /*
   * >>> DIE DREHFEDERN AM LINKELEMENT SIND KEINE EINGABE MEHR. <<<
   *
   * Weisung vom 9. September, als Frage: «macht es sinn die drehsteifigkeit
   * hier noch eingeben zu koennen, die einzelnen gurte sind gelenkig
   * gelagert? welche auswirkung hat es?» - Entschieden: ganz raus.
   *
   * Der Befund, der es entschied: sie wirkte im MODELL (die Ausleitung
   * reichte alle sechs Grade durch), nicht aber in der Anzeige und im
   * Nachweis (`linkEinspannung` liest nur die Wegfeder). Anwendung und
   * AxisVM rechneten dann verschiedene Systeme.
   *
   * Geprueft wird deshalb der WEG: eine Zahl in K_YY - auch aus einem alten
   * Stand - darf nirgends mehr ankommen.
   */
  {
    const mitDreh = { auflagerLinks: { OG: { x: 'Rigid', yy: 50000, xx: 'Rigid' },
                                       UG: { x: 'Rigid', zz: 1234 } } };
    /*
     * AUSGENOMMEN K_XX (Weisung vom 16. September): die Torsion um die
     * Jochachse ist wieder einstellbar. Die beiden Biegegrade nicht.
     */
    ['OG', 'UG'].forEach((eb) => {
      const b = AUF.linkBedingung(mitDreh, 'joch', eb);
      wahr(`${eb}: die beiden Biegegrade bleiben frei`,
           ['yy', 'zz'].every((g) => b[g] === 'Free'),
           ['xx', 'yy', 'zz'].map((g) => `${g}=${b[g]}`).join(' '));
      wahr(`${eb}: die Wegfedern gelten weiter`, b.x === 'Rigid');
    });
    wahr('K_XX kommt an, wo sie steht',
         AUF.linkBedingung(mitDreh, 'joch', 'OG').xx === 'Rigid'
         && AUF.linkBedingung(mitDreh, 'joch', 'UG').xx === 'Rigid'
         && AUF.linkBedingung({ auflagerLinks: { UG: { xx: 'Free' } } }, 'joch', 'UG').xx === 'Free');
    wahr('… auch als Zahl, und aus den Optionen',
         AUF.linkBedingung({ auflagerLinks: { UG: { xx: 500 } } }, 'joch', 'UG').xx === 500
         && AUF.linkVorgabe({ auflagerVorgabe: { joch: { OG: { xx: 'Rigid' } } } },
                            'joch', 'OG').xx === 'Rigid');
    // Auch aus den Optionen kommt keine durch.
    const ausOpt = { auflagerVorgabe: { joch: { OG: { yy: 9999 } } } };
    wahr('Die Voreinstellung bringt auch keine mit',
         AUF.linkVorgabe(ausOpt, 'joch', 'OG').yy === 'Free');
    // Und im Modell steht sie dann auf Free.
    const wD = basis({ endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.0,
                       mastSteg: 'jochachse', L: 20 });
    const mD = modell(wD, getProfil(wD.profOG), getProfil(wD.profUG),
                      getStahl(wD.stahl), T.getTragjoch('J90'));
    const jD = AX.stabmodellJson({ ...mD, ...mitDreh }, { auflagerModell: 'mast' });
    const kuD = jD.staebe.find((x) => x.name === 'LINK_A_OGL').kraftuebertragung;
    wahr('Das Linkelement traegt keine Biegefeder',
         ['yy', 'zz'].every((g) => kuD[g] === 'Free'));
    wahr('… wohl aber die gesetzte Torsionsfeder', kuD.xx === 'Rigid',
         JSON.stringify(kuD));
    wahr('Die Maske fuehrt K_XX unter den Federwerten, mit dem FEM-Hinweis',
         /data-grad="xx"/.test((await import(J("ui.auflagerlinks.js"))).auflagerDiagrammHtml({}, 'joch'))
         && /K_XX wirkt nur im FEM-Modell/.test((await import(J("ui.auflagerlinks.js"))).auflagerDiagrammHtml({}, 'joch'))
         && !/data-grad="yy"/.test((await import(J("ui.auflagerlinks.js"))).auflagerDiagrammHtml({}, 'joch')));
  }

  /*
   * =============== DIE AUFLAGERBEDINGUNG ALS ENDBEDINGUNG ==============
   *
   * Weisung vom 9. September, auf Rueckfrage entschieden: eine Wahl, die
   * c_phi aus der eingestellten Auflagerbedingung nimmt - was im Diagramm
   * steht, rechnet dann auch der Ersatzbalken.
   *
   * DER MAST KOMMT IN REIHE DAZU. Steht einer im Modell, sitzen zwei Federn
   * hintereinander; ohne diesen Schritt hiesse «beide Gurte starr» voll
   * eingespannt, obwohl der Mast sich biegt - die unsichere Annahme.
   */
  {
    const basisL = { tragwerksart: 'joch', jd: 500,
                     mastProfil: 'HEB 240', mastH: 7.0, mastSteg: 'jochachse',
                     mastVorhanden: true, endbedingung: 'links' };
    // Die Vorgabe des Tragjochs ist ein Gelenk: der Obergurt laesst laengs los.
    const g = AUF.drehfedern(basisL);
    pruef('Die Vorgabe ergibt ein Gelenk', g.cA, 0, 1e-9, 'kNm/rad');
    wahr('… und sagt es in der Bezeichnung', /gelenkig/.test(g.art));

    // Beide Gurte starr: dann bleibt der MAST als einzige Nachgiebigkeit.
    const starr = { ...basisL,
                    auflagerLinks: { OG: { x: 'Rigid' }, UG: { x: 'Rigid' } } };
    const mastFeder = AUF.mastSteifigkeit(starr, 'A').cPhi;
    pruef('Starre Gurte lassen den Masten uebrig',
          AUF.drehfedern(starr).cA, mastFeder, 1e-6, 'kNm/rad');
    wahr('… und die Bezeichnung nennt beide',
         /Gurte starr/.test(AUF.drehfedern(starr).art));

    /*
     * EINE FEDER JE GURT: Reihenschaltung ueber den Hebelarm, danach mit dem
     * Masten in Reihe. Nachgerechnet von Hand.
     */
    const mitFeder = { ...basisL,
                       auflagerLinks: { OG: { x: 20000 }, UG: { x: 20000 } } };
    const h = 0.5;
    const cAnschluss = (20000 * 20000) / (20000 + 20000) * h * h;
    const soll = 1 / (1 / cAnschluss + 1 / mastFeder);
    pruef('Gurtfedern und Mast in Reihe',
          AUF.drehfedern(mitFeder).cA, soll, 1e-6, 'kNm/rad');
    wahr('Die Reihe ist weicher als jede der beiden',
         AUF.drehfedern(mitFeder).cA < Math.min(cAnschluss, mastFeder));

    // Ohne Mast im Modell bleibt die Anschlussfeder allein.
    const ohneMast = { ...mitFeder, mastVorhanden: false };
    pruef('Ohne Masten gilt die Anschlussfeder',
          AUF.drehfedern(ohneMast).cA, cAnschluss, 1e-6, 'kNm/rad');

    wahr('Die Wahl steht in der Liste',
         AUF.ENDBEDINGUNGEN.some((x) => x.key === 'links'));
    /*
     * UND SIE VERAENDERT DEN NACHWEIS - das ist der Punkt der Uebung. Mit
     * starren Gurten steht dieselbe Feder da wie bei «Steifigkeit aus Mast»
     * im unverschieblichen Fall; mit der Vorgabe (Gelenk) ist es die
     * weichste aller Annahmen.
     */
    wahr('Gelenk ist weicher als die Mastfeder',
         AUF.drehfedern(basisL).cA < AUF.drehfedern({ ...basisL,
           endbedingung: 'mast' }).cA);
  }

  /*
   * >>> DAS ANSICHTSBILD TRAEGT DIE ANSCHLUSSART. <<<
   *
   * Sie stand in einer eigenen Optionsskizze; die ist weg (Weisung,
   * 9. September). Damit muss dieses Bild sie zeigen - sonst waere die
   * Angabe ersatzlos verschwunden.
   */
  {
    const AL = await import(J('ui.auflagerlinks.js'));
    const bild = (an) => AL.auflagerDiagrammHtml(
      { mastVorhanden: true, mastAnschluss: an, jd: 500 }, 'joch');
    wahr('Der durchlaufende Mast laeuft durch',
         bild('durchlaufend').includes('läuft durch'));
    wahr('Der Kragmast endet am Joch',
         bild('kragarm').includes('endet hier'));
    /*
     * UND ZWAR ALS LAGE, nicht nur als Wort: der Kragmast beginnt erst auf
     * der Anschlussebene. Das Rechteck des Masten faengt dort an.
     */
    const oben = (an) => Number(bild(an)
      .match(/<rect class="kasten" x="\d+" y="(\d+)"/)[1]);
    wahr('Der Kragmast beginnt tiefer als der durchlaufende',
         oben('kragarm') > oben('durchlaufend'),
         `${oben('kragarm')} gegen ${oben('durchlaufend')}`);
  }

  /*
   * =================== IST DAS SYSTEM GEHALTEN? ========================
   *
   * Weisung, 9. September: «zudem noch warnung wenn system labil gelagert».
   *
   * Gerechnet wird der Rang der Bedingungsmatrix eines Starrkoerpers mit
   * sechs Freiheitsgraden. Die Kontrollen halten die vier Faelle fest, in
   * denen man sich vertun kann - und den wichtigsten Fall ueberhaupt: dass
   * die VORGABE haelt. Ein Werkzeug, das seine eigene Voreinstellung als
   * labil meldet, wuerde niemand ernst nehmen.
   */
  const labil = (w, art = 'joch', opt = {}) => AUF.linkLabilitaet(w, art, opt);
  wahr('Die Vorgabe des Tragjochs haelt', labil({}).labil === false);
  wahr('… mit allen sechs Bewegungen gesperrt', labil({}).rang === 6);
  wahr('Die Vorgabe des Abfangjochs haelt ebenso',
       labil({}, 'abfangjoch').labil === false);
  /*
   * QUER LOSGELASSEN: haelt keine Ebene mehr in y, steht das Joch in
   * Gleisrichtung auf nichts. Das ist der Fall, den man beim Einstellen des
   * Gelenks am ehesten baut - und den kein Schalter fuer sich anzeigt.
   */
  const ohneY = labil({ auflagerLinks: { OG: { y: 'Free' }, UG: { y: 'Free' } } });
  wahr('Ohne Halt in y ist das System labil', ohneY.labil === true);
  wahr('… und die Verschiebung in y wird benannt',
       ohneY.moden.some((m) => m.achse === 'y' && m.art === 'verschiebung'));
  /*
   * LAENGS: die Vorgabe haelt x nur am Obergurt (seit dem 16. September). Laesst auch der los,
   * fehlt die Jochachse - eine einzige Bewegung, nicht mehr.
   */
  const ohneX = labil({ auflagerLinks: { OG: { x: 'Free' } } });
  wahr('Ohne Halt in x ebenfalls labil', ohneX.labil === true);
  wahr('… und zwar genau eine Bewegung', ohneX.fehlend === 1);
  wahr('… naemlich die Jochachse',
       ohneX.moden[0].achse === 'x' && ohneX.moden[0].art === 'verschiebung');
  /*
   * NUR EINE EBENE: zwei Punkte auf EINER Linie laengs x halten alles ausser
   * der Drehung um diese Linie. Das ist die Torsion - und der Grund, warum
   * der Anschluss ueberhaupt zwei Ebenen hat.
   */
  // Mit freier K_XX - die gehaltene haelt die Torsion auch an EINER Ebene.
  const eine = labil({ auflagerLinks: { OG: { x: 'Free', y: 'Free', z: 'Free', xx: 'Free' },
                                      UG: { x: 'Rigid', xx: 'Free' } } });
  wahr('Mit gehaltener K_XX haelt auch eine Ebene die Torsion',
       labil({ auflagerLinks: { OG: { x: 'Free', y: 'Free', z: 'Free' },
                                UG: { x: 'Rigid' } } }).labil === false);
  wahr('Nur eine tragende Ebene laesst die Torsion frei',
       eine.labil === true && eine.moden[0].achse === 'xx');
  /*
   * EINE FEDER HAELT, EINE FEDER MIT NULL NICHT. Der Unterschied ist die
   * ganze Frage: 0 kN/m ist die Schreibweise fuer «frei», und wer sie
   * eintippt, meint es auch so.
   */
  wahr('Eine Feder haelt wie eine Halterung',
       labil({ auflagerLinks: { OG: { y: 25000 }, UG: { y: 25000 } } })
         .labil === false);
  wahr('Eine Feder mit 0 haelt nicht',
       labil({ auflagerLinks: { OG: { y: 0 }, UG: { y: 0 } } }).labil === true);
  /*
   * DIE VORGABE AUS DEN OPTIONEN wird ueber `lies` gelesen - der Dialog
   * zeigt dasselbe Bild und muss dieselbe Warnung bekommen.
   */
  wahr('Die Pruefung liest auch die Voreinstellung',
       labil({}, 'joch',
             { lies: (e) => AUF.linkVorgabe(
                 { auflagerVorgabe: { joch: { OG: { y: 'Free' },
                                              UG: { y: 'Free' } } } }, 'joch', e) })
         .labil === true);

  /*
   * IM MODELL: die Bedingung wandert in die Linkelemente. Das ist der Punkt
   * der ganzen Uebung - eine Einstellung, die nirgends ankommt, ist keine.
   */
  const wL = basis({ endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.0,
                     mastSteg: 'jochachse', L: 20 });
  const mLb = modell(wL, getProfil(wL.profOG), getProfil(wL.profUG),
                     getStahl(wL.stahl), T.getTragjoch('J90'));
  const j1 = AX.stabmodellJson(mLb, { auflagerModell: 'mast' });
  const lOG = j1.staebe.find((x) => x.name === 'LINK_A_OGL');
  const lUG = j1.staebe.find((x) => x.name === 'LINK_A_UGL');
  // Vorgabe seit dem 16. September: Obergurt x y, Untergurt y z.
  wahr('Der Obergurt-Link haelt laengs und laesst lotrecht los',
       lOG.kraftuebertragung.x === 'Rigid' && lOG.kraftuebertragung.z === 'Free');
  wahr('Der Untergurt-Link traegt lotrecht und laesst laengs los',
       lUG.kraftuebertragung.x === 'Free' && lUG.kraftuebertragung.z === 'Rigid');
  const j2 = AX.stabmodellJson(
    { ...mLb, auflagerLinks: { OG: { x: 'Rigid' }, UG: { z: 25000 } } },
    { auflagerModell: 'mast' });
  wahr('Eine Aenderung kommt im Modell an',
       j2.staebe.find((x) => x.name === 'LINK_A_OGL')
         .kraftuebertragung.x === 'Rigid');
  pruef('Auch eine Feder',
        j2.staebe.find((x) => x.name === 'LINK_A_UGL').kraftuebertragung.z,
        25000, 1e-9, 'kN/m');

  /* =====================================================================
   * =================== STEHENDE STARRELEMENTE ==========================
   * =====================================================================
   *
   * Weisung, 5. September: "beachte noch beim tragjoch alt das man noch
   * starrelemente (vertikale) an den enden und beim uebergang zum knick hin
   * anbringen."
   *
   * Am verjuengten Ende laufen die Gurte zusammen; ohne Riegel dazwischen
   * ist das Endstueck in seiner Ebene ein Gelenkviereck, und die beiden
   * Linkelemente haengen an einem weichen Gebilde statt an einer Scheibe.
   *
   * >>> WO EIN BLECH STEHT, BRAUCHT ES KEINEN (15. September). <<<
   *
   * Befund am aufgebauten Modell: "warum hat es hier noch zwei
   * starrelemente beim letzten stehenden blech?" - und auf den Vorschlag:
   * "ja so umsetzen wie beschrieben."
   *
   * An der Station x = 0 standen zwei Bauteile uebereinander: der Riegel auf
   * den Gurtachsen und, 21 mm daneben auf der Schenkelflucht, das ENDBLECH.
   * Zwei parallele Bauteile teilen sich die Kraft nach ihrer Steifigkeit -
   * gegen ein Starrelement traegt das Blech NICHTS. Wer die Blechkraft am
   * Jochende ablesen will, liest eine Null, und das Endblech ist das am
   * staerksten beanspruchte des Jochs.
   *
   * Die Regel traegt beide Faelle: am geraden Jochende ist das Endblech die
   * Scheibe, am verjuengten Ende - wo kein Blech steht - der Riegel.
   */
  const riegel = (jm) => jm.staebe.filter((x) => /^RIEGEL_/.test(x.name));
  const xVon = (n) => Number(n.split('_')[2]);
  const blechStellen = (mm2) => (mm2.stationsListe ?? [])
    .filter((s2) => (s2.vertikal?.breite ?? 0) > 0).map((s2) => s2.x);

  /*
   * DAS GERADE JOCH traegt an beiden Enden ein Blech - also keinen Riegel.
   */
  const rNeu = riegel(j1);
  wahr('Das gerade Joch bekommt keine Riegel mehr', rNeu.length === 0,
       rNeu.map((x) => x.name).join(' '));
  wahr('\u2026 weil an beiden Enden ein Blech steht',
       blechStellen(mLb).some((x) => Math.abs(x) < 1e-9)
       && blechStellen(mLb).some((x) => Math.abs(x - 20) < 1e-9),
       blechStellen(mLb).slice(0, 3).join(' '));

  /*
   * DAS ALTE JOCH IST VERJUENGT. Dort beginnt die Blecheinteilung erst hinter
   * der Voute - am Jochende steht keines, und genau dort bleibt der Riegel.
   * Am KNICK dagegen steht eines (3.000 m), also faellt er dort weg.
   */
  let wAlt = basis({ typ: 'J90-alt', L: 20, endbedingung: 'mast',
                     mastProfil: 'HEB 240', mastH: 7.0,
                     mastSteg: 'jochachse' });
  wAlt = typUebernehmen(wAlt, T.getTragjoch('J90-alt'));
  const mAlt = modell(wAlt, getProfil(wAlt.profOG), getProfil(wAlt.profUG),
                      getStahl(wAlt.stahl), T.getTragjoch('J90-alt'));
  const rAlt = riegel(AX.stabmodellJson(mAlt, { auflagerModell: 'mast' }));
  const stellen = [...new Set(rAlt.map((x) => xVon(x.name)))]
    .sort((a2, b2) => a2 - b2);
  wahr('Das verjuengte Joch behaelt die beiden Enden',
       stellen.length === 2, stellen.join(' '));
  pruef('Enden bei 0 und L', stellen[0] + stellen[1], 20, 1e-6, 'm');
  wahr('Vier Riegel, zwei je Ende', rAlt.length === 4, `${rAlt.length}`);
  wahr('Alle sind Starrkoerper', rAlt.every((x) => x.art === 'starr'));
  wahr('Sie verbinden Ober- und Untergurt',
       rAlt.every((x) => /^OG/.test(x.von) && /^UG/.test(x.bis)));
  wahr('Am verjuengten Ende steht kein Blech',
       !blechStellen(mAlt).some((x) => Math.abs(x) < 1e-9),
       blechStellen(mAlt).slice(0, 3).join(' '));
  wahr('Am Knick dagegen schon - deshalb dort kein Riegel',
       blechStellen(mAlt).some((x) => Math.abs(x - 3.0) < 1e-6)
       && !stellen.some((x) => Math.abs(x - 3.0) < 1e-6));
}

titel('35  Der Mast im Modell: Starrkoerper, Linkelement, Fundament');

/*
 * WEISUNG DES AUFTRAGGEBERS, 27. August:
 *   je Gurtebene ein Starrkoerper ueber die beiden Gurte, von dort ein
 *   Linkelement an den Mast - Kraefte starr, Momente frei -, und der Mast
 *   bis zum Fundament, dort starr eingespannt.
 *
 * Damit entsteht das Kraeftepaar, das im Ersatzbalken die Drehfeder
 * vertritt, aus der Biegung des Mastes zwischen Ober- und Untergurthoehe.
 */
{
  const AXM = await import(J('export.axisvm.js'));
  const wM = basis({
    // EINE Last, ein Wert: 1.0 kN/m lotrecht. Damit ist q L^2/8 = 50 kNm,
    // und jede Abweichung im Modell faellt sofort auf. Genau so ist in
    // AxisVM gerechnet worden.
    lastHerkunft: 'manuell', gkManuell: 0, wkManuell: 0, skManuell: 1.0,
    schneeAktiv: true,
    lastfall: 'Schnee', beiwerteFest: { G: 0, WindX: 0, WindY: 0, Schnee: 1 },
    endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.0,
    mastSteg: 'jochachse', mastAnschluss: 'durchlaufend',
    mastWindAufJoch: false, schraubenGrenze: false,
  });
  const mM = modell(wM, getProfil(wM.profOG), getProfil(wM.profUG),
                    getStahl(wM.stahl), T.getTragjoch('J90'));
  const j = AXM.stabmodellJson(mM, { knotenmodell: 'anschnitt', auflagerModell: 'mast' });
  const stabVon = (n) => j.staebe.find((x) => x.name === n);
  const knotenVon = (n) => j.knoten.find((x) => x.name === n);

  // --- Der Mast selbst ----------------------------------------------------
  pruef('Zwei Auflager, eines je Mastfuss', j.auflager.length, 2, 1e-12, 'Stk');
  wahr('Beide Fuesse voll eingespannt',
       j.auflager.every((a) => ['ux', 'uy', 'uz', 'fix', 'fiy', 'fiz']
         .every((f) => a[f] === 'Rigid')),
       j.auflager.map((a) => `${a.knoten}:${a.fiy}`).join(' '));
  wahr('Und sie sitzen am Mastfuss, nicht am Joch',
       j.auflager.every((a) => a.knoten.endsWith('_F')));
  // Die Hoehe H misst der Rechenkern bis zur JOCHACHSE - dort steht im
  // Ersatzbalken die Drehfeder. Der Mastfuss liegt also H unter der Achse.
  const oben = knotenVon('MAST_A_OG').z, unten = knotenVon('MAST_A_UG').z;
  pruef('Die Jochhoehe steht zwischen den beiden Anschluessen',
        oben - unten, mM.h, 1e-6, 'm');
  pruef('Der Mastfuss liegt H unter der Jochachse',
        (oben + unten) / 2 - knotenVon('MAST_A_F').z, 7.0, 1e-6, 'm');

  // --- Anschluss je Gurtebene ---------------------------------------------
  ['A', 'B'].forEach((e) => ['OG', 'UG'].forEach((g) => {
    /* =====================================================================
     * DIE KETTE LAEUFT VOM MASTEN ZUM GURT
     * =====================================================================
     *
     * Weisung vom 11. September: «Auflager so machen dass zuerst die
     * starrelemente von mast ausgeht (150 mm) von hier aus wie bei den
     * anbauteilen vorgehen oben werden beide Gurte jeweils ueber
     * linkelemente (50 mm) gehalten.»
     *
     * Vorher lief sie umgekehrt: zwei Starrstaebe VOM Gurt auf einen
     * Sammelknoten, von dort ein Link ZUM Masten. Der starre Teil gehoerte
     * damit dem Joch, und die Konsole am Masten war gar nicht abgebildet.
     *
     * >>> SEIT DEM 15. SEPTEMBER IST ES DIE KETTE DES ABFANGJOCHS. <<<
     *
     * Weisung: "das auflger fuer das tragjoch angleichen an abfangjoch, wie
     * beschrieben." Der Ansatz sitzt versetzt am Masten, und je Gurt - nicht
     * je Gurtebene - haelt ein eigenes Link:
     *
     *   MAST_A_A_OG --[KONSOLE in x, a_K]--> KONS_A_OG
     *   KONS_A_OG   --[KONSARM in y]-------> ARM_A_OGL
     *   ARM_A_OGL   --[LINKSTIEL in z]-----> ANS_A_OGL
     *   ANS_A_OGL   --[LINK in z, 50 mm]---> Gurt OG links
     *
     * "der obere ausschnitt ist die halterung der ZWEI obergurte" (Weisung
     * vom 5. September, Plural) - zwei Gurte, zwei Linkelemente.
     * =================================================================== */
    const kons = stabVon(`KONSOLE_${e}_${g}`);
    wahr(`Ende ${e}, ${g}: die Konsole geht starr vom Masten aus`,
         kons && kons.art === 'starr'
         && kons.von === `MAST_${e}_A_${g}` && kons.bis === `KONS_${e}_${g}`,
         kons && `${kons.von} -> ${kons.bis}`);
    const glied = (art, seite) => stabVon(`${art}_${e}_${g}${seite}`);
    ['L', 'R'].forEach((seite) => {
      const arm = glied('KONSARM', seite);
      const stiel = glied('LINKSTIEL', seite);
      wahr(`Ende ${e}, ${g}${seite}: von der Konsole ein Arm zur Gurtachse`,
           arm && arm.art === 'starr' && arm.von === `KONS_${e}_${g}`
           && arm.bis === `ARM_${e}_${g}${seite}`);
      wahr(`Ende ${e}, ${g}${seite}: und von dort ein Stiel zum Gurt hin`,
           stiel && stiel.art === 'starr'
           && stiel.von === `ARM_${e}_${g}${seite}`
           && stiel.bis === `ANS_${e}_${g}${seite}`);
      const lk = glied('LINK', seite);
      wahr(`Ende ${e}, ${g}${seite}: die letzten 50 mm sind das Link`,
           lk && lk.art === 'link' && lk.von === `ANS_${e}_${g}${seite}`);
    });
    const l = glied('LINK', 'L');
    // Vorgabe seit dem 16. September: Obergurt x y, Untergurt y z.
    const sollX = g === 'OG' ? 'Rigid' : 'Free';
    const sollZ = g === 'OG' ? 'Free' : 'Rigid';
    wahr(`Ende ${e}, ${g}: laengs ${sollX === 'Free' ? 'frei' : 'starr'}`,
         l.kraftuebertragung.x === sollX, JSON.stringify(l.kraftuebertragung));
    wahr(`Ende ${e}, ${g}: quer starr, lotrecht ${sollZ === 'Free' ? 'frei' : 'starr'}`,
         l.kraftuebertragung.y === 'Rigid' && l.kraftuebertragung.z === sollZ);
    wahr(`Ende ${e}, ${g}: K_XX gehalten, die Biegegrade frei`,
         l.kraftuebertragung.xx === 'Rigid'
         && ['yy', 'zz'].every((f) => l.kraftuebertragung[f] === 'Free'));
    /*
     * UND BEIDE GURTE DER EBENE TRAGEN DIESELBE BEDINGUNG. Sie kommt aus
     * derselben Maske; zwei Links, die auseinanderliefen, waeren ein Ende,
     * das sich links anders lagert als rechts.
     */
    wahr(`Ende ${e}, ${g}: beide Gurte gleich gelagert`,
         JSON.stringify(glied('LINK', 'R').kraftuebertragung)
         === JSON.stringify(l.kraftuebertragung));
  }));
  /*
   * DIE BEIDEN LAENGEN, EINZELN GEPRUEFT (Weisung, 11. September). Verschoben
   * wird nach INNEN, nicht die Mastachse nach aussen: die Stuetzweite bleibt
   * die des Rechenkerns, und die Konsole ragt nie ueber das Jochende hinaus.
   */
  /* =========================================================================
   * DER MAST IM ABFANGJOCH-MODELL
   * =========================================================================
   *
   * Weisung vom 11. September: «Auflager so machen dass zuerst die
   * starrelemente von mast ausgeht (150 mm) von hier aus wie bei den
   * anbauteilen vorgehen oben werden beide Gurte jeweils ueber linkelemente
   * (50 mm) gehalten.»
   *
   * Bis dahin hatte das Abfangjoch-Modell keinen Masten: es lagerte auf
   * einem Punkt je Ende, und im Ausleitungsdialog stand «Mit Mast»
   * ausgegraut. Die Weisung vom 4. September nannte ihn schon.
   *
   * DIESELBE KETTE, NUR LIEGEND: beim Tragjoch stehen Ober- und Untergurt
   * uebereinander und die Kette laeuft in der Jochachse nach innen; hier
   * liegen die beiden Gurte nebeneinander, und sie laeuft quer.
   * ======================================================================= */
  if (AJ.abfangDbDa()) {
    const AXA2 = await import(J('export.axisvm.abfang.js'));
    const jm = AXA2.abfangAxisvmModell('A240', 12.5,
      { mast: { profil: 'HEB 240', hoehe: 7.5 } });
    const knM = (n) => jm.knoten.find((k) => k.name === n);
    const stM = (n) => jm.staebe.find((s) => s.name === n);
    const lg = (n) => {
      const s = stM(n);
      if (!s) return null;
      const a = knM(s.von), b = knM(s.bis);
      return Math.hypot(b.x - a.x, b.y - a.y, b.z - a.z);
    };
    wahr('Das Abfangjoch baut jetzt einen Masten', Boolean(stM('MAST_A')));
    /*
     * ZWEI STUECKE, EINE HOEHE. Der Mast ist am Konsolansatz geteilt
     * (Weisung, 12. September) - oben das kurze Stueck bis zur Jochachse,
     * unten der Rest bis zum Fuss. Zusammen ist er so hoch wie angegeben.
     */
    pruef('… und er ist so hoch wie angegeben',
          lg('MAST_A_O') + lg('MAST_A'), 7.5, 1e-9, 'm');
    /* =====================================================================
     * >>> DIE KONSOLE MISST EINE HALBE MASTBREITE, IN x. <<<
     * =====================================================================
     *
     * Zwei Befunde, beide am Modell gesehen:
     *
     * 11. September: «hier fehlen noch die 150 mm auskragung von der
     * mastachse in x richtung.» Sie stand quer und fuellte den halben
     * Gurtabstand - die falsche Achse.
     *
     * 12. September: «mach noch die konsolenlaenge abhaengig vom Masttyp
     * (halbe mastbreite) und ein feld wo man diesen wert auch ueberschreiben
     * kann.» Die 150 mm waren pauschal; beim HEB 300 endete die Konsole
     * damit noch innerhalb des Profils. HEB 240 -> 120 mm.
     */
    wahr('Die Konsole geht starr vom Konsolansatz am Masten aus',
         stM('KONSOLE_A')?.von === 'MAST_A_A'
         && stM('KONSOLE_A')?.art === 'starr');
    pruef('… und kragt eine halbe Mastbreite aus (HEB 240)',
          knM('KONS_A').x - knM('MAST_A_A').x, 0.12, 1e-9, 'm');
    wahr('… nach INNEN, nicht unter den Ueberstand',
         knM('KONS_A').x > knM('MAST_A_K').x
         && knM('KONS_B').x < knM('MAST_B_K').x);
    /*
     * DAS FELD SCHLAEGT DIE ABLEITUNG. `auflagerKonsole` in mm; 0 heisst
     * "dem Masten folgen" - nicht "leer", denn ein leeres Zahlenfeld laesst
     * sich in dieser Oberflaeche nicht zurueckgeben.
     */
    const mitFeld = AXA2.abfangAxisvmModell('A240', 12.5,
      { mast: { profil: 'HEB 240', hoehe: 7.5 }, auflagerKonsole: 200 });
    const kvF = (n2) => mitFeld.knoten.find((k2) => k2.name === n2);
    pruef('Das Feld überschreibt sie', kvF('KONS_A').x - kvF('MAST_A_A').x,
          0.20, 1e-9, 'm');
    const mitNull = AXA2.abfangAxisvmModell('A240', 12.5,
      { mast: { profil: 'HEB 260', hoehe: 7.5 }, auflagerKonsole: 0 });
    const kvN = (n2) => mitNull.knoten.find((k2) => k2.name === n2);
    pruef('… und 0 führt zurück zum Masten (HEB 260)',
          kvN('KONS_A').x - kvN('MAST_A_A').x, 0.13, 1e-9, 'm');

    /* =====================================================================
     * >>> JEDES GLIED LAEUFT IN GENAU EINER ACHSE. <<<
     * =====================================================================
     *
     * Weisung vom 12. September: «die starrelemente rechtwinklig machen und
     * nicht zurueckfuehren auf die mastachse lage» und «um nicht mit den
     * elementen zu kollidieren, die starrelemente versetzt in der z achse
     * ansetzen».
     *
     * Vorher lief EIN schraeger Arm von der Konsolspitze zurueck auf den
     * Gurtknoten an der Mastachse - zwei Richtungen in einem Stab, und
     * mitten durch die Gurte hindurch.
     */
    const achse = (nm2) => {
      const s2 = stM(nm2);
      if (!s2) return '-';
      const a2 = knM(s2.von), b2 = knM(s2.bis);
      const d2 = [Math.abs(b2.x - a2.x), Math.abs(b2.y - a2.y), Math.abs(b2.z - a2.z)];
      const gross = d2.filter((v) => v > 1e-9);
      return gross.length === 1 ? 'xyz'[d2.findIndex((v) => v > 1e-9)] : 'schräg';
    };
    wahr('Die Konsole läuft in x', achse('KONSOLE_A') === 'x');
    wahr('Der Arm zum Gurt läuft in y',
         achse('KONSARM_AV') === 'y' && achse('KONSARM_AH') === 'y');
    wahr('Der Stiel darunter läuft in z',
         achse('LINKSTIEL_AV') === 'z' && achse('LINKSTIEL_AH') === 'z');
    wahr('Und das Linkelement auch',
         achse('LINK_AV') === 'z' && achse('LINK_AH') === 'z');
    pruef('Das Linkelement misst 50 mm', lg('LINK_AV'), 0.05, 1e-9, 'm');
    /*
     * >>> NICHT ZURUECK AUF DIE MASTACHSE. <<<
     * Der Gurt hat an der Konsolspitze einen eigenen Knoten - sonst gaebe es
     * den rechten Winkel nicht: ein Stabzug bildet nur ab, was seine Knoten
     * hergeben.
     */
    wahr('Der Gurt hat an der Konsolspitze einen Knoten',
         Math.abs(knM(stM('LINK_AV').bis).x - knM('KONS_A').x) < 1e-9);
    wahr('… und ein Gurtstab berührt ihn',
         jm.staebe.some((s2) => /^[VH]_S\d|^GABEL_|^GARM_/.test(s2.name)
           && [s2.von, s2.bis].includes(stM('LINK_AV').bis)));
    /*
     * >>> UNTER DEN GURTEN DURCH. <<<
     * Eine halbe Profilhoehe plus 50 mm Luft. Das A240 traegt ein IPE 240:
     * 0.120 + 0.050 = 0.170 m unter der Schwerachse.
     */
    pruef('Die Starrelemente liegen unter dem Gurt',
          knM('KONS_A').z, -0.17, 1e-9, 'm');
    wahr('… und tiefer als die Bleche auf Flanschhöhe',
         knM('KONS_A').z < -Math.abs(knM('BL_U0_a').z) + 1e-9);
    /*
     * >>> DER MAST MUSS NICHT AM ENDE STEHEN. <<<
     *
     * Weisung vom 11. September: «die auflager koennen innerhalb des
     * traegers frei in der x richtung liegen. es gibt tragjoche die haben
     * eine auskragung, da der mast nicht am ende sondern weiter nach innen
     * liegt, zum Beispiel in einer Bauphase.»
     *
     * Der Ueberstand folgt aus Traegerlaenge und Stuetzweite; wandert der
     * Mast nach innen, hat die Kette mitzuwandern und ihre 150 mm zu
     * behalten. Geprueft ueber die ganze Laengenspanne des Typs - der
     * Ueberstand waechst dabei von wenigen Zentimetern auf einen halben
     * Meter.
     */
    let jeGeprueft = 0;
    const schief = [];
    const bereich2 = AJ.abfangLaengenbereich('A240');
    for (let Lj = bereich2.min; Lj <= bereich2.max + 1e-9; Lj += 0.5) {
      const jL = Math.round(Lj * 100) / 100;
      let mo;
      try {
        mo = AXA2.abfangAxisvmModell('A240', jL,
                                     { mast: { profil: 'HEB 240', hoehe: 7.5 } });
      } catch { continue; }
      jeGeprueft++;
      const kv = (n2) => mo.knoten.find((k2) => k2.name === n2);
      for (const e2 of ['A', 'B']) {
        const kk = kv(`KONS_${e2}`), mk = kv(`MAST_${e2}_A`);
        if (!kk || !mk || Math.abs(Math.abs(kk.x - mk.x) - 0.12) > 1e-9) {
          schief.push(`${jL} m / ${e2}`);
        }
      }
    }
    wahr(`Die Auskragung haelt ihr Mass, wo der Mast auch steht (${jeGeprueft} Laengen)`,
         schief.length === 0, schief.slice(0, 3).join('; '));
    /*
     * >>> DAS AUFLAGER SITZT AM MASTFUSS, NICHT MEHR AM JOCHENDE. <<<
     */
    wahr('Die Auflager sitzen an den Mastfuessen',
         jm.auflager.every((a) => /^MAST_._F$/.test(a.knoten)
                               && a.modell === 'mast'));
    wahr('… und beide Fuesse sind voll eingespannt',
         jm.auflager.every((a) => ['ux', 'uy', 'uz', 'fix', 'fiy', 'fiz']
           .every((f) => a[f] === 'Rigid')));
    wahr('Der Mastquerschnitt traegt seine Kennwerte',
         jm.querschnitte.some((c) => c.name === 'MAST_HEB240'
                                  && c.form === 'I' && c.A > 0));
    /*
     * OHNE MASTANGABE BLEIBT ES BEIM ALTEN WEG. Wer keinen Masten fuehrt,
     * bekommt weiterhin einen Auflagerpunkt je Ende - die Weisung vom
     * 4. September gilt unveraendert fort.
     */
    /* =====================================================================
     * >>> KEIN ANSCHLUSS DARF IN DER LUFT HAENGEN. <<<
     * =====================================================================
     *
     * Befund vom 11. September, am Modell in AxisVM gesehen: das Endblech
     * stand frei im Raum, ohne Verbindung zu den Traegern.
     *
     * Der Grund war der Gabelbereich. Dort laeuft der Gurtstab bewusst
     * nicht weiter - an seiner Stelle traegt der Verbundstab GABEL, und der
     * liegt auf einer eigenen Achse. Die Knoten V_x / H_x an einer Station
     * MITTEN im Bereich blieben uebrig: angelegt, aber von keinem Stab mehr
     * beruehrt. Das Blech hing daran und damit an nichts.
     *
     * >>> DIE REGEL, NICHT DER EINZELFALL. <<<
     *
     * Geprueft wird deshalb nicht die eine Stelle, sondern der Satz: JEDER
     * Knoten, an dem etwas angeschlossen ist, muss auch von einem tragenden
     * Laengsbauteil beruehrt werden - Gurt, Gabel oder Uebergangsarm.
     * Ausgenommen sind allein die Knoten IM Bauteil (`_a`/`_b`), der
     * Auflagerpunkt und der Mast: die tragen ihre Aufgabe selbst.
     *
     * Gelaufen ueber alle Typen und Laengen - der Gabelbereich liegt fest,
     * die Blechstationen wandern mit der Laenge, und ob beide aufeinander
     * treffen, entscheidet sich erst im Einzelfall. A270 entging dem Fehler
     * nur, weil sein Endblech neben den Bereich faellt.
     * =================================================================== */
    let geprueft = 0;
    const haengend = [];
    for (const t of AJ.abfangjoche()) {
      const typ = t.typ ?? t.id;
      let bereich;
      try { bereich = AJ.abfangLaengenbereich(typ); } catch { continue; }
      for (let L = bereich.min; L <= bereich.max + 1e-9; L += 0.5) {
        const jl = Math.round(L * 100) / 100;
        let mo;
        try { mo = AXA2.abfangAxisvmModell(typ, jl, {}); } catch { continue; }
        geprueft++;
        const anKnoten = new Map();
        for (const s of mo.staebe) for (const k of [s.von, s.bis]) {
          if (!anKnoten.has(k)) anKnoten.set(k, []);
          anKnoten.get(k).push(s.name);
        }
        for (const [k, liste] of anKnoten) {
          if (/_a$|_b$/.test(k) || /^AUFL_/.test(k) || /^MAST_/.test(k)) continue;
          if (liste.some((n2) => /^[VH]_S\d|^GABEL_|^GARM_/.test(n2))) continue;
          haengend.push(`${typ}/${jl} m: ${k}`);
        }
      }
    }
    wahr(`Kein Anschlussknoten ohne tragendes Laengsbauteil (${geprueft} Modelle)`,
         haengend.length === 0, haengend.slice(0, 3).join('; '));

    /* =====================================================================
     * >>> DAS AUFLAGER STEHT DORT, WO DIE STUETZWEITE ES HINSTELLT. <<<
     * =====================================================================
     *
     * Befund vom 12. September: der Mast am Ende B stand beim A240/12.5 m
     * bei x = 11.59 m statt bei 12.25 m - zwei Drittelmeter daneben, und mit
     * ihm das Auflager und die Stuetzweite des ganzen FEM-Modells.
     *
     * Der Grund war ein INDEX, der seine Liste ueberlebt hat. `iA`/`iB`
     * zeigen in die Stationsliste, und die wird danach noch einmal
     * angefasst: der Gabelbereich schiebt seine beiden Grenzen hinein und
     * sortiert neu. Jede Einfuegung vor dem Auflager schiebt dessen Eintrag
     * nach hinten - der Index zeigt dann auf den Nachbarn.
     *
     * Der Ueberstand ist (L - js)/2 je Ende, und beide Auflager liegen
     * symmetrisch dazu. Das ist von der Stationsliste unabhaengig und
     * deshalb die richtige Probe: geprueft wird gegen die ZAHL, nicht gegen
     * einen zweiten Index.
     */
    const danebenA = [];
    for (const t of AJ.abfangjoche()) {
      const typ = t.typ ?? t.id;
      let bereich;
      try { bereich = AJ.abfangLaengenbereich(typ); } catch { continue; }
      for (let L2 = bereich.min; L2 <= bereich.max + 1e-9; L2 += 0.5) {
        const jl = Math.round(L2 * 100) / 100;
        let mo;
        try { mo = AXA2.abfangAxisvmModell(typ, jl, {}); } catch { continue; }
        const ue2 = mo.tragwerk.ueberstand;
        const soll = [ue2, mo.tragwerk.L - ue2];
        const ist = mo.auflager.map((a) => a.x).sort((u, v) => u - v);
        if (ist.length !== 2
            || Math.abs(ist[0] - soll[0]) > 1e-9
            || Math.abs(ist[1] - soll[1]) > 1e-9) {
          danebenA.push(`${typ}/${jl} m: ${ist.join(' | ')} statt ${soll.join(' | ')}`);
        }
      }
    }
    wahr('Beide Auflager stehen um den Ueberstand eingerueckt',
         danebenA.length === 0, danebenA.slice(0, 3).join('; '));
    /*
     * UND DIE STELLE SELBST, mit Mass: das Endblech von A240/12.5 m sitzt
     * bei x = 1.380 m, mitten im Gabelbereich 0.850 … 1.465 m. Es haengt an
     * der Gabelachse - um die halbe Flanschbreite weiter aussen als der
     * Gurt, deshalb GV_/GH_ und nicht V_/H_.
     */
    const a240 = AXA2.abfangAxisvmModell('A240', 12.5, {});
    const endblech = a240.staebe.find((s) => s.name === 'BL_O0_3');
    wahr('Das Endblech im Gabelbereich haengt an der Gabel',
         endblech?.bis === 'GV_1.380', String(endblech?.bis));
    wahr('… und der Gabelstab beruehrt denselben Knoten',
         a240.staebe.some((s) => /^GABEL_V/.test(s.name)
                              && (s.von === 'GV_1.380' || s.bis === 'GV_1.380')));

    const jo = AXA2.abfangAxisvmModell('A240', 12.5, {});
    wahr('Ohne Mastangabe lagert es weiter auf Punkten',
         jo.auflager.every((a) => a.modell === 'punkt')
         && !jo.staebe.some((s) => /^MAST_/.test(s.name)));
    /*
     * DAS MERKMAL SAGT, WAS DAS MODELL KANN. `anbau-kette` fuehrt es
     * bewusst NICHT: die Anbauteile haengen hier als Punktlasten am Gurt,
     * nicht als Kette aus Starrelementen. Die Bruecke meldet das beim
     * Aufbau, und die Meldung soll stehen bleiben.
     */
    wahr('Mit Mast nennt das Modell die neue Anschlussart',
         (jm.merkmale ?? []).includes('mast-konsole-link'));
    wahr('… und behauptet keine Anbauteil-Kette',
         !(jm.merkmale ?? []).includes('anbau-kette'));
  }

  /*
   * DIE MASSE DER KETTE (Weisung vom 11. September, angeglichen am
   * 15. September). Das Modell steht auf HEB 240, die Konsole misst also
   * die halbe Mastbreite: 120 mm. Das Link misst seine 50 mm in z.
   */
  pruef('Die Konsole misst die halbe Mastbreite',
        knotenVon('KONS_A_OG').x - knotenVon('MAST_A_OG').x, 0.12, 1e-9, 'm');
  pruef('Am anderen Ende ebenso, spiegelbildlich',
        knotenVon('MAST_B_OG').x - knotenVon('KONS_B_OG').x, 0.12, 1e-9, 'm');
  wahr('Der Konsolknoten liegt auf der Jochachse',
       Math.abs(knotenVon('KONS_A_OG').y) < 1e-9);
  {
    const laenge = (n) => {
      const s = stabVon(n);
      if (!s) return NaN;
      const p1 = knotenVon(s.von), p2 = knotenVon(s.bis);
      return Math.hypot(p2.x - p1.x, p2.y - p1.y, p2.z - p1.z);
    };
    pruef('Das Linkelement misst 50 mm', laenge('LINK_A_OGL'), 0.05, 1e-9, 'm');
    pruef('… auch am Untergurt', laenge('LINK_A_UGR'), 0.05, 1e-9, 'm');
    /*
     * UND ES LIEGT LOTRECHT UEBER DEM GURTKNOTEN - der Anschlusspunkt
     * verschiebt sich in der Jochachse nicht mehr gegen den Gurt.
     */
    const lk = stabVon('LINK_A_OGL');
    wahr('Das Link steht lotrecht über dem Gurt',
         Math.abs(knotenVon(lk.von).x - knotenVon(lk.bis).x) < 1e-9
         && Math.abs(knotenVon(lk.von).y - knotenVon(lk.bis).y) < 1e-9);
  }
  pruef('Die Mastachse steht in der Jochendebene',
        knotenVon('MAST_A_OG').x, 0, 1e-9, 'm');
  pruef('Und am anderen Ende auf der Stuetzweite',
        knotenVon('MAST_B_OG').x, 20, 1e-9, 'm');

  // --- Der Querschnitt: R folgt aus der Flaeche ---------------------------
  const qs = j.querschnitte.find((q) => q.name.startsWith('MAST_'));
  wahr('Der Mast traegt ein I-Profil', qs && qs.form === 'I', qs && qs.form);
  wahr('Und nennt sein Profil', qs.profil === 'HEB 240', qs.profil);
  {
    // A = 2*b*tf + (h-2tf)*tw + (4-pi)*R^2 - mit dem ausgeleiteten R muss
    // die Flaeche die der Tabelle sein. Sonst meldet die Bruecke sie zurueck.
    const [h, b, tw, tf, R] = qs.parameter;
    const A = (2 * b * tf + (h - 2 * tf) * tw + (4 - Math.PI) * R * R) / 1e6;
    // 1e-7 statt 1e-9: R geht auf sechs Nachkommastellen gerundet in die
    // Datei, das schlaegt mit 1.7e-11 m2 auf die Flaeche durch.
    pruef('Der Ausrundungsradius trifft die Tabellenflaeche', A, qs.A, 1e-7, 'm2');
    pruef('Und liegt beim HEB 240 auf dem Normwert 21 mm', R, 21, 0.05, 'mm');
  }

  // --- Die Drehlage folgt der Stegrichtung --------------------------------
  wahr('Steg in Jochachse: Profilhoehe in die Jochachse',
       JSON.stringify(stabVon('MAST_A_S2').lcsZ) === '[1,0,0]',
       JSON.stringify(stabVon('MAST_A_S2').lcsZ));
  {
    const wQ = { ...wM, mastSteg: 'quer' };
    const mQ = modell(wQ, getProfil(wQ.profOG), getProfil(wQ.profUG),
                      getStahl(wQ.stahl), T.getTragjoch('J90'));
    const jQ = AXM.stabmodellJson(mQ, { knotenmodell: 'anschnitt', auflagerModell: 'mast' });
    wahr('Steg gedreht: Profilhoehe in die Gleisrichtung',
         JSON.stringify(jQ.staebe.find((x) => x.name === 'MAST_A_S2').lcsZ) === '[0,1,0]');
  }

  // --- Ohne Mast kein Mastmodell -----------------------------------------
  {
    const wG = basis({ endbedingung: 'gelenkig', mastVorhanden: false });
    const mG = modell(wG, getProfil(wG.profOG), getProfil(wG.profUG),
                      getStahl(wG.stahl), T.getTragjoch('J90'));
    let meldung = '';
    try { AXM.stabmodellJson(mG, { auflagerModell: 'mast' }); }
    catch (f) { meldung = f.message; }
    // Sie zeigt auf den Schalter, der ihn einschaltet - seit dem 28. August
    // steht der unter «Masten» und nicht mehr in der Endauflagerwahl.
    wahr('Ohne Mast sagt die Ausleitung, was fehlt',
         meldung.includes('Mast') && meldung.includes('Masten im Modell'),
         meldung);
  }
  wahr('Und der Dialog bietet das Modell nur mit Mast an',
       AXM.AUFLAGERMODELLE.find((a) => a.key === 'mast').braucht === 'mast');

  /*
   * DIE MESSUNG AM GEBAUTEN MODELL, HIER FESTGEHALTEN.
   *
   * AxisVM 18 r1k, 27.08.: Feldmoment 27.60 kNm gegen 29.51 kNm der
   * Anwendung. Aus dem Feldmoment rueckgerechnet ergibt das eine wirksame
   * Drehfeder von 3.98*E*I/H - der Lehrbuchwert 4.00 des unverschieblichen
   * Rahmens auf ein halbes Prozent. Damit steht dieser Aufbau gegen die
   * Theorie: Geometrie, Querschnitt, Anschluss und Einspannung stimmen.
   *
   * ENTSCHIEDEN AM 31. AUGUST: der Rechenkern nimmt jetzt 4.00 statt 3.10.
   * Damit rechnet die Anwendung 27.57 kNm gegen die gemessenen 27.60 - eine
   * Uebereinstimmung auf ein Promille. Diese Kontrolle haelt beides fest:
   * dass der Rechenkern den Lehrbuchwert ansetzt und dass die Messung selbst
   * darauf fuehrt.
   */
  {
    const EIH = E_STAHL * mM.federn.mastA.I / mM.federn.mastA.H;
    pruef('E*I/H des HEB 240 auf 7.00 m', EIH, 3378, 1e-3, 'kNm/rad');
    pruef('Der Rechenkern nimmt davon das 4.00-fache',
          mM.federn.roh.cA / EIH, MAST_UNVERSCHIEBLICH, 1e-9, '-');
    const feldBei = (c) => {
      const r = auflagermomente({ L: mM.L, qd: mM.qd, P: [], M: [],
                                  EI: mM.steif.EI, cA: c, cB: c,
                                  theta0A: 0, theta0B: 0, MkA: 0, MkB: 0 });
      return (mM.qd * mM.L * mM.L) / 8 - Math.abs(r.MA);
    };
    pruef('Damit rechnet die Anwendung 27.57 kNm im Feld',
          feldBei(mM.federn.roh.cA), 27.5697, 1e-3, 'kNm');
    // Das ist der eigentliche Gewinn des Entscheids: gemessen 27.60.
    wahr('… und trifft die Messung auf ein Promille',
         Math.abs(feldBei(mM.federn.roh.cA) - 27.60) / 27.60 < 2e-3);
    // Gemessen wurden 27.60 - welche Feder erklaert das?
    let lo = 100, hi = 1e7;
    for (let i = 0; i < 200; i++) {
      const mid = Math.sqrt(lo * hi);
      if (feldBei(mid) > 27.60) lo = mid; else hi = mid;
    }
    const cEff = Math.sqrt(lo * hi);
    pruef('Gemessene 27.60 kNm bedeuten 3.98 mal E*I/H', cEff / EIH, 3.98, 2e-3, '-');
    wahr('Also der Lehrbuchwert des unverschieblichen Rahmens',
         Math.abs(cEff / EIH - 4.00) < 0.03, (cEff / EIH).toFixed(3));
  }
}

titel('36  Der Weg von der Ausleitung in AxisVM');

/*
 * DER AUFBAU SOLL OHNE AUFRAEUMEN GEHEN.
 *
 * Bisher galt in der Bruecke "die einzige *.json daneben". Das ging genau
 * EINMAL gut: der Aufbau legt selbst AxisVM_zuordnung.json daneben, das
 * Auslesen dazu seine Ergebnisdatei. Ab dem zweiten Lauf lagen mehrere da
 * und das Skript hielt an - wer bauen wollte, musste vorher loeschen.
 */
{
  const CMD = readFileSync(join(HIER, 'com', 'AxisVM_aufbauen.cmd'), 'utf8');
  const PS1 = readFileSync(join(HIER, 'com', 'AxisVM_aufbauen.ps1'), 'utf8');

  wahr('Die Bruecke erkennt eine Modelldatei am Format',
       /IstModelldatei/.test(PS1)
       && /tragjoch-stabmodell/.test(PS1.slice(PS1.indexOf('function IstModelldatei'),
                                               PS1.indexOf('function IstModelldatei') + 900)));
  wahr('Und liest dafuer nur den Dateianfang',
       /OpenRead/.test(PS1) && /byte\[\] 800/.test(PS1));
  wahr('Von mehreren nimmt sie die juengste',
       /Sort-Object LastWriteTime -Descending/.test(PS1));
  wahr('Und sagt, welche sie uebergangen hat',
       /Modelldateien daneben/.test(PS1));
  wahr('Die eigene Zuordnungsdatei traegt ein anderes Format',
       /format\s*=\s*'tragjoch-axisvm-zuordnung'/.test(PS1));

  /*
   * ALLES, WAS ZU EINEM MODELL GEHOERT, LIEGT BEIM MODELL.
   *
   * Bericht, Zuordnung und Ergebnisse standen frueher immer neben dem
   * SKRIPT. Das geht fuer ein Tragwerk; bei mehreren Projekten mit je
   * mehreren Jochen ueberschreibt sich dort alles gegenseitig.
   */
  wahr('Die Nebendateien heissen wie die Modelldatei',
       /function NebenDatei/.test(PS1));
  ['_bericht.txt', '_zuordnung.json', '_ergebnisse.json'].forEach((a) => {
    wahr(`Und dazu gehoert ${a}`, PS1.includes(`NebenDatei $Json '${a}'`));
  });
  wahr('Das Modell selbst liegt ohnehin dort',
       /ChangeExtension\(\$Json, '\.axs'\)/.test(PS1));
  wahr('Die Startdatei nennt keinen festen Berichtspfad mehr',
       !/AxisVM_aufbau_bericht\.txt/.test(CMD));
  wahr('Und reicht weitere Schalter mit durch',
       /:sammeln/.test(CMD) && /set "ARGS=%ARGS% %1"/.test(CMD));
  wahr('Auslesen ruft mit denselben Argumenten auf',
       readFileSync(join(HIER, 'com', 'AxisVM_auslesen.cmd'), 'utf8')
         .includes('AxisVM_aufbauen.cmd" %* -Auslesen'));

  /*
   * STAPEL: JE MODELL EIN AxisVM-MODELL (Weisung).
   *
   * Ein Projekt hat eine Reihe von Tragwerken. Jedes wird EINZELN in ein
   * eigenes AxisVM-Modell gebaut und liegt als eigene .axs neben seiner
   * Ausleitung - nicht alle zusammen in eine Datei.
   */
  wahr('Ein Ordner laesst sich uebergeben', /\[string\]\$Ordner,/.test(PS1));
  wahr('Und ein hineingezogener Ordner wird dazu',
       CMD.includes('set "ARGS=-Ordner') && CMD.includes('%ERSTES%'),
       CMD.split(NL).filter((z) => z.includes('-Ordner')).join(' | '));
  wahr('Gebaut wird je Datei ein eigener Lauf',
       /\$PSCommandPath/.test(PS1) && /'-Stapel'/.test(PS1));
  // Kein Read-Host mehr im Klartext - es steckt jetzt hinter `Warte`,
  // und die prueft den Schalter.
  wahr('Im Stapel wartet niemand auf Enter',
       /function Warte/.test(PS1)
       && PS1.split('Read-Host').length === 2
       && /if \(-not \$Stapel\) \{ Read-Host/.test(PS1),
       `${PS1.split('Read-Host').length - 1} Read-Host`);
  wahr('Der Sammelbericht liegt im Ordner',
       /Join-Path \$Ordner 'AxisVM_stapel_bericht\.txt'/.test(PS1));
  wahr('Und nennt jede Datei mit Erfolg oder Fehlschlag',
       /FEHLGESCHLAGEN/.test(PS1) && /gebaut  ->/.test(PS1));

  // Ziehen statt kopieren: Windows uebergibt den Pfad als erstes Argument.
  wahr('Die Startdatei nimmt eine hineingezogene Datei entgegen',
       /set "ARGS=-Json/.test(CMD) && /ERSTES/.test(CMD));
  wahr('Ein Schalter bleibt ein Schalter',
       /if "%ERSTES:~0,1%"=="-" goto :starten/.test(CMD));
  // Der Browser nennt eine zweite Ausleitung "... (1).json"; eine Klammer
  // im Pfad wuerde einen Klammerblock der Eingabeaufforderung schliessen.
  wahr('Und tut das ohne Klammerbloecke',
       !/if defined ERSTES \(/.test(CMD) && /goto :starten/.test(CMD));
}

{
  // DER NAME MUSS SAGEN, WAS DRIN STEHT: Knoten- und Auflagermodell aendern
  // das Tragwerk. Unter demselben Namen legte der Browser die zweite
  // Ausleitung als "... (1).json" ab - und die Bruecke nimmt die juengste.
  const AXN = await import(J('export.axisvm.js'));
  const wN = basis({ endbedingung: 'gelenkig' });
  const mN = modell(wN, getProfil(wN.profOG), getProfil(wN.profUG),
                    getStahl(wN.stahl), T.getTragjoch('J90'));
  const namen = new Set();
  let heruntergeladen = null;
  /*
   * ATTRAPPEN FUER DEN DOWNLOAD - UND SIE WERDEN ZURUECKGEGEBEN.
   *
   * `delete globalThis.URL` nahm nicht die Attrappe weg, sondern das
   * eingebaute URL von Node: alles danach lief auf einen ReferenceError.
   * Gemerkt und wiederhergestellt statt geloescht.
   */
  const echt = { Blob: globalThis.Blob, URL: globalThis.URL,
                 document: globalThis.document };
  globalThis.Blob = class { constructor(t) { this.t = t; } };
  globalThis.URL = { createObjectURL: () => 'blob:x', revokeObjectURL: () => {} };
  globalThis.document = { createElement: () => ({ click() { heruntergeladen = this.download; } }) };
  ['gurte', 'punkt', 'mitte'].forEach((am) => ['anschnitt', 'schwerachsen'].forEach((km) => {
    const r = AXN.exportiereJson(wN, { modell,
      profOG: getProfil(wN.profOG), profUG: getProfil(wN.profUG),
      stahl: getStahl(wN.stahl), joch: T.getTragjoch('J90') },
      { knotenmodell: km, auflagerModell: am });
    namen.add(r.name);
    wahr(`Der Name nennt ${km} und ${am}`,
         r.name.includes(km) && r.name.endsWith(`_${am}.json`), r.name);
  }));
  pruef('Sechs Einstellungen, sechs verschiedene Namen', namen.size, 6, 1e-12, 'Stk');

  /*
   * DIE VERORTUNG STEHT IM NAMEN, IN DER BEZEICHNUNG UND IM MODELL.
   *
   * Ein Projekt hat eine Reihe von Tragwerken; ohne Verortung heissen sie
   * alle "J90, 20.00 m". Rechnerisch aendert sie nichts - deshalb wird hier
   * geprueft, dass sie ueberall ankommt UND dass sie nichts verschiebt.
   */
  {
    const wV = basis({ endbedingung: 'gelenkig',
                       linie: '999', km: '012.345', ortschaft: 'Beispielort' });
    const mV = modell(wV, getProfil(wV.profOG), getProfil(wV.profUG),
                      getStahl(wV.stahl), T.getTragjoch('J90'));
    pruef('Die Verortung aendert das Feldmoment nicht', mV.MA, mN.MA, 1e-12, 'kNm');
    wahr('Das Modell traegt sie mit',
         mV.linie === '999' && mV.km === '012.345' && mV.ortschaft === 'Beispielort');
    // REIHENFOLGE LINIE - ORT - KM (Weisung): vom Groben zum Feinen.
    wahr('Als Zeile gelesen: Linie, Ort, KM',
         verortung(mV) === 'Linie 999 · Beispielort · KM 012.345',
         verortung(mV));
    wahr('Leere Angaben fallen weg',
         verortung({ linie: '', km: '012.345', ortschaft: '' }) === 'KM 012.345');
    wahr('Ohne Angabe bleibt die Zeile leer', verortung({}) === '');
    const jV = AXN.stabmodellJson(mV, { knotenmodell: 'anschnitt' });
    wahr('Die Ausleitung nennt sie einzeln',
         jV.tragwerk.linie === '999' && jV.tragwerk.km === '012.345'
         && jV.tragwerk.ortschaft === 'Beispielort');
    wahr('Und in der Bezeichnung', jV.tragwerk.bezeichnung.includes('KM 012.345'),
         jV.tragwerk.bezeichnung);
    const rV = AXN.exportiereJson(wV, { modell,
      profOG: getProfil(wV.profOG), profUG: getProfil(wV.profUG),
      stahl: getStahl(wV.stahl), joch: T.getTragjoch('J90') },
      { knotenmodell: 'anschnitt', auflagerModell: 'punkt' });
    wahr('Der Dateiname traegt sie vorne, in derselben Reihenfolge',
         rV.name.startsWith('AxisVM_L999_Beispielort_KM012.345_'), rV.name);
    // Sonderzeichen und Leerzeichen taugen nicht in einen Dateinamen.
    wahr('Und vertraegt Leerzeichen im Ortsnamen',
         verortungKurz({ ortschaft: 'Bahnhof Nord' }) === 'Bahnhof-Nord',
         verortungKurz({ ortschaft: 'Bahnhof Nord' }));
    wahr('Ebenso einen Schraegstrich',
         !verortungKurz({ ortschaft: 'A/B' }).includes('/'),
         verortungKurz({ ortschaft: 'A/B' }));
  }

  /*
   * DER MASTWIND AUF DAS JOCH IST AUS (Weisung, 27. August).
   *
   * Der Ersatzbalken kann ihn nur als AUFGEZWUNGENE Auflagerverdrehung
   * fassen - eine Ersatzgroesse fuer etwas, das im Stabmodell schlicht eine
   * Last auf dem Masten ist. Steht der Mast im Modell, traegt er sie selbst;
   * die Ersatzgroesse waere dann ein zweiter Ansatz derselben Last.
   */
  {
    const f = FELDER.find((x) => x.key === 'mastWindAufJoch');
    wahr('Der Startwert des Mastwind-Schalters ist aus', f.standard === false,
         String(f.standard));
    wahr('Und standardwerte() traegt ihn so',
         standardwerte().mastWindAufJoch === false);
    // Ohne ihn gibt es keine aufgezwungene Verdrehung - aber der Mast bleibt
    // Auflager, seine Drehfeder wirkt weiter.
    const wA = basis({ endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.0,
                       mastSteg: 'jochachse', mastAnschluss: 'durchlaufend',
                       wMastAusTabelle: false, wMast: 0.4,
                       beiwerteFest: { G: 0, WindX: 1, WindY: 0, Schnee: 0 } });
    const mAus = modell(wA, getProfil(wA.profOG), getProfil(wA.profUG),
                        getStahl(wA.stahl), T.getTragjoch('J90'));
    const mAn = modell({ ...wA, mastWindAufJoch: true },
                       getProfil(wA.profOG), getProfil(wA.profUG),
                       getStahl(wA.stahl), T.getTragjoch('J90'));
    wahr('Aus heisst: keine aufgezwungene Verdrehung',
         Math.abs(mAus.theta0A) < 1e-12 && Math.abs(mAn.theta0A) > 0,
         `${mAus.theta0A} gegen ${mAn.theta0A}`);
    wahr('Die Drehfeder des Mastes wirkt trotzdem',
         mAus.federn.roh.cA > 0);
  }

  /*
   * DER WIND AUF DEN MAST IST KEINE OPTION (Weisung, 27. August).
   *
   * Steht der Mast im Stabmodell, ist er Teil des Tragwerks und wird belastet
   * wie das Joch - in beiden Richtungen, jede in ihrem Lastfall. Beide Werte
   * kommen aus derselben Tabellenzeile; die Stegrichtung entscheidet nur,
   * welche Spalte quer und welche laengs ist.
   */
  {
    const bauM = (profil, steg = 'jochachse') => {
      // DIE EINWIRKUNGSKLASSE WIRD GENANNT, nicht geerbt. Die Zahlen unten
      // sind die EK2-Spalte der Lasttabelle; als der Startwert am
      // 1. September auf EK1 wechselte, fielen sie, ohne dass am Geprueften
      // etwas falsch war.
      const w = basis({ endbedingung: 'mast', mastProfil: profil, mastH: 7.0,
                        mastSteg: steg, mastAnschluss: 'durchlaufend',
                        windKlasse: '1.1' });
      return modell(w, getProfil(w.profOG), getProfil(w.profUG),
                    getStahl(w.stahl), T.getTragjoch('J90'));
    };
    const mH = bauM('HEB 240');
    pruef('HEB 240 faengt in beiden Richtungen gleich viel',
          mH.mastLast.A.x, mH.mastLast.A.y, 1e-12, 'kN/m');
    // Das HEM 240 ist das einzige Profil der Tabelle, das nicht quadratisch
    // ist - an ihm faellt eine vertauschte Spalte ueberhaupt auf.
    const mM = bauM('HEM 240');
    pruef('HEM 240 quer zum Gleis', mM.mastLast.A.x, 0.38, 1e-9, 'kN/m');
    pruef('HEM 240 in Gleisrichtung', mM.mastLast.A.y, 0.42, 1e-9, 'kN/m');
    // Steg gedreht heisst: die beiden Spalten tauschen.
    const mQ = bauM('HEM 240', 'quer');
    pruef('Steg gedreht tauscht die beiden Spalten', mQ.mastLast.A.x, 0.42, 1e-9, 'kN/m');
    pruef('Und die andere ebenso', mQ.mastLast.A.y, 0.38, 1e-9, 'kN/m');

    // Im Modell steht die Last auf JEDEM Maststab, je Richtung ein Lastfall.
    const jM = AXN.stabmodellJson(mM, { knotenmodell: 'anschnitt', auflagerModell: 'mast' });
    const qM = jM.lasten.strecke.filter((q) => q.stab.startsWith('MAST_'));
    /*
     * ZEHN STUECKE, JE ZWEI RICHTUNGEN.
     *
     * Der Schaft wird geteilt, wo etwas an ihm haengt. Je Mast sind das
     * fuenf Stuecke: Fuss - Konsolansatz Untergurt - Untergurt - Obergurt -
     * Konsolansatz Obergurt - Kopf.
     *
     * Die beiden KONSOLANSAETZE kamen am 15. September dazu (Weisung: "das
     * auflger fuer das tragjoch angleichen an abfangjoch"). Die Konsole
     * setzt seither versetzt an, damit sie nicht in der Ebene des
     * horizontalen Blechs laeuft - und der Mast wird dort GETEILT, statt
     * einen zweiten Stab neben sich zu bekommen: sie ist angeschweisst.
     *
     * Vorher waren es sechs Stuecke (zwei Maste zu dreien). Die Windlast
     * aendert sich dadurch nicht - sie steht auf jedem Stueck mit demselben
     * Wert -, wohl aber ihre Zahl.
     */
    pruef('Zehn Maststaebe, je zwei Richtungen', qM.length, 20, 1e-12, 'Stk');
    wahr('Jochachse im Lastfall WindX',
         qM.filter((q) => q.lastfall === 'WindX')
           .every((q) => q.richtung === 'X' && Math.abs(q.wert - 0.38) < 1e-9));
    wahr('Gleisrichtung im Lastfall WindY',
         qM.filter((q) => q.lastfall === 'WindY')
           .every((q) => q.richtung === 'Y' && Math.abs(q.wert - 0.42) < 1e-9));
    // Ohne Mast im Modell gibt es nichts zu belasten.
    const jP = AXN.stabmodellJson(mM, { knotenmodell: 'anschnitt', auflagerModell: 'punkt' });
    wahr('Ohne Mast im Modell keine Maststreckenlast',
         jP.lasten.strecke.every((q) => !q.stab.startsWith('MAST_')));
  }
  void heruntergeladen;
  globalThis.Blob = echt.Blob; globalThis.URL = echt.URL;
  globalThis.document = echt.document;
}

titel('37  Anbauteile am Masten');

/*
 * WEISUNG DES AUFTRAGGEBERS, 27. August: am Masten sollen sich Anbauteile
 * und Leiter ansetzen lassen - ausser Jochaufsatz und Haengestuetze.
 *
 * Die Ausnahme steht nicht als Verbotsliste im Code, sie steht in den Daten:
 * die Bauteiltabelle fuehrt drei Rollen, und `traeger` tragen genau die
 * Jochaufsaetze und die Haengestuetze. Ein Traeger IST das, was auf dem Joch
 * sitzt oder daran haengt.
 */
{
  const AXA = await import(J('export.axisvm.js'));
  const DA = await import(J('data.anbauteile.js'));
  const { konstruktionsChecks } = await import(J('core.checks.js'));

  // Die Regel gegen die Datenbank gelesen, nicht gegen eine Liste im Code.
  {
    const traeger = FL.flBauteile().filter((b) => b.rolle === 'traeger');
    wahr('Traeger sind genau Jochaufsaetze und Haengestuetzen',
         traeger.length > 0
         && traeger.every((b) => /jochaufsatz|haengestuetze|haengerohr/.test(b.id)),
         traeger.map((b) => b.id).join(' '));
    // Traverse, Ausleger, Lampe: Aufbau, also am Masten zulaessig.
    ['anbauteil-leiter-traverse', 'anbauteil-ausleger-typ-rohr',
     'anbauteil-lampe-led'].forEach((id) => {
      wahr(`${id} ist kein Traeger`,
           FL.getFlBauteil(id).rolle !== 'traeger', FL.getFlBauteil(id).rolle);
    });
  }

  const vorl = DA.getVorlage('leiter-traverse');
  const bauTeil = (o) => ({
    id: o.id, name: o.name, vorlage: 'leiter-traverse',
    x: o.x ?? 0, raster: vorl.raster ?? 0.4, befestigung: vorl.befestigung,
    module: JSON.parse(JSON.stringify(vorl.module)), aktiv: true, ...o });

  const wM = basis({
    endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.0,
    mastSteg: 'jochachse', mastAnschluss: 'durchlaufend',
    anbauteile: [
      bauTeil({ id: 'T1', name: 'am Joch', x: 6 }),
      bauTeil({ id: 'M1', name: 'am Mast A', ort: 'mastA', hMast: 5.0 }),
      bauTeil({ id: 'M2', name: 'am Mast B', ort: 'mastB', hMast: 4.0 }),
      bauTeil({ id: 'M3', name: 'in der Luft', ort: 'mastA', hMast: 99 }),
    ] });
  const mM = modell(wM, getProfil(wM.profOG), getProfil(wM.profUG),
                    getStahl(wM.stahl), T.getTragjoch('J90'));

  // --- Der Ersatzbalken kennt nur das Joch --------------------------------
  wahr('Am Joch gerechnet wird nur, was am Joch haengt',
       (mM.anbauteileFlach ?? []).every((t) => !DA.amMast(t)));
  pruef('Drei Baugruppen stehen an den Masten', mM.anbauMast.length, 3, 1e-12, 'Stk');
  {
    // Ein Teil an den Masten zu haengen darf das Joch NICHT belasten.
    const wOhne = { ...wM, anbauteile: wM.anbauteile.filter((a) => !a.ort) };
    const mOhne = modell(wOhne, getProfil(wM.profOG), getProfil(wM.profUG),
                         getStahl(wM.stahl), T.getTragjoch('J90'));
    pruef('Sie aendern das Stuetzmoment des Jochs nicht', mM.MA, mOhne.MA, 1e-12, 'kNm');
  }

  // --- Im Stabmodell mit Mast stehen sie ----------------------------------
  const jM = AXA.stabmodellJson(mM, { knotenmodell: 'anschnitt',
                                      auflagerModell: 'mast', eingabe: wM });
  const knV = new Map(jM.knoten.map((k) => [k.name, k]));
  /*
   * Der Mast wird dort geteilt, wo etwas an ihm haengt: Fuss, Anbauhoehe,
   * Untergurt, Obergurt - seit dem 5. September zusaetzlich am KOPF, der
   * durch die Kopplung an die Anschlusshoehe (H + 0.50 m) immer da ist, und
   * seit dem 15. September an den beiden KONSOLANSAETZEN (siehe dort: die
   * Konsole setzt versetzt an und ist angeschweisst, nicht angehaengt).
   * Also sechs Stuecke.
   */
  const stA = jM.staebe.filter((x) => /^MAST_A_S/.test(x.name));
  pruef('Der Mast A ist an der Anbauhoehe geteilt', stA.length, 6, 1e-12, 'Stk');
  pruef('Und der Knoten liegt auf der eingegebenen Hoehe',
        knV.get('MAST_A_H1').z - knV.get('MAST_A_F').z, 5.0, 1e-9, 'm');
  wahr('Die Kette haengt am Mastknoten',
       jM.staebe.some((x) => x.name.startsWith('ARMM') && x.von === 'MAST_A_H1'));
  // Gespiegelt am Ende B: aussen liegt dort in -x.
  {
    const b = jM.staebe.find((x) => x.name.startsWith('ARMM') && x.von === 'MAST_B_H1');
    wahr('Am Ende B haengt sie am dortigen Mastknoten', !!b);
    wahr('Und die Mastachse steht auf der Stuetzweite',
         Math.abs(knV.get('MAST_B_H1').x - 20) < 1e-9);
  }
  // Die Lasten sitzen an den Knoten der Kette, nicht am Joch.
  {
    const amMastKn = new Set(jM.knoten.filter((k) => k.name.startsWith('AM')).map((k) => k.name));
    const lp = jM.lasten.punkt.filter((q) => amMastKn.has(q.knoten));
    wahr('Am Masten stehen Lasten', lp.length > 0, `${lp.length} Punktlasten`);
    wahr('Und zwar in mehreren Lastfaellen',
         new Set(lp.map((q) => q.lastfall)).size > 1,
         [...new Set(lp.map((q) => q.lastfall))].join(' '));
  }
  /* =======================================================================
   * >>> EINE HOEHE UEBER DER MASTSPITZE WIRD GEBAUT (20. September). <<<
   * =======================================================================
   *
   * Weisung: «lasten oberhalb mastspitze zulassen.»
   *
   * Hier stand das Gegenteil - «ein Teil in der Luft wird nicht gebaut»,
   * und die Datei fuehrte es in `anbauMastAus`. Das war die Stelle, an der
   * Nachweis und Ausleitung auseinanderliefen: der Nachweis rechnete die
   * Last auf ihrem Hebelarm, das Modell kannte sie nicht.
   *
   * Jetzt bekommt sie ihren Knoten auf der Mastachse und haengt an einem
   * STARREN Stueck ueber der Spitze. Das Teil «in der Luft» sitzt auf
   * h = 99 m an einem Masten von 7.50 m - absichtlich absurd: die Weisung
   * setzt keine Grenze, und eine erfundene waere schlechter als der
   * Hinweis, der die Stelle beim Namen nennt.
   * ===================================================================== */
  {
    const aus = jM.tragwerk.anbauMastAus;
    pruef('Nichts faellt mehr aus dem Modell', aus.length, 0, 1e-12, 'Stk');
    const kopf = Math.max(...jM.knoten.filter((k) => /^MAST_A_(KOPF|OG)$/.test(k.name))
      .map((k) => k.z));
    const hoch = jM.knoten.find((k) => /^MAST_A_H\d+$/.test(k.name)
      && Math.abs(k.z - (knV.get('MAST_A_F').z + 99)) < 1e-9);
    wahr('Das Teil ueber der Spitze hat seinen Knoten', !!hoch,
         hoch ? `${hoch.name} auf z = ${hoch.z.toFixed(2)}` : 'keiner');
    const auf = jM.staebe.filter((x) => /^MASTAUFSATZ_A_/.test(x.name));
    pruef('Und ein starres Stueck traegt ihn', auf.length, 1, 1e-12, 'Stk');
    wahr('Es beginnt an der Mastspitze und ist starr',
         auf[0].art === 'starr'
         && Math.abs((knV.get(auf[0].von)?.z ?? -9) - kopf) < 1e-9
         && auf[0].bis === hoch?.name,
         `${auf[0].von} -> ${auf[0].bis}, ${auf[0].art}`);
    wahr('Die Kette haengt daran',
         jM.staebe.some((x) => x.name.startsWith('ARMM') && x.von === hoch?.name));
    const amHoch = new Set(jM.knoten
      .filter((k) => k.name.startsWith('AM') && k.z > kopf + 1e-9).map((k) => k.name));
    wahr('Und ihre Lasten stehen im Modell',
         jM.lasten.punkt.some((q) => amHoch.has(q.knoten)),
         `${jM.lasten.punkt.filter((q) => amHoch.has(q.knoten)).length} Punktlasten`);
    const { hinweise } = await import(J('core.checks.js'));
    const hz = hinweise(mM).join(' | ');
    wahr('Der Hinweis nennt die Stelle, ohne sie zu verbieten',
         /über der Mastspitze/.test(hz) && /zugelassen/.test(hz),
         (hz.split(' | ').find((z) => /Mastspitze/.test(z)) ?? '-').slice(0, 90));
  }
  /*
   * UNTER DER FUNDAMENTKOTE bleibt es beim Vermerk - das ist der andere
   * Fall (Entscheid vom 18. September: keine Last unter Terrain). Ein
   * eigenes Modell, damit die Zahlen oben unberuehrt bleiben.
   */
  {
    const wU = { ...wM, anbauteile: [...wM.anbauteile,
      bauTeil({ id: 'M4', name: 'unter Terrain', ort: 'mastA', hMast: -1 })] };
    const mU = modell(wU, getProfil(wU.profOG), getProfil(wU.profUG),
                      getStahl(wU.stahl), T.getTragjoch('J90'));
    const jU = AXA.stabmodellJson(mU, { knotenmodell: 'anschnitt',
                                        auflagerModell: 'mast', eingabe: wU });
    const aus = jU.tragwerk.anbauMastAus;
    pruef('Unter der Fundamentkote faellt es weiter heraus', aus.length, 1, 1e-12, 'Stk');
    wahr('Und ist benannt', aus[0].name === 'unter Terrain' && aus[0].hMast === -1,
         JSON.stringify(aus[0]));
  }
  // Ohne Mast im Modell gibt es nichts anzuhaengen.
  {
    const jP = AXA.stabmodellJson(mM, { knotenmodell: 'anschnitt',
                                        auflagerModell: 'punkt', eingabe: wM });
    wahr('Ohne Mast im Modell keine Kette am Masten',
         jP.staebe.every((x) => !x.name.startsWith('ARMM')));
  }

  // --- Kein Traeger am Masten (Pruefung P6) -------------------------------
  {
    const ohne = konstruktionsChecks(mM).find((c) => c.id === 'P6');
    wahr('P6 steht in der Liste, sobald etwas am Masten haengt', !!ohne);
    wahr('Und ist erfuellt, solange kein Traeger dabei ist', ohne.ok === true,
         ohne.status);
    // Eine Haengestuetze am Masten muss auffallen.
    const hs = DA.getVorlage('hs-nur');
    const wHS = { ...wM, anbauteile: [{ id: 'X', name: 'HS am Mast',
      vorlage: 'hs-nur', x: 0, raster: hs.raster ?? 0.4,
      befestigung: hs.befestigung, ort: 'mastA', hMast: 5,
      module: JSON.parse(JSON.stringify(hs.module)), aktiv: true }] };
    const mHS = modell(wHS, getProfil(wM.profOG), getProfil(wM.profUG),
                       getStahl(wM.stahl), T.getTragjoch('J90'));
    const p6 = konstruktionsChecks(mHS).find((c) => c.id === 'P6');
    wahr('Eine Haengestuetze am Masten faellt auf', p6.ok === false, p6.status);
    wahr('Und wird beim Namen genannt',
         /Hängestütze|Haengerohr|Hängerohr/.test(p6.status), p6.status);
  }

  /*
   * AM MASTEN HAENGT KEIN KETTENWERK UNMITTELBAR (Weisung, 27. August).
   *
   * "Die Kettenwerke werden nicht direkt am Masten gehaengt, ausser wenn sie
   * abgefangen werden, sondern auf Ausleger. Am Masten werden nur einzelne
   * Leiter gehaengt oder, falls es Zusatzleiter sind, ueber eine Traverse."
   *
   * Ein Kettenwerk ist Tragseil UND Fahrdraht - die Bauteiltabelle sagt es
   * im Namen, nicht eine Liste im Code.
   */
  {
    const kw = FL.flBauteile().filter((b) => FL.istKettenwerk(b));
    const einzeln = FL.flBauteile()
      .filter((b) => b.gruppe === 'drahtwerk' && !FL.istKettenwerk(b));
    pruef('Vier Kettenwerke in der Tabelle', kw.length, 4, 1e-12, 'Stk');
    wahr('Jedes traegt Tragseil und Fahrdraht',
         kw.every((b) => /ts:/i.test(b.name) && /fd:/i.test(b.name)),
         kw.map((b) => b.name).join(' | '));
    pruef('Acht einzelne Leiter daneben', einzeln.length, 8, 1e-12, 'Stk');
    wahr('Und keiner davon traegt beides',
         einzeln.every((b) => !(/ts:/i.test(b.name) && /fd:/i.test(b.name))));

    // Ein Kettenwerk unmittelbar am Masten: die Vorlage leiter-nfl bringt
    // ein Drahtwerk ohne Aufbau mit.
    const anMast = (vorlage, id) => {
      const v = DA.getVorlage(vorlage);
      const w = basis({ endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.0,
        mastSteg: 'jochachse', mastAnschluss: 'durchlaufend',
        anbauteile: [{ id, name: id, vorlage, x: 0, raster: v.raster ?? 0.4,
                       befestigung: v.befestigung, ort: 'mastA', hMast: 5,
                       module: JSON.parse(JSON.stringify(v.module)), aktiv: true }] });
      return konstruktionsChecks(
        modell(w, getProfil(w.profOG), getProfil(w.profUG),
               getStahl(w.stahl), T.getTragjoch('J90'))).find((c) => c.id === 'P7');
    };
    // Der NT-Ausleger bringt einen Aufbau mit - dort ist das Kettenwerk richtig.
    const mitAusleger = anMast('hs-nt-ausleger', 'MITAUS');
    wahr('Mit Ausleger ist das Kettenwerk am Masten in Ordnung',
         mitAusleger.ok === true, mitAusleger.status);
    /*
     * EIN EINZELNER LEITER DARF UNMITTELBAR HAENGEN - aber «Leiter N-FL» ist
     * keiner. Die Vorlage traegt drahtwerk-n-fl-ts-stcu-50-fd-cu-107, also
     * Tragseil UND Fahrdraht: ein Kettenwerk. Der Rueckleiter (leiter-rl,
     * Cu 95) ist der einzelne Leiter - und der darf.
     */
    const rueckleiter = anMast('leiter-rl', 'RUECKLEITER');
    wahr('Ein einzelner Leiter darf unmittelbar haengen',
         rueckleiter.ok === true, rueckleiter.status);
    const nfl2 = anMast('leiter-nfl', 'NFL');
    wahr('Ein Kettenwerk ohne Ausleger faellt auf',
         nfl2.ok === false && /Kettenwerk/.test(nfl2.status), nfl2.status);
    // Und die Traverse mit Zusatzleiter ebenso - sie IST der Aufbau.
    const traverse = anMast('leiter-traverse', 'TRAVERSE');
    wahr('Zusatzleiter ueber eine Traverse ebenso',
         traverse.ok === true, traverse.status);
    // Die Ausnahme ist noch nicht gebaut - deshalb Hinweis, nicht Fehler.
    wahr('P7 ist ein Hinweis, kein Fehler',
         traverse.warnungNichtFehler === true);
  }
}

titel('38  Hinterlegte Querprofil-Zeichnung');

/*
 * WEISUNG DES AUFTRAGGEBERS, 27. August: die Zeichnung transparent hinter das
 * Modell legen, um Bauteile zuzuordnen und Laengen abzugreifen, ohne im
 * PDF-Reader zu messen.
 *
 * "Die QP-Zeichnungen sind immer orthogonal, eine Ausrichtung ist daher nicht
 * notwendig. Es ist nur die Ansicht auf das Tragwerk vorhanden, xz-Ebene."
 *
 * Damit bleiben drei Unbekannte - Massstab und Lage in x und z -, und zwei
 * Punkte mit bekannten Modellkoordinaten bestimmen alle drei. Gerechnet wird
 * das hier; das Bild selbst braucht einen Browser und steht nicht im
 * Pruefstand.
 */
{
  const BZ = await import(J('bild.zeichnung.js'));

  // --- Waagrechter Bezug: die beiden Jochenden ---------------------------
  {
    // 800 Bildpunkte entsprechen 20 m: 0.025 m je Punkt.
    const p1 = { px: 200, py: 300 }, p2 = { px: 1000, py: 300 };
    const w1 = { x: 0, z: 0 }, w2 = { x: 20, z: 0 };
    const k = BZ.kalibriere(p1, p2, w1, w2);
    pruef('Massstab aus der Jochlaenge', k.s, 0.025, 1e-12, 'm/Punkt');
    // Die geklickten Punkte muessen genau auf ihre Modellpunkte fallen.
    const a = BZ.bildNachWelt(k, p1.px, p1.py);
    const b = BZ.bildNachWelt(k, p2.px, p2.py);
    pruef('Der erste Klick trifft x = 0', a.x, 0, 1e-9, 'm');
    pruef('Der zweite Klick trifft x = L', b.x, 20, 1e-9, 'm');
    wahr('Und beide liegen auf der Jochachse',
         Math.abs(a.z) < 1e-9 && Math.abs(b.z) < 1e-9);
    // Hin und zurueck.
    const r = BZ.weltNachBild(k, 12.5, -3);
    const h = BZ.bildNachWelt(k, r.px, r.py);
    pruef('Hin und zurueck: x', h.x, 12.5, 1e-9, 'm');
    pruef('Hin und zurueck: z', h.z, -3, 1e-9, 'm');
    // z zeigt im Bild nach unten, im Modell nach oben.
    wahr('Tiefer im Bild heisst tiefer im Modell',
         BZ.bildNachWelt(k, 200, 500).z < BZ.bildNachWelt(k, 200, 300).z);
  }

  // --- Lotrechter Bezug: der Mast ----------------------------------------
  {
    // 280 Punkte entsprechen 7.00 m: 0.025 m je Punkt, dasselbe Bild.
    const k = BZ.kalibriere({ px: 200, py: 580 }, { px: 200, py: 300 },
                            { x: 0, z: -7 }, { x: 0, z: 0 });
    pruef('Massstab aus der Masthoehe', k.s, 0.025, 1e-12, 'm/Punkt');
    pruef('Der Fusspunkt liegt auf -H', BZ.bildNachWelt(k, 200, 580).z, -7, 1e-9, 'm');
    wahr('Der Kopfpunkt auf der Jochachse',
         Math.abs(BZ.bildNachWelt(k, 200, 300).z) < 1e-9);
  }

  /*
   * DER MASSSTAB KOMMT AUS DER LAENGEREN RICHTUNG.
   *
   * Klickt man die beiden Jochenden, liegen sie waagrecht weit auseinander
   * und lotrecht fast uebereinander. Naehme man die lotrechte Differenz,
   * stuende im Nenner fast nur das Klickrauschen - ein Punkt daneben ergaebe
   * einen wilden Massstab.
   */
  {
    const genau = BZ.kalibriere({ px: 200, py: 300 }, { px: 1000, py: 300 },
                                { x: 0, z: 0 }, { x: 20, z: 0 });
    const schief = BZ.kalibriere({ px: 200, py: 300 }, { px: 1000, py: 304 },
                                 { x: 0, z: 0 }, { x: 20, z: 0 });
    pruef('Vier Punkte schief aendern den Massstab nicht',
          schief.s, genau.s, 1e-12, 'm/Punkt');
    // Die Lage mittelt den schiefen Klick heraus: 2 Punkte statt 4.
    pruef('Und die Hoehe nur um die Haelfte des Fehlers',
          (schief.z0 - genau.z0) / genau.s, 2, 1e-9, 'Punkte');
  }

  // --- Was keine Kalibrierung ergibt -------------------------------------
  wahr('Zwei gleiche Punkte ergeben keine Kalibrierung',
       BZ.kalibriere({ px: 5, py: 5 }, { px: 5, py: 5 },
                     { x: 0, z: 0 }, { x: 20, z: 0 }) === null);
  wahr('Ein fehlender Punkt ebenso',
       BZ.kalibriere(null, { px: 5, py: 5 }, { x: 0, z: 0 }, { x: 1, z: 0 }) === null);
  wahr('Ohne Kalibrierung gibt es keinen Rahmen',
       BZ.bildRahmen(null, 100, 50) === null
       && BZ.bildNachWelt(null, 1, 1) === null);

  // --- Der Rahmen, den die Ansicht zeichnet ------------------------------
  {
    const k = BZ.kalibriere({ px: 0, py: 0 }, { px: 400, py: 0 },
                            { x: 0, z: 0 }, { x: 10, z: 0 });
    const r = BZ.bildRahmen(k, 400, 200);
    pruef('Rahmen links', r.xVon, 0, 1e-9, 'm');
    pruef('Rahmen rechts', r.xBis, 10, 1e-9, 'm');
    wahr('Rahmen oben auf der Jochachse', Math.abs(r.zBis) < 1e-9);
    pruef('Rahmen unten', r.zVon, -5, 1e-9, 'm');
  }

  // --- Das Bild aus einem Einfuege- oder Ziehereignis ---------------------
  {
    const evMit = { clipboardData: { files: [{ type: 'image/png' }], items: [] } };
    wahr('Ein eingefuegtes Bild wird gefunden', !!BZ.bildAusEreignis(evMit));
    const evText = { clipboardData: { files: [{ type: 'text/plain' }], items: [] } };
    wahr('Text nicht', BZ.bildAusEreignis(evText) === null);
    // Der Bildschirmausschnitt kommt als item, nicht als file.
    const datei = { type: 'image/png' };
    const evItem = { clipboardData: { files: [],
      items: [{ kind: 'file', type: 'image/png', getAsFile: () => datei }] } };
    wahr('Ein Bildschirmausschnitt ebenso', BZ.bildAusEreignis(evItem) === datei);
    wahr('Ohne Zwischenablage nichts', BZ.bildAusEreignis({}) === null);
    // Ziehen liefert dataTransfer statt clipboardData - derselbe Weg.
    wahr('Und eine hineingezogene Datei ebenso',
         !!BZ.bildAusEreignis({ dataTransfer: { files: [{ type: 'image/jpeg' }] } }));
  }

  // --- Die Bezugsmasse ---------------------------------------------------
  {
    const R = await import(J('render.3d.js'));
    const wB = basis({ L: 24, mastVorhanden: false });
    const mB = modell(wB, getProfil(wB.profOG), getProfil(wB.profUG),
                      getStahl(wB.stahl), T.getTragjoch('J90'));
    const eB = rechne(wB);
    const szB = R.erzeugeSzene(eB.modell, eB);
    const j = BZ.bezugPunkte('joch', mB);
    pruef('Der Jochbezug spannt ueber die ganze Laenge', j[1].x - j[0].x, 24, 1e-9, 'm');
    wahr('Beide Punkte auf der Jochachse', j[0].z === 0 && j[1].z === 0);
    const jS = BZ.bezugPunkte('joch', mB, szB);
    wahr('Aus der Szene dieselben Jochenden',
         jS[0].x === 0 && jS[1].x === 24 && jS[0].z === 0 && jS[1].z === 0);
    wahr('Ohne Mast gibt es keinen Mastbezug',
         BZ.bezugPunkte('mast', mB, szB) === null
         && BZ.bezugPunkte('mastLaenge', mB, szB) === null);
    const wM = basis({ endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.0,
                       mastLaenge: 9.0,
                       mastSteg: 'jochachse', mastAnschluss: 'durchlaufend' });
    const eM = rechne(wM);
    const mM = eM.modell;
    const szM = R.erzeugeSzene(mM, eM);
    const mb = BZ.bezugPunkte('mast', mM, szM);
    pruef('Mit Mast reicht der Bezug ueber die Masthoehe',
          mb[1].z - mb[0].z, 7, 1e-9, 'm');
    wahr('Und beide stehen am linken Masten',
         mb[0].x === mb[1].x && mb[0].x === szM.bezug.masten.A.x);
    wahr('Jeder Punkt sagt, was anzuklicken ist',
         [...j, ...mb].every((x) => typeof x.text === 'string' && x.text.length > 10));

    /* =====================================================================
     * >>> DER BEZUG SITZT, WO DER MAST GEZEICHNET IST (18. September). <<<
     * =====================================================================
     *
     * Gemeldet: ueber die Mastlaenge eingemessen, stimmte der Massstab nicht.
     * Der Bezug rechnete den Masten selbst nach - Fuss bei -H, oben die
     * Jochachse. Gezeichnet steht der Fuss H unter der UNTERKANTE, und das
     * Blatt hebt alles um H an. Gemessen wird deshalb an der Schwerachse,
     * die im Bild steht.
     * =================================================================== */
    const achseA = szM.linien.filter((l) => l.gruppe === 'mast' && l.schwerachse
      && Math.abs(l.punkte[0][0] - szM.bezug.masten.A.x) < 1e-9);
    const zs = achseA.flatMap((l) => l.punkte.map((p) => p[2]));
    pruef('Der Mastfuss des Bezugs ist der gezeichnete', mb[0].z, Math.min(...zs),
          1e-9, 'm');
    wahr('Der Anschluss liegt an der Unterkante, nicht auf der Jochachse',
         mb[1].z < -0.05, `z = ${mb[1].z.toFixed(3)}`);
    const ml = BZ.bezugPunkte('mastLaenge', mM, szM);
    pruef('Die Mastlaenge spannt Fuss bis Kopf', ml[1].z - ml[0].z, 9.0, 1e-9, 'm');
    wahr('… vom selben Fuss', ml[0].z === mb[0].z);
    {
      // Auf dem Blatt ist die Szene um H angehoben (blattSzene) - der Bezug
      // wandert mit, und in einer vereinten Szene gilt der des gerechneten.
      const v = R.szeneVerschieben(szM, 5, {}, 7);
      pruef('Verschoben wandert der Fuss mit', v.bezug.masten.A.zF,
            szM.bezug.masten.A.zF + 7, 1e-9, 'm');
      pruef('… und die Lage in x', v.bezug.masten.A.x, szM.bezug.masten.A.x + 5, 1e-9, 'm');
      pruef('… und das Joch', v.bezug.joch.xB, szM.bezug.joch.xB + 5, 1e-9, 'm');
      const nb = R.szeneVerschieben(szB, 40, {}, 0);
      const ver = R.szenenVereinen([{ ...nb, aktiv: false }, { ...v, aktiv: true }]);
      wahr('Vereint gilt der Bezug des gerechneten Tragwerks',
           ver.bezug === v.bezug);
    }

    /* =====================================================================
     * >>> WAS ZUR WAHL STEHT, HAENGT AM MODELL. <<<
     * =====================================================================
     *
     * Weisung vom 12. September: "man muesste hier eine auswahl vornehmen ob
     * ein mast (vertikal) oder ein joch (horizontal) als referenz dient. und
     * die zeichnung muesste dann entsprechend positioniert werden."
     *
     * `bezuegeFuer` fuehrt nur, was es im Modell wirklich gibt - und das
     * freie Mass, das es immer gibt.
     * =================================================================== */
    wahr('Ohne Mast stehen Joch und freies Mass zur Wahl',
         BZ.bezuegeFuer(mB, szB).map((b) => b.key).join() === 'joch,frei');
    wahr('Mit Mast dazu Masthoehe und Mastlaenge',
         BZ.bezuegeFuer(mM, szM).map((b) => b.key).join()
           === 'joch,mast,mastLaenge,frei');
    wahr('Jeder gemessene Bezug bringt seine zwei Punkte gleich mit',
         BZ.bezuegeFuer(mM, szM).every((b) => b.frei
           || (Array.isArray(b.welt) && b.welt.length === 2
               && typeof b.label === 'string')));
    wahr('Ohne Modell steht nichts zur Wahl', BZ.bezuegeFuer(null).length === 0);
    /*
     * UND DIE ZEICHNUNG WIRD ENTSPRECHEND GESETZT. Ein Blatt in bekannter
     * Lage (0.025 m je Punkt): die Bildpunkte der Bezuege aus der Umkehrung,
     * dann ueber jeden Bezug eingemessen - jedes Mal muss dieselbe Lage
     * herauskommen, sonst passt nur eine der Richtungen.
     */
    {
      const wahrK = { s: 0.025, x0: -6, z0: 3 };
      const bild = (w) => BZ.weltNachBild(wahrK, w.x, w.z);
      for (const b of BZ.bezuegeFuer(mM, szM).filter((x) => !x.frei)) {
        const k = BZ.kalibriere(bild(b.welt[0]), bild(b.welt[1]), b.welt[0], b.welt[1]);
        pruef(`Ueber «${b.label}» eingemessen: 0.025 m je Punkt`, k.s, 0.025, 1e-9,
              'm/Punkt');
        wahr(`… und dieselbe Lage`, Math.abs(k.x0 - wahrK.x0) < 1e-9
             && Math.abs(k.z0 - wahrK.z0) < 1e-9);
      }
      // Die Erkennung findet Mastachsen auf der JOCHACHSE und den Mastfuss.
      const eJ = BZ.erkennungsWelt('joch', mM, szM);
      const eMa = BZ.erkennungsWelt('mast', mM, szM);
      wahr('Die Erkennung misst waagrecht zwischen den Mastachsen',
           eJ[0].x === szM.bezug.masten.A.x && eJ[1].x === szM.bezug.masten.B.x
           && eJ[0].z === 0);
      wahr('… und lotrecht vom Fuss zur Jochachse',
           eMa[0].z === mb[0].z && eMa[1].z === 0);
    }

    /* =====================================================================
     * >>> FREIES MASS UND AUSRICHTEN (18. September). <<<
     * =====================================================================
     *
     * «die referenz ist starr am mastfuss» - der Bezugspunkt ist jetzt
     * waehlbar: ein Modellpunkt oder ein frei angeklickter. Ausrichten
     * verschiebt nur; das freie Mass setzt nur den Massstab und haelt den
     * ersten Punkt fest.
     * =================================================================== */
    {
      const alt = { s: 0.02, x0: -3, z0: 8 };
      const p1 = { px: 100, py: 200 }, p2 = { px: 400, py: 600 };
      const f = BZ.kalibriereFrei(p1, p2, 10, alt);
      pruef('Freies Mass: Laenge durch den Abstand im Bild', f.s, 10 / 500, 1e-12,
            'm/Punkt');
      const w1a = BZ.bildNachWelt(alt, p1.px, p1.py);
      const w1n = BZ.bildNachWelt(f, p1.px, p1.py);
      wahr('… und der erste Punkt bleibt, wo er war',
           Math.abs(w1a.x - w1n.x) < 1e-9 && Math.abs(w1a.z - w1n.z) < 1e-9);
      wahr('Ohne Laenge kein Massstab', BZ.kalibriereFrei(p1, p2, 0, alt) === null);
      wahr('Zwei gleiche Punkte ebenso', BZ.kalibriereFrei(p1, p1, 5, alt) === null);

      const pk = BZ.ausrichtPunkte(szM);
      const keys = pk.map((p) => p.key).join();
      wahr('Ausrichten bietet Fuss, Anschluss und Kopf beider Masten und die Jochenden',
           keys === 'fussA,anA,kopfA,fussB,anB,kopfB,jochA,jochB', keys);
      const kopf = pk.find((p) => p.key === 'kopfA');
      pruef('Der Kopf liegt auf der Mastlaenge', kopf.z - mb[0].z, 9.0, 1e-9, 'm');
      const ziel = pk.find((p) => p.key === 'kopfA');
      const a = BZ.ausrichten(alt, { px: 321, py: 77 }, ziel);
      const w = BZ.bildNachWelt(a, 321, 77);
      wahr('Ausgerichtet liegt der Bildpunkt auf dem Modellpunkt',
           Math.abs(w.x - ziel.x) < 1e-9 && Math.abs(w.z - ziel.z) < 1e-9);
      wahr('… und der Massstab bleibt', a.s === alt.s);
    }

    /* =====================================================================
     * >>> DIE VORLAEUFIGE LAGE: UM DAS MODELL, NICHT DOPPELTE JOCHLAENGE. <<<
     * =====================================================================
     *
     * Gemeldet am 18. September: die Zeichnung lag viel zu gross da. Beim
     * Einzelmast wurde das Bild auf 40 m gestreckt, gegen einen Masten von
     * zehn. Jetzt nimmt das Modell rund zwei Drittel des Bildes ein.
     * =================================================================== */
    {
      const g = { xMin: -0.5, xMax: 0.5, zMin: -10, zMax: 1 };
      const k = BZ.vorlaeufigeLage(g, 2000, 1400);
      const r = BZ.bildRahmen(k, 2000, 1400);
      pruef('Einzelmast: das Modell fuellt zwei Drittel der Bildhoehe',
            11 / (r.zBis - r.zVon), BZ.VORLAEUFIG_ANTEIL, 1e-9, '');
      wahr('… und das Bild ist nicht breiter als 30 m', r.xBis - r.xVon < 30,
           `${(r.xBis - r.xVon).toFixed(1)} m`);
      wahr('… mittig um das Modell',
           Math.abs((r.xVon + r.xBis) / 2) < 1e-9
           && Math.abs((r.zVon + r.zBis) / 2 - (-4.5)) < 1e-9);
      const kJ = BZ.vorlaeufigeLage({ xMin: 0, xMax: 20, zMin: 0, zMax: 9 }, 2000, 1400);
      const rJ = BZ.bildRahmen(kJ, 2000, 1400);
      pruef('Joch: zwei Drittel der Bildbreite', 20 / (rJ.xBis - rJ.xVon),
            BZ.VORLAEUFIG_ANTEIL, 1e-9, '');
      wahr('Ohne Grenzen trotzdem eine Lage',
           BZ.vorlaeufigeLage(null, 2000, 1400).s > 0);
    }
  }

  /*
   * DAS PAKET: ZIP MIT BILDERN DANEBEN (Weisung).
   *
   * Die hinterlegten Zeichnungen gehoeren beim Ausleiten als eigene Dateien
   * in den Ablageordner, nicht als Base64 in die JSON. Geschrieben wird mit
   * demselben ZIP-Schreiber, den die .xlsx schon benutzt - ein zweiter waere
   * einer zu viel.
   */
  {
    const XL = await import(J('export.xlsx.js'));
    const bild = new Uint8Array([0xff, 0xd8, 0xff, 0xe0, 1, 2, 3, 250, 0, 77]);
    const paket = XL.zip([
      { name: 'ablage.json', inhalt: '{"art":"tragjoch-ablage"}' },
      { name: 'zeichnungen/TJ-1.jpg', inhalt: bild },
    ]);
    wahr('Ein Paket beginnt mit PK', paket[0] === 0x50 && paket[1] === 0x4b);
    const zurueck = XL.entpacke(paket);
    pruef('Zwei Dateien im Paket', zurueck.length, 2, 1e-12, 'Stk');
    wahr('Die JSON kommt unveraendert zurueck',
         new TextDecoder().decode(zurueck[0].inhalt) === '{"art":"tragjoch-ablage"}');
    wahr('Und das Bild Byte fuer Byte',
         zurueck[1].name === 'zeichnungen/TJ-1.jpg'
         && zurueck[1].inhalt.length === bild.length
         && [...zurueck[1].inhalt].every((b, i) => b === bild[i]));
    // Ein leeres Bild darf nicht durchrutschen.
    const leer = XL.entpacke(XL.zip([{ name: 'a', inhalt: new Uint8Array(0) }]));
    pruef('Auch eine leere Datei bleibt eine Datei', leer.length, 1, 1e-12, 'Stk');
    // Etwas, das keine ZIP ist, sagt es.
    let meldung = '';
    try { XL.entpacke(new Uint8Array([1, 2, 3, 4])); } catch (f) { meldung = f.message; }
    wahr('Etwas anderes wird abgewiesen', meldung.includes('Paket'), meldung);
  }

  /*
   * DIE MASSKETTE DER ZEICHNUNG (Weisung, 27. August: "die masskette ist
   * immer vorhanden, bau die fanglinien ein").
   *
   * Ueber dem Joch steht auf jedem Querprofil eine Kette von Massen in
   * Zentimetern ab dem linken Jochende - die Stellen, an denen wirklich
   * etwas haengt. Einmal abgeschrieben, faengt die Eingabe darauf.
   */
  {
    const { massketteLesen, fangeAufMasskette } = await import(J('core.constants.js'));
    // Die Kette des Schulungsbeispiels: J60 E ueber 12 m.
    const r = massketteLesen('0 15 209 474 735 885 983 1185 1200', 12);
    pruef('Neun Masse gelesen', r.werte.length, 9, 1e-12, 'Stk');
    pruef('In Metern, aufsteigend', r.werte[2], 2.09, 1e-12, 'm');
    pruef('Und das letzte ist die Jochlaenge', r.werte[8], 12, 1e-12, 'm');
    wahr('Ohne Beanstandung', r.hinweis === null);
    // Grosszuegig gelesen: abgeschrieben wird von Hand.
    wahr('Komma, Strichpunkt, Zeilenumbruch trennen ebenso',
         massketteLesen(`15; 209${NL}474,  735`, 0).werte.join(' ')
           === '0.15 2.09 4.74 7.35',
         massketteLesen(`15; 209${NL}474,  735`, 0).werte.join(' '));
    wahr('Doppelte Masse zaehlen einmal',
         massketteLesen('15 15 209', 0).werte.length === 2);
    /*
     * OHNE KETTE MUSS ALLES WEITERGEHEN.
     *
     * Sie steht NICHT auf jedem Blatt (Auftraggeber, 27.08. - zunaechst
     * anders gesagt und gleich darauf berichtigt). Sie ist damit eine
     * Beigabe, kein Weg: wo sie fehlt, wird auf der Zeichnung gemessen, und
     * nichts darf deshalb anhalten oder sich beschweren.
     */
    wahr('Leere Kette bleibt leer', massketteLesen('', 12).werte.length === 0);
    wahr('Und beanstandet nichts', massketteLesen('', 12).hinweis === null);
    wahr('Auch Leerzeichen allein nicht',
         massketteLesen('   ', 12).werte.length === 0
         && massketteLesen('   ', 12).hinweis === null);
    wahr('Und undefiniert ebenso',
         massketteLesen(undefined, 12).werte.length === 0);

    /*
     * DAS LETZTE MASS IST DIE GEGENPROBE. Stimmt es nicht mit der Jochlaenge,
     * ist entweder die Kette aus einer anderen Zeichnung, die Laenge falsch
     * eingestellt, oder es wurden Millimeter abgeschrieben.
     */
    const falsch = massketteLesen('0 15 1200', 20);
    wahr('Eine unpassende Kette faellt auf', !!falsch.hinweis, falsch.hinweis ?? '');
    wahr('Und der Hinweis nennt beide Zahlen',
         falsch.hinweis.includes('12.00') && falsch.hinweis.includes('20.00'));

    // --- Fangen ----------------------------------------------------------
    const k = r.werte;
    pruef('2.07 faengt auf 2.09', fangeAufMasskette(2.07, k), 2.09, 1e-12, 'm');
    pruef('7.30 faengt auf 7.35', fangeAufMasskette(7.30, k), 7.35, 1e-12, 'm');
    pruef('Wer trifft, bleibt', fangeAufMasskette(4.74, k), 4.74, 1e-12, 'm');
    pruef('Wer weit daneben liegt, behaelt seinen Wert',
          fangeAufMasskette(3.40, k), 3.40, 1e-12, 'm');
    /*
     * DIE GRENZE IST NIE GROESSER ALS DIE HALBE LUECKE. 11.85 und 12.00
     * liegen 15 cm auseinander; mit der festen Grenze von 20 cm wuerde das
     * eine das andere ueberdecken, und ein Klick dazwischen faende die
     * falsche Stelle.
     */
    pruef('Zwischen zwei engen Massen gewinnt das naehere',
          fangeAufMasskette(11.92, k), 11.85, 1e-12, 'm');
    pruef('Und knapp darueber das andere',
          fangeAufMasskette(11.94, k), 12, 1e-12, 'm');
    wahr('Ohne Kette faengt nichts', fangeAufMasskette(2.07, []) === 2.07);

    // --- Das Modell traegt sie mit ---------------------------------------
    const wK = basis({ L: 12, masskette: '0 15 209 474 735 885 983 1185 1200' });
    const mK = modell(wK, getProfil(wK.profOG), getProfil(wK.profUG),
                      getStahl(wK.stahl), T.getTragjoch('J90'));
    pruef('Das Modell fuehrt die gelesene Kette', mK.masskette.length, 9, 1e-12, 'Stk');
    // Rechnerisch aendert sie nichts - sie ist eine Anschrift, keine Aussage.
    const wO = basis({ L: 12 });
    const mO = modell(wO, getProfil(wO.profOG), getProfil(wO.profUG),
                      getStahl(wO.stahl), T.getTragjoch('J90'));
    pruef('Und aendert am Feldmoment nichts', mK.MA, mO.MA, 1e-12, 'kNm');
    // Ohne Eintrag fuehrt das Modell eine leere Kette - kein null, kein
    // Sonderfall, den die Ansicht auseinanderhalten muesste.
    wahr('Ohne Eintrag eine leere Kette',
         Array.isArray(mO.masskette) && mO.masskette.length === 0);
    // Und ein Anbauteil behaelt dann jeden Wert, auf drei Stellen genau.
    wahr('Und die Lage bleibt, wie sie eingestellt wurde',
         fangeAufMasskette(7.123, mO.masskette) === 7.123);
  }

  // Verkleinert und als JPEG - die Zahlen stehen an einer Stelle.
  pruef('Verkleinert auf 2000 Punkte Breite', BZ.MAX_BREITE, 2000, 1e-12, 'Punkte');
  wahr('Und als JPEG mit fester Guete', BZ.GUETE > 0.7 && BZ.GUETE < 0.95,
       String(BZ.GUETE));
}

titel('39  Traeger neben den Bindeblechen');

/*
 * WEISUNG DES AUFTRAGGEBERS, 27. August: "die haengestuetze und jochaufsaetze
 * duerfen sich nicht mit den verbindungsblechen beruehren. diese sind
 * automatisch nebenan zu schieben." Dazu: "x auch auf 10 cm runden".
 *
 * Betroffen sind genau die TRAEGER - und das steht wieder in den Daten:
 * `rolle: 'traeger'` tragen die drei Jochaufsaetze und die Haengestuetze,
 * eben das, was am Joch angeschlagen wird. Ein Drahtwerk haengt an einem
 * Aufbau und beruehrt das Joch nie.
 */
{
  const CA = await import(J('core.anbauteile.js'));
  const { konstruktionsChecks: chk } = await import(J('core.checks.js'));

  const wB = basis({ typ: 'J90', L: 20, anbauteile: [] });
  const mB = modell(wB, getProfil(wB.profOG), getProfil(wB.profUG),
                    getStahl(wB.stahl), T.getTragjoch('J90'));

  // --- Die Sperrbereiche kommen aus der Stationsliste --------------------
  const sperren = CA.blechSperren(mB);
  wahr('Je Station ein Sperrbereich',
       sperren.length === mB.stationsListe.length, `${sperren.length}`);
  {
    const s0 = sperren[0], st0 = mB.stationsListe[0];
    // Die Blechbreite steht in Millimetern, der Sperrbereich in Metern.
    pruef('Und er ist so breit wie das Blech',
          s0.bis - s0.von, st0.vertikal.breite / 1000, 1e-9, 'm');
    pruef('Mittig auf der Station', (s0.von + s0.bis) / 2, st0.x, 1e-9, 'm');
  }
  wahr('Luft vergroessert ihn beidseitig',
       Math.abs((CA.blechSperren(mB, 0.05)[0].bis - CA.blechSperren(mB, 0.05)[0].von)
                - (sperren[0].bis - sperren[0].von) - 0.10) < 1e-9);

  // --- Freischieben ------------------------------------------------------
  {
    const st = mB.stationsListe[5];          // eine Station in der Jochmitte
    const b = st.vertikal.breite / 1000;
    // EINE Klemme genau auf dem Blech: raster 0 heisst, beide fallen zusammen.
    const r0 = CA.freieLageAmJoch(st.x, 0, mB);
    wahr('Genau auf dem Blech wird verschoben', r0.verschoben);
    // Knapp daneben, nicht auf die Kante - und auf Millimeter, damit die Zahl
    // in eine Zeichnung passt. Gerundet wird nach AUSSEN: nach innen stuende
    // das Bauteil wieder auf dem Blech.
    wahr('Und zwar knapp daneben, nicht auf die Kante',
         Math.abs(r0.x - st.x) > b / 2,
         `${(r0.x - st.x).toFixed(4)} m gegen halbe Blechbreite ${(b / 2).toFixed(4)}`);
    wahr('Auf ganze Millimeter',
         Math.abs(r0.x * 1000 - Math.round(r0.x * 1000)) < 1e-6, String(r0.x));
    wahr('Mindestens einen Millimeter, nicht auf die Kante',
         Math.abs(r0.x - st.x) >= b / 2 + 0.001 - 1e-9,
         String(Math.abs(r0.x - st.x)));
    wahr('Und nicht weiter als noetig',
         Math.abs(r0.x - st.x) < b / 2 + 0.0021, String(Math.abs(r0.x - st.x)));
    // Daneben bleibt daneben.
    const frei = st.x + 0.30;
    pruef('Wer frei steht, bleibt stehen', CA.freieLageAmJoch(frei, 0, mB).x,
          frei, 1e-12, 'm');
    wahr('Und meldet keine Verschiebung', !CA.freieLageAmJoch(frei, 0, mB).verschoben);
  }

  /*
   * ZWEI KLEMMEN, NICHT EINE. Ein Traeger haengt im Abstand `raster`; beide
   * Klemmen muessen an einem Blech vorbei. Mit raster = Stationsabstand
   * saessen beide zugleich auf je einem Blech - dann muss die Lage weichen,
   * obwohl ihre MITTE frei liegt.
   */
  {
    const a1 = mB.stationsListe[1].x - mB.stationsListe[0].x;
    const mitte = (mB.stationsListe[4].x + mB.stationsListe[5].x) / 2;
    // Die Mitte zwischen zwei Stationen ist fuer sich frei ...
    wahr('Die Mitte zwischen zwei Blechen ist frei',
         !CA.freieLageAmJoch(mitte, 0, mB).verschoben);
    // ... aber mit einem Raster von einem Stationsabstand sitzen beide
    // Klemmen auf den Nachbarblechen.
    const r = CA.freieLageAmJoch(mitte, a1, mB);
    wahr('Mit dem Raster eines Feldes weicht sie trotzdem', r.verschoben,
         `${mitte.toFixed(3)} -> ${r.x.toFixed(3)}`);
  }

  /*
   * ERST WEITEN, DANN WEICHEN (Weisung, 27. August).
   *
   * "Die Joche sind fix, die Anbauteile werden drum herum angebracht. Im
   * Normalfall stehen die Klemmen 0.40 m, aber sollten diese im Bereich der
   * Knoten zu liegen kommen, dann ist der Abstand entsprechend zu
   * vergroessern."
   *
   * Die Weitung ist die gebaute Abhilfe: die Stuetze bleibt, wo sie
   * hingehoert, und ihre Klemmen ueberspannen das Blech.
   */
  {
    const st = mB.stationsListe[6];
    // Eine Lage, bei der die linke Klemme auf dem Blech sitzt.
    const x = st.x + 0.20;
    const an = CA.passeTraegerAn(x, 0.40, mB);
    wahr('Statt zu verschieben wird geweitet', an.geweitet && !an.verschoben,
         JSON.stringify(an));
    pruef('Die Lage bleibt, wo sie ist', an.x, x, 1e-12, 'm');
    wahr('Und das Raster wird groesser', an.raster > 0.40, String(an.raster));
    wahr('Auf ganze Millimeter', Math.abs(an.raster * 1000 - Math.round(an.raster * 1000)) < 1e-6);
    // Beide Klemmen sind danach frei.
    const sperren = CA.blechSperren(mB);
    const frei = (p2) => !sperren.some((sp) => p2 > sp.von - 1e-9 && p2 < sp.bis + 1e-9);
    wahr('Beide Klemmen liegen danach frei',
         frei(an.x - an.raster / 2) && frei(an.x + an.raster / 2),
         `${(an.x - an.raster / 2).toFixed(3)} / ${(an.x + an.raster / 2).toFixed(3)}`);
    // Wer schon frei sitzt, bleibt unangetastet.
    const ohne = CA.passeTraegerAn(st.x, 0.40, mB);
    wahr('Wer frei sitzt, behaelt Lage und Raster',
         !ohne.geweitet && !ohne.verschoben && ohne.raster === 0.40);
  }

  /*
   * BEIDE KLEMMEN MUESSEN AUF DEM JOCH BLEIBEN.
   *
   * Am wirklichen Querprofil aufgefallen: ein Mass 16 cm vor dem Jochende.
   * Dort laege die geweitete Klemme JENSEITS des Jochs - ein Anschluss an
   * nichts. Die Weitung ist dort keine Abhilfe.
   */
  {
    const nahEnde = mB.L - 0.16;
    const r = CA.freiesRasterAmJoch(nahEnde, 0.40, mB);
    wahr('So nah am Ende wird nicht geweitet', !r.geweitet,
         `${nahEnde.toFixed(2)} m -> Raster ${r.raster}`);
    // Und am Jochanfang ebenso.
    wahr('Am Jochanfang ebensowenig',
         !CA.freiesRasterAmJoch(0.16, 0.40, mB).geweitet);
  }

  // Ohne Bleche gibt es nichts auszuweichen.
  wahr('Ohne Stationsliste bleibt alles, wie es ist',
       CA.freieLageAmJoch(3.3, 0.4, {}).x === 3.3);

  // --- Wer ist ein Traeger? ----------------------------------------------
  {
    const rolle = (id) => FL.getFlBauteil(id).rolle;
    const DA = await import(J('data.anbauteile.js'));
    const hs = DA.getVorlage('hs-nur'), ja = DA.getVorlage('ja-einfach');
    const tr = DA.getVorlage('leiter-traverse'), rl = DA.getVorlage('leiter-rl');
    wahr('Die Haengestuetze ist ein Traeger', CA.hatTraeger(hs.module, rolle));
    wahr('Der Jochaufsatz ebenso', CA.hatTraeger(ja.module, rolle));
    wahr('Die Traverse nicht', !CA.hatTraeger(tr.module, rolle));
    wahr('Der Rueckleiter nicht', !CA.hatTraeger(rl.module, rolle));
    wahr('Ohne Module nichts', !CA.hatTraeger(undefined, rolle));
  }

  // --- Pruefung P8 -------------------------------------------------------
  {
    const st = mB.stationsListe[6];
    const hs = (await import(J('data.anbauteile.js'))).getVorlage('hs-nur');
    const teil = (x) => ({ id: 'HS', name: 'Haengestuetze', vorlage: 'hs-nur',
      x, raster: 0, befestigung: hs.befestigung, aktiv: true,
      module: JSON.parse(JSON.stringify(hs.module)) });
    const bau = (x) => {
      const w = basis({ typ: 'J90', L: 20, anbauteile: [teil(x)] });
      return modell(w, getProfil(w.profOG), getProfil(w.profUG),
                    getStahl(w.stahl), T.getTragjoch('J90'));
    };
    const drauf = chk(bau(st.x)).find((c) => c.id === 'P8');
    wahr('P8 faengt eine Klemme auf dem Blech', drauf && drauf.ok === false,
         drauf?.status);
    wahr('Und nennt Name und Stelle',
         /Haengestuetze|Hängestütze/.test(drauf.status)
         && drauf.status.includes(st.x.toFixed(2)), drauf.status);
    const frei = chk(bau(st.x + 0.30)).find((c) => c.id === 'P8');
    wahr('Daneben ist sie erfuellt', frei.ok === true, frei.status);
    // Ohne Traeger am Joch gibt es nichts zu pruefen - dann steht P8 nicht da.
    const ohne = chk(mB).find((c) => c.id === 'P8');
    wahr('Ohne Traeger steht P8 gar nicht in der Liste', ohne === undefined);
  }

  /*
   * P1 UND DIE BAUTEILE AM MASTEN - ein selbst eingebauter Fehlalarm.
   *
   * P1 prueft, ob die Befestigungspunkte auf dem Joch liegen: x +- raster/2
   * zwischen 0 und L. Mit den Anbauteilen AM MASTEN (dieselbe Sitzung) kam
   * ein Fall dazu, den die Pruefung nicht kannte: ein Teil am Masten wird
   * ueber seine HOEHE angesetzt, sein x steht auf 0 und bedeutet nichts.
   *
   * Ergebnis im laufenden Programm: ein Rueckleiter auf einer Traverse am
   * Mast A meldete "AUSSERHALB: Leiter-Traverse am Joch" - weil die halbe
   * Klemmweite von 0.60 m links von x = 0 zu liegen kam. Das Joch war in
   * Ordnung, die Meldung nicht.
   *
   * P6, P7 und P8 klammern die Masten laengst aus. P1 nicht - bis jetzt.
   */
  {
    const hs = (await import(J('data.anbauteile.js'))).getVorlage('hs-nur');
    const teil = (o) => ({ id: 'X', name: o.name ?? 'Teil', vorlage: 'hs-nur',
      x: o.x ?? 5, raster: o.raster ?? 0.4, ort: o.ort, hMast: o.hMast,
      befestigung: hs.befestigung, aktiv: true,
      module: JSON.parse(JSON.stringify(hs.module)) });
    const p1 = (teile) => {
      const w = basis({ typ: 'J90', L: 20, endbedingung: 'mast',
                        mastProfil: 'HEB 260', mastH: 7.5, anbauteile: teile });
      const m = modell(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch('J90'));
      return chk(m).find((c) => c.id === 'P1');
    };

    // Der gemeldete Fall, nachgestellt: x = 0, raster 0.60, am Mast A.
    const amMast = p1([teil({ name: 'Leiter-Traverse', ort: 'mastA',
                              x: 0, raster: 0.6, hMast: 6 })]);
    wahr('Ein Bauteil am Masten faellt nicht bei P1 durch',
         amMast.ok === true, amMast.status);
    wahr('Und es wird bei P1 gar nicht mitgezaehlt',
         amMast.text.includes('der 0 Anbauteile'), amMast.text);

    // Am Joch gilt die Regel unveraendert.
    wahr('Am Joch bleibt P1 erfuellt', p1([teil({ x: 5 })]).ok === true);
    {
      const raus = p1([teil({ name: 'zu weit rechts', x: 19.9 })]);
      wahr('Ueber das rechte Ende hinaus faellt es durch', raus.ok === false);
      pruef('Und die Zahl zeigt den rechten Rand', raus.vorhanden, 20.1, 1e-9, 'm');
      wahr('Gegen die Jochlaenge', raus.erforderlich === 20 && raus.richtung === '<=');
    }
    /*
     * DIE ZAHL MUSS DIE VERLETZUNG ZEIGEN. Links hinaus stand vorher
     * "10.11 <= 20.00" mit einem Kreuz daneben - der groesste RECHTE Rand,
     * waehrend links etwas fehlte. Die Zeile erklaerte gar nichts.
     */
    {
      const links = p1([teil({ name: 'zu weit links', x: 0.1 }), teil({ x: 10 })]);
      wahr('Links hinaus faellt es durch', links.ok === false, links.status);
      pruef('Und die Zahl zeigt den linken Rand', links.vorhanden, -0.1, 1e-9, 'm');
      wahr('Gegen null', links.erforderlich === 0 && links.richtung === '>=');
      wahr('Der Name steht in der Meldung', links.status.includes('zu weit links'),
           links.status);
    }
    // Ohne Anbauteile gibt es nichts zu pruefen - und keinen Fehlalarm.
    wahr('Ohne Anbauteile ist P1 erfuellt', p1([]).ok === true);
  }
}

titel('40  Masten und Joch in der Zeichnung erkennen');

/*
 * WEISUNG DES AUFTRAGGEBERS, 27. August: eine automatische Erkennung von
 * Masten und Jochen, und die Zeichnung danach selbst ausrichten.
 *
 * SIE SCHLAEGT VOR, SIE ENTSCHEIDET NICHT. Eine Zeichnung ist kein Datensatz:
 * was darauf steht, steht dort fuer einen Menschen. Jede Erkennung ist eine
 * Vermutung, und eine Vermutung, die sich als Messung ausgibt, waere
 * schlimmer als gar keine. Das Ergebnis traegt sein Zutrauen bei sich, und
 * die zwei Klicks bleiben erreichbar.
 *
 * GEPRUEFT WIRD AUF NACHGEBAUTEN BLAETTERN. Ein Bild braucht einen Browser;
 * die Geometrie nicht. Die Erkennung rechnet deshalb auf einer MASKE, und
 * die laesst sich hier Pixel fuer Pixel hinlegen - mit allem, was auf einem
 * Querprofil sonst noch steht und die Sache stoeren koennte.
 */
{
  const EK = await import(J('bild.erkennung.js'));

  /** Ein nachgebautes Querprofil: Blatt, Masskette, Joch, Masten, Gleise. */
  const blatt = (o = {}) => {
    const B = o.breite ?? 1200, H = o.hoehe ?? 800;
    const m = new Uint8Array(B * H);
    const setz = (x, y) => { if (x >= 0 && x < B && y >= 0 && y < H) m[y * B + x] = 1; };
    const waag = (y, x0, x1, d = 1) => {
      for (let x = x0; x <= x1; x++) for (let k = 0; k < d; k++) setz(x, y + k);
    };
    const senk = (x, y0, y1, d = 1) => {
      for (let y = y0; y <= y1; y++) for (let k = 0; k < d; k++) setz(x + k, y);
    };
    // Der Blattrahmen - er laeuft ueber die ganze Hoehe und Breite und ist
    // damit der gefaehrlichste Mitbewerber, fuer den Masten wie fuer das Joch.
    if (o.rahmen !== false) {
      waag(6, 6, B - 7); waag(H - 7, 6, B - 7);
      senk(6, 6, H - 7); senk(B - 7, 6, H - 7);
    }
    // Masskette: eine lange duenne Waagrechte mit Teilstrichen, ueber dem Joch.
    if (o.kette !== false) {
      waag(70, 200, 1000);
      [200, 260, 420, 560, 700, 830, 940, 1000].forEach((x) => senk(x, 62, 78));
    }
    // Das Joch: zwei Gurte mit Fuellstaeben dazwischen.
    const jochOben = o.jochOben ?? 180, jochUnten = o.jochUnten ?? 194;
    const xL = o.xL ?? 200, xR = o.xR ?? 1000;
    waag(jochOben, xL, xR, 3); waag(jochUnten, xL, xR, 3);
    for (let x = xL; x <= xR; x += 40) senk(x, jochOben, jochUnten + 3, 2);
    /*
     * Zwei Masten, verschieden lang - das ist der Normalfall. Sie koennen
     * aber UEBER das Joch hinauslaufen (`ueberstand`): oben traegt dann jeder
     * eine Traverse mit einem Einzelleiter. Das ist kein Sonderfall, es steht
     * so auf den Blaettern - und es hat die erste Fassung der Erkennung zu
     * Fall gebracht, die den Mastkopf fuer die Jochachse hielt.
     */
    const ue = o.ueberstand ?? 0;
    senk(xL, jochOben - 2 - ue, o.fussL ?? 640, 6);
    senk(xR, jochOben - 2 - ue, o.fussR ?? 610, 5);
    if (ue > 0) {
      waag(jochOben - ue + 6, xL, xL + 70, 3);
      waag(jochOben - ue + 4, xR - 70, xR, 3);
    }
    // Eine Masskette kann auch ZWISCHEN Mastkopf und Joch stehen. Dann hilft
    // kein Fenster mehr - nur noch, dass ein Joch mehr Tinte traegt.
    if (o.ketteTief) {
      const y = jochOben - Math.round(ue / 2);
      waag(y, xL, xR);
      [xL, 380, 520, 660, 800, xR].forEach((x) => senk(x, y - 8, y + 8));
    }
    // Lichtraumprofile: grosse Kaesten, deren Seiten senkrecht sind.
    for (let i = 0; i < 3; i++) {
      const x0 = 300 + i * 220, x1 = x0 + 170, y0 = 300, y1 = 560;
      waag(y0, x0, x1); waag(y1, x0, x1); senk(x0, y0, y1); senk(x1, y0, y1);
    }
    // Terrainlinie, strichpunktiert, und das Schriftfeld.
    for (let x = 60; x < B - 60; x += 12) waag(600, x, x + 7);
    waag(700, 60, B - 60); waag(760, 60, B - 60);
    return { m, B, H, xL, xR, achse: (jochOben + jochUnten + 3) / 2 };
  };

  // --- Der Normalfall ----------------------------------------------------
  {
    const b = blatt();
    const r = EK.erkenneTragwerk(b.m, b.B, b.H);
    wahr('Das Tragwerk wird gefunden', !!r);
    pruef('Der linke Mast sitzt auf seiner Achse', r.p1.px, b.xL + 2.5, 0.6, 'Punkte');
    pruef('Der rechte ebenso', r.p2.px, b.xR + 2, 0.6, 'Punkte');
    // Die Achse liegt ZWISCHEN den Gurten, nicht auf einem davon.
    pruef('Die Jochachse liegt zwischen den Gurten', r.p1.py, b.achse, 0.02, 'Punkte');
    wahr('Und beide Punkte auf derselben Hoehe', r.p1.py === r.p2.py);
    wahr('Mit vollem Zutrauen', r.guete > 0.9, r.guete.toFixed(2));
  }

  /*
   * DER BLATTRAHMEN IST KEIN MAST - und keine Jochachse.
   *
   * Er laeuft ueber die ganze Blatthoehe und schlaegt jeden Masten an Laenge;
   * seine obere Kante laeuft ueber die ganze Breite und schlaegt jeden Gurt
   * an Tinte. Beides ist gemessen worden, und beides ging zuerst schief:
   * die Erkennung fand die Blattkante statt des Jochs.
   *
   * Zwei Regeln halten ihn draussen: der aeusserste Rand zaehlt nicht mit,
   * und das Joch wird am MASTKOPF gesucht statt auf dem ganzen Blatt.
   */
  {
    const mit = EK.erkenneTragwerk(...(() => { const b = blatt(); return [b.m, b.B, b.H]; })());
    const b2 = blatt({ rahmen: false });
    const ohne = EK.erkenneTragwerk(b2.m, b2.B, b2.H);
    wahr('Mit Rahmen und ohne dasselbe Ergebnis',
         Math.abs(mit.p1.px - ohne.p1.px) < 0.01
         && Math.abs(mit.p1.py - ohne.p1.py) < 0.01,
         `${mit.p1.px}/${mit.p1.py} gegen ${ohne.p1.px}/${ohne.p1.py}`);
    pruef('Und die Achse trifft die Jochmitte', ohne.p1.py, b2.achse, 0.02, 'Punkte');
  }

  // Die Masskette liegt darueber und ist ebenfalls eine lange Waagrechte -
  // sie darf die Jochachse nicht an sich ziehen.
  {
    const b = blatt(), o = blatt({ kette: false });
    const rm = EK.erkenneTragwerk(b.m, b.B, b.H);
    const ro = EK.erkenneTragwerk(o.m, o.B, o.H);
    wahr('Die Masskette zieht die Achse nicht an sich',
         Math.abs(rm.p1.py - ro.p1.py) < 0.01, `${rm.p1.py} gegen ${ro.p1.py}`);
  }

  /*
   * DER MAST LAEUFT UEBER DAS JOCH HINAUS.
   *
   * Gemessen an einem Querprofil J70 E / 15 m auf DP26 und DPM24: beide
   * Masten ragen ueber das Joch und tragen oben je eine Traverse mit einem
   * 95Cu. Die erste Fassung ankerte am MASTKOPF - und fand die Traverse:
   * Jochachse 103 statt 282, Zutrauen 0.10. Sie hat den Vorschlag damit
   * immerhin verworfen statt ihn zu behaupten, geholfen hat sie nicht.
   *
   * Der Anker ist jetzt die ganze Mastlaenge, und gewaehlt wird das
   * tintenreichste durchlaufende Band darin.
   */
  {
    const b = blatt({ ueberstand: 190 });
    const r = EK.erkenneTragwerk(b.m, b.B, b.H);
    wahr('Ein Mast darf ueber das Joch hinausragen', !!r);
    pruef('Die Traverse ist nicht die Jochachse', r.p1.py, b.achse, 0.5, 'Punkte');
    wahr('Und das Zutrauen bleibt voll', r.guete > 0.9, r.guete.toFixed(2));
  }

  /*
   * DIE MASSKETTE ZWISCHEN MASTKOPF UND JOCH.
   *
   * Steht sie dort, liegt sie MITTEN im Suchbereich, und sie fuellt den
   * Streifen so ganz wie ein Gurt. Dass sie trotzdem verliert, liegt allein
   * am Band: ein Joch sind zwei Gurte mit Fuellstaeben, eine Masskette ist
   * ein Strich.
   */
  {
    const o = blatt({ ueberstand: 190 });
    const k = blatt({ ueberstand: 190, ketteTief: true });
    const ro = EK.erkenneTragwerk(o.m, o.B, o.H);
    const rk = EK.erkenneTragwerk(k.m, k.B, k.H);
    wahr('Eine Masskette im Suchbereich zieht die Achse nicht an sich',
         Math.abs(rk.p1.py - ro.p1.py) < 0.01, `${rk.p1.py} gegen ${ro.p1.py}`);
  }

  // --- Was NICHT erkannt werden darf --------------------------------------
  {
    const leer = new Uint8Array(400 * 300);
    wahr('Ein leeres Blatt ergibt nichts',
         EK.erkenneTragwerk(leer, 400, 300) === null);
    // Nur ein Mast: kein Joch.
    const eins = new Uint8Array(400 * 300);
    for (let y = 40; y < 260; y++) for (let d = 0; d < 4; d++) eins[y * 400 + 200 + d] = 1;
    wahr('Ein einzelner Mast ergibt nichts',
         EK.erkenneTragwerk(eins, 400, 300) === null);
    // Zwei Masten zu nah beieinander: das waere kein Joch.
    const nah = new Uint8Array(400 * 300);
    [200, 230].forEach((x) => {
      for (let y = 40; y < 260; y++) for (let d = 0; d < 4; d++) nah[y * 400 + x + d] = 1;
    });
    wahr('Zwei Masten dicht nebeneinander ebenso',
         EK.erkenneTragwerk(nah, 400, 300) === null);
  }

  /*
   * DAS ZUTRAUEN MUSS SINKEN, wenn die Sache nicht eindeutig ist.
   *
   * Steht ein dritter, ebenso langer senkrechter Strich auf dem Blatt - ein
   * Signalmast, ein Kandelaber, ein angeschnittenes Nachbartragwerk -, dann
   * ist nicht mehr klar, welche zwei gemeint sind. Genau dann soll die
   * Erkennung nicht behaupten, sie wisse es.
   */
  {
    const b = blatt();
    const r1 = EK.erkenneTragwerk(b.m, b.B, b.H);
    const d = blatt();
    for (let y = 178; y < 640; y++) {
      for (let k = 0; k < 6; k++) d.m[y * d.B + 600 + k] = 1;
    }
    const r2 = EK.erkenneTragwerk(d.m, d.B, d.H);
    wahr('Ein dritter langer Strich senkt das Zutrauen',
         r2 && r2.guete < r1.guete, `${r1.guete.toFixed(2)} -> ${r2?.guete.toFixed(2)}`);
  }

  // --- Rot ist dunkel -----------------------------------------------------
  /*
   * Auf einem Querprofil ist das NEUE rot gezeichnet - und der Mast, den man
   * sucht, ist oft genau das. Reines Rot hat eine wahrgenommene Helligkeit
   * von 76: deutlich unter der Schwelle, obwohl sein Rotkanal voll
   * ausgesteuert ist. Wer nur den Rotkanal prueft, saehe es als hell.
   */
  {
    const px = (r, g, bl, a = 255) => [r, g, bl, a];
    const daten = new Uint8ClampedArray([
      ...px(0, 0, 0), ...px(255, 0, 0), ...px(255, 255, 255),
      ...px(200, 200, 200), ...px(0, 0, 255), ...px(255, 255, 255, 0),
    ]);
    const maske = EK.maskeAusBild(daten, 6, 1);
    wahr('Schwarz ist dunkel', maske[0] === 1);
    wahr('Rot auch', maske[1] === 1);
    wahr('Weiss nicht', maske[2] === 0);
    wahr('Helles Grau nicht', maske[3] === 0);
    wahr('Blau schon', maske[4] === 1);
    wahr('Durchsichtiges gilt als hell', maske[5] === 0);
  }
}

titel('41  Welche Nachweise gefuehrt werden');

/*
 * WEISUNG DES AUFTRAGGEBERS, 27. August: waehlen koennen, welche Nachweise
 * gefuehrt werden - Jochtragwerk, Auflager Joch, Knicken Joch, Mast.
 *
 * BEIM NACHSEHEN KAM EIN BEFUND HERAUS, DER DIE AUFGABE VERAENDERT HAT:
 * von den vier genannten gibt es zwei gar nicht. core.vierendeel.js sagt es
 * seit jeher selbst - "KEIN Knicknachweis, bewusst nicht enthalten" -, und
 * ein Mastnachweis existiert ebenso wenig; der Mast ist eine Drehfeder und
 * seit kurzem Geometrie in der Ausleitung.
 *
 * Entschieden hat der Auftraggeber: beide erscheinen, unschaltbar, als NICHT
 * GEFUEHRT. Und ein abgeschalteter Nachweis wird nicht gefuehrt und nie als
 * erfuellt gezaehlt.
 *
 * >>> DAS IST DIE EIGENTLICHE GEFAHR AN DIESER WEISUNG. <<<
 * Ein abgeschalteter Nachweis, der einfach aus der Liste faellt, sieht aus
 * wie ein bestandener. Die Kontrollen unten halten genau das fest.
 */
{
  const CH = await import(J('core.checks.js'));

  // --- Die Gruppen -------------------------------------------------------
  {
    const g = CH.NACHWEISGRUPPEN.map((x) => x.key);
    /*
     * SECHS SEIT DEM 15. SEPTEMBER: erst wurde das Knicken des Masten eine
     * eigene Gruppe, damit es sich abschalten laesst, ohne den
     * Querschnittsnachweis mitzunehmen - dann die Torsion, aus demselben
     * Grund und mit derselben Begruendung: der Ansatz rechnet einen
     * freistehenden Kragarm, und die Leiter halten den Kopf.
     */
    wahr('Sechs Gruppen, in der Reihenfolge der Weisungen',
         g.join(',') === 'jochtragwerk,auflagerJoch,knickenJoch,mast,'
                       + 'knickenMast,torsionMast',
         g.join(','));
    const da = CH.NACHWEISGRUPPEN.filter((x) => x.vorhanden).map((x) => x.key);
    wahr('Fuenf davon gibt es',
         da.join(',') === 'jochtragwerk,auflagerJoch,mast,knickenMast,'
                        + 'torsionMast',
         da.join(','));
    wahr('Knicken ist nicht enthalten',
         CH.NACHWEISGRUPPEN.find((x) => x.key === 'knickenJoch').vorhanden === false);
    // Der Mast seit dem 28. August schon - und sein `was` sagt, was FEHLT.
    wahr('Der Mast ist enthalten',
         CH.NACHWEISGRUPPEN.find((x) => x.key === 'mast').vorhanden === true);
    /*
     * SEIT DEM 2. SEPTEMBER MIT STABILITAET - UND SEIT DEM 15. SEPTEMBER
     * ALS EIGENE GRUPPE.
     *
     * Weisung: "das knicken des masten deaktivierbar machen. der nachweis
     * ist zu konservativ, da die Leiter (Rueckleiter an Mast und die
     * Kettenwerke am Joch) den Masten stabilisieren und somit sich ein
     * andere Lk und Moment einstellt."
     *
     * Abschaltbar ist, was eine eigene Gruppe ist: der Schalter der Gruppe
     * `mast` wuerde den Querschnitt mitnehmen, und der bleibt zu fuehren.
     */
    const grp = (k) => CH.NACHWEISGRUPPEN.find((x) => x.key === k);
    wahr('Das Knicken des Masten ist eine eigene Gruppe',
         grp('knickenMast')?.vorhanden === true);
    wahr('\u2026 und voreingestellt gefuehrt - der strengere Fall',
         grp('knickenMast')?.standard === true);
    wahr('\u2026 der Mast selbst nennt es nicht mehr',
         !/Biegeknicken/.test(grp('mast').was));
    wahr('\u2026 dafuer die eigene Gruppe',
         /Biegeknicken/.test(grp('knickenMast').was));
    wahr('\u2026 und das Biegedrillknicken ausdruecklich nicht',
         /Biegedrillknicken bleibt in beiden F\u00e4llen aussen vor/
           .test(grp('knickenMast').was));
    /*
     * DER GRUND STEHT DABEI. Ein Schalter, dessen Begruendung nur im
     * Sitzungsprotokoll steht, wird beim naechsten Mal falsch gestellt.
     */
    wahr('\u2026 und der Grund, warum man ihn ausschaltet',
         /R\u00fcckleiter/.test(grp('knickenMast').was)
         && /Kettenwerke/.test(grp('knickenMast').was));
    wahr('Das Auflager ist vorhanden, aber nicht voreingestellt',
         CH.NACHWEISGRUPPEN.find((g) => g.key === 'auflagerJoch').vorhanden === true);
  }

  /*
   * WAS ES NICHT GIBT, WIRD NICHT GEFUEHRT - auch wenn es in einer alten
   * Datei auf true steht. Eine Ablage aus einer spaeteren Fassung, in der es
   * den Knicknachweis gaebe, darf hier nicht behaupten, er sei gefuehrt.
   */
  {
    const a = CH.nachweiseAuswahl({ knickenJoch: true });
    wahr('Ein gespeichertes true macht keinen Nachweis',
         a.knickenJoch === false, JSON.stringify(a));
    wahr('Ohne Angabe gilt die Voreinstellung der Gruppe',
         CH.nachweiseAuswahl(undefined).jochtragwerk === true
         && CH.nachweiseAuswahl(undefined).auflagerJoch === false);
    wahr('Ausgeschaltet bleibt ausgeschaltet',
         CH.nachweiseAuswahl({ jochtragwerk: false }).jochtragwerk === false);
    // Wer ihn einschaltet, bekommt ihn - die Voreinstellung ist keine Sperre.
    wahr('Eingeschaltet wird er gefuehrt',
         CH.nachweiseAuswahl({ auflagerJoch: true }).auflagerJoch === true);
  }

  // --- Welche Pruefung zu welcher Gruppe gehoert -------------------------
  {
    const gv = (id) => CH.gruppeVon({ id });
    wahr('Q1 gehoert zum Jochtragwerk', gv('Q1') === 'jochtragwerk');
    wahr('Q12 auch', gv('Q12') === 'jochtragwerk');
    wahr('A1 zum Auflager', gv('A1') === 'auflagerJoch');
    // Die Plausibilitaetspruefungen sind Konstruktionsregeln, keine
    // Tragsicherheit - sie gehoeren zu keiner Gruppe und bleiben immer.
    ['P1', 'P2', 'P3', 'P6', 'P7', 'P8'].forEach((id) =>
      wahr(`${id} gehoert zu keiner Gruppe`, gv(id) === null));
  }

  // --- Abschalten laesst die Pruefungen verschwinden ---------------------
  {
    const mach = (nw) => {
      const w = basis({ typ: 'J90', L: 20, endbedingung: 'mast',
                        mastProfil: 'HEB 260', mastH: 7.5, schraubenFgrenz: 24,
                        nachweise: nw });
      const m = modell(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch('J90'));
      return CH.konstruktionsChecks(m);
    };
    const alle = mach(undefined);
    const zaehl = (cs, re) => cs.filter((c) => re.test(c.id)).length;
    wahr('Voreingestellt stehen Querschnittspruefungen da', zaehl(alle, /^Q\d+$/) > 0,
         `${zaehl(alle, /^Q\d+$/)} Stueck`);
    wahr('Der Gurtanschluss A1 aber nicht - er ist ab Werk aus',
         zaehl(alle, /^A1$/) === 0);
    wahr('Eingeschaltet steht er da',
         zaehl(mach({ auflagerJoch: true }), /^A1$/) === 1);

    const ohneJoch = mach({ jochtragwerk: false, auflagerJoch: true });
    wahr('Ohne Jochtragwerk keine Querschnittspruefung', zaehl(ohneJoch, /^Q\d+$/) === 0);
    wahr('A1 steht trotzdem noch da', zaehl(ohneJoch, /^A1$/) === 1);
    wahr('Und die Plausibilitaet bleibt', zaehl(ohneJoch, /^P\d+$/) > 0);

    const ohneAufl = mach({ auflagerJoch: false });
    // (Dasselbe wie die Voreinstellung - hier ausdruecklich geschrieben.)
    wahr('Ohne Auflager kein A1', zaehl(ohneAufl, /^A1$/) === 0);
    wahr('Die Querschnitte bleiben', zaehl(ohneAufl, /^Q\d+$/) > 0);
  }

  // --- Das Urteil verschweigt nichts -------------------------------------
  {
    const u = (nw, checks = []) => CH.urteilKonstruktion(checks, nw);
    const std = u(undefined);
    // Seit dem 28. August ist der Mast dabei; nicht gefuehrt bleiben das
    // Auflager (ausgeschaltet) und das Knicken (nicht enthalten).
    wahr('Voreingestellt sind ZWEI Nachweise nicht gefuehrt',
         std.nichtGefuehrt.length === 2,
         std.nichtGefuehrt.map((g) => `${g.titel} (${g.grund})`).join(', '));
    /*
     * DER GRUND MUSS STIMMEN. «Abgewaehlt» stand hier zuerst - es behauptet,
     * der Benutzer habe entschieden. Beim Auflagernachweis stimmt das nicht:
     * der ist ab Werk aus. «Ausgeschaltet» sagt, was der Fall ist, ohne zu
     * sagen, wer es war.
     */
    wahr('Das Auflager ist ausgeschaltet, nicht fehlend',
         std.nichtGefuehrt.find((g) => g.key === 'auflagerJoch').grund === 'ausgeschaltet');
    wahr('Knicken ist nicht enthalten',
         std.nichtGefuehrt.filter((g) => g.grund === 'nicht enthalten')
           .map((g) => g.key).join(',') === 'knickenJoch');
    wahr('Der Mast steht nicht mehr darunter',
         !std.nichtGefuehrt.some((g) => g.key === 'mast'));
    wahr('Das Jochtragwerk gilt als gefuehrt', std.tragwerkGefuehrt === true);

    const ab = u({ jochtragwerk: false });
    wahr('Ausgeschaltet wird als solches genannt',
         ab.nichtGefuehrt.find((g) => g.key === 'jochtragwerk')?.grund === 'ausgeschaltet');
    wahr('Und das Urteil weiss, dass eta keines mehr ist',
         ab.tragwerkGefuehrt === false);
    wahr('Dann sind es drei - der Mast bleibt gefuehrt',
         ab.nichtGefuehrt.length === 3,
         ab.nichtGefuehrt.map((g) => g.key).join(','));

    /*
     * DER GEFAEHRLICHE FALL, ausgeschrieben.
     *
     * Eine VERLETZTE Pruefung, deren Gruppe abgeschaltet wird: sie faellt aus
     * der Liste, und alleOk steht auf true. Das ist fuer sich richtig - die
     * Liste sagt ueber das, was gefuehrt wurde, die Wahrheit. Allein waere es
     * gefaehrlich. Deshalb MUSS nichtGefuehrt die Gruppe nennen.
     */
    const kaputt = [{ id: 'A1', ok: false, text: 'Gurtanschluss' }];
    const mitA1 = u(undefined, kaputt);
    wahr('Gefuehrt und verletzt: das Urteil faellt', mitA1.alleOk === false);
    const ohneA1 = u({ auflagerJoch: false }, []);
    wahr('Abgeschaltet: die Liste ist sauber', ohneA1.alleOk === true);
    wahr('ABER die Gruppe steht als nicht gefuehrt da',
         ohneA1.nichtGefuehrt.some((g) => g.key === 'auflagerJoch'
                                       && g.grund === 'ausgeschaltet'));
  }


  /*
   * WELCHE VERLETZUNG DAS URTEIL ROT FAERBT.
   *
   * Weisung des Auftraggebers, 28. August: "hier sollte alles gruen sein, die
   * verletzung ist nicht so relevant". Vorher machte JEDE verletzte Pruefung
   * das Urteil rot - eine Klemme zehn Zentimeter neben ihrem Platz sah aus
   * wie ein ueberschrittener Nachweis. Wer das ein paarmal sieht, liest die
   * Farbe nicht mehr.
   *
   * Rot bleibt: eta > 1, und eine Verletzung, die ETA SELBST hinfaellig
   * macht. Das ist genau eine - die Querschnittsklasse. Klasse 4 heisst, der
   * Querschnitt beult vor dem Fliessen; dann darf gar nicht elastisch
   * gerechnet werden, und ein gruenes Urteil daneben waere die eine Zeile,
   * die wirklich in die Irre fuehrt.
   */
  {
    const u = (checks) => CH.urteilKonstruktion(checks, { auflagerJoch: true });
    // Eine Konstruktionsregel: gemeldet, aber nicht bindend.
    const weich = u([{ id: 'P8', ok: false, text: 'Klemme auf einem Blech' }]);
    wahr('Eine verletzte Konstruktionsregel steht im Urteil',
         weich.alleOk === false && weich.anzahlVerletzt === 1);
    wahr('Aber sie faerbt es nicht rot', weich.bindendVerletzt === false);

    // Die Querschnittsklasse: bindend.
    const hart = u([{ id: 'Q1', ok: false, text: 'Klasse 4', urteilBindend: true }]);
    wahr('Eine verletzte Querschnittsklasse schon',
         hart.bindendVerletzt === true);

    // Beides zusammen: die bindende gewinnt.
    const beides = u([{ id: 'P8', ok: false, text: 'weich' },
                      { id: 'Q1', ok: false, text: 'hart', urteilBindend: true }]);
    wahr('Zusammen entscheidet die bindende', beides.bindendVerletzt === true);
    pruef('Und gezaehlt werden trotzdem beide', beides.anzahlVerletzt, 2, 1e-12, 'Stk');

    // Erfuellte Pruefungen faerben nichts.
    wahr('Ohne Verletzung ist nichts bindend',
         u([{ id: 'Q1', ok: true, urteilBindend: true }]).bindendVerletzt === false);
  }

  /*
   * UND DIE KLASSE TRAEGT DIE MARKE WIRKLICH. Ohne sie waere die Trennung
   * oben eine Verabredung ohne Gegenstueck: die Q-Pruefungen kommen aus
   * konstruktionsChecks, nicht aus dem Pruefstand.
   */
  {
    const w = basis({ typ: 'J90', L: 20 });
    const mm = modell(w, getProfil(w.profOG), getProfil(w.profUG),
                      getStahl(w.stahl), T.getTragjoch('J90'));
    const cs = CH.konstruktionsChecks(mm);
    const qs = cs.filter((c) => /^Q\d+$/.test(c.id));
    wahr('Jede Querschnittspruefung ist bindend',
         qs.length > 0 && qs.every((c) => c.urteilBindend === true),
         `${qs.length} Stueck`);
    const ps = cs.filter((c) => /^P\d+$/.test(c.id));
    wahr('Keine Konstruktionsregel ist es',
         ps.length > 0 && ps.every((c) => c.urteilBindend !== true),
         ps.map((c) => c.id).join(', '));
  }

  // --- Der Reiter im Optionen-Dialog -------------------------------------
  {
    const SCH = await import(J('ui.schema.js'));
    const themen = SCH.optionenThemen(basis()).map((t) => t.key);
    wahr('Der Optionen-Dialog hat einen Reiter Nachweise',
         themen.includes('nachweise'), themen.join(', '));
    wahr('Und die Nachweise stehen in keinem Feld-Abschnitt',
         SCH.optionenFelder(basis(), 'nachweise').length === 0);
    wahr('Die Voreinstellung steht in den Standardwerten',
         standardwerte().nachweise?.jochtragwerk === true
         && standardwerte().nachweise?.auflagerJoch === false);
  }
}

titel('42  Der lange Mast mit Zusatzleitern');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August: "die masten immer einen halben meter
 * ueber den obergurt fuehren" und "ausserdem ist ein langer masten mit
 * zusatzleitern wie im beispiel, dann sollte man dies eingeben koennen".
 *
 * Das Beispiel ist das dritte Querprofil: J70 E / 15 m auf DP26 und DPM24,
 * beide 12.5 m lang, Anschlusshoehe ha = 8.31 m. Die Masten ragen also gut
 * vier Meter ueber das Joch und tragen dort je eine Traverse mit einem 95Cu.
 *
 * Auf dem Blatt steht beides: die GESAMTLAENGE und die Anschlusshoehe.
 * Gefragt wird deshalb nach der Laenge - so steht es dort -, der Ueberstand
 * ergibt sich als Laenge minus H.
 *
 * >>> DIE LAENGE DARF DIE DREHFEDER NICHT ANFASSEN. <<<
 * In die Feder geht H ein, Fuss bis Jochachse: das ist die Laenge, ueber die
 * sich der Mast unter dem Anschluss verbiegt. Was darueber hinausragt, ist
 * ein Kragarm mit eigenen Lasten und macht die Einspannung des Jochs nicht
 * weicher. Ginge die Gesamtlaenge in c_phi ein, waere jedes Joch mit langem
 * Masten still weicher gerechnet.
 */
{
  const AU = await import(J('core.auflager.js'));
  const R = await import(J('render.3d.js'));
  const AX = await import(J('export.axisvm.js'));

  const ein = (extra) => ({ ...standardwerte(), typ: 'J90', L: 20,
                            endbedingung: 'mast', mastProfil: 'HEB 260',
                            mastH: 8.31, ...extra });

  // --- Laenge und Ueberstand ---------------------------------------------
  {
    const ohne = AU.mastSteifigkeit(ein({}), 'A');
    const lang = AU.mastSteifigkeit(ein({ mastLaenge: 12.5 }), 'A');
    /*
     * >>> OHNE ANGABE STEHT DER MAST 0.50 M UEBER. <<<
     *
     * Weisung vom 5. September: «das feld Mastlaenge mit der Anschlusshoehe
     * koppeln, die Mastlaenge als voreinstellwert 0.5m laenger auf
     * anschlusshoehe bezogen.»
     *
     * Hier stand «Ueberstand null». Das galt fuer das MODELL - im BILD
     * stand daneben eine andere Regel (mindestens 0.50 m ueber die Oberkante
     * des Obergurts), und beide wussten nichts voneinander.
     */
    /*
     * H = 8.31 m, jd = 500 mm: die Oberkante des Obergurts liegt 0.25 m
     * ueber der Jochachse, der Mindestueberstand 0.50 m darueber - also
     * 9.06 m, aufgerundet auf das Halbmeterraster 9.50 m.
     */
    pruef('Die Vorgabe zaehlt ab Oberkante Obergurt',
          AU.mastLaengeVorgabe(8.31, 500), 9.5, 1e-9, 'm');
    pruef('Ohne jd bleibt es die Jochachse',
          AU.mastLaengeVorgabe(8.31, 0), 9.0, 1e-9, 'm');
    pruef('Sie liegt immer auf dem Halbmeterraster',
          AU.mastLaengeVorgabe(9.0, 600) % AU.MAST_RASTER, 0, 1e-12, 'm');
    wahr('Und nie unter dem Mindestueberstand',
         AU.mastLaengeVorgabe(9.0, 600) >= 9.0 + 0.3 + 0.5 - 1e-9);
    pruef('Ohne Angabe folgt die Laenge daraus', ohne.laenge,
          AU.mastLaengeVorgabe(8.31, ein({}).jd), 1e-9, 'm');
    pruef('Mit 12.5 m Laenge ueber 8.31 m Hoehe', lang.ueberstand, 12.5 - 8.31,
          1e-9, 'm');
    pruef('Die Laenge steht am Modell', lang.laenge, 12.5, 1e-12, 'm');

    // DIE PRUEFUNG, DIE ZAEHLT.
    pruef('Die Drehfeder bleibt dieselbe', lang.cPhi, ohne.cPhi, 1e-12, 'kNm/rad');
    pruef('Und H bleibt Fuss bis Jochachse', lang.H, 8.31, 1e-12, 'm');
    // Eine Laenge KUERZER als H waere ein Tippfehler - kein negativer Ueberstand.
    pruef('Eine zu kurze Laenge ergibt keinen negativen Ueberstand',
          AU.mastSteifigkeit(ein({ mastLaenge: 5 }), 'A').ueberstand, 0, 1e-12, 'm');
  }

  /*
   * AM ENDE B GILT DIE EIGENE ANGABE - aber PROFIL, LAENGE und HOEHE
   * folgen seit dem 2. September ZWEI Schaltern, nicht mehr einem.
   *
   * `mastZwei`  = der MAST am Ende B ist ein anderer (Profil, Laenge, Steg)
   * `mastHZwei` = das Joch schliesst dort ANDERS HOCH an
   *
   * Getrennt, weil `mastenProjizieren` den ersten schon setzt, wenn sich
   * bloss die Profile unterscheiden - und dann waere `mastHB` mit seinem
   * Standardwert 7.50 m still in die Drehfeder geraten. Ausfuehrlich in
   * core.constants.js, anschlusshoehe().
   */
  {
    const w = ein({ mastLaenge: 12.5, mastZwei: true, mastHZwei: true,
                    mastHB: 9.0, mastLaengeB: 14.0, mastProfilB: 'HEB 240' });
    pruef('Ende B traegt seine eigene Laenge',
          AU.mastSteifigkeit(w, 'B').ueberstand, 14.0 - 9.0, 1e-9, 'm');
    pruef('Ende A bleibt davon unberuehrt',
          AU.mastSteifigkeit(w, 'A').ueberstand, 12.5 - 8.31, 1e-9, 'm');

    // DIE PRUEFUNG, DIE DEN GRUND DER TRENNUNG FESTHAELT.
    const nurMast = ein({ mastLaenge: 12.5, mastZwei: true, mastHZwei: false,
                          mastHB: 9.0, mastLaengeB: 14.0,
                          mastProfilB: 'HEB 240' });
    pruef('Ein anderes Profil allein verschiebt die Anschlusshoehe nicht',
          AU.mastSteifigkeit(nurMast, 'B').H, 8.31, 1e-12, 'm');
    pruef('… das Profil gilt trotzdem',
          AU.mastSteifigkeit(nurMast, 'B').laenge, 14.0, 1e-12, 'm');

    // ALTE DATEIEN KENNEN DEN NEUEN SCHALTER NICHT - dann gilt der alte.
    const alt = ein({ mastLaenge: 12.5, mastZwei: true, mastHB: 9.0,
                      mastLaengeB: 14.0, mastProfilB: 'HEB 240' });
    delete alt.mastHZwei;
    pruef('Ohne den neuen Schalter gilt der alte', AU.mastSteifigkeit(alt, 'B').H,
          9.0, 1e-12, 'm');
  }

  // --- Im Bild ------------------------------------------------------------
  {
    const bauen = (extra) => {
      const w = ein(extra);
      const erg = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                           getStahl(w.stahl), T.getTragjoch(w.typ));
      return { w, erg, sz: R.erzeugeSzene(erg.modell, erg) };
    };
    const kopfVon = (sz) => {
      const f = sz.flaechen.filter((x) => x.teil === 'MAST_A');
      return Math.max(...f.flatMap((x) => x.punkte.map((p) => p[2])));
    };
    const fussVon = (sz) => {
      const f = sz.flaechen.filter((x) => x.teil === 'MAST_A');
      return Math.min(...f.flatMap((x) => x.punkte.map((p) => p[2])));
    };
    const kurz = bauen({});
    const lang = bauen({ mastLaenge: 12.5 });
    // Ohne Angabe: der halbe Meter ueber dem Obergurt, mehr nicht.
    const zOG = Math.max(...kurz.sz.flaechen.filter((f) => f.gruppe === 'profil')
      .flatMap((f) => f.punkte.map((p) => p[2])));
    wahr('Ohne Laengenangabe endet er ueber dem Obergurt',
         kopfVon(kurz.sz) >= zOG + 0.5 - 1e-9,
         `${(kopfVon(kurz.sz) - zOG).toFixed(3)} m`);
    // Mit Angabe: der Fuss bleibt, der Kopf steigt.
    pruef('Der Fuss bleibt, wo er war', fussVon(lang.sz), fussVon(kurz.sz), 1e-9, 'm');
    pruef('Der Koerper misst die ganze Laenge',
          kopfVon(lang.sz) - fussVon(lang.sz), 12.5, 1e-9, 'm');
    wahr('Er ragt also weit ueber das Joch',
         kopfVon(lang.sz) > zOG + 3, `${(kopfVon(lang.sz) - zOG).toFixed(2)} m ueber dem Obergurt`);
    // Und das Bild reicht bis dorthin.
    wahr('Die Bildgrenzen reichen bis zum Kopf',
         lang.sz.grenzen.zMax >= kopfVon(lang.sz) - 1e-9,
         `zMax = ${lang.sz.grenzen.zMax.toFixed(2)} m`);

    /*
     * DIE VERMASSUNG (Weisung): "die vermassung des jochs nach unten nehmen
     * ca. um 4m und noch die masten vermassen (joch unterkante)".
     *
     * Das Mastmass laeuft von der Joch UNTERKANTE zum Fuss - genau die
     * Strecke, die als Masthoehe H eingegeben wird. Das Mass zeigt also die
     * eingetippte Zahl und nicht eine, die man erst umrechnen muss.
     */
    const massVon = (sz, feld) => sz.masse.find((mm) => mm.feld === feld);
    {
      const mh = massVon(lang.sz, 'mastH');
      wahr('Der Mast ist vermasst', !!mh, mh ? mh.text : '(fehlt)');
      pruef('Und zwar ueber die Masthoehe', Math.abs(mh.p1[2] - mh.p0[2]), 8.31,
            1e-9, 'm');
      pruef('Ab der Joch Unterkante', mh.p1[2], fussVon(lang.sz) + 8.31, 1e-9, 'm');
      wahr('Das Mass nennt die eingetippte Zahl', mh.text.includes('8.31'), mh.text);
      // Seitlich versetzt, nicht quer: in der Laengsansicht laege ein
      // Querversatz genau hinter dem Masten.
      wahr('Seitlich versetzt, in der Jochachse',
           mh.ab[0] !== 0 && mh.ab[1] === 0, JSON.stringify(mh.ab));

      const lm = massVon(lang.sz, 'mastLaenge');
      wahr('Bei angegebener Laenge steht auch sie da', !!lm, lm ? lm.text : '(fehlt)');
      pruef('Ueber die ganze Laenge', Math.abs(lm.p1[2] - lm.p0[2]), 12.5, 1e-9, 'm');
      /*
       * SIE STEHT JETZT IMMER DA: ohne Angabe ist die Laenge H + 0.50 m,
       * also gibt es einen Ueberstand und damit eine Masskette dafuer.
       */
      wahr('Ohne Laengenangabe steht sie trotzdem da',
           !!massVon(kurz.sz, 'mastLaenge'));
      wahr('Die Masthoehe aber schon', !!massVon(kurz.sz, 'mastH'));
    }
    /*
     * DIE JOCHLAENGE HAENGT TIEF - rund vier Meter. Dicht unter dem Untergurt
     * lag sie zwischen den Mastfuessen und deren Angaben.
     */
    {
      const mL = massVon(lang.sz, 'L');
      const zUG = Math.min(...lang.sz.flaechen.filter((f) => f.gruppe === 'profil')
        .flatMap((f) => f.punkte.map((p) => p[2])));
      wahr('Die Jochlaenge haengt rund vier Meter tiefer',
           mL.p0[2] < zUG - 3.5 && mL.p0[2] > zUG - 4.5,
           `${(zUG - mL.p0[2]).toFixed(2)} m unter dem Untergurt`);
      pruef('Und sie misst die Jochlaenge', mL.p1[0] - mL.p0[0], 20, 1e-9, 'm');
    }
  }

  /*
   * ====== DER ANKER IN DER AXISVM-AUSLEITUNG ===========================
   *
   * Weisung vom 11. September: «die anker im 3d nachziehen und im axis
   * testen.»
   *
   * >>> UND DER TEST HAT SOFORT ETWAS GEFUNDEN. <<<
   *
   * Erster Aufbau in AxisVM X8: «ABBRUCH: Querschnitt
   * ANKER_U12_PLATZHALTER nicht anlegbar». Der Formschluessel hiess `R`,
   * die Bruecke kennt `Rectangle` - sie probiert ihre Kandidaten durch,
   * prueft je die Form und haelt an, wenn keiner passt. Richtig so: ein
   * geratener Querschnitt waere schlimmer als ein Abbruch.
   *
   * Deshalb prueft die erste Kontrolle hier nicht den Anker, sondern ALLE
   * Querschnitte gegen die Formen, die die Bruecke fuehrt.
   */
  {
    const einA = (extra) => ({
      ...standardwerte(), typ: 'J90', L: 20, xLage: 0, twId: 'T1',
      mastVorhanden: true, endbedingung: 'mast', mastProfil: 'HEB 240',
      mastH: 7.5, mastSteg: 'jochachse', ...extra });
    const laufA = (masten) => {
      const w = CCa.rechensatz(einA({ masten }));
      const erg = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                           getStahl(w.stahl), T.getTragjoch(w.typ));
      return AX.stabmodellJson(erg.modell, { eingabe: w,
                                             auflagerModell: 'mast' });
    };
    const CCa = await import(J('core.constants.js'));
    const jA = laufA([
      { id: 'M1', x: 0, profil: 'HEB 240',
        anker: { typ: 'U12', h: 4, a: 3, richtung: 'x', seite: 'minus',
                 befestigung: 'ankerplatte' } },
      { id: 'M2', x: 20, profil: 'HEB 240',
        anker: { typ: 'U14', h: 5, a: 4, richtung: 'y', seite: 'plus',
                 befestigung: 'ankerplatte' } }]);

    /*
     * >>> JEDER QUERSCHNITT TRAEGT EINE FORM, DIE DIE BRUECKE KENNT. <<<
     *
     * Die Liste steht in AxisVM_aufbauen.ps1; ein Name daneben bricht den
     * Aufbau ab, und zwar erst im Programm, nach zwei Minuten Aufbauzeit.
     */
    const FORMEN = ['Angle', 'Rectangle', 'DoppelU', 'Channel', 'I'];
    const fremd = (jA.querschnitte ?? [])
      .filter((q) => q.form && !FORMEN.includes(q.form));
    wahr('Alle Querschnitte tragen eine bekannte Form',
         fremd.length === 0, fremd.map((q) => `${q.name}:${q.form}`).join(', '));

    /* =====================================================================
     * >>> DIE STUETZE IST ZWEI PROFILE, KEIN ERSATZRECHTECK. <<<
     * =====================================================================
     *
     * Weisung vom 15. September: "weiter mit stufe 1 der druckstuetze."
     *
     * Bis dahin ging EIN Stab hinaus - ein Rechteck gleicher Flaeche,
     * gelenkig an beiden Enden. Fuer die Normalkraft war das genug, fuer
     * das Bild nicht: der Keil ist das Kennzeichen des Bauteils, und im
     * Modell stand ein Balken.
     *
     * JETZT: zwei Stabzuege aus dem Einzelprofil, keilfoermig gespreizt,
     * je Ende ein Starrelement zum gemeinsamen Anschlusspunkt, und an den
     * beiden vermassten Knickstellen eine Lasche.
     *
     *   je Anker  2 Reihen x 3 Abschnitte  = 6 Profilstaebe
     *             2 Kopf- + 2 Fussanschluesse
     *             2 Laschen
     */
    const prof = (jA.staebe ?? []).filter((x) => /^ANKERPROFIL_/.test(x.name));
    /*
     * >>> DIE REIHEN SIND AN JEDER BLECHSTATION GETEILT. <<<
     *
     * Seit dem 15. September stehen die Bindebleche im Modell (Befund:
     * "die verbindungsbleche sind nicht modelliert"), und wo ein Blech
     * sitzt, braucht das Profil einen Knoten. Je Reihe also ein Abschnitt
     * mehr als Bleche.
     *
     *   Anker A  U12, L = 5.000 m  ->  3 Bleche, 4 Abschnitte je Reihe
     *   Anker B  U14, L = 6.403 m  ->  5 Bleche, 6 Abschnitte je Reihe
     */
    const zahlA = AN.ankerBindebleche('U12', 5).length;
    const zahlB = AN.ankerBindebleche('U14', Math.hypot(4, 5)).length;
    pruef('Drei Bleche am kurzen Anker', zahlA, 3, 1e-12, 'Stk');
    wahr('Je Reihe ein Abschnitt mehr als Bleche',
         prof.length === 2 * ((zahlA + 1) + (zahlB + 1)),
         `${prof.length} gegen ${2 * ((zahlA + 1) + (zahlB + 1))}`);
    wahr('Sie sind Staebe, keine Starrkoerper',
         prof.every((x) => x.art === 'stab'));
    /*
     * >>> UND ZWAR DURCHLAUFEND. <<<
     *
     * Das Gelenk sitzt am ANSCHLUSS, nicht zwischen zwei Abschnitten
     * desselben Profils. Eine Kette gelenkiger Staebe waere ein
     * Gelenkviereck - es gaebe keinen Keil mehr, sondern einen Mechanismus.
     */
    wahr('\u2026 und durchlaufend, ohne Gelenk dazwischen',
         prof.every((x) => !x.gelenkAnfang && !x.gelenkEnde));
    const ansch = (jA.staebe ?? [])
      .filter((x) => /^ANKER(KOPF|FUSS)_/.test(x.name));
    wahr('Acht Anschluesse - je Anker zwei oben und zwei unten',
         ansch.length === 8, `${ansch.length}`);
    /* =====================================================================
     * >>> DAS GELENK LIEGT IN DER PROFILACHSE, NICHT AM LAGER. <<<
     * =====================================================================
     *
     * Befund vom 16. September aus AxisVM: "Knoten hat keine Steifigkeit.
     * (1x) - YY (1x)". Der Lagerknoten trug ein Auflager mit allen drei
     * Drehungen frei, und daran hingen zwei Linkelemente, die keine Momente
     * uebertragen. Beide lagen KOLLINEAR in der Spreizrichtung: eine
     * Drehung um diese Gerade bewegt keinen der drei Punkte, also hielt sie
     * niemand.
     *
     * Weisung: "ich denke wir koennen nicht direkt einen linkelement an das
     * lager setzen, wir sollten hier ueber ein starrelement gehen und in der
     * achse der c-Profile einen kurzen teil als link ausbilden. das gleiche
     * dann auch beim knoten beim anschluss masten." 50 mm, innerhalb der
     * Stuetzenlaenge, alle drei Momente frei.
     *
     * Die Kette ist seither dreiteilig:
     *
     *   Lagerknoten --STARR-- s = sL --LINK-- s = 2*sL --PROFIL--
     *
     * Und das starre Stueck muss IN DIE ACHSE hineinreichen: ginge es nur
     * quer, laege sein Endpunkt wieder auf der Geraden, und der Nullmodus
     * bliebe. Genau das nagelt die Kontrolle unten fest.
     */
    wahr('Die Anschluesse ans Lager sind STARR, nicht gelenkig',
         ansch.every((x) => !x.gelenkAnfang),
         ansch.map((x) => x.gelenkAnfang ?? '-').join(' '));
    wahr('\u2026 und werden als Starrkoerper ausgeleitet',
         ansch.every((x) => x.art === 'starr'),
         [...new Set(ansch.map((x) => x.art))].join(' '));
    const gelenke = (jA.staebe ?? [])
      .filter((x) => /^ANKERGELENK_/.test(x.name));
    wahr('Acht Gelenkstuecke - je Anker zwei oben und zwei unten',
         gelenke.length === 8, `${gelenke.length}`);
    wahr('Jedes gibt alle drei Momente frei',
         gelenke.every((x) => x.gelenkAnfang === 'M'));
    wahr('\u2026 und wird als Linkelement ausgeleitet',
         gelenke.every((x) => x.art === 'link'),
         [...new Set(gelenke.map((x) => x.art))].join(' '));
    /*
     * >>> SIE MESSEN 50 mm UND LIEGEN IN DER ACHSE. <<<
     *
     * In der Achse, weil das Profil dort weiterlaeuft - ein Gelenkstueck
     * quer dazu waere ein zweiter Hebel, kein Bolzen.
     */
    {
      const knG = new Map((jA.knoten ?? []).map((k) => [k.name, k]));
      const lgG = (st3) => {
        const p1 = knG.get(st3.von), p2 = knG.get(st3.bis);
        return Math.hypot(p2.x - p1.x, p2.y - p1.y, p2.z - p1.z);
      };
      gelenke.slice(0, 2).forEach((g2, i4) => {
        pruef(`Gelenkstueck ${i4 + 1} misst 50 mm`, lgG(g2), 0.05, 1e-4, 'm');
      });
      /*
       * >>> UND DAS STARRE STUECK REICHT IN DIE ACHSE. <<<
       *
       * Die Probe auf den Nullmodus: der Endpunkt des Starrelements darf
       * NICHT auf der Geraden durch den Lagerknoten in Spreizrichtung
       * liegen. Am Anker in der Jochachse heisst das: er muss sich in x
       * oder z vom Lagerknoten unterscheiden.
       */
      const fuss = ansch.find((x) => /^ANKERFUSS_A_L$/.test(x.name));
      const pLager = knG.get(fuss.von), pEnde = knG.get(fuss.bis);
      const dQuer = Math.hypot(pEnde.x - pLager.x, pEnde.z - pLager.z);
      wahr('Das Starrelement reicht in die Profilachse hinein',
           dQuer > 0.02,
           `${(dQuer * 1000).toFixed(0)} mm neben der Spreizgeraden`);
      pruef('\u2026 und zwar um das Gelenkmass', dQuer, 0.05, 2e-2, 'm');
    }
    /* =====================================================================
     * >>> DIE BINDEBLECHE, ZWEI JE STATION. <<<
     * =====================================================================
     *
     * Befund vom 15. September am aufgebauten Modell: "die verbindungsbleche
     * sind nicht modelliert." Es standen zwei Starrelemente an den
     * Knickstellen da - eine Andeutung. Die Werkstattzeichnung fuehrt sie
     * vollstaendig: zwei Bleche je Station, oben und unten zwischen den
     * Stegen, FLA 140/8.
     */
    const blech = (jA.staebe ?? []).filter((x) => /^ANKERBLECH_/.test(x.name));
    wahr('Zwei Bleche je Station',
         blech.length === 2 * (zahlA + zahlB),
         `${blech.length} gegen ${2 * (zahlA + zahlB)}`);
    wahr('Sie sind Staebe, keine Starrkoerper',
         blech.every((x) => x.art === 'stab'));
    /* =====================================================================
     * >>> BREITE ZUERST, DICKE ZWEITENS - AN ALLEN DREI BLECHSORTEN. <<<
     * =====================================================================
     *
     * Befund vom 15. September am aufgebauten Modell: "die verbindungsbleche
     * sind nicht richtig ausgerichtet" - verdreht um die Stabachse. Das
     * Ankerblech stand als [8, 140] da, also [Dicke, Breite].
     *
     * DIE REGEL steht an zwei Stellen, die in AxisVM nachgemessen richtig
     * stehen: `blechQuerschnitt` (Tragjoch) schreibt [breite, dicke],
     * `blechQs` (Abfangjoch) schreibt [b, t]. Ein Rechteck legt seine ERSTE
     * Zahl quer zur Referenzrichtung, die zweite IN sie.
     *
     * Diese Kontrolle vergleicht die drei Sorten miteinander - faellt eine
     * aus der Reihe, faellt sie hier auf. Am Ankerblech ist der Unterschied
     * nicht Kosmetik: 140 gegen 8 mm heisst Faktor (140/8)^2 = 306 in der
     * Biegesteifigkeit, und das Modell rechnete klaglos weiter.
     */
    const qsBl = (jA.querschnitte ?? []).find((x) => /^ANKERBLECH_/.test(x.name));
    const qsJoch = (jA.querschnitte ?? []).find((x) => /^BLECH_V_/.test(x.name));
    wahr('Das Ankerblech steht als [Breite, Dicke] da',
         qsBl.parameter[0] > qsBl.parameter[1],
         JSON.stringify(qsBl.parameter));
    wahr('\u2026 wie das Bindeblech des Jochs',
         qsJoch.parameter[0] > qsJoch.parameter[1],
         JSON.stringify(qsJoch.parameter));
    pruef('Und zwar mit den Massen des Blatts: Breite',
          qsBl.parameter[0], AN.ankerBlechSatz('U12').laenge, 1e-12, 'mm');
    pruef('\u2026 und Dicke',
          qsBl.parameter[1], AN.ankerBlechSatz('U12').dicke, 1e-12, 'mm');
    /*
     * UND I_y IST DIE STARKE ACHSE - dieselbe Zuordnung wie bei `blechQs`.
     * Ein vertauschtes Traegheitsmoment faellt in AxisVM nicht auf: die
     * Bruecke misst die FLAECHE zurueck, und die ist bei beiden gleich.
     */
    wahr('I_y ist die starke Achse des Blechs', qsBl.Iy > qsBl.Iz,
         `${qsBl.Iy} gegen ${qsBl.Iz}`);
    wahr('Keine Laschen mehr',
         !(jA.staebe ?? []).some((x) => /^ANKERLASCHE_/.test(x.name)));
    /*
     * >>> UND SIE LIEGEN NICHT IN DER ACHSE. <<<
     *
     * Das Paar mit seinem Hebelarm macht den mehrteiligen Druckstab steif;
     * ein einzelnes Blech auf der Profilachse waere die halbe Wahrheit.
     * Jedes Blech haengt deshalb ueber einen kurzen starren Stiel an der
     * Achse - (h - t)/2 lang, beim U12 also 56 mm.
     */
    const stiel = (jA.staebe ?? []).filter((x) => /^ANKERSTIEL_/.test(x.name));
    wahr('Vier Stiele je Station', stiel.length === 4 * (zahlA + zahlB),
         `${stiel.length}`);
    const kante = (jA.staebe ?? []).filter((x) => /^ANKERKANTE_/.test(x.name));
    wahr('\u2026 und zu jedem eine Kante', kante.length === stiel.length,
         `${kante.length}`);
    pruef('Der Stiel misst (h - t)/2', AN.ankerBlechVersatz('U12'), 56,
          1e-12, 'mm');
    pruef('… und beim U14 entsprechend', AN.ankerBlechVersatz('U14'), 66,
          1e-12, 'mm');
    {
      const knV2 = new Map((jA.knoten ?? []).map((k) => [k.name, k]));
      const lg2 = (nm2) => {
        const st2 = (jA.staebe ?? []).find((x) => x.name === nm2);
        const p1 = knV2.get(st2.von), p2 = knV2.get(st2.bis);
        return Math.hypot(p2.x - p1.x, p2.y - p1.y, p2.z - p1.z);
      };
      // Die Toleranz ist RELATIV (siehe pruef): 56 mm auf Mikrometer
      // gerundete Knoten geben rund 2e-6 Abweichung.
      pruef('Im Modell gemessen', lg2('ANKERSTIEL_A_LO1'), 0.056, 1e-5, 'm');
      /* =====================================================================
       * >>> DAS BLECH MISST DIE LICHTE WEITE, NICHT DEN ACHSABSTAND. <<<
       * =====================================================================
       *
       * Befund vom 15. September am Modell: "die bleche einkuerzen so dass
       * diese der lichten breite entsprechen. momentan sind sie auf die
       * schwerelinie der u-Traeger ausgerichtet."
       *
       * Das Blech ist zwischen die STEGE geschweisst. Zwischen Stegruecken
       * und Schwerachse liegt ey = 16 mm, je Seite - das Blech war also
       * 32 mm zu lang. Am engen Ende sind das 136 statt 104 mm, ein
       * Drittel.
       *
       * Der Anschluss geht seither ueber eine ECKE: Stiel in der
       * Profilhoehe, Kante quer auf den Stegruecken. Jedes Glied in einer
       * Achse, wie an der Auflagerkette.
       */
      pruef('Die Kante misst ey', lg2('ANKERKANTE_A_LO1'),
            AN.ankerQuerschnitt('U12').ey / 100, 1e-5, 'm');
      pruef('Das Blech misst die lichte Weite am engen Ende',
            lg2('ANKERBLECH_A_O1'), AN.ankerSpreizung('U12').schmal / 1000,
            1e-5, 'm');
      pruef('\u2026 und am weiten',
            lg2('ANKERBLECH_A_O3'), AN.ankerSpreizung('U12').breit / 1000,
            1e-5, 'm');
      wahr('\u2026 also nicht den Achsabstand',
           Math.abs(lg2('ANKERBLECH_A_O1')
                    - AN.ankerAchsabstandAn('U12', 5, 0) / 1000) > 0.03,
           `${lg2('ANKERBLECH_A_O1').toFixed(3)} gegen `
           + `${(AN.ankerAchsabstandAn('U12', 5, 0) / 1000).toFixed(3)} m`);
      /*
       * UND OBEN WIE UNTEN DASSELBE - ein Blechpaar, das auseinanderliefe,
       * waere keines.
       */
      pruef('Oben und unten gleich lang', lg2('ANKERBLECH_A_U1'),
            lg2('ANKERBLECH_A_O1'), 1e-9, 'm');
      wahr('Oben und unten gegenlaeufig',
           knV2.get('ANKBL_A_LO1').z > knV2.get('ANKBL_A_LU1').z
           || Math.abs(knV2.get('ANKBL_A_LO1').x
                       - knV2.get('ANKBL_A_LU1').x) > 1e-9);
    }
    // Und der alte Einzelstab ist weg.
    wahr('Kein Ersatzstab mehr',
         !(jA.staebe ?? []).some((x) => /^ANKER_[AB]$/.test(x.name)));
    /* =====================================================================
     * >>> DAS ANKERFUNDAMENT HAELT AUCH DIE DREHUNGEN. <<<
     * =====================================================================
     *
     * Befund des Auftraggebers vom 16. September, nach zwei Laeufen: "das
     * auflager bei der druckstütze muss gehalten sein."
     *
     * >>> UND DAS IST KEIN WIDERSPRUCH ZUR GELENKIGEN LAGERUNG. <<<
     *
     * Weisung vom 9. September: "diese sind gelenkig gelagert" - das gilt
     * weiter. Das Gelenk ist nur UMGEZOGEN: bis zum 16. September war das
     * Auflager die einzige Stelle, an der die Stuetze drehen konnte,
     * seither sitzt es 50 mm weiter oben im Gelenkstueck, wo die Schraube
     * ist.
     *
     * ZWEI GELENKE HINTEREINANDER SIND EINES ZUVIEL. Daran scheiterten die
     * beiden Laeufe davor: erst "Knoten hat keine Steifigkeit (YY)", dann
     * "numerische Instabilitaeten" mit 1.5e8 mm Verformung. Beide Male
     * leitete an diesem Knoten NICHTS ein Moment ein.
     *
     * Ueber das Gelenkstueck kommt trotzdem kein Moment in die Stuetze -
     * das Fundament haelt den kurzen Starrkoerper, nicht den Stab.
     */
    const aufA = (jA.auflager ?? []).filter((x) => /^ANKER_/.test(x.knoten));
    wahr('Zwei Ankerfundamente', aufA.length === 2);
    wahr('Sie halten die Verschiebungen',
         aufA.every((x) => x.ux === 'Rigid' && x.uy === 'Rigid'
                        && x.uz === 'Rigid'));
    wahr('… und seit dem 16. September auch die Drehungen',
         aufA.every((x) => x.fix === 'Rigid' && x.fiy === 'Rigid'
                        && x.fiz === 'Rigid'));
    /*
     * DAS GELENK DER STUETZE IST DAMIT NICHT VERSCHWUNDEN, es sitzt im
     * Gelenkstueck. Diese Probe haelt beides zusammen - faellt sie, ist die
     * Stuetze eingespannt statt gelenkig.
     */
    wahr('Und das Gelenk sitzt im Gelenkstueck, nicht im Auflager',
         (jA.staebe ?? []).filter((x) => /^ANKERGELENK_/.test(x.name))
           .every((x) => x.art === 'link'
                      && x.kraftuebertragung?.xx === 'Free'
                      && x.kraftuebertragung?.yy === 'Free'
                      && x.kraftuebertragung?.zz === 'Free'));
    wahr('Der Mastfuss bleibt dagegen eingespannt',
         (jA.auflager ?? []).filter((x) => /^MAST_/.test(x.knoten))
           .every((x) => x.fix === 'Rigid'));

    /*
     * >>> DIE EBENE FOLGT DER EINGABE. <<<
     *
     * Quer zum Gleis steht der Anker in der Jochachse, laengs in
     * Gleisrichtung. Im Modell ist das der Unterschied zwischen einem
     * Anker, der die Umlenkkraft haelt, und einem, der nichts haelt.
     */
    const kn = (nm) => (jA.knoten ?? []).find((k) => k.name === nm);
    const fA = kn('ANKER_A_F'), fB = kn('ANKER_B_F');
    wahr('Der quer stehende steht in der Jochachse',
         Math.abs(fA.y) < 1e-9 && Math.abs(fA.x - (-3)) < 1e-9,
         `x ${fA.x} y ${fA.y}`);
    wahr('Der laengs stehende in Gleisrichtung',
         Math.abs(fB.x - 20) < 1e-9 && Math.abs(fB.y - 4) < 1e-9,
         `x ${fB.x} y ${fB.y}`);
    pruef('Der Anschluss sitzt auf der Ankerhoehe ueber dem Fuss',
          kn('MAST_A_ANK').z - fA.z, 4, 1e-6, 'm');

    /* =====================================================================
     * >>> DER KEIL, MIT DEN MASSEN DER ZEICHNUNG. <<<
     * =====================================================================
     *
     * Der Anker A steht QUER zum Gleis (Jochachse), also spreizt er in
     * GLEISRICHTUNG - quer zur Ankerebene.
     *
     * >>> DER BEZUG IST BEANTWORTET (15. September). <<<
     *
     * Weisung auf die Rueckfrage: "gemaess zeichnung im grundlagen ordner."
     * Schnitt B-B zeigt die beiden U mit den STEGEN GEGENEINANDER; das Mass
     * steht zwischen den Stegruecken, ist also die lichte Weite. Der
     * Achsabstand ist eine SCHWERACHSE weiter je Seite - beim UNP 120
     * ey = 16 mm, nicht eine halbe Profilbreite:
     *
     *   am Fundament (eng)   104 + 2*16 = 136 mm
     *   am Masten (weit)     225 + 2*16 = 257 mm
     *
     * Bis zum 15. September stand hier 159 bzw. 280 mm - die Lesart "plus
     * eine Profilbreite". Sie war falsch, und die Zeichnung sagt es.
     *
     * >>> UND DAS ENGE ENDE IST EIN QUADRATISCHER KASTEN. <<<
     *
     * Die lichte Weite ist h - 2*t des Blechs: U12 120 - 16 = 104, U14
     * 140 - 16 = 124. Diese Probe nagelt den Zusammenhang fest - faellt
     * sie, ist entweder das Profil oder das Blech vertauscht.
     */
    const kL0 = kn('ANK_A_L0'), kR0 = kn('ANK_A_R0');
    /*
     * ZWEI STELLEN MEHR JE ENDE seit dem 16. September: die Reihe beginnt
     * nicht mehr am Stuetzenende, sondern 50 mm davor (Gelenk) und 100 mm
     * davor (Starrelement). Der letzte Knoten liegt entsprechend 50 mm vor
     * dem Fundament.
     */
    const letzteA = AN.ankerBindebleche('U12', 5).length + 3;
    const kLn = kn(`ANK_A_L${letzteA}`), kRn = kn(`ANK_A_R${letzteA}`);
    pruef('Am Masten stehen die Profile 257 mm auseinander',
          kR0.y - kL0.y, 0.257, 1e-9, 'm');
    pruef('Am Fundament 136 mm', kRn.y - kLn.y, 0.136, 1e-9, 'm');
    wahr('Sie liegen symmetrisch zur Ankerebene',
         Math.abs(kL0.y + kR0.y) < 1e-9 && Math.abs(kLn.y + kRn.y) < 1e-9);
    pruef('Die lichte Weite ist h - 2t des Blechs',
          AN.ankerSpreizung('U12').schmal,
          AN.ankerQuerschnitt('U12').h - 2 * AN.ankerBlechSatz('U12').dicke,
          1e-12, 'mm');
    pruef('… und beim U14 ebenso',
          AN.ankerSpreizung('U14').schmal,
          AN.ankerQuerschnitt('U14').h - 2 * AN.ankerBlechSatz('U14').dicke,
          1e-12, 'mm');
    /*
     * DIE PARALLELEN STUECKE: 1610 mm am weiten Ende, 990 mm am engen - so
     * vermasst das Blatt sie, und dort sitzen zugleich das erste und das
     * letzte Bindeblech. Die Stationen der Einteilung SIND die Knickstellen
     * des Keils.
     */
    const lg3 = (a2, b2) => Math.hypot(b2.x - a2.x, b2.y - a2.y, b2.z - a2.z);
    /*
     * DIE ERSTEN UND LETZTEN 100 mm GEHOEREN DEM ANSCHLUSS (16. September):
     * 50 mm Starrelement, 50 mm Gelenkstueck. Die Masse des Blattes zaehlen
     * weiter ab dem STUETZENENDE - im Modell bleiben davon 1610 - 100 =
     * 1510 mm zwischen dem Gelenk und dem ersten Blech.
     */
    pruef('Oben bleiben vom parallelen Stueck 1510 mm',
          lg3(kn('ANK_A_L1'), kn('ANK_A_L2')), 1.510, 1e-4, 'm');
    /*
     * DIE REIHE: 0 und 1 sind der Anschluss oben, dann die Bleche, dann
     * letzteA-1 und letzteA der Anschluss unten. Das letzte Blech liegt
     * also bei letzteA-2.
     */
    pruef('Unten 890 mm', lg3(kn(`ANK_A_L${letzteA - 2}`),
                              kn(`ANK_A_L${letzteA - 1}`)), 0.890, 1e-4, 'm');
    wahr('\u2026 und zusammen mit dem Anschluss sind es wieder 1610 und 990',
         Math.abs(lg3(kn('ANK_A_L1'), kn('ANK_A_L2')) + 2 * 0.05 - 1.610) < 1e-4
         && Math.abs(lg3(kn(`ANK_A_L${letzteA - 2}`),
                         kn(`ANK_A_L${letzteA - 1}`)) + 2 * 0.05 - 0.990) < 1e-4);
    pruef('Im parallelen Stueck aendert sich nichts',
          kn('ANK_A_R1').y - kn('ANK_A_L1').y, 0.257, 1e-9, 'm');

    /* =====================================================================
     * >>> DIE EINTEILUNG IST DIE DER ZEICHNUNG - ALLE VIER TABELLEN. <<<
     * =====================================================================
     *
     * Erstes Blech 990 mm vom engen Ende, letztes 1610 mm vom weiten,
     * dazwischen gleichmaessig mit hoechstens 1200 mm. Die beiden
     * Werkstattzeichnungen fuehren vier Laengen; die Regel trifft jede.
     */
    const stat = (typ, L2) => AN.ankerBindebleche(typ, L2)
      .map((x) => Math.round(x.x * 1000));
    wahr('U12 / 5.00 m: drei Bleche wie gezeichnet',
         stat('U12', 5).join(' ') === '990 2190 3390', stat('U12', 5).join(' '));
    wahr('U12 / 7.00 m: fuenf',
         stat('U12', 7).join(' ') === '990 2090 3190 4290 5390',
         stat('U12', 7).join(' '));
    wahr('U12 / 9.00 m: sieben',
         stat('U12', 9).join(' ') === '990 2057 3123 4190 5257 6323 7390',
         stat('U12', 9).join(' '));
    /*
     * BEIM U14 UEBER 11.00 m GEHT DIE TEILUNG GENAU AUF - 8400 / 1200 = 7.
     * In Fliesskomma kommt 7.000000000000001 heraus; ohne Epsilon im
     * Aufrunden stuende dort ein Feld zuviel. Die Zeichnung sagt acht
     * Bleche, und diese Kontrolle haelt es fest.
     */
    wahr('U14 / 11.00 m: acht, mit genau 1200 mm Teilung',
         stat('U14', 11).join(' ') === '990 2190 3390 4590 5790 6990 8190 9390',
         stat('U14', 11).join(' '));

    /*
     * >>> UND DIE LUECKE STEHT IM BERICHT. <<<
     *
     * Der Katalog fuehrt die Stuetze als «2x UNP 120» - eine Bezeichnung,
     * keine Flaeche. UNP-Profile stehen nicht im Profilkatalog. Ausgeleitet
     * wird ein Ersatzrechteck, und das darf nicht in einem Kommentar
     * stehen.
     */
    const bA = jA.tragwerk?.anker ?? [];
    wahr('Der Bericht nennt beide Anker', bA.length === 2);
    /*
     * >>> DER VERMERK SAGT, WAS DASTEHT - UND WAS DARAN LESART IST. <<<
     *
     * Seit dem 15. September zwei Profile statt eines Rechtecks. Drei Dinge
     * muessen im Bericht stehen, weil sie Annahmen sind und keine Angaben:
     * der BEZUG des Spreizmasses, die LASCHEN (nur an den vermassten
     * Stellen, starr statt Flachstahl) und das GELENK um die Bolzenachse.
     */
    wahr('Der Bericht sagt, dass zwei Profile dastehen',
         bA.every((v) => v.zweiProfile === true));
    wahr('\u2026 und nennt den Keil mit seinen Massen',
         bA.every((v) => /keilf\u00f6rmig gespreizt \(\d+\u2192\d+ mm /.test(v.vermerk)));
    /*
     * >>> SEIT DEM 15. SEPTEMBER STEHT DORT KEINE LESART MEHR. <<<
     *
     * Hier stand, der Vermerk muesse den Achsabstand eine LESART nennen und
     * sagen, dass Anzahl und Abstand der Laschen fehlen. Beides war richtig,
     * solange nur das Bemessungsblatt vorlag. Die Werkstattzeichnung fuehrt
     * den Bezug (Schnitt B-B) und die Blecheinteilung vollstaendig - jetzt
     * nennt der Vermerk die MASSE, nicht die Luecke.
     */
    wahr('\u2026 nennt die lichte Weite zwischen den Stegen',
         bA.every((v) => /lichte Weite zwischen den Stegen/.test(v.vermerk)),
         bA[0]?.vermerk ?? '');
    wahr('\u2026 und die Zahl der Blechstationen',
         bA.every((v) => /\d+ Bindeblech-Stationen/.test(v.vermerk)
                      && v.bleche > 0));
    wahr('\u2026 mit den Randmassen der Einteilung',
         bA.every((v) => /990 mm vom engen/.test(v.vermerk)
                      && /1610 mm vom weiten/.test(v.vermerk)));
    /*
     * MASSGEBEND BLEIBT DAS BEMESSUNGSDIAGRAMM - daran aendert auch ein
     * vollstaendiges Modell nichts. Die Kurve kennt Keil und Blecheinteilung
     * bereits; sie ist die gepruefte Angabe, das Modell die Darstellung.
     */
    wahr('\u2026 und nennt das Bemessungsdiagramm massgebend',
         bA.every((v) => /Bemessungsdiagramm/.test(v.vermerk)));
    /*
     * >>> DER VERMERK NENNT DEN KEIL, NICHT MEHR EINE LUECKE. <<<
     *
     * Weisung vom 11. September: «hier ist ein beispiel der logik fuer das
     * spreizmass der Druckstueze U12, dises ist auf die restlichen
     * anwendbar.» Bis dahin sagte der Bericht, das Spreizmass stehe in
     * keiner Zeichnung. Jetzt steht es im Katalog, und der Bericht sagt
     * das Richtige: I_z ist VERAENDERLICH und im Ersatzrechteck nicht
     * abgebildet - das ist eine andere Aussage als "nicht erfasst".
     */

    wahr('Die Spreizung steht als eigenes Feld im Bericht',
         bA.every((v) => v.spreizung?.schmal_mm > 0
                      && v.spreizung.breit_mm > v.spreizung.schmal_mm));
    wahr('… und nennt den Bezug der Masslinie',
         bA.every((v) => /lichte Weite/.test(v.spreizung.bezug)),
         bA.map((v) => v.spreizung.bezug).join(' | '));
    /*
     * >>> UND DER QUERSCHNITT TRAEGT DIE WERTE, NICHT MEHR EINEN
     * PLATZHALTER. <<<
     *
     * Weisung vom 11. September: «die querschnittswerte gemaess c5 szs oder
     * en nachtragen.» Hier stand die Probe auf den Platzhalternamen -
     * richtig, solange keine Werte da waren.
     *
     * Ausgeleitet wird ein RECHTECK gleicher Flaeche: zwei gespreizte
     * U-Profile sind kein parametrischer Querschnitt, und fuer einen
     * Pendelstab zaehlt E·A. In AxisVM zurueckgemessen: +0.0 % gegen den
     * Tabellenwert.
     */
    const qsA = (jA.querschnitte ?? []).filter((q) => /^ANKER_/.test(q.name));
    wahr('Kein Platzhalter mehr',
         qsA.every((q) => !/PLATZHALTER/.test(q.name)));
    wahr('Der Querschnitt nennt Profil und Quelle',
         qsA.every((q) => /UNP/.test(q.profil) && /C5|EN /.test(q.profil)));
    /*
     * >>> UND ER IST DAS EINZELPROFIL, NICHT DER VERBUND. <<<
     *
     * Zwei Staebe tragen zusammen die Verbundflaeche; jeder einzelne traegt
     * seine eigene. `Iz` des Verbunds steht im Blatt auf null - er haengt am
     * Spreizmass, und das ist ein Keil, kein fester Wert. Im Modell kommt
     * er jetzt aus der GEOMETRIE: zwei Profile im Abstand, nicht eine Zahl.
     */
    pruef('U12: die Flaeche des EINZELPROFILS, in m2',
          qsA.find((q) => /U12/.test(q.name)).A,
          AN.ankerQuerschnitt('U12').AEinzel / 1e4, 1e-12, 'm2');
    pruef('\u2026 und sein I_y', qsA.find((q) => /U12/.test(q.name)).Iy,
          AN.ankerQuerschnitt('U12').IyEinzel / 1e8, 1e-15, 'm4');
    wahr('Der Querschnitt ist ein U, kein Rechteck',
         qsA.every((q) => q.form === 'Channel'));
    /*
     * DIE PARAMETER STEHEN IN DER REIHENFOLGE DER BRUECKE: [h, b, tw, tf, R],
     * STEG VOR FLANSCH. Am 4. September gemessen, dass die naheliegende
     * Lesart den Abfangjochgurt 21 % zu weich machte - und die
     * Flaechenprobe fand es nicht, weil vertauschte Dicken fast dieselbe
     * Flaeche geben.
     */
    {
      const qU = qsA.find((q) => /U12/.test(q.name));
      const qwU = AN.ankerQuerschnitt('U12');
      wahr('Die Parameter stehen in der Reihenfolge der Bruecke',
           qU.parameter[0] === qwU.h && qU.parameter[1] === qwU.b
           && qU.parameter[2] === qwU.tw && qU.parameter[3] === qwU.tf,
           JSON.stringify(qU.parameter));
    }
    wahr('Ohne Anker steht nichts davon da',
         (laufA([{ id: 'M1', x: 0, profil: 'HEB 240' }])
           .staebe ?? []).every((x) => !/^ANKER_/.test(x.name)));

    /* =====================================================================
     * DIE VORSATZKONSOLE ALS STARRELEMENT
     * =====================================================================
     *
     * Weisung vom 11. September: «wir koennen es idealisiert mit einem
     * pauschalen abstand (starrelement) von ca. 0.15m modellieren.»
     *
     * Die Stuetze sitzt nicht auf der Mastachse, sondern am Flansch. Damit
     * greift ihre Kraft EXZENTRISCH an, und der Mast traegt das zugehoerige
     * Moment - bei 20 kN sind das 3 kNm.
     * =================================================================== */
    const kons = (jA.staebe ?? []).filter(
      (s) => /^ANKERKONSOLE_/.test(s.name));
    wahr('Je Anker eine Konsole', kons.length === 2);
    {
      const kn = (nm) => (jA.knoten ?? []).find((k) => k.name === nm);
      kons.forEach((s) => {
        const p0 = kn(s.von), p1 = kn(s.bis);
        const d = Math.hypot(p1.x - p0.x, p1.y - p0.y, p1.z - p0.z);
        pruef(`${s.name}: 0.15 m vom Masten weg`, d, 0.15, 1e-9, 'm');
      });
      /*
       * UND DER ANKER HAENGT AN IHREM ENDE, nicht mehr am Masten: sonst
       * staende die Konsole daneben und truege nichts.
       */
      const stA2 = (jA.staebe ?? []).filter((s) => /^ANKER_/.test(s.name));
      wahr('Der Anker beginnt am Konsolenende',
           stA2.every((s) => /_K$/.test(s.von)));
      wahr('… und die Konsole ist ein STARR-Querschnitt',
           kons.every((s) => /STARR/.test(s.querschnitt)));
    }
    wahr('Der Bericht nennt die Idealisierung',
         bA.every((v) => v.konsole_m === 0.15));

    /* =====================================================================
     * DAS SPREIZMASS
     * =====================================================================
     *
     * Weisung vom 11. September: «die abstaende der beiden enden sind
     * vermasst. diese verlaufen zuerst parallel bis zur ersten vermassung,
     * hier links mit 990 mm und rechts mit 3390 mm angegeben. von da an
     * verlaeuft der abstand variabel, da verbindungen der beiden enden.»
     *
     * Die 3390 mm der Zeichnung sind 1610 mm vom anderen Ende her - das
     * Blatt des U14 fuehrt beide Masse, und nur so laesst sich die Logik
     * auf andere Laengen uebertragen. Die Stuetze ist verstellbar; ein
     * Mass ab dem ENDE gilt fuer jede Laenge, eines ab dem Nullpunkt der
     * Zeichnung nur fuer diese eine.
     * =================================================================== */
    const spU12 = AN.ankerSpreizung('U12');
    pruef('U12: das enge Ende', spU12.schmal, 104, 1e-9, 'mm');
    pruef('U12: das weite Ende', spU12.breit, 225, 1e-9, 'mm');
    pruef('U12: parallel am engen Ende', spU12.parallelSchmal, 990, 1e-9, 'mm');
    pruef('U12: parallel am weiten Ende', spU12.parallelBreit, 1610, 1e-9, 'mm');
    pruef('U14: das enge Ende ist weiter', AN.ankerSpreizung('U14').schmal,
          124, 1e-9, 'mm');
    /* =====================================================================
     * >>> DER BEZUG STAND OFFEN - UND IST BEANTWORTET. <<<
     * =====================================================================
     *
     * Bis zum 15. September stand hier: "Die Masslinie steht zwischen den
     * beiden Profilen; ob sie die lichte Weite, den Achsabstand oder das
     * Aussenmass misst, sagt das Blatt nicht." Richtig - das
     * BEMESSUNGSBLATT sagt es nicht.
     *
     * Die WERKSTATTZEICHNUNG sagt es. Auf die Rueckfrage kam die Weisung
     * "gemaess zeichnung im grundlagen ordner", und Schnitt B-B zeigt die
     * beiden U mit den Stegen gegeneinander: das Mass steht zwischen den
     * Stegruecken, und die Bindebleche sind genau dort eingeschweisst.
     *
     * DIE LEHRE steht in der Sache selbst: die Angabe fehlte nicht, sie lag
     * in einer anderen Unterlage. Vier Tage lang rechnete das Werkzeug mit
     * einer Lesart, wo eine Zeichnung danebenlag.
     */
    wahr('Der Bezug der Masslinie steht fest',
         /lichte Weite/.test(spU12.bezug ?? ''), String(spU12.bezug));
    /*
     * UND ER TRAEGT: der Achsabstand ist die lichte Weite plus zwei
     * Schwerachsabstaende. Beim UNP 120 ey = 16 mm, also 104 + 32 = 136 mm
     * am engen Ende - nicht 159, wie die verworfene Lesart gab.
     */
    pruef('Der Achsabstand am engen Ende',
          AN.ankerAchsabstandAn('U12', 5, 0), 136, 1e-9, 'mm');
    pruef('… und am weiten', AN.ankerAchsabstandAn('U12', 5, 5), 257,
          1e-9, 'mm');
    wahr('Das Seil hat kein Spreizmass', AN.ankerSpreizung('SA20') === null);

    // Der Verlauf ueber eine Stuetze von 5.00 m, Stelle fuer Stelle.
    const sp5 = (x) => AN.ankerSpreizungAn('U12', 5, x);
    pruef('Am engen Ende', sp5(0), 104, 1e-9, 'mm');
    pruef('… und noch bei 0.99 m parallel', sp5(0.99), 104, 1e-9, 'mm');
    pruef('In der Mitte des veraenderlichen Stuecks', sp5(2.19), 164.5,
          1e-9, 'mm');
    pruef('Ab 3.39 m wieder parallel', sp5(3.39), 225, 1e-9, 'mm');
    pruef('Am weiten Ende', sp5(5), 225, 1e-9, 'mm');
    wahr('Der Abstand waechst ueberall, nirgends faellt er',
         Array.from({ length: 50 }, (_, i) => sp5((i * 5) / 49))
           .every((v, i, a) => i === 0 || v >= a[i - 1] - 1e-9));
    /*
     * KURZE STUETZEN zeigt die Zeichnung nicht: 990 + 1610 = 2.60 m, und
     * darunter ueberlappen die beiden parallelen Stuecke. Dann laeuft der
     * Abstand linear ueber die ganze Laenge - die Enden stimmen, und mehr
     * gibt das Blatt nicht her. Ein NaN oder ein Sprung waere schlimmer.
     */
    pruef('Kurze Stuetze: die Mitte liegt dazwischen',
          AN.ankerSpreizungAn('U12', 2, 1), 164.5, 1e-9, 'mm');
    pruef('Kurze Stuetze: das enge Ende stimmt',
          AN.ankerSpreizungAn('U12', 2, 0), 104, 1e-9, 'mm');
    pruef('Kurze Stuetze: das weite Ende stimmt',
          AN.ankerSpreizungAn('U12', 2, 2), 225, 1e-9, 'mm');
    wahr('Ausserhalb wird nicht extrapoliert, sondern gekappt',
         sp5(-3) === 104 && sp5(99) === 225);
    wahr('Ohne Sortimentseintrag kommt null, kein NaN',
         AN.ankerSpreizungAn('SA20', 5, 2) === null
         && AN.ankerSpreizungAn('U12', 0, 0) === null);

    /* =====================================================================
     * DAS WEITE ENDE SITZT AM MASTEN
     * =====================================================================
     *
     * Weisung vom 11. September: «das weite ende der Druckstuetze liegt auf
     * seite Mast. dieses wird dann direkt an den flanschen oder mit einer
     * vorsatzkonsole befestigt.»
     *
     * Das dreht die Zeichnung um: hier stand das enge Ende oben, weil eine
     * Konsole schmal aussieht. Sie ist es nicht - die beiden Profile fassen
     * den Mastflansch, und dafuer muessen sie auseinanderstehen.
     * =================================================================== */
    wahr('Der Katalog sagt, welches Ende am Masten sitzt',
         spU12.weitesEnde === 'mast' && spU12.engesEnde === 'fundament');
    /*
     * IM BILD gemessen, nicht im Katalog: `mastKoerper` zeichnet den Keil,
     * und seine erste Stuetzstelle ist der Mastpunkt. Die Linien tragen die
     * Profilachsen; ihr Abstand minus der gezeichneten Profilbreite ist der
     * lichte Spalt.
     */
    {
      const KB = await import(J('render.koerper.js'));
      const MP = await import(J('data.masten.js'));
      const k = KB.mastKoerper({
        profil: MP.getMastprofil('HEB 240'), achse: 'y', x: 0,
        zFuss: -8.5, zAnschluss: 0, zKopf: 0.5, name: 'A',
        anker: { typ: 'U12', h: 6.43, a: 4.5, richtung: 'y', seite: 'plus' },
        ankerSpreiz: AN.ankerSpreizung('U12'),
      });
      const ll = (k.linien ?? []).filter((x) => x.anker && x.stark);
      wahr('Die Stuetze ist zwei Profile, nicht eines', ll.length === 2);
      if (ll.length === 2) {
        const a2 = ll[0].punkte, b2 = ll[1].punkte;
        const spalt = (i) => (b2[i][0] - a2[i][0]) * 1000;
        wahr('… am MASTEN stehen sie weit auseinander',
             spalt(0) > spalt(a2.length - 1) + 50,
             `${spalt(0).toFixed(0)} gegen ${spalt(a2.length - 1).toFixed(0)} mm`);
        wahr('… und der Abstand nimmt nirgends zu',
             a2.every((p, i) => i === 0 || spalt(i) <= spalt(i - 1) + 1e-6));
      }
      /*
       * DIE ANSCHRIFT NENNT DIE LAENGE NICHT MEHR (Weisung vom
       * 11. September: «beim beschriften im 3d die laenge weglassen beim
       * anker»). Sie steht an der Bemassung daneben.
       */
      const ta = (k.bauteiltitel ?? []).filter((t) => /^Anker /.test(t.text));
      /*
       * DIE ANSCHRIFT TRAEGT POS., TYP UND WINKEL - und nur diese drei.
       * Weisung vom 11. September: «beim beschriften im 3d die laenge
       * weglassen» und «den winkel dazunehmen». Die Laenge steht an der
       * Bemassung daneben.
       */
      wahr('Die Anschrift nennt Pos., Typ und Winkel', ta.length === 1
           && /^Anker A · U12 · α = \d+\.\d°$/.test(ta[0].text), ta[0]?.text);
      wahr('… und nicht die Laenge', !/L = /.test(ta[0]?.text ?? ''));
      /*
       * SIE STEHT AM FUNDAMENT (Weisung: «die beschriftung zum
       * ankerfundament nehmen, so das diese besser verteilt sind») - auf
       * halber Stablaenge lag sie mitten im Bild.
       */
      wahr('… und sie steht am Ankerfundament',
           Math.abs(ta[0].p[1] - 4.5) < 0.5 && ta[0].p[2] < -7.5,
           JSON.stringify(ta[0].p.map((v) => +v.toFixed(2))));
      wahr('Der Winkel hat keine eigene Anschrift mehr',
           !(k.bauteiltitel ?? []).some((t) => /^α = /.test(t.text)));
      /*
       * DAS HOEHENMASS STEHT AM MASTEN (Weisung: «die vertikale vermassung
       * auf seite mast rueber nehmen»), also auf der Mastachse - nicht
       * ueber dem Ankerfundament.
       */
      const mH = (k.masse ?? []).find((mm) => mm.feld === 'ankerH');
      wahr('Das Hoehenmass steht auf der Mastachse',
           Math.abs(mH.p0[0]) < 1e-9 && Math.abs(mH.p0[1]) < 1e-9);
    }

    /* =====================================================================
     * DAS KNICKEN DER STUETZE - DIE KONTROLLRECHNUNG
     * =====================================================================
     *
     * Weisung vom 11. September: ein Knicknachweis, «falls einfach
     * umsetzbar». Einfach ist die Ebene SENKRECHT zur Spreizung; die andere
     * ist ein mehrteiliger Druckstab nach EN 1993-1-1 6.4 und steckt im
     * Bemessungsdiagramm.
     * =================================================================== */
    {
      const k8 = AN.ankerKnicken('U12', 8);
      // Euler von Hand: N_cr = pi^2 * E * I / L^2, I = 728 cm4, L = 800 cm.
      pruef('U12 ueber 8 m: N_cr', k8.Ncr,
            (Math.PI ** 2 * 21000 * 728) / (800 * 800), 1e-9, 'kN');
      pruef('… N_pl = A · f_y', k8.Npl, 34.0 * 23.5, 1e-9, 'kN');
      pruef('… bezogene Schlankheit', k8.lambda,
            Math.sqrt(k8.Npl / k8.Ncr), 1e-12, '-');
      wahr('… Knicklinie c', k8.knicklinie === 'c');
      wahr('… chi liegt zwischen 0 und 1', k8.chi > 0 && k8.chi < 1);
      /*
       * >>> DER WIDERSTANDSBEIWERT IST 1.05. <<<
       *
       * Grundlage der Bemessung ist SIA 263 (Weisung, 12. September); dort
       * ist gamma_M fuer Stabilitaetsprobleme 1.05, nicht die 1.00, die
       * EN 1993-1-1 empfiehlt. Die Maske fuehrt ihn als `gammaM0` mit genau
       * diesem Vorgabewert.
       *
       * Hier stand `N_b,Rd = chi * N_pl` - die Gleichung OHNE Beiwert. Sie
       * ging durch, solange der Rueckfallwert der Funktion 1.00 war, und
       * haette jede Aenderung daran als Fehler gemeldet, statt sie zu
       * pruefen. Der Beiwert steht jetzt in der Zeile.
       */
      pruef('… N_b,Rd = chi · N_pl / gamma_M', k8.NbRd,
            (k8.chi * k8.Npl) / 1.05, 1e-9, 'kN');
      pruef('… und der Rueckfallwert ist der der SIA', k8.gammaM1, 1.05,
            1e-12, '-');
      pruef('… ein eigener Wert schlaegt ihn',
            AN.ankerKnicken('U12', 8, { gammaM1: 1.0 }).NbRd,
            k8.chi * k8.Npl, 1e-9, 'kN');

      /* =====================================================================
       * >>> DIE KNICKKURVE GEGEN DIE TAFEL DER NORM. <<<
       * =====================================================================
       *
       * Weisung vom 12. September: «überprüfe die berechnung der knicklast
       * hier im rechenkern mit der fachliteratur … als grundlage für die
       * bemessung gilt die sia stahlbaunorm 263.»
       *
       * SIA 263 und EN 1993-1-1 fuehren dieselbe Knickkurve - die
       * europaeischen Knicklinien a/b/c/d mit denselben Imperfektions-
       * beiwerten und derselben Gleichung:
       *
       *   Phi = 0.5 [1 + alpha (lambda - 0.2) + lambda^2]
       *   chi = 1 / (Phi + sqrt(Phi^2 - lambda^2))  <= 1
       *
       * Beide Normen drucken sie zusaetzlich als TAFEL. Die Tafelwerte sind
       * die unabhaengige Grösse, an der sich die Umsetzung messen laesst -
       * sie stehen nicht in diesem Werkzeug, sondern im Buch.
       *
       * Genommen sind die vier meistzitierten Werte bei lambda = 1.00 und
       * der Plateauwert bei 0.2. Was darueber hinaus in der Tafel steht,
       * liesse sich ergaenzen; diese fuenf genuegen, um eine vertauschte
       * Kurve oder ein falsches alpha aufzudecken.
       */
      const chiKurve = (lam, alpha) => {
        const Phi = 0.5 * (1 + alpha * (lam - 0.2) + lam * lam);
        return Math.min(1, 1 / (Phi + Math.sqrt(Math.max(0, Phi * Phi - lam * lam))));
      };
      const ALPHA = { a: 0.21, b: 0.34, c: 0.49, d: 0.76 };
      const TAFEL = { a: 0.6656, b: 0.5970, c: 0.5399, d: 0.4671 };
      Object.entries(TAFEL).forEach(([kurve, soll]) => {
        /*
         * TOLERANZ 2e-4, RELATIV: die Tafel ist auf vier Stellen gedruckt,
         * bei chi ~ 0.5 sind das rund 1e-4 relativ. Enger zu pruefen hiesse,
         * die Rundung der Tafel zu pruefen und nicht die Formel.
         */
        pruef(`Knicklinie ${kurve} bei lambda = 1.00 (Tafel)`,
              chiKurve(1.0, ALPHA[kurve]), soll, 2e-4, '-');
      });
      wahr('Bis lambda = 0.2 gilt der Querschnitt, chi = 1',
           Object.values(ALPHA).every((a) => Math.abs(chiKurve(0.2, a) - 1) < 1e-12));
      /*
       * UND DIE OBERE SCHRANKE: chi * N_pl bleibt unter der Eulerlast. Die
       * Knickkurve naehert sich ihr von unten an - das ist ihre Herkunft und
       * eine Probe, die ohne jede Tafel auskommt.
       */
      wahr('Die Kurve bleibt unter Euler',
           [0.5, 1.0, 1.5, 2.0, 3.0].every((lam) =>
             chiKurve(lam, 0.49) < 1 / (lam * lam)));
      /*
       * DIE STUETZE SELBST, mit allen Zwischenwerten - U12 ueber 6.00 m,
       * von Hand nachgerechnet:
       *
       *   N_cr   = pi^2 * 21000 * 728 / 600^2 =  419.13 kN
       *   N_pl   = 34.0 * 23.5                =  799.00 kN
       *   lambda = sqrt(799.00 / 419.13)      =    1.3807
       *   Phi    = 0.5 [1 + 0.49*1.1807 + 1.9063] = 1.7424
       *   chi    = 1 / (1.7424 + 1.0629)      =    0.3565
       *   N_b,Rd = 0.3565 * 799.00 / 1.05     =  271.3  kN
       */
      {
        const k6 = AN.ankerKnicken('U12', 6, { fy: 23.5, gammaM1: 1.05 });
        pruef('U12 ueber 6 m: N_cr', k6.Ncr, 419.129, 0.001, 'kN');
        pruef('… lambda', k6.lambda, 1.38069, 1e-4, '-');
        pruef('… chi (Linie c)', k6.chi, 0.35646, 1e-4, '-');
        pruef('… N_b,Rd', k6.NbRd, 271.28, 1e-3, 'kN');
      }
      /*
       * >>> UND SIE LIEGT UEBER DER KURVE DES BLATTES. <<<
       *
       * Das ist die eigentliche Aussage: die Stuetze knickt NICHT senkrecht
       * zur Spreizebene, sondern IN ihr - und deshalb ist das Blatt
       * strenger. Faellt diese Kontrolle einmal um, stimmt etwas an der
       * Anordnung nicht.
       */
      [6, 8, 10, 10.5].forEach((L) => {
        wahr(`Bei ${L.toFixed(2)} m bleibt die Kontrolle ueber dem Blatt`,
             AN.ankerKnicken('U12', L).NbRd > AN.ankerZulDruck('U12', L));
      });
      wahr('Ein laengerer Stab knickt frueher',
           AN.ankerKnicken('U12', 10).NbRd < AN.ankerKnicken('U12', 6).NbRd);
      wahr('Das Seil bekommt keinen Knicknachweis',
           AN.ankerKnicken('SA20', 8) === null);
      wahr('… und der Nachweis sagt, was er nicht enthaelt',
           /6\.4/.test(k8.nichtEnthalten));
    }

    /* =====================================================================
     * UEBER DER GROESSTEN LIEFERBAREN LAENGE
     * =====================================================================
     *
     * Weisung vom 11. September: «wenn die maximallaenge ueberschritten ist,
     * dann warnung angeben.»
     *
     * Auf DRUCK fiel das immer auf - `ankerZulDruck` gibt dort null. Auf ZUG
     * nicht: die zulaessige Kraft haengt an der BEFESTIGUNG, nicht an der
     * Laenge, und eine zwoelf Meter lange U12 bekam klaglos ihr eta.
     * =================================================================== */
    wahr('Kurz genug: lieferbar',
         AN.ankerNachweis('U12', 50, 9).lieferbar === true);
    wahr('Zu lang auf ZUG: Nachweis gefuehrt, aber gemeldet',
         AN.ankerNachweis('U12', 50, 12).lieferbar === false
         && AN.ankerNachweis('U12', 50, 12).eta > 0);
    wahr('… und die Warnung nennt beide Laengen',
         /12\.00/.test(AN.ankerNachweis('U12', 50, 12).warnung)
         && /10\.50/.test(AN.ankerNachweis('U12', 50, 12).warnung));
    wahr('Zu lang auf DRUCK: kein Nachweis',
         AN.ankerNachweis('U12', -50, 12).eta === null
         && AN.ankerNachweis('U12', -50, 12).lieferbar === false);
    wahr('Ein Seil auf Druck traegt das Feld auch',
         AN.ankerNachweis('SA20', -10, 8).lieferbar === true);

    /* =====================================================================
     * >>> DIE BUEHNE ZEIGT JEDES DIAGRAMM, NICHT NUR DIE DREI DES JOCHS. <<<
     * =====================================================================
     *
     * Befund vom 15. September: "die diagramme der masten laden im mittleren
     * fenster wenn man draufdrueckt."
     *
     * `zeichneBuehne` fuehrte eine Titelliste mit DREI Eintraegen und holte
     * das Bild aus `diagramme()` - dem Satz des Jochs. Ein Klick auf ein
     * Mastdiagramm setzte die Buehne auf `mast-schnitt-0`; den Schluessel
     * gibt es dort nicht, also oeffnete sich das Modellfenster mit leerem
     * Koerper und ohne Titel. Das Modell war weg, das Diagramm kam nicht.
     *
     * DASSELBE GALT DEM ABFANGJOCH: die Seitenleiste zeichnet seine Kurven
     * mit `abfangDiagramme`, die Buehne rief unbesehen `diagramme()` - sie
     * zeigte die Kurven eines Ersatzbalkens, den es dort nicht gibt.
     *
     * Geprueft wird am QUELLTEXT: app.js laesst sich ohne Fenster nicht
     * laden. Die Aussage ist trotzdem festzunageln - sie war vier Tage lang
     * falsch, ohne dass eine Kontrolle etwas gemerkt haette.
     */
    {
      const appQ = APP_QUELLE();
      wahr('Es gibt eine Stelle, die jedes Diagramm kennt',
           appQ.includes('function diagrammSatz(erg, breite)'));
      wahr('Die Buehne holt ihr Bild von dort',
           /const bild = diagrammSatz\(letzte\.anzeige, breite\)\[buehne\]/
             .test(appQ));
      wahr('\u2026 und nicht mehr unbesehen aus diagramme()',
           !/const dia = diagramme\(letzte\.anzeige, breite\)/.test(appQ));
      wahr('Der Satz kennt das Abfangjoch',
           /const abD = erg\.abfang \? abfangDiagramme\(erg\.abfang, breite\)/
             .test(appQ));
      wahr('\u2026 und die Diagramme der Masten',
           appQ.includes("setz('mast-schnitt', w.schnitt)")
           && appQ.includes("setz('mast-eta', w.ausnutzung)")
           && appQ.includes("setz('anker-bem', w.bemessung)"));
      /*
       * DIE BREITE IST EIN ARGUMENT. Sie stand als 860 fest in der
       * Diagrammbildung - deshalb konnte die Buehne die Bilder gar nicht in
       * ihrer eigenen Breite bauen.
       */
      wahr('Die Breite der Bauteildiagramme ist ein Argument',
           appQ.includes('function weitereDiagramme(erg, breite)')
           && appQ.includes('mastDiagramme(mn, { breite, name,'));
      /*
       * UND WAS ES NICHT GIBT, ZIEHT NICHTS AUF. Ein leeres Modellfenster
       * ist schlechter als gar keine Reaktion.
       */
      wahr('Ohne Bild bleibt das Modell stehen',
           appQ.includes('if (!bild?.svg) {'));
    }

    /* =====================================================================
     * >>> EIN EINGEPRAEGTES MOMENT AM MASTEN LANDET AUF SEINER ACHSE. <<<
     * =====================================================================
     *
     * Weisung vom 15. September: "berichtigen und durchgaengigkeit zu axisvm
     * schaffen."
     *
     * >>> WAS FALSCH WAR. <<<
     *
     * `core.mast.js` schrieb `Mq: k.Myy, Ml: k.Mzz` - und davon war nur das
     * erste richtig. Der Anbauteilsatz fuehrt die Momente GLOBAL (M_xx um
     * die Jochachse, M_yy um y, M_zz um die Lotrechte); am JOCH fallen die
     * Ebenen damit zusammen, am stehenden MASTEN nicht:
     *
     *   M_xx  →  Laengsbiegung (Ml)      war: gar nicht aufsummiert
     *   M_yy  →  Querbiegung   (Mq)      war: richtig
     *   M_zz  →  Torsion       (Mt)      war: als Laengsbiegung gefuehrt
     *
     * Zwei Fehler in entgegengesetzte Richtung. Der zweite war der
     * unangenehme: ein M_xx fiel ersatzlos aus dem Nachweis.
     *
     * >>> UND DIE VORZEICHEN. <<<
     *
     * Mq = +M_y, Ml = -M_x, Mt = -M_z - nachgerechnet an den Anteilen, die
     * ohnehin drinstehen (F_z positiv nach unten). Ein blosses Vertauschen
     * der beiden Felder haette den zweiten Fehler durch einen dritten
     * ersetzt: das Moment zoege ab, statt sich aufzuaddieren.
     *
     * >>> SEIT DER UMSTELLUNG AUF GLOBALE GROESSEN STEHT DAS IM RECHENWEG. <<<
     *
     * Weisung vom 15. September: "konvention app global nachziehen." Der
     * Mastnachweis fuehrt jetzt selbst F_x/F_y/F_z und M_xx/M_yy/M_zz -
     * dieselben Namen wie das Joch, der Anbauteilsatz und die Ausleitung.
     * Ein eingepraegtes Moment wandert unveraendert durch; die Minuszeichen
     * sitzen an den Anteilen, wo sie hingehoeren, statt in der Anschrift.
     */
    {
      const CM = await import(J('core.mast.js'));
      const teilMitM = {
        id: 'MM', name: 'Traverse', vorlage: 'direkt', ort: 'mastA',
        hMast: 5.0, x: 0.8, y: 0.3, raster: 0, aktiv: true,
        lasten: [block({ einwirkung: 'G', Mxx: 7, Myy: 11, Mzz: 5 })],
      };
      const wM2 = basis({
        endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.0,
        mastSteg: 'jochachse', anbauteile: [teilMitM] });
      const mM2 = modell(wM2, getProfil(wM2.profOG), getProfil(wM2.profUG),
                         getStahl(wM2.stahl), T.getTragjoch('J90'));
      const lastM = (CM.mastLasten(mM2, 'A')?.lasten ?? [])
        .find((l) => l.art === 'anbau');
      wahr('Das Teil am Masten kommt mit seinen Momenten an', Boolean(lastM));
      /*
       * DIE BEIWERTE STEHEN SCHON DRIN - `proGruppe` traegt Bemessungswerte.
       * Geprueft wird deshalb das VERHAELTNIS der drei zueinander und ihr
       * Vorzeichen, nicht der nackte Zahlenwert: 7 / 11 / 5 mit demselben
       * Beiwert bleiben 7 : 11 : 5.
       */
      const bw = lastM.Myy / 11;
      wahr('Ein Beiwert ist im Spiel, und er ist positiv', bw > 0,
           `${bw.toFixed(3)}`);
      /*
       * KEINE UMRECHNUNG MEHR: die Last traegt die globalen Groessen, und
       * die drei stehen unveraendert da, wo sie hingehoeren.
       */
      pruef('M_yy kommt als M_yy an', lastM.Myy / bw, 11, 1e-9, 'kNm');
      pruef('M_xx als M_xx', lastM.Mxx / bw, 7, 1e-9, 'kNm');
      pruef('M_zz als M_zz', (lastM.Mzz ?? 0) / bw, 5, 1e-9, 'kNm');
      /*
       * >>> UND ES KOMMT IN DEN SCHNITTGROESSEN AN. <<<
       *
       * Die Zuordnung an der Last nuetzt nichts, wenn die Stationsschleife
       * das Glied nicht aufnimmt - genau daran fehlte es bei der Torsion:
       * `Mt` hatte ueberhaupt kein eingepraegtes Glied.
       */
      const st2 = CM.mastSchnitt(mM2, 'A')?.stationen ?? [];
      const unten = st2.find((s) => Math.abs(s.z) < 1e-9);
      wahr('Die Torsion steht in den Schnittgroessen',
           Math.abs(unten?.Mzz ?? 0) > 1e-9,
           `${(unten?.Mzz ?? 0).toFixed(3)} kNm`);
      /*
       * >>> UND DIE STATION FUEHRT DIE GLOBALEN NAMEN. <<<
       *
       * Die alten Ebenenfelder gibt es nicht mehr. Das ist die haerteste
       * Kontrolle der ganzen Umstellung: wer sie noch liest, bekommt
       * `undefined` und schreibt NaN in eine Tabelle, statt laut zu
       * scheitern - genau so stand die Torsionsspalte des Berichts lange
       * auf null, weil dort `st.T` gelesen wurde.
       */
      wahr('Die Station fuehrt F_x, F_y, F_z',
           ['Fx', 'Fy', 'Fz'].every((f) => Number.isFinite(unten?.[f])));
      wahr('\u2026 und M_xx, M_yy, M_zz',
           ['Mxx', 'Myy', 'Mzz'].every((f) => Number.isFinite(unten?.[f])));
      wahr('\u2026 und keine Ebenenfelder mehr',
           ['Mq', 'Ml', 'Mt', 'Vq', 'Vl'].every((f) => unten?.[f] === undefined),
           Object.keys(unten ?? {}).join(' '));
      /*
       * SIE LAEUFT UEBER DIE GANZE HOEHE DURCH - eine Torsion wird nach
       * unten nicht kleiner, anders als ein Biegemoment aus einer
       * Horizontalkraft.
       */
      const oben = st2.find((s) => Math.abs(s.z - 5.0) < 1e-6);
      pruef('Sie ist am Fuss dieselbe wie am Anschluss',
            unten?.Mzz ?? 0, oben?.Mzz ?? 0, 1e-9, 'kNm');

      /* ===================================================================
       * >>> DURCHGAENGIG ZU AXISVM: DIESELBE EINGABE, DIESELBE ACHSE. <<<
       * ===================================================================
       *
       * Die Ausleitung gibt die Momente GLOBAL weiter - Mx/My/Mz am
       * Anschlussknoten, unveraendert, gleichgueltig ob das Teil am Joch
       * oder am Masten sitzt. Das war schon richtig; falsch war die
       * App-Seite. Diese Kontrolle haelt beide zusammen: waeren sie je
       * wieder verschieden, prueft man am Modell etwas anderes, als die
       * App rechnet.
       */
      const AX2 = await import(J('export.axisvm.js'));
      const erg2 = berechne(wM2, getProfil(wM2.profOG), getProfil(wM2.profUG),
                            getStahl(wM2.stahl), T.getTragjoch('J90'));
      const bau2 = AX2.stabmodell(erg2.modell, { knotenmodell: 'anschnitt' });
      const satz = AX2.lasten(erg2.modell, bau2, { anbau: 'mast' });
      const mom2 = (satz?.moment ?? []).filter((x) => /_G_/.test(x.name));
      const holM = (r) => mom2.filter((x) => x.richtung === r)
        .reduce((s, x) => s + x.wert, 0);
      wahr('Die Ausleitung setzt Momente am Masten', mom2.length >= 3,
           mom2.map((x) => `${x.richtung} ${x.wert}`).join(' '));
      const bwA = holM('My') / 11;
      pruef('AxisVM: M_yy geht als My hinaus', holM('My') / bwA, 11, 1e-6, 'kNm');
      pruef('\u2026 M_xx als Mx', holM('Mx') / bwA, 7, 1e-6, 'kNm');
      pruef('\u2026 und M_zz als Mz', holM('Mz') / bwA, 5, 1e-6, 'kNm');
      /*
       * DIE PROBE, DIE BEIDE SEITEN ZUSAMMENHAELT. Was die Ausleitung als
       * Mx/My/Mz schreibt, muss die App unter demselben Namen fuehren.
       * Seit der Umstellung auf globale Groessen ist das eine GLEICHHEIT,
       * kein Vorzeichentausch - vorher hiess es -Ml/Mq/-Mt.
       */
      pruef('App und Ausleitung fuehren dasselbe M_xx',
            lastM.Mxx / bw, holM('Mx') / bwA, 1e-6, 'kNm');
      pruef('\u2026 dasselbe M_yy', lastM.Myy / bw, holM('My') / bwA,
            1e-6, 'kNm');
      pruef('\u2026 und dasselbe M_zz',
            (lastM.Mzz ?? 0) / bw, holM('Mz') / bwA, 1e-6, 'kNm');
      /*
       * >>> DIE MASKE SAGT ES AM RICHTIGEN ORT. <<<
       *
       * Der Hinweis unter den Momentfeldern erklaerte die Achsen AM JOCH -
       * auch unter einem Teil am Masten, wo er das Falsche mitsagte
       * ("Biegung im Grundriss", "treten ins Joch ein"). Und er sagt jetzt,
       * dass die Torsion am Masten zwar gefuehrt, aber nicht nachgewiesen
       * wird: lautlos aus dem Nachweis fallen darf nichts.
       */
      const uiQ2 = readFileSync(
        new URL('./js/ui.js', import.meta.url), 'utf8');
      /*
       * >>> UND DIE TABELLE SAGT ES, WO MAN DIE ZAHLEN ABLIEST. <<<
       *
       * Die Mastreihe fuehrt ihre Groessen in EBENEN (quer, laengs,
       * Torsion). Wer eine Zahl von dort ins Statikprogramm traegt oder
       * von dort zurueckliest, braucht die globale Achse daneben - mit
       * ihrem Vorzeichen: M_q = +M_yy, M_l = -M_xx, M_t = -M_zz.
       */
      wahr('Die Mastreihe hat eine zweite Kopfzeile',
           uiQ2.includes('<tr class="kopf-achse">'));
      /*
       * SIE STEHT JETZT OBEN: die Spalte heisst nach der globalen Groesse,
       * die zweite Zeile sagt, was sie am stehenden Masten anrichtet.
       * Vorher war es umgekehrt, und die Anschrift trug Minuszeichen.
       */
      wahr('… mit den globalen Groessen als Spaltennamen',
           uiQ2.includes('<th class="num">M_yy [kNm]</th>'
                         + '<th class="num">M_xx [kNm]</th>')
           && uiQ2.includes('<th class="num">M_zz [kNm]</th>'));
      wahr('… und den Kraeften dazu',
           uiQ2.includes('<th class="num">F_z [kN]</th>')
           && uiQ2.includes('<th class="num">F_x [kN]</th>'
                            + '<th class="num">F_y [kN]</th>'));
      wahr('… und keinem Minuszeichen in der Ueberschrift',
           !uiQ2.includes('<th class="num">−M_xx'));
      /*
       * WAS GEFUEHRT, ABER NICHT NACHGEWIESEN IST, STEHT DA. Eine Zahl in
       * einer Tabelle sieht sonst aus wie eine gefuehrte Groesse.
       */
      /*
       * SEIT DEM WOELBKRAFTTORSIONSNACHWEIS sagt die Tabelle nicht mehr,
       * dass die Torsion nicht gefuehrt werde - sie sagt, WIE sie gefuehrt
       * wird. Der Ansatz steckt eine Annahme (woelbeingespannter Fuss), und
       * die darf nicht in einer Zahl verschwinden.
       */
      wahr('Die Tabelle nennt den Woelbkrafttorsionsnachweis',
           uiQ2.includes('M_zz als Wölbkrafttorsion nachgewiesen')
           && uiQ2.includes('wölbeingespannten Fuss'));
      wahr('… aber nur, wo eine Woelbspannung da ist',
           /n\.stationen\.some\(\(st\) => Math\.abs\(st\.sigW \?\? 0\) > 0\.5\)/
             .test(uiQ2));
      wahr('Und die Tabelle hat eine Spalte dafuer',
           uiQ2.includes('${f0(st.sigW ?? 0)}')
           && uiQ2.includes('σ_ω [N/mm²]'));
      wahr('Der Momenthinweis unterscheidet den Ort',
           uiQ2.includes('function momentHinweis(a)')
           && /if \(!amMast\(a\)\)/.test(uiQ2));
      wahr('\u2026 und nennt am Masten die Torsion beim Namen',
           uiQ2.includes('M_zz Torsion um die '));
      wahr('\u2026 samt dem, was mit ihr nicht geschieht',
           uiQ2.includes('nicht nachgewiesen'));
    }

    /* =====================================================================
     * >>> DIE PILLEN SIND GLEICH LANG, UND OHNE URTEIL OHNE FARBE. <<<
     * =====================================================================
     *
     * Weisung vom 16. September: "bei den pillen, alle gleich lang machen,
     * beim anker noch ergaenzung anschreiben, damit es nicht gleich ist wie
     * beim mast m2. bei der kachel, wenn kein tragsicherheitsurteil, dann
     * ohne farbe, das gleiche gilt auch fuer die einzelnen bauteil kacheln."
     *
     * >>> WARUM SIE UNGLEICH WAREN. <<<
     *
     * `.nw-gruppe` war ein eigener Flexcontainer mit `flex: 1 1 auto` -
     * damit bekam jede GRUPPE gleich viel Raum, gleichgueltig ob drei
     * Pillen darin standen oder eine. Die einzelne Ankerpille wurde so
     * dreimal so lang wie eine Gurtpille. `display: contents` loest die
     * Gruppe auf; verloren geht nichts, denn der Gruppentitel steht ohnehin
     * im `title` jeder Pille.
     *
     * >>> UND WARUM AUCH GELB EINE AUSSAGE WAERE. <<<
     *
     * Mein erster Anlauf faerbte die Hauptkachel beim Einzellastfall GELB.
     * Das heisst "Vorsicht, aber gerechnet" - gemeint ist etwas anderes:
     * hier wird NICHT geurteilt. Eine Farbe, die kein Urteil traegt, gibt
     * es nicht.
     */
    {
      const cq = readFileSync(
        new URL('./css/style.css', import.meta.url), 'utf8');
      wahr('Die Pillengruppe teilt den Raum nicht mehr auf',
           /\.nw-gruppe \{ display: contents; \}/.test(cq));
      wahr('… und jede Pille bekommt denselben Anteil',
           cq.includes('.schiene-nw > div, .nw-gruppe > div { flex: 1 1 0;'));
      wahr('Ohne Urteil traegt die Kachel keine Farbe',
           /\.urteil\.ohne \{/.test(cq));
      const uq4 = readFileSync(
        new URL('./js/ui.js', import.meta.url), 'utf8');
      wahr('Die Uebersicht schaltet die Ampel ab, wo sie nicht urteilt',
           uq4.includes("const ampelU = (v) => (einzelLastfall ? '' : ampel(v))"));
      wahr('… und benutzt sie auch',
           (uq4.match(/ampelU\(/g) ?? []).length >= 8);
      wahr('Die Hauptkachel ist dann farblos, nicht gelb',
           (uq4.match(/einzelLastfall \? 'ohne' : U\.zustand/g) ?? []).length === 2);
      /*
       * Seit dem 24. September traegt die Kachel bei der Stellung «beide»
       * das Maximum ueber beide Nachweisarten (urteilMitGebrauch). Der
       * EINZELLASTFALL bleibt davon unberuehrt - dort wird nicht
       * geurteilt, also gibt es auch nichts zu vereinigen.
       */
      {
        const UIQ = await import(J('ui.js'));
        const basis = { eta: 0.5, zustand: 'ok', wer: 'Mast M1', text: 'x' };
        const erg = { verformung: { eta: 2, ok: false, A: { eta: 2 } },
                      modell: { federn: { namen: { A: 'M1' } } } };
        const U4 = UIQ.urteilMitGebrauch(basis, erg, 'beide', false);
        pruef('«beide»: die Kopfzahl ist das Maximum', U4.eta, 2, 1e-12, '–');
        wahr('… und die Farbe folgt ihm', U4.zustand === 'nok', U4.zustand);
        wahr('… der Text nennt beide Urteile getrennt',
             /x · Gebrauchstauglichkeit NICHT erfüllt/.test(U4.text), U4.text);
        wahr('… und das massgebende Bauteil', U4.wer === 'Verformung M1', U4.wer);
        wahr('Beim Einzellastfall bleibt alles, wie es war',
             UIQ.urteilMitGebrauch(basis, erg, 'beide', true) === basis);
        wahr('«Tragsicherheit» laesst die Verformung draussen',
             UIQ.urteilMitGebrauch(basis, erg, 'trag', false) === basis);
        const U5 = UIQ.urteilMitGebrauch(basis, erg, 'gzg', false);
        wahr('«Gebrauchstauglichkeit» zeigt allein sie',
             U5.eta === 2 && /^Gebrauchstauglichkeit/.test(U5.text), U5.text);
        // «Nicht gefuehrt» ist kein Urteil und bleibt gelb.
        wahr('«nicht gefuehrt» bleibt gelb',
             UIQ.urteilMitGebrauch({ ...basis, zustand: 'warn' }, erg, 'beide', false)
               .zustand === 'warn');
      }
      const aq3 = APP_QUELLE();
      wahr('Die Pillen ebenso',
           aq3.includes("anzeigeKombi === 'umhuellend' ? stufe(v) : ''"));
      /*
       * DIE ANKERPILLE HEISST NICHT WIE DER MAST. In der Schiene standen
       * zwei Pillen "M2" untereinander, eine mit 0.95 und eine mit 0.11.
       */
      wahr('Die Ankerpille traegt ihre eigene Anschrift',
           aq3.includes('teile.push([`Ank ${name}`,'));
    }

    /* =====================================================================
     * >>> DAS FENSTER GIBT ES AUCH FUER DEN MASTEN. <<<
     * =====================================================================
     *
     * Weisung vom 16. September: "diese fenster auch für die maste anzeigen.
     * bei den jochen noch die anschlusshöhe (bezogen auf m1) ergänzen als
     * feld. diese maske auch über das kontextmenue aufrufbar machen."
     *
     * Dasselbe Muster wie beim Tragwerk: was ein Bauteil AUSMACHT, steht in
     * einem Fenster beisammen. Beim Masten sind das fuenf Zahlen - Profil,
     * Stegrichtung, Anschlusshoehe, Gesamtlaenge, Stelle.
     *
     * Geprueft wird am Quelltext: `app.js` laesst sich ohne Fenster nicht
     * laden.
     */
    {
      const aq2 = APP_QUELLE();
      wahr('Es gibt ein Fenster fuer den Masten',
           aq2.includes('function dialogMast(app, mastId)'));
      ['dlg-m-profil', 'dlg-m-h', 'dlg-m-l', 'dlg-m-x'].forEach((f) => {
        wahr(`Es fuehrt ${f}`, aq2.includes(f));
      });
      wahr('… und die Stegrichtung als Knopfreihe',
           aq2.includes('data-m-steg='));
      /*
       * ERST DEN MASTEN WAEHLEN, DANN SCHREIBEN - `mastProfil` und `mastH`
       * gehoeren dem GEWAEHLTEN Masten. Ohne diesen Schritt landeten sie
       * bei einem anderen.
       */
      const iOk = aq2.indexOf("n.querySelector('[data-m-ok]').onclick");
      const blockOk = aq2.slice(iOk, iOk + 1200);
      wahr('Das Fenster waehlt erst den Masten, dann schreibt es',
           iOk > 0
           && blockOk.indexOf("aendern('mastAktiv', m.id)")
              < blockOk.indexOf("aendern('mastProfil'"));
      /*
       * >>> DIE ANSCHLUSSHOEHE STEHT AUCH IM TRAGWERKSFENSTER. <<<
       *
       * Sie ist die dritte Zahl, die ein Joch beschreibt - Typ, Stuetzweite,
       * Hoehe -, und sie stand als einzige nicht dort. Bezogen auf M1: die
       * Hoehe gehoert dem MASTEN, und ein Joch hat zwei davon.
       */
      wahr('Das Tragwerksfenster fuehrt die Anschlusshoehe',
           aq2.includes('dlg-tw-h')
           && aq2.includes('function hoeheVonM1(app, t)'));
      wahr('… gelesen am ersten Masten des Tragwerks',
           aq2.includes('function erstenMastVon(app, t)'));
      wahr('… und geschrieben ueber ihn',
           /aendern\('mastAktiv', m1\.id\)/.test(aq2));
      /*
       * >>> UND BEIDE FENSTER STEHEN IM KONTEXTMENUE. <<<
       *
       * Sie waren nur ueber den zweiten Klick auf ein angewaehltes Bauteil
       * zu erreichen - ein Weg, den man kennen muss.
       */
      wahr('Das Tragwerksfenster steht im Kontextmenue',
           /tun: \(\) => dialogTragwerk\(app, id\)/.test(aq2));
      wahr('Das Mastfenster ebenso',
           /tun: \(\) => dialogMast\(app, mastId\)/.test(aq2));
      wahr('… und der Sprung in die Seitenleiste bleibt daneben',
           aq2.includes("{ text: 'In der Seitenleiste bearbeiten', tun: () => {"));
    }

    /* =====================================================================
     * >>> EIN EINZELLASTFALL IST KEIN NACHWEIS. <<<
     * =====================================================================
     *
     * Weisung vom 16. September: "die ausnutzung sollte sich immer auf die
     * bemessung aller relevanten kombinationen beziehen ... sonst geht man
     * gefahr, beim versehentlichen umschalten auf einen lastfall gruene
     * kacheln zu sehen und in der hauptkachel heisst noch zusaetzlich
     * Tragsicherheit erfuellt, was nicht korrekt ist nach sia, da nicht
     * massgebende kombination beachtet."
     *
     * Die Norm verlangt die unguenstigste Kombination. Ein Lastfall zeigt,
     * WAS eine einzelne Einwirkung anrichtet - er beantwortet nicht die
     * Frage, ob das Bauteil haelt. Bis hierher stand "Tragsicherheit
     * erfuellt" auch dann da.
     *
     * Geprueft wird am Quelltext: `ui.js` laesst sich ohne Fenster nicht
     * laden. Die Aussage ist trotzdem festzunageln - sie ist die einzige
     * im Werkzeug, bei der ein Fehler als GRUENE Kachel erscheint.
     */
    {
      const uq3 = readFileSync(
        new URL('./js/ui.js', import.meta.url), 'utf8');
      wahr('Die Uebersicht kennt die Quelle ihrer Zahlen',
           uq3.includes('const einzelLastfall = opt.quelle')
           && uq3.includes('function quellSchalter(opt, einzel, eBem)'));
      wahr('Beim Einzellastfall faellt das Tragsicherheitsurteil weg',
           uq3.includes('Einzellastfall — kein Tragsicherheitsurteil'));
      wahr('… und die Zeile nennt die Bemessung daneben',
           uq3.includes('Die Bemessung über alle Kombinationen gibt'));
      /*
       * DIE BEMESSUNG WANDERT IMMER MIT - sonst haette die Uebersicht keine
       * Zahl, gegen die sie den Lastfall stellen koennte.
       */
      const aq = APP_QUELLE();
      wahr('Die Huellkurve kommt unabhaengig von der Anzeige an',
           /bemessung: kombi\.huellkurve \? letzte\.bemessung : null/.test(aq)
           && /quelle: anzeigeKombi/.test(aq));
      /*
       * >>> DIE KNICKEN-KACHEL FOLGT DER NACHWEISAUSWAHL. <<<
       *
       * Weisung: "die kachel knicken mast ausblenden wenn der nachweis in
       * den optionen nicht aktiv geschalten ist." Wer das Knicken
       * abschaltet, tut es mit Grund - eine Knickzahl, die daneben
       * stehenbliebe, waere eine Auskunft ueber eine Rechnung, die man
       * ausdruecklich nicht fuehrt.
       */
      wahr('Die Knicken-Kachel steht nur bei gefuehrtem Nachweis',
           /if \(e\.knick && urteil\.nachweise\?\.knickenMast !== false\)/
             .test(uq3));
      wahr('… und heisst nach dem Bauteil, nicht nach dem Masten',
           uq3.includes('`Knicken Stütze ${name}`'));
      /*
       * >>> UND DIE STUETZE TRAEGT IHRE AUSNUTZUNG. <<<
       *
       * Weisung: "kann man noch die druckstuetze bei der ausnutzung in der
       * entsprechender farbe darstellen und nicht einfach nur grau im 3d."
       * Sie hatte kein `werte`-Feld, und die Einfaerbung liest genau das.
       */
      const kq = readFileSync(
        new URL('./js/render.koerper.js', import.meta.url), 'utf8');
      wahr('Der Ankerkoerper traegt ein eta, wenn eines da ist',
           kq.includes('{ werte: { eta: o.ankerEta } }'));
      const rq = readFileSync(
        new URL('./js/render.3d.js', import.meta.url), 'utf8');
      wahr('… und die Szene reicht es herein',
           rq.includes('ankerEta: erg?.anker?.[name]?.nachweis?.eta ?? null'));
    }

    /* =====================================================================
     * >>> DER REITER AUFLAGER ZEIGT DEN MASTFUSS ZUERST. <<<
     * =====================================================================
     *
     * Weisung vom 16. September: "bei den reaktionskraefte die mastfuss als
     * primaeren output nehmen, falls diese nicht modelliert sind die
     * jochauflager. wie koennte man bei mehreren Masten / Jochenden eine
     * bessere uebersicht in der sidebar ermoeglichen. gehe die sidebar
     * auflager durch und optimiere und vereinfache so weit wie moeglich,
     * aehnliches vorgehen wie bei der karte Anbauteile."
     *
     * Der Mastfuss ist die Zahl, die das Haus weitergibt - die
     * Bestandesschutz-Pruefung fragt nach F_z, F_x, F_y, M_yy und M_xx AM
     * FUSS. Bisher stand das Jochauflager oben und der Mastfuss unten in
     * der letzten Zeile einer Tabelle ueber die ganze Hoehe.
     *
     * Geprueft wird am QUELLTEXT: `ui.js` laesst sich ohne Fenster nicht
     * laden. Die Aussagen sind trotzdem festzunageln - eine Sidebar, die
     * still wieder umfaellt, merkt niemand.
     */
    {
      const uq = readFileSync(
        new URL('./js/ui.js', import.meta.url), 'utf8');
      wahr('Der Mastfuss steht oben',
           uq.includes("abschnitt('Reaktionskräfte am Mastfuss'"));
      wahr('… mit den Bemessungswerten angeschrieben',
           /Bemessungswerte des gewählten Lastfalls/.test(uq));
      /*
       * OHNE MAST RUECKT DAS JOCHAUFLAGER NACH OBEN - es ist derselbe
       * Reiter, und er zeigt in beiden Faellen die Kraft, die aus dem
       * Tragwerk herausgeht.
       */
      wahr('Ohne Mast steht das Jochauflager oben',
           uq.includes("abschnitt('Reaktionskräfte am Jochauflager'")
           && /if \(!masten\.length\) \{/.test(uq));
      /*
       * DIE UEBERSICHT IST EINE SPALTE JE MAST. Mit einer Zeile je Mast und
       * sieben Zahlenspalten lief die Tabelle rechts aus der schmalen
       * Sidebar hinaus; gedreht braucht sie bei zwei Masten drei Spalten.
       */
      wahr('Die Fusstabelle steht quer - eine Spalte je Mast',
           uq.includes("masten.map((mm) => `<th class=\"num\">${esc(mm.name)}</th>`)"));
      wahr('… und fuehrt alle sechs Groessen plus eta',
           ['F_z', 'F_x', 'F_y', 'M_yy', 'M_xx', 'M_zz']
             .every((g) => uq.includes(`{ g: '${g}'`)));
      /*
       * UND WAS EINEN REGELWERT HAT, IST ZUGEKLAPPT - dieselbe Regel wie in
       * der Karte Anbauteile.
       */
      ['auflager-mast-', 'auflager-joch', 'auflager-hinweis'].forEach((k) => {
        wahr(`Zugeklappt: ${k}`, uq.includes(`'${k}`) || uq.includes(`\`${k}`));
      });
      /*
       * KEIN DOPPELTER KOPF. In der Klappe steht der Name schon oben;
       * zweimal dasselbe untereinander sieht nach einem Fehler aus.
       */
      wahr('Die Klappe ruft das Mastblatt ohne eigenen Kopf',
           /mastEndeHtml\(mm\.n, \{ \[mm\.ende\]: mm\.name \}, false\)/
             .test(uq));
      wahr('… und das Mastblatt kann beides',
           uq.includes('function mastEndeHtml(n, namenVon = {}, mitKopf = true)'));
    }

    /* =====================================================================
     * >>> ZWEI TEILE NEBENEINANDER SIND EINE GABEL, KEINE REIHE. <<<
     * =====================================================================
     *
     * Befund vom 15. September aus dem aufgebauten Modell: "ich habe die
     * traverse mittig genommen und die beiden buendelleiter jeweils einen
     * meter in x richtung angesetzt, links und rechts. diese wurden aber im
     * axis hintereinander angesetzt."
     *
     * `anbauKette` machte jedes Teil zum Traeger des naechsten - und legte
     * damit einen Starrstab von x = -1 quer durch den Masten nach x = +1.
     * Der Kommentar dort nannte diese Grenze und hielt fest, in den
     * Vorlagen komme keine Gabel vor. Beides war ueberholt, sobald jemand
     * den Fall eingab.
     *
     * DIE REGEL: angereiht wird nur, was in Richtung des tragenden Glieds
     * WEITER AUSSEN liegt. Sonst zweigt das Teil am Stufenanfang ab.
     */
    {
      const CA2 = await import(J('core.anbauteile.js'));
      const tl = (id, x, rolle) => ({ id, name: id, x, y: 0, z: 0, rolle,
                                      stationX: 0 });
      const gab = CA2.anbauKette(
        [tl('TRAV', 0, 'traverse'), tl('L_LI', -1, 'leiter'),
         tl('L_RE', 1, 'leiter')], { x0: 0, zAn: 0 });
      const von = (id) => gab.glieder.find((g) => g.teil?.id === id)?.von;
      wahr('Beide Leiter haengen an der Wurzel, nicht aneinander',
           von('L_LI')?.x === 0 && von('L_RE')?.x === 0,
           gab.glieder.map((g) => `${g.von.x}->${g.bis.x}`).join(' '));
      wahr('Kein Glied laeuft quer durch den Masten',
           !gab.glieder.some((g) => g.von.x * g.bis.x < -1e-9));
      /*
       * UND DIE REIHE BLEIBT EINE REIHE. Beim NT-Ausleger stehen zwei
       * Punkte desselben Bauteils hintereinander - Anschluss 0.3 m,
       * Kragarm 1.5 m. Wer daraus eine Gabel machte, haengte das Kettenwerk
       * an den Anschlusspunkt statt ans Ende des Arms.
       */
      const reihe = CA2.anbauKette(
        [tl('ANS', 0.3, 'aufbau'), tl('ARM', 1.5, 'aufbau')],
        { x0: 0, zAn: 0 });
      wahr('Was weiter aussen liegt, wird angereiht',
           reihe.glieder.find((g) => g.teil?.id === 'ARM')?.von?.x === 0.3,
           reihe.glieder.map((g) => `${g.von.x}->${g.bis.x}`).join(' '));
      /*
       * DIE RESULTANTE BLEIBT DIESELBE. Bei lauter Starrkoerpern aendert
       * die Reihenfolge an den Kraeften nichts - das war das Argument, mit
       * dem die Grenze stehenblieb. Es stimmt, und es reicht nicht: wer das
       * Modell ansieht, glaubt der Geometrie.
       */
      wahr('Jedes Teil hat weiterhin genau einen Punkt',
           gab.belegung.length === 3
           && new Set(gab.belegung.map((b) => b.teil.id)).size === 3);
    }

    /* =====================================================================
     * >>> DIE STUETZE HAENGT AN EINEM KNOTEN DES MASTEN. <<<
     * =====================================================================
     *
     * Befund vom 15. September aus dem aufgebauten Modell: "die
     * druckstuetze hat im axis keinen knoten am masten, dieser ging durch."
     *
     * Der Ankerblock setzte den Knoten - und sein Kommentar sagte sogar,
     * warum er in die Stabteilung gehoert. Nur kam er ZU SPAET: `zStufen`
     * wird frueher gebildet, und die Maststaebe standen, bevor der Anker
     * an die Reihe kam. Der Knoten entstand, lag aber auf keinem Stabende.
     *
     * EIN KOMMENTAR IST KEINE REIHENFOLGE. Deshalb wird hier GEMESSEN, was
     * er behauptet: zwei Maststaebe enden an diesem Knoten.
     */
    {
      const mAnk = rechne(basis({
        endbedingung: 'mast', mastProfil: 'HEB 240', mastH: 7.0,
        mastAnkerA: { typ: 'U12', h: 5.0, a: 3.5, richtung: 'x', seite: 1,
                      befestigung: 'ankerplatte' } })).modell;
      const bAnk = AX.stabmodell(mAnk, { knotenmodell: 'anschnitt' });
      const knAnk = [...(bAnk.knoten?.values?.() ?? [])]
        .find((k) => /^MAST_.*_ANK$/.test(k.name));
      wahr('Es gibt einen Ankerknoten am Masten', Boolean(knAnk),
           knAnk?.name ?? 'keiner');
      const dran = bAnk.staebe.filter((x) => x.von === knAnk?.name
                                          || x.bis === knAnk?.name);
      const mastdran = dran.filter((x) => /^MAST_[AB]_S\d+$/.test(x.name));
      pruef('Zwei Maststaebe enden dort - der Mast ist geteilt',
            mastdran.length, 2, 1e-12, 'Staebe');
      wahr('… und die Ankerkonsole haengt daran',
           dran.some((x) => /^ANKERKONSOLE_/.test(x.name)),
           dran.map((x) => x.name).join(' '));
      /*
       * UND DER KNOTEN SITZT AUF DER ANSCHLUSSHOEHE. Ohne diese Probe
       * koennte er irgendwo liegen und die Kontrolle darueber waere
       * trotzdem gruen.
       */
      pruef('Er liegt auf der Anschlusshoehe des Ankers',
            knAnk.z - (mAnk.federn?.mastA?.zFuss ?? -mAnk.federn?.mastA?.H ?? 0),
            5.0, 1e-6, 'm');
    }

    /* =====================================================================
     * >>> DIE TORSION AM OFFENEN PROFIL - WOELBKRAFTTORSION. <<<
     * =====================================================================
     *
     * Weisung vom 15. September: den Torsionsnachweis am Masten nachziehen,
     * "Vlasov, wie gerechnet".
     *
     * >>> WARUM NICHT tau = M_t*t/I_t. <<<
     *
     * Weil ein I-Profil offen ist. Am EINGESPANNTEN FUSS - dem massgebenden
     * Schnitt - ist die Verdrillung theta' = 0; dort traegt St. Venant
     * NICHTS, und die ganze Torsion laeuft ueber die Woelbung. Ein Nachweis
     * mit tau allein waere ausgerechnet dort leer.
     *
     * >>> OHNE NEUE ZAHL IM SORTIMENT. <<<
     *
     * I_w = I_z * h_m^2 / 4 fuer das doppelt-symmetrische I. Die Kontrolle
     * haelt fest, dass die Formel den Tabellenwert trifft - sonst waere es
     * eine Herleitung an die Stelle einer Angabe, und die ist nicht
     * zulaessig.
     */
    {
      const MP = await import(J('data.masten.js'));
      const MA2 = await import(J('core.mast.js'));
      const heb = MP.mastprofile().find((p) => p.name === 'HEB 240');
      const wt = MA2.woelbtorsion(heb, 8.0);
      wahr('Es gibt einen Woelbsatz zum Profil', Boolean(wt));
      /*
       * DER TABELLENWERT DES HEB 240 ist 486900 cm^6. Die Formel darf ihn
       * nicht mehr als ein Prozent verfehlen - dann ist sie brauchbar.
       */
      pruef('I_w trifft den Tabellenwert', wt.Iw, 486900, 3e-3, 'cm^6');
      pruef('Der Flanschmittenabstand ist h - t_f', wt.hm, 22.3, 1e-9, 'cm');
      pruef('W_f ist t_f*b^2/6 eines Flansches', wt.Wf, (1.7 * 24 * 24) / 6,
            1e-9, 'cm^3');
      /*
       * DIE ABKLINGLAENGE ist die Aussage des ganzen Ansatzes: ueber gut
       * einen Meter faellt die Woelbspannung auf ein Drittel. Wer sie nicht
       * kennt, rechnet das Kraeftepaar in den Flanschen ueber die ganze
       * Hoehe - beim HEB 240 ueber 8 m ist das Faktor 7 zu hoch.
       */
      pruef('Die Abklinglaenge 1/k', 1 / wt.k, 111.1, 1e-3, 'cm');
      /*
       * >>> DAS BIMOMENT: AM FUSS GROSS, AM KOPF NULL. <<<
       *
       * Genau umgekehrt zum St.-Venant-Anteil. Die Randbedingungen sind
       * woelbeingespannter Fuss und woelbfreier Kopf.
       */
      pruef('Am Fuss ist B = M_zz/k * tanh(k*L)',
            wt.bimoment(5, 0), (5 * 100 / wt.k) * Math.tanh(wt.k * 800),
            1e-9, 'kNcm^2');
      pruef('Am Kopf ist es null', wt.bimoment(5, 8), 0, 1e-9, 'kNcm^2');
      wahr('Und dazwischen faellt es ab',
           wt.bimoment(5, 1) < wt.bimoment(5, 0)
           && wt.bimoment(5, 4) < wt.bimoment(5, 1));
      /*
       * DIE SPANNUNG, NACHGERECHNET VON HAND: HEB 240 ueber 8 m, M_zz = 5
       * kNm gibt B = 55600 kNcm^2, M_Fl = B/h_m = 2490 kNcm, und mit
       * W_f = 163.2 cm^3 sind das 153 N/mm^2. Bei f_y = 235 allein eta 0.65
       * - die Torsion am offenen Profil ist keine Nebengroesse.
       */
      pruef('sigma_omega am Fuss', wt.sigma(5, 0), 152.7, 1e-3, 'N/mm^2');
      pruef('Sie waechst linear mit M_zz', wt.sigma(10, 0), 2 * wt.sigma(5, 0),
            1e-9, 'N/mm^2');
      /*
       * OHNE WERTE KEIN SATZ. Ein Profil ohne I_z oder I_t - oder ein Mast
       * ohne Hoehe - gibt null zurueck, nicht NaN.
       */
      wahr('Ohne Profilwerte gibt es keinen Satz',
           MA2.woelbtorsion({ Iz: 0, It: 0 }, 8) === null
           && MA2.woelbtorsion(heb, 0) === null);
      /*
       * >>> UND SIE STECKT IM NACHWEIS. <<<
       *
       * Die Kunstlast von oben traegt M_zz; mit ihr muss eta steigen, ohne
       * sie darf sich nichts aendern. Das ist die Probe, dass der Ansatz
       * angeschlossen ist und nicht neben dem Nachweis herlaeuft.
       */
      const teilTors = {
        id: 'MT', name: 'Traverse', vorlage: 'direkt', ort: 'mastA',
        hMast: 5.0, x: 0.8, y: 0.3, raster: 0, aktiv: true,
        lasten: [block({ einwirkung: 'G', Mxx: 7, Myy: 11, Mzz: 5 })],
      };
      const wTors = basis({ endbedingung: 'mast', mastProfil: 'HEB 240',
                            mastH: 7.0, mastSteg: 'jochachse',
                            anbauteile: [teilTors] });
      const mTors = modell(wTors, getProfil(wTors.profOG),
                           getProfil(wTors.profUG), getStahl(wTors.stahl),
                           T.getTragjoch('J90'));
      const nwMitM = MA2.mastNachweis(mTors, 'A');
      wahr('Der Nachweis fuehrt eine Woelbspannung',
           (nwMitM?.massgebend?.sigW ?? 0) > 1,
           `${(nwMitM?.massgebend?.sigW ?? 0).toFixed(1)} N/mm2`);
      wahr('Sie steckt in der Gesamtspannung',
           Math.abs(nwMitM.massgebend.sig
                    - (nwMitM.massgebend.sigN + nwMitM.massgebend.sigQ
                       + nwMitM.massgebend.sigL + nwMitM.massgebend.sigW))
             < 1e-9);
      wahr('Der Woelbsatz wandert an den Nachweis',
           Number.isFinite(nwMitM?.woelb?.k));
      const ohneM = rechne(basis({ endbedingung: 'mast',
                                   mastProfil: 'HEB 240', mastH: 7.0 }));
      wahr('Ohne Torsion bleibt die Woelbspannung null',
           (ohneM.mast?.A?.massgebend?.sigW ?? 0) < 1e-9);
      /* ===================================================================
       * >>> UND ER LAESST SICH ABSCHALTEN. <<<
       * ===================================================================
       *
       * Weisung vom 15. September: "torsionsnachweis abschalbar machen."
       * Dieselbe Ueberlegung wie beim Knicken: der Ansatz rechnet einen
       * FREISTEHENDEN Kragarm, der seine Torsion allein ueber die Woelbung
       * am Fuss abtraegt. Halten die Leiter den Mastkopf, dreht er sich
       * dort nicht frei.
       *
       * NICHT GEFUEHRT HEISST NICHT GERECHNET: sigma_omega faellt auf null,
       * statt als Zahl dazustehen, die niemand zaehlt.
       */
      const nwAus = MA2.mastNachweis(mTors, 'A', { torsion: false });
      pruef('Abgeschaltet ist die Woelbspannung null',
            nwAus.massgebend.sigW, 0, 1e-12, 'N/mm2');
      wahr('Und der Nachweis sagt es',
           nwAus.torsionGefuehrt === false && nwMitM.torsionGefuehrt === true);
      wahr('Abgeschaltet faellt eta auf den Rest zurueck',
           nwAus.massgebend.eta < nwMitM.massgebend.eta,
           `${nwAus.massgebend.eta.toFixed(3)} gegen `
           + `${nwMitM.massgebend.eta.toFixed(3)}`);
      /*
       * DIE EINGABE REICHT DIE GRUPPE DURCH. Ohne das waere der Schalter
       * eine Angabe ohne Wirkung - und das ist schlimmer als kein Schalter.
       */
      const eAus = rechne(basis({ endbedingung: 'mast',
                                  mastProfil: 'HEB 240', mastH: 7.0,
                                  anbauteile: [teilTors],
                                  nachweise: { torsionMast: false } }));
      wahr('Die Nachweisauswahl kommt am Masten an',
           (eAus.mast?.A?.massgebend?.sigW ?? 0) < 1e-12
           && eAus.mast?.A?.torsionGefuehrt === false);
      const eAn = rechne(basis({ endbedingung: 'mast',
                                 mastProfil: 'HEB 240', mastH: 7.0,
                                 anbauteile: [teilTors] }));
      wahr('Ohne Angabe ist er an - der strengere Fall',
           (eAn.mast?.A?.massgebend?.sigW ?? 0) > 1);
    }

    /* =====================================================================
     * >>> DIE DRUCKSTUETZE IM BILD IST DAS BAUTEIL, NICHT ZWEI QUADER. <<<
     * =====================================================================
     *
     * Weisung vom 15. September: "die detailierte modellierung der
     * druckstuetze in der app nachziehen."
     *
     * Die AxisVM-Ausleitung baut sie seit demselben Tag als zwei U-Profile
     * mit ihren Bindeblechen - im Bild standen weiter zwei glatte Quader.
     * Beide sollen dasselbe Bauteil zeigen; sonst prueft man am Modell
     * etwas anderes, als man auf dem Schirm hat.
     *
     * Gemessen wird am Baustein `mastKoerper`, mit den Daten des Sortiments
     * von Hand hereingereicht - genau so, wie es die beiden Szenen tun.
     */
    {
      const KO = await import(J('render.koerper.js'));
      const typ = 'U12';
      const qs = AN.ankerQuerschnitt(typ);
      const bl = AN.ankerBlechSatz(typ);
      const vs = AN.ankerBlechVersatz(typ);
      /*
       * DIE EINHEITEN SIND GEMISCHT - und das ist die Falle, in die ich beim
       * Bauen zuerst gelaufen bin. `data/anker.json` fuehrt h, b, t_w, t_f in
       * MILLIMETERN (120/55/7/9), e_y aber in ZENTIMETERN (1.6). Ungerechnet
       * stuende im Bild ein U von 1.20 m Hoehe.
       */
      const inCm = (v) => Number(v) / 10;
      const prof = { h: inCm(qs.h), b: inCm(qs.b), tw: inCm(qs.tw),
                     tf: inCm(qs.tf), ey: Number(qs.ey) };
      const baueAnker = (zusatz = {}) => KO.mastKoerper({
        profil: { h: 24, b: 24, tw: 1, tf: 1.7, reihe: 'HEB', name: 'HEB 240' },
        x: 0, H: 8.0, zFuss: -1.5, zKopf: 8.5, name: 'A',
        anker: { typ, h: 6.0, a: 4.0, richtung: 'quer', seite: +1 },
        ankerSpreiz: AN.ankerSpreizung(typ), ankerEy: qs.ey,
        ankerProfil: prof,
        ankerBlechMass: { laenge: bl.laenge, dicke: bl.dicke, versatz: vs },
        ankerBleche: (L) => AN.ankerBindebleche(typ, L),
        ...zusatz,
      });
      const mk = baueAnker();
      const ff = mk.flaechen.filter((x) => /^ANKER_/.test(x.teil ?? ''));
      /*
       * SCHWERACHSEN IN DER FARBE DES RESULTATS (17. September): «die
       * schwerelinien auch einfärben bei der druckstütze und dem seilanker.
       * die schwerelinien beim Masten fehlt.»
       */
      {
        const mitEta = baueAnker({ ankerEta: 0.4, nachweis: { stationen: [
          { z: 0, eta: 0.6, sig: 100, N: 10 }, { z: 4, eta: 0.3, sig: 50, N: 5 }] } });
        const achsen = mitEta.linien.filter((l) => l.schwerachse);
        wahr('Der Mast hat seine Schwerachse, abschnittsweise mit Kennwert',
             achsen.some((l) => /^Schwerachse/.test(l.label) && l.werte?.eta === 0.6));
        wahr('Die Profilachsen der Stuetze tragen das η des Ankers',
             achsen.filter((l) => l.anker).length >= 2
             && achsen.filter((l) => l.anker).every((l) => l.werte?.eta === 0.4));
        const seil = KO.mastKoerper({
          profil: { h: 24, b: 24, tw: 1, tf: 1.7, reihe: 'HEB', name: 'HEB 240' },
          x: 0, H: 8.0, zFuss: -1.5, zKopf: 8.5, name: 'A', ankerEta: 0.2,
          anker: { typ: 'SA20', h: 6.0, a: 4.0, richtung: 'quer', seite: +1 } });
        wahr('… und die Achsen des Seilankers ebenso',
             seil.linien.filter((l) => l.anker && l.schwerachse)
               .every((l) => l.werte?.eta === 0.2)
             && seil.linien.some((l) => l.anker && l.schwerachse));
        const r3 = readFileSync(join(HIER, 'js', 'render.3d.js'), 'utf8');
        wahr('Das 3D faerbt Schwerachsen mit Kennwert ein',
             /if \(l\.schwerachse\) \{[\s\S]{0,700}this\._grundfarbe\(l, t\)/.test(r3));
      }
      const pfl = ff.filter((x) => /^Anker /.test(x.label ?? ''));
      const bfl = ff.filter((x) => /^Bindeblech/.test(x.label ?? ''));
      /*
       * >>> ZWEI PROFILE, DREI ABSCHNITTE, EIN ACHTECK. <<<
       *
       * Der Verlauf hat zwei Knicke - dort, wo das parallele Stueck am
       * Masten endet und dort, wo das andere vor dem Fundament beginnt.
       * Ein U hat acht Ecken, ein Abschnitt also acht Seiten und zwei
       * Deckel: 2 * 3 * 10 = 60.
       */
      pruef('Die Stuetze ist ein Achteck, kein Quadrat',
            pfl.length, 60, 1e-9, 'Flaechen');
      /*
       * >>> DIE OFFENE SEITE ZEIGT NACH AUSSEN. <<<
       *
       * Schnitt B-B der Werkstattzeichnung: die STEGE gegeneinander, die
       * Flansche nach aussen; das Spreizmass steht zwischen den
       * Stegruecken, und dort sind die Bindebleche eingeschweisst.
       *
       * Am ENGEN Ende (Fundament) laesst sich das nachrechnen: der halbe
       * Achsabstand ist (104 + 2*16)/2 = 68 mm, der Stegruecken liegt e_y
       * = 16 mm INNERHALB davon, die Flanschspitze b - e_y = 39 mm
       * ausserhalb. Also 52 bis 107 mm - und spiegelbildlich auf der
       * anderen Seite.
       */
      const amFuss = pfl.flatMap((x) => x.punkte)
        .filter((p) => Math.abs(p[2] + 1.5) < 0.2).map((p) => p[1]);
      pruef('Die Flanschspitze steht 107 mm von der Mitte',
            Math.max(...amFuss) * 1000, 107, 1e-4, 'mm');
      pruef('\u2026 und der Stegruecken 52 mm - er zeigt nach innen',
            Math.min(...amFuss.filter((v) => v > 0)) * 1000, 52, 1e-4, 'mm');
      wahr('Das zweite Profil steht spiegelbildlich',
           Math.abs(Math.min(...amFuss) + Math.max(...amFuss)) < 1e-9,
           `${Math.min(...amFuss).toFixed(4)} / ${Math.max(...amFuss).toFixed(4)}`);
      /*
       * >>> UND DIE BINDEBLECHE MACHEN AUS ZWEI STAEBEN EIN BAUTEIL. <<<
       *
       * Die Einteilung ist die der Werkstattzeichnung, dieselbe, die
       * `ankerBindebleche` fuehrt und die AxisVM-Ausleitung baut. Zwei je
       * Stelle - oben und unten, buendig mit den Profilkanten.
       */
      const LSt = Math.hypot(4.0, 6.0);
      const stat = AN.ankerBindebleche(typ, LSt);
      wahr('Es gibt eine Blecheinteilung', stat.length >= 4,
           `${stat.length} Stellen`);
      pruef('Zwei Bleche je Stelle, je sechs Flaechen',
            bfl.length, stat.length * 2 * 6, 1e-9, 'Flaechen');
      /*
       * DAS BLECH SPANNT DIE LICHTE WEITE, NICHT DEN ACHSABSTAND. Es liegt
       * zwischen den Stegruecken - 104 mm am engen Ende, nicht 136.
       */
      const eins = bfl.slice(0, 6).flatMap((x) => x.punkte).map((p) => p[1]);
      const weite = (Math.max(...eins) - Math.min(...eins)) * 1000;
      wahr('Das erste Blech spannt die lichte Weite',
           weite > 103.9 && weite < 106.5, `${weite.toFixed(1)} mm`);
      /*
       * SEINE MITTE LIEGT (h - t)/2 VON DER PROFILACHSE - beim U12 56 mm,
       * die Aussenkante also buendig mit dem Profil bei 60 mm. Gemessen an
       * beiden Blechen einer Stelle: ihr Abstand ist 2 * 56 = 112 mm.
       */
      pruef('Der Versatz der Bleche ist (h - t)/2', vs, 56, 1e-9, 'mm');
      /*
       * >>> OHNE PROFIL BLEIBT ES BEIM QUADER. <<<
       *
       * Ein Seilanker hat keinen Querschnitt und keine Bindebleche. Ein
       * Bild, das ihm welche andichtet, waere schlimmer als das alte.
       */
      const ohne = baueAnker({ ankerProfil: null, ankerBlechMass: null });
      const oF = ohne.flaechen.filter((x) => /^ANKER_/.test(x.teil ?? ''));
      pruef('Ohne Profilangabe bleiben es Quader',
            oF.filter((x) => /^Anker /.test(x.label ?? '')).length,
            2 * 3 * 6, 1e-9, 'Flaechen');
      wahr('\u2026 und es gibt keine Bindebleche',
           !oF.some((x) => /^Bindeblech/.test(x.label ?? '')));
      /*
       * >>> UND BEIDE SZENEN REICHEN DIE DATEN HEREIN. <<<
       *
       * `render.koerper.js` ist reine Geometrie und laedt keine Datenbank -
       * die Szene holt Querschnitt, Blechmass und Einteilung. Die
       * Einteilung braucht die Stablaenge, die erst dort feststeht: deshalb
       * eine Funktion, kein Feld.
       */
      /*
       * >>> UND DIE KETTE TRAEGT BIS IN DIE ECHTE SZENE. <<<
       *
       * Bis hierher ist am BAUSTEIN gemessen, mit von Hand
       * hereingereichten Daten. Das beweist die Geometrie, nicht die
       * Verdrahtung: ein `ankerDetail`, das die Szene gar nicht ruft, faellt
       * dabei nicht auf. Also einmal durch `erzeugeSzene` - so, wie die
       * Maske es tut.
       */
      {
        const R3 = await import(J('render.3d.js'));
        /*
         * DIE MASKE FUEHRT `ankerTyp/ankerH/ankerA`, DAS MODELL
         * `mastAnkerA` - zwei Namen fuer dieselbe Sache, und die Maske
         * setzt sie um (`ANKERFELDER` in app.js). Hier wird das Modell
         * gefuellt, nicht die Maske.
         */
        const mitAnk = rechne(basis({
          mastVorhanden: true, mastProfil: 'HEB 240', mastH: 8.0,
          mastAnkerA: { typ, h: 6.0, a: 4.0, richtung: 'x', seite: 1,
                        befestigung: 'ankerplatte' } }));
        const sz = R3.erzeugeSzene(mitAnk.modell, mitAnk);
        const szA = sz.flaechen.filter((x) => /^ANKER_/.test(x.teil ?? ''));
        const szB = szA.filter((x) => /^Bindeblech/.test(x.label ?? ''));
        wahr('Die Szene zeichnet die Stuetze als Profil',
             szA.some((x) => /^Anker /.test(x.label ?? '')),
             `${szA.length} Flaechen`);
        wahr('\u2026 und ihre Bindebleche gleich mit',
             szB.length > 0 && szB.length % 6 === 0,
             `${szB.length / 6} Bleche`);
        /*
         * OHNE STUETZE KEINE BLECHE. Der Fall, den niemand einstellt und
         * der trotzdem der haeufigste ist.
         */
        const ohneAnk = rechne(basis({ mastVorhanden: true,
                                       mastProfil: 'HEB 240', mastH: 8.0 }));
        const szO = R3.erzeugeSzene(ohneAnk.modell, ohneAnk);
        wahr('Ohne Stuetze steht nichts davon im Bild',
             !szO.flaechen.some((x) => /^ANKER_/.test(x.teil ?? '')));
      }
      ['render.3d.js', 'render.abfang.js'].forEach((datei) => {
        const sq = readFileSync(
          new URL(`./js/${datei}`, import.meta.url), 'utf8');
        wahr(`${datei} reicht die Stuetzendetails herein`,
             /\.\.\.ankerDetail\(/.test(sq) && sq.includes('function ankerDetail'));
        wahr(`${datei} rechnet den Querschnitt in cm um`,
             sq.includes('const inCm = (v) =>')
             && /h: inCm\(qs\.h\)/.test(sq));
        wahr(`${datei} reicht die Einteilung als Funktion`,
             /ankerBleche: \(L\) => hol\(\(\) => ankerBindebleche\(typ, L\)\)/
               .test(sq));
      });
    }

    /* =====================================================================
     * >>> JEDE SCHNITTGROESSE TRAEGT IHRE STATISCHE BENENNUNG. <<<
     * =====================================================================
     *
     * Weisung vom 15. September: "bei allen schnittkraeften anschrift neben
     * dem quer laengs vertikal etc. die statischen benennung auffuehren wie
     * Fx Fy Fz und das gleiche mit den Momenten Mxx Myy Mzz."
     *
     * Die Schreibweise stand schon im Werkzeug - `core.anbauteile.js` fuehrt
     * die eingepraegten Lasten der Anbauteile seit jeher so:
     *
     *   F_x  in der Jochachse    M_xx  um die Jochachse (Torsion)
     *   F_y  in Gleisrichtung    M_yy  um y - biegt quer
     *   F_z  lotrecht            M_zz  um z - biegt im Grundriss
     *
     * >>> SIE IST GLOBAL, UND DAS IST DER PUNKT. <<<
     *
     * Am Ersatzbalken des Jochs faellt sie mit der oertlichen zusammen -
     * seine Stabachse IST die Jochachse, `M_y,ed` ist `M_yy`. AM MASTEN
     * NICHT: dort steht die Stabachse lotrecht, seine Normalkraft ist
     * oertlich `N` und global `F_z`. Wer die Werte ins Statikprogramm oder
     * in die Mastfusstabelle traegt, braucht die globale.
     *
     * Die Zuordnung ist nicht erfunden: `core.mast.js` setzt beim
     * Anbauteil-Moment selbst `Mq: k.Myy`.
     */
    {
      const CH = await import(J('render.charts.js'));
      const cq = readFileSync(
        new URL('./js/render.charts.js', import.meta.url), 'utf8');
      /*
       * AM MASTEN GEPRUEFT, weil dort beide Systeme auseinandergehen. Eine
       * Kunstreihe reicht - geprueft wird die Anschrift, nicht die Rechnung.
       */
      const md = CH.mastDiagramme({ stationen: [
        { z: 0, Myy: 3, Mxx: 4, Fz: 5, Fx: 6, eta: 0.3 },
        { z: 8, Myy: 0, Mxx: 0, Fz: 1, Fx: 0, eta: 0.1 },
      ] }, { breite: 860, name: 'Probe' });
      const kurz = (h) => [...h.matchAll(
        /class="legende-kurz"[^>]*>([^<]*)<tspan[^>]*>([^<]*)</g)]
        .map((m) => `${m[1]}_${m[2]}`);
      const kM = kurz(md.schnitt);
      wahr('Der Mast fuehrt vier statische Benennungen',
           kM.length === 4, kM.join(' '));
      wahr('M quer ist M_yy - das Moment um die Gleisachse',
           kM[0] === 'M_yy', kM[0]);
      /*
       * OHNE VORZEICHEN, SEIT DER UMSTELLUNG: die Kurve traegt das globale
       * Moment selbst. Bis dahin stand hier "-M_xx", weil der Nachweis in
       * Ebenen rechnete und die Rechte-Hand-Regel fuer x und y
       * gegenlaeufige Drehsinne gibt.
       */
      wahr('M laengs ist M_xx - um die Jochachse',
           kM[1] === 'M_xx', kM[1]);
      wahr('Die Normalkraft des stehenden Masten ist global F_z',
           kM[2] === 'F_z', kM[2]);
      wahr('Und seine Querkraft F_x, in der Jochachse',
           kM[3] === 'F_x', kM[3]);
      /*
       * DIE DRUCKSTUETZE BEKOMMT KEINE. Sie steht schraeg; ihre Normalkraft
       * laeuft auf keiner globalen Achse, und `F_x` daneben waere falsch.
       */
      wahr('Die Stuetze traegt kein Achsenkuerzel',
           /const serien = \[\{ name: `zul/.test(cq)
           && /KEIN ACHSENKUERZEL AN DER STUETZE/.test(cq));
      /*
       * DIE ZUORDNUNG AM JOCH steht im Quelltext - sie an einem gerechneten
       * Ergebnis abzulesen hiesse, den halben Prueflauf davorzuhaengen.
       */
      wahr('Am Ersatzbalken gehoert M_y,ed zu M_yy',
           /r\.My\), band: band\('My'\),\s*\n\s*kurz: 'M_yy'/.test(cq));
      wahr('\u2026 V_z,ed zu F_z',
           /r\.Vz\), band: band\('Vz'\),\s*\n\s*kurz: 'F_z'/.test(cq));
      wahr('\u2026 M_z,ed zu M_zz',
           /r\.Mz\), band: band\('Mz'\),\s*\n\s*kurz: 'M_zz'/.test(cq));
      wahr('\u2026 und die Torsion T_x,ed zu M_xx',
           /band: band\('Tx'\), kurz: 'M_xx'/.test(cq));
      /*
       * UND AM ABFANGJOCH IST ES VERDREHT: es liegt waagrecht, seine
       * Rahmenebene auch - die Biegung darin dreht um die LOTRECHTE Achse.
       * Genau dafuer steht das Kuerzel da.
       */
      wahr('Die Rahmenebene des Abfangjochs biegt um z',
           /sn\('Mzz'\),\s*\n\s*kurz: 'M_zz'/.test(cq));
      wahr('\u2026 und ihre Querkraft laeuft in Gleisrichtung',
           /sn\('Fy'\),\s*\n\s*kurz: 'F_y'/.test(cq));

      /* ===================================================================
       * >>> DIE MESSSTELLE IM GROSSEN DIAGRAMM. <<<
       * ===================================================================
       *
       * Zweite Haelfte derselben Weisung: "zudem wenn die diagramme gross
       * sind messstelle definieren koenen mit zahlenoutput."
       *
       * Das Bild traegt seine Zahlen mit - Achsenlage, Stuetzstellen, je
       * Serie die Werte mit Einheit. Gezeichnet wird davon nichts; erst
       * `verdrahteMessung` macht daraus einen Faden. Hier laesst sich nur
       * der Datensatz pruefen, nicht die Bedienung: der Pruefstand hat kein
       * Fenster.
       */
      const roh = /data-mess="([^"]*)"/.exec(md.schnitt);
      wahr('Das Bild traegt seinen Datensatz mit', !!roh);
      const dm = JSON.parse(roh[1].replace(/&quot;/g, '"')
        .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&'));
      wahr('Er kennt die Stuetzstellen', dm.punkte.length === 2
           && dm.punkte[1] === 8, dm.punkte.join(' '));
      wahr('\u2026 und je Serie Werte, Kuerzel und Einheit',
           dm.serien.length === 4 && dm.serien[2].kurz === 'F_z'
           && dm.serien[2].einheit === 'kN' && dm.serien[2].werte[0] === 5,
           JSON.stringify(dm.serien[2]));
      /*
       * UND SIE LIEST DIE GLOBALEN FELDER DER STATION. Die Kunstreihe oben
       * traegt nur `Myy/Mxx/Fz/Fx`; laese eine Serie noch einen alten
       * Ebenennamen, stuende ihre Kurve auf null - stumm, nicht laut.
       */
      wahr('Die Kurve liest die globalen Felder der Station',
           dm.serien.every((s) => s.werte.some((v) => Math.abs(v) > 0)),
           dm.serien.map((s) => `${s.kurz}:${s.werte[0]}`).join(' '));
      wahr('Die Achsenlage steht dabei - ohne sie kein Faden',
           [dm.mL, dm.mT, dm.x0, dm.x1].every(Number.isFinite)
           && dm.y1 > dm.y0);
      wahr('Und die Einheit der x-Achse',
           dm.xEinheit === 'm', dm.xEinheit);
      /*
       * DER FADEN RASTET AUF DIE STUETZSTELLEN EIN. Sie SIND die
       * Nachweisstellen; zwischen zweien liegt eine gerade Verbindung, die
       * niemand gerechnet hat. Derselbe Grund, aus dem `abfangDiagramme`
       * kein feineres Raster zeichnet.
       */
      wahr('Der Faden sucht die naechstgelegene Stuetzstelle',
           /if \(Math\.abs\(x - v\) < Math\.abs\(d\.punkte\[b\] - v\)\) b = i;/
             .test(cq));
      wahr('\u2026 und er laesst sich festhalten',
           cq.includes("svg.addEventListener('click'")
           && cq.includes('let fest = null;'));
      wahr('\u2026 auch mit den Pfeiltasten',
           cq.includes("ev.key === 'ArrowLeft'"));
      /*
       * DIE SPANNE WANDERT MIT, wo es eine gibt: bei einer Umhuellenden ist
       * gerade sie die Auskunft.
       */
      wahr('Wo ein Band steht, traegt der Datensatz die Spanne',
           /band: s\.band \? \[s\.band\[0\]\.map\(r4\), s\.band\[1\]\.map\(r4\)\]/
             .test(cq));
      /*
       * VERDRAHTET WIRD NUR DIE BUEHNE. In der Seitenleiste liegen die
       * Stuetzstellen auf schmaler Spalte so dicht, dass der Faden mehr
       * raet als misst.
       */
      const appQ2 = APP_QUELLE();
      wahr('Die Buehne verdrahtet den Faden', appQ2.includes('verdrahteMessung(n);'));
      wahr('\u2026 und sonst niemand',
           (appQ2.match(/verdrahteMessung\(/g) ?? []).length === 1);
      wahr('Ohne DOM tut die Verdrahtung nichts',
           CH.verdrahteMessung(null) === 0
           && CH.verdrahteMessung({}) === 0);

      /* ===================================================================
       * >>> UND DIE LEGENDE LAEUFT NICHT AUS DEM BILD. <<<
       * ===================================================================
       *
       * Sie stand in EINER Zeile. Mit dem Kuerzel daneben waere sie beim
       * Abfangjoch darueber hinausgelaufen - "M Gurt lotrecht (halbe Last +
       * Torsion)" ist ein langer Name -, und was aus dem viewBox faellt,
       * ist einfach weg. Jetzt bricht sie um, und der obere Rand waechst
       * mit.
       */
      const lang = [
        { name: 'N Kraeftepaar (e = 12.3 cm)', werte: [0, 1],
          kurz: 'F_x', einheit: 'kN' },
        { name: 'M Gurt lotrecht (halbe Last + Torsion)', werte: [0, 1],
          kurz: 'M_yy', einheit: 'kNm' },
        { name: 'M oertlich zwischen zwei Blechen', werte: [0, 1],
          cls: 'serie-4', kurz: 'M_zz', einheit: 'kNm' },
      ];
      [860, 566].forEach((br) => {
        const h = CH.linienDiagramm({ titel: 'Probe', breite: br,
                                      punkte: [0, 10], serien: lang });
        const xs = [...h.matchAll(/class="legende(?:-kurz)?" x="([\d.]+)"/g)]
          .map((m) => Number(m[1]));
        wahr(`Bei ${br} px bleibt die Legende im Bild`,
             Math.max(...xs) + 30 < br - 16,
             `bis ${Math.max(...xs).toFixed(0)} von ${br - 16}`);
        const ys = [...new Set([...h.matchAll(/class="legende" [^>]*y="([\d.]+)"/g)]
          .map((m) => m[1]))];
        wahr(`\u2026 auf mehreren Zeilen (${br} px)`, ys.length > 1,
             ys.join(' '));
      });
      /*
       * UND DER OBERE RAND WAECHST MIT: sonst liegt die zweite Zeile im
       * Gitter.
       */
      const eng = CH.linienDiagramm({ titel: 'Probe', breite: 566,
                                      punkte: [0, 10], serien: lang });
      const gitterY = [...eng.matchAll(/class="grid" x1="[\d.]+" y1="([\d.]+)" x2="[\d.]+" y2="[\d.]+"/g)]
        .map((m) => Number(m[1]));
      const legY = [...eng.matchAll(/class="legende" [^>]*y="([\d.]+)"/g)]
        .map((m) => Number(m[1]));
      wahr('Die oberste Legendenzeile liegt ueber dem Gitter',
           Math.max(...legY) < Math.min(...gitterY.filter((y) => y > 20)) + 1,
           `Legende bis ${Math.max(...legY)}, Gitter ab ${Math.min(...gitterY)}`);
    }

    /* =====================================================================
     * >>> DIE KRAFTBILDER AN DEN KURVEN SIND WEG. <<<
     * =====================================================================
     *
     * Weisung vom 15. September: "nimm diese sekundaeren erklaer skizzen zu
     * den einzelnen kurven weg, diese sind meist nicht ganz korrekt und
     * verwirren mehr als sie helfen."
     *
     * >>> WAS SIE WAREN, UND WARUM SIE NICHT STIMMEN KONNTEN. <<<
     *
     * Ein Klick auf einen Legendeneintrag zeigte unter dem Diagramm eine
     * kleine Skizze: welche Kraefte die Groesse am Joch meint. Gebaut waren
     * sie aus den FORMELN, nicht aus dem gerechneten Zustand - sie zeigten
     * den Regelfall, auch wo das Vorzeichen gerade andersherum stand.
     *
     * Schon am 11. September war derselbe Mangel gemeldet worden ("die
     * verdrahtung der sekundaeren diagramme unter verlaeufe sind nicht
     * korrekt"): die Kurven des Abfangjochs trugen damals die Bilder des
     * TRAGJOCHS. Damals wurde die Verdrahtung berichtigt; jetzt faellt der
     * ganze Zweig, und das ist die ehrlichere Antwort. Ein Bild, das neben
     * der Kurve steht und manchmal das Gegenteil sagt, ist schlimmer als
     * keines.
     *
     * >>> WO DIE ERKLAERUNG JETZT STEHT. <<<
     *
     * Im Handbuch - dort laesst sie sich am Fall nachrechnen, statt als
     * Piktogramm neben einer Zahl zu stehen.
     *
     * Diese Kontrolle haelt fest, dass nichts davon zurueckkommt: weder das
     * Modul, noch ein Schluessel an einer Serie, noch der Platz in der Maske.
     */
    {
      const quelle = readFileSync(
        new URL('./js/render.charts.js', import.meta.url), 'utf8');
      const uiQ = readFileSync(
        new URL('./js/ui.js', import.meta.url), 'utf8');
      wahr('Keine Serie traegt mehr einen Skizzenschluessel',
           !/skizze: '[A-Za-z]+'/.test(quelle),
           (quelle.match(/skizze: '[A-Za-z]+'/g) ?? []).join(' '));
      wahr('Die Legende ist kein Knopf mehr',
           !quelle.includes('legende-eintrag')
           && !quelle.includes('legende-treffer'));
      wahr('Unter dem Diagramm haengt kein Platz dafuer',
           !uiQ.includes('dia-skizze'));
      wahr('Und die Maske laedt das Modul nicht mehr',
           !uiQ.includes('render.skizzen.js'));
      /*
       * DAS MODUL SELBST IST FORT. Ein Modul, das niemand laedt, faellt aus
       * dem Buendel und bleibt im Ordner liegen - der Bericht des Buendlers
       * nennt es dann unter "nicht eingebundene Module". Besser ganz weg.
       */
      let da = true;
      try { await import(J('render.skizzen.js')); } catch { da = false; }
      wahr('Das Modul render.skizzen.js gibt es nicht mehr', da === false);
      /*
       * DIE UEBRIGEN SKIZZEN BLEIBEN - sie sind etwas anderes: die
       * Optionsskizzen erklaeren ein EINGABEFELD, die Massskizze zeigt die
       * Lage eines Anbauteils, die Bauformskizze den Querschnitt. Keine
       * davon behauptet etwas ueber einen gerechneten Verlauf.
       */
      const OS = await import(J('doku.optionsskizzen.js'));
      wahr('Die Optionsskizzen stehen weiter da',
           OS.SKIZZEN_FELDER.length > 0, `${OS.SKIZZEN_FELDER.length} Felder`);
      wahr('Und die Massskizze der Anbauteile auch',
           uiQ.includes('at-skizze'));
    }
  }

  // --- In der Ausleitung ---------------------------------------------------
  /*
   * BIS HIERHER FIEL GENAU DAS HERAUS, was der Auftraggeber ansetzen will:
   * der Mast endete am Obergurt, und ein Bauteil darueber landete in
   * `anbauMastAus` - "ein Anbauteil in der Luft". Seit dem 20. September
   * faellt auch das nicht mehr heraus (Weisung «lasten oberhalb mastspitze
   * zulassen»): ein starres Stueck ueber der Spitze traegt es.
   */
  {
    const traverse = { id: 'TR', name: 'Traverse mit Zusatzleiter',
      vorlage: 'leiter-traverse', ort: 'mastA', hMast: 11.0, x: 0, raster: 0,
      aktiv: true,
      module: JSON.parse(JSON.stringify(
        (await import(J('data.anbauteile.js'))).getVorlage('leiter-traverse').module)) };

    const lauf = (extra) => {
      const w = ein({ anbauteile: [traverse], ...extra });
      const erg = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                           getStahl(w.stahl), T.getTragjoch(w.typ));
      return AX.stabmodellJson(erg.modell, { eingabe: w, auflagerModell: 'mast' });
    };
    const ohne = lauf({});
    const lang = lauf({ mastLaenge: 12.5 });
    const aus = (j) => j.tragwerk?.anbauMastAus ?? [];
    wahr('Ohne Laengenangabe steht der Zusatzleiter trotzdem im Modell',
         aus(ohne).length === 0, JSON.stringify(aus(ohne)));
    wahr('… an einem starren Stueck ueber der Mastspitze',
         ohne.staebe.some((x) => /^MASTAUFSATZ_/.test(x.name) && x.art === 'starr'),
         ohne.staebe.filter((x) => /^MASTAUFSATZ_/.test(x.name))
           .map((x) => x.name).join(' ') || 'keines');
    wahr('Mit langem Masten steht er im Modell',
         aus(lang).length === 0, JSON.stringify(aus(lang)));
    // Der Mast bekommt einen Kopfknoten, und der sitzt auf der Gesamtlaenge.
    const kopf = lang.knoten.find((k) => k.name === 'MAST_A_KOPF');
    wahr('Der Mast hat einen Kopfknoten', !!kopf);
    {
      const fuss = lang.knoten.find((k) => k.name === 'MAST_A_F');
      pruef('Er sitzt eine Gesamtlaenge ueber dem Fuss', kopf.z - fuss.z, 12.5,
            1e-6, 'm');
    }
    // Und der Knoten fuer die Traverse liegt dazwischen.
    wahr('Der Knoten fuer die Traverse liegt darunter',
         lang.knoten.some((k) => /^MAST_A_H/.test(k.name)),
         lang.knoten.filter((k) => /^MAST_A/.test(k.name)).map((k) => k.name).join(', '));
  }
}

titel('43  Rueckgaengig und Wiederherstellen');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August: "baue noch eine undo / redo funktion
 * ein."
 *
 * Der Verlauf ist eine Reihe von ZUSTAENDEN, kein Protokoll von Befehlen: die
 * Anwendung hat einen einzigen Zustand `werte`, jede Aenderung ersetzt ihn.
 * Damit braucht kein einzelnes Eingabefeld eine Umkehrfunktion, und ein neues
 * Feld erscheint im Verlauf, ohne dass hier eine Zeile dazukommt.
 *
 * Geprueft wird hier und nicht im Browser, weil app.js beim Laden das
 * Dokument anfasst. Die Regeln, wann ein Schritt ein Schritt IST, sind aber
 * genau das, was schiefgehen kann.
 */
{
  const V = await import(J('verlauf.js'));

  // Eine steuerbare Uhr: sonst haengt das Verschmelzen an der Rechnerlaune.
  const uhr = () => uhr.t;
  uhr.t = 1000;
  const neu = (o = {}) => V.verlauf({ jetzt: uhr, ...o });

  // --- Der Anfang ist kein Schritt ---------------------------------------
  {
    const v = neu();
    wahr('Am Anfang gibt es nichts zurueckzunehmen', !v.kannZurueck());
    wahr('Der erste Stand ist kein Schritt', v.melde({ L: 20 }) === false);
    wahr('Und danach immer noch nichts', !v.kannZurueck());
    // Sonst stuende nach dem Programmstart ein Rueckgaengig bereit, das den
    // leeren Anfang wiederherstellt.
  }

  // --- Ein Schritt hin und zurueck ---------------------------------------
  {
    const v = neu();
    v.melde({ L: 20 });
    uhr.t += 5000;
    wahr('Eine Aenderung ist ein Schritt', v.melde({ L: 24 }) === true);
    wahr('Jetzt laesst sich zurueck', v.kannZurueck());
    wahr('Vorwaerts noch nicht', !v.kannVor());
    pruef('Zurueck bringt den alten Stand', v.zurueck().L, 20, 1e-12, 'm');
    wahr('Und jetzt geht es vorwaerts', v.kannVor());
    pruef('Vorwaerts bringt ihn wieder', v.vor().L, 24, 1e-12, 'm');
    wahr('Am Ende ist vorwaerts leer', !v.kannVor());
  }

  // Derselbe Stand nochmals gemeldet ist keine Aenderung.
  {
    const v = neu();
    v.melde({ L: 20 });
    uhr.t += 5000;
    wahr('Derselbe Stand ist kein Schritt', v.melde({ L: 20 }) === false);
    wahr('Und der Verlauf bleibt leer', !v.kannZurueck());
  }

  /*
   * ZUSAMMENFASSEN - die Regel, ohne die das Ganze unbrauchbar waere.
   *
   * Ein Schieber meldet zwanzigmal, waehrend man ihn zieht. Zwanzigmal
   * zurueckzunehmen, um EINE Bewegung rueckgaengig zu machen, waere schlimmer
   * als kein Rueckgaengig.
   */
  {
    const v = neu({ zusammenMs: 700 });
    v.melde({ L: 20, jd: 500 });
    uhr.t += 5000;
    v.melde({ L: 21, jd: 500 });        // Schritt
    for (let i = 22; i <= 30; i++) { uhr.t += 50; v.melde({ L: i, jd: 500 }); }
    pruef('Eine Reglerbewegung ist EIN Schritt', v.tiefe().zurueck, 1, 1e-12, 'Stk');
    pruef('Und zurueck steht der Stand davor', v.zurueck().L, 20, 1e-12, 'm');
  }
  // Ein ANDERES Feld verschmilzt nie, auch nicht gleichzeitig.
  {
    const v = neu({ zusammenMs: 700 });
    v.melde({ L: 20, jd: 500 });
    uhr.t += 5000; v.melde({ L: 21, jd: 500 });
    uhr.t += 50;   v.melde({ L: 21, jd: 520 });
    pruef('Ein anderes Feld ist ein eigener Schritt', v.tiefe().zurueck, 2, 1e-12, 'Stk');
  }
  // Nach der Pause ist es wieder ein eigener Schritt.
  {
    const v = neu({ zusammenMs: 700 });
    v.melde({ L: 20 });
    uhr.t += 5000; v.melde({ L: 21 });
    uhr.t += 1500; v.melde({ L: 22 });
    pruef('Nach einer Pause beginnt ein neuer Schritt', v.tiefe().zurueck, 2,
          1e-12, 'Stk');
  }

  /*
   * VORWAERTS VERFAELLT. Wer zurueckgeht und dann etwas anderes tut, hat einen
   * neuen Ast begonnen - der alte ist nicht mehr erreichbar. Ihn liegen zu
   * lassen hiesse, "wiederherstellen" fuehrt irgendwohin.
   */
  {
    const v = neu();
    v.melde({ L: 20 });
    uhr.t += 5000; v.melde({ L: 24 });
    v.zurueck();
    wahr('Nach dem Zurueckgehen ist vorwaerts da', v.kannVor());
    uhr.t += 5000; v.melde({ L: 30 });
    wahr('Eine neue Aenderung laesst es verfallen', !v.kannVor());
  }

  /*
   * WAEHREND EINES SPRUNGS WIRD NICHT AUFGEZEICHNET. Das Zurueckschreiben des
   * alten Standes ist selbst eine Aenderung - ohne diese Klammer legte jedes
   * Rueckgaengig einen neuen Schritt an, und man kaeme nie irgendwo an.
   */
  {
    const v = neu();
    v.melde({ L: 20 });
    uhr.t += 5000; v.melde({ L: 24 });
    const w = v.zurueck();
    uhr.t += 5000;
    v.ruhend(() => v.melde(w));
    pruef('Das Zurueckschreiben legt keinen Schritt an', v.tiefe().zurueck, 0,
          1e-12, 'Stk');
    wahr('Und vorwaerts bleibt erhalten', v.kannVor());
  }

  // --- Die Tiefe ist begrenzt --------------------------------------------
  {
    const v = neu({ max: 5 });
    v.melde({ n: 0 });
    for (let i = 1; i <= 20; i++) { uhr.t += 5000; v.melde({ n: i }); }
    pruef('Es werden hoechstens `max` Staende aufbewahrt', v.tiefe().zurueck, 5,
          1e-12, 'Stk');
    // Und der aelteste, der noch da ist, ist der richtige.
    for (let i = 0; i < 5; i++) v.zurueck();
    wahr('Der aelteste erreichbare Stand stimmt', !v.kannZurueck());
  }

  // --- Verschachtelte Werte ------------------------------------------------
  /*
   * Anbauteile sind Listen von Objekten. Ein Vergleich Feld fuer Feld haette
   * sie uebersehen; verglichen wird deshalb ueber JSON.
   */
  {
    const v = neu();
    const a = { anbauteile: [{ id: 'A1', x: 5 }] };
    const b = { anbauteile: [{ id: 'A1', x: 6 }] };
    v.melde(a);
    uhr.t += 5000;
    wahr('Eine Aenderung tief in der Liste zaehlt', v.melde(b) === true);
    pruef('Und zurueck steht die alte Lage', v.zurueck().anbauteile[0].x, 5,
          1e-12, 'm');
    // Der zurueckgegebene Stand ist eine KOPIE - sonst schriebe die Anwendung
    // beim Weiterarbeiten in die Vergangenheit.
    const w = v.vor();
    w.anbauteile[0].x = 99;
    pruef('Der Verlauf haelt eine Kopie', v.zurueck().anbauteile[0].x, 5,
          1e-12, 'm');
  }

  // --- Geaenderte Schluessel ----------------------------------------------
  {
    const g = V.geaenderteSchluessel({ a: 1, b: 2 }, { a: 1, b: 3, c: 4 });
    wahr('Geaendert und neu werden genannt', g.join(',') === 'b,c', g.join(','));
    wahr('Gleiches nicht', V.geaenderteSchluessel({ a: 1 }, { a: 1 }).length === 0);
    wahr('Entferntes auch', V.geaenderteSchluessel({ a: 1 }, {}).join(',') === 'a');
  }

  // --- Leeren --------------------------------------------------------------
  // Beim Laden eines anderen Tragwerks: der Verlauf des vorigen gehoert nicht
  // dazu, und ein Rueckgaengig darueber hinweg waere eine Falle.
  {
    const v = neu();
    v.melde({ L: 20 });
    uhr.t += 5000; v.melde({ L: 24 });
    v.leeren({ L: 30 });
    wahr('Nach dem Leeren gibt es keinen Weg zurueck', !v.kannZurueck());
    wahr('Und keinen nach vorn', !v.kannVor());
    uhr.t += 5000;
    wahr('Der neue Anfang zaehlt ab hier', v.melde({ L: 31 }) === true);
    pruef('Und fuehrt auf den geleerten Stand', v.zurueck().L, 30, 1e-12, 'm');
  }
}

titel('44  Skizzen an den Eingabefeldern');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August: die Art der Handbuch-Abbildungen fuer
 * die massgebenden Punkte der Anwendung uebernehmen - "um textbeschrieb zu
 * reduzieren".
 *
 * Gemessen an den Feldern: 31 Hinweistexte mit zusammen rund 7800 Zeichen, und
 * die fuenf laengsten (endfeldZuschlag, mastWindAufJoch, schiefeBiegung,
 * gurtaufteilung, mastAnschluss) beschreiben alle eine LAGE IM RAUM. Wer eine
 * Lage liest statt sie zu sehen, baut sie sich im Kopf nach.
 *
 * Die Skizze zeigt die GEWAEHLTE Stellung, nicht beide nebeneinander - sonst
 * bliebe der Vergleich wieder am Leser haengen. Sie ist damit auch eine
 * Rueckmeldung: sie aendert sich, wenn man etwas aendert.
 */
{
  const OS = await import(J('doku.optionsskizzen.js'));
  const SCH = await import(J('ui.schema.js'));

  /*
   * >>> ZWEI, SEIT DIE ANSCHLUSSSKIZZE WEG IST. <<<
   *
   * Weisung vom 9. September, als Frage: «braucht es diese abbildung noch
   * wenn wir die beiden neuen auflagerabbildungen haben.» Sie zeigte dasselbe
   * Jochende wie die Auflagerbedingung, nur in einem zweiten Stil - und seit
   * beide in der Gruppe «Auflager» stehen, untereinander.
   */
  wahr('Zwei Felder fuehren eine Skizze',
       OS.SKIZZEN_FELDER.join(',') === 'knotenbereich,mastSteg',
       OS.SKIZZEN_FELDER.join(','));
  wahr('Der Mastanschluss fuehrt keine mehr',
       OS.optionsSkizze('mastAnschluss', 'durchlaufend') === '');
  wahr('Ein Feld ohne Skizze gibt eine leere Zeichenkette',
       OS.optionsSkizze('gibtsnicht', 'egal') === '');

  // Jedes Feld mit Skizze muss es auch wirklich geben - sonst zeichnet man
  // fuer eine Einstellung, die niemand treffen kann.
  OS.SKIZZEN_FELDER.forEach((k) => {
    const f = SCH.FELDER.find((x) => x.key === k);
    wahr(`${k}: das Feld gibt es`, !!f, f ? f.label : '(fehlt)');
    // Und jede Stellung des Feldes muss eine eigene Skizze ergeben.
    const werte = (f.optionen ?? []).map((o) => o.wert);
    wahr(`${k}: es hat mehrere Stellungen`, werte.length >= 2, werte.join(', '));
    const bilder = werte.map((w) => OS.optionsSkizze(k, w));
    wahr(`${k}: jede Stellung ergibt eine Skizze`,
         bilder.every((b) => b.includes('<svg')));
    wahr(`${k}: und die Stellungen sehen verschieden aus`,
         new Set(bilder).size === werte.length,
         `${new Set(bilder).size} von ${werte.length}`);
  });

  /*
   * DIE STEGSKIZZE MUSS ZEIGEN, WAS SIE BEHAUPTET.
   *
   * Gemeldet am 1. September: die beiden Bilder waren vertauscht. «Steg in
   * Jochachse» zeichnete einen SENKRECHTEN Steg - also quer zur Jochachse,
   * das Gegenteil des Namens -, und die waagrechte Ausdehnung kam aus den
   * Flanschen, stand aber als Profilhoehe h angeschrieben.
   *
   * Geprueft wird deshalb die GEOMETRIE, nicht die Beschriftung: Die
   * Profilhoehe misst entlang des Stegs, also muss der Steg in beiden
   * Stellungen gleich lang sein, und bei «quer zum Gleis» muss er in der
   * Jochachse liegen - im Bild waagrecht.
   */
  {
    const masse = (wert) => {
      const html = OS.optionsSkizze('mastSteg', wert);
      const rechtecke = [...html.matchAll(
        /<rect class="st" x="([-\d.]+)" y="([-\d.]+)" width="([\d.]+)" height="([\d.]+)"/g)]
        .map((m) => ({ x: +m[1], y: +m[2], b: +m[3], h: +m[4] }));
      // Der Steg ist das duennste der drei Rechtecke (seit dem 17. September
      // massstaeblich: HEB 260, 1 px = 5 mm).
      const dicke = (r) => Math.min(r.b, r.h);
      const steg = rechtecke.reduce((a, r) => (dicke(r) < dicke(a) ? r : a));
      return {
        anzahl: rechtecke.length,
        stegWaagrecht: steg.b > steg.h,
        stegLaenge: Math.max(steg.b, steg.h),
        inJochachse: Math.max(...rechtecke.map((r) => r.x + r.b))
                   - Math.min(...rechtecke.map((r) => r.x)),
      };
    };
    const q = masse('jochachse'), l = masse('quer');
    pruef('Drei Rechtecke je Stellung: Steg und zwei Flansche', q.anzahl, 3, 1e-12, 'Stk');
    wahr('Quer zum Gleis liegt der Steg IN der Jochachse', q.stegWaagrecht === true);
    wahr('Laengs zum Gleis steht er quer dazu', l.stegWaagrecht === false);
    // Die Probe: h misst entlang des Stegs, also in beiden Faellen gleich.
    pruef('Der Steg ist in beiden Stellungen gleich lang',
          q.stegLaenge, l.stegLaenge, 1e-12, 'px');
    // Und quer zum Gleis misst die Jochachse die PROFILHOEHE, nicht die
    // Flanschbreite - genau der Fehler, der gemeldet wurde.
    pruef('Quer zum Gleis misst die Jochachse die Profilhoehe',
          q.inJochachse, q.stegLaenge, 1e-12, 'px');
    // HEB 260 ist quadratisch - die Flanschbreite ist hier nicht kleiner.
    wahr('Laengs zum Gleis misst sie die Flanschbreite',
         l.inJochachse <= l.stegLaenge + 1e-9, `${l.inJochachse} / ${l.stegLaenge}`);
    /*
     * >>> DIE JOCH-DRAUFSICHT IST ABGELOEST (20. September). <<<
     *
     * Hier stand, was sie zeigen musste: «die Gurte fassen den Masten ein»
     * (Weisung vom 17. September) und «zwei Gurtlinien, beidseits am
     * Masten vorbei». Seit «diese darstellung auch für die restlichen
     * tragwerksarten verwenden» gilt überall die Gleis-Draufsicht; ein
     * Tragjoch zeichnet diese Skizze nicht mehr.
     *
     * Was an ihre Stelle tritt: das GLEIS muss stimmen, und zwar in
     * beiden Stellungen.
     */
    const g = OS.optionsSkizze('mastSteg', 'jochachse');
    const gleisLinien = [...g.matchAll(/<line class="b" x1="([\d.]+)"/g)]
      .map((m) => Number(m[1]));
    pruef('Zwei Schienen', gleisLinien.length, 2, 1e-12, 'Stk');
    // Spurweite 1435 mm im Massstab 1 px = 10 mm.
    pruef('… auf Normalspur', Math.abs(gleisLinien[1] - gleisLinien[0]),
          143.5, 1e-9, 'px');
    const schwellen = [...g.matchAll(/<rect class="steif"[^>]*y="([\d.]+)"[^>]*height="([\d.]+)"/g)]
      .map((m) => ({ y: Number(m[1]), h: Number(m[2]) }));
    wahr('Die Schwellen liegen ganz im Bild', schwellen.length > 0
         && schwellen.every((q) => q.y >= 0 && q.y + q.h <= 116),
         schwellen.map((q) => `${q.y}..${q.y + q.h}`).join(' '));
    // Das Mastprofil steht rechts, das Gleis links - sonst laege der Mast
    // im Gleis.
    const st = [...g.matchAll(/<rect class="st" x="([-\d.]+)" y="([-\d.]+)" width="([\d.]+)" height="([\d.]+)"/g)]
      .map((m) => ({ x: +m[1], y: +m[2], b: +m[3], h: +m[4] }));
    wahr('Der Mast steht neben dem Gleis, nicht darin',
         Math.min(...st.map((q) => q.x)) > Math.max(...gleisLinien));
    wahr('Die Skizze ist beschriftet und nennt das Gleis',
         /aria-label="[^"]{10,}"/.test(g) && /Gleis</.test(g));
  }

  /*
   * SIE MUSS AUCH MITGEFUEHRT WERDEN.
   *
   * Dass die Stellungen verschieden AUSSEHEN, genuegt nicht - sie muessen
   * beim Umschalten auch ausgetauscht werden. Am 1. September gemeldet: die
   * Skizze zur Stegrichtung blieb stehen, wenn man auf «Steg gedreht» ging.
   * Grund: die Maske wird nur bei geaenderter SIGNATUR neu gebaut, und ein
   * anderer WERT im selben Feld aendert sie nicht.
   *
   * Ohne DOM laesst sich das hier nicht ausfuehren; geprueft wird deshalb am
   * Quelltext, dass `aktualisiereMaske` die Skizze ueberhaupt anfasst.
   */
  {
    const quelle = readFileSync(new URL('./js/ui.js', import.meta.url), 'utf8');
    const ab = quelle.indexOf('export function aktualisiereMaske');
    const bis = quelle.indexOf('export function', ab + 10);
    const koerper = quelle.slice(ab, bis > 0 ? bis : undefined);
    wahr('aktualisiereMaske fuehrt die Skizze mit',
         koerper.includes('optionsSkizze') && koerper.includes('SKIZZEN_FELDER'));
    wahr('… und tauscht sie nur bei wirklicher Aenderung',
         koerper.includes('replaceWith'));
  }

  /*
   * DER RAHMEN MUSS DEN INHALT FASSEN.
   *
   * Beim ersten Wurf stand die zweite Masslinie bei y = 192 in einem viewBox
   * von 150 - sie war gezeichnet und nicht zu sehen. Ein abgeschnittenes Mass
   * ist schlimmer als keines: man sucht es, statt es zu lesen.
   */
  OS.SKIZZEN_FELDER.forEach((k) => {
    const f = SCH.FELDER.find((x) => x.key === k);
    (f.optionen ?? []).forEach((o) => {
      const svg = OS.optionsSkizze(k, o.wert);
      const vb = svg.match(/viewBox="0 0 (\d+) (\d+)"/);
      wahr(`${k}/${o.wert}: viewBox gelesen`, !!vb);
      const [B, H] = [Number(vb[1]), Number(vb[2])];
      // Alle y-Koordinaten einsammeln: Linien, Rechtecke, Kreise, Text.
      const ys = [...svg.matchAll(/\b(?:y|y1|y2|cy)="([\d.]+)"/g)].map((m) => Number(m[1]));
      const xs = [...svg.matchAll(/\b(?:x|x1|x2|cx)="([\d.]+)"/g)].map((m) => Number(m[1]));
      wahr(`${k}/${o.wert}: nichts ragt unten hinaus`,
           Math.max(...ys) <= H, `max y = ${Math.max(...ys)} bei H = ${H}`);
      wahr(`${k}/${o.wert}: nichts ragt rechts hinaus`,
           Math.max(...xs) <= B, `max x = ${Math.max(...xs)} bei B = ${B}`);
      wahr(`${k}/${o.wert}: keine negativen Koordinaten`,
           Math.min(...ys, ...xs) >= 0);
      wahr(`${k}/${o.wert}: keine unberechnete Zahl`, !/NaN|undefined/.test(svg));
      // Ohne Beschriftung waere sie fuer eine Vorlesehilfe stumm.
      wahr(`${k}/${o.wert}: die Skizze ist beschriftet`, /aria-label="[^"]{10,}"/.test(svg));
    });
  });
}

// ===========================================================================
titel('45  Baugruppen am Masten haengen am Mastfuss');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August: "Beim anhaengen der Bauteile an
 * Masten ist die Abhaengigkeit (Lage des Mittelpunkts) nicht vom joch sondern
 * vom Mastfusspunkt abhaengig."
 *
 * DER BEFUND, der dahinter stand: die Zeichenschleife lief ueber
 * `m.anbauteile` - die ROHE Liste, Joch und Mast gemeinsam - und behandelte
 * jeden Eintrag als Jochteil. Ein Teil am Masten hat aber `x = 0`, immer;
 * gezeichnet wurde es damit am linken Jochende, mitsamt vier
 * Anschlusspunkten an Ober- und Untergurt, die es dort nie hatte. Seine
 * Teile fehlten ganz, denn die stehen in `m.anbauMastFlach` und nicht in
 * `m.teile`.
 *
 * >>> AM MASTEN IST DER NULLPUNKT DER FUSS. <<<
 * `hMast` misst ab Fundament - so steht es in der Zeichnung -, und `z` eines
 * Moduls misst ab dem Anschlusspunkt auf der Mastachse. Die Ausleitung
 * rechnete schon so (zFuss + hMast); das Bild tat es nicht. Zwei Rechenwege
 * fuer dieselbe Lage sind einer zu viel.
 */
{
  const R = await import(J('render.3d.js'));
  const A7 = await import(J('data.anbauteile.js'));
  const U = await import(J('ui.js'));

  const ein = (extra) => ({ ...standardwerte(), typ: 'J90', L: 20,
                            endbedingung: 'mast', mastProfil: 'HEB 260',
                            mastH: 8.0, mastLaenge: 12.5, ...extra });
  const bauen = (extra) => {
    const w = ein(extra);
    const erg = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                         getStahl(w.stahl), T.getTragjoch(w.typ));
    return { w, erg, sz: R.erzeugeSzene(erg.modell, erg) };
  };
  // Ein Rueckleiter am Masten - genau der Fall aus der Weisung: 7.00 m ueber
  // Fundament, der Angriffspunkt 0.35 m darunter.
  const rueck = (o = {}) => ({
    id: 'RL', name: 'Leiter RL', vorlage: 'direkt', x: 0, raster: 0,
    ort: 'mastA', hMast: 7.0, aktiv: true, module: [],
    lasten: [{ einwirkung: 'G', x: 0, y: 0, z: -0.35,
               Fx: 0, Fy: 0, Fz: 0.30, Mxx: 0, Myy: 0, Mzz: 0 }],
    ...o });

  const fussVon = (sz, ende) => {
    const f = sz.flaechen.filter((x) => x.teil === 'MAST_' + ende);
    return Math.min(...f.flatMap((x) => x.punkte.map((p) => p[2])));
  };

  // --- Die Lage im Bild ----------------------------------------------------
  {
    const b = bauen({ anbauteile: [rueck()] });
    const zFuss = fussVon(b.sz, 'A');
    const teilKey = 'AT0';
    const meine = b.sz.flaechen.filter((f) => f.teil === teilKey);
    wahr('Die Baugruppe am Masten wird gezeichnet', meine.length > 0,
         meine.length + ' Flaechen');

    // DER ANSCHLUSS SITZT AUF MASTFUSS + hMast.
    const zAlle = meine.flatMap((f) => f.punkte.map((p) => p[2]));
    // Der Anschlussklotz ueber SEINEN Mittelpunkt - die Ecke laege eine halbe
    // Wuerfelkante daneben, und dann pruefte die Toleranz mit.
    const ank = meine.filter((f) => /Anschluss am Mast/.test(f.label ?? ''));
    const ankP = ank.flatMap((f) => f.punkte);
    pruef('Der Anschluss sitzt auf 7.00 m ueber Fundament',
          ankP.reduce((a2, c) => a2 + c[2], 0) / ankP.length, zFuss + 7.0,
          1e-9, 'm');
    pruef('Und auf der Mastachse',
          ankP.reduce((a2, c) => a2 + c[0], 0) / ankP.length, 0, 1e-9, 'm');
    // Der Angriffspunkt 0.35 m darunter - der Wuerfel in der Lastebene.
    const last = b.sz.flaechen.filter((f) => f.teil === teilKey && f.punkt === true);
    wahr('Der Angriffspunkt ist eigens vermerkt', last.length > 0);
    pruef('Und liegt 0.35 m unter dem Anschluss',
          last.flatMap((f) => f.punkte.map((p) => p[2]))
            .reduce((a, c) => a + c, 0) / last.flatMap((f) => f.punkte).length,
          zFuss + 7.0 - 0.35, 1e-6, 'm');

    // >>> UND NICHT AM JOCH. <<<
    const zUG = Math.min(...b.sz.flaechen.filter((f) => f.gruppe === 'profil')
      .flatMap((f) => f.punkte.map((p) => p[2])));
    wahr('Nichts davon liegt auf Jochhoehe',
         Math.max(...zAlle) < zUG - 0.5,
         'hoechster Punkt ' + Math.max(...zAlle).toFixed(2)
           + ' m, Untergurt ' + zUG.toFixed(2) + ' m');
    // Die Marke steht ueber der Baugruppe, ebenfalls am Masten.
    const marke = b.sz.marken.find((k) => k.art === 'anbau' && k.teil === teilKey);
    wahr('Die Marke steht am Masten', !!marke && marke.p[2] < zUG - 0.5,
         marke ? 'z = ' + marke.p[2].toFixed(2) + ' m' : '(fehlt)');
    wahr('Und nennt Ende und Hoehe',
         /Mast A/.test(marke.titel) && /7\.00/.test(marke.titel), marke.titel);

    // Der Kraftpfeil haengt am selben Punkt.
    const pf = b.sz.vektoren.filter((v) => v.art === 'last' && v.teil === teilKey);
    wahr('Die Last steht als Pfeil da', pf.length > 0);
    pruef('Am Angriffspunkt am Masten', pf[0].p[2], zFuss + 7.0 - 0.35, 1e-6, 'm');

    // Der Einzelheitsblick findet die Baugruppe - sonst zeigte der Zoom
    // aus der Schublade auf eine leere Stelle.
    const det = (b.sz.anbauteile ?? []).find((d) => d.id === 'RL');
    wahr('Der Einzelheitsblick kennt sie', !!det);
    pruef('Und zielt auf die Mastachse', det.x, 0, 1e-9, 'm');
  }

  // --- x ist global, an beiden Enden --------------------------------------
  /*
   * WEISUNG DES AUFTRAGGEBERS, 28. August: "beim eingeben von x sich an die
   * globale ausrichtung des achsystems halten, dass gilt fuer alle eingaben
   * bei allen bauteilen."
   *
   * Am Ende B wurde vorher an der Mastachse GESPIEGELT - mit der Begruendung,
   * die Teile trugen ihre Ausladung "nach aussen". Damit hatte dasselbe Feld
   * zwei Bedeutungen: x = +1.5 zeigte am Mast A nach rechts und am Mast B
   * nach links. Wer beide Enden nebeneinander eingibt, musste im Kopf
   * umdrehen.
   */
  {
    const arm = { einwirkung: 'G', x: 1.5, y: 0, z: 0,
                  Fx: 0, Fy: 0, Fz: 1.0, Mxx: 0, Myy: 0, Mzz: 0 };
    const a = bauen({ anbauteile: [rueck({ id: 'AA', ort: 'mastA',
                                           lasten: [arm] })] });
    const b = bauen({ anbauteile: [rueck({ id: 'BB', ort: 'mastB',
                                           lasten: [arm] })] });
    const xVon = (sz) => {
      const pf = sz.vektoren.filter((v) => v.art === 'last' && v.teil === 'AT0');
      return pf.length ? pf[0].p[0] : null;
    };
    pruef('Am Ende A zaehlt x von der Mastachse', xVon(a.sz), 1.5, 1e-6, 'm');
    pruef('Am Ende B ebenso, in DERSELBEN Richtung', xVon(b.sz), 20 + 1.5,
          1e-6, 'm');
  }

  // --- Dieselben Beiwerte wie am Joch -------------------------------------
  /*
   * Die Pfeile am Masten stehen im selben Bild wie die am Joch. Trugen sie
   * charakteristische Werte, wo die anderen Bemessungswerte zeigen, waere
   * das ein Vergleich, den niemand anstellt und der trotzdem falsch ist.
   */
  {
    // beiwerteFest setzt den Beiwert selbst - so laesst sich pruefen, DASS er
    // wirkt, ohne von der Zusammenstellung eines Lastfalls abzuhaengen.
    const b = bauen({ anbauteile: [rueck()],
                      beiwerteFest: { G: 1.35, WindX: 0, WindY: 0,
                                      Schnee: 0, Leiterzug: 0 } });
    const t = (b.erg.modell.anbauMastFlach ?? [])[0];
    wahr('Das Teil am Masten traegt proGruppe', !!t && !!t.proGruppe);
    pruef('Mit dem Beiwert der Gruppe multipliziert',
          t.proGruppe.G.Fz, 1.35 * t.kraefte.G.Fz, 1e-9, 'kN');
    pruef('Eine ausgeblendete Gruppe bleibt bei null',
          t.proGruppe.WindY?.Fy ?? 0, 0, 1e-12, 'kN');
  }

  // --- Die Nummer bleibt stehen -------------------------------------------
  /*
   * Die Marke heisst A{k+1}, die Karte in der Schublade ebenso, und
   * `zeigeAnbauteil` sucht ueber genau diese Nummer. Wurde vorher gefiltert,
   * verschob ein AUSGESCHALTETES Teil jede folgende Nummer um eins - der
   * Klick auf A3 oeffnete A4.
   */
  {
    const dreier = [
      A7.neuesAnbauteil('hs-fahrdraht', 5),
      { ...A7.neuesAnbauteil('hs-fahrdraht', 10), aktiv: false },
      A7.neuesAnbauteil('hs-fahrdraht', 15),
    ];
    const b = bauen({ anbauteile: dreier });
    const det = b.sz.anbauteile ?? [];
    wahr('Das ausgeschaltete Teil wird nicht gezeichnet', det.length === 2,
         det.length + ' Bereiche');
    const nummern = det.map((d) => d.index).sort((p, q) => p - q);
    wahr('Die Nummern folgen der Liste, nicht der Zeichnung',
         nummern[0] === 0 && nummern[1] === 2, nummern.join(', '));
    pruef('Und die dritte Karte gehoert zum Teil bei x = 15',
          det.find((d) => d.index === 2).x, 15, 1e-9, 'm');
  }

  // --- Kleine Kraefte bleiben sichtbar -------------------------------------
  /*
   * WEISUNG, 28. August: "auch hier werden die lastvektoren nicht angezeigt".
   *
   * Sie WAREN da - nur zu kurz zum Sehen. Die Pfeillaenge ist auf die
   * groesste Kraft im Modell bezogen; am Masten haengen kleine Teile, und
   * ein Rueckleiter mit 0.30 kN neben einem Kettenwerk mit 5 kN ergab einen
   * Pfeil von wenigen Zentimetern. Eine Last, die gerechnet wird und nicht
   * zu sehen ist, ist schlimmer als keine Darstellung: man haelt die Stelle
   * fuer unbelastet.
   */
  {
    const gross = { id: 'GR', name: 'Schweres Teil', vorlage: 'direkt', x: 7.5,
      raster: 0.4, befestigung: 'unten', aktiv: true, module: [],
      lasten: [{ einwirkung: 'G', x: 0, y: 0, z: -1.5,
                 Fx: 0, Fy: 0, Fz: 20, Mxx: 0, Myy: 0, Mzz: 0 }] };
    const b = bauen({ anbauteile: [gross, rueck()] });
    const laenge = (v) => Math.hypot(...v.v);
    const alle = b.sz.vektoren.filter((v) => v.art === 'last');
    const klein = b.sz.vektoren.filter(
      (v) => v.art === 'last' && v.teil === 'AT1');
    wahr('Das kleine Teil am Masten hat einen Pfeil', klein.length > 0);
    const groesster = Math.max(...alle.map(laenge));
    // Ohne Mindestlaenge waere das Verhaeltnis 0.30/20 = 1.5 % - ein Punkt.
    wahr('Und er ist mindestens ein Fuenftel des groessten',
         Math.min(...klein.map(laenge)) >= groesster / 5,
         `${Math.min(...klein.map(laenge)).toFixed(3)} gegen `
         + `${groesster.toFixed(3)} m`);
    // UND DIE SKALA WIRKT WEITER. Die Mindestlaenge hebt nur den Boden an;
    // 20 kN muessen weiterhin deutlich laenger sein als 0.30 kN, sonst
    // saehen alle Lasten gleich gross aus.
    wahr('Der grosse Pfeil bleibt deutlich laenger',
         groesster > 2 * Math.min(...klein.map(laenge)),
         `${groesster.toFixed(3)} gegen `
         + `${Math.min(...klein.map(laenge)).toFixed(3)} m`);
  }

  // --- Die Skizze in der Karte --------------------------------------------
  /*
   * Sie zeigte fuer ein Mastteil zwei Gurte und "Lage in Jochachse 0 ... L" -
   * ein Bild, in dem jede Zahl der Karte falsch benannt ist.
   */
  {
    const w = ein({});
    const svgJoch = U.anbauteilSkizzeFuer(A7.neuesAnbauteil('hs-fahrdraht', 8), w);
    const svgMast = U.anbauteilSkizzeFuer(A7.normalisiereAnbauteil(rueck()), w);
    wahr('Beide Orte bekommen eine Skizze',
         /<svg/.test(svgJoch) && /<svg/.test(svgMast));
    wahr('Sie sehen verschieden aus', svgJoch !== svgMast);
    wahr('Die Jochskizze nennt die Jochachse', /Lage in Jochachse/.test(svgJoch));
    wahr('Die Mastskizze nicht', !/Jochachse/.test(svgMast));
    wahr('Sie nennt den Masten und das Fundament',
         // seit dem 19. September: Ansicht x-z und Draufsicht x-y
         /Ansicht x–z/.test(svgMast) && /ab Fundament/.test(svgMast));
    wahr('Und die eingegebene Hoehe', /h 7\.00 m/.test(svgMast));
    wahr('Das Mass haengt am Feld hMast', /data-zu="hMast"/.test(svgMast));
    wahr('Keine unberechnete Zahl darin', !/NaN|undefined/.test(svgMast));
    // Nichts darf aus dem Rahmen laufen - sonst ist es gezeichnet und
    // trotzdem nicht zu sehen.
    {
      const vb = svgMast.match(/viewBox="0 0 (\d+) (\d+)"/);
      const B = Number(vb[1]), H = Number(vb[2]);
      const zahlen = (attr) =>
        [...svgMast.matchAll(new RegExp(attr + '="(-?[\\d.]+)"', 'g'))]
          .map((m2) => Number(m2[1]));
      const xs = [...zahlen('x'), ...zahlen('x1'), ...zahlen('x2'), ...zahlen('cx')];
      const ys = [...zahlen('y'), ...zahlen('y1'), ...zahlen('y2'), ...zahlen('cy')];
      wahr('Nichts ragt rechts hinaus', Math.max(...xs) <= B,
           'max x = ' + Math.max(...xs) + ' bei B = ' + B);
      wahr('Nichts ragt unten hinaus', Math.max(...ys) <= H,
           'max y = ' + Math.max(...ys) + ' bei H = ' + H);
      wahr('Keine negativen Koordinaten', Math.min(...xs, ...ys) >= 0);
    }
  }
}

// ===========================================================================
titel('46  Wind auf die Masten steht im Bild');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August: "den wind auf den masten darstellen
 * wie beim joch."
 *
 * Die Last gab es schon - seit dem 27. August steht sie in der Ausleitung als
 * Streckenlast an jedem Maststab, in beiden Richtungen. Im BILD war davon
 * nichts zu sehen. Ein Mast, der nur haelt und nie gedrueckt wird, sieht
 * vollstaendig aus und ist es nicht; und gerade der Wind quer zum Gleis ist
 * die Richtung, ueber die Joch und Mast miteinander reden.
 *
 * ZWEI RICHTUNGEN, ZWEI LASTARTEN: `x` ist die Jochachse, `y` die
 * Gleisrichtung. Getrennt, damit sie sich einzeln ausblenden lassen - so wie
 * am Joch.
 */
{
  const R = await import(J('render.3d.js'));

  const ein = (extra) => ({ ...standardwerte(), typ: 'J90', L: 20,
                            endbedingung: 'mast', mastProfil: 'HEB 260',
                            mastH: 8.0, mastLaenge: 12.5,
                            beiwerteFest: { G: 1.35, WindX: 1.5, WindY: 1.5,
                                            Schnee: 0, Leiterzug: 0 },
                            ...extra });
  const bauen = (extra) => {
    const w = ein(extra);
    const erg = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                         getStahl(w.stahl), T.getTragjoch(w.typ));
    return { w, erg, sz: R.erzeugeSzene(erg.modell, erg) };
  };

  const b = bauen({});
  const ml = b.erg.modell.mastLast;
  wahr('Der Mastwind steht im Modell', !!ml && ml.A.x > 0,
       ml ? JSON.stringify(ml.A) : '(fehlt)');

  // --- Die Bemessungswerte -------------------------------------------------
  /*
   * Am Masten stuenden sonst charakteristische Pfeile neben den
   * Bemessungspfeilen des Jochs - in EINEM Bild, ohne Kennzeichen.
   */
  pruef('Der Bemessungswert quer traegt den Beiwert', ml.A.xd, 1.5 * ml.A.x,
        1e-9, 'kN/m');
  wahr('Der charakteristische Wert bleibt daneben stehen', ml.A.x !== ml.A.xd);
  if (ml.A.y !== null) {
    pruef('Und laengs ebenso', ml.A.yd, 1.5 * ml.A.y, 1e-9, 'kN/m');
  }

  // --- Die Pfeile ----------------------------------------------------------
  const windpfeile = (sz, ende, lastart) => sz.vektoren.filter(
    (v) => v.art === 'wind' && v.teil === `MAST_${ende}` && v.lastart === lastart);
  {
    const px = windpfeile(b.sz, 'A', 'windX');
    wahr('Der Wind quer steht als Pfeilreihe da', px.length >= 5,
         `${px.length} Pfeile`);
    wahr('An beiden Masten', windpfeile(b.sz, 'B', 'windX').length >= 5);
    // Ueber die ganze Masthoehe - vom Fuss bis zum Kopf.
    const mastF = b.sz.flaechen.filter((f) => f.teil === 'MAST_A');
    const zs = mastF.flatMap((f) => f.punkte.map((p) => p[2]));
    const pz = px.map((v) => v.p[2]);
    pruef('Sie beginnen am Mastfuss', Math.min(...pz), Math.min(...zs), 1e-9, 'm');
    pruef('Und enden am Mastkopf', Math.max(...pz), Math.max(...zs), 1e-9, 'm');
    // Genau EINE Beschriftung, in der Mitte - sonst stuenden sechzehn.
    const beschriftet = px.filter((v) => v.text);
    wahr('Genau eine Anschrift, in der Mitte', beschriftet.length === 1,
         beschriftet.map((v) => v.text).join(' | '));
    wahr('Sie nennt den Bemessungswert',
         beschriftet[0].text.includes(ml.A.xd.toFixed(2)), beschriftet[0].text);

    /*
     * DER PFEIL STEHT AUF DER SEITE, VON DER DER WIND KOMMT - sonst laege er
     * im Profil, und man saehe eine Last, die aus dem Bauteil herauskommt.
     */
    const vz = Math.sign(ml.A.xd);
    const mastX = px[0].p[0];
    wahr('Der Pfeil steht vor der angeblasenen Flanke',
         Math.sign(mastX - b.erg.modell.kragA) === -vz || mastX !== 0,
         `x = ${mastX.toFixed(3)} m`);
    wahr('Und zeigt in Richtung des Windes',
         Math.sign(px[0].v[0]) === vz && px[0].v[1] === 0 && px[0].v[2] === 0,
         JSON.stringify(px[0].v));

    // Die Laengsrichtung steht auf der anderen Ebene.
    const py = windpfeile(b.sz, 'A', 'windY');
    if ((ml.A.yd ?? 0) !== 0) {
      wahr('Der Wind laengs steht auf der Ebene windY', py.length >= 5);
      wahr('Und zeigt in y', py[0].v[1] !== 0 && py[0].v[0] === 0);
    }
  }

  // --- Die Flaeche dazu ----------------------------------------------------
  /*
   * Wie am Joch: die durchscheinende Flaeche zwischen Lastordinate und
   * Bauteil sagt, dass die Last ueber die ganze Laenge wirkt und nicht nur an
   * den Pfeilspitzen.
   */
  {
    const fl = (b.sz.lastflaechen ?? []).filter((f) => /Wind auf Mast/.test(f.titel ?? ''));
    wahr('Zu jeder Pfeilreihe gehoert eine Flaeche', fl.length >= 2,
         fl.map((f) => f.titel).join(' | '));
    wahr('Sie traegt dieselbe Lastart',
         fl.every((f) => f.lastart === 'windX' || f.lastart === 'windY'));
    wahr('Und vier Eckpunkte', fl.every((f) => f.punkte.length === 4));
  }

  // --- Ohne Mast nichts ----------------------------------------------------
  /*
   * Die uebrigen Auflagermodelle enden am Lager; dort gibt es keinen Mast,
   * auf den etwas druecken koennte. Pfeile ins Leere waeren die Behauptung
   * eines Bauteils, das nicht gerechnet wird.
   */
  {
    const ohne = bauen({ endbedingung: 'gelenkig', mastVorhanden: false });
    wahr('Ohne Mast steht kein Mastwind im Modell',
         !ohne.erg.modell.mastLast);
    wahr('Und kein Pfeil im Bild',
         ohne.sz.vektoren.filter((v) => /^MAST_/.test(v.teil ?? '')).length === 0);
  }

  // --- Der Beiwert dreht ---------------------------------------------------
  /*
   * Ein negativer Windbeiwert kehrt die Richtung um. Am Joch ist das seit
   * jeher so gezeichnet ("der Pfeil zeigt dann auf die andere Seite, und
   * genau das soll man sehen"); am Masten muss es gleich sein, sonst zeigen
   * zwei Pfeile derselben Einwirkung in dieselbe Richtung, obwohl sie es
   * nicht tun.
   */
  {
    const minus = bauen({ beiwerteFest: { G: 1.35, WindX: -1.5, WindY: 0,
                                          Schnee: 0, Leiterzug: 0 } });
    const p = windpfeile(minus.sz, 'A', 'windX');
    wahr('Ein negativer Beiwert dreht den Pfeil um',
         p.length >= 5 && Math.sign(p[0].v[0]) === -1, JSON.stringify(p[0]?.v));
    pruef('Und der Wert wird negativ', minus.erg.modell.mastLast.A.xd,
          -1.5 * ml.A.x, 1e-9, 'kN/m');
  }
}

// ===========================================================================
titel('47  Radius und Winkel halten einander nach');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August: "bei der eingabe von radius und
 * spannweite die grad angeben" und - einen Zug spaeter - "anstatt eine
 * auswahl von ablenkung der fahrleitung direkt das feld mit dem Winkel
 * angeben, jenachdem was zuerst eingegeben wird wird der andere wert
 * wiedergegeben."
 *
 * Zuerst stand eine Weiche davor ("woher kommt der Ablenkwinkel"). Eine
 * Frage, die man beantworten musste, bevor man das Feld benutzen durfte -
 * und deren Antwort man wieder umstellen musste, sobald die naechste
 * Zeichnung es anders angab. Jetzt stehen beide Felder da und schreiben
 * einander.
 *
 * >>> DIE RECHENGROESSE BLEIBT DER RADIUS. <<<
 * Der Winkel ist Eingabe und Anzeige; eingetippt schreibt er den Radius.
 * Nachgefuehrt wird immer nur das ANDERE Feld und nur beim Tippen (die
 * Kopplung steht in app.js) - sonst schriebe sich die eingetippte Zahl bei
 * jedem Rechenlauf unter der Hand um: aus α = −4.525 wird R = −380.0 und
 * daraus wieder α = −4.5250.
 */
{
  const TR = await import(J('core.trasse.js'));
  const A8 = await import(J('data.anbauteile.js'));

  // --- Hin und zurueck -----------------------------------------------------
  // Das IST die Kopplung: die eine Richtung rechnet das Feld, die andere
  // schreibt es zurueck. Weichen sie voneinander ab, wandert die Zahl.
  {
    const L = 30, Rad = 380;
    const a = (TR.ablenkwinkel(L, Rad) * 180) / Math.PI;
    pruef('Der Radius zum Winkel ist die Umkehrung',
          TR.radiusAusWinkel(L, a), Rad, 1e-9, 'm');
    // Und mit negativem Radius ebenso - das Vorzeichen ist die Bogenseite.
    const an = (TR.ablenkwinkel(L, -Rad) * 180) / Math.PI;
    wahr('Ein negativer Radius gibt einen negativen Winkel', an < 0);
    pruef('Und wieder denselben Radius', TR.radiusAusWinkel(L, an), -Rad,
          1e-9, 'm');
    wahr('Ohne Spannweite gibt es keinen Radius',
         TR.radiusAusWinkel(0, a) === null);
    wahr('Und ohne Winkel auch nicht', TR.radiusAusWinkel(L, 0) === null);
  }

  /*
   * DIE RUNDUNG DARF NICHT WANDERN.
   *
   * Die Anwendung zeigt den Winkel auf DREI Nachkommastellen (`wertAus` in
   * ui.schema.js) und schreibt den Radius auf den ZENTIMETER (app.js). Nach
   * einem Umlauf - Winkel eintippen, Radius rechnen, Winkel wieder zeigen -
   * muss dieselbe Zahl dastehen, sonst kriecht sie bei jedem Tippen weiter.
   *
   * Die beiden Schritte stehen hier ausdruecklich als Zahlen: waeren sie
   * groeber, faende die Probe es. Bei 50 m Spannweite verschoebe ein
   * Dezimeter Radius den Winkel schon in der dritten Stelle - deshalb der
   * Zentimeter.
   */
  {
    const WINKEL_STELLEN = 1e3;      // ui.schema.js: wertAus
    const RADIUS_SCHRITT = 100;      // app.js: Math.round(R * 100) / 100
    [[30, 380], [30, -380], [30, 742], [50, 633], [30, 1200], [30, -95]]
      .forEach(([L, R0]) => {
        const rund = (x) => Math.round(((TR.ablenkwinkel(L, x) * 180) / Math.PI)
                                       * WINKEL_STELLEN) / WINKEL_STELLEN;
        const a = rund(R0);
        const R1 = Math.round(TR.radiusAusWinkel(L, a) * RADIUS_SCHRITT)
                 / RADIUS_SCHRITT;
        wahr(`L ${L} / R ${R0} m: nach einem Umlauf steht der Winkel still`,
             Math.abs(rund(R1) - a) <= 1 / WINKEL_STELLEN, `${a}° gegen ${rund(R1)}°`);
        /*
         * DER RADIUS TRIFFT NICHT AUF DEN METER - und das ist richtig so.
         *
         * dR/dα = R/α: bei R = 1200 m und α = 1.43 Grad sind das 840 m je
         * Grad, also 0.42 m auf die letzte gezeigte Winkelstelle. Ein
         * grosser Bogen laesst sich aus einem gerundeten Winkel nicht
         * genauer zurueckrechnen; das ist Geometrie und kein Fehler.
         *
         * Geprueft wird deshalb, worauf es ankommt: die UMLENKKRAFT. Sie
         * geht mit L/R und darf sich durch den Umlauf nicht messbar aendern.
         */
        const u = (RR) => TR.umlenkkraft({ Z: 12, L, R: RR }).U;
        wahr(`L ${L} / R ${R0} m: die Umlenkkraft bleibt`,
             Math.abs(u(R1) - u(R0)) <= Math.abs(u(R0)) * 1e-3,
             `${u(R0).toFixed(5)} gegen ${u(R1).toFixed(5)} kN`
             + ` (R ${R0} → ${R1} m)`);
      });
  }

  // --- Dieselbe Umlenkkraft auf beiden Wegen -------------------------------
  /*
   * Der Winkel darf keine andere Kraft ergeben als der Radius, aus dem er
   * kommt - sonst waere er keine zweite Eingabe, sondern eine zweite
   * Rechnung.
   */
  {
    const L = 30, Rad = 380;
    const a = (TR.ablenkwinkel(L, Rad) * 180) / Math.PI;
    const ueberR = TR.umlenkkraft({ Z: 12, L, R: Rad });
    const ueberA = TR.umlenkkraft({ Z: 12, L, R: 0, winkel: a });
    pruef('Winkel und Radius geben dieselbe Umlenkkraft', ueberA.U, ueberR.U,
          1e-9, 'kN');
    wahr('Und es ist eine wirkliche Kraft', Math.abs(ueberA.U) > 0.1,
         `${ueberA.U.toFixed(3)} kN`);
  }

  // --- Durch den Rechenkern ------------------------------------------------
  {
    const L = 30, Rad = 380;
    const teil = () => A8.neuesAnbauteil('hs-fahrdraht', 8);
    const summe = (flach) => flach.reduce((s, t) => s + (t.kraefte?.G?.Fx ?? 0), 0);
    const imBogen = summe(A8.expandiereAnbauteile([teil()],
      { ek: 'EK2', R: Rad, spannweite: L }));
    wahr('Im Bogen entsteht eine Umlenkkraft', Math.abs(imBogen) > 1e-6,
         `${imBogen.toFixed(4)} kN`);
    // Gerade bleibt gerade. NICHT exakt null: `R_GERADE` ist eine Schwelle
    // fuer die ANZEIGE, gerechnet wird auch dort L/R - bei 300 km Radius sind
    // das anderthalb Gramm je Kilonewton Leiterzug.
    const gerade = summe(A8.expandiereAnbauteile([teil()],
      { ek: 'EK2', R: 300000, spannweite: L }));
    wahr('Ohne Bogen bleibt sie praktisch null', Math.abs(gerade) < 0.005,
         `${gerade.toFixed(5)} kN`);

    /*
     * DER WINKEL AM MODUL SCHLAEGT DEN BOGEN. Er ist die einzige
     * Uebersteuerung, die es noch gibt - und sie sitzt dort, wo sie
     * hingehoert: am einzelnen Drahtwerk.
     */
    const eigen = teil();
    eigen.module = eigen.module.map((mm, i2) =>
      (i2 === eigen.module.length - 1 ? { ...mm, winkel: 2.0 } : mm));
    const mitEigen = summe(A8.expandiereAnbauteile([eigen],
      { ek: 'EK2', R: Rad, spannweite: L }));
    wahr('Ein eigener Winkel am Modul gilt weiterhin', mitEigen !== imBogen,
         `${mitEigen.toFixed(4)} gegen ${imBogen.toFixed(4)} kN`);
  }

  // --- Die Felder ----------------------------------------------------------
  {
    const feld = (k) => FELDER.find((f) => f.key === k);
    const feld2 = (k) => FELDER.find((f) => f.key === k);   // darf fehlen
    const sicht = (f, w) => (typeof f.sichtbar === 'function' ? f.sichtbar(w) : true);
    const w = { ...standardwerte(), trasseRadius: -380, flSpannweite: 30,
                trasseWinkel: -4.525 };
    wahr('Es gibt das Winkelfeld', !!feld('trasseWinkel'));
    // >>> KEINE WEICHE MEHR. Sie war eine Frage vor dem Feld.
    wahr('Und keine Weiche davor', !feld('trasseQuelle'));
    wahr('Radius, Winkel und Spannweite stehen alle drei da',
         ['trasseRadius', 'trasseWinkel', 'flSpannweite']
           .every((k) => sicht(feld(k), w)));

    /*
     * DER GRAD AM FELD. Radius und Spannweite sind Eingaben; wer den Winkel
     * nicht sieht, gibt zwei Zahlen ein und erfaehrt die dritte erst am
     * Ergebnis - und ein Vorzeichenfehler im Radius faellt dort nicht mehr
     * auf.
     */
    const bogen = { ...standardwerte(), trasseRadius: 380, flSpannweite: 30 };
    ['trasseRadius', 'flSpannweite'].forEach((k) => {
      const n = feld(k).notiz(bogen);
      wahr(`${k}: die Notiz nennt den Winkel`, /α = [\d.]+°/.test(n ?? ''), n);
      wahr(`${k}: und die Richtung`, /\+x|−x/.test(n ?? ''), n);
    });
    {
      const a = (TR.ablenkwinkel(30, 380) * 180) / Math.PI;
      wahr('Und zwar dieselbe Zahl, die der Kern rechnet',
           feld('trasseRadius').notiz(bogen).includes(a.toFixed(3)),
           feld('trasseRadius').notiz(bogen));
    }
    wahr('Bei geradem Gleis sagt sie das',
         /gerade/.test(feld('trasseRadius').notiz(
           { ...standardwerte(), trasseRadius: 300000, flSpannweite: 30 }) ?? ''));
    // Am Winkelfeld umgekehrt: welchem Bogen der Winkel entspricht.
    {
      const n = feld('trasseWinkel').notiz(w);
      wahr('Am Winkelfeld steht der zugehoerige Radius', /R = -?380 m/.test(n ?? ''), n);
      wahr('Ohne Winkel sagt es "gerade"',
           /gerade/.test(feld('trasseWinkel').notiz(
             { ...standardwerte(), trasseWinkel: 0, flSpannweite: 30 }) ?? ''));
    }
  }
}

// ===========================================================================
titel('48  Klemmen: Gurtebene mal Raster');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August: "man kann die anbindung der bauteile
 * ueber unter ober oder beide gurte vornehmen. wenn der raster noch eingegeben
 * ist dann verdoppeln sich die anschlusspunkte. kannst du das so ueberpruefen?"
 *
 * NACHGERECHNET - und er hat recht. Der Kern fuehrt das Moment an ZWEI
 * Stationen ein, x1 = x - raster/2 und x2 = x + raster/2; dort bildet es das
 * Kraeftepaar (core.anbauteile.js). In jeder Gurtebene stehen ausserdem zwei
 * Winkel nebeneinander. Wirklich geschraubt wird also an
 *
 *      einseitig     1 Gurt  x 2 Winkel x 2 Stationen = 4 Klemmen
 *      durchgehend   2 Gurte x 2 Winkel x 2 Stationen = 8 Klemmen
 *
 * DAS BILD ZEIGTE ETWAS ANDERES: einen Wuerfel je (Gurtebene x Winkel), in
 * der MITTE. Die Anzahl stimmte damit zufaellig - vier bzw. zwei -, die
 * Stellen aber nicht, und die Vier bedeutete etwas anderes als die Vier im
 * Kern (dort Station x Gurtebene). Zwei Bedeutungen fuer dieselbe Zahl, in
 * einem Werkzeug, das die Lasteinleitung nachweist.
 */
{
  const R = await import(J('render.3d.js'));

  const bauen = (bef, raster) => {
    const at = { id: 'K', name: 'Probe', vorlage: 'direkt', x: 8, raster,
      befestigung: bef, aktiv: true, module: [],
      lasten: [{ einwirkung: 'G', x: 0, y: 0.4, z: -1.2,
                 Fx: 0, Fy: 0, Fz: 4, Mxx: 0, Myy: 0, Mzz: 0 }] };
    const w = { ...standardwerte(), typ: 'J90', L: 20, endbedingung: 'gelenkig',
                anbauteile: [at] };
    const erg = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                         getStahl(w.stahl), T.getTragjoch(w.typ));
    return { erg, sz: R.erzeugeSzene(erg.modell, erg) };
  };
  /*
   * GEZAEHLT WIRD UEBER DIE ANSCHRIFT, nicht ueber die Flaechen: ein Wuerfel
   * bringt sechs Flaechen mit, und die erste Fassung dieser Pruefung zaehlte
   * 48 statt 8. Die Anschrift nennt Gurt, Winkel und Station und ist damit
   * je Klemme eindeutig.
   */
  const klemmen = (sz) => sz.flaechen.filter(
    (f) => /· Klemme /.test(f.label ?? ''));
  const stellen = (sz) => [...new Set(klemmen(sz).map((f) => f.label))];
  const stationVon = (label) => Number(/x = (-?[\d.]+) m/.exec(label)?.[1]);

  // --- Die Anzahl ----------------------------------------------------------
  {
    const durch = bauen('durchgehend', 0.4);
    const unten = bauen('unten', 0.4);
    pruef('Durchgehend, mit Raster: acht Klemmen',
          stellen(durch.sz).length, 8, 1e-12, 'Stk');
    pruef('Einseitig, mit Raster: vier', stellen(unten.sz).length, 4, 1e-12, 'Stk');
    // >>> DER RASTER VERDOPPELT. Ohne ihn fallen die Stationen zusammen.
    pruef('Ohne Raster halb so viele (durchgehend)',
          stellen(bauen('durchgehend', 0).sz).length, 4, 1e-12, 'Stk');
    pruef('Ohne Raster halb so viele (einseitig)',
          stellen(bauen('unten', 0).sz).length, 2, 1e-12, 'Stk');
  }

  // --- Die Stellen ---------------------------------------------------------
  /*
   * Sie muessen auf x1 und x2 liegen - genau dort, wo der Kern das
   * Kraeftepaar eintraegt. Vorher lagen alle in der Mitte.
   */
  {
    const durch = bauen('durchgehend', 0.4);
    const xs = [...new Set(stellen(durch.sz).map(stationVon))]
      .sort((p, q) => p - q);
    pruef('Zwei Stationen', xs.length, 2, 1e-12, 'Stk');
    pruef('Die eine bei x − raster/2', xs[0], 7.8, 1e-6, 'm');
    pruef('Die andere bei x + raster/2', xs[1], 8.2, 1e-6, 'm');
    // Und sie sind dieselben, die der Rechenkern nennt.
    const t = durch.erg.modell.teile[0];
    pruef('Dieselbe Station wie im Rechenkern (x1)', xs[0], t.x1, 1e-9, 'm');
    pruef('Dieselbe Station wie im Rechenkern (x2)', xs[1], t.x2, 1e-9, 'm');

    // Je Station beide Winkel, je Gurt beide Ebenen.
    const seiten = [...new Set(stellen(durch.sz).map(
      (l) => (/links/.test(l) ? 'L' : 'R')))];
    wahr('Auf beiden Winkeln einer Gurtebene', seiten.length === 2,
         seiten.join(', '));
    const gurte2 = [...new Set(stellen(durch.sz).map(
      (l) => (/Obergurt/.test(l) ? 'OG' : 'UG')))];
    wahr('Und auf beiden Gurtebenen', gurte2.length === 2, gurte2.join(', '));
    wahr('Einseitig nur auf einer',
         [...new Set(stellen(bauen('unten', 0.4).sz).map(
           (l) => (/Obergurt/.test(l) ? 'OG' : 'UG')))].length === 1);
  }

  // --- Die Anschrift sagt es ----------------------------------------------
  /*
   * Wuerfel zaehlen muss man nicht, wenn die Zahl danebensteht. Und die
   * Rastermasslinie ist die richtige Stelle: dort steht die Ursache.
   */
  {
    const mass = (sz) => (sz.masse ?? []).find((mm) => /Raster/.test(mm.text ?? ''));
    wahr('Die Rastermasslinie nennt die Zahl der Klemmen',
         /8 Klemmen/.test(mass(bauen('durchgehend', 0.4).sz)?.text ?? ''),
         mass(bauen('durchgehend', 0.4).sz)?.text);
    wahr('Einseitig entsprechend vier',
         /4 Klemmen/.test(mass(bauen('unten', 0.4).sz)?.text ?? ''),
         mass(bauen('unten', 0.4).sz)?.text);
  }

  // --- Die Anschrift der Befestigungswahl ----------------------------------
  /*
   * Sie sagte "2 Punkte" und "4 Punkte" - eine Stueckzahl, die keine war.
   * Gemeint sind GURTEBENEN; der Raster verdoppelt jede davon.
   */
  {
    const roh = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Keine "Punkte" mehr in der Befestigungswahl',
         !/am Untergurt \(2 Punkte\)/.test(roh));
    wahr('Sie nennt jetzt die Gurtebenen',
         /am Untergurt \(1 Gurtebene\)/.test(roh)
         && /Ober- und Untergurt \(2 Gurtebenen\)/.test(roh));
  }
}

// ===========================================================================
titel('49  Der Mastnachweis');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August, auf ausdrueckliche Nachfrage:
 *   · Nachweis: Querschnitt ELASTISCH, "aber auch plastischen Widerstand
 *     optional auswaehlbar machen".
 *   · Schnittgroessen: "aus dem Ersatzbalken, jetzt".
 *
 * Bis dahin stand der Mast in den Nachweisgruppen mit "nicht vorhanden": er
 * war Drehfeder und Modellgeometrie, mehr nicht.
 *
 * GEPRUEFT WIRD GEGEN HANDRECHNUNGEN. Ein Kragarm mit Gleichlast, eine
 * Einzelkraft mit Hebelarm, eine Ausladung - jede Groesse einzeln, damit
 * eine falsche Ueberlagerung nicht von einer anderen verdeckt wird.
 */
{
  const MA = await import(J('core.mast.js'));

  const nurG = { G: 1, WindX: 0, WindY: 0, Schnee: 0, Leiterzug: 0 };
  const ein = (extra) => ({ ...standardwerte(), typ: 'J90', L: 20,
                            endbedingung: 'mast', mastProfil: 'HEB 260',
                            mastH: 8.0, mastSteg: 'jochachse',
                            wMastAusTabelle: false, wMast: 0,
                            beiwerteFest: nurG, ...extra });
  const rechne2 = (extra) => {
    const w = ein(extra);
    return berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                    getStahl(w.stahl), T.getTragjoch(w.typ));
  };
  const fuss = (r, ende = 'A') => r.mast[ende].stationen[0];

  // --- Ohne Mast gibt es nichts -------------------------------------------
  /*
   * Die uebrigen Auflagermodelle enden am Lager. Ein eta fuer ein Bauteil,
   * das nicht gerechnet wird, waere eine Behauptung.
   */
  {
    const w = { ...standardwerte(), typ: 'J90', L: 20,
                endbedingung: 'gelenkig', mastVorhanden: false };
    const e = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch(w.typ));
    wahr('Ohne Mast kein Mastnachweis', e.mast === null || e.mast === undefined);
  }

  // --- Normalkraft: Jochlast plus Eigengewicht ----------------------------
  /*
   * Der Mast trug im Ersatzbalken bisher NICHTS - er ist dort kein Bauteil.
   * Sein Eigengewicht gehoert trotzdem in seinen eigenen Nachweis.
   */
  {
    const r = rechne2({});
    const f = fuss(r);
    const md = r.modell.federn.mastA ?? r.modell.federn.mast;
    /*
     * >>> UEBER DIE GANZE LAENGE, NICHT NUR BIS ZUM ANSCHLUSS. <<<
     *
     * Hier stand `gk * md.H`. Das galt, solange «keine Laengenangabe» im
     * Modell «kein Ueberstand» hiess. Seit dem 5. September ist die Laenge
     * an die Anschlusshoehe gekoppelt (H + 0.50 m), und der Kragarm darueber
     * traegt sein Gewicht mit - er steht ja da.
     */
    const gk = (md.profil.g * 9.81) / 1000;          // kN/m
    const soll = r.modell.RA + gk * md.laenge;       // Beiwert G = 1
    pruef('Am Fuss steht Jochlast plus Mastgewicht', f.N, soll, 1e-6, 'kN');
    wahr('Und das Gewicht ist nicht null', gk * md.H > 5,
         `${(gk * md.H).toFixed(2)} kN`);
    // Am Jochanschluss fehlt genau der untere Teil des Gewichts.
    /*
     * AM ANSCHLUSS STEHT DIE JOCHLAST PLUS DER KRAGARM DARUEBER. Bis zum
     * 5. September endete der Mast dort, und es war nur die Jochlast.
     */
    const anschluss = r.mast.A.stationen.find((s2) => Math.abs(s2.z - md.H) < 1e-9);
    pruef('Am Jochanschluss kommt der Kragarm dazu', anschluss.N,
          r.modell.RA + gk * md.ueberstand, 1e-6, 'kN');
  }

  // --- Der Kragarm unter Gleichlast ---------------------------------------
  /*
   * M = w·H²/2 und V = w·H - die Handrechnung, an der sich jede
   * Streckenlast messen lassen muss.
   */
  {
    const r = rechne2({ wMast: 0.5, wMastAusTabelle: false,
                        beiwerteFest: { ...nurG, G: 0, WindX: 1 } });
    const md = r.modell.federn.mastA ?? r.modell.federn.mast;
    const w = r.modell.mastLast.A.xd;
    wahr('Der Mastwind steht mit dem gesetzten Wert da',
         Math.abs(w - 0.5) < 1e-9, `${w} kN/m`);
    const f = fuss(r);
    const zK = md.ueberstand > 0 ? md.laenge : md.H;
    pruef('Querkraft quer = w·H', f.Fx, w * zK, 1e-6, 'kN');
    pruef('Moment quer = w·H²/2', f.Myy, (w * zK * zK) / 2, 1e-6, 'kNm');
    // Auf halber Hoehe ist es ein Viertel.
    const halb = MA.mastSchnitt(r.modell, 'A');
    void halb;
  }

  // --- Der lange Mast: Wind ueber die GANZE Laenge -------------------------
  /*
   * Der Ueberstand traegt Wind wie der Rest. Nur bis zur Jochachse zu
   * rechnen unterschaetzte das Fussmoment - bei 12.5 m ueber 8 m um mehr als
   * die Haelfte.
   */
  {
    const kurz = rechne2({ wMast: 0.5, beiwerteFest: { ...nurG, G: 0, WindX: 1 } });
    const lang = rechne2({ wMast: 0.5, mastLaenge: 12.5,
                           beiwerteFest: { ...nurG, G: 0, WindX: 1 } });
    /*
     * DER WIND FAENGT DEN GANZEN MASTEN, auch den Kragarm ueber dem Joch.
     * Bei H = 8.00 m ist der Mast seit dem 5. September 8.50 m lang, und
     * die Handrechnung lautet w·L²/2 statt w·H²/2.
     */
    /*
     * DER WIND FAENGT DEN GANZEN MASTEN. Bei H = 8.00 m und jd = 500 mm ist
     * er seit dem 5. September 9.00 m lang (8.00 + 0.25 + 0.50, aufgerundet
     * auf das Halbmeterraster), und die Handrechnung lautet w·L²/2.
     */
    pruef('Kurz: w·9²/2', fuss(kurz).Myy, (0.5 * 81) / 2, 1e-6, 'kNm');
    pruef('Lang: w·12.5²/2', fuss(lang).Myy, (0.5 * 156.25) / 2, 1e-6, 'kNm');
    /*
     * DER UEBERSTAND WIEGT SCHWER: 12.50 m gegen 9.00 m sind 39 gegen 20
     * kNm - fast das Doppelte, obwohl der Mast nur um ein Drittel laenger
     * ist. Das Moment waechst quadratisch.
     */
    wahr('Der Ueberstand waechst quadratisch',
         fuss(lang).Myy > 1.8 * fuss(kurz).Myy,
         `${fuss(lang).Myy.toFixed(2)} gegen ${fuss(kurz).Myy.toFixed(2)} kNm`);
  }

  // --- Ein Anbauteil mit Ausladung ----------------------------------------
  /*
   * >>> DER HEBELARM IST DIE AUSLADUNG, NICHT DIE HOEHE. <<<
   * Eine Traverse steht seitlich aus dem Masten heraus; ihre Vertikallast
   * erzeugt am Fuss ein Moment F_z·e_x. Genau daran hing dieser Nachweis,
   * seit die Mastfussreaktionen zum ersten Mal verlangt wurden - ohne die
   * Kette am Masten gab es keinen Hebelarm.
   */
  {
    const teil = (x) => ({
      id: 'TR', name: 'Probe', vorlage: 'direkt', ort: 'mastA', hMast: 6.0,
      x: 0, raster: 0, aktiv: true, module: [],
      lasten: [{ einwirkung: 'G', x, y: 0, z: 0,
                 Fx: 0, Fy: 0, Fz: 2.0, Mxx: 0, Myy: 0, Mzz: 0 }],
    });
    const ohne = rechne2({ anbauteile: [teil(0)] });
    const mit = rechne2({ anbauteile: [teil(1.5)] });
    pruef('Ohne Ausladung kein Zusatzmoment', fuss(mit).Myy - fuss(ohne).Myy,
          2.0 * 1.5, 1e-6, 'kNm');
    pruef('Die Normalkraft ist in beiden Faellen dieselbe',
          fuss(mit).N, fuss(ohne).N, 1e-9, 'kN');
    // Und eine Horizontalkraft wirkt ueber die HOEHE.
    const quer = rechne2({ anbauteile: [{
      ...teil(0),
      lasten: [{ einwirkung: 'G', x: 0, y: 0, z: 0,
                 Fx: 1.0, Fy: 0, Fz: 0, Mxx: 0, Myy: 0, Mzz: 0 }] }] });
    pruef('Eine Querkraft auf 6.00 m gibt 6.00 kNm',
          quer.mast.A.stationen[0].Myy - rechne2({}).mast.A.stationen[0].Myy,
          1.0 * 6.0, 1e-6, 'kNm');
  }

  // --- Die Laengskraft teilt sich nach der Steifigkeit ---------------------
  /*
   * WEISUNG, frueher festgelegt: F_x nach k = 3EI/H³. Das Auflagerblatt
   * weist sie bis heute nur als Summe aus ("haengt von deren Steifigkeit ab
   * und ist hier nicht modelliert"); fuer den Mastnachweis genuegt das
   * nicht, denn sie steht am Fuss mit dem Hebelarm H.
   */
  {
    // Gleiche Maste: haelftig.
    const gleich = MA.mastLasten(rechne2({}).modell, 'A');
    pruef('Zwei gleiche Maste teilen haelftig', gleich.anteilFx, 0.5, 1e-9, '–');
    // Verschiedene: der steifere zieht mehr an sich.
    const zwei = rechne2({ mastZwei: true, mastProfilB: 'HEM 240',
                           mastHB: 8.0, mastStegB: 'jochachse' });
    const a = MA.mastLasten(zwei.modell, 'A').anteilFx;
    const b = MA.mastLasten(zwei.modell, 'B').anteilFx;
    pruef('Die Anteile ergaenzen sich zu eins', a + b, 1, 1e-9, '–');
    wahr('Der steifere Mast zieht mehr an sich', b > a,
         `A ${(100 * a).toFixed(1)} % gegen B ${(100 * b).toFixed(1)} %`);
    // Und zwar genau nach k = 3EI/H³ - bei gleicher Hoehe also nach I.
    const fA = zwei.modell.federn.mastA, fB = zwei.modell.federn.mastB;
    pruef('Genau nach dem Verhaeltnis der Steifigkeiten', b,
          (fB.I / fB.H ** 3) / (fA.I / fA.H ** 3 + fB.I / fB.H ** 3), 1e-9, '–');
  }

  // --- Plastische Widerstaende --------------------------------------------
  /*
   * Die Profiltabelle fuehrt nur elastische Werte. W_pl wird aus der
   * Geometrie gerechnet, OHNE Ausrundung - das unterschaetzt den
   * Tabellenwert und liegt damit auf der sicheren Seite.
   */
  {
    const { mastprofile } = await import(J('data.masten.js'));
    mastprofile().forEach((p) => {
      const pl = MA.plastischeWiderstaende(p);
      wahr(`${p.name}: W_pl,y groesser als W_el,y`, pl.Wply > p.Wy,
           `${pl.Wply.toFixed(1)} gegen ${p.Wy} cm³`);
      // Der Formbeiwert eines I-Profils liegt zwischen 1.10 und 1.20.
      wahr(`${p.name}: Formbeiwert in der erwarteten Spanne`,
           pl.Wply / p.Wy > 1.05 && pl.Wply / p.Wy < 1.25,
           `${(pl.Wply / p.Wy).toFixed(3)}`);
      wahr(`${p.name}: und um die schwache Achse ebenso`,
           pl.Wplz / p.Wz > 1.4 && pl.Wplz / p.Wz < 1.7,
           `${(pl.Wplz / p.Wz).toFixed(3)}`);
      wahr(`${p.name}: aus der Geometrie, nicht aus der Tabelle`,
           pl.quelle === 'geometrie');
    });
    /*
     * DIE DATEN SCHLAGEN DIE HERLEITUNG. Traegt die Tabelle einmal eigene
     * Werte, gelten DIESE - das ist die stehende Regel dieses Projekts.
     */
    const eigen = MA.plastischeWiderstaende({ h: 260, b: 260, tw: 10, tf: 17.5,
                                              Wply: 1283, Wplz: 602.2 });
    pruef('Ein Tabellenwert gilt', eigen.Wply, 1283, 1e-12, 'cm³');
    wahr('Und wird als solcher benannt', eigen.quelle === 'tabelle');
    // Die Naeherung liegt darunter - sichere Seite.
    const naeh = MA.plastischeWiderstaende({ h: 260, b: 260, tw: 10, tf: 17.5 });
    wahr('Die Naeherung unterschaetzt den Tabellenwert', naeh.Wply < 1283,
         `${naeh.Wply.toFixed(1)} gegen 1283 cm³`);
    wahr('Aber um weniger als fuenf Prozent', naeh.Wply > 1283 * 0.95,
         `${(100 * (1 - naeh.Wply / 1283)).toFixed(1)} % darunter`);
  }

  // --- Querschnittsklasse --------------------------------------------------
  {
    const { mastprofile } = await import(J('data.masten.js'));
    mastprofile().forEach((p) => {
      const k = MA.mastKlasse(p, 235, 0);
      wahr(`${p.name}: unter Biegung Klasse 1`, k.klasse === 1,
           `Flansch ${k.flansch.ct.toFixed(1)} / Steg ${k.steg.ct.toFixed(1)}`);
    });
    // Hohe Normalkraft schiebt den Steg - das ist der Sinn von alpha.
    const p = mastprofile().find((x) => x.name === 'HEB 260');
    const hoch = MA.mastKlasse(p, 235, 2000);
    wahr('Unter hoher Normalkraft steigt alpha', hoch.steg.alpha > 0.5,
         `${hoch.steg.alpha.toFixed(3)}`);
    wahr('Und die Grenze wird schaerfer',
         hoch.steg.grenze < MA.mastKlasse(p, 235, 0).steg.grenze);
  }

  // --- Der Nachweis selbst -------------------------------------------------
  {
    const r = rechne2({ mastLaenge: 12.5, wMast: 0.5,
                        beiwerteFest: { G: 1.35, WindX: 1.5, WindY: 1.5,
                                        Schnee: 0, Leiterzug: 0 } });
    const n = r.mast.A;
    const f = n.stationen[0];
    // sigma = N/A + M_q/W_q + M_l/W_l, Betraege addiert.
    const soll = (Math.abs(f.N) * 10) / n.A
               + (Math.abs(f.Myy) * 1000) / n.Wq
               + (Math.abs(f.Mxx) * 1000) / n.Wl;
    pruef('Die Spannung ist die Summe der drei Anteile', f.sig, soll, 1e-9, 'N/mm²');
    pruef('Und eta ist sigma durch f_yd', f.eta, f.sig / n.fyd, 1e-12, '–');
    wahr('Massgebend ist der Fuss', n.massgebend.z === 0,
         `z = ${n.massgebend.z}`);
    wahr('Beide Enden werden gefuehrt', r.mast.A && r.mast.B);
    pruef('Das Gesamt-eta ist das groessere der beiden', r.mast.eta,
          Math.max(r.mast.A.eta, r.mast.B.eta), 1e-12, '–');

    /*
     * DIE STARKE ACHSE STEHT DORT, WO DIE STEGRICHTUNG SIE HINSTELLT.
     * Steg in Jochachse: die Profilhoehe liegt quer zum Gleis, also traegt
     * die starke Achse die Biegung aus dem Wind QUER.
     */
    wahr('Steg in Jochachse: quer ist die starke Achse', n.Wq > n.Wl,
         `${n.Wq} gegen ${n.Wl} cm³`);
    const gedreht = rechne2({ mastSteg: 'quer', mastLaenge: 12.5 });
    wahr('Gedreht ist es umgekehrt',
         gedreht.mast.A.Wq < gedreht.mast.A.Wl,
         `${gedreht.mast.A.Wq} gegen ${gedreht.mast.A.Wl} cm³`);
  }

  // --- Plastisch nur bei Klasse 1 oder 2 -----------------------------------
  {
    const el = rechne2({ mastLaenge: 12.5, mastPlastisch: false });
    const pl = rechne2({ mastLaenge: 12.5, mastPlastisch: true });
    wahr('Der Schalter greift', pl.mast.A.plastischWirksam === true);
    wahr('Und nicht, wenn er aus ist', el.mast.A.plastischWirksam === false);
    wahr('Plastisch ist eta kleiner', pl.mast.eta < el.mast.eta,
         `${pl.mast.eta.toFixed(3)} gegen ${el.mast.eta.toFixed(3)}`);
    pruef('Genau im Verhaeltnis der Widerstandsmomente',
          el.mast.A.Wq / pl.mast.A.Wq,
          MASTPROFIL_VERHAELTNIS(pl.mast.A), 1e-9, '–');
    function MASTPROFIL_VERHAELTNIS(n) {
      const p = MA.plastischeWiderstaende(n.profil);
      const stegQuer = n.stegrichtung.achse === 'y';
      return n.profil[stegQuer ? 'Wy' : 'Wz']
           / (stegQuer ? p.Wply : p.Wplz);
    }
    /*
     * >>> UND NUR BEI KLASSE 1 ODER 2. <<< Das ist EN 1993-1-1 und keine
     * Wahl: ein Querschnitt der Klasse 3 erreicht die
     * Fliessgelenkschnittgroesse nicht.
     */
    const n = pl.mast.A;
    wahr('Der Nachweis sagt, welche Klasse er gefunden hat',
         Number.isFinite(n.klasse.klasse) && n.klasse.klasse <= 2);
    wahr('Und dass der Wunsch gestellt war',
         n.plastischGewuenscht === true);
  }
}

// ===========================================================================
titel('50  Der Winkel bekommt seine Ausrundung');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August: "Die L Profile sind ohne Rundungen
 * im Axis Modell. Es sollten die LNP Profile gemaess Norm sein, EN Standard."
 *
 * r1 und r2 standen in der Ausleitung auf NULL - mit dem Vermerk, die Radien
 * staenden in den Profiltabellen dieses Werkzeugs nicht. Der Winkel war damit
 * ein scharfkantiges Polygon, und seine Flaeche rund zwei Prozent zu klein.
 *
 * Fuer einen gleichschenkligen Winkel nach EN 10056-1 gilt
 *      A = t*(2a - t) + (1 - pi/4)*(r1^2 - 2*r2^2),   r2 = r1/2
 * Nach r1 aufgeloest liefert die Tabellenflaeche den Radius.
 *
 * >>> DAS IST NICHT DER NORMRADIUS, SONDERN DER, DER DIE FLAECHE TRIFFT. <<<
 * Genau das wird hier geprueft - und die Grenzen dieser Aussage mit.
 */
{
  const AX = await import(J('export.axisvm.js'));
  const { PROFILE } = await import(J('data.profiles.js'));
  const c = 1 - Math.PI / 4;

  PROFILE().forEach((p) => {
    const r = AX.winkelRadien(p);
    // >>> DIE FLAECHE MUSS GENAU STIMMEN. Das ist der Zweck der Rechnung.
    const A = (p.t * (p.aH + p.aV - p.t) + c * (r.r1 * r.r1 - 2 * r.r2 * r.r2)) / 100;
    pruef(`${p.name}: die Flaeche wird getroffen`, A, p.A, 5e-3, 'cm2');
    wahr(`${p.name}: r2 ist die Haelfte von r1`,
         Math.abs(r.r2 - r.r1 / 2) < 0.01, `${r.r1} / ${r.r2}`);
    /*
     * DER RADIUS BLEIBT IN EINER GROESSENORDNUNG, DIE EIN WINKEL HAT - oder
     * er ist null, und dann sagt die Quelle warum: beim ungleichschenkligen
     * L 130x80x12 ist die Tabellenflaeche genau t*(aH+aV-t), also OHNE
     * Kehle. Da gibt es nichts zurueckzurechnen. Ehrlich null ist besser als
     * eine erfundene Zahl - und es steht in der Ausleitung.
     */
    if (r.r1 > 0) {
      wahr(`${p.name}: der Radius ist plausibel`,
           r.r1 < 2.2 * p.t, `${r.r1} mm bei t = ${p.t}`);
      wahr(`${p.name}: aus der Flaeche, nicht aus der Tabelle`,
           r.quelle === 'flaeche');
    } else {
      wahr(`${p.name}: ohne Ausrundung, und es steht dabei`,
           r.quelle === 'keine', r.quelle);
    }
  });

  /*
   * DIE DATEN SCHLAGEN DIE HERLEITUNG. Traegt die Profiltabelle einmal
   * eigene Radien, gelten DIESE - dieselbe Regel wie bei W_pl des Mastes.
   */
  {
    const r = AX.winkelRadien({ aH: 90, aV: 90, t: 9, A: 15.5, r1: 11, r2: 5.5 });
    pruef('Ein Tabellenradius gilt', r.r1, 11, 1e-12, 'mm');
    wahr('Und wird als solcher benannt', r.quelle === 'tabelle');
  }

  /*
   * DER ABSTAND ZUM NORMRADIUS - ausdruecklich gemessen, damit niemand die
   * Zahl fuer den Normwert haelt. Der Beiwert (1-pi/4)/2 ist klein; die auf
   * 0.1 cm2 gerundete Tabellenflaeche laesst r1 um gut einen Millimeter
   * schwanken. Fuer das Modell zaehlt die FLAECHE, und die trifft er.
   */
  {
    const norm = { 'L 80x80x8': 10, 'L 90x90x9': 11, 'L 100x100x10': 12,
                   'L 120x120x12': 13, 'L 130x130x12': 14 };
    Object.entries(norm).forEach(([nm, rn]) => {
      const p = PROFILE().find((q) => q.name === nm);
      if (!p) return;
      const r = AX.winkelRadien(p);
      wahr(`${nm}: nahe am Normradius, aber nicht gleich`,
           Math.abs(r.r1 - rn) < 2.0,
           `${r.r1} gegen ${rn} mm nach EN 10056-1`);
    });
  }

  // --- In der Ausleitung ---------------------------------------------------
  {
    const w = { ...standardwerte(), typ: 'J90', L: 20 };
    const erg = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                         getStahl(w.stahl), T.getTragjoch(w.typ));
    const j = AX.stabmodellJson(erg.modell, { eingabe: w });
    const g = j.querschnitte.filter((q) => /^GURT_/.test(q.name));
    wahr('Beide Gurtquerschnitte stehen in der Datei', g.length === 2);
    g.forEach((q) => {
      wahr(`${q.name}: r1 ist nicht mehr null`, q.parameter[3] > 0,
           JSON.stringify(q.parameter));
      wahr(`${q.name}: r2 ebenfalls`, q.parameter[4] > 0);
      // Der Katalogname geht mit - die Bruecke versucht ihn vor dem
      // parametrischen Weg.
      wahr(`${q.name}: der Katalogname geht mit`,
           q.katalog?.norm === 'EN 10056-1' && /^L /.test(q.katalog.bezeichnung),
           JSON.stringify(q.katalog));
    });
  }

  // --- Und die Bruecke versucht ihn ---------------------------------------
  {
    const ps = readFileSync(join(HIER, 'com', 'AxisVM_aufbauen.ps1'), 'utf8');
    wahr('Die Bruecke versucht zuerst den Katalog',
         ps.indexOf('AddFromCatalog(Katalog') < ps.indexOf('AddL(Name, a, b'));
    wahr('Und faellt auf den vermessenen Weg zurueck',
         /AddL\(Name, a, b, tw, tf, r1, r2, cspRolled\)/.test(ps));
    // Die Datei bleibt reines ASCII - sonst bricht sie beim Laden.
    wahr('Die .ps1 ist reines ASCII',
         // eslint-disable-next-line no-control-regex
         !/[^␀-]/.test(ps));
  }
}

// ===========================================================================
titel('51  Was ein Leiter an dieser Stelle abgibt');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August:
 *
 *   "Bei den Leitern eine Auswahl einfuegen, ob Staendige / Veraenderliche /
 *    Staendige+Veraenderliche wirkt. Es kann sein, dass der Leiter nur
 *    abgezogen wird (bei Fahrdraht der Fall), oder dass die Befestigung am
 *    Joch nur das Tragseil eine Ablenkkraft hat und der Fahrdraht nicht, da
 *    dieser Anteil in die Drueckstuetze geht. Die staendigen aber beiden zum
 *    Tragseil gehen und von der Befestigung am Joch getragen."
 *
 * >>> DIE ACHSE IST NICHT "STAENDIG / VERAENDERLICH". <<<
 * Gewicht UND Ablenkkraft sind beide staendig (Gruppe G). Der genannte Fall
 * trennt sie trotzdem: das Gewicht kommt am Joch an, die Ablenkung des
 * Fahrdrahts nicht. Eine Wahl mit zwei Stellungen traefe ihn also gar nicht.
 * Getrennt wird nach dem, was wirklich verschiedene Wege geht - Gewicht,
 * Ablenkung, Wind/Schnee. Auf Rueckfrage so entschieden.
 */
{
  const A9 = await import(J('data.anbauteile.js'));

  const bogen = { ek: 'EK2', R: 380, spannweite: 30 };
  const leiter = (o = {}) => ({
    id: 'KW', name: 'Kettenwerk', vorlage: 'direkt', x: 8, raster: 0.4,
    befestigung: 'unten', aktiv: true, lasten: [],
    module: [{ bauteil: 'drahtwerk-cu-95', anzahl: 1, z: -1.35, y: 0, ...o }],
  });
  const kr = (o) => {
    const f = A9.expandiereAnbauteile([leiter(o)], bogen);
    return f.reduce((s2, t) => ({
      Gz: s2.Gz + (t.kraefte?.G?.Fz ?? 0),
      Gx: s2.Gx + (t.kraefte?.G?.Fx ?? 0),
      // Der Leiter traegt Wind QUER (windLaengs fuehrt die Tabelle fuer
      // Drahtwerke nicht - ein Seil hat in Laengsrichtung keine Flaeche).
      Qx: s2.Qx + (t.kraefte?.WindX?.Fx ?? 0),
    }), { Gz: 0, Gx: 0, Qx: 0 });
  };

  // --- Ohne Angabe wirkt alles --------------------------------------------
  /*
   * Alte Baugruppen fuehren die Haken nicht. Sie muessen unveraendert
   * weiterrechnen - sonst aendert eine Fassung still jedes gespeicherte
   * Tragwerk.
   */
  const voll = kr({});
  wahr('Ohne Angabe wirkt das Gewicht', Math.abs(voll.Gz) > 1e-6, `${voll.Gz}`);
  wahr('Ohne Angabe wirkt die Ablenkung', Math.abs(voll.Gx) > 1e-6, `${voll.Gx}`);
  wahr('Ohne Angabe wirkt der Wind', Math.abs(voll.Qx) > 1e-6, `${voll.Qx}`);

  // --- Der Fall aus der Weisung -------------------------------------------
  /*
   * DER FAHRDRAHT AM JOCH: sein Gewicht haengt am Tragseil und kommt hier an,
   * seine Ablenkung geht in die Drueckstuetze. Genau ein Haken.
   */
  {
    const ohneAblenk = kr({ wirktAblenk: false });
    pruef('Das Gewicht bleibt', ohneAblenk.Gz, voll.Gz, 1e-12, 'kN');
    pruef('Die Ablenkung faellt weg', ohneAblenk.Gx, 0, 1e-12, 'kN');
    pruef('Und der Wind bleibt', ohneAblenk.Qx, voll.Qx, 1e-12, 'kN');
    // >>> BEIDE SIND STAENDIG. Waere nach staendig/veraenderlich getrennt
    // worden, haette dieser Fall das Gewicht mitgenommen.
    wahr('Gewicht und Ablenkung stehen beide in der Gruppe G',
         Math.abs(voll.Gz) > 1e-6 && Math.abs(voll.Gx) > 1e-6);
  }

  // --- Die anderen beiden Haken -------------------------------------------
  {
    const ohneG = kr({ wirktG: false });
    pruef('Ohne Gewicht ist F_z null', ohneG.Gz, 0, 1e-12, 'kN');
    pruef('Die Ablenkung bleibt', ohneG.Gx, voll.Gx, 1e-12, 'kN');
    const ohneQ = kr({ wirktQ: false });
    pruef('Ohne Wind ist F_x aus Wind null', ohneQ.Qx, 0, 1e-12, 'kN');
    pruef('Das Gewicht bleibt auch dann', ohneQ.Gz, voll.Gz, 1e-12, 'kN');
    // Alle drei aus: der Leiter wird nur abgezogen und gibt hier nichts ab.
    const nichts = kr({ wirktG: false, wirktAblenk: false, wirktQ: false });
    wahr('Alle drei aus: der Leiter gibt hier nichts ab',
         nichts.Gz === 0 && nichts.Gx === 0 && nichts.Qx === 0);
  }

  // --- Nur Drahtwerke fuehren die Wahl ------------------------------------
  /*
   * Ein Traeger hat keine Ablenkkraft, und wer sein Gewicht nicht will,
   * schaltet das Modul ab. Die Haken dort anzubieten hiesse, eine Frage zu
   * stellen, die es nicht gibt.
   */
  {
    const stuetze = {
      id: 'HS', name: 'Stuetze', vorlage: 'direkt', x: 8, raster: 0.4,
      befestigung: 'unten', aktiv: true, lasten: [],
      module: [{ bauteil: 'anbauteil-haengestuetze-od-haengerohr', anzahl: 1,
                 z: -1.35, y: 0, wirktG: false }],
    };
    const f = A9.expandiereAnbauteile([stuetze], bogen);
    const Gz = f.reduce((s2, t) => s2 + (t.kraefte?.G?.Fz ?? 0), 0);
    wahr('Bei einem Traeger greift der Haken nicht', Math.abs(Gz) > 1e-6,
         `${Gz.toFixed(4)} kN`);
    wahr('Und er traegt keine Wirkungsangabe',
         f.every((t) => t.rolle !== 'drahtwerk' ? t.wirkung === null : true));
  }

  // --- Die Wirkung steht am Teil ------------------------------------------
  // Ausleitung und Darstellung sollen sie benennen koennen, nicht nur die
  // Summe sehen.
  {
    const f = A9.expandiereAnbauteile([leiter({ wirktAblenk: false })], bogen);
    const t = f.find((x) => x.rolle === 'drahtwerk');
    wahr('Das Drahtwerk traegt seine Wirkung', t.wirkung
         && t.wirkung.G === true && t.wirkung.ablenk === false
         && t.wirkung.Q === true, JSON.stringify(t.wirkung));
  }

  // --- Das Kettenwerk als Klammer -----------------------------------------
  /*
   * Es geht in KEINE Rechnung ein - noch nicht. Es haelt zusammen, was
   * zusammengehoert: Tragseil und Fahrdraht. Der Havariefall (Bruch eines
   * Kettenwerks, mit staendigen Lasten charakteristisch und dem Leiterzug bei
   * -20 Grad) waehlt spaeter darueber aus.
   */
  {
    const f = A9.expandiereAnbauteile([leiter({ kettenwerk: 'KW1' })], bogen);
    const t = f.find((x) => x.rolle === 'drahtwerk');
    wahr('Das Kettenwerk wandert mit', t.kettenwerk === 'KW1', t.kettenwerk);
    const ohne = A9.expandiereAnbauteile([leiter({})], bogen)
      .find((x) => x.rolle === 'drahtwerk');
    wahr('Ohne Angabe bleibt es leer', ohne.kettenwerk === null);
    // Und es aendert nichts an den Kraeften.
    pruef('Es geht in keine Rechnung ein',
          kr({ kettenwerk: 'KW1' }).Gx, voll.Gx, 1e-12, 'kN');
  }

  // --- In der Maske --------------------------------------------------------
  {
    const roh = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Die drei Haken stehen in der Maske',
         /wirktG/.test(roh) && /wirktAblenk/.test(roh) && /wirktQ/.test(roh));
    wahr('Und das Kettenwerksfeld', /data-mk="kettenwerk"/.test(roh));
    /*
     * SIE ERSCHEINEN NUR BEIM DRAHTWERK - und seit dem 13. September
     * unmittelbar unter dem Fahrdrahtfeld (Weisung: «zudem sollte dies
     * unterhalb von fahrdraht stehen damit man die zugehoerigkeit (nur auf
     * fahrdraht angewendet) versteht»). Vorher standen sie drei Abschnitte
     * weiter unten, hinter Angriffspunkt und Ablenkung.
     *
     * Geprueft wird die AUSSAGE, nicht die Zeilennummer: der Aufruf haengt
     * am Drahtwerk, und er folgt dem Partnerfeld.
     */
    wahr('Nur im Drahtwerkzweig',
         roh.includes("${drahtwerk ? wirkungHtml(i, k, m) : ''}"));
    wahr('… und unmittelbar unter dem Fahrdrahtfeld',
         roh.includes("${partnerFeld(m, k, i)}${drahtwerk ? wirkungHtml"));
    /*
     * DIE ABLENKUNG IST SEIT DEM 15. SEPTEMBER EIN KLAPPABSCHNITT (Weisung:
     * "bauteil karte ablenkung in zweite ebene"). Der Marker heisst deshalb
     * nicht mehr `sec-klein`, sondern `at-abl-` - die AUSSAGE der Kontrolle
     * bleibt dieselbe: der Wirkungsblock steht davor, nicht dahinter.
     */
    wahr('… nicht mehr hinter der Ablenkung',
         roh.indexOf('wirkungHtml(i, k, m)')
           < roh.indexOf('klapp(`at-abl-'));
    /*
     * DER TITEL NENNT DEN FAHRDRAHT (Weisung: «der Titel wirkt hier
     * kettenwerk ist etwas missverstaendlich»).
     */
    /*
     * DIE UEBERSCHRIFT NENNT KEINEN EINZELNEN LEITER MEHR - seit dem
     * 15. September haben die drei Haken ZWEI Bezuege (Gewicht beiden,
     * Ablenkung und Wind dem Fahrdraht). Eine Ueberschrift, die «am
     * Fahrdraht» sagt, waere fuer den Gewichtshaken falsch. Der Bezug steht
     * jetzt an jedem Haken.
     */
    wahr('Jeder Haken traegt seinen Bezug',
         roh.includes("bezug: 'beide'") && roh.includes("bezug: 'fahrdraht'"));
    wahr('… und die Maske schreibt ihn an',
         roh.includes('wirk-bez') && roh.includes('const marke = (x)'));
    wahr('Bei einem einzelnen Leiter faellt die Marke weg',
         roh.includes("if (!kw) return '';"));
    wahr('… und «Wirkt hier · Kettenwerk» ist weg',
         !roh.includes("`Kettenwerk ${m.kettenwerk}`"));
    /*
     * DER HINWEIS IST EINGEKLAPPT (Weisung: «den infotext unterhalb
     * einklappbar machen und auf ein minimum reduzieren»). `hinweisHtml`
     * klappt alles ueber HINWEIS_KURZ zu; geprueft wird, dass der Text
     * durch diese Funktion laeuft und nicht als fester Absatz dasteht.
     */
    wahr('Der Hinweis laeuft durch hinweisHtml',
         roh.includes('hinweisHtml(`wirk-${i}-${k}`, kurz)'));
    wahr('… und steht nicht mehr als fester Absatz da',
         !roh.includes('class="hinweis wirk-bezug"'));
  }
}

// ===========================================================================
titel('52  Masten und Auflagerung sind zwei Fragen');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August: "hier nicht abhaengig machen, ob
 * Mast im Modell aufgefuehrt wird oder nicht. Die Haupttragwerke sollten
 * global gesteuert werden."
 *
 * Bis dahin entschied die Auswahl "Endauflager" beides zugleich: WIE das Joch
 * gelagert ist UND OB es ueberhaupt einen Masten gibt. Wer gelenkig rechnen
 * wollte, verlor den Masten aus Bild, Ausleitung, Wind und Nachweis. Wer den
 * Masten sehen wollte, musste seine Steifigkeit ansetzen.
 *
 *      mastVorhanden   ob er dasteht  - Bauteil, Bild, Ausleitung, Nachweis
 *      endbedingung    woher die Drehfeder des Jochendes kommt
 */
{
  const AU = await import(J('core.auflager.js'));
  const R = await import(J('render.3d.js'));

  const bau = (o) => {
    const w = { ...standardwerte(), typ: 'J90', L: 20, mastProfil: 'HEB 260',
                mastH: 8, ...o };
    const erg = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                         getStahl(w.stahl), T.getTragjoch(w.typ));
    return { w, erg, sz: R.erzeugeSzene(erg.modell, erg) };
  };

  // --- Die Weiche ---------------------------------------------------------
  wahr('Eingeschaltet steht ein Mast', AU.mastImModell({ mastVorhanden: true }));
  wahr('Ausgeschaltet keiner', !AU.mastImModell({ mastVorhanden: false }));
  /*
   * ALTE DATEIEN RECHNEN UNVERAENDERT. Fehlt die Angabe, gilt der fruehere
   * Zusammenhang - sonst bekaeme jedes gespeicherte Tragwerk mit gelenkigem
   * Auflager still einen Masten dazu, mit Wind, Nachweis und Ausleitung.
   */
  wahr('Ohne Angabe gilt der fruehere Zusammenhang',
       AU.mastImModell({ endbedingung: 'mast' })
       && !AU.mastImModell({ endbedingung: 'gelenkig' }));
  wahr('Und der Schalter schlaegt ihn',
       AU.mastImModell({ endbedingung: 'gelenkig', mastVorhanden: true })
       && !AU.mastImModell({ endbedingung: 'mast', mastVorhanden: false }));

  /*
   * >>> DIE PRUEFUNG, DIE ZAEHLT. <<<
   * Ein Mast im Modell darf die JOCHRECHNUNG nicht anfassen, solange die
   * Endbedingung ihn nicht als Feder verlangt. Sonst waere die Trennung
   * keine: man schaltete ein Bauteil ein und bekaeme eine andere Ausnutzung.
   */
  ['gelenkig', 'voll', 'manuell'].forEach((eb) => {
    const ohne = bau({ endbedingung: eb, mastVorhanden: false });
    const mit = bau({ endbedingung: eb, mastVorhanden: true });
    pruef(`${eb}: der Mast aendert die Jochausnutzung nicht`,
          mit.erg.max.etaGesamt, ohne.erg.max.etaGesamt, 1e-12, '-');
    pruef(`${eb}: und auch die Drehfeder nicht`,
          mit.erg.modell.federn.cA, ohne.erg.modell.federn.cA, 1e-9, 'kNm/rad');
    // Er steht trotzdem da - mit allem, was dazugehoert.
    wahr(`${eb}: der Mast steht im Modell`, !!mit.erg.modell.federn.mast);
    wahr(`${eb}: er wird gezeichnet`,
         mit.sz.flaechen.some((f) => /^MAST_/.test(f.teil ?? '')));
    wahr(`${eb}: er traegt Wind`, !!mit.erg.modell.mastLast);
    wahr(`${eb}: und er wird nachgewiesen`,
         mit.erg.mast != null && Number.isFinite(mit.erg.mast.eta));
    // Ohne ihn nichts davon.
    wahr(`${eb}: ausgeschaltet ist er ganz weg`,
         !ohne.erg.modell.federn.mast && !ohne.erg.modell.mastLast
         && (ohne.erg.mast === null || ohne.erg.mast === undefined)
         && !ohne.sz.flaechen.some((f) => /^MAST_/.test(f.teil ?? '')));
  });

  // --- Umgekehrt: die Feder wirkt weiterhin -------------------------------
  {
    const feder = bau({ endbedingung: 'mast', mastVorhanden: true });
    const ohne = bau({ endbedingung: 'gelenkig', mastVorhanden: true });
    wahr('Mit "Steifigkeit aus Mast" entsteht eine Feder',
         feder.erg.modell.federn.cA > 0);
    pruef('Ohne sie bleibt das Ende gelenkig', ohne.erg.modell.federn.cA, 0,
          1e-12, 'kNm/rad');
    wahr('Und das aendert die Jochausnutzung sehr wohl',
         Math.abs(feder.erg.max.etaGesamt - ohne.erg.max.etaGesamt) > 1e-3,
         `${feder.erg.max.etaGesamt.toFixed(4)} gegen `
         + `${ohne.erg.max.etaGesamt.toFixed(4)}`);
  }

  // --- "Aus Mast" gewaehlt, aber keiner da --------------------------------
  /*
   * Dann wird gelenkig gerechnet - und zwar LAUT. Still eine Feder aus einem
   * Bauteil zu bilden, das nicht dasteht, waere die schlimmere Antwort; still
   * gelenkig zu rechnen aber auch, denn das ist der Unterschied zwischen
   * einem eingespannten und einem frei aufliegenden Joch.
   */
  {
    const { hinweise } = await import(J('core.checks.js'));
    const b = bau({ endbedingung: 'mast', mastVorhanden: false });
    pruef('Ohne Masten keine Feder', b.erg.modell.federn.cA, 0, 1e-12, 'kNm/rad');
    wahr('Die Bezeichnung sagt es',
         /kein Mast/.test(b.erg.modell.federn.art), b.erg.modell.federn.art);
    wahr('Und ein Hinweis steht in der Liste',
         hinweise(b.erg.modell).join(' | ').includes('GELENKIG'),
         hinweise(b.erg.modell).find((h) => /Endauflager/.test(h)) ?? '(keiner)');
  }

  // --- Die Maske folgt derselben Antwort ----------------------------------
  {
    const feld = (k) => FELDER.find((f) => f.key === k);
    const feld2 = (k) => FELDER.find((f) => f.key === k);   // darf fehlen
    const sicht = (f, w) => (typeof f.sichtbar === 'function' ? f.sichtbar(w) : true);
    const an = { ...standardwerte(), endbedingung: 'gelenkig', mastVorhanden: true };
    const aus = { ...standardwerte(), endbedingung: 'mast', mastVorhanden: false };
    wahr('Es gibt den Schalter', !!feld('mastVorhanden'));
    wahr('Er steht in der Gruppe der Masten',
         feld('mastVorhanden').gruppe === 'mast');
    // >>> DIE MASTFELDER HAENGEN AM SCHALTER, NICHT AN DER ENDBEDINGUNG.
    ['mastProfil', 'mastH', 'mastLaenge', 'mastSteg', 'wMast'].forEach((k) => {
      wahr(`${k}: sichtbar bei gelenkigem Auflager mit Masten`,
           sicht(feld(k), an));
      wahr(`${k}: unsichtbar ohne Masten, auch bei "aus Mast"`,
           !sicht(feld(k), aus));
    });
    // Das BAUTEIL steht bei den Masten, die LAST bei den Einwirkungen.
    // Beides haengt am selben Schalter, aber es sind zwei Fragen: welcher
    // Mast dasteht, und was auf ihn drueckt.
    ['mastProfil', 'mastH', 'mastLaenge', 'mastSteg'].forEach((k) => {
      wahr(`${k}: steht in der Gruppe der Masten`, feld(k).gruppe === 'mast');
    });
    ['wMast', 'mastWindAufJoch'].forEach((k) => {
      wahr(`${k}: steht bei den Einwirkungen`, feld(k).gruppe === 'ein');
    });
    // KEINE OPTION MEHR: der Schalter, der den Tabellenwert abwaehlen liess,
    // ist weg. Steht ein Mast im Modell, faengt er Wind.
    wahr('Der Schalter "aus der Lasttabelle" ist entfallen',
         !feld2('wMastAusTabelle'));
    // Seit dem 20. September GANZ gesperrt, nicht nur bis «Werte
    // bearbeiten»: der Kern hat den eingetippten Wert nie gelesen, und ein
    // flaches Feld kann mehrere Masten mit verschiedenen Profilen ohnehin
    // nicht bedienen (Abschnitt 109).
    wahr('Die Mastwindlast steht gesperrt, in beiden Richtungen',
         feld('wMast').nurAnzeige === true && feld('wMastY').nurAnzeige === true);
    // Die Auflagerung behaelt, was Auflagerung ist.
    ['endbedingung', 'cPhi', 'kragA', 'kragB', 'mastAnschluss']
      .forEach((k) => wahr(`${k}: bleibt bei der Auflagerung`,
                           feld(k).gruppe === 'aufl'));
    // Und die Gruppe steht im Reiter.
    const U = await import(J('ui.js'));
    wahr('Die Gruppe steht im Reiter System',
         U.EINGABE_TABS.find((t) => t.id === 'system').gruppen.includes('mast'));
  }
}

// ===========================================================================
titel('52b Steht ein Mast im Modell, wird er auch ausgeleitet');
// Bis zum 31. August war 'gurte' die Vorgabe des AxisVM-Dialogs, gleich ob
// ein Mast dastand oder nicht. Wer ihn im FEM haben wollte, musste ihn eigens
// waehlen - und wer es vergass, rechnete ihn im Ersatzbalken als Drehfeder
// und im FEM gar nicht.
{
  const AXV = await import(J('export.axisvm.js'));
  const j90v = T.getTragjoch('J90');
  const mitMast = rechne({ ...basis(), ...typUebernehmen({ ...standardwerte() }, j90v),
    typ: 'J90', L: 15.5, mastVorhanden: true, endbedingung: 'mast',
    mastProfil: 'HEB 260', mastH: 7.5 }).modell;
  const ohneMast = rechne({ ...basis(), ...typUebernehmen({ ...standardwerte() }, j90v),
    typ: 'J90', L: 15.5, mastVorhanden: false, endbedingung: 'gelenkig' }).modell;
  wahr('Mit Mast ist die Vorgabe das Mastmodell',
       AXV.auflagerVorgabe(mitMast) === 'mast', AXV.auflagerVorgabe(mitMast));
  wahr('Ohne Mast bleibt es bei der Bauweise',
       AXV.auflagerVorgabe(ohneMast) === 'gurte', AXV.auflagerVorgabe(ohneMast));
  // Die Altbauweise ist zu flach fuer ein Kraeftepaar - das galt vorher und gilt weiter.
  wahr('Altbauweise ohne Mast lagert in der Ebenenmitte',
       AXV.auflagerVorgabe({ ...ohneMast, bauweise: 'alt' }) === 'mitte');
  // Und die Wahl im Dialog sticht die Vorgabe weiterhin.
  const gewaehlt = AXV.stabmodell(mitMast, { knotenmodell: 'anschnitt',
                                             auflagerModell: 'gurte' });
  wahr('Eine ausdrueckliche Wahl sticht die Vorgabe',
       gewaehlt.auflager.every((a) => a.modell === 'gurte'));
}

// ===========================================================================
titel('53  Die Beschriftung laesst kein Endfeld leer');

/*
 * WEISUNG DES AUFTRAGGEBERS, 28. August: "Ich habe noch etwas bemerkt: das
 * Endfeld auf einer Seite weist keine Resultate auf in der App."
 *
 * NACHGEMESSEN AN SEINER AUSLEITUNG (J70, 15 m, Mast HEM 240, sechs
 * Baugruppen am Joch): der Rechenkern liefert an BEIDEN Enden Werte, und
 * jede Blechflaeche traegt ihren Kennwert. Es fehlten nur die ZAHLEN.
 *
 * DIE URSACHE war die Ausduennung der Beschriftung: sie sortierte streng
 * nach Betrag und setzte die sechzig groessten. Die grossen Werte liegen in
 * Feldmitte, die kleinen am Auflager - also fielen die Auflagerbereiche
 * zuerst weg, und weil die Lasten selten genau symmetrisch sind, oft nur auf
 * einer Seite.
 *
 * Die FARBE war die ganze Zeit da. Ein Bild, das einen Bereich
 * unbeschriftet laesst, liest sich aber wie "hier ist nichts gerechnet".
 */
{
  const R = await import(J('render.3d.js'));

  // Der Fall aus der Ausleitung, so weit er sich aus ihr nachbauen laesst.
  const at = (id, x) => ({
    id, name: id, vorlage: 'direkt', x, raster: 0.4, befestigung: 'unten',
    aktiv: true, module: [],
    lasten: [{ einwirkung: 'G', x: 0, y: 0, z: -1.3,
               Fx: -1.736842, Fy: 0, Fz: 0.6, Mxx: 0, Myy: 0, Mzz: 0 },
             { einwirkung: 'WindX', x: 0, y: 0, z: -1.3,
               Fx: 0.72, Fy: 0, Fz: 0, Mxx: 0, Myy: 0, Mzz: 0 }] });
  const w = { ...standardwerte(), typ: 'J70', L: 15, a1: 0.75,
              endbedingung: 'mast', mastProfil: 'HEM 240', mastH: 8,
              mastLaenge: 12.5, knotenbereich: 'anschnitt',
              anbauteile: [4.1, 5.39, 8.057, 8.467, 9.5, 12.2]
                .map((x, i) => at(`A${i + 1}`, x)) };
  const erg = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                       getStahl(w.stahl), T.getTragjoch(w.typ));
  const sz = R.erzeugeSzene(erg.modell, erg);

  // --- Erst der Befund: gerechnet ist ueberall ----------------------------
  {
    const bl = sz.flaechen.filter((f) => f.gruppe === 'blech');
    const ohne = bl.filter((f) => !f.werte || f.werte.eta === null
                                            || f.werte.eta === undefined);
    const x = (f) => f.punkte.reduce((s2, q) => s2 + q[0], 0) / f.punkte.length;
    /*
     * Am ENDBLECH gibt es keine Horizontalbleche - an beiden Enden gleich.
     * Das ist die einzige Stelle ohne Kennwert, und sie ist symmetrisch.
     */
    const xsOhne = [...new Set(ohne.map((f) => Math.round(x(f) * 100) / 100))];
    wahr('Ohne Kennwert sind nur die Enden',
         xsOhne.every((v) => v < 0.2 || v > 14.8), xsOhne.join(', '));
    wahr('Und zwar BEIDE Enden gleich',
         xsOhne.some((v) => v < 0.2) === xsOhne.some((v) => v > 14.8));
    // Die Vertikalbleche tragen an beiden Enden einen Wert.
    const beiX = (ziel) => bl.filter((f) => Math.abs(x(f) - ziel) < 0.06
      && /V_[LR]/.test(f.label ?? ''));
    wahr('Das erste Vertikalblech traegt einen Wert',
         beiX(0).length > 0 && beiX(0).every((f) => Number.isFinite(f.werte?.eta)));
    wahr('Das letzte ebenso',
         beiX(15).length > 0 && beiX(15).every((f) => Number.isFinite(f.werte?.eta)));
    /*
     * NICHT DERSELBE WERT: die Baugruppen liegen zwischen 4.1 und 12.2 m,
     * ihr Schwerpunkt also links der Mitte. Das Joch ist belastet
     * unsymmetrisch - und genau das macht die alte Ausduennung so tueckisch,
     * denn sie laesst dann die SCHWAECHER beanspruchte Seite leer.
     */
    wahr('Beide Enden tragen einen wirklichen Wert',
         beiX(0)[0].werte.eta > 0 && beiX(15)[0].werte.eta > 0,
         `${beiX(0)[0].werte.eta.toFixed(3)} gegen `
         + `${beiX(15)[0].werte.eta.toFixed(3)}`);
  }

  // --- Und jetzt die Beschriftung -----------------------------------------
  /*
   * Nachgestellt wird, was `_werte` tut: Kandidaten sammeln, ordnen, die
   * ersten sechzig nehmen. Geprueft wird die ORDNUNG - sie entscheidet, wer
   * bei knappem Platz uebrig bleibt.
   */
  {
    /*
     * NUR DAS JOCH. Der Befund betraf die Beschriftung der BLECHE: sie brach
     * mitten im Feld ab. Seit dem 1. September traegt auch der Mast seine
     * Ausnutzung, und seine Abschnitte liegen an den Mastachsen, also an den
     * Enden - mit ihnen deckte die Betragsordnung die Enden scheinbar wieder
     * ab, und die Pruefung mass ihren eigenen Gegenstand nicht mehr.
     */
    const kand = sz.flaechen
      .filter((f) => Number.isFinite(f.werte?.eta) && !/^MAST_/.test(f.teil ?? ''))
      .map((f) => ({ v: f.werte.eta,
                     x: f.punkte.reduce((s2, q) => s2 + q[0], 0) / f.punkte.length,
                     betrag: Math.abs(f.werte.eta) }));
    wahr('Es gibt mehr Kandidaten als Plaetze', kand.length > 60,
         `${kand.length} Kandidaten`);

    // ALT: streng nach Betrag. NEU: reihum ueber die Spalten.
    const nurGroesste = [...kand].sort((a, b) => b.betrag - a.betrag).slice(0, 60);
    const verteilt = R.beschriftungsReihenfolge(kand).slice(0, 60);

    const spanne = (liste) => {
      const xs = liste.map((k) => k.x);
      return { min: Math.min(...xs), max: Math.max(...xs) };
    };
    const a = spanne(nurGroesste), b = spanne(verteilt);
    /*
     * >>> DAS IST DER BEFUND. <<< Nach Betrag geordnet beginnt die
     * Beschriftung erst weit im Feld; verteilt beginnt sie am Auflager.
     */
    wahr('Nach Betrag geordnet bleiben die Enden leer',
         a.min > 0.5 || a.max < 14.5,
         `x von ${a.min.toFixed(2)} bis ${a.max.toFixed(2)} m`);
    wahr('Verteilt reicht die Beschriftung bis an beide Enden',
         b.min < 0.5 && b.max > 14.5,
         `x von ${b.min.toFixed(2)} bis ${b.max.toFixed(2)} m`);

    /*
     * UND DIE MASSGEBENDE STELLE BLEIBT BESCHRIFTET. Das war der Sinn der
     * alten Ordnung, und er darf nicht verlorengehen: der groesste Wert des
     * Bildes steht in der ersten Runde, weil seine Spalte gleich drankommt.
     */
    const groesster = kand.reduce((p2, q) => (q.betrag > p2.betrag ? q : p2));
    wahr('Der groesste Wert steht weiterhin unter den ersten',
         verteilt.slice(0, 14).some((k) => Math.abs(k.v - groesster.v) < 1e-12),
         `${groesster.v.toFixed(3)} bei x = ${groesster.x.toFixed(2)} m`);
    /*
     * INNERHALB EINER SPALTE BLEIBT DIE ORDNUNG NACH BETRAG - an einem
     * gebauten Fall geprueft, wo jede Spalte bekannt ist. Am Modell waere
     * die Spaltengrenze nicht nachzurechnen, ohne die Funktion
     * nachzuprogrammieren.
     */
    const bau = [];
    for (let sp = 0; sp < 4; sp++) {
      for (let r = 0; r < 3; r++) {
        bau.push({ x: sp * 10 + r, betrag: 10 - r, v: 10 - r, spalte: sp });
      }
    }
    const ord = R.beschriftungsReihenfolge(bau, 4);
    wahr('Die erste Runde nimmt aus jeder Spalte einen',
         new Set(ord.slice(0, 4).map((k) => k.spalte)).size === 4,
         ord.slice(0, 4).map((k) => `S${k.spalte}:${k.betrag}`).join(' '));
    wahr('Und zwar den groessten der Spalte',
         ord.slice(0, 4).every((k) => k.betrag === 10));
    wahr('Die zweite Runde den zweitgroessten',
         ord.slice(4, 8).every((k) => k.betrag === 9));
    pruef('Es geht nichts verloren', ord.length, bau.length, 1e-12, 'Stk');
  }
}

// ===========================================================================
titel('54  Projektsteuerung: Auswahl, Vorschau, Ersatzspeicher');
// Drei Ergaenzungen nach dem Vorbild von BlockCalc. Der Pruefstand hat kein
// IndexedDB und kein localStorage; geprueft wird deshalb, was OHNE Browser
// pruefbar ist: die Form der Ausleitung, die Auswahl und die Vorschau.
{
  const ST = await import(J('store.js'));

  wahr('Es gibt eine Liste der Paketteile', Array.isArray(ST.PAKETTEILE));
  wahr('Sie nennt Tragwerke, Vorlagen und Zeichnungen',
       ['eintraege', 'vorlagen', 'zeichnungen']
         .every((k) => ST.PAKETTEILE.some((t) => t.key === k)),
       ST.PAKETTEILE.map((t) => t.key).join(' '));
  wahr('Jedes Teil traegt eine Beschriftung',
       ST.PAKETTEILE.every((t) => typeof t.label === 'string' && t.label.length > 2));

  // DIE VORSCHAU IST EINE EIGENE FUNKTION, nicht ein Nebenprodukt des
  // Einlesens: sie darf nichts schreiben.
  wahr('paketInhalt steht bereit', typeof ST.paketInhalt === 'function');
  // Function.length zaehlt nur Parameter VOR dem ersten mit Standardwert;
  // bei (wahl = null) ist sie null und taugt als Pruefung nichts. Geprueft
  // wird deshalb am Quelltext, dass die Auswahl in der Signatur steht.
  {
    const quelle = readFileSync(new URL('./js/store.js', import.meta.url), 'utf8');
    wahr('alsPaket nimmt eine Auswahl entgegen',
         quelle.includes('export async function alsPaket(wahl'));
    wahr('ausPaket nimmt eine Auswahl entgegen',
         quelle.includes('export async function ausPaket(daten, wahl'));
  }

  // ERSATZSPEICHER. Ohne IndexedDB faellt die Ablage auf localStorage
  // zurueck, statt mit einer Ausnahme abzubrechen. Im Pruefstand gibt es
  // beides nicht - geprueft wird, dass die Auskunft da ist.
  wahr('Die Ablage sagt, ob sie im Ersatz laeuft',
       typeof ST.ersatzspeicherAktiv === 'function');
  wahr('Ohne Zugriff meldet sie zunaechst kein Ersatzverfahren',
       ST.ersatzspeicherAktiv() === false);
}

// ===========================================================================
titel('55  Der Mast darf nach innen ruecken');
// Weisung vom 11. September: das Auflager kann INNERHALB der Gurtenden
// liegen. Rueckt der Mast nach innen, sitzen die Anschlusspunkte auf den
// Gurten statt an der Stirn, und das Joch kragt darueber hinaus. Grenze ist
// BERUEHRUNG, gemessen am FLANSCHRAND - anliegend zulaessig, ueberschneidend
// nicht.
//
// Weisung vom 15. September: "die auskragung kann frei gewaehlt werden nicht
// nur innerhalb des endfeldes." Damit faellt die letzte Schranke: geprueft
// wird der Fussabdruck gegen ALLE Bleche, nicht nur gegen das erste.
{
  const AU = await import(J('core.auflager.js'));
  const AXM = await import(J('export.axisvm.js'));
  const j90m = T.getTragjoch('J90');
  const mach = (kragA) => rechne({
    ...basis(), ...typUebernehmen({ ...standardwerte() }, j90m),
    typ: 'J90', L: 15.5, kragA, kragB: 0, anbauteile: [],
    mastVorhanden: true, endbedingung: 'mast',
    mastProfil: 'HEB 260', mastH: 7.5,
  }).modell;

  const m0 = mach(0);
  const m4 = mach(0.4);

  // --- Geometrie ---------------------------------------------------------
  pruef('Ohne Kragarm steht der Mast an der Stirn', AU.mastAchse(m0, 'A'), 0, 1e-12, 'm');
  pruef('Mit Kragarm rueckt er nach innen', AU.mastAchse(m4, 'A'), 0.4, 1e-12, 'm');
  // HEB 260 ist quadratisch: 260 mm in jeder Drehlage.
  pruef('Tiefe in Jochachse aus dem Profil', AU.mastTiefe(m4, 'A'), 0.26, 1e-9, 'm');

  const fr = AU.mastFreiraum(m4, 'A');
  // Erstes Bindeblech bei a1 = 0.75 m, 100 mm breit -> Kante bei 0.70 m.
  pruef('Kante des ersten Blechs', fr.blech, 0.70, 1e-9, 'm');
  // Grenze = Blechkante minus halbe Masttiefe: anliegend, kein Spiel.
  pruef('Grenze ist Beruehrung am Flanschrand', fr.grenze, 0.70 - 0.13, 1e-9, 'm');
  pruef('Und es bleibt der Rest bis dorthin', fr.frei, 0.17, 1e-9, 'm');
  wahr('Kein Ueberschnitt bei 0.40 m', fr.ueberschnitt === false);
  wahr('Ueberschnitt bei 0.70 m',
       AU.mastFreiraum(mach(0.7), 'A').ueberschnitt === true);
  // ANLIEGEND IST ZULAESSIG - das ist der Kern der Weisung.
  wahr('Genau anliegend ist noch zulaessig',
       AU.mastFreiraum(mach(0.57), 'A').ueberschnitt === false);

  // --- Pruefung P9 -------------------------------------------------------
  const CH9 = await import(J('core.checks.js'));
  const p9 = (mm) => CH9.konstruktionsChecks(mm).find((c) => c.id === 'P9A');
  wahr('P9 meldet den freien Weg', /noch 170 mm/.test(p9(m4).status), p9(m4).status);
  wahr('P9 ist erfuellt, solange nichts ueberschneidet', p9(m4).ok === true);
  wahr('P9 faellt beim Ueberschnitt', p9(mach(0.7)).ok === false);
  wahr('\u2026 und sagt, wie weit er im Blech steht',
       /130 mm im liegenden Bindeblech/.test(p9(mach(0.7)).status), p9(mach(0.7)).status);

  /* =======================================================================
   * >>> UND ZWAR IN JEDEM FELD, NICHT NUR IM ENDFELD. <<<
   * =======================================================================
   *
   * Weisung vom 15. September: "die auskragung kann frei gewaehlt werden
   * nicht nur innerhalb des endfeldes."
   *
   * Bis dahin suchte `mastFreiraum` das ERSTE Blech vom Jochende her und
   * machte dessen Kante zur Grenze. Ein Mast bei 1.20 m stand damit
   * rechnerisch "im Blech", obwohl er zwischen den Blechen bei 0.75 und 1.50
   * frei in der Luecke steht - 120 mm Luft auf jeder Seite.
   *
   * DIE STATIONEN des J90 / 15.50 m, in den ersten Metern:
   *
   *   0.000  0.750  1.500  2.250  3.000   (je 100 mm breit)
   *
   * Der HEB 260 misst 260 mm, also 130 mm je Seite.
   */
  wahr('Im zweiten Feld steht er frei', p9(mach(1.2)).ok === true,
       p9(mach(1.2)).status);
  pruef('Die Grenze ist dort die naechste Blechkante',
        AU.mastFreiraum(mach(1.2), 'A').grenze, 1.45 - 0.13, 1e-9, 'm');
  pruef('Und es bleiben 120 mm', AU.mastFreiraum(mach(1.2), 'A').frei,
        0.12, 1e-9, 'm');
  wahr('Auch im vierten Feld', p9(mach(2.0)).ok === true, p9(mach(2.0)).status);
  /*
   * >>> DIE GRENZE BINDET JETZT AUF BEIDEN SEITEN. <<<
   *
   * Steht der Mast dicht HINTER einem Blech, ist der kuerzere Ausweg der
   * nach innen - und die Grenze ist eine untere Schranke. Vorher gab es nur
   * eine Richtung, weil nur das erste Blech zaehlte.
   */
  {
    const fr25 = AU.mastFreiraum(mach(2.5), 'A');
    wahr('Hinter dem Blech bindet sie von aussen', fr25.op === '>=', fr25.op);
    pruef('\u2026 an dessen hinterer Kante', fr25.grenze, 2.30 + 0.13, 1e-9, 'm');
    wahr('\u2026 und P9 prueft in dieser Richtung',
         p9(mach(2.5)).richtung === '>=' && p9(mach(2.5)).ok === true,
         `${p9(mach(2.5)).richtung} ${p9(mach(2.5)).status}`);
  }
  /*
   * MITTEN IM INNEREN BLECH fallt er weiterhin durch - das ist der Sinn der
   * Pruefung. Bei 2.20 m ueberschneidet der Flansch das Blech bei 2.25 um
   * 130 mm; der kuerzere Ausweg zeigt nach aussen.
   */
  wahr('Im inneren Blech faellt er', p9(mach(2.2)).ok === false);
  wahr('\u2026 und die Meldung nennt das Mass',
       /130 mm im liegenden Bindeblech/.test(p9(mach(2.2)).status), p9(mach(2.2)).status);

  // --- Ausleitung --------------------------------------------------------
  // DAS EIGENTLICHE ZIEL: Ersatzbalken und FEM-Modell muessen dasselbe
  // Tragwerk beschreiben. Bis zum 1. September setzte die Ausleitung den
  // Mast starr auf x = 0 und x = L, gleich was die Kragarmangabe sagte.
  const bau = AXM.stabmodell(m4, { knotenmodell: 'anschnitt' });
  const aufA = bau.auflager.filter((a) => a.ende === 'A');
  wahr('Das Auflager sitzt an der Mastachse',
       aufA.every((a) => Math.abs(a.x - 0.4) < 1e-9),
       [...new Set(aufA.map((a) => a.x))].join(' '));
  // Ohne Knoten dort haetten die Starrkoerper im Nichts gehangen.
  const knotenDort = [...bau.knoten.values()]
    .filter((k) => Math.abs(k.x - 0.4) < 1e-6 && /^(OG|UG)[LR]_/.test(k.name));
  pruef('Vier Gurtknoten an der Mastachse', knotenDort.length, 4, 1e-12, 'Stk');
  // Und der Gurt ist dort geteilt, nicht durchlaufend.
  const geteilt = bau.staebe.filter((st) => /^OGL_S/.test(st.name))
    .filter((st) => Math.abs(bau.knoten.get(st.bis).x - 0.4) < 1e-6);
  wahr('Der Gurtstab endet an der Mastachse', geteilt.length === 1);
}

// ===========================================================================
titel('56  Die Farbskala folgt den sichtbaren Ebenen');
// Weisung: die Skala auf die dargestellten Bauteile begrenzen. Die Masten
// tragen meist die groesste Einwirkung; blendet man sie aus, soll der
// Verlauf im Joch wieder auflesbar sein.
{
  const R56 = await import(J('render.3d.js'));
  const j56 = T.getTragjoch('J90');
  const e56 = rechne({
    ...basis(), ...typUebernehmen({ ...standardwerte() }, j56),
    typ: 'J90', L: 15.5, mastVorhanden: true, endbedingung: 'mast',
    mastProfil: 'HEB 260', mastH: 7.5, mastLaenge: 9,
  });
  const sz56 = R56.erzeugeSzene(e56.modell, e56);

  // Ohne Browser gibt es keine Ansicht; die Methode wird deshalb an einem
  // Traeger mit den paar Feldern aufgerufen, die sie liest.
  const traeger = {
    szene: sz56,
    ebenen: { profil: true, blech: true, mast: true, anbau: true },
    gruppen: {},
    _ebeneAn: R56.Modellansicht.prototype._ebeneAn,
    _bereichSichtbar: R56.Modellansicht.prototype._bereichSichtbar,
  };
  const bereich = (feld) => traeger._bereichSichtbar(feld);

  const mitMast = bereich('M');
  traeger._bereichCache = null;
  traeger.ebenen.mast = false;
  const ohneMast = bereich('M');

  wahr('Mit Masten regiert sein Moment die Skala', mitMast > 10,
       `${mitMast.toFixed(1)} kNm`);
  wahr('Ohne Masten bleibt das Joch unter sich', ohneMast < 5,
       `${ohneMast.toFixed(2)} kNm`);
  wahr('Der Unterschied ist erheblich, nicht kosmetisch',
       mitMast / ohneMast > 5, `Faktor ${(mitMast / ohneMast).toFixed(0)}`);

  // DER CACHE DARF NICHT LUEGEN. Er haengt am Zustand der Ebenen; wer ihn
  // nicht mitfuehrt, zeigt nach dem Umschalten die alte Skala.
  traeger.ebenen.mast = true;
  const wieder = bereich('M');
  pruef('Wieder eingeschaltet gilt wieder die grosse Skala',
        wieder, mitMast, 1e-9, 'kNm');

  // OHNE SICHTBARE WERTE keine Skala von null: dann gilt der Bereich der
  // ganzen Szene, denn eine Skala von null faerbte alles gleich.
  traeger._bereichCache = null;
  traeger.ebenen = { profil: false, blech: false, mast: false, anbau: false };
  pruef('Ohne sichtbare Fläche gilt der Bereich der Szene',
        bereich('M'), sz56.bereiche.M, 1e-9, 'kNm');
}

// ===========================================================================
titel('57  Tastenkuerzel lassen sich abschalten');
// Weisung: die erweiterten Kuerzel unter Optionen deaktivierbar machen.
// Gemeint sind die EINZELNEN Tasten; Escape und Strg+Z bleiben immer.
{
  const SCH57 = await import(J('ui.schema.js'));
  const f57 = SCH57.FELDER.find((x) => x.key === 'tastenkuerzel');
  wahr('Es gibt den Schalter', !!f57);
  wahr('Er steht im Optionsdialog', f57.optionenDialog === true);
  wahr('Und im Startwert EIN', f57.standard === true);
  wahr('standardwerte() traegt ihn so', SCH57.standardwerte().tastenkuerzel === true);
  wahr('Er steht unter Darstellung',
       SCH57.OPTIONEN_ABSCHNITTE.some((a) => a.thema === 'ansicht'
                                          && a.keys.includes('tastenkuerzel')));

  /*
   * DIE VIER SPERREN, am Quelltext festgehalten - ausfuehren laesst sich der
   * Handler ohne DOM nicht.
   */
  const aq57 = APP_QUELLE();
  const ab = aq57.indexOf('function tastendruck');
  const bis = aq57.indexOf('function dialogTasten');
  const koerper = aq57.slice(ab, bis > ab ? bis : undefined);
  wahr('Sperre 1: jedes Eingabefeld', koerper.includes('imFeld'));
  wahr('Sperre 2: offener Dialog', koerper.includes("querySelector('.dialog')"));
  wahr('Sperre 3: Sondertasten', koerper.includes('e.altKey'));
  wahr('Sperre 4: der Schalter', koerper.includes("tastenkuerzel === false"));
  // ESCAPE UND STRG+Z STEHEN VOR ALLEN SPERREN - sie duerfen nie ausfallen.
  wahr('Escape wird vor den Sperren behandelt',
       koerper.indexOf("'Escape'") < koerper.indexOf('imFeld'));
  wahr('Strg+Z ebenso',
       koerper.indexOf('e.ctrlKey || e.metaKey') < koerper.indexOf("tastenkuerzel === false"));
}

// ===========================================================================
titel('58  Der Sparmodus haelt nicht laenger als seine Bewegung');
// Gemeldet am 1. September: nach dem Deaktivieren des Masten zeigte das Joch
// nur noch die Schwerelinien, keinen Koerper mehr.
//
// URSACHE: `sparsam` laesst die Volumenflaechen weg und behaelt die Achsen -
// waehrend man am Fensterrand zieht, zaehlt die Bildfolge mehr als das
// Volumen. Ein Klick auf einen Ebenenschalter baut aber die Werkzeugleiste
// neu, das aendert die Groesse der Zeichenflaeche, und der ResizeObserver
// meldet eine Aenderung. Das folgende zeichne() traf auf ein gesetztes
// `sparsam` und liess die Koerper weg - bis zur naechsten Groessenaenderung,
// also womoeglich nie.
{
  const R58 = await import(J('render.3d.js'));
  const q58 = readFileSync(new URL('./js/render.3d.js', import.meta.url), 'utf8');

  // Die Flaechen haengen am Kennzeichen - das ist die Stelle, an der sich der
  // Fehler zeigte.
  wahr('Ohne sparsam keine Volumenflaechen',
       q58.includes('if (!this.sparsam) this.szene.flaechen.forEach'));

  // UND ZEICHNEN SETZT ES ZURUECK, ausser man verlangt es ausdruecklich.
  const ab = q58.indexOf('  zeichne({ sparsam = false } = {}) {');
  wahr('zeichne() nimmt die Sparsamkeit als Angabe', ab > 0);
  const koerper58 = q58.slice(ab, q58.indexOf('zeichneJetzt', ab));
  wahr('… und setzt sie sonst zurueck',
       koerper58.includes('if (!sparsam) this.sparsam = false;'));

  // Die Groessenaenderung behaelt ihren Weg: sie ruft _male() unmittelbar und
  // wird von der Aenderung an zeichne() nicht beruehrt. Gesucht wird die
  // DEFINITION, nicht die erste Erwaehnung des Namens.
  const abG = q58.indexOf('  passeGroesseAn(');
  wahr('Es gibt passeGroesseAn', abG > 0);
  const koerperG = q58.slice(abG);
  wahr('Die Groessenaenderung malt unmittelbar', koerperG.includes('this._male();'));
  wahr('Sie setzt das Kennzeichen selbst',
       koerperG.includes('this.sparsam = jetzt - '));
  wahr('Und stellt danach voll nach', koerperG.includes('this.sparsam = false;'));
}

// ===========================================================================
titel('59  Bewegung: eine Vorgabe fuer die ganze Anwendung');
// Weisung: die Animation nicht so abgehackt, und das soll global gelten.
//
// Vorher stand in zwanzig Regeln eine eigene Zahl - .12s, .14s, .15s, .18s,
// .2s, .22s, .3s. Keine war falsch, aber zusammen ergaben sie kein
// Verhalten, sondern zwanzig.
{
  const css59 = readFileSync(new URL('./css/style.css', import.meta.url), 'utf8');

  // --- Die Tokens gibt es --------------------------------------------------
  ['--t-schnell', '--t-mittel', '--t-ruhig', '--t-kurve'].forEach((k) => {
    wahr(`Es gibt ${k}`, css59.includes(`${k}:`));
  });

  /*
   * DIE KURVE STECKT IM TOKEN, nicht in einer eigenen Regel.
   *
   * Der erste Versuch setzte sie auf den Sternwaehler. Das wirkte nicht: die
   * Kurzform «transition: background .12s» schreibt ALLE Untereigenschaften,
   * also auch die Kurve, und setzt sie dabei auf «ease» zurueck. Am Knopf
   * stand danach weiter «ease, ease, ease».
   */
  ['--t-schnell', '--t-mittel', '--t-ruhig'].forEach((k) => {
    const zeile = css59.split('\n').find((z) => z.trim().startsWith(`${k}:`)) ?? '';
    wahr(`${k} traegt die Kurve mit`, zeile.includes('var(--t-kurve)'), zeile.trim());
  });

  // --- Keine verstreuten Zahlen mehr ---------------------------------------
  // OHNE KOMMENTARE. Der Text ueber den Tokens nennt die Kurzform als
  // Beispiel; eine Pruefung, die den eigenen Erklaertext mitliest, findet
  // Fehler, wo keine sind.
  const ohneKommentar = css59.replace(/[/][*][\s\S]*?[*][/]/g, '');
  const zeilen59 = ohneKommentar.split('\n').filter((z) => z.includes('transition:'));
  const ohneToken = zeilen59.filter((z) => !z.includes('var(--t-'));
  wahr('Jede Uebergangsregel benutzt ein Token', ohneToken.length === 0,
       ohneToken.slice(0, 2).map((z) => z.trim().slice(0, 60)).join(' | ') || 'alle');
  wahr('Und es sind nicht nur zwei', zeilen59.length > 15,
       `${zeilen59.length} Regeln`);

  // --- Wer keine Bewegung will, bekommt keine ------------------------------
  // Die Vorgabe des Betriebssystems sticht alles. Sie war schon da und darf
  // durch die Tokens nicht verlorengehen.
  wahr('prefers-reduced-motion bleibt beruecksichtigt',
       css59.includes('prefers-reduced-motion'));
  wahr('… und schaltet auf einen Wimpernschlag, nicht auf null',
       css59.includes('transition-duration: .01ms !important'));

  // --- Der Dialog bewegt seine Hoehe ---------------------------------------
  wahr('interpolate-size erlaubt den Uebergang auf auto',
       css59.includes('interpolate-size: allow-keywords'));
  const abD = css59.indexOf('.dialog-reiter {');
  const blockD = abD > 0 ? css59.slice(abD, css59.indexOf('}', abD)) : '';
  wahr('Der Reiterdialog bewegt seine Hoehe',
       blockD.includes('transition: height'), blockD.trim().slice(0, 70));
  wahr('… und bleibt oben verankert', blockD.includes('align-self: flex-start'));
}

// ===========================================================================
titel('60  Die Hoehe des Optionsdialogs wandert');
// Frage des Auftraggebers: funktioniert die Animation beim Umschalten der
// Themenbereiche? Sie tat es NICHT, und der Grund ist lehrreich.
{
  const aq60 = APP_QUELLE();
  const css60 = readFileSync(new URL('./css/style.css', import.meta.url), 'utf8');

  /*
   * WARUM CSS ALLEIN NICHT REICHT.
   *
   * `transition: height` braucht einen Startwert; eine Hoehe aus dem Inhalt
   * hat keinen. Auch mit `height: auto` und `interpolate-size` sprang sie -
   * nachgemessen von 308 auf 794 px, und vierzehn Bilder hintereinander
   * zeigten bereits den Endwert. Der Grund ist der harte Austausch: der ganze
   * Rahmen wird durch innerHTML ersetzt, und der Browser sieht keinen
   * Zwischenzustand.
   */
  wahr('Der Reiterwechsel laesst die Hoehe wandern',
       aq60.includes('const hoeheWandern'));
  wahr('… und der Reiterknopf benutzt sie',
       aq60.includes('hoeheWandern(neu)'));

  const ab = aq60.indexOf('const hoeheWandern');
  const koerper = aq60.slice(ab, aq60.indexOf('const neu =', ab));
  /*
   * ZWISCHEN DEN BEIDEN MESSUNGEN LIEGT DER TAUSCH.
   *
   * Nicht der erste `tauschen()` im Text zaehlt - das ist der Notausstieg
   * fuer Browser ohne animate(). Geprueft wird der Abschnitt ZWISCHEN den
   * beiden Messungen; dort muss er stehen.
   */
  {
    const iVon = koerper.indexOf('const von');
    const iBis = koerper.indexOf('const bis');
    wahr('Beide Messungen stehen in dieser Reihenfolge', iVon > 0 && iVon < iBis);
    wahr('Und dazwischen wird getauscht',
         koerper.slice(iVon, iBis).includes('tauschen()'));
  }
  wahr('Ohne Aenderung keine Bewegung',
       koerper.includes('Math.abs(bis - von) < 1'));
  // DIE DAUER KOMMT AUS DER VORGABE, nicht aus einer eigenen Zahl - sonst
  // liefe sie an der globalen Bewegungsvorgabe vorbei.
  wahr('Die Dauer kommt aus dem Token',
       koerper.includes("getPropertyValue('--t-ruhig')"));
  wahr('Und die Kurve ist die der Anwendung',
       koerper.includes('cubic-bezier(.22, 1, .3, 1)'));
  // KEINE FESTE HOEHE BLEIBT STEHEN: animate() faellt von selbst zurueck,
  // eine gesetzte Stilangabe taete das nicht.
  wahr('Es bleibt keine feste Hoehe stehen',
       !koerper.includes('style.height ='));

  // Die CSS-Seite bleibt, wie sie war: oben verankert, Hoehe nach Inhalt.
  const abD = css60.indexOf('.dialog-reiter {');
  const blockD = abD > 0 ? css60.slice(abD, css60.indexOf('}', abD)) : '';
  wahr('Der Dialog bleibt oben verankert', blockD.includes('align-self: flex-start'));
  wahr('Und seine Hoehe folgt dem Inhalt', blockD.includes('height: auto'));
}

// ===========================================================================
// PRUEFUNG 61: die Skala umfasst nur, was zu sehen ist - und die Legende
// sagt es auch. Weisung vom 1. September, nachdem der zweite Teil fehlte.
{
  const aq61 = APP_QUELLE();
  const r61 = readFileSync(new URL('./js/render.3d.js', import.meta.url), 'utf8');
  const idx61 = readFileSync(new URL('./index.html', import.meta.url), 'utf8');
  const css61 = readFileSync(new URL('./css/style.css', import.meta.url), 'utf8');

  /*
   * DIE KOERPER FOLGTEN DER SICHTBARKEIT SCHON, DIE LEGENDE NICHT.
   *
   * Nachgemessen mit ausgeblendetem Masten: die Koerper zeigten die Spanne
   * bis 1.12 kNm, die Legende behauptete weiter 69.28 - denn das Umschalten
   * einer Ebene rief `zeichne()`, aber nicht `zeichneLegende()`.
   */
  {
    const ab = aq61.indexOf('const nach = () => {');
    const koerper = ab > 0 ? aq61.slice(ab, aq61.indexOf('};', ab)) : '';
    wahr('Das Umschalten einer Ebene zeichnet neu',
         koerper.includes('ansicht.zeichne()'));
    wahr('… und die Legende gleich mit', /zeichneLegende\((app)?\)/.test(koerper));
  }
  wahr('Die Skala zaehlt nur eingeschaltete Ebenen',
       r61.includes('_bereichSichtbar(feld)')
       && r61.includes('if (f.gruppe && !this._ebeneAn(f.gruppe)) return;'));

  // DER TITEL GEHOERT ZUM BAUTEIL. Ist der Mast aus, stand sein Profil
  // sonst ueber leerem Grund.
  wahr('Der Masttitel traegt seine Ebene',
       r61.includes("tab: 'system', gruppe: 'mast'"));
  wahr('… und ausgeblendete Titel entfallen',
       r61.includes('if (bt.gruppe && !this._ebeneAn(bt.gruppe)) return;'));
  /*
   * DER JOCHTITEL NICHT: er benennt das TRAGWERK, nicht die Gurte. Mit
   * gruppe: 'gurt' verschwand er beim ersten Versuch ganz - den Schluessel
   * gibt es nicht, er heisst 'profil', und _ebeneAn meldete false.
   */
  {
    /*
     * DER ANKER IST DIE LAGE, nicht der Text: der Titel traegt seit dem
     * 3. September die Positionsnummer davor (P2 · J90 · 20.00 m), und ein
     * Anker im Text zerbricht bei jeder Anschrift neu. Die Aussage bleibt
     * dieselbe - kein `gruppe:` am Jochtitel.
     */
    const ab = r61.indexOf('p: [m.L / 2, 0, zOK + 0.95],');
    const koerper = ab > 0 ? r61.slice(ab, r61.indexOf('});', ab)) : '';
    wahr('Der Jochtitel bleibt ungebunden',
         koerper.length > 0 && !koerper.includes('gruppe:'));
  }

  // NUR DER RAHMEN LEUCHTET AUF, nicht die Schrift (Weisung): man faehrt
  // beim Drehen vielmal unbewusst darueber.
  {
    /*
     * DAS FENSTER WURDE GROESSER, weil der Rumpf es wurde: seit dem
     * 2. September steht davor der Zweig fuer die passiven Titel (sie
     * werden gedaempft gezeichnet und sind nicht anklickbar). Die Aussage
     * bleibt dieselbe - nur der Rahmen leuchtet auf, nicht die Schrift.
     */
    const ab = r61.indexOf('const warm = this._titelUnterZeiger === bt;');
    const koerper = ab > 0 ? r61.slice(ab, ab + 2600) : '';
    wahr('Der Rahmen folgt dem Zeiger', koerper.includes('warm ? t.acc'));
    wahr('… die Schrift aber nicht',
         koerper.includes('c.fillStyle = t.on2 ?? t.on;')
         && !koerper.includes('warm ? t.acc : (t.on2'));
    wahr('… und der Grund behaelt seine Deckung',
         koerper.includes('c.globalAlpha = 0.72;'));
  }

  // DIE BEIDEN KOPFLEISTEN SIND WEG (Weisung) - damit stehen die Reiter
  // beider Seitenspalten auf gleicher Hoehe. Nachgemessen: 46 px und 46 px.
  wahr('Keine Kopfleiste mehr im Rumpf', !idx61.includes('panel-kopf'));
  wahr('… und keine Regel dafuer im Stil', !css61.includes('.panel-kopf'));
  wahr('… und niemand schreibt mehr hinein',
       !aq61.includes("el('modell-info')") && !aq61.includes('modellInfoText'));
  // Der Fehlerfall beim Bildeinlesen braucht dafuer einen anderen Weg.
  wahr('Der Handlungsbalken traegt jetzt die Meldung',
       aq61.includes('function meldeImBalken')
       && aq61.includes('meldeImBalken(`Das Bild'));
}

// ===========================================================================
// PRUEFUNG 62: die Messoption fuer die schiefe Biegung im PyNite-Export.
// Sie dient der Kalibrierung und darf die Ausleitung NICHT anfassen.
{
  const { pyniteSkript } = await import(J('export.pynite.js'));
  const { winkelwerteFuer } = await import(J('core.winkel.js'));
  const m62 = modell(
    { ...standardwerte(), typ: 'J90', L: 15, mastVorhanden: false },
    getProfil(T.getTragjoch('J90').og.profil),
    getProfil(T.getTragjoch('J90').ug.profil),
    getStahl('S235'), T.getTragjoch('J90'));

  const normal = pyniteSkript(m62, { knotenmodell: 'anschnitt' }).text;
  const schief = pyniteSkript(m62, { knotenmodell: 'anschnitt',
                                     gurteSchief: true }).text;

  /*
   * OHNE DIE OPTION AENDERT SICH NICHTS.
   *
   * Das ist die wichtigste der Kontrollen: was der Auftraggeber ausleitet,
   * fuehrt die Gurte schenkelparallel, wie jedes Pruefmodell.
   */
  wahr('Der normale Export dreht keinen Stab', !normal.includes('rotation='));

  // MIT DER OPTION DREHEN GENAU DIE GURTE - und zwar gegeneinander.
  const drehungen = [...schief.matchAll(
    /add_member\('((?:OG|UG)(?:L|R))_S\d+'[^)]*rotation=(-?[\d.]+)/g)]
    .map((t) => ({ ecke: t[1], rot: Number(t[2]) }));
  wahr('Mit der Option drehen sich Gurtstaebe', drehungen.length > 0);
  wahr('… und zwar um 45 Grad', drehungen.every((d) => Math.abs(d.rot) === 45));
  const je = (e) => drehungen.filter((d) => d.ecke === e).map((d) => d.rot);
  const einheitlich = (e) => je(e).length > 0 && new Set(je(e)).size === 1;
  wahr('Jede Ecke dreht einheitlich',
       ['OGL', 'OGR', 'UGL', 'UGR'].every(einheitlich));
  /*
   * DAS MUSTER IST DIE SACHE. Die beiden Gurte einer Ebene muessen
   * GEGENEINANDER drehen - stuenden sie gleichsinnig, wichen sie gemeinsam
   * aus und die Bleche bekaemen fast nichts. Genau darauf beruht der ganze
   * Ansatz (SCHIEFE_BIEGUNG in core.querschnitt.js).
   */
  wahr('Die Gurte einer Horizontalebene drehen gegeneinander',
       je('OGL')[0] === -je('OGR')[0] && je('UGL')[0] === -je('UGR')[0]);
  wahr('… und die einer Vertikalebene ebenso',
       je('OGL')[0] === -je('UGL')[0] && je('OGR')[0] === -je('UGR')[0]);

  // DER QUERSCHNITT WECHSELT AUF DIE HAUPTACHSEN. Ohne das waere die
  // Drehung wirkungslos: ein Querschnitt mit Iy = Iz ist drehsymmetrisch.
  {
    const wOG = winkelwerteFuer(getProfil(T.getTragjoch('J90').og.profil));
    const zeile = /add_section\('GURT_OG', ([^)]*)\)/.exec(schief);
    wahr('Der Gurtquerschnitt steht in Hauptachsen', !!zeile
      && Math.abs(Number(zeile[1].split(',')[1]) - wOG.I1 / 1e12)
         < wOG.I1 / 1e12 * 1e-9);
    const zeileN = /add_section\('GURT_OG', ([^)]*)\)/.exec(normal);
    wahr('… und im normalen Export schenkelparallel', !!zeileN
      && Math.abs(Number(zeileN[1].split(',')[1]) - wOG.Iz / 1e12)
         < wOG.Iz / 1e12 * 1e-9);
    // Beim gleichschenkligen Winkel sind Iy und Iz gleich - erst die
    // Hauptachsen unterscheiden sich, und zwar deutlich.
    wahr('Die Hauptachsen unterscheiden sich wirklich', wOG.I1 > 3 * wOG.I2);
  }
}

// ===========================================================================
// PRUEFUNG 63: die Verortung im Kopf.
// Seit dem Wegfall der Kopfleiste ueber dem Modell gab es beim Rechnen keine
// Stelle mehr, die sagte, WELCHES Tragwerk auf dem Tisch liegt. Sie steht
// jetzt im Projektknopf - neben Projekt und Name, bei den uebrigen Angaben,
// die das Tragwerk benennen statt es zu beschreiben.
{
  const aq63 = APP_QUELLE();
  const css63 = readFileSync(new URL('./css/style.css', import.meta.url), 'utf8');

  wahr('Der Kopf holt die Verortung aus der einen Stelle',
       /import \{[^}]*\bverortung\b[^}]*\}\s*from '\.\/core\.constants\.js'/
         .test(aq63));

  {
    const ab = aq63.indexOf('function aktualisiereProjektKnopf()');
    const koerper = ab > 0 ? aq63.slice(ab, aq63.indexOf('\n}', ab)) : '';
    wahr('Der Projektknopf traegt die Verortung',
         koerper.includes('class="tb-ort"') && koerper.includes('esc(ort)'));
    // Drei leere Trennzeichen sagen nichts: ohne Angabe faellt sie ganz weg.
    wahr('… und laesst sie weg, wenn nichts eingetragen ist',
         /\(ort \?[^\n]*tb-ort/.test(koerper));
    // Der Name des Tragwerks bleibt das Erste; die Verortung ergaenzt ihn.
    wahr('… hinter dem Namen, nicht davor',
         koerper.indexOf('<b>') > 0
         && koerper.indexOf('<b>') < koerper.indexOf('tb-ort'));
  }

  /*
   * SIE ZIEHT SOFORT NACH. Waehrend Linie und Kilometer getippt werden, steht
   * der Speicherzustand laengst auf «ungesichert» - haengt das Neuzeichnen
   * allein daran, bleibt der Knopf stehen. Der Vergleich muss deshalb VOR dem
   * fruehen Ruecksprung stehen.
   */
  {
    const ab = aq63.indexOf('function pruefeUngesichert()');
    const koerper = ab > 0 ? aq63.slice(ab, aq63.indexOf('\n}', ab)) : '';
    const vergleich = koerper.indexOf('gezeigteVerortung');
    const ruecksprung = koerper.indexOf('gesicherteSignatur === null) return');
    wahr('Die Verortung im Knopf zieht bei jeder Eingabe nach',
         vergleich > 0 && ruecksprung > 0 && vergleich < ruecksprung);
    wahr('… und zeichnet nur bei echter Aenderung neu',
         /ort !== gezeigteVerortung/.test(koerper));
  }

  /*
   * DAS FELD BLEIBT UNTER DEM CURSOR STEHEN. verdrahteOptionen meldet jede
   * Taste und markiert sie als Zwischenstand; wer das uebergeht, ersetzt das
   * Feld beim Tippen und verliert den Fokus nach dem ersten Buchstaben.
   */
  {
    const ab = aq63.indexOf("ui.verdrahteOptionen(ui.el('bs-verortung')");
    const koerper = ab > 0 ? aq63.slice(ab, aq63.indexOf('\n  });', ab)) : '';
    wahr('Die Verortungsfelder kennen den Zwischenstand',
         /\(k, v, zwischenstand\)/.test(koerper));
    wahr('… und zeichnen erst beim Verlassen neu',
         koerper.indexOf('if (zwischenstand) return;') > 0
         && koerper.indexOf('if (zwischenstand) return;')
            < koerper.indexOf('zeichneSchublade(app)'));
  }

  {
    const ab = css63.indexOf('.tb-ort {');
    const regel = ab > 0 ? css63.slice(ab, css63.indexOf('}', ab)) : '';
    wahr('Die Verortung steht leiser als der Name', regel.includes('var(--dim)'));
    /*
     * BEIM EINKLAPPEN GIBT SIE ALS ERSTE NACH. Ohne min-width: 0 legt flex
     * jedem Kind den Boden seines laengsten Wortes unter - die Verortung
     * bliebe stehen und der Knopf schnitte stattdessen hinten ab.
     */
    const kleiner = /flex-shrink:\s*(\d+)/.exec(regel);
    wahr('… und gibt beim Einklappen als Erste nach',
         regel.includes('min-width: 0') && !!kleiner && Number(kleiner[1]) > 1);
    wahr('… mit Auslassungspunkten statt hartem Schnitt',
         regel.includes('text-overflow: ellipsis'));
  }
}

// ===========================================================================
// PRUEFUNG 63: die Verortung steht im Kopf. Sie unterscheidet die Tragwerke
// eines Projekts - der Jochtyp tut das nicht, ein Projekt hat viele J90.
{
  const aq63 = APP_QUELLE();
  const css63 = readFileSync(new URL('./css/style.css', import.meta.url), 'utf8');

  const ab = aq63.indexOf('function aktualisiereProjektKnopf');
  const koerper = ab > 0 ? aq63.slice(ab, aq63.indexOf('\n}', ab)) : '';
  wahr('Der Projektknopf holt die Verortung', koerper.includes('verortung(werte)'));
  // WAS FEHLT, FAELLT WEG: drei leere Trennzeichen sagen nichts.
  wahr('… und zeigt sie nur, wenn es sie gibt', koerper.includes('ort ?'));
  // Gelesen wird, ob der Name im Import steht - nicht an welcher Stelle.
  wahr('Die Einfuhr steht wieder',
       /import \{[^}]*\bverortung\b[^}]*\}\s*from '\.\/core\.constants\.js'/.test(aq63));
  wahr('Und der Stil daempft sie', css63.includes('.tb-ort'));

  /*
   * SIE ZIEHT NACH, OHNE AM SPEICHERZUSTAND ZU HAENGEN.
   *
   * Der Knopf wurde nur neu gezeichnet, wenn der Zustand wechselte. Wer die
   * Verortung nachtraegt, steht laengst auf «ungesichert» - sie waere erst
   * verspaetet erschienen.
   */
  {
    const a2 = aq63.indexOf('function pruefeUngesichert');
    const k2 = a2 > 0 ? aq63.slice(a2, aq63.indexOf('\n}', a2)) : '';
    wahr('Eine geaenderte Verortung zeichnet den Knopf neu',
         k2.includes('gezeigteVerortung') && k2.includes('zeigeSpeicherstand()'));
  }

  // Die Reihenfolge der Angaben ist Weisung: vom Groben zum Feinen.
  const { verortung: v63 } = await import(J('core.constants.js'));
  wahr('Linie, Ort, Kilometer - in dieser Reihenfolge',
       v63({ linie: '600', ortschaft: 'Schwyz', km: '016.661' })
       === 'Linie 600 · Schwyz · KM 016.661');
  wahr('Ohne Eintrag bleibt sie leer', v63({}) === '');
  wahr('Und einzelne Luecken fallen einzeln weg',
       v63({ ortschaft: 'Schwyz', km: '016.661' }) === 'Schwyz · KM 016.661');
}

// ===========================================================================
// PRUEFUNG 64: die Tragwerksart als Weiche. Weisung vom 28. August («die
// Haupttragwerke sollten global gesteuert werden»), gebaut am 2. September.
{
  const { TRAGWERKSARTEN, tragwerksart: art64, hatTraeger } =
    await import(J('core.constants.js'));
  const { GRUPPEN: G64, gruppeGilt, sichtbareFelder } =
    await import(J('ui.schema.js'));
  const UI64 = await import(J('ui.js'));
  const { BAUFORMEN_KEYS, bauformSkizze } =
    await import(J('doku.optionsskizzen.js'));

  // Vier seit dem 2. September: das Abfangjoch kam dazu (Typ A, zwei
  // UPE-Gurte mit Sprossen - nicht der vierteilige Vierendeel).
  wahr('Vier Tragwerksarten', TRAGWERKSARTEN.length === 4);
  wahr('Das Abfangjoch hat zwei Masten',
       TRAGWERKSARTEN.find((a) => a.key === 'abfangjoch')?.masten === 2);
  /*
   * ALTE DATEIEN RECHNEN UNVERAENDERT. Fehlt die Angabe, ist es ein
   * Tragjoch - das war bis zum 2. September der einzige Fall. Dasselbe
   * Vorgehen wie bei `mastVorhanden`.
   */
  wahr('Ohne Angabe gilt das Tragjoch', art64({}).key === 'joch');
  wahr('… auch bei unbekanntem Wert', art64({ tragwerksart: 'quatsch' }).key === 'joch');
  wahr('Der Einzelmast hat keinen Traeger',
       hatTraeger({ tragwerksart: 'einzelmast' }) === false);
  wahr('Joch und Tragausleger haben einen',
       hatTraeger({ tragwerksart: 'joch' })
       && hatTraeger({ tragwerksart: 'tragausleger' }));

  // JEDE ART HAT IHR BILD. Eine Karte ohne Skizze waere ein leeres Feld,
  // und die Wahl haengt genau an diesem Bild.
  wahr('Jede Art ist gezeichnet',
       TRAGWERKSARTEN.every((a) => BAUFORMEN_KEYS.includes(a.key)));
  wahr('… und die Skizze traegt wirklich etwas',
       TRAGWERKSARTEN.every((a) => bauformSkizze(a.key).includes('<svg')));

  /*
   * DER TRAGAUSLEGER IST OBEN ABGESPANNT, NICHT UNTEN ABGESTREBT.
   *
   * Hier stand zuerst ein Dreieck mit einer Strebe von unten - das Gegenteil
   * dessen, was das Querprofil zeigt. Es ist kein Zeichenfehler, sondern ein
   * statischer: die Schraege ist ein ZUGband vom Mastkopf ans freie Ende.
   * Eine Strebe von unten waere ein Druckstab und braeuchte einen
   * Knicknachweis, den es hier nicht gibt.
   *
   * Geprueft wird an den Koordinaten: der Mast steht rechts (grosses x), der
   * Ausleger kragt nach links. Das Band muss am Mast OBEN beginnen (kleines
   * y) und links TIEFER ankommen.
   */
  {
    const svg = bauformSkizze('tragausleger');
    const linien = [...svg.matchAll(
      /<line[^>]*x1="(\d+)"[^>]*y1="(\d+)"[^>]*x2="(\d+)"[^>]*y2="(\d+)"/g)]
      .map((t) => ({ x1: +t[1], y1: +t[2], x2: +t[3], y2: +t[4] }));
    // Schraege Linien mit nennenswerter Laenge - das Band ist die einzige.
    const schraeg = linien.filter((l) => l.y1 !== l.y2 && l.x1 !== l.x2
                                      && Math.abs(l.x1 - l.x2) > 40);
    wahr('Genau ein Zugband in der Skizze', schraeg.length === 1);
    const b = schraeg[0];
    if (b) {
      const amMast = b.x1 > b.x2 ? { x: b.x1, y: b.y1 } : { x: b.x2, y: b.y2 };
      const amEnde = b.x1 > b.x2 ? { x: b.x2, y: b.y2 } : { x: b.x1, y: b.y1 };
      wahr('Es beginnt am Masten, also rechts', amMast.x > 140);
      wahr('… oben am Kopf', amMast.y < 40);
      wahr('… und kommt am freien Ende tiefer an', amEnde.y > amMast.y);
    }
    // Der Mast ragt UEBER den Ausleger hinaus - sonst gaebe es keinen Punkt,
    // an dem das Band ansetzen koennte.
    const mast = linien.find((l) => l.x1 === l.x2 && Math.abs(l.y1 - l.y2) > 60);
    const ausleger = linien.find((l) => l.y1 === l.y2 && Math.abs(l.x1 - l.x2) > 80);
    wahr('Der Mast ragt ueber den Ausleger hinaus',
         !!mast && !!ausleger && Math.min(mast.y1, mast.y2) < ausleger.y1 - 15);
  }

  // BEIDE MASTKARTEN STEHEN GLEICH HERUM: Mast rechts, Ausleger nach links,
  // wie auf dem Querprofil. Spiegelverkehrt waeren sie schwer zu vergleichen.
  {
    const mastX = (key) => {
      const l = [...bauformSkizze(key).matchAll(
        /<line[^>]*x1="(\d+)"[^>]*y1="(\d+)"[^>]*x2="(\d+)"[^>]*y2="(\d+)"/g)]
        .map((t) => ({ x1: +t[1], y1: +t[2], x2: +t[3], y2: +t[4] }))
        .find((z) => z.x1 === z.x2 && Math.abs(z.y1 - z.y2) > 60);
      return l ? l.x1 : null;
    };
    wahr('Der Mast steht bei beiden Arten rechts',
         mastX('einzelmast') > 100 && mastX('tragausleger') > 100);
  }

  /*
   * WAS NICHT GILT, VERSCHWINDET. Beim Einzelmast gibt es keinen Traeger -
   * also keinen Jochtyp, keine Gurtprofile, keine Bindebleche, keine
   * Auflagerung eines Jochs.
   */
  const em = { tragwerksart: 'einzelmast' };
  const jo = { tragwerksart: 'joch' };
  /*
   * Die Gruppe 'typ' ist am 13. September in 'geo' aufgegangen - ein
   * Abschnitt mit einem einzigen Feld, dessen Masse im naechsten standen
   * (Weisung: «sidebar system aufraeumen»).
   */
  ['geo', 'blech', 'stueck'].forEach((gid) => {
    wahr(`Gruppe ${gid} entfaellt beim Einzelmast`, gruppeGilt(gid, em) === false);
    wahr(`… und gilt beim Joch`, gruppeGilt(gid, jo) === true);
  });
  /* =======================================================================
   * >>> DER PROFILREITER IST DIE AUSNAHME. <<<
   * =======================================================================
   *
   * Weisung vom 11. September: «alle ergaenzten bauteile unter profile
   * nachfuehren, so wie bei den tragjochen.»
   *
   * Er stand hier in der Liste dessen, was beim Einzelmasten entfaellt - zu
   * Recht, solange er nur die zwei Winkelgurte fuehrte. Inzwischen traegt er
   * die PROFILTAFEL aller Bauteile (Gurte, Masten, Anker) und die
   * Stahlguete, und beides gilt jedem Tragwerk.
   *
   * Die Gurtfelder blenden sich weiterhin selbst aus - ueber `sichtbar` am
   * FELD, nicht ueber die Gruppe. Das ist derselbe Weg, den das Auflager
   * schon geht.
   * ===================================================================== */
  wahr('Gruppe prof gilt jeder Tragwerksart',
       ['joch', 'einzelmast', 'abfangjoch', 'tragausleger']
         .every((a) => gruppeGilt('prof', { tragwerksart: a }) === true));
  {
    const feldGilt = (key, w) => {
      const f = FELDER.find((x) => x.key === key);
      return !f?.sichtbar || f.sichtbar(w) === true;
    };
    wahr('… aber die Gurtfelder nur am Vierendeeltraeger',
         feldGilt('profOG', jo) === true
         && feldGilt('profOG', em) === false
         && feldGilt('profOG', { tragwerksart: 'abfangjoch' }) === false);
    wahr('… und die Stahlguete ueberall',
         ['joch', 'einzelmast', 'abfangjoch']
           .every((a) => feldGilt('stahl', { tragwerksart: a }) === true));
  }
  /*
   * >>> DAS AUFLAGER GEHT UEBER DIE FELDER, NICHT UEBER DIE GRUPPE. <<<
   *
   * Weisung vom 9. September: eine einzige Gruppe fuers Auflager. Sie fuehrt
   * seither keine Artenschranke mehr - sonst saehe das Abfangjoch sie nie,
   * und genau dort ist die Bedingung am Masten einzustellen. Was nur den
   * Ersatzbalken des Tragjochs betrifft, traegt die Schranke am FELD.
   *
   * Geprueft wird deshalb das Ergebnis: beim Einzelmasten steht dort kein
   * Feld, und die Gruppe erscheint gar nicht (zeichneMaske laesst eine
   * leere Gruppe weg).
   */
  wahr('Gruppe aufl gilt formal fuer jede Art', gruppeGilt('aufl', em) === true);
  wahr('… hat beim Einzelmast aber kein Feld',
       sichtbareFelder('aufl', em).length === 0);
  wahr('… und beim Joch ihre Endbedingung',
       sichtbareFelder('aufl', jo).some((f) => f.key === 'endbedingung'));
  /*
   * DIE AUFLAGERBEDINGUNG AM MASTEN steht jetzt ebenfalls dort - beim Joch
   * wie beim Abfangjoch, sobald ein Mast im Modell ist.
   */
  const mitMast = (art) => ({ tragwerksart: art, mastVorhanden: true });
  ['joch', 'abfangjoch'].forEach((art) => {
    wahr(`Die Auflagerbedingung steht beim ${art} in der Gruppe Auflager`,
         sichtbareFelder('aufl', mitMast(art)).some((f) => f.key === 'auflagerLinks'));
  });
  wahr('… und beim Einzelmasten nirgends',
       ['aufl', 'mast'].every((g) =>
         !sichtbareFelder(g, mitMast('einzelmast'))
           .some((f) => f.key === 'auflagerLinks')));
  wahr('Die Gruppe Masten fuehrt sie nicht mehr',
       !sichtbareFelder('mast', mitMast('joch'))
         .some((f) => f.key === 'auflagerLinks'));
  // Die Masten und die Lasten gelten immer - sie sind bei jeder Art da.
  ['art', 'mast', 'trasse', 'anbau', 'ein', 'komb'].forEach((gid) => {
    wahr(`Gruppe ${gid} gilt bei jeder Art`,
         gruppeGilt(gid, em) && gruppeGilt(gid, jo));
  });

  /*
   * EINE QUELLE FUER SIGNATUR UND ZEICHNUNG.
   *
   * Zwei getrennte Listen waren der Fehler, an dem die Bauformwahl zuerst
   * scheiterte: gezeichnet wurde gefiltert, die Signatur zaehlte
   * ungefiltert - sie blieb beim Umschalten gleich, die Maske wurde nicht
   * neu gebaut, und die angeklickte Karte sprang zurueck.
   */
  wahr('Der Systemreiter zeigt beim Joch mehr Gruppen als beim Einzelmast',
       UI64.gruppenFuer('system', jo).length
       > UI64.gruppenFuer('system', em).length);
  wahr('Und die Signatur unterscheidet die Arten',
       UI64.maskenSignatur(jo, 'system') !== UI64.maskenSignatur(em, 'system'));

  // WAS NICHT GERECHNET WIRD, STEHT DA. Der Kern kennt bis auf weiteres nur
  // das Tragjoch; still weiterzurechnen waere die schlimmste Antwort.
  {
    const { hinweise } = await import(J('core.checks.js'));
    const mJ = modell({ ...standardwerte(), typ: 'J90', L: 15 },
      getProfil(T.getTragjoch('J90').og.profil),
      getProfil(T.getTragjoch('J90').ug.profil),
      getStahl('S235'), T.getTragjoch('J90'));
    const hJ = hinweise(mJ);
    /*
     * SEIT DEM 2. SEPTEMBER RECHNET DER EINZELMAST.
     *
     * Der Hinweis «gerechnet wird weiterhin das Tragjoch» gilt deshalb nur
     * noch dem TRAGAUSLEGER - er ist nach den Werkstattzeichnungen ein
     * gegliederter Stab aus zwei UPE, und der Vierendeel-Kern traegt dort
     * nicht unveraendert. Beim Einzelmast waere der Hinweis jetzt falsch.
     */
    const hE = hinweise({ ...mJ, tragwerksart: 'tragausleger' });
    wahr('Beim Joch kein solcher Hinweis',
         !hJ.some((t) => /gerechnet wird weiterhin/.test(t)));
    wahr('Beim Tragausleger steht er, und ganz oben',
         /gerechnet wird weiterhin/.test(hE[0] ?? ''));
    /*
     * UND DAS MODELL REICHT DIE ANGABEN WIRKLICH DURCH.
     *
     * Der erste Anlauf hatte den Hinweis gebaut und im Pruefstand gruen
     * dastehen - dort wurde `tragwerksart` von Hand ins Modell gesetzt. In
     * der Anwendung erschien er NIE: `modell()` zaehlt seine Felder einzeln
     * auf, und diese beiden fehlten. Ein Sicherungshinweis, der nicht
     * ausloest, ist schlimmer als keiner.
     */
    const mA = modell({ ...standardwerte(), typ: 'J90', L: 15,
                        tragwerksart: 'tragausleger',
                        weitere: [{ id: 'T2' }, { id: 'T3' }] },
      getProfil(T.getTragjoch('J90').og.profil),
      getProfil(T.getTragjoch('J90').ug.profil),
      getStahl('S235'), T.getTragjoch('J90'));
    wahr('Das Modell traegt die Tragwerksart', mA.tragwerksart === 'tragausleger');
    wahr('… und die Anzahl auf dem Blatt', mA.tragwerkeAufBlatt === 3);
    const hM = hinweise(mA);
    wahr('Beide Hinweise stehen dann in der Liste',
         hM.some((x) => /gerechnet wird weiterhin/.test(x))
         && hM.some((x) => /3 Tragwerke auf diesem Querprofil/.test(x)));
    wahr('Bei einem Tragwerk kein Anzahl-Hinweis',
         !hinweises1().some((x) => /Tragwerke auf diesem Querprofil/.test(x)));
    function hinweises1() {
      return hinweise(modell({ ...standardwerte(), typ: 'J90', L: 15 },
        getProfil(T.getTragjoch('J90').og.profil),
        getProfil(T.getTragjoch('J90').ug.profil),
        getStahl('S235'), T.getTragjoch('J90')));
    }
  }
}

// ===========================================================================
// PRUEFUNG 65: das Querprofil traegt mehrere Tragwerke. Weisung vom
// 2. September, auf Rueckfrage bestaetigt: Jochreihen haben gemeinsame
// Zwischenmasten.
{
  const C = await import(J('core.constants.js'));
  const UI = await import(J('ui.js'));

  const blatt = () => ({ typ: 'J90', L: 15, linie: '600', km: '016.661',
                         trasseRadius: 700, mastProfil: 'HEB 260' });

  // ALTE DATEIEN SIND EIN QUERPROFIL MIT EINEM TRAGWERK.
  wahr('Ohne Liste steht genau ein Tragwerk da', C.anzahlTragwerke({}) === 1);
  wahr('… und es ist ein Joch', C.tragwerksart(C.tragwerkSatz({})).key === 'joch');

  // DIE BLATTANGABEN GELTEN ALLEN. Ein Querprofil hat EINEN Radius.
  {
    const w = C.tragwerkHinzu(blatt(), 'einzelmast', { mastProfil: 'DP26' });
    const alle = C.tragwerkeVon(w);
    wahr('Zwei Tragwerke auf dem Blatt', alle.length === 2);
    wahr('Beide erben Linie und Kilometer',
         alle.every((t) => t.linie === '600' && t.km === '016.661'));
    wahr('… und den Radius', alle.every((t) => t.trasseRadius === 700));
    wahr('Die Blattangaben stehen nicht im Tragwerksteil',
         !('linie' in C.tragwerkTeil(w)) && !('trasseRadius' in C.tragwerkTeil(w)));
  }

  /*
   * ERSETZEN, NICHT UEBERLAGERN - der Fehler, der beim ersten Anlauf
   * durchging.
   *
   * `{ ...w, ...gewaehltes }` sieht richtig aus und ist es nicht: was im
   * gewaehlten Tragwerk FEHLT, bleibt vom bisherigen stehen. Das Joch trug
   * danach die Tragwerksart des Einzelmastes, weil der alte Satz das Feld
   * gar nicht kannte. Zwei Tragwerke vermischt, und dem Ergebnis sieht man
   * es nicht an.
   */
  {
    let w = C.tragwerkHinzu(blatt(), 'einzelmast', { mastProfil: 'DP26' });
    wahr('Das neue Tragwerk ist gleich das aktive',
         C.tragwerksart(w).key === 'einzelmast' && w.mastProfil === 'DP26');
    w = C.tauscheAktives(w, 'T1');
    wahr('Zurueck beim Joch: die Art stimmt', C.tragwerksart(w).key === 'joch');
    wahr('… und seine eigenen Werte auch',
         w.typ === 'J90' && w.L === 15 && w.mastProfil === 'HEB 260');
    w = C.tauscheAktives(w, 'T2');
    wahr('Und der Mast hat seine behalten',
         C.tragwerksart(w).key === 'einzelmast' && w.mastProfil === 'DP26');
    w = C.tauscheAktives(w, 'T1');
    wahr('Hin und her aendert nichts',
         C.tragwerksart(w).key === 'joch' && w.mastProfil === 'HEB 260');
  }

  // DIE REIHENFOLGE AUF DEM BLATT BLEIBT. Sonst spraenge das angeklickte
  // Tragwerk beim Anklicken an eine andere Stelle.
  {
    let w = C.tragwerkHinzu(blatt(), 'einzelmast');
    w = C.tragwerkHinzu(w, 'tragausleger');
    const vorher = C.tragwerkeSortiert(w).map((t) => t.id).join(',');
    w = C.tauscheAktives(w, 'T1');
    const nachher = C.tragwerkeSortiert(w).map((t) => t.id).join(',');
    wahr('Umschalten sortiert die Liste nicht um', vorher === nachher);
    wahr('Genau eines ist aktiv',
         C.tragwerkeSortiert(w).filter((t) => t.aktiv).length === 1);
  }

  // DAS LETZTE LAESST SICH NICHT ENTFERNEN: ein Querprofil ohne Tragwerk ist
  // kein Zustand, in den man geraten koennen soll.
  {
    let w = C.tragwerkHinzu(blatt(), 'einzelmast');
    w = C.tragwerkWeg(w, 'T1');
    wahr('Ein Tragwerk laesst sich wegnehmen', C.anzahlTragwerke(w) === 1);
    wahr('Das letzte nicht', C.anzahlTragwerke(C.tragwerkWeg(w, w.twId)) === 1);
  }

  // DER NAME KOMMT VON DEN BAUTEILEN, nicht von einer Nummer.
  wahr('Ein Joch heisst nach Typ und Laenge',
       C.tragwerkName({ typ: 'J90', L: 15 }) === 'J90 · 15.00 m');
  wahr('Ein Mast nach Profil und Laenge',
       C.tragwerkName({ tragwerksart: 'einzelmast', mastProfil: 'DP26',
                        mastLaenge: 12 }) === 'DP26 · 12.00 m');

  /*
   * DIE LISTE GEHOERT IN DIE MASKENSIGNATUR.
   *
   * Ohne sie blieb die Maske stehen: der Klick auf «+ Mast» setzte den Wert,
   * und die Liste zeigte weiter einen Eintrag. Derselbe Fehler wie beim
   * Standort der Anbauteile, zwei Wochen frueher - und beim Umschalten der
   * Tragwerksart, eine Stunde frueher.
   */
  {
    const w1 = blatt();
    const w2 = C.tragwerkHinzu(w1, 'einzelmast');
    wahr('Ein Tragwerk mehr aendert die Signatur',
         UI.maskenSignatur(w1, 'system') !== UI.maskenSignatur(w2, 'system'));
    const w3 = C.tauscheAktives(w2, 'T1');
    wahr('… und ein anderes aktives ebenso',
         UI.maskenSignatur(w2, 'system') !== UI.maskenSignatur(w3, 'system'));
  }
}

// ===========================================================================
// PRUEFUNG 66: der Einzelmast rechnet. Weisung vom 2. September: «Einzelmast
// zuerst, ganz fertig.»
{
  const { berechneEinzelmast, modellEinzelmast, berechne } =
    await import(J('core.vierendeel.js'));

  const basis = { ...standardwerte(), tragwerksart: 'einzelmast',
                  mastVorhanden: true, mastProfil: 'HEB 260',
                  mastH: 9, mastLaenge: 12, windKlasse: 'EK2', anbauteile: [] };
  const mitBw = (bw) => berechneEinzelmast({ ...basis, beiwerteFest: bw },
                                           getStahl('S235'));

  /*
   * DIE GLEICHLAST AM KRAGARM - die Kontrolle, die alles andere traegt.
   *
   * Wind ueber die Masthoehe ist eine Gleichlast; am eingespannten Fuss gilt
   * V = q·H und M = q·H²/2, also M = V·H/2. Stimmt dieses Verhaeltnis, sind
   * Lastansatz, Hebelarm und Integration zusammen richtig - und zwar ohne
   * dass eine Zahl von aussen dazukaeme.
   */
  {
    const e = mitBw({ G: 1, WindX: 1.5, WindY: 0, Schnee: 0 });
    const fuss = e.mast.A.stationen[0];
    wahr('Wind quer erzeugt Querkraft am Fuss', fuss.Fx > 0.1);
    pruef('M_q = V_q · H/2 am Kragarm', fuss.Myy, fuss.Fx * 12 / 2, 1e-9, 'kNm');
    wahr('… und in Gleisrichtung nichts', Math.abs(fuss.Fy) < 1e-9);
  }
  {
    const e = mitBw({ G: 1, WindX: 0, WindY: 1.5, Schnee: 0 });
    const fuss = e.mast.A.stationen[0];
    wahr('Wind laengs erzeugt Querkraft in Gleisrichtung', fuss.Fy > 0.1);
    /*
     * DAS MINUS GEHOERT ZUR GLOBALEN GROESSE: `M_xx` dreht um die Jochachse,
     * und eine Kraft in +y ueber die Hoehe erzeugt ein Moment um -x. Seit
     * der Umstellung (15. September) fuehrt der Nachweis die globale Groesse,
     * nicht mehr die Ebene.
     */
    pruef('… mit demselben Hebelarm', -fuss.Mxx, fuss.Fy * 12 / 2,
          1e-9, 'kNm');
  }
  /*
   * DIE SCHWACHE ACHSE IST DIE UNGUENSTIGERE. Steg quer zum Gleis heisst:
   * starke Achse quer, schwache in Gleisrichtung. Derselbe Wind muss dort
   * mehr ausmachen - sonst waeren die Achsen vertauscht, und das faellt
   * einem Ergebnis sonst nicht an.
   */
  {
    const quer = mitBw({ G: 1, WindX: 1.5, WindY: 0, Schnee: 0 });
    const laengs = mitBw({ G: 1, WindX: 0, WindY: 1.5, Schnee: 0 });
    wahr('Wind auf die schwache Achse ist unguenstiger',
         laengs.max.etaGesamt > quer.max.etaGesamt);
  }

  // NUR EIGENGEWICHT: eine Normalkraft, sonst nichts. HEB 260 mit 93 kg/m
  // ueber 12 m sind rund 11 kN.
  {
    const e = mitBw({ G: 1, WindX: 0, WindY: 0, Schnee: 0 });
    const fuss = e.mast.A.stationen[0];
    wahr('Eigengewicht steht als Normalkraft am Fuss',
         fuss.N > 9 && fuss.N < 13);
    wahr('… und erzeugt kein Moment',
         Math.abs(fuss.Myy) < 1e-9 && Math.abs(fuss.Mxx) < 1e-9);
  }

  /*
   * DAS ERGEBNIS HAT DIESELBE FORM WIE BEIM JOCH - mit leeren Stellen statt
   * fehlenden. Die Auswertung fragt nach `knoten`, `max` und `mast`; was es
   * nicht gibt, ist leer und nicht undefined, damit keine Anzeige auf halbem
   * Weg abbricht.
   */
  {
    const e = mitBw({ G: 1, WindX: 1.5, WindY: 0, Schnee: 0 });
    wahr('Keine Knoten, aber eine Liste', Array.isArray(e.knoten) && !e.knoten.length);
    wahr('Ein Gesamt-eta gibt es', Number.isFinite(e.max.etaGesamt));
    /*
     * SEIT DEM BIEGEKNICKNACHWEIS IST ES DER NACHWEIS, nicht der
     * Querschnitt. Am gemessenen Regelmasten ist das Knicken das groessere
     * von beiden - die Kopfzahl haette es sonst verschwiegen, waehrend
     * daneben «Tragsicherheit erfuellt» steht.
     */
    wahr('Es ist der Nachweis des Mastes, nicht nur sein Querschnitt',
         e.max.etaGesamt === e.mast.etaNachweis);
    wahr('… und damit das groessere von Querschnitt und Knicken',
         e.max.etaGesamt === Math.max(e.mast.eta, e.mast.etaStabil));
    wahr('Kein Auflagerblatt', e.auflager === null);
  }

  // KEIN JOCH IM MODELL: die Jochgroessen stehen auf NULL, nicht auf
  // undefined - `mastLasten` addiert sie, und undefined machte daraus NaN.
  {
    const m = modellEinzelmast(basis, getStahl('S235'));
    wahr('Die Jochreaktionen sind null',
         m.RA === 0 && m.MA === 0 && m.wd === 0);
    wahr('… und die Lastlisten leer',
         m.H.length === 0 && m.T.length === 0 && m.N.length === 0);
    wahr('Der Mast steht im Modell', Boolean(m.federn?.mastA ?? m.federn?.mast));
  }

  /*
   * BERECHNE() FINDET DEN WEG SELBST. Der Aufrufer uebergibt weiterhin
   * Profile und Tragjoch - sie werden beim Einzelmast nicht gebraucht, und
   * genau das darf nicht dazu fuehren, dass er etwas anderes rechnet.
   */
  {
    const j = T.getTragjoch('J90');
    const e = berechne({ ...basis, beiwerteFest: { G: 1, WindX: 1.5, WindY: 0, Schnee: 0 } },
      getProfil(j.og.profil), getProfil(j.ug.profil), getStahl('S235'), j);
    wahr('berechne() verzweigt auf den Einzelmast',
         e.knoten.length === 0 && Boolean(e.mast));
  }

  // OHNE MASTPROFIL GEHT ES NICHT - und das wird gesagt, nicht geraten.
  {
    let fehler = null;
    try {
      modellEinzelmast({ ...basis, mastVorhanden: false }, getStahl('S235'));
    } catch (e) { fehler = e.message; }
    wahr('Ein Einzelmast ohne Masten meldet sich',
         /Mastprofil/.test(fehler ?? ''));
  }
}

// ===========================================================================
// PRUEFUNG 67: die Lage auf dem Querprofil. Weisung vom 2. September: «man
// muesste also eine x-Koordinate eingeben koennen fuer die einzelnen Masten».
{
  const C = await import(J('core.constants.js'));
  const { bauformSkizze, BAUFORMEN_KEYS } = await import(J('doku.optionsskizzen.js'));

  // EIN JOCH HAT ZWEI MASTEN - bei x0 und x0 + jt.
  wahr('Das Joch stellt zwei Masten',
       C.mastLagen({ tragwerksart: 'joch', xLage: 4, L: 12 }).join(',') === '4,16');
  wahr('Der Einzelmast einen',
       C.mastLagen({ tragwerksart: 'einzelmast', xLage: 7 }).join(',') === '7');
  wahr('Der Tragausleger auch einen',
       C.mastLagen({ tragwerksart: 'tragausleger', xLage: 7, L: 9 }).join(',') === '7');
  wahr('Das Abfangjoch zwei',
       C.mastLagen({ tragwerksart: 'abfangjoch', xLage: 0, L: 15 }).join(',') === '0,15');

  /*
   * DIE LISTE FOLGT DER ANORDNUNG, nicht der Einfuegereihenfolge.
   *
   * Vorher zaehlte `pos` - eine Zahl, die nichts bedeutete. Wer drei
   * Tragwerke auf einem Blatt hat, sucht sie dort, wo sie stehen.
   */
  {
    let w = { typ: 'J90', L: 12, xLage: 20 };
    w = C.tragwerkHinzu(w, 'einzelmast', { xLage: 5 });
    w = C.tragwerkHinzu(w, 'einzelmast', { xLage: 40 });
    const x = C.tragwerkeSortiert(w).map((t) => C.lageVon(t));
    wahr('Nach der Lage geordnet', x.join(',') === '5,20,40');
  }
  /*
   * OHNE EINGETRAGENE LAGE BLEIBT DIE REIHENFOLGE STEHEN.
   *
   * Alle auf null heisst: `pos` entscheidet. Sonst spraenge die Liste bei
   * jedem neuen Tragwerk, und man klickte dem eigenen Zeiger hinterher.
   */
  {
    let w = { typ: 'J90', L: 12 };
    w = C.tragwerkHinzu(w, 'einzelmast');
    w = C.tragwerkHinzu(w, 'tragausleger');
    const ids = C.tragwerkeSortiert(w).map((t) => t.id).join(',');
    wahr('Ohne Lage bleibt die Einfuegereihenfolge', ids === 'T1,T2,T3');
  }

  /*
   * DER GETEILTE MAST - der eigentliche Grund fuer die Lage.
   *
   * Zwei Joche in einer Reihe teilen sich den Zwischenmasten. Er ist an
   * einer ZAHL erkennbar, nicht an einer Absichtserklaerung: gleiche Stelle
   * heisst naeher als zehn Zentimeter beieinander.
   */
  {
    let w = { typ: 'J90', L: 12, xLage: 0 };
    w = C.tragwerkHinzu(w, 'joch', { L: 10, xLage: 12 });
    const g = C.geteilteMasten(w);
    wahr('Die Jochreihe teilt einen Masten', g.length === 1);
    wahr('… und zwar bei x0 = 12', Math.abs(g[0].x - 12) < 1e-9);
    wahr('… zwischen beiden Jochen',
         g[0].ids.length === 2 && g[0].ids.includes('T1') && g[0].ids.includes('T2'));
  }
  {
    // Fuenf Zentimeter Versatz sind ein Eingabefehler, kein zweiter Mast.
    let w = { typ: 'J90', L: 12, xLage: 0 };
    w = C.tragwerkHinzu(w, 'joch', { L: 10, xLage: 12.05 });
    wahr('Fuenf Zentimeter gelten als dieselbe Stelle',
         C.geteilteMasten(w).length === 1);
    let w2 = { typ: 'J90', L: 12, xLage: 0 };
    w2 = C.tragwerkHinzu(w2, 'joch', { L: 10, xLage: 14 });
    wahr('Zwei Meter nicht', C.geteilteMasten(w2).length === 0);
  }
  // Zwei Einzelmasten weit auseinander teilen sich nichts.
  {
    let w = { tragwerksart: 'einzelmast', xLage: 0 };
    w = C.tragwerkHinzu(w, 'einzelmast', { xLage: 9 });
    wahr('Getrennte Masten teilen sich nichts', C.geteilteMasten(w).length === 0);
  }

  // DAS ABFANGJOCH IST GEZEICHNET - und flach, im Unterschied zum Tragjoch.
  wahr('Auch das Abfangjoch hat sein Bild',
       BAUFORMEN_KEYS.includes('abfangjoch')
       && bauformSkizze('abfangjoch').includes('<svg'));
  {
    // Zwei Gurte dicht beieinander statt zweier Ebenen mit Bauhoehe: die
    // beiden waagrechten Linien liegen naeher zusammen als beim Tragjoch.
    // NUR BAUTEILLINIEN (class="b"). Die Terrainlinie laeuft ueber die ganze
    // Breite und zaehlte beim ersten Anlauf als dritter Gurt mit.
    const hoehen = (key) => [...bauformSkizze(key).matchAll(
      /<line class="b"[^>]*x1="(\d+)"[^>]*y1="(\d+)"[^>]*x2="(\d+)"[^>]*y2="(\d+)"/g)]
      .map((t) => ({ x1: +t[1], y1: +t[2], x2: +t[3], y2: +t[4] }))
      .filter((l) => l.y1 === l.y2 && Math.abs(l.x1 - l.x2) > 80)
      .map((l) => l.y1).sort((a, b) => a - b);
    const abf = hoehen('abfangjoch'), joch = hoehen('joch');
    wahr('Beide zeigen zwei Gurte', abf.length === 2 && joch.length === 2);
    wahr('Das Abfangjoch ist flacher als das Tragjoch',
         (abf[1] - abf[0]) < (joch[1] - joch[0]));
  }

  /*
   * DER HINWEIS NENNT DIE STELLE, nicht die Moeglichkeit.
   *
   * «Ein Mast, den sich zwei Tragwerke teilen, wird noch nicht gekoppelt»
   * war wahr und nutzlos. Wer die Lagen eingetragen hat, bekommt die Zahl.
   */
  {
    const { hinweise } = await import(J('core.checks.js'));
    const h = hinweise({ tragwerkeAufBlatt: 2,
                         geteilteMasten: [{ x: 12, ids: ['T1', 'T2'] }],
                         tragwerksart: 'einzelmast' });
    wahr('Der geteilte Mast steht mit seiner Lage da',
         h.some((t) => /x₀ = 12\.00 m/.test(t)));
    wahr('… und die fehlende Rahmenwirkung dazu',
         h.some((t) => /Rahmenwirkung/.test(t)));
  }
}

// ===========================================================================
// PRUEFUNG 68: der Mast ist das Grundelement. Weisung vom 2. September: «Ein
// Mast kann zum Beispiel ein Joch und einen Tragausleger stuetzen.»
{
  const C = await import(J('core.constants.js'));
  const reihe = () => {
    let w = { typ: 'J90', L: 12, xLage: 0, mastProfil: 'HEB 260',
              mastH: 8, mastLaenge: 12, mastSteg: 'quer' };
    return C.tragwerkHinzu(w, 'joch', { L: 10, xLage: 12, mastProfil: 'HEB 240' });
  };

  /*
   * DIE MIGRATION VERSCHMILZT DEN ZWISCHENMASTEN.
   *
   * Alte Dateien tragen die Mastangaben flach je Tragwerk; ein Mast, an dem
   * zwei Joche haengen, stand darin zweimal. Beim Einlesen wird daraus
   * einer - und was vorher bei jedem Aufruf neu vermutet wurde, steht
   * seither als Verweis da.
   */
  {
    const w = reihe();
    const m = C.mastenVon(w);
    wahr('Aus zwei Jochen werden drei Masten', m.length === 3);
    const mitte = m.find((x) => Math.abs(x.x - 12) < 1e-9);
    wahr('Der mittlere traegt beide',
         mitte?.traegt.length === 2 && mitte.traegt.includes('T1')
         && mitte.traegt.includes('T2'));
    wahr('Und die aeusseren je eines',
         m.filter((x) => x.traegt.length === 1).length === 2);
  }

  /*
   * >>> «STEHT OHNE MASTEN» VERSCHIEBT DIE NAMEN NICHT. <<<
   *
   * Weisung vom 9. September: «ich versteh die logik nicht beim ein
   * ausblenden der masten, in der 3d abbildung werden gewisse
   * nachgeschoben.»
   *
   * Das mastlose Tragwerk zaehlt jetzt MIT: es legt seine Lagen an, traegt
   * `ohneMast` und faellt erst am Ende weg - nachdem die Nummern vergeben
   * sind. Dieselbe Regel wie beim Ausblenden (Weisung, 3. September:
   * «namen ueber ausblenden hinweg stabil halten»).
   */
  {
    const drei = () => {
      let w = { typ: 'J90', L: 20, xLage: 0, mastProfil: 'HEB 240', mastH: 7 };
      w = C.tragwerkHinzu(w, 'joch', { L: 20, xLage: 20, mastProfil: 'HEB 260' });
      return C.tragwerkHinzu(w, 'joch', { L: 15, xLage: 40,
                                          mastProfil: 'HEM 240' });
    };
    const namen = (w) => C.mastenVon(w).map((m) => `${m.id}@${m.x}`).join(' ');
    const voll = drei();
    wahr('Eine Reihe von drei Jochen hat vier Masten',
         C.mastenVon(voll).length === 4);
    wahr('… M1 bis M4 an 0, 20, 40, 55',
         namen(voll) === 'M1@0 M2@20 M3@40 M4@55');
    /*
     * ACHTUNG BEI DER ID: `tragwerkHinzu` macht das NEUE Tragwerk zum
     * aktiven - nach zweimal Hinzufuegen liegt T1 in `weitere`, und genau
     * das soll `tragwerkAendern` koennen.
     */
    const ohne1 = C.tragwerkAendern(voll, 'T1', () => ({ mastVorhanden: false }));
    wahr('Ohne Masten am ersten Joch faellt nur der aeussere weg',
         namen(ohne1) === 'M2@20 M3@40 M4@55');
    const ohne2 = C.tragwerkAendern(voll, 'T2', () => ({ mastVorhanden: false }));
    wahr('… und am mittleren bleiben alle vier stehen',
         namen(ohne2) === 'M1@0 M2@20 M3@40 M4@55');
    /*
     * DIE ANGABEN GEHOEREN DEM, DER DEN MASTEN WIRKLICH TRAEGT. Der Mast
     * bei 40 wurde von T2 angelegt (HEB 260); steht T2 ohne Masten, gilt
     * das Profil von T3.
     */
    const bei = (w, x) => C.mastenVon(w).find((m) => Math.abs(m.x - x) < 1e-9);
    wahr('Der geteilte Mast traegt sonst das Profil seines Anlegers',
         bei(voll, 40)?.profil === 'HEB 260');
    wahr('… und ohne dessen Masten das des anderen Traegers',
         bei(ohne2, 40)?.profil === 'HEM 240');
    wahr('Ein Mast, den nur ein mastloses Tragwerk traegt, ist weg',
         bei(ohne1, 0) === undefined);
    wahr('Der geteilte bleibt, weil der Nachbar ihn traegt',
         bei(ohne1, 20)?.traegt.includes('T2') === true);
  }

  /*
   * >>> UND DER SCHALTER WECHSELT DAS GERECHNETE TRAGWERK NICHT. <<<
   *
   * `tragwerkAendern` greift das Feld an, wo immer es liegt - flach im
   * Blatt beim aktiven, in `weitere` bei den uebrigen.
   */
  {
    let w = { twId: 'T1', typ: 'J90', L: 12, xLage: 0, mastProfil: 'HEB 260' };
    w = C.tragwerkHinzu(w, 'joch', { L: 10, xLage: 12 });   // T2 wird aktiv
    const aktiv = w.twId;
    const n = C.tragwerkAendern(w, 'T1', () => ({ mastVorhanden: false }));
    wahr('Das gerechnete Tragwerk bleibt, wo es war', n.twId === aktiv);
    wahr('… und das andere hat den Schalter',
         C.tragwerkeVon(n).find((t) => t.id === 'T1').mastVorhanden === false);
    const m = C.tragwerkAendern(n, aktiv, () => ({ mastVorhanden: false }));
    wahr('Auch das aktive laesst sich so schalten',
         m.mastVorhanden === false && m.twId === aktiv);
    wahr('Eine unbekannte Id laesst das Blatt stehen',
         C.tragwerkAendern(w, 'T9', () => ({ mastVorhanden: false })) === w);
  }

  /*
   * >>> GEKOPPELT WIRD NUR, WER EINE LAGE TRAEGT. <<<
   *
   * Der Standardwert von x0 ist null. Ohne diese Regel stehen ALLE
   * Tragwerke, an denen niemand die Lage eingetragen hat, bei null - und
   * ihre Masten verschmelzen zu einem einzigen. Genau das ist beim ersten
   * Lauf passiert: drei unabhaengige Tragwerke teilten sich einen Masten,
   * das Profil sprang beim Aendern auf einen fremden Wert, und der Kern
   * bekam ein leeres Profil. Eine FEHLENDE Angabe darf nichts koppeln.
   */
  {
    let w = { typ: 'J90', L: 12, mastProfil: 'HEB 260', mastH: 8 };
    w = C.tragwerkHinzu(w, 'einzelmast');
    w = C.tragwerkHinzu(w, 'einzelmast');
    wahr('Ohne Lage teilt sich niemand einen Masten',
         C.geteilteMasten(w).length === 0);
    wahr('… und jeder hat seinen eigenen',
         C.mastenVon(w).every((m) => m.traegt.length === 1));
  }

  /*
   * >>> DIE ANSCHLUSSHOEHE GEHOERT NICHT DEM MASTEN. <<<
   *
   * Weisung vom 2. September auf Nachfrage: zwei Joche koennen am selben
   * Masten VERSCHIEDEN HOCH anschliessen. H beschreibt dann die VERBINDUNG
   * Tragwerk-Mast; am Masten abgelegt gewaenne eines der beiden Joche, und
   * das andere rechnete still mit einer fremden Hoehe. Die Drehfeder haengt
   * daran - es waere ein Fehler, den man dem Ergebnis nicht ansieht.
   */
  {
    let w = { typ: 'J90', L: 12, xLage: 0, mastProfil: 'HEB 260',
              mastH: 8, mastLaenge: 12, mastSteg: 'quer' };
    w = C.tragwerkHinzu(w, 'joch', { L: 10, xLage: 12, mastH: 8.5 });
    w = { ...w, masten: C.mastenVon(w) };
    wahr('Der Mast traegt keine Anschlusshoehe',
         C.mastenVon(w).every((m) => m.H === undefined));
    const t1 = C.tragwerkeVon(w).find((t) => t.id === 'T1');
    const t2 = C.tragwerkeVon(w).find((t) => t.id === 'T2');
    wahr('Jedes Tragwerk behaelt seine eigene',
         C.mastenProjizieren({ ...t1 }, w, t1).mastH === 8
         && C.mastenProjizieren({ ...t2 }, w, t2).mastH === 8.5);
    /*
     * WAS DEM MASTEN GEHOERT, BLEIBT GETEILT - und `mastZwei` bedeutet
     * «Ende B WEICHT AB», nicht «es gibt zwei». Sind beide Masten gleich,
     * wird das Feld nicht gesetzt und `mastProfilB` bleibt weg; sonst wuerde
     * der Standardwert von `mastHB` ploetzlich wirksam.
     */
    wahr('Bei gleichen Masten kein mastZwei',
         C.mastenProjizieren({ ...t1 }, w, t1).mastZwei !== true);
    wahr('… und das Profil kommt vom Masten',
         C.mastenProjizieren({ ...t1 }, w, t1).mastProfil === 'HEB 260');
  }
  {
    // Unterscheiden sie sich, wird es gesetzt - und beide Profile stehen da.
    let v = { typ: 'J90', L: 12, xLage: 0, mastProfil: 'HEB 260', mastH: 8 };
    v = C.tragwerkHinzu(v, 'joch', { L: 10, xLage: 12 });
    v = { ...v, masten: C.mastenVon(v) };
    v = C.setzeMastAngabe(v, 'B', 'mastProfilB', 'HEM 240');
    const t = C.tragwerkeVon(v)[0];
    const satz = C.mastenProjizieren({ ...t }, v, t);
    wahr('Bei verschiedenen Masten schon',
         satz.mastZwei === true && satz.mastProfilB === 'HEM 240');
  }

  // DER KERN SIEHT DIE ANGABEN FLACH - so wie immer.
  {
    const w = reihe();
    const t2 = C.tragwerkeVon(w).find((t) => t.id === 'T2');
    const satz = C.mastenProjizieren({}, w, t2);
    wahr('Mast A projiziert', satz.mastProfil === 'HEB 260');
    wahr('Mast B projiziert', satz.mastProfilB === 'HEB 240');
    wahr('… und mastZwei ist gesetzt', satz.mastZwei === true);
  }

  /*
   * DER GEWINN: EINE AENDERUNG WIRKT AUF BEIDE.
   *
   * Wer das Profil des Zwischenmastes aendert, aendert es fuer BEIDE
   * Tragwerke, die daran haengen. Genau so soll es sein - es ist ein Mast.
   */
  {
    let w = reihe();
    w = { ...w, masten: C.mastenVon(w) };
    w = C.setzeMastAngabe(w, 'A', 'mastProfil', 'HEM 240');
    const mitte = C.mastenVon(w).find((m) => Math.abs(m.x - 12) < 1e-9);
    wahr('Der Zwischenmast hat das neue Profil', mitte.profil === 'HEM 240');
    const t1 = C.tragwerkeVon(w).find((t) => t.id === 'T1');
    const s1 = C.mastenProjizieren({}, w, t1);
    wahr('Das Nachbartragwerk sieht es an seinem Ende B',
         s1.mastProfilB === 'HEM 240');
    wahr('… und sein eigenes Ende A bleibt', s1.mastProfil === 'HEB 260');
  }

  /*
   * EIN LEERES PROFIL IST KEINE ANGABE - und eine Liste ohne Profile keine
   * Liste. Ein Auswahlfeld, dessen Wert nicht in der Liste steht, meldet
   * einen leeren String; blind uebernommen brach der Kern mit «Unbekanntes
   * Mastprofil: » ab, ohne zu sagen, woher der leere Wert kam.
   */
  {
    let w = reihe();
    w = { ...w, masten: C.mastenVon(w) };
    const vorher = C.mastenVon(w)[0].profil;
    const nachher = C.mastenVon(C.setzeMastAngabe(w, 'A', 'mastProfil', ''))[0].profil;
    wahr('Ein leeres Profil wird abgewiesen', nachher === vorher);
  }
  {
    // Selbstheilung: die Liste ist eine ABLEITUNG, kein Original.
    const w = { ...reihe(), masten: [{ id: 'M1', x: 0, profil: '', traegt: ['T1'] }] };
    const m = C.mastenVon(w);
    wahr('Eine profillose Liste wird verworfen und neu gebaut',
         m.length === 3 && m.every((x) => x.profil));
  }

  /*
   * DIE LISTE WIRD NACHGEFUEHRT, NICHT FESTGESCHRIEBEN.
   *
   * Sie ist eine ABLEITUNG: wer ein Tragwerk verschiebt oder ein Joch
   * verlaengert, verschiebt seine Masten mit. Eine einmal gespeicherte Liste
   * veraltet dabei still - beim ersten Anlauf fehlte nach dem Verschieben
   * eines Jochs sein zweiter Mast, und die Kachel zeigte die alte Lage.
   */
  {
    let w = { typ: 'J90', L: 20, xLage: 0, mastProfil: 'HEB 240', mastH: 8 };
    w = { ...w, masten: C.mastenVon(w) };
    wahr('Ein Joch stellt zwei Masten', C.mastenVon(w).length === 2);
    // Jetzt verschieben - die Lagen muessen mitgehen.
    const v = { ...w, xLage: 20 };
    const lagen = C.mastenVon(v).map((m) => m.x).join(',');
    wahr('Verschieben fuehrt die Lagen nach', lagen === '20,40');
    // Und verlaengern.
    const l = { ...w, L: 25 };
    wahr('Verlaengern ebenso',
         C.mastenVon(l).map((m) => m.x).join(',') === '0,25');
  }
  {
    // WAS EINGESTELLT WURDE, BLEIBT. Nachgefuehrt werden Lage und
    // Zugehoerigkeit; Profil und Hoehe gehoeren dem Masten.
    let w = { typ: 'J90', L: 20, xLage: 0, mastProfil: 'HEB 240', mastH: 8 };
    w = { ...w, masten: C.mastenVon(w) };
    w = C.setzeMastAngabe(w, 'B', 'mastProfilB', 'HEM 240');
    const v = { ...w, xLage: 7 };
    const mB = C.mastenVon(v)[1];
    wahr('Das eingestellte Profil ueberlebt das Verschieben',
         mB.profil === 'HEM 240' && Math.abs(mB.x - 27) < 1e-9);
  }

  // RECHENSATZ: was der Kern bekommt. Ohne Liste aendert sich nichts -
  // alte Dateien laufen unveraendert.
  {
    const ohne = { typ: 'J90', L: 12, mastProfil: 'HEB 220', mastH: 8 };
    wahr('Ohne Mastenliste bleibt der Satz, wie er ist',
         C.rechensatz(ohne).mastProfil === 'HEB 220');
  }
}

// ===========================================================================
// PRUEFUNG 69: das ganze Querprofil in einem Bild. Weisung vom 2. September:
// «man laesst die Tragwerke im 3d angezeigt passiv und man kann dann
// draufdruecken um auf diese aktiv umzuschalten».
{
  const R = await import(J('render.3d.js'));

  const szene = () => ({
    flaechen: [{ punkte: [[0, 0, 0], [4, 0, 0], [4, 1, 0]], xMitte: 2,
                 gruppe: 'profil' }],
    linien: [{ punkte: [[0, 0, 0], [4, 0, 0]] }],
    marken: [{ p: [2, 0, 1], text: 'M' }],
    masse: [{ p0: [0, 0, 0], p1: [4, 0, 0], text: '4 m' }],
    bauteiltitel: [{ p: [2, 0, 2], text: 'J90' }],
    vektoren: [{ p: [2, 0, 1], v: [0, 0, -1], text: 'F' }],
    lastflaechen: [{ punkte: [[0, 0, 1], [4, 0, 1]] }],
    schnitt: { x: 2, poly: [[2, 0, 0], [2, 1, 0]] },
    stationen: [0, 2, 4], xNachweis: 2, schnittAktiv: true,
    /*
     * DER BEREICH, DEN DER ZOOM ANFAEHRT. Er traegt x UND z - siehe die
     * Kontrollen weiter unten; er wurde beim Verschieben vergessen.
     */
    anbauteile: [{ index: 0, name: 'A1', teil: 'AT0', x: 2, r: 0.2,
                   xMin: 1.8, xMax: 2.2, zMin: -1, zMax: 0.5 }],
    legende: [{ key: 'gurt', label: 'Gurt' }],
    bereiche: { eta: 0.5 },
    grenzen: { xMin: 0, xMax: 4, yMin: 0, yMax: 1, zMin: -1, zMax: 2 },
  });

  /*
   * VERSCHOBEN WIRD GENAU EINE ACHSE.
   *
   * Alles, was eine x-Koordinate traegt, bekommt dx dazu. `v` ist eine
   * RICHTUNG, kein Ort - ein verschobener Kraftpfeil zeigte sonst woandershin.
   */
  {
    const v = R.szeneVerschieben(szene(), 10, { twId: 'T2', passiv: true });
    pruef('Die Flaeche wandert', v.flaechen[0].punkte[0][0], 10, 1e-12, 'm');
    pruef('… und ihre Mitte mit', v.flaechen[0].xMitte, 12, 1e-12, 'm');
    pruef('Die Linie wandert', v.linien[0].punkte[1][0], 14, 1e-12, 'm');
    pruef('Die Marke wandert', v.marken[0].p[0], 12, 1e-12, 'm');
    pruef('Die Masslinie wandert', v.masse[0].p1[0], 14, 1e-12, 'm');
    pruef('Der Bauteiltitel wandert', v.bauteiltitel[0].p[0], 12, 1e-12, 'm');
    pruef('Der Vektor wandert an seinem Ort', v.vektoren[0].p[0], 12, 1e-12, 'm');
    wahr('… aber seine RICHTUNG bleibt',
         v.vektoren[0].v.join(',') === '0,0,-1');
    pruef('Die Station wandert', v.stationen[2], 14, 1e-12, 'm');
    /*
     * DER NACHWEISSCHNITT IST EINE x-KOORDINATE - und wurde beim ersten
     * Anlauf vergessen. Der Knopf «auf den Nachweisschnitt» fuhr dann auf
     * x = 0.38, waehrend das Tragwerk bei 20 bis 40 stand. Kein Fehler,
     * keine Meldung - die Kamera fuhr nur an eine Stelle, an der nichts ist.
     */
    pruef('Und der Nachweisschnitt auch', v.xNachweis, 12, 1e-12, 'm');
    /* =====================================================================
     * >>> UND DER BEREICH DES ANBAUTEILS. <<<
     * =====================================================================
     *
     * Gemeldet am 12. September: «zoom auf bauteil funktioniert nicht, der
     * bildausschnitt ist nicht im bild wenn man es anklickt.»
     *
     * `anbauteile` traegt je Teil den Bereich, den `zeigeAnbauteil` anfaehrt.
     * Er stand in den Koordinaten des EINZELNEN Tragwerks, waehrend alles
     * andere verschoben wurde - dieselbe Falle wie beim Nachweisschnitt eine
     * Zeile darueber, und aus demselben Grund uebersehen: es ist keine
     * Zeichnung, sondern eine Koordinate.
     *
     * >>> DIESER TEIL WANDERT AUCH IN z. <<<
     *
     * `blattSzene` hebt jede Szene um die Anschlusshoehe an, damit die
     * Mastfuesse auf einer Hoehe liegen. Am gemessenen Fall: Szene von
     * -1.05 bis 9.80, das Teil aber bei -2.92 bis 0.22 - siebeneinhalb Meter
     * zu tief, und die Kamera fuhr unter das Modell.
     */
    const vz = R.szeneVerschieben(szene(), 10, { twId: 'T2' }, 7.5);
    pruef('Der Bereich des Anbauteils wandert in x', vz.anbauteile[0].x,
          12, 1e-12, 'm');
    pruef('… mit seinen beiden Raendern', vz.anbauteile[0].xMax, 12.2, 1e-12, 'm');
    pruef('… und er wandert in z mit', vz.anbauteile[0].zMin, 6.5, 1e-12, 'm');
    pruef('… beide Raender', vz.anbauteile[0].zMax, 8.0, 1e-12, 'm');
    wahr('… die Nummer bleibt, sonst faende ihn niemand',
         vz.anbauteile[0].index === 0 && vz.anbauteile[0].teil === 'AT0');
    /*
     * DER BEREICH MUSS IN DER SZENE LIEGEN. Das ist die Probe, die den
     * Befund gefunden haette: was der Zoom anfaehrt, hat innerhalb der
     * Grenzen zu liegen, in denen das Modell steht.
     */
    wahr('Der angefahrene Bereich liegt in den Grenzen der Szene',
         vz.anbauteile.every((b) => b.zMin >= vz.grenzen.zMin - 1e-9
                                 && b.zMax <= vz.grenzen.zMax + 1e-9
                                 && b.x >= vz.grenzen.xMin - 1e-9
                                 && b.x <= vz.grenzen.xMax + 1e-9),
         `Teil z ${vz.anbauteile[0].zMin}…${vz.anbauteile[0].zMax}, `
         + `Szene z ${vz.grenzen.zMin}…${vz.grenzen.zMax}`);
    pruef('Die Grenzen wandern', v.grenzen.xMin, 10, 1e-12, 'm');
    pruef('… beide', v.grenzen.xMax, 14, 1e-12, 'm');
    wahr('Quer und hoch bleibt alles stehen',
         v.grenzen.yMax === 1 && v.grenzen.zMax === 2
         && v.flaechen[0].punkte[2][1] === 1);
    // DIE KENNZEICHNUNG WANDERT IN JEDEN TEIL - daran haengt Farbe und Klick.
    wahr('Jeder Teil weiss, zu wem er gehoert',
         v.flaechen[0].twId === 'T2' && v.flaechen[0].passiv === true
         && v.marken[0].twId === 'T2' && v.vektoren[0].passiv === true);
  }

  /*
   * VEREINEN: die Grenzen umschliessen alles, die Legende steht einmal da.
   *
   * DER SCHNITT GEHOERT DEM AKTIVEN. Zwei Nachweisschnitte in einem Bild
   * waeren zwei Antworten auf eine Frage.
   */
  {
    const a = { ...R.szeneVerschieben(szene(), 0, { twId: 'T1', passiv: true }) };
    const b = { ...R.szeneVerschieben(szene(), 10, { twId: 'T2' }), aktiv: true };
    b.schnitt = { x: 12, poly: [] };
    const g = R.szenenVereinen([a, b]);
    pruef('Die Grenzen umschliessen beide', g.grenzen.xMin, 0, 1e-12, 'm');
    pruef('… bis zum Ende', g.grenzen.xMax, 14, 1e-12, 'm');
    wahr('Die Flaechen sind zusammengelegt', g.flaechen.length === 2);
    wahr('Die Legende steht einmal da', g.legende.length === 1);
    wahr('Der Schnitt ist der des aktiven', g.schnitt.x === 12);
    wahr('… und seine Stelle ebenso', g.xNachweis === 12);
    wahr('Und die Stationen sind alle da', g.stationen.length === 6);
    /*
     * >>> DIE BEREICHE GEHOEREN DEM AKTIVEN TRAGWERK. <<<
     *
     * Sie standen in der vereinten Szene gar nicht - `zeigeAnbauteil` fand
     * nichts und tat nichts: in einer Jochreihe war der Zoom auf ein Bauteil
     * wirkungslos, ohne jede Meldung.
     *
     * Alle zu sammeln waere falsch: `index` zaehlt je Tragwerk von vorn, und
     * ein Klick auf A1 fuehre zum A1 des Nachbarn. Die Schublade zeigt die
     * Teile des aktiven Tragwerks, also gehoeren seine Bereiche hierher -
     * wie der Schnitt und seine Stelle.
     */
    wahr('Die Bereiche der Anbauteile stehen in der vereinten Szene',
         (g.anbauteile ?? []).length === 1);
    pruef('… und es sind die des AKTIVEN', g.anbauteile[0].x, 12, 1e-12, 'm');
  }
  {
    // Ein einzelnes Tragwerk bleibt, wie es ist - kein Umweg ohne Not.
    const eine = szene();
    wahr('Eine Szene bleibt sie selbst', R.szenenVereinen([eine]) === eine);
    wahr('Nichts ergibt nichts', R.szenenVereinen([null, null]) === null);
  }

  /*
   * DER EINZELMAST WIRD VOM SELBEN CODE GEZEICHNET.
   *
   * Er hatte lange gar kein Bild: `erzeugeSzene` beginnt mit dem Querschnitt
   * des Jochs, und ohne vier Winkel brach der Aufbau ab. Ihn ein zweites Mal
   * zu zeichnen waere die schlechtere Antwort gewesen - zwei
   * Mastzeichnungen laufen auseinander, und dann zeigt das Bild etwas
   * anderes als der Nachweis. Er bekommt jetzt einen ERSATZQUERSCHNITT ohne
   * Ausdehnung; die Schleifen ueber Gurte und Bleche laufen leer, der Mast
   * entsteht wie immer.
   */
  {
    const { berechneEinzelmast } = await import(J('core.vierendeel.js'));
    const w = { ...standardwerte(), tragwerksart: 'einzelmast',
                mastVorhanden: true, mastProfil: 'HEB 260',
                mastH: 8, mastLaenge: 12, anbauteile: [] };
    const e = berechneEinzelmast(w, getStahl('S235'));
    const sz = R.erzeugeSzene(e.modell, e);
    wahr('Der Einzelmast hat Koerper', sz.flaechen.length > 100);
    wahr('… und zwar Mastkoerper',
         sz.flaechen.every((f) => f.gruppe === 'mast'));
    wahr('Keine Gurte, keine Bleche',
         !sz.flaechen.some((f) => f.gruppe === 'profil' || f.gruppe === 'blech'));
    /*
     * DIE GRENZEN KOMMEN AUS DEN GEZEICHNETEN KOERPERN.
     *
     * Beim Joch spannen sie sich zwischen den Gurtenden auf - x von 0 bis L.
     * Ein Einzelmast hat weder L noch Huelle; beides ist null, und die
     * Grenzen hatten damit keine Ausdehnung. Die Einpassung fand nichts,
     * worauf sie haette zoomen koennen, und das Bild blieb leer, obwohl
     * hunderte Mastflaechen darin standen.
     */
    const g = sz.grenzen;
    wahr('Die Grenzen haben Ausdehnung in x', g.xMax > g.xMin);
    wahr('… und in y', g.yMax > g.yMin);
    wahr('… und umfassen den Masten', g.zMax - g.zMin > 8);
    const xs = sz.flaechen.flatMap((f) => f.punkte.map((p) => p[0]));
    wahr('Kein Koerper steht ausserhalb',
         Math.min(...xs) >= g.xMin - 1e-9 && Math.max(...xs) <= g.xMax + 1e-9);
  }
}

// ===========================================================================
// PRUEFUNG 70: eine Handlung, die nicht geht, sagt es.
{
  const aq70 = APP_QUELLE();

  /*
   * DAS SCHWEIGEN IST SCHLIMMER ALS DER FEHLER.
   *
   * Gemessen am 2. September: der Excel-Knopf am Einzelmasten brach mit
   * «Cannot read properties of undefined (reading herkunft)» ab - und zwar
   * lautlos. Keine Datei, keine Meldung, keine rote Zeile. Der Fehler landete
   * in window.onerror und starb dort. Wer auf «Ausleiten» drueckt und nichts
   * bekommt, sucht die Datei im Download-Ordner, im Papierkorb, in den
   * Einstellungen - und rechnet zuletzt damit, dass das Programm es gar nicht
   * versucht hat.
   */
  wahr('Es gibt eine Klammer fuer Handlungen',
       aq70.includes('function handlung(was, fn)'));
  {
    const ab = aq70.indexOf('function handlung(was, fn)');
    const koerper = aq70.slice(ab, aq70.indexOf('\n}', ab));
    wahr('Sie faengt den Bruch', koerper.includes('catch'));
    wahr('… meldet ihn im Handlungsbalken', koerper.includes('meldeImBalken'));
    wahr('… und schreibt ihn ganz in die Konsole',
         koerper.includes('console.error'));
  }

  // JEDER AUSLEITWEG LAEUFT DURCH SIE. Einer, der es nicht taete, waere
  // genau der, der wieder schweigt.
  wahr('Die Excel-Ausleitung ist umklammert',
       /handlung\('Excel-Ausleitung'/.test(aq70));
  wahr('Die AxisVM-Wege sind es auch',
       /return (app\.)?handlung\(name, \(\) => \{/.test(aq70));
  wahr('… und zwar alle vier',
       /json: 'COM-Ausleitung'/.test(aq70) && /dxf: 'DXF-Ausleitung'/.test(aq70)
       && /pynite: 'PyNite-Ausleitung'/.test(aq70) && /'SAF-Ausleitung'/.test(aq70));
  wahr('Auch das Drucken', /handlung\('Drucken'/.test(aq70));

  /*
   * UND EIN DURCHGANG, DER DAS MELDET.
   *
   * Der Pruefstand prueft Bausteine; er kennt keinen Durchgang durch alle
   * Wege. Waehrend hier 2290 Kontrollen gruen standen, tat der Excel-Knopf
   * am Einzelmasten nichts. `durchlauf.mjs` geht die Wege ab und schreibt
   * auf, was bricht.
   */
  {
    const d = readFileSync(new URL('./durchlauf.mjs', import.meta.url), 'utf8');
    wahr('Der Durchlauf kennt alle drei Faelle',
         /\['Joch', joch\]/.test(d) && /\['Einzelmast', einzelmast\]/.test(d)
         && /\['Jochreihe', reihe\]/.test(d));
    wahr('… und prueft die Ausleitung auf das ganze Blatt',
         d.includes('Deckt die Ausleitung das ganze Blatt ab'));
    wahr('… und repariert nichts', d.includes('repariert nichts')
         || d.includes('REPARIERT NICHTS'));
  }
}

// ===========================================================================
// PRUEFUNG 71: der Einzelmast geht durch ALLE Wege. Die sechs Befunde des
// Durchlaufs vom 2. September, einzeln festgehalten.
{
  const { berechneEinzelmast, konstruktionsChecks: kcAlt } =
    await import(J('core.vierendeel.js'));
  const CK = await import(J('core.checks.js'));
  const AX = await import(J('export.axisvm.js'));
  const PY = await import(J('export.pynite.js'));
  const V71 = await import(J('core.vierendeel.js'));

  const w71 = { ...standardwerte(), tragwerksart: 'einzelmast',
                mastVorhanden: true, mastProfil: 'HEB 260',
                mastH: 8, mastLaenge: 12, anbauteile: [] };
  const e71 = berechneEinzelmast(w71, getStahl('S235'));

  /*
   * OHNE JOCH KEINE JOCHPRUEFUNGEN - eine LEERE Liste, keine Ausnahme.
   *
   * Es sind keine Pruefungen verletzt, es gibt keine. Die erste Zeile brach
   * mit «Cannot read properties of undefined (reading aH)» ab, weil sie das
   * Winkelprofil des Obergurts suchte.
   */
  {
    const ck = CK.konstruktionsChecks(e71.modell);
    wahr('Der Einzelmast hat keine Konstruktionspruefungen',
         Array.isArray(ck) && ck.length === 0);
  }

  // MASSVARIANTEN SIND JOCHMASSE - beim Einzelmasten gibt es nichts zu
  // vergleichen, und `null` sagt genau das.
  wahr('Kein Massvariantenvergleich',
       V71.vergleichMassvarianten(w71, null, null, getStahl('S235'), null) === null);

  /*
   * DAS STABMODELL: EIN STAB UND EIN FUNDAMENT.
   *
   * Kein Ersatzprofil - ein GURT_OG in der AxisVM-Datei waere ein Bauteil,
   * das es nicht gibt, in einem Modell, das jemand rechnet. Was gezeichnet
   * wird, darf naeherungsweise sein; was ausgeleitet wird, nicht.
   */
  {
    const bau = AX.stabmodell(e71.modell, { knotenmodell: 'anschnitt' });
    wahr('Der Einzelmast leitet sich aus', bau.staebe.length > 0);
    wahr('… und zwar nur als Mast',
         bau.staebe.every((st) => /^MAST_A_/.test(st.name)));
    wahr('Keine Gurtquerschnitte in der Datei',
         ![...bau.querschnitte.keys()].some((k) => /^GURT_/.test(k)));
    wahr('Der Fuss ist eingespannt',
         bau.auflager.length === 1 && bau.auflager[0].art === 'eingespannt');
    /*
     * DIE HOEHENNULL IST DER ANSCHLUSS, nicht der Fuss - wie beim Joch.
     * Sonst staende ein Einzelmast neben einem Joch um H versetzt in der Luft.
     */
    const zs = [...bau.knoten.values()].map((k) => k.z);
    /*
     * SEIT DEM 18. SEPTEMBER hat der Einzelmast keine Anschlusshoehe mehr:
     * sie ist ausgeblendet, und der Mast ist frei vom Fuss bis zum Kopf. Die
     * Hoehennull liegt damit am Kopf, und die Laenge (12 m) reicht nach unten.
     * Ein H im Satz, das niemand mehr sieht, verschiebt nichts.
     */
    pruef('Der Fuss liegt eine Mastlaenge unter dem Kopf', Math.min(...zs), -12, 1e-9, 'm');
    pruef('… und der Kopf auf der Hoehennull', Math.max(...zs), 0, 1e-9, 'm');
  }

  // PYNITE: das Skript entsteht, auch ohne Feldmitten. Nur die
  // Gegenueberstellung am Ende bleibt leer - es gibt nichts zu vergleichen.
  {
    const py = PY.pyniteSkript(e71.modell, { knotenmodell: 'anschnitt' });
    wahr('Ein PyNite-Skript entsteht', py.text.includes('add_member'));
    wahr('… mit dem Masten darin', /MAST_A_S1/.test(py.text));
  }
}

// ===========================================================================
// PRUEFUNG 72: das ganze Querprofil in EIN Stabmodell. Weisung vom
// 2. September: «die jochreihe müsste zwingend zusammen modelliert werden
// -> Rahmenwirkung».
{
  const AX72 = await import(J('export.axisvm.js'));
  const V72 = await import(J('core.vierendeel.js'));
  const C72 = await import(J('core.constants.js'));

  const reihe = () => {
    let w = typUebernehmen({ ...standardwerte(), typ: 'J90', bearbeiten: false },
                           T.getTragjoch('J90'));
    w.L = 20; w.xLage = 0; w.mastVorhanden = true;
    return C72.tragwerkHinzu(w, 'joch', { L: 15, xLage: 20 });
  };
  const deps72 = { modellVon: (satz) => V72.modell(satz,
    getProfil(satz.profOG), getProfil(satz.profUG),
    getStahl(satz.stahl), T.getTragjoch(satz.typ)) };

  {
    const w = reihe();
    const bau = AX72.stabmodellBlatt(w, deps72, { knotenmodell: 'anschnitt' });
    const xs = [...bau.knoten.values()].map((k) => k.x);
    /*
     * DAS MODELL UMFASST DAS GANZE BLATT.
     *
     * Vorher reichte es von 0 bis 15 - das aktive Tragwerk allein, in seinen
     * OERTLICHEN Koordinaten, als staende es bei null. Das erste Joch fehlte
     * ganz, und man sah es der Datei nicht an.
     */
    pruef('Das Stabmodell beginnt beim ersten Masten', Math.min(...xs), 0, 1e-6, 'm');
    /*
     * 35.10, NICHT 35.00 - das Entflechten rueckt das zweite Joch um zehn
     * Zentimeter. Die Endbleche zweier Joche duerfen einander nicht
     * beruehren (Weisung), und die Jochlaenge steht fest; also wandert die
     * Lage. Genau das ist die gemeldete Modellunschaerfe.
     */
    pruef('… und endet beim letzten', Math.max(...xs), 35.1, 1e-6, 'm');

    /*
     * >>> DER GETEILTE MAST IST EINER. <<<
     *
     * Nicht durch Kopplung, sondern durch den NAMEN: heissen die Mastknoten
     * nach dem MASTEN (MAST_M2_F) statt nach dem Jochende (MAST_A_F), findet
     * das zweite Joch den Masten des ersten wieder. Ein Stab, zwei
     * Anschluesse, EIN Fundament.
     */
    const fuesse = [...bau.knoten.keys()].filter((n) => /^MAST_.*_F$/.test(n));
    wahr('Drei Masten fuer zwei Joche', fuesse.length === 3);
    wahr('… und ein Fundament je Mast', bau.auflager.length === 3);
    wahr('Keine widerspruechlichen Knoten',
         (bau.blatt?.widerspruch?.length ?? 0) === 0);

    // DIE TRAGWERKE BLEIBEN UNTERSCHEIDBAR: ein Praefix je Tragwerk, die
    // Masten davon ausgenommen - sie gehoeren dem Blatt.
    const namen = [...bau.knoten.keys()];
    wahr('Jedes Tragwerk traegt sein Praefix',
         namen.some((n) => n.startsWith('T1_')) && namen.some((n) => n.startsWith('T2_')));
    wahr('Die Masten tragen keines',
         namen.filter((n) => /^MAST_/.test(n)).length > 0);

    /*
     * DIE LASTEN WERDEN JE TRAGWERK GEHOLT UND VEREINT.
     *
     * `lasten(m, bau)` braucht beides - das Modell fuer die Groessen, das
     * Stabmodell fuer die Knotennamen. Ohne Anbauteil traegt ein Joch keine
     * Punktlasten (das Eigengewicht rechnet AxisVM aus den Staeben), also
     * wird hier eines gesetzt.
     */
    wahr('Die Lastlisten stehen bereit',
         bau.lasten && Array.isArray(bau.lasten.punkt)
         && Array.isArray(bau.lasten.strecke));
  }
  {
    const A72 = await import(J('data.anbauteile.js'));
    let w = reihe();
    w = { ...w, anbauteile: [{ ...A72.neuesAnbauteil('hs-fahrdraht', 8),
                               name: 'FL' }] };
    const bau = AX72.stabmodellBlatt(w, deps72, { knotenmodell: 'anschnitt' });
    wahr('Mit Anbauteil tragen beide Tragwerke Lasten bei',
         bau.lasten.punkt.length > 0);
    /*
     * JEDE LAST ZEIGT AUF EINEN KNOTEN IHRES TRAGWERKS.
     *
     * Das Anbauteil steht an EINEM Tragwerk - Lasten von beiden zu erwarten
     * waere falsch. Was zaehlt: der Knoten traegt das Praefix, unter dem er
     * auch im Modell steht. Ohne das zeigte die Last ins Leere, und AxisVM
     * bekaeme eine Kraft ohne Angriffspunkt.
     */
    const namen = new Set(bau.knoten.keys());
    wahr('Jede Last zeigt auf einen vorhandenen Knoten',
         bau.lasten.punkt.every((l) => namen.has(String(l.knoten ?? l.node))));
    wahr('… und der traegt ein Tragwerkspraefix',
         bau.lasten.punkt.every((l) => /^T\d+_/.test(String(l.knoten ?? l.node))));
  }

  /*
   * EIN EINZELNES TRAGWERK GEHT DEN ALTEN WEG.
   *
   * Kein Umweg ohne Not: die Namen bleiben, wie sie waren (MAST_A_*), und
   * eine Datei von gestern sieht aus wie eine von heute.
   */
  {
    let w = typUebernehmen({ ...standardwerte(), typ: 'J90', bearbeiten: false },
                           T.getTragjoch('J90'));
    w.L = 20; w.mastVorhanden = true;
    const bau = AX72.stabmodellBlatt(w, deps72, { knotenmodell: 'anschnitt' });
    const namen = [...bau.knoten.keys()];
    wahr('Ein Tragwerk: keine Praefixe', !namen.some((n) => /^T\d+_/.test(n)));
    wahr('… und die Masten heissen A und B',
         namen.some((n) => n === 'MAST_A_F') && namen.some((n) => n === 'MAST_B_F'));
  }

  /*
   * DER HOEHENVERSATZ GLEICHT VERSCHIEDENE ANSCHLUSSHOEHEN AUS.
   *
   * Schliesst das zweite Joch 50 cm hoeher an denselben Masten an, liegt
   * seine Achse 50 cm hoeher - und sein Mastfuss trotzdem auf derselben
   * Kote. Sonst stuende derselbe Mast zweimal da, gegeneinander versetzt.
   */
  {
    let w = typUebernehmen({ ...standardwerte(), typ: 'J90', bearbeiten: false },
                           T.getTragjoch('J90'));
    /*
     * VERSCHIEDENE ANSCHLUSSHOEHEN - und seit dem 5. September auch
     * verschiedene LAENGEN, weil sie daran haengen. Beide Tragwerke tragen
     * ihre eigene; das zweite bekommt sie ausdruecklich mit, sonst erbte es
     * die des ersten und der geteilte Mast staende zweimal verschieden da.
     */
    w.L = 20; w.xLage = 0; w.mastVorhanden = true; w.mastH = 8;
    w.mastLaenge = 8.5;
    w = C72.tragwerkHinzu(w, 'joch',
                          { L: 15, xLage: 20, mastH: 8.5, mastLaenge: 9.0 });
    const bau = AX72.stabmodellBlatt(w, deps72, { knotenmodell: 'anschnitt' });
    wahr('Auch bei verschiedenen Anschlusshoehen kein Widerspruch',
         (bau.blatt?.widerspruch?.length ?? 0) === 0);
    const fuesse = [...bau.knoten.keys()].filter((n) => /^MAST_.*_F$/.test(n));
    wahr('… und weiterhin drei Masten', fuesse.length === 3);
  }
}

// ===========================================================================
// PRUEFUNG 73: die Endbleche zweier Joche duerfen einander nicht beruehren.
// Weisung vom 2. September: min. 5 cm zur Mastachse, also 10 cm zwischen den
// beiden Blechachsen.
{
  const AX73 = await import(J('export.axisvm.js'));
  const C73 = await import(J('core.constants.js'));
  const V73 = await import(J('core.vierendeel.js'));

  /*
   * >>> WARUM DAS NICHT KOSMETIK IST. <<<
   *
   * Die Endbleche sitzen am Jochende - erste und letzte Station liegen bei
   * x = 0 und x = L. Treffen zwei Joche an einem Zwischenmasten zusammen,
   * fallen beide auf DENSELBEN Punkt: in AxisVM zwei Bleche im selben Ort,
   * mit Knoten, die aufeinanderliegen, ohne verbunden zu sein.
   */
  {
    let w = typUebernehmen({ ...standardwerte(), typ: 'J90', bearbeiten: false },
                           T.getTragjoch('J90'));
    w.L = 20; w.xLage = 0; w.mastVorhanden = true;
    w = C73.tragwerkHinzu(w, 'joch', { L: 15, xLage: 20 });
    const eng = C73.engeJochenden(w);
    wahr('Zwei Joche Stoss an Stoss werden erkannt', eng.length === 1);
    pruef('… und die Luecke ist null', eng[0].luecke, 0, 1e-9, 'm');

    const deps = { modellVon: (satz) => V73.modell(satz,
      getProfil(satz.profOG), getProfil(satz.profUG),
      getStahl(satz.stahl), T.getTragjoch(satz.typ)) };
    const bau = AX73.stabmodellBlatt(w, deps, { knotenmodell: 'anschnitt' });

    // DIE AUSLEITUNG RUECKT NACH - und sagt es.
    wahr('Die Ausleitung entflicht', bau.blatt.entflochten.length === 1);
    pruef('… um die fehlenden 10 cm', bau.blatt.entflochten[0].dx, 0.10, 1e-9, 'm');
    wahr('… und nennt den Grund', /Endbleche/.test(bau.blatt.entflochten[0].wegen));

    /*
     * DER GETEILTE MAST STEHT MITTIG. Fuenf Zentimeter von jedem Blech -
     * er kann nicht an beiden Enden zugleich sein.
     */
    const fuss = [...bau.knoten.entries()]
      .filter(([n]) => /^MAST_.*_F$/.test(n)).map(([, k]) => k.x).sort((a, b) => a - b);
    wahr('Drei Masten', fuss.length === 3);
    pruef('Der Zwischenmast steht mittig', fuss[1], 20.05, 1e-6, 'm');
    pruef('… fuenf Zentimeter vom linken Blech', fuss[1] - 20, 0.05, 1e-6, 'm');
    pruef('… und fuenf vom rechten', 20.10 - fuss[1], 0.05, 1e-6, 'm');
    wahr('Und kein Knoten steht doppelt',
         (bau.blatt.widerspruch?.length ?? 0) === 0);
  }

  // WER GENUG ABSTAND HAT, WIRD NICHT ANGEFASST.
  {
    let w = typUebernehmen({ ...standardwerte(), typ: 'J90', bearbeiten: false },
                           T.getTragjoch('J90'));
    w.L = 20; w.xLage = 0; w.mastVorhanden = true;
    w = C73.tragwerkHinzu(w, 'joch', { L: 15, xLage: 20.5 });
    wahr('Ein halber Meter Luft genuegt', C73.engeJochenden(w).length === 0);
  }

  // UND DIE AUSWERTUNG SAGT ES, nicht erst die Datei.
  {
    const { hinweise } = await import(J('core.checks.js'));
    const h = hinweise({ engeJochenden: [{ links: 'T1', rechts: 'T2', x: 20, luecke: 0 }],
                         tragwerksart: 'einzelmast' });
    wahr('Die Modellunschaerfe steht in den Hinweisen',
         h.some((t) => /Jochenden/.test(t) && /Modell weicht|weicht damit/.test(t)));
  }
}

// ===========================================================================
const CH9x = await import(J('core.checks.js'));
// PRUEFUNG 74: Biegeknicken des Mastes, EN 1993-1-1, 6.3. Weisung vom
// 2. September: «nimm noch die stabilitätsnachweis mit ein in die app».
{
  const M74 = await import(J('core.mast.js'));
  const V74 = await import(J('core.vierendeel.js'));
  const MP = await import(J('data.masten.js'));

  const mast = (o = {}) => {
    const w = { ...standardwerte(), tragwerksart: 'einzelmast',
                mastVorhanden: true, mastProfil: 'HEB 260',
                mastH: 9, mastLaenge: 12, anbauteile: [],
                beiwerteFest: { G: 1, WindX: 1.5, WindY: 0, Schnee: 0 }, ...o };
    const e = V74.berechneEinzelmast(w, getStahl('S235'));
    return { e, s: M74.mastSchnitt(e.modell, 'A'), m: e.modell };
  };
  /*
   * DIE ANSCHLUSSREGEL (13. September) gilt fuer Joch und Tragausleger. Der
   * Einzelmast hat seit dem 18. September keine Anschlusshoehe mehr und
   * rechnet jede Masse auf ihrer eigenen Hoehe (Entscheid auf Nachfrage).
   * Geprueft wird die Regel deshalb am selben Masten, mit Anschluss auf 9 m.
   */
  const mitAnschluss = (o = {}) => {
    const r = mast(o);
    return { ...r, s: { ...r.s, H: 9 }, m: { ...r.m, tragwerksart: 'tragausleger' } };
  };

  /*
   * DIE EULERLAST GEGEN DIE HANDRECHNUNG.
   *
   * N_cr = pi^2 EI / L_cr^2. Beim HEB 260 (I_z = 5135 cm^4) mit L_cr = 24 m
   * sind das rund 185 kN - eine Zahl, die sich in einer Minute nachrechnen
   * laesst, und genau darum steht sie hier.
   */
  {
    const { s, m } = mast();
    const k = M74.mastStabilitaet(s, m, { beta: 2.0 });
    const p = MP.mastprofile().find((x) => x.name === 'HEB 260');
    /*
     * L_cr = beta * z_eq, und z_eq ist die Ersatzhoehe nach Rayleigh. Der
     * Einzelmast der Probe traegt nur sein Eigengewicht, und das ist
     * VERTEILT: sein Anteil im Rayleigh-Quotienten ist das Integral
     * L^2 (1/4 - 1/pi^2), und die Hoehe, auf der eine Punktmasse dasselbe
     * taete, liegt bei 0.6001 L - nicht beim Schwerpunkt 0.5 L.
     */
    pruef('Die Ersatzhoehe des verteilten Eigengewichts', k.zN / k.L,
          0.60007, 1e-4, '– (von L)');
    pruef('L_cr = beta · Ersatzhoehe', k.Lcr, 2 * 0.60007 * 12, 1e-4, 'm');
    const NcrSoll = (Math.PI ** 2 * 210000 * (p.Iz * 1e4))
                  / ((k.Lcr * 1000) ** 2) / 1000;
    pruef('N_cr um die schwache Achse', k.NcrZ, NcrSoll, 1e-6, 'kN');
    pruef('N_Rk = A · f_y', k.NRk, (p.A * 100 * 235) / 1000, 1e-9, 'kN');
    pruef('lambda_quer = sqrt(N_Rk / N_cr)', k.lamZ,
          Math.sqrt(k.NRk / k.NcrZ), 1e-12, '–');
  }

  /*
   * DIE KNICKLINIE FOLGT DER GEOMETRIE, nicht einer Annahme.
   *
   * EN 1993-1-1, Tabelle 6.2: gewalzte I-Profile mit h/b <= 1.2 bekommen
   * y-y die Linie b und z-z die Linie c. Die Mastprofile des Sortiments
   * liegen zwischen 1.00 und 1.09 - also durchweg b/c.
   */
  {
    const { s, m } = mast();
    const k = M74.mastStabilitaet(s, m, {});
    wahr('HEB 260: Linie b um y, c um z',
         k.knicklinie.y === 'b' && k.knicklinie.z === 'c');
    pruef('… mit alpha 0.34 und 0.49', k.alphaY, 0.34, 1e-12, '–');
    pruef('…', k.alphaZ, 0.49, 1e-12, '–');
    // chi nach 6.3.1.2, gegen die geschlossene Formel.
    const phi = 0.5 * (1 + k.alphaZ * (k.lamZ - 0.2) + k.lamZ ** 2);
    pruef('chi_z nach 6.3.1.2', k.chiZ,
          1 / (phi + Math.sqrt(phi ** 2 - k.lamZ ** 2)), 1e-12, '–');
    wahr('chi liegt zwischen 0 und 1', k.chiZ > 0 && k.chiZ <= 1);
    wahr('Die schwache Achse knickt eher', k.chiZ < k.chiY);
  }

  /* =========================================================================
   * >>> DIE GANZE GLEICHUNG, VON HAND NACHGERECHNET. <<<
   * =========================================================================
   *
   * Nachgefragt am 12. September: «kannst du das knicken auch beim masten
   * selbst pruefen?» Die Bausteine standen hier schon - Euler, N_Rk, lambda,
   * die Knicklinie, chi. Die INTERAKTION nicht, und sie ist es, die am Ende
   * die Ausnutzung liefert.
   *
   * Druck und zweiachsige Biegung nach SIA 263, Ziffer 5.1.10.1,
   * Gleichung (50). Der Wortlaut liegt seit dem 13. September vor; bis dahin
   * stand hier EN 1993-1-1, 6.61/6.62 mit den Beiwerten aus Anhang B.
   *
   * >>> DIE NORMEN UNTERSCHEIDEN SICH IM ANSATZ, NICHT NUR IN ZAHLEN. <<<
   *
   * EN arbeitet mit Interaktionsbeiwerten k_ij, SIA mit dem
   * VERGROESSERUNGSFAKTOR 1/(1 - N_Ed/N_cr) - dem Momentenzuwachs zweiter
   * Ordnung, unmittelbar hingeschrieben. Die Knickkurve davor ist in beiden
   * dieselbe; das ist an der Tafel geprueft (siehe die Kontrollen beim
   * Anker).
   *
   * DER FALL: HEB 260, 12.0 m, Kragarm (beta = 2), Wind quer, S235,
   * gamma_M = 1.05. Die Ersatzhoehe des verteilten Eigengewichts liegt bei
   * 0.6001 * 12.00 = 7.201 m, also L_cr = 14.402 m.
   *
   *   N_Ky,Rd = 0.39636 * 2782.40 / 1.05      = 1050.3  kN
   *   N_Kz,Rd = 0.15038 * 2782.40 / 1.05      =  398.5  kN
   *   N_K,Rd  = Minimum                        =  398.5  kN
   *   N_Ed/N_K,Rd                              =    0.02747
   *   1/(1 - 10.948/1490.9)                    =    1.00739
   *   M_D,Rd  = 269.78 / 1.05                  =  256.93 kNm
   *   eta     = 0.02747 + 1.00739 * 35.64/256.93 = 0.16722
   */
  {
    const { s, m } = mast();
    const k = M74.mastStabilitaet(s, m, {});
    const g = k.gammaM1;
    pruef('Der Widerstandsbeiwert ist der der SIA', g, 1.05, 1e-12, '–');
    /*
     * DIE WIDERSTAENDE, Ziffer 4.5.1.3 und 5.1.3.
     */
    pruef('N_Ky,Rd = chi_y N_Rk / gamma_M', k.NKyRd,
          (k.chiY * k.NRk) / g, 1e-12, 'kN');
    pruef('N_Kz,Rd ebenso', k.NKzRd, (k.chiZ * k.NRk) / g, 1e-12, 'kN');
    pruef('N_K,Rd ist das Minimum der beiden (5.1.10.1)', k.NKRd,
          Math.min(k.NKyRd, k.NKzRd), 1e-12, 'kN');
    wahr('… und das ist hier die schwache Achse', k.NKRd === k.NKzRd);
    /*
     * OMEGA = 1.0 nach Ziffer 5.1.10.3: «Bei querbelasteten Staeben und
     * verschieblichen Rahmen duerfen die Gleichungen (50) und (51)
     * naeherungsweise auch verwendet werden, wobei omega = 1,0 einzusetzen
     * ist.» Der Mast traegt Wind ueber die ganze Hoehe.
     */
    pruef('omega = 1.0 (5.1.10.3, querbelasteter Stab)', k.omega, 1.0, 1e-12, '–');
    /*
     * DER VERGROESSERUNGSFAKTOR - hier steckt das Moment zweiter Ordnung.
     * Die Norm verlangt N_Ed und M_Ed «nach Theorie 1. Ordnung (ohne
     * Ersatzimperfektionen)»; der Zuwachs kommt aus diesem Faktor.
     */
    pruef('Vergroesserungsfaktor um y', k.vy,
          1 / (1 - k.NEd / k.NcrY), 1e-12, '–');
    pruef('… und um z', k.vz, 1 / (1 - k.NEd / k.NcrZ), 1e-12, '–');
    wahr('Er ist groesser als eins', k.vy > 1 && k.vz > 1);
    /*
     * >>> GLEICHUNG (50), VON HAND. <<<
     */
    pruef('Gleichung (50), von Hand', k.eta50,
          k.NEd / k.NKRd
          + (k.omega * k.vy) * (k.MyEd / k.MDRd)
          + (k.omega * k.vz) * (k.MzEd / k.MzRd), 1e-12, '–');
    pruef('Die Ausnutzung des Beispiels', k.eta, 0.16722, 1e-4, '–');
    wahr('Der Nachweis IST Gleichung (50)', k.eta === k.eta50);
    /*
     * DER KIPPWIDERSTAND IST DER BIEGEWIDERSTAND - Weisung vom
     * 13. September: «das kippen nicht einbauen.»
     */
    wahr('M_D,Rd ist M_y,Rd - Kippen wird nicht gefuehrt',
         Math.abs(k.MDRd - k.MyRd) < 1e-12);
    /*
     * >>> GLEICHUNG (51), Ziffer 5.1.10.2 - die zulaessige Alternative. <<<
     *
     * beta = 0.4 + N_Ed/N_Rd + b/(h - t_f), jedoch beta >= 1. Beim HEB 260
     * ist b/(h - t_f) = 260/242.5 = 1.0722, also beta rund 1.48.
     */
    const pM = MP.mastprofile().find((x) => x.name === 'HEB 260');
    pruef('beta nach 5.1.10.2', k.beta51,
          Math.max(1, 0.4 + k.NEd / k.NRd + pM.b / (pM.h - pM.tf)), 1e-12, '–');
    wahr('… und es ist mindestens eins', k.beta51 >= 1);
    pruef('M_y,red,Rd nach 5.1.10.2', k.MyredRd,
          Math.min(k.MDRd * (1 - k.NEd / k.NKRd) * (1 - k.NEd / k.NcrY),
                   k.omega * k.MDRd), 1e-12, 'kNm');
    pruef('M_z,red,Rd ebenso', k.MzredRd,
          k.MzRd * (1 - k.NEd / k.NKRd) * (1 - k.NEd / k.NcrZ), 1e-12, 'kNm');
    pruef('Gleichung (51), von Hand', k.eta51,
          (k.omega * k.MyEd / k.MyredRd) ** k.beta51
          + (k.omega * k.MzEd / k.MzredRd) ** k.beta51, 1e-12, '–');
    /*
     * GEFUEHRT WIRD (50). «darf» in 5.1.10.2 heisst: die Norm laesst die
     * Wahl; (50) gilt ohne Bedingung. (51) steht daneben, damit sichtbar
     * ist, was die Alternative ergaebe.
     */
    wahr('Gefuehrt wird (50), nicht (51)', k.eta !== k.eta51);
    /*
     * DIE MOMENTE STEHEN IN DEN PROFILACHSEN, nicht in den Bauachsen. Bei
     * Steg quer zum Gleis nimmt die starke Achse das Quermoment; das ist die
     * Identitaet, und genau deshalb faellt ein Vertauschen hier nicht auf -
     * es faellt beim GEDREHTEN Steg auf, und dort steht die Kontrolle.
     */
    wahr('Bei Steg quer zum Gleis nimmt die starke Achse das Quermoment',
         s.stegrichtung?.achse === 'y' && Math.abs(k.MyEd - k.MqEd) < 1e-12);
    const gedreht = mast({ mastSteg: 'quer' });
    const kg = M74.mastStabilitaet(gedreht.s, gedreht.m, {});
    wahr('… und bei gedrehtem Steg die schwache',
         Math.abs(kg.MzEd - kg.MqEd) < 1e-12
         && Math.abs(kg.MyEd - kg.MlEd) < 1e-12);
    /*
     * DASSELBE MOMENT UM DIE SCHWACHE ACHSE MUSS MEHR AUSNUTZEN. Eine Probe
     * ohne Zahl aus dem Buch: W_z ist beim HEB 260 knapp ein Drittel von
     * W_y, und chi_z ist kleiner als chi_y.
     */
    wahr('Der gedrehte Steg nutzt staerker aus', kg.eta > k.eta,
         `${kg.eta.toFixed(3)} gegen ${k.eta.toFixed(3)}`);
    /*
     * UND DIE SCHRANKE: ohne Normalkraft und ohne Moment ist die Gleichung
     * null, mit wachsendem Moment waechst sie monoton. Eine Probe, die
     * keine Zahl aus dem Buch braucht.
     */
    wahr('Ohne Momente bleibt nur der Druckanteil',
         Math.abs((k.NEd / k.NKRd) - (k.eta50 - k.vy * k.MyEd / k.MDRd
                                      - k.vz * k.MzEd / k.MzRd)) < 1e-12);
  }

  /* =========================================================================
   * >>> DIE MASSENPUNKTE UND IHRE HOEHE. <<<
   * =========================================================================
   *
   * Weisung vom 12. September: «zu beachten sind auch die massenpunkte und
   * deren hoehe bezogen auf den eingespannten stab (mast)».
   *
   * Der Mast ist ein eingespannter Kragarm. Eine Druckkraft in der Hoehe a
   * knickt ihn mit N_cr = pi^2 EI / (2a)^2 - je hoeher sie sitzt, desto
   * kleiner die Knicklast. Sitzen mehrere Kraefte auf verschiedenen Hoehen,
   * ist die sichere Idealisierung, sie ALLE auf die oberste zu legen: nach
   * oben verschoben wirkt jede Masse unguenstiger.
   *
   * Genau das rechnet der Kern: `z_N` ist die oberste Krafteinleitung, und
   * `N_Ed` ist der FUSSWERT, also die Summe. Die Paarung ist damit die
   * konservative - und sie ist es, die hier geprueft wird.
   *
   * >>> DER EINTRITT, NICHT DER ANGRIFFSPUNKT. <<<
   *
   * Eine Haengestuetze traegt ihren Fahrdraht anderthalb Meter unter ihrer
   * Befestigung. In den MASTEN kommt die Kraft an der Befestigung, und bis
   * dorthin drueckt sie. Mit dem Angriffspunkt gerechnet fiele die
   * Knicklaenge zu kurz aus - die unsichere Seite.
   */
  {
    /*
     * POSITIVES F_z DRUECKT. Beim ersten Anlauf standen hier negative
     * Werte - dann ziehen die Lasten nach oben, die Normalkraft NIMMT zum
     * Fuss hin ab, und N_Ed fiel auf 7.79 kN statt auf 26.9. Die Rechnung
     * war richtig, die Probe falsch herum; das Vorzeichen steht deshalb
     * jetzt hier.
     */
    const traverse = (id, h, Fz) => ({
      id, name: `Traverse ${id}`, ort: 'mastA', hMast: h, aktiv: true,
      raster: 0, module: [{ z: 0 }],
      lasten: [{ einwirkung: 'G', z: 0, Fz }],
    });
    const mitPunkten = mitAnschluss({ anbauteile: [
      traverse('oben', 11.0, 3), traverse('mitte', 7.0, 8),
      traverse('unten', 3.0, 5)] });
    const kp = M74.mastStabilitaet(mitPunkten.s, mitPunkten.m, {});
    const lot = (mitPunkten.s.lasten ?? [])
      .filter((l) => Math.abs(l.Fz ?? 0) > 1e-9);
    wahr('Jeder Massenpunkt steht mit seiner Hoehe da', lot.length >= 3,
         lot.map((l) => `${l.name} @ ${l.zAnschluss ?? l.z}`).join(', '));
    /*
     * SEIT DEM 13. SEPTEMBER NICHT MEHR DIE OBERSTE, sondern die
     * ANSCHLUSSHOEHE - alle drei Traversen rechnen auf 9.00 m mit, das
     * Eigengewicht auf 6.00 m, und dazwischen liegt die Ersatzhoehe.
     */
    /*
     * ALLE DREI STEHEN UNTER DEM ANSCHLUSS (11, 7 und 3 m gegen 9 m? nein:
     * die oberste steht auf 11 und bleibt dort). Geprueft wird deshalb die
     * Aufteilung: was unter dem Anschluss sitzt, wird zusammengefasst; was
     * darueber steht, bleibt einzeln.
     */
    /*
     * SEIT DEM 18. SEPTEMBER jede auf ihrer eigenen Hoehe, auch unter dem
     * Anschluss: «falls es auf höhe joch ist, anpassen entsprechend
     * einzelmast logik». Nichts wird mehr auf 9 m hochgesetzt.
     */
    const traversenZ = (h, P) => kp.massen.some((x) => Math.abs(x.z - h) < 1e-9
      && Math.abs(x.P - P) < 1e-9 && x.herkunft === 'eigene Befestigungshöhe');
    wahr('Jede Traverse rechnet auf ihrer eigenen Hoehe, auch unter dem Anschluss',
         traversenZ(7, 8) && traversenZ(3, 5)
         && !kp.massen.some((x) => x.herkunft === 'Anschlusshöhe'),
         kp.massen.map((x) => `${x.name} ${x.P} kN @ ${x.z} m`).join(', '));
    wahr('… und die oberste Traverse bleibt auf 11 m',
         kp.massen.some((x) => Math.abs(x.z - 11) < 1e-9
                            && Math.abs(x.P - 3.0) < 1e-9));
    wahr('Die Ersatzhoehe liegt zwischen Eigengewicht und Anschluss',
         kp.zN > 7.0 && kp.zN < 10.0, `${kp.zN.toFixed(3)} m`);
    /*
     * DIE SUMME STEHT DER OBERSTEN HOEHE GEGENUEBER. Waere N_Ed nur die
     * oberste Einzelkraft, fiele der Nachweis zu guenstig aus.
     */
    const summe = lot.reduce((a, l) => a + Math.abs(l.Fz), 0);
    wahr('N_Ed ist der Fusswert - Summe plus Eigengewicht des Masten',
         kp.NEd > summe * 1.05,
         `N_Ed ${kp.NEd.toFixed(2)} gegen Summe ${summe.toFixed(2)} kN`);
    /*
     * UND DIE HOEHE WIRKT: derselbe Satz Lasten, nur tiefer angesetzt, gibt
     * eine kuerzere Knicklaenge und ein groesseres chi. Das ist die Probe
     * auf die Richtung - ohne Zahl aus dem Buch.
     */
    const tiefer = mitAnschluss({ anbauteile: [
      traverse('oben', 6.0, 3), traverse('mitte', 5.0, 8),
      traverse('unten', 3.0, 5)] });
    const kt = M74.mastStabilitaet(tiefer.s, tiefer.m, {});
    /*
     * Die eigenen Hoehen der Teile aendern daran NICHTS mehr - sie werden
     * ja alle auf den Anschluss gesetzt. Geprueft wird deshalb, dass es
     * wirklich so ist.
     */
    /*
     * TIEFER ANGESETZTE MASSEN KNICKEN WENIGER - jetzt wieder, denn was
     * ueber dem Anschluss sass, bleibt dort. Im tieferen Satz steht nichts
     * mehr oben, also faellt die Ersatzhoehe.
     */
    wahr('Tiefer angesetzte Massen geben eine kleinere Ersatzhoehe',
         kt.zN < kp.zN,
         `${kt.zN.toFixed(4)} gegen ${kp.zN.toFixed(4)} m`);
    /*
     * DER EINTRITT ZAEHLT. Eine Last, die 1.50 m unter ihrer Befestigung
     * angreift, darf die Knicklaenge nicht verkuerzen.
     */
    const haenge = {
      id: 'hs', name: 'Haengestuetze', ort: 'mastA', hMast: 9.0, aktiv: true,
      raster: 0, module: [{ z: -1.5 }],
      lasten: [{ einwirkung: 'G', z: -1.5, Fz: 6 }],
    };
    const kh = M74.mastStabilitaet(mast({ anbauteile: [haenge] }).s,
                                   mast({ anbauteile: [haenge] }).m, {});
    /*
     * Der Eintritt zaehlt weiter - aber nur noch dafuer, OB das Teil ueber
     * dem Anschluss sitzt. Seine Masse rechnet auf der Anschlusshoehe mit.
     */
    wahr('Die Masse rechnet auf der Anschlusshoehe mit',
         Math.abs(kh.massen[0].z - 9.0) < 1e-9);
  }

  // EIN LAENGERER MAST KNICKT FRUEHER - die Richtung muss stimmen.
  {
    const kurz = M74.mastStabilitaet(mast({ mastLaenge: 8 }).s,
                                     mast({ mastLaenge: 8 }).m, {});
    const lang = M74.mastStabilitaet(mast({ mastLaenge: 16 }).s,
                                     mast({ mastLaenge: 16 }).m, {});
    wahr('Der laengere Mast hat das kleinere chi', lang.chiZ < kurz.chiZ);
    wahr('… und die groessere Schlankheit', lang.lamZ > kurz.lamZ);
  }
  // UND EIN GROESSERER BEIWERT WIRKT WIE EIN LAENGERER MAST.
  {
    const { s, m } = mast();
    const a = M74.mastStabilitaet(s, m, { beta: 1.0 });
    const b = M74.mastStabilitaet(s, m, { beta: 2.0 });
    pruef('Doppelter Beiwert, doppelte Knicklaenge', b.Lcr, 2 * a.Lcr, 1e-9, 'm');
    wahr('… und kleineres chi', b.chiZ < a.chiZ);
  }

  /*
   * >>> UND ER IST NICHT NEBENSAECHLICH. <<<
   *
   * Am 31. August hiess es, das Knicken sei «nie massgebend auf grund der
   * verhältnissmässig kleinen lasten». Gemessen am HEB 260 ueber 12 m mit
   * beta = 2.0 liegt es bei 0.1465 gegen 0.1360 aus dem Querschnitt - also
   * KNAPP DARUEBER. Die Normalkraft ist zwar klein (11 kN Eigengewicht),
   * aber chi_z faellt bei einer Schlankheit von 3.88 auf 0.059, und der
   * Momentenanteil wird mit k_yy = 0.93 hochgesetzt.
   *
   * Die Vermutung war also gut begruendet und trotzdem knapp daneben -
   * genau dafuer rechnet man es aus.
   */
  {
    const { e } = mast();
    wahr('Der Nachweis wird gefuehrt', Number.isFinite(e.mast.etaStabil));
    wahr('\u2026 und liegt in derselben Groessenordnung',
         e.mast.etaStabil > e.mast.eta * 0.5
         && e.mast.etaStabil < e.mast.eta * 2);
    // Das URTEIL zaehlt beides, die Farbskala nur den Querschnitt.
    wahr('etaNachweis ist das groessere der beiden',
         e.mast.etaNachweis === Math.max(e.mast.eta, e.mast.etaStabil));
  }

  /* =======================================================================
   * >>> UND ER LAESST SICH ABSCHALTEN. <<<
   * =======================================================================
   *
   * Weisung vom 15. September: "das knicken des masten deaktivierbar machen.
   * der nachweis ist zu konservativ, da die Leiter (Rueckleiter an Mast und
   * die Kettenwerke am Joch) den Masten stabilisieren und somit sich ein
   * andere Lk und Moment einstellt."
   *
   * NICHT GEFUEHRT HEISST NICHT GERECHNET. Eine Zahl, die dastuende und
   * nicht zaehlte, wuerde gelesen - deshalb steht `stabil` dann auf null
   * und nicht auf einem Wert, den man uebersehen muss.
   *
   * GEMESSEN am J90 / 20.00 m mit HEB 260 und H = 8.00 m:
   *
   *   gefuehrt      eta 0.7793 Querschnitt, 0.8344 Knicken -> 0.8344
   *   abgeschaltet  eta 0.7793 Querschnitt,   -   Knicken -> 0.7793
   *
   * Also 6.6 % - und genau darum geht die Weisung: der freistehende Kragarm
   * beschreibt einen Masten, den die Leiter in Wirklichkeit halten.
   */
  {
    const jochMast = (nachweise) => {
      const w = { ...basis(), endbedingung: 'mast', mastVorhanden: true,
                  mastProfil: 'HEB 260', mastH: 8.0, L: 20, nachweise };
      return rechne(w);
    };
    const an = jochMast({ knickenMast: true });
    const aus = jochMast({ knickenMast: false });
    const vor = jochMast(undefined);

    wahr('Abgeschaltet wird die Stabilitaet gar nicht erst gerechnet',
         aus.mast.A.stabil === null && aus.mast.B.stabil === null);
    wahr('\u2026 und das Merkmal sagt es',
         aus.mast.knickenGefuehrt === false && an.mast.knickenGefuehrt === true);
    pruef('Der Querschnitt bleibt unberuehrt', aus.mast.eta, an.mast.eta,
          1e-12, '-');
    pruef('Der Nachweis faellt auf ihn zurueck', aus.mast.etaNachweis,
          aus.mast.eta, 1e-12, '-');
    wahr('\u2026 und das ist weniger als mit Knicken',
         aus.mast.etaNachweis < an.mast.etaNachweis,
         `${aus.mast.etaNachweis.toFixed(4)} gegen ${an.mast.etaNachweis.toFixed(4)}`);
    /*
     * OHNE ANGABE GILT DIE VORGABE, und die ist AN. Wer nichts einstellt,
     * bekommt den strengeren Fall - eine alte Datei ohne das Feld ebenso.
     */
    pruef('Ohne Angabe wird gefuehrt', vor.mast.etaNachweis,
          an.mast.etaNachweis, 1e-12, '-');
    /*
     * UND ES STEHT IM URTEIL. Ein abgeschalteter Nachweis, den niemand
     * sieht, waere die gefaehrlichste Zeile dieser Anwendung.
     */
    const ch = CH9x.konstruktionsChecks(aus.modell);
    const uAus = CH9x.urteilKonstruktion(ch, { knickenMast: false }, 'joch');
    const uAn = CH9x.urteilKonstruktion(ch, { knickenMast: true }, 'joch');
    wahr('Abgeschaltet steht er unter den nicht gefuehrten',
         uAus.nichtGefuehrt.some((g) => g.key === 'knickenMast'
                                     && g.grund === 'ausgeschaltet'),
         uAus.nichtGefuehrt.map((g) => g.key).join(' '));
    wahr('\u2026 und eingeschaltet nicht',
         !uAn.nichtGefuehrt.some((g) => g.key === 'knickenMast'));
  }

  /*
   * >>> DER GEDREHTE STEG. Ein Befund vom 2. September, unsichere Seite. <<<
   *
   * Gerechnet wurde in BAUACHSEN - «quer» und «laengs» - und 6.61/6.62 der
   * Reihe nach daraufgelegt. Steht der Steg quer zum Gleis, ist das
   * dasselbe: die starke Achse nimmt das Quermoment. Beim GEDREHTEN Steg
   * nimmt es die schwache - der Widerstand W wurde getauscht, chi und k
   * nicht. 6.61 stand mit chi_y (0.166) neben einem Moment um die schwache
   * Achse und kam auf eta 0.443 statt 0.532: 20 % zu klein.
   *
   * EN 1993-1-1, 6.3.3 kennt nur Profilachsen. Also erst drehen, dann
   * einsetzen - und die Kontrolle haelt fest, dass der gedrehte Steg NICHT
   * guenstiger dasteht als der ungedrehte.
   */
  {
    const gerade = mast({ mastSteg: 'jochachse' });
    const gedreht = mast({ mastSteg: 'quer' });
    const kG = M74.mastStabilitaet(gerade.s, gerade.m, { beta: 2.0 });
    const kD = M74.mastStabilitaet(gedreht.s, gedreht.m, { beta: 2.0 });
    wahr('Der gedrehte Steg wird nicht guenstiger', kD.eta >= kG.eta - 1e-9);
    // Und die Momente stehen in den Profilachsen, nicht in den Bauachsen.
    wahr('Beim gedrehten Steg traegt die schwache Achse das Quermoment',
         Math.abs(kD.MzEd - kD.MqEd) < 1e-9
         && Math.abs(kG.MyEd - kG.MqEd) < 1e-9);
    wahr('Der Widerstand folgt derselben Zuordnung',
         Math.abs(kD.MRz - kD.MRq) < 1e-9 && Math.abs(kG.MRy - kG.MRq) < 1e-9);
  }

  /* =========================================================================
   * >>> WO DIE MASSEN SITZEN - UND WIE SIE GEWOGEN WERDEN. <<<
   * =========================================================================
   *
   * Weisung vom 13. September: «die massen der anbauteile ist auf die höhe
   * der joche oder der tragausleger zuzuweisen oder bei den einzelmasten den
   * auslegern (anschlusshöhe) der masseschwerpunkt der masten ist auf den
   * masseschwerpunkt zu setzen. falls es mit dieser definition noch den
   * rayleigh braucht, dann einbauen.»
   *
   * Damit sind es ZWEI Massen auf zwei Hoehen, und die bisherige Regel
   * («die oberste Krafteinleitung zaehlt») genuegt nicht mehr. Der
   * Rayleigh-Quotient mit der Knickfigur des Kragarms
   *
   *     w(z) = delta [1 - cos(pi z / 2L)]        g(a) = a/2 - (L/2pi) sin(pi a/L)
   *
   * liefert die ERSATZHOEHE z_eq aus  g(z_eq) = Sum P_i g(a_i) / Sum P_i.
   *
   * >>> ZWEI PROBEN, DIE OHNE DEN KERN AUSKOMMEN. <<<
   *
   * Erstens der Grenzfall: EINE Masse an der Spitze muss die Eulerlast des
   * Kragarms ergeben, N_cr = pi^2 EI/(2L)^2. Das ist die Herkunft der Formel
   * und faellt auf, wenn an ihr gedreht wird.
   *
   * Zweitens die Formel selbst, hier unabhaengig nachgerechnet.
   */
  {
    const gVon = (a, L2) => a / 2 - (L2 / (2 * Math.PI)) * Math.sin((Math.PI * a) / L2);
    const zEq = (massen, L2) => {
      const Pg = massen.reduce((a, x) => a + x.P, 0);
      const soll = massen.reduce((a, x) => a + x.P * gVon(Math.min(x.z, L2), L2), 0) / Pg;
      let u = 0, o = L2;
      for (let i = 0; i < 60; i++) {
        const mi = (u + o) / 2;
        if (gVon(mi, L2) < soll) u = mi; else o = mi;
      }
      return (u + o) / 2;
    };
    // Der Grenzfall: eine Masse an der Spitze -> ihre eigene Hoehe.
    pruef('Eine Masse an der Spitze gibt die Spitze',
          zEq([{ z: 12, P: 5 }], 12), 12, 1e-9, 'm');
    // Und zwei gleiche Massen liegen dazwischen, nicht bei der hoeheren.
    const zw = zEq([{ z: 12, P: 5 }, { z: 6, P: 5 }], 12);
    wahr('Zwei Massen liegen dazwischen', zw > 6 && zw < 12,
         `${zw.toFixed(3)} m`);

    /*
     * >>> UND JETZT GEGEN DEN KERN. <<<
     *
     * Der Einzelmast der Probe traegt keine Jochlast - es bleibt sein
     * EIGENGEWICHT, und das sitzt nach der Weisung im Schwerpunkt L/2.
     * HEB 260: 93 kg/m, also 0.9123 kN/m mal 12 m = 10.95 kN auf 6.00 m.
     */
    const ohne = mast();
    const kO = M74.mastStabilitaet(ohne.s, ohne.m, { beta: 2.0 });
    wahr('Ohne weitere Last bleibt das Eigengewicht', kO.massen.length === 1);
    /*
     * >>> ES IST VERTEILT, NICHT EIN PUNKT IM SCHWERPUNKT. <<<
     *
     * Die Weisung vom 13. September setzte es in den Schwerpunkt; auf
     * Nachfrage am selben Tag ("kannst du die abweichungen so anpassen das
     * es aus deiner sicht stimmt") wird es als das gerechnet, was es ist.
     *
     * Im Rayleigh-Quotienten traegt eine verteilte Last q das Integral
     * q * Integral(0..L) g dz = q L^2 (1/4 - 1/pi^2) = 0.148679 q L^2,
     * waehrend dieselbe Last im Schwerpunkt nur P g(L/2) = 0.109014 P L
     * beitraegt - ein Drittel zu wenig.
     *
     * DIE PROBE RECHNET DAS INTEGRAL SELBST. Sie haengt nicht an einer
     * Zahl aus dem Kern, sondern an der Stammfunktion:
     *   Integral z/2 dz = L^2/4,  Integral sin(pi z/L) dz = 2L/pi.
     */
    wahr('… und es steht als verteilt da',
         kO.massen[0].herkunft === 'verteilt über die Länge');
    const gI = (L2) => L2 * L2 * (0.25 - 1 / (Math.PI * Math.PI));
    const gV = (a, L2) => a / 2 - (L2 / (2 * Math.PI)) * Math.sin((Math.PI * a) / L2);
    pruef('Die Ersatzhoehe traegt das Integral der verteilten Last',
          gV(kO.zN, kO.L), gI(kO.L) / kO.L, 1e-6, 'm');
    pruef('… sie liegt bei 0.600 L, nicht bei 0.500',
          kO.zN / kO.L, 0.60007, 1e-4, '–');
    wahr('… also hoeher als der Schwerpunkt', kO.zN > kO.L / 2,
         `${kO.zN.toFixed(3)} gegen ${(kO.L / 2).toFixed(3)} m`);
    wahr('Der Schwerpunkt steht zum Vergleich daneben',
         Math.abs(kO.massen[0].schwerpunkt - kO.L / 2) < 1e-9);

    /*
     * MIT ANBAUTEIL: es wird der ANSCHLUSSHOEHE zugewiesen, nicht seiner
     * eigenen. Der Mast der Probe schliesst auf 9.00 m an; das Teil steht
     * auf 7.00 m und rechnet trotzdem auf 9.00 m mit.
     */
    const teil = { ...A.neuesAnbauteil('hs-fahrdraht', 0), ort: 'mastA',
                   hMast: 7 };
    const { s, m } = mitAnschluss({ anbauteile: [teil] });
    const k = M74.mastStabilitaet(s, m, { beta: 2.0 });
    // Seit dem 18. September auf der eigenen Hoehe, nicht auf 9 m.
    const teilM = k.massen.filter((x) => x.herkunft === 'eigene Befestigungshöhe');
    wahr('Mit Anbauteil stehen seine Lastpunkte neben dem Eigengewicht',
         teilM.length >= 1 && k.massen.length === teilM.length + 1);
    wahr('… und zwar auf seiner Befestigungshoehe, nicht auf dem Anschluss',
         teilM.every((x) => Math.abs(x.z - 7.0) < 1e-9),
         teilM.map((x) => `${x.z} m`).join(', '));
    pruef('Die Ersatzhoehe stimmt mit der Formel ueberein',
          k.zN, zEq(k.massen, k.L), 1e-6, 'm');
    wahr('… und sie liegt zwischen Schwerpunkt und Anschluss',
         k.zN > 6.0 && k.zN < 9.0, `${k.zN.toFixed(3)} m`);
    pruef('Die Gesamtlaenge steht daneben', k.L, 12, 1e-9, 'm');
    {
      // Der Einzelmast selbst: dasselbe Teil bleibt auf seinen 7.00 m.
      const eM = mast({ anbauteile: [teil] });
      const kE = M74.mastStabilitaet(eM.s, eM.m, { beta: 2.0 });
      wahr('Einzelmast: das Teil rechnet auf seiner eigenen Hoehe',
           kE.massen.some((x) => Math.abs(x.z - 7.0) < 1e-9
                              && x.herkunft === 'eigene Befestigungshöhe')
           && !kE.massen.some((x) => x.herkunft === 'Anschlusshöhe'));
      wahr('… und genau wie am Masten mit Anschluss - eine Regel fuer alle',
           Math.abs(kE.zN - k.zN) < 1e-9, `${kE.zN.toFixed(3)} gegen ${k.zN.toFixed(3)} m`);
    }
    /*
     * DIE RICHTUNG: mehr Last oben hebt die Ersatzhoehe. Das ist die Probe,
     * die ohne jede Zahl auskommt.
     */
    const schwer = { ...A.neuesAnbauteil('hs-fahrdraht', 0), ort: 'mastA',
                     hMast: 7 };
    const kS2 = M74.mastStabilitaet(mitAnschluss({ anbauteile: [schwer, schwer] }).s,
                                    mitAnschluss({ anbauteile: [schwer, schwer] }).m,
                                    { beta: 2.0 });
    wahr('Mehr Last auf 7 m zieht die Ersatzhoehe dorthin',
         Math.abs(kS2.zN - 7) < Math.abs(k.zN - 7),
         `${kS2.zN.toFixed(3)} gegen ${k.zN.toFixed(3)} m`);
    wahr('… und die Normalkraft steigt', kS2.NEd > k.NEd);

    /*
     * >>> WAS ÜBER DEM ANSCHLUSS SITZT, WIRD GENANNT. <<<
     *
     * Die Weisung setzt die Anbauteile auf die Anschlusshoehe. Eine Traverse
     * DARUEBER sitzt damit rechnerisch tiefer als in Wirklichkeit - die
     * unsichere Seite. Gerechnet wird nach der Weisung; ausgewiesen wird es
     * trotzdem, sonst steht die Abweichung nirgends.
     */
    const oben = { ...A.neuesAnbauteil('hs-fahrdraht', 0), ort: 'mastA',
                   hMast: 11 };
    const kU = M74.mastStabilitaet(mitAnschluss({ anbauteile: [oben] }).s,
                                   mitAnschluss({ anbauteile: [oben] }).m, { beta: 2.0 });
    /*
     * EINE Baugruppe bringt MEHRERE Lastpunkte mit - die Haengestuetze und
     * die Fahrleitung daran. Gezaehlt werden die Punkte, nicht die Teile.
     */
    /*
     * >>> UND ES BLEIBT AUCH OBEN. <<<
     *
     * Die Weisung setzt die Anbauteile auf die Anschlusshoehe. Fuer alles
     * darunter ist das die sichere Seite - nach oben verschoben wirkt eine
     * Masse unguenstiger. Fuer eine Traverse DARUEBER waere es die
     * unsichere; auf Nachfrage entschieden gilt deshalb
     * z = max(Anschlusshoehe, eigene Hoehe).
     */
    // Seit dem 18. September wird nichts mehr verschoben - also auch nichts
    // als Abweichung ausgewiesen.
    wahr('Ohne Verschiebung gibt es keine Abweichung auszuweisen',
         (kU.ueberAnschluss ?? []).length === 0);
    wahr('… und rechnet auf seiner eigenen Hoehe mit',
         kU.massen.some((x) => Math.abs(x.z - 11) < 1e-9
                            && x.herkunft.startsWith('eigene')));
    wahr('… die Ersatzhoehe steigt dadurch', kU.zN > kO.zN,
         `${kU.zN.toFixed(3)} gegen ${kO.zN.toFixed(3)} m`);
    wahr('… und der Anschluss steht als Bezug daneben',
         Math.abs(kU.zAnschluss - 9.0) < 1e-9);
  }

  /*
   * OHNE MASTLAENGE GILT DIE VORGABE - H + 0.50 m. Bis zum 5. September
   * endete der Mast dort am Anschluss; seither steht er einen halben Meter
   * darueber, und die Laenge misst bis zum Kopf. Sie geht in den Rayleigh
   * ein: die Knickfigur gehoert dem ganzen Kragarm.
   */
  {
    const { s, m } = mast({ mastLaenge: 0 });
    const k = M74.mastStabilitaet(s, m, { beta: 2.0 });
    pruef('Ohne Gesamtlaenge gilt die Vorgabe', k.L, 10.0, 1e-9, 'm');
    pruef('… und die Ersatzhoehe folgt ihr', k.zN / k.L, 0.60007, 1e-4, '–');
  }
}

// ===========================================================================
// PRUEFUNG 75: der Mast als angewaehltes Bauteil, und die Zeichnung, die sich
// nachtraeglich schieben laesst. Weisung vom 2. September.
{
  const C75 = await import(J('core.constants.js'));
  const R75 = await import(J('render.3d.js'));

  /*
   * DREI MASTEN UNTER ZWEI JOCHEN.
   *
   * Die Frage des Auftraggebers: «Wie kann man drei verschiedene Masttypen
   * eingeben?» Sie liess sich vorher nur ueber vier Enden zweier Tragwerke
   * beantworten, von denen zwei derselbe Mast waren. Hier steht, dass es
   * jetzt drei Adressen sind - und dass jede ihr eigenes Profil behaelt.
   */
  const reihe = () => {
    let w = { typ: 'J90', L: 20, xLage: 0, mastProfil: 'HEB 260',
              mastVorhanden: true, endbedingung: 'mast' };
    return C75.tragwerkHinzu(w, 'joch', { L: 15, xLage: 20 });
  };

  {
    const w = reihe();
    const m = C75.mastenVon(w);
    wahr('Zwei Joche stehen auf drei Masten', m.length === 3);
    wahr('Der mittlere ist geteilt',
         (m[1].traegt ?? []).length === 2);
    wahr('… und die aeusseren nicht',
         (m[0].traegt ?? []).length === 1 && (m[2].traegt ?? []).length === 1);
  }

  // JEDER MAST BEKOMMT SEIN EIGENES PROFIL - ueber seine Id, nicht ueber ein
  // Ende. Das ist der ganze Gewinn der Kachelreihe.
  {
    let w = reihe();
    const ids = C75.mastenVon(w).map((m) => m.id);
    w = C75.setzeMastAngabe(w, ids[0], 'mastProfil', 'HEB 240');
    w = C75.setzeMastAngabe(w, ids[1], 'mastProfil', 'HEM 240');
    w = C75.setzeMastAngabe(w, ids[2], 'mastProfil', 'HEB 220');
    const p = C75.mastenVon(w).map((m) => m.profil);
    wahr('Drei Masten, drei Profile',
         p[0] === 'HEB 240' && p[1] === 'HEM 240' && p[2] === 'HEB 220');
  }

  /*
   * >>> DIE MASTENLISTE UEBERSTEHT DAS UMSCHALTEN. <<<
   *
   * Sie stand nicht in BLATT_FELDER, also nahm `tragwerkTeil` sie mit ins
   * weggelegte Tragwerk - und aus dem angewaehlten kam eine alte Liste
   * zurueck oder gar keine. Ein Mast, dem man gerade ein Profil gegeben
   * hatte, stand nach einem Klick auf das Nachbarjoch wieder mit dem alten
   * da. Genau dieser Weg wird hier gegangen.
   */
  {
    let w = reihe();
    const ids = C75.mastenVon(w).map((m) => m.id);
    w = C75.setzeMastAngabe(w, ids[2], 'mastProfil', 'HEB 220');
    const andere = C75.tragwerkeVon(w).find((t) => t.id !== (w.twId ?? 'T1'));
    w = C75.tauscheAktives(w, andere.id);
    wahr('Nach dem Umschalten steht das Profil noch da',
         C75.mastenVon(w).some((m) => m.profil === 'HEB 220'));
    w = C75.tauscheAktives(w, (w.weitere ?? [])[0].id);
    wahr('… und nach dem Zurueckschalten auch',
         C75.mastenVon(w).some((m) => m.profil === 'HEB 220'));
  }

  // DIE KACHELWAHL. Ohne sie gilt der Mast am Ende A des gerechneten
  // Tragwerks - so verhaelt sich jede Datei aus der Zeit vor den Kacheln.
  {
    const w = reihe();
    const ids = C75.mastenVon(w).map((m) => m.id);
    wahr('Ohne Wahl gilt der erste Mast des aktiven Tragwerks',
         C75.gewaehlterMast(w)?.id === C75.mastenFuer(w, C75.tragwerkeVon(w)[0])[0].id);
    wahr('Mit Wahl gilt der angeklickte',
         C75.gewaehlterMast({ ...w, mastAktiv: ids[2] })?.id === ids[2]);
    wahr('Eine Id, die es nicht mehr gibt, faellt zurueck',
         Boolean(C75.gewaehlterMast({ ...w, mastAktiv: 'M99' })));
  }

  /*
   * >>> EIN ABGESCHALTETER MAST DARF SEINEM NACHBARN NICHT SEIN PROFIL
   *     VERERBEN. <<<
   *
   * Am 2. September im Browser gemessen: drei Masten (HEB 260 / HEB 240 /
   * HEM 240), dann die Masten des linken Jochs abgeschaltet. Die Nummern
   * werden LAUFEND vergeben - der uebrig gebliebene Mast bei x 20 hiess
   * danach M1 und bekam ueber die Id das Profil des verschwundenen: HEB 260
   * statt HEB 240. Ein Mast mit einem fremden Profil, und man sieht es ihm
   * nicht an.
   *
   * Seither geht die STELLE vor der Nummer (mastenVon in
   * core.constants.js). Die Nummer ist eine Laufnummer; ein Mast ist, wo er
   * steht.
   */
  {
    let w = reihe();
    const ids = C75.mastenVon(w).map((m) => m.id);
    w = C75.setzeMastAngabe(w, ids[0], 'mastProfil', 'HEB 260');
    w = C75.setzeMastAngabe(w, ids[1], 'mastProfil', 'HEB 240');
    w = C75.setzeMastAngabe(w, ids[2], 'mastProfil', 'HEM 240');

    // Die Masten des LINKEN Jochs abschalten - es ist nicht das aktive.
    const links = C75.tragwerkeSortiert(w)[0];
    let w2 = C75.tauscheAktives(w, links.id);
    w2 = { ...w2, mastVorhanden: false };
    const uebrig = C75.mastenVon(w2);
    wahr('Zwei Masten bleiben stehen', uebrig.length === 2);
    wahr('Der Mast bei x = 20 behaelt sein eigenes Profil',
         uebrig.find((m) => Math.abs(m.x - 20) < 0.01)?.profil === 'HEB 240');
    wahr('… und der am rechten Ende auch',
         uebrig.find((m) => Math.abs(m.x - 35) < 0.01)?.profil === 'HEM 240');

    // UND EIN VERSCHOBENES JOCH NIMMT SEINEN MASTEN MIT. Dort trifft die
    // Stelle nicht mehr - dann faengt die Nummer den Fall.
    const w3 = { ...w, xLage: 21 };
    wahr('Ein verschobener Mast behaelt sein Profil ueber die Nummer',
         C75.mastenVon(w3).find((m) => Math.abs(m.x - 36) < 0.01)?.profil
           === 'HEM 240');
  }

  /*
   * >>> DER KLICK INS BLATT UND DIE LAGE IM TRAGWERK. <<<
   *
   * Am 2. September im Browser gemessen und als Fehler bestaetigt: aktiv war
   * das rechte Joch (x0 = 20), geklickt wurde auf das LINKE bei x 1.54 -
   * abgelegt wurde das Bauteil am RECHTEN bei dessen Ortskoordinate 1.54,
   * also auf dem Blatt bei 21.54. Zwanzig Meter neben der Stelle, auf die
   * gezeigt wurde. Umgekehrt liess sich auf dem rechten Joch nichts
   * absetzen: dort liegen die Blattkoordinaten 20 bis 40, geprueft wurde
   * gegen 0 bis L.
   *
   * Die Ansicht spricht BLATTKOORDINATEN, die Bauteillage zaehlt ab dem
   * linken Ende ihres Tragwerks. Solange nur eines dastand, war das
   * dasselbe.
   */
  {
    const w = reihe();                       // T1 bei 0 (L 20), T2 bei 20 (L 15)
    const [links, rechts] = C75.tragwerkeSortiert(w);
    pruef('Blatt 1.54 ist am linken Joch die 1.54',
          C75.blattNachLokal(links, 1.54), 1.54, 1e-12, 'm');
    pruef('… und am rechten waere es -18.46',
          C75.blattNachLokal(rechts, 1.54), -18.46, 1e-12, 'm');
    pruef('Hin und zurueck ist dasselbe',
          C75.lokalNachBlatt(rechts, C75.blattNachLokal(rechts, 27)), 27,
          1e-12, 'm');

    // WELCHES TRAGWERK STEHT DORT? Ohne diese Frage bekam man «daneben»,
    // waehrend der Zeiger mitten auf einem Joch stand.
    wahr('Bei x = 5 steht das linke', C75.tragwerkBeiX(w, 5)?.id === links.id);
    wahr('Bei x = 30 steht das rechte', C75.tragwerkBeiX(w, 30)?.id === rechts.id);
    wahr('Bei x = 60 steht keines', C75.tragwerkBeiX(w, 60) === null);
    // An der Fuge treffen sich beide - dann gilt das erste von links.
    wahr('An der Fuge gilt das linke', C75.tragwerkBeiX(w, 20)?.id === links.id);
  }

  /*
   * >>> EIN BAUTEIL AM GETEILTEN MASTEN GEHOERT BEIDEN. <<<
   *
   * Weisung vom 2. September: «das bauteil am geteilten masten beheben».
   *
   * Der Befund: Anbauteile standen je Tragwerk. Am Joch richtig - am MASTEN
   * nicht, denn den mittleren Masten einer Jochreihe teilen sich zwei.
   * Eine Traverse an ihm war vom Nachbarn aus unsichtbar, und wurde der
   * Nachbar gerechnet, fehlte ihre Last: der Mast traegt sie, gleichgueltig
   * welches Joch man gerade nachweist.
   */
  {
    const V75 = await import(J('core.vierendeel.js'));
    const AX75 = await import(J('export.axisvm.js'));
    const bauReihe = () => {
      let w = { ...standardwerte(), typ: 'J90', L: 20, xLage: 0,
                endbedingung: 'mast', mastVorhanden: true, anbauteile: [] };
      return C75.tragwerkHinzu(w, 'joch', { L: 15, xLage: 20, anbauteile: [] });
    };
    const trav = (o = {}) => ({ ...A.neuesAnbauteil('hs-fahrdraht', 0),
                                name: 'Traverse', ort: 'mastA', hMast: 6.5,
                                ...o });

    let w = bauReihe();                      // aktiv ist T2, sein Ende A = M2
    const geteilt = C75.mastenVon(w).find((m) => (m.traegt ?? []).length > 1);
    wahr('Der mittlere Mast ist geteilt', Boolean(geteilt));

    w = C75.setzeAnbauteileAn(w, [...(w.anbauteile ?? []), trav()]);
    wahr('Das Bauteil liegt am Masten, nicht am Tragwerk',
         (w.mastAnbauteile ?? []).some((a) => a.mastId === geteilt.id));
    wahr('… und nicht mehr in der Tragwerksliste',
         !(w.anbauteile ?? []).some((a) => a.name === 'Traverse'
           && a.ort === undefined));

    // VOM AKTIVEN aus haengt es am Ende A, VOM NACHBARN aus am Ende B -
    // derselbe Mast, von zwei Seiten gesehen.
    const meins = (sw) => (sw.anbauteile ?? []).find((a) => a.name === 'Traverse');
    wahr('Vom aktiven Tragwerk aus haengt es am Ende A',
         meins(w)?.ort === 'mastA');
    const anderes = C75.tragwerkeVon(w).find((t) => t.id !== (w.twId ?? 'T1'));
    let w2 = C75.tauscheAktives(w, anderes.id);
    w2 = { ...w2, anbauteile: C75.anbauteileFuer(w2, C75.tragwerkeVon(w2)[0]) };
    wahr('Vom Nachbarn aus am Ende B', meins(w2)?.ort === 'mastB');

    // DIE LAST IST IN BEIDEN RECHNUNGEN.
    const bauen = (sw) => V75.modell(C75.rechensatz(sw),
      getProfil(sw.profOG), getProfil(sw.profUG), getStahl(sw.stahl),
      T.getTragjoch(sw.typ));
    wahr('Das aktive Tragwerk rechnet es mit',
         (bauen(w).anbauMastFlach ?? []).length > 0);
    wahr('Der Nachbar auch',
         (bauen(w2).anbauMastFlach ?? []).length > 0);

    /*
     * >>> UND DIE AUSLEITUNG HAENGT ES EINMAL AN. <<<
     *
     * Dort stehen beide Tragwerke in EINEM Modell, und der Zwischenmast ist
     * EIN Mast. Ohne Sperre gemessen: vier Arm-Staebe und zehn Punktlasten
     * statt zwei und fuenf - die Traverse zweimal am selben Masten, mit
     * doppelter Last, und man saehe es der Datei nicht an.
     */
    const deps = { modellVon: (satz) => V75.modell(satz,
      getProfil(satz.profOG), getProfil(satz.profUG), getStahl(satz.stahl),
      T.getTragjoch(satz.typ)) };
    const bau = AX75.stabmodellBlatt(w, deps, { knotenmodell: 'anschnitt' });
    pruef('Ein Anschlusspunkt je Bauteil, nicht zwei',
          (bau.arme ?? []).length, 2, 1e-9, 'Stueck');
    wahr('Die Arm-Staebe stehen einmal da',
         bau.staebe.filter((x) => /ARMM/.test(x.name)).length === 2);

    // AM NICHT GETEILTEN MASTEN aendert sich nichts - dort gibt es keinen
    // Nachbarn, der mitsehen koennte.
    {
      let e = { ...standardwerte(), typ: 'J90', L: 20, xLage: 0,
                endbedingung: 'mast', mastVorhanden: true, anbauteile: [] };
      e = C75.setzeAnbauteileAn(e, [trav()]);
      wahr('Auch der einzelne Mast traegt sein Bauteil',
           (e.anbauteile ?? []).some((a) => a.name === 'Traverse'));
    }

    /*
     * ALTE DATEIEN: das Bauteil steckt noch im Tragwerk, mit `ort` und ohne
     * Mast-Id. Es wird gefunden, ohne dass jemand die Datei umschreibt.
     */
    {
      const alt = bauReihe();
      alt.anbauteile = [trav()];
      delete alt.mastAnbauteile;
      const gefunden = C75.mastAnbauVon(alt);
      wahr('Ein eingebettetes Mastteil wird gefunden', gefunden.length === 1);
      wahr('… und dem richtigen Masten zugeordnet',
           gefunden[0].mastId === C75.mastenFuer(alt,
             C75.tragwerkeVon(alt)[0])[0].id);
    }

    // EIN WEGGELEGTES TRAGWERK TRAEGT KEINE KOPIE. Sonst stuende sie beim
    // naechsten Umschalten als eigene Angabe wieder da und bekaeme nicht
    // mehr mit, was am Masten geschieht.
    wahr('Das weggelegte Tragwerk traegt keine Mastteile',
         !(w2.weitere ?? []).some(
           (t) => (t.anbauteile ?? []).some((a) => a.ort === 'mastA'
                                               || a.ort === 'mastB')));
  }

  /*
   * >>> ZWEI JOCHE DUERFEN SICH BERUEHREN, NICHT DURCHDRINGEN. <<<
   *
   * Weisung vom 2. September: «das überschneiden der joche sollte nicht
   * möglich sein.» Beruehren SCHON - das ist die Jochreihe, und genau diese
   * Stelle muss erreichbar bleiben.
   */
  {
    const w = reihe();                    // T1: 0..20, T2: L 15 bei 20
    const f = (x) => C75.freieLage(w, 'T2', x);
    pruef('Rechts daneben bleibt, wo es ist', f(25).x, 25, 1e-9, 'm');
    pruef('Genau anschliessend ist erlaubt', f(20).x, 20, 1e-9, 'm');
    wahr('… und gilt nicht als geklemmt', f(20).geklemmt === false);
    pruef('Einen Meter hinein wird zurueckgeschoben', f(19).x, 20, 1e-9, 'm');
    wahr('… und sagt es', f(19).geklemmt === true);
    // Von links kommend wird links abgesetzt: das rechte Ende trifft dann
    // das linke Ende des Nachbarn.
    pruef('Von links kommend links anschliessend', f(0).x, -15, 1e-9, 'm');
    pruef('Der Bereich eines Jochs ist [x0, x0+L]',
          C75.bereichVon(C75.tragwerkeSortiert(w)[0])[1], 20, 1e-9, 'm');
  }

  /*
   * >>> EIN TRAGWERK BEISEITELEGEN. <<<
   *
   * Weisung: «wie könnte man einzelne tragabschnitte komplett ausblenden im
   * modell / Anbauteile / nachweis?» Ausgeblendet heisst NICHT DA - sonst
   * blendet man einen Abschnitt aus und findet seine Zahlen weiter in der
   * Auswertung.
   */
  {
    const AX = await import(J('export.axisvm.js'));
    const V = await import(J('core.vierendeel.js'));
    // Ein vollstaendiger Satz - die Ausleitung braucht Profile und Stahl,
    // `reihe()` traegt nur die Geometrie.
    let w = C75.tragwerkHinzu(
      { ...standardwerte(), typ: 'J90', L: 20, xLage: 0,
        endbedingung: 'mast', mastVorhanden: true, anbauteile: [] },
      'joch', { L: 15, xLage: 20, anbauteile: [] });
    wahr('Zunaechst sind beide sichtbar', C75.sichtbareTragwerke(w).length === 2);
    // Das nicht aktive ausblenden.
    const anderes = C75.tragwerkeVon(w).find((t) => t.id !== (w.twId ?? 'T1'));
    let w2 = C75.tauscheAktives(w, anderes.id);
    w2 = { ...w2, ausgeblendet: true };
    w2 = C75.tauscheAktives(w2, w.twId ?? 'T1');
    wahr('Danach zaehlt eines', C75.anzahlSichtbar(w2) === 1);
    wahr('… im Datensatz stehen aber weiter zwei',
         C75.anzahlTragwerke(w2) === 2);
    wahr('Seine Masten bringt es nicht mehr mit',
         C75.mastenVon(w2).length < C75.mastenVon(w).length);

    // UND DIE AUSLEITUNG LAESST ES WEG - nennt es aber im Bericht.
    const deps = { modellVon: (satz) => V.modell(satz,
      getProfil(satz.profOG), getProfil(satz.profUG), getStahl(satz.stahl),
      T.getTragjoch(satz.typ)) };
    const bau = AX.stabmodellBlatt(w2, deps, { knotenmodell: 'anschnitt' });
    const fuesse = [...bau.knoten.keys()].filter((n) => /^MAST_.*_F$/.test(n));
    wahr('Das ausgeblendete steht nicht in der Datei', fuesse.length === 2);
    wahr('… und der Bericht sagt, dass es Absicht war',
         (bau.blatt?.versteckt ?? []).includes(anderes.id));
  }

  /*
   * >>> DIE MASKENSIGNATUR DARF NICHT AN EINEM SCHIEBER HAENGEN. <<<
   *
   * Sie entscheidet, ob die Maske NEU GEBAUT wird - und ein Neubau ersetzt
   * jedes Eingabefeld, auch das, das man gerade in der Hand hat.
   *
   * Gemeldet am 2. September: «der schieber hackt ab nach dem ersten
   * raster». Ursache: in der Signatur standen der NAME des Tragwerks
   * («J90 · 20.00 m»), seine LAGE und die Stellen der Masten. Alle drei
   * haengen an der Jochlaenge. Jeder Rasterschritt baute die Maske neu, der
   * Schieber unter dem Finger verschwand, der Zug brach ab. Dasselbe galt
   * fuer das Zahlenfeld der Lage: jeder Tastendruck nahm ihm den Fokus.
   *
   * Diese Kontrolle haelt die Trennung fest: was sich beim Ziehen aendert,
   * gehoert in die Nachfuehrung, nicht in die Signatur.
   */
  {
    const UI75 = await import(J('ui.js'));
    const w = typUebernehmen({ ...standardwerte(), typ: 'J90' },
                             T.getTragjoch('J90'));
    const sig = (o) => UI75.maskenSignatur({ ...w, ...o }, 'system');
    wahr('Die Jochlaenge baut die Maske nicht neu',
         sig({ L: 20 }) === sig({ L: 20.5 }));
    wahr('Die Lage auch nicht',
         sig({ xLage: 0 }) === sig({ xLage: 3.25 }));
    wahr('Ein anderes Mastprofil auch nicht',
         sig({ mastProfil: 'HEB 240' }) === sig({ mastProfil: 'HEB 260' }));

    /*
     * WAS DIE MASKE SEHR WOHL NEU BAUEN MUSS: alles, was aendert, WELCHE
     * Felder dastehen. Ohne diese Gegenprobe waere die Kontrolle darueber
     * mit einer Signatur erfuellt, die sich nie aendert.
     */
    const zwei = C75.tragwerkHinzu(w, 'einzelmast', {});
    wahr('Ein zweites Tragwerk baut sie neu',
         UI75.maskenSignatur(zwei, 'system') !== sig({}));
    wahr('Ein ausgeblendetes Tragwerk ebenso',
         UI75.maskenSignatur({ ...zwei, ausgeblendet: true }, 'system')
           !== UI75.maskenSignatur(zwei, 'system'));
    wahr('Und die Masten ein- oder auszuschalten ebenso',
         sig({ mastVorhanden: false }) !== sig({ mastVorhanden: true }));
  }

  /*
   * >>> DER MAST HEISST UEBERALL GLEICH. <<<
   *
   * Weisung vom 2. September: «ich bin der meinung das wir masten klar
   * definiert haben sollten und nicht als auflager a und b, das führt zu
   * verwirrung bei einer jochreihe.»
   *
   * Zu Recht: «Ende B» benennt das ENDE DES JOCHS, nicht den Masten. Der
   * Zwischenmast einer Reihe ist das Ende B des linken Jochs UND das Ende A
   * des rechten - ein Bauteil mit zwei Namen. Sein Name kommt jetzt aus der
   * Reihenfolge auf dem Blatt und gilt von beiden Seiten.
   */
  {
    const w = reihe();                     // T1 bei 0, T2 bei 20 (aktiv)
    const [links, rechts] = C75.tragwerkeSortiert(w);
    pruef('Drei Masten', C75.mastenVon(w).length, 3, 1e-9, 'Stueck');
    wahr('Von links gezaehlt heissen sie M1, M2, M3',
         C75.mastenVon(w).map((m) => C75.mastName(w, m)).join(',') === 'M1,M2,M3');

    // DIE PROBE: derselbe Mast, von beiden Jochen aus.
    wahr('Das Ende B des linken Jochs ist M2',
         C75.mastNameAmEnde(w, links, 'B') === 'M2');
    wahr('… und das Ende A des rechten ebenfalls',
         C75.mastNameAmEnde(w, rechts, 'A') === 'M2');
    wahr('Die aeusseren heissen M1 und M3',
         C75.mastNameAmEnde(w, links, 'A') === 'M1'
         && C75.mastNameAmEnde(w, rechts, 'B') === 'M3');

    // Und der Name wandert in den Rechensatz - das Bild kennt den
    // Blattzusammenhang nicht und bekommt ihn von dort.
    const satz = C75.tragwerkSatz(w, rechts.id);
    wahr('Der Satz traegt die Namen mit',
         satz.mastNameA === 'M2' && satz.mastNameB === 'M3');
  }

  /*
   * EINE BESCHRIFTUNG DARF RECHNEN - und muss dann mitlaufen.
   *
   * `label` als Funktion macht aus «Anschlusshöhe Ende B» ein
   * «Anschlusshöhe Ende B · Mast M2». Der Preis: sie haengt an Werten, die
   * NICHT in der Maskensignatur stehen (sie zogen sonst den Schieber mit).
   * Gemessen am 2. September stand deshalb «Mast M1» ueber einem Feld, das
   * M2 meinte, bis `aktualisiereMaske` sie mitfuehrte.
   */
  {
    const mitFn = FELDER.filter((f) => typeof f.label === 'function');
    wahr('Es gibt gerechnete Beschriftungen', mitFn.length >= 3);
    const w = reihe();
    wahr('Sie geben Text, keinen Code',
         mitFn.every((f) => typeof f.label(w) === 'string' && f.label(w).length));
    // DIE NACHFUEHRUNG MUSS ES TUN. Ohne sie bliebe der alte Text stehen.
    const r = readFileSync(new URL('./js/ui.js', import.meta.url), 'utf8');
    wahr('aktualisiereMaske fuehrt sie nach',
         r.includes("typeof f?.label !== 'function'"));
  }

  /*
   * ZIEHEN RASTET GROB, DAS FELD BLEIBT FEIN.
   *
   * Weisung vom 2. September: «die masten beim verschieben per drag and drop
   * auf halbe meter rastern ansonsten das eingabefeld nutzen. das gleiche
   * für die schieber.»
   *
   * Fuenf Zentimeter waren die falsche Zahl fuer eine Ziehgeste: auf 240
   * Punkten Breite und vierzig Metern Blatt ist ein Bildpunkt rund siebzehn
   * Zentimeter, das Raster lag also unter der Aufloesung der Geste.
   */
  {
    pruef('Das Ziehraster ist ein halber Meter', C75.ZUG_RASTER, 0.5, 1e-12, 'm');
    pruef('20.17 rastet auf 20.00', C75.aufRaster(20.17), 20, 1e-12, 'm');
    pruef('20.30 rastet auf 20.50', C75.aufRaster(20.30), 20.5, 1e-12, 'm');
    pruef('Auch nach unten', C75.aufRaster(-3.4), -3.5, 1e-12, 'm');

    // DAS FELD BLEIBT FEIN. Zwei Schrittweiten an einem Wert: der Schieber
    // rastet grob, das Zahlenfeld daneben auf den Zentimeter.
    const grob = FELDER.filter((f) => f.zugSchritt);
    wahr('Es gibt Felder mit grober Ziehstufe', grob.length >= 4);
    /*
     * >>> DER HALBE METER GILT FUER LAENGEN. <<<
     *
     * Weisung vom 11. September: der Anker traegt jetzt auch seine NEIGUNG
     * als Schieber, und die rastet auf fuenf Grad. Hier stand «alle Felder
     * mit Ziehstufe rasten auf 0.5» - richtig, solange alle in Metern
     * massen. Die Regel bleibt, ihr Geltungsbereich steht jetzt dabei.
     */
    const inMetern = grob.filter((f) => f.einheit === 'm');
    wahr('Die Laengen rasten am Schieber auf den halben Meter',
         inMetern.length >= 4 && inMetern.every((f) => f.zugSchritt === 0.5));
    wahr('… und der Winkel auf fuenf Grad',
         grob.filter((f) => f.einheit === '°')
             .every((f) => f.zugSchritt === 5));
    wahr('… und im Feld feiner',
         grob.every((f) => f.schritt < f.zugSchritt));
    wahr('Die Jochlaenge ist darunter',
         grob.some((f) => f.key === 'L'));
  }

  /*
   * >>> DAS KONTEXTMENUE DARF SICH NICHT SELBST WEGZIEHEN. <<<
   *
   * Es schliesst bei einem `pointerdown` daneben. Ohne die Pruefung, OB der
   * Druck daneben war, schloss es auch bei einem Druck DARIN - und der
   * folgende `click` landete auf nichts. Mit nachgestellten Klicks faellt
   * das nicht auf (die feuern kein `pointerdown`), mit einer echten Maus
   * haette kein einziger Eintrag funktioniert.
   *
   * Am 2. September so gebaut, am 3. September mit einer echten Maus
   * gefunden. Die Kontrolle liest den Quelltext, weil das Menue in app.js
   * lebt und keinen Einstieg von aussen hat.
   */
  {
    const r = APP_QUELLE();
    const ab = r.indexOf('const zu = (e) => {');
    // Das Fenster wurde groesser: seit dem 3. September steht davor der
    // Grund, warum `e.target` ein Node SEIN MUSS (wheel und blur liefern
    // das Fenster, und `Node.contains(Window)` wirft).
    const koerper = ab > 0 ? r.slice(ab, ab + 900) : '';
    wahr('Ein Druck IM Menue schliesst es nicht',
         koerper.includes('n.contains(e.target)'));
    // Und die Felder halten es offen: wer den Typ aendert, zieht oft gleich
    // die Laenge nach.
    wahr('Ein Feld im Menue schliesst es ebenfalls nicht',
         r.includes('DAS MENUE BLEIBT OFFEN'));
  }

  /*
   * >>> EIN NEUES TRAGWERK LANDET NEBEN DEM LETZTEN, NICHT DARAUF. <<<
   *
   * Weisung vom 3. September, sinngemaess: «ich frage mich ob dies bei einem
   * tragwerk das über drei joche geht noch sinnvoll ist.»
   *
   * Es war es nicht: `tragwerkHinzu` uebernahm den ganzen bisherigen Satz -
   * samt `xLage`. Drei Tragjoche standen danach alle bei x0 = 0,
   * deckungsgleich; in der Leiste war nur das oberste anklickbar, im Modell
   * steckten sie ineinander.
   */
  {
    let w = { typ: 'J90', L: 20, xLage: 0, twId: 'T1', flSpannweite: 40 };
    w = C75.tragwerkHinzu(w, 'joch', {});
    w = C75.tragwerkHinzu(w, 'joch', { L: 15 });
    const lagen = C75.tragwerkeSortiert(w).map((t) => C75.bereichVon(t));
    wahr('Drei Joche stehen in einer Reihe',
         lagen.map((b) => b.join('-')).join(' ') === '0-20 20-40 40-55');
    // Jedes schliesst am rechten Ende des vorigen an - dort steht der
    // gemeinsame Zwischenmast.
    pruef('Vier Masten, keine doppelten', C75.mastenVon(w).length, 4, 1e-9, 'Stk');

    /*
     * EIN EINZELMAST HAT KEINE LAENGE. «Am rechten Ende anschliessen» hiesse
     * bei ihm: an dieselbe Stelle. Er rueckt um die Spannweite weiter.
     */
    const m1 = C75.tragwerkHinzu({ typ: 'J90', L: 20, xLage: 0, twId: 'T1',
                                   flSpannweite: 40 }, 'einzelmast', {});
    const m2 = C75.tragwerkHinzu(m1, 'einzelmast', {});
    const xs = C75.tragwerkeSortiert(m2).map((t) => C75.lageVon(t));
    wahr('Einzelmasten stehen nicht aufeinander',
         new Set(xs.map((x) => x.toFixed(2))).size === xs.length);
  }

  /*
   * >>> WAS UEBEREINANDER STEHT, DARF SICH DECKEN. <<<
   *
   * Weisung vom 3. September: «wir haben zudem bei den abfangjochen zwei
   * joche übereinander.» Ein Abfangjoch sitzt UEBER einem Tragjoch, auf
   * denselben Masten und auf derselben Strecke - die Regel «nichts darf sich
   * ueberschneiden» haette diesen Aufbau verboten. Verboten bleibt die
   * Ueberschneidung GLEICHER Art.
   */
  {
    let w = { typ: 'J90', L: 20, xLage: 0, twId: 'T1' };
    w = C75.tragwerkHinzu(w, 'abfangjoch', { xLage: 0, L: 20 });
    const abfang = w.twId;
    const f = C75.freieLage(w, abfang, 0);
    pruef('Ein Abfangjoch darf auf dem Tragjoch liegen', f.x, 0, 1e-9, 'm');
    wahr('… und wird nicht geklemmt', f.geklemmt === false);

    // Zwei Tragjoche dagegen schon.
    let z = { typ: 'J90', L: 20, xLage: 0, twId: 'T1' };
    z = C75.tragwerkHinzu(z, 'joch', { L: 20 });
    const g = C75.freieLage(z, z.twId, 5);
    wahr('Zwei Tragjoche werden auseinandergeschoben', g.geklemmt === true);

    /*
     * >>> UND ZWEI ABFANGJOCHE STEHEN UEBEREINANDER. <<<
     *
     * Weisung vom 3. September, praezisiert: «es gibt im normalfall nur
     * abfangjoche die übereinander montiert sind. die tragjoche sind immer
     * in reihe.»
     *
     * Die erste Fassung sagte «verschiedene Arten duerfen sich decken» - das
     * war zu weit gefasst UND zu eng: es haette zwei Abfangjoche
     * auseinandergeschoben, obwohl gerade die uebereinander gehoeren.
     */
    let ab = { typ: 'J90', L: 20, xLage: 0, twId: 'T1',
               tragwerksart: 'abfangjoch' };
    ab = C75.tragwerkHinzu(ab, 'abfangjoch', { xLage: 0, L: 20 });
    wahr('Zwei Abfangjoche duerfen uebereinander stehen',
         C75.freieLage(ab, ab.twId, 0).geklemmt === false);
  }

  /*
   * >>> DIE POSITIONSNUMMER: P1, P2, ... VON LINKS. <<<
   *
   * Weisung vom 3. September: «die joche sollten auch kurzbezeichnungen
   * (positionen) damit man die eingabe in der Sidebar nachvollziehen kann.»
   *
   * Die Masten heissen laengst M1, M2 und die Anbauteile A1, A2 - nur die
   * Tragwerke trugen im Bild keine Kennung. Auf einer Reihe stand dreimal
   * «J90 · 20.00 m».
   *
   * NICHT die `twId`: sie zaehlt in der Reihenfolge, in der ANGELEGT wurde.
   * Ein Abfangjoch, zwischen zwei bestehende gesetzt, heisst T4 und steht in
   * der Mitte - eine Nummer, die man von links nach rechts liest, muss von
   * links nach rechts zaehlen.
   */
  {
    let w = { typ: 'J90', L: 20, xLage: 0, twId: 'T1' };
    w = C75.tragwerkHinzu(w, 'joch', {});          // T2, rechts daneben
    w = C75.tragwerkHinzu(w, 'abfangjoch', { xLage: 0, L: 20 });  // T3, links
    const sortiert = C75.tragwerkeSortiert(w);
    // Seit dem 19. September nach dem Typ («T A M MT»), je Typ von links.
    wahr('Von links gezaehlt, je Typ: T1, A1, T2',
         sortiert.map((t) => C75.tragwerkPos(w, t)).join(',') === 'T1,A1,T2',
         sortiert.map((t) => C75.tragwerkPos(w, t)).join(','));
    // Die Id zaehlt anders - und genau darum wird sie nicht angezeigt.
    wahr('Die Id folgt der Anlegereihenfolge, nicht der Lage',
         sortiert.map((t) => t.id).join(',') !== 'T1,T2,T3');
    // Und sie wandert in den Rechensatz, damit das Bild sie anschreiben kann.
    wahr('Der Satz traegt die Position mit',
         Boolean(C75.tragwerkSatz(w, sortiert[1].id).twPos));
  }

  /*
   * >>> EIN TITEL IM BILD WEISS, WEM ER GEHOERT. <<<
   *
   * Gemeldet am 3. September: «wenn ich die mastbezeichnung im 3d anklicke
   * wird nicht in der sidebar auf M2 oder M1 umgeschalten.» Der Klick fuehrte
   * auf das FELD «Mastprofil» - welcher Mast dort angewaehlt war, blieb wie
   * es war. Man klickte auf M2 und bearbeitete M1.
   *
   * Der Masttitel traegt jetzt sein Ende, und der Treffer geht mit an die
   * Anwendung. Geprueft am Quelltext, weil beides in Ansicht und Anwendung
   * lebt und keinen Einstieg von aussen hat.
   */
  {
    const r3 = readFileSync(new URL('./js/render.3d.js', import.meta.url), 'utf8');
    const rA = APP_QUELLE();
    wahr('Der Masttitel nennt sein Ende', r3.includes('mastEnde: name,'));
    wahr('Der Treffer geht an die Anwendung',
         r3.includes('this.opt.beiMass?.(mt.feld, mt.tab, mt.bt ?? null)'));
    wahr('Auch ein gedaempfter Titel ist anklickbar',
         r3.includes('ANKLICKBAR IST ER TROTZDEM'));
    /*
     * DIE REIHENFOLGE IM BLOCK, nicht in der Datei.
     *
     * Hier stand `rA.indexOf(...)` ueber die GANZE Datei - und fiel am
     * 16. September, als das Mastfenster dazukam: dessen `mastAktiv` steht
     * weiter oben, hat mit dem Masttitel aber nichts zu tun. Eine Kontrolle,
     * die am falschen Ort misst, meldet einen Fehler, den es nicht gibt -
     * und uebersieht den, den es geben koennte.
     *
     * Gemessen wird deshalb der Block `beiMass` selbst.
     */
    {
      const i0 = rA.indexOf('beiMass: (feld, tab, bt) => {');
      const blockM = rA.slice(i0, i0 + 800);
      wahr('Die Anwendung waehlt erst das Tragwerk, dann den Masten',
           i0 > 0
           && blockM.indexOf("aendern('tragwerkAktiv', bt.twId)")
              < blockM.indexOf("aendern('mastAktiv', m.id)"));
    }
  }

  /*
   * >>> AUCH ALLEIN STEHT EIN TRAGWERK AN SEINER STELLE. <<<
   *
   * Gemeldet am 3. September: «beim separierter darstellung werden die
   * lasten (linien) der ausgeblendeten noch dargestellt.»
   *
   * `blattSzene` hatte einen Kurzschluss: bleibt EIN Tragwerk sichtbar, gab
   * es die unverschobene Szene zurueck - in den eigenen Koordinaten des
   * Tragwerks, 0 bis L. Solange ein Blatt eines trug und dessen Lage null
   * war, stimmte das. Blendet man auf einer Reihe die anderen aus, sprang
   * das uebrige auf x = 0, waehrend Masskette und hinterlegte Zeichnung
   * weiter in Blattkoordinaten stehen: Linien an Stellen, an denen nichts
   * mehr ist.
   *
   * Und dasselbe traf das Setzen von Bauteilen: `stelleAus` rechnet den
   * Klick von der Blatt- in die Tragwerkskoordinate um. Stand die Szene
   * unverschoben da, ging jeder Klick um x0 daneben.
   */
  {
    const rA = APP_QUELLE();
    const ab = rA.indexOf('function blattSzene(erg) {');
    const koerper = ab > 0 ? rA.slice(ab, rA.indexOf('\nfunction ', ab + 10)) : '';
    /*
     * GESUCHT WIRD DIE ANWEISUNG, nicht der Text: der Kommentar darueber
     * ZITIERT die entfernte Zeile, damit man weiss, was einmal dastand. Ein
     * blosses `includes` faende sie dort wieder und meldete den Fehler als
     * bestehend.
     */
    wahr('blattSzene kennt keinen Kurzschluss mehr',
         koerper.length > 0 && !koerper.split(/\r?\n/).some(
           (z) => z.trim() === 'if (alle.length < 2) return eigen;'));
    wahr('… und verschiebt jedes Teil an seine Lage',
         koerper.includes('szeneVerschieben({ ...eigen, aktiv: true }, dx,'));
  }

  /*
   * >>> DIE LAENGENGRENZE GILT NUR DEM ENDE B. <<<
   *
   * Weisung vom 3. September: «das verschieben der tragwerke in der sidebar
   * nochmals auf die funktionalität und logik checken.»
   *
   * Dabei gefunden: `mastGrenzen` legte die Sortimentsgrenze des Jochtyps
   * AUCH auf das Ende A. Am Ende A gezogen VERSCHIEBT sich das Tragwerk -
   * seine Laenge aendert sich gar nicht. Bei einem J90 (8 bis 26.5 m) liess
   * sich ein Joch von 20 m deshalb nur zwischen -6.5 und +12 m um sein
   * rechtes Ende schieben: eine Schranke, die niemand erklaeren kann.
   */
  {
    const UI = await import(J('ui.js'));
    const w = reihe();
    const masten = C75.mastenVon(w);
    const links = UI.mastRollen(w, masten[0].id);      // nur Ende A
    wahr('Der linke Mast ist nur ein Ende A',
         Boolean(links.alsA) && !links.alsB);
    pruef('Ihn zu ziehen kennt keine Laengengrenze',
          UI.mastGrenzen(links, -500), -500, 1e-9, 'm');
    pruef('… auch nicht nach oben', UI.mastGrenzen(links, 500), 500, 1e-9, 'm');

    // Am Ende B dagegen aendert das Ziehen die LAENGE - dort ist der
    // Sortimentsbereich die richtige Grenze.
    const rechts = UI.mastRollen(w, masten[masten.length - 1].id);
    wahr('Der rechte Mast ist ein Ende B', Boolean(rechts.alsB));
    const { laengenbereich: lb } = await import(J('data.tragjoche.js'));
    const b = lb(T.getTragjoch(rechts.alsB.t.typ));
    pruef('Er bleibt im Sortiment', UI.mastGrenzen(rechts, 1e4),
          rechts.alsB.x0 + b.max, 1e-9, 'm');
  }

  /*
   * >>> EIN ABFANGJOCH SCHLIESST NICHT AN, ES SITZT DARUEBER. <<<
   *
   * Weisung vom 3. September: «es gibt im normalfall nur abfangjoche die
   * übereinander montiert sind.» Es wird auf DIESELBEN Masten montiert wie
   * das Joch darunter - also uebernimmt es dessen Lage, statt sich rechts
   * anzuhaengen. Der Regelfall gehoert in die Vorgabe.
   */
  {
    let w = { typ: 'J90', L: 20, xLage: 0, twId: 'T1', mastH: 7.5 };
    w = C75.tragwerkHinzu(w, 'abfangjoch', {});
    w = { ...w, mastH: 9.0 };
    w = C75.tragwerkHinzu(w, 'abfangjoch', {});
    w = { ...w, mastH: 10.5 };
    const b = C75.tragwerkeSortiert(w).map((t) => C75.bereichVon(t).join('-'));
    wahr('Alle drei stehen ueber derselben Strecke',
         b.join(' ') === '0-20 0-20 0-20');
    // UND AUF DENSELBEN MASTEN. Zwei Masten, jeder traegt drei Tragwerke.
    const m = C75.mastenVon(w);
    pruef('Zwei Masten fuer drei Tragwerke', m.length, 2, 1e-9, 'Stk');
    wahr('Jeder traegt alle drei', m.every((x) => (x.traegt ?? []).length === 3));

    /*
     * SIE UNTERSCHEIDEN SICH NUR IN DER ANSCHLUSSHOEHE - also steht sie im
     * Namen. «HEB 240 · 9.00 m» las sich wie ein Mast; mit dem H davor liest
     * es sich als das, was es ist. Ein eigener Typ (A160, A200, A240) steht
     * noch aus.
     */
    const namen = C75.tragwerkeSortiert(w).map(C75.tragwerkName);
    wahr('Das Abfangjoch nennt seine Anschlusshoehe',
         namen[1].includes('H 9.00 m') && namen[2].includes('H 10.50 m'));
    wahr('Das Tragjoch nennt weiter seinen Typ', namen[0].includes('J90'));
  }

  /*
   * >>> DER HINWEIS SAGT, WAS HEUTE GILT. <<<
   *
   * Bis zum 9. September stand dort «gerechnet wird weiterhin das Tragjoch»
   * - waehrend die Uebersicht danebem «η Gurt 1.575 · UPE 160» zeigte, die
   * Zahl des Abfangjochs. Zwei Aussagen ueber dieselbe Groesse, eine davon
   * falsch.
   */
  {
    /*
     * Gelesen wird der QUELLTEXT: `hinweise` braucht ein volles Modell, und
     * geprueft wird hier der Satz, nicht der Weg dorthin.
     */
    const r9 = readFileSync(new URL('./js/core.checks.js', import.meta.url),
                            'utf8');
    wahr('Der Hinweis nennt den eigenen Nachweis',
         r9.includes('die ganze Auswertung ist seine eigene'));
    wahr('… und nicht mehr «weiterhin das Tragjoch»',
         !r9.includes('gerechnet wird weiterhin das '));
    /*
     * >>> UND DIE REITER GEHOEREN JETZT DAZU. <<<
     *
     * Weisung vom 10. September: «die reiter schnitt verläufe und auflager
     * beim abfangjoch fertig machen.» Hier stand «nennt aber die Reiter,
     * die es noch sind» - der Hinweis zaehlte sie als AUSNAHME auf. Jetzt
     * zaehlt er sie als Teil der eigenen Auswertung.
     */
    wahr('… und zaehlt die Reiter dazu',
         r9.includes('Reiter SCHNITT, VERLÄUFE und AUFLAGER'));
    wahr('Nirgends steht mehr, sie rechneten den Ersatzbalken',
         !r9.includes('rechnen dagegen weiter den'));
    /*
     * DIE GLIEDERUNG DES AUFLAGERBLATTS BLEIBT EIN HINWEIS: das Tragjoch
     * fuehrt Einwirkungsgruppen, das Abfangjoch Faelle. Wer die beiden
     * Blaetter nebeneinanderlegt, muss das wissen.
     */
    wahr('Das Auflagerblatt nennt seine andere Gliederung',
         r9.includes('nach FÄLLEN aufgeschlüsselt'));
  }

  /*
   * ====== ZUG-/DRUCKSTUETZEN UND SEILANKER AM MASTEN ===================
   *
   * Weisung vom 9. September: «bitte danach die moeglichkeit Zuganker oder
   * Drucksuetzen an den masten zu modelieren. diese sind gelenkig gelagert.
   * … koennen anhand des bemessungdiagramms nachgewiessen werden.»
   *
   * Das Sortimentsblatt fuehrt die zulaessige DRUCKBELASTUNG ueber die
   * Stuetzenlaenge - eine fallende Kurve je Typ. Die Werte sind aus der
   * Vektorquelle des Diagramms ausgelesen, nicht am Bildschirm abgegriffen.
   */
  if (AN.ankerDbDa()) {
    wahr('Das Ankersortiment ist geladen', AN.ankerTypen().length >= 3,
         `${AN.ankerTypen().length} Typen`);
    wahr('Die Stuetze traegt Druck, das Seil nicht',
         AN.ankerTraegtDruck('U12') && AN.ankerTraegtDruck('U14')
         && !AN.ankerTraegtDruck('SA20'));

    /*
     * >>> DIE KURVE FAELLT, WEIL DIE STUETZE KNICKT. <<<
     *
     * Je laenger sie ist, desto weniger Druck traegt sie. Das ist die
     * Aussage des Diagramms, und sie muss ueber die ganze Laenge gelten -
     * eine Kurve, die irgendwo wieder steigt, waere falsch abgelesen.
     */
    ['U12', 'U14'].forEach((typ) => {
      const t2 = AN.getAnkerTyp(typ);
      const N = t2.druck.N;
      wahr(`${typ}: die zulaessige Druckkraft faellt mit der Laenge`,
           N.every((v, i) => i === 0 || v < N[i - 1] + 1e-9));
      wahr(`${typ}: die Kurve endet an der groessten Laenge`,
           Math.abs(t2.druck.L[t2.druck.L.length - 1] - t2.laengeMax) < 1e-9);
      wahr(`${typ}: sie beginnt an der Kappung`,
           Math.abs(N[0] - t2.druck.kappung) < 1e-9);
    });

    /*
     * STUETZSTELLEN AUS DEM DIAGRAMM - abgelesen im halben Meter.
     * U12 bei 10.50 m (seiner groessten Laenge) rund 44 kN,
     * U14 bei 12.50 m rund 51 kN. Der laengere Typ traegt bei gleicher
     * Laenge mehr; das ist der Grund, ihn zu waehlen.
     */
    pruef('U12 bei 10.50 m', AN.ankerZulDruck('U12', 10.5), 43.7, 0.05, 'kN');
    pruef('U12 bei 8.00 m', AN.ankerZulDruck('U12', 8.0), 75.6, 0.05, 'kN');
    pruef('U14 bei 12.50 m', AN.ankerZulDruck('U14', 12.5), 51.2, 0.05, 'kN');
    pruef('U14 bei 10.50 m', AN.ankerZulDruck('U14', 10.5), 75.0, 0.05, 'kN');
    wahr('Der U14 traegt bei gleicher Laenge mehr als der U12',
         AN.ankerZulDruck('U14', 10.5) > AN.ankerZulDruck('U12', 10.5));
    /*
     * ZWISCHEN DEN STUETZSTELLEN WIRD INTERPOLIERT - die Kurve ist glatt,
     * und die Laenge einer Stuetze ist keine runde Zahl.
     */
    pruef('Zwischen 8.00 und 9.00 m liegt die Mitte',
          AN.ankerZulDruck('U12', 8.5), (75.6 + 60.0) / 2, 1e-9, 'kN');
    /*
     * KURZ: DER QUERSCHNITT KAPPT. Unterhalb des Schnittpunkts mit der
     * Kappungslinie laeuft die Kurve waagrecht - dort knickt die Stuetze
     * nicht mehr, sondern der Querschnitt fliesst.
     */
    pruef('Kurz gekappt bei der Querschnittsgrenze',
          AN.ankerZulDruck('U12', 5.0), 135, 1e-9, 'kN');
    /*
     * LANG: ES GIBT SIE NICHT. Die Kurve fortzusetzen hiesse, ein Bauteil
     * zu bemessen, das niemand liefert.
     */
    wahr('Ueber der groessten Laenge gibt es keinen Wert',
         AN.ankerZulDruck('U12', 11.0) === null
         && AN.ankerZulDruck('U14', 13.0) === null);
    wahr('Und ein Seil hat gar keine Druckkurve',
         AN.ankerZulDruck('SA20', 8.0) === null);

    /*
     * >>> AUF ZUG ENTSCHEIDET DIE BEFESTIGUNG, NICHT DIE LAENGE. <<<
     *
     * Ein Zugstab knickt nicht. Das Blatt nennt zwei Werte: den grossen fuer
     * Ankerplatte und Vorsetzkonsole, den kleineren fuer Ankereisen oder
     * Anschlussbuegel. Es ist die BEFESTIGUNG, die begrenzt.
     */
    pruef('Zug an Ankerplatte', AN.ankerZulZug('U12', 'ankerplatte'),
          135, 1e-9, 'kN');
    pruef('Zug an Ankereisen', AN.ankerZulZug('U12', 'ankereisen'),
          90, 1e-9, 'kN');
    wahr('Beide Stuetzentypen tragen denselben Zug',
         AN.ankerZulZug('U12', 'ankerplatte')
         === AN.ankerZulZug('U14', 'ankerplatte'));
    pruef('Der Seilanker traegt 67 kN Betriebslast',
          AN.ankerZulZug('SA20'), 67, 1e-9, 'kN');
    wahr('Seine Bruchkraft ist ein Vielfaches davon und steht nicht im '
         + 'Nachweis',
         AN.getAnkerTyp('SA20').bruchkraft > 3 * AN.ankerZulZug('SA20'));

    /*
     * >>> DER NACHWEIS SAGT, WAS BEGRENZT. <<<
     *
     * Gegen Knicken hilft ein groesserer Typ, gegen die Befestigung nur eine
     * andere Befestigung. Eine blosse Zahl liesse offen, wo man ansetzt.
     */
    const nD = AN.ankerNachweis('U12', -40, 9.0);
    wahr('Druck wird gegen die Knickkurve geprueft', nD.grund === 'knicken');
    pruef('… und eta ist Kraft durch zulaessig', nD.eta,
          40 / AN.ankerZulDruck('U12', 9.0), 1e-9, '-');
    wahr('Kurzer Druckstab: der Querschnitt begrenzt',
         AN.ankerNachweis('U12', -40, 5.0).grund === 'querschnitt');
    wahr('Zug: die Befestigung begrenzt',
         AN.ankerNachweis('U12', 40, 9.0).grund === 'befestigung');
    /*
     * EIN SEIL AUF DRUCK HAENGT DURCH. Bis zum 16. September galt das als
     * Fehler im Modell (eta = unendlich); seither faellt es aus und wird als
     * Hinweis gemeldet - siehe Abschnitt 66.
     */
    const nS = AN.ankerNachweis('SA20', -10, 8.0);
    wahr('Ein Seil auf Druck haengt durch', nS.ok === true
         && nS.grund === 'schlaff' && nS.eta === null);
    /*
     * UEBER DEM SORTIMENT GIBT ES KEIN URTEIL - weder ja noch nein.
     */
    const nU = AN.ankerNachweis('U12', -40, 11.5);
    wahr('Ueber der groessten Laenge steht kein Urteil da',
         nU.ok === null && nU.grund === 'ueberSortiment');
    /*
     * >>> ES SIND ZULAESSIGE KRAEFTE, KEINE BEMESSUNGSWIDERSTAENDE. <<<
     *
     * Das Blatt stammt aus dem Verfahren der zulaessigen Spannungen. Womit
     * die Zahlen zu vergleichen sind, steht im Ergebnis - damit niemand
     * einen Bemessungswert dagegenhaelt, ohne es zu merken.
     */
    wahr('Der Nachweis nennt seine Vergleichsbasis',
         nD.vergleichsbasis === 'zulaessigeKraft');

    /*
     * >>> DIE GEOMETRIE AM MASTEN. <<<
     *
     * Zwei Masse beschreiben den Stab: die Anschlusshoehe am Masten und der
     * waagrechte Abstand seines Fundaments. Alles Uebrige folgt daraus.
     */
    const g345 = AN.ankerGeometrie(4, 3);
    pruef('3-4-5: die Laenge folgt aus Pythagoras', g345.L, 5, 1e-9, 'm');
    pruef('… der Winkel gegen die Waagrechte', g345.alpha,
          (Math.atan2(4, 3) * 180) / Math.PI, 1e-9, '°');
    pruef('… der waagrechte Anteil', g345.cos, 0.6, 1e-9, '-');
    pruef('… der lotrechte', g345.sin, 0.8, 1e-9, '-');
    wahr('Ohne brauchbare Masse gibt es keine Geometrie',
         AN.ankerGeometrie(0, 3) === null
         && AN.ankerGeometrie(4, -1) === null
         && AN.ankerGeometrie(NaN, 3) === null);
    /*
     * >>> JE STEILER DER STAB, DESTO GROESSER SEINE KRAFT. <<<
     *
     * Gegen eine waagrechte Kraft wirkt nur der waagrechte Anteil N·cos α.
     * Steil angesetzt wird cos α klein, und N muss wachsen - der Anker
     * arbeitet gegen sich selbst. Das ist der Grund, das Ankerfundament
     * nicht zu nah an den Masten zu setzen.
     */
    const flach = AN.ankerGeometrie(2, 8);   // flach: alpha rund 14 Grad
    const steil = AN.ankerGeometrie(8, 2);   // steil: alpha rund 76 Grad
    wahr('Der steile Stab traegt bei gleicher Wirkung mehr',
         AN.ankerStabkraft(30, steil) > AN.ankerStabkraft(30, flach),
         `steil ${AN.ankerStabkraft(30, steil).toFixed(1)} gegen `
         + `flach ${AN.ankerStabkraft(30, flach).toFixed(1)} kN`);
    wahr('… und der flache liegt nahe bei der Kraft selbst',
         AN.ankerStabkraft(30, flach) < 32);
    pruef('N = H / cos alpha', AN.ankerStabkraft(30, g345), 50, 1e-9, 'kN');
    wahr('Ohne Geometrie keine Stabkraft',
         AN.ankerStabkraft(30, null) === null);
    /*
     * UND DIE LAENGE GEHT IN DEN NACHWEIS. Ein Stab mit 4 m Hoehe und 8 m
     * Abstand ist 8.94 m lang - danach fragt die Knickkurve, nicht nach der
     * Hoehe.
     */
    const g2 = AN.ankerGeometrie(4, 8);
    pruef('Die Laenge entscheidet, nicht die Hoehe',
          AN.ankerNachweis('U12', -30, g2.L).zul,
          AN.ankerZulDruck('U12', g2.L), 1e-9, 'kN');

    /*
     * >>> DER ANKER GEHOERT DEM MASTEN. <<<
     *
     * Er steht an EINEM Masten, gehoert keinem Tragwerk und wandert beim
     * Nachfuehren der Liste mit - zugeordnet ueber die STELLE, nicht ueber
     * die Nummer. Sonst bekaeme nach dem Verschieben eines Jochs ein
     * fremder Mast den Anker, so wie es beim Profil schon einmal war.
     */
    {
      const CC2 = await import(J('core.constants.js'));
      const basis = { typ: 'J90', L: 20, xLage: 0, mastProfil: 'HEB 240',
                      mastH: 7.0, twId: 'T1' };
      const mitAnker = CC2.setzeMastAnker(basis, 'M2',
        { typ: 'U12', h: 4.0, a: 3.0, seite: 'vorn',
          befestigung: 'ankerplatte' });
      const masten = CC2.mastenVon(mitAnker);
      wahr('Der Anker steht am gemeinten Masten',
           masten.find((m) => m.id === 'M2')?.anker?.typ === 'U12');
      wahr('… und nur dort',
           masten.filter((m) => m.anker).length === 1);
      /*
       * VERSCHIEBT MAN DAS TRAGWERK, wandert der Anker mit seinem Masten -
       * er haengt an der Stelle, nicht an der Nummer.
       */
      const verschoben = CC2.mastenVon({ ...mitAnker, xLage: 5 });
      wahr('Nach dem Verschieben steht er immer noch an einem Masten',
           verschoben.filter((m) => m.anker).length === 1);
      /*
       * UND ER LAESST SICH WEGNEHMEN. Ein Anker ist ein Bauteil: entweder
       * er steht da, oder er steht nicht da.
       */
      const ohne = CC2.mastenVon(CC2.setzeMastAnker(mitAnker, 'M2', null));
      wahr('Weggenommen ist er weg',
           ohne.every((m) => m.anker === undefined));
      wahr('Ein unbekannter Mast aendert nichts',
           CC2.setzeMastAnker(basis, 'M9', { typ: 'U12' }) === basis);
      wahr('Die eigenen Felder des Masten sind benannt',
           CC2.MAST_EIGEN.includes('anker'));

      /*
       * >>> WOMIT EIN NEUER ANKER ANFAENGT. <<<
       *
       * Weisung vom 11. September: «als voreinstellwerte die anker sind im
       * abstand von 4.50 m (fundamente). der anker hat einen winkel von ca
       * 60°.»
       *
       * Der Winkel zaehlt gegen die WAAGRECHTE. Bei 60 Grad ist der Stab
       * genau doppelt so lang wie der Abstand - das ist die Probe, die
       * beide Angaben zugleich prueft.
       */
      const aq60 = APP_QUELLE();
      const zahl = (n) => {
        const m2 = aq60.match(new RegExp(`const ${n} = ([0-9.]+);`));
        return m2 ? Number(m2[1]) : NaN;
      };
      pruef('Der Fundamentabstand ist voreingestellt',
            zahl('ANKER_ABSTAND_VOR'), 4.5, 1e-12, 'm');
      pruef('Und die Neigung', zahl('ANKER_WINKEL_VOR'), 60, 1e-12, '°');
      {
        const a0 = zahl('ANKER_ABSTAND_VOR'), g0 = zahl('ANKER_WINKEL_VOR');
        const h0 = Math.round(a0 * Math.tan((g0 * Math.PI) / 180) * 100) / 100;
        const g1 = AN.ankerGeometrie(h0, a0);
        pruef('Daraus folgt die Anschlusshoehe', h0, 7.79, 0.005, 'm');
        pruef('… und die Stablaenge ist das Doppelte des Abstands',
              g1.L, 2 * a0, 0.005, 'm');
        pruef('… mit der Neigung, die dastand', g1.alpha, g0, 0.05, '°');
        /*
         * SIE LIEGT IM SORTIMENT - und zwar nicht am Rand. In der Kappung
         * unter sechs Metern sagt die Kurve nichts mehr aus; dort steht
         * der Querschnitt, nicht das Knicken.
         */
        const t12 = AN.getAnkerTyp('U12');
        wahr('Die Stablaenge liegt im Sortiment',
             g1.L <= t12.laengeMax + 1e-9 && g1.L > t12.druck.kappungAb,
             `${g1.L.toFixed(2)} m in 5.95 bis ${t12.laengeMax} m`);
        pruef('Der U12 traegt dort 60 kN Druck',
              AN.ankerZulDruck('U12', g1.L), 60, 0.5, 'kN');
      }
      /*
       * DER SCHIEBER FUER DIE NEIGUNG SPEICHERT NICHTS. Sie folgt aus
       * Hoehe und Abstand; zwei Speicherorte fuer dieselbe Groesse laufen
       * auseinander. Deshalb steht `ankerWinkel` NICHT in ANKERFELDER.
       */
      wahr('Der Winkel wird nicht gespeichert',
           /const ANKERFELDER = \{[^}]*\}/.test(aq60)
           && !/ankerWinkel: '/.test(aq60));
      wahr('… sondern verstellt die Hoehe',
           /if \(key === 'ankerWinkel'\)/.test(aq60));
      /*
       * >>> UND DIE EBENE FAENGT DORT AN, WO SIE WIRKT. <<<
       *
       * Ein schraeger Stab haelt nur die Ebene, in der er liegt. Am
       * Tragjoch kippt die Umlenkkraft den Masten quer zum Gleis, am
       * Abfangjoch steht die grosse Kraft laengs. Ohne diese
       * Unterscheidung setzt man am Abfangjoch einen Anker und sieht eine
       * Null - genau das ist am 10. September passiert.
       *
       * Im Browser gemessen, A240 mit Leiter bei x = 10.00 und den
       * Voreinstellwerten 4.50 m / 60 Grad: eta M3 von 2.205 auf 0.234,
       * der Anker selbst bei 0.509.
       */
      // Seit dem 17. September ueberall laengs (Weisung: «beim anker /
      // druckstütze als voreingabewert längs einstellen»).
      wahr('Die voreingestellte Ebene ist laengs',
           /const ankerRichtungVor = \(\) => 'y'/.test(aq60)
           && /richtung: 'y', seite: 'plus', befestigung: 'ankerplatte'/.test(aq60));
      wahr('… und sie wird beim Setzen angewandt',
           /richtung: ankerRichtungVor\(werte\)/.test(aq60));
    }

    /*
     * ====== DER MAST IST AM ANKERPUNKT GEHALTEN (VARIANTE 3) ===========
     *
     * Weisung vom 10. September, auf Nachfrage: «nimm variante 3 und die
     * charakteristische kraft.» Also ein Zweifeldsystem - unten die
     * Einspannung, auf der Ankerhoehe eine unverschiebliche Stuetze,
     * darueber ein Kragarm.
     *
     * Geprueft wird gegen die Loesungen, die im Buch stehen: der propped
     * cantilever ist einfach statisch unbestimmt und hat geschlossene
     * Formeln. Eine Rechnung gegen sich selbst waere keine Kontrolle.
     */
    {
      const MA = await import(J('core.mast.js'));
      /** Ein Lastbild von Hand - nur das, was `ankerHaltekraft` liest. */
      const g = (o2) => ({ zKopf: 10, wQuer: 0, lasten: [], ...o2 });

      /*
       * KRAFT AM KOPF, HALTERUNG AM KOPF: die Stuetze nimmt die ganze
       * Kraft. Alles andere waere kein Gleichgewicht.
       */
      const kopf = g({ lasten: [{ z: 10, Fx: 10, Fz: 0, Mq: 0, ex: 0 }] });
      pruef('Halterung am Kopf nimmt die ganze Kraft',
            MA.ankerHaltekraft(kopf, 10), -10, 1e-9, 'kN');
      /*
       * KRAFT AM KOPF, HALTERUNG AUF HALBER HOEHE: X = -F·(3L-a)/(2a).
       * Mit L = 10, a = 5 sind das -2.5·F - die Stuetze zieht MEHR als die
       * Last, weil der obere Teil auskragt. Der Fuss bekommt den Rest.
       */
      pruef('Halterung auf halber Hoehe zieht ueber',
            MA.ankerHaltekraft(kopf, 5), -10 * (3 * 10 - 5) / (2 * 5),
            1e-9, 'kN');
      /*
       * GLEICHLAST UEBER DIE HOEHE, HALTERUNG AM KOPF: X = -3qL/8, die
       * bekannte Loesung des propped cantilever.
       */
      const gleich = g({ wQuer: 2 });
      pruef('Gleichlast, Halterung am Kopf: 3qL/8',
            MA.ankerHaltekraft(gleich, 10), -(3 * 2 * 10) / 8, 1e-9, 'kN');
      /*
       * KEINE LAST, KEINE HALTEKRAFT. Und ohne brauchbare Hoehe kein Wert.
       */
      pruef('Ohne Last haelt der Anker nichts',
            MA.ankerHaltekraft(g({}), 5), 0, 1e-12, 'kN');
      wahr('Ohne Hoehe gibt es keine Haltekraft',
           MA.ankerHaltekraft(kopf, 0) === null
           && MA.ankerHaltekraft(null, 5) === null);
      /*
       * EIN MOMENT AM KOPF wirkt wie eine Kraft mit Hebel - dieselbe
       * Biegelinie, dieselbe Halterung. M am Kopf, Halterung am Kopf:
       * X = -3M/(2L).
       */
      const mom = g({ lasten: [{ z: 10, Fx: 0, Fz: 0, Myy: 20, ex: 0 }] });
      pruef('Ein Moment am Kopf: 3M/(2L)',
            MA.ankerHaltekraft(mom, 10), -(3 * 20) / (2 * 10), 1e-9, 'kN');
      /*
       * UND DIE AUSMITTE EINER VERTIKALLAST ZAEHLT MIT - dieselben zwei
       * Quellen, die `mastSchnitt` addiert.
       */
      const ausmitte = g({ lasten: [{ z: 10, Fx: 0, Fz: 20, Mq: 0, ex: 1 }] });
      pruef('Vertikallast ueber die Ausladung wirkt wie ein Moment',
            MA.ankerHaltekraft(ausmitte, 10),
            MA.ankerHaltekraft(mom, 10), 1e-9, 'kN');

      /*
       * >>> AUS DER HALTEKRAFT WIRD DIE STABKRAFT. <<<
       *
       * Der Stab laeuft schraeg; nur sein waagrechter Anteil haelt. Steht
       * das Fundament in +x und drueckt die Stuetze den Masten in −x
       * zurueck, ist der Stab auf DRUCK - er stemmt sich dagegen.
       */
      const geo = AN.ankerGeometrie(4, 3);      // L = 5, cos = 0.6
      const kD = MA.ankerStabkraftAus(-30, geo, 'plus');
      pruef('N = X / cos alpha', kD.N, -50, 1e-9, 'kN');
      wahr('… und der Stab steht auf Druck', kD.N < 0);
      /*
       * AUF DER ANDEREN SEITE DREHT ES SICH UM: dieselbe Haltekraft, ein
       * Fundament in −x - und der Stab zieht.
       */
      const kZ = MA.ankerStabkraftAus(-30, geo, 'minus');
      pruef('Auf der Gegenseite dreht sich das Vorzeichen', kZ.N, 50,
            1e-9, 'kN');
      /*
       * DIE LOTRECHTE KOMPONENTE BELASTET DEN MASTEN. Ein Zuganker zieht
       * ihn nach unten, eine Druckstuetze hebt ihn - beides steht
       * unterhalb des Anschlusspunktes in der Normalkraft.
       */
      pruef('Zug zieht den Masten nach unten', kZ.Fz, 50 * geo.sin,
            1e-9, 'kN');
      wahr('… und Druck hebt ihn', kD.Fz < 0);
      wahr('Ohne Geometrie keine Stabkraft',
           MA.ankerStabkraftAus(-30, null) === null);

      /*
       * >>> EIN SCHRAEGER STAB HAELT NUR SEINE EIGENE EBENE. <<<
       *
       * Am TRAGJOCH kippt die Umlenkkraft den Masten quer zum Gleis - dort
       * gehoert der Anker in die Jochachse. Am ABFANGJOCH steht die grosse
       * Kraft LAENGS, und ein Anker quer dazu haelt davon nichts.
       *
       * Im Browser gemessen, A240 mit einem Leiter bei x = 10.00: der
       * Endmast stand bei eta 2.205, und ein Anker in der Jochachse aenderte
       * daran NICHTS - seine Kraft war null. In Gleisrichtung gesetzt fiel
       * eta auf 0.593.
       */
      const nurY = { zKopf: 10, wQuer: 0, wLaengs: 0,
                     lasten: [{ z: 10, Fx: 0, Fy: 12, Fz: 0,
                                Mq: 0, Ml: 0, ex: 0, ey: 0 }] };
      pruef('Eine Kraft laengs haelt der Anker laengs',
            MA.ankerHaltekraft(nurY, 10, 'y'), -12, 1e-9, 'kN');
      pruef('… und der Anker quer haelt davon nichts',
            MA.ankerHaltekraft(nurY, 10, 'x'), 0, 1e-12, 'kN');
      const nurX = { zKopf: 10, wQuer: 0, wLaengs: 0,
                     lasten: [{ z: 10, Fx: 12, Fy: 0, Fz: 0,
                                Mq: 0, Ml: 0, ex: 0, ey: 0 }] };
      pruef('Umgekehrt genauso',
            MA.ankerHaltekraft(nurX, 10, 'x'), -12, 1e-9, 'kN');
      pruef('… und nichts in der anderen Ebene',
            MA.ankerHaltekraft(nurX, 10, 'y'), 0, 1e-12, 'kN');
      /*
       * AUCH DER WIND AUF DEN MASTEN gehoert in seine Ebene: quer der eine,
       * laengs der andere.
       */
      const wind = { zKopf: 10, wQuer: 2, wLaengs: 1, lasten: [] };
      pruef('Der Wind quer wirkt in der Jochachse',
            MA.ankerHaltekraft(wind, 10, 'x'), -(3 * 2 * 10) / 8, 1e-9, 'kN');
      pruef('… und der Wind laengs in Gleisrichtung',
            MA.ankerHaltekraft(wind, 10, 'y'), -(3 * 1 * 10) / 8, 1e-9, 'kN');
      /*
       * UND DIE STABKRAFT WIRKT DORT, WO DER STAB LIEGT. Eine Kraft in y
       * hat am Masten nichts in x verloren - sonst entlastete ein Anker die
       * Ebene, in der er gar nicht steht.
       */
      const kY = MA.ankerStabkraftAus(-30, geo, 'plus', 'y');
      wahr('Der laengs liegende Stab wirkt in y',
           kY.Fy === -30 && kY.Fx === 0);
      const kX = MA.ankerStabkraftAus(-30, geo, 'plus', 'x');
      wahr('… der quer liegende in x',
           kX.Fx === -30 && kX.Fy === 0);
      wahr('Die lotrechte Komponente gilt in beiden Ebenen',
           Math.abs(kX.Fz - kY.Fz) < 1e-12);

      /*
       * >>> UND DIE GANZE KETTE. <<<
       *
       * Vom Anker am Masten der Liste ueber den Rechensatz, die
       * Drehfedern und die Mastlasten bis zur Kraft im Stab. Jedes Glied
       * ist einzeln geprueft; diese Kontrolle prueft, dass sie
       * zusammenhaengen - genau daran hat es beim ersten Anlauf gefehlt.
       */
      const CC3 = await import(J('core.constants.js'));
      const AU3 = await import(J('core.auflager.js'));
      const w3 = {
        typ: 'J90', L: 20, xLage: 0, twId: 'T1',
        mastVorhanden: true, endbedingung: 'mast',
        mastProfil: 'HEB 240', mastH: 7.5, mastSteg: 'quer',
        masten: [
          { id: 'M1', x: 0, profil: 'HEB 240' },
          { id: 'M2', x: 20, profil: 'HEB 240',
            anker: { typ: 'U12', h: 4, a: 3, seite: 'plus',
                     befestigung: 'ankerplatte' } },
        ],
      };
      const rs3 = CC3.rechensatz(w3);
      wahr('Der Rechensatz traegt den Anker am richtigen Ende',
           rs3.mastAnkerA === null && rs3.mastAnkerB?.typ === 'U12');
      const f3 = AU3.drehfedern(rs3);
      wahr('Die Mastangaben tragen ihn weiter',
           f3.mastB?.anker?.typ === 'U12' && !f3.mastA?.anker);
      const m3 = {
        L: 20, federn: f3, RA: 20, RB: 20, MA: 5, MB: 5,
        wd: 0, H: [], T: [], N: [{ x: 10, w: 20 }],
        beiwerte: { G: 1 }, stahl: { fy: 235 }, gammaM0: 1,
        mastLast: { A: { xd: 0, yd: 0 }, B: { xd: 0, yd: 0 } },
        anbauMastFlach: [],
      };
      const sB = MA.mastSchnitt(m3, 'B');
      wahr('Am Ende B steht die Ankerkraft', !!sB.ankerkraft);
      wahr('Am Ende A steht keine',
           MA.mastSchnitt(m3, 'A').ankerkraft === null);
      pruef('Die Stablaenge kommt aus der Geometrie',
            sB.ankerkraft.geo.L, 5, 1e-9, 'm');
      /*
       * DER ANKER ENTLASTET DEN MASTFUSS. Genau dafuer steht er da: ohne
       * ihn traegt die Einspannung das ganze Moment, mit ihm einen Teil
       * davon. Verglichen wird an derselben Stelle, im selben Lastbild.
       */
      const ohneAnker = MA.mastSchnitt(
        { ...m3, federn: { ...f3, mastB: { ...f3.mastB, anker: null } } },
        'B');
      const MqFuss = (x) => Math.abs(x.stationen[0].Myy);
      wahr('Der Anker entlastet den Mastfuss',
           MqFuss(sB) < MqFuss(ohneAnker),
           `${MqFuss(sB).toFixed(1)} statt ${MqFuss(ohneAnker).toFixed(1)} kNm`);
      /*
       * UND ER STEHT AN SEINER STELLE IM VERLAUF: unterhalb des
       * Anschlusspunktes wirkt er, oberhalb nicht.
       */
      const beiZ = (x, z) => x.stationen.reduce(
        (a2, b2) => (Math.abs(b2.z - z) < Math.abs(a2.z - z) ? b2 : a2));
      wahr('Ueber dem Anker aendert er nichts',
           Math.abs(beiZ(sB, 6).Myy - beiZ(ohneAnker, 6).Myy) < 1e-9);
      wahr('… darunter sehr wohl',
           Math.abs(beiZ(sB, 2).Myy - beiZ(ohneAnker, 2).Myy) > 1e-6);
    }
  }

  /*
   * ====== WAS DAS ABFANGJOCH AN DIE MASTEN ABGIBT ======================
   *
   * Weisung vom 9. September: «fange danach noch mit dem implementieren der
   * Masten beim Abfangjoch an.»
   *
   * Der Mastnachweis las bisher die Reaktionen des TRAGJOCH-Ersatzbalkens;
   * am Abfangjoch beschreiben sie ein anderes Tragwerk. `abfangAuswertung`
   * gibt jetzt seine eigenen Auflagerkraefte aus - je Ende, je Fall, mit den
   * Anteilen, aus denen sie kommen.
   */
  if (AJ.abfangDbDa()) {
    const AB7 = await import(J('core.abfangjoch.js'));
    const leiter7 = (id, x, verlauf, bauteil) => ({
      id, vorlage: 'hs-fahrdraht', name: id, x, ort: 'joch', aktiv: true,
      anbindung: 'mitte', verlauf, module: [{ bauteil, anzahl: 1, z: 0 }],
    });
    const rechne7 = (teile) => AB7.abfangAuswertung({
      typ: 'A240', jt: 12.5, gk: 0.42, wk: 0.31, sk: 0.24, anbauteile: teile,
      gammaG: 1.3, gammaQ: 1.3, psi0: 0.5, fyd: 22.38, ek: 'EK2', L_FL: 0 });

    /*
     * >>> ZWEI GEGENLAEUFIGE LEITER SIND EIN KRAEFTEPAAR. <<<
     *
     * Einer zieht nach vorn, einer nach hinten - in der Summe null. Die
     * beiden Masten bekommen dieselbe Kraft, aber in entgegengesetzter
     * Richtung: das Joch dreht sich um die lotrechte Achse, und genau das
     * muessen die Masten halten.
     */
    const paar = rechne7([
      leiter7('vorn', 4, 'vorn', 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107'),
      leiter7('hinten', 8, 'hinten', 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107')]);
    wahr('Das Abfangjoch weist seine Auflagerkraefte aus',
         !!paar.auflager?.A && !!paar.auflager?.B);
    pruef('Ein Kraeftepaar gibt zwei gleich grosse Kraefte',
          paar.auflager.A.Fy, -paar.auflager.B.Fy, 1e-9, 'kN');
    pruef('… und beide Enden tragen dasselbe Gewicht',
          paar.auflager.A.Fz, paar.auflager.B.Fz, 1e-9, 'kN');
    wahr('Beide Kraefte stehen nach unten',
         paar.auflager.A.Fz > 0 && paar.auflager.B.Fz > 0);

    /*
     * >>> GLEICHGEWICHT: WAS OBEN HINEINGEHT, KOMMT UNTEN HERAUS. <<<
     *
     * Die charakteristischen Anteile eines Falles muessen sich zur ganzen
     * Last summieren. Ein Leiter allein zieht 14.9 kN; A und B zusammen
     * halten sie, wie der Hebel es verlangt.
     */
    const einer = rechne7([
      leiter7('vorn', 3, 'vorn', 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107')]);
    const wind = (e) => einer.auflager[e].faelle.find((f) => f.key === 'wind+y');
    pruef('Ein Leiter, zwei Auflager: die Summe ist die Zugkraft',
          wind('A').anteile.Z + wind('B').anteile.Z, 14.9, 1e-6, 'kN');
    wahr('Der naehere Mast bekommt mehr',
         Math.abs(wind('A').anteile.Z) > Math.abs(wind('B').anteile.Z));
    /*
     * DAS EIGENGEWICHT DES JOCHS teilt sich zu gleichen Teilen: es ist eine
     * Gleichlast auf einem symmetrischen Traeger.
     */
    pruef('Das Jochgewicht traegt jedes Ende zur Haelfte',
          wind('A').anteile.G, wind('B').anteile.G, 1e-9, 'kN');
    pruef('… und zusammen sind es 0.42 kN/m auf 12.50 m',
          wind('A').anteile.G + wind('B').anteile.G, 0.42 * 12.5, 0.3, 'kN');

    /*
     * >>> JEDER FALL STEHT DA, UND EINER IST MASSGEBEND. <<<
     */
    // Seit dem 17. September der Wind in vier Richtungen: 4 + 4 + Havarie.
    wahr('Alle Faelle sind ausgewiesen, jeder mit Wind in beiden Richtungen',
         einer.auflager.A.faelle.length === 9
         && AB7.ABFANG_FAELLE.every((f) => einer.auflager.A.faelle.some((x) => x.fall === f.key)));
    {
      const w4 = einer.auflager.A.faelle.filter((f) => f.fall === 'wind');
      wahr('Wind leitend in ±y und ±x',
           w4.length === 4 && new Set(w4.map((f) => `${f.windY}${f.windX}`)).size === 4);
      // Seit dem 18. September je eine Richtung, nicht diagonal.
      wahr('… je eine Richtung, nie beide zugleich',
           w4.every((f) => (f.windY === 0) !== (f.windX === 0)));
      const plusY = w4.find((f) => f.windY > 0);
      const minusY = w4.find((f) => f.windY < 0);
      pruef('Der Gegenwind aendert nur den Windanteil',
            plusY.Fy - minusY.Fy, 2 * plusY.beiwerte.w * plusY.anteile.W, 1e-9, 'kN');
    }
    wahr('Der massgebende ist einer davon',
         einer.auflager.A.faelle.some((f) => f.key === einer.auflager.A.fall));
    /*
     * IM HAVARIEFALL FEHLT DER SCHNEE - die staendigen Lasten stehen
     * charakteristisch da, die veraenderlichen gar nicht.
     */
    const hav = einer.auflager.A.faelle.find((f) => f.key === 'havarie');
    pruef('Havarie: die staendige Last ohne Beiwert',
          hav.Fz, hav.anteile.G, 1e-9, 'kN');
    wahr('… und ohne Schneeanteil', hav.beiwerte.s === 0
         && hav.beiwerte.w === 0);

    /*
     * >>> DIE KRAFT IN JOCHACHSE WIRD JETZT GEFUEHRT. <<<
     *
     * Wind quer zum Gleis laeuft im liegenden Traeger als Normalkraft an
     * seine Enden. Verteilt wird sie nicht hier, sondern nach der
     * Kopfsteifigkeit der beiden Masten (`mastLasten`) - deshalb steht sie
     * als SUMME da.
     */
    wahr('Die Kraft in Jochachse steht als Summe da',
         Number.isFinite(paar.auflager.A.faelle[0].Fxges));
    /*
     * UND DER ANSCHLUSSPUNKT SITZT NEBEN DER MASTACHSE. Der vordere Gurt
     * ist in der Jochachse frei; die Kraft haengt am hinteren, und der
     * liegt um den halben Gurtabstand daneben. Genau daraus kommt die
     * Torsion, die die Weisung stehen laesst.
     */
    pruef('Der Anschluss sitzt um den halben Gurtabstand daneben',
          paar.auflager.ey, (paar.q.e / 100) / 2, 1e-12, 'm');
    /*
     * DIE CHARAKTERISTISCHE KOMBINATION STEHT DANEBEN - alle Anteile mit
     * Beiwert 1. Sie wird gebraucht, wo eine ZULAESSIGE Kraft
     * gegenuebersteht: beim Zuganker am Masten.
     */
    const wA = paar.auflager.A.faelle.find((f) => f.key === 'wind+y');
    // Weisung vom 18. September: Wind nie in x und y zugleich.
    wahr('Abfangjoch: kein Windfall traegt x und y zugleich',
         paar.auflager.A.faelle.every((f) => !(f.windX && f.windY) || f.key === f.fall),
         paar.auflager.A.faelle.map((f) => f.key).join(','));
    pruef('Charakteristisch: das Gewicht ohne Beiwert',
          wA.char.Fz, wA.anteile.G + wA.anteile.S, 1e-9, 'kN');
    wahr('… und kleiner als der Bemessungswert', wA.char.Fz < wA.Fz);
  }

  /*
   * ====== DIE DREI AUSWERTUNGSREITER DES ABFANGJOCHS ===================
   *
   * Weisung vom 10. September: «die reiter schnitt verläufe und auflager
   * beim abfangjoch fertig machen.»
   *
   * Sie zeigten die Auswertung des TRAGJOCH-Ersatzbalkens - vier
   * Winkelecken, zwei Blechebenen, Gruppenreaktionen. Am Abfangjoch sind
   * das andere Bauteile und eine andere Gliederung.
   */
  if (AJ.abfangDbDa()) {
    const CH = await import(J('render.charts.js'));
    const AB10 = await import(J('core.abfangjoch.js'));
    const rD = AB10.abfangAuswertung({
      typ: 'A240', jt: 12.5, gk: 0.42, wk: 0.31, sk: 0.24,
      anbauteile: [{ id: 'a', vorlage: 'hs-fahrdraht', name: 'L', x: 6,
                     ort: 'joch', aktiv: true, anbindung: 'mitte',
                     verlauf: 'vorn',
                     module: [{ bauteil: 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107',
                                anzahl: 1, z: -1.5, y: 0.8 }] }],
      gammaG: 1.3, gammaQ: 1.3, psi0: 0.5, fyd: 22.38, ek: 'EK2', L_FL: 40 });

    /*
     * >>> DIE VERLAEUFE ZEIGEN BEIDE EBENEN UND DIE TORSION. <<<
     *
     * Am Tragjoch stehen dort M_y, V_z, M_z, T_x eines Traegers mit vier
     * Winkelgurten. Hier sind es die zwei Ebenen des liegenden Traegers,
     * und daneben das, was im GURT ankommt - Kraeftepaar, lotrechte
     * Biegung, oertliche Biegung.
     */
    const dia = CH.abfangDiagramme(rD, 900);
    wahr('Die drei Diagramme stehen da',
         !!dia?.schnittgroessen && !!dia?.ebene && !!dia?.ausnutzung);
    wahr('Sie sind SVG und nennen das Abfangjoch',
         /^<figure/.test(dia.schnittgroessen)
         && /Abfangjoch/.test(dia.schnittgroessen));
    wahr('Die Torsion hat ihre eigene Kurve',
         /M Torsion/.test(dia.schnittgroessen));
    wahr('Das Kraeftepaar steht im Gurtdiagramm',
         /Kr..?ftepaar/.test(dia.ebene));
    wahr('Und die Ausnutzung nennt das Gurtprofil',
         dia.ausnutzung.includes(rD.q.gurt.name));
    wahr('Ohne Reihe gibt es kein Diagramm',
         CH.abfangDiagramme(null) === null
         && CH.abfangDiagramme({ reihe: [] }) === null);

    /*
     * >>> DIE DREI REITER GEHEN AN DIE RICHTIGE FUNKTION. <<<
     *
     * Geprueft am Quelltext, weil die Reiter im Browser haengen - die REGEL
     * dahinter laesst sich hier festhalten: liegt ein Abfangjoch vor, wird
     * seine eigene Auswertung gezeichnet, sonst die des Tragjochs.
     */
    {
      const aq59 = APP_QUELLE();
      const uq59 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
      wahr('Der Schnittreiter kennt das Abfangjoch',
           /if \(erg\.abfang\) ui\.zeichneAbfangSchnitt/.test(aq59));
      wahr('Der Auflagerreiter auch',
           /if \(erg\.abfang\?\.auflager\) ui\.zeichneAbfangAuflager/
             .test(aq59));
      wahr('Und die Verlaeufe nehmen abfangDiagramme',
           /abfangDiagramme\(erg\.abfang, 860\)/.test(aq59));
      wahr('Die beiden Zeichner sind ausgefuehrt',
           /export function zeichneAbfangSchnitt/.test(uq59)
           && /export function zeichneAbfangAuflager/.test(uq59));
      /*
       * DER MASSVARIANTENVERGLEICH DARF FEHLEN. Er stellt die
       * Hebelarm-Definitionen des Tragjochs gegenueber; am Abfangjoch gibt
       * es das nicht, und `vergleich.zeilen` brach die ganze Seite ab.
       */
      wahr('Der Verlaufsreiter haelt einen fehlenden Vergleich aus',
           /vergleich\?\.zeilen\?\.length/.test(uq59));
    }
  }

  /*
   * ====== DIE TORSION DES LIEGENDEN TRAEGERS ===========================
   *
   * Weisung vom 10. September: «die torsion des liegenden traegers noch
   * rechnen.»
   *
   * Der Traeger liegt waagrecht; alles, was NEBEN seiner Achse angreift,
   * verdreht ihn. Ein offener Traeger aus zwei Gurten traegt das als
   * WOELBKRAFTTORSION - die beiden Gurte biegen sich lotrecht gegenlaeufig.
   * Ein Torsionsmoment T ist damit dasselbe wie zwei entgegengesetzte
   * Kraefte ±T/e.
   */
  if (AJ.abfangDbDa()) {
    const AB9 = await import(J('core.abfangjoch.js'));
    const teilT = (id, x, y, z) => ({
      id, vorlage: 'hs-fahrdraht', name: id, x, ort: 'joch', aktiv: true,
      anbindung: 'mitte', verlauf: 'vorn',
      module: [{ bauteil: 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107',
                 anzahl: 1, z, y }] });
    const rechneT = (teile) => AB9.abfangAuswertung({
      typ: 'A240', jt: 12.5, gk: 0.42, wk: 0.31, sk: 0.24, anbauteile: teile,
      gammaG: 1.3, gammaQ: 1.3, psi0: 0.5, fyd: 22.38, ek: 'EK2',
      L_FL: 40 });

    /*
     * >>> DAS TORSIONSMOMENT EINES BAUTEILS. <<<
     *
     * Lotrechte Kraft mal seitlichem Versatz. Ein Drahtwerk ueber 40 m
     * Spannweite wiegt 0.8 kN; einen Meter neben der Achse sind das
     * 0.8 kNm.
     */
    const lwMitte = AB9.abfangAnbauLasten(teilT('a', 6, 0, -1.5),
      { ek: 'EK2', R: 0, spannweite: 40 });
    const lwSeite = AB9.abfangAnbauLasten(teilT('a', 6, 1.0, -1.5),
      { ek: 'EK2', R: 0, spannweite: 40 });
    pruef('In der Achse gibt es keine Torsion', lwMitte.TG, 0, 1e-12, 'kNm');
    pruef('Einen Meter daneben: F_z mal Hebel',
          lwSeite.TG, lwSeite.Gz * 1.0, 1e-9, 'kNm');
    /*
     * >>> DER LEITERZUG MACHT KEINE TORSION. <<<
     *
     * Er wird an der ANBINDUNG eingeleitet, nicht dort, wo der Draht
     * haengt. «Mitte Traeger» heisst genau das. Waere es anders, ergaebe
     * sich ein Torsionsmoment in der Groesse des Rahmenmoments - hier
     * 14.9 kN mal 1.5 m -, und kein Abfangjoch waere je nachweisbar.
     */
    wahr('Der Leiterzug steht nicht in der Torsion',
         Math.abs(lwSeite.Z) > 10 && Math.abs(lwSeite.TG) < 1.0);

    /*
     * >>> IM GURT KOMMT SIE AN. <<<
     *
     * Gemessen an A240 / 12.50 m, ein Drahtwerk bei x = 6.00 m:
     * ohne Versatz eta 0.499, einen Meter daneben 0.564. Das Moment im
     * massgebenden Gurt waechst von 9.01 auf 13.35 kNm.
     */
    const ohneV = rechneT([teilT('a', 6, 0, -1.5)]);
    const mitV = rechneT([teilT('a', 6, 1.0, -1.5)]);
    pruef('Ohne Versatz kein Zusatzmoment',
          ohneV.gurt.Mxx, 0, 1e-12, 'kNm');
    wahr('Mit Versatz waechst das Moment im Gurt',
         mitV.gurt.MgurtVert > ohneV.gurt.MgurtVert,
         `${mitV.gurt.MgurtVert.toFixed(2)} statt `
         + `${ohneV.gurt.MgurtVert.toFixed(2)} kNm`);
    pruef('… und zwar genau um das Torsionsmoment',
          mitV.gurt.MgurtVert,
          Math.abs(mitV.gurt.schnitt.Myy) / 2 + mitV.gurt.Mxx,
          1e-9, 'kNm');
    wahr('Die Ausnutzung folgt', mitV.gurt.eta > ohneV.gurt.eta);
    /*
     * DIE LOTRECHTE LAST AENDERT SICH DABEI NICHT - der Versatz verschiebt
     * sie nur seitlich. Waere M_vert mitgewachsen, waere die Torsion
     * doppelt gezaehlt.
     */
    pruef('Die lotrechte Biegung bleibt dieselbe',
          mitV.gurt.schnitt.Myy, ohneV.gurt.schnitt.Myy, 1e-9, 'kNm');

    /*
     * >>> UND AM AUFLAGER STEHT DAS KRAEFTEPAAR. <<<
     *
     * Von Hand: T = 0.8 kNm, e = 0.656 m -> Ersatzkraft 1.22 kN bei
     * x = 6.00. Der Balken (Stuetzweite 12.00, Kragarm 0.25) gibt am Ende A
     * 0.635 kN; mit gamma_G = 1.3 sind das 0.83 kN.
     */
    pruef('Das Kraeftepaar am Auflager',
          mitV.auflager.A.Ptors, 0.83, 0.02, 'kN');
    pruef('Ohne Versatz steht dort nichts',
          ohneV.auflager.A.Ptors, 0, 1e-12, 'kN');
    /*
     * IM MASTEN WIRD DARAUS EIN MOMENT LAENGS - das Kraeftepaar ueber den
     * Achsabstand der Gurte. Genau der Anteil, der bis zum 10. September
     * fehlte, und er fehlte auf der unsicheren Seite.
     */
    const MA9 = await import(J('core.mast.js'));
    const AU9 = await import(J('core.auflager.js'));
    const f9 = AU9.drehfedern({ endbedingung: 'mast', mastVorhanden: true,
      mastProfil: 'HEB 240', mastH: 7.5, mastSteg: 'jochachse' });
    const m9 = (aufl) => ({
      L: 12.5, federn: f9, RA: 0, RB: 0, MA: 0, MB: 0, wd: 0,
      H: [], T: [], N: [], beiwerte: { G: 1.3 }, stahl: { fy: 235 },
      gammaM0: 1, mastLast: { A: { xd: 0, yd: 0 }, B: { xd: 0, yd: 0 } },
      anbauMastFlach: [], abfangAuflager: aufl });
    const gTors = MA9.mastLasten(m9(mitV.auflager), 'A');
    /*
     * DIE TORSION DES JOCHS KOMMT ALS BIEGUNG UM DIE JOCHACHSE AN - und
     * die zaehlt negativ, wenn die Ebene "laengs" positiv zaehlte. Seit dem
     * 15. September fuehrt der Mastnachweis die globale Groesse `M_xx`;
     * das Mass ist dasselbe geblieben.
     */
    pruef('Der Mast bekommt das Moment um die Jochachse',
          -gTors.lasten[0].Mxx,
          mitV.auflager.A.Ptors * 2 * mitV.auflager.ey, 1e-9, 'kNm');
    pruef('Ohne Torsion bekommt er keines',
          MA9.mastLasten(m9(ohneV.auflager), 'A').lasten[0].Mxx,
          0, 1e-12, 'kNm');
  }

  /*
   * ====== DER MASTNACHWEIS AM ABFANGJOCH ===============================
   *
   * Weisung vom 10. September: «den mastnachweis beim abfangjoch fertig
   * machen.»
   *
   * Bis dahin las `mastLasten` die Reaktionen des TRAGJOCH-Ersatzbalkens -
   * am Abfangjoch die Zahlen eines anderen Tragwerks. Jetzt kommen sie aus
   * `abfangAuswertung`.
   */
  if (AJ.abfangDbDa()) {
    const AB8 = await import(J('core.abfangjoch.js'));
    const MA8 = await import(J('core.mast.js'));
    const AU8 = await import(J('core.auflager.js'));

    const federn8 = AU8.drehfedern({
      endbedingung: 'mast', mastVorhanden: true, mastProfil: 'HEB 240',
      mastH: 7.5, mastSteg: 'jochachse' });
    const modell8 = { L: 12.5, federn: federn8, RA: 99, RB: 99, MA: 99, MB: 99,
                      wd: 9, H: [], T: [], N: [{ x: 6, w: 99 }],
                      beiwerte: { G: 1.3 }, stahl: { fy: 235 }, gammaM0: 1.0,
                      mastLast: { A: { xd: 0, yd: 0 }, B: { xd: 0, yd: 0 } },
                      anbauMastFlach: [] };
    const leiter8 = (id, x, verlauf) => ({
      id, vorlage: 'hs-fahrdraht', name: id, x, ort: 'joch', aktiv: true,
      anbindung: 'mitte', verlauf,
      module: [{ bauteil: 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107',
                 anzahl: 1, z: 0 }] });
    const rechne8 = (teile) => AB8.abfangAuswertung({
      typ: 'A240', jt: 12.5, gk: 0.42, wk: 0.31, sk: 0.24, anbauteile: teile,
      gammaG: 1.3, gammaQ: 1.3, psi0: 0.5, fyd: 22.38, ek: 'EK2', L_FL: 0 });

    /*
     * >>> DIE JOCHKRAFT KOMMT AUS DEM ABFANGJOCH, NICHT AUS DEM TRAGJOCH. <<<
     *
     * Das Modell traegt absichtlich unsinnige Tragjochwerte (RA = 99 kN,
     * MA = 99 kNm). Taeuchten sie im Ergebnis auf, laese `mastLasten` noch
     * den Ersatzbalken.
     */
    const abS = rechne8([]);
    const mAb = { ...modell8, abfangAuflager: abS.auflager };
    const gA = MA8.mastLasten(mAb, 'A');
    wahr('Die Jochkraft kommt aus dem Abfangjoch',
         gA.quelle === 'abfangjoch');
    pruef('… und traegt seine Auflagerkraft',
          gA.lasten[0].Fz, abS.auflager.A.Fz, 1e-9, 'kN');
    wahr('Kein Wert aus dem Tragjoch-Ersatzbalken',
         Math.abs(gA.lasten[0].Fz - 99) > 1
         && gA.lasten[0].Myy === 0 && gA.lasten[0].Mxx === 0);
    wahr('Ohne Abfangjoch bleibt es beim Tragjoch',
         MA8.mastLasten(modell8, 'A').quelle === 'tragjoch');

    /*
     * >>> AM ANSCHLUSS GEHT KEIN MOMENT UEBER. <<<
     *
     * Die Links des Abfangjochs haben alle Momentengrade frei, und die
     * Drehung um z ist bewusst geloest - der vordere Gurt ist in der
     * Jochachse frei. Was bleibt, ist die Torsion aus der Exzentrizitaet:
     * die Kraft in der Jochachse haengt am HINTEREN Gurt, um den halben
     * Gurtabstand neben der Mastachse.
     */
    pruef('Der Anschluss sitzt neben der Mastachse',
          Math.abs(gA.lasten[0].ey), abS.auflager.ey, 1e-12, 'm');
    wahr('… und zwar hinten', gA.lasten[0].ey < 0);

    /*
     * >>> SYMMETRISCH BELASTET SIND BEIDE MASTEN GLEICH. <<<
     *
     * Ohne Anbauteile traegt das Joch nur sich selbst; die beiden Enden
     * bekommen dasselbe. Ein Unterschied waere ein Fehler im Lastbild.
     */
    const nwA = MA8.mastNachweis(mAb, 'A', {});
    const nwB = MA8.mastNachweis(mAb, 'B', {});
    pruef('Ohne Anbauteile tragen beide Masten dasselbe',
          nwA.eta, nwB.eta, 1e-9, '-');

    /*
     * >>> UND EIN LEITER NAHE AM ENDE BELASTET DIESES ENDE. <<<
     *
     * Gemessen im Browser an A240 / 12.50 m mit einem Leiter bei x = 10.00:
     * F_y 7.61 kN am naeheren Mast gegen 19.72 kN am ferneren - und der
     * Nachweis folgt: eta 0.982 gegen 2.205. Das ist der Grund, warum ein
     * Abfangjoch den Endmasten sprengen kann, waehrend das Joch selbst
     * haelt.
     */
    const einseitig = rechne8([leiter8('vorn', 10, 'vorn')]);
    const mE = { ...modell8, abfangAuflager: einseitig.auflager };
    wahr('Der Leiter bei x = 10.00 belastet das Ende B staerker',
         Math.abs(einseitig.auflager.B.Fy)
         > 2 * Math.abs(einseitig.auflager.A.Fy),
         `${einseitig.auflager.B.Fy.toFixed(2)} gegen `
         + `${einseitig.auflager.A.Fy.toFixed(2)} kN`);
    wahr('… und der Mastnachweis folgt',
         MA8.mastNachweis(mE, 'B', {}).eta
         > MA8.mastNachweis(mE, 'A', {}).eta);
    /*
     * DIE KRAFT IN GLEISRICHTUNG BIEGT DEN MASTEN LAENGS, nicht quer. Sie
     * steht am Kopf und wirkt ueber die volle Anschlusshoehe - das ist die
     * Beanspruchung, fuer die das Abfangjoch dasteht.
     */
    const stB = MA8.mastSchnitt(mE, 'B').stationen[0];
    pruef('Sie erzeugt das Moment laengs',
          Math.abs(stB.Mxx),
          Math.abs(einseitig.auflager.B.Fy) * 7.5, 0.6, 'kNm');
    wahr('… und quer bleibt es klein', Math.abs(stB.Myy) < 1e-9);

    /*
     * >>> DIE KRAFT IN JOCHACHSE WIRD NACH KOPFSTEIFIGKEIT VERTEILT. <<<
     *
     * Sie kommt als SUMME aus dem Abfangjoch - der liegende Traeger leitet
     * sie als Normalkraft an seine Enden -, und wie sie sich aufteilt,
     * entscheidet die Steifigkeit der beiden Mastkoepfe. Bei gleichen
     * Masten ist das die Haelfte.
     */
    const mFx = { ...modell8,
      abfangAuflager: { ...abS.auflager,
        A: { ...abS.auflager.A, Fxges: 10 },
        B: { ...abS.auflager.B, Fxges: 10 } } };
    pruef('Gleiche Masten teilen sich die Kraft in Jochachse',
          MA8.mastLasten(mFx, 'A').lasten[0].Fx, 5, 1e-9, 'kN');
    /*
     * UND SIE ERZEUGT DIE TORSION - ueber die Exzentrizitaet des
     * Anschlusses. Genau der Anteil, den die Weisung vom 5. September
     * stehen laesst.
     */
    const stFx = MA8.mastSchnitt(mFx, 'A').stationen[0];
    pruef('Die Torsion kommt aus der Exzentrizitaet',
          Math.abs(stFx.Mzz), 5 * abS.auflager.ey, 1e-9, 'kNm');
  }

  /*
   * ====== DIE REGLIERTEMPERATUR HAENGT AN DER KOMBINATION ==============
   *
   * Weisung vom 9. September: «Die temperatur ist an die kombinationen
   * gekoppelt. Wind leiteinwirkung -> +5° Schnee leiteinwirkung -5° und
   * Havariefall (ohne veraenderliche einwirkungen) -> -20° dabei sollte ein
   * leiter als bruch bestimmt werden koennen optional um den massgebenden
   * fall zu bestimmen fuer den nachweis.»
   */
  if (AJ.abfangDbDa()) {
    const AB6 = await import(J('core.abfangjoch.js'));
    wahr('Drei Faelle, jeder mit seiner Temperatur',
         AB6.ABFANG_FAELLE.map((f) => `${f.key}:${f.tempFall}`).join(',')
         === 'wind:tragsicherheit,schnee:schnee,havarie:havarie');
    const FLx = await import(J('data.fl.js'));
    pruef('Wind leitend rechnet mit +5 °C',
          FLx.reglierTemperatur('tragsicherheit'), 5, 1e-9, '°C');
    pruef('Schnee leitend mit −5 °C',
          FLx.reglierTemperatur('schnee'), -5, 1e-9, '°C');
    pruef('Havarie mit −20 °C',
          FLx.reglierTemperatur('havarie'), -20, 1e-9, '°C');

    const leiter = (id, x, verlauf, bruch = false) => ({
      id, vorlage: 'hs-fahrdraht', name: `Leiter ${verlauf}`, x, ort: 'joch',
      aktiv: true, anbindung: 'mitte', verlauf, bruch,
      module: [{ bauteil: 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107', anzahl: 1, z: 0 }],
    });
    const rechne = (teile) => AB6.abfangAuswertung({
      typ: 'A240', jt: 12.5, gk: 0.42, wk: 0.31, sk: 0.24, anbauteile: teile,
      gammaG: 1.3, gammaQ: 1.3, psi0: 0.5, fyd: 22.38, ek: 'EK2', L_FL: 0 });

    /*
     * DER BRUCH WIRKT NUR IM HAVARIEFALL - dort faellt die Zugkraft weg,
     * in den beiden anderen zieht der Leiter weiter.
     */
    const zwei = [leiter('a', 4, 'vorn'), leiter('b', 8, 'hinten')];
    const mitBruch = [leiter('a', 4, 'vorn'), leiter('b', 8, 'hinten', true)];
    const rOhne = rechne(zwei), rMit = rechne(mitBruch);
    const zug = (r, k) => r.faelle.find((f) => f.key === k).leiterzug;
    /*
     * >>> IM HAVARIEFALL ZIEHEN BEIDE - UND ZWAR KALT. <<<
     *
     * Seit die Reglagetabelle scharf ist, stehen die drei Faelle auf drei
     * Zugkraeften. Das Drahtwerk N-FL StCu 50 / Cu 107 traegt bei -20 °C
     * 8.0 (Ts) + 8.5 (Fd) = 16.5 kN, bei +5 °C dagegen 6.4 + 8.5 = 14.9.
     * Zwei Leiter geben 33.0 gegen 29.8 - der Havariefall ist damit NICHT
     * mehr der kleinste.
     */
    pruef('Im Havariefall ziehen beide kalt', zug(rOhne, 'havarie'),
          33.0, 1e-9, 'kN');
    pruef('… bei Wind dagegen bei +5 Grad', zug(rOhne, 'wind'),
          29.8, 1e-9, 'kN');
    /*
     * BEIM SCHNEE KOMMT DIE ZUSATZLAST DAZU: Spalte «-5 °C +Z» mit
     * 0.007 kN/m, das Tragseil zieht dort 8.0 statt 7.0 kN. Damit steht der
     * Schneefall beim N-FL auf demselben Zug wie der Havariefall - der
     * Unterschied zwischen beiden liegt allein in den Beiwerten.
     */
    pruef('… und bei Schnee mit Zusatzlast', zug(rOhne, 'schnee'),
          2 * (8.0 + 8.5), 1e-9, 'kN');
    wahr('Kalt zieht das Drahtwerk staerker als bei Wind',
         zug(rOhne, 'havarie') > zug(rOhne, 'wind')
         && zug(rOhne, 'schnee') > zug(rOhne, 'wind'));
    pruef('Mit Bruch nur noch einer', zug(rMit, 'havarie'),
          zug(rOhne, 'havarie') / 2, 1e-9, 'kN');
    wahr('… und Wind und Schnee bleiben unberuehrt',
         zug(rMit, 'wind') === zug(rOhne, 'wind')
         && zug(rMit, 'schnee') === zug(rOhne, 'schnee'));
    wahr('Der gebrochene Leiter steht mit Namen da',
         rMit.faelle.find((f) => f.key === 'havarie').gebrochen.length === 1);
    wahr('Ohne Bruchangabe bricht keiner',
         rOhne.faelle.every((f) => f.gebrochen.length === 0));

    /*
     * DAS ERGEBNIS NENNT DEN MASSGEBENDEN FALL - «eta 0.72» sagt sonst
     * nicht, ob Wind, Schnee oder ein Bruch dahintersteht.
     */
    wahr('Das Ergebnis nennt den massgebenden Fall',
         AB6.ABFANG_FAELLE.some((f) => f.key === rOhne.fall), rOhne.fall);
    /*
     * UND KEIN FALL STEHT MEHR OHNE TABELLE DA. Weisung vom 9. September:
     * «tabelle scharf stellen.» Waere sie es nicht, rechnete der kalte Fall
     * mit dem Wert von +5 °C - und stuende zu guenstig da.
     */
    wahr('Kein Fall rechnet mehr ohne Tabelle',
         rOhne.faelle.every((f) => f.ohneTabelle === false));

    /*
     * DER HAVARIEFALL RECHNET OHNE VERAENDERLICHE EINWIRKUNGEN - dafuer mit
     * der groessten Zugkraft und ohne Teilsicherheitsbeiwert auf den
     * staendigen Lasten. Ob er massgebend wird, entscheidet sich am
     * einzelnen Tragwerk; der Bruch kann ihn dorthin bringen.
     */
    const nurHav = AB6.ABFANG_FAELLE.find((f) => f.key === 'havarie');
    wahr('Der Havariefall hat keine Leiteinwirkung', nurHav.leit === null);
    wahr('… und nennt seine Beiwerte im Hinweis',
         /veränderlich/i.test(nurHav.hinweis) && /−20/.test(nurHav.hinweis));
  }

  /*
   * ====== ANBAUTEILE LIESSEN SICH NICHT MEHR SETZEN ====================
   *
   * Weisung vom 9. September: «anbauteile lassen sich nicht zuweisen ueber
   * den button im 3d fenster und auch nicht ueber drag and drop per kachel.»
   *
   * >>> DER BEFUND. <<<
   *
   * Die Blattszene HEBT jedes Tragwerk um seine Anschlusshoehe an, seit der
   * Mastfuss der Referenzpunkt ist (Weisung vom 8. September). Auf dem Blatt
   * liegt die Jochachse damit bei z = H, im Tragwerk bei z = 0. `stelleAus`
   * fing weiter um 0 - also 7.50 m UNTER dem Joch. Im Browser gemessen: ein
   * Klick auf die Jochachse gab «Dort ist x = 23.69 m, z = 6.99 m -- auf das
   * Joch oder einen Masten klicken», ein Klick in die leere Luft darunter
   * (z = 0.00) oeffnete das Menue.
   *
   * Fuer x stand die Umrechnung laengst da (`blattNachLokal`), fuer z nicht.
   * Geprueft wird der Quelltext, weil die Geste im Browser haengt - die
   * REGEL dahinter laesst sich hier festhalten: EINE Hebung, und der
   * Fangbereich rechnet mit ihr.
   */
  {
    const aq58 = APP_QUELLE();
    wahr('Die Hebung steht an EINER Stelle',
         (aq58.match(/const hebungVon = /g) ?? []).length === 1);
    wahr('Die Blattszene hebt damit an', aq58.includes('const dz = hebungVon(t)'));
    wahr('Und der Fangbereich rechnet sie heraus',
         /const zl = w\.z - (app\.)?hebungVon\(t\)/.test(aq58));
    /*
     * KEIN ROHES w.z MEHR IM FANGBEREICH. Genau das war der Fehler; eine
     * Kontrolle auf das Vorhandensein von `zl` allein wuerde ihn nicht
     * bemerken, wenn daneben das alte `w.z` stehen bliebe.
     */
    const fang = aq58.slice(aq58.indexOf('function stelleAus('),
                            aq58.indexOf('function stelleGewaehlt('));
    wahr('Der Fangbereich vergleicht nicht mehr gegen die Blatthoehe',
         !/Math\.abs\(w\.z\)/.test(fang) && !/w\.z \+ H/.test(fang));
    wahr('… und der Mast wird auf derselben Hoehe gefangen',
         // seit dem 19. September ueber `grenze` (am Einzelmast bis zum Kopf)
         fang.includes('zl + H') && fang.includes(': oben - H - (h / 2)')
         && fang.includes('zl < grenze'));
    /*
     * BEIDE WEGE GEHEN DURCH DIESELBE FUNKTION - der Knopf im Modellfenster
     * und das Ablegen per Kachel. Waeren es zwei, waere einer davon beim
     * naechsten Mal wieder falsch.
     */
    wahr('Das Ablegen fragt dieselbe Stelle wie der Klick',
         /v\.addEventListener\('drop'[\s\S]{0,900}?stelleAus\((app, )?w\)/.test(aq58));
  }

  /*
   * ====== EINE KACHEL JE VORLAGE =======================================
   *
   * Weisung vom 9. September: «Die kacheln sind teilweise mehrfach
   * enthalten, die ich mal definiert und gespeichert habe.»
   */
  {
    const AN = await import(J('data.anbauteile.js'));
    const v = (name, bauteil, z = 0) => ({
      id: `EV-${Math.random().toString(36).slice(2, 8)}`, name, raster: 0.4,
      befestigung: 'oben', module: [{ bauteil, anzahl: 1, z }],
      lastbloecke: [], eigen: true,
    });
    /*
     * DIESELBE VORLAGE ZWEIMAL GESICHERT ist eine Vorlage. Die ID zaehlt
     * nicht mit - sie wird bei jedem Sichern neu gewuerfelt und waere genau
     * das Merkmal, an dem sich zwei gleiche Kacheln unterscheiden.
     */
    const a1 = v('Meine Stuetze', 'drahtwerk-n-fl-cu-107');
    const a2 = v('Meine Stuetze', 'drahtwerk-n-fl-cu-107');
    wahr('Zweimal dasselbe gibt eine Kachel',
         AN.entdoppelteVorlagen([a1, a2]).length === 1);
    wahr('… und die ID spielt dabei keine Rolle',
         AN.vorlagenKennung(a1) === AN.vorlagenKennung(a2));
    /*
     * ZWEI DINGE DESSELBEN NAMENS BLEIBEN ZWEI. Der Name ist frei gewaehlt
     * und taugt allein nicht als Kennung; entschieden wird am INHALT.
     */
    const b = v('Meine Stuetze', 'drahtwerk-n-fl-cu-107', -0.5);
    wahr('Gleicher Name, anderer Inhalt: beide bleiben',
         AN.entdoppelteVorlagen([a1, b]).length === 2);
    wahr('Die erste ihrer Art bleibt stehen',
         AN.entdoppelteVorlagen([a1, a2, b])[0].id === a1.id);
    wahr('Eine leere Liste bleibt leer',
         AN.entdoppelteVorlagen([]).length === 0
         && AN.entdoppelteVorlagen(null).length === 0);
    /*
     * ENTDOPPELT WIRD BEIM SETZEN - so raeumt schon das Laden eines alten
     * Standes auf, statt die Doppelung nur zu verstecken.
     */
    const vorher = AN.vorlagen().length;
    AN.setzeEigeneVorlagen([a1, a2, b]);
    wahr('Gesetzt werden zwei, nicht drei',
         AN.vorlagen().length === vorher + 2);
    AN.setzeEigeneVorlagen([]);

    /*
     * >>> UND SIE GEHOEREN DEM BLATT. <<<
     *
     * Am einzelnen Tragwerk trug jedes Joch seine eigene Kachelliste. Eine
     * selbstgebaute Kachel ist Handwerkszeug des Anwenders, keine
     * Eigenschaft eines Jochs - wie die Masten und die Masskette.
     */
    const CC = await import(J('core.constants.js'));
    wahr('Die eigenen Vorlagen sind eine Blattangabe',
         CC.BLATT_FELDER.includes('eigeneVorlagen'));
    wahr('… und bleiben deshalb nicht am Tragwerk haengen',
         CC.tragwerkTeil({ L: 12, eigeneVorlagen: [a1] }).eigeneVorlagen
         === undefined);
    wahr('… sondern stehen in den Blattangaben',
         (CC.blattAngaben({ eigeneVorlagen: [a1] }).eigeneVorlagen ?? [])
           .length === 1);
  }

  /*
   * >>> DIE ZUGKRAFT IM MODELL. <<<
   *
   * Weisung vom 9. September: «die zugkraft im modell noch pruefen.»
   * Gemessen an A240 / 12.50 m, ein Drahtwerk bei x = 10.00 m: Betrag,
   * Richtung und Angriffsstelle muessen in Kern, Bild und Ausleitung
   * dieselben sein.
   */
  if (AJ.abfangDbDa()) {
    const AB5 = await import(J('core.abfangjoch.js'));
    const RA5 = await import(J('render.abfang.js'));
    const XA5 = await import(J('export.axisvm.abfang.js'));
    const teilV = (verlauf) => ({
      id: `AT-${verlauf}`, vorlage: 'hs-fahrdraht', name: `Leiter ${verlauf}`,
      x: 10, ort: 'joch', aktiv: true, anbindung: 'mitte', verlauf,
      module: [{ bauteil: 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107', anzahl: 1, z: 0 }],
    });
    const o5 = { ek: 'EK2', L_FL: 0, R: 0 };
    const kern = AB5.abfangAnbauLasten(teilV('vorn'), { ...o5, spannweite: 0 });
    const bild = (RA5.abfangSzene('A240', 12.5,
      { anbauteile: [teilV('vorn')], ...o5 }).vektoren ?? [])
      .find((v) => v.lastart === 'leiterzug');
    const mod = XA5.abfangAxisvmModell('A240', 12.5,
      { anbauteile: [teilV('vorn')], ...o5 });
    const last = (mod.lasten?.punkt ?? []).find((p) => p.lastfall === 'Leiterzug');

    pruef('Kern und Bild nennen denselben Zug',
          Number(String(bild.text).match(/([\d.]+)/)[1]), Math.abs(kern.Z),
          0.005, 'kN');
    pruef('Und das Modell auch', Math.abs(Number(last.wert)), Math.abs(kern.Z),
          1e-9, 'kN');
    wahr('Es zieht in Gleisrichtung', last.richtung === 'Y');
    wahr('Der Lastfall heisst «Leiterzug»', last.lastfall === 'Leiterzug');
    /*
     * DER ANGRIFFSKNOTEN LIEGT AUF DER TRAEGERACHSE - und der starre Arm
     * fuehrt zu EINEM Gurt: «so dass entweder der vordere oder hintere
     * Traeger belastet wird» (Weisung, 4. September).
     */
    const knA = (mod.knoten ?? []).find((k) => k.name === last.knoten);
    wahr('Der Knoten sitzt auf der Traegerachse',
         Math.abs(knA.y) < 1e-9 && Math.abs(knA.z) < 1e-9,
         `(${knA.x}, ${knA.y}, ${knA.z})`);
    pruef('… an der Stelle des Bauteils', Number(knA.x), 10, 0.01, 'm');
    const arme = (mod.staebe ?? []).filter((st) => /^ATARM_/.test(st.name ?? ''));
    pruef('Genau ein starrer Arm zum Gurt', arme.length, 1, 1e-9, 'Stk');
    wahr('… und zwar zum vorderen', /_1V$/.test(arme[0].name)
         && arme[0].art === 'starr', arme[0].name);
    /*
     * HINTEN ABGEFANGEN dreht das Vorzeichen und den Arm - beides, sonst
     * zoege der Leiter am falschen Gurt.
     */
    const modH = XA5.abfangAxisvmModell('A240', 12.5,
      { anbauteile: [teilV('hinten')], ...o5 });
    const lastH = (modH.lasten?.punkt ?? []).find((p) => p.lastfall === 'Leiterzug');
    wahr('Hinten abgefangen zieht nach hinten', Number(lastH.wert) < 0);
    wahr('… und haengt am hinteren Gurt',
         (modH.staebe ?? []).some((st) => /^ATARM_1H$/.test(st.name ?? '')));
    /*
     * EIN DURCHGEHENDER LEITER ZIEHT NICHT - dann darf im Modell auch keine
     * Leiterzuglast stehen.
     */
    const modD = XA5.abfangAxisvmModell('A240', 12.5,
      { anbauteile: [teilV('durchgehend')], ...o5 });
    /*
     * DER DURCHGEHENDE LEITER ZIEHT NICHT - weder mit eigener Last noch
     * ueber die Pauschale (Weisung, 9. September: «die pauschale bei
     * durchgehend rausnehmen»). Nachweis und Modell sagen jetzt dasselbe:
     * null.
     */
    wahr('Der durchgehende Leiter bringt keine Zuglast',
         !(modD.lasten?.punkt ?? []).some((p) => p.lastfall === 'Leiterzug'));
  }

  /*
   * >>> DIE BEMESSUNGSFESTIGKEIT DES ABFANGJOCHS. <<<
   *
   * Weisung vom 9. September, beim Pruefen des A240 aufgefallen: die
   * Auswertung bekam `fyd: stahl.fyd` - ein Feld, das `getStahl` nicht
   * fuehrt. Der Wert war `undefined`, und `abfangAuswertung` fiel auf ihren
   * Rueckfallwert 21.8 kN/cm² zurueck. Bei S355 waeren das 33.8 statt 21.8
   * gewesen: die Ausnutzung um 55 % zu hoch, ohne dass man saehe, woher.
   */
  {
    const AB4 = await import(J('core.abfangjoch.js'));
    const P4 = await import(J('data.profiles.js'));
    pruef('S235 mit gamma 1.05', AB4.abfangFyd(P4.getStahl('S235'), 1.05),
          22.381, 0.001, 'kN/cm²');
    pruef('S355 mit gamma 1.05', AB4.abfangFyd(P4.getStahl('S355'), 1.05),
          33.810, 0.001, 'kN/cm²');
    pruef('Ein anderer Beiwert wirkt', AB4.abfangFyd(P4.getStahl('S235'), 1.0),
          23.5, 1e-9, 'kN/cm²');
    /*
     * OHNE STAHL BLEIBT DIE NOTBREMSE - der Rueckfallwert. Er ist die
     * Ausnahme, nicht die Regel.
     */
    pruef('Ohne Stahl der Rueckfallwert', AB4.abfangFyd(null, 1.05),
          21.8, 1e-9, 'kN/cm²');
    /*
     * UND SIE KOMMT AN: mit S355 traegt derselbe Typ, der mit dem
     * Rueckfallwert ueberschritten waere.
     */
    if (AJ.abfangDbDa()) {
      const mit = (stahl) => AB4.abfangAuswertung({
        typ: 'A160', jt: 12.5, gk: 0.42, wk: 0.31, sk: 0.24,
        anbauteile: [], gammaG: 1.3, gammaQ: 1.3, psi0: 0.5,
        fyd: AB4.abfangFyd(P4.getStahl(stahl), 1.05) });
      wahr('Der hoehere Stahl senkt die Ausnutzung',
           mit('S355').max.eta < mit('S235').max.eta * 0.75,
           `${mit('S235').max.eta.toFixed(3)} -> ${mit('S355').max.eta.toFixed(3)}`);
    }
  }

  /*
   * ============ DIE ANBAUTEILE AM ABFANGJOCH ==========================
   *
   * Weisung vom 9. September: «die anbauteile im abfangjoch pruefen.» Zwei
   * Befunde kamen dabei heraus.
   *
   * ERSTENS: BILD UND NACHWEIS RECHNETEN VERSCHIEDEN. `abfangAnbauLasten`
   * ist DIESELBE Quelle fuer Nachweis, Bild und Ausleitung - sie braucht
   * aber ihre Angaben (Kombination, Spannweite, Radius, Temperaturfall).
   * Die Ausleitung reichte sie durch, die Szene nicht:
   *
   *      Nachweis   G = 1.70 kN     (Spannweite 60 m)
   *      Bild alt   G = 0.50 kN     (ohne Spannweite)
   *
   * ZWEITENS: EIN DRAHTWERK OHNE ABFANGWIRKUNG. Ein Bauteil mit Drahtwerk,
   * das ueber die GURTE angebunden ist, bringt keine Laengskraft. Das kann
   * richtig sein und kann der Fall sein, um dessentwillen das Abfangjoch
   * dasteht - am Ergebnis sieht man es nicht.
   */
  if (AJ.abfangDbDa()) {
    const AB3 = await import(J('core.abfangjoch.js'));
    const RA3 = await import(J('render.abfang.js'));
    const teil = {
      id: 'AT-p', vorlage: 'hs-fahrdraht', name: 'Fahrleitung Gleis 1',
      x: 6.25, ort: 'joch', aktiv: true,
      module: [
        { bauteil: 'anbauteil-haengestuetze-od-haengerohr', anzahl: 1, z: -1.35 },
        { bauteil: 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107', anzahl: 1, z: -2.7 },
      ],
    };
    const lastOpt = { ek: 'EK2', L_FL: 60, R: 0 };
    const lw = AB3.abfangAnbauLasten(teil, { ...lastOpt, spannweite: 60 });
    wahr('Das Anbauteil bringt Eigengewicht und Wind',
         lw.Gz > 0 && lw.Qy > 0, `Gz ${lw.Gz.toFixed(2)}  Qy ${lw.Qy.toFixed(2)}`);

    /*
     * DIE PFEILE IM BILD ZEIGEN DIESELBE ZAHL - mit den Angaben, ohne sie
     * nicht. Genau das war der Fehler.
     */
    const gVon = (sz) => {
      const v = (sz.vektoren ?? []).find((x) => x.lastart === 'staendig');
      return v ? Number(String(v.text).match(/([\d.]+)/)?.[1] ?? 0) : 0;
    };
    const mitAngaben = RA3.abfangSzene('A160', 12.5,
      { anbauteile: [teil], ...lastOpt });
    const ohneAngaben = RA3.abfangSzene('A160', 12.5, { anbauteile: [teil] });
    pruef('Der Kraftpfeil zeigt das Eigengewicht des Nachweises',
          gVon(mitAngaben), lw.Gz, 0.005, 'kN');
    wahr('… und ohne die Angaben zeigte er weniger',
         gVon(ohneAngaben) < gVon(mitAngaben) - 0.5,
         `${gVon(ohneAngaben)} gegen ${gVon(mitAngaben)}`);

    /*
     * DAS TEIL TRAEGT EIN DRAHTWERK UND FAENGT NICHTS AB - weil seine
     * Vorlage zur Gruppe `haengestuetze` gehoert. Der Hinweis nennt es.
     */
    wahr('Ohne Abfangwirkung gibt es keine Laengskraft', lw.Z === 0);
    const ohneZug = AB3.abfangZugOhneWirkung([teil]);
    wahr('Das Werkzeug nennt das Teil beim Namen',
         ohneZug.length === 1 && ohneZug[0].name === 'Fahrleitung Gleis 1');
    /*
     * UMGESTELLT AUF «MITTE TRAEGER» kommt die Kraft - und der Hinweis
     * verschwindet. Beides muss gelten, sonst waere er ein Dauerzustand.
     */
    const abgefangen = { ...teil, anbindung: 'mitte', verlauf: 'vorn' };
    const lw2 = AB3.abfangAnbauLasten(abgefangen, { ...lastOpt, spannweite: 60 });
    wahr('Auf «Mitte Traeger» zieht der Leiter', Math.abs(lw2.Z) > 0,
         `Z ${lw2.Z.toFixed(2)} kN`);
    wahr('… und der Hinweis entfaellt',
         AB3.abfangZugOhneWirkung([abgefangen]).length === 0);
    /*
     * EIN TEIL OHNE DRAHTWERK wird nicht genannt - sonst stuende der Hinweis
     * bei jedem Jochaufsatz.
     */
    wahr('Ein Teil ohne Drahtwerk bleibt unerwaehnt',
         AB3.abfangZugOhneWirkung([{ name: 'Aufsatz', x: 3, ort: 'joch',
                                     module: [{ bauteil: null }] }]).length === 0);
  }

  /*
   * >>> DAS ABFANGJOCH FAERBT NACH SEINEM EIGENEN NACHWEIS. <<<
   *
   * Weisung vom 9. September: «das abfangjoch im modell fertig bauen, es ist
   * noch alles grau und ohne anbauteile. nimm beim namen des jochs im 3d die
   * station weg. achte darauf das die darstellung dem prinzip der tragjoche
   * entspricht.»
   *
   * Grau war es aus einem Grund, der seit dem 8. September nicht mehr gilt:
   * `abfangAuswertung` rechnet Gurt und Bleche Station fuer Station. Die
   * Szene bekommt dieses Ergebnis jetzt und traegt dieselben Felder wie das
   * Tragjoch - eta, sig_v, sig, M, V.
   */
  if (AJ.abfangDbDa()) {
    const RA2 = await import(J('render.abfang.js'));
    const AB2 = await import(J('core.abfangjoch.js'));
    const typ = 'A330', jt = 26.5;
    const ergA = AB2.abfangAuswertung({
      typ, jt, gk: 0.5, wk: 0.3, sk: 0.2, anbauteile: [],
      gammaG: 1.3, gammaQ: 1.5, psi0: 0.5, fyd: 21.8, ek: 'EK2' });
    wahr('Der Abfangjoch-Nachweis liefert eine Reihe',
         (ergA?.reihe?.length ?? 0) > 5 && (ergA?.bleche?.bleche?.length ?? 0) > 5);

    const mitEta = (sz) => (sz.flaechen ?? [])
      .filter((f) => f.werte && Number.isFinite(f.werte.eta));
    const grau = RA2.abfangSzene(typ, jt, {});
    const bunt = RA2.abfangSzene(typ, jt, { erg: ergA });
    wahr('Ohne Ergebnis bleibt es neutral', mitEta(grau).length === 0);
    wahr('Mit Ergebnis tragen die Gurte ihre Ausnutzung',
         mitEta(bunt).filter((f) => /GURT/.test(f.teil ?? '')).length > 100);
    wahr('… und die Bleche ihre eigene',
         mitEta(bunt).filter((f) => /BL_|STEIFE/.test(f.teil ?? '')).length > 20);
    /*
     * DIE WERTE SIND NICHT ALLE GLEICH - sonst waere es eine Farbe statt
     * eines Verlaufs, und die Station am Auflager saehe aus wie die in
     * Feldmitte.
     */
    const etas = mitEta(bunt).map((f) => f.werte.eta);
    wahr('Die Ausnutzung laeuft ueber den Traeger',
         Math.max(...etas) > Math.min(...etas) + 0.05,
         `${Math.min(...etas).toFixed(3)} … ${Math.max(...etas).toFixed(3)}`);
    wahr('Die Felder heissen wie beim Tragjoch',
         ['eta', 'sig_v', 'sig', 'M'].every((k) =>
           Number.isFinite(mitEta(bunt)[0].werte[k])));
    /*
     * DER NAME TRAEGT KEINE STATIONSZAHL (Weisung, 9. September). Beim
     * Tragjoch steht dort auch nur Typ und Laenge.
     */
    const titel = (bunt.bauteiltitel ?? []).map((x) => x.text).join(' ');
    wahr('Der Bauteiltitel nennt Typ und Laenge', /A330 · 26\.50 m/.test(titel));
    wahr('… und keine Stationen', !/Station/.test(titel), titel);
    /*
     * UND DIE ANBAUTEILE STEHEN IM BILD - Arm, Staender und der Verlauf des
     * Leiters, wie beim Tragjoch.
     */
    const mitAt = RA2.abfangSzene(typ, jt, { erg: ergA, anbauteile: [
      { name: 'Fahrleitung Gleis 1', x: 10, ort: 'joch', module: [{ z: -0.35 }] },
    ] });
    wahr('Ein Anbauteil wird gezeichnet',
         (mitAt.flaechen ?? []).filter((f) => f.gruppe === 'anbau').length > 5);
  }

  /*
   * >>> DER MASTFUSS IST DER NULLPUNKT DES BLATTES. <<<
   *
   * Weisung vom 9. September: «Die Anschlusshoehe bezieht sich immer auf den
   * Mastfuss des linken (ersten masten). der punkt ist somit als referenz des
   * modells zu lesen. wenn man den wert anschlusshoehe aendert dann wandert
   * das joch und nicht der mastfuss, da man sonst nicht zwei joche
   * uebereinander vernuenftig eingeben kann.»
   *
   * Der Rechenkern baut jedes Tragwerk fuer sich, mit der JOCHACHSE auf
   * z = 0 und dem Fuss bei -H. `blattSzene` hebt jede Szene deshalb um +H;
   * dann liegen alle Fuesse auf 0. Geprueft wird der Baustein, der das
   * traegt: `szeneVerschieben` mit einem dz.
   */
  {
    const R3z = await import(J('render.3d.js'));
    const sz = { flaechen: [{ punkte: [[0, 0, -7.5], [1, 0, 0]] }],
                 linien: [], marken: [{ p: [0, 0, -7.5] }],
                 masse: [{ p0: [0, 0, -7.5], p1: [0, 0, 0] }],
                 bauteiltitel: [], vektoren: [], lastflaechen: [],
                 grenzen: { xMin: 0, xMax: 20, zMin: -7.5, zMax: 0.5 } };
    const hoch = R3z.szeneVerschieben(sz, 3, {}, 7.5);
    pruef('Der Fusspunkt liegt nach der Hebung auf null',
          hoch.flaechen[0].punkte[0][2], 0, 1e-9, 'm');
    pruef('… und die Jochachse auf der Anschlusshoehe',
          hoch.flaechen[0].punkte[1][2], 7.5, 1e-9, 'm');
    pruef('Die Marke wandert mit', hoch.marken[0].p[2], 0, 1e-9, 'm');
    pruef('Die Masslinie auch', hoch.masse[0].p0[2], 0, 1e-9, 'm');
    pruef('Und x bleibt, wie es war', hoch.flaechen[0].punkte[1][0], 4, 1e-9, 'm');
    pruef('Die Grenzen wandern mit', hoch.grenzen.zMin, 0, 1e-9, 'm');
    /*
     * ZWEI TRAGWERKE MIT VERSCHIEDENER ANSCHLUSSHOEHE stehen danach auf
     * DERSELBEN Grundlinie - das ist der Fall, um den es geht: zwei Joche
     * uebereinander auf denselben Masten.
     */
    const tief = R3z.szeneVerschieben(
      { ...sz, flaechen: [{ punkte: [[0, 0, -10.5], [1, 0, 0]] }] },
      0, {}, 10.5);
    pruef('Auch das hoeher angeschlossene steht auf null',
          tief.flaechen[0].punkte[0][2], 0, 1e-9, 'm');
    wahr('… und sein Joch liegt hoeher',
         tief.flaechen[0].punkte[1][2] > hoch.flaechen[0].punkte[1][2],
         `${tief.flaechen[0].punkte[1][2]} gegen ${hoch.flaechen[0].punkte[1][2]}`);
    // Ohne dz bleibt alles, wie es war - der Regelfall des Bausteins.
    pruef('Ohne Hebung bleibt z unberuehrt',
          R3z.szeneVerschieben(sz, 5).flaechen[0].punkte[0][2], -7.5, 1e-9, 'm');
  }

  /*
   * >>> DIE MASTNOTIZ IST WEG - SIE STAND ZWEIMAL DA. <<<
   *
   * Weisung vom 9. September: «die benennung unterhalb braucht es nicht,
   * diese ist schon oben enthalten.»
   *
   * Sie nannte Typ und Laenge des angewaehlten Masten (Weisung vom
   * 3. September: «die info über den masten auf den typ und länge
   * begrenzen»). Seit die Masten ihre eigene ZEILE in der Leiste haben,
   * steht dort dasselbe und mehr - Name, Profil und Stelle, der angewaehlte
   * hervorgehoben.
   */
  {
    const r = readFileSync(new URL('./js/ui.js', import.meta.url), 'utf8');
    wahr('Die Mastnotiz unter der Leiste ist raus',
         !r.includes('mastenNotizHtml') && !r.includes('qp-mast-notiz'));
    /*
     * SEIT DEM 13. SEPTEMBER TRAEGT JEDER MAST WIEDER SEINE EIGENE ZEILE
     * (Weisung: «kannst du die laenge und typ bei jedem masten schreiben,
     * sonst wirken diese tragwerke untergeordnet im bezug zum joch»). Vom
     * 11. bis dahin stand alles in einer Sammelzeile `qp-mastreihe`; die
     * Klasse heisst jetzt `qp-mastzeile`, und die Angabe steht im Namen -
     * nicht mehr nur im Titel.
     */
    wahr('… und die Mastzeile traegt die Angabe',
         r.includes('qp-mastzeile') && r.includes('ohne Profil'));
    wahr('… und jeder Mast ist einzeln anwaehlbar',
         r.includes('data-qp-mast='));
    wahr('… und sein Anker haengt daran',
         r.includes('qp-ankerstrich') && r.includes('data-qp-anker='));
    // Seit dem 17. September als Strebe mit Gelenk und Fundament gezeichnet.
    wahr('… als Strebe mit Gelenk und Fundament',
         r.includes('qa-strebe') && r.includes('qa-gelenk')
         && (r.includes('qa-fund') || r.includes('qa-strich')));
  }

  /*
   * >>> DIE LEISTE BLEIBT BEDIENBAR. <<<
   *
   * Weisung vom 9. September: «funktioniert dieser button +Tragwerke?» -
   * Nein, vier Tage lang nicht. Der Horcher fiel am 5. September weg, als
   * das ZIEHEN aus der Leiste genommen wurde: der Schnitt lief von
   * `[data-qp-mast]` bis zum naechsten Block, und das Aufklappmenue lag
   * dazwischen.
   *
   * Ein Knopf, der nichts tut, faellt niemandem auf, der ihn nicht drueckt.
   * Deshalb wird ab jetzt gezaehlt: JEDES `data-...` der Leiste braucht
   * seinen Horcher in `verdrahteLeiste`.
   */
  {
    const r = readFileSync(new URL('./js/ui.js', import.meta.url), 'utf8');
    const ab = r.indexOf('export function verdrahteLeiste(');
    const koerper = ab > 0 ? r.slice(ab, r.indexOf('\n}\n', ab)) : '';
    ['qp-neu-auf', 'qp-mast', 'qp-sicht', 'qp-tw'].forEach((d) => {
      wahr(`Die Leiste verdrahtet ${d}`, koerper.includes(d), d);
    });
    wahr('Das Aufklappmenue schaltet `hidden`',
         koerper.includes('liste.hidden = !liste.hidden'));
  }

  /*
   * >>> EIN JOCH GEHT NICHT DURCH EINEN FREMDEN MASTEN HINDURCH. <<<
   *
   * Weisung vom 3. September: «die tragwerkseingabe auf kollisionen checken
   * so dass joche nicht durch angrenzende masten hindurchgehen können.»
   *
   * Zwei Faelle liess die bisherige Regel durch, beide gemessen:
   *
   *   EIN EINZELMAST hat keine Ausdehnung; die Ueberschneidung zweier
   *   BEREICHE fasst ihn nicht. Ein Joch, auf L = 40 gesetzt, stand danach
   *   0..40 mit einem fremden Masten bei 30 mitten darin.
   *
   *   EIN ABFANGJOCH ist von der Bereichsregel ausgenommen. Um fuenf Meter
   *   verschoben stand sein Mast bei 5 im Joch darunter (0..20) und dessen
   *   Mast bei 20 im Abfangjoch (5..25).
   */
  {
    // A) DIE LAENGE HAELT AM NAECHSTEN MASTEN AN.
    let a = { typ: 'J90', L: 20, xLage: 0, twId: 'T1', mastProfil: 'HEB 240',
              mastH: 7.5, flSpannweite: 30 };
    a = C75.tragwerkHinzu(a, 'einzelmast', {});
    a = { ...a, xLage: 30 };
    a = C75.tauscheAktives(a, 'T1');
    pruef('Bis an den Masten heran ist erlaubt',
          C75.freieLaenge(a, 'T1', 30).L, 30, 1e-9, 'm');
    wahr('… und gilt nicht als geklemmt',
         C75.freieLaenge(a, 'T1', 30).geklemmt === false);
    pruef('Darueber hinaus wird angehalten',
          C75.freieLaenge(a, 'T1', 40).L, 30, 1e-9, 'm');
    wahr('… und sagt es', C75.freieLaenge(a, 'T1', 40).geklemmt === true);
    pruef('Darunter bleibt alles frei',
          C75.freieLaenge(a, 'T1', 25).L, 25, 1e-9, 'm');

    // B) DAS ABFANGJOCH RASTET AUF DIE MASTEN DES JOCHS DARUNTER.
    let b = { typ: 'J90', L: 20, xLage: 0, twId: 'T1', mastProfil: 'HEB 240',
              mastH: 7.5 };
    b = C75.tragwerkHinzu(b, 'abfangjoch', {});
    pruef('Fuenf Meter verschoben wird es zurueckgeholt',
          C75.freieLage(b, b.twId, 5).x, 0, 1e-9, 'm');
    wahr('Deckungsgleich ist erlaubt',
         C75.freieLage(b, b.twId, 0).geklemmt === false);

    // C) UND EINE ALTE DATEI SAGT ES.
    const alt = { ...a, L: 40 };
    const k = C75.mastKollisionen(alt);
    pruef('Die alte Lage wird gemeldet', k.length, 1, 1e-9, 'Stueck');
    pruef('… mit der Stelle', k[0].x, 30, 1e-9, 'm');
    wahr('Eine saubere Lage meldet nichts',
         C75.mastKollisionen(a).length === 0);
    // DAS ENDE DARF AUF DEM MASTEN LIEGEN - dort steht der gemeinsame.
    wahr('Ein Mast am Ende ist keine Durchdringung',
         C75.mastKollisionen({ ...a, L: 30 }).length === 0);
  }

  /*
   * >>> DIE STELLE DES ANGEWAEHLTEN MASTEN IST EIN FELD. <<<
   *
   * Gemeldet am 3. September: «beim angeklicktem rechten masten, wird der x
   * wert der lage nicht aktualisiert.» Es war kein Fehler IM Feld, sondern
   * ein fehlendes Feld: «Lage auf dem Querprofil x0» ist die Lage des
   * TRAGWERKS, und die aendert sich nicht, wenn man den rechten Masten
   * anklickt.
   *
   * Das neue Feld liest die Stelle des angewaehlten Masten und schreibt sie
   * ueber denselben Weg wie das Ziehen an der Marke.
   */
  {
    const F = FELDER.find((x) => x.key === 'mastX');
    wahr('Es gibt ein Feld fuer die Maststelle', Boolean(F));
    const w = reihe();
    const masten = C75.mastenVon(w);
    // Ohne Wahl gilt der Mast am Ende A des gerechneten Tragwerks.
    pruef('Ohne Wahl zeigt es den Masten am Ende A',
          F.wertAus(w), C75.gewaehlterMast(w).x, 1e-9, 'm');
    // Mit Wahl den angeklickten - hier der aeusserste rechts.
    const rechts = masten[masten.length - 1];
    pruef('Mit Wahl den angeklickten',
          F.wertAus({ ...w, mastAktiv: rechts.id }), rechts.x, 1e-9, 'm');
    wahr('Die Beschriftung nennt ihn beim Namen',
         F.label({ ...w, mastAktiv: rechts.id })
           .includes(C75.mastName(w, rechts)));
  }

  /*
   * DIE TYPWAHL IST GEGLIEDERT.
   *
   * Weisung vom 3. September: «beim dropdown sollte man das etwas gliedern,
   * das man es besser finden kann.» Die Liste war sortiert - erst das
   * aktuelle Sortiment, dann die Altbauweise -, aber man SAH die Ordnung
   * nicht. Eine sortierte Liste ohne Trennung liest sich wie eine
   * unsortierte.
   */
  {
    // Die Liste wird erst gefuellt, wenn die Typendatenbank steht.
    const { setzeTypOptionen } = await import(J('ui.schema.js'));
    const o = setzeTypOptionen();
    wahr('Jede Zeile traegt ihre Gruppe', o.every((x) => x.gruppe));
    const g = [...new Set(o.map((x) => x.gruppe))];
    wahr('Aktuelles Sortiment steht zuerst', g[0] === 'Aktuelles Sortiment');
    wahr('Die Altbauweise folgt', g[1].startsWith('Altbauweise'));
    wahr('Und die Vergleichsmodelle stehen hinten',
         g.indexOf('Vergleichsmodelle') > 1);
  }

  /*
   * ===================================================================
   * DAS SORTIMENT DER ABFANGJOCHE.
   * ===================================================================
   *
   * Weisung vom 3. September: «weiter mit dem aufbau der abfangjoche gehen.
   * die zeichnungen sind unter den grundlagen, beachte dass es hier auch ein
   * sortiment aktuell und alt gibt.»
   *
   * Siebzehn Typen aus den Sortimentsblaettern - sieben im aktuellen
   * Sortiment (A160 bis A360), zehn in der Altbauweise. Geprueft wird der
   * UMFANG, nicht jede Zahl: dass keine Bauweise fehlt, dass die
   * Laengenbereiche zusammenpassen und dass die Liste die Ordnung ZEIGT.
   */
  {
    const alle = AJ.abfangjoche();
    wahr('Das Sortiment steht vollstaendig', alle.length === 17);
    const neu = alle.filter((a) => a.bauweise === 'neu');
    const alt = alle.filter((a) => a.bauweise === 'alt');
    wahr('Sieben im aktuellen Sortiment', neu.length === 7);
    wahr('Zehn in der Altbauweise', alt.length === 10);
    wahr('Das aktuelle Sortiment reicht von A160 bis A360',
         neu[0].typ === 'A160' && neu[neu.length - 1].typ === 'A360');
    wahr('Jeder Typ nennt sein Gurtprofil', alle.every((a) => a.profil));
    // Die Bindebleche sitzen bei ALLEN im 500er-Raster - so steht es in der
    // Mass-Tabelle der Schemablaetter (Spalte A2-A9). Waere das je anders,
    // muesste es hier auffallen.
    wahr('Alle im 500er-Raster',
         alle.every((a) => a.masse?.teilung === 500));
    wahr('Und alle mit 280 mm Bauhoehe am Ende',
         alle.every((a) => a.masse?.jdEnde === 280));

    /*
     * >>> DIE ALTBAUWEISE FUEHRT NUR EINE GROESSTE LAENGE. <<<
     *
     * Auf ihren Blaettern steht «jt max.» und keine kleinste. Eine erfundene
     * Untergrenze waere eine Angabe, die niemand gemacht hat.
     */
    wahr('Die Altbauweise nennt keine kleinste Laenge',
         alt.every((a) => a.jt[0] === null));
    const bA160 = AJ.abfangLaengenbereich('A160');
    pruef('A160 von', bA160.min, 5.5, 1e-9, 'm');
    pruef('A160 bis', bA160.max, 12.5, 1e-9, 'm');
    const bAlt = AJ.abfangLaengenbereich('UAP 130');
    pruef('Die Altbauweise bis', bAlt.max, 9.5, 1e-9, 'm');
    pruef('… und ab der kleinsten Laenge des Sortiments', bAlt.min, 5.5, 1e-9, 'm');
    wahr('Die Beschriftung sagt es',
         bAlt.text.startsWith('bis') && bA160.text.includes('–'));

    /*
     * DIESELBE GLIEDERUNG WIE BEIM TRAGJOCH - aus demselben Grund: eine
     * sortierte Liste ohne Trennung liest sich wie eine unsortierte.
     */
    const { abfangOptionen } = await import(J('ui.schema.js'));
    const o = abfangOptionen();
    wahr('Siebzehn Zeilen zur Wahl', o.length === 17);
    wahr('Jede traegt ihre Gruppe', o.every((x) => x.gruppe));
    const g = [...new Set(o.map((x) => x.gruppe))];
    wahr('Aktuelles Sortiment zuerst', g[0] === 'Aktuelles Sortiment');
    wahr('Altbauweise danach', g.length === 2 && g[1].startsWith('Altbauweise'));
    wahr('Die Zeile nennt Profil und Laengenbereich',
         o[0].text.includes('UPE 160') && o[0].text.includes('12.5'));
  }

  /*
   * ===================================================================
   * DER AUFBAU DER ABFANGJOCHE - aus den Konstruktionszeichnungen.
   * ===================================================================
   *
   * Weisung vom 3. September: «Die Abfangjoche sind liegende
   * Vierendeeltraeger.» Meine erste Lesart der Sortimentsblaetter -
   * «zweigurtiger Traeger, der Kern passt darauf nicht» - war falsch.
   *
   * Der Schnitt A-A zeigt zwei Gurte NEBENEINANDER, die Stueckliste nennt
   * sie beim Namen: Gurt, Verstaerkung, Bindeblech L, Bindeblech,
   * Bindeblech R. Es sind BINDEBLECHE wie beim Tragjoch, je eines oben und
   * unten - kein anderes Bauprinzip, nur eine Ebene statt zweier.
   */
  {
    const A160 = AJ.getAbfangjoch('A160');
    const auf = AJ.abfangAufbau('A160');
    wahr('A160 fuehrt zwei Gurte', auf.gurte === 2);
    wahr('… aus UPE 160', auf.gurtprofil === 'UPE 160');
    /*
     * >>> DER HEBELARM IST k, NICHT h. <<<
     *
     * Das war die Frage, die ich vorgaengig stellen musste. k = d + 2b ist
     * das Aussenmass im FELD und spannt die Rahmenebene auf; h ist das
     * Aussenmass am JOCHENDE. Bei A160 sind beide 420 - bei den gekropften
     * Typen nicht, und dort waere die Verwechslung teuer.
     */
    pruef('k folgt aus d und b', auf.d + 2 * auf.b, auf.k, 1e-9, 'mm');
    const a200 = AJ.abfangAufbau('A200');
    pruef('… auch beim gekropften A200', a200.d + 2 * a200.b, a200.k, 1e-9, 'mm');
    pruef('und h ist das ENDmass', a200.spreizung + 2 * a200.b,
          A160.masse ? 440 : 440, 1e-9, 'mm');
    wahr('Die beiden sind dort verschieden', a200.k !== 440);
    // Die Spreizung am Ende ist bei allen erfassten Typen 280.
    for (const t of AJ.abfangjoche().filter((x) => x.aufbau)) {
      wahr(`${t.typ} spreizt am Ende auf 280`, t.aufbau.spreizung === 280);
    }

    /*
     * >>> DIE JOCHENDEN SIND ABGEKROEPFT. <<<
     *
     * Weisung vom 4. September: «zudem sind die jochenden in der
     * gesamtbreite nicht verfuengt (abgekroepft)». In der Draufsicht laufen
     * die Gurte zum Ende hin zusammen. Bei A300 gibt die Werkstattzeichnung
     * am Jochende aussen 600 - das sind 300 licht plus zweimal die
     * Flanschbreite 150 -, und die beiden innenliegenden Deckbleche zu 10
     * machen daraus die Spreizung 280.
     */
    {
      const w = (t, x, jt) => AJ.abfangLichteWeite(t, x, jt);
      pruef('A300 misst am Jochende 300 licht', w('A300', 0, 13), 300, 1e-9, 'mm');
      pruef('… aussen also 600', w('A300', 0, 13) + 2 * AJ.abfangAufbau('A300').b,
            600, 1e-9, 'mm');
      pruef('… und die Deckbleche machen daraus die Spreizung',
            w('A300', 0, 13) - 2 * 10, AJ.abfangAufbau('A300').spreizung,
            1e-9, 'mm');
      /*
       * >>> `d` IST DER STEGABSTAND, NICHT DIE LICHTE WEITE. <<<
       *
       * Hier stand bis zum 4. September `d` als Sollwert - und der
       * Pruefstand hielt damit fest, was die Zeichnung widerlegt. Sie
       * bemasst im Feld drei Werte ineinander, bei A270 735 | 600 | 465:
       * aussen ueber die Flanschspitzen, die Stegachsen, licht. Beim UPE
       * liegt der Steg AUF der Innenkante, dort sind beide gleich; beim IPE
       * in der Mitte, und licht ist d - b.
       */
      pruef('Im Feld steht die volle lichte Weite', w('A300', 6.5, 13),
            AJ.abfangLichtFeld('A300'), 1e-9, 'mm');
      pruef('… und die ist beim I um eine Flanschbreite kleiner als d',
            AJ.abfangLichtFeld('A300'),
            AJ.abfangAufbau('A300').d - AJ.abfangAufbau('A300').b, 1e-9, 'mm');
      pruef('Beim U sind Stegabstand und lichte Weite dasselbe',
            AJ.abfangLichtFeld('A240'), AJ.abfangAufbau('A240').d, 1e-9, 'mm');
      /*
       * DIE PROBE MACHT DIE STUECKLISTE: jedes Bindeblech misst die lichte
       * Weite an seiner Station. Vorher lagen die inneren Endbleche der
       * IPE-Typen 80 mm daneben.
       */
      for (const [t2, jt2, x2, soll] of [['A270', 13, 13 - 1.46, 391],
                                         ['A360', 21.5, 21.5 - 1.465, 371],
                                         ['A200', 11, 1.375, 342],
                                         ['A240', 14, 14 - 0.91, 280]]) {
        wahr(`${t2}: das Blech bei ${x2.toFixed(2)} m misst ${soll}`,
             Math.abs(w(t2, x2, jt2) - soll) < 5);
      }
      // Das lange Ende knickt frueher als das kurze - 850 gegen 920.
      wahr('Das lange Ende knickt frueher als das kurze',
           w('A300', 0.9, 13) > w('A300', 13 - 0.9, 13));
      // A160 ist gerade und kennt keine Kroepfung.
      wahr('A160 ist gerade', AJ.abfangKroepfung('A160') === null);
      pruef('… und misst ueberall gleich', w('A160', 0, 12.5),
            w('A160', 6.25, 12.5), 1e-9, 'mm');
      /*
       * DIE QUERSTEIFE AM JOCHENDE BELEGT DIE KROEPFUNG: A240 fuehrt dort
       * ein IPE 240 x 280, und 280 ist genau die Spreizung. Ein Riegel von
       * 280 haette im Feld, bei 600 lichter Weite, keinen Anschluss.
       */
      pruef('A240 riegelt am Ende ueber 280', AJ.abfangQuersteife('A240').ende.laenge,
            w('A240', 0, 14), 1e-9, 'mm');
    }

    /*
     * DIE BINDEBLECHE - Regelblech im Feld, Endbleche abweichend.
     *
     * Das Regelblech ist so lang wie der lichte Abstand der Gurte: es fuellt
     * genau die Luecke. Faellt das je auseinander, stimmt eine der beiden
     * Angaben nicht.
     */
    const bl = AJ.abfangBindeblech('A160');
    pruef('Das Regelblech fuellt die Luecke', bl.regel.l, auf.d, 1e-9, 'mm');
    wahr('Es liegt in zwei Ebenen', bl.ebenen === 2);
    wahr('Die Endbleche sind staerker',
         bl.endeL.t > bl.regel.t && bl.endeR.t > bl.regel.t);

    /*
     * >>> DIE GABEL AM JOCHENDE. <<<
     *
     * Weisung vom 3. September: «beachte noch die verstaerkung zu den
     * jochenden (Gabel)». Ein aufgesetztes Gurtstueck GLEICHEN Profils, das
     * den Gurtquerschnitt im Anschlussbereich verdoppelt - und genau dort
     * liegt der Nachweisschnitt am Auflager.
     */
    const gab = AJ.abfangGabel('A160');
    wahr('Die Gabel ist erfasst', Boolean(gab));
    wahr('Sie hat das Profil des Gurtes', gab.profil === auf.gurtprofil);
    wahr('Und sitzt an beiden Enden', gab.anzahl === 2);
    for (const t of AJ.abfangjoche().filter((x) => x.verstaerkung)) {
      wahr(`${t.typ} traegt seine Gabel`,
           t.verstaerkung.profil === t.aufbau.gurtprofil
           && t.verstaerkung.laenge > 0);
    }

    /*
     * DIE MASS-TABELLE - die Blecheinteilung je gefuehrte Laenge.
     *
     * >>> MASSGEBEND SIND DIE DATEN, NICHT DIE HERLEITUNG. <<<
     *
     * QV1 = jt - 4.0 m liesse sich herleiten und stimmt fuer jede erfasste
     * Zeile. Genau deshalb steht es hier als KONTROLLE und nicht als
     * Rechenweg: bestaetigt die Herleitung die Daten, ist das ein gutes
     * Zeichen; ersetzt sie die Daten, ist es ein Verstoss gegen die
     * stehende Vorgabe.
     */
    const l160 = A160.laengen;
    wahr('A160 fuehrt 15 Laengen', l160.length === 15);
    // 158 Laengen ueber das aktuelle Sortiment - jede aus ihrem Schemablatt.
    pruef('Das Sortiment fuehrt 158 Laengen',
          AJ.abfangjoche().reduce((n, t) => n + (t.laengen?.length ?? 0), 0),
          158, 1e-9, 'Stk');
    wahr('Von 5.50 bis 12.50 m',
         l160[0].jt === 5.5 && l160[l160.length - 1].jt === 12.5);
    wahr('Die Regelteilung ist ueberall 500',
         l160.every((z) => z.A === 500));
    wahr('Das erste Feld wechselt 250/500',
         l160.every((z) => z.A1 === 250 || z.A1 === 500));
    wahr('QV1 bestaetigt die Herleitung jt - 4.0 m',
         l160.every((z) => Math.abs(z.QV1 - (z.jt * 1000 - 4000)) < 1e-6));
    // Die Ueberhoehungsabschnitte decken die ganze Jochlaenge - symmetrisch,
    // je Haelfte die Summe der S-Werte.
    wahr('Die Ueberhoehung teilt die ganze Laenge',
         l160.every((z) => Math.abs(2 * z.S.reduce((a2, b2) => a2 + b2, 0)
                                    - z.jt * 1000) < 2));
    const a200L = AJ.getAbfangjoch('A200').laengen;
    wahr('A200 fuehrt 23 Laengen', a200L.length === 23);
    wahr('… von 6.00 bis 17.00 m',
         a200L[0].jt === 6.0 && a200L[a200L.length - 1].jt === 17.0);
    wahr('… und teilt die Laenge ebenso',
         a200L.every((z) => Math.abs(2 * z.S.reduce((a2, b2) => a2 + b2, 0)
                                     - z.jt * 1000) < 2));

    /*
     * DIE ZEILE ZUR LAENGE - nur bei einer GEFUEHRTEN Laenge.
     *
     * Eine Zwischenlaenge bekommt keine erfundene Einteilung, sondern null.
     * Der Aufrufer muss dann sagen, dass er sie nicht kennt.
     */
    wahr('Eine gefuehrte Laenge findet ihre Zeile',
         AJ.abfangMasse('A160', 9.5)?.dm === '095');
    wahr('Eine Zwischenlaenge findet keine',
         AJ.abfangMasse('A160', 9.7) === null);
    wahr('Und eine ausserhalb ebenso wenig',
         AJ.abfangMasse('A160', 20) === null);

    /*
     * WAS VOLLSTAENDIG IST, SAGT DIE DATENBANK SELBST.
     *
     * Ohne Mass-Tabelle steht der Aufbau da, aber keine Blecheinteilung -
     * und ohne die gibt es keinen Nachweisschnitt. Das muss abfragbar sein,
     * sonst rechnet der Kern auf halben Daten weiter.
     */
    /*
     * SEIT DEM 3. SEPTEMBER IST DAS AKTUELLE SORTIMENT GANZ ERFASST.
     *
     * Sieben Typen, jeder mit Aufbau, Bindeblechen, Endverstaerkung und
     * Mass-Tabelle. Die Altbauweise fuehrt nichts davon - fuer sie liegen
     * keine Konstruktionszeichnungen vor -, und das muss sichtbar bleiben,
     * damit niemand auf halben Daten rechnet.
     */
    const neuT = AJ.abfangjoche().filter((x) => x.bauweise === 'neu');
    wahr('Sieben Typen im aktuellen Sortiment', neuT.length === 7);
    for (const t of neuT) {
      wahr(`${t.typ} ist vollstaendig`, AJ.abfangVollstaendig(t.typ));
    }
    const altT = AJ.abfangjoche().filter((x) => x.bauweise === 'alt');
    wahr('Die Altbauweise ist es nicht',
         altT.every((t) => !AJ.abfangVollstaendig(t.typ)));

    /*
     * >>> AB A270 IST DIE ENDVERSTAERKUNG KEINE GABEL MEHR. <<<
     *
     * A160 bis A240 setzen ein Gurtstueck gleichen Profils auf. Ab A270
     * tritt ein DECKBLECH an seine Stelle, asymmetrisch: 1450 mm am linken
     * Jochende, 650 am rechten. Wer nur nach `verstaerkung` fragt, findet
     * bei den vier grossen Typen nichts - und weist den unverstaerkten
     * Querschnitt an der Stelle nach, an der der verstaerkte steht.
     */
    for (const t of neuT) {
      const e = AJ.abfangEndverstaerkung(t.typ);
      wahr(`${t.typ} traegt eine Endverstaerkung`, Boolean(e));
      wahr(`… und sagt ihre Bauart`,
           e.art === (['A160', 'A200', 'A240'].includes(t.typ)
             ? 'gabel' : 'deckblech'));
    }
    const gab240 = AJ.abfangEndverstaerkung('A240');
    wahr('Die Gabel hat das Profil des Gurtes',
         gab240.teile[0].profil === AJ.abfangAufbau('A240').gurtprofil);
    const dbl = AJ.abfangEndverstaerkung('A330');
    wahr('Das Deckblech sitzt an beiden Enden', dbl.teile.length === 2);
    wahr('… links laenger als rechts',
         dbl.teile[0].l === 1450 && dbl.teile[1].l === 650);
    wahr('Und beide Enden gleich breit',
         dbl.teile[0].b === dbl.teile[1].b);

    /*
     * DIE VIERENDEEL-BEREICHE. A160 und A200 fuehren einen, ab A240 sind es
     * mehrere - dazwischen sitzen die Quersteifungen aus dem Gurtprofil.
     * Ihre Summe plus die Randbereiche ergibt die Jochlaenge nicht exakt;
     * geprueft wird deshalb nur, dass die Bereiche da sind und wachsen.
     */
    for (const t of neuT) {
      wahr(`${t.typ} fuehrt seine Vierendeel-Bereiche`,
           t.laengen.every((z) => Array.isArray(z.QV) && z.QV.length >= 1));
      const kurz = t.laengen[0].QV.length;
      const lang = t.laengen[t.laengen.length - 1].QV.length;
      wahr(`… und teilt laengere Joche feiner`, lang >= kurz);
    }
    // Die Ueberhoehung teilt bei ALLEN Typen die ganze Jochlaenge.
    for (const t of neuT) {
      wahr(`${t.typ} teilt die Laenge mit seiner Ueberhoehung`,
           t.laengen.every((z) => Math.abs(
             2 * z.S.reduce((a2, b2) => a2 + b2, 0) - z.jt * 1000) < 2));
    }
  }

  /*
   * >>> DER ABFANGJOCHTYP GEHOERT NICHT INS FELD `typ`. <<<
   *
   * Erster Versuch am 3. September: eine Liste, zwei Sortimente, je nach
   * Art. Das brach sofort - `typ` ist die Angabe, mit der der RECHENKERN
   * sein Joch holt (`getTragjoch`). Ein «A160» darin warf «Unbekannter
   * Tragjochtyp», und zwar beim blossen ZIEHEN AN EINER MASTMARKE, weit weg
   * von der Eingabe.
   */
  {
    const fTyp = FELDER.find((x) => x.key === 'typ');
    const fAbf = FELDER.find((x) => x.key === 'abfangTyp');
    wahr('Es gibt ein eigenes Feld fuer den Abfangjochtyp', Boolean(fAbf));
    const alsJoch = { tragwerksart: 'joch' };
    const alsAbf = { tragwerksart: 'abfangjoch' };
    wahr('Am Tragjoch steht der Tragjochtyp',
         fTyp.sichtbar(alsJoch) && !fAbf.sichtbar(alsJoch));
    wahr('Am Abfangjoch der Abfangjochtyp',
         !fTyp.sichtbar(alsAbf) && fAbf.sichtbar(alsAbf));
    wahr('Und beide nie zugleich',
         !(fTyp.sichtbar(alsAbf) && fAbf.sichtbar(alsAbf)));

    /*
     * DER BUG SELBST: Ziehen an der Marke eines Abfangjochs.
     *
     * `mastGrenzen` fragte blind `getTragjoch(t.typ)`. Steht dort ein
     * Abfangjochtyp - oder, wie hier, gar keiner -, flog die Ausnahme.
     */
    const w = C75.tragwerkHinzu(
      { typ: 'J90', L: 12, xLage: 0, mastProfil: 'HEB 240',
        mastH: 8, mastLaenge: 12 },
      'abfangjoch', { abfangTyp: 'A160', L: 10 });
    const tAbf = C75.tragwerkeVon(w).find(
      (t) => C75.tragwerksart(t).key === 'abfangjoch');
    wahr('Das Abfangjoch traegt seinen Typ', tAbf?.abfangTyp === 'A160');
    // Und die Leiste nennt ihn: zwei uebereinander unterscheiden sich sonst
    // nur in der Anschlusshoehe, und «Abfangjoch · H 7.50 m» sagt nicht,
    // welches Sortiment darunter liegt.
    wahr('Die Bezeichnung nennt ihn',
         C75.tragwerkName(w, tAbf).startsWith('A160'));
    wahr('Und keinen Tragjochtyp im Rechenfeld',
         tAbf?.typ === undefined || tAbf.typ !== 'A160');
    const UIA = await import(J('ui.js'));
    // An JEDER Marke des Blattes, nicht nur an einer - der Fehler haengt
    // daran, WELCHES Tragwerk am gezogenen Ende haengt.
    let flog = null;
    for (const m of C75.mastenVon(w)) {
      try { UIA.mastGrenzen(UIA.mastRollen(w, m.id), m.x); }
      catch (e) { flog = e; }
    }
    wahr('Ziehen an seinen Mastmarken wirft nicht', flog === null);
  }

  /*
   * >>> UND DER NACHWEIS SAGT, DASS ER KEINER IST. <<<
   *
   * Das Sortiment steht in der Maske, und wer den Typ waehlt, darf annehmen,
   * dass damit gerechnet wird. Wird es nicht: das Abfangjoch ist ein
   * zweigurtiger Traeger mit Sprossen, der Kern rechnet vier Winkelgurte
   * mit Bindeblechen. Ein Werkzeug, das hier still die Jochrechnung
   * weiterfuehrt, waere die schlimmste Antwort.
   */
  {
    const { hinweise: hwA } = await import(J('core.checks.js'));
    // Am GERECHNETEN Modell, nicht an einem Stueckwerk: `hinweise` fragt
    // auch die Querschnittsklassifizierung, und die braucht Profile.
    const modellVon = (extra) =>
      rechne({ ...standardwerte(), ...extra }).modell;
    const h = hwA(modellVon({ tragwerksart: 'abfangjoch', abfangTyp: 'A160' }));
    const zeile = h.find((x) => x.includes('Abfangjoch'));
    wahr('Der Hinweis steht da', Boolean(zeile));
    wahr('Er nennt den gewaehlten Typ', zeile.includes('A160'));
    /*
     * >>> ER SAGT JETZT, DASS ES SEIN EIGENER NACHWEIS IST. <<<
     *
     * Weisung vom 10. September: die drei Reiter sind fertig. Hier stand
     * «sagt, dass das Tragjoch gerechnet wird» - das war die Aussage,
     * solange sie den Ersatzbalken zeigten. Jetzt zaehlt der Hinweis sie
     * als Teil der eigenen Auswertung auf.
     */
    wahr('Und sagt, dass die ganze Auswertung seine eigene ist',
         zeile.includes('seine eigene'));
    wahr('… und nennt die drei Reiter',
         zeile.includes('SCHNITT, VERLÄUFE und AUFLAGER'));
    const ohne = hwA(modellVon({ tragwerksart: 'joch' }));
    wahr('Beim Tragjoch steht er nicht',
         !ohne.some((x) => x.includes('Abfangjoch')));
  }

  /*
   * >>> DIE BESCHRIFTUNG UEBERLEBT DIE NACHFUEHRUNG. <<<
   *
   * Die Leiste im Feld «Tragwerke» ist das einzige Feld, dessen INHALT
   * nachgefuehrt wird statt seines Werts - Laengen, Lagen und Profile
   * aendern sich beim Ziehen fortwaehrend. `leisteNachfuehren` setzt dazu
   * das `innerHTML` der Marke `[data-tragwerkfeld]` neu.
   *
   * Die Marke sass am AEUSSEREN Feldrahmen. Damit fiel bei jedem Mastklick
   * die Beschriftung «Tragwerke auf diesem Querprofil» weg und der Hinweis
   * darunter mit ihr: `tragwerkfeldHtml` liefert beides nicht. Die Maske
   * sackte um zwei Zeilen zusammen und beim naechsten vollen Neubau wieder
   * auseinander.
   *
   * Weisung vom 3. September: «kannst du diesen text immer anlassen auch
   * wenn man auf die masten klickt, da sonst die darstellung springt.»
   */
  {
    const UIF = await import(J('ui.js'));
    const f = FELDER.find((x) => x.key === 'tragwerksart');
    const h = UIF.feldHtml(f, 'joch', standardwerte());
    const iLabel = h.indexOf('Tragwerke auf diesem Querprofil');
    const iMarke = h.indexOf('data-tragwerkfeld');
    wahr('Das Feld traegt seine Beschriftung', iLabel >= 0);
    wahr('Und die Marke der Nachfuehrung', iMarke >= 0);
    // DAS ist die Invariante: Beschriftung ausserhalb, Inhalt innerhalb.
    wahr('Die Beschriftung steht VOR der Marke', iLabel < iMarke);
    wahr('Der Hinweis steht dahinter',
         h.lastIndexOf('hinweis') > iMarke);
    // Gegenprobe: ein gewoehnliches Feld traegt gar keine Marke.
    const g = UIF.feldHtml(FELDER.find((x) => x.key === 'xLage'), 0,
                           standardwerte());
    wahr('Ein gewoehnliches Feld traegt keine',
         !g.includes('data-tragwerkfeld'));
  }

  /* =========================================================================
   * >>> JE MAST EINE ZEILE, GLEICHWERTIG MIT DEM JOCH. <<<
   * =========================================================================
   *
   * Weisung vom 13. September: «kannst du die laenge und typ bei jedem
   * masten schreiben, sonst wirken diese tragwerke untergeordnet im bezug
   * zum joch. design gleichwertig waehlen.»
   *
   * Davor stand eine Sammelzeile - «Masten / 2 x HEB 240 / 8.50 m» - und
   * auf der Bahn nur die Nummer, senkrecht. Das Joch hatte Kuerzel, Namen
   * und Linie; der Mast eine Anzahl.
   *
   * Geprueft wird an der ZEICHENKETTE, nicht am DOM: `querprofilLeisteHtml`
   * ist reine Textarbeit und laeuft damit auch hier in Node.
   */
  {
    const UIF = await import(J('ui.js'));
    const MA = await import(J('core.auflager.js'));
    const joch = (extra = {}) => ({
      ...standardwerte(), tragwerksart: 'joch', typ: 'J100', L: 15,
      xLage: 0, mastH: 7.5, jd: 500,
      mastProfil: 'HEB 240', mastVorhanden: true, ...extra,
    });
    const h = UIF.querprofilLeisteHtml(joch());
    const zeilen = (s, klasse) =>
      (s.match(new RegExp(`class="qp-zeile[^"]*${klasse}`, 'g')) ?? []).length;
    /*
     * 1 - DIE FORM IST DIESELBE.
     */
    wahr('Jeder Mast hat seine eigene Zeile', zeilen(h, 'qp-mastzeile') === 2);
    wahr('Die Sammelzeile ist weg', !h.includes('qp-mastreihe'));
    wahr('… und mit ihr die senkrechte Anschrift',
         !h.includes('qp-mastschrift'));
    wahr('«2 Stueck» und «2 x» stehen nicht mehr da',
         !h.includes('St\u00fcck') && !h.includes('2 \u00d7'));
    /*
     * DIESELBEN DREI SPALTEN WIE BEIM JOCH: Platz fuers Kaestchen, Name,
     * Bahn. Das IST die Gleichwertigkeit - nicht eine Aehnlichkeit der
     * Farbe, sondern dasselbe Raster.
     */
    const mastZeile = /<div class="qp-zeile qp-mastzeile[^>]*>([\s\S]*?)<\/div>/
      .exec(h)?.[1] ?? '';
    // Seit dem Baum (19. September) steht die Lage als Zahl, nicht als Bahn.
    for (const teil of ['qp-auge-platz', 'class="qp-name"', 'class="qp-lage"']) {
      wahr(`Die Mastzeile traegt ${teil} wie die Jochzeile`,
           mastZeile.includes(teil));
    }
    /*
     * 2 - KUERZEL UND NAME, WIE BEIM JOCH.
     */
    wahr('Das Kuerzel nennt Nummer und Gattung',
         h.includes('>M1</b>') && h.includes('>M2</b>'));
    wahr('Der Name traegt Profil und Laenge',
         (h.match(/HEB 240 \u00b7 8\.50 m/g) ?? []).length >= 2);
    /*
     * DIE LAENGE STEHT DA, OBWOHL SIE NIEMAND EINGETIPPT HAT. `mastLaenge`
     * fehlt im Satz; die Maske zeigt dort die Vorgabe, und die Leiste
     * rechnet dieselbe.
     */
    const soll = MA.mastLaengeVorgabe(7.5, 500);
    wahr('Die Laenge ist die Vorgabe des Feldes',
         h.includes(`${soll.toFixed(2)} m`), `${soll.toFixed(2)} m`);
    const hL = UIF.querprofilLeisteHtml(joch({ mastLaenge: 11.5 }));
    wahr('… und eine eingetippte Laenge schlaegt sie',
         hL.includes('11.50 m'));
    /*
     * 3 - DIE LAGE, ANGESCHRIEBEN.
     */
    const masse = [...h.matchAll(
      /<div class="qp-zeile qp-mastzeile[\s\S]*?class="qp-lage">([-\d.]+)</g)]
      .map((m) => m[1]);
    wahr('Jeder Mast traegt seine Lage', masse.length === 2, masse.join(', '));
    wahr('… und zwar seine eigene',
         masse[0] === '0.00' && masse[1] === '15.00');
    /*
     * 4 - KEINE ZAHL ZWEIMAL.
     *
     * Die Enden des Jochs SIND seine Masten, und die schreiben ihre Lage
     * eine Zeile tiefer an. Stuende sie auch an der Linie, laege dieselbe
     * Zahl zweimal untereinander.
     */
    const jochZeile = /<div class="qp-zeile(?! qp-mastzeile)[^"]*"[\s\S]*?<\/div>/
      .exec(h)?.[0] ?? '';
    wahr('Steht das Joch auf Masten, schweigt seine Linie',
         !jochZeile.includes('qp-mass-links')
         && !jochZeile.includes('qp-mass-rechts'));
    wahr('… und die Jochzeile bleibt so flach wie zuvor',
         !jochZeile.includes('qp-bahn-mass'));
    const hO = UIF.querprofilLeisteHtml(joch({ mastVorhanden: false }));
    // Die Lage steht als Zahl rechts in der Zeile, von-bis.
    wahr('Ohne Masten schreibt die Zeile ihre Enden an',
         hO.includes('class="qp-lage">0.00–15.00<'));
    wahr('… und ohne Masten gibt es auch keine Mastzeile',
         zeilen(hO, 'qp-mastzeile') === 0);
    /*
     * 5 - VERSCHIEDENE MASTEN STEHEN VERSCHIEDEN DA. Das war der Anlass
     * der Weisung: eine Sammelzeile kann nur EINEN Namen tragen.
     */
    const hG = UIF.querprofilLeisteHtml(joch({
      masten: [{ id: 'M1', x: 0, profil: 'HEB 240', laenge: 8.5 },
               { id: 'M2', x: 15, profil: 'HEB 260', laenge: 12.0 }] }));
    wahr('Jeder traegt sein eigenes Profil',
         hG.includes('HEB 240 \u00b7 8.50 m')
         && hG.includes('HEB 260 \u00b7 12.00 m'));
    /*
     * 6 - DER ANKER HAT KEINE EIGENE ZEILE MEHR (Weisung, 11. September),
     * steht aber im Namen und als Strich auf der Bahn.
     */
    const hA = UIF.querprofilLeisteHtml(joch({
      masten: [{ id: 'M1', x: 0, profil: 'HEB 240', laenge: 8.5,
                 anker: { typ: 'A160', h: 2, a: 3 } },
               { id: 'M2', x: 15, profil: 'HEB 240', laenge: 8.5 }] }));
    wahr('Der Anker steht als Marke an seinem Masten',
         hA.includes('>A160 quer<') && hA.includes('data-qp-anker="M1"'));
    wahr('… und als Strich auf der Bahn',
         hA.includes('qp-ankerstrich'));
    wahr('… aber nicht in einer eigenen Zeile',
         zeilen(hA, 'qp-mastzeile') === 2);
    /* =====================================================================
     * >>> DIE AUSNUTZUNG STEHT IM KUERZEL - WO SIE GERECHNET IST. <<<
     * =====================================================================
     *
     * Weisung vom 13. September: «offene fragen umsetzen» - darunter das
     * angebotene eta je Bauteil.
     *
     * Gerechnet wird das AKTIVE Tragwerk; eine volle Huellkurve kostet
     * nachgemessen 32 ms, bei drei Tragwerken also hundert Millisekunden bei
     * jedem Tastendruck. Die uebrigen Zeilen tragen deshalb einen STRICH -
     * nicht nichts. Eine leere Stelle liest sich wie «in Ordnung».
     */
    UIF.setzeEtaFuerLeiste({ twId: 'T1', tragwerk: 0.45,
                             masten: { M1: 0.98, M2: 1.07 } });
    const hEta = UIF.querprofilLeisteHtml(joch());
    const marken = [...hEta.matchAll(/class="qp-eta ([a-z]+)"[^>]*>([^<]*)</g)]
      .map((m) => `${m[2].trim()} [${m[1]}]`);
    wahr('Das gerechnete Tragwerk traegt seine Zahl',
         marken[0] === 'η 0.45 [ok]', marken.join(' | '));
    wahr('Der knappe Mast steht als Warnung da', marken[1] === 'η 0.98 [warn]');
    wahr('Der ueberschrittene als Fehler', marken[2] === 'η 1.07 [fail]');
    /*
     * DIE SCHWELLE BEI 0.95 ist keine Norm, sondern eine Warnung vor dem
     * Rand: wer bei 0.97 steht, soll es sehen, bevor eine Laenge um zehn
     * Zentimeter waechst.
     */
    UIF.setzeEtaFuerLeiste({ twId: 'T1', tragwerk: 0.95, masten: {} });
    wahr('Genau auf der Schwelle ist es noch erfuellt',
         /class="qp-eta ok"[^>]*>η 0.95/.test(UIF.querprofilLeisteHtml(joch())));
    /*
     * OHNE GERECHNETE ZAHL EIN STRICH, und der Titel sagt warum.
     */
    UIF.setzeEtaFuerLeiste(null);
    const hOhne = UIF.querprofilLeisteHtml(joch());
    wahr('Ohne Rechnung stehen ueberall Striche',
         (hOhne.match(/class="qp-eta leer"/g) ?? []).length === 3,
         `${(hOhne.match(/class="qp-eta leer"/g) ?? []).length} Striche`);
    wahr('… und sagen, dass nicht gerechnet wurde',
         hOhne.includes('nicht gerechnet'));
    /*
     * EIN ANDERES TRAGWERK BEKOMMT KEINE FREMDE ZAHL. Das ist die Falle
     * dieser Loesung: `etaLeiste` liegt im Modul und ueberlebt den
     * Neuaufbau der Maske.
     */
    UIF.setzeEtaFuerLeiste({ twId: 'T2', tragwerk: 0.45, masten: {} });
    wahr('Die Zahl gilt nur ihrem Tragwerk',
         (UIF.querprofilLeisteHtml(joch()).match(/class="qp-eta leer"/g) ?? [])
           .length === 3);
    UIF.setzeEtaFuerLeiste(null);

    /*
     * >>> KEINE FELDWEITEN MEHR. <<<
     *
     * Am 13. September gebaut und am selben Tag wieder heraus - Weisung:
     * «feldweite angabe ueberfluessig.» Die Weite zwischen zwei Masten IST
     * die Stuetzweite ihres Jochs, und die steht eine Zeile hoeher im
     * Namen. Die Kontrolle bleibt als Schranke: wer sie wieder einbaut,
     * faellt hier auf.
     */
    wahr('Die Leiste zeigt keine Feldweiten',
         !UIF.querprofilLeisteHtml(joch()).includes('qp-kette'));
    /*
     * >>> DER JOCHSTRICH IST SO DICK WIE DER MASTSTRICH. <<<
     *
     * Weisung vom 13. September: «den strich fuer das joch weniger dick
     * machen, ist gleich wichtig wie mast bauteil.» Der Balken war vier
     * Pixel hoch, der Maststrich zwei breit - ein Bauteil, das doppelt so
     * fett gezeichnet ist, liest sich als das wichtigere.
     *
     * DIE FALLE dabei ist die Trefferflaeche: ein zwei Pixel hoher Knopf
     * ist mit der Maus nicht zu treffen. Sie kommt aus durchsichtigen
     * Raendern, und die Farbe bleibt ueber `background-clip` im Inhalt.
     * Wer die Regel spaeter aufraeumt, faellt hier auf.
     */
    const cssL = readFileSync(join(HIER, 'css', 'style.css'), 'utf8');
    const regel = (name) => {
      const i = cssL.indexOf(`\n.${name} {`);
      return i < 0 ? '' : cssL.slice(i, cssL.indexOf('}', i));
    };
    const px = (s, feld) => {
      const m = new RegExp(`${feld}:\\s*(\\d+(?:\\.\\d+)?)px`).exec(s);
      return m ? Number(m[1]) : NaN;
    };
    const rL = regel('qp-linie');
    const rM = regel('qp-mast-marke');
    pruef('Der Jochstrich ist so dick wie der Maststrich',
          px(rL, 'height'), px(rM, 'width'), 1e-12, 'px');
    wahr('… und behaelt seine Trefferflaeche',
         /border-top:\s*4px solid transparent/.test(rL)
         && /background-clip:\s*content-box/.test(rL), rL.trim().slice(0, 60));

    /*
     * 6b - EIN EINZELMAST IST SEIN TRAGWERK - KEINE ZWEITE ZEILE.
     *
     * Bei einer Bauform mit EINEM Masten sind Tragwerk und Mast dasselbe
     * Bauteil; zweimal «HEB 260 · 7.50 m» untereinander ist keine
     * Gleichwertigkeit, sondern Rauschen. Dann schreibt die Tragwerkslinie
     * die Lage an - sonst stuende sie nirgends.
     */
    const einz = (extra = {}) => ({
      ...standardwerte(), tragwerksart: 'einzelmast', xLage: 4, mastH: 7.5,
      jd: 0, mastProfil: 'HEB 260', mastVorhanden: true, ...extra });
    const hE = UIF.querprofilLeisteHtml(einz());
    wahr('Der Einzelmast bekommt keine zweite Zeile',
         zeilen(hE, 'qp-mastzeile') === 0);
    wahr('… und seine Lage steht in seiner Zeile',
         hE.includes('class="qp-lage">4.00<'));
    /*
     * AUSNAHME ANKER: er haengt am Masten, nicht am Tragwerk, und sein
     * Strich braucht eine Bahn.
     */
    const hEA = UIF.querprofilLeisteHtml(einz({
      masten: [{ id: 'M1', x: 4, profil: 'HEB 260', laenge: 8,
                 anker: { typ: 'A160', h: 2, a: 3 } }] }));
    // Seit dem Baum: der Anker steht als Marke in der Zeile des Einzelmasts.
    wahr('Mit Anker bleibt es eine Zeile, der Anker steht darin',
         zeilen(hEA, 'qp-mastzeile') === 0 && hEA.includes('>A160 quer<'));
    wahr('… und traegt den Ankerstrich', hEA.includes('qp-ankerstrich'));
    /*
     * 7 - WAS NICHT VERLOREN GEHEN DARF: Name UND Symbol waehlen den
     * Masten an, beide tragen `data-qp-mast` (wie beim Joch Name und
     * Linie), und der volle Text steht im Titel.
     */
    wahr('Name und Symbol fuehren beide auf den Masten',
         (h.match(/data-qp-mast="/g) ?? []).length === 4);
    wahr('… und nennen seine Lage im Titel',
         h.includes('bei x = 0.00 m') && h.includes('bei x = 15.00 m'));
  }

  /* =========================================================================
   * >>> WER TRAEGT WEN, UND WIE HOCH SCHLIESST ES AN. <<<
   * =========================================================================
   *
   * Frage vom 13. September: «was koennte eine uebersicht verbessern?»
   *
   * Zwei Angaben fehlten, und beide standen bestenfalls im Titel unter dem
   * Zeiger:
   *
   *   1. WEN DER MAST TRAEGT. «M2 · MAST ⊕» sagte «geteilt», nicht von wem.
   *      Auf einer Jochreihe ist das die wichtigste Angabe ueberhaupt.
   *   2. DIE ANSCHLUSSHOEHE. Die Zeile zeigte Profil und GESAMTLAENGE; im
   *      Querprofil gefragt ist die Unterkante des Jochs - und seit dem
   *      12. September gibt es dazu den Fusspunkt.
   */
  {
    const UIF = await import(J('ui.js'));
    const reihe = {
      ...standardwerte(), tragwerksart: 'joch', typ: 'J100', L: 20, xLage: 0,
      mastH: 7.5, jd: 500, mastProfil: 'HEB 240', mastVorhanden: true,
      twId: 'T1',
      weitere: [{ id: 'T2', tragwerksart: 'joch', typ: 'J90', L: 15,
                  xLage: 20, mastH: 7.5, jd: 500, mastProfil: 'HEB 260',
                  mastVorhanden: true }],
    };
    const h = UIF.querprofilLeisteHtml(reihe);
    /*
     * 1 - DIE TRAEGER STEHEN IM KUERZEL.
     */
    // Seit dem Baum (19. September): die Masten stehen unter ihrem Tragwerk,
    // der geteilte einmal, beim ersten, mit «auch T2».
    const at = (s) => h.indexOf(s);
    wahr('Die Masten stehen unter ihrem Tragwerk',
         at('>T1</b>') < at('>M1</b>') && at('>M1</b>') < at('>M2</b>')
         && at('>M2</b>') < at('>T2</b>') && at('>T2</b>') < at('>M3</b>'));
    wahr('Der Zwischenmast steht einmal und nennt den Nachbarn',
         (h.match(/>M2<\/b>/g) ?? []).length === 1 && h.includes('>auch T2<'));
    /*
     * DAS ZEICHEN ⊕ IST WEG - es sagte «geteilt», und das sagen jetzt die
     * Namen. Zwei Zeichen fuer dieselbe Aussage sind eines zuviel.
     */
    wahr('Das Zeichen für «geteilt» ist raus', !h.includes('⊕'));
    /*
     * BEI EINEM EINZIGEN TRAGWERK bleibt es weg: «M1 · MAST · P1» waere
     * eine Angabe ohne Alternative.
     */
    const eines = UIF.querprofilLeisteHtml({
      ...standardwerte(), tragwerksart: 'joch', typ: 'J100', L: 15, xLage: 0,
      mastH: 7.5, jd: 500, mastProfil: 'HEB 240', mastVorhanden: true });
    wahr('Steht nur ein Tragwerk da, nennt der Mast keinen Nachbarn',
         eines.includes('>M1</b>') && !eines.includes('>auch '));
    /*
     * 2 - DIE ANSCHLUSSHOEHE, UND DER FUSSPUNKT NUR WENN ER EINER IST.
     */
    wahr('Die Anschlusshoehe steht da',
         (h.match(/H 7\.50 m/g) ?? []).length === 3);
    wahr('Ohne Fussversatz steht kein Fusspunkt da', !h.includes('Fuss'));
    const hF = UIF.querprofilLeisteHtml({
      ...reihe,
      masten: [{ id: 'M1', x: 0, profil: 'HEB 240', laenge: 8.5, fuss: -0.4 },
               { id: 'M2', x: 20, profil: 'HEB 240', laenge: 8.5 },
               { id: 'M3', x: 35, profil: 'HEB 260', laenge: 8.5 }] });
    wahr('Ein Fussversatz steht mit Vorzeichen da',
         hF.includes('Fuss −0.40 m'));
    wahr('… und nur an SEINEM Masten',
         (hF.match(/Fuss /g) ?? []).length === 1);
    /*
     * DER ANKER STEHT IN DERSELBEN ZEILE - er hat keine eigene mehr
     * (Weisung, 11. September).
     */
    const hA = UIF.querprofilLeisteHtml({
      ...reihe,
      masten: [{ id: 'M1', x: 0, profil: 'HEB 240', laenge: 8.5,
                 anker: { typ: 'A160', h: 2, a: 3 } },
               { id: 'M2', x: 20, profil: 'HEB 240', laenge: 8.5 },
               { id: 'M3', x: 35, profil: 'HEB 260', laenge: 8.5 }] });
    wahr('Der Anker steht neben der Hoehe', hA.includes('A160 quer'));
    /*
     * 3 - ZWEI AUSWAHLEN, ZWEI STAERKEN.
     *
     * «warum m2 anders?» - M1 war angewaehlt, M2 nicht. Der Grund war
     * richtig, die Darstellung nicht: Tragwerk UND Mast trugen denselben
     * Flaechenton. Das gerechnete Tragwerk behaelt ihn, der angewaehlte
     * Mast bekommt einen schmalen Balken.
     */
    const css = readFileSync(join(HIER, 'css', 'style.css'), 'utf8');
    const regel = /\.qp-zeile\.qp-mastzeile\.an\s*\{([^}]*)\}/.exec(css)?.[1] ?? '';
    wahr('Die Mastauswahl hat eine eigene Regel', Boolean(regel.trim()));
    wahr('… ohne Flaechenton', /background:\s*none/.test(regel));
    wahr('… dafuer mit einem Balken', /inset 2px 0 0/.test(regel));
    // Und das Tragwerk behaelt seinen - sonst waere nichts gewonnen.
    const twRegel = /\.qp-zeile\.an\s*\{([^}]*)\}/.exec(css)?.[1] ?? '';
    wahr('Das gerechnete Tragwerk behaelt die Flaeche',
         /background:\s*var\(--acc-s\)/.test(twRegel));
  }

  /*
   * >>> DAS MASTSYMBOL STEHT AUF SEINER STELLE. <<<
   *
   * Weisung vom 13. September: «das jochende ist versetzt im bezug zum
   * masten.» Im Browser nachgemessen: die Jochlinie begann bei 147.5 px,
   * die Mitte des Mastsymbols lag bei 136.5 - elf Pixel daneben, genau die
   * halbe Symbolbreite.
   *
   * `.qp-mast` traegt `transform: translateX(-50%)`, weil es sonst mit
   * seiner linken Kante auf der Prozentstelle saesse. In der Mastreihe
   * sitzt es aber IN der Gruppe, und die ist schon auf die Stelle
   * zentriert: ohne `left: 50%` bleibt es an seiner statischen Position
   * stehen, und die Verschiebung zieht es zusaetzlich nach links.
   *
   * DAS IST EINE ZEILE CSS UND EIN FEHLER, DEN MAN NICHT RECHNET, SONDERN
   * SIEHT. Geprueft wird deshalb die Regel selbst - eine Textkontrolle, wie
   * an den uebrigen Stellen, an denen Zeichnung und Zahl zusammenpassen
   * muessen.
   */
  {
    const css = readFileSync(join(HIER, 'css', 'style.css'), 'utf8');
    const regel = /\.qp-mastgruppe\s+\.qp-mast\s*\{([^}]*)\}/.exec(css)?.[1] ?? '';
    wahr('Die Regel der Mastgruppe steht da', Boolean(regel.trim()));
    wahr('… und setzt das Symbol auf die Mitte der Gruppe',
         /left:\s*50%/.test(regel), regel.trim());
    // Und die Gruppe selbst sitzt mittig auf ihrer Stelle - sonst waere die
    // Mitte der Gruppe nicht die Stelle.
    const gruppe = /\.qp-mastgruppe\s*\{([^}]*)\}/.exec(css)?.[1] ?? '';
    wahr('Die Gruppe ist auf ihre Stelle zentriert',
         /translateX\(-50%\)/.test(gruppe));
    // Das Symbol nimmt die halbe Breite wieder zurueck.
    const mast = /\n\.qp-mast\s*\{([^}]*)\}/.exec(css)?.[1] ?? '';
    wahr('Das Symbol nimmt die halbe Breite zurueck',
         /translateX\(-50%\)/.test(mast));
  }

  /*
   * >>> DIE BEIDEN AUSSCHNITTE HABEN EIGENE SYMBOLE. <<<
   *
   * Weisung vom 3. September: «kannst du zutreffendere symbole fuer diese
   * buttons finden.» Vorher standen dort eine Lupe und vier Ecken nach
   * aussen - beides sagt «zoom» und keines sagt, WORAUF. Die Frage ist aber
   * nicht die Vergroesserung, sondern der Ausschnitt.
   */
  {
    const { ICONS } = await import(J('design.js'));
    wahr('Es gibt ein Symbol fuer das ganze Querprofil',
         Boolean(ICONS.querprofilGanz));
    wahr('… und eines fuer das einzelne Tragwerk',
         Boolean(ICONS.querprofilEines));
    wahr('Beide sind verschieden',
         ICONS.querprofilGanz !== ICONS.querprofilEines);
    /*
     * DER EIGENTLICHE BRUCHPUNKT: Name und Definition muessen zusammen
     * passen. `icon('tippfehler')` liefert klaglos ein LEERES Bildchen -
     * der Knopf steht dann ohne Zeichen da, und niemand bemerkt es beim
     * Umbenennen.
     */
    const { icon: ic } = await import(J('design.js'));
    for (const n of ['querprofilGanz', 'querprofilEines']) {
      wahr(`${n} zeichnet wirklich`, ic(n).includes(ICONS[n]));
    }
    // Und die alten stehen noch fuer ihre eigenen Stellen.
    wahr('Lupe und Aufziehen bleiben erhalten',
         Boolean(ICONS.zoom) && Boolean(ICONS.aufziehen));
  }

  /*
   * >>> EIN MAST, EIN KOERPER. <<<
   *
   * Auf einer Jochreihe traegt der Zwischenmast zwei Tragwerke - und bis
   * zum 3. September baute JEDES von beiden ihn in seine Szene. Zwei
   * Koerper an derselben Stelle geben flackernde Flaechen, doppelte
   * Windpfeile und ein Bild, dem man nicht ansieht, was davon eines ist.
   *
   * Gemeldet als: «die darstellung des masten hier bei der
   * zwischenabstuetzung scheint nicht sauber modelliert zu sein, ich denke
   * das ist noch ein ueberbleibsel der geteilten masten auslegung.»
   */
  {
    const w = reihe();                       // P1: 0-20, P2: 20-35
    const masten = C75.mastenVon(w);
    const geteilt = masten.filter((m) => (m.traegt ?? []).length > 1);
    wahr('Die Reihe hat einen geteilten Masten', geteilt.length === 1);

    /*
     * DAS GERECHNETE TRAGWERK HAT VORRANG.
     *
     * Nur seine Szene faerbt nach Ausnutzung ein. Waehlte man den anderen,
     * verloere der Mast seine Farbe - er stuende da, als sei er nicht
     * nachgewiesen.
     */
    const p1 = C75.mastZeichenplan(w, 'T1');
    wahr('T1 zeichnet beide seiner Enden', p1.T1.A && p1.T1.B);
    wahr('T2 laesst das geteilte Ende weg', p1.T2.A === false);
    wahr('… und zeichnet sein freies', p1.T2.B === true);

    // Und umgekehrt, wenn T2 gerechnet wird.
    const p2 = C75.mastZeichenplan(w, 'T2');
    wahr('T2 zeichnet dann beide', p2.T2.A && p2.T2.B);
    wahr('T1 laesst das geteilte Ende weg', p1.T1.B !== p2.T1.B);
    wahr('… naemlich sein Ende B', p2.T1.B === false);
    wahr('Sein freies Ende bleibt', p2.T1.A === true);

    /*
     * JEDER MAST WIRD GENAU EINMAL GEZEICHNET - das ist die eigentliche
     * Aussage, und sie laesst sich zaehlen.
     */
    for (const aktiv of ['T1', 'T2']) {
      const p = C75.mastZeichenplan(w, aktiv);
      let n = 0;
      for (const t of C75.tragwerkeSortiert(w)) {
        if (p[t.id].A) n += 1;
        if (p[t.id].B) n += 1;
      }
      pruef(`Bei ${aktiv} so viele Koerper wie Masten`, n, masten.length,
            1e-9, 'Stk');
    }

    /*
     * OHNE GETEILTEN MASTEN AENDERT SICH NICHTS.
     *
     * Ein einzelnes Tragwerk zeichnet beide Enden wie zuvor - sonst haette
     * die Kur den Regelfall beschaedigt.
     */
    const allein = { typ: 'J90', L: 20, xLage: 0, mastProfil: 'HEB 240',
                     mastH: 8, mastLaenge: 12 };
    const pa = C75.mastZeichenplan(allein, 'T1');
    wahr('Ein einzelnes Tragwerk zeichnet beide Enden',
         pa.T1.A === true && pa.T1.B === true);
  }

  /*
   * >>> DIE SZENE EINES TRAGWERKS BLEIBT IN SEINEN GRENZEN. <<<
   *
   * Gemeldet am 3. September mit Bild: «hier der screenshot mit den
   * ueberstehenden lastflaechen und schwerelinien, die nicht sauber
   * ausgeblendet werden.» Der Verdacht war, die Teile seien nicht je
   * Jochtraeger zugeschnitten.
   *
   * Nachgemessen sind sie es: nur die halbe Blech- und Mastdicke ragt ueber
   * die Grenze, und das muss sie - ein Bauteil auf der Achse steht zur
   * Haelfte davor. Was fehlte, war das AUSBLENDEN: der Knopf «nur das
   * gerechnete Tragwerk» fuhr bloss die Kamera heran, der Nachbar stand
   * weiter da. Seither ruft er `nurDiesesZeigen`.
   *
   * Diese Kontrolle haelt die gemessene Aussage fest. Liefe eine Linie oder
   * eine Lastflaeche je ueber ihr Tragwerk hinaus, waere das Ausblenden
   * wieder wirkungslos - und man saehe es an dieser Stelle.
   */
  {
    const w = { ...standardwerte(), L: 20 };
    const e = rechne(w);
    const sz = R75.erzeugeSzene(e.modell, e);
    const L = e.modell.L;
    /*
     * Bauteile stehen zur Haelfte vor der Achse - ein Zehntelmeter Luft.
     *
     * SEIT DEM 11. SEPTEMBER MEHR (Weisung: «die fundamentkoepfe vertikal
     * machen und etwas doppel so dick wie den masten darstellen»). Der
     * Fundamentkopf ist doppelt so breit wie der Mast und steht am Jochende;
     * er ragt damit ueber die Tragwerkslaenge hinaus - und das ist richtig,
     * ein Fundament IST breiter als sein Mast. Beim HEB 240 sind es 0.24 m
     * je Seite.
     *
     * Die Kontrolle soll weiter fangen, was WIRKLICH danebensteht: eine
     * Lastflaeche des Nachbarjochs, eine Linie ueber das halbe Blatt. Dafuer
     * genuegt ein halber Meter.
     */
    const LUFT = 0.5;
    const xVon = (t) => {
      const v = [];
      const gehe = (a) => {
        if (!Array.isArray(a)) return;
        if (typeof a[0] === 'number') { v.push(a[0]); return; }
        a.forEach(gehe);
      };
      gehe(t.punkte ?? t.poly ?? (t.p ? [t.p] : null));
      return v.length ? [Math.min(...v), Math.max(...v)] : null;
    };
    for (const feld of ['linien', 'lastflaechen', 'vektoren', 'marken',
                        'flaechen']) {
      const liste = sz[feld] ?? [];
      const raus = liste.filter((t) => {
        const b = xVon(t);
        return b && (b[0] < -LUFT || b[1] > L + LUFT);
      });
      wahr(`${feld}: nichts ragt aus dem Tragwerk`, raus.length === 0);
    }
    // Und die Systemachse endet genau am Tragwerk, nicht am Blattrand.
    const achsen = (sz.linien ?? []).filter((t) => t.gruppe === 'achse');
    wahr('Es gibt Achsenlinien', achsen.length > 0);
    wahr('Sie enden am Tragwerk',
         achsen.every((t) => {
           const b = xVon(t);
           return !b || (b[0] >= -LUFT && b[1] <= L + LUFT);
         }));
  }

  /*
   * >>> DIE GURTPROFILE DER ABFANGJOCHE. <<<
   *
   * Der Winkelkatalog traegt das Tragjoch; das Abfangjoch braucht UPE und
   * IPE, und die standen bis zum 3. September nirgends. Es sind NORMWERTE
   * (EN 10365 / DIN 1026-2), keine gemessenen - geprueft wird deshalb, ob
   * sie zu sich selbst passen.
   */
  {
    const PR = await import(J('data.profiles.js'));
    /*
     * ACHT, seit IPE 240 dazukam - es ist kein Gurtprofil, sondern die
     * QUERSTEIFE von A240. Die Tabelle traegt beide Rollen, weil beide
     * dieselben Werte brauchen.
     */
    wahr('Acht Walzprofile', PR.GURTPROFILE().length === 8);
    wahr('IPE 240 ist dabei - die Quersteife von A240',
         PR.GURTPROFILE().some((p) => p.name === 'IPE 240'));
    /*
     * DIE SCHAERFSTE PLAUSIBILITAETSPRUEFUNG, DIE ES HIER GIBT:
     * Flaeche mal Wichte muss das Laufmetergewicht ergeben. Ein Tippfehler
     * in A oder G faellt damit sofort auf - und beide gehen in den Nachweis.
     */
    for (const p of PR.GURTPROFILE()) {
      pruef(`${p.name}: A x 7.85 ergibt G`, p.A * 0.785, p.G, p.G * 0.005,
            'kg/m');
    }
    // Und die Hauptmasse stimmen mit den Sortimentsblaettern ueberein.
    for (const t of AJ.abfangjoche().filter((x) => x.aufbau)) {
      const p = PR.getGurtprofil(t.aufbau.gurtprofil);
      pruef(`${t.typ}: Profilhoehe wie im Blatt`, p.h * 10, t.aufbau.a,
            0.5, 'mm');
      pruef(`${t.typ}: Flanschbreite wie im Blatt`, p.b * 10, t.aufbau.b,
            0.5, 'mm');
      /*
       * >>> UND c IST DIE FLANSCHDICKE. <<<
       *
       * Erste Lesart war «Stegdicke». Falsch - bei UPE 160 steht c = 9.5,
       * und das ist t_f; t_w waere 5.5. Wer damit rechnet, setzt fast die
       * halbe Dicke an.
       */
      pruef(`${t.typ}: c ist die Flanschdicke`, p.tf * 10, t.aufbau.c,
            0.05, 'mm');
    }

    /*
     * >>> DER HEBELARM IST NICHT k. <<<
     *
     * k ist das Aussenmass ueber beide Gurte; der Hebelarm der Vierendeel-
     * Wirkung ist der Abstand der SCHWERACHSEN. Beim UPE liegt die Achse um
     * e_y innerhalb des Stegruckens, beim IPE in der Profilmitte.
     *
     * Bei A160 sind das 38.3 statt 42.0 cm, bei A270 73.5 statt 87.0 - neun
     * bis fuenfzehn Prozent, und sie gehen VOLL ins Moment. Mit k gerechnet
     * laege der Nachweis auf der unsicheren Seite.
     */
    pruef('A160: Achsabstand statt Aussenmass',
          PR.gurtAchsabstand('UPE 160', 42.0), 42.0 - 2 * 1.84, 1e-9, 'cm');
    /*
     * >>> BEIM I IST `d` SCHON DER ACHSABSTAND. <<<
     *
     * Weisung vom 4. September: «Die 600 sind bei den IPE Typen auf die
     * schwerelinie bezogen und bei den UPE auf die aussenkante.» Der Steg
     * eines I liegt in der Mitte - das Mass zwischen den Stegen ist damit
     * das Mass zwischen den Schwerelinien.
     *
     * Hier stand `k - b`, und das las `d` als lichte Weite. Bei A270 lag der
     * Hebelarm damit auf 735 statt 600 mm - zweiundzwanzig Prozent zu gross,
     * auf der unsicheren Seite.
     */
    pruef('A270: das Mass d ist der Achsabstand',
          PR.gurtAchsabstand('IPE 270', 73.5, 60.0), 60.0, 1e-9, 'cm');
    pruef('… ohne d bleibt die Naeherung k - b',
          PR.gurtAchsabstand('IPE 270', 73.5), 73.5 - 13.5, 1e-9, 'cm');
    for (const t of AJ.abfangjoche().filter((x) => x.aufbau)) {
      const k = t.aufbau.k / 10;
      const e = PR.gurtAchsabstand(t.aufbau.gurtprofil, k);
      wahr(`${t.typ}: der Hebelarm ist kleiner als k`, e < k && e > 0.6 * k);
    }
    /*
     * DIE DREI MASSE DER DRAUFSICHT GEHEN INEINANDER AUF: aussen ueber die
     * Flanschspitzen, die Schwerelinien, licht. Bei A270 735 | 600 | 465,
     * und das Regelbindeblech misst 463.
     */
    for (const t of AJ.abfangjoche().filter(
      (x) => x.aufbau && x.aufbau.gurtprofil.startsWith('IPE'))) {
      const a2 = t.aufbau;
      pruef(`${t.typ}: der Achsabstand ist d`,
            PR.gurtAchsabstand(a2.gurtprofil, a2.k / 10, a2.d / 10),
            a2.d / 10, 1e-9, 'cm');
      pruef(`${t.typ}: aussen ist d + b`, a2.k, a2.d + a2.b, 1e-9, 'mm');
      pruef(`${t.typ}: licht ist d - b`, AJ.abfangLichtFeld(t.typ),
            a2.d - a2.b, 1e-9, 'mm');
      wahr(`${t.typ}: und das Regelblech trifft licht`,
           Math.abs(AJ.abfangBindeblech(t.typ).regel.l
                    - AJ.abfangLichtFeld(t.typ)) < 5);
    }
  }

  /*
   * >>> DIE MASTNAMEN BLEIBEN UEBER DAS AUSBLENDEN HINWEG STEHEN. <<<
   *
   * Weisung vom 3. September: «namen ueber ausblenden hinweg stabil halten,
   * sonst fuehrt es zu missverstaendnissen.»
   *
   * Die Id eines Masten IST seine Laufnummer, und sie wurde nur ueber die
   * SICHTBAREN Tragwerke vergeben. Wer den linken Nachbarn beiseitelegte,
   * sah M2 zu M1 werden und M3 zu M2 - derselbe Mast hiess je nach Ansicht
   * anders, und die Nachweise nannten ihn beim falschen Namen.
   */
  {
    const w = reihe();                       // P1: 0-20, P2: 20-35
    const vorher = C75.mastenVon(w).map((m) => C75.mastName(w, m));
    wahr('Drei Masten, M1 bis M3',
         vorher.join(',') === 'M1,M2,M3');

    // Den linken Nachbarn beiseitelegen.
    const ohne = { ...w, weitere: (w.weitere ?? []).map(
      (t) => ({ ...t, ausgeblendet: true })) };
    const nachher = C75.mastenVon(ohne);
    wahr('Danach stehen zwei im Bild', nachher.length === 2);
    const namen = nachher.map((m) => C75.mastName(ohne, m));
    wahr('Und sie heissen weiterhin M2 und M3',
         namen.join(',') === 'M2,M3');

    /*
     * DER GETEILTE MAST BLEIBT SICHTBAR. Ihn traegt auch das sichtbare
     * Tragwerk - er verschwindet nicht, nur weil der Nachbar weg ist.
     */
    wahr('Der geteilte Mast steht weiter da',
         nachher.some((m) => Math.abs(m.x - 20) < 1e-6));
    // Und er hat seine Angaben behalten: die Zuordnung laeuft ueber die
    // Stelle und passiert VOR dem Weglassen der versteckten.
    const geteiltVor = C75.mastenVon(w).find((m) => Math.abs(m.x - 20) < 1e-6);
    const geteiltNach = nachher.find((m) => Math.abs(m.x - 20) < 1e-6);
    wahr('… mit demselben Profil',
         geteiltVor.profil === geteiltNach.profil);

    // Mit `mitVersteckten` kommen alle - daran haengt die Nummernvergabe.
    wahr('Alle drei sind weiterhin abrufbar',
         C75.mastenVon(ohne, 0.1, true).length === 3);
    wahr('Der ausgeblendete ist als solcher gekennzeichnet',
         C75.mastenVon(ohne, 0.1, true).filter((m) => m.versteckt).length === 1);
  }

  /*
   * ===================================================================
   * DER RECHENKERN DES ABFANGJOCHS - erster Baustein.
   * ===================================================================
   *
   * Weisung vom 3. September: liegender Vierendeeltraeger, als einfacher
   * Balken abgebildet, mit der Umrechnung auf die einzelnen Gurte.
   */
  {
    const AK = await import(J('core.abfangjoch.js'));
    const PR = await import(J('data.profiles.js'));

    /*
     * >>> e IST NICHT k. <<<
     *
     * Der Hebelarm ist der Abstand der SCHWERACHSEN. Mit dem Aussenmass zu
     * rechnen laege neun bis fuenfzehn Prozent auf der unsicheren Seite.
     */
    for (const t of AJ.abfangjoche().filter((x) => x.aufbau)) {
      const q = AK.abfangQuerschnitt(t.typ);
      wahr(`${t.typ}: e ist kleiner als k`, q.e < q.k);
      /*
       * >>> DIE U-PROFILE ZEIGEN NACH AUSSEN. <<<
       *
       * Weisung vom 3. September nach Blick ins AxisVM-Modell. Der Schnitt
       * A-A bestaetigt es: die STEGE liegen innen im Abstand d, die
       * Flansche zeigen nach aussen, und die Schwerachse liegt um e_y
       * weiter aussen. Hier stand `gurtAchsabstand(gurt, k)` ohne d - das
       * ist die umgekehrte Lage und gab bei A160 38.3 statt 31.7 cm.
       */
      pruef(`${t.typ}: e stimmt mit gurtAchsabstand`,
            q.e, PR.gurtAchsabstand(q.gurt, q.k, q.d), 1e-9, 'cm');
      // Die Gegenprobe der Geometrie: d/2 + b = k/2.
      if (q.gurt.reihe === 'UPE') {
        pruef(`${t.typ}: d/2 + b ergibt k/2`,
              q.d / 2 + q.gurt.b, q.k / 2, 1e-9, 'cm');
        // Und der Hebelarm liegt zwischen d und k - naeher an d.
        wahr(`${t.typ}: e liegt zwischen d und k`, q.e > q.d && q.e < q.k);
      }
      /*
       * DER STEINER-ANTEIL IST HIER ALLES. Bei A160 ist I_z des Gurtes
       * 85 cm4, der Steiner-Anteil 16 100 - das Zweihundertfache. Faellt
       * das je unter das Zehnfache, stimmt etwas an der Geometrie nicht.
       */
      const steiner = 2 * q.gurt.A * (q.e / 2) ** 2;
      const eigen = 2 * q.gurt.Iz;
      wahr(`${t.typ}: der Steiner-Anteil traegt`, steiner > 10 * eigen);
      pruef(`${t.typ}: I_rahmen ist Eigen + Steiner`,
            q.Irahmen, eigen + steiner, 1e-6, 'cm4');
      // Und die Flaeche ist die zweier Gurte - nicht mehr, nicht weniger.
      pruef(`${t.typ}: A ist zweimal der Gurt`, q.A, 2 * q.Agurt, 1e-9, 'cm2');
    }
    // Ueber das Sortiment waechst der Querschnitt durchweg.
    const reihe6 = ['A160', 'A200', 'A240', 'A270', 'A300', 'A330', 'A360']
      .map((x) => AK.abfangQuerschnitt(x));
    for (let i = 1; i < reihe6.length; i++) {
      wahr(`${reihe6[i].typ} ist steifer als ${reihe6[i - 1].typ}`,
           reihe6[i].Irahmen > reihe6[i - 1].Irahmen);
    }

    /*
     * >>> DIE UMRECHNUNG AUF DIE GURTE: N = M / e. <<<
     *
     * Das Kraeftepaar ist die Vierendeel-Annahme. Gegengerechnet von Hand:
     * bei A160 (e = 38.3 cm) und M = 50 kNm sind das 50 / 0.383 = 130.5 kN.
     */
    const qA = AK.abfangQuerschnitt('A160');
    const kr = AK.abfangGurtkraefte(50, qA.e);
    pruef('A160: Gurtkraft bei M = 50 kNm', kr.N, 50 / (qA.e / 100), 1e-9, 'kN');
    pruef('… von Hand nachgerechnet', kr.N, 130.5, 0.6, 'kN');
    wahr('Zug und Druck sind gleich gross und entgegengesetzt',
         Math.abs(kr.zug + kr.druck) < 1e-9 && kr.zug > 0);
    // Doppeltes Moment, doppelte Kraft - die Beziehung ist linear.
    pruef('Doppeltes Moment gibt doppelte Kraft',
          AK.abfangGurtkraefte(100, qA.e).N, 2 * kr.N, 1e-9, 'kN');
    // Ein groesserer Hebelarm entlastet die Gurte.
    const qB = AK.abfangQuerschnitt('A360');
    wahr('Der groessere Typ hat kleinere Gurtkraefte',
         AK.abfangGurtkraefte(50, qB.e).N < kr.N);

    /*
     * QUER ZUR EBENE: jeder Gurt fuer sich, halbe Last (Weisung).
     */
    pruef('Die Querlast teilt sich haelftig',
          AK.abfangLastQuer(3.4).jeGurt, 1.7, 1e-9, 'kN/m');

    /*
     * >>> jt IST NICHT js. <<<
     *
     * Mit der Jochlaenge statt der Stuetzweite zu rechnen ueberschaetzt das
     * Feldmoment um das Quadrat des Verhaeltnisses - bei A160/9.50 waeren
     * das elf Prozent auf der unsicheren Seite.
     */
    const sw = AK.abfangStuetzweite('A160', 9.5);
    wahr('Die Stuetzweite ist kleiner als die Jochlaenge', sw.bis < 9.5);
    pruef('A160/9.50 spannt bis 9.00 m', sw.bis, 9.0, 1e-9, 'm');
    wahr('Eine ungefuehrte Laenge hat keine Stuetzweite',
         AK.abfangStuetzweite('A160', 9.7) === null);

    /*
     * >>> DIE BLECHZAHL KOMMT AUS DER STUECKLISTE. <<<
     *
     * Der erste Versuch leitete sie aus QV1 und der Regelteilung ab und lag
     * DURCHWEG 4 BIS 6 BLECHE ZU TIEF (A160/9.5 m: 22 gegen 26). Stehende
     * Vorgabe: massgebend sind die Daten, nicht die Herleitung.
     *
     * Diese Kontrolle ist die Gegenprobe an der Zeichnung selbst.
     */
    const SOLL = { 12.5: 38, 12: 36, 11.5: 34, 11: 32, 10.5: 30, 10: 28,
                   9.5: 26, 9: 24, 8.5: 22, 8: 20, 7.5: 18, 7: 16,
                   6.5: 14, 6: 12, 5.5: 10 };
    let stimmt = 0;
    for (const z of AJ.getAbfangjoch('A160').laengen) {
      const b = AK.abfangBlechstationen('A160', z.jt);
      if (b && b.blecheListe === SOLL[z.jt]) stimmt += 1;
    }
    pruef('A160: alle Laengen fuehren ihre Stueckzahl',
          stimmt, 15, 1e-9, 'Stk');
    /*
     * >>> UND DIE STUECKZAHL IST NICHT MEHR DIE BLECHZAHL. <<<
     *
     * `bleche` zaehlt jetzt die Stationen des SCHEMAS mal zwei, nicht die
     * Regelbleche der Stueckliste. Bei A160 / 9.50 m sind das 32 gegen 26 -
     * der Unterschied sind die drei Stationen in den Endbereichen, die die
     * Stueckliste teils als Sonderbleche fuehrt.
     */
    const b95 = AK.abfangBlechstationen('A160', 9.5);
    wahr('Je Station eines oben und eines unten',
         b95.bleche === b95.anzahl * 2);
    /*
     * >>> DIE STATIONEN FOLGEN DER FELDFOLGE, NICHT EINEM RASTER. <<<
     *
     * Hier stand «jeder Abstand gleich der Regelteilung». Das galt, solange
     * die Lage geschaetzt war. Das Schemablatt zeigt die Felder aber als
     * «A9 A8 ... A2 A1 A1 A2 ... A9»: aussen die Regelteilung, in der MITTE
     * das Paar A1. Bei A160 / 9.50 m sind das zehn Felder zu 500 und zwei
     * zu 250 - die Kontrolle haette den richtigen Fall abgelehnt.
     */
    const abst = b95.stationen.slice(1).map((x, i) => x - b95.stationen[i]);
    /*
     * >>> DIE RANDFELDER SIND WEDER TEILUNG NOCH MITTLERES FELD. <<<
     *
     * Weisung vom 3. September: «Die Masse in den Endbereichen stimmen
     * nicht mit der Zeichnung ueberein.» Zwischen den beiden aeusseren
     * Blechen misst A160 links 550, rechts zweimal 550 - erst dazwischen
     * gilt die Tabelle. Die alte Kontrolle liess nur Teilung oder A1 zu und
     * haette die richtige Lage abgewiesen.
     */
    const innen = abst.slice(1, -2);
    wahr('Im QV-Bereich: Regelteilung oder mittleres Feld',
         innen.every((d) => Math.abs(d - b95.teilung) < 1e-9
                         || Math.abs(d - b95.erstesFeld) < 1e-9));
    wahr('Die Regelteilung steht am Rand des QV-Bereichs',
         Math.abs(innen[0] - b95.teilung) < 1e-9
         && Math.abs(innen.at(-1) - b95.teilung) < 1e-9);
    // Die drei Randfelder stehen so, wie das Schemablatt sie bemasst.
    pruef('Links das zweite Feld: 550 mm', abst[0], 0.55, 1e-9, 'm');
    pruef('Rechts das erste Feld: 550 mm', abst.at(-2), 0.55, 1e-9, 'm');
    pruef('Rechts das zweite Feld: 550 mm', abst.at(-1), 0.55, 1e-9, 'm');
    // Und die Summe der Felder ist die Laenge der Blechreihe.
    pruef('Die Felder decken die Blechreihe',
          abst.reduce((a2, b2) => a2 + b2, 0),
          b95.stationen.at(-1) - b95.stationen[0], 1e-9, 'm');
    wahr('Sie liegen alle im Joch',
         b95.stationen[0] > 0 && b95.stationen.at(-1) < 9.5);
    /*
     * OHNE ERFASSTE STUECKZAHL KOMMT NULL - keine geratene Einteilung.
     * Eine erfundene waere die Grundlage eines Nachweisschnitts, der
     * nirgends steht.
     */
    /*
     * >>> ALLE SIEBEN TYPEN FUEHREN JETZT IHRE STUECKZAHLEN. <<<
     *
     * Nachgetragen am 3. September aus den Konstruktionszeichnungen. Die
     * Reihen sind NICHT linear: bei A240 stehen 48, 36 und 24 je zweimal,
     * weil der Traeger ab dieser Groesse in mehrere Vierendeel-Bereiche
     * gegliedert ist. Genau deshalb waere eine Formel falsch gewesen.
     */
    const neuAlle = AJ.abfangjoche().filter((x) => x.bauweise === 'neu');
    for (const t of neuAlle) {
      wahr(`${t.typ} fuehrt fuer jede Laenge eine Blechzahl`,
           t.laengen.every((z) => z.bleche > 0));
    }
    pruef('158 Laengen mit Blechzahl',
          neuAlle.reduce((n, t) => n + t.laengen.filter(
            (z) => z.bleche > 0).length, 0), 158, 1e-9, 'Stk');
    /*
     * JE STATION ZWEI BLECHE - die Zahl muss GERADE sein. Diese Kontrolle
     * hat den Blattfehler bei A360 gefunden.
     */
    const ungerade = neuAlle.flatMap((t) => t.laengen
      .filter((z) => z.bleche % 2 !== 0)
      .map((z) => `${t.typ}/${z.jt}`));
    wahr('Genau eine Laenge fuehrt eine ungerade Blechzahl',
         ungerade.length === 1 && ungerade[0] === 'A360/21');
    wahr('… und sie ist als fraglich angeschrieben',
         Boolean(AJ.getAbfangjoch('A360').laengen
           .find((z) => z.jt === 21).blechFraglich));
    /*
     * >>> UND SIE WIRD NICHT GERECHNET. <<<
     *
     * 85 Bleche sind bei zwei je Station unmoeglich; der Wert steht
     * zwischen 60 und 56 in einer sonst streng absteigenden Reihe. Ihn
     * stillschweigend zu runden waere eine Zahl, die niemand geprueft hat,
     * in einem Nachweis, dem man es nicht ansieht.
     */
    /*
     * >>> SEIT DEM 3. SEPTEMBER TRAEGT DIE STUECKZAHL DIE LAGE NICHT MEHR. <<<
     *
     * Hier stand «liefert keine Einteilung»: die Stationen wurden aus der
     * Stueckzahl abgeleitet, und eine unmoegliche Zahl gab keine Lage. Seit
     * die Lage aus dem Schema kommt - Randmasse plus Feldfolge aus QV und
     * A1 - ist A360 / 21.00 m wieder rechenbar. Die 85 bleiben fraglich;
     * sie ZAEHLEN Bleche, sie verteilen sie nicht.
     */
    const f21 = AK.abfangBlechstationen('A360', 21.0);
    wahr('Die fragliche Laenge hat trotzdem eine Lage', Boolean(f21));
    wahr('… und sagt, dass ihre Stueckzahl fraglich ist',
         f21.blechFraglich === true);
    wahr('… und gilt wieder als rechenbar',
         AK.abfangRechenbar('A360', 21.0));
    wahr('Ihre Nachbarn ebenso',
         AK.abfangRechenbar('A360', 20.5) && AK.abfangRechenbar('A360', 21.5));
    // 157 von 158 lassen sich rechnen - eine einzige nicht.
    let rechenbar = 0;
    for (const t of neuAlle) {
      for (const z of t.laengen) {
        if (AK.abfangBlechstationen(t.typ, z.jt)) rechenbar += 1;
      }
    }
    /*
     * ALLE 158 - vorher waren es 157, und die Lage galt nur bei zwanzig als
     * belegt. Beides haengt an derselben Aenderung: die Feldzahl folgt aus
     * QV und A1, nicht aus der Stueckzahl.
     */
    pruef('158 Laengen sind rechenbar', rechenbar, 158, 1e-9, 'Stk');

    wahr('Eine ungefuehrte Laenge hat keine Einteilung',
         AK.abfangBlechstationen('A200', 10.3) === null);
    /*
     * >>> UND DIE LAGE IST HIER BELEGT. <<<
     *
     * Bei A160 / 9.50 m geht die Feldfolge auf, und die Reihe steht dort,
     * wo die Zeichnung sie zeigt: erstes Blech bei 2.000 m (1450 + 550),
     * letztes bei 7.500 (2000 + QV1 5500). Frueher stand hier die
     * Naeherung - sie lag bei 1.875 m.
     */
    wahr('Die Lage ist belegt', b95.randGenau === true);
    /*
     * >>> DIE ENDEN SIND NICHT GLEICH LANG. <<<
     *
     * Weisung vom 3. September: «auf der linken seite kommt das erste blech
     * schon bei 1450mm und dann das naechste nach 550 und auf der rechten
     * sind es 900 und dann zweimal 550 mm». Hier stand 2.000 und 7.500 -
     * die symmetrische Reihe ohne die Bleche der Endbereiche.
     */
    pruef('Erstes Blech bei 1.450 m', b95.stationen[0], 1.45, 1e-6, 'm');
    pruef('Zweites bei 2.000 m', b95.stationen[1], 2.0, 1e-6, 'm');
    pruef('Letztes bei 8.600 m', b95.stationen.at(-1), 8.6, 1e-6, 'm');
    pruef('Vorletztes bei 8.050 m', b95.stationen.at(-2), 8.05, 1e-6, 'm');
    // 9.500 - 0.900: das letzte Blech misst vom RECHTEN Ende.
    pruef('Das letzte Blech steht 900 mm vom rechten Ende',
          9.5 - b95.stationen.at(-1), 0.9, 1e-6, 'm');
    /*
     * FUENFZEHN, NICHT SECHZEHN: A160 / 9.50 m fuehrt A1 = 250, und dort
     * bilden die beiden halben Felder EIN Regelfeld ohne Blech dazwischen
     * (Weisung, 4. September). Bis dahin stand hier 16 - und der Pruefstand
     * hielt damit das Paar fest, das der Stueckliste zu fehlen schien.
     */
    pruef('Fuenfzehn Stationen', b95.anzahl, 15, 1e-9, 'Stk');
    /*
     * WO SIE NICHT AUFGEHT, BLEIBT DIE NAEHERUNG - und sagt es. Ab A240
     * sitzen Quersteifungen zwischen den QV-Bereichen; wie sich die Bleche
     * darauf verteilen, steht nicht in einer Formel.
     */
    /*
     * ======================================================================
     * >>> DIE QUERSTEIFEN AB A240. <<<
     * ======================================================================
     *
     * Weisung vom 3. September: «die quersteifen ab A240 richtig ansetzen.»
     *
     * An den Grenzen der QV-Bereiche sitzt statt eines Bindeblechpaares ein
     * Riegel aus Walzprofil - die Stueckliste fuehrt ihn als eigene Position
     * «Querversteifung». Vorher rechnete der Kern dort ein Blech, und die
     * Zaehlung von Schema und Stueckliste ging um ebenso viele Stationen
     * auseinander.
     */
    const GEGLIEDERT = ['A240', 'A270', 'A300', 'A330', 'A360'];
    for (const t of GEGLIEDERT) {
      wahr(`${t} fuehrt eine Quersteife`, Boolean(AJ.abfangQuersteife(t)));
    }
    wahr('A160 und A200 fuehren keine - sie sind ungegliedert',
         !AJ.abfangQuersteife('A160') && !AJ.abfangQuersteife('A200'));
    /*
     * >>> SIE SITZEN AUF DEN QV-GRENZEN - UND ZWAR AUF STATIONEN. <<<
     *
     * Der erste Bereich beginnt bei 2000, der letzte endet bei jt - 2000.
     * Faellt eine Grenze zwischen zwei Bleche, waere die Zuordnung geraten.
     * Geprueft an allen 120 Laengen der fuenf gegliederten Typen.
     */
    let aufStation = 0;
    let steifenZahl = 0;
    for (const t of GEGLIEDERT) {
      for (const z2 of AJ.getAbfangjoch(t).laengen) {
        const e2 = AK.abfangBlechstationen(t, z2.jt);
        if (!e2) continue;
        const QV2 = z2.QV ?? [z2.QV1];
        let g2 = 2000;
        const gr = [g2];
        for (const q2 of QV2) { g2 += q2; gr.push(g2); }
        const mm = e2.stationen.map((v) => Math.round(v * 1000));
        if (gr.every((v) => mm.includes(v))) aufStation += 1;
        // Zahl der Steifen: nB + 1, bei A240 zusaetzlich das Endstueck.
        const soll = QV2.length + 1 + (t === 'A240' ? 1 : 0);
        if (e2.quersteifen === soll) steifenZahl += 1;
      }
    }
    pruef('Jede QV-Grenze faellt auf eine Blechstation',
          aufStation, 120, 1e-9, 'Stk');
    pruef('Und die Steifenzahl ist nB + 1', steifenZahl, 120, 1e-9, 'Stk');
    /*
     * >>> DAMIT GEHEN SCHEMA UND STUECKLISTE AUF. <<<
     *
     * Vorher lagen sie ab A240 um bis zu neun Stationen auseinander - das
     * waren genau die Steifen. Was bleibt, ist der eine systematische
     * Fehlbetrag bei A1 = 250: dort fuehrt die Stueckliste durchweg ein
     * Blechpaar zu wenig, bei A160 wie bei A360.
     */
    let deckt500 = 0;
    let ab250 = 0;
    for (const t of neuAlle) {
      for (const z2 of t.laengen) {
        const e2 = AK.abfangBlechstationen(t.typ, z2.jt);
        if (!e2 || e2.stationenListe === null) continue;
        if (z2.A1 === 500) { if (e2.blechzahlStimmt) deckt500 += 1; }
        else if (e2.anzahl - e2.stationenListe === 1) ab250 += 1;
      }
    }
    pruef('Bei A1 = 500 deckt sich jede Laenge', deckt500, 77, 1e-9, 'Stk');
    /*
     * >>> DER FEHLBETRAG WAR KEINER. <<<
     *
     * Hier stand bis zum 4. September, der Stueckliste fehle bei A1 = 250
     * «durchweg genau ein Paar». Sie hatte recht: bei A1 = 250 ist 2 x A1
     * = A, die beiden halben Felder sind zusammen ein Regelfeld, und in der
     * Mitte sitzt kein Blech (Weisung: «es hat nicht immer zwingend in der
     * mitte ein verbindungsblech»). Jetzt deckt sich JEDE Laenge.
     */
    pruef('Und bei A1 = 250 auch', ab250, 0, 1e-9, 'Stk');
    /*
     * >>> DER RIEGEL BIEGT UM SEINE SCHWACHE ACHSE. <<<
     *
     * Die Rahmenebene liegt waagrecht, der Steg der Steife steht senkrecht
     * (Schnitt C-C). W_y einzusetzen gaebe bei IPE 240 das Siebenfache und
     * einen Nachweis, der immer aufginge.
     */
    {
      const PR2 = await import(J('data.profiles.js'));
      const p2 = PR2.getGurtprofil('IPE 240');
      const n2 = AK.abfangSteifennachweis('IPE 240', 40, 1.0, 30.0, 21.8);
      pruef('Der Riegel rechnet mit W_z', n2.W, p2.Wz, 1e-9, 'cm3');
      wahr('… nicht mit W_y', Math.abs(n2.W - p2.Wy) > 1);
      // Den Schub tragen die Flansche, nicht der ganze Querschnitt.
      pruef('Schubflaeche: beide Flansche', n2.A, 2 * p2.b * p2.tf, 1e-9, 'cm2');
      wahr('… und das ist weniger als der Querschnitt', n2.A < p2.A);
      /*
       * EIN RIEGEL NIMMT DIE GANZE QUERKRAFT, ein Blechpaar teilt sie.
       * Deshalb steht im Steifennachweis V und nicht V/2 - bei sonst
       * gleichen Zahlen ist sein Moment doppelt so gross wie das eines
       * einzelnen Blechs.
       */
      const bl2 = AJ.abfangBindeblech('A240').regel;
      const nb = AK.abfangBlechnachweis(bl2, 40, 1.0, 30.0, 21.8);
      pruef('Sein Moment ist das doppelte eines Blechs',
            n2.Mblech / nb.Mblech, 2.0, 1e-9, '-');
      /*
       * >>> UND IST DAMIT FAST GENAU DAS BLECHPAAR. <<<
       *
       * W_z eines I ist im Wesentlichen 2*t_f*b^2/6 - die Formel des
       * Blechpaares mit den Flanschmassen. Bei A240 liegt die Steife
       * deshalb ein Prozent UNTER dem Paar, das sie ersetzt; die frueher
       * notierte Auskunft «immer auf der sicheren Seite» galt nur fuer die
       * grossen Typen.
       */
      const paar = 2 * ((bl2.t / 10) * (bl2.b / 10) ** 2 / 6);
      wahr('A240: die Steife liegt knapp unter dem Blechpaar',
           p2.Wz / paar > 0.97 && p2.Wz / paar < 1.0);
      wahr('A360: deutlich darueber',
           PR2.getGurtprofil('IPE 360').Wz
           / (2 * ((AJ.abfangBindeblech('A360').regel.t / 10)
                   * (AJ.abfangBindeblech('A360').regel.b / 10) ** 2 / 6)) > 1.8);
    }
    /*
     * >>> DER NACHWEIS SETZT SIE AN DER RICHTIGEN STELLE AN. <<<
     */
    {
      const Vf = (x) => 4.0 * (8.0 / 2 - x);
      const a240 = AK.abfangBlechnachweise('A240', 8.0, Vf, 21.8);
      const st2 = a240.bleche.filter((b2) => b2.istSteife);
      pruef('A240 / 8.00 m: vier Steifen im Nachweis', st2.length, 4, 1e-9, 'Stk');
      wahr('Sie stehen auf den QV-Grenzen und am Jochende',
           st2.map((b2) => Math.round(b2.x * 1000)).join(',') === '2000,4000,6000,7090');
      wahr('Jede kennt ihr Profil',
           st2.every((b2) => b2.profil === 'IPE 240'));
      wahr('Die uebrigen bleiben Bleche',
           a240.bleche.filter((b2) => !b2.istSteife).length === 8);
    }

    /*
     * AUCH BEI A240 STEHT DIE LAGE - und die Endmasse sind andere als bei
     * A160: 1380/620 links, 545/545/910 rechts. Beide Seiten summieren auf
     * 2000, sonst waere eines der Masse falsch abgelesen.
     */
    const grob = AK.abfangBlechstationen('A240', 12.0);
    wahr('Bei A240 steht die Lage ebenso', grob?.randGenau === true);
    pruef('A240: erstes Blech bei 1.380 m', grob.stationen[0], 1.38, 1e-6, 'm');
    pruef('A240: letztes 910 mm vom Ende',
          12.0 - grob.stationen.at(-1), 0.91, 1e-6, 'm');

    /*
     * WAS SICH RECHNEN LAESST, SAGT DER KERN SELBST.
     */
    /*
     * >>> DER SPANNUNGSNACHWEIS DES GURTES - OHNE KNICKEN. <<<
     *
     * Weisung vom 3. September: «die knicklaenge hinten anstellen und mit
     * axis kalibrieren. die 500mm sind zu unkonservativ da sich der gesamte
     * traeger biegt in der horizontal und vertikal ebene.»
     *
     * Der Nachweis fuehrt deshalb den QUERSCHNITT, nicht die Stabilitaet -
     * und sagt das im Ergebnis. Ein eta, das den Druckgurt wie einen
     * Zuggurt behandelt und das verschweigt, waere die gefaehrlichste Zahl
     * dieser Anwendung.
     */
    {
      const q = AK.abfangQuerschnitt('A160');
      const fyd = 23.5 / 1.05;                  // S235, kN/cm2
      const nw = AK.abfangGurtnachweis(
        q, { Mzz: 50, Myy: 8, Fy: 20 }, 0.5, fyd);

      /*
       * Von Hand: N = M / e auf die Gurtflaeche.
       *
       * Hier stand `50 / 0.383` - der Hebelarm der frueheren, falschen
       * Profillage (Steg aussen). Seit dem 3. September zeigen die U-Profile
       * nach AUSSEN, e liegt bei 0.317 m, und die Zahl waere von Hand
       * nachgerechnet 157.8 / 22.0 = 7.17 kN/cm2. Genommen wird sie aus `e`,
       * damit sie beim naechsten Geometriefund mitwandert statt zu brechen.
       */
      pruef('Normalspannung aus dem Kraeftepaar',
            nw.sigN, (50 / (q.e / 100)) / q.Agurt, 1e-9, 'kN/cm2');
      pruef('… und von Hand nachgerechnet', nw.sigN, 7.17, 0.02, 'kN/cm2');
      /*
       * >>> HALBE LAST JE GURT. <<<
       *
       * Weisung vom 3. September: «jeder Gurt fuer sich, halbe Last», ueber
       * seine starke Achse. Hier stand `800 / 113.9` - das Moment des
       * GANZEN Traegers gegen das Widerstandsmoment EINES Gurtes, also das
       * Doppelte. `abfangLastQuer` schreibt die Regel seit damals hin und
       * wurde von niemandem aufgerufen; aufgefallen ist es beim Einbau der
       * Torsion, die erst wissen muss, was ein Gurt traegt.
       *
       * M_vert = 8 kNm -> 4 kNm je Gurt auf W_y = 113.9 cm3 -> 3.51 kN/cm2
       */
      pruef('Biegung quer zur Rahmenebene: halbe Last je Gurt',
            nw.sigVert, 400 / 113.9, 0.02, 'kN/cm2');
      pruef('… und das Moment im Gurt ist die Haelfte',
            nw.MgurtVert, 4, 1e-9, 'kNm');
      pruef('… passend zu abfangLastQuer',
            AK.abfangLastQuer(8).jeGurt, nw.MgurtVert, 1e-9, 'kNm');
      /*
       * >>> DIE TORSION ADDIERT SICH IM EINEN GURT. <<<
       *
       * Sie ist das gegenlaeufige Kraeftepaar: im einen Gurt dazu, im
       * anderen davon ab. Massgebend ist der eine.
       */
      const nwT = AK.abfangGurtnachweis(
        q, { Mzz: 50, Myy: 8, Mxx: 2, Fy: 20 }, 0.5, fyd);
      pruef('Torsion kommt zum halben Moment dazu',
            nwT.MgurtVert, 4 + 2, 1e-9, 'kNm');
      wahr('… und ihr Vorzeichen aendert nichts',
           AK.abfangGurtnachweis(
             q, { Mzz: 50, Myy: 8, Mxx: -2, Fy: 20 },
             0.5, fyd).MgurtVert === nwT.MgurtVert);
      wahr('Ohne Torsion bleibt es beim halben Moment',
           nw.Mxx === 0);
      // oertlich: V/2 * a/2 = 10 * 0.25 = 2.5 kNm auf W_z = 18.3 cm3
      pruef('Oertliche Biegung zwischen den Blechen',
            nw.sigOertl, (nw.Moertl * 100) / q.Wgurtz, 1e-9, 'kN/cm2')
      pruef('Und die Summe ist die Summe',
            nw.sigma, nw.sigN + nw.sigVert + nw.sigOertl, 1e-9, 'kN/cm2');
      pruef('eta ist sigma durch f_yd', nw.eta, nw.sigma / fyd, 1e-9, '-');

      /*
       * DER OERTLICHE ANTEIL IST UNGEDAEMPFT - und das mit Absicht.
       *
       * Beim Tragjoch mindert GURT_DAEMPFUNG = 0.45 ihn, gemessen an 80
       * PyNite-Laeufen. Der Wert gilt fuer VIER Winkelgurte mit zwei
       * Blechebenen und ist auf zwei Walzprofile nicht uebertragbar. Bis er
       * gemessen ist, steht 1.0: die sichere Seite.
       */
      pruef('Der oertliche Anteil ist ungedaempft', nw.daempfung, 1.0, 1e-9, '-');

      /*
       * >>> UND DAS ERGEBNIS SAGT, WAS FEHLT. <<<
       */
      wahr('Der Nachweis sagt, dass Knicken fehlt', nw.knickenGefuehrt === false);
      wahr('… und nennt den Grund',
           /[Kk]nicklänge/.test(nw.knickenGrund)
           && /unkonservativ/.test(nw.knickenGrund));

      // Ein groesserer Blechabstand erhoeht den oertlichen Anteil - linear.
      const weit = AK.abfangGurtnachweis(
        q, { Mzz: 50, Myy: 8, Fy: 20 }, 1.0, fyd);
      pruef('Doppelter Blechabstand, doppelter oertlicher Anteil',
            weit.sigOertl, 2 * nw.sigOertl, 1e-9, 'kN/cm2');
      // Ohne Querkraft faellt er weg.
      const ohneV = AK.abfangGurtnachweis(
        q, { Mzz: 50, Myy: 8, Fy: 0 }, 0.5, fyd);
      pruef('Ohne Querkraft kein oertlicher Anteil', ohneV.sigOertl, 0, 1e-9,
            'kN/cm2');
    }

    /*
     * DER HINWEIS STEHT BEI DER ART, NICHT IN DER ALLGEMEINEN LISTE.
     *
     * Eine Nachweisgruppe «Knicken Abfanggurt» stuende auch am Tragjoch
     * unter den nicht gefuehrten - und das hat gar keinen Abfanggurt. Der
     * erste Versuch machte genau das, und vier Kontrollen fielen darueber.
     */
    {
      const { hinweise: hwK } = await import(J('core.checks.js'));
      const mA = rechne({ ...standardwerte(), tragwerksart: 'abfangjoch',
                          abfangTyp: 'A160' }).modell;
      const zeilen = hwK(mA).join(' | ');
      wahr('Beim Abfangjoch steht der Knick-Hinweis',
           zeilen.includes('Knicken des Druckgurtes'));
      const mJ = rechne(standardwerte()).modell;
      wahr('Beim Tragjoch steht er nicht',
           !hwK(mJ).join(' | ').includes('Druckgurtes'));
    }

    wahr('A160 ist rechenbar', AK.abfangRechenbar('A160', 9.5));
    wahr('Eine ungefuehrte Laenge nicht', !AK.abfangRechenbar('A160', 9.7));
    wahr('Und die Altbauweise nicht', !AK.abfangRechenbar('UAP 130'));
  }

  /*
   * >>> DER BINDEBLECHNACHWEIS DES ABFANGJOCHS. <<<
   *
   * Dieselbe Systematik wie beim Tragjoch (Weisung: «ueber die vorhandenen
   * bleche und den nachweisschnitt wie beim tragjoch»):
   *
   *      M_Blech = V_Ebene * ( a_links + a_rechts ) / 4
   *      V_Blech = 2 * M_Blech / Hebelarm
   *
   * Zwei Blechebenen statt vier - je eines oben und unten - teilen sich die
   * Querkraft der Rahmenebene.
   */
  {
    const AK = await import(J('core.abfangjoch.js'));
    const q = AK.abfangQuerschnitt('A160');
    const bl = AJ.abfangBindeblech('A160').regel;      // 100/8 x 280

    /*
     * VON HAND NACHGERECHNET. V = 40 kN, Felder 0.5 + 0.5 m, e = 38.3 cm:
     *   V_Ebene = 20 kN
     *   M_Blech = 20 * 1.0 / 4      = 5.0 kNm
     *   V_Blech = 2 * 5.0 / 0.383   = 26.1 kN
     *   W = 0.8 * 10^2 / 6          = 13.33 cm3
     *   sigma = 500 / 13.33         = 37.5 kN/cm2
     */
    const n = AK.abfangBlechnachweis(bl, 40, 1.0, q.e, 21.8);
    pruef('Die Querkraft teilt sich auf zwei Ebenen', n.Vebene, 20, 1e-9, 'kN');
    pruef('M_Blech = V_Ebene * Sa / 4', n.Mblech, 5.0, 1e-9, 'kNm');
    pruef('V_Blech = 2 * M / e', n.Vblech, 2 * 5.0 / (q.e / 100), 1e-9, 'kN');
    pruef('W = t * b^2 / 6', n.W, (0.8 * 10 * 10) / 6, 1e-9, 'cm3');
    pruef('A = b * t', n.A, 8.0, 1e-9, 'cm2');
    pruef('Biegespannung von Hand', n.sigma, 37.5, 0.1, 'kN/cm2');
    /*
     * DIE VERGLEICHSSPANNUNG LIEGT UEBER BEIDEN EINZELWERTEN - Biegung und
     * Schub treffen sich an derselben Stelle. Waere sie kleiner als die
     * Biegung allein, stimmte die Wurzel nicht.
     */
    wahr('sigma_v liegt ueber der Biegung allein', n.sigmaV > n.sigma);
    pruef('sigma_v nach von Mises', n.sigmaV,
          Math.sqrt(n.sigma ** 2 + 3 * n.tau ** 2), 1e-9, 'kN/cm2');
    pruef('eta ist sigma_v / fyd', n.eta, n.sigmaV / 21.8, 1e-9, '-');
    // Doppelte Querkraft, doppelte Spannung - die Beziehung ist linear.
    pruef('Doppelte Querkraft gibt doppeltes eta',
          AK.abfangBlechnachweis(bl, 80, 1.0, q.e, 21.8).eta, 2 * n.eta,
          1e-9, '-');
    // Ohne Blechmasse keine Zahl, sondern eine Ausnahme.
    let flog = null;
    try { AK.abfangBlechnachweis({}, 40, 1.0, q.e, 21.8); }
    catch (e) { flog = e; }
    wahr('Ohne Blechmasse wirft es', flog !== null);

    /*
     * ALLE BLECHE EINES JOCHS - jedes an SEINER Stelle.
     *
     * Mit dem Auflagerwert fuer alle zu rechnen waere grob konservativ, mit
     * dem mittleren unsicher. Geprueft wird an einem einfachen Balken:
     * V(x) laeuft von +qL/2 linear auf -qL/2.
     */
    const L = 9.5, qd = 4.0;
    const Vfn = (x) => qd * (L / 2 - x);
    const alle = AK.abfangBlechnachweise('A160', L, Vfn, 21.8);
    wahr('Es sind so viele Nachweise wie Stationen',
         alle.bleche.length === 15);
    wahr('Jedes Blech kennt seine Stelle',
         alle.bleche.every((b) => b.x > 0 && b.x < L));
    /*
     * DAS RANDFELD IST NUR EIN FELD BREIT. Es zu verdoppeln waere bequem
     * und falsch - das Randblech traegt weniger Feld, aber mehr Querkraft.
     */
    wahr('Das erste Blech hat nur ein Nachbarfeld',
         alle.bleche[0].aL === 0 && alle.bleche[0].aR > 0);
    wahr('Das letzte ebenso',
         alle.bleche.at(-1).aR === 0 && alle.bleche.at(-1).aL > 0);
    wahr('Die inneren haben zwei',
         alle.bleche.slice(1, -1).every((b) => b.aL > 0 && b.aR > 0));
    // Rand- und Endbleche sind staerker als das Regelblech.
    wahr('Die Randbleche sind Endbleche',
         alle.bleche[0].istRand && alle.bleche.at(-1).istRand);
    wahr('Und die inneren tragen das Regelmass',
         alle.bleche.slice(1, -1).every((b) => b.masse.b === bl.b
                                            && b.masse.t === bl.t));
    // Das massgebende ist wirklich das groesste.
    wahr('Das massgebende Blech ist das mit dem groessten eta',
         alle.bleche.every((b) => b.eta <= alle.massgebend.eta + 1e-12));
    /*
     * IN DER MITTE IST DIE QUERKRAFT NULL - dort muss das eta gegen null
     * gehen. Faellt das je aus, sitzt die Querkraft an der falschen Stelle.
     */
    const mitte = alle.bleche.reduce(
      (m, b) => (Math.abs(b.x - L / 2) < Math.abs(m.x - L / 2) ? b : m));
    wahr('Das mittlere Blech ist das schwaechst beanspruchte',
         mitte.eta < alle.massgebend.eta);
    /*
     * OHNE ERFASSTE EINTEILUNG GIBT ES KEINE NACHWEISE - keine geratenen.
     *
     * Hier stand A200/10.0 - seit dem Nachtrag der Stueckzahlen ist diese
     * Laenge erfasst, und die Kontrolle pruefte nichts mehr. Genommen wird
     * jetzt die FRAGLICHE Laenge: A360/21.00 m fuehrt 85 Bleche, ungerade
     * und damit unmoeglich.
     */
    /*
     * Die fragliche Stueckzahl blockiert den Nachweis nicht mehr - die Lage
     * kommt aus dem Schema. Was nicht geht, ist eine UNGEFUEHRTE Laenge:
     * dort gibt es weder Tabellenzeile noch Feldfolge.
     */
    wahr('Die fragliche Laenge wird jetzt nachgewiesen',
         AK.abfangBlechnachweise('A360', 21.0, Vfn, 21.8) !== null);
    wahr('Eine ungefuehrte Laenge ebenso wenig',
         AK.abfangBlechnachweise('A200', 10.3, Vfn, 21.8) === null);
  }

  /*
   * >>> DER EINZELMAST TRAEGT EINE BENENNUNG, NICHT DREI. <<<
   *
   * Gemeldet am 3. September: «hier braucht es nur eine tragwerkbenennung
   * fuer den einzelmasten.» Im Bild standen drei Anschriften ueber einem
   * einzigen Stiel:
   *
   *      HEB 240 · 7.50 m          das Ende B derselben Rechnung
   *      M3 · HEB 240 · 7.50 m     das Ende A
   *      P2 · frei · 0.00 m        der Jochtitel
   *
   * Der Jochtitel benennt dort ein Bauteil, das nicht dasteht: kein Jochtyp
   * (deshalb «frei»), keine Jochlaenge (deshalb 0.00 m). Und die
   * Mastschleife lief ueber beide Enden, obwohl es nur einen Masten gibt.
   */
  {
    const {  modellEinzelmast: mEM } = await import(J('core.vierendeel.js'));
    const wEM = { ...standardwerte(), tragwerksart: 'einzelmast', twPos: 'P2',
                  mastProfil: 'HEB 240', mastH: 7.5, mastLaenge: 7.5 };
    const szEM = R75.erzeugeSzene(mEM(wEM, getStahl(wEM.stahl)), null);
    const tEM = szEM.bauteiltitel ?? [];
    pruef('Der Einzelmast traegt genau eine Benennung', tEM.length, 1,
          1e-9, 'Stk');
    /*
     * SIE LEISTET BEIDES: Tragwerk und Mast. Die Position steht voran -
     * sie ersetzt den Jochtitel, der dort keinen Gegenstand hat -, dann der
     * Mastname, dann Profil und Laenge.
     */
    wahr('Sie nennt die Position', tEM[0].text.startsWith('P2 · '));
    wahr('… den Masten', tEM[0].text.includes('M1'));
    wahr('… das Profil', tEM[0].text.includes('HEB 240'));
    wahr('… und die Laenge', tEM[0].text.includes('7.50 m'));
    /*
     * UND KEIN JOCHTITEL: «frei» und «0.00 m» waren die Merkmale des
     * Titels, der dort nichts zu suchen hatte.
     */
    wahr('Kein Jochtitel beim Einzelmasten',
         !tEM.some((b) => b.text.includes('frei')
                       || b.text.includes('0.00 m')));

    /*
     * DAS JOCH BEHAELT SEINE DREI - Jochtitel und zwei Masten. Die Kur darf
     * den Regelfall nicht beschaedigen.
     */
    const eJ = rechne({ ...standardwerte(), L: 20, twPos: 'P1' });
    const tJ = R75.erzeugeSzene(eJ.modell, eJ).bauteiltitel ?? [];
    pruef('Das Joch traegt weiterhin drei', tJ.length, 3, 1e-9, 'Stk');
    wahr('Darunter sein Jochtitel',
         tJ.some((b) => b.text.startsWith('P1 · J90')));
    wahr('Und der Jochtitel nennt die Jochlaenge',
         tJ.some((b) => b.text.includes('20.00 m')));
  }

  /*
   * >>> DAS ABFANGJOCH ALS STABMODELL FUER AxisVM. <<<
   *
   * Der Jochexport baut vier Winkelgurte in zwei Blechebenen, senkrecht.
   * Das Abfangjoch ist ein anderes Tragwerk - zwei Walzgurte nebeneinander,
   * Bindebleche oben und unten, und der Rahmen LIEGT.
   */
  {
    const XA = await import(J('export.axisvm.abfang.js'));
    const m = XA.abfangAxisvmModell('A160', 9.5, { Fh: 22 });

    wahr('Das Format ist das des Aufbauskripts',
         m.format === 'tragjoch-stabmodell');
    wahr('Es sagt, was es ist',
         m.merkmale.includes('abfangjoch')
         && m.tragwerk.bauform.includes('Vierendeel'));

    /*
     * >>> DIE GURTE STEHEN NEBENEINANDER, NICHT UEBEREINANDER. <<<
     *
     * Das ist der ganze Unterschied zum Tragjoch. Alle Knoten liegen auf
     * z = 0, und die beiden Gurte trennt der Achsabstand e in y.
     */
    /*
     * DIE KNOTEN LIEGEN AUF DREI HOEHEN - Schwerachse und beide Flansche.
     *
     * Hier stand «alle auf einer Hoehe». Das galt fuer die Fassung mit einem
     * mittigen Riegel; seit die Bleche auf den Flanschen liegen (Weisung,
     * 3. September), sind es drei Ebenen. Die GURTKNOTEN liegen weiterhin
     * auf der Schwerachse - dort und nur dort stimmen die
     * Traegheitsmomente des Gurtstabs.
     */
    wahr('Die Gurtknoten liegen auf der Schwerachse',
         m.knoten.filter((k) => /^[VH]_/.test(k.name))
           .every((k) => Math.abs(k.z) < 1e-12));
    /*
     * >>> ZWEI GURTEBENEN - UND DAZWISCHEN DIE RIEGELKNOTEN. <<<
     *
     * Hier stand «genau zwei y-Ebenen im ganzen Modell». Das galt, solange
     * der Riegel ein einzelner Stab von Achse zu Achse war. Seit die
     * Knotenbereiche steif ausgebildet sind (Weisung, 3. September), sitzen
     * zwischen den Gurten zwei weitere Knoten je Riegel - dort, wo das
     * Bauteil beginnt und endet. Gezaehlt wird deshalb an den GURTknoten.
     */
    const ys = [...new Set(m.knoten.filter((k) => /^[VH][OU]?_/.test(k.name))
      .map((k) => Math.round(k.y * 1e6) / 1e6))];
    wahr('Es gibt genau zwei Gurtebenen', ys.length === 2);
    pruef('Ihr Abstand ist der Hebelarm', Math.abs(ys[0] - ys[1]),
          m.tragwerk.e, 1e-9, 'm');
    // Die Riegelknoten liegen INNERHALB der Gurte, nie ausserhalb.
    wahr('Die Riegelknoten liegen zwischen den Gurten',
         m.knoten.filter((k) => /_[ab]$/.test(k.name))
           .every((k) => Math.abs(k.y) < m.tragwerk.e / 2 + 1e-9));

    /*
     * >>> DER STEG STEHT VOR DEM FLANSCH - BEI BEIDEN. <<<
     *
     * Hier stand «AddC nimmt (h, b, e, tw, R), AddI nimmt (h, b, tw, tf, R).
     * Die Reihenfolge ist NICHT dieselbe» - und das war falsch. Am
     * 4. September im Querschnittseditor gemessen, indem beide Belegungen
     * gebaut und an ihrem Traegheitsmoment geprueft wurden:
     *
     *   e=9.5, tw=5.5   I_y  7'215'754   I_z   781'415
     *   e=5.5, tw=9.5   I_y  8'826'018   I_z 1'054'530
     *   Norm UPE 160    I_y  9'111'000   I_z 1'068'300
     *
     * `e` ist die STEGDICKE, obwohl `tw` danebensteht und anderes nahelegt.
     * Mit der alten Belegung war der Gurt 21 % zu weich in der starken und
     * 27 % in der schwachen Achse - und die Flaechenprobe fand es nicht,
     * weil vertauschte Dicken fast dieselbe Flaeche geben.
     */
    const gurt = m.querschnitte.find((q) => q.name === 'GURT');
    wahr('Der UPE-Gurt ist ein U-Profil', gurt.form === 'Channel');
    pruef('h steht vorn', gurt.parameter[0], 160, 1e-9, 'mm');
    pruef('dann b', gurt.parameter[1], 70, 1e-9, 'mm');
    pruef('dann die STEGdicke', gurt.parameter[2], 5.5, 1e-9, 'mm');
    pruef('dann der Flansch', gurt.parameter[3], 9.5, 1e-9, 'mm');
    // Und beim IPE-Typ dreht sich die Reihenfolge um.
    const mI = XA.abfangAxisvmModell('A270', 15.0, { Fh: 22 });
    const gI = mI.querschnitte.find((q) => q.name === 'GURT');
    wahr('Der IPE-Gurt ist ein I-Profil', gI.form === 'I');
    pruef('dort steht der Steg vor dem Flansch', gI.parameter[2], 6.6, 1e-9, 'mm');
    pruef('und der Flansch danach', gI.parameter[3], 10.2, 1e-9, 'mm');

    /*
     * DIE STAEBE. Je Feld zwei Gurte, je Station ein Bindeblech, dazu die
     * beiden Endbleche.
     */
    const gurtS = m.staebe.filter((x) => x.querschnitt === 'GURT');
    const blS = m.staebe.filter((x) => x.querschnitt === 'BLECH');
    const beS = m.staebe.filter((x) => x.querschnitt === 'BLECH_ENDE');
    /*
     * ZWEI BLECHE JE STATION - oben und unten auf Flanschhoehe (Weisung,
     * 3. September). Hier stand «eines je Station»; das war die Fassung mit
     * einem mittigen Riegel, und die bildet den Kasten nicht ab, den zwei
     * Bleche mit den Gurten bilden.
     */
    /*
     * >>> JE RIEGEL DREI STAEBE: STARR - BLECH - STARR. <<<
     *
     * Weisung vom 3. September: «im bereich der knoten die ueberlagerung
     * der traeger und verbindungsbleche steif ausbilden.» Sechzehn
     * Stationen zu zwei Ebenen sind 32 Riegel - und 96 Staebe.
     */
    /*
     * Vierzehn Stationen tragen das Regelblech - die sechzehnte Reihe minus
     * die beiden, an denen laut Zeichnung ein Endblech sitzt (Weisung vom
     * 4. September: «diese letzten stehenden bleche am schluss des traegers
     * sollten nicht sein» - sie stehen jetzt an ihrer Station, nicht mehr
     * am Traegerende). Je Station zwei Ebenen, je Riegel drei Staebe.
     */
    // Eine Station weniger (kein Blech in der Mitte) sind sechs Staebe
    // weniger: zwei Ebenen zu je starr - Blech - starr.
    pruef('Zwei Bindebleche je Station', blS.length, 78, 1e-9, 'Stk');
    const mittel = blS.filter((x) => x.name.endsWith('_2'));
    pruef('… davon 26 das Blech selbst', mittel.length, 26, 1e-9, 'Stk');
    wahr('Die beiden Enden sind Starrkoerper',
         blS.filter((x) => /_[13]$/.test(x.name))
           .every((x) => x.art === 'starr'));
    pruef('Vier Endbleche - zwei Enden, zwei Ebenen',
          beS.filter((x) => x.name.endsWith('_2')).length, 4, 1e-9, 'Stk');
    /*
     * >>> UND AB A240 STEHT AN DEN QV-GRENZEN EIN RIEGEL. <<<
     *
     * Weisung vom 3. September: «die quersteifen ab A240 richtig ansetzen.»
     * Im Modell heisst das: ein Stab mit dem I-Querschnitt der Steife auf
     * der Gurt-Schwerachse - nicht zwei Flachstaehle auf Flanschhoehe.
     */
    {
      const m240 = XA.abfangAxisvmModell('A240', 8.0, {});
      const stS = m240.staebe.filter((x) => x.querschnitt === 'STEIFE');
      pruef('A240 / 8.00 m: vier Steifen im Modell',
            stS.filter((x) => x.name.endsWith('_2')).length, 4, 1e-9, 'Stk');
      const qsQ = m240.querschnitte.find((q2) => q2.name === 'STEIFE');
      wahr('Sie ist ein I-Profil, kein Rechteck',
           qsQ?.form === 'I' && qsQ.profil === 'IPE 240');
      /*
       * DIE REFERENZ IST [0,0,1], NICHT [1,0,0] WIE BEIM BLECH. Der Riegel
       * steht mit senkrechtem Steg; in der waagrechten Rahmenebene wirkt
       * damit seine schwache Achse - so, wie der Nachweis sie ansetzt.
       * Andersherum waere das Modell um I_y/I_z daneben, bei IPE 240 um
       * das Vierzehnfache.
       */
      wahr('Ihr Steg steht senkrecht',
           stS.every((x) => x.lcsZ[0] === 0 && x.lcsZ[2] === 1));
      /*
       * DER STEIFE KNOTENBEREICH GILT AUCH FUER SIE: das IPE 240 x 600
       * misst 600 mm, der Achsabstand der Gurte 647.6 - beide Enden sind
       * um 23.8 mm starr.
       */
      wahr('Auch sie hat steife Enden',
           stS.filter((x) => /_[13]$/.test(x.name)).length === 8);
      /*
       * Beide zeigen jetzt mit z nach oben - der Unterschied steckt im
       * QUERSCHNITT: die Steife ist ein I mit senkrechtem Steg, das Blech
       * ein flach liegendes Rechteck (Dicke hoch, Breite quer).
       */
      wahr('… und die Bleche liegen flach',
           m240.staebe.filter((x) => x.querschnitt === 'BLECH')
             .every((x) => x.lcsZ[2] === 1));
      // Sie sitzt auf der Schwerachse, die Bleche auf Flanschhoehe.
      const kn = new Map(m240.knoten.map((n2) => [n2.name, n2]));
      wahr('Sie sitzt auf der Schwerachse der Gurte',
           stS.every((x) => Math.abs(kn.get(x.von).z) < 1e-9));
      // Acht Blechstationen bleiben - zwoelf Stationen, vier davon Steifen.
      /*
       * Zwoelf Stationen, vier davon Steifen, zwei mit Endblech - sechs
       * bleiben fuer das Regelblech, in zwei Ebenen.
       */
      pruef('Sechs Blechstationen bleiben',
            m240.staebe.filter((x) => x.querschnitt === 'BLECH'
                                   && x.name.endsWith('_2')).length,
            12, 1e-9, 'Stk');
    }
    // Sie liegen auf drei Hoehen: Schwerachse und beide Flansche.
    const zEb = [...new Set(m.knoten.map((n2) => Math.round(n2.z * 1e6) / 1e6))];
    pruef('Drei Ebenen in z', zEb.length, 3, 1e-9, 'Stk');
    wahr('Symmetrisch zur Schwerachse',
         Math.abs(Math.min(...zEb) + Math.max(...zEb)) < 1e-9
         && zEb.includes(0));
    /*
     * >>> DIE GURTE LAUFEN DURCH - AUCH UEBER DIE STEIFEN ABSCHNITTE. <<<
     *
     * Hier stand die Zahl der Gurtstaebe gegen die halbe Knotenzahl. Das
     * ging auf, solange jeder Knoten ein Gurtknoten war; seit die
     * Flanschknoten und die Riegelknoten dazukommen, nicht mehr. Geprueft
     * wird jetzt, worauf es ankommt: an jedem Gurt haengt zwischen je zwei
     * benachbarten Knoten genau ein Stab, und keiner fehlt.
     */
    /*
     * >>> IM GABELBEREICH TRAEGT DER VERBUNDSTAB. <<<
     *
     * Der Gurt laeuft dort NICHT weiter - er waere doppelt vorhanden,
     * einmal fuer sich und einmal im Verbund. Gezaehlt wird deshalb die
     * Summe aus beiden: sie deckt jedes Feld genau einmal.
     */
    // Stationen aus Gurt- UND Gabelknoten: vor der Gabel gibt es seit dem
    // 17. September keinen Gurtknoten mehr, der an keinem Stab haengt.
    const gk = new Set(m.knoten.filter((k) => /^G?V_/.test(k.name))
      .map((k) => Math.round(k.x * 1e6))).size;
    const laengs = m.staebe.filter((x) => /^[VH]_S\d+$/.test(x.name)
                                       || /^GABEL_[VH]\d+$/.test(x.name));
    pruef('Je Feld zwei Laengsstaebe', laengs.length, (gk - 1) * 2, 1e-9, 'Stk');
    wahr('Kein Knoten ohne Stab',
         m.knoten.every((k) => m.staebe.some((s2) => s2.von === k.name || s2.bis === k.name)),
         m.knoten.filter((k) => !m.staebe.some((s2) => s2.von === k.name || s2.bis === k.name))
           .map((k) => k.name).join(', '));
    wahr('Die Bemessungskombination kommt als Tragsicherheit an',
         m.kombinationen.some((k) => k.key === 'ULS' && k.art === 'tragsicherheit'));
    /*
     * DIE LINIENLAST LAEUFT UEBER ALLE ABSCHNITTE (Weisung, 3. September:
     * «achte darauf dass die linienlast durchgeht, wie bei tragjoch»).
     * Auch der steife Knotenbereich traegt sein Eigengewicht - sonst fehlte
     * es genau dort, wo das Blech aufliegt.
     */
    const gs = new Set(laengs.map((x) => x.name));
    const mitLast = new Set(m.lasten.strecke.map((l) => l.stab));
    wahr('Jeder Gurtabschnitt traegt seine Linienlast',
         [...gs].every((n2) => mitLast.has(n2)));
    /*
     * >>> IM GURT WIRD NICHTS AUSGESTEIFT. <<<
     *
     * Hier stand «auch die steifen Gurtabschnitte tragen ihre Linienlast».
     * Sie gibt es nicht mehr: Weisung vom 4. September, «die aussteiffung in
     * den gurten wuerde ich weglassen, da diese auch die biegung um y
     * beeinflussen». Der Gurt laeuft ununterbrochen durch, und damit auch
     * seine Last - das prueft die Zeile darueber.
     */
    wahr('Kein Gurtabschnitt traegt steifes Material', !m.staebe.some(
      (x) => x.querschnitt === 'GURT' && /^[VH]_S\d+$/.test(x.name)
          && x.steifesMaterial === true));
    /*
     * `lcsZ` HAELT DEN QUERSCHNITT AUFRECHT. Ohne diese Angabe legt AxisVM
     * die lokale Achse nach eigener Regel, der Gurt laege auf der Seite -
     * mit vertauschten Traegheitsmomenten und einem Ergebnis, dem man es
     * nicht ansieht.
     */
    /*
     * Jeder Stab sagt seine lokale z-Achse. Die STARREN ARME stehen
     * senkrecht - fuer sie waere [0,0,1] die Stabachse selbst und damit
     * ungueltig; sie tragen [0,1,0].
     */
    wahr('Jeder Stab sagt seine lokale z-Achse',
         m.staebe.every((x) => Array.isArray(x.lcsZ) && x.lcsZ.length === 3));
    /*
     * DIE GURTE stehen aufrecht - z nach oben, wie beim Tragjoch. Die
     * BLECHE brauchen z in die TRAEGERACHSE, damit ihre Breite dorthin
     * zeigt; mit z nach oben stuenden sie hochkant, und ihre
     * Biegesteifigkeit laege um (b/t)^2 daneben.
     */
    /*
     * >>> DIE GURTE STEHEN SPIEGELBILDLICH. <<<
     *
     * Weisung vom 4. September: «gurte spiegelsymetrisch auf die jochachse
     * bezogen (c ist gegen aussen offen)». Ein U-Profil laesst sich in
     * AxisVM nicht spiegeln; die Referenz dreht es um 180 Grad um die
     * Stabachse, und beim UPE vertauscht das genau die Oeffnungsrichtung.
     * Aufrecht stehen beide - nur eben andersherum.
     */
    wahr('Die Gurte stehen aufrecht',
         m.staebe.filter((x) => x.querschnitt === 'GURT' && x.art === 'stab')
           .every((x) => Math.abs(x.lcsZ[2]) === 1));
    wahr('... und spiegelbildlich zur Jochachse',
         m.staebe.filter((x) => /^V_S[0-9]+$/.test(x.name))
           .every((x) => x.lcsZ[2] === 1)
         && m.staebe.filter((x) => /^H_S[0-9]+$/.test(x.name))
              .every((x) => x.lcsZ[2] === -1));
    /*
     * >>> DIE BLECHE LIEGEN FLACH - UEBER DEN QUERSCHNITT, NICHT UEBER DIE
     *     REFERENZ. <<<
     *
     * Hier stand «z in die Traegerachse» (`lcsZ = [1,0,0]`). Im aufgebauten
     * Modell standen die Bleche damit hochkant (Weisung, 4. September: «die
     * bleche sind stehen anstatt liegend»): die Referenz griff nicht, und
     * AxisVM legte seine lokale z in die Vertikalebene.
     *
     * Jetzt traegt der QUERSCHNITT die Lage - BREITE zuerst, DICKE
     * zweitens (`parameter: [m.b, m.t]`, siehe `blechQs`) - und
     *
     * >>> DIESER SATZ STAND HIER FALSCH HERUM, BIS ZUM 15. SEPTEMBER. <<<
     *
     * Er sagte "h = Dicke, b = Breite" - das Gegenteil dessen, was
     * `blechQs` und `blechQuerschnitt` beide schreiben. Beim Bindeblech der
     * Druckstuetze habe ich ihn geglaubt statt die Zeile zu lesen, und das
     * Blech stand im Modell um 90 Grad verdreht (Befund: "die
     * verbindungsbleche sind nicht richtig ausgerichtet"). Ein Kommentar,
     * der dem Quelltext widerspricht, ist schlimmer als keiner - er wird
     * geglaubt.
     * die Referenz zeigt nach oben. Damit liegt das Blech flach, gleich ob
     * die Referenz ankommt oder nicht.
     */
    wahr('Die Bleche stehen aufrecht referenziert',
         m.staebe.filter((x) => x.querschnitt.startsWith('BLECH'))
           .every((x) => x.lcsZ[2] === 1));
    /*
     * >>> DIE BREITE STEHT VORN. <<<
     *
     * Zweimal daneben: erst `[b,t]` mit Referenz `[1,0,0]`, dann `[t,b]` mit
     * `[0,0,1]` - beide Male stand das Blech hochkant im Modell. Die zwei
     * Aenderungen heben einander auf. `AddRectangular(h, b)` legt h in die
     * lokale y, nicht in die lokale z; mit senkrechter Referenz gehoert
     * damit die BREITE nach vorn.
     */
    wahr('… und ihr Querschnitt ist die Breite quer, die Dicke hoch',
         (() => {
           const q2 = m.querschnitte.find((x) => x.name === 'BLECH');
           return q2.parameter[0] > q2.parameter[1];
         })());
    wahr('Die starren Arme stehen selbst senkrecht',
         m.staebe.filter((x) => x.name.startsWith('ARM_'))
           .every((x) => x.lcsZ[2] === 0));

    /*
     * >>> DIE GABEL SITZT AUSSEN, UM EINE FLANSCHBREITE VERSETZT. <<<
     *
     * Weisung vom 4. September: «achte dabei dass die schwerelinie versetzt
     * ist, da der gurt durchlaeuft und die aufdoppelung aussen
     * angeschweisst ist» - «ja versatz sauber modellieren».
     *
     * Gebaut wird kein gemittelter Verbundquerschnitt, sondern das, was
     * dasteht: ein zweiter Stab desselben Profils auf seiner eigenen Achse,
     * an jedem Knoten starr mit dem Gurt verbunden.
     */
    {
      const gb = m.staebe.filter((x) => x.name.startsWith('GABEL_'));
      const ga = m.staebe.filter((x) => x.name.startsWith('GARM_'));
      wahr('Die Gabel steht als eigener Stab da', gb.length > 0);
      wahr('… und haengt an starren Querarmen',
           ga.length > 0 && ga.every((x) => x.art === 'starr'));
      const PR3 = await import(J('data.profiles.js'));
      /*
       * >>> DER VERBUND LIEGT AUF DER HALBEN FLANSCHBREITE. <<<
       *
       * Die beiden Einzelachsen liegen eine ganze Flanschbreite
       * auseinander; der Schwerpunkt zweier gleicher Profile liegt
       * dazwischen. Der Auftraggeber hat es im Querschnittsmodul gemessen:
       * y_G = 35.0 mm bei einem UPE 160 mit b = 70.
       */
      const p2 = PR3.getGurtprofil(m.tragwerk.gurtprofil);
      const kn2 = new Map(m.knoten.map((n2) => [n2.name, n2]));
      pruef('Ihr Versatz ist die halbe Flanschbreite',
            m.tragwerk.gabel.versatz, p2.b / 200, 1e-9, 'm');
      /*
       * DER QUERSCHNITT IST DER ECHTE, kein Ersatz mit gerechneten Werten:
       * zwei gleichsinnige U als Polygonzug ueber AddCustom (Weisung,
       * 4. September). Die Kennwerte stehen daneben - sie tragen die
       * Flaechenprobe des Aufbauskripts und lassen sich gegen das
       * Querschnittsmodul halten.
       */
      const qg = m.querschnitte.find((x) => x.name === 'GABEL');
      wahr('Die Gabel traegt einen Doppel-U-Querschnitt', qg?.form === 'DoppelU');
      pruef('Seine Flaeche ist die doppelte', qg.A, 2 * p2.A / 1e4, 1e-12, 'm2');
      pruef('… und sein I_z traegt den Steiner-Anteil',
            qg.Iz, 2 * (p2.Iz + p2.A * (p2.b / 2) ** 2) / 1e8, 1e-12, 'm4');
      wahr('Der Verbundstab steht auf der Verbundachse',
           gb.every((x) => Math.abs(kn2.get(x.von).y)
                           > m.tragwerk.e / 2 + p2.b / 400));
      wahr('Sie liegt AUSSEN, nicht innen',
           gb.every((x) => Math.abs(kn2.get(x.von).y) > m.tragwerk.e / 2));
      // Sie beginnt 850 mm vom Jochende und ist so lang wie im Sortiment.
      const xg = gb.map((x) => kn2.get(x.von).x);
      pruef('Sie beginnt bei 0.850 m', Math.min(...xg), 0.85, 1e-9, 'm');
      /*
       * >>> DIE GABEL LIEGT IM ANZUG. <<<
       *
       * Weisung vom 4. September: «beachte das auf der langen gabel die
       * verstaerkung im anzug liegt.» Sie beginnt genau am Knick (850) und
       * laeuft auf dem verjuengten Stueck - ihre Achse folgt also der des
       * Gurtes und ist an ihrem Ende weiter aussen als an ihrem Anfang.
       */
      const yg = gb.flatMap((x) => [Math.abs(kn2.get(x.von).y),
                                    Math.abs(kn2.get(x.bis).y)]);
      // A160 ist `form: 'gerade'` und kennt keinen Anzug - dort steht die
      // Gabel auf einer Achse. Bei den gekropften Typen wandert sie.
      wahr('Beim geraden Typ steht sie auf einer Achse',
           !AJ.abfangKroepfung(m.tragwerk.typ)
           === (Math.max(...yg) - Math.min(...yg) < 1e-9));
      const xe = gb.map((x) => kn2.get(x.bis).x);
      pruef('… und endet 660 mm weiter',
            Math.max(...xe) - Math.min(...xg), 0.66, 1e-9, 'm');
      /*
       * >>> NUR AN EINEM ENDE. <<<
       *
       * Hier stand bis zum 4. September das Gegenteil - «An beiden Enden des
       * Jochs» - und der Pruefstand hielt damit einen Modellfehler fest.
       * Weisung: «beachte das die verstaerkung nur einseitig ist aufgrund
       * der laengeren gabel fuer das einfaedelnde montieren der traeger
       * zwischen zwei masten.» Verstaerkt ist das lange Montageende, das
       * kurze nicht.
       */
      wahr('Nur am langen Jochende, nicht am kurzen',
           Math.max(...xe) < m.tragwerk.L - 1);
      // Ein Stueck je Gurt - in Feldern gebaut, aber auf zwei Achsen.
      pruef('Auf zwei Achsen, eine je Gurt',
            new Set(gb.map((x) => kn2.get(x.von).y.toFixed(6))).size,
            2, 1e-9, 'Achsen');
    }

    /*
     * >>> DIE KROEPFUNG STEHT IM STABMODELL. <<<
     *
     * Weisung vom 4. September: «die modelle sind mit kroepfung in axis zu
     * modellieren.» Der Achsabstand der Gurte ist damit keine Zahl mehr,
     * sondern eine Funktion von x - und der Hebelarm der Vierendeel-Wirkung
     * faellt am Auflagerschnitt auf rund drei Viertel.
     */
    {
      const yV = m.knoten.filter((n2) => /^V_/.test(n2.name))
        .sort((a2, b2) => a2.x - b2.x);
      const eAm = (x) => {
        const n2 = yV.reduce((b2, k2) => (Math.abs(k2.x - x) < Math.abs(b2.x - x)
          ? k2 : b2), yV[0]);
        return Math.round(n2.y * 2000);
      };
      const auf2 = AJ.abfangAufbau(m.tragwerk.typ);
      pruef('Im Feld steht der volle Achsabstand', eAm(m.tragwerk.L / 2),
            Math.round(m.tragwerk.e * 1000), 1e-9, 'mm');
      // A160 ist gerade - dort ist der Achsabstand ueberall derselbe.
      wahr('Beim geraden Typ bleibt er ueberall gleich',
           Boolean(AJ.abfangKroepfung(m.tragwerk.typ))
           === (eAm(0) < eAm(m.tragwerk.L / 2)));
      wahr('… und beide Enden verhalten sich gleich',
           (eAm(0) < eAm(m.tragwerk.L / 2))
           === (eAm(m.tragwerk.L) < eAm(m.tragwerk.L / 2)));
      /*
       * DIE KNICKE SIND KNOTEN. Ohne sie liefe der Gurt geradlinig darueber
       * hinweg - ein Stabzug bildet nur ab, was seine Knoten hergeben.
       */
      const kr2 = AJ.abfangKroepfung(m.tragwerk.typ);
      if (kr2) {
        for (const v of [kr2.knickLangesEnde / 1000, kr2.vollbreiteAb / 1000]) {
          wahr(`Der Knick bei ${v.toFixed(3)} m ist ein Knoten`,
               yV.some((n2) => Math.abs(n2.x - v) < 1e-9));
        }
        // Vor dem Knick steht die Endweite, dahinter waechst sie.
        pruef('Bis zum Knick bleibt die Endweite',
              eAm(kr2.knickLangesEnde / 2000),
              kr2.lichtEnde + (Math.round(m.tragwerk.e * 1000) - auf2.d),
              1e-9, 'mm');
      }
    }

    /*
     * >>> DAS DECKBLECH LIEGT AN DER INNEREN FLANSCHSPITZE. <<<
     *
     * Weisung vom 4. September: «Die Deckbleche hier beim A300 liegen auf
     * der achse des IPE, diese sollten innenseitig buendig anliegen gemaess
     * zeichnung.»
     *
     * Die Ursache lag nicht am Blech, sondern am Gurt: der Versatz von der
     * lichten Kante zur Schwerachse wurde gegen `d` gerechnet, und seit `d`
     * der Stegabstand ist, kam dabei beim I NULL heraus. Die Gurtachse lag
     * damit um eine halbe Flanschbreite zu weit innen - genau dort, wo das
     * Blech sitzt.
     *
     * A300 am Jochende: licht 300, Achse auf 225, Flanschspitzen auf 150 und
     * 300 (aussen 600). Das Blech von 140 bis 150, in z um 5 mm hinter jeder
     * Flanschkante (Schnitt B-B).
     */
    {
      const szA = R3D.abfangSzene('A300', 13.0);
      const vorn = (teil) => {
        const f = szA.flaechen.filter((q) => q.teil === teil
          && q.punkte.every((pt) => pt[0] <= 0.5 + 1e-9) && q.punkte[0][1] > 0);
        const ys = f.flatMap((q) => q.punkte.map((pt) => pt[1] * 1000));
        const zs = f.flatMap((q) => q.punkte.map((pt) => pt[2] * 1000));
        return { y0: Math.min(...ys), y1: Math.max(...ys),
                 z0: Math.min(...zs), z1: Math.max(...zs) };
      };
      /*
       * >>> OHNE WERTE KEINE FARBE AUS DER SKALA. <<<
       *
       * Weisung vom 4. September: «die farbe fuer die resultatauswertung
       * fuer das abfangjoch modell nachziehen.» Die Ansicht faerbt nach
       * `f.werte[feld]`; fehlt das Feld GANZ, faellt sie auf die
       * Bauteilfarbe zurueck - und das Abfangjoch stand in den
       * Plot-Ansichten im gewoehnlichen Stahlton da, als waere es
       * nachgewiesen. Ein leerer Wertesatz laesst es neutral.
       */
      wahr('Jede Flaeche traegt einen Wertesatz',
           szA.flaechen.every((f) => f.werte !== undefined));
      wahr('… und er ist leer', szA.flaechen.every(
        (f) => Object.keys(f.werte).length === 0));
      /*
       * DIE MASTEN STEHEN UNTER DEN AUFLAGERN (Weisung, 4. September). Ohne
       * Mastangabe wird keiner gezeichnet - er waere eine Behauptung ueber
       * die Lagerung.
       */
      wahr('Ohne Mastangabe steht kein Mast',
           !szA.flaechen.some((f) => f.gruppe === 'mast'));
      const szM = R3D.abfangSzene('A300', 13.0,
        { mast: { profil: 'HEB 240', hoehe: 7.5, stegrichtung: 'jochachse' } });
      const mst = szM.flaechen.filter((f) => f.gruppe === 'mast');
      /*
       * ZWEI MASTKOERPER - die Fundamentkoepfe zaehlen nicht mit. Sie stehen
       * seit dem 11. September als eigene Teile in derselben Gruppe
       * (Weisung: «die fundamentkoepfe vertikal machen»); ohne diese
       * Unterscheidung zaehlte die Kontrolle vier.
       */
      wahr('Mit Angabe zwei Masten',
           new Set(mst.map((f) => f.teil)
             .filter((t) => t && !/^(ANKER)?FUNDAMENT/.test(t))).size === 2);
      wahr('… und je einen Fundamentkopf',
           new Set(mst.map((f) => f.teil)
             .filter((t) => /^FUNDAMENT/.test(t ?? ''))).size === 2);
      // Der Mast endet am Fuss, der Klotz liegt darunter (18. September).
      const mstOhneFk = mst.filter((f) => !/^(ANKER)?FUNDAMENT/.test(f.teil ?? ''));
      pruef('Sie reichen bis zum Fundament',
            Math.min(...mstOhneFk.flatMap((f) => f.punkte.map((p2) => p2[2]))),
            -7.5, 1e-9, 'm');
      /*
       * >>> UND SIE RAGEN UEBER DEN ANSCHLUSS. <<<
       *
       * Weisung vom 10. September: «warum sehen die masten anders aus im 3d
       * als die bei den tragjochen?» Hier stand «und enden an der
       * Jochachse» - genau das war der Unterschied. Beim Tragjoch fuehrt die
       * Zeichnung den Masten mindestens einen halben Meter ueber die
       * Oberkante des Traegers, und dort sitzen die Traversen.
       *
       * A300: Profilhoehe 300 mm, also 0.15 + 0.50 = 0.65 m ueber der
       * Jochachse.
       */
      pruef('… und ragen ueber den Anschluss hinaus',
            Math.max(...mst.flatMap((f) => f.punkte.map((p2) => p2[2]))),
            0.65, 1e-9, 'm');
      /*
       * >>> DAS LAGER SITZT AM MASTFUSS, NICHT AN DER JOCHACHSE. <<<
       *
       * Weisung vom 10. September: «bei den masten beim abfangjoch sind
       * noch lagersymbole beim auflager zum masten, diese sind so bei den
       * tragjochen nicht vorhanden.»
       *
       * Beim Tragjoch wurde die Marke aus genau diesem Grund schon einmal
       * verlegt: unten steht das FUNDAMENT, und dort ist eingespannt. Am
       * Jochende sitzt der ANSCHLUSS - beim Abfangjoch die Drehfeder um z,
       * die daneben angeschrieben ist. Ein Auflagersymbol dort las sich wie
       * ein Lager.
       */
      const aufM = szM.marken.filter((k) => k.art === 'auflager');
      wahr('Zwei Auflagermarken', aufM.length === 2);
      wahr('Sie sitzen unter dem Mastfuss', aufM[0].p[2] < -7.5, `${aufM[0].p[2]}`);
      pruef('… an der Unterkante des Fundamentklotzes',
            Math.min(...mst.flatMap((f) => f.punkte.map((p2) => p2[2]))),
            aufM[0].p[2], 1e-9, 'm');
      // Ohne Lagerangabe kein Text: Profil und Hoehe stehen im Titel.
      const txtM = szM.marken.filter((k) => k.art === 'auflagertext');
      wahr('Ohne Lagerangabe steht kein Text', txtM.length === 0,
           txtM.map((k) => k.zeilen.join(' / ')).join(' | '));
      /*
       * OHNE MAST GIBT ES KEINEN FUSS - dann bleibt die Marke am Joch, wie
       * beim Tragjoch auch. Eine Marke im Nichts waere schlimmer als eine
       * am falschen Ort.
       */
      const aufO = szA.marken.filter((k) => k.art === 'auflager');
      wahr('Ohne Mast bleibt die Marke am Joch',
           aufO.length === 2 && aufO[0].p[2] > -1);

      /*
       * >>> JEDER MAST TRAEGT SEINE ANSCHRIFT. <<<
       *
       * Weisung vom 11. September: «die beschriftungspillen im 3d fehlen
       * bei den masten.» Beim Tragjoch steht ueber jedem Mastkopf
       * «M2 · HEB 240 · 8.00 m», und ein Klick darauf oeffnet SEIN
       * Profilfeld. Hier fehlte sie ganz: das Bild nannte den Masten
       * nirgends, und anklicken liess er sich auch nicht.
       */
      const szN = R3D.abfangSzene('A300', 13.0, {
        mast: { profil: 'HEB 240', hoehe: 7.5, stegrichtung: 'jochachse' },
        masten: {
          A: { profil: 'HEB 240', hoehe: 7.5, name: 'M2',
               stegrichtung: 'jochachse' },
          B: { profil: 'HEB 260', hoehe: 8.0, name: 'M3',
               stegrichtung: 'jochachse' } } });
      const titelM = (szN.bauteiltitel ?? []).filter((t) => t.mastEnde);
      wahr('Zwei Mastanschriften', titelM.length === 2);
      wahr('Sie nennen Namen, Profil und Laenge',
           titelM.some((t) => t.text.includes('M2')
                           && t.text.includes('HEB 240'))
           && titelM.some((t) => t.text.includes('M3')
                              && t.text.includes('HEB 260')));
      /*
       * DAS ENDE GEHOERT AN DIE ANSCHRIFT - sonst bearbeitet man M2 und
       * klickt auf M3. Dieselbe Falle wie beim Tragjoch am 3. September.
       */
      wahr('Jede sagt, welchen Masten sie meint',
           titelM.every((t) => t.mastEnde && t.feld === 'mastProfil'));
      wahr('… und sie stehen ueber dem Mastkopf',
           titelM.every((t) => t.p[2] > 0));
      wahr('Ohne Mast keine Anschrift',
           (szA.bauteiltitel ?? []).every((t) => !t.mastEnde));

      /*
       * >>> DIE VERTEILTEN LASTEN. <<<
       *
       * Weisung vom 11. September: «die lasten sind nicht abgebildet wenn
       * abfangjoch ausgewählt.» Gezeichnet waren nur die EINZELLASTEN der
       * Anbauteile; was ueber die ganze Laenge wirkt, fehlte. Ohne
       * Anbauteile war das Bild damit leer, obwohl das Joch sich selbst
       * traegt.
       */
      const szL = R3D.abfangSzene('A240', 12.5, {
        mast: { profil: 'HEB 240', hoehe: 7.5, stegrichtung: 'jochachse' },
        erg: { lasten: { gk: 0.42, wk: 0.31, sk: 0.24 } } });
      const arten = new Set((szL.vektoren ?? [])
        .filter((v) => v.gruppe === 'last')
        .map((v) => v.lastart));
      wahr('Eigengewicht, Schnee und Wind stehen im Bild',
           arten.has('staendig') && arten.has('schnee') && arten.has('windY'),
           [...arten].join(', '));
      wahr('Und jede traegt ihre Flaeche',
           (szL.lastflaechen ?? []).length === 3);
      wahr('Die Flaechen nennen den Wert',
           (szL.lastflaechen ?? []).some((f) => /0\.42/.test(f.titel))
           && (szL.lastflaechen ?? []).some((f) => /0\.31/.test(f.titel)));
      /*
       * DIE ZAHLEN KOMMEN AUS DEM NACHWEIS, nicht aus einer zweiten
       * Abfrage des Sortiments. Genau das ist am 9. September schon einmal
       * auseinandergelaufen - Bild 0.50 kN gegen Nachweis 1.70.
       */
      wahr('Ohne Ergebnis keine verteilte Last',
           (R3D.abfangSzene('A240', 12.5, {
             mast: { profil: 'HEB 240', hoehe: 7.5,
                     stegrichtung: 'jochachse' } }).lastflaechen ?? [])
             .length === 0);
      /*
       * >>> UND DAS DREIECK STEHT NUR, WO KEINE SCHRAFFUR IST. <<<
       *
       * Weisung vom 10. September: «nimm die pfeilsymbole weg, es genuegt
       * das einspannsymbol.» Am Mastfuss zeichnet `mastKoerper` die
       * Fussschraffur - sie zeigt die EINSPANNUNG. Das Auflagerdreieck
       * daneben sagt nur «hier ist ein Lager» und laesst offen, welches;
       * zwei Symbole nebeneinander sind keine doppelte Auskunft, sondern
       * eine unklare.
       */
      wahr('Mit Mast steht kein Auflagerdreieck mehr',
           aufM.every((k) => k.ohneSymbol === true));
      wahr('… ohne Mast dagegen schon',
           aufO.every((k) => !k.ohneSymbol));
      wahr('Der Name bleibt in beiden Faellen',
           aufM.every((k) => k.text) && aufO.every((k) => k.text));
      /*
       * BEIDE SZENEN NEHMEN DENSELBEN BAUSTEIN. Waeren es zwei, liefe die
       * eine der anderen wieder davon - genau das war der Befund.
       */
      {
        const rq = readFileSync(join(HIER, 'js', 'render.abfang.js'), 'utf8');
        const r3 = readFileSync(join(HIER, 'js', 'render.3d.js'), 'utf8');
        wahr('Die Abfangszene ruft den gemeinsamen Mastbaustein',
             /mastKoerper\(/.test(rq));
        wahr('… und die Tragjochszene auch', /mastKoerper\(/.test(r3));
        /*
         * Und keine ZWEITE Ankerzeichnung daneben - der Kommentar darf den
         * Baustein nennen, der Code nicht noch einmal dasselbe malen.
         */
        wahr('Die Ankerlinien stehen nur im Baustein',
             !/anker: true/.test(r3) && !/anker: true/.test(rq));
      }

      const g = vorn('GURT_V'), db = vorn('DECK_L');
      pruef('A300 am Ende: innere Flanschspitze bei 150', g.y0, 150, 1e-6, 'mm');
      pruef('… aeussere bei 300, aussen also 600', g.y1, 300, 1e-6, 'mm');
      pruef('Das Deckblech schliesst buendig an', db.y1, g.y0, 1e-6, 'mm');
      pruef('… und ist 10 mm dick', db.y1 - db.y0, 10, 1e-6, 'mm');
      wahr('Es liegt INNEN, nicht auf der Achse', db.y1 < (g.y0 + g.y1) / 2);
      pruef('In der Hoehe bleibt es 5 mm hinter der Flanschkante',
            g.z1 - db.z1, 5, 1e-6, 'mm');
    }

    // Der Kern des Abfangjochs traegt die Anbindungsregel.
    const AK = await import(J('core.abfangjoch.js'));

    /*
     * ================ FIX ODER BEWEGLICH ABGEFANGEN =====================
     *
     * Weisung vom 4. September, woertlich: «bei den leitern werden die N-FL
     * Tragseile fix (temperatur abhaengig, fuer die bemessung mit wind wird
     * 5 Grad angesetzt) und die R-FL Tragseile beweglich (immer volle
     * leiterzugkraft) abgefangen. bei der Fahrleitung N-FL sind es im
     * Normalfall die 8.5 und bei den R-FL die 10 kN und beide beweglich,
     * somit temperatur unabhaengig.»
     */
    {
      const art = (id) => FL.abfangArt(id);
      wahr('N-FL: das Tragseil ist FIX abgefangen',
           art('drahtwerk-n-fl-stcu-50').ts === 'fix');
      wahr('R-FL: das Tragseil ist BEWEGLICH',
           art('drahtwerk-r-fl-stcu-92').ts === 'beweglich');
      wahr('Beide Fahrdraehte sind beweglich',
           art('drahtwerk-n-fl-cu-107').fd === 'beweglich'
           && art('drahtwerk-r-fl-cu-107').fd === 'beweglich');
      /*
       * >>> DER EINZELLEITER IST FIX ABGESPANNT. <<<
       *
       * Weisung vom 9. September: «der cu95 ist fix abgefangen, tabelle
       * scharf stellen.» Erkannt wird er daran, dass er zu keinem
       * Kettenwerk gehoert - `n-fl` und `r-fl` stehen nur bei den
       * Fahrleitungen im Namen.
       */
      wahr('Der Rueckleiter Cu 95 ist FIX abgespannt',
           art('drahtwerk-cu-95').art === 'fix');
      wahr('… und die Buendel ebenso',
           ['x2', 'x3', 'x4'].every(
             (x) => art(`drahtwerk-cu-95-${x}`).art === 'fix'));
      wahr('… womit er der Temperatur folgt',
           FL.abfangkraft('drahtwerk-cu-95').temperaturabhaengig);
      pruef('Der N-FL-Fahrdraht zieht mit 8.5 kN',
            FL.leiterzug('drahtwerk-n-fl-cu-107'), 8.5, 1e-9, 'kN');
      pruef('Der R-FL-Fahrdraht mit 10', FL.leiterzug('drahtwerk-r-fl-cu-107'),
            10, 1e-9, 'kN');
      /*
       * DAS GANZE N-FL-DRAHTWERK IST GEMISCHT: Tragseil fix, Fahrdraht
       * beweglich. Beim R-FL sind beide beweglich, es ist damit
       * temperaturunabhaengig.
       */
      wahr('Das N-FL-Drahtwerk ist gemischt abgefangen',
           art('drahtwerk-n-fl-ts-stcu-50-fd-cu-107').art === 'gemischt');
      wahr('Das R-FL-Drahtwerk ganz beweglich',
           art('drahtwerk-r-fl-ts-stcu-92-fd-cu-107').art === 'beweglich');
      wahr('… und damit temperaturunabhaengig',
           !FL.abfangkraft('drahtwerk-r-fl-ts-stcu-92-fd-cu-107')
             .temperaturabhaengig);
      wahr('Das N-FL-Drahtwerk dagegen nicht',
           FL.abfangkraft('drahtwerk-n-fl-ts-stcu-50-fd-cu-107')
             .temperaturabhaengig);
      // Die Summe der Teile ist das Drahtwerk: 6.4 + 8.5 = 14.9.
      pruef('N-FL: Ts + Fd geben das Drahtwerk',
            FL.leiterzug('drahtwerk-n-fl-stcu-50')
            + FL.leiterzug('drahtwerk-n-fl-cu-107'),
            FL.leiterzug('drahtwerk-n-fl-ts-stcu-50-fd-cu-107'), 1e-9, 'kN');
      pruef('R-FL ebenso', FL.leiterzug('drahtwerk-r-fl-stcu-92')
            + FL.leiterzug('drahtwerk-r-fl-cu-107'),
            FL.leiterzug('drahtwerk-r-fl-ts-stcu-92-fd-cu-107'), 1e-9, 'kN');
      /*
       * >>> DIE DREI FAELLE STEHEN AUF DREI ZUGKRAEFTEN. <<<
       *
       * Das N-FL-Tragseil StCu 50 folgt der Reglagetabelle, Zeile
       * «sh 1.90 m, 8 kN, Ts belastet»: 6.4 kN bei +5 Grad, 7.0 bei -5,
       * 8.0 bei -20. Der Katalogwert ist die Spalte +5.
       */
      pruef('Ts StCu 50 bei Wind (+5 Grad)',
            FL.abfangkraft('drahtwerk-n-fl-stcu-50',
                           { tempFall: 'tragsicherheit' }).Z, 6.4, 1e-9, 'kN');
      pruef('… bei Schnee (-5 Grad +Z)',
            FL.abfangkraft('drahtwerk-n-fl-stcu-50',
                           { tempFall: 'schnee' }).Z, 8.0, 1e-9, 'kN');
      pruef('… bei Havarie (-20 Grad)',
            FL.abfangkraft('drahtwerk-n-fl-stcu-50',
                           { tempFall: 'havarie' }).Z, 8.0, 1e-9, 'kN');
      wahr('… und keiner davon ohne Tabelle',
           ['tragsicherheit', 'schnee', 'havarie'].every(
             (tf) => !FL.abfangkraft('drahtwerk-n-fl-stcu-50',
                                     { tempFall: tf }).ohneTabelle));
      /*
       * BEIM BEWEGLICHEN AENDERT SICH NICHTS. Die Nachspannung haelt die
       * Kraft konstant - eine Tabelle wuerde ihn auch dann nicht
       * beschreiben, wenn eine dalaege.
       */
      pruef('Das R-FL zieht kalt gleich stark',
            FL.abfangkraft('drahtwerk-r-fl-ts-stcu-92-fd-cu-107',
                           { tempFall: 'havarie' }).Z, 22, 1e-9, 'kN');
      wahr('Beim beweglichen fehlt die Tabelle nie',
           !FL.abfangkraft('drahtwerk-r-fl-stcu-92',
                           { tempFall: 'havarie' }).ohneTabelle);
      /*
       * >>> WO EINE ZEILE FEHLT, WIRD ES GEMELDET. <<<
       *
       * Fuer das Drahtwerk Ts StCu 50 / Fd Cu 150 (14.5 kN) fuehrt die
       * Reglagetabelle keine Zeile - sie kennt StCu 50 nur mit Fd Cu 107
       * und Cu 150 nur mit StCu 92. Geraten wird nicht; die Funktion sagt,
       * dass der Wert von +5 Grad dasteht.
       */
      wahr('Ohne passende Zeile bleibt es beim Wert von +5 Grad',
           FL.abfangkraft('drahtwerk-n-fl-ts-stcu-50-fd-cu-150',
                          { tempFall: 'havarie' }).ohneTabelle);

      /*
       * ============== DIE REGLAGETABELLE ==============================
       *
       * Weisung vom 9. September: «die werte sin in einer anderen app
       * hinterlegt.» Von dort kommt die Tabelle des Rueckleiters Cu 95.
       *
       * >>> DER STUETZWERT BEI +5 IST DIE PROBE. <<<
       *
       * Katalog und Tabelle beschreiben dasselbe. Faellt die Spalte +5 der
       * Tabelle nicht mit `leiterzug` zusammen, laufen zwei Zahlen
       * nebeneinander her - und im Nachweis steht bald die falsche.
       */
      {
        const mitTab = FL.flBauteile()
          .filter((b) => FL.reglageTabelle(b.id));
        wahr('Der Katalog fuehrt Reglagetabellen', mitTab.length > 0,
             `${mitTab.length} Drahtwerke`);
        mitTab.forEach((b) => {
          pruef(`${b.id}: Spalte +5 ist der Katalogwert`,
                FL.reglageZug(b.id, 5), FL.leiterzug(b.id), 1e-9, 'kN');
          const r = FL.reglageTabelle(b.id);
          wahr(`${b.id}: kalt zieht staerker`,
               r.vals.every((v, i) => i === 0 || v <= r.vals[i - 1] + 1e-9));
          wahr(`${b.id}: Temperaturen steigen`,
               r.temps.every((v, i) => i === 0 || v > r.temps[i - 1]));
        });

        // Der Rueckleiter Cu 95, 6 kN Basiskraft - drei Stuetzstellen.
        pruef('Cu 95 bei -20 Grad', FL.reglageZug('drahtwerk-cu-95', -20),
              6.0, 1e-9, 'kN');
        pruef('… bei -5 Grad', FL.reglageZug('drahtwerk-cu-95', -5),
              4.6, 1e-9, 'kN');
        pruef('… bei +5 Grad', FL.reglageZug('drahtwerk-cu-95', 5),
              3.9, 1e-9, 'kN');
        // Vier Leiter ziehen viermal so stark.
        pruef('Vier Cu 95 bei -20', FL.reglageZug('drahtwerk-cu-95-x4', -20),
              24.0, 1e-9, 'kN');

        /*
         * ZWISCHEN DEN STUETZSTELLEN WIRD LINEAR INTERPOLIERT - eine
         * Naeherung, die im Nachweis nie zum Zug kommt: -20, -5 und +5 sind
         * selbst Stuetzstellen.
         */
        pruef('Zwischen -5 und 0 wird interpoliert',
              FL.reglageZug('drahtwerk-cu-95', -2.5), 4.4, 1e-9, 'kN');
        /*
         * AUSSERHALB GILT DER RANDWERT. Die Tabelle zu verlaengern hiesse,
         * ueber ihren Geltungsbereich hinaus zu rechnen.
         */
        pruef('Unter -20 bleibt es beim Randwert',
              FL.reglageZug('drahtwerk-cu-95', -40), 6.0, 1e-9, 'kN');
        pruef('Ueber +40 ebenso',
              FL.reglageZug('drahtwerk-cu-95', 60), 2.6, 1e-9, 'kN');
        // Wo keine Zeile passt, gibt es keine Zahl - der Fahrdraht Cu 150
        // am Tragseil StCu 50 kommt in der Tabelle nicht vor.
        wahr('Ohne passende Zeile gibt es keine Zahl',
             FL.reglageZug('drahtwerk-n-fl-ts-stcu-50-fd-cu-150', -20)
             === null);
        // Das N-FL-Tragseil dagegen steht darin.
        pruef('Ts StCu 50 bei -20 Grad',
              FL.reglageZug('drahtwerk-n-fl-stcu-50', -20), 8.0, 1e-9, 'kN');
        pruef('Das ganze Drahtwerk mit Fahrdraht',
              FL.reglageZug('drahtwerk-n-fl-ts-stcu-50-fd-cu-107', -20),
              16.5, 1e-9, 'kN');

        /*
         * >>> DIE TABELLE IST SCHARF. <<<
         *
         * Weisung vom 9. September. Vier Rueckleiter Cu 95 ziehen im
         * Havariefall 24.0 kN statt 15.6 - ein Unterschied von 8.4 kN, der
         * vorher fehlte.
         */
        pruef('Cu 95 rechnet bei Havarie mit -20 Grad',
              FL.abfangkraft('drahtwerk-cu-95', { tempFall: 'havarie' }).Z,
              6.0, 1e-9, 'kN');
        pruef('… bei Schnee mit -5 Grad und Zusatzlast',
              FL.abfangkraft('drahtwerk-cu-95', { tempFall: 'schnee' }).Z,
              6.5, 1e-9, 'kN');

        /*
         * >>> DIE SPALTE «-5 °C +Z». <<<
         *
         * Weisung vom 9. September: «man kann fuer die bemessung -5° +Z
         * (0.007 kN/m) nehmen. dieser wert ist fuer Tragwerke die unterhalb
         * von 1000 hoehenmeter liegen.» Der Schnee haengt am Leiter und
         * zieht ihn straffer - 6.5 statt 4.6 kN beim Cu 95.
         */
        pruef('Der Schneefall traegt 0.007 kN/m',
              FL.reglierZusatzlast('schnee'), 0.007, 1e-12, 'kN/m');
        wahr('Wind und Havarie tragen keine',
             FL.reglierZusatzlast('tragsicherheit') === 0
             && FL.reglierZusatzlast('havarie') === 0);
        pruef('Ohne Zusatzlast steht die blosse Temperatur da',
              FL.reglageZug('drahtwerk-cu-95', -5), 4.6, 1e-9, 'kN');
        pruef('Mit 0.007 die Spalte +Z',
              FL.reglageZug('drahtwerk-cu-95', -5, { zusatzlast: 0.007 }),
              6.5, 1e-9, 'kN');
        pruef('Die Tabelle fuehrt auch 0.015',
              FL.reglageZug('drahtwerk-cu-95', -5, { zusatzlast: 0.015 }),
              8.4, 1e-9, 'kN');
        /*
         * INTERPOLIERT WIRD HIER NICHT. Die Spalte gilt bei -5 °C und fuer
         * genau die Lasten, die dastehen - alles andere waere erfunden.
         */
        wahr('Eine andere Zusatzlast gibt es nicht',
             FL.reglageZug('drahtwerk-cu-95', -5, { zusatzlast: 0.01 })
             === null);
        wahr('… und eine andere Temperatur auch nicht',
             FL.reglageZug('drahtwerk-cu-95', -20, { zusatzlast: 0.007 })
             === null);
        /*
         * VIER RUECKLEITER IM SCHNEE ziehen 26.0 kN - mehr als im
         * Havariefall mit 24.0. Der kaelteste Fall ist nicht der groesste.
         */
        pruef('Vier Rueckleiter im Schnee',
              FL.abfangkraft('drahtwerk-cu-95-x4',
                             { tempFall: 'schnee' }).Z, 26.0, 1e-9, 'kN');
        pruef('Vier Rueckleiter im Havariefall',
              FL.abfangkraft('drahtwerk-cu-95-x4',
                             { tempFall: 'havarie' }).Z, 24.0, 1e-9, 'kN');
        wahr('Der Wert kommt aus der Tabelle, nicht aus dem Katalog',
             FL.abfangkraft('drahtwerk-cu-95',
                            { tempFall: 'havarie' }).ausTabelle);
      }

      /*
       * ====== DIE QUERSCHNITTSWERTE DER STUETZEN ========================
       *
       * Weisung vom 11. September: «die querschnittswerte gemaess c5 szs
       * oder en nachtragen.» Sie standen nirgends: der Katalog fuehrte
       * «2x UNP 120» als Bezeichnung, und UNP-Profile stehen weder im
       * Profilkatalog des Werkzeugs noch - unter den naheliegenden Namen -
       * im Katalog von AxisVM.
       */
      if (AN.ankerDbDa()) {
        const qU12 = AN.ankerQuerschnitt('U12');
        const qU14 = AN.ankerQuerschnitt('U14');
        wahr('Beide Stuetzen fuehren ihre Werte',
             !!qU12?.A && !!qU14?.A);
        wahr('… und nennen ihre Quelle',
             /C5|EN /.test(qU12.quelle) && /C5|EN /.test(qU14.quelle));

        /*
         * >>> DIE PROBE IST DAS GEWICHT. <<<
         *
         * Ein abgetippter Wert faellt sonst erst im Nachweis auf, und dann
         * als Zahl ohne Herkunft. A und G stehen in der Tabelle getrennt
         * nebeneinander und haengen ueber die Dichte zusammen:
         *
         *      G [kg/m] = A [cm2] · 0.785
         *
         * Beide sind gerundet (A auf 0.1 cm2, G auf 0.1 kg/m), deshalb ein
         * Prozent Toleranz. Ein Zahlendreher faellt damit auf, eine Rundung
         * nicht.
         */
        [qU12, qU14].forEach((q) => {
          pruef(`${q.profil}: A mal Dichte gibt das Tabellengewicht`,
                q.AEinzel * 0.785 * q.anzahl, q.G, q.G * 0.01, 'kg/m');
        });
        /*
         * DER VERBUND IST DAS VIELFACHE - beide Profile liegen parallel,
         * die starke Achse faellt zusammen.
         */
        pruef('U12: A des Verbunds', qU12.A, qU12.AEinzel * qU12.anzahl,
              1e-9, 'cm2');
        pruef('U12: I_y des Verbunds', qU12.Iy, qU12.IyEinzel * qU12.anzahl,
              1e-9, 'cm4');
        /*
         * >>> I_z DES VERBUNDS IST NICHT ERFASST. <<<
         *
         * Es haengt am Spreizmass, und das steht in keiner Zeichnung, die
         * hier vorliegt. `null` sagt das; eine Zahl daraus zu machen hiesse,
         * das Mass zu erfinden.
         */
        wahr('I_z des Verbunds steht ausdruecklich auf null',
             qU12.Iz === null && qU14.Iz === null);
        wahr('… waehrend das Einzelprofil seines fuehrt',
             qU12.IzEinzel > 0 && qU14.IzEinzel > 0);
        /*
         * DER GROESSERE TYP IST GROESSER - eine Kontrolle, die ein
         * vertauschtes Wertepaar findet.
         */
        wahr('Der U14 hat mehr Flaeche und mehr Traegheit',
             qU14.A > qU12.A && qU14.Iy > qU12.Iy);
        /*
         * >>> BEIM SEIL STEHT DIE DEHNUNG IM BLATT, NICHT DIE FLAECHE. <<<
         *
         * 0.1 mm je Meter und kN heisst E·A = 10'000 kN. Die Flaeche folgt
         * daraus mit E = 21'000 kN/cm2.
         */
        const qS = AN.ankerQuerschnitt('SA20');
        pruef('Der Seilanker traegt E·A aus dem Blatt', qS.EA, 10000,
              1e-9, 'kN');
        pruef('… und seine Flaeche folgt daraus', qS.A * 21000, qS.EA,
              0.5, 'kN');
        wahr('Ein Seil hat kein Traegheitsmoment',
             qS.Iy === null && qS.Iz === null);
      }
    }

    /*
     * ================= DER BALKEN MIT ZWEI KRAGARMEN ====================
     *
     * Er traegt die Schnittgroessen des Abfangjochs. Geprueft wird gegen
     * die drei Faelle, die man im Kopf hat - sonst prueft man eine Formel
     * gegen sich selbst.
     */
    {
      const b1 = AK.abfangBalken(10, 0, { q: 1 });
      pruef('Gleichlast: M = qL²/8', b1.M(5), 12.5, 1e-9, 'kNm');
      pruef('… und V am Auflager qL/2', b1.V(0), -5, 1e-9, 'kN');
      pruef('… in der Mitte null', b1.V(5), 0, 1e-9, 'kN');
      const b2 = AK.abfangBalken(10, 0, { F: [{ x: 5, wert: 4 }] });
      pruef('Einzelkraft mittig: M = FL/4', b2.M(5), 10, 1e-9, 'kNm');
      /*
       * DER KRAGARM IST DER GRUND FUER DIESEN RECHNER. Das Abfangjoch
       * ragt an beiden Enden ueber die Auflager hinaus - bei A160 / 9.50 m
       * um 250 mm -, und dort sitzt der Nachweisschnitt.
       */
      const b3 = AK.abfangBalken(10, 2, { F: [{ x: 0, wert: 3 }] });
      pruef('Kragarm: M am Auflager = F·ue', Math.abs(b3.M(2)), 6, 1e-9, 'kNm');
      wahr('Am freien Ende ist er null', Math.abs(b3.M(0)) < 1e-9);
      // Das Gleichgewicht muss aufgehen: Summe der Auflagerkraefte = Last.
      const b4 = AK.abfangBalken(13, 0.25, { q: 1.2, F: [{ x: 4, wert: 9 }] });
      pruef('Die Auflagerkraefte tragen die ganze Last',
            b4.A + b4.B, 1.2 * 13 + 9, 1e-9, 'kN');
      wahr('Am Traegerende ist das Moment null',
           Math.abs(b4.M(0)) < 1e-9 && Math.abs(b4.M(13)) < 1e-9);
    }

    /*
     * ================ DIE AUSWERTUNG DES ABFANGJOCHS ====================
     *
     * Weisung vom 4. September: «nachweise beim Abfangjoch aktualisieren.»
     * Bis dahin standen rechts in der Anwendung die Nachweise des
     * TRAGJOCHS - Obergurt, Untergurt, Bindeblech -, waehrend links ein
     * Abfangjoch gewaehlt war.
     */
    {
      const at2 = [{ ...A.neuesAnbauteil('leiter-nfl', 4.0), name: 'N-FL' },
                   { ...A.neuesAnbauteil('leiter-rfl', 9.0), name: 'R-FL' }];
      const e2 = AK.abfangAuswertung({
        typ: 'A300', jt: 13.0, gk: 1.08, wk: 0.61, sk: 0.52,
        anbauteile: at2, gammaG: 1.3, gammaQ: 1.3, psi0: 0.5,
        fyd: 21.8, L_FL: 60 });
      wahr('Sie kommt zustande', Boolean(e2));
      pruef('Die Stuetzweite ist js, nicht jt', e2.js, 12.5, 1e-9, 'm');
      pruef('Der Ueberstand folgt daraus', e2.ueberstand, 0.25, 1e-9, 'm');
      /*
       * DIE LEITERZUGKRAEFTE KOMMEN AUS DEN KENNWERTEN (Weisung,
       * 4. September): N-FL 14.9 + R-FL 22.0 = 36.9 kN.
       */
      pruef('Der Leiterzug summiert die Kennwerte',
            e2.lasten.leiterzug, 36.9, 1e-9, 'kN');
      wahr('Der Gurtnachweis steht', Number.isFinite(e2.gurt?.eta));
      wahr('Der Blechnachweis auch', Number.isFinite(e2.blech?.eta));
      pruef('η gesamt ist der groessere der beiden', e2.max.eta,
            Math.max(e2.gurt.eta, e2.blech.eta), 1e-12, '-');
      /*
       * >>> MEHR LEITERZUG, MEHR AUSNUTZUNG. <<<
       *
       * Die Probe, die eine vertauschte Achse fangen wuerde: der Leiterzug
       * wirkt IN der Rahmenebene, und dort traegt der Vierendeel ueber das
       * Kraeftepaar N = M/e. Verdoppelt man ihn, muss N steigen.
       */
      const e3 = AK.abfangAuswertung({
        typ: 'A300', jt: 13.0, gk: 1.08, wk: 0.61, sk: 0.52,
        anbauteile: [...at2, { ...A.neuesAnbauteil('leiter-rfl', 6.0),
                               name: 'R-FL 2' }],
        gammaG: 1.3, gammaQ: 1.3, psi0: 0.5, fyd: 21.8, L_FL: 60 });
      wahr('Ein dritter Leiter erhoeht die Gurtkraft', e3.gurt.N > e2.gurt.N);
      wahr('… und damit die Ausnutzung', e3.max.eta > e2.max.eta);
      /*
       * EIN DURCHGEHENDER LEITER ZIEHT NICHT. Sein Eigengewicht bleibt,
       * seine Laengskraft nicht - der Unterschied muss sich im Nachweis
       * zeigen, sonst waere die Eingabe folgenlos.
       */
      const e4 = AK.abfangAuswertung({
        typ: 'A300', jt: 13.0, gk: 1.08, wk: 0.61, sk: 0.52,
        anbauteile: at2.map((t3) => ({ ...t3, verlauf: 'durchgehend' })),
        gammaG: 1.3, gammaQ: 1.3, psi0: 0.5, fyd: 21.8, L_FL: 60 });
      pruef('Durchgehend: kein Leiterzug', e4.lasten.leiterzug, 0, 1e-9, 'kN');
      wahr('… und eine kleinere Gurtkraft', e4.gurt.N < e2.gurt.N);
      /*
       * DIE BEIWERTE SIND DIE DER EINGABE - dieselben wie beim Tragjoch.
       * Ein groesseres γ_G muss durchschlagen.
       */
      const e5 = AK.abfangAuswertung({
        typ: 'A300', jt: 13.0, gk: 1.08, wk: 0.61, sk: 0.52,
        anbauteile: at2, gammaG: 1.5, gammaQ: 1.3, psi0: 0.5,
        fyd: 21.8, L_FL: 60 });
      wahr('Ein groesseres γ_G erhoeht die Ausnutzung',
           e5.max.eta > e2.max.eta);
      // Ohne erfasste Laenge gibt es keine Auswertung, statt einer erfundenen.
      wahr('Eine ungefuehrte Laenge gibt null',
           AK.abfangAuswertung({ typ: 'A300', jt: 13.37 }) === null);
    }

    /*
     * ================= DIE LASTEN IM BILD ===============================
     *
     * Weisung vom 4. September: «Die lasten darstellen im 3d die die
     * leiterzugkraefte ausweisen.» Gezeichnet wird, was das Modell
     * aufbringt - dieselbe Quelle, `abfangAnbauLasten`.
     */
    {
      const at3 = [{ ...A.neuesAnbauteil('leiter-nfl', 4.0), name: 'N-FL' },
                   { ...A.neuesAnbauteil('leiter-rfl', 9.0), name: 'R-FL',
                     verlauf: 'hinten' },
                   { ...A.neuesAnbauteil('leiter-rl', 11.0), name: 'RL',
                     verlauf: 'durchgehend' }];
      const szL = R3D.abfangSzene('A300', 13.0,
        { anbauteile: at3, L_FL: 60, ek: 'EK2' });
      const zug = szL.vektoren.filter((v) => v.lastart === 'leiterzug');
      pruef('Zwei Leiterzugpfeile - der dritte geht durch',
            zug.length, 2, 1e-9, 'Stk');
      wahr('Der vordere zieht nach +y, der hintere nach -y',
           zug.some((v) => v.v[1] > 0) && zug.some((v) => v.v[1] < 0));
      wahr('Sie nennen ihre Kraft',
           zug.every((v) => /Z_ab = \d/.test(v.text)));
      wahr('Alle drei tragen ihr Eigengewicht',
           szL.vektoren.filter((v) => v.lastart === 'staendig').length === 3);
      /*
       * >>> DER ZUGPFEIL SITZT AN DER ABSPANNUNG. <<<
       *
       * Weisung vom 9. September: «den kraftvektor auf die markierung
       * schieben und nicht in der mitte joch.» Der Leiter endet am Klotz,
       * und dort zieht er; auf der Jochachse sah es aus, als greife die
       * Kraft am Traeger selbst an.
       *
       * DAS MODELL BLEIBT: die Ausleitung setzt Z weiter auf den Knoten der
       * Traegerachse - das prueft der Abschnitt gleich darunter.
       */
      wahr('Die uebrigen Pfeile greifen auf der Jochachse an',
           szL.vektoren.filter((v) => v.lastart !== 'leiterzug')
             .every((v) => v.p[1] === 0 && v.p[2] === 0));
      wahr('Der Zugpfeil sitzt am Ende des Leiters',
           zug.every((v) => Math.abs(v.p[1]) > 1 && v.p[2] < 0),
           zug.map((v) => `y ${v.p[1].toFixed(2)} z ${v.p[2].toFixed(2)}`).join(' · '));
      wahr('… und auf der Seite, auf der er abgefangen wird',
           zug.every((v) => Math.sign(v.p[1]) === Math.sign(v.v[1])));
      /*
       * DIESELBE QUELLE WIE DIE AUSLEITUNG. Ein Bild, das eine Kraft zeigt,
       * die das Modell nicht aufbringt, ist schlimmer als keines.
       */
      const mL = XA.abfangAxisvmModell('A300', 13.0,
        { anbauteile: at3, L_FL: 60, ek: 'EK2' });
      const fh = mL.lasten.punkt.filter((p2) => p2.lastfall === 'Leiterzug');
      pruef('Auch das Modell kennt zwei Leiterzugkraefte',
            fh.length, 2, 1e-9, 'Stk');
      wahr('Und dieselben Betraege wie das Bild',
           fh.every((p2) => zug.some(
             (v) => v.text.includes(Math.abs(p2.wert).toFixed(2)))));
    }

    /*
     * ============ WO EIN ANBAUTEIL AM ABFANGJOCH ANGREIFT ===============
     *
     * Weisung vom 4. September: «die anbindung an das joch erfolgt ueber die
     * beiden gurte fuer die vertikalen elemente (jochaufsatz / haengestuetze
     * / fahrleitung etc.) Die Abgefangenen Leiter wirken auf mitte Traeger.
     * Die Abgefangenen leiter koennen auf beiden Seiten angesetzt werden.»
     */
    {
      const nfl = { ...A.neuesAnbauteil('leiter-nfl', 4.0), name: 'N-FL' };
      const rfl = { ...A.neuesAnbauteil('leiter-rfl', 8.0), name: 'R-FL',
                    seite: 'H' };
      const hs = { ...A.neuesAnbauteil('hs-fahrdraht', 6.0), name: 'HS' };
      pruef('Der Leiter zieht auf Mitte Traeger',
            AK.abfangAnbindung(nfl).art === 'mitte' ? 1 : 0, 1, 1e-9, '-');
      pruef('Die Haengestuetze sitzt auf beiden Gurten',
            AK.abfangAnbindung(hs).art === 'gurte' ? 1 : 0, 1, 1e-9, '-');
      /*
       * >>> DER VERLAUF, NICHT DIE SEITE. <<<
       *
       * Weisung vom 4. September: «ist dieser durchgehen (keine
       * abfangkraefte) oder wird dieser vorne oder hinten abgefangen».
       * Ohne Angabe gilt «vorn abgefangen» - ein Abfangjoch faengt ab.
       */
      wahr('Ohne Angabe wird vorn abgefangen',
           AK.abfangAnbindung(nfl).verlauf === 'vorn'
           && AK.abfangAnbindung(nfl).seite === 'V');
      wahr('Die alte Angabe seite:H gilt weiter als «hinten abgefangen»',
           AK.abfangAnbindung({ ...nfl, seite: 'H' }).verlauf === 'hinten');
      wahr('Mit Angabe von hinten', AK.abfangAnbindung(rfl).seite === 'H');
      const durch = { ...nfl, verlauf: 'durchgehend' };
      wahr('Ein durchgehender Leiter hat keine Seite',
           AK.abfangAnbindung(durch).seite === null);
      wahr('… und faengt nichts ab', !AK.abfangAnbindung(durch).abgefangen);
      wahr('Ein abgefangener schon', AK.abfangAnbindung(nfl).abgefangen);
      /*
       * IM MODELL: kein Leiterzug, aber Eigengewicht und Wind. Ein
       * durchgehender Leiter haengt am Joch, er zieht nur nicht daran.
       */
      const mD = XA.abfangAxisvmModell('A300', 13.0,
        { anbauteile: [durch], L_FL: 60 });
      wahr('Der durchgehende Leiter traegt keinen Leiterzug',
           !mD.lasten.punkt.some((p2) => p2.name === 'FH_AT1'));
      wahr('Wohl aber Eigengewicht',
           mD.lasten.punkt.some((p2) => p2.name === 'G_AT1' && p2.wert < 0));
      /*
       * >>> UND DIE PAUSCHALE ENTFAELLT. <<<
       *
       * Weisung vom 9. September: «die pauschale bei durchgehend
       * rausnehmen.» Bis dahin bekam ein Modell mit ausschliesslich
       * durchgehenden Leitern die Regelabfangung von 22 kN - eine Last, die
       * aus keiner Eingabe folgt und die der Nachweis nicht kennt (dort
       * stand 0.00 kN).
       *
       * Wer «durchgehend» eintraegt, hat die Abfangung beschrieben; sie ist
       * null. Der Regelfall gilt nur noch, wo GAR KEIN Leiter steht.
       */
      wahr('Und die pauschale Abfangkraft entfaellt',
           !mD.lasten.punkt.some((p2) => p2.name === 'FH_V'
                                      || p2.name === 'FH_H'));
      {
        const mLeer = XA.abfangAxisvmModell('A300', 13.0, { anbauteile: [] });
        wahr('Ohne jeden Leiter bleibt der Regelfall',
             mLeer.lasten.punkt.some((p2) => p2.name === 'FH_V')
             && mLeer.lasten.punkt.some((p2) => p2.name === 'FH_H'));
        const mHs = XA.abfangAxisvmModell('A300', 13.0, { anbauteile: [hs] });
        wahr('… und auch bei einem Teil, das kein Leiter ist',
             mHs.lasten.punkt.some((p2) => p2.name === 'FH_V'));
      }
      wahr('Die Vorgabe ist als solche gekennzeichnet',
           AK.abfangAnbindung(nfl).vorgegeben);
      wahr('Eine gesetzte Anbindung sticht sie aus',
           AK.abfangAnbindung({ ...nfl, anbindung: 'gurte' }).art === 'gurte');
      // Beim vertikalen Element gibt es keine Seite - es sitzt auf beiden.
      wahr('Das vertikale Element kennt keine Seite',
           AK.abfangAnbindung(hs).seite === null);

      /*
       * IM MODELL: EIN KNOTEN AUF DER JOCHACHSE, STARRE ARME ZU DEN GURTEN.
       * Der Leiter bekommt einen Arm, das vertikale Element zwei.
       */
      const mA = XA.abfangAxisvmModell('A300', 13.0,
        { anbauteile: [nfl, rfl, hs], L_FL: 60 });
      pruef('Drei Anbauteile, drei Knoten',
            mA.knoten.filter((n2) => /^AT\d+$/.test(n2.name)).length,
            3, 1e-9, 'Stk');
      wahr('Sie sitzen auf der Jochachse',
           mA.knoten.filter((n2) => /^AT\d+$/.test(n2.name))
             .every((n2) => n2.y === 0 && n2.z === 0));
      pruef('Vier starre Arme: 1 + 1 + 2',
            mA.staebe.filter((x2) => /^ATARM_/.test(x2.name)).length,
            4, 1e-9, 'Stk');
      wahr('… und alle sind Starrkoerper',
           mA.staebe.filter((x2) => /^ATARM_/.test(x2.name))
             .every((x2) => x2.art === 'starr'));
      // Der Leiter vorn zieht in +y, der hintere in -y.
      const fh = (n2) => mA.lasten.punkt.find((p2) => p2.name === n2);
      pruef('Der Leiter vorn zieht mit +14.9 kN', fh('FH_AT1').wert,
            14.9, 1e-9, 'kN');
      pruef('Der hintere mit -22', fh('FH_AT2').wert, -22, 1e-9, 'kN');
      wahr('Die Haengestuetze traegt keinen Leiterzug', !fh('FH_AT3'));
      wahr('Wohl aber Eigengewicht', fh('G_AT3').wert < 0);
      /*
       * DIE PAUSCHALE ABFANGKRAFT WEICHT, sobald abgefangene Leiter
       * eingetragen sind - sonst stuende sie zusaetzlich in der Mitte.
       */
      wahr('Die pauschale Abfangkraft steht dann nicht mehr da',
           !mA.lasten.punkt.some((p2) => p2.name === 'FH_V'));
      const mB = XA.abfangAxisvmModell('A300', 13.0, { anbauteile: [hs] });
      wahr('Ohne Leiter bleibt sie',
           mB.lasten.punkt.some((p2) => p2.name === 'FH_V'));
    }

    /*
     * DIE GEGENPROBE AN EINEM GEKROPFTEN TYP. A160 ist gerade; erst A240
     * zeigt, was die Weisung meint.
     */
    {
      const m2 = XA.abfangAxisvmModell('A240', 14.0, {});
      const yV = m2.knoten.filter((n2) => /^V_/.test(n2.name))
        .sort((a2, b2) => a2.x - b2.x);
      const eAm = (x) => {
        const n2 = yV.reduce((b2, k2) => (Math.abs(k2.x - x) < Math.abs(b2.x - x)
          ? k2 : b2), yV[0]);
        return Math.round(n2.y * 2000);
      };
      pruef('A240 im Feld: 656 mm Achsabstand', eAm(7.0), 656, 1e-9, 'mm');
      pruef('… am langen Jochende nur 336', eAm(0), 336, 1e-9, 'mm');
      pruef('… und am kurzen ebenso', eAm(14.0), 336, 1e-9, 'mm');
      pruef('Der Knick bei 0.850 m ist ein Knoten',
            yV.filter((n2) => Math.abs(n2.x - 0.85) < 1e-9).length, 1, 1e-9, 'Stk');
      pruef('Die volle Weite steht ab 1.940 m',
            yV.filter((n2) => Math.abs(n2.x - 1.94) < 1e-9).length, 1, 1e-9, 'Stk');
      /*
       * DIE RIEGEL SPANNEN UEBER DIE LICHTE WEITE IHRER STATION - nicht
       * ueber eine feste Zahl. Im Feld sind das 600, am Jochende 280.
       */
      const kn3 = new Map(m2.knoten.map((n2) => [n2.name, n2]));
      const bl3 = m2.staebe.filter((x2) => /^BL_O\d+_2$/.test(x2.name));
      const laengen = new Set(bl3.map((x2) => Math.round(
        (kn3.get(x2.bis).y - kn3.get(x2.von).y) * 1000)));
      wahr('Im Feld messen die Riegel 600', laengen.has(600));
      wahr('… und im Anzug sind sie kuerzer',
           [...laengen].some((v) => v > 400 && v < 600));
    }

    /*
     * >>> DIE AUFLAGER SIND UM y UND z FREI. <<<
     *
     * Weisung vom 3. September. Die Torsion um die Traegerachse bleibt
     * gehalten; in Laengsrichtung haelt nur EIN Ende, sonst bekaeme der
     * Traeger Zwang aus seiner eigenen Verkuerzung.
     */
    wahr('Beide Biegungen sind gelenkig',
         m.auflager.every((l) => l.fiy === 'Free' && l.fiz === 'Free'));
    wahr('Die Torsion ist gehalten',
         m.auflager.every((l) => l.fix === 'Rigid'));
    wahr('Nur ein Ende haelt in Laengsrichtung',
         m.auflager.filter((l) => l.ux === 'Rigid').length === 1
         && m.auflager.filter((l) => l.ux === 'Free').length === 1);
    /*
     * >>> EIN PUNKT JE ENDE, NICHT ZWEI GURTE. <<<
     *
     * Weisung vom 4. September: «die gabel gegen ende hin ist offen. nur
     * ueber die auflagerpunkte lagern.» Zwei gehaltene Gurtknoten koennten
     * ein Kraeftepaar aufnehmen und das Ende um z einspannen - die offene
     * Gabel kann das nicht.
     */
    pruef('Zwei Auflager - eines je Ende', m.auflager.length, 2, 1e-9, 'Stk');
    wahr('Sie sitzen auf der Jochachse',
         m.auflager.every((l) => {
           const k2 = m.knoten.find((n2) => n2.name === l.knoten);
           return Math.abs(k2.y) < 1e-12 && Math.abs(k2.z) < 1e-12;
         }));
    wahr('Ein Schott haengt sie starr an beide Gurte',
         m.staebe.filter((x) => x.name.startsWith('SCHOTT_')).length === 4
         && m.staebe.filter((x) => x.name.startsWith('SCHOTT_'))
              .every((x) => x.art === 'starr'));

    /*
     * DER LEITERZUG GREIFT IN DER TRAEGERMITTELEBENE AN (Weisung) - auf
     * beide Gurte gleich, keine planmaessige Torsion. Er wirkt in y.
     */
    wahr('Der Leiterzug wirkt in Gleisrichtung',
         m.lasten.punkt.every((l) => l.richtung === 'Y'));
    pruef('Er teilt sich auf beide Gurte',
          m.lasten.punkt.reduce((a2, l) => a2 + l.wert, 0), 22, 1e-9, 'kN');
    wahr('Und beide bekommen gleich viel',
         m.lasten.punkt[0].wert === m.lasten.punkt[1].wert);
    // Das Eigengewicht quer dazu, je Gurt die Haelfte.
    /*
     * DREI STRECKENLASTEN, DREI RICHTUNGEN. Bis zum 4. September trug das
     * Modell nur das Eigengewicht; seither kommen Wind und Schnee auf den
     * Jochtraeger dazu (Weisung: «der wind auf den jochtraeger kann den
     * grundlagen entnommen werden»). Der Wind steht waagrecht quer zur
     * Traegerachse - in Gleisrichtung -, Eigengewicht und Schnee lotrecht.
     */
    const q = (lf) => m.lasten.strecke.filter((l) => l.lastfall === lf);
    wahr('Das Eigengewicht wirkt lotrecht nach unten',
         q('G').length > 0 && q('G').every((l) => l.richtung === 'Z' && l.wert < 0));
    wahr('Der Schnee ebenso',
         q('SchneeJoch').every((l) => l.richtung === 'Z' && l.wert < 0));
    wahr('Der Wind waagrecht in Gleisrichtung',
         q('WindJoch').length > 0
         && q('WindJoch').every((l) => l.richtung === 'Y'));
    /*
     * DIE ZAHLEN STEHEN IN DER SORTIMENTSTABELLE, nicht in einer Formel:
     * A160 traegt 0.32 kN/m Wind bei EK2 und 0.24 kN/m Schnee bei 1.25 -
     * je Gurt die Haelfte.
     */
    pruef('A160: Wind 0.32 kN/m, je Gurt 0.16',
          q('WindJoch')[0].wert, 0.16, 1e-9, 'kN/m');
    pruef('… und Schnee 0.24, je Gurt 0.12',
          q('SchneeJoch')[0].wert, -0.12, 1e-9, 'kN/m');

    /*
     * >>> KEIN VERWEIS INS LEERE. <<<
     *
     * Das COM-Skript liest die Datei stur: es sucht jeden Knoten, jeden
     * Stab, jeden Lastfall in seiner Tabelle nach. Was es dort nicht
     * findet, meldet es als «Punktlast an unbekanntem Knoten» - oder bricht
     * ab. Dieselbe Probe hier, ueber vier Typen und mit Anbauteilen, kostet
     * nichts und faengt genau diese Klasse Fehler.
     */
    for (const [t2, jt2] of [['A160', 9.5], ['A240', 14.0],
                             ['A300', 13.0], ['A360', 21.5]]) {
      const mv = XA.abfangAxisvmModell(t2, jt2, { anbauteile: [
        { ...A.neuesAnbauteil('leiter-nfl', 4.0), name: 'N-FL' },
        { ...A.neuesAnbauteil('leiter-rfl', 8.0), name: 'R-FL', verlauf: 'hinten' },
        { ...A.neuesAnbauteil('hs-fahrdraht', 6.0), name: 'HS' },
      ], L_FL: 60, ek: 'EK2' });
      const kn = new Set(mv.knoten.map((n2) => n2.name));
      const st = new Set(mv.staebe.map((x2) => x2.name));
      const qs = new Set(mv.querschnitte.map((x2) => x2.name));
      const lfk = new Set(mv.lastfaelle.map((x2) => x2.key));
      wahr(`${t2}: jeder Stab haengt an zwei bekannten Knoten`,
           mv.staebe.every((x2) => kn.has(x2.von) && kn.has(x2.bis)));
      wahr(`${t2}: jeder Stab hat seinen Querschnitt`,
           mv.staebe.every((x2) => qs.has(x2.querschnitt)));
      wahr(`${t2}: jede Last sitzt an einem bekannten Ort`,
           mv.lasten.punkt.every((p2) => kn.has(p2.knoten))
           && mv.lasten.strecke.every((p2) => st.has(p2.stab)));
      wahr(`${t2}: jede Last kennt ihren Lastfall`,
           mv.lasten.punkt.every((p2) => lfk.has(p2.lastfall))
           && mv.lasten.strecke.every((p2) => lfk.has(p2.lastfall)));
      wahr(`${t2}: jede Kombination auch`,
           mv.kombinationen.every((k2) => k2.anteile.every(
             (an2) => lfk.has(an2.lastfall))));
      wahr(`${t2}: jede Lastrichtung ist X, Y oder Z`,
           [...mv.lasten.punkt, ...mv.lasten.strecke].every(
             (p2) => ['X', 'Y', 'Z'].includes(p2.richtung)));
    }

    /*
     * OHNE ERFASSTE BLECHEINTEILUNG KEIN MODELL - die Bleche stuenden
     * sonst irgendwo, und das Modell saehe richtig aus.
     */
    let flog = null;
    try { XA.abfangAxisvmModell('A200', 10.3, {}); } catch (e) { flog = e; }
    wahr('Ohne Blecheinteilung wirft es', flog !== null);
  }

  /*
   * >>> DAS MASSGEBENDE RAHMENFELD IST NICHT DIE REGELTEILUNG. <<<
   *
   * Gefunden am 3. September beim Vergleich mit AxisVM und PyNite: beide
   * gaben ein Gurtmoment vier- bis fuenfmal ueber dem des Kerns, und die
   * massgebende Stelle war nicht die Feldmitte, sondern das AUFLAGER.
   *
   * Der Grund ist Geometrie, kein Kennwert: zwischen Auflager und erstem
   * Blech liegen bei A160 / 9.50 m ganze 2.00 m, die Regelteilung misst
   * 0.50. Das erste Rahmenfeld ist VIERMAL so lang - und dort steht
   * zugleich die groesste Querkraft.
   *
   * Gemessen: eta 0.61 mit der Regelteilung, 1.65 mit dem Randfeld,
   * 1.54 in AxisVM. Der Kern lag auf der UNSICHEREN Seite, um das
   * Zweieinhalbfache; mit dem richtigen Feld trifft er AxisVM auf sieben
   * Prozent und bleibt konservativ.
   */
  {
    const AK = await import(J('core.abfangjoch.js'));
    const rf = AK.abfangRahmenfeld('A160', 9.5);
    wahr('Es gibt ein massgebendes Rahmenfeld', Boolean(rf));
    /*
     * >>> DAS RANDFELD IST KLEINER GEWORDEN - UND RICHTIGER. <<<
     *
     * Hier standen 2.00 m und der Faktor 4. Das war die symmetrische Reihe
     * ohne die Endbleche. Nach dem Schema sitzt das erste Blech bei
     * 1.450 m, und das Auflager liegt um den Ueberstand (jt - js)/2 = 0.25
     * naeher: 1.200 m bleiben, knapp zweieinhalb Regelteilungen. Das
     * Randfeld ist immer noch das massgebende - nur nicht mehr so gross,
     * wie die Schaetzung glauben machte.
     */
    pruef('Der Ueberstand ueber das Auflager', rf.ueberstand, 0.25, 1e-6, 'm');
    pruef('Das Randfeld misst 1.20 m', rf.randfeld, 1.2, 1e-6, 'm');
    pruef('Und ist das laengste', rf.a, 1.2, 1e-6, 'm');
    pruef('Zweikommavier Regelteilungen', rf.faktor, 2.4, 1e-6, '-');
    /*
     * DIE FELDER DECKEN DIE STUETZWEITE - kein Stueck faellt weg. Waere
     * eines vergessen, waere der Nachweis dort blind.
     */
    const sw = AK.abfangStuetzweite('A160', 9.5);
    pruef('Die Felder decken die Stuetzweite',
          rf.felder.reduce((a2, b2) => a2 + b2, 0), sw.bis, 1e-6, 'm');
    /*
     * IN DER MITTE SITZT KEIN BLECH - A160 / 9.50 m fuehrt A1 = 250, und
     * die beiden halben Felder sind zusammen ein Regelfeld von 500. Hier
     * stand 0.25; das war die Fassung mit dem Blech dazwischen.
     */
    pruef('Das kuerzeste Feld ist die Regelteilung',
          Math.min(...rf.felder), 0.5, 1e-6, 'm');

    /*
     * >>> UND DAS AENDERT DEN NACHWEIS. <<<
     *
     * Dieselbe Rechnung, einmal mit der Regelteilung und einmal mit dem
     * Randfeld. Der Unterschied ist der Faktor, um den der Kern danebenlag.
     */
    const q = AK.abfangQuerschnitt('A160');
    const F = 22, L = sw.bis;
    const s0 = { Mzz: (F * L) / 4, Myy: 0, Fy: F / 2 };
    const mitTeilung = AK.abfangGurtnachweis(q, s0, rf.teilung, 21.8);
    const mitRand = AK.abfangGurtnachweis(q, s0, rf.a, 21.8);
    wahr('Mit dem Randfeld faellt der Nachweis strenger aus',
         mitRand.eta > mitTeilung.eta);
    pruef('… und zwar um den Faktor des Feldes',
          mitRand.Moertl / mitTeilung.Moertl, rf.faktor, 1e-9, '-');
    /*
     * DIE GEGENPROBE AN AxisVM. Gemessen am 3. September fuer A160 / 9.50 m
     * unter 22 kN Leiterzug: sigma 33.56, eta 1.539. Der Kern darf darueber
     * liegen - konservativ ist richtig - aber nicht um Welten, sonst waere
     * das Sortiment unbrauchbar.
     */
    /*
     * >>> DIE AxisVM-REFERENZ IST HINFAELLIG. <<<
     *
     * Sie wurde am 3. September gemessen (eta 1.539) - mit dem damaligen
     * Hebelarm (38.3 statt 31.7 cm) UND dem damaligen Querschnitt (I_z 85.3
     * statt 106.8). Beide sind seither berichtigt; die Zahl gehoert neu
     * gemessen, sobald das Modell wieder rechnet.
     *
     * Was bleibt und geprueft wird, ist die AUSSAGE, die von der Referenz
     * unabhaengig ist: mit dem Randfeld faellt der Nachweis strenger aus als
     * mit der Regelteilung, und zwar um den Faktor des Feldes. Eine
     * Zahlengegenprobe, die auf ueberholten Daten beruht, waere schlimmer
     * als keine.
     */
    wahr('Das Randfeld schaerft den Nachweis um den Feldfaktor',
         Math.abs(mitRand.Moertl / mitTeilung.Moertl - rf.faktor) < 1e-9);

    // Ohne erfasste Einteilung kein Rahmenfeld - keine geratene Laenge.
    wahr('Ohne Einteilung kein Rahmenfeld',
         AK.abfangRahmenfeld('A200', 10.3) === null);
  }

  /*
   * >>> EIN SCHALTER DARF SICH NICHT SELBST VERSTECKEN. <<<
   *
   * Weisung vom 3. September: «Dieser button ist sehr maechtig. wie kann man
   * sonst die Masten wieder einblenden?»
   *
   * Das Symbol in der Tragwerksleiste schaltet die Masten eines Tragwerks
   * aus - und war danach der EINZIGE Weg zurueck: alle uebrigen Mastfelder
   * haengen an `mastDa`, mit den Masten verschwand also die ganze Gruppe
   * «Masten» aus der Seitenleiste. Gemessen: null Felder blieben stehen.
   */
  {
    const { sichtbareFelder: sfM } = await import(J('ui.schema.js'));
    const w = standardwerte();
    const mit = sfM('mast', w).map((f) => f.key);
    const ohne = sfM('mast', { ...w, mastVorhanden: false })
      .map((f) => f.key);
    wahr('Mit Masten steht die Gruppe voll da', mit.length > 5);
    /*
     * DAS IST DER KERN: ohne Masten bleibt GENAU EIN Feld - der Schalter,
     * der sie zurueckholt. Faellt er je weg, ist der Rueckweg wieder nur
     * das Symbol in der Leiste.
     */
    wahr('Ohne Masten bleibt der Rueckweg stehen',
         ohne.includes('mastVorhanden'));
    pruef('… und zwar als einziges Feld', ohne.length, 1, 1e-9, 'Stk');
    wahr('Er steht auch im vollen Zustand da', mit.includes('mastVorhanden'));
    // Beim Einzelmasten gaebe es nichts abzuschalten - er IST der Mast.
    wahr('Beim Einzelmasten steht er nicht',
         !sfM('mast', { ...w, tragwerksart: 'einzelmast' })
           .map((f) => f.key).includes('mastVorhanden'));
  }

  /*
   * DIE ZEICHNUNG SCHIEBEN - der Massstab bleibt unangetastet.
   *
   * Geprueft wird an der Kalibrierung selbst, ohne Zeichenflaeche: die
   * Umrechnung Bildschirm -> Welt braucht einen Projektor, das Verschieben
   * in Metern nicht. Und genau das ist der Weg der Pfeiltasten.
   */
  {
    const schieb = R75.Modellansicht.prototype.verschiebeZeichnungWelt;
    const stand = { zeichnung: { kalibrierung: { s: 0.01, x0: -10, z0: 4 } },
                    opt: {} };
    wahr('Verschoben wird', schieb.call(stand, 0.30, -0.20) === true);
    pruef('x0 folgt', stand.zeichnung.kalibrierung.x0, -9.70, 1e-12, 'm');
    pruef('z0 folgt', stand.zeichnung.kalibrierung.z0, 3.80, 1e-12, 'm');
    pruef('Der Massstab bleibt', stand.zeichnung.kalibrierung.s, 0.01, 1e-15,
          'm/Punkt');
    wahr('Ohne Kalibrierung passiert nichts',
         schieb.call({ zeichnung: null, opt: {} }, 1, 1) === false);
    wahr('Eine unbrauchbare Zahl wird abgewiesen',
         schieb.call(stand, NaN, 0) === false);
    pruef('… und laesst die Lage stehen', stand.zeichnung.kalibrierung.x0,
          -9.70, 1e-12, 'm');
  }
}

titel('61  Der Feldkatalog und das Fenster der Bauteildaten');
/* ===========================================================================
 * >>> DER KATALOG IST DIE PRUEFREGEL, NICHT NUR EINE ANSCHRIFT. <<<
 * ===========================================================================
 *
 * Weisung vom 16. September: alle Tragwerksdaten aus der Datenbank, die
 * Parameter in Tabellen, die Daten strukturierter. Der Katalog beschreibt
 * JEDE Spalte JEDER Tabelle der Dateien - mit Einheit, Pflicht und Bereich.
 *
 * DIESE KONTROLLEN PRUEFEN DEN KATALOG GEGEN DIE WIRKLICHEN DATEIEN. Eine
 * Spalte ohne Eintrag fällt hier auf, nicht erst, wenn jemand eine Höhe in
 * der falschen Einheit pflegt.
 * ========================================================================= */
{
  const K = await import(J('data.katalog.js'));
  const D = await import(J('ui.daten.js'));
  const X = await import(J('export.xlsx.js'));
  const roh = (n) => JSON.parse(readFileSync(join(HIER, 'data', n + '.json'), 'utf8'));
  const tab = {};
  for (const s of TBF.SORTIMENTE) tab[s] = roh(s);
  const baum = Object.fromEntries(Object.entries(tab)
    .map(([s, t]) => [s, TBF.setzeZusammen(t)]));

  pruef('Elf Abschnitte', K.ABSCHNITTE.length, 11, 1e-12, 'Stk');
  wahr('Jeder Abschnitt nennt Sortiment, Tabelle und Schluessel',
       K.ABSCHNITTE.every((a) => TBF.SORTIMENTE.includes(a.db) && a.tabelle && a.schluessel));
  wahr('Jeder Abschnitt ist Norm oder Sortiment',
       K.ABSCHNITTE.every((a) => ['norm', 'sortiment'].includes(a.herkunft)));
  wahr('Jede Haupttabelle des Aufbaus hat ihren Abschnitt',
       TBF.SORTIMENTE.every((s) => TBF.AUFBAU[s].listen.every((l) =>
         K.ABSCHNITTE.some((a) => a.db === s && a.tabelle === l.name))));
  wahr('Jede Untertabelle des Aufbaus hat ihre Beschreibung',
       TBF.SORTIMENTE.every((s) => TBF.tabellenVon(s).filter((t) => !t.haupt)
         .every((t) => K.ABSCHNITTE.some((a) => a.db === s && a.tabellen?.[t.name]))),
       TBF.SORTIMENTE.flatMap((s) => TBF.tabellenVon(s).filter((t) => !t.haupt
         && !K.ABSCHNITTE.some((a) => a.db === s && a.tabellen?.[t.name]))
         .map((t) => `${s}/${t.name}`)).join(', '));
  /*
   * EINE ZAHL OHNE EINHEIT IST DIE FALLE, um die es hier geht. Ausgenommen
   * sind reine Zählwerte; sie tragen `einheit: null` ausdrücklich.
   */
  {
    const ohne = [];
    for (const s of TBF.SORTIMENTE) {
      for (const t of K.tabellenKatalog(s)) {
        for (const sp of t.spalten) {
          if (sp.feld.typ === 'zahl' && sp.feld.einheit === undefined) {
            ohne.push(`${s}/${t.name}/${sp.pfad}`);
          }
        }
      }
    }
    wahr('Jede Zahl im Katalog nennt ihre Einheit oder sagt ausdruecklich keine',
         ohne.length === 0, ohne.join(' | '));
  }

  // --- Die Dateien gegen den Katalog ----------------------------------------
  {
    let unbekannt = 0;
    let bereich = 0;
    const fehler = [];
    for (const s of TBF.SORTIMENTE) {
      const r = K.pruefeTabellen(s, tab[s]);
      fehler.push(...r.fehler);
      unbekannt += r.warnung.filter((w) => /ohne Katalogeintrag/.test(w)).length;
      bereich += r.warnung.filter((w) => /erwartet/.test(w)).length;
    }
    wahr('Jede Spalte jeder Datei steht im Katalog', unbekannt === 0, `${unbekannt} ${TBF.SORTIMENTE.flatMap((s) => K.pruefeTabellen(s, tab[s]).warnung.filter((w) => /ohne Katalogeintrag/.test(w))).join(" | ")}`);
    wahr('Kein Wert liegt ausserhalb seines Bereichs', bereich === 0, `${bereich}`);
    /*
     * >>> DER BESTAND IST FEHLERFREI - SEIT DEM 20. SEPTEMBER. <<<
     *
     * Hier stand «genau EIN Fehler, und er ist echt»: «abfangjoch-a200»
     * gab es zweimal in der Lasttabelle, mit 0.66 und mit 0.58 kN/m -
     * altes und neues Bausortiment unter derselben Kennung. Beim Laden
     * des Datenpakets fiel es auf («1 Fehler - so laesst sich der Stand
     * nicht uebernehmen»), und im laufenden Betrieb gewann still der
     * erste Treffer: das ALTE mit 0.66.
     *
     * Weisung: «nur abfangjoch mit 0.58 nehmen, so wie in den
     * projektierungsdokumenten» und «in der bennenung sollte alt neu
     * unterschieden werden». Die Typentabelle unterscheidet laengst - dort
     * heisst die alte Reihe nach ihrem Profil (UAP 130 .. UAP 250), die
     * neue A160..A360. Die Lasttabelle tut es jetzt auch; die Gewichte
     * ordnen eindeutig zu (0.66 kN/m = UAP 200 mit 66 kg/m).
     *
     * Die alte Kontrolle hielt den Befund fest und sagte: «wird die
     * Kennung berichtigt, faellt sie - und das ist dann die richtige
     * Meldung.» Genau so ist es gekommen.
     */
    pruef('Kein Fehler im Bestand', fehler.length, 0, 1e-12, 'Stk');
    {
      // Die Lasttabelle war die Stelle: dort ist `id` der Schluessel.
      const ids = (tab.fl_bauteile?.tabellen?.bauteile ?? []).map((z) => z.id);
      const doppelt = [...new Set(ids.filter((k, i) => ids.indexOf(k) !== i))];
      wahr('… keine Kennung der Lasttabelle steht zweimal da',
           doppelt.length === 0, doppelt.join(' · ') || `${ids.length} Bauteile`);
      // Und die beiden Abfangjochreihen sind auseinanderzuhalten.
      const abf = (tab.fl_bauteile?.tabellen?.bauteile ?? [])
        .filter((z) => /^abfangjoch-/.test(String(z.id)));
      const alt2 = abf.filter((z) => /altes Bausortiment/.test(String(z.bemerkung ?? '')));
      wahr('… und die alte Reihe heisst nach ihrem Profil',
           alt2.length > 0 && alt2.every((z) => /^UAP |^IPE /.test(String(z.name))),
           alt2.map((z) => z.name).join(', ') || 'keine alte Reihe');
    }
    const gesamt = K.pruefeBestand(baum);
    pruef('Die Pruefung am Baum sagt dasselbe', gesamt.fehler.length, 0, 1e-12, 'Stk');
    pruef('… ueber alle elf Abschnitte', gesamt.abschnitte.length, 11, 1e-12, 'Stk');
  }

  // --- Was die Pruefung abweisen muss -----------------------------------------
  {
    const st = (z) => K.pruefeTabelle('normen', 'stahlgueten', [z]);
    wahr('Ein fehlendes Pflichtfeld ist ein Fehler',
         st({ name: 'X', fy: 235 }).fehler.length === 1);
    wahr('Eine Zahl, die keine ist, ist ein Fehler',
         st({ name: 'X', fy: 'viel', fu: 360 }).fehler.length === 1);
    /*
     * EIN WERT AUSSERHALB DES BEREICHS WIRD GEMELDET, NICHT ABGELEHNT - sonst
     * verböte der Katalog genau das, wofür die Datenbank da ist: einen
     * neuen Typ.
     */
    const r = st({ name: 'X', fy: 900, fu: 360 });
    wahr('Ein Wert ausserhalb des Bereichs ist nur eine Warnung',
         r.fehler.length === 0 && r.warnung.length === 1, r.warnung.join(' '));
    wahr('Eine unerlaubte Auswahl ist ein Fehler',
         K.pruefeTabelle('normen', 'winkelprofile', [{ name: 'L', form: 'rund' }])
           .fehler.some((x) => x.includes('«Form»')));
    wahr('Eine Spalte ohne Katalogeintrag wird gemeldet',
         st({ name: 'X', fy: 235, fu: 360, zaehigkeit: 27 }).warnung
           .some((x) => /zaehigkeit/.test(x)));
    wahr('Ein Wahrheitswert, der keiner ist, ist ein Fehler',
         K.pruefeTabelle('tragjoche', 'typen', [{ ...tab.tragjoche.tabellen.typen[1],
           sortiment: 'ja' }]).fehler.some((x) => /ja noch nein/.test(x)));
    // Ein Blech, dessen Typ es nicht gibt
    const waise = JSON.parse(JSON.stringify(tab.tragjoche));
    waise.tabellen.bleche.push({ typ: 'J999', ebene: 'vertikal', nr: 1, pos: 1,
                                 breite: 100, dicke: 8, laenge: 300 });
    wahr('Ein Blech ohne seinen Typ ist ein Fehler',
         K.pruefeTabellen('tragjoche', waise).fehler.some((x) => /J999/.test(x)));
    // Die Abkürzung für einen einzelnen Satz in Baumform
    const a = K.abschnitt('stahlgueten');
    wahr('Ein Satz in Baumform laesst sich pruefen',
         K.pruefeSatz(a, { name: 'X', fy: 235 }).fehler.length === 1);
  }

  // --- Die Spalten des Fensters ---------------------------------------------
  {
    /*
     * >>> EIN SATZ MIT BEKANNTEN FELDERN WIRD AUFGEFALTET. <<<
     *
     * Die Windlast des Masten steht als quer/längs mal EK1..EK3 - sechs
     * Spalten, in jeder eine Zahl.
     */
    const sp = K.spaltenVon('masten', 'typen', tab.masten.tabellen.typen);
    pruef('Masttypen: Profil und sechs Windwerte', sp.length, 7, 1e-12, 'Spalten');
    wahr('Die Anschrift nennt den Weg dorthin',
         sp[1].kopf === 'Windlast · quer zum Gleis · EK1', sp[1].kopf);
    wahr('Der Pfad ist der der Datei', sp[1].pfad === 'wind/quer/EK1', sp[1].pfad);
    wahr('Und die Einheit steht daneben', sp[1].feld.einheit === 'kN/m');

    const bl = K.spaltenVon('tragjoche', 'bleche', tab.tragjoche.tabellen.bleche);
    wahr('Die Bleche fuehren zuerst ihre Schluessel: Typ, Ebene, Nr.',
         bl.slice(0, 3).map((s) => s.pfad).join(',') === 'typ,ebene,nr',
         bl.slice(0, 3).map((s) => s.pfad).join(','));
    wahr('Die Blechdicke steht in mm',
         bl.find((s) => s.pfad === 'dicke')?.feld.einheit === 'mm');
    // Seit J60 seine Bleche hat (18. September), fuehrt kein Typ mehr einen
    // leeren Behaelter - geprueft wird der Mechanismus an einer eigenen Zeile.
    wahr('Ein leerer Behaelter hat seine Spalte',
         K.spaltenVon('tragjoche', 'typen', [{ typ: 'X', bleche: null }])
           .some((s) => s.pfad === 'bleche'));

    wahr('Eine Blechliste wird gezaehlt, nicht ausgeschrieben',
         K.alsText([{ pos: 1 }, { pos: 2 }], { typ: 'frei' }) === '2 Einträge');
    wahr('Ein Zahlenpaar wird ausgeschrieben',
         K.alsText([8, 16], { typ: 'liste' }) === '8 · 16');
    wahr('Eine Luecke in einer Liste bleibt sichtbar',
         K.alsText([null, 12.5], { typ: 'liste' }) === '– · 12.5');
  }

  // --- Die Excel-Blaetter -----------------------------------------------------
  {
    const bl = D.blaetter(tab, X.STIL);
    const anzahl = TBF.SORTIMENTE.reduce((s, db) => s + K.tabellenKatalog(db).length, 0);
    pruef('Uebersicht und ein Blatt je Tabelle', bl.length, anzahl + 1, 1e-12, 'Blaetter');
    wahr('Das erste Blatt ist die Uebersicht', bl[0].name === 'Übersicht');
    wahr('Kein Blattname ist laenger als einunddreissig Zeichen',
         bl.every((b) => b.name.length <= 31));
    wahr('Kein Blattname traegt ein Zeichen, das Excel verbietet',
         bl.every((b) => !/[:\\/?*[\]]/.test(b.name)),
         bl.filter((b) => /[:\\/?*[\]]/.test(b.name)).map((b) => b.name).join(', '));
    wahr('Die Blattnamen sind eindeutig', new Set(bl.map((b) => b.name)).size === bl.length);
    /*
     * DIE FUENFTE ZEILE TRAEGT DIE PFADE - das Einlesen findet an ihnen die
     * Spalten, auch wenn jemand sie umstellt.
     */
    const blech = bl.find((b) => b.name === 'Trag · Bindebleche');
    wahr('Das Blechblatt steht in der Mappe', Boolean(blech));
    wahr('Zeile fuenf traegt die Spaltenpfade',
         blech?.rows[D.PFADZEILE - 1].map((c) => c.v).slice(0, 3).join(',') === 'typ,ebene,nr');
    const mappe = X.arbeitsmappe(bl);
    wahr('Die Mappe entsteht', mappe instanceof Uint8Array && mappe.length > 50000,
         `${mappe?.length} Bytes`);
    const mitPruefung = D.blaetter(tab, X.STIL, { blech: [{ typ: 'J1', fehler: ['x'],
                                                               warnung: [], hinweis: [] }] });
    wahr('Auf Wunsch kommt das Pruefblatt ans Ende',
         mitPruefung[mitPruefung.length - 1].name === 'Prüfung');
  }

  // --- Die Trennung von Norm und Sortiment ----------------------------------
  {
    const norm = K.abschnitteVon('norm').map((a) => a.key);
    const sort = K.abschnitteVon('sortiment').map((a) => a.key);
    wahr('Norm: Stahlgueten und die drei Profiltabellen',
         norm.join(',') === 'stahlgueten,winkelprofile,walzprofile,mastprofile',
         norm.join(','));
    wahr('Sortiment: sieben Abschnitte in sechs Dateien',
         sort.length === 7 && new Set(K.abschnitteVon('sortiment').map((a) => a.db)).size === 6,
         sort.join(','));
    wahr('Alle Normabschnitte stehen in der Normdatei',
         K.abschnitteVon('norm').every((a) => a.db === 'normen'));
    wahr('Kein Sortimentsabschnitt steht in der Normdatei',
         K.abschnitteVon('sortiment').every((a) => a.db !== 'normen'));
  }
}

titel('62  Die Tabellenform der Datendateien');
/* ===========================================================================
 * >>> VERLUSTFREI ODER GAR NICHT. <<<
 * ===========================================================================
 *
 * Weisung vom 16. September: die JSON-Dateien selbst werden in Tabellen
 * umgebaut. Der Rechenkern sieht weiterhin den Baum - also muss der Weg
 * Tabelle -> Baum -> Tabelle jede Zahl, jede Luecke und jede Reihenfolge
 * der Bleche tragen. Ein Verlust hier waere ein Verlust im Nachweis, und er
 * fiele nirgends sonst auf.
 * ========================================================================= */
{
  const kanon = (v) => (Array.isArray(v) ? v.map(kanon)
    : (v && typeof v === 'object')
      ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, kanon(v[k])]))
      : v);
  const gleich = (a, b) => JSON.stringify(kanon(a)) === JSON.stringify(kanon(b));

  // --- Die wirklichen Dateien ---------------------------------------------
  for (const s of TBF.SORTIMENTE) {
    const roh = JSON.parse(readFileSync(join(HIER, 'data', s + '.json'), 'utf8'));
    wahr(`${s}: die Datei steht in Tabellenform`,
         TBF.istTabellenform(roh) && roh.sortiment === s);
    const baum = TBF.setzeZusammen(roh);
    const wieder = TBF.zerlege(s, baum);
    wahr(`${s}: Tabelle -> Baum -> Tabelle ist verlustfrei`,
         gleich(wieder.tabellen, roh.tabellen) && gleich(wieder.angaben, roh.angaben));
    wahr(`${s}: der Dateitext liest sich zurueck`,
         gleich(JSON.parse(TBF.alsDateitext(wieder)), roh));
  }
  {
    const tj = JSON.parse(readFileSync(join(HIER, 'data', 'tragjoche.json'), 'utf8'));
    /*
     * ZWEI LISTEN GLEICHER FORM WERDEN EINE TABELLE. Die vertikalen und die
     * horizontalen Bleche standen getrennt; jetzt ist es eine Blechliste mit
     * der Spalte `ebene`.
     */
    const ebenen = new Set(tj.tabellen.bleche.map((z) => z.ebene));
    wahr('Eine Blechtabelle traegt beide Ebenen',
         ebenen.has('vertikal') && ebenen.has('horizontal'), [...ebenen].join(','));
    wahr('Jedes Blech nennt seinen Typ',
         tj.tabellen.bleche.every((z) => typeof z.typ === 'string'));
    wahr('Die Staffelung je Ausfuehrung verweist auf ihre Ausfuehrung',
         tj.tabellen.ausfuehrung_staffelung.every((z) =>
           Number.isFinite(z.ausfuehrung) && z.typ && z.ebene));
    pruef('Die Masstabelle hat eine Zeile je Laenge',
          tj.tabellen.masstabelle.length, 54, 1e-12, 'Zeilen');
    wahr('Die Laenge bleibt Text - sie ist ein Schluessel',
         tj.tabellen.masstabelle.every((z) => typeof z.L === 'string'));
  }

  // --- Die Sonderfaelle, an einem erfundenen Baum ---------------------------
  {
    const baum = {
      _hinweis: 'frei',
      _leer: {},
      typen: [
        { typ: 'A', og: { ja: 60, jf: 6 },
          bleche: { vertikal: [{ pos: 1 }, { pos: 2 }], horizontal: [] },
          staffelung: {}, liste: [1, null, 3],
          ausfuehrungen: [{ bez: 'I',
                            staffelung: { vertikal: [{ pos: 1, anzahl: null }] } }] },
        { typ: 'B', bleche: null, ausfuehrungen: [] },
      ],
      masstabelle: { _kommentar: 'x', zeilen: { '8.00': [750, 750], '8.50': [] } },
    };
    const tab = TBF.zerlege('tragjoche', baum);
    const zurueck = TBF.setzeZusammen(tab);
    wahr('Sonderfaelle: zurueck derselbe Baum', gleich(zurueck, baum),
         JSON.stringify(zurueck).slice(0, 200));
    wahr('Eine leere Liste bleibt eine leere Liste',
         Array.isArray(zurueck.typen[0].bleche.horizontal)
         && zurueck.typen[0].bleche.horizontal.length === 0);
    wahr('null bleibt null, nicht «fehlt»', zurueck.typen[1].bleche === null);
    wahr('Ein leerer Satz bleibt ein leerer Satz',
         gleich(zurueck.typen[0].staffelung, {}));

    /*
     * WER IN EXCEL SORTIERT, VERSCHIEBT KEINE BLECHE. Die Reihenfolge kommt
     * aus `nr`, nicht aus der Lage der Zeile.
     */
    const umgestellt = JSON.parse(JSON.stringify(tab));
    umgestellt.tabellen.bleche.reverse();
    wahr('Umgestellte Zeilen ergeben dieselbe Reihenfolge',
         TBF.setzeZusammen(umgestellt).typen[0].bleche.vertikal[0].pos === 1);

    let fehler = null;
    try { TBF.zerlege('masten', { typen: [{ profil: 'X', 'a/b': 1 }] }); }
    catch (e) { fehler = e.message; }
    wahr('Ein Schluessel mit «/» wird abgewiesen', /Pfadzeichen/.test(fehler ?? ''),
         fehler);

    const doppelt = JSON.parse(JSON.stringify(tab));
    doppelt.tabellen.typen.push({ ...doppelt.tabellen.typen[0] });
    fehler = null;
    try { TBF.setzeZusammen(doppelt); } catch (e) { fehler = e.message; }
    wahr('Ein doppelter Typ mit Untertabellen wird abgewiesen',
         /zweimal/.test(fehler ?? ''), fehler);

    const waise = JSON.parse(JSON.stringify(tab));
    waise.tabellen.bleche.push({ typ: 'Z', ebene: 'vertikal', nr: 1, pos: 9 });
    fehler = null;
    try { TBF.setzeZusammen(waise); } catch (e) { fehler = e.message; }
    wahr('Ein Blech ohne seinen Typ wird abgewiesen', /keine Zeile/.test(fehler ?? ''),
         fehler);

    fehler = null;
    try { TBF.ausTabellen(tab, 'masten'); } catch (e) { fehler = e.message; }
    wahr('Eine Datei des falschen Sortiments wird abgewiesen',
         /erwartet/.test(fehler ?? ''), fehler);
    wahr('Ein Baum geht unveraendert durch', TBF.ausTabellen(baum) === baum);
  }

  // --- Excel-Zellen -----------------------------------------------------------
  {
    const faelle = [0.37, 0, true, false, 'HEB 240', '[kein Satz]', "'zitiert",
                    [4.51, 5], [], {}, [null, 12.5], { a: 1 }];
    for (const v of faelle) {
      wahr(`Zelle hin und zurueck: ${JSON.stringify(v)}`,
           JSON.stringify(TBF.zelleEin(TBF.zelleAus(v))) === JSON.stringify(v),
           JSON.stringify(TBF.zelleAus(v)));
    }
    wahr('null wird eine leere Zelle', TBF.zelleAus(null) === null);
    wahr('Eine leere Zelle heisst «fehlt»',
         TBF.zelleEin('') === undefined && TBF.zelleEin(null) === undefined);
  }
}

titel('63  Die Farbe ohne Urteil bleibt in der Uebersicht');
/*
 * `ampelU` ist innerhalb von `zeichneUebersicht` definiert - sie schweigt,
 * wenn ein Einzellastfall gezeigt wird. Am 16. September stand sie nach
 * einem Suchen-und-Ersetzen auch in `zeichneSchnitt`, wo es sie nicht gibt:
 * der Reiter «Schnitt» brach beim Zeichnen ab, und kein Pruefstandlauf
 * merkte es, weil hier nichts gezeichnet wird. Diese Kontrolle liest den
 * Quelltext statt ihn auszufuehren.
 */
{
  const src = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
  const von = src.indexOf('export function zeichneUebersicht(');
  const bis = src.indexOf('\nexport function ', von + 10);
  const stellen = [...src.matchAll(/\bampelU\(/g)].map((m) => m.index);
  wahr('ampelU wird verwendet', stellen.length > 0);
  /*
   * Seit dem 18. September teilen sich Tragjoch und Einzelmast die Kacheln
   * (`bauteilKacheln` bekommt ampelU als Parameter, `zeichneEinzelmast`
   * definiert sein eigenes). Geprueft wird deshalb der eigentliche Fehler:
   * jede Funktion, die ampelU ruft, hat es selbst - als Konstante oder als
   * Parameter.
   */
  const ohne = stellen.filter((i) => {
    const kopf = Math.max(src.lastIndexOf('\nfunction ', i),
                          src.lastIndexOf('\nexport function ', i));
    const stueck = src.slice(kopf, i);
    const parameter = stueck.slice(0, stueck.indexOf('{'));
    return !/\bampelU\b/.test(parameter) && !/const ampelU\b/.test(stueck);
  });
  wahr('ampelU wird nur gerufen, wo es definiert ist', ohne.length === 0,
       ohne.map((i) => `Zeile ${src.slice(0, i).split('\n').length}`).join(', '));
  wahr('… und die Uebersicht des Jochs definiert es',
       /const ampelU\b/.test(src.slice(von, bis)));
}

titel('64  Die Regel der Blecheinteilung');
/* ===========================================================================
 * >>> SICHTBAR GEMACHT, NICHT HERGELEITET. <<<
 * ===========================================================================
 *
 * Weisung vom 16. September, auf Rückfrage entschieden: die Regel der
 * Blecheinteilung wird sichtbar gemacht und geprüft, sie erzeugt keine
 * Geometrie. Die erste Kontrolle ist deshalb die wichtigste: was die Regel
 * zeigt, ist GENAU die Stationsliste, mit der der Rechenkern rechnet.
 * ========================================================================= */
{
  const BR = await import(J('core.blechregel.js'));
  const j80 = T.getTragjoch('J80');

  // Dieselben Stationen und Bleche wie im Modell
  {
    const e = BR.einteilung(j80, 12);
    const w = { ...basis(), ...typUebernehmen({ ...standardwerte(), bearbeiten: false }, j80),
                typ: 'J80', L: 12 };
    const sl = rechne(w).modell.stationsListe;
    pruef('Gleich viele Stationen wie im Modell', e.anzahl, sl.length, 1e-12, 'Stk');
    wahr('An denselben Stellen',
         e.stationen.every((s, i) => Math.abs(s.x - sl[i].x) < 1e-6),
         e.stationen.slice(0, 4).map((s, i) => `${s.x}/${sl[i].x}`).join(' '));
    wahr('Mit denselben Blechen',
         e.stationen.every((s, i) => (s.vertikal?.pos ?? null) === (sl[i].vertikal?.pos ?? null)
           && (s.horizontal?.pos ?? null) === (sl[i].horizontal?.pos ?? null)));
    wahr('Die Feldweiten stammen aus der Masstabelle', e.quelle === 'masstabelle');
    wahr('Am Jochende liegt kein horizontales Blech (Gabel)',
         e.stationen[0].horizontal === null && e.stationen.at(-1).horizontal === null);
    const sv = Object.values(e.stueck.vertikal).reduce((a, b) => a + b, 0);
    const sh = Object.values(e.stueck.horizontal).reduce((a, b) => a + b, 0);
    pruef('Vertikal zwei Bleche mehr als horizontal - die beiden Jochenden',
          sv - sh, 2, 1e-12, 'Stk');
  }

  // Die Prüfung am wirklichen Sortiment
  {
    const alle = BR.pruefeAlle();
    const f = alle.reduce((s, p) => s + p.fehler.length, 0);
    pruef('Keine Widersprueche in den Blechdaten', f, 0, 1e-12, 'Stk');
    const ms = alle.find((p) => p.art === 'masstabelle');
    wahr('Die Masstabelle wird einmal geprueft, nicht je Typ', Boolean(ms)
         && alle.filter((p) => p.art === 'masstabelle').length === 1);
    /*
     * DREI ZEILEN GEHEN NICHT AUF - 26.50, 29.00, 29.50 m. Die Datei vermerkt
     * sie selbst als unschlüssig; die Regel rechnet es nach.
     */
    wahr('Die drei unschluessigen Zeilen werden genannt',
         /26\.50[\s\S]*29\.00[\s\S]*29\.50/.test(ms.warnung.join(' ')), ms.warnung.join(' '));
    const j120 = alle.find((p) => p.typ === 'J120');
    /*
     * J120, VERTIKAL: die festen Stufen reichen bis 25.50 m über die
     * Feldmitte, der Normbereich beginnt bei 23 m. Dort sollte das
     * Feldblech vorkommen - deshalb eine Warnung, keine blosse Auskunft.
     */
    wahr('J120: die Staffelung ueber die Mitte im Normbereich ist eine Warnung',
         j120.warnung.some((w) => /vertikal/.test(w) && /Normbereich/.test(w)),
         j120.warnung.join(' | '));
    const j100 = alle.find((p) => p.typ === 'J100');
    wahr('J100: ausserhalb des Normbereichs nur ein Hinweis',
         j100.warnung.length === 0 && j100.hinweis.some((h) => /Feldmitte/.test(h)));
    /*
     * J60 HAT SEINE BLECHE (18. September, aus der Konstruktionszeichnung,
     * Index c). Bis dahin stand hier «ohne Bleche wird genannt»; jetzt muss
     * er aufgehen wie J80 - jede Laenge gegen die Stueckliste.
     */
    {
      const j60 = alle.find((p) => p.typ === 'J60');
      wahr('J60: keine Warnung und kein Hinweis mehr',
           j60.warnung.length === 0 && j60.hinweis.length === 0,
           [...j60.warnung, ...j60.hinweis].join(' | '));
      wahr('J60: alle 17 Laengen stimmen mit der Stueckliste',
           j60.laengen.length === 17 && j60.laengen.every((l) => l.stimmt !== false),
           `${j60.laengen.length} Laengen`);
    }
    const aj = alle.filter((p) => p.art === 'abfangjoch' && p.laengen.length);
    wahr('Abfangjoche: Schema und Stueckliste stimmen ueberein',
         aj.length > 0 && aj.every((p) => p.laengen.every((l) => l.stimmt !== false)));
  }

  // Die Prüfung erkennt, was sie erkennen soll
  {
    const kaputt = JSON.parse(JSON.stringify(j80));
    kaputt.staffelung.vertikal[0].pos = 99;
    wahr('Ein Blech der Staffelung, das es nicht gibt, ist ein Fehler',
         BR.pruefeTragjoch(kaputt).fehler.some((x) => /Pos\. 99/.test(x)));
    const offen = JSON.parse(JSON.stringify(j80));
    offen.staffelung.horizontal[1].anzahl = null;
    wahr('Eine offene Stufe vor dem Schluss ist ein Fehler',
         BR.pruefeTragjoch(offen).fehler.some((x) => /offene Stufe/.test(x)));
    const doppelt = JSON.parse(JSON.stringify(j80));
    doppelt.bleche.vertikal.push({ ...doppelt.bleche.vertikal[0] });
    wahr('Eine Blech-Pos. zweimal ist ein Fehler',
         BR.pruefeTragjoch(doppelt).fehler.some((x) => /zweimal/.test(x)));
    const luecke = JSON.parse(JSON.stringify(T.getTragjoch('J80-alt')));
    luecke.ausfuehrungen.splice(1, 1);
    wahr('Eine Luecke zwischen den Ausfuehrungen wird genannt',
         BR.pruefeTragjoch(luecke).warnung.some((x) => /fehlt der Bereich/.test(x)),
         BR.pruefeTragjoch(luecke).warnung.join(' | '));
  }

  // Das Abfangjoch
  {
    const e = BR.einteilungAbfang('A240', AJ.abfangLaengen('A240')[3]);
    wahr('A240: eine Einteilung entsteht', Boolean(e) && e.anzahl > 5);
    wahr('… mit Endblechen und Quersteifen, wo das Schema sie fuehrt',
         e.stationen[0].art === 'endeL' && e.quersteifen >= 0);
  }
}

titel('65  Bauteildaten einlesen: Abgleich mit Vorschau');
/* ===========================================================================
 * >>> EINE UNVERAENDERTE MAPPE MELDET NICHTS. <<<
 * ===========================================================================
 *
 * Weisung vom 16. September: «den import auch umsetzen», auf Rückfrage
 * entschieden: Abgleich mit Vorschau. Die Grundprobe ist der Leerlauf:
 * ausleiten, einlesen, abgleichen - und keine einzige Änderung. Jede
 * Meldung dort wäre ein Fehler der Hin- oder Rückrichtung und würde
 * wirkliche Änderungen in der Vorschau verdecken.
 * ========================================================================= */
{
  const E = await import(J('data.einlesen.js'));
  const D = await import(J('ui.daten.js'));
  const X = await import(J('export.xlsx.js'));
  const roh = (n) => JSON.parse(readFileSync(join(HIER, 'data', n + '.json'), 'utf8'));
  const tab = {};
  for (const s of TBF.SORTIMENTE) tab[s] = roh(s);
  const kopie = (o) => JSON.parse(JSON.stringify(o));

  const vergleiche = async (bytes, name = 'mappe.xlsx', basisTab = tab) => {
    const g = await E.leseDatei(name, bytes);
    const r = Object.entries(g.teile).map(([db, neu]) =>
      E.abgleich(db, basisTab[db], neu, { ausExcel: g.quelle === 'excel' }));
    return { g, r, n: r.reduce((s, x) => s + x.aenderungen, 0) };
  };

  /*
   * EINE MAPPE, WIE EXCEL SIE SPEICHERT: verdichtet. Der eigene Schreiber
   * legt unverdichtet ab; hier wird dieselbe Mappe mit Deflate neu gepackt,
   * damit der Leser den Weg geht, den eine gespeicherte Datei nimmt.
   */
  const verdichtet = async (bytes) => {
    const crcT = new Uint32Array(256).map((_, i) => {
      let c = i;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      return c >>> 0;
    });
    const crc = (b) => {
      let c = 0xffffffff;
      for (const x of b) c = crcT[(c ^ x) & 0xff] ^ (c >>> 8);
      return (c ^ 0xffffffff) >>> 0;
    };
    const teile = [];
    const zentral = [];
    let ofs = 0;
    for (const e of await X.entpackeAlle(bytes)) {
      const strom = new Blob([e.inhalt]).stream()
        .pipeThrough(new CompressionStream('deflate-raw'));
      const dicht = new Uint8Array(await new Response(strom).arrayBuffer());
      const name = new TextEncoder().encode(e.name);
      const k = new DataView(new ArrayBuffer(30));
      k.setUint32(0, 0x04034b50, true); k.setUint16(4, 20, true);
      k.setUint16(8, 8, true); k.setUint32(14, crc(e.inhalt), true);
      k.setUint32(18, dicht.length, true); k.setUint32(22, e.inhalt.length, true);
      k.setUint16(26, name.length, true);
      const z = new DataView(new ArrayBuffer(46));
      z.setUint32(0, 0x02014b50, true); z.setUint16(4, 20, true); z.setUint16(6, 20, true);
      z.setUint16(10, 8, true); z.setUint32(16, crc(e.inhalt), true);
      z.setUint32(20, dicht.length, true); z.setUint32(24, e.inhalt.length, true);
      z.setUint16(28, name.length, true); z.setUint32(42, ofs, true);
      teile.push(new Uint8Array(k.buffer), name, dicht);
      zentral.push(new Uint8Array(z.buffer), name);
      ofs += 30 + name.length + dicht.length;
    }
    const zl = zentral.reduce((s, b) => s + b.length, 0);
    const ende = new DataView(new ArrayBuffer(22));
    ende.setUint32(0, 0x06054b50, true);
    ende.setUint16(8, zentral.length / 2, true); ende.setUint16(10, zentral.length / 2, true);
    ende.setUint32(12, zl, true); ende.setUint32(16, ofs, true);
    const alle = [...teile, ...zentral, new Uint8Array(ende.buffer)];
    const aus = new Uint8Array(alle.reduce((s, b) => s + b.length, 0));
    let p = 0;
    for (const b of alle) { aus.set(b, p); p += b.length; }
    return aus;
  };

  const mappe = X.arbeitsmappe(D.blaetter(tab, X.STIL));

  // --- Der Leerlauf ----------------------------------------------------------
  {
    const a = await vergleiche(mappe);
    pruef('Eigene Mappe: alle sieben Sortimente gelesen',
          Object.keys(a.g.teile).length, 7, 1e-12, 'Stk');
    pruef('Eigene Mappe: keine Aenderung', a.n, 0, 1e-12, 'Stk');
    const dicht = await verdichtet(mappe);
    wahr('Die verdichtete Mappe ist wirklich verdichtet',
         dicht.length < mappe.length / 3, `${dicht.length} gegen ${mappe.length} Bytes`);
    const b = await vergleiche(dicht);
    pruef('Verdichtete Mappe: keine Aenderung', b.n, 0, 1e-12, 'Stk');
    for (const s of ['tragjoche', 'anbauteile']) {
      const c = await vergleiche(new TextEncoder().encode(JSON.stringify(tab[s])), s + '.json');
      pruef(`JSON in Tabellenform (${s}): keine Aenderung`, c.n, 0, 1e-12, 'Stk');
      const d = await vergleiche(new TextEncoder().encode(
        JSON.stringify(TBF.setzeZusammen(tab[s]))), s + '.json');
      pruef(`JSON in Baumform (${s}): keine Aenderung`, d.n, 0, 1e-12, 'Stk');
    }
    const paket = { format: 'tragjoch-daten', version: 2,
                    tragjoche: tab.tragjoche, masten: TBF.setzeZusammen(tab.masten) };
    const e = await vergleiche(new TextEncoder().encode(JSON.stringify(paket)), 'paket.json');
    wahr('Ein Datenpaket liefert seine Teile, gleich welcher Form',
         Object.keys(e.g.teile).sort().join(',') === 'masten,tragjoche' && e.n === 0);
  }

  // --- Eine bearbeitete Mappe ---------------------------------------------------
  {
    const t2 = kopie(tab);
    const bl = t2.tragjoche.tabellen.bleche.find((z) => z.typ === 'J80'
      && z.ebene === 'vertikal' && z.nr === 1);
    bl.dicke += 2;
    t2.normen.tabellen.stahlgueten.push({ name: 'S460', fy: 460, fu: 540 });
    t2.anbauteile.tabellen.module.shift();
    // Ein Wert wird geleert, und ein leerer bleibt leer
    const bt = t2.fl_bauteile.tabellen.bauteile.find((z) => z.id === 'anbauteil-ausleger-typ-rohr');
    delete bt.eigengewicht;
    const a = await vergleiche(X.arbeitsmappe(D.blaetter(t2, X.STIL)));
    const nach = (db) => a.r.find((x) => x.db === db);
    pruef('Vier Eingriffe, vier Aenderungen', a.n, 4, 1e-12, 'Stk');
    const tj = nach('tragjoche');
    const g = tj.tabellen.find((t) => t.name === 'bleche').geaendert[0];
    wahr('Die Blechdicke wird Feld fuer Feld gezeigt',
         g?.felder.length === 1 && g.felder[0].pfad === 'dicke'
         && g.felder[0].neu === g.felder[0].alt + 2, JSON.stringify(g?.felder));
    wahr('J80 ist geprueft - die Aenderung wird eigens genannt',
         tj.geprueft.includes('J80'), tj.geprueft.join(','));
    wahr('Die neue Stahlguete ist neu',
         nach('normen').tabellen.find((t) => t.name === 'stahlgueten').neu.length === 1);
    wahr('Das geloeschte Modul ist entfernt',
         nach('anbauteile').tabellen.find((t) => t.name === 'module').entfernt.length === 1);
    const fl = nach('fl_bauteile').tabellen.find((t) => t.name === 'bauteile').geaendert[0];
    wahr('Eine geleerte Zelle wird null', fl?.felder[0].pfad === 'eigengewicht'
         && fl.felder[0].neu === null, JSON.stringify(fl?.felder));
    wahr('… und die Pruefung faellt: das Eigengewicht ist Pflicht',
         !nach('fl_bauteile').pruefung.ok
         && nach('fl_bauteile').pruefung.fehler.some((x) => /Eigengewicht/.test(x)));
    wahr('Das Ergebnis traegt die neue Dicke',
         tj.ergebnis.tabellen.bleche.some((z) => z.typ === 'J80' && z.ebene === 'vertikal'
           && z.nr === 1 && z.dicke === bl.dicke));
    wahr('Und laesst sich zusammensetzen',
         TBF.setzeZusammen(tj.ergebnis).typen.find((x) => x.typ === 'J80')
           .bleche.vertikal[0].dicke === bl.dicke);
    wahr('Unveraenderte Sortimente bleiben ohne Aenderung',
         nach('anker').aenderungen === 0 && nach('masten').aenderungen === 0);
  }

  // --- Teile, die fehlen ---------------------------------------------------------
  {
    const bl = D.blaetter(tab, X.STIL).filter((b) => b.name !== 'Trag · Bindebleche');
    const a = await vergleiche(X.arbeitsmappe(bl));
    const t = a.r.find((x) => x.db === 'tragjoche').tabellen.find((x) => x.name === 'bleche');
    wahr('Ein fehlendes Blatt laesst seine Tabelle stehen', t.uebernommen
         && a.r.find((x) => x.db === 'tragjoche').ergebnis.tabellen.bleche.length
            === tab.tragjoche.tabellen.bleche.length);
    wahr('… und die Datei sagt es', a.g.hinweise.some((h) => /Bindebleche/.test(h)));
    pruef('… ohne Aenderung', a.n, 0, 1e-12, 'Stk');
  }

  // --- Was abgewiesen werden muss --------------------------------------------------
  {
    const wirft = async (bytes, name, muster) => {
      try { await E.leseDatei(name, bytes); return false; }
      catch (e) { return muster.test(e.message); }
    };
    const fremd = X.arbeitsmappe([{ name: 'Tabelle1', rows: [['a', 'b'], [1, 2]] }]);
    wahr('Eine fremde Mappe wird abgewiesen',
         await wirft(fremd, 'fremd.xlsx', /Übersicht/));
    wahr('Unlesbares wird abgewiesen',
         await wirft(new TextEncoder().encode('kein json'), 'x.json', /weder/));
    wahr('Ein JSON ohne Sortiment wird abgewiesen',
         await wirft(new TextEncoder().encode('{"a":1}'), 'x.json', /keinem Sortiment/));
  }

  // --- Der hinterlegte Stand ---------------------------------------------------------
  {
    E.eingelesenVerwerfen();
    wahr('Ohne Einlesen ist nichts hinterlegt', E.eingelesen() === null);
    const t2 = kopie(tab.masten);
    t2.tabellen.typen[0]['wind/quer/EK2'] = 0.99;
    E.eingelesenSpeichern({ masten: t2 }, 'probe.xlsx');
    wahr('Der Stand ist hinterlegt, mit Quelle und Zeit',
         E.eingelesen()?.quelle === 'probe.xlsx' && Boolean(E.eingelesen()?.stand));
    const gesetzt = {};
    const r = E.eingelesenAnwenden({ masten: (b) => { gesetzt.masten = b; } });
    wahr('Beim Start wird er angewendet', r.angewendet.join() === 'masten'
         && gesetzt.masten.typen[0].wind.quer.EK2 === 0.99);
    const kaputt = kopie(tab.masten);
    delete kaputt.tabellen.typen[0].profil;
    E.eingelesenSpeichern({ masten: kaputt }, 'kaputt.xlsx');
    const r2 = E.eingelesenAnwenden({ masten: () => { throw new Error('darf nicht'); } });
    wahr('Ein fehlerhafter Stand wird nicht angewendet, sondern gemeldet',
         r2.angewendet.length === 0 && r2.fehler.length === 1, r2.fehler.join(' '));
    E.eingelesenVerwerfen();
    wahr('Verworfen ist er weg', E.eingelesen() === null);
    wahr('Als Datei geschrieben ist er wieder Tabellenform',
         TBF.istTabellenform(JSON.parse(E.alsDatei(t2))));
  }

  // --- Die Vorschau ------------------------------------------------------------------
  {
    const t2 = kopie(tab);
    t2.tragjoche.tabellen.bleche[0].dicke += 1;
    const a = await vergleiche(X.arbeitsmappe(D.blaetter(t2, X.STIL)));
    const html = D.zeichneAbgleich(a.r, { datei: 'probe.xlsx', quelle: 'excel' });
    wahr('Die Vorschau nennt die Aenderung', /1<\/b> Änderung/.test(html));
    wahr('Sie nennt den geprueften Satz', /Geprüfte Sätze ändern sich/.test(html));
    /*
     * GESPERRT WIRD NUR, WAS SICH AENDERT - und seit der Berichtigung der
     * doppelten Kennung (20. September) gibt es gar keinen bestehenden
     * Befund mehr. Die Vorschau darf deshalb weder sperren noch einen
     * melden.
     */
    wahr('Die Vorschau sperrt nichts',
         !/so lässt sich der Stand nicht übernehmen/.test(html)
         && !/bestehende/.test(html),
         /bestehende/.test(html) ? 'es steht doch ein Befund da' : 'frei');
  }
}

titel('66  Der Seilanker traegt nur Zug');
/* ===========================================================================
 * >>> MUESSTE DAS SEIL DRUECKEN, FAELLT ES AUS. <<<
 * ===========================================================================
 *
 * Befund vom 16. September: «der zugstab wirkt nicht nur auf zug.» Auf
 * Rückfrage: gemeint ist der Seilanker; in einer Kombination, in der er
 * drücken müsste, fällt er aus, der Mast trägt allein, und der
 * Ankernachweis sagt es als Hinweis ohne eta.
 *
 * Geprüft wird an demselben Lastbild wie in Abschnitt 44: einmal liegt das
 * Seil auf der Zugseite, einmal auf der Druckseite.
 * ========================================================================= */
{
  const MK = await import(J('core.mast.js'));
  const CC6 = await import(J('core.constants.js'));
  const AU6 = await import(J('core.auflager.js'));
  const mitAnker = (anker) => {
    const w = {
      typ: 'J90', L: 20, xLage: 0, twId: 'T1',
      mastVorhanden: true, endbedingung: 'mast',
      mastProfil: 'HEB 240', mastH: 7.5, mastSteg: 'quer',
      masten: [
        { id: 'M1', x: 0, profil: 'HEB 240' },
        { id: 'M2', x: 20, profil: 'HEB 240', ...(anker ? { anker } : {}) },
      ],
    };
    const f = AU6.drehfedern(CC6.rechensatz(w));
    return {
      L: 20, federn: f, RA: 20, RB: 20, MA: 5, MB: 5,
      wd: 0, H: [], T: [], N: [{ x: 10, w: 20 }],
      beiwerte: { G: 1 }, stahl: { fy: 235 }, gammaM0: 1,
      mastLast: { A: { xd: 0, yd: 0 }, B: { xd: 0, yd: 0 } },
      anbauMastFlach: [],
    };
  };
  const anker = (typ, seite) => ({ typ, h: 4, a: 3, seite, befestigung: 'ankerplatte' });
  const ohne = MK.mastSchnitt(mitAnker(null), 'B');

  // Welche Seite drückt? Die Stütze trägt beides und sagt es am Vorzeichen.
  const uPlus = MK.mastSchnitt(mitAnker(anker('U12', 'plus')), 'B').ankerkraft;
  const uMinus = MK.mastSchnitt(mitAnker(anker('U12', 'minus')), 'B').ankerkraft;
  wahr('Die Stuetze traegt auf beiden Seiten - einmal Zug, einmal Druck',
       Math.sign(uPlus.N) === -Math.sign(uMinus.N) && uPlus.N !== 0,
       `plus ${uPlus.N.toFixed(2)}, minus ${uMinus.N.toFixed(2)} kN`);
  const zugSeite = uPlus.N > 0 ? 'plus' : 'minus';
  const druckSeite = zugSeite === 'plus' ? 'minus' : 'plus';

  // Das Seil auf der Zugseite: es trägt wie die Stütze
  const sZ = MK.mastSchnitt(mitAnker(anker('SA20', zugSeite)), 'B');
  wahr('Das Seil auf der Zugseite traegt', sZ.ankerkraft.N > 0 && !sZ.ankerkraft.schlaff,
       `${sZ.ankerkraft.N.toFixed(2)} kN`);
  pruef('… mit derselben Kraft wie die Stuetze dort', sZ.ankerkraft.N,
        (zugSeite === 'plus' ? uPlus : uMinus).N, 1e-9, 'kN');
  wahr('… und entlastet den Mastfuss',
       Math.abs(sZ.stationen[0].Myy) < Math.abs(ohne.stationen[0].Myy));

  // Das Seil auf der Druckseite: es fällt aus
  const sD = MK.mastSchnitt(mitAnker(anker('SA20', druckSeite)), 'B');
  wahr('Das Seil auf der Druckseite haengt durch', sD.ankerkraft.schlaff === true);
  pruef('… seine Kraft ist null', sD.ankerkraft.N, 0, 1e-12, 'kN');
  wahr('… und es sagt, was es haette druecken muessen',
       sD.ankerkraft.NohneAusfall < 0, `${sD.ankerkraft.NohneAusfall?.toFixed(2)} kN`);
  /*
   * DER MAST STEHT DANN ALLEIN - Station fuer Station dieselben
   * Schnittgroessen wie ganz ohne Anker. Bis zum 16. September hielt ihn
   * das Seil auch hier, und der Mastfuss war auf der unsicheren Seite
   * entlastet.
   */
  const gleich = sD.stationen.length === ohne.stationen.length
    && sD.stationen.every((s, i) => ['N', 'Myy', 'Mxx', 'Fx', 'Fy']
      .every((k) => Math.abs((s[k] ?? 0) - (ohne.stationen[i][k] ?? 0)) < 1e-9));
  wahr('Der Mast traegt allein - wie ohne Anker', gleich);
  const stD = MK.mastSchnitt(mitAnker(anker('U12', druckSeite)), 'B');
  wahr('Die Stuetze auf derselben Seite haelt dagegen weiter',
       Math.abs(stD.stationen[0].Myy) < Math.abs(ohne.stationen[0].Myy));

  // Der Nachweis
  const nS = AN.ankerNachweis('SA20', 0, 5, { schlaff: true, NohneAusfall: -7 });
  wahr('Der Nachweis sagt «haengt durch» - ohne eta, ohne Versagen',
       nS.grund === 'schlaff' && nS.eta === null && nS.ok === true, JSON.stringify(nS));
  wahr('… und nennt die Kraft, die es haette druecken muessen', nS.NohneAusfall === -7);
  const nRoh = AN.ankerNachweis('SA20', -10, 8.0);
  wahr('Ein negatives N von aussen heisst dasselbe',
       nRoh.grund === 'schlaff' && nRoh.ok === true && nRoh.NohneAusfall === -10);
  wahr('Die Stuetze auf Druck bleibt ein Knicknachweis',
       AN.ankerNachweis('U12', -40, 9.0).grund === 'knicken');
  const nZ = AN.ankerNachweis('SA20', 30, 8.0);
  wahr('Das Seil auf Zug wird gegen seine Betriebslast nachgewiesen',
       nZ.grund === 'befestigung' && Math.abs(nZ.eta - 30 / 67) < 1e-9, JSON.stringify(nZ));
}

titel('67  Der Seilanker in der AxisVM-Ausleitung');
/* ===========================================================================
 * >>> NUR ZUG - UEBER DAS LINKELEMENT AM MASTEN. <<<
 * ===========================================================================
 *
 * Befund vom 16. September: «dies noch beim export zum axis vm auch beachten
 * und verbindungs anpassen.» Das Seil war ein Balken mit Momentengelenken
 * an beiden Enden, also ein Pendelstab für Zug UND Druck.
 *
 * Jetzt: Konsole -- Seilkopf (Link, Ortssystem, x nur Zug) -- Seil -- Gelenk
 * -- Fundament. Die Nichtlinearität steht nur am Link, weil sie nur dort
 * an der Schnittstelle vermessen ist.
 * ========================================================================= */
{
  const AXs = await import(J('export.axisvm.js'));
  const CCs = await import(J('core.constants.js'));
  const lauf = (anker) => {
    const w = CCs.rechensatz({
      ...standardwerte(), typ: 'J90', L: 20, xLage: 0, twId: 'T1',
      mastVorhanden: true, endbedingung: 'mast', mastProfil: 'HEB 240',
      mastH: 7.5, mastSteg: 'jochachse',
      masten: [{ id: 'M1', x: 0, profil: 'HEB 240', anker },
               { id: 'M2', x: 20, profil: 'HEB 240' }] });
    const erg = berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                         getStahl(w.stahl), T.getTragjoch(w.typ));
    return AXs.stabmodellJson(erg.modell, { eingabe: w, auflagerModell: 'mast' });
  };
  const j = lauf({ typ: 'SA20', h: 4, a: 3, richtung: 'x', seite: 'minus',
                   befestigung: 'ankerplatte' });
  const st = (n) => (j.staebe ?? []).find((x) => new RegExp(n).test(x.name));
  const kopf = st('^SEILKOPF_');
  const seil = st('^ANKER_[^_]+$');

  wahr('Der Seilkopf steht im Modell', Boolean(kopf), (j.staebe ?? [])
    .filter((x) => /ANKER|SEIL/.test(x.name)).map((x) => x.name).join(', '));
  wahr('… als Linkelement', kopf?.art === 'link');
  wahr('… im Ortssystem seiner Linie', kopf?.system === 'lokal');
  wahr('… und in der Achse nur Zug', kopf?.nichtlinear?.x === 'nurZug'
       && Object.keys(kopf?.nichtlinear ?? {}).length === 1);
  const k = kopf?.kraftuebertragung ?? {};
  wahr('Quer und in Torsion gehalten, beide Biegemomente frei',
       k.x === 'Rigid' && k.y === 'Rigid' && k.z === 'Rigid' && k.xx === 'Rigid'
       && k.yy === 'Free' && k.zz === 'Free', JSON.stringify(k));
  wahr('Das Seil schliesst an den Seilkopf an',
       Boolean(seil) && seil.von === kopf?.bis, `${seil?.von} / ${kopf?.bis}`);
  wahr('… ist ein Stab mit Gelenk nur am Fundament',
       seil?.art === 'stab' && seil.gelenkEnde === 'M' && !seil.gelenkAnfang);
  const kn = (n) => (j.knoten ?? []).find((x) => x.name === n);
  const a = kn(kopf?.von), b = kn(kopf?.bis), f = kn(seil?.bis);
  const lg = (p, q2) => Math.hypot(q2.x - p.x, q2.y - p.y, q2.z - p.z);
  pruef('Der Seilkopf ist 50 mm lang', lg(a, b), 0.05, 1e-5, 'm');
  wahr('… und liegt in der Seilachse',
       Math.abs(lg(a, b) + lg(b, f) - lg(a, f)) < 1e-6);
  const qs = (j.querschnitte ?? []).find((x) => x.name === seil?.querschnitt);
  wahr('Das Seil ist ein Quadrat gleicher Flaeche, kein Blech',
       qs && Math.abs(qs.parameter[0] - qs.parameter[1]) < 1e-6
       && Math.abs(qs.parameter[0] * qs.parameter[1]
                   - AN.ankerQuerschnitt('SA20').A * 100) < 1e-3,
       JSON.stringify(qs?.parameter));
  wahr('Der Bericht nennt den Anker «nur Zug»',
       (j.anker ?? []).some((x) => x.typ === 'SA20' && x.nurZug === true)
       || JSON.stringify(j).includes('"nurZug":true'));

  // Die Stütze bleibt, wie sie war
  const jU = lauf({ typ: 'U12', h: 4, a: 3, richtung: 'x', seite: 'minus',
                    befestigung: 'ankerplatte' });
  wahr('Die Stuetze hat keinen Seilkopf und nichts «nur Zug»',
       !(jU.staebe ?? []).some((x) => /^SEILKOPF_/.test(x.name) || x.nichtlinear));
  wahr('Kein anderes Linkelement steht im Ortssystem',
       (j.staebe ?? []).filter((x) => x.system === 'lokal').length === 1);

  // Die Brücke kennt die Felder
  const ps1 = readFileSync(join(HIER, 'com', 'AxisVM_aufbauen.ps1'), 'utf8');
  wahr('Die Bruecke setzt lnlTensionOnly aus der Datei',
       /'nurZug'\s*\{\s*'lnlTensionOnly'\s*\}/.test(ps1));
  wahr('… und das Ortssystem', /sysLocal/.test(ps1) && /\$sb\.system/.test(ps1));
  wahr('… und sagt, dass es nur nichtlinear wirkt', /NICHTLINEAREN Berechnung/.test(ps1));
  wahr('Die Bruecke ist reines ASCII', /^[\x00-\x7F]*$/.test(ps1));
}

titel('68  Das Menueband und der Name der Anwendung');
/*
 * Weisung vom 16. September: «wo ist die tabelle aufrufbar? und noch das
 * menueband allgemein überarbeiten ordnen und den appnamen auf Vierendeel
 * umschreiben.» Die Bauteildaten waren nur über die Taste k erreichbar.
 *
 * Geprüft wird der Quelltext: der Prüfstand zeichnet keine Oberfläche.
 */
{
  const app = APP_QUELLE();
  const html = readFileSync(join(HIER, 'index.html'), 'utf8');
  const man = JSON.parse(readFileSync(join(HIER, 'manifest.webmanifest'), 'utf8'));
  const CCn = await import(J('core.constants.js'));

  const kopf = app.slice(app.indexOf('function baueKopf'),
                         app.indexOf('\nfunction aktualisiereProjektKnopf'));
  const gruppen = [...kopf.matchAll(/gruppe\('([^']+)'/g)].map((m) => m[1]);
  wahr('Drei Gruppen in dieser Reihenfolge',
       gruppen.join(' | ') === 'Ausgabe | Bearbeiten | Hilfe und Einstellungen',
       gruppen.join(' | '));
  const lage = (id) => kopf.indexOf(`id="${id}"`) >= 0 ? kopf.indexOf(`id="${id}"`)
                                                        : kopf.indexOf(`'${id}'`);
  // Seit dem 19. September («lege alle relevanten buttons in einen
  // export»): ein Knopf «Export» ganz links, AxisVM darin zuoberst.
  wahr('Der Export-Knopf steht ganz links', lage('btn-ausleiten') >= 0
       && ['btn-zurueck', 'btn-speichern', 'btn-optionen']
         .every((id) => lage(id) > lage('btn-ausleiten')));
  wahr('… und die vier einzelnen Ausgabe-Knoepfe sind weg',
       ['btn-axisvm', 'btn-bericht', 'btn-export', 'btn-drucken']
         .every((id) => !app.includes(`'${id}'`) && !app.includes(`"${id}"`)));
  const menue = app.slice(app.indexOf('function exportMenue()'),
                          app.indexOf('function exportMenueVerdrahten'));
  const eintraege = [...menue.matchAll(/text: '([^']+)'/g)].map((m) => m[1]);
  wahr('Das Menue fuehrt AxisVM (JSON, SAF, DXF), PyNite, Bericht, Excel, Drucken',
       eintraege.length === 7 && /COM/.test(eintraege[0])
       && ["ax('json')", "ax('saf')", "ax('dxf')", "ax('pynite')", 'dialogBericht(app)',
           'exportKlick', 'window.print()'].every((t) => menue.includes(t)),
       eintraege.join(' · '));
  wahr('… und der AxisVM-Dialog nimmt das Format vorgewaehlt entgegen',
       /export function dialogAxisvm\(app, format = 'json'\)/.test(
         readFileSync(join(HIER, 'js', 'app.axisvm.js'), 'utf8')));
  // Weisung vom 17. September: «bauteildaten und tastenkürzel unter optionen führen».
  wahr('Bauteildaten und Tastenkuerzel stehen nicht mehr im Band',
       !kopf.includes('btn-bauteildaten') && !kopf.includes('btn-tasten'));
  const opt = app.slice(app.indexOf('function dialogOptionen'),
                        app.indexOf('function dialogOptionen') + 12000);
  wahr('… sondern im Optionen-Fenster',
       /\[data-bauteildaten\]'\)\.onclick = \(\) => \{ d\.zu\(\); (app\.)?dialogBauteildaten\(\)/.test(opt)
       && /\[data-tasten\]'\)\.onclick = \(\) => \{ d\.zu\(\); (app\.)?dialogTasten\(\)/.test(opt));
  wahr('… und bleiben ueber die Tasten erreichbar',
       /id: 'bauteildaten', taste: 'k'/.test(app));
  wahr('Die Titel lesen das Kuerzel aus der Belegung, nicht aus dem Text',
       /tasteVon\(t\)/.test(kopf));
  wahr('Die Datenbasis in den Optionen fuehrt zum Fenster',
       /data-daten-fenster/.test(readFileSync(join(HIER, 'js', 'ui.js'), 'utf8'))
       && /\[data-daten-fenster\][\s\S]{0,80}dialogBauteildaten/.test(app));

  wahr('Die Anwendung heisst Vierendeel', CCn.APP_NAME === 'Vierendeel');
  wahr('… im Fenstertitel und im Logo',
       /<title>Vierendeel<\/title>/.test(html) && /tb-logo">VIERENDEEL</.test(html));
  wahr('… im Manifest', man.short_name === 'Vierendeel' && /^Vierendeel/.test(man.name));
  wahr('… in der Fusszeile', /st-version'\)\.textContent = `\$\{APP_NAME\}/.test(app));
  wahr('Kein Dateiname beginnt mehr mit «Tragjoch_»', !/`Tragjoch[_-]/.test(app));
  /*
   * DIE KENNUNGEN BLEIBEN. Der Browserspeicher und die Dateiformate tragen
   * «tragjoch» - umbenannt waeren alle gespeicherten Staende weg.
   */
  wahr('Die Kennungen im Browserspeicher bleiben',
       /'tragjoch-daten-v1'/.test(readFileSync(join(HIER, 'js', 'data.paket.js'), 'utf8'))
       && /'tragjoch-eingelesen-v1'/.test(readFileSync(join(HIER, 'js', 'data.einlesen.js'), 'utf8')));
  wahr('Das Bauteil heisst weiterhin Tragjoch',
       CCn.TRAGWERKSARTEN.find((a) => a.key === 'joch')?.label === 'Tragjoch');
}

titel('69  Das auskragende Joch: was die Maste bekommen');
/* ===========================================================================
 * Befund vom 16. September am Testtragwerk (J70-alt, L = 16.50 m, Mast B
 * 7.30 m vor dem Jochende): «der Mast auf Seite auskragendes Joch hatte zu
 * niedrige Momente und zu kleine Ausnutzung im Vergleich zur App.»
 *
 * Gegen AxisVM nachgerechnet. Die Anwendung verteilte die Querkraefte ueber
 * die ganze Jochlaenge und gab das Stuetzmoment des Feldes in den Masten
 * statt des Anschlussmoments. Beides ist hier festgehalten, dazu der Hebel
 * der Konsole und die Bereinigung der Ausleitung.
 * ========================================================================= */
{
  const CCk = await import(J('core.constants.js'));
  const MAk = await import(J('core.mast.js'));
  const AUk = await import(J('core.auflager.js'));
  const AXk = await import(J('export.axisvm.js'));
  const { getMastprofil } = await import(J('data.masten.js'));
  const satz = (krag, zusatz = {}) => CCk.rechensatz({
    ...standardwerte(), typ: 'J90', L: 16.5, kragA: 0, kragB: krag, xLage: 0,
    mastVorhanden: true, endbedingung: 'mast', mastProfil: 'HEB 220', mastH: 7.4,
    mastSteg: 'jochachse',
    masten: [{ id: 'M1', x: 0, profil: 'HEB 220' },
             { id: 'M2', x: 16.5 - krag, profil: 'HEB 220' }], ...zusatz });
  const lauf = (w) => berechne(w, getProfil(w.profOG), getProfil(w.profUG),
                               getStahl(w.stahl), T.getTragjoch(w.typ));
  const joch = (m, e) => MAk.mastLasten(m, e).lasten[0];

  // --- ohne Kragarm: wie bisher, nur B global gezaehlt --------------------
  const m0 = lauf(satz(0)).modell;
  pruef('Ohne Kragarm: F_y je Mast die Haelfte', joch(m0, 'B').Fy,
        (m0.wd * 16.5 + (m0.H ?? []).reduce((s, p) => s + p.w, 0)) / 2, 1e-9, 'kN');
  const eK = AUk.konsolLaenge(m0, getMastprofil('HEB 220'));
  pruef('Die Konsole ist eine halbe Mastbreite lang', eK, 0.11, 1e-12, 'm');
  pruef('Mast A: Anschlussmoment plus F_z mal Konsole', joch(m0, 'A').Myy,
        m0.MA + joch(m0, 'A').Fz * eK, 1e-9, 'kNm');
  pruef('Mast B: dasselbe, global mit umgekehrtem Drehsinn', joch(m0, 'B').Myy,
        -m0.MB - joch(m0, 'B').Fz * eK, 1e-9, 'kNm');
  wahr('Die Konsole gibt F_y keinen Arm - keine Torsion aus dem Joch',
       joch(m0, 'A').ex === 0 && joch(m0, 'A').eKonsole === eK);

  // --- mit Kragarm ---------------------------------------------------------
  const m1 = lauf(satz(7.3)).modell;
  const Ls = 9.2;
  const Hsum = (m1.H ?? []).reduce((s, p) => s + p.w, 0);
  const FyB = m1.wd * 16.5 * (8.25 / Ls)
            + (m1.H ?? []).reduce((s, p) => s + p.w * (p.x / Ls), 0);
  pruef('Mit Kragarm: F_y nach dem Hebelgesetz um die Mastachsen',
        joch(m1, 'B').Fy, FyB, 1e-9, 'kN');
  pruef('… und beide zusammen sind die ganze Kraft',
        joch(m1, 'A').Fy + joch(m1, 'B').Fy, m1.wd * 16.5 + Hsum, 1e-9, 'kN');
  wahr('… der innere Mast traegt deutlich mehr als die Haelfte',
       joch(m1, 'B').Fy > 0.8 * (m1.wd * 16.5 + Hsum),
       `${joch(m1, 'B').Fy.toFixed(2)} kN`);
  const MkB = m1.feldmodell.MkB;
  wahr('Das Kragarmmoment ist da', MkB > 10, `${MkB.toFixed(2)} kNm`);
  pruef('In den Masten geht das Anschlussmoment M_B − M_kB', joch(m1, 'B').Myy,
        -(m1.MB - MkB) - joch(m1, 'B').Fz * eK, 1e-9, 'kNm');
  const an = AUk.jochAnteile(m1);
  pruef('jochAnteile rechnet dasselbe', an.B.Man, m1.MB - MkB, 1e-12, 'kNm');

  // Gelenkig: der Mast bekommt nur F_z mal Konsole - nicht das Kragarmmoment.
  const mg = lauf(satz(7.3, { endbedingung: 'gelenkig' })).modell;
  pruef('Gelenkig mit Kragarm: M_B ist das Kragarmmoment', mg.MB,
        mg.feldmodell.MkB, 1e-9, 'kNm');
  pruef('… und der Mast bekommt davon nichts, nur F_z·e', joch(mg, 'B').Myy,
        -joch(mg, 'B').Fz * eK, 1e-9, 'kNm');

  // Die Federbegrenzung liest das Anschlussmoment.
  const bf = AUk.begrenzeFeder({ L: 9.2, qd: 0, P: [], M: [], EI: 2e4,
                                 cA: 5000, cB: 5000, h: 0.3, Fgrenz: 50,
                                 MkA: 0, MkB: 20 });
  wahr('Ein Kragarm allein drueckt die Feder nicht auf null',
       bf.cB > 0 && bf.FB <= 50 + 1e-6,
       `c_B ${bf.cB.toFixed(0)}, F_B ${bf.FB.toFixed(2)} kN`);

  // --- die Ausleitung ------------------------------------------------------
  const w2 = satz(7.3);
  const j2 = AXk.stabmodellJson(lauf(w2).modell, { eingabe: w2, auflagerModell: 'mast' });
  const lage = new Map();
  j2.knoten.forEach((k) => {
    const s = `${k.x.toFixed(6)}|${k.y.toFixed(6)}|${k.z.toFixed(6)}`;
    lage.set(s, (lage.get(s) ?? []).concat(k.name));
  });
  const doppelt = [...lage.values()].filter((v) => v.length > 1);
  wahr('Kein Knoten liegt auf einem anderen', doppelt.length === 0,
       doppelt.slice(0, 3).map((v) => v.join('=')).join(', '));
  const schl = j2.lasten.punkt.map((p) => `${p.knoten}|${p.lastfall}|${p.richtung}`);
  wahr('Je Knoten, Lastfall und Richtung hoechstens eine Last',
       new Set(schl).size === schl.length);
  const kombi = (k) => (j2.kombinationen.find((x) => x.key === k)?.anteile ?? [])
    .map((a) => a.lastfall).sort().join(',');
  wahr('«Ständig (Tragwerk)» umfasst Joch und Anbauteile, ohne Ablenkung',
       kombi('gk') === 'G,G_Anbau', kombi('gk'));
  wahr('«Ablenkkräfte ständig» nur die Ablenkung', kombi('ablk') === 'G_Ablenk',
       kombi('ablk'));
  wahr('Ein Nachweisfall traegt alle drei staendigen Teile',
       kombi('windYp').startsWith('G,G_Ablenk,G_Anbau'), kombi('windYp'));

  // Zwei Lasten am selben Mastpunkt werden eine.
  const zweiAmMast = ['T1', 'T2'].map((id, i) => ({
    id, name: `Teil ${i + 1}`, vorlage: 'direkt', ort: 'mastA', hMast: 5.0,
    x: 0, y: 0, raster: 0, aktiv: true,
    lasten: [block({ einwirkung: 'G', Fz: i ? 1.6 : 0.15 })] }));
  const w3 = satz(0, { anbauteile: zweiAmMast });
  const j3 = AXk.stabmodellJson(lauf(w3).modell, { eingabe: w3, auflagerModell: 'mast' });
  const amMast = j3.lasten.punkt.filter((p) => p.richtung === 'Z'
                                           && /^MAST_A/.test(p.knoten));
  wahr('Zwei Teile am selben Mastpunkt: eine Last', amMast.length === 1,
       JSON.stringify(amMast));
  pruef('… mit der Summe', amMast[0]?.wert ?? 0, -1.75, 1e-9, 'kN');

  // Die Bruecke sichert nach dem Rechnen.
  const ps1k = readFileSync(join(HIER, 'com', 'AxisVM_aufbauen.ps1'), 'utf8');
  wahr('Die Bruecke sichert die Ergebnisse nach dem Rechnen',
       /Ergebnisse gesichert/.test(ps1k) && /^[\x00-\x7F]*$/.test(ps1k));
  /*
   * DIE ZWEITE FLANSCHKANTE (Option, 16. September) haelt nur quer. Die
   * Lagerungsstudie in AxisVM: lotrecht an beiden Kanten gehalten zwaengt
   * die Mastverdrehung den Gurt (978 statt 190 N/mm²), nur quer 168.
   */
  const w5 = satz(7.3, { auflagerZweiFlansche: true });
  const j5 = AXk.stabmodellJson(lauf(w5).modell, { eingabe: w5, auflagerModell: 'mast' });
  const l2 = j5.staebe.filter((x) => /^LINK2_/.test(x.name));
  wahr('Mit der Option: vier Links an der zweiten Kante, nur am inneren Mast',
       l2.length === 4 && l2.every((x) => /^LINK2_B_/.test(x.name)),
       l2.map((x) => x.name).join(', '));
  wahr('… sie halten nur quer',
       l2.every((x) => x.kraftuebertragung.y === 'Rigid'
         && x.kraftuebertragung.x === 'Free' && x.kraftuebertragung.z === 'Free'),
       JSON.stringify(l2[0]?.kraftuebertragung));
  const kn5 = new Map(j5.knoten.map((k) => [k.name, k]));
  pruef('… an der anderen Flanschkante', kn5.get(l2[0]?.bis)?.x ?? 0,
        16.5 - 7.3 + 0.11, 1e-9, 'm');
  const j6 = AXk.stabmodellJson(lauf(satz(7.3)).modell, { eingabe: satz(7.3), auflagerModell: 'mast' });
  wahr('Ohne die Option bleibt es bei einer Konsole',
       !j6.staebe.some((x) => /^LINK2_/.test(x.name)));
  wahr('Die Option steht in der Maske, nur mit Kragarm',
       FELDER.find((f) => f.key === 'auflagerZweiFlansche')
         ?.sichtbar({ ...satz(7.3), mastVorhanden: true }) === true
       && FELDER.find((f) => f.key === 'auflagerZweiFlansche')
         ?.sichtbar({ ...satz(0), mastVorhanden: true }) === false);
  /*
   * KEINE REFERENZ PARALLEL ZUR STABACHSE (16. September). Das Abfangjoch
   * mit Mast gab dem lotrechten Masten lcsZ = [0, 0, 1]; AxisVM rechnete
   * darauf wortlos nicht. Geprueft wird jeder Stab beider Ausleitungen.
   */
  const parallel = (mm) => {
    const K = new Map(mm.knoten.map((k) => [k.name, k]));
    return mm.staebe.filter((st) => {
      const a = K.get(st.von), b = K.get(st.bis);
      const d = [b.x - a.x, b.y - a.y, b.z - a.z];
      const n = Math.hypot(...d);
      const z = st.lcsZ ?? [0, 0, 1];
      const k = [d[1] * z[2] - d[2] * z[1], d[2] * z[0] - d[0] * z[2], d[0] * z[1] - d[1] * z[0]];
      return Math.hypot(...k) / (n || 1) < 1e-6;
    }).map((st) => st.name);
  };
  wahr('Tragjoch mit Mast: keine Stabachse parallel zur Referenz',
       parallel(j5).length === 0, parallel(j5).join(', '));
  const AJk = await import(J('data.abfangjoche.js'));
  if (AJk.abfangDbDa()) {
    const XAk = await import(J('export.axisvm.abfang.js'));
    for (const steg of ['jochachse', 'quer']) {
      const ma = XAk.abfangAxisvmModell('A240', 8.0,
        { mast: { profil: 'HEB 240', hoehe: 7.0, stegrichtung: steg } });
      wahr(`Abfangjoch mit Mast (${steg}): keine Stabachse parallel zur Referenz`,
           parallel(ma).length === 0, parallel(ma).join(', '));
      const mst = ma.staebe.find((st) => st.name === 'MAST_A');
      wahr(`… der Mast folgt der Stegrichtung (${steg})`,
           JSON.stringify(mst.lcsZ) === JSON.stringify(steg === 'jochachse' ? [1, 0, 0] : [0, 1, 0]),
           JSON.stringify(mst.lcsZ));
      // K_XX gehalten auch beim Abfangjoch (Weisung vom 17. September).
      const lk = ma.staebe.filter((st) => /^LINK_/.test(st.name));
      wahr(`… die Links halten K_XX (${steg})`,
           lk.length === 4 && lk.every((st) => st.kraftuebertragung.xx === 'Rigid'),
           lk.map((st) => st.kraftuebertragung.xx).join(','));
    }
  }
  /*
   * EINE FEDERZAHL AM LINK KOMMT ALS FEDER AN. Bis zum 16. September
   * setzte die Bruecke alles ausser 'Free' auf starr - die Maske bot
   * Federwerte an, AxisVM rechnete ohne sie.
   */
  wahr('Die Bruecke uebernimmt Federzahlen der Links',
       /TryParse\(\$wie/.test(ps1k) && /\$script:nFeder\+\+; \$zahl/.test(ps1k));
  const w4 = satz(0, { auflagerLinks: { UG: { z: 25000 }, OG: { xx: 800 } } });
  const j4 = AXk.stabmodellJson(lauf(w4).modell, { eingabe: w4, auflagerModell: 'mast' });
  const k4 = (n) => j4.staebe.find((x) => x.name === n).kraftuebertragung;
  wahr('… und die Ausleitung schreibt sie als Zahl',
       k4('LINK_B_UGR').z === 25000 && k4('LINK_A_OGL').xx === 800,
       `${JSON.stringify(k4('LINK_B_UGR'))} ${JSON.stringify(k4('LINK_A_OGL'))}`);
}

titel('70  Die Ablage nach BlockCalc: Einlesen, Ausleiten, Sicherung');
/* ===========================================================================
 * Weisung vom 17. September: «checke nochmals die projektmanagement
 * funktionalität von der app block calc und übertrage diese in diese app …
 * checke noch den import einzelner und ganzer projekte» - und auf die Liste:
 * «alles umsetzen».
 *
 * Befund dabei: JSON einlesen und ausleiten brachen mit «will is not
 * defined» ab. Geprueft wird die Ablage deshalb am Speicher selbst, mit
 * einem nachgebildeten localStorage - ohne IndexedDB nimmt sie den
 * Ersatzspeicher, und der ist dieselbe Schnittstelle.
 * ========================================================================= */
{
  const merk = globalThis.localStorage;
  const mem = new Map();
  globalThis.localStorage = {
    get length() { return mem.size; },
    key: (i) => [...mem.keys()][i] ?? null,
    getItem: (k) => (mem.has(k) ? mem.get(k) : null),
    setItem: (k, v) => mem.set(k, String(v)),
    removeItem: (k) => mem.delete(k),
  };
  try {
    const S = await import(J('store.js') + '?ablage70');
    await S.sichern({ name: 'Joch A', projekt: 'P1', werte: { linie: '600', km: '1.000' } });
    await S.sichern({ name: 'Joch B', projekt: 'P1', werte: { linie: '600' } });
    await S.vorlageSichern({ name: 'V1', werte: { typ: 'J90' } });
    localStorage.setItem('tragjoch-tasten', '{"a":1}');

    const json = await S.alsJson();
    wahr('JSON ausleiten laeuft', JSON.parse(json).eintraege.length === 2);

    const paket = await S.alsPaket({ eintraege: true, vorlagen: false, zeichnungen: true });
    const inh = await S.paketInhalt(paket);
    wahr('Abgewaehlte Vorlagen bleiben draussen', inh.vorlagen === 0);
    wahr('Die Vorschau nennt jeden Eintrag und seine Kollision',
         inh.liste.length === 2 && inh.liste.every((e) => e.doppeltZu));
    const inhJ = await S.paketInhalt(new TextEncoder().encode(json));
    wahr('… auch fuer eine JSON', inhJ.liste.length === 2 && !inhJ.zip);

    const vorher = (await S.liste()).length;
    const ids = inh.liste.map((e) => e.id);
    const r = await S.einlesen(paket, { doppelt: { [ids[0]]: 'ueberspringen' },
                                        doppeltAlle: 'ersetzen' });
    wahr('Je Eintrag: ueberspringen und ersetzen',
         r.uebersprungen === 1 && r.ersetzt === 1 && r.eintraege === 0, JSON.stringify(r));
    wahr('… ohne neue Eintraege', (await S.liste()).length === vorher);
    const r2 = await S.einlesen(paket, { ids: [ids[1]], zielProjekt: 'P2' });
    wahr('Nur die gewaehlten, in ein anderes Projekt',
         r2.eintraege === 1 && (await S.projektNamen()).join() === 'P1,P2');

    const sich = await S.alsSicherung();
    const inhS = await S.paketInhalt(sich);
    wahr('Die Sicherung traegt Einstellungen und Vorlagen',
         inhS.einstellungen >= 1 && inhS.vorlagen === 1);
    mem.delete('tragjoch-tasten');
    const r3 = await S.einlesen(sich, { ids: [], vorlagen: false, einstellungen: true });
    wahr('… und spielt sie zurueck',
         localStorage.getItem('tragjoch-tasten') === '{"a":1}' && r3.einstellungen >= 1);
    wahr('Ohne ausdrueckliche Wahl keine Einstellungen',
         (await S.einlesen(sich, { ids: [] })).einstellungen === 0);

    // Erst hier: das Einlesen legt Kopien an und haette die Paketproben
    // oben verfaelscht.
    const n = await S.ausJson(json);
    pruef('JSON einlesen laeuft - Tragwerke und Vorlage', n, 3, 0, 'Stk');
    const r4 = await S.einlesen(new TextEncoder().encode(
      '﻿' + JSON.stringify([{ name: 'Alt', werte: {} }])));
    wahr('Eine blosse Liste mit BOM wird gelesen', r4.eintraege === 1);

    /*
     * ZWEIMAL DERSELBE NAME IN EINER DATEI (17. September): beide auf
     * «ersetzen» - der zweite darf den ersten nicht ueberschreiben.
     */
    const zwei = new TextEncoder().encode(JSON.stringify({ format: 'tragjoch-ablage',
      eintraege: [
        { id: 'd1', name: 'Joch A', projekt: 'P1', werte: { km: 'erster' } },
        { id: 'd2', name: 'Joch A', projekt: 'P1', werte: { km: 'zweiter' } }] }));
    const vorZwei = (await S.liste()).length;
    const inhZ = await S.paketInhalt(zwei);
    wahr('Die Vorschau kennzeichnet den wiederholten Namen',
         inhZ.liste[0].wiederholt === false && inhZ.liste[1].wiederholt === true);
    const rZ = await S.einlesen(zwei, { doppeltAlle: 'ersetzen' });
    const aNamen = (await S.liste()).filter((x) => x.name === 'Joch A' && x.projekt === 'P1');
    wahr('Zweimal «ersetzen»: der erste ersetzt, der zweite kommt als Kopie',
         rZ.ersetzt === 1 && rZ.alsKopie === 1 && rZ.eintraege === 1
         && (await S.liste()).length === vorZwei + 1
         && ['erster', 'zweiter'].every((k) => aNamen.some((x) => x.werte?.km === k)),
         JSON.stringify(rZ));

    const e = (await S.liste()).find((x) => x.name === 'Alt');
    await S.eintragFeld(e.id, 'km', ' 12.345 ');
    wahr('Die Tabelle schreibt Beschriftungen in die Werte',
         (await S.laden(e.id)).werte.km === '12.345');
    let fehler = null;
    try { await S.eintragFeld(e.id, 'L', 3); } catch (x) { fehler = x; }
    wahr('… aber nie Rechenwerte', Boolean(fehler));
  } finally {
    globalThis.localStorage = merk;
  }

  // Die Oberflaeche
  const aq70 = APP_QUELLE();
  const sq70 = readFileSync(join(HIER, 'js', 'ui.schema.js'), 'utf8');
  const man70 = JSON.parse(readFileSync(join(HIER, 'manifest.webmanifest'), 'utf8'));
  wahr('Projekt und Tragwerk sind Auswahlfelder',
       aq70.includes('id="bs-projekt"') && aq70.includes('id="bs-tragwerk"')
       && aq70.includes('+ Neues Projekt') && aq70.includes('+ Neues Tragwerk'));
  wahr('Die Ablage ist eine Tabelle mit Suche und Sortierung',
       aq70.includes('class="ab-tabelle"') && aq70.includes('id="bs-suche"')
       && aq70.includes('id="bs-sort"'));
  wahr('Beschriftungen sind unmittelbar bearbeitbar',
       aq70.includes('data-ed-feld') && aq70.includes('store.eintragFeld('));
  wahr('Ausleiten je Projekt und je Eintrag',
       aq70.includes('data-projekt-aus') && aq70.includes('data-eintrag-aus'));
  wahr('Sicherung erstellen und einspielen',
       aq70.includes('store.alsSicherung()') && aq70.includes('ablageEinlesenWaehlen(app, true)'));
  wahr('Die Projektliste laesst sich drucken',
       aq70.includes('function projektlisteDrucken') && aq70.includes("classList.add('druck-liste')"));
  wahr('Speichern ueberschreibt ohne Dialog, wenn ein Eintrag geladen ist',
       aq70.includes("ui.el('btn-speichern').onclick = () => ablageSpeichern(app, false)"));
  wahr('Die Wiederherstellung wird gemeldet',
       aq70.includes('wiederhergestellt') && aq70.includes('gesichert: gesicherteSignatur'));
  wahr('Ein hineingezogenes Paket geht in den Einlesedialog',
       /0x50 && roh\[1\] === 0x4b\) \{\s*try \{ await dialogEinlesen/.test(aq70));
  const st70 = readFileSync(join(HIER, 'js', 'store.js'), 'utf8');
  wahr('Der Dateiwaehler haengt im Dokument, nennt den Namen und bricht still ab',
       /document\.body\.appendChild\(i\)/.test(st70)
       && /mitName \? \{ daten, name: f\.name \}/.test(st70)
       && /addEventListener\('cancel'/.test(st70)
       && /dateiLesenRoh\(\{ mitName: true \}\)/.test(aq70)
       && /if \(!e\?\.abgebrochen\)/.test(aq70));
  wahr('Das Manifest nimmt auch .zip an',
       JSON.stringify(man70.file_handlers).includes('.zip'));
  wahr('Projektnummer, Bearbeiter und Datum sind Felder der Verortung',
       ['projektNr', 'bearbeiter', 'datum'].every((k) =>
         new RegExp(`key: '${k}', gruppe: 'ort'`).test(sq70)));
}

titel('71  Havariefall am Tragjoch und am Masten');
/* ===========================================================================
 * Weisung vom 17. September: «der Ablenkwinkel kann zur hälfte angewendet
 * werden … bei den übrigen tragwerken tragjoch mast, wird bei den leitern
 * direkt an joch oder am masten nur ein anteil von 10% der leiterzugkraft
 * angesetzt» - Bruch ueber den Schalter an der Bauteilkarte.
 * ========================================================================= */
{
  const L71 = await import(J('core.lasten.js'));
  const A71 = await import(J('data.anbauteile.js'));
  const FL71 = await import(J('data.fl.js'));
  const grund = { ...standardwerte(), typ: 'J90', L: 20, trasseRadius: 600,
    anbauteile: [{ ...A71.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL' }] };
  const lf = L71.lastfaelle(grund);
  const hav = lf.filter((l) => l.art === 'aussergewoehnlich');
  /*
   * >>> DAS VORZEICHEN STEHT IN DER KRAFT (24. September). <<<
   *
   * Hier wurde `beiwerte.HavarieY === -1` fuer den zweiten Fall geprueft.
   * Der Beiwert gilt allen Leitern des Falls gemeinsam, und seit die
   * einseitige Abfangung eine FESTE Zugrichtung hat, geht das nicht mehr:
   * ihr Zug faellt beim Riss weg, er kehrt sich nicht um. Gedreht wird
   * jetzt in `havarieEinsetzen`, Leiter fuer Leiter; der Beiwert bleibt
   * +1. Die RICHTUNG des Falls steht weiterhin in `vorzeichen`.
   */
  wahr('Mit Leiter gibt es zwei Havariefaelle, beide Richtungen',
       hav.length === 2 && hav.every((l) => l.nachweis && l.beiwerte.G === 1
         && l.beiwerte.WindX === 0 && l.beiwerte.WindY === 0 && l.beiwerte.Schnee === 0
         && l.beiwerte.HavarieY === 1)
       && hav[0].vorzeichen === 1 && hav[1].vorzeichen === -1,
       hav.map((l) => l.bez).join(' | '));
  wahr('Ohne Leiter keiner',
       !L71.lastfaelle({ ...grund, anbauteile: [] })
         .some((l) => l.art === 'aussergewoehnlich'));
  const flach = (bruch) => A71.expandiereAnbauteile(
    grund.anbauteile.map((a) => ({ ...a, bruch })), { ek: 'EK2', R: 600, spannweite: 60 });
  const dw = (liste) => liste.find((t) => t.rolle === 'drahtwerk');
  const heil = dw(flach(false)), weg = dw(flach(true));
  const Gx = heil.kraefte.G.Fx;
  const h = A71.havarieAnteile({ id: heil.bauteil, n: heil.anzahl ?? 1, GxHier: Gx });
  pruef('Ohne Bruch: Ablenkung bei −20 °C', Gx + heil.kraefte.HavarieX.Fx,
        Gx * h.faktor, 1e-9, 'kN');
  pruef('… und kein Laengszug', heil.kraefte.HavarieY.Fy, 0, 1e-12, 'kN');
  pruef('Mit Bruch: die halbe Ablenkung', Gx + weg.kraefte.HavarieX.Fx,
        0.5 * Gx * h.faktor, 1e-9, 'kN');
  pruef('… und 10 % des Leiterzugs laengs', weg.kraefte.HavarieY.Fy,
        0.10 * h.Z20 * (heil.anzahl ?? 1), 1e-9, 'kN');
  wahr('Z(−20 °C) kommt aus der Reglagetabelle oder sagt, dass sie fehlt',
       (() => { const k = FL71.abfangkraft(heil.bauteil, { tempFall: 'havarie' });
                return k.Z === h.Z20 && (k.ausTabelle || k.ohneTabelle || !k.temperaturabhaengig); })());
  const { vergleichKombinationen: vgl } = await import(J('core.vierendeel.js'));
  const r = vgl({ ...grund, anbauteile: grund.anbauteile.map((a) => ({ ...a, bruch: true })) },
    getProfil(grund.profOG), getProfil(grund.profUG), getStahl(grund.stahl), T.getTragjoch('J90'));
  wahr('Der Havariefall wird gerechnet und geht in die Huellkurve',
       hav.every((l) => r.ergebnisse?.[l.key]) && Number.isFinite(r.huellkurve.max.etaGesamt));
  const tx = Math.max(...r.ergebnisse.havariep.knoten.map((k) => Math.abs(k.Tx ?? 0)));
  wahr('Der Laengszug erzeugt Torsion bzw. Querbiegung im Joch',
       tx > 0 || Math.max(...r.ergebnisse.havariep.knoten.map((k) => Math.abs(k.Mz ?? 0))) > 0);
  const ui71 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
  // Seit dem 19. September in der Uebersicht unter Lasten, die Karte verweist.
  wahr('Die Bruchwahl steht in der Übersicht, die Karte verweist darauf',
       /data-hav="reisst"/.test(ui71) && /hatDrahtwerk\(a\)/.test(ui71)
       && ui71.includes('steht unter <b>Lasten → Havarie</b>'));
  wahr('… und die Maske fuehrt jedes Kaestchen mit seinem eigenen Wert nach',
       /inp\.checked = k === 'aktiv' \? a\.aktiv !== false : a\[k\] === true/.test(ui71));
}

titel('73  Ablenkwinkel null ist ein Winkel');
/* Weisung vom 17. September: «wenn man hier 0 einsetzt hat es keine auswirkung». */
{
  const TR73 = await import(J('core.trasse.js'));
  const A73 = await import(J('data.anbauteile.js'));
  pruef('Winkel 0: keine Umlenkung', TR73.umlenkkraft({ Z: 10, L: 30, R: 600, winkel: 0 }).U,
        0, 1e-12, 'kN');
  wahr('Leer: aus Radius und Spannweite',
       TR73.umlenkkraft({ Z: 10, L: 30, R: 600, winkel: null }).U > 0);
  pruef('Der Modulwinkel meldet die Null', A73.modulWinkel({ winkel: 0 }, { R: 600, spannweite: 30 }),
        0, 1e-12, '°');
  const at = { ...A73.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL' };
  const mitNull = { ...at, module: at.module.map((m) => ({ ...m, winkel: 0 })) };
  const gx = (a) => A73.expandiereAnbauteile([a], { ek: 'EK2', R: 600, spannweite: 30 })
    .filter((t) => t.rolle === 'drahtwerk').reduce((s, t) => s + t.kraefte.G.Fx, 0);
  wahr('Am Bauteil: mit 0 keine Ablenkkraft, leer eine',
       Math.abs(gx(mitNull)) < 1e-12 && Math.abs(gx(at)) > 0, `${gx(at).toFixed(3)} kN`);
}

titel('74  Seilanker: der Wind aus beiden Richtungen');
/* Frage vom 17. September: «bei zuganker auswahl -x ausrichtung wirkt der
 * anker auch als druckelement, denke ich». Im Mastnachweis faellt das Seil
 * aus, wo es druecken muesste; der Ankernachweis sah aber den Gegenwind
 * nicht. */
{
  const MK = await import(J('core.mast.js'));
  const A74 = await import(J('data.anbauteile.js'));
  const basis = { ...standardwerte(), typ: 'J90', L: 15, mastVorhanden: true,
    mastProfil: 'HEB 260', mastH: 8, trasseRadius: 600,
    anbauteile: [{ ...A74.neuesAnbauteil('hs-fahrdraht', 7.5), name: 'FL' }] };
  const { vergleichKombinationen: vgl74 } = await import(J('core.vierendeel.js'));
  const kraft = (seite) => {
    const w = { ...basis, mastAnkerA: { typ: 'SA20', h: 7.79, a: 4.5, richtung: 'y',
                                        seite, befestigung: 'ankerplatte' } };
    const r = vgl74(w, getProfil(w.profOG), getProfil(w.profUG), getStahl(w.stahl),
                    T.getTragjoch('J90'));
    return (key) => r.ergebnisse[key]?.mast?.A?.ankerkraft;
  };
  const plus = kraft('plus'), minus = kraft('minus');
  wahr('Im Mastnachweis faellt das Seil aus, wo es druecken muesste',
       plus('windYp').schlaff === true && plus('windYm').N > 0
       && minus('windYm').schlaff === true && minus('windYp').N > 0);
  wahr('Die charakteristischen Faelle kennen den Wind nur in einer Richtung',
       plus('wyk').schlaff === true && minus('wyk').N > 0);
  const aq74 = APP_QUELLE();
  wahr('Der Ankernachweis sieht den Gegenwind in den charakteristischen Faellen',
       minus('wykm').schlaff === true && plus('wykm').N > 0);
  pruef('… und der Zug aus dem Gegenwind ist der gespiegelte',
        plus('wykm').N, minus('wyk').N, 1e-9, 'kN');
  const ui74 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
  wahr('Die Seitenwahl folgt der Ebene: Optionstexte stehen in der Signatur',
       /const feldSignatur = \(werte\) => \(f\) =>/.test(ui74)
       && /sichtbareFelder\(gid, werte\)\.map\(feldSignatur\(werte\)\)/.test(ui74));
}

titel('75  Abfangjoch: Mast und Anker ueber alle Windrichtungen');
/* Weisung vom 17. September: «der wind in y und x sollte immer auf beide
 * seiten angesetzt werden» - «die masten und anker nicht vergessen». */
{
  // Seit dem 19. September steht die Ankerrechnung in core.anker.js (A1).
  const aq75 = APP_QUELLE();
  wahr('Der Mast am Abfangjoch ist die Huellkurve ueber alle Faelle',
       /erg\.mast = mastNachweiseHuelle\(abfangVarianten\(erg\.abfang\.auflager\)/.test(aq75));
  wahr('… mit Mastwind und Mast-Anbauteilen im selben Fall',
       /xd: bw\.w \* wx \* \(s\.x \?\? 0\)/.test(aq75)
       && /WindY: bw\.w \* wy/.test(aq75));
  wahr('Der Anker am Abfangjoch sieht jeden Fall charakteristisch',
       /abfangModell\(modell, auflager, fa, fb, true\)/.test(aq75));
  const MK75 = await import(J('core.mast.js'));
  const h = MK75.mastNachweiseHuelle([
    { fall: 'a', erg: { A: { eta: 0.3, etaMitStabilitaet: 0.4, ende: 'A' },
                        B: { eta: 0.9, etaMitStabilitaet: 0.9, ende: 'B' } } },
    { fall: 'b', erg: { A: { eta: 0.5, etaMitStabilitaet: 0.6, ende: 'A' },
                        B: { eta: 0.2, etaMitStabilitaet: 0.2, ende: 'B' } } }]);
  wahr('Die Huellkurve nimmt je Ende den groessten Nachweis und nennt den Fall',
       h.A.fall === 'b' && h.B.fall === 'a' && h.etaNachweis === 0.9);
}

titel('76  Die Huellkurve nimmt den Masten aus jedem Fall');
/* Meldung vom 17. September: «in diesem fall wirkt immernoch der zuganker
 * stabilisierend oder der wind in die gegenrichtung wird nicht angesetzt».
 * Die Huellkurve gab den Mast des ERSTEN Nachweisfalls weiter; der
 * Einzelmast wurde nur in einem Fall gerechnet. */
{
  const A76 = await import(J('data.anbauteile.js'));
  const { vergleichKombinationen: vgl76 } = await import(J('core.vierendeel.js'));
  const seil = { typ: 'SA20', h: 7.79, a: 4.5, richtung: 'y', seite: 'minus',
                 befestigung: 'ankerplatte' };
  const joch = { ...standardwerte(), typ: 'J90', L: 15, mastVorhanden: true,
    mastProfil: 'HEB 260', mastH: 8, trasseRadius: 600, mastAnkerA: seil,
    anbauteile: [{ ...A76.neuesAnbauteil('hs-fahrdraht', 7.5), name: 'FL' }] };
  const r = vgl76(joch, getProfil(joch.profOG), getProfil(joch.profUG),
                  getStahl(joch.stahl), T.getTragjoch('J90'));
  const jeFall = r.lastfaelle.filter((l) => l.nachweis)
    .map((l) => r.ergebnisse[l.key].mast.A.etaMitStabilitaet);
  pruef('Tragjoch: der Mast in der Huellkurve ist das Maximum der Faelle',
        r.huellkurve.mast.A.etaMitStabilitaet, Math.max(...jeFall), 1e-12, '–');
  wahr('… und das ist der Gegenwind mit schlaffem Seil',
       r.ergebnisse.windYm.mast.A.ankerkraft.schlaff === true
       && r.huellkurve.mast.A.fall === 'windYm',
       `Fall ${r.huellkurve.mast.A.fall}`);
  const em = { ...standardwerte(), tragwerksart: 'einzelmast', mastVorhanden: true,
    mastProfil: 'HEB 260', mastH: 8, trasseRadius: 600, mastAnkerA: seil,
    anbauteile: [{ ...A76.neuesAnbauteil('hs-fahrdraht', 0), name: 'FL',
                   ort: 'mastA', hMast: 7 }] };
  const re = vgl76(em, null, null, getStahl(em.stahl), null);
  const jeFallE = re.lastfaelle.filter((l) => l.nachweis)
    .map((l) => re.ergebnisse[l.key].max.etaGesamt);
  pruef('Einzelmast: die Huellkurve gibt es, und sie ist das Maximum',
        re.huellkurve?.max?.etaGesamt, Math.max(...jeFallE), 1e-12, '–');
  const aq76 = APP_QUELLE();
  wahr('Die App rechnet auch den Einzelmast ueber alle Kombinationen',
       /const kombi = vergleichKombinationen\(rs, profOG, profUG, stahl, joch\);/.test(aq76)
       && /erg\.anker = erg\.abfang\?\.auflager\s*\? ankerAmAbfangjoch/.test(aq76));
}

titel('77  Der Seilanker in Ergebnisfarben');
{
  const rk77 = readFileSync(join(HIER, 'js', 'render.koerper.js'), 'utf8');
  const zweig = rk77.slice(rk77.indexOf('DER SEILANKER TRAEGT SEINE AUSNUTZUNG'));
  wahr('Auch der Seilanker traegt sein η fuer die Einfaerbung',
       /werte: \{ eta: o\.ankerEta \}/.test(zweig.slice(0, 600)));
}

titel('78  Einzelmast: die Anbauteile stehen im Bild');
/* Gemeldet am 18. September: beim Einzelmasten werden die Anbauteile im
 * Modell nicht dargestellt, obwohl sie gerechnet werden. */
{
  const R78 = await import(J('render.3d.js'));
  const A78 = await import(J('data.anbauteile.js'));
  const em = { ...standardwerte(), tragwerksart: 'einzelmast', mastVorhanden: true,
    mastProfil: 'HEB 240', mastH: 7.5,
    anbauteile: [
      { ...A78.neuesAnbauteil('hs-nt-ausleger', 0), name: 'Ausleger', ort: 'mastA', hMast: 6.5 },
      { ...A78.neuesAnbauteil('hs-fahrdraht', 0), name: 'Aus', ort: 'mastA', hMast: 5, aktiv: false }] };
  const e = berechne(em, null, null, getStahl(em.stahl), null);
  wahr('Das Modell fuehrt die ganze Liste, am Masten',
       e.modell.anbauteile.length === 2 && e.modell.anbauteile.every((a) => a.ort === 'mastA'));
  const sz = R78.erzeugeSzene(e.modell, e);
  const koerper = sz.flaechen.filter((f) => f.gruppe === 'anbau');
  wahr('Die Szene zeichnet das Anbauteil', koerper.length > 0,
       `${koerper.length} Flaechen`);
  wahr('… mit Marke A1 und ohne das ausgeschaltete',
       sz.marken.some((m2) => m2.text === 'A1') && !sz.marken.some((m2) => m2.text === 'A2'));
  // Die Szene misst z ab der Jochachse; der Anschluss sitzt hMast ueber
  // dem Mastfuss.
  const fuss = Math.min(...sz.flaechen.filter((f) => /^MAST_/.test(f.teil ?? ''))
    .flatMap((f) => f.punkte.map((p) => p[2])));
  const anschluss = koerper.filter((f) => /Anschluss am Mast/.test(f.label ?? ''));
  const zAn = anschluss.length
    ? Math.max(...anschluss.flatMap((f) => f.punkte.map((p) => p[2]))) - 0.045 : NaN;
  pruef('… an seiner Hoehe ueber dem Mastfuss', zAn - fuss, 6.5, 1e-6, 'm');
  const ohneX = A78.expandiereAnbauteile([{ ...A78.neuesAnbauteil('hs-fahrdraht', 0),
    x: undefined, ort: 'mastA', hMast: 5 }], { ek: 'EK2' });
  wahr('Eine Baugruppe ohne Lage rechnet mit x = 0, nicht mit NaN',
       ohneX.every((t) => Number.isFinite(t.x)));

  /*
   * DIE ZEICHNUNG AM EINZELMASTEN EINMESSEN (18. September).
   *
   * Er hat kein Joch und keine Anschlusshoehe - also weder das waagrechte
   * Mass noch die Hoehe H. Es bleiben die Mastlaenge vom gezeichneten Fuss
   * und das freie Mass.
   */
  const BZ78 = await import(J('bild.zeichnung.js'));
  const wahl78 = BZ78.bezuegeFuer(e.modell, sz).map((b) => b.key).join();
  wahr('Einzelmast: eingemessen wird ueber die Mastlaenge oder frei',
       wahl78 === 'mastLaenge,frei', wahl78);
  const mb78 = BZ78.bezugPunkte('mastLaenge', e.modell, sz);
  pruef('… vom gezeichneten Fuss', mb78[0].z, fuss, 1e-6, 'm');
  pruef('… ueber die Mastlaenge', mb78[1].z - mb78[0].z,
        e.modell.federn.mast.laenge, 1e-9, 'm');
  const ap78 = BZ78.ausrichtPunkte(sz).map((p) => p.key).join();
  wahr('… und ausgerichtet an Fuss und Kopf, ohne Joch und Anschluss',
       ap78 === 'fussA,kopfA' && BZ78.ausrichtPunkte(sz)[0].label.startsWith('Mast:'),
       ap78);

  // Das Abfangjoch legt seine Bezuege ebenso bei - der Mast endet dort an
  // der Jochachse.
  const RA78 = await import(J('render.abfang.js'));
  const AJ78 = await import(J('data.abfangjoche.js'));
  if (AJ78.abfangDbDa?.() ?? true) {
    let szA = null;
    try {
      szA = RA78.abfangSzene('A330', 20, { anbauteile: [],
        mast: { profil: 'HEB 240', hoehe: 7.0, stegrichtung: 'jochachse', ueberstand: 1.5 } });
    } catch { szA = null; }
    if (szA) {
      const mA = BZ78.bezugPunkte('mast', null, szA);
      pruef('Abfangjoch: Masthoehe bis zum Anschluss', mA[1].z - mA[0].z, 7.0, 1e-9, 'm');
      const lA = BZ78.bezugPunkte('mastLaenge', null, szA);
      pruef('… und die Mastlaenge mit dem Ueberstand', lA[1].z - lA[0].z, 8.5, 1e-9, 'm');
      wahr('… und das Joch ueber die ganze Laenge',
           BZ78.bezugPunkte('joch', null, szA)[1].x === 20);
    }
  }
}

titel('79  Einzelmast: keine Anschlusshoehe, Standorte nur was da ist');
/* Weisung vom 18. September: «diese eingabe beim einzelmast ohne
 * tragausleger ist nicht relevant, ausblenden. Die Standortauswahl nur auf
 * vorhandene Elemente beziehen.» Auf Nachfrage entschieden: die Massen der
 * Anbauteile sitzen im Stabilitaetsnachweis je auf ihrer eigenen Hoehe. */
{
  const A79 = await import(J('data.anbauteile.js'));
  const R79 = await import(J('render.3d.js'));
  const U79 = await import(J('ui.js'));
  const { mastLaengeVorgabe } = await import(J('core.auflager.js'));
  const feldH = FELDER.find((f) => f.key === 'mastH');
  const em = (H, L) => ({ ...standardwerte(), tragwerksart: 'einzelmast', mastVorhanden: true,
    mastProfil: 'HEB 240', mastH: H, mastLaenge: L,
    anbauteile: [{ ...A79.neuesAnbauteil('hs-nt-ausleger', 0), name: 'Ausleger',
                   ort: 'mastA', hMast: 6.5 }] });
  wahr('Die Anschlusshoehe ist beim Einzelmast ausgeblendet',
       feldH.sichtbar(em(7.5, 8.5)) === false);
  wahr('… beim Tragjoch mit Masten steht sie da',
       feldH.sichtbar({ ...standardwerte(), mastVorhanden: true }) === true);

  const rechne79 = (w) => berechne(w, null, null, getStahl(w.stahl), null);
  const e5 = rechne79(em(5.0, 8.5)), e9 = rechne79(em(9.0, 8.5));
  const m5 = e5.mast.A ?? e5.mast, m9 = e9.mast.A ?? e9.mast;
  pruef('Der Mast ist so lang, wie eingegeben - auch mit H darueber',
        m9.zKopf, 8.5, 1e-9, 'm');
  pruef('Die ausgeblendete Hoehe aendert den Spannungsnachweis nicht',
        m9.eta, m5.eta, 1e-12, '');
  pruef('… und den Stabilitaetsnachweis nicht',
        m9.etaMitStabilitaet, m5.etaMitStabilitaet, 1e-12, '');
  const ms = m5.stabil.massen.find((x) => /Ausleger/.test(x.name));
  pruef('Die Masse des Auslegers sitzt auf seiner Befestigungshoehe', ms?.z, 6.5, 1e-9, 'm');
  wahr('… und nichts steht «ueber dem Anschluss»',
       m5.stabil.ueberAnschluss.length === 0 && m5.stabil.zAnschluss === null);
  const ohneL = rechne79(em(7.5, 0));
  pruef('Ohne Laenge gilt die Vorgabe aus der alten Hoehe wie bisher',
        (ohneL.mast.A ?? ohneL.mast).zKopf, mastLaengeVorgabe(7.5, standardwerte().jd), 1e-9, 'm');

  const sz79 = R79.erzeugeSzene(e5.modell, e5);
  const achse = sz79.linien.filter((l) => l.gruppe === 'mast' && l.schwerachse)
    .flatMap((l) => l.punkte.map((p) => p[2]));
  pruef('Im Bild reicht der Mast vom Fuss genau ueber seine Laenge',
        Math.max(...achse) - Math.min(...achse), 8.5, 1e-9, 'm');

  /*
   * UND AM TRAGJOCH DIESELBE REGEL (18. September): «werden die mast massen
   * ... bei den jochtragwerken auf höhe joch gesetzt? ... anpassen
   * entsprechend einzelmast logik.» Die Jochlast bleibt auf H, ein Teil am
   * Masten rechnet auf seiner Befestigungshoehe.
   */
  {
    const wj = basis({ endbedingung: 'mast', mastVorhanden: true, mastProfil: 'HEB 240',
      mastH: 7.5, mastSteg: 'jochachse', mastAnschluss: 'durchlaufend',
      anbauteile: [{ ...A79.neuesAnbauteil('hs-nt-ausleger', 0),
        name: 'Ausleger am Masten', ort: 'mastA', hMast: 4.0 }] });
    const ej = rechne(wj);
    const kj = (ej.mast.A ?? ej.mast).stabil;
    const jl = kj.massen.find((x) => x.name === 'Jochlast');
    pruef('Tragjoch: die Jochlast auf der Anschlusshoehe', jl?.z, (ej.mast.A ?? ej.mast).H,
          1e-9, 'm');
    const am = kj.massen.filter((x) => x.herkunft === 'eigene Befestigungshöhe');
    wahr('… das Teil am Masten auf seinen 4.00 m, nicht auf der Jochhoehe',
         am.length > 0 && am.every((x) => Math.abs(x.z - 4.0) < 1e-9),
         am.map((x) => `${x.name} @ ${x.z}`).join(', '));
  }

  // --- Standorte -----------------------------------------------------------
  const orte = (w) => U79.anbauOrteVorhanden(w).join();
  wahr('Einzelmast: nur am Masten', orte(em(7.5, 8.5)) === 'mastA', orte(em(7.5, 8.5)));
  wahr('Tragjoch mit Masten: Joch und beide Masten',
       orte({ ...standardwerte(), mastVorhanden: true }) === 'joch,mastA,mastB');
  wahr('Tragjoch ohne Masten: nur am Joch',
       orte({ ...standardwerte(), mastVorhanden: false }) === 'joch');
  wahr('Mast mit Tragausleger: Ausleger und sein Mast',
       orte({ ...standardwerte(), tragwerksart: 'tragausleger', mastVorhanden: true })
         === 'joch,mastA');
}

titel('80  Die Fussleiste sagt dasselbe wie die Hauptkachel');
// Befund vom 18. September: unten «Alle Nachweise erfüllt», oben
// «2 Prüfung(en) verletzt · 2 Nachweis(e) nicht geführt».
{
  const { urteilFusszeile } = await import(J('core.checks.js'));
  const u = { anzahlVerletzt: 2, nichtGefuehrt: [{}, {}], tragwerkGefuehrt: true };
  const z = urteilFusszeile({ gut: true, eta: 0.89, wer: ' (Mast M1)', urteil: u });
  wahr('Kein «Alle Nachweise erfüllt» mehr', !/Alle Nachweise/.test(z), z);
  wahr('Verletzte Prüfungen stehen in der Zeile', /2 Prüfungen verletzt/.test(z), z);
  wahr('Nicht geführte Nachweise stehen in der Zeile', /2 nicht geführt/.test(z), z);
  wahr('Das massgebende Bauteil bleibt', /η = 0\.890 \(Mast M1\)/.test(z), z);
  const leer = urteilFusszeile({ gut: true, eta: 0.5,
    urteil: { anzahlVerletzt: 0, nichtGefuehrt: [], tragwerkGefuehrt: true } });
  wahr('Ohne Befund keine Anhängsel', leer === 'Tragsicherheit erfüllt · η = 0.500', leer);
  wahr('Einzahl bei einer Prüfung',
       /1 Prüfung verletzt/.test(urteilFusszeile({ gut: true, eta: 0.5,
         urteil: { anzahlVerletzt: 1 } })));
  wahr('Überschritten heisst NICHT erfüllt',
       /Tragsicherheit NICHT erfüllt/.test(urteilFusszeile({ gut: false, eta: 1.2, urteil: u })));
  wahr('Ohne Jochnachweis kein Tragsicherheitsurteil',
       /^Jochtragwerk nicht geführt/.test(urteilFusszeile({ gut: true, eta: 0.5,
         urteil: { tragwerkGefuehrt: false } })));
}

titel('81  Der Mast trifft nur liegende Bleche und die Gurte');
// Weisung vom 18. September: «am jochende sind nur die stehenden vertikalen
// bindebleche vorhanden … als voreingabe sollte die mastachse genau auf die
// jochlänge ausgerichtet sein … beachtet werden, dass der masten nicht auf
// ein liegendes blech trifft, oder bei den kleinen jochtypen wo sich die
// breite verjüngt nicht mit den gurten kollidiert.»
{
  const CH = await import(J('core.checks.js'));
  const AU = await import(J('core.auflager.js'));
  const mach = (typ, L, kragA, mastProfil = 'HEB 240', mastSteg = 'jochachse') => rechne({
    ...basis(), ...typUebernehmen({ ...standardwerte() }, T.getTragjoch(typ)),
    typ, L, kragA, kragB: 0, anbauteile: [], mastVorhanden: true,
    endbedingung: 'mast', mastProfil, mastSteg, mastH: 7.5,
  }).modell;
  const p = (m, id) => CH.konstruktionsChecks(m).find((c) => c.id === id);

  const m0 = mach('J90', 20, 0);
  wahr('Am Jochende steht ein stehendes Blech …',
       (m0.stationsListe[0].vertikal?.breite ?? 0) > 0);
  wahr('… aber kein liegendes', !(m0.stationsListe[0].horizontal?.breite > 0));
  wahr('Die Vorgabe (Mastachse am Jochende) besteht P9', p(m0, 'P9A').ok === true,
       p(m0, 'P9A').status);
  wahr('Ebenso am Ende B', p(m0, 'P9B').ok === true, p(m0, 'P9B').status);
  wahr('Ins erste liegende Blech (0.75 m) gerückt, fällt er',
       p(mach('J90', 20, 0.75), 'P9A').ok === false);

  // Lichte Weite: aussen 520 - 2 x 90 = 340 mm am Ende, 260 mm im Feld.
  const lw0 = AU.mastLichteWeite(m0, 'A');
  pruef('Lichte Weite am Jochende J90', lw0.licht, 0.34, 1e-9, 'm');
  wahr('P10 am Ende erfüllt', p(m0, 'P10A').ok === true, p(m0, 'P10A').status);
  const lw2 = AU.mastLichteWeite(mach('J90', 20, 2.0, 'HEB 260'), 'A');
  pruef('Im Feld verjüngt auf 260 mm', lw2.licht, 0.26, 1e-9, 'm');
  wahr('HEB 260 liegt dort an und besteht', lw2.ok === true);
  // HEM 240 mit Steg längs zum Gleis: 270 mm quer - zu breit für das Feld.
  const mQ = mach('J90', 20, 2.0, 'HEM 240', 'quer');
  pruef('HEM 240, Steg längs: 270 mm quer', AU.mastBreiteQuer(mQ, 'A'), 0.27, 1e-9, 'm');
  wahr('… und P10 meldet die Kollision mit den Gurten', p(mQ, 'P10A').ok === false,
       p(mQ, 'P10A').status);
  wahr('Am Ende passt derselbe Mast', p(mach('J90', 20, 0, 'HEM 240', 'quer'), 'P10A').ok === true);
  // J60 fiel bis zu seinen Blechen durch: der Ersatz legte am Ende auch
  // ein liegendes Blech.
  [8, 12, 16].forEach((L) => {
    const m = mach('J60', L, 0);
    wahr(`J60 / ${L} m: Mast am Jochende besteht P9`,
         p(m, 'P9A').ok === true && p(m, 'P9B').ok === true, p(m, 'P9A').status);
  });
}

titel('82  Nachweisbericht: jede Formel geht mit ihren Zahlen auf');
// Weisung vom 18. September: Druckbericht -> PDF, Hauptteil mit Anhang,
// Bilder ausschaltbar, Umfang einstellbar, zuerst das Tragjoch mit Masten.
// Der Bericht rechnet nicht - geprueft wird, dass die Formel, die er
// hinschreibt, mit den eingesetzten Werten die Zahl daneben ergibt.
{
  const NB = await import(J('export.nachweisbericht.js'));
  const CH = await import(J('core.checks.js'));
  const V = await import(J('core.vierendeel.js'));
  const C = await import(J('core.constants.js'));
  const w0 = { ...typUebernehmen({ ...standardwerte(), bearbeiten: false, typ: 'J90' },
                                  T.getTragjoch('J90')),
               L: 20, mastVorhanden: true,
               anbauteile: [{ ...A.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL Gleis 1' }] };
  const w = C.rechensatz(w0);
  const args = [w, getProfil(w.profOG), getProfil(w.profUG), getStahl(w.stahl), T.getTragjoch('J90')];
  const erg = berechne(...args);
  const kombi = V.vergleichKombinationen(...args);
  const checks = CH.konstruktionsChecks(erg.modell);
  const urteil = CH.urteilKonstruktion(checks, w.nachweise, 'joch');
  const bem = { ...kombi.huellkurve, anker: erg.anker };
  urteil.bauteile = CH.bauteilUrteil(bem, w.nachweise, 'joch');
  const d = { werte: w, erg: bem, kombi, checks, urteil, hinweise: CH.hinweise(erg.modell),
              fassung: 'Test', datum: '18.09.2026',
              bilder: { skizze: '<svg id="t-skizze"></svg>', verlaeufe: '<svg id="t-verl"></svg>',
                        eta: '<svg id="t-eta"></svg>', modell3d: 'data:image/png;base64,AAAA' } };
  const html = NB.nachweisbericht(d);

  ['2 Grundlagen', '3 System', '4 Einwirkungen', '5 Lastfälle', '6 Schnittgrössen',
   '7 Nachweise', '8 Konstruktionsprüfungen', '9 Nicht geführte', '10 Kräfte am Mastfuss',
   'Anhang'].forEach((k) => wahr(`Kapitel «${k}» steht da`, html.includes(k)));
  wahr('Kein «undefined», «NaN» oder «[object Object]» im Bericht',
       !/undefined|NaN|\[object Object\]/.test(html),
       (html.match(/.{30}(undefined|NaN|\[object Object\]).{30}/) ?? [''])[0]);
  wahr('Keine Anzeigeoption unter «womit gerechnet»', !/Blickwinkel|Projektion/.test(html));

  // --- Die Ketten gegen ihre eigenen Zahlen --------------------------------
  const m = erg.modell;
  const fyd = m.stahl.fy / m.gammaM0;
  const km = kombi.ergebnisse[kombi.massgebend];
  const e = km.max.eta.massgebendeEcke;
  pruef('Gurt: σ_N = |N| / A', Math.abs(e.N) * 10 / e.A, e.sig_N, 1e-6, 'N/mm²');
  pruef('Gurt: σ_My = M_y,lok / W_y', e.My_lokal * 1000 / e.Wy, e.sig_My, 1e-6, 'N/mm²');
  pruef('Gurt: σ_Mz = M_z,lok / W_z', e.Mz_lokal * 1000 / e.Wz, e.sig_Mz, 1e-6, 'N/mm²');
  pruef('Gurt: σ = Summe der Teile', e.sig_N + e.sig_My + e.sig_Mz, e.sig_v, 1e-6, 'N/mm²');
  pruef('Gurt: η = σ / f_yd', e.sig_v / fyd, e.eta, 1e-9, '');
  pruef('Gurt: N_My = M_y / (2h)', Math.abs(km.max.eta.My) / (2 * km.max.eta.h),
        Math.abs(e.N_My), 1e-6, 'kN');
  pruef('Die Kette steht auf dem η der Umhüllenden', e.eta, kombi.huellkurve.max.etaGesamt, 1e-9, '');
  const b = km.max.etaB;
  pruef('Blech: W = t·b²/6', b.tBB * b.hBB ** 2 / 6, b.W_Blech, 1e-6, 'mm³');
  pruef('Blech: σ = M / W', b.M_Blech * 1e6 / b.W_Blech, b.sig_B, 1e-6, 'N/mm²');
  pruef('Blech: τ = 1.5·V/(t·b)', 1.5 * b.V_Blech * 1000 / (b.tBB * b.hBB), b.tau_B, 1e-6, 'N/mm²');
  pruef('Blech: σ_v = √(σ² + 3τ²)', Math.sqrt(b.sig_B ** 2 + 3 * b.tau_B ** 2), b.sig_vB, 1e-6, 'N/mm²');
  pruef('Blech: η = σ_v / f_yd', b.sig_vB / fyd, b.etaB, 1e-9, '');
  const n = bem.mast.A, q = n.massgebend, s = n.stabil;
  pruef('Mast: σ_N = N / A', q.N * 10 / n.A, q.sigN, 1e-6, 'N/mm²');
  pruef('Mast: σ_längs = M_längs / W_längs', Math.abs(q.Mxx) * 1000 / n.Wl, q.sigL, 1e-6, 'N/mm²');
  pruef('Mast: σ = Summe der Teile', q.sigN + q.sigQ + q.sigL + q.sigW, q.sig, 1e-6, 'N/mm²');
  pruef('Mast: Gleichung (50) aus den gedruckten Werten',
        s.NEd / s.NKRd + s.omega * s.vy * s.MyEd / s.MyRd + s.omega * s.vz * s.MzEd / s.MzRd,
        s.eta50, 1e-9, '');
  pruef('Mast: 1/(1 − N_Ed/N_cr,y)', 1 / (1 - s.NEd / s.NcrY), s.vy, 1e-9, '');
  wahr('Die Zahl der Gurtkette steht im Bericht', html.includes(`<b>${NB.zahl(e.eta, 3)}</b>`));
  wahr('η(50) steht im Bericht', html.includes(`<b>${NB.zahl(s.eta50, 3)}</b>`));

  // --- Umfang und Bilder ---------------------------------------------------
  const nur = NB.nachweisbericht(d, { umfang: 'massgebend' });
  wahr('«Nur massgebend» hat keinen Anhang', !nur.includes('<h2>Anhang</h2>'));
  const voll = NB.nachweisbericht(d, { umfang: 'vollstaendig' });
  wahr('«Vollständig» schreibt die Stationen je Kombination aus', /A4 Stationen:/.test(voll));
  wahr('Alle Bilder stehen, wenn eingeschaltet',
       ['t-skizze', 't-verl', 't-eta', 'data:image/png'].every((k) => html.includes(k)));
  const ohne = NB.nachweisbericht(d, { bilder: { skizze: false, verlaeufe: false, eta: false, modell3d: false } });
  wahr('Kein Bild, wenn alle ausgeschaltet',
       !['t-skizze', 't-verl', 't-eta', 'data:image/png'].some((k) => ohne.includes(k)));
  const eins = NB.nachweisbericht(d, { bilder: { verlaeufe: false } });
  wahr('Jedes Bild einzeln abschaltbar', !eins.includes('t-verl') && eins.includes('t-skizze'));

  // --- Grenzen dieser Fassung ----------------------------------------------
  // Weisung vom 18. September: «den abfangjoch weglassen».
  let fehler = null;
  try { NB.nachweisbericht({ ...d, werte: { ...w, tragwerksart: 'abfangjoch' } }); }
  catch (x) { fehler = x.message; }
  wahr('Abfangjoch: der Bericht sagt, dass er es nicht enthält',
       /Einzelmast ab/.test(fehler ?? ''), fehler);
  wahr('Die Kapitel sind lückenlos nummeriert (Tragjoch)',
       [...html.matchAll(/<h2>(\d+) /g)].every((m2, i) => Number(m2[1]) === i + 1));
  wahr('Der Hinweis nennt den Mast als nachgewiesenes Bauteil',
       CH.hinweise(erg.modell).some((h) => /Auflager und Bauteil/.test(h))
       && !CH.hinweise(erg.modell).some((h) => /nachgewiesen wird nur das Joch/.test(h)));
  /*
   * Die Knick-Kontrollrechnung der Stuetze steht im Bericht (Weisung vom
   * 18. September: «die nachweise dieser auch übernehmen im
   * nachweisbericht») - und ihre Kette geht auf.
   */
  {
    const AN = await import(J('data.anker.js'));
    const kn = AN.ankerDbDa() ? AN.ankerKnicken('U12', 6) : null;
    if (kn) {
      const dk = { ...d, erg: { ...bem, anker: { A: {
        nachweis: { typ: 'U12', N: -10, zul: 50, L: 6, eta: 0.2, text: 'Druck' }, knick: kn } } } };
      const hk = NB.nachweisbericht(dk);
      const nb = Number(hk.match(/data-pruef="NbRd">([\d.]+)/)?.[1]);
      wahr('Bericht: die Knick-Kontrolle der Stuetze steht da', Number.isFinite(nb));
      pruef('… N_b,Rd = χ·N_pl/γ_M1 geht auf', nb, kn.chi * kn.Npl / kn.gammaM1, 0.06, 'kN');
      pruef('… N_cr = π²·E·I/L² geht auf', kn.Ncr,
            Math.PI ** 2 * kn.E * kn.I / (kn.L * 100) ** 2, 1e-9, 'kN');
    }
  }
}

titel('83  Einzelmast: kein Phantom-Ende B, Leiste und Bericht auf der Bemessung');
// Meldung vom 18. September: «die rechte sidebar beim einzelmast … schien
// nicht genau richtige werte wiederzuspiegeln». Die Leiste las einen
// Lastfall; der Kern rechnete dazu einen zweiten Masten B, den es nicht gibt.
{
  const NB = await import(J('export.nachweisbericht.js'));
  const CH = await import(J('core.checks.js'));
  const V = await import(J('core.vierendeel.js'));
  const C = await import(J('core.constants.js'));
  const joch = { ...typUebernehmen({ ...standardwerte(), bearbeiten: false, typ: 'J90' },
                                    T.getTragjoch('J90')), L: 20, mastVorhanden: true,
                 anbauteile: [] };
  let w0 = C.tragwerkWeg(C.tragwerkHinzu(joch, 'einzelmast',
    { mastProfil: 'HEB 260', mastLaenge: 8.5 }), 'T1');
  w0.anbauteile = [{ ...A.neuesAnbauteil('hs-nt-ausleger', 0), name: 'Ausleger',
                     ort: 'mastA', hMast: 6.5 }];
  const mit = (anker) => C.rechensatz(C.setzeMastAnker(w0, C.mastenVon(w0)[0].id, anker));
  const lauf = (w) => {
    const args = [w, getProfil(w.profOG), getProfil(w.profUG), getStahl(w.stahl),
                  T.getTragjoch(w.typ ?? 'J90')];
    return { erg: berechne(...args), kombi: V.vergleichKombinationen(...args) };
  };

  // Druckstuetze: das Phantom ohne Anker war massgebend (0.191 statt 0.129).
  const u12 = mit({ typ: 'U12', a: 4.5, h: 7.79, richtung: 'y', seite: 'plus',
                    befestigung: 'ankerplatte' });
  const r1 = lauf(u12);
  wahr('Einzelmast: kein Mastnachweis am Ende B', !r1.kombi.huellkurve.mast?.B && !r1.erg.mast?.B);
  const bt1 = CH.bauteilUrteil(r1.kombi.huellkurve, u12.nachweise, 'einzelmast');
  wahr('Das Urteil kennt nur Mast M1', bt1.liste.length === 1 && bt1.liste[0].name === 'Mast M1',
       bt1.liste.map((x) => x.name).join(', '));
  pruef('… mit dem η der Umhüllenden', bt1.eta,
        r1.kombi.huellkurve.mast.A.etaMitStabilitaet, 1e-12, '');

  // Seilanker auf der Gegenwindseite: der erste Fall ist nicht massgebend.
  const sa = mit({ typ: 'SA20', a: 4.5, h: 7.79, richtung: 'y', seite: 'minus',
                   befestigung: 'ankerplatte' });
  const r2 = lauf(sa);
  const hk = r2.kombi.huellkurve.mast.A;
  wahr('Die Umhüllende nennt ihre massgebende Kombination', typeof hk.fall === 'string', hk.fall);
  wahr('… und sie ist nicht der erste Nachweisfall',
       hk.etaMitStabilitaet > (r2.erg.mast.A.etaMitStabilitaet + 0.05),
       `${hk.etaMitStabilitaet.toFixed(3)} gegen ${r2.erg.mast.A.etaMitStabilitaet.toFixed(3)}`);

  const urteil = CH.urteilKonstruktion([], sa.nachweise, 'einzelmast');
  wahr('Beim Einzelmast fehlt kein Jochnachweis',
       !urteil.nichtGefuehrt.some((g) => /joch/i.test(g.key)),
       urteil.nichtGefuehrt.map((g) => g.key).join(', '));
  urteil.bauteile = CH.bauteilUrteil(r2.kombi.huellkurve, sa.nachweise, 'einzelmast');

  // --- Der Bericht des Einzelmasts ----------------------------------------
  const html = NB.nachweisbericht({ werte: sa, erg: { ...r2.kombi.huellkurve },
    kombi: r2.kombi, checks: [], urteil, hinweise: CH.hinweise(r2.erg.modell),
    fassung: 'Test', datum: '18.09.2026', bilder: {} });
  wahr('Einzelmast: der Bericht entsteht', html.includes('Statischer Nachweis'));
  wahr('… ohne Joch-Kapitel', !/Winkelgurte|Bindebleche|Konstruktionsprüfungen/.test(html));
  wahr('… mit dem Mast und Gleichung (50)',
       html.includes('§') === false && html.includes('Stabilität nach SIA 263')
       && html.includes(`<b>${NB.zahl(hk.stabil.eta50, 3)}</b>`));
  wahr('… lückenlos nummeriert', [...html.matchAll(/<h2>(\d+) /g)]
    .every((m2, i) => Number(m2[1]) === i + 1));
  wahr('… massgebend ist die Kombination der Umhüllenden',
       html.includes(r2.kombi.lastfaelle.find((l) => l.key === hk.fall).bez));
  wahr('Kein «undefined», «NaN» oder «[object Object]»',
       !/undefined|NaN|\[object Object\]/.test(html),
       (html.match(/.{30}(undefined|NaN|\[object Object\]).{30}/) ?? [''])[0]);

  /*
   * >>> STAENDIG (TRAGWERK) + ABLENKKRAEFTE = GANZES G, OHNE DOPPELTES. <<<
   *
   * Befund vom 18. September am neuen Auflagerreiter: beim Einzelmast waren
   * beide Faelle gleich, beim Joch stand das Masteigengewicht in beiden.
   * Geprueft an beiden Arten, mit Bogen (Ablenkkraft ungleich null).
   */
  const fussVon = (w, key) => {
    const args = [w, getProfil(w.profOG), getProfil(w.profUG), getStahl(w.stahl),
                  T.getTragjoch(w.typ ?? 'J90')];
    return V.vergleichKombinationen(...args).ergebnisse[key]?.mast?.A?.stationen?.[0];
  };
  const nurG = (w) => {
    const args = [{ ...w, beiwerteFest: { G: 1, WindX: 0, WindY: 0, Schnee: 0,
                                          HavarieX: 0, HavarieY: 0 } },
                  getProfil(w.profOG), getProfil(w.profUG), getStahl(w.stahl),
                  T.getTragjoch(w.typ ?? 'J90')];
    return berechne(...args).mast?.A?.stationen?.[0];
  };
  const mitBogen = (w) => C.rechensatz({ ...w, trasseRadius: 600 });
  const faelle = [['Einzelmast', mitBogen(w0)],
    ['Tragjoch', mitBogen({ ...joch,
      anbauteile: [{ ...A.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL' }] })]];
  faelle.forEach(([name, w]) => {
    const gk = fussVon(w, 'gk'), ab = fussVon(w, 'ablk'), g = nurG(w);
    ['Fz', 'Fx', 'Myy', 'Mxx'].forEach((k) => {
      pruef(`${name}: ${k} aus Tragwerk + Ablenkung = ganzes G`,
            (gk?.[k] ?? 0) + (ab?.[k] ?? 0), g?.[k] ?? 0, 1e-6, '');
    });
    wahr(`${name}: das Masteigengewicht steht nicht bei den Ablenkkräften`,
         Math.abs(ab?.Fz ?? 0) < Math.abs(gk?.Fz ?? 0) * 0.1,
         `ablk Fz ${ab?.Fz?.toFixed(2)} gegen gk ${gk?.Fz?.toFixed(2)}`);
  });
}

titel('84  Joch weg, Masten bleiben; nichts unter der Fundamentkote');
// Weisung vom 18. September: «es sollte möglich sein ein joch zu löschen und
// zwei einzelmasten zu haben die auf der identischen höhe ausgelegt sind.
// eine last unterhalb der fundamentkote sollte nicht möglich sein … wenn ich
// aus einem jochtragwerk einen einzelmasten mache, dann bleiben alle
// anbauteile bestehen, diese sollten gelöscht werden mit dem joch.»
{
  const C = await import(J('core.constants.js'));
  const AU = await import(J('core.auflager.js'));
  const CH = await import(J('core.checks.js'));
  const V = await import(J('core.vierendeel.js'));
  let w = { ...typUebernehmen({ ...standardwerte(), bearbeiten: false, typ: 'J90' },
                               T.getTragjoch('J90')), L: 20, mastVorhanden: true,
            anbauteile: [{ ...A.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL am Joch' }] };
  const [m1, m2] = C.mastenVon(w);
  w = C.setzeAnbauteileAn(w, [...w.anbauteile,
    { ...A.neuesAnbauteil('hs-nt-ausleger', 0), name: 'Ausleger M2', ort: 'mastB', hMast: 6.5 }]);
  w = C.setzeMastAnker(w, m1.id, { typ: 'U12', a: 4.5, h: 7.79, richtung: 'y', seite: 'plus',
                                   befestigung: 'ankerplatte' });
  const laengeVon = (m, t, ende) => ((Number(m.laenge) || 0) > 0 ? Number(m.laenge)
    : AU.mastLaengeVorgabe((Number(ende === 'B' ? (t.mastHB ?? t.mastH) : t.mastH) || 0)
                           - (Number(m.fuss) || 0), t.jd));
  const sollL = laengeVon(m1, C.tragwerkeVon(w)[0], 'A');
  const neu = C.jochZuEinzelmasten(w, C.tragwerkeVon(w)[0].id, laengeVon);
  const tw = C.tragwerkeVon(neu);
  wahr('Aus dem Joch werden zwei Einzelmasten',
       tw.length === 2 && tw.every((t) => C.tragwerksart(t).key === 'einzelmast'),
       tw.map((t) => C.tragwerksart(t).key).join(', '));
  const masten = C.mastenVon(neu);
  wahr('… an den beiden Maststellen', masten.map((m) => m.x).sort((a, b) => a - b).join() === '0,20',
       masten.map((m) => m.x).join());
  wahr('… mit derselben Länge wie am Joch',
       masten.every((m) => Math.abs(m.laenge - sollL) < 1e-9), `${masten.map((m) => m.laenge)} / ${sollL}`);
  wahr('… und demselben Profil', masten.every((m) => m.profil === m1.profil));
  wahr('Der Anker bleibt an seinem Masten',
       masten.find((m) => Math.abs(m.x - m1.x) < 1e-9)?.anker?.typ === 'U12');
  const alleTeile = tw.flatMap((t) => C.anbauteileFuer(neu, t));
  wahr('Das Teil am Joch geht mit dem Joch', !alleTeile.some((a) => a.name === 'FL am Joch'),
       alleTeile.map((a) => a.name).join(', '));
  wahr('Das Teil am Masten bleibt am Masten', alleTeile.some((a) => a.name === 'Ausleger M2'));
  const e1 = C.jochZuEinzelmasten(neu, tw[0].id, laengeVon);
  wahr('Ein Einzelmast ist kein Joch - dort ändert sich nichts', e1 === neu);

  // --- Nichts unter der Fundamentkote ------------------------------------
  const nt = { ...A.neuesAnbauteil('hs-nt-ausleger', 0), ort: 'mastA', hMast: 0 };
  pruef('Der NT-Ausleger hängt 2.70 m unter seine Befestigung', A.haengeTiefe(nt), 2.7, 1e-9, 'm');
  wahr('Am Joch zählt keine Tiefe', A.haengeTiefe({ ...nt, ort: 'joch' }) === 0);
  let em = C.tragwerkWeg(C.tragwerkHinzu(w, 'einzelmast', { mastProfil: 'HEB 240' }),
                         C.tragwerkeVon(w)[0].id);
  em = { ...em, anbauteile: [{ ...A.neuesAnbauteil('hs-fahrdraht', 10), name: 'Altlast' },
                             { ...nt, name: 'Tief' }] };
  const rs = C.rechensatz(em);
  const m = V.modellEinzelmast
    ? V.modellEinzelmast(rs, getStahl(rs.stahl))
    : berechne(rs, getProfil(rs.profOG), getProfil(rs.profUG), getStahl(rs.stahl), T.getTragjoch('J90')).modell;
  wahr('Ein Teil am Joch hängt beim Einzelmast nicht mehr am Masten',
       !(m.anbauMastFlach ?? []).some((t) => /Altlast/.test(t.name)));
  const h = CH.hinweise(m);
  wahr('… und der Hinweis sagt, dass es nicht gerechnet wird',
       h.some((x) => /stehen noch am Joch/.test(x) && /NICHT gerechnet/.test(x)), h.join(' | '));
  // Weisung vom 18. September: «die darstellung der farben im 3d des
  // einzelmasten gleich gestalten wie beim mast beim tragjoch.» Ein zweiter,
  // grauer Mast B lag ueber dem gefaerbten.
  {
    const R3 = await import(J('render.3d.js'));
    const e3 = berechne(rs, getProfil(rs.profOG), getProfil(rs.profUG), getStahl(rs.stahl),
                        T.getTragjoch(rs.typ ?? 'J90'));
    const f3 = R3.erzeugeSzene(e3.modell, e3).flaechen.filter((x) => x.gruppe === 'mast');
    wahr('3D-Einzelmast: nur ein Mast, kein grauer Mast B darüber',
         !f3.some((x) => /_B$/.test(x.teil ?? '')), [...new Set(f3.map((x) => x.teil))].join(' '));
    wahr('… und er trägt seine Ausnutzung wie am Joch',
         f3.filter((x) => x.teil === 'MAST_A' && x.werte?.eta !== undefined).length > 10);
    // «hier ist das gelenkig eh falsch, da einzelmast» (18. September).
    const mk3 = R3.erzeugeSzene(e3.modell, e3).marken;
    wahr('3D-Einzelmast: keine Lagerangabe des Jochs am Fuss',
         !mk3.some((x) => x.art === 'auflagertext' || x.art === 'auflager'),
         mk3.filter((x) => x.gruppe === 'auflager').map((x) => (x.zeilen ?? [x.text]).join('/')).join(' | '));
  }
  wahr('Eine Last unter der Fundamentkote wird gemeldet',
       h.some((x) => /Tief: Last UNTER der Fundamentkote \(z = −?-?2\.70/.test(x)), h.join(' | '));
}


titel('85  Teile am Masten folgen der Stelle, nicht der Laufnummer');
/*
 * Gesehen am 18. September im Browser: Joch P1, Einzelmast P2 bei x 10 mit
 * Traverse, dann ein zweites Joch rechts und P1 entfernt. Die Laufnummern
 * wurden neu vergeben, und die Traverse hing danach am geteilten Masten bei
 * x 20 - P2 ohne Teile, das Joch mit einer fremden Last.
 */
{
  const C = await import(J('core.constants.js'));
  let w = { ...typUebernehmen({ ...standardwerte(), bearbeiten: false, typ: 'J90' },
                              T.getTragjoch('J90')),
            L: 20, xLage: 0, mastVorhanden: true, anbauteile: [] };
  w = C.tragwerkHinzu(w, 'einzelmast', { xLage: 10 });
  const idEm = w.twId;
  w = C.setzeAnbauteileAn(w, [{ ...A.neuesAnbauteil('leiter-traverse', 0),
                                name: 'Trav', ort: 'mastA', hMast: 8 }]);
  const bei = (x) => C.mastenVon(w).find((m) => Math.abs(m.x - x) < 0.01);
  w = C.setzeMastAngabe(w, bei(10).id, 'mastProfil', 'HEB 260');
  w = C.tragwerkHinzu(w, 'joch', { xLage: 20 });
  w = C.tauscheAktives(w, 'T1');
  w = C.jochZuEinzelmasten(w, 'T1', () => 8.5);
  const teileVon = (t) => C.anbauteileFuer(w, t).filter((a) => /^mast/.test(a.ort ?? ''))
    .map((a) => a.name);
  const alle = C.tragwerkeVon(w);
  const em = alle.find((t) => t.id === idEm);
  wahr('Die Traverse bleibt am Einzelmast bei x 10', teileVon(em).includes('Trav'),
       alle.map((t) => `${t.id}:${teileVon(t).join('+')}`).join(' '));
  wahr('… und haengt an keinem anderen Tragwerk',
       alle.filter((t) => t.id !== idEm).every((t) => !teileVon(t).includes('Trav')));
  wahr('Das Profil bleibt ebenfalls an seiner Stelle', bei(10).profil === 'HEB 260');
  // Neu geschrieben stehen Liste und Teile auf denselben Nummern.
  const fest = C.mastenFest(w);
  wahr('Nach dem Festschreiben zeigt mastId auf den Masten bei x 10',
       fest.mastAnbauteile.every((a) => fest.masten.find((m) => m.id === a.mastId)?.x === 10));
}

titel('86  Die Windlast des Masten folgt der Windklasse');
/*
 * Gemeldet am 18. September: «die lastwerte beim ändern der ek bleiben
 * beim masten gleich angezeigt». Die Mastliste hielt w_Mast der Windklasse
 * fest, unter der sie zuletzt geschrieben wurde.
 */
{
  const C = await import(J('core.constants.js'));
  const MW = MA_SORT.mastWind;
  let w = { ...typUebernehmen({ ...standardwerte(), bearbeiten: false, typ: 'J90' },
                              T.getTragjoch('J90')),
            L: 20, mastVorhanden: true, anbauteile: [], windKlasse: '0.9' };
  const nachfuehren = (x) => ({ ...x, wMast: MW(x.mastProfil ?? 'HEB 240', x.windKlasse === '1.3' ? 'EK3' : 'EK1', x.mastSteg ?? 'jochachse') });
  w = nachfuehren(w);
  w = C.setzeMastAngabe(w, C.mastenVon(w)[0].id, 'mastProfil', 'HEB 240');
  const ek1 = C.rechensatz(w).wMast;
  w = nachfuehren({ ...w, windKlasse: '1.3' });
  const ek3 = C.rechensatz(w).wMast;
  wahr('w_Mast wechselt mit der Windklasse', ek3 > ek1 + 1e-6, `${ek1} → ${ek3}`);
  pruef('… auf den Tabellenwert von EK3', ek3, MW('HEB 240', 'EK3', 'jochachse'), 1e-9, 'kN/m');
  // Von Hand freigegeben gilt der gespeicherte Wert.
  let h = C.setzeMastAngabe({ ...w, lastenBearbeiten: true }, C.mastenVon(w)[0].id, 'wMast', 0.77);
  pruef('Von Hand gesetzt bleibt w_Mast stehen', C.rechensatz(h).wMast, 0.77, 1e-12, 'kN/m');
}

titel('87  Einzelmast: Gleis in der Stegskizze, ein x-Feld, plastisch in der Nachweisleiste');
// Weisungen vom 18. September.
{
  const OS = await import(J('doku.optionsskizzen.js'));
  const em = { tragwerksart: 'einzelmast' };
  const g1 = OS.optionsSkizze('mastSteg', 'jochachse', em);
  const g2 = OS.optionsSkizze('mastSteg', 'quer', em);
  wahr('Stegskizze am Einzelmast zeigt das Gleis', /Gleis</.test(g1) && /Gleis</.test(g2));
  wahr('… und unterscheidet die beiden Stellungen', g1 !== g2);
  /*
   * >>> UND AM JOCH DIESELBE (Weisung vom 20. September). <<<
   * «diese darstellung auch für die restlichen tragwerksarten verwenden.»
   * Hier stand «am Joch bleibt das Joch die Orientierung» - die
   * Joch-Draufsicht ist abgeloest, das Gleis gilt überall.
   */
  ['joch', 'abfangjoch', 'tragausleger'].forEach((art) => {
    wahr(`Auch am ${art} zeigt die Stegskizze das Gleis`,
         /Gleis</.test(OS.optionsSkizze('mastSteg', 'jochachse', { tragwerksart: art })));
  });
  wahr('… und es ist wirklich dieselbe Skizze wie am Einzelmast',
       OS.optionsSkizze('mastSteg', 'jochachse', { tragwerksart: 'joch' }) === g1);
  const C = await import(J('core.constants.js'));
  const joch = { ...typUebernehmen({ ...standardwerte(), bearbeiten: false, typ: 'J90' },
                                    T.getTragjoch('J90')), L: 20, mastVorhanden: true, anbauteile: [] };
  const wE = C.tragwerkWeg(C.tragwerkHinzu(joch, 'einzelmast', { xLage: 5 }), 'T1');
  const fX = FELDER.find((f) => f.key === 'mastX');
  wahr('Das Feld «Stelle des Masten» fehlt am Einzelmast (x₀ genuegt)', !fX.sichtbar(wE));
  wahr('… und steht am Joch', fX.sichtbar(joch) === true);
  wahr('«Mast plastisch» steht nicht mehr im System',
       FELDER.find((f) => f.key === 'mastPlastisch').versteckt === true);
}

titel('89  Tragausleger: nicht nachgewiesen, bis ein Kragarm-Modell steht');
// Entscheid vom 18. September: Warnung statt Sperre.
{
  const CH = await import(J('core.checks.js'));
  const u = CH.urteilKonstruktion([], {}, 'tragausleger');
  wahr('Tragausleger: kein Tragwerksurteil', u.tragwerkGefuehrt === false
       && u.nichtNachgewiesen === 'Tragausleger');
  wahr('… und er steht zuoberst unter «nicht geführt»', u.nichtGefuehrt[0]?.key === 'tragausleger');
  const z = CH.urteilFusszeile({ gut: true, eta: 0.4, urteil: u });
  wahr('Die Fussleiste sagt «NICHT nachgewiesen», nicht «erfüllt»',
       /NICHT nachgewiesen/.test(z) && !/erfüllt/.test(z), z);
  wahr('Das Tragjoch bleibt unberuehrt',
       CH.urteilKonstruktion([], { jochtragwerk: true }, 'joch').nichtNachgewiesen === null);
}

titel('90  mitBauteilen: ein Ergebnis mit Abfangjoch, Mast und Anker');
// Durchsicht vom 18. September, Punkt A2: sechs Stellen legten die Bauteile
// von Hand hinueber; dreimal fehlte eines.
{
  const CH = await import(J('core.checks.js'));
  const huelle = { max: { eta: 0.5 }, mast: { A: { eta: 0.3 } } };
  const erg = { mast: { A: { eta: 0.9 } }, anker: { A: { nachweis: { eta: 0.2 } } } };
  const t = CH.mitBauteilen(huelle, erg);
  wahr('Der Anker kommt aus dem Bemessungsdurchgang', t.anker === erg.anker);
  wahr('Am Tragjoch bleibt der Mast der Huellkurve', t.mast === huelle.mast);
  wahr('Die Huellkurve selbst bleibt unberuehrt', huelle.anker === undefined);
  const ab = { ...erg, abfang: { auflager: { A: {} } } };
  const a = CH.mitBauteilen(huelle, ab);
  wahr('Am Abfangjoch: Abfangnachweis und Mast aus dem Durchgang',
       a.abfang === ab.abfang && a.mast === ab.mast);
  wahr('Fehlt der Huellkurve der Mast, ersatzweise der des Durchgangs (nur auf Wunsch)',
       CH.mitBauteilen({ max: {} }, erg, { mastErsatz: true }).mast === erg.mast
       && CH.mitBauteilen({ max: {} }, erg).mast === undefined);
  // Keine Handuebertragung mehr in app.js und ui.js.
  const quelle = APP_QUELLE()
    + readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
  wahr('Keine Stelle legt Anker oder Abfangjoch mehr von Hand dazu',
       !/anker: (letzte\.)?erg\??\.anker|anzeige\.(abfang|anker|mast) =/.test(quelle));
}

titel('91  app.*.js: jede Funktion bekommt das Kontextobjekt');
/*
 * Seit dem 19. September ist app.js geteilt (Durchsicht, Punkt A1). Die
 * Funktionen der Module nehmen «app» als ersten Parameter. Beim Schnitt der
 * Optionen stand danach «onclick = dialogOptionen» - der Browser reichte
 * das Klickereignis als «app» hinein, und der Dialog brach ab. Jede
 * Erwaehnung einer solchen Funktion in app.js muss sie mit «(app» rufen
 * (oder ist ein Schluessel des Kontextobjekts).
 */
{
  const ohneKommentar = (t) => t.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/\/\/[^\n]*/g, ' ');
  const app91 = ohneKommentar(readFileSync(join(HIER, 'js', 'app.js'), 'utf8'))
    .split('\n').filter((l) => !/^import |^\s+[\w$, ]+\} from '/.test(l)).join('\n');
  const faelle = [];
  readdirSync(join(HIER, 'js')).filter((f) => /^app\..+\.js$/.test(f)).forEach((f) => {
    const t = readFileSync(join(HIER, 'js', f), 'utf8');
    for (const m of t.matchAll(/^export (?:async )?function ([\w$]+)\(app\b/gm)) {
      const n = m[1];
      // Nicht in Anfuehrungszeichen: «key === 'kontextMast'» ist kein Aufruf.
      for (const s of app91.matchAll(new RegExp(String.raw`(?<![\w$.'"])` + n + String.raw`\b(?!['"])`, 'g'))) {
        const danach = app91.slice(s.index + n.length, s.index + n.length + 5);
        if (danach.startsWith('(app') || /^\s*:/.test(danach)) continue;
        faelle.push(`${f}: ${n}`);
      }
    }
  });
  wahr('Keine Funktion eines app.*.js wird ohne «app» gerufen oder uebergeben',
       faelle.length === 0, faelle.join(', '));
}

titel('92  Erklaertexte abschaltbar (U4)');
// Entscheid vom 19. September: Schalter in den Optionen, Vorgabe ein.
{
  const f92 = FELDER.find((f) => f.key === 'erklaertexte');
  wahr('Der Schalter «Erklaertexte» steht in den Optionen, Vorgabe ein',
       f92?.optionenDialog === true && f92.typ === 'schalter' && f92.standard === true);
  const css92 = readFileSync(join(HIER, 'css', 'style.css'), 'utf8');
  wahr('… die Stilregel blendet nur die Erklaertexte der Seitenleisten aus',
       css92.includes('body.ohne-erklaertexte .panel .feld > small.hinweis')
       && !css92.includes('body.ohne-erklaertexte .feld-notiz'));
  wahr('… und app.js setzt die Klasse', APP_QUELLE().includes("toggle('ohne-erklaertexte'"));
}

titel('88  Seitenleiste: die Knick-Kachel der Druckstuetze');
/*
 * Gemeldet am 18. September: «das einfügen einer druckstütze / anker ist
 * nicht möglich beim einzelmast». Der Grund lag nicht am Einzelmast: beim
 * Herausloesen von `bauteilKacheln` hiess die Kachelliste `k`, und die
 * Knick-Kachel ueberdeckte sie mit `const k = e.knick`. Jede Stuetze unter
 * Druck brach die Seitenleiste mit «k.push is not a function» ab.
 */
{
  const U = await import(J('ui.js'));
  const erg = {
    modell: { federn: { namen: { A: 'M1' } } },
    anker: { A: {
      nachweis: { typ: 'U12', N: -20, eta: 0.4, grund: null, lieferbar: true },
      knick: { NbRd: 120, lambda: 1.1, chi: 0.5, I: 100, Ncr: 300, nichtEnthalten: '' },
    } },
  };
  let kacheln = null, fehler = null;
  try { kacheln = U.bauteilKacheln(erg, { nachweise: {} }, () => 'ok'); }
  catch (e) { fehler = e.message; }
  wahr('Eine Stuetze unter Druck bricht die Kacheln nicht ab', fehler === null, fehler);
  wahr('… und ihre Knick-Kachel steht da',
       (kacheln ?? []).some((x) => /Knicken Stütze M1/.test(x)), String(kacheln?.length));
}
titel('72  Oertlicher Anteil: vorzeichenrichtig gemessen, additiv belassen');
/* ===========================================================================
 * Weisung vom 17. September: «örtlicher anteil umsetzen», nur im Weg
 * «vorzeichenrichtig», Drehsinn am Stabmodell bestimmt.
 *
 * GEMESSEN (kalibrieren.mjs --nur oertlich, 72 Stellen, J90 bis J130):
 * die vorzeichenrichtigen Wege liegen im Mittel naeher am FEM, aber an
 * 10 bzw. 20 Stellen UNTER ihm (bis 0.47). Additiv bleibt ueberall sicher
 * (Minimum 1.03), ueberschaetzt neben der Einleitung aber bis Faktor 19.
 * Deshalb bleibt OERTLICH_WEG auf 'additiv' - bis zum Entscheid.
 * ========================================================================= */
{
  const QS72 = await import(J('core.querschnitt.js'));
  wahr('Die Vorgabe bleibt additiv', QS72.OERTLICH_WEG === 'additiv');
  wahr('Die Messwege stehen bereit',
       ['additiv', 'fest', 'fest-', 'mit', 'gegen'].every((w) => QS72.OERTLICH_WEGE.includes(w)));
  const e72 = { ...standardwerte(), typ: 'J90', L: 14, mastVorhanden: false,
    torsionModell: 'verteilt',
    anbauteile: [teil({ id: 'S', x: 5.18, raster: 0.4, befestigung: 'durchgehend',
      lasten: [block({ einwirkung: 'WindY', x: 0, z: -1.5, Fy: 3 })] })] };
  const r72 = (o) => berechne({ ...e72, ...o,
    beiwerteFest: { G: 0, WindX: 0, WindY: 1, Schnee: 0 } },
    getProfil(e72.profOG), getProfil(e72.profUG), getStahl(e72.stahl), T.getTragjoch('J90'));
  const hk = r72({ ebenenUeberlagerung: 'huellkurve', oertlichWeg: 'fest' });
  const hk0 = r72({ ebenenUeberlagerung: 'huellkurve' });
  pruef('In der Huellkurve wirkt der Weg nicht', hk.max.etaGesamt, hk0.max.etaGesamt, 1e-12, '–');
  const vz0 = r72({ ebenenUeberlagerung: 'vorzeichen' });
  const vzF = r72({ ebenenUeberlagerung: 'vorzeichen', oertlichWeg: 'fest' });
  const ho = (r) => r.knoten.map((k) => k.ebenen.find((e) => e.id === 'H_O')?.V_Ebene ?? 0);
  wahr('Vorzeichenrichtig veraendert er die Ebenen neben der Einleitung',
       ho(vz0).some((v, i) => Math.abs(v - ho(vzF)[i]) > 1e-6));
  wahr('Das Kraeftepaar traegt seine Ebene und sein Vorzeichen',
       vz0.modell.lokal.filter((l) => l.torsion).every((l) => ['H_O', 'H_U', 'V_L', 'V_R'].includes(l.ebeneId))
       && vz0.modell.lokal.some((l) => l.torsion && l.dF < 0));
  const mess = JSON.parse(readFileSync(join(HIER, 'kalibrierung_oertlich.json'), 'utf8'));
  /*
   * DIE ABMINDERUNG (Weisung vom 17. September: «abminderung soweit wie
   * sinnvoll um so nahe wie möglich an die fem berechnung zu kommen»).
   */
  wahr('Einseitig: der Faktor ist die gemessene Grenze',
       QS72.OERTLICH_FAKTOR.einseitig === mess.kWahl['vorzeichen|oben'].k
       && QS72.OERTLICH_FAKTOR.einseitig === mess.kWahl['huellkurve|oben'].k,
       `${QS72.OERTLICH_FAKTOR.einseitig} / gemessen ${mess.kWahl['vorzeichen|oben'].k}`);
  wahr('Durchgehend: der Faktor liegt nicht unter der gemessenen Grenze',
       QS72.OERTLICH_FAKTOR.durchgehend >= mess.kWahl['vorzeichen|durchgehend'].k
       && QS72.OERTLICH_FAKTOR.durchgehend >= mess.kWahl['huellkurve|durchgehend'].k,
       `${QS72.OERTLICH_FAKTOR.durchgehend} / gemessen ${mess.kWahl['vorzeichen|durchgehend'].k}`);
  wahr('… und an keiner Messstelle liegt das Werkzeug damit unter dem Stabmodell',
       mess.kWahl['vorzeichen|alle'].min >= 1 && mess.kWahl['huellkurve|alle'].min >= 1);
  const add = mess.bewertung.find((b) => b.weg === 'additiv');
  wahr('Die Messung belegt: additiv ist ueberall auf der sicheren Seite',
       add.min >= 1 && mess.bewertung.filter((b) => b.weg !== 'additiv' && b.weg !== 'mit')
         .every((b) => b.min < 0.95),
       mess.bewertung.map((b) => `${b.weg} ${b.min.toFixed(2)}`).join(' · '));
}

titel('93  COM-Ausleitung: was die Bruecke liest, steht in der Datei');
/*
 * Weisung vom 19. September: «checke die com schnittstelle». Geprueft wird
 * die Datei, die `com/AxisVM_aufbauen.ps1` liest - AxisVM wird dafuer nicht
 * gestartet. Befunde der Pruefung, alle auf der unsicheren Seite:
 *  - die App gab `app.werte` roh weiter: am Einzelmast fehlten Anker und
 *    Teile am Masten (2 Knoten statt 83), am Joch der Seilanker;
 *  - die Einzelmast-Ausleitung baute weder Anker noch Teile am Masten;
 *  - in der Jochreihe fehlten die Streckenlasten (Wind, Schnee auf dem Joch,
 *    Mastwind), die steifen Gurtabschnitte zeigten auf einen Querschnitt
 *    ohne Praefix, und der geteilte Mast stand zweimal im Modell.
 */
{
  const V93 = await import(J('core.vierendeel.js'));
  const C93 = await import(J('core.constants.js'));
  const AX93 = await import(J('export.axisvm.js'));
  const ps1 = readFileSync(join(HIER, 'com', 'AxisVM_aufbauen.ps1'), 'utf8');
  const modellVon = (s) => V93.modell({ ...s, beiwerteFest: null }, getProfil(s.profOG),
    getProfil(s.profUG), getStahl(s.stahl), T.getTragjoch(s.typ));
  const jsonVon = (w, o) => AX93.stabmodellJson(modellVon(w),
    { ...o, eingabe: w, bau: AX93.blattWennMehrere(w, { modellVon }, o) });
  const joch = (x = {}) => Object.assign(
    typUebernehmen({ ...standardwerte(), typ: 'J90', bearbeiten: false }, T.getTragjoch('J90')),
    { L: 20, xLage: 0, mastVorhanden: true,
      anbauteile: [{ ...A.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL' }] }, x);
  const o = { knotenmodell: 'anschnitt', auflagerModell: 'mast' };

  // Was die Bruecke erwartet - aus ihrem Quelltext, nicht aus dem Gedaechtnis.
  wahr('Die Bruecke liest das Format «tragjoch-stabmodell»',
       ps1.includes("'tragjoch-stabmodell'"));
  wahr('… und die Listen knoten, staebe, querschnitte, auflager, lasten.*',
       ['$d.knoten', '$d.staebe', '$d.querschnitte', '$d.auflager',
        '$d.lasten.punkt', '$d.lasten.strecke'].every((t) => ps1.includes(t)));

  /** Querverweise einer Datei: jeder Name zeigt auf etwas, das da ist. */
  const fehler = (d) => {
    const f = [];
    const kn = new Set(d.knoten.map((k) => k.name));
    const qs = new Set(d.querschnitte.map((q) => q.name));
    const st = new Set(d.staebe.map((s) => s.name));
    const lf = new Set(d.lastfaelle.map((l) => l.key));
    if (d.format !== 'tragjoch-stabmodell') f.push('Format');
    if (!(d.merkmale ?? []).includes('anbau-kette')) f.push('Merkmal anbau-kette');
    d.staebe.forEach((s) => {
      if (!kn.has(s.von) || !kn.has(s.bis)) f.push(`Stab ${s.name}: Knoten`);
      if (!qs.has(s.querschnitt)) f.push(`Stab ${s.name}: Querschnitt ${s.querschnitt}`);
    });
    d.auflager.forEach((a) => { if (!kn.has(a.knoten)) f.push(`Auflager ${a.knoten}`); });
    ['punkt', 'moment', 'strecke'].forEach((art) => (d.lasten[art] ?? []).forEach((l) => {
      if (!lf.has(l.lastfall)) f.push(`Last: Lastfall ${l.lastfall}`);
      if (art === 'strecke' ? !st.has(l.stab) : !kn.has(l.knoten)) f.push(`Last ${art}: Ort`);
      if (!Number.isFinite(l.wert)) f.push(`Last ${art}: Wert`);
    }));
    d.knoten.forEach((k) => { if (![k.x, k.y, k.z].every(Number.isFinite)) f.push(`Knoten ${k.name}`); });
    (d.kombinationen ?? []).forEach((kb) => (kb.anteile ?? []).forEach((a) => {
      if (!lf.has(a.lastfall)) f.push(`Kombination ${kb.bez}`);
    }));
    const dop = (a) => a.length !== new Set(a).size;
    if (dop(d.knoten.map((k) => k.name))) f.push('doppelte Knotennamen');
    if (dop(d.staebe.map((s) => s.name))) f.push('doppelte Stabnamen');
    return [...new Set(f)];
  };

  const dJ = jsonVon(joch(), o);
  wahr('Joch mit Masten: Datei stimmig', fehler(dJ).length === 0, fehler(dJ).slice(0, 4).join(' | '));

  let em = C93.tragwerkWeg(C93.tragwerkHinzu(joch(), 'einzelmast',
    { mastProfil: 'HEB 260', mastLaenge: 10 }), 'T1');
  em = C93.setzeMastAnker(em, C93.mastenVon(em)[0].id, { typ: 'U12', a: 4.5, h: 7.79,
    richtung: 'y', seite: 'plus', befestigung: 'ankerplatte' });
  const dE = jsonVon(C93.rechensatz(em), o);
  wahr('Einzelmast mit Anker: Datei stimmig', fehler(dE).length === 0, fehler(dE).slice(0, 4).join(' | '));
  wahr('… mit Anker (zweites Auflager) und den Teilen am Masten',
       dE.auflager.length === 2 && dE.staebe.length > 20, `${dE.auflager.length} Auflager, ${dE.staebe.length} Staebe`);

  const dR = jsonVon(C93.tragwerkHinzu(joch(), 'joch', { L: 15, xLage: 20 }), o);
  wahr('Jochreihe: Datei stimmig', fehler(dR).length === 0, fehler(dR).slice(0, 4).join(' | '));
  wahr('… mit Streckenlasten auf den Jochen und am geteilten Masten',
       dR.lasten.strecke.some((l) => /^T\d+_/.test(l.stab))
       && dR.lasten.strecke.some((l) => /^MAST_M2_S/.test(l.stab)));

  // Zwei Joche auf verschiedener Hoehe am selben Masten: EIN Zug, lueckenlos.
  let wH = joch({ mastH: 8, mastLaenge: 8.5 });
  wH = C93.tragwerkHinzu(wH, 'joch', { L: 15, xLage: 20, mastH: 8.5, mastLaenge: 9.0 });
  const dH = jsonVon(wH, o);
  const zug = dH.staebe.filter((s) => /^MAST_M2_S\d+$/.test(s.name));
  const zH = (n) => dH.knoten.find((k) => k.name === n).z;
  wahr('Verschiedene Anschlusshoehen: Datei stimmig', fehler(dH).length === 0,
       fehler(dH).slice(0, 4).join(' | '));
  wahr('… der geteilte Mast ist ein lueckenloser Zug durch beide Anschluesse',
       zug.every((s, i) => i === 0 || s.von === zug[i - 1].bis)
       && zug.every((s) => zH(s.bis) > zH(s.von))
       && zug.some((s) => s.bis.includes('k0_')) && zug.some((s) => s.bis.includes('k500_')),
       zug.map((s) => s.bis).join(' → '));
  wahr('… und jeder Abschnitt traegt seinen Mastwind',
       zug.every((s) => dH.lasten.strecke.some((l) => l.stab === s.name)));

  const quelle93 = readFileSync(join(HIER, 'js', 'app.axisvm.js'), 'utf8');
  wahr('Die App leitet den Rechensatz aus, nicht die rohen Werte',
       quelle93.includes('const satz = rechensatz(app.werte);')
       && !/exportiere\w*\(app\.werte/.test(quelle93));

  /* =====================================================================
   * >>> LASTEN UEBER DER MASTSPITZE - KOMMT DIE BRUECKE DAMIT ZURECHT?
   * ===================================================================
   * Weisung vom 20. September: «lasten oberhalb mastspitze zulassen», dazu
   * «falls com schnittstelle betroffen ist, diese auch nachfuehren».
   *
   * GEMESSEN, NICHT BEHAUPTET: die Ausleitung schreibt den Aufsatz als
   * gewoehnlichen STARREN Stab (`MASTAUFSATZ_...`, art 'starr'). Die
   * Bruecke liest die Art aus dem Feld `art` (Funktion StabArt) und macht
   * daraus einen Starrkoerper - sie braucht dafuer keinen neuen Namen zu
   * kennen. Genau das haelt diese Kontrolle fest; ein kuenftiger Stab mit
   * einer Art, die die Bruecke NICHT kennt, faellt hier auf.
   *
   * Der Ruckfall ueber den Querschnittsnamen ('STARR') gilt nur alten
   * Dateien - auf ihn darf sich ein neuer Stab nicht verlassen.
   * =================================================================== */
  {
    let wU = C93.tragwerkWeg(C93.tragwerkHinzu(joch(), 'einzelmast',
      { mastProfil: 'HEB 260', mastLaenge: 8.5 }), 'T1');
    wU = C93.setzeAnbauteileAn(wU, [
      { ...A.neuesAnbauteil('leiter-traverse', 0), ort: 'mastA', hMast: 9.6 },
      { ...A.neuesAnbauteil('mast-nt-ausleger', 0), ort: 'mastA', hMast: 7.0 }]);
    const dU = jsonVon(C93.rechensatz(wU), o);
    wahr('Teil ueber der Mastspitze: Datei stimmig', fehler(dU).length === 0,
         fehler(dU).slice(0, 4).join(' | '));
    const auf = dU.staebe.filter((x) => /(^|_)MASTAUFSATZ_/.test(x.name));
    pruef('… und der Aufsatz steht darin', auf.length, 1, 1e-12, 'Stk');
    /*
     * DIE BRUECKE VERZWEIGT AUF GENAU DREI ARTEN. Steht in der Datei eine
     * vierte, legt sie den Stab als gewoehnlichen Stab an - mit dem
     * Ersatzquerschnitt 500x500 mm und dessen Eigengewicht. Das ist der
     * Fehler, der am 20. September das Blattmodell 33 t schwer machte.
     */
    const arten = [...new Set(dU.staebe.map((x) => x.art ?? 'stab'))];
    wahr('Jede Stabart der Datei ist eine, die die Bruecke kennt',
         arten.every((a) => ['stab', 'starr', 'link'].includes(a))
         && ps1.includes("$art -eq 'starr'") && ps1.includes("$art -eq 'link'"),
         arten.join(' '));
    wahr('… und die Bruecke liest sie aus dem Feld, nicht aus dem Namen',
         /function StabArt\(\$sb\) \{\s*\r?\n\s*if \(\$sb\.art\)/.test(ps1));
  }
}

titel('94  Befunde aus der Bedienung vom 19. September');
/*
 * Fuenf Weisungen, im Wortlaut:
 *  «Bei anzahl keine negativ eingabe ermöglichen»
 *  «Bei den modalen dafür sorgen das es nicht schliesst wenn man mit der maus
 *   den klick loslässt und nicht innerhalb des modals ist»
 *  «Raster (befestigung an joch) nicht zuverlässig beim automatischem setzen
 *   neben den knotenbereichen, die zahl wird immer grösser.»
 *  «Wenn leiter koordinate x und z wert haben, dann extrudiert der arm auf
 *   den z wert.»
 *  «Bei der eingabe der bauteile ein dubplizieren mit rechtsklick oder button
 *   ermöglichen.»
 */
{
  const U94 = await import(J('ui.js'));
  const A94 = await import(J('core.anbauteile.js'));
  wahr('Anzahl: negativ wird null, halbe Stueck werden gerundet',
       U94.anzahlZulaessig(-3) === 0 && U94.anzahlZulaessig(2.4) === 2
       && U94.anzahlZulaessig('x') === 0 && U94.anzahlZulaessig(4) === 4);
  const q94 = (d) => readFileSync(join(HIER, 'js', d), 'utf8');
  const ui94 = q94('ui.js'), app94 = q94('app.js');
  wahr('… beide Anzahlfelder (Karte, Vorlage) tragen min="0" und werden begrenzt',
       ui94.includes(`feld === 'anzahl' ? ' min="0"' : ''`)
       && /data-vk="anzahl"[^>]*\n\s*min="0"/.test(ui94)
       && app94.includes("if (inp.dataset.vk === 'anzahl') wert = ui.anzahlZulaessig(wert);"));

  wahr('Dialog schliesst nur, wenn Druecken UND Loslassen auf dem Schleier liegen',
       app94.includes('scrim.onpointerdown = (e) => { aufSchleierGedrueckt = e.target === scrim; };')
       && app94.includes('const zuMachen = aufSchleierGedrueckt && e.target === scrim;'));

  // Raster: dasselbe Teil, fuenfmal an dieselbe Stelle neben einem Blech.
  const m94 = { L: 10, stationsListe: [{ x: 5, vertikal: { breite: 100 } }] };
  let teil = { raster: 0.4 };
  const folge = [];
  for (let k = 0; k < 5; k++) {
    const an = A94.passeTraegerAn(5.2, A94.rasterNormVon(teil), m94);
    teil = { ...A94.rasterGesetzt(teil, an), x: an.x };
    folge.push(teil.raster);
  }
  wahr('Raster: wiederholtes Setzen neben dem Knoten waechst nicht',
       folge.every((r) => r === folge[0]) && folge[0] > 0.4 && teil.rasterNorm === 0.4,
       folge.join(' / '));
  const frei = A94.passeTraegerAn(3, A94.rasterNormVon(teil), m94);
  const zurueck = A94.rasterGesetzt(teil, frei);
  wahr('… und faellt an freier Stelle aufs Normalmass zurueck',
       zurueck.raster === 0.4 && zurueck.rasterNorm === undefined);
  // Der gemeldete Fall: Blechteilung 0.80 m, das Teil wandert von Lage zu
  // Lage. Vom letzten Raster aus gerechnet wuchs es auf 2.52 m.
  const mR = { L: 12, stationsListe: [0.3, 1.1, 1.9, 2.7, 3.5, 4.3, 5.1, 5.9, 6.7, 7.5]
    .map((x) => ({ x, vertikal: { breite: 120 } })) };
  let altR = 0.4, neuMax = 0, teilR = { raster: 0.4 };
  for (let k = 0; k < 40; k++) {
    const x = Math.round((1 + ((k * 0.37) % 6)) * 10) / 10;
    const a1 = A94.passeTraegerAn(x, altR, mR);
    if (a1.geweitet) altR = a1.raster;
    const a2 = A94.passeTraegerAn(x, A94.rasterNormVon(teilR), mR);
    teilR = A94.rasterGesetzt(teilR, a2);
    neuMax = Math.max(neuMax, teilR.raster);
  }
  wahr('… 40 Lagen hintereinander: das Raster bleibt unter Normalmass + 0.40 m',
       neuMax <= 0.8 + 1e-9 && altR > 2, `neu hoechstens ${neuMax} m, vorher ${altR} m`);

  // Kette: Leiter aussen UND hoeher als die Traverse.
  const kette = (teile, zAn) => A94.anbauKette(teile, { x0: 5, zAn }).glieder
    .map((g) => [g.von.x, g.von.z, g.bis.x, g.bis.z]);
  const k1 = kette([{ rolle: 'traeger', x: 5, stationX: 5, z: 1 },
                    { rolle: 'aufbau', x: 5, stationX: 5, z: 2 },
                    { rolle: 'drahtwerk', x: 6, stationX: 5, z: 2.3 }], 0.2);
  /* =======================================================================
   * >>> ZUERST z, DANN y, DANN x (Weisung vom 20. September). <<<
   * =======================================================================
   *
   * «bei den koordinaten der anbauteile, zuerst die z komponente afahren.»
   *
   * Hier stand die umgekehrte Folge vom 19. September: «der Jochaufsatz
   * endet an der Traverse, nicht auf Leiterhoehe» - der Weg lief erst
   * waagrecht bis unter den Leiter und dann senkrecht zu ihm.
   *
   * >>> WAS DAVON BLEIBT UND WAS NICHT. <<<
   * Der BEFUND vom 19. September bleibt behoben: gestreckt wird weiterhin
   * nur ein TRAEGER (`streckbar` in core.anbauteile.js). Der Jochaufsatz
   * ist nach wie vor 1.0 m lang und nicht 1.3 - was hier senkrecht bis auf
   * Leiterhoehe laeuft, ist das Glied DES LEITERS, nicht der verlaengerte
   * Aufsatz. Im BILD sieht beides gleich aus; das ist der Preis der neuen
   * Folge und dem Auftraggeber gemeldet.
   * ===================================================================== */
  wahr('Kette am Joch: zuerst z, dann y, dann x',
       JSON.stringify(k1) === JSON.stringify([[5, 0.2, 5, 1.2], [5, 1.2, 5, 2.2],
                                              [5, 2.2, 5, 2.5], [5, 2.5, 6, 2.5]]),
       JSON.stringify(k1));
  wahr('… und der Traeger selbst wird nicht laenger',
       Math.abs(k1[1][3] - 2.2) < 1e-9, `Aufsatz endet auf ${k1[1][3]}`);
  const k2 = kette([{ rolle: 'traeger', x: 5, stationX: 5, z: -1.35 },
                    { rolle: 'aufbau', x: 6.25, stationX: 5, z: -2.7 },
                    { rolle: 'drahtwerk', x: 7.5, stationX: 5, z: -2.7 }], -0.2);
  wahr('… der NT-Ausleger bleibt: Stuetze bis zum Ausleger, dann waagrecht',
       JSON.stringify(k2) === JSON.stringify([[5, -0.2, 5, -1.55], [5, -1.55, 5, -2.9],
                                              [5, -2.9, 6.25, -2.9], [6.25, -2.9, 7.5, -2.9]]),
       JSON.stringify(k2));

  const K94 = await import(J('app.kontext.js'));
  const liste94 = [{ id: 'AT-a', name: 'Test', ort: 'joch', x: 9.8, module: [], lasten: [] }];
  let gesetzt = null;
  const app94x = { werte: { L: 10, anbauteile: liste94 }, letzte: null,
                   setzeAnbauteile: (l) => { gesetzt = l; }, meldeImBalken: () => {} };
  K94.anbauteilDuplizieren(app94x, 0);
  wahr('Duplizieren: Kopie steht daneben, am Jochende nach innen, mit neuer Kennung',
       gesetzt?.length === 2 && Math.abs(gesetzt[1].x - 9.3) < 1e-9
       && gesetzt[1].id !== 'AT-a' && gesetzt[1].module !== liste94[0].module);
  wahr('… Knopf in der Karte, Rechtsklick auf die Zeile, Eintrag im Kontextmenue',
       ui94.includes('data-at-dup="${i}"') && ui94.includes('beiAnbauKontext?.(')
       && q94('app.kontext.js').includes("text: 'Duplizieren', tun: () => anbauteilDuplizieren(app, i)"));

  // «hier die mastbezeichnungen a b weglassen» · «die weissen schwereachsen
  // bei den inaktiven elementen grau machen wie die körper»
  const r94 = q94('render.3d.js');
  const aufl = r94.slice(r94.indexOf("if (mk.art === 'auflager') {"),
                         r94.indexOf("if (mk.art === 'auflagertext') return;"));
  wahr('3D: unter dem Mastfuss steht kein A/B mehr', aufl.length > 0 && !aufl.includes('fillText'));
  // «die bennenung hier gelenkig und k weglassen» (19. September)
  wahr('3D: auch «gelenkig · κ» steht nicht mehr unter dem Fuss',
       r94.includes("if (mk.art === 'auflagertext') return;"));
  wahr('3D: Achsen am passiven Tragwerk grau wie seine Koerper',
       (r94.match(/l\.passiv \? \(t\.xdim \?\? t\.dim\)/g) ?? []).length === 2);
}

titel('95  Anbauteile und Ebenen: Befunde vom 19. September (zweiter Teil)');
/*
 * Im Wortlaut:
 *  «Anbauteile müssen einzeln gelöscht werden es wäre gut wenn man einen
 *   button hätte für refresh»
 *  «Bei anbauteilen die koordinaten so steuern dass der y wert zuerst
 *   abgefahren wird falls eingegeben vor dem x. das bauteil wird nicht
 *   richtig dargestellt wenn x und y engegeben -> fläche anstatt stäbe.»
 *  «Nach dem abspeichern eines bauteils wir dieser nicht sofort in die liste
 *   aufgenommen sonder man muss hin und herschalten in der sidebar»
 *  «Die layersteuerung beim einzelmasten checken, insbesondere beim Modell»
 */
{
  const A95 = await import(J('core.anbauteile.js'));
  const U95 = await import(J('ui.js'));
  const R95 = await import(J('render.3d.js'));
  const q95 = (d) => readFileSync(join(HIER, 'js', d), 'utf8');
  const kette = (teile, zAn) => A95.anbauKette(teile, { x0: 5, zAn }).glieder
    .map((g) => [g.von.x, g.von.y, g.von.z, g.bis.x, g.bis.y, g.bis.z]);
  const waagSchraeg = (gl) => gl.some((g) => Math.abs(g[3] - g[0]) > 1e-9
                                         && Math.abs(g[4] - g[1]) > 1e-9);
  const k1 = kette([{ rolle: 'traeger', x: 5, stationX: 5, z: -1.35 },
                    { rolle: 'drahtwerk', x: 6, y: 0.5, stationX: 5, z: -2.7 }], -0.2);
  wahr('Kette: an der Stuetze erst y, dann x - kein Glied schraeg in x und y',
       !waagSchraeg(k1) && JSON.stringify(k1.slice(-2))
         === JSON.stringify([[5, 0, -2.9, 5, 0.5, -2.9], [5, 0.5, -2.9, 6, 0.5, -2.9]]),
       JSON.stringify(k1));
  const k2 = kette([{ rolle: 'traeger', x: 5, stationX: 5, z: 1 },
                    { rolle: 'aufbau', x: 5, stationX: 5, z: 2 },
                    { rolle: 'drahtwerk', x: 6, y: 0.5, stationX: 5, z: 2.3 }], 0.2);
  /*
   * >>> SEIT DEM 20. SEPTEMBER: z, y, x. <<<
   * Weisung: «bei den koordinaten der anbauteile, zuerst die z komponente
   * afahren.» Hier stand die umgekehrte Folge. Was BLEIBT, ist der Grund
   * dieses Abschnitts: kein Glied schraeg in x und y zugleich.
   */
  wahr('… an der Traverse: z, dann y, dann x zum Leiter',
       !waagSchraeg(k2) && JSON.stringify(k2.slice(-3)) === JSON.stringify([
         [5, 0, 2.2, 5, 0, 2.5], [5, 0, 2.5, 5, 0.5, 2.5], [5, 0.5, 2.5, 6, 0.5, 2.5]]),
       JSON.stringify(k2));
  const k3 = kette([{ rolle: 'drahtwerk', x: 6, y: 0.5, stationX: 5, z: -0.35 }], -0.2);
  wahr('… ein Leiter allein am Joch: ebenfalls erst y', !waagSchraeg(k3), JSON.stringify(k3));
  const r95 = q95('render.3d.js');
  wahr('3D: ein schraeges Glied ist ein Stab um seine Achse, keine Platte',
       /achsen > 1 \? schraegerStab\(p0, p1, dk, dk, o3\)/.test(r95));

  const vl = (ev) => U95.maskenSignatur({ anbauteile: [], eigeneVorlagen: ev }, 'anbau');
  wahr('Eine gespeicherte Vorlage baut die Maske neu (Signatur)',
       vl([]) !== vl([{ id: 'EV-1', name: 'Neu' }]));

  const ui95 = q95('ui.js'), app95 = q95('app.js');
  wahr('Knopf «Alle entfernen» mit Rueckfrage, getrennt nach Joch und Masten',
       ui95.includes('data-at-alle-weg') && app95.includes('function anbauteileAlleEntfernen()')
       && app95.includes('<button class="btn" data-joch>Nur die am Joch</button>'));

  wahr('Einzelmast: keine Systemachse ohne Joch',
       /if \(m\.L > 0\) \{\s*linien\.push\(\{ gruppe: 'achse', stark: true/.test(r95));
  wahr('… die Schwerachse des Masten folgt auch dem Schalter «Schwerachsen»',
       r95.includes("if (!this.sparsam && l.schwerachse && l.gruppe === 'mast'")
       && r95.includes("&& !this._ebeneAn('achse')) return;"));
  const fake = { szene: { flaechen: [{ gruppe: 'mast' }, { gruppe: 'anbau' }],
                          linien: [{ gruppe: 'mast', schwerachse: true }],
                          marken: [], vektoren: [{ gruppe: 'last' }], masse: [] } };
  const da = R95.Modellansicht.prototype.ebenenVorhanden.call(fake);
  wahr('… Schalter ohne Inhalt werden ausgegraut (Profil, Bleche, Auflager, Masse)',
       ['mast', 'anbau', 'achse', 'raster'].every((k) => da.has(k))
       && ['profil', 'blech', 'auflager', 'masse'].every((k) => !da.has(k))
       && q95('app.layout.js').includes('app.ansicht.ebenenVorhanden()'),
       [...da].join(', '));
}

titel('96  Tragwerksliste: Baum mit Lageband, Namen nach dem Typ');
/*
 * Weisung vom 19. September: «A mit dem Band warum braucht man die p und m
 * bennenung bei den masten, mach die bennenung entsprechend dem typ T A M MT»
 */
{
  const C96 = await import(J('core.constants.js'));
  const U96 = await import(J('ui.js'));
  let w = { ...standardwerte(), tragwerksart: 'joch', typ: 'J90', L: 20, xLage: 20,
            mastH: 7.5, jd: 500, mastProfil: 'HEB 240', mastVorhanden: true, twId: 'T1' };
  w = C96.tragwerkHinzu(w, 'einzelmast', { xLage: 0, mastProfil: 'HEB 240', mastLaenge: 8.5 });
  w = C96.tragwerkHinzu(w, 'abfangjoch', { xLage: 20, L: 12.5 });
  w = C96.tragwerkHinzu(w, 'tragausleger', { xLage: 60 });
  const namen = C96.tragwerkeSortiert(w).map((t) => C96.tragwerkPos(w, t));
  wahr('Je Typ gezaehlt: M (Einzelmast), T, A, MT', ['M1', 'T1', 'A1', 'MT1']
       .every((n) => namen.includes(n)), namen.join(', '));
  const em = C96.tragwerkeSortiert(w).find((t) => C96.tragwerksart(t).key === 'einzelmast');
  wahr('Der Einzelmast heisst wie sein Mast',
       C96.tragwerkPos(w, em) === C96.mastName(w, C96.mastenFuer(w, em)[0]));
  const mt = C96.tragwerkeSortiert(w).find((t) => C96.tragwerksart(t).key === 'tragausleger');
  wahr('Der Mast des Tragauslegers heisst MT1, nicht M…',
       C96.mastName(w, C96.mastenFuer(w, mt)[0]) === 'MT1');
  const mNamen = C96.mastenVon(w).map((m) => C96.mastName(w, m));
  wahr('Die M-Zaehlung laeuft ohne Luecke ueber Einzel- und Jochmasten',
       mNamen.filter((n) => /^M\d/.test(n)).every((n, i) => n === `M${i + 1}`),
       mNamen.join(', '));
  const h = U96.querprofilLeisteHtml(w);
  wahr('Kein P-Kuerzel mehr in der Leiste', !/>P\d/.test(h));
  wahr('Ein Lageband, darunter der Baum',
       h.indexOf('class="qp-band') >= 0 && h.indexOf('class="qp-band') < h.indexOf('qp-baum'));
  wahr('Der geteilte Mast bei 20 m steht einmal im Baum, mit «auch A1»',
       h.includes('>auch A1<'));
  wahr('Im Band liegen Tragjoch und Abfangjoch in zwei Bahnen',
       (h.match(/qp-bandlinie/g) ?? []).length === 2
       && new Set([...h.matchAll(/qp-bandlinie[^"]*"[\s\S]*?top:(\d+)px/g)].map((m) => m[1])).size === 2);
  wahr('Der Tragausleger traegt «nicht nachgewiesen» in seiner Zeile',
       h.includes('>nicht nachgewiesen<'));
}

titel('97  Teile am Masten: Weg und Skizze (Ansicht x-z, Draufsicht x-y)');
/*
 * Weisung vom 19. September: «prüfe diese darstellung auf deren richtigkeit»
 * und «mach eine ansicht in xz und eine draufsicht in xy».
 */
{
  const A97 = await import(J('core.anbauteile.js'));
  const U97 = await import(J('ui.js'));
  const kette = (teile) => A97.anbauKette(teile, { x0: 0, zAn: 0, amMast: true }).glieder
    .map((g) => [g.von.x, g.von.y, g.von.z, g.bis.x, g.bis.y, g.bis.z]);
  const k = kette([{ rolle: 'drahtwerk', x: 1, y: 0.5, stationX: 0, z: -0.6 }]);
  /*
   * >>> AM MASTEN EBENSO: z, y, x (Weisung vom 20. September). <<<
   *
   * Hier stand «erst waagrecht auf der Anschlusshoehe» - mit der
   * Begruendung, ein Starrstab auf der Mastachse versteife den Masten
   * zwischen h und h + z. Er tut es nicht: die Kette haengt an EINEM
   * Wurzelknoten, und ihr erster Punkt ist ein freier Kettenknoten, mit
   * keinem zweiten Mastknoten verbunden.
   */
  wahr('Am Masten: zuerst lotrecht, dann y, dann x',
       JSON.stringify(k) === JSON.stringify([[0, 0, 0, 0, 0, -0.6], [0, 0, -0.6, 0, 0.5, -0.6],
                                             [0, 0.5, -0.6, 1, 0.5, -0.6]]), JSON.stringify(k));
  /* =======================================================================
   * >>> … SOFERN NICHTS ANDERES EINGEGEBEN WURDE (24. September). <<<
   * =======================================================================
   *
   * Weisung: «bei den koordinaten eingabe in den anbauteilen, die
   * reihenfolge beachten, jenachdem welcher wert zuerst eingegeben wird,
   * wird dieser auch abgefahren. dies sollte dann global in der app
   * gelten.»
   *
   * z, y, x ist damit nur noch die VORGABE - sie gilt, wo nichts
   * mitgeschrieben ist (alter Stand, nie gesetztes Feld). Die Kontrolle
   * darueber misst genau diesen Fall; hier steht der andere.
   * ===================================================================== */
  {
    const ziel = (folge) => A97.anbauKette(
      [{ rolle: 'drahtwerk', x: 1, y: 0.5, stationX: 0, z: -0.6, folge }],
      { x0: 0, zAn: 0, amMast: true }).glieder
      .map((g) => [g.bis.x, g.bis.y, g.bis.z]);
    wahr('Zuerst x eingegeben: der Weg faengt in x an',
         JSON.stringify(ziel('xyz')) === JSON.stringify(
           [[1, 0, 0], [1, 0.5, 0], [1, 0.5, -0.6]]), JSON.stringify(ziel('xyz')));
    wahr('Zuerst y eingegeben: der Weg faengt in y an',
         JSON.stringify(ziel('yxz')) === JSON.stringify(
           [[0, 0.5, 0], [1, 0.5, 0], [1, 0.5, -0.6]]), JSON.stringify(ziel('yxz')));
    wahr('Nur x gesetzt: danach gilt wieder die Vorgabe z, y',
         JSON.stringify(ziel('x')) === JSON.stringify(
           [[1, 0, 0], [1, 0, -0.6], [1, 0.5, -0.6]]), JSON.stringify(ziel('x')));
    wahr('Ohne Folge bleibt alles, wie es war',
         JSON.stringify(ziel(undefined)) === JSON.stringify(ziel('zyx')));
    /*
     * DIE FOLGE ENTSTEHT BEIM TIPPEN - und nur beim ERSTEN Mal. Wer eine
     * schon gesetzte Koordinate nachjustiert, soll den Weg nicht umlegen;
     * wer sie auf null stellt, nimmt die Achse wieder heraus.
     */
    let f = '';
    f = A97.achsfolge(f, 'z', 1.5); f = A97.achsfolge(f, 'x', 1.0);
    f = A97.achsfolge(f, 'y', 0.5);
    pruef('achsfolge: drei Eingaben, drei Achsen', f.length, 3, 1e-12, 'Stk');
    wahr('… in der Reihenfolge der Eingabe', f === 'zxy', f);
    wahr('… Nachjustieren legt den Weg nicht um',
         A97.achsfolge(f, 'z', 2.0) === 'zxy', A97.achsfolge(f, 'z', 2.0));
    wahr('… auf null gestellt faellt die Achse heraus',
         A97.achsfolge(f, 'x', 0) === 'zy', A97.achsfolge(f, 'x', 0));
    wahr('… und ein fremdes Feld laesst sie stehen',
         A97.achsfolge(f, 'anzahl', 3) === 'zxy');
    // Was nicht eingegeben wurde, folgt in der Vorgabe z, y, x.
    wahr('achsenFolge fuellt den Rest in der Vorgabe auf',
         JSON.stringify(A97.achsenFolge('x')) === JSON.stringify(['x', 'z', 'y'])
         && JSON.stringify(A97.achsenFolge('')) === JSON.stringify(['z', 'y', 'x']),
         JSON.stringify(A97.achsenFolge('x')));
    /*
     * >>> GLOBAL IN DER APP. <<< Die Weisung sagt es ausdruecklich, und es
     * ist keine zweite Stelle noetig: Bild, Ausleitung und Rechenkern
     * holen ihre Kette alle aus `anbauKette`. Gemessen wird hier, dass die
     * Folge den ganzen Weg bis in die AxisVM-Datei ueberlebt.
     */
    const ui97 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Die Maske schreibt die Folge beim Tippen fort',
         ui97.includes('achsfolge(m[mod].folge, feld, wert)'));
    const da97 = readFileSync(join(HIER, 'js', 'data.anbauteile.js'), 'utf8');
    wahr('… und sie reist mit dem flachen Teil mit',
         da97.includes('...(m.folge ? { folge: m.folge } : {})'));
  }
  const k0 = kette([{ rolle: 'drahtwerk', x: 0, y: 0, stationX: 0, z: -0.6 }]);
  wahr('… ohne Ausladung genau ein lotrechtes Glied', k0.length === 1
       && k0[0][3] === 0 && k0[0][5] === -0.6, JSON.stringify(k0));
  const q97 = (d) => readFileSync(join(HIER, 'js', d), 'utf8');
  wahr('Modell, 3D und Karte bilden die Mastkette gleich (amMast)',
       q97('export.axisvm.js').includes('{ x0: 0, zAn: 0, amMast: true }')
       && q97('render.3d.js').includes('{ x0: 0, zAn: 0, amMast: true }')
       && q97('ui.js').includes('amMast: amMast(a) }'));

  const w97 = { ...standardwerte(), tragwerksart: 'joch', typ: 'J90', L: 20, xLage: 0,
                mastH: 7.5, jd: 500, mastProfil: 'HEB 240', mastVorhanden: true };
  const svg = U97.anbauteilSkizzeFuer({ name: 'RL', ort: 'mastA', hMast: 7.2,
    module: [{ bauteil: 'x', x: 0, y: 0, z: -0.6 }], lasten: [] }, w97);
  wahr('Skizze: Ansicht x-z und Draufsicht x-y', svg.includes('Ansicht x–z')
       && svg.includes('Draufsicht x–y'));
  wahr('… nennt den Masten beim Namen, nicht «Mast A»', svg.includes('· M1<') && !svg.includes('Mast A'));
  wahr('… ohne x kein Arm (kein x-Mass)', !svg.includes('data-zu="x"'));
  wahr('… die Mastlaenge steht da, auch wenn sie nur die Vorgabe ist', /L \d+\.\d\d m/.test(svg));
  const svgX = U97.anbauteilSkizzeFuer({ name: 'T', ort: 'mastB', hMast: 7,
    module: [{ bauteil: 'x', x: 1, y: 0.5, z: 0.35 }], lasten: [] }, w97);
  wahr('… mit x und y: beide Masse, F_x und F_y in der Draufsicht',
       (svgX.match(/data-zu="x"/g) ?? []).length >= 2 && svgX.includes('data-zu="y"')
       && (svgX.match(/data-zu="Fy"/g) ?? []).length === 2);
  wahr('Der Erklaertext sagt «x global», nicht mehr «ins Feld»',
       !q97('ui.js').includes('weist dabei ins Feld'));
}

titel('98  Geteilter Mast: Jochkraefte der Nachbarn (Sofortmassnahme)');
/*
 * Gemessen am 19. September: am geteilten HEB 240 einer Reihe J90/20 +
 * J90/20 fehlte die Jochkraft der Nachbarseite (Laengsmoment 59.3 statt
 * 104.4 kNm, Biegespannung 182 statt 319 N/mm²). Weisung: «ja
 * sofortmassnahme zuerst». Havarie oertlich: der Nachbar nur staendig.
 */
{
  const C98 = await import(J('core.constants.js'));
  const N98 = await import(J('core.nachbarn.js'));
  const V98 = await import(J('core.vierendeel.js'));
  const M98 = await import(J('core.mast.js'));
  const A98 = await import(J('data.anbauteile.js'));
  let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
  w.L = 20; w.xLage = 0; w.mastVorhanden = true;
  w.anbauteile = [{ ...A98.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL 1' }];
  w = C98.tragwerkHinzu(w, 'joch', { L: 20, xLage: 20 });
  w = C98.setzeAnbauteileAn(w, [{ ...A98.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL 2' }]);
  const [t1, t2] = C98.tragwerkeSortiert(w);
  const satz = (t, mit) => (mit ? N98.rechensatzMitNachbarn : C98.rechensatz)(C98.tauscheAktives(w, t.id));
  const hk = (s) => V98.vergleichKombinationen(s, ...N98.kernArgumente(s)).huellkurve.mast;
  const etaVon = (m, e) => m[e].etaNachweis ?? m[e].eta;
  const alt1 = hk(satz(t1, false)), neu1 = hk(satz(t1, true)), neu2 = hk(satz(t2, true));
  wahr('Der geteilte Mast (T1 Ende B) wird ungünstiger', etaVon(neu1, 'B') > etaVon(alt1, 'B') * 1.5,
       `${etaVon(alt1, 'B').toFixed(3)} -> ${etaVon(neu1, 'B').toFixed(3)}`);
  wahr('… und hat von beiden Seiten dieselbe Ausnutzung',
       Math.abs(etaVon(neu1, 'B') - etaVon(neu2, 'A')) < 1e-9,
       `${etaVon(neu1, 'B').toFixed(3)} / ${etaVon(neu2, 'A').toFixed(3)}`);
  wahr('Der Aussenmast bleibt unverändert', Math.abs(etaVon(neu1, 'A') - etaVon(alt1, 'A')) < 1e-9);

  // Das gemessene Laengsmoment am Fuss: 104.4 kNm bei Wind +y.
  const s1 = satz(t1, true);
  const e = V98.berechne({ ...s1, lastfall: 'windYp' }, ...N98.kernArgumente(s1));
  const fuss = M98.mastSchnitt(e.modell, 'B').stationen.find((st) => Math.abs(st.z) < 1e-9);
  wahr('Längsmoment am Fuss wie gemessen (104.4 kNm)', Math.abs(Math.abs(fuss.Mxx) - 104.4) < 0.1,
       `${fuss.Mxx.toFixed(1)} kNm`);
  const lasten = M98.mastLasten(e.modell, 'B').lasten;
  wahr('Die Nachbarkraft steht mit Namen in der Lastliste',
       lasten.some((l) => l.art === 'nachbarjoch' && l.nachbar === C98.tragwerkPos(w, t2)));

  // Havarie oertlich: im Havariefall rechnet der Nachbar ohne Havarie-Beiwerte.
  const q98 = readFileSync(join(HIER, 'js', 'core.nachbarn.js'), 'utf8');
  wahr('Havarie örtlich: der Nachbar ohne Havarie-Beiwerte',
       q98.includes('HavarieX: 0, HavarieY: 0') && q98.includes('const fest = havarie || !ziel.key;'));
  // Ohne geteilten Mast bleibt alles wie es war.
  const einzel = N98.rechensatzMitNachbarn(typUebernehmen({ ...standardwerte(), typ: 'J90' },
    T.getTragjoch('J90')));
  wahr('Ein einzelnes Joch bekommt keine Nachbarn', einzel.nachbarJochlasten === undefined);
  const CH98 = await import(J('core.checks.js'));
  const hin = CH98.hinweise(e.modell).map((x) => (typeof x === 'string' ? x : x?.text ?? '')).join(' ');
  wahr('Der Hinweis nennt den Nachbarn und die fehlende Rahmenwirkung',
       hin.includes('Jochkräfte von T2') && hin.includes('Rahmenwirkung'));
}

titel('99  Anbauteile am Einzelmast: alle Eingabewege');
/*
 * Weisung vom 19. September: «checke die eingabe der anbauteile am
 * einzelmasten über all die verschiedene möglichkeiten. insobesondere über
 * den button im 3d fenster.» Knopf, Kontextmenue, Kachel ziehen und
 * Vorwahl laufen alle ueber `stelleAus`.
 */
{
  const C99 = await import(J('core.constants.js'));
  const N99 = await import(J('core.nachbarn.js'));
  const V99 = await import(J('core.vierendeel.js'));
  const AU99 = await import(J('core.auflager.js'));
  const SZ99 = await import(J('app.setzen.js'));
  const U99 = await import(J('ui.js'));
  const K99 = await import(J('app.kontext.js'));
  const basis = () => {
    const w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
    w.L = 20; w.xLage = 0; w.mastVorhanden = true; w.anbauteile = [];
    return w;
  };
  // Einzelmast ohne eingetragene Laenge - so, wie «+ Tragwerk» ihn anlegt.
  const wE = C99.tragwerkWeg(C99.tragwerkHinzu(basis(), 'einzelmast', { xLage: 5 }), 'T1');
  const sE = C99.rechensatz(wE);
  const eE = V99.berechne(sE, ...N99.kernArgumente(sE));
  const lang = AU99.einzelmastLaenge(sE);
  const tE = C99.tragwerkeVon(wE)[0];
  const appE = { letzte: { erg: eE }, werte: wE, hebungVon: () => lang + (Number(sE.mastFuss) || 0) };
  const klick = (app, x, z) => SZ99.stelleAus(app, { x, y: 0, z });
  const kopf = klick(appE, C99.lageVon(tE), lang - 0.3);
  wahr('Einzelmast: ein Klick knapp unter dem Kopf trifft den Masten, nicht ein «Joch»',
       kopf?.ort === 'mastA' && Math.abs(kopf.hMast - (lang - 0.3)) < 0.03, JSON.stringify(kopf));
  wahr('… auch genau auf dem Kopf', klick(appE, C99.lageVon(tE), lang)?.ort === 'mastA');
  wahr('… weit darueber nichts', klick(appE, C99.lageVon(tE), lang + 0.6) === null);
  wahr('… und unten am Masten wie bisher', klick(appE, C99.lageVon(tE), 2)?.hMast === 2);

  // Gegenprobe am Joch: Jochachse -> Joch, Mast darunter -> Mast.
  const wJ = basis();
  const sJ = C99.rechensatz(wJ);
  const eJ = V99.berechne(sJ, ...N99.kernArgumente(sJ));
  const appJ = { letzte: { erg: eJ }, werte: wJ, hebungVon: () => Number(sJ.mastH) || 0 };
  const H = Number(sJ.mastH);
  wahr('Joch: die Jochachse trifft weiter das Joch', klick(appJ, 10, H)?.ort === 'joch');
  wahr('… der Mast darunter den Masten', klick(appJ, 0, H - 3)?.ort === 'mastA');

  wahr('Der Hoehenregler reicht am Einzelmast bis zum Kopf (nicht bis zur Anschlusshoehe)',
       Math.abs(U99.mastKopfHoehe(sE, 'A') - lang) < 1e-9 && lang > (Number(sE.mastH) || 0),
       `${U99.mastKopfHoehe(sE, 'A')} m, Anschlusshoehe ${sE.mastH} m`);

  /*
   * >>> DER ANSCHLUSS BLEIBT AM MASTEN (Klarstellung vom 24. September). <<<
   *
   * «der anschlusspunkt liegt innerhalb der mastlänge, aber es sollte dann
   * möglich sein die z koordinate des anbauteils oberhalb der mastspitze
   * anzusetzen (Mastverlängerung mit Rohr)»
   *
   * Hier stand kurzzeitig «der Regler reicht zwei Meter ueber die
   * Mastspitze hinaus» - meine erste Lesart der Weisung vom 20. September,
   * und sie stellte den ANSCHLUSS in die Luft. Geschraubt wird am Masten;
   * hinaus ragt das Rohr, also die z-Koordinate des Moduls.
   */
  pruef('Der Regler endet an der Mastspitze',
        U99.mastReglerHoehe(sE, 'A') - U99.mastKopfHoehe(sE, 'A'), 0, 1e-9, 'm');

  // Duplizieren: die Kopie steigt, bis sie an die Spitze stoesst.
  const teil = { id: 'AT-k', name: 'RL', ort: 'mastA', hMast: lang - 0.8, x: 0, module: [], lasten: [] };
  let gesetzt = null;
  K99.anbauteilDuplizieren({ werte: { ...sE, anbauteile: [teil] }, letzte: null,
    setzeAnbauteile: (l) => { gesetzt = l; }, meldeImBalken: () => {} }, 0);
  wahr('Duplizieren unter der Spitze: die Kopie steht darueber',
       Math.abs(gesetzt?.[1]?.hMast - (lang - 0.3)) < 1e-9, `${gesetzt?.[1]?.hMast} m`);
  {
    // An der Spitze geht es wieder abwaerts - sonst wanderte die Kopie
    // mit jedem Klick weiter in die Luft.
    const oben = { ...teil, hMast: lang - 0.2 };
    let g2 = null;
    K99.anbauteilDuplizieren({ werte: { ...sE, anbauteile: [oben] }, letzte: null,
      setzeAnbauteile: (l) => { g2 = l; }, meldeImBalken: () => {} }, 0);
    wahr('… an der Spitze wieder darunter',
         g2?.[1]?.hMast < oben.hMast, `${g2?.[1]?.hMast} m`);
  }

  const q99 = readFileSync(join(HIER, 'js', 'app.setzen.js'), 'utf8');
  wahr('Ein Traeger am Einzelmast: kein Rat «ans Joch»',
       q99.includes('dieses Tragwerk hat kein Joch'));
  const ui99 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
  wahr('Karte nennt den Masten beim Namen (M1), nicht «MA»', ui99.includes('`${mName} ${f2(a.hMast ?? 0)} m`'));
}

titel('100  Anbauteil-Vorlagen nach Ort: Joch, Mast, beide');
/*
 * Weisung vom 19. September: «wir sollten die anbauteile template auf die
 * tragwerksarten anpassen. beim mast sind die ausleger relevant und die
 * zusatzleiter an traversen.» Am Masten: Rueckleiter direkt, Lampe alt/LED
 * mit Rohr, Fahrdrahtabzug mit Konsole 1 m, NT- und Rohrausleger, Traverse
 * mit Zusatzleiter. «nach ort trennen».
 */
{
  const A100 = await import(J('data.anbauteile.js'));
  const SZ100 = await import(J('app.setzen.js'));
  const alle = A100.vorlagen();
  const ort = (id) => A100.vorlageOrt(alle.find((v) => v.id === id) ?? { id });
  wahr('Ohne Spalte: mit Traeger ans Joch, sonst an beide',
       A100.vorlageOrt({ module: [{ bauteil: alle.flatMap((v) => v.module ?? [])
         .find((m) => { try { return FL.getFlBauteil(m.bauteil).rolle === 'traeger'; } catch { return false; } })?.bauteil }] }) === 'joch'
       && A100.vorlageOrt({ module: [] }) === 'beide');
  wahr('Die Spalte gilt, wo sie steht',
       A100.vorlageOrt({ ort: 'mast', module: [] }) === 'mast');
  wahr('Eine Mast-Vorlage passt an den Masten, nicht ans Joch',
       A100.vorlagePasstAn({ ort: 'mast' }, 'mastA') && !A100.vorlagePasstAn({ ort: 'mast' }, 'joch'));
  wahr('… eine Joch-Vorlage umgekehrt',
       A100.vorlagePasstAn({ ort: 'joch' }, 'joch') && !A100.vorlagePasstAn({ ort: 'joch' }, 'mastB'));
  const mastIds = alle.filter((v) => ort(v.id) === 'mast').map((v) => v.id);
  if (mastIds.length) {
    // Mit den Betreiberdaten: die fuenf angewiesenen Vorlagen am Masten.
    wahr('Am Masten stehen die angewiesenen Vorlagen',
         ['mast-nt-ausleger', 'mast-rohrausleger', 'mast-fd-abzug', 'mast-lampe-led-rohr',
          'mast-lampe-alt-rohr'].every((id) => mastIds.includes(id))
         && ['leiter-traverse', 'leiter-rl'].every((id) => ort(id) === 'beide'),
         mastIds.join(', '));
    const app100 = { werte: {}, letzte: null };
    const amMast = SZ100.vorlagenFuer(app100, 'mastA').map((e) => e.v.id);
    const amJoch = SZ100.vorlagenFuer(app100, 'joch').map((e) => e.v.id);
    wahr('Beim Setzen am Masten keine Joch-Vorlage, am Joch keine Mast-Vorlage',
         !amMast.some((id) => ort(id) === 'joch') && !amJoch.some((id) => ort(id) === 'mast')
         && amMast.includes('mast-nt-ausleger') && amJoch.includes('hs-fahrdraht'));
  }
  const q100 = readFileSync(join(HIER, 'js', 'app.setzen.js'), 'utf8');
  wahr('Ziehen/Vorwahl an die falsche Stelle wird abgewiesen, mit passendem Text',
       q100.includes('if (vorl && !vorlagePasstAn(vorl, st.ort))')
       && q100.includes('ist eine Vorlage fürs Joch, und dieses Tragwerk hat keines.'));
  const ui100 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
  wahr('Die Kachelliste zeigt am Einzelmast nur, was an den Masten passt',
       ui100.includes("&& (!ohneJoch || vorlagePasstAn(v, 'mast')));")
       && ui100.includes("['mast', 'Am Masten', 'grpUebrige'],"));
}

titel('101  Havarie je Leiter: nur einer reisst, Uebersicht, Ausleitung');
/*
 * Weisung vom 19. September: «eine übersicht mit allen leitern ermöglichen
 * wo man die leiter bestimmen kann die reissen und die berechnung
 * durchführen mit den regeln voll und 10%. beachte das nur ein leiter im
 * havariefall rissen kann und nicht mehrer. als einzelner leiter zählt auch
 * das kettenwerk Fd + Ts.» Rueckfrage: je Richtung eigener Zug; «die
 * lastfälle müssten dann im axis gebildet werden für die nachrechnung».
 */
{
  const A101 = await import(J('data.anbauteile.js'));
  const C101 = await import(J('core.constants.js'));
  const V101 = await import(J('core.vierendeel.js'));
  const N101 = await import(J('core.nachbarn.js'));
  const L101 = await import(J('core.lasten.js'));
  const AX101 = await import(J('export.axisvm.js'));
  let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
  w.L = 20; w.xLage = 0; w.mastVorhanden = true;
  w.anbauteile = [{ ...A101.neuesAnbauteil('hs-fahrdraht', 6), name: 'FL 1' },
                  { ...A101.neuesAnbauteil('hs-fahrdraht', 14), name: 'FL 2' }];
  const leiter = A101.leiterListe(w.anbauteile);
  wahr('Die Uebersicht findet beide Leiter', leiter.length === 2, leiter.map((l) => l.name).join(' | '));
  // Kettenwerk: zwei Module mit derselben Bezeichnung sind EIN Leiter.
  const kw = A101.leiterListe([{ id: 'X', name: 'KW', aktiv: true, module: [
    { bauteil: leiter[0].teile.length ? w.anbauteile[0].module.find((m) => /^drahtwerk-/.test(m.bauteil)).bauteil : '', kettenwerk: 'KW1' },
    { bauteil: w.anbauteile[0].module.find((m) => /^drahtwerk-/.test(m.bauteil)).bauteil, kettenwerk: 'KW1' }] }]);
  wahr('Ein Kettenwerk (gleiche Bezeichnung) zaehlt als EIN Leiter', kw.length === 1 && kw[0].key === 'kw:KW1');

  w.havarie = Object.fromEntries(leiter.map((l, i) => [l.key, { reisst: true, name: l.name,
    ...(i === 1 ? { zugM: 30 } : {}) }]));
  const s = C101.rechensatz(w);
  const hav = L101.lastfaelle(s).filter((l) => l.art === 'aussergewoehnlich');
  wahr('Je angehaktem Leiter zwei Faelle, dazu einer ohne Bruch',
       hav.length === 5 && hav.filter((l) => l.bruchLeiter).length === 4);
  const zug = (lf) => {
    const e = V101.berechne({ ...s, lastfall: lf.key }, ...N101.kernArgumente(s));
    return (e.modell.anbauteileFlach ?? []).filter((t) => Math.abs(t.kraefte?.HavarieY?.Fy ?? 0) > 1e-9);
  };
  const jeFall = hav.filter((l) => l.bruchLeiter).map((lf) => ({ lf, z: zug(lf) }));
  wahr('In jedem Fall zieht NUR der gerissene Leiter laengs',
       jeFall.every(({ lf, z }) => z.length === 1 && z[0].leiter === lf.bruchLeiter));
  const z20 = leiter[1].zug20;
  const m2 = jeFall.find(({ lf }) => lf.bruchLeiter === leiter[1].key && lf.vorzeichen < 0);
  const p2 = jeFall.find(({ lf }) => lf.bruchLeiter === leiter[1].key && lf.vorzeichen > 0);
  /*
   * Das Vorzeichen steht seit dem 24. September in der KRAFT, nicht mehr
   * im Beiwert (siehe Abschnitt 71): der -y-Fall traegt darum -3.00 kN.
   * Am Ergebnis aendert das nichts - fruehers +3.00 kN mal Beiwert -1.
   */
  wahr('10 % des Zugs; in -y der angegebene Zug (30 kN), in +y die Tabelle',
       Math.abs(m2.z[0].kraefte.HavarieY.Fy + 3.0) < 1e-9
       && Math.abs(p2.z[0].kraefte.HavarieY.Fy - 0.1 * z20) < 1e-9,
       `${p2.z[0].kraefte.HavarieY.Fy} / ${m2.z[0].kraefte.HavarieY.Fy}`);
  const ohne = hav.find((l) => !l.bruchLeiter);
  wahr('… und im Fall ohne Bruch zieht keiner', zug(ohne).length === 0);

  // Ausleitung: je Kandidat eigene Lastfaelle, die Kombination greift sie.
  const modellVon = (x) => V101.modell({ ...x, beiwerteFest: null },
    ...N101.kernArgumente(x).slice(0, 3), T.getTragjoch(x.typ));
  const dat = AX101.stabmodellJson(modellVon(s), { knotenmodell: 'anschnitt', eingabe: s });
  const lfKeys = dat.lastfaelle.map((l) => l.key);
  wahr('AxisVM: je Leiter Ablenkung und Zug +y / -y als eigene Lastfaelle',
       leiter.every((l) => [`HavarieX|${l.key}`, `HavarieY|${l.key}|p`, `HavarieY|${l.key}|m`]
         .every((k) => lfKeys.includes(k))));
  const summe = (fall) => dat.lasten.punkt.filter((p) => p.lastfall === fall && p.richtung === 'Y')
    .reduce((a, p) => a + p.wert, 0);
  const kb = dat.kombinationen.find((k) => k.key === m2.lf.key);
  const fy = kb.anteile.reduce((a, an) => a + an.faktor * summe(an.lastfall), 0);
  wahr('… und die Kombination L2 -y ergibt -3.00 kN in Gleisrichtung wie der Kern',
       Math.abs(fy + 3.0) < 1e-9 && kb.anteile.some((an) => an.lastfall === `HavarieY|${leiter[1].key}|m`),
       `${fy.toFixed(3)} kN · ${kb.bez}`);
  wahr('… mit kurzen Namen fuer AxisVM', dat.lastfaelle.filter((l) => l.leiter).every((l) => l.label.length <= 30));

  // Alter Stand: Merker «Bruch» an beiden Baugruppen -> Auswahl, Merker weg.
  const alt = { ...w, havarie: undefined,
    anbauteile: w.anbauteile.map((a) => ({ ...a, bruch: true })) };
  const neu = A101.havarieAnheben(alt);
  wahr('Alte Merker werden zur Auswahl, einzeln gerechnet',
       Object.keys(neu.havarie ?? {}).length === 2 && neu.anbauteile.every((a) => a.bruch === undefined));

  const ui101 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
  wahr('Die Uebersicht steht unter Lasten', ui101.includes("gruppen: ['ein', 'havarie', 'komb']")
       && ui101.includes('data-hav="reisst"'));
}

titel('102  Havariefall abschaltbar (Nachweis und Ausleitung)');
/*
 * Weisung vom 19. September: «den havarielastfall deaktivierbar machen
 * (nachweis / export)». Ein Schalter `havarieAus` am Tragwerk.
 */
{
  const A102 = await import(J('data.anbauteile.js'));
  const C102 = await import(J('core.constants.js'));
  const V102 = await import(J('core.vierendeel.js'));
  const N102 = await import(J('core.nachbarn.js'));
  const L102 = await import(J('core.lasten.js'));
  const AX102 = await import(J('export.axisvm.js'));
  let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
  w.L = 20; w.xLage = 0; w.mastVorhanden = true;
  w.anbauteile = [{ ...A102.neuesAnbauteil('hs-fahrdraht', 6), name: 'FL 1' }];
  const l1 = A102.leiterListe(w.anbauteile)[0];
  w.havarie = { [l1.key]: { reisst: true, name: l1.name } };
  const hav = (x) => L102.lastfaelle(C102.rechensatz(x)).filter((l) => l.art === 'aussergewoehnlich');
  wahr('Vorgabe: der Havariefall wird gerechnet', hav(w).length === 3);
  const aus = { ...w, havarieAus: true };
  wahr('Abgeschaltet: kein Havariefall in der Liste', hav(aus).length === 0);
  const s = C102.rechensatz(aus);
  const e = V102.berechne(s, ...N102.kernArgumente(s));
  wahr('… das Modell traegt den Schalter, der Hinweis sagt es',
       e.modell.havarieAus === true);
  const modellVon = (x) => V102.modell({ ...x, beiwerteFest: null },
    ...N102.kernArgumente(x).slice(0, 3), T.getTragjoch(x.typ));
  const dat = AX102.stabmodellJson(modellVon(s), { knotenmodell: 'anschnitt', eingabe: s });
  wahr('Ausleitung: kein Havarie-Lastfall, keine Havarie-Last, keine Havarie-Kombination',
       !dat.lastfaelle.some((l) => /^Havarie/.test(l.key))
       && ![...dat.lasten.punkt, ...dat.lasten.moment, ...dat.lasten.strecke].some((p) => /^Havarie/.test(p.lastfall))
       && !dat.kombinationen.some((k) => k.art === 'aussergewoehnlich')
       && dat.kombinationen.length > 0);
  const sAn = C102.rechensatz(w);
  const datAn = AX102.stabmodellJson(modellVon(sAn), { knotenmodell: 'anschnitt', eingabe: sAn });
  wahr('… eingeschaltet stehen sie da', datAn.lastfaelle.some((l) => l.key === `HavarieY|${l1.key}|p`)
       && datAn.kombinationen.some((k) => k.art === 'aussergewoehnlich'));

  const ui102 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
  wahr('Der Schalter steht in der Havarie-Gruppe', ui102.includes('data-hav-an="1"')
       && ui102.includes("onChange('havarieAus', !inp.checked)"));
  const ab102 = readFileSync(join(HIER, 'js', 'core.abfangjoch.js'), 'utf8');
  const nb102 = readFileSync(join(HIER, 'js', 'core.nachbarn.js'), 'utf8');
  wahr('Abfangjoch: abgeschaltet ohne den Fall «havarie» und ohne Laeufe je Leiter',
       ab102.includes("!(o.ohneHavarie === true && f.key === 'havarie')")
       && nb102.includes('ohneHavarie: satzA.havarieAus === true')
       && nb102.includes('satzA.havarieAus === true ? [] : havarieKandidaten'));
}

titel('103  Einzelmast: Ausleitung baut das Mastmodell, nicht den Jochweg');
/*
 * Gemeldet am 20. September: «Die com funktioniert nicht.» - mit einem
 * Einzelmasten als aktivem Tragwerk brach die AxisVM-Ausleitung ab:
 * «Cannot read properties of undefined (reading 'aH')» in `hebelarme`.
 * Grund: `berechne` hat die Weiche fuer den Einzelmasten, `modell` hatte
 * sie nicht - und die Ausleitung holt sich das Modell direkt. Sie bekam
 * den Jochweg ohne Gurtprofile (der Einzelmast fuehrt keine).
 */
{
  const C103 = await import(J('core.constants.js'));
  const V103 = await import(J('core.vierendeel.js'));
  const N103 = await import(J('core.nachbarn.js'));
  const AX103 = await import(J('export.axisvm.js'));
  let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
  w.L = 20; w.xLage = 0; w.mastVorhanden = true;
  let mitEm = C103.tragwerkHinzu(w, 'einzelmast', { xLage: 40, L: 20 });
  const idEm = C103.tragwerkeVon(mitEm).find((t) => t.tragwerksart === 'einzelmast').id;
  const idJoch = C103.tragwerkeVon(mitEm).find((t) => t.id !== idEm).id;
  mitEm = C103.tauscheAktives(mitEm, idEm);
  const satzEm = N103.rechensatzMitNachbarn(mitEm);

  // OHNE Profile - genau so ruft die Ausleitung, wenn das Ergebnis des
  // aktiven Tragwerks ein Einzelmast ist (`erg.modell` fuehrt keine Gurte).
  const mEm = V103.modell({ ...satzEm, beiwerteFest: null }, undefined, undefined,
                          getStahl(satzEm.stahl), undefined);
  wahr('modell() gibt am Einzelmast das Mastmodell zurueck, ohne Gurtprofile',
       mEm.tragwerksart === 'einzelmast' && mEm.profOG === undefined);

  // Und die Ausleitung laeuft damit durch - vorher warf sie in `hebelarme`.
  const deps = { berechne: V103.berechne, modell: V103.modell,
                 profOG: mEm.profOG, profUG: mEm.profUG, stahl: mEm.stahl, joch: mEm.joch,
                 modellVon: (s2) => V103.modell({ ...s2, beiwerteFest: null },
                   getProfil(s2.profOG), getProfil(s2.profUG),
                   getStahl(s2.stahl), T.getTragjoch(s2.typ)) };
  const bau = AX103.blattWennMehrere(satzEm, deps, { knotenmodell: 'anschnitt' });
  const dat = AX103.stabmodellJson(mEm, { knotenmodell: 'anschnitt', eingabe: satzEm, bau });
  wahr('… die COM-Ausleitung baut das Blatt (Joch und Einzelmast)',
       dat.knoten.length > 100 && dat.staebe.length > 100 && dat.lastfaelle.length > 0);

  // Allein auf dem Blatt: kein Joch, nur der Mast - und kein Abbruch.
  const alleinSatz = N103.rechensatzMitNachbarn(C103.tragwerkWeg(mitEm, idJoch));
  const mAllein = V103.modell({ ...alleinSatz, beiwerteFest: null }, undefined, undefined,
                              getStahl(alleinSatz.stahl), undefined);
  const datAllein = AX103.stabmodellJson(mAllein, { knotenmodell: 'anschnitt', eingabe: alleinSatz });
  wahr('… und allein auf dem Blatt steht der Mast in der Datei',
       datAllein.staebe.length >= 1 && datAllein.staebe.some((s) => /MAST/i.test(s.name ?? '')),
       `${datAllein.knoten.length} Knoten · ${datAllein.staebe.length} Staebe`);

  // Gegenprobe: am Joch aendert die Weiche nichts.
  const satzJoch = N103.rechensatzMitNachbarn(C103.tauscheAktives(mitEm, idJoch));
  const mJoch = V103.modell({ ...satzJoch, beiwerteFest: null }, getProfil(satzJoch.profOG),
                            getProfil(satzJoch.profUG), getStahl(satzJoch.stahl),
                            T.getTragjoch(satzJoch.typ));
  wahr('Am Joch bleibt es beim Jochweg', mJoch.tragwerksart !== 'einzelmast'
       && !!mJoch.profOG && mJoch.knotenLagen !== undefined || !!mJoch.profOG);

  const q103 = readFileSync(join(HIER, 'js', 'core.vierendeel.js'), 'utf8');
  wahr('Die Weiche steht in `modell`, wie in `berechne`',
       /export function modell\([^)]*\)\s*\{[\s\S]{0,1200}?tragwerksart\(inp\)\.key === 'einzelmast'[\s\S]{0,80}?return modellEinzelmast\(inp, stahl\);/.test(q103));
}

titel('104  Blattmodell: Praefix darf Starrelemente und Stabachsen nicht verlieren');
/*
 * Am 20. September am aufgebauten AxisVM-Modell gesehen: «das jochmodell
 * sieht nicht korrekt aus, hat es die querschnitte verworfen?» - im
 * Blattmodell heissen Stab und Querschnitt «T1_OGL_S0» / «T1_STARR».
 * `starrArt` verglich mit «STARR», `lcs` mit «GURT_OG» und «OG…»; beide
 * fielen durch. Folge: die Starrelemente wurden gewoehnliche Staebe mit
 * dem Ersatzquerschnitt 500x500 mm (327 kN Eigengewicht im Lastfall G bei
 * J90/20 m), und Gurtwinkel wie Bleche standen ungedreht.
 *
 * Die Kontrolle vergleicht DASSELBE Tragwerk allein und im Blatt: was der
 * Einzelweg baut, muss der Blattweg auch bauen.
 */
{
  const C104 = await import(J('core.constants.js'));
  const V104 = await import(J('core.vierendeel.js'));
  const N104 = await import(J('core.nachbarn.js'));
  const AX104 = await import(J('export.axisvm.js'));
  let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
  w.L = 20; w.xLage = 0; w.mastVorhanden = true;
  const modellVon = (satz) => V104.modell({ ...satz, beiwerteFest: null },
    getProfil(satz.profOG), getProfil(satz.profUG),
    getStahl(satz.stahl), T.getTragjoch(satz.typ));
  const deps = { berechne: V104.berechne, modell: V104.modell, modellVon };

  const allein = AX104.stabmodellJson(modellVon(N104.rechensatzMitNachbarn(w)),
    { knotenmodell: 'anschnitt' });
  // Dasselbe Joch, aber ein zweites Tragwerk daneben: jetzt mit Praefix.
  const reihe = C104.tragwerkHinzu(w, 'joch', { xLage: 25, L: 15 });
  const satzR = N104.rechensatzMitNachbarn(reihe);
  const blatt = AX104.stabmodellJson(modellVon(satzR),
    { knotenmodell: 'anschnitt', eingabe: satzR,
      bau: AX104.blattWennMehrere(satzR, deps, { knotenmodell: 'anschnitt' }) });

  const starr = (dat) => dat.staebe.filter((s) => s.art === 'starr').length;
  wahr('Das Blatt fuehrt Starrelemente wie der Einzelweg',
       starr(blatt) > 0 && starr(allein) > 0,
       `allein ${starr(allein)} · Blatt ${starr(blatt)}`);
  const richtungen = (dat) => new Set(dat.staebe.map((s) => (s.lcsZ ?? []).join(','))).size;
  wahr('… und dieselben Stabachsrichtungen (Gurtwinkel, Bleche gedreht)',
       richtungen(blatt) >= richtungen(allein) && richtungen(blatt) > 2,
       `allein ${richtungen(allein)} · Blatt ${richtungen(blatt)}`);

  // Stab fuer Stab: der Rohname ist in beiden Dateien derselbe.
  const jeRoh = (dat, praefix) => new Map(dat.staebe
    .filter((s) => s.name.startsWith(praefix))
    .map((s) => [s.name.slice(praefix.length), `${s.art}|${(s.lcsZ ?? []).join(',')}`]));
  const a1 = jeRoh(allein, ''), b1 = jeRoh(blatt, 'T1_');
  const gemeinsam = [...a1.keys()].filter((k) => b1.has(k));
  const anders = gemeinsam.filter((k) => a1.get(k) !== b1.get(k));
  wahr('Jeder Stab des Jochs wird im Blatt gleich gebaut wie allein',
       gemeinsam.length > 300 && anders.length === 0,
       `${gemeinsam.length} verglichen, ${anders.length} verschieden`
       + (anders.length ? `: ${anders.slice(0, 3).map((k) => `${k} ${a1.get(k)} statt ${b1.get(k)}`).join(' ; ')}` : ''));

  // PyNite erkennt die Bleche ebenfalls am Namen - auch dort mit Praefix.
  const PY104 = await import(J('export.pynite.js'));
  const satzR2 = N104.rechensatzMitNachbarn(reihe);
  const pyText = PY104.pyniteSkript(modellVon(satzR2), { knotenmodell: 'anschnitt',
    bau: AX104.blattWennMehrere(satzR2, deps, { knotenmodell: 'anschnitt' }) }).text;
  // add_section('T1_BLECH_V_100x10', A, Iy, Iz, J) - stehend und liegend
  // muessen sich in Iy/Iz unterscheiden, sonst ist die Drehlage verloren.
  const qsZeile = (kenn) => {
    const z = pyText.split('\n').find((r) => r.startsWith('M.add_section(') && r.includes(kenn));
    return z ? z.replace(/^[^,]*,/, '').split(',').map((x) => parseFloat(x)) : null;
  };
  const zV = qsZeile('BLECH_V_100x10'), zH = qsZeile('BLECH_H_100x10');
  wahr('PyNite: stehende und liegende Bleche bleiben auch im Blatt unterschiedlich',
       !!zV && !!zH && zV[1] !== zH[1] && zV[2] !== zH[2],
       zV && zH ? `V Iy ${zV[1]} Iz ${zV[2]} · H Iy ${zH[1]} Iz ${zH[2]}` : 'Zeile nicht gefunden');

  // Und kein Starrelement traegt im Blatt den 500x500-Ersatzquerschnitt.
  const klotz = blatt.staebe.filter((s) => /(^|_)STARR$/.test(s.querschnitt) && s.art === 'stab').length;
  wahr('Kein Starrelement bleibt als 500x500-Stab stehen (Eigengewicht!)', klotz === 0, `${klotz}`);
}

titel('105  Abfangjoch im Blattmodell: eigener Traeger, nicht der Jochweg');
/*
 * Am 20. September gemessen: stand ein Abfangjoch auf einem Blatt mit
 * mehreren Tragwerken, baute `stabmodell` es als TRAGJOCH - vier Winkel
 * L 90x90x9 mit Blechebenen statt zweier liegender Walzprofile mit Gabel
 * und Kroepfung. Entscheid: «Richtig einbauen».
 *
 * Die Kontrolle vergleicht DASSELBE Abfangjoch allein und im Blatt.
 */
{
  const C105 = await import(J('core.constants.js'));
  const V105 = await import(J('core.vierendeel.js'));
  const N105 = await import(J('core.nachbarn.js'));
  const AX105 = await import(J('export.axisvm.js'));
  const AXA105 = await import(J('export.axisvm.abfang.js'));
  const MA105 = await import(J('data.masten.js'));
  const modellVon = (satz) => V105.modell({ ...satz, beiwerteFest: null },
    getProfil(satz.profOG), getProfil(satz.profUG),
    getStahl(satz.stahl), T.getTragjoch(satz.typ));
  const deps = { berechne: V105.berechne, modell: V105.modell, modellVon };

  let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
  w.L = 20; w.xLage = 0; w.mastVorhanden = true;
  let blatt = C105.tragwerkHinzu(w, 'abfangjoch',
    { xLage: 20, L: 15, abfangTyp: 'A200', mastH: 8 });
  const tAb = C105.tragwerkeVon(blatt).find((t2) => t2.tragwerksart === 'abfangjoch');
  blatt = C105.tauscheAktives(blatt, tAb.id);
  blatt = C105.setzeAnbauteileAn(blatt,
    [{ ...A.neuesAnbauteil('leiter-nfl', 5), name: 'N-FL 1' }]);
  // Gerechnet wird das Tragjoch - das Abfangjoch ist der NACHBAR auf dem Blatt.
  blatt = C105.tauscheAktives(blatt,
    C105.tragwerkeVon(blatt).find((t2) => t2.id !== tAb.id).id);

  const satz = N105.rechensatzMitNachbarn(blatt);
  const satzAb = C105.tragwerkSatz(satz, tAb.id);
  const opt = { knotenmodell: 'anschnitt', auflagerModell: 'mast' };
  const bau = AX105.blattWennMehrere(satz, deps, opt);
  const pre = `${tAb.id}_`;
  const imBlatt = bau.staebe.filter((s) => s.name.startsWith(pre));

  wahr('Das Abfangjoch steht mit SEINEN Querschnitten im Blatt, nicht mit Jochwinkeln',
       imBlatt.some((s) => /_GURT$/.test(s.qs)) && imBlatt.some((s) => /_GABEL$/.test(s.qs))
       && !imBlatt.some((s) => /GURT_OG|GURT_UG/.test(s.qs)),
       [...new Set(imBlatt.map((s) => s.qs))].join(', '));

  // Dieselbe Ausleitung wie allein - Stab fuer Stab.
  const eigen = AXA105.abfangAxisvmModell(satzAb.abfangTyp, Number(satzAb.L), {
    knotenmodell: 'anschnitt', anbauteile: satzAb.anbauteile ?? [],
    auflagerLinks: satzAb.auflagerLinks, L_FL: Number(satzAb.L_FL) || 0,
    R: Number(satzAb.R) || 0, ek: satzAb.ek,
    schneeAktiv: satzAb.schneeAktiv, schneeKlasse: satzAb.schneeKlasse,
    mast: { profil: satzAb.mastProfil, hoehe: Number(satzAb.mastH),
            stegrichtung: satzAb.mastSteg },
  });
  const nE = new Set(eigen.staebe.filter((s) => !/^MAST_/.test(s.name)).map((s) => s.name));
  const nB = new Set(imBlatt.map((s) => s.name.slice(pre.length)));
  const anders = [...nE].filter((n) => !nB.has(n)).concat([...nB].filter((n) => !nE.has(n)));
  wahr('Traeger im Blatt = Traeger allein (ohne die Masten, die das Blatt benennt)',
       nE.size > 200 && anders.length === 0, `${nE.size} Staebe, ${anders.length} verschieden`);

  // Die Knoten stehen an derselben Stelle, nur um die Lage verschoben.
  const kE = new Map(eigen.knoten.map((k) => [k.name, k]));
  let dx = new Set(), dy = 0;
  bau.knoten.forEach((k, name) => {
    if (!name.startsWith(pre)) return;
    const e = kE.get(name.slice(pre.length));
    if (!e) return;
    dx.add(Math.round((k.x - e.x) * 1000)); dy = Math.max(dy, Math.abs(k.y - e.y));
  });
  wahr('… und sind nur verschoben, nicht verformt', dx.size === 1 && dy < 1e-9,
       `Verschiebung ${[...dx].map((v) => (v / 1000).toFixed(3)).join('/')} m`);

  // Die Lasten stehen in den Einwirkungsgruppen des Blattes (Entscheid 20. Sept.).
  const gruppen = {};
  [...bau.lasten.punkt, ...bau.lasten.strecke]
    .filter((l) => String(l.name ?? '').startsWith(pre))
    .forEach((l) => { gruppen[l.lastfall] = (gruppen[l.lastfall] ?? 0) + Math.abs(l.wert); });
  const eigenLeiterzug = [...eigen.lasten.punkt, ...eigen.lasten.strecke]
    .filter((l) => l.lastfall === 'Leiterzug').reduce((a, l) => a + Math.abs(l.wert), 0);
  wahr('Der staendige Leiterzug steht in G_Ablenk, gleich gross wie allein',
       Math.abs((gruppen.G_Ablenk ?? 0) - eigenLeiterzug) < 1e-6 && eigenLeiterzug > 0,
       `${(gruppen.G_Ablenk ?? 0).toFixed(2)} gegen ${eigenLeiterzug.toFixed(2)} kN`);
  wahr('… und keine Gruppe traegt einen Namen des Abfangjochs',
       !Object.keys(gruppen).some((g) => /Leiterzug|WindJoch|SchneeJoch/.test(g)),
       Object.keys(gruppen).join(', '));

  /*
   * DER VERSATZ DES VERBUNDQUERSCHNITTS MUSS MIT (20. September).
   *
   * Die Gabel des Abfangjochs ist ZWEI U-Profile, um eine Flanschbreite
   * versetzt. Das Blattmodell schrieb das Feld `versatz` nicht mit - die
   * COM-Bruecke baute beide uebereinander, und ihre Flaechenprobe meldete
   * am aufgebauten Modell -51.4 % (0.002105 statt 0.004334 m2). Gefunden
   * erst in AxisVM, nicht am Pruefstand.
   */
  const datV = AX105.stabmodellJson(modellVon(satz), { ...opt, eingabe: satz, bau });
  const gabel = datV.querschnitte.find((q) => /GABEL$/.test(q.name));
  wahr('Der Verbundquerschnitt traegt seinen Versatz in die Datei',
       !!gabel && gabel.form === 'DoppelU' && gabel.versatz > 0,
       gabel ? `${gabel.name} versatz ${gabel.versatz} mm, A ${gabel.A} m2` : 'keine Gabel');

  // Der geteilte Mast traegt EINEN Stabzug, nicht zwei uebereinander.
  const dat = AX105.stabmodellJson(modellVon(satz), { ...opt, eingabe: satz, bau });
  const knotenVon = new Map(dat.knoten.map((k) => [k.name, k]));
  const zug = dat.staebe.filter((s) => /^MAST_M2_S\d+$/.test(s.name));
  const dopp = zug.filter((a, i) => zug.findIndex((b) => b.von === a.von && b.bis === a.bis) !== i);
  const laenge = zug.reduce((a2, s) => {
    const p = knotenVon.get(s.von), q = knotenVon.get(s.bis);
    return a2 + (p && q ? Math.abs(q.z - p.z) : 0);
  }, 0);
  wahr('Der geteilte Mast (Joch und Abfangjoch) steht als EIN Zug da',
       zug.length > 1 && dopp.length === 0 && laenge > 8 && laenge < 9,
       `${zug.length} Abschnitte, ${laenge.toFixed(2)} m, ${dopp.length} deckungsgleich`);
}

titel('106  Abfangjoch-Ausleitung: Havarie je Leiter');
/*
 * Entscheid vom 20. September: «Gleich mit einbauen». Damit faellt der
 * offene Punkt vom 19. September weg - die Abfangjoch-Ausleitung legte
 * keine Havariefaelle an. Regel seit dem 17. September: voller Leiterzug,
 * der gerissene zieht nicht mehr, die uebrigen bei -20 °C.
 *
 * Geschrieben wird die AENDERUNG gegenueber dem staendigen Leiterzug; die
 * Kombination greift beides.
 */
{
  const C106 = await import(J('core.constants.js'));
  const A106 = await import(J('data.anbauteile.js'));
  const N106 = await import(J('core.nachbarn.js'));
  const AXA106 = await import(J('export.axisvm.abfang.js'));
  let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
  w.L = 15; w.xLage = 0; w.mastVorhanden = true; w.anbauteile = [];
  w = C106.tragwerkWeg(C106.tragwerkHinzu(w, 'abfangjoch',
    { xLage: 0, L: 15, abfangTyp: 'A200', mastH: 8 }), 'T1');
  w = C106.setzeAnbauteileAn(w, [
    { ...A106.neuesAnbauteil('leiter-nfl', 4), name: 'N-FL vorn' },
    { ...A106.neuesAnbauteil('leiter-rfl', 11), name: 'R-FL hinten' }]);
  const leiter = A106.leiterListe(C106.rechensatz(w).anbauteile);
  const bauen = (havarie) => {
    const s2 = C106.rechensatz({ ...w, havarie });
    return AXA106.abfangAxisvmModell('A200', 15, {
      knotenmodell: 'anschnitt', anbauteile: s2.anbauteile ?? [],
      L_FL: Number(s2.L_FL) || 0, R: Number(s2.R) || 0, ek: s2.ek,
      schneeAktiv: s2.schneeAktiv, schneeKlasse: s2.schneeKlasse,
      havarie: s2.havarie });
  };
  const wahl = Object.fromEntries(leiter.map((l) => [l.key, { reisst: true, name: l.name }]));
  const dat = bauen(wahl);
  const zug = (fall) => dat.lasten.punkt
    .filter((p) => p.lastfall === fall && p.richtung === 'Y')
    .reduce((a, p) => a + p.wert, 0);

  wahr('Je angehaktem Leiter ein Lastfall und eine Kombination',
       leiter.every((l) => dat.lastfaelle.some((x) => x.key === `HavarieY|${l.key}`)
         && dat.kombinationen.some((k) => k.key === `havarie|${l.key}`)),
       dat.lastfaelle.filter((x) => /^HavarieY/.test(x.key)).map((x) => x.label).join(' · '));
  wahr('… die Havariekombination ist aussergewoehnlich, ohne veraenderliche Lasten',
       dat.kombinationen.filter((k) => /^havarie/.test(k.key)).every((k) => k.art === 'aussergewoehnlich'
         && k.anteile.every((an) => an.faktor === 1)
         && !k.anteile.some((an) => /Wind|Schnee/.test(an.lastfall))));

  // In jedem Fall zieht nur noch der andere Leiter - und der bei -20 °C.
  const gesamt = (key) => {
    const k = dat.kombinationen.find((x) => x.key === `havarie|${key}`);
    return k.anteile.reduce((a, an) => a + an.faktor * zug(an.lastfall), 0);
  };
  const staendig = zug('Leiterzug');
  const soll = leiter.map((l) => l.zug20 ?? 0);
  wahr('In jedem Fall faellt genau ein Leiter aus, die uebrigen ziehen bei -20 °C',
       Math.abs(gesamt(leiter[0].key) - soll[1]) < 1e-6
       && Math.abs(gesamt(leiter[1].key) - soll[0]) < 1e-6,
       `staendig ${staendig.toFixed(2)} · ohne L1 ${gesamt(leiter[0].key).toFixed(2)}`
       + ` · ohne L2 ${gesamt(leiter[1].key).toFixed(2)} kN`);

  // Und die Datei bringt dasselbe wie der Rechenkern.
  const erg = N106.abfangAuswertungFuer({ ...w, havarie: wahl }, getStahl(w.stahl));
  const je = (ende) => Object.fromEntries(
    (erg?.auflager?.[ende]?.faelle ?? []).map((f) => [f.key, f.Fy ?? 0]));
  const fa = je('A'), fb = je('B');
  const paare = leiter.map((l) => [gesamt(l.key), (fa[`havarie|${l.key}`] ?? 0) + (fb[`havarie|${l.key}`] ?? 0)]);
  wahr('Datei und Rechenkern tragen denselben Laengszug',
       paare.every(([datei, kern]) => Math.abs(datei - kern) < 1e-6),
       paare.map(([a2, b2]) => `${a2.toFixed(3)}/${b2.toFixed(3)}`).join(' · '));

  // Auch ohne Reglagetabelle (Zug temperaturunabhaengig) muss die
  // Kombination dastehen - sie unterscheidet sich in den Beiwerten.
  const q106 = readFileSync(join(HIER, 'js', 'export.axisvm.abfang.js'), 'utf8');
  wahr('Die Havariekombination steht auch ohne Aenderung des Zugs',
       q106.includes("p2.lastfall === 'Leiterzug'") && q106.includes('h.mitLast'));

  // Ohne Auswahl: ein Fall ohne Leiterbruch, alle bei -20 °C.
  const ohne = bauen(undefined);
  const zugO = (fall) => ohne.lasten.punkt
    .filter((p) => p.lastfall === fall && p.richtung === 'Y').reduce((a, p) => a + p.wert, 0);
  const kO = ohne.kombinationen.find((k) => k.key === 'havarie');
  wahr('Ohne Auswahl: ein Fall «ohne Leiterbruch», alle Leiter bei -20 °C',
       !!kO && Math.abs(kO.anteile.reduce((a, an) => a + an.faktor * zugO(an.lastfall), 0)
                        - (soll[0] + soll[1])) < 1e-6,
       kO ? `${kO.bez} = ${kO.anteile.reduce((a, an) => a + an.faktor * zugO(an.lastfall), 0).toFixed(2)} kN`
          : 'fehlt');
}

titel('107  Abfangjoch: Masten nach innen, Laenge nach den Masten');
/*
 * Weisung vom 20. September: «die masten werden nach innen gesetzt wenn
 * primär ein jochtyp und länge ausgewählt wurde. wenn aber die masten schon
 * vorhanden sind sollte sich der jochtyp daran richten und wenn notwendig
 * den nächst längeren joch auswählen.»
 *
 * Das Sortiment fuehrt je Laenge einen Bereich zulaessiger Stuetzweiten;
 * Vorgabe ist die groesste, also 0.25 m Ueberstand je Seite (Entscheid).
 */
{
  const C107 = await import(J('core.constants.js'));
  const K107 = await import(J('core.abfangjoch.js'));
  const V107 = await import(J('core.vierendeel.js'));
  const N107 = await import(J('core.nachbarn.js'));
  const AX107 = await import(J('export.axisvm.js'));

  const t = { tragwerksart: 'abfangjoch', abfangTyp: 'A160', L: 12.5, xLage: 20 };
  wahr('Der Ueberstand ist 0.25 m je Seite (groesste Stuetzweite)',
       Math.abs(C107.abfangUeberstand(t) - 0.25) < 1e-9,
       `${C107.abfangUeberstand(t)} m`);
  const lagen = C107.mastLagen(t);
  wahr('Die Lage ist der ERSTE MAST, der Traeger kragt darueber hinaus',
       Math.abs(lagen[0] - 20) < 1e-9 && Math.abs(lagen[1] - 32) < 1e-9
       && Math.abs(C107.lageOrtsnull(t) - 19.75) < 1e-9,
       `Masten ${lagen.join(' / ')} · Traeger ab ${C107.lageOrtsnull(t)}`);
  wahr('Beim Tragjoch bleibt die Mastachse am Jochende',
       C107.mastLagen({ tragwerksart: 'joch', L: 20, xLage: 20 }).join() === '20,40'
       && C107.abfangUeberstand({ tragwerksart: 'joch', L: 20 }) === 0);

  // Die Laenge richtet sich nach vorhandenen Masten - naechst laengeres Joch.
  wahr('12.00 m Mastabstand traegt das A160 / 12.50 m',
       K107.abfangFuerStuetzweite('A160', 12.0)?.L === 12.5);
  const v = K107.abfangFuerStuetzweite('A160', 12.5);
  wahr('12.50 m braucht das naechst laengere Joch (A200 / 13.00 m)',
       v?.typ === 'A200' && Math.abs(v.L - 13) < 1e-9,
       v ? `${v.typ} / ${v.L}` : 'keines');
  wahr('Was kein Joch traegt, wird nicht erfunden',
       K107.abfangFuerStuetzweite('A160', 30) === null);

  // Im Blatt faellt der geteilte Mast jetzt genau zusammen.
  let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
  w.L = 20; w.xLage = 20; w.mastVorhanden = true;
  const blatt = C107.tragwerkHinzu(w, 'abfangjoch',
    { xLage: 20, L: 12.5, abfangTyp: 'A160', mastH: 7.5 });
  const satz = N107.rechensatzMitNachbarn(blatt);
  const modellVon = (s2) => V107.modell({ ...s2, beiwerteFest: null },
    getProfil(s2.profOG), getProfil(s2.profUG), getStahl(s2.stahl), T.getTragjoch(s2.typ));
  const bau = AX107.blattWennMehrere(satz, { berechne: V107.berechne, modell: V107.modell, modellVon },
    { knotenmodell: 'anschnitt', auflagerModell: 'mast' });
  const mastX = (id) => {
    const xs = [];
    bau.knoten.forEach((k, n) => { if (n.startsWith(`MAST_${id}`)) xs.push(+k.x.toFixed(3)); });
    return [...new Set(xs)];
  };
  const m1 = mastX('M1');
  wahr('Der geteilte Mast steht an EINER Stelle - Mast und Anschluss zusammen',
       m1.length === 1 && Math.abs(m1[0] - 20) < 1e-6, `x ${m1.join(' / ')}`);
  wahr('… und der zweite Mast des Abfangjochs steht auf seiner Stuetzweite',
       mastX('M3').length === 1 && Math.abs(mastX('M3')[0] - 32) < 1e-6,
       `x ${mastX('M3').join(' / ')}`);

  const q107 = readFileSync(join(HIER, 'js', 'app.js'), 'utf8');
  wahr('Passt die Laenge nicht zu den Masten, sagt es die Anwendung',
       q107.includes('abfangFuerStuetzweite(werte.abfangTyp, js)')
       && q107.includes('die Masten stehen ${js.toFixed(2)} m auseinander'));
}

titel('108  COM-Schnittstelle: Mastfuss eingespannt, Datei in sich stimmig');
/*
 * Gemeldet am 20. September mit dem Auflagerdialog aus AxisVM: «der masten
 * soll eingespannt sein, dies wurde gebaut». Im aufgebauten Modell trugen
 * die beiden EINZELMASTFUESSE yy = 0 und zz = 0 - der Mast stand auf einem
 * Gelenk, waehrend jeder Jochmastfuss 1e10 hatte.
 *
 * Grund: `stabmodellEinzelmast` schrieb nur `art: 'eingespannt'`, und
 * `stuetzung` kannte die Angabe nicht - es baute den JOCH-Fall (Auflager
 * auf dem Mastkopf, Verdrehung um y als Feder aus c_phi). Am Einzelmasten
 * gibt es keine Jochfeder, also c = 0: «frei».
 *
 * Dazu die Kontrollen, die eine Datei in sich stimmig halten - «checke die
 * schnittstellen und checks für die com schnittstelle modellaufbau».
 */
{
  const C108 = await import(J('core.constants.js'));
  const V108 = await import(J('core.vierendeel.js'));
  const N108 = await import(J('core.nachbarn.js'));
  const AX108 = await import(J('export.axisvm.js'));
  const A108 = await import(J('data.anbauteile.js'));
  const modellVon = (s2) => V108.modell({ ...s2, beiwerteFest: null },
    getProfil(s2.profOG), getProfil(s2.profUG), getStahl(s2.stahl), T.getTragjoch(s2.typ));

  const datei = (w) => {
    const satz = N108.rechensatzMitNachbarn(w);
    const erg = V108.berechne(satz, getProfil(satz.profOG), getProfil(satz.profUG),
                              getStahl(satz.stahl), T.getTragjoch(satz.typ));
    const m0 = erg.modell;
    const deps = { berechne: V108.berechne, modell: V108.modell,
                   profOG: m0.profOG, profUG: m0.profUG, stahl: m0.stahl, joch: m0.joch,
                   modellVon };
    const m = deps.modell({ ...satz, beiwerteFest: null },
                          deps.profOG, deps.profUG, deps.stahl, deps.joch);
    const opt = { knotenmodell: 'anschnitt', auflagerModell: 'mast', eingabe: satz };
    return AX108.stabmodellJson(m, { ...opt, bau: AX108.blattWennMehrere(satz, deps, opt) });
  };

  // a) Einzelmast allein, mit einem Teil am Masten
  let em = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
  em.L = 20; em.xLage = 0; em.mastVorhanden = true;
  em = C108.tragwerkWeg(C108.tragwerkHinzu(em, 'einzelmast',
    { mastProfil: 'HEB 260', mastH: 8, mastLaenge: 12 }), 'T1');
  em = C108.setzeAnbauteileAn(em,
    [{ ...A108.neuesAnbauteil('leiter-traverse', 0), hMast: 9.5, ort: 'mastA' }]);
  // b) Blatt: Joch, Einzelmast
  let bl = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
  bl.L = 20; bl.xLage = 0; bl.mastVorhanden = true;
  bl = C108.tragwerkHinzu(bl, 'einzelmast',
    { xLage: 40, mastProfil: 'HEB 260', mastH: 8, mastLaenge: 12 });

  const fest = (a) => ['ux', 'uy', 'uz', 'fix', 'fiy', 'fiz'].every((f) => a[f] === 'Rigid');
  [['Einzelmast allein', em], ['Blatt mit Einzelmast', bl]].forEach(([name, w]) => {
    const dat = datei(w);
    const fuesse = dat.auflager.filter((a) => a.modell === 'mast');
    const lose = fuesse.filter((a) => !fest(a));
    wahr(`${name}: jeder Mastfuss ist voll eingespannt`,
         fuesse.length > 0 && lose.length === 0,
         `${fuesse.length} Fuesse` + (lose.length
           ? `, lose: ${lose.map((a) => `${a.knoten} fiy ${a.fiy} fiz ${a.fiz}`).join(', ')}` : ''));

    // Die Datei muss in sich stimmen: jede Last auf einem Stab/Knoten, den
    // es gibt, und jeder Stab auf einem Querschnitt, den es gibt.
    const knoten = new Set(dat.knoten.map((k) => k.name));
    const staebe = new Set(dat.staebe.map((s) => s.name));
    const qs = new Set(dat.querschnitte.map((q) => q.name));
    const lose2 = [
      ...dat.lasten.punkt.filter((l) => !knoten.has(l.knoten)).map((l) => `Punktlast ${l.knoten}`),
      ...dat.lasten.moment.filter((l) => !knoten.has(l.knoten)).map((l) => `Moment ${l.knoten}`),
      ...dat.lasten.strecke.filter((l) => !staebe.has(l.stab)).map((l) => `Strecke ${l.stab}`),
      ...dat.staebe.filter((s) => !knoten.has(s.von) || !knoten.has(s.bis)).map((s) => `Stab ${s.name}`),
      ...dat.staebe.filter((s) => !qs.has(s.querschnitt)).map((s) => `QS ${s.querschnitt}`),
      ...dat.auflager.filter((a) => !knoten.has(a.knoten)).map((a) => `Auflager ${a.knoten}`),
    ];
    wahr(`${name}: jede Last und jeder Stab zeigt auf Vorhandenes`,
         lose2.length === 0, lose2.slice(0, 4).join(' · ') || 'stimmig');

    // Und der Wind steht in BEIDEN Richtungen am Masten - gemeldet am
    // 20. September: «bei wind in y hat das modell keine last beim
    // einzelmasten generiert» (damals hiessen beide Masten MAST_A und
    // verschmolzen, siehe Abschnitt 107).
    const amMast = (lf) => dat.lasten.strecke
      .filter((l) => l.lastfall === lf && /^MAST_/.test(l.stab)).length;
    wahr(`${name}: Mastwind steht in x UND in y`,
         amMast('WindX') > 0 && amMast('WindY') > 0,
         `WindX ${amMast('WindX')} · WindY ${amMast('WindY')}`);
  });

  // Jede Kombination greift nur Lastfaelle, die es gibt.
  const dat = datei(bl);
  const lfKeys = new Set(dat.lastfaelle.map((l) => l.key));
  const fehl = dat.kombinationen.flatMap((k) => k.anteile
    .filter((an) => !lfKeys.has(an.lastfall)).map((an) => `${k.key} -> ${an.lastfall}`));
  wahr('Jede Kombination greift nur vorhandene Lastfaelle', fehl.length === 0,
       fehl.slice(0, 3).join(' · ') || `${dat.kombinationen.length} Kombinationen`);
}

titel('109  Mastwind: die Maske zeigt, was der Kern rechnet');
/*
 * Gemeldet am 20. September, mit dem Reiter LASTEN eines Einzelmasten:
 * «hier ist die windlast in y nicht aufgefuehrt beim einzelmasten. auch die
 * angabe in der sidebar passt nicht ganz.»
 *
 * Drei Sachen steckten darin, alle an derselben Naht:
 *
 *   1  Die Maske fuehrte nur EINEN Mastwind - den in der Jochachse. Der Kern
 *      rechnet seit dem 27. August mit beiden Richtungen, und am Einzelmasten
 *      ist die GLEISRICHTUNG die massgebende (in Jochachse steht dort nichts,
 *      was den Kopf halten koennte).
 *
 *   2  Das Feld zeigte den in der Mastliste ABGELEGTEN Wert, der Kern nahm
 *      den Tabellenwert: an einem HEB 220 stand 0.37 kN/m in der Maske (ein
 *      Rest vom HEB 240 der Vorlage) und gerechnet wurden 0.28 kN/m.
 *
 *   3  «Werte bearbeiten» gab das Feld frei, aber der eingetragene Wert
 *      wirkte NICHT: `wMastAusTabelle` wird nirgends gesetzt, also war
 *      `vonHand` immer falsch und die Tabelle gewann stillschweigend.
 *      Nachgemessen, ob die Eingabe wirken SOLL: nein. Es gibt ein flaches
 *      Feld, aber mehrere Masten - an einem Joch HEB 220 / HEM 240 gaebe es
 *      beiden 0.37 statt 0.28 und 0.31 kN/m. Die Tabelle bleibt, das Feld
 *      wird gesperrt (`nurAnzeige`); eine Eingabe je Mast waere ein eigener
 *      Entscheid und liegt dem Auftraggeber vor.
 *
 * Dazu die Laufmeterlasten des Jochs (g_k, w_k, s_k, Zuschlag): sie standen
 * am Einzelmasten in der Maske, obwohl der Kern dort L = 0 rechnet.
 */
{
  const DM = await import(J('data.masten.js'));
  const LA109 = await import(J('core.lasten.js'));
  const C109 = await import(J('core.constants.js'));
  const V109 = await import(J('core.vierendeel.js'));
  const S109 = await import(J('ui.schema.js'));
  const NB109b = await import(J('core.nachbarn.js'));

  const einzelmast = (extra = {}) => {
    let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
    w.L = 20; w.xLage = 0; w.mastVorhanden = true;
    w = C109.tragwerkWeg(C109.tragwerkHinzu(w, 'einzelmast',
      { mastProfil: 'HEB 220', mastLaenge: 12 }), 'T1');
    return { ...w, ...extra };
  };

  // a) Die Paarung der beiden Richtungen steht an EINER Stelle.
  const paar = DM.mastWindBeide('HEM 240', 'EK2', 'jochachse');
  wahr('mastWindBeide: Jochachse und Gleisrichtung getrennt',
       paar.jochachse === DM.mastWind('HEM 240', 'EK2', 'jochachse')
       && paar.gleis === DM.mastWind('HEM 240', 'EK2', 'quer'),
       `HEM 240 EK2: ${paar.jochachse} / ${paar.gleis} kN/m`);
  const gedreht = DM.mastWindBeide('HEM 240', 'EK2', 'quer');
  wahr('mastWindBeide: die Stegrichtung tauscht die Spalten',
       gedreht.jochachse === paar.gleis && gedreht.gleis === paar.jochachse,
       `gedreht: ${gedreht.jochachse} / ${gedreht.gleis} kN/m`);

  // b) Maske gegen Kern - ueber Profile, Klassen und Stegrichtungen.
  const fX = S109.feld('wMast');
  const fY = S109.feld('wMastY');
  const abweichend = [];
  ['HEB 200', 'HEB 220', 'HEB 260', 'HEM 240'].forEach((prof) => {
    ['0.9', '1.1', '1.3'].forEach((wk) => {
      ['jochachse', 'quer'].forEach((steg) => {
        const w = einzelmast({ windKlasse: wk, mastProfil: prof, mastSteg: steg });
        const m = V109.modellEinzelmast({ ...w, lastfall: 'wyk' }, getStahl(w.stahl));
        const x = fX.wertAus(w), y = fY.wertAus(w);
        if (Math.abs(x - m.mastLast.A.x) > 1e-12 || Math.abs(y - m.mastLast.A.y) > 1e-12) {
          abweichend.push(`${prof}/${wk}/${steg}: Maske ${x}/${y} gegen Kern `
                        + `${m.mastLast.A.x}/${m.mastLast.A.y}`);
        }
      });
    });
  });
  wahr('Maske und Kern nennen denselben Mastwind (24 Faelle)',
       abweichend.length === 0, abweichend[0] ?? 'keine Abweichung');

  // c) Die zweite Richtung ist angeschrieben und keine Eingabe.
  wahr('w_Mast,y steht in der Maske und ist gesperrt',
       fY.nurAnzeige === true && fY.sichtbar(einzelmast()) === true,
       `sym ${fY.sym}`);

  // d) Die Tabelle gewinnt - und die Maske behauptet nichts anderes.
  {
    const w = einzelmast({ lastHerkunft: 'manuell', lastenBearbeiten: true, wMast: 0.61 });
    const m = V109.modellEinzelmast({ ...w, lastfall: 'wyk' }, getStahl(w.stahl));
    wahr('Auch freigegeben gilt die Tabelle, nicht das flache Feld',
         Math.abs(m.mastLast.A.x - 0.28) < 1e-12, `x = ${m.mastLast.A.x} kN/m`);
    wahr('… und die Maske zeigt denselben Wert',
         Math.abs(fX.wertAus(w) - m.mastLast.A.x) < 1e-12, `Maske ${fX.wertAus(w)} kN/m`);
    wahr('w_Mast,x ist deshalb gesperrt, nicht scheinbar frei',
         fX.nurAnzeige === true && fX.ausLast === undefined, 'nurAnzeige');
    /*
     * ZWEI MASTEN, ZWEI PROFILE - der Grund, warum es kein Eingabefeld gibt.
     * Ein flaches Feld gaebe beiden denselben Wert.
     */
    const NB109 = await import(J('core.nachbarn.js'));
    let zwei = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
    zwei.L = 20; zwei.xLage = 0; zwei.mastVorhanden = true; zwei.mastProfil = 'HEB 220';
    zwei = { ...zwei, masten: C109.mastenVon(zwei)
      .map((mm, i) => ({ ...mm, profil: i === 0 ? 'HEB 220' : 'HEM 240' })) };
    // Ueber den Weg der Anwendung: erst der Rechensatz, dann das Modell -
    // sonst kennt `drehfedern` die Mastliste nicht.
    const rz = NB109.rechensatzMitNachbarn(zwei);
    const mz = V109.modell({ ...rz, lastfall: 'wyk' }, getProfil(rz.profOG),
      getProfil(rz.profUG), getStahl(rz.stahl), T.getTragjoch(rz.typ));
    wahr('Jeder Mast bekommt den Wind SEINES Profils',
         Math.abs(mz.mastLast.A.x - 0.28) < 1e-12
         && Math.abs(mz.mastLast.B.x - 0.31) < 1e-12,
         `A ${mz.mastLast.A.x} · B ${mz.mastLast.B.x} kN/m`);
  }

  // e) Laufmeterlasten des Jochs stehen nicht am Einzelmasten.
  {
    const em = einzelmast({ schneeAktiv: true });
    const joch = typUebernehmen({ ...standardwerte(), typ: 'J90', schneeAktiv: true },
                                T.getTragjoch('J90'));
    const jochLasten = ['gkManuell', 'wkManuell', 'skManuell', 'gZusatz', 'schneeKlasse'];
    const sichtbar = (f, w) => (f.sichtbar ? Boolean(f.sichtbar(w)) : true);
    const amMasten = jochLasten.filter((k) => sichtbar(S109.feld(k), em));
    const amJoch = jochLasten.filter((k) => sichtbar(S109.feld(k), joch));
    wahr('Am Einzelmasten steht keine Laufmeterlast des Jochs',
         amMasten.length === 0, amMasten.join(', ') || 'keine');
    wahr('Am Joch stehen sie alle', amJoch.length === jochLasten.length,
         amJoch.join(', '));
    // Die Windklasse bleibt - sie waehlt die Zeile der Mastwindtabelle.
    wahr('Die Windklasse bleibt am Einzelmasten sichtbar',
         sichtbar(S109.feld('windKlasse'), em), 'waehlt die Zeile des Mastwinds');

    /*
     * >>> UND KEIN FELD DARF DA STEHEN, DAS NICHTS TUT. <<<
     *
     * Weisung vom 20. September: «man sollte die tragjoche und masten
     * gleichwertig behandeln und nur die felder auflisten die auch im
     * modell vorkommen.» Gemessen wird deshalb die WIRKUNG: jedes der
     * ausgeblendeten Felder darf am Einzelmasten weder den Nachweis noch
     * die Spalten der Lastfalltabelle veraendern.
     */
    const nachweisAbdruck = (w2) => {
      const s2 = NB109b.rechensatzMitNachbarn(w2);
      const v = V109.vergleichKombinationen(s2, getProfil(s2.profOG),
        getProfil(s2.profUG), getStahl(s2.stahl), T.getTragjoch(s2.typ));
      const e2 = V109.berechne(s2, getProfil(s2.profOG), getProfil(s2.profUG),
        getStahl(s2.stahl), T.getTragjoch(s2.typ));
      return JSON.stringify([e2.mast?.etaNachweis, e2.max?.etaGesamt,
        v.lastfaelle.map((z) => [z.eta, z.qd, z.wd])]);
    };
    const ohneWirkung = [];
    [['gkManuell', 0.6, 1.2], ['wkManuell', 0.52, 1.04], ['skManuell', 0.27, 0.54],
     ['gZusatz', 0, 0.4], ['schneeKlasse', '0.9', '1.25'],
     ['mastWindAufJoch', false, true]].forEach(([k, a, b]) => {
      const gleich = nachweisAbdruck(einzelmast({ schneeAktiv: true, [k]: a }))
                  === nachweisAbdruck(einzelmast({ schneeAktiv: true, [k]: b }));
      if (!gleich) ohneWirkung.push(k);
      if (sichtbar(S109.feld(k), em)) ohneWirkung.push(k + ' steht trotzdem da');
    });
    wahr('Die ausgeblendeten Felder aendern am Einzelmasten nichts',
         ohneWirkung.length === 0, ohneWirkung.join(', ') || 'keines wirkt');
  }

  // f) Im Bild steht der Wind in y am Masten - er war der Anlass.
  {
    const R109 = await import(J('render.3d.js'));
    const w = einzelmast();
    const faelle = LA109.lastfaelle(w);
    const wyk = faelle.find((f) => f.key === 'wyk');
    const erg = berechne({ ...w, lastfall: wyk.key }, getProfil(w.profOG),
                         getProfil(w.profUG), getStahl(w.stahl), T.getTragjoch(w.typ));
    const sz = R109.erzeugeSzene(erg.modell, erg);
    const amMast = (art) => (sz.vektoren ?? [])
      .filter((v) => v.lastart === art && /^MAST_/.test(String(v.teil ?? ''))).length;
    wahr('Wind in Gleisrichtung steht am Einzelmasten im Bild',
         amMast('windY') > 0, `${amMast('windY')} Pfeile`);
  }
}


titel('110  Einzelmast: Durchlauf ueber Modellierung und Auswertung');
/*
 * Weisung vom 20. September: «kannst du zudem ein paar durchläufe bei der
 * modellieren und auswertung des einzelmasten vornehmen, es scheint, dass
 * wir sehr viele bugs haben.»
 *
 * 367 Aufbauten durchgefahren (Profil x Laenge x Einwirkungsklasse x
 * Stegrichtung x Anbauteile, dazu Anker, Schnee, Havarie, Blatt). Drei
 * Befunde blieben - sie stehen hier als Wache.
 */
{
  const DM110 = await import(J('data.masten.js'));
  const C110 = await import(J('core.constants.js'));
  const V110 = await import(J('core.vierendeel.js'));
  const CH110 = await import(J('core.checks.js'));
  const AX110 = await import(J('export.axisvm.js'));
  const NB110 = await import(J('core.nachbarn.js'));
  const A110 = await import(J('data.anbauteile.js'));
  const S110 = await import(J('ui.schema.js'));

  const mv110 = (s) => V110.modell({ ...s, beiwerteFest: null },
    getProfil(s.profOG), getProfil(s.profUG), getStahl(s.stahl), T.getTragjoch(s.typ));

  const einzelmast = (o = {}) => {
    let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
    w.L = 20; w.xLage = 0; w.mastVorhanden = true;
    w = C110.tragwerkWeg(C110.tragwerkHinzu(w, 'einzelmast', {
      mastProfil: o.profil ?? 'HEB 220', mastLaenge: o.laenge ?? 12 }), 'T1');
    w.windKlasse = o.ek ?? '0.9';
    if (o.hMast !== undefined) {
      w = C110.setzeAnbauteileAn(w, [{ ...A110.neuesAnbauteil('leiter-traverse', 0),
                                       hMast: o.hMast, ort: 'mastA' }]);
    }
    return w;
  };
  const rechne110 = (w) => {
    const s = NB110.rechensatzMitNachbarn(w);
    return { s, erg: V110.berechne(s, getProfil(s.profOG), getProfil(s.profUG),
                                   getStahl(s.stahl), T.getTragjoch(s.typ)) };
  };
  const datei110 = (s, erg) => {
    const m0 = erg.modell;
    const deps = { berechne: V110.berechne, modell: V110.modell, profOG: m0.profOG,
                   profUG: m0.profUG, stahl: m0.stahl, joch: m0.joch, modellVon: mv110 };
    const m = deps.modell({ ...s, beiwerteFest: null },
      deps.profOG, deps.profUG, deps.stahl, deps.joch);
    const opt = { knotenmodell: 'anschnitt', auflagerModell: 'mast', eingabe: s };
    return AX110.stabmodellJson(m, { ...opt, bau: AX110.blattWennMehrere(s, deps, opt) });
  };

  /* =====================================================================
   * a) OHNE MASTEN-SORTIMENT WIRD KEINE WINDLAST ERFUNDEN
   * ===================================================================
   * Gemeldet mit einem HEB 220 / 12.00 m: «dieser mast heb 220 zeigt
   * immernochnicht eine windlast in y.» In der Maske standen 0.30 kN/m -
   * der Tabellenwert eines HEB 240, ein Rest in der Mastliste -, in
   * Gleisrichtung nichts, und im Bild fehlte der Pfeil. Ursache: ohne
   * Masten-Sortiment faellt `mastprofile()` auf die Normprofile zurueck,
   * und die tragen keine Windzeile.
   */
  {
    const gesichert = DM110.mastenDB();
    try {
      DM110.setzeMastenDB({ typen: [] });
      wahr('Ohne Sortiment gibt es keine Windzeile',
           !DM110.mastenDbDa() && DM110.mastWind('HEB 220', 'EK1', 'jochachse') === null,
           'mastenDbDa ' + DM110.mastenDbDa());
      let w = einzelmast({ profil: 'HEB 220', laenge: 12 });
      // Ein Rest in der Mastliste, wie er beim Profilwechsel entsteht.
      w = { ...w, wMast: 0.30,
            masten: C110.mastenVon(w).map((m) => ({ ...m, wMast: 0.30 })) };
      const { erg } = rechne110(w);
      const ml = erg.modell.mastLast?.A;
      wahr('… und der Kern erfindet keine',
           ml?.x === null && ml?.y === null && ml?.fehlt === true,
           `x ${ml?.x} · y ${ml?.y} · fehlt ${ml?.fehlt}`);
      wahr('… die Maske zeigt nichts statt eines fremden Wertes',
           S110.feld('wMast').wertAus(w) === null
           && S110.feld('wMastY').wertAus(w) === null,
           `Maske ${S110.feld('wMast').wertAus(w)} / ${S110.feld('wMastY').wertAus(w)}`);
      const h = CH110.hinweise(erg.modell).join(' ');
      wahr('… und die Anwendung sagt es laut',
           /Mastwind fehlt/.test(h) && /unsicheren Seite/.test(h),
           h.slice(0, 60) || 'kein Hinweis');
    } finally {
      // Der Prüfstand darf nicht mit halb geleerter Datenbasis weiterlaufen.
      DM110.setzeMastenDB(gesichert);
    }
    wahr('Das Sortiment steht danach wieder', DM110.mastenDbDa()
         && DM110.mastWind('HEB 220', 'EK1', 'jochachse') === 0.28,
         'HEB 220 EK1 = ' + DM110.mastWind('HEB 220', 'EK1', 'jochachse'));
  }

  /* =====================================================================
   * b) EIN TEIL UEBER DER MASTSPITZE WIRD GEBAUT (20. September)
   * ===================================================================
   * Weisung: «lasten oberhalb mastspitze zulassen.»
   *
   * Hier stand der Befund davor: der Nachweis rechnete es auf einem
   * Hebelarm, den das Modell nicht kannte - die Ausleitung liess es weg
   * und vermerkte es. Jetzt bauen beide dasselbe: ein starres Stueck
   * ueber der Spitze traegt die Last, und der Hinweis sagt, dass dort
   * kein Mastprofil mehr steht.
   */
  {
    const { s, erg } = rechne110(einzelmast({ laenge: 8, hMast: 9.0 }));
    const dat = datei110(s, erg);
    const h = CH110.hinweise(erg.modell).join(' ');
    wahr('Teil ueber der Mastspitze: die Anwendung nennt es',
         /über der Mastspitze/.test(h) && /zugelassen/.test(h),
         h.slice(0, 80) || 'kein Hinweis');
    wahr('… und nichts faellt aus der Datei',
         (dat.tragwerk.anbauMastAus ?? []).length === 0,
         JSON.stringify(dat.tragwerk.anbauMastAus));
    const auf = dat.staebe.filter((x) => /^MASTAUFSATZ_/.test(x.name));
    pruef('… ein starres Stueck traegt die Last', auf.length, 1, 1e-12, 'Stk');
    wahr('… und es ist wirklich starr, kein Mastprofil',
         auf[0].art === 'starr', `${auf[0].art} / ${auf[0].querschnitt}`);
    const drin = rechne110(einzelmast({ laenge: 12, hMast: 9.0 }));
    const hd = CH110.hinweise(drin.erg.modell).join(' ');
    wahr('… und kein Hinweis, wenn es unter der Spitze sitzt',
         !/über der Mastspitze/.test(hd)
         && (datei110(drin.s, drin.erg).tragwerk.anbauMastAus ?? []).length === 0,
         'Mast 12 m, Teil auf 9 m');
  }

  /* =====================================================================
   * b2) DIE MASTVERLAENGERUNG MIT ROHR (Klarstellung vom 24. September)
   * ===================================================================
   * «der anschlusspunkt liegt innerhalb der mastlänge, aber es sollte dann
   * möglich sein die z koordinate des anbauteils oberhalb der mastspitze
   * anzusetzen (Mastverlängerung mit Rohr)»
   *
   * Das ist der Fall, um den es wirklich geht - und er laeuft ueber einen
   * ganz anderen Weg als b): die Wurzel der Kette sitzt am Masten, das
   * Rohr ist ein GLIED DER KETTE auf der Mastachse (seit der Folge z, y,
   * x vom 20. September laeuft es lotrecht hinauf). Kein `MASTAUFSATZ`.
   * ===================================================================== */
  {
    // Das Modul steigt ueber die Spitze - das Rohr. Gesetzt wird ueber
    // `setzeAnbauteileAn`: ein Blattsatz fuehrt die Teile am aktiven
    // Tragwerk, und ein Griff in `w.anbauteile` erreicht sie nicht.
    const teilR = A110.neuesAnbauteil('leiter-traverse', 0);
    const roh = C110.setzeAnbauteileAn(einzelmast({ laenge: 8.5 }), [{
      ...teilR, hMast: 8.0, ort: 'mastA',
      module: (teilR.module ?? []).map((m) => ({ ...m, z: (m.z ?? 0) + 1.5 })) }]);
    const { s: sR, erg: eR } = rechne110(roh);
    const dR = datei110(sR, eR);
    const fuss = dR.knoten.find((k) => k.name === 'MAST_A_F').z;
    const hoch = dR.knoten.filter((k) => k.z - fuss > 8.5 + 1e-9);
    wahr('Rohr: der Lastpunkt steht ueber der Spitze', hoch.length > 0,
         hoch.map((k) => `${k.name} ${(k.z - fuss).toFixed(2)} m`).join(' '));
    const namen = new Set(hoch.map((k) => k.name));
    wahr('… und seine Lasten stehen dort',
         (dR.lasten.punkt ?? []).some((q) => namen.has(q.knoten)),
         `${(dR.lasten.punkt ?? []).filter((q) => namen.has(q.knoten)).length} Punktlasten`);
    wahr('… der Mast selbst endet an seiner Spitze',
         dR.staebe.filter((x) => /^MAST_A_S\d+$/.test(x.name))
           .every((x) => dR.knoten.find((k) => k.name === x.bis).z - fuss <= 8.5 + 1e-9));
    wahr('… kein MASTAUFSATZ - das Rohr ist ein Glied der Kette',
         dR.staebe.every((x) => !/MASTAUFSATZ/.test(x.name))
         && dR.staebe.some((x) => /^ARMM/.test(x.name)));
    wahr('… nichts faellt aus dem Modell',
         (dR.tragwerk.anbauMastAus ?? []).length === 0);
    const hR = CH110.hinweise(eR.modell).join(' ');
    wahr('… und der Hinweis nennt die Mastverlaengerung',
         /über der Mastspitze/.test(hR) && /Rohr/.test(hR),
         hR.slice(0, 90) || 'kein Hinweis');
    /* =====================================================================
     * >>> UND DAS ROHR IST EIN ANBAUTEIL (Weisung vom 24. September). <<<
     * ===================================================================
     * «rohr / Mastaufsatz selbst ist als anbauteil zu verstehen, keine
     * Ausnutzung bestimmen von diesen bauteilen.»
     *
     * Der Hinweis sagte bis hierher «das Rohr selbst ist nicht
     * nachgewiesen» - das las sich wie ein Mangel. Er ist keiner: ein
     * Anbauteil ist nicht Gegenstand des Nachweises, sondern der Weg, auf
     * dem die Last ans Tragwerk kommt.
     *
     * GEMESSEN, NICHT BEHAUPTET: im Urteil stehen Joch, Mast und Anker -
     * kein Anbauteil. Diese Wache schlaegt an, sobald eines hineinkaeme.
     */
    wahr('Der Hinweis nennt es ein Anbauteil, keinen Mangel',
         /Anbauteil/.test(hR) && !/nicht nachgewiesen/.test(hR),
         (hR.split(' – ').pop() ?? '').slice(0, 80));
    {
      const u = CH110.bauteilUrteil(eR, null, 'einzelmast');
      const erlaubt = new Set(['joch', 'mast', 'anker']);
      wahr('Im Urteil steht kein Anbauteil',
           u.liste.every((b) => erlaubt.has(b.key)),
           u.liste.map((b) => `${b.key}/${b.name}`).join(' · ') || 'leer');
      // Und es traegt auch keinen Namen aus der Baugruppe.
      wahr('… und keiner seiner Namen taucht darin auf',
           u.liste.every((b) => !/Traverse|Leiter|Rohr|Ausleger/.test(b.name)),
           u.liste.map((b) => b.name).join(' · '));
    }
  }

  /* =====================================================================
   * c) AUF DEM BLATT BLEIBT G GETRENNT - UND DIE LAGE STIMMT
   * ===================================================================
   * Gefunden beim Durchlauf: sobald ein zweites Tragwerk dastand, lag das
   * Gewicht eines Anbauteils in `G` statt in `G_Anbau` (die COM-Ausleitung
   * nahm die Lasten des fertigen Blattmodells, und die waren ohne
   * `gTrennen` gebaut). Die Bemessung aenderte das nicht, die
   * charakteristischen Einzelfaelle schon.
   */
  {
    const jeFall = (dat) => {
      const z = {};
      [...(dat.lasten.punkt ?? []), ...(dat.lasten.moment ?? [])]
        .forEach((l) => { z[l.lastfall] = (z[l.lastfall] ?? 0) + 1; });
      return z;
    };
    const allein = einzelmast({ laenge: 12, hMast: 9.0 });
    const a1 = rechne110(allein);
    const zAllein = jeFall(datei110(a1.s, a1.erg));

    const blatt = C110.tragwerkHinzu(allein, 'joch',
      { L: 18, xLage: 25, typ: 'J90', mastVorhanden: true });
    const b1 = rechne110(blatt);
    const zBlatt = jeFall(datei110(b1.s, b1.erg));
    wahr('Auf dem Blatt bleibt die Anbaulast in G_Anbau',
         (zAllein.G_Anbau ?? 0) > 0 && (zBlatt.G_Anbau ?? 0) >= (zAllein.G_Anbau ?? 0)
         && !(zBlatt.G > 0 && !(zAllein.G > 0)),
         `allein ${JSON.stringify(zAllein)} · Blatt ${JSON.stringify(zBlatt)}`);

    /* Drei Einzelmasten: eigene Fuesse, eigene Profile, richtige Lage. */
    let drei = einzelmast({ laenge: 12, profil: 'HEB 260' });
    drei = C110.tragwerkHinzu(drei, 'einzelmast',
      { xLage: 10, mastProfil: 'HEB 220', mastLaenge: 10 });
    drei = C110.tragwerkHinzu(drei, 'einzelmast',
      { xLage: 25, mastProfil: 'HEM 240', mastLaenge: 14 });
    const d3 = rechne110(drei);
    const dat3 = datei110(d3.s, d3.erg);
    const fuesse = dat3.auflager.filter((a) => a.modell === 'mast');
    const kn3 = new Map(dat3.knoten.map((k) => [k.name, k]));
    wahr('Drei Einzelmasten: drei eigene Fuesse',
         fuesse.length === 3, fuesse.map((a) => a.knoten).join(', '));
    // Das Feld `x` des Auflagers blieb beim oertlichen Nullpunkt stehen -
    // in der Datei stand x = 0 fuer einen Masten weit draussen.
    const schief = fuesse.filter((a) => Math.abs(a.x - (kn3.get(a.knoten)?.x ?? 0)) > 1e-9);
    wahr('… und ihr Auflager nennt die Lage des Blattes',
         schief.length === 0,
         schief.length ? schief.map((a) => `${a.knoten}: Feld ${a.x} gegen Knoten `
           + kn3.get(a.knoten)?.x).join(' · ')
           : fuesse.map((a) => a.x).join(', '));
    const profile = new Set(dat3.querschnitte.filter((q) => /^MAST_/.test(q.name))
      .map((q) => q.name));
    wahr('… und jeder sein eigenes Profil', profile.size === 3,
         [...profile].join(', '));
  }
}


titel('111  Stabwerksloeser (core.stabwerk.js)');
/*
 * Schritt 2 des Bauplans vom 19. September. Der Loeser frisst das Modell,
 * das `stabmodellJson` ohnehin fuer AxisVM schreibt - ein Modellbauer fuer
 * alle Wege.
 *
 * ER HAENGT AN KEINEM NACHWEIS. Diese Kontrollen pruefen ihn fuer sich:
 * zuerst gegen geschlossene Loesungen (dort muss die Zahl EXAKT stimmen,
 * sonst ist das Element falsch), dann am wirklichen Jochmodell gegen das
 * Gleichgewicht.
 */
{
  const FEM = await import(J('core.stabwerk.js'));
  const V111 = await import(J('core.vierendeel.js'));
  const AX111 = await import(J('export.axisvm.js'));
  const NB111 = await import(J('core.nachbarn.js'));

  const E = 210000, G = 81000;          // N/mm2, wie in der Datei
  const Ek = E * 1000, Gk = G * 1000;   // kN/m2
  const FEST = { ux: 'Rigid', uy: 'Rigid', uz: 'Rigid',
                 fix: 'Rigid', fiy: 'Rigid', fiz: 'Rigid' };
  const REC = (name, b, h) => ({ name, form: 'Rectangle', parameter: [b, h],
                                 A: null, Iy: null, Iz: null, It: null });
  const modell111 = (o) => ({
    material: { E, G }, materialSteif: { faktor: 1000 },
    querschnitte: o.qs, knoten: o.knoten, staebe: o.staebe, auflager: o.auflager,
    lastfaelle: [{ key: 'L', label: 'L', art: 'Others' }],
    lasten: { punkt: o.punkt ?? [], moment: o.moment ?? [], strecke: o.strecke ?? [] },
    kombinationen: [],
  });

  /* Rechteck 100 x 200 mm: b in lokaler y, h in lokaler z. */
  const b0 = 0.1, h0 = 0.2;
  const A0 = b0 * h0;
  const Iy0 = (b0 * h0 ** 3) / 12;      // Biegung in der x-z-Ebene
  const Iz0 = (h0 * b0 ** 3) / 12;      // Biegung in der x-y-Ebene
  const L0 = 4, F0 = 10;
  const kragarm = {
    qs: [REC('R', 100, 200)],
    knoten: [{ name: 'A', x: 0, y: 0, z: 0 }, { name: 'B', x: L0, y: 0, z: 0 }],
    staebe: [{ name: 'S', von: 'A', bis: 'B', querschnitt: 'R', art: 'stab',
               lcsZ: [0, 0, 1] }],
    auflager: [{ knoten: 'A', ...FEST }],
  };
  const uVon = (r, kn, dof) => r.u.get('L')[r.knotenIdx.get(kn) * 6 + dof];

  // --- a) Kragarm: jede Steifigkeit einzeln ------------------------------
  {
    let r = FEM.loese(modell111({ ...kragarm,
      punkt: [{ knoten: 'B', richtung: 'Z', wert: -F0, lastfall: 'L' }] }));
    pruef('Kragarm, Last z: Durchbiegung', uVon(r, 'B', 2),
          -(F0 * L0 ** 3) / (3 * Ek * Iy0), 1e-12, 'm');
    pruef('… Einspannmoment M_y', r.auflagerkraefte('L')[0].fiy, -F0 * L0, 1e-9, 'kNm');

    r = FEM.loese(modell111({ ...kragarm,
      punkt: [{ knoten: 'B', richtung: 'Y', wert: F0, lastfall: 'L' }] }));
    pruef('Kragarm, Last y: Verschiebung', uVon(r, 'B', 1),
          (F0 * L0 ** 3) / (3 * Ek * Iz0), 1e-12, 'm');

    r = FEM.loese(modell111({ ...kragarm,
      punkt: [{ knoten: 'B', richtung: 'X', wert: F0, lastfall: 'L' }] }));
    pruef('Kragarm, Laengskraft', uVon(r, 'B', 0), (F0 * L0) / (Ek * A0), 1e-12, 'm');

    const It0 = FEM.qsWerte(REC('R', 100, 200)).It;
    r = FEM.loese(modell111({ ...kragarm,
      moment: [{ knoten: 'B', richtung: 'Mx', wert: 5, lastfall: 'L' }] }));
    pruef('Kragarm, Torsion', uVon(r, 'B', 3), (5 * L0) / (Gk * It0), 1e-12, 'rad');

    const q0 = 3;
    r = FEM.loese(modell111({ ...kragarm,
      strecke: [{ stab: 'S', richtung: 'Z', wert: -q0, lastfall: 'L' }] }));
    pruef('Kragarm, Gleichlast: Durchbiegung', uVon(r, 'B', 2),
          -(q0 * L0 ** 4) / (8 * Ek * Iy0), 1e-12, 'm');
    pruef('… und M am Fuss', r.auflagerkraefte('L')[0].fiy,
          -(q0 * L0 ** 2) / 2, 1e-9, 'kNm');
    wahr('… das freie Ende bleibt momentfrei',
         Math.abs(r.stabkraft('L').get('S')[10]) < 1e-9);
  }

  // --- b) Einfeldtraeger, Rahmen, Drehfeder ------------------------------
  {
    const q1 = 5, Ls = 6;
    const r = FEM.loese(modell111({
      qs: [REC('R', 100, 200)],
      knoten: [{ name: 'A', x: 0, y: 0, z: 0 }, { name: 'M', x: Ls / 2, y: 0, z: 0 },
               { name: 'B', x: Ls, y: 0, z: 0 }],
      staebe: [{ name: 'S1', von: 'A', bis: 'M', querschnitt: 'R', art: 'stab', lcsZ: [0, 0, 1] },
               { name: 'S2', von: 'M', bis: 'B', querschnitt: 'R', art: 'stab', lcsZ: [0, 0, 1] }],
      auflager: [
        { knoten: 'A', ux: 'Rigid', uy: 'Rigid', uz: 'Rigid', fix: 'Rigid', fiy: 'Free', fiz: 'Free' },
        { knoten: 'B', ux: 'Free', uy: 'Rigid', uz: 'Rigid', fix: 'Rigid', fiy: 'Free', fiz: 'Free' }],
      strecke: [{ stab: 'S1', richtung: 'Z', wert: -q1, lastfall: 'L' },
                { stab: 'S2', richtung: 'Z', wert: -q1, lastfall: 'L' }],
    }));
    pruef('Einfeldtraeger: w in Feldmitte', uVon(r, 'M', 2),
          -(5 * q1 * Ls ** 4) / (384 * Ek * Iy0), 1e-12, 'm');
    pruef('… M in Feldmitte', -r.stabkraft('L').get('S1')[10],
          (q1 * Ls ** 2) / 8, 1e-9, 'kNm');
    pruef('… Auflagerkraft', r.auflagerkraefte('L')[0].uz, (q1 * Ls) / 2, 1e-9, 'kN');
  }
  {
    // Eingespannter Stiel mit Kragriegel: das Moment geht um die Ecke.
    const Fr = 8, hS = 5, lR = 3;
    const r = FEM.loese(modell111({
      qs: [REC('R', 200, 200)],
      knoten: [{ name: 'F', x: 0, y: 0, z: 0 }, { name: 'K', x: 0, y: 0, z: hS },
               { name: 'E', x: lR, y: 0, z: hS }],
      staebe: [{ name: 'ST', von: 'F', bis: 'K', querschnitt: 'R', art: 'stab', lcsZ: [1, 0, 0] },
               { name: 'RI', von: 'K', bis: 'E', querschnitt: 'R', art: 'stab', lcsZ: [0, 0, 1] }],
      auflager: [{ knoten: 'F', ...FEST }],
      punkt: [{ knoten: 'E', richtung: 'Z', wert: -Fr, lastfall: 'L' }],
    }));
    const a = r.auflagerkraefte('L')[0];
    pruef('Rahmen: Auflagerkraft lotrecht', a.uz, Fr, 1e-9, 'kN');
    pruef('… Einspannmoment am Fuss', a.fiy, -Fr * lR, 1e-9, 'kNm');
    pruef('… Normalkraft im Stiel', r.stabkraft('L').get('ST')[0], Fr, 1e-9, 'kN');
  }
  {
    const Fd = 12, c = 4000;   // kNm/rad
    const r = FEM.loese(modell111({ ...kragarm,
      auflager: [{ knoten: 'A', ux: 'Rigid', uy: 'Rigid', uz: 'Rigid',
                   fix: 'Rigid', fiy: 'Flexible', fiz: 'Rigid', cFiy_kNm: c }],
      punkt: [{ knoten: 'B', richtung: 'Z', wert: -Fd, lastfall: 'L' }] }));
    pruef('Drehfeder am Auflager', uVon(r, 'B', 2),
          -((Fd * L0 ** 3) / (3 * Ek * Iy0) + ((Fd * L0) / c) * L0), 1e-11, 'm');
  }

  // --- c) Das Linkelement --------------------------------------------------
  {
    /*
     * Der Link liegt laengs y: seine lokale x-Achse ist global y, also
     * haelt «xx: Rigid» die BIEGEVERDREHUNG des Kragarms. z bleibt frei -
     * senkrecht traegt nur der Kragarm, aber mit gefuehrtem Ende:
     * w = F L^3 / (12 E I) statt / (3 E I).
     */
    const Fl = 6;
    const r = FEM.loese(modell111({
      qs: [REC('R', 100, 200), REC('STARR', 500, 500)],
      knoten: [{ name: 'A', x: 0, y: 0, z: 0 }, { name: 'B', x: 4, y: 0, z: 0 },
               { name: 'C', x: 4, y: 0.05, z: 0 }],
      staebe: [{ name: 'S', von: 'A', bis: 'B', querschnitt: 'R', art: 'stab', lcsZ: [0, 0, 1] },
               { name: 'LK', von: 'B', bis: 'C', querschnitt: 'STARR', art: 'link',
                 lcsZ: [0, 0, 1],
                 kraftuebertragung: { x: 'Rigid', y: 'Rigid', z: 'Free',
                                      xx: 'Rigid', yy: 'Free', zz: 'Free' } }],
      auflager: [{ knoten: 'A', ...FEST }, { knoten: 'C', ...FEST }],
      punkt: [{ knoten: 'B', richtung: 'Z', wert: -Fl, lastfall: 'L' }],
    }));
    // Toleranz 1e-4: «Rigid» ist im Link eine ZAHL (LINK_STARR), kein
    // Zwang - der Rest ist das Verhaeltnis zur Stabsteifigkeit (1e-5).
    pruef('Link: z frei, Ende gefuehrt', uVon(r, 'B', 2),
          -(Fl * 4 ** 3) / (12 * Ek * Iy0), 1e-4, 'm');
    wahr('… und das zweite Auflager traegt lotrecht nichts',
         Math.abs(r.auflagerkraefte('L')[1].uz) < 1e-6);
  }

  // --- d) Am wirklichen Jochmodell: das Gleichgewicht ----------------------
  /*
   * Die geschlossenen Faelle oben sind klein und gut konditioniert. Das
   * Joch ist es nicht: 483 Starrelemente, das kuerzeste 11 mm lang. Erst
   * Jacobi-Skalierung und Nachiteration holen die Stellen zurueck - ohne
   * sie lag das Gleichgewicht um bis zu 46 % daneben (20. September).
   */
  {
    let w111 = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
    w111.L = 20; w111.xLage = 0; w111.mastVorhanden = true;
    const satz = NB111.rechensatzMitNachbarn(w111);
    const erg = berechne(satz, getProfil(satz.profOG), getProfil(satz.profUG),
                         getStahl(satz.stahl), T.getTragjoch(satz.typ));
    const m = V111.modell({ ...satz, beiwerteFest: null }, erg.modell.profOG,
                          erg.modell.profUG, erg.modell.stahl, erg.modell.joch);
    const dat = AX111.stabmodellJson(m, { knotenmodell: 'anschnitt',
                                          auflagerModell: 'mast', eingabe: satz });
    const r = FEM.loese(dat);
    wahr('Das Jochmodell laesst sich zerlegen',
         r.n > 1000, `${r.n} Freiheitsgrade · Bandbreite ${r.bw}`);

    const kn = new Map(dat.knoten.map((k) => [k.name, k]));
    const st = new Map(dat.staebe.map((x) => [x.name, x]));
    const lastsumme = (fall) => {
      const s2 = { X: 0, Y: 0, Z: 0 };
      (dat.lasten.punkt ?? []).filter((l) => l.lastfall === fall)
        .forEach((l) => { s2[l.richtung] += l.wert; });
      (dat.lasten.strecke ?? []).filter((l) => l.lastfall === fall).forEach((l) => {
        const bb = st.get(l.stab);
        const p1 = kn.get(bb.von), p2 = kn.get(bb.bis);
        s2[l.richtung] += l.wert * Math.hypot(p2.x - p1.x, p2.y - p1.y, p2.z - p1.z);
      });
      return s2;
    };
    let schlimm = 0; let woFall = '';
    dat.lastfaelle.forEach((lf) => {
      const p = lastsumme(lf.key);
      const a = r.auflagerkraefte(lf.key);
      const sum = { X: a.reduce((t, x) => t + x.ux, 0),
                    Y: a.reduce((t, x) => t + x.uy, 0),
                    Z: a.reduce((t, x) => t + x.uz, 0) };
      const gross = Math.max(Math.abs(p.X), Math.abs(p.Y), Math.abs(p.Z));
      if (gross < 1e-9) return;
      const abw = Math.max(...['X', 'Y', 'Z'].map((d) => Math.abs(p[d] + sum[d]))) / gross;
      if (abw > schlimm) { schlimm = abw; woFall = lf.key; }
    });
    wahr('Kraftgleichgewicht in jedem Lastfall',
         schlimm < 1e-8, `groesste Abweichung ${(schlimm * 100).toExponential(2)} %`
         + (woFall ? ` (${woFall})` : ''));
    /*
     * DER REST DER GLEICHUNG - RELATIV, NICHT ABSOLUT.
     *
     * K*u - p ueber die freien Freiheitsgrade muss null sein. Wie klein
     * «null» hier werden kann, gibt die Konditionierung vor und nicht
     * der Loeser: ein 11 mm langes Starrelement traegt 12EI/L^3 = 1e17
     * bei, ein Gurtstab 1.2e4 - schon das Aufsummieren von K*u kostet
     * die letzten Stellen. Gemessen am J90/20 m (Nachiterationen 0..12):
     *
     *     0 -> 4.76e-3 kN   1 -> 3.71e-3   2 -> 4.47e-3   3 -> 4.15e-3
     *     5 -> 4.57e-3      8 -> 3.59e-3  12 -> 3.68e-3 kN
     *
     * Es SINKT NICHT WEITER, es rauscht um 1e-4 der groessten Knoten-
     * kraft. Eine absolute Schranke (frueher 1e-6 kN) misst darum nicht
     * den Loeser, sondern die Groesse des Modells. Gemessen wird deshalb
     * gegen `bezug` - den groessten Betrag in K*u. Dass die Loesung
     * trotzdem stimmt, sagt die Kontrolle darueber: das Gleichgewicht
     * der Auflagerkraefte stimmt auf 1e-7 %.
     */
    {
      const q = r.restkraft('WindY');
      wahr('… und der Rest verschwindet gegen die Knotenkraefte',
           q.gross / q.bezug < 1e-3,
           `${(q.gross / q.bezug).toExponential(2)} von ${q.bezug.toFixed(1)} kN`
           + ` (${q.gross.toExponential(2)} kN bei ${q.wo})`);
    }

    /*
     * DIE ANTWORT HAENGT NICHT AN DER ERSATZSTEIFIGKEIT. Gemessen von
     * Faktor 1 bis 10 - fuenf gleiche Stellen. Das ist die eigentliche
     * Rechtfertigung fuer den kleinen Wert.
     */
    const ry = (f) => FEM.loese(dat, { starrFaktor: f }).auflagerkraefte('WindY')[0].uy;
    const r1 = ry(1), r10 = ry(10);
    wahr('Die Loesung haengt nicht am Starrfaktor (1 gegen 10)',
         Math.abs(r1 - r10) / Math.abs(r1) < 1e-5,
         `${r1.toFixed(5)} gegen ${r10.toFixed(5)} kN`);
  }
}


titel('112  Leiter: durchgehend, beidseitig oder einseitig abgefangen');
/* ===========================================================================
 * Weisung vom 24. September, im Wortlaut:
 *
 *   «Die leiter koenen als durchgehend / beidseiig abgefangen / einseitig
 *    abgefangen definiert werden. bei den durchgehenden wid ein 10% anteil
 *    beim Leiterriss gerechnet. bei den beidseitig abgefangenen wid der
 *    volle leiterzug einseitig angesezt und beim einseitg abgefangenen,
 *    hebt sich der leiterzug auf, dies kann bei mehreren abfangungen an
 *    einem abfangtraeger zu unguenstigen lastfaellen dann fuehren, die
 *    massgebend sein koennen.»
 *
 * Rueckgefragt und bestaetigt: der Leiterzug wirkt auch STAENDIG, und die
 * Wahl gilt allen vier Tragwerksarten.
 * ========================================================================= */
{
  const A112 = await import(J('data.anbauteile.js'));
  const L112 = await import(J('core.lasten.js'));
  const C112 = await import(J('core.constants.js'));
  const V112 = await import(J('core.vierendeel.js'));
  const N112 = await import(J('core.nachbarn.js'));
  const FL112 = await import(J('data.fl.js'));

  // --- a) Die Anteile je Art, gegen die Reglagetabelle -------------------
  const id = 'drahtwerk-n-fl-ts-stcu-50-fd-cu-107';
  const Z5 = FL112.leiterzug(id);
  const Z20 = FL112.abfangkraft(id, { tempFall: 'havarie' }).Z;
  pruef('N-FL: Zug bei +5 °C', Z5, 14.9, 1e-9, 'kN');
  pruef('N-FL: Zug bei -20 °C', Z20, 16.5, 1e-9, 'kN');
  const an = (art, o = {}) => A112.havarieAnteile({ id, art, ...o });
  {
    // DURCHGEHEND: staendig nichts, beim Riss 10 %.
    pruef('durchgehend: kein staendiger Laengszug', an('durchgehend').Gy, 0, 1e-12, 'kN');
    pruef('… beim Riss 10 % von Z(-20 °C)',
          an('durchgehend', { bruch: true }).Fy, 0.1 * Z20, 1e-9, 'kN');
    // BEIDSEITIG: staendig heben sich die Zuege auf, beim Riss der volle.
    pruef('beidseitig: kein staendiger Laengszug', an('beidseitig').Gy, 0, 1e-12, 'kN');
    pruef('… beim Riss der VOLLE Zug einseitig',
          an('beidseitig', { bruch: true }).Fy, Z20, 1e-9, 'kN');
    // EINSEITIG: staendig der volle Zug, beim Riss faellt er weg.
    pruef('einseitig: staendig der volle Zug bei +5 °C', an('einseitig').Gy, Z5, 1e-9, 'kN');
    pruef('… beim Riss faellt genau er weg',
          an('einseitig', { bruch: true }).Fy, -Z5, 1e-9, 'kN');
    pruef('… und ohne Riss waechst er auf Z(-20 °C)',
          an('einseitig').Fy, Z20 - Z5, 1e-9, 'kN');
    // Die Richtung spiegelt alles.
    const m = an('einseitig', { richtung: -1 });
    pruef('… in -y kehrt sich alles um', m.Gy, -Z5, 1e-9, 'kN');
    wahr('… und der Betrag bleibt derselbe',
         Math.abs(m.Fy + (Z20 - Z5)) < 1e-9, `${m.Fy}`);
  }
  // Ein alter Stand kennt keine Art - er rechnet weiter wie bisher.
  wahr('Ohne Angabe gilt «durchgehend»',
       Math.abs(A112.havarieAnteile({ id, bruch: true }).Fy - 0.1 * Z20) < 1e-9
       && L112.ABFANG_VORGABE === 'durchgehend');

  // --- b) Am Tragwerk: was jede Art bewirkt ------------------------------
  const bau = (art, ri) => {
    let w = { ...standardwerte(), tragwerksart: 'einzelmast', mastLaenge: 8.5,
              L: 0, xLage: 0, mastVorhanden: true };
    w = C112.setzeAnbauteileAn(w, [{ ...A112.neuesAnbauteil('mast-nt-ausleger', 0),
                                     ort: 'mastA', hMast: 7.0 }]);
    const l = A112.leiterListe(C112.rechensatz(w).anbauteile ?? [])[0];
    return { ...w, havarie: { [l.key]: { reisst: true, name: l.name,
      ...(art !== 'durchgehend' ? { art } : {}), ...(ri ? { richtung: ri } : {}) } } };
  };
  const etas = (art, ri) => {
    const s2 = N112.rechensatzMitNachbarn(bau(art, ri));
    const v = V112.vergleichKombinationen(s2, ...N112.kernArgumente(s2));
    const e = (k) => v.ergebnisse[k]?.mast?.A?.etaMitStabilitaet ?? 0;
    const bruch = v.lastfaelle.filter((z) => z.key.startsWith('havarie|'));
    const wind = v.lastfaelle.filter((z) => z.nachweis && /wind/i.test(z.key));
    return { wind: Math.max(...wind.map((z) => e(z.key)), 0),
             bruch: Math.max(...bruch.map((z) => e(z.key)), 0) };
  };
  {
    const dg = etas('durchgehend');
    const bs = etas('beidseitig');
    const es = etas('einseitig', '+y');
    /*
     * DER ALTE STAND BLEIBT DER ALTE. «durchgehend» rechnet, was die
     * Anwendung seit dem 17. September rechnet - daran darf sich durch
     * die neue Wahl nichts aendern.
     */
    wahr('durchgehend: staendig ohne Laengszug, der Riss bleibt klein',
         Math.abs(dg.wind - 0.2704) < 5e-3 && Math.abs(dg.bruch - 0.9345) < 5e-3,
         `Wind ${dg.wind.toFixed(4)} · Riss ${dg.bruch.toFixed(4)}`);
    wahr('beidseitig: staendig gleich, der Riss aber zehnmal so gross',
         Math.abs(bs.wind - dg.wind) < 1e-9 && bs.bruch > 9 * dg.bruch,
         `Wind ${bs.wind.toFixed(4)} · Riss ${bs.bruch.toFixed(4)}`);
    /*
     * >>> UND HIER ZIEHT ER SCHON STAENDIG. <<<
     * Ein einseitig abgefangener Leiter an einem Masten ohne Gegenzug
     * erzeugt ein Moment, das der Mast allein nicht traegt - genau
     * deshalb steht dort in der Praxis ein Anker. Der Riss ENTLASTET.
     */
    wahr('einseitig: staendig gross, der Riss entlastet',
         es.wind > 10 * dg.wind && es.bruch < 0.2 * dg.bruch,
         `Wind ${es.wind.toFixed(4)} · Riss ${es.bruch.toFixed(4)}`);
  }

  // --- c) Zwei Abfangungen, die sich aufheben ----------------------------
  /* =====================================================================
   * >>> DER FALL, VON DEM DIE WEISUNG SPRICHT. <<<
   * «dies kann bei mehreren abfangungen an einem abfangtraeger zu
   *  unguenstigen lastfaellen dann fuehren, die massgebend sein koennen.»
   * ===================================================================== */
  {
    let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
    w.L = 20; w.xLage = 0; w.mastVorhanden = true;
    w = C112.setzeAnbauteileAn(w, [
      { ...A112.neuesAnbauteil('hs-fahrdraht', 7), name: 'FL Gleis 1' },
      { ...A112.neuesAnbauteil('hs-fahrdraht', 13), name: 'FL Gleis 2' }]);
    const leiter = A112.leiterListe(C112.rechensatz(w).anbauteile ?? []);
    const hav = {};
    leiter.forEach((l, i) => { hav[l.key] = { reisst: true, name: l.name,
      art: 'einseitig', richtung: i === 0 ? '+y' : '-y' }; });
    const s2 = N112.rechensatzMitNachbarn({ ...w, havarie: hav });
    const v = V112.vergleichKombinationen(s2, ...N112.kernArgumente(s2));
    const fy = (k) => (v.ergebnisse[k]?.modell?.anbauteileFlach ?? [])
      .reduce((a2, t) => a2 + (t.kraefte?.G?.Fy ?? 0) + (t.kraefte?.HavarieY?.Fy ?? 0), 0);
    const wind = v.lastfaelle.find((z) => z.nachweis && /wind/i.test(z.key));
    pruef('Zwei entgegengesetzte Abfangungen heben sich auf', fy(wind.key), 0, 1e-9, 'kN');
    const bruch = v.lastfaelle.filter((z) => z.key.startsWith('havarie|'));
    wahr('… der Riss laesst den vollen Zug der anderen Seite stehen',
         bruch.every((z) => Math.abs(Math.abs(fy(z.key)) - 16.5) < 1e-9),
         bruch.map((z) => fy(z.key).toFixed(2)).join(' / '));
    const eta = (k) => v.ergebnisse[k]?.mast?.A?.etaMitStabilitaet ?? 0;
    wahr('… und einer dieser Faelle wird massgebend',
         Math.max(...bruch.map((z) => eta(z.key)))
           > Math.max(...v.lastfaelle.filter((z) => z.nachweis
               && !z.key.startsWith('havarie')).map((z) => eta(z.key))) * 0.8,
         `Riss ${Math.max(...bruch.map((z) => eta(z.key))).toFixed(4)}`);
  }

  // --- d) Die Karte zeigt die Zahl, nicht nur den Prozentsatz ------------
  /*
   * Frage vom 24. September: «wo sieht man den lastanteil beim
   * havariefall?» - bis dahin stand dort der Prozentsatz als Satz, aber
   * nicht, wieviel das an diesem Leiter ist.
   */
  {
    const ui112 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Die Havarie-Karte fuehrt Abfangung und Richtung',
         ui112.includes("data-hav=\"art\"") && ui112.includes("data-hav=\"richtung\""));
    wahr('… und die Kraefte als Zahl, aus derselben Funktion wie der Kern',
         ui112.includes('havarieAnteile({ id: bt'));
    // Die Bauteil-Id reist dafuer mit der Leiterliste mit.
    const l0 = A112.leiterListe([{ ...A112.neuesAnbauteil('hs-fahrdraht', 5), aktiv: true }])[0];
    wahr('… die Leiterliste nennt den Tabelleneintrag',
         Boolean(l0.teile[0].bauteilId), l0.teile[0].bauteilId ?? '-');
  }

  // --- e) Zuganker und Druckstuetze --------------------------------------
  /* =====================================================================
   * Frage vom 24. September: «wie wirken sich die abfangungen und der
   * havariefall auf die zuganker und Druckstuezen aus?»
   *
   * Die Antwort war ein Befund: der staendige Zug einer Abfangung kam
   * voll am Anker an, der HAVARIEFALL aber nicht - `ankerAuswertung`
   * nahm nur die charakteristischen Faelle. Am ABFANGJOCH war er immer
   * dabei (er ist einer der drei Faelle dort). Dieselbe Abspannung wurde
   * also je nach Tragwerksart verschieden nachgewiesen.
   *
   * Weisung auf Rueckfrage: «Ja, gegen dieselbe zulaessige Kraft.»
   * ===================================================================== */
  {
    const AK112 = await import(J('core.anker.js'));
    const mitAnker = (art, typ, ri) => {
      let w = { ...standardwerte(), tragwerksart: 'einzelmast', mastLaenge: 10,
                L: 0, xLage: 0, mastVorhanden: true };
      w = C112.setzeAnbauteileAn(w, [{ ...A112.neuesAnbauteil('mast-nt-ausleger', 0),
                                       ort: 'mastA', hMast: 8.0 }]);
      w = C112.setzeMastAnker(w, C112.mastenVon(w)[0].id,
        { typ, a: 4.5, h: 7.8, richtung: 'y', seite: 'plus', befestigung: 'ankerplatte' });
      const l = A112.leiterListe(C112.rechensatz(w).anbauteile ?? [])[0];
      const s2 = N112.rechensatzMitNachbarn({ ...w, havarie: { [l.key]: {
        reisst: true, name: l.name,
        ...(art !== 'durchgehend' ? { art } : {}), ...(ri ? { richtung: ri } : {}) } } });
      const v = V112.vergleichKombinationen(s2, ...N112.kernArgumente(s2));
      return { an: AK112.ankerAuswertung(v, s2), v };
    };
    /*
     * >>> DER STAENDIGE ZUG KOMMT VOLL AM ANKER AN. <<<
     * Und die RICHTUNG entscheidet, ob er drueckt oder zieht - beim
     * Seilanker also, ob er ueberhaupt traegt (Entscheid 16. September).
     */
    const ep = mitAnker('einseitig', 'U12', '+y').an;
    const em = mitAnker('einseitig', 'U12', '-y').an;
    pruef('Einseitig +y: der Leiter DRUECKT den Anker', ep.A.kraft.N, -49.54, 0.05, 'kN');
    pruef('Einseitig -y: er ZIEHT ihn', em.A.kraft.N, 49.54, 0.05, 'kN');
    wahr('… und Druck ist der ungleich schaerfere Fall (Knicken)',
         ep.eta > 2 * em.eta, `${ep.eta.toFixed(3)} gegen ${em.eta.toFixed(3)}`);
    {
      const seil = mitAnker('einseitig', 'SA20', '+y').an;
      wahr('Ein Seilanker haengt durch, wo die Stuetze drueckt',
           seil.A.nachweis.grund === 'schlaff' || seil.A.kraft.N >= 0,
           `${seil.A.kraft.N.toFixed(2)} kN · ${seil.A.nachweis.grund ?? '-'}`);
    }
    /* =====================================================================
     * >>> UND DER HAVARIEFALL WIRD NACHGEWIESEN (24. September). <<<
     * Bei BEIDSEITIGER Abfangung entsteht die grosse Ankerkraft ueberhaupt
     * erst beim Riss - vorher stand dort eta 0.064 statt 0.763.
     * =================================================================== */
    const bs = mitAnker('beidseitig', 'U12').an;
    wahr('Beidseitig: der Havariefall ist massgebend',
         /Havarie/.test(bs.A.bez ?? ''), bs.A.bez ?? '-');
    pruef('… mit dem vollen Leiterzug', bs.A.kraft.N, -45.72, 0.05, 'kN');
    wahr('… und eta liegt zehnfach ueber dem Windfall',
         bs.eta > 0.7 && bs.eta < 0.85, `${bs.eta.toFixed(3)}`);
    wahr('Die Fallarten des Ankernachweises stehen an EINER Stelle',
         JSON.stringify(AK112.ANKER_FALLARTEN)
           === JSON.stringify(['charakteristisch', 'aussergewoehnlich']));
    /*
     * Die Tragsicherheits-Faelle bleiben draussen: sie tragen Teil-
     * sicherheitsbeiwerte und gehoeren nicht gegen eine zulaessige Kraft.
     */
    wahr('… und die Tragsicherheits-Faelle bleiben draussen',
         !AK112.ANKER_FALLARTEN.includes('tragsicherheit'));
  }
}

titel('113  Mastverformung im Gebrauchszustand');
/* ===========================================================================
 * Weisung vom 24. September, im Wortlaut:
 *
 *   «Mastfervormung berechnen lassen infolge wind / staendige und deren
 *    kombination. die massgebende werte sind Mastspitze 1:100
 *    (wind+staendige) / 1:200 (nur Wind) und auf hoehe Fahrdraht oder
 *    vereinfacht auf hoehe Ausleger / Jochauflager -> hier ist der
 *    Grenzwert 40mm. Die Gebrauchstauglichkeit kombination ist in diesem
 *    fall der Wind bei 0.70 (Betriebswind Wiederkehrperioda 5 Jahre).»
 *
 * Auf Rueckfrage: die 40 mm QUER zum Gleis, die Spitze in BEIDEN
 * Richtungen; die 40 mm gegen den Fall NUR WIND.
 * ========================================================================= */
{
  const A113 = await import(J('data.anbauteile.js'));
  const C113 = await import(J('core.constants.js'));
  const V113 = await import(J('core.vierendeel.js'));
  const N113 = await import(J('core.nachbarn.js'));
  const VF113 = await import(J('core.verformung.js'));
  const L113 = await import(J('core.lasten.js'));
  const E = 210e6;                       // kN/m2, wie core.auflager.js

  const lauf = (w) => {
    const s2 = N113.rechensatzMitNachbarn(w);
    return V113.vergleichKombinationen(s2, ...N113.kernArgumente(s2));
  };
  const nackt = { ...standardwerte(), tragwerksart: 'einzelmast', mastLaenge: 10,
                  L: 0, xLage: 0, mastVorhanden: true, anbauteile: [] };

  // --- a) Gegen die geschlossene Loesung --------------------------------
  /*
   * DER NACKTE MAST IST EIN KRAGARM MIT GLEICHLAST. Dafuer gibt es eine
   * Formel, und sie ist der Massstab: w = q*L^4 / (8*E*I).
   */
  {
    const v = lauf(nackt);
    const f = v.lastfaelle.find((z) => z.art === 'charakteristisch'
      && /Wind \+y/.test(z.bez ?? ''));
    const g = v.ergebnisse[f.key].mast.A;
    const kopf = g.verformung[g.verformung.length - 1];
    pruef('Der Kopf liegt auf der Mastspitze', kopf.z, g.zKopf, 1e-9, 'm');
    pruef('Kragarm mit Gleichlast: w = q L^4 / 8EI',
          kopf.y, (g.wLaengs * g.zKopf ** 4) / (8 * E * g.Iq), 1e-12, 'm');
    wahr('… und quer bewegt sich nichts, wo kein Querwind steht',
         Math.abs(kopf.x) < 1e-12, `${kopf.x}`);
    pruef('Am Fuss ist die Verformung null', g.verformung[0].y, 0, 1e-12, 'm');
    /*
     * DIE ACHSEN GEHOEREN RICHTIG ZUGEORDNET: quer zum Gleis biegt der
     * Mast ueber `I`, in Gleisrichtung ueber `Iq`. Vertauscht waere die
     * Verformung beim Regelfall (Steg quer) um Faktor 2.9 daneben.
     */
    const fx = v.lastfaelle.find((z) => z.art === 'charakteristisch'
      && /Wind \+x/.test(z.bez ?? ''));
    const gx = v.ergebnisse[fx.key].mast.A;
    const kx = gx.verformung[gx.verformung.length - 1];
    pruef('Querwind biegt ueber die starke Achse I',
          kx.x, (gx.wQuer * gx.zKopf ** 4) / (8 * E * gx.I), 1e-12, 'm');
  }

  // --- b) Die Kombination ----------------------------------------------
  /*
   * >>> STAENDIG + 0.70 MAL WIND, UND ZWAR GERECHNET. <<<
   * Die Verformung ist linear, also muss der Betriebswindfall genau die
   * Summe sein - das prueft, dass die Beiwerte ankommen.
   */
  {
    const teil = A113.neuesAnbauteil('leiter-traverse', 0);
    const w = C113.setzeAnbauteileAn({ ...nackt }, [{ ...teil, ort: 'mastA',
      hMast: 9.0, module: (teil.module ?? []).map((m) => ({ ...m, x: 1.5 })) }]);
    const v = lauf(w);
    const kopfVon = (k) => {
      const g = v.ergebnisse[k]?.mast?.A;
      return g ? g.verformung[g.verformung.length - 1] : null;
    };
    const stG = v.lastfaelle.find((z) => /Ständig \(Tragwerk\)/.test(z.bez ?? ''));
    const wx = v.lastfaelle.find((z) => z.art === 'charakteristisch'
      && /Wind \+x/.test(z.bez ?? ''));
    const bx = v.lastfaelle.find((z) => z.stufe === 'betrieb'
      && /Wind \+x/.test(z.bez ?? ''));
    const g0 = kopfVon(stG.key), w0 = kopfVon(wx.key), b0 = kopfVon(bx.key);
    wahr('Das exzentrische Gewicht biegt schon staendig quer',
         Math.abs(g0.x) > 1e-4, `${(g0.x * 1000).toFixed(2)} mm`);
    pruef('Betriebswind = staendig + 0.70 mal Wind',
          b0.x, g0.x + L113.BETRIEBSWIND * w0.x, 1e-12, 'm');
  }

  // --- c) Die drei Grenzwerte -------------------------------------------
  {
    const teil = A113.neuesAnbauteil('mast-nt-ausleger', 0);
    const w = C113.setzeAnbauteileAn({ ...nackt },
      [{ ...teil, ort: 'mastA', hMast: 8.0 }]);
    const v = lauf(w);
    const n = VF113.verformungsNachweis(v);
    wahr('Der Nachweis steht da', Boolean(n?.A?.nachweise?.length));
    pruef('Drei Nachweise', n.A.nachweise.length, 3, 1e-12, 'Stk');
    const finde = (re) => n.A.nachweise.find((x) => re.test(x.was));
    const sG = finde(/ständig \+ Betriebswind/);
    const sW = finde(/^Mastspitze, nur Wind/);
    const qu = finde(/quer zum Gleis/);
    pruef('Mastspitze mit staendig: Grenze L/100', sG.grenz, n.A.L / 100, 1e-12, 'm');
    pruef('Mastspitze nur Wind: Grenze L/200', sW.grenz, n.A.L / 200, 1e-12, 'm');
    pruef('Auf Ausleger-/Fahrdrahthoehe: 40 mm', qu.grenz, 0.040, 1e-12, 'm');
    wahr('… und dort wird QUER gemessen', qu.achse === 'x', qu.achse);
    wahr('… die Stelle ist der Fahrdraht, nicht die Spitze',
         n.A.stelle && n.A.stelle.z < n.A.L - 1e-9,
         `${n.A.stelle?.was} auf ${n.A.stelle?.z?.toFixed(2)} m`);
    /*
     * DIE 40 mm GEGEN NUR WIND (Rueckfrage vom 24. September) - also
     * gegen denselben Fall wie L/200, nicht gegen die Kombination.
     */
    wahr('… gegen den Fall NUR WIND',
         v.lastfaelle.find((z) => z.key === qu.lastfall)?.art === 'charakteristisch',
         qu.bez ?? '-');
    wahr('Die Spitze mit staendig kommt aus der Betriebskombination',
         v.lastfaelle.find((z) => z.key === sG.lastfall)?.stufe === 'betrieb',
         sG.bez ?? '-');
  }

  // --- c2) Die Hoehe laesst sich eintragen -------------------------------
  /* =======================================================================
   * Weisung vom 24. September: «es sollte einen schieber geben welche
   * höhe für die farhdrahtverschiebung massgebend ist.»
   *
   * Die Automatik misst am ANSCHLUSSPUNKT eines Teils; der Fahrdraht
   * hängt darunter, und wie weit, weiss die Zeichnung.
   * ===================================================================== */
  {
    const teil = A113.neuesAnbauteil('mast-nt-ausleger', 0);
    const grund = C113.setzeAnbauteileAn({ ...nackt },
      [{ ...teil, ort: 'mastA', hMast: 8.0 }]);
    const ohne = VF113.verformungsNachweis(lauf(grund));
    pruef('Ohne Eingabe bleibt es bei der Automatik',
          ohne.A.stelle.z, 8.0, 1e-9, 'm');

    // >>> EINE EINGETRAGENE HOEHE GEHT VOR. <<<
    const mit = VF113.verformungsNachweis(lauf({ ...grund, fdHoehe: 5.5 }));
    pruef('Die eingetragene Höhe gilt', mit.A.stelle.z, 5.5, 1e-9, 'm');
    /*
     * UND SIE AENDERT DEN NACHWEIS, nicht nur die Anschrift: tiefer am
     * Masten ist die Verschiebung kleiner.
     */
    const quer = (n) => n.A.nachweise.find((x) => /quer zum Gleis/.test(x.was));
    wahr('… und der gemessene Wert wird kleiner, weil sie tiefer liegt',
         quer(mit).wert < quer(ohne).wert - 1e-9,
         `${(quer(mit).wert * 1000).toFixed(1)} gegen ${
           (quer(ohne).wert * 1000).toFixed(1)} mm`);
    wahr('… der Nachweis nennt die Höhe, gegen die er läuft',
         /5\.50 m/.test(quer(mit).was), quer(mit).was);
    // Der Grenzwert bleibt, was er ist - 40 mm.
    pruef('… gegen unveränderte 40 mm', quer(mit).grenz, 0.040, 1e-12, 'm');

    /*
     * UEBER DEM MASTKOPF GILT SIE NICHT. Dort steht keine Verschiebung,
     * die der Mastkern gerechnet hätte; ein Nachweis an einer Stelle
     * ausserhalb des Modells wäre eine Zahl ohne Grundlage.
     */
    const drueber = VF113.verformungsNachweis(lauf({ ...grund, fdHoehe: 99 }));
    pruef('Über dem Mastkopf fällt sie auf die Automatik zurück',
          drueber.A.stelle.z, 8.0, 1e-9, 'm');
    // Und am Joch wirkt sie ebenso - beide Modellbauer führen das Feld.
    let j2 = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
    j2.L = 20; j2.xLage = 0; j2.mastVorhanden = true; j2.fdHoehe = 6.0;
    pruef('Am Joch ebenso',
          VF113.verformungsNachweis(lauf(j2)).A.stelle.z, 6.0, 1e-9, 'm');
  }

  // --- d) Am Joch: das Jochauflager ist die Stelle -----------------------
  {
    let j = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
    j.L = 20; j.xLage = 0; j.mastVorhanden = true;
    j = C113.setzeAnbauteileAn(j, [{ ...A113.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL' }]);
    const n = VF113.verformungsNachweis(lauf(j));
    wahr('Am Joch wird auf der Anschlusshoehe gemessen',
         n?.A?.stelle?.was === 'Jochauflager',
         `${n?.A?.stelle?.was} auf ${n?.A?.stelle?.z?.toFixed(2)} m`);
    wahr('… und beide Masten stehen da', Boolean(n.A && n.B));
  }

  // --- e) Sie faerbt kein Urteil -----------------------------------------
  /*
   * Entscheid vom 18. September: die Urteilsfarbe folgt allein der
   * Tragsicherheit. Ein ueberschrittener Gebrauchswert wird
   * ANGESCHRIEBEN, faerbt aber nichts.
   */
  {
    const CH113 = await import(J('core.checks.js'));
    const v = lauf(nackt);
    const erg = v.ergebnisse[v.massgebend ?? Object.keys(v.ergebnisse)[0]];
    erg.verformung = VF113.verformungsNachweis(v);
    const u = CH113.bauteilUrteil(erg, null, 'einzelmast');
    wahr('Die Verformung steht nicht im Urteil',
         u.liste.every((b) => b.key !== 'verformung'),
         u.liste.map((b) => b.key).join(' '));
    // Sie reist aber mit in die Anzeige - sonst faende sie die Spalte nie.
    const mb = CH113.mitBauteilen({ }, erg);
    wahr('… wandert aber mit `mitBauteilen` in die Anzeige',
         Boolean(mb.verformung));
    const ui113 = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    wahr('Die Kachel steht ohne Ampel da',
         /kachel\(`Verformung \$\{name\}`[\s\S]{0,400}?'',/.test(ui113));
  }
}

titel('114  Diagramme: was die Seitenleiste zeigt, zieht die Buehne auf');
/* ===========================================================================
 * Gemeldet am 24. September: «die diagramme, lassen sich nicht gross machen
 * bei gewissen tragwerksarten.»
 *
 * Am EINZELMASTEN tat ein Klick auf «Schnittgroessen ueber die Masthoehe»
 * gar nichts. Der Grund: `diagrammSatz` rief `diagramme(erg)` unbesehen -
 * die Funktion des JOCHS, die mit `erg.knoten.map(...)` beginnt. Ein
 * Einzelmast hat keinen Ersatzbalken und keine Knoten; sie warf, bevor der
 * Satz gebaut war, und damit fehlten auch die MASTDIAGRAMME, die danach
 * hineingekommen waeren.
 *
 * Die Kontrolle prueft den Zusammenhang, nicht die Stelle: jede Kennung,
 * die die Seitenleiste als Knopf anbietet, muss im Satz der Buehne stehen.
 * ========================================================================= */
{
  const RC114 = await import(J('render.charts.js'));
  const C114 = await import(J('core.constants.js'));
  const V114 = await import(J('core.vierendeel.js'));
  const N114 = await import(J('core.nachbarn.js'));
  const A114 = await import(J('data.anbauteile.js'));
  const CH114 = await import(J('core.checks.js'));
  const VF114 = await import(J('core.verformung.js'));
  const AK114 = await import(J('core.anker.js'));

  /*
   * DIE BEIDEN STELLEN, NACHGEBAUT. Sie stehen in app.js und haengen dort
   * am Zustand; hier steht ihr Kern, damit der Zusammenhang messbar ist.
   * Weicht app.js davon ab, faellt es in den Quelltextkontrollen unten auf.
   */
  const satzVon = (erg, breite) => {
    const abD = erg.abfang ? RC114.abfangDiagramme(erg.abfang, breite) : null;
    const haupt = abD ?? (erg.knoten?.length ? RC114.diagramme(erg, breite) : null);
    const satz = {};
    if (haupt) {
      satz.schnittgroessen = haupt.schnittgroessen;
      satz.ebene = haupt.ebene;
      satz.ausnutzung = haupt.ausnutzung;
    }
    ['A', 'B'].forEach((ende) => { /* Platzhalter, siehe weiter unten */ });
    let i = 0;
    ['A', 'B'].forEach((ende) => {
      const mn = erg.mast?.[ende] ?? null;
      const ak = erg.anker?.[ende] ?? null;
      if (!mn && !ak) return;
      const md = mn ? RC114.mastDiagramme(mn, { breite, name: `Ende ${ende}` }) : null;
      if (!md && !ak?.nachweis) return;
      if (md?.schnitt) satz[`mast-schnitt-${i}`] = md.schnitt;
      if (md?.ausnutzung) satz[`mast-eta-${i}`] = md.ausnutzung;
      if (md?.verformung) satz[`mast-verf-${i}`] = md.verformung;
      i += 1;
    });
    return satz;
  };

  const lauf = (w) => {
    const s2 = N114.rechensatzMitNachbarn(w);
    const v = V114.vergleichKombinationen(s2, ...N114.kernArgumente(s2));
    const erg = V114.berechne(s2, ...N114.kernArgumente(s2));
    erg.anker = AK114.ankerAuswertung(v, s2);
    erg.verformung = VF114.verformungsNachweis(v);
    return CH114.mitBauteilen(v.huellkurve ?? erg, erg, { mastErsatz: true });
  };

  const joch = () => {
    let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
    w.L = 20; w.xLage = 0; w.mastVorhanden = true;
    return C114.setzeAnbauteileAn(w, [{ ...A114.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL' }]);
  };
  const einzel = () => C114.setzeAnbauteileAn(
    { ...standardwerte(), tragwerksart: 'einzelmast', mastLaenge: 10,
      L: 0, xLage: 0, mastVorhanden: true },
    [{ ...A114.neuesAnbauteil('mast-nt-ausleger', 0), ort: 'mastA', hMast: 8.0 }]);

  /* =====================================================================
   * >>> DER BEFUND SELBST: AM EINZELMASTEN STAND NICHTS. <<<
   * =================================================================== */
  {
    const e = lauf(einzel());
    const satz = satzVon(e, 600);
    wahr('Einzelmast: der Ersatzbalken faellt weg, nicht der ganze Satz',
         !satz.schnittgroessen && Boolean(satz['mast-schnitt-0']),
         Object.keys(satz).join(' ') || 'leer');
    wahr('… und die Ausnutzung des Masten steht da',
         Boolean(satz['mast-eta-0']));
    wahr('… und die Verformung',
         Boolean(satz['mast-verf-0']));
    // Ohne Knoten darf `diagramme` gar nicht erst gerufen werden.
    let warf = false;
    try { RC114.diagramme({ knoten: undefined }, 600); } catch { warf = true; }
    wahr('Die Jochfunktion braucht Knoten - genau darum die Weiche', warf);
  }

  /* Und am Joch bleibt alles, wie es war. */
  {
    const e = lauf(joch());
    const satz = satzVon(e, 600);
    wahr('Joch: die drei Jochdiagramme stehen da',
         Boolean(satz.schnittgroessen && satz.ebene && satz.ausnutzung));
    wahr('… dazu beide Masten mit Schnitt, Ausnutzung und Verformung',
         ['mast-schnitt-0', 'mast-eta-0', 'mast-verf-0',
          'mast-schnitt-1', 'mast-eta-1', 'mast-verf-1'].every((k) => satz[k]),
         Object.keys(satz).join(' '));
  }

  /*
   * DIE BEIDEN STELLEN IN app.js MUESSEN DIESELBEN KENNUNGEN VERGEBEN -
   * die Seitenleiste als Knopf, die Buehne als Schluessel. Gingen sie
   * auseinander, taete ein Klick wieder nichts.
   */
  {
    const appQ = readFileSync(join(HIER, 'js', 'app.js'), 'utf8');
    const uiQ = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    ['anker-bem', 'mast-schnitt', 'mast-eta', 'mast-verf'].forEach((k) => {
      wahr(`«${k}» kennen beide Stellen`,
           appQ.includes(`setz('${k}'`) && uiQ.includes(`\`${k}-\${i}\``),
           `app ${appQ.includes(`setz('${k}'`)} · ui ${uiQ.includes(`\`${k}-\${i}\``)}`);
      wahr(`… und die Buehne hat einen Titel dafuer`,
           new RegExp(`'${k}':`).test(appQ));
    });
    wahr('Die Buehne baut den Ersatzbalken nur mit Knoten',
         appQ.includes("erg.knoten?.length ? diagramme(erg, breite) : null"));
  }
}

titel('115  Gebrauchstauglichkeit: eigener Plot, eigene Wahl');
/* ===========================================================================
 * Weisung vom 24. September, im Wortlaut:
 *
 *   «setze noch ein resultat plott gebrauchstauglichkeit das müsste man
 *    dann auch irgendwie in den ergebnissen auswählbar machen,
 *    Tragsicherheit Gebrauchstagulichkeit oder beide.»
 *
 * Auf Rueckfrage entschieden:
 *   - der Plot traegt η AUS DEM NACHWEIS, je Mast (nicht einen Verlauf
 *     gegen einen Grenzwert, den es zwischen den beiden Nachweisstellen
 *     gar nicht gibt);
 *   - die Wahl wirkt auf die Ergebnisleiste UND auf die Plotliste.
 * ========================================================================= */
{
  const R115 = await import(J('render.3d.js'));
  const LY115 = await import(J('app.layout.js'));
  const UI115 = await import(J('ui.js'));
  const C115 = await import(J('core.constants.js'));
  const V115 = await import(J('core.vierendeel.js'));
  const N115 = await import(J('core.nachbarn.js'));
  const A115 = await import(J('data.anbauteile.js'));
  const CH115 = await import(J('core.checks.js'));
  const VF115 = await import(J('core.verformung.js'));
  const AK115 = await import(J('core.anker.js'));

  const lauf = (w) => {
    const s2 = N115.rechensatzMitNachbarn(w);
    const v = V115.vergleichKombinationen(s2, ...N115.kernArgumente(s2));
    const erg = V115.berechne(s2, ...N115.kernArgumente(s2));
    erg.anker = AK115.ankerAuswertung(v, s2);
    erg.verformung = VF115.verformungsNachweis(v);
    return CH115.mitBauteilen(v.huellkurve ?? erg, erg, { mastErsatz: true });
  };
  const joch115 = () => {
    let w = typUebernehmen({ ...standardwerte(), typ: 'J90' }, T.getTragjoch('J90'));
    w.L = 20; w.xLage = 0; w.mastVorhanden = true;
    return C115.setzeAnbauteileAn(w, [{ ...A115.neuesAnbauteil('hs-fahrdraht', 10), name: 'FL' }]);
  };
  const einzel115 = () => C115.setzeAnbauteileAn(
    { ...standardwerte(), tragwerksart: 'einzelmast', mastLaenge: 10,
      L: 0, xLage: 0, mastVorhanden: true },
    [{ ...A115.neuesAnbauteil('mast-nt-ausleger', 0), ort: 'mastA', hMast: 8.0 }]);

  // --- a) Der Mast traegt sein η der Gebrauchstauglichkeit --------------
  /*
   * >>> UND ZWAR GENAU DAS AUS DEM NACHWEIS. <<<
   * Der Plot darf keine zweite Zahl bilden; er zeigt, was in der Kachel
   * daneben steht.
   */
  {
    const e = lauf(einzel115());
    const sz = R115.erzeugeSzene(e.modell, e);
    const mast = sz.flaechen.filter((f) => f.gruppe === 'mast' && f.werte);
    wahr('Der Mast traegt η der Gebrauchstauglichkeit',
         mast.length > 0 && mast.every((f) => Number.isFinite(f.werte.etaGzg)),
         `${mast.length} Koerper`);
    pruef('… und es ist das η des Nachweises',
          mast[0].werte.etaGzg, e.verformung.A.eta, 1e-12, '–');
    /*
     * UEBER DIE GANZE HOEHE GLEICH - auch am Ueberstand ueber den
     * Nachweisbereich. Der Nachweis gilt dem Masten, nicht der Station;
     * ein Verlauf waere eine erfundene Zahl (siehe render.koerper.js).
     */
    wahr('… ueber die ganze Hoehe derselbe Wert',
         new Set(mast.map((f) => f.werte.etaGzg.toFixed(12))).size === 1,
         `${new Set(mast.map((f) => f.werte.etaGzg.toFixed(12))).size} verschiedene`);
    // Die Schwerachse faerbt mit, wie bei jeder anderen Groesse.
    wahr('Auch die Schwerachse des Masten traegt ihn',
         (sz.linien ?? []).filter((l) => l.gruppe === 'mast' && l.schwerachse)
           .every((l) => Number.isFinite(l.werte?.etaGzg)));
    // Und η der Tragsicherheit steht unveraendert daneben.
    wahr('… neben dem η der Tragsicherheit, nicht an seiner Stelle',
         mast.every((f) => Number.isFinite(f.werte.eta)));
  }

  // --- b) Das Joch bleibt grau ------------------------------------------
  {
    const e = lauf(joch115());
    const sz = R115.erzeugeSzene(e.modell, e);
    const jochTeile = sz.flaechen.filter(
      (f) => (f.gruppe === 'profil' || f.gruppe === 'blech') && f.werte);
    wahr('Gurte und Bleche fuehren kein η der Gebrauchstauglichkeit',
         jochTeile.length > 0
         && jochTeile.every((f) => !Number.isFinite(f.werte.etaGzg)),
         `${jochTeile.length} Teile geprueft`);
    const mast = sz.flaechen.filter((f) => f.gruppe === 'mast' && f.werte?.etaGzg);
    wahr('… die beiden Masten am Joch aber schon', mast.length > 0);
  }

  // --- c) Die Wahl filtert die Plotliste --------------------------------
  {
    const alle = LY115.modiFuer('beide').map((m) => m.key);
    const trag = LY115.modiFuer('trag').map((m) => m.key);
    const gzg = LY115.modiFuer('gzg').map((m) => m.key);
    wahr('«beide» zeigt alles', alle.length === R115.MODI.length);
    wahr('«Tragsicherheit» nimmt Verformung und η_w weg',
         !trag.includes('w') && !trag.includes('etaGzg') && trag.includes('eta'),
         trag.join(' '));
    wahr('«Gebrauchstauglichkeit» laesst nur diese beiden stehen',
         gzg.filter((k) => R115.MODI.find((m) => m.key === k)?.art === 'plot')
           .join(' ') === 'w etaGzg',
         gzg.join(' '));
    /*
     * DIE BAUTEILMODI BLEIBEN IMMER. Sie zeigen das Modell, nicht ein
     * Ergebnis - waeren sie weg, liesse sich der Plot bei «nur
     * Gebrauchstauglichkeit» nicht mehr abschalten.
     */
    wahr('Die Bauteilmodi stehen in jeder Stellung',
         ['neutral', 'positionen'].every(
           (k) => trag.includes(k) && gzg.includes(k)));
  }

  // --- d) Was weggefiltert wird, darf nicht aufgetragen bleiben ----------
  /*
   * Sonst zeigte das Modell weiter σ_v, mit Legende und ohne einen Knopf,
   * es zurueckzustellen.
   */
  {
    const app = { nachweisart: 'gzg', ansicht: { modus: 'sig_v' } };
    wahr('Der weggefilterte Plot wird umgestellt', LY115.modusKorrigieren(app));
    wahr('… auf eine Groesse, die es noch gibt',
         LY115.modiFuer('gzg').some((m) => m.key === app.ansicht.modus),
         app.ansicht.modus);
    const app2 = { nachweisart: 'gzg', ansicht: { modus: 'w' } };
    wahr('Ein Plot, der bleibt, wird nicht angetastet',
         LY115.modusKorrigieren(app2) === false && app2.ansicht.modus === 'w');
    const app3 = { nachweisart: 'trag', ansicht: { modus: 'etaGzg' } };
    LY115.modusKorrigieren(app3);
    wahr('… und in der Gegenrichtung ebenso',
         app3.ansicht.modus !== 'etaGzg', app3.ansicht.modus);
  }

  // --- e) Die Kacheln sind zwei Gruppen ----------------------------------
  /*
   * >>> DIE VORAUSSETZUNG DAFUER, SIE WEGLASSEN ZU KOENNEN. <<<
   * Bis zum 24. September standen die Verformungskacheln MITTEN unter den
   * η-Kacheln der Tragsicherheit - auf einem anderen Lastniveau, gegen
   * ein anderes Mass, ohne Ampel.
   */
  {
    const e = lauf(einzel115());
    const trag = UI115.bauteilKacheln(e, { nachweise: {} }, () => '');
    const gzg = UI115.gzgKacheln(e);
    wahr('Die Verformung steht nicht mehr bei den Tragsicherheitskacheln',
         trag.every((h) => !/Verformung/.test(h)));
    wahr('… sondern in ihrer eigenen Gruppe',
         gzg.length > 0 && gzg.every((h) => /Verformung/.test(h)),
         `${gzg.length} Kachel(n)`);
    // Ohne Ampel - der Entscheid vom 18. September gilt weiter.
    wahr('… ohne Ampelfarbe',
         gzg.every((h) => !/kz (ok|warn|fail)/.test(h)));
    const block = UI115.gzgBlockHtml(e);
    wahr('Der Block nennt den Betriebswind', /ψ 0\.70/.test(block), block.slice(0, 120));
    // Und er sagt es auch, wenn es nichts zu zeigen gibt.
    wahr('Ohne Verformungsnachweis steht ein Satz statt einer Luecke',
         /Kein Verformungsnachweis/.test(UI115.gzgBlockHtml({ })));
  }

  // --- f) Die Wahl steht an EINER Stelle und ist verdrahtet --------------
  {
    const uiQ = readFileSync(join(HIER, 'js', 'ui.js'), 'utf8');
    const appQ = readFileSync(join(HIER, 'js', 'app.js'), 'utf8');
    const lyQ = readFileSync(join(HIER, 'js', 'app.layout.js'), 'utf8');
    pruef('Drei Stellungen', UI115.NACHWEISARTEN.length, 3, 1e-12, 'Stk');
    wahr('Vorgabe ist «beide» - wer nichts waehlt, sieht alles',
         /nachweisart = 'beide'/.test(appQ)
         && /opt\.nachweisart \?\? 'beide'/.test(uiQ));
    wahr('Beide Uebersichten zeigen die Leiste',
         (uiQ.match(/nachweisartLeiste\(nwArt\)/g) ?? []).length === 2);
    wahr('… und verdrahten sie',
         (uiQ.match(/verdrahteNachweisart\(node, opt\);/g) ?? []).length === 2);
    wahr('… und app.js reicht die Wahl an beide',
         (appQ.match(/beiNachweisart: setzeNachweisart/g) ?? []).length === 2);
    /*
     * SIE RECHNET NICHT NEU. Ein Anzeigefilter, der `neuRechnen` riefe,
     * fuellte den Verlauf (Rueckgaengig) mit Schritten ohne Aenderung.
     */
    const fn = appQ.slice(appQ.indexOf('function setzeNachweisart'));
    wahr('Das Umschalten rechnet nicht neu',
         !/neuRechnen\(\)/.test(fn.slice(0, fn.indexOf('function zeichneAuswertung'))));
    // Und die Plotliste haengt an derselben Wahl - kein zweiter Waehler.
    wahr('Die Plotliste folgt derselben Wahl',
         /modiFuer\(app\.nachweisart\)/.test(lyQ));
  }

  // --- f2) Achtmal dieselbe Zahl ist keine Auskunft ----------------------
  /*
   * Gemeldet am 24. September mit dem Bild eines Masten: «Die werteplotts
   * sind nicht gut lesbar» - achtmal «1.97» untereinander. Die Ausduennung
   * kannte nur Abstaende im Bild, nicht die Frage, ob zwei Zahlen etwas
   * Verschiedenes sagen. Bei einer Groesse, die dem BAUTEIL gehoert statt
   * der Station, sagen sie es nie.
   */
  {
    const acht = Array.from({ length: 8 }, (_, i) =>
      ({ v: 1.9663, x: 100, y: 50 + i * 40, betrag: 1.9663, teil: 'MAST_A' }));
    const eins = R115.entdoppelteWerte(acht, 2);
    pruef('Achtmal derselbe Wert am selben Bauteil: eine Zahl',
          eins.length, 1, 1e-12, 'Stk');
    wahr('… und zwar die mittlere, nicht das abgeschnittene Ende',
         Math.abs(eins[0].y - 190) <= 20, `y = ${eins[0].y}`);
    // Verschiedene Werte bleiben alle stehen - jeder ist eine eigene Auskunft.
    const viele = [0.31, 0.44, 0.58, 0.72].map((v, i) =>
      ({ v, x: 100, y: 50 + i * 40, betrag: v, teil: 'MAST_A' }));
    pruef('Verschiedene Werte bleiben',
          R115.entdoppelteWerte(viele, 2).length, 4, 1e-12, 'Stk');
    // Gleiche Werte an VERSCHIEDENEN Bauteilen sind zwei Auskuenfte.
    const zwei = ['MAST_A', 'MAST_B'].map((teil, i) =>
      ({ v: 1.97, x: 100 + i * 50, y: 50, betrag: 1.97, teil }));
    pruef('Gleicher Wert an zwei Bauteilen bleibt zweimal',
          R115.entdoppelteWerte(zwei, 2).length, 2, 1e-12, 'Stk');
    // Ohne Bauteilangabe wird nichts weggenommen.
    pruef('Ohne Bauteilangabe bleibt alles',
          R115.entdoppelteWerte([{ v: 1, x: 0, y: 0 }, { v: 1, x: 9, y: 9 }], 2).length,
          2, 1e-12, 'Stk');
    /*
     * UND DIE ZIFFER IST LESBAR: das Kaestchen bleibt blass, die Zahl
     * steht fast voll da. Eine rote Ziffer mit 0.62 auf einem roten
     * Bauteil war kaum zu entziffern.
     */
    const q115 = readFileSync(join(HIER, 'js', 'render.3d.js'), 'utf8');
    wahr('Ziffer und Kaestchen haben eigene Deckkraft',
         /farbeVon\(k\.v\), 0\.95, 0\.62\)/.test(q115)
         && /saum \?\? deckung/.test(q115));
  }

  // --- g) Ueber alle vier Tragwerksarten ---------------------------------
  {
    const arten = [['Tragjoch', joch115()], ['Einzelmast', einzel115()]];
    arten.forEach(([was, w]) => {
      const e = lauf(w);
      const sz = R115.erzeugeSzene(e.modell, e);
      const mast = sz.flaechen.filter((f) => f.gruppe === 'mast' && f.werte?.etaGzg);
      wahr(`${was}: der Plot findet seinen Wert`, mast.length > 0,
           `η ${mast[0]?.werte?.etaGzg?.toFixed(3) ?? '-'}`);
    });
  }
}

// ===========================================================================
console.log('\n' + '='.repeat(104));
console.log(`ERGEBNIS:  ${bestanden} bestanden, ${gefallen} gefallen`);
if (gefallen) {
  console.log('\nNICHT BESTANDEN:');
  fehlerliste.forEach((f) => console.log('  · ' + f));
}
console.log('='.repeat(104));
process.exit(gefallen ? 1 : 0);
